) AS d(code, en, ru)
WHERE i."code" IS NULL
  AND NOT EXISTS (SELECT 1 FROM "ingredients" x WHERE x."code" = d.code)
  AND i."id" = (
    SELECT t."ingredientId" FROM "ingredient_translations" t JOIN "ingredients" j ON j."id" = t."ingredientId"
    WHERE j."code" IS NULL AND ((t."language" = 'en' AND lower(t."name") = lower(d.en)) OR (t."language" = 'ru' AND lower(t."name") = lower(d.ru)))
    ORDER BY t."createdAt", t."ingredientId" LIMIT 1
  );

