INSERT INTO "food_translations" ("id", "foodId", "language", "name", "description", "content", "updatedAt") VALUES
  ('b7dff307-0913-544e-849f-0a144b9cae98', 'bc2b07c6-63a1-5747-a095-569764b1764b', 'ru', 'Салат с тунцом и кускусом', 'Сытный салат без майонеза: кускус, тунец, фасоль, свежие овощи и зелень с лёгкой оливково-лимонной заправкой.', '<ol><li>Сварите яйца всмятку (около 6 минут в кипящей воде), остудите, очистите и разрежьте пополам.</li><li>Залейте кускус таким же объёмом кипятка, накройте и оставьте на 5 минут, затем взрыхлите вилкой.</li><li>В большой миске соедините фасоль, половинки помидоров черри, нарезанные сельдерей и красный лук, шнитт-лук, петрушку и каперсы. Размять тунец вилкой и добавьте к овощам.</li><li>Добавьте паприку, зиру, соль, перец, уксус, лимонный сок и оливковое масло, аккуратно перемешайте и дайте настояться несколько минут.</li><li>Выложите кускус на блюдо, сверху распределите салат с тунцом, украсьте яйцами и кольцами лука.</li></ol><p><em>Подавайте комнатной температуры, сверху с половинками яиц и кольцами красного лука.</em></p>', CURRENT_TIMESTAMP),
  ('8c8ebecd-6d5d-511d-8ab6-b6138ed2810f', 'bc2b07c6-63a1-5747-a095-569764b1764b', 'en', 'Tuna couscous salad', 'A filling mayo-free salad of couscous, tuna, beans, fresh vegetables and herbs with a light olive oil and lemon dressing.', '<ol><li>Soft-boil the eggs (about 6 minutes in boiling water), cool them, peel and halve.</li><li>Cover the couscous with an equal volume of boiling water, close with a lid for 5 minutes, then fluff with a fork.</li><li>In a large bowl combine the beans, halved cherry tomatoes, chopped celery and red onion, chives, parsley and capers. Flake the tuna with a fork and add it to the vegetables.</li><li>Add the paprika, cumin, salt, pepper, vinegar, lemon juice and olive oil, toss gently and let the flavours blend for a few minutes.</li><li>Spread the couscous on a platter, top with the tuna salad and garnish with the eggs and onion rings.</li></ol><p><em>Serve at room temperature topped with halved eggs and red onion rings.</em></p>', CURRENT_TIMESTAMP),
  ('24d52c94-41e5-5e21-9ebe-a579dfe30140', 'e6c9e6a4-8472-5ca1-9395-fd8f935e8575', 'ru', 'Запечённые спагетти с рикоттой и томатным соусом', 'Спагетти в овощном томатном соусе, залитые смесью яиц, рикотты и пармезана и запечённые под сырной корочкой.', '<ol><li>Разогрейте духовку до 190 °C. В большой жаропрочной сковороде или сотейнике нагрейте оливковое масло и 4–5 минут обжаривайте тёртый лук.</li><li>Добавьте чеснок и тёртую морковь и готовьте ещё 3 минуты, помешивая.</li><li>Влейте измельчённые томаты и воду, положите соль, перец, орегано и паприку. Доведите до кипения, убавьте огонь, накройте крышкой и томите 15–20 минут, изредка помешивая.</li><li>Пока варится соус, отварите спагетти до состояния аль денте, откиньте и ополосните.</li><li>Снимите крышку, добавьте спагетти в соус и перемешайте. Взбейте яйца с рикоттой и пармезаном, вмешайте смесь в пасту.</li><li>Посыпьте тёртой моцареллой и запекайте 15–20 минут, пока сыр не расплавится и не зарумянится; для корочки можно ненадолго включить гриль.</li><li>Украсьте рубленым базиликом и петрушкой, при желании добавьте хлопья красного перца.</li></ol><p><em>Посыпьте свежим базиликом и петрушкой, подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('b1e917d1-b85a-5d1e-80df-74606083da7c', 'e6c9e6a4-8472-5ca1-9395-fd8f935e8575', 'en', 'Baked spaghetti with ricotta and tomato sauce', 'Spaghetti tossed in a vegetable tomato sauce, mixed with eggs, ricotta and Parmesan, and baked under a layer of melted mozzarella.', '<ol><li>Heat the oven to 190°C. In a large ovenproof pan or braiser warm the olive oil and cook the grated onion for 4–5 minutes.</li><li>Add the garlic and grated carrots and cook for 3 more minutes, stirring.</li><li>Pour in the crushed tomatoes and water, add salt, pepper, oregano and paprika. Bring to a boil, lower the heat, cover and simmer for 15–20 minutes, stirring occasionally.</li><li>While the sauce simmers, cook the spaghetti until al dente, then drain and rinse.</li><li>Uncover the sauce and stir in the spaghetti. Whisk the eggs with ricotta and Parmesan and mix this into the pasta.</li><li>Top with shredded mozzarella and bake for 15–20 minutes until melted and bubbling; switch to the grill briefly for a browner crust.</li><li>Garnish with torn basil and chopped parsley, and add chilli flakes if you like.</li></ol><p><em>Garnish with fresh basil and parsley and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('5b1d5c62-bf03-552f-ad53-8baef2e616f5', '0110046d-e398-5a8c-b984-b64665db6ed1', 'ru', 'Картофельный гратен с чесночным сыром', 'Тонко нарезанный картофель, запечённый в сливочном соусе с мягким сыром с чесноком и травами. Сытный гарнир к мясу и птице.', '<ol><li>Очистите картофель и нарежьте очень тонкими кружками по 2–3 мм (удобно сделать это слайсером).</li><li>В большой кастрюле на слабом-среднем огне соедините сыр, молоко, сливки, чеснок и тимьян, добавьте чёрный перец и 1 ч. л. соли. Прогрейте до растворения сыра, не доводя до кипения.</li><li>Выложите картофель в соус, аккуратно перемешайте и доведите до слабого кипения, около 5 минут. Тем временем разогрейте духовку до 190 °C.</li><li>Смажьте маслом форму примерно 25 × 20 см, слоями уложите картофель шумовкой, залейте оставшимся соусом.</li><li>Запекайте 45–50 минут до золотистой корочки и пузырящегося соуса, пока нож не войдёт в центр без сопротивления. Дайте постоять 10 минут.</li></ol><p><em>Дайте гратену постоять 10 минут после духовки, чтобы он схватился, и подавайте к мясу или птице.</em></p>', CURRENT_TIMESTAMP),
  ('2de83de0-aae4-5ac7-9ef5-fc9fa09e0f1e', '0110046d-e398-5a8c-b984-b64665db6ed1', 'en', 'Potato gratin with garlic and herb cheese', 'Thinly sliced potatoes baked in a creamy sauce flavoured with garlic and herb soft cheese. A rich side for meat and poultry.', '<ol><li>Peel the potatoes and slice them very thinly, 2–3 mm thick (a mandoline makes this quicker).</li><li>In a large saucepan over medium-low heat combine the cheese, milk, cream, garlic and thyme, then add black pepper and 1 tsp salt. Warm until the cheese melts, without letting it boil.</li><li>Add the potato slices to the sauce, stir gently and bring to a light simmer for about 5 minutes. Meanwhile heat the oven to 190°C.</li><li>Butter a baking dish of about 25 × 20 cm, layer the potatoes in it with a slotted spoon and pour over the remaining sauce.</li><li>Bake for 45–50 minutes until golden and bubbling and a knife slides through the middle with little resistance. Rest for 10 minutes.</li></ol><p><em>Rest the gratin for 10 minutes after baking so it sets, then serve with roast meat or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('14a0b29d-f1b1-527b-b9c3-3f66d3d20372', '90cb5678-b0c8-5478-87b0-a37722f8b0ef', 'ru', 'Манаиш с заатаром', 'Ближневосточные дрожжевые лепёшки с пряной смесью заатар и оливковым маслом. Подходят на завтрак, как закуска или к овощам.', '<ol><li>Смешайте тёплую воду, сахар и дрожжи, оставьте на 10 минут до появления пены.</li><li>Соедините муку, соль и 2 ст. л. оливкового масла, сделайте углубление, влейте дрожжевую смесь и замесите мягкое тесто. Месите на присыпанной мукой поверхности около 10 минут до эластичности.</li><li>Сформируйте шар, положите в слегка смазанную маслом миску, накройте влажной тканью и оставьте в тепле на 1,5 часа.</li><li>Обомните тесто, разделите на 8 шариков, накройте и оставьте ещё на 30 минут. Смешайте заатар с 8 ст. л. оливкового масла.</li><li>Разогрейте духовку до 200 °C вместе с противнем. Раскатайте шарики в лепёшки диаметром около 12 см, пальцами сделайте ямки и нанесите на каждую ложку заатара с маслом, оставив узкий край.</li><li>Выложите лепёшки на смазанный горячий противень и выпекайте 7–8 минут, пока низ и края слегка не подрумянятся. Дайте 5 минут постоять.</li></ol><p><em>Подавайте тёплыми со свежими помидорами, огурцами и оливками, по желанию с брынзой или лабне.</em></p>', CURRENT_TIMESTAMP),
  ('b08cb3a5-8928-5145-816b-ee5f4ddddb5d', '90cb5678-b0c8-5478-87b0-a37722f8b0ef', 'en', 'Za''atar manakish', 'Levantine yeast flatbreads topped with za''atar and olive oil. Good for breakfast, as a snack or served with vegetables.', '<ol><li>Mix the lukewarm water, sugar and yeast and leave for 10 minutes until foamy.</li><li>Combine the flour, salt and 2 tbsp olive oil, make a well, pour in the yeast mixture and stir to a soft dough. Knead on a floured surface for about 10 minutes until smooth and elastic.</li><li>Shape into a ball, place in a lightly oiled bowl, cover with a damp cloth and leave in a warm spot for 1½ hours.</li><li>Punch the dough down, divide into 8 balls, cover and rest for 30 more minutes. Mix the za''atar with 8 tbsp olive oil.</li><li>Heat the oven to 200°C with a baking sheet inside. Flatten the balls into discs of about 12 cm, dimple them with your fingertips and spoon the za''atar mix onto each, leaving a narrow border.</li><li>Place the discs on the oiled hot baking sheet and bake for 7–8 minutes until the bottoms and edges are lightly browned. Rest for about 5 minutes.</li></ol><p><em>Serve warm with fresh tomatoes, cucumbers and olives, and feta or labneh if you like.</em></p>', CURRENT_TIMESTAMP),
  ('1134e437-f265-57c9-adf5-54f70f6986bf', 'd68268e7-1130-5462-89c1-f61c7a886714', 'ru', 'Паста с курицей в сливочном соусе с вялеными томатами', 'Паста фузилли с курицей в сливочно-сырном соусе с вялеными томатами, чесноком и тимьяном. Хороший способ использовать остатки запечённой курицы или индейки.', '<ol><li>В глубокой сковороде или кастрюле разогрейте масло и 5 минут обжаривайте лук с щепоткой соли до мягкости. Добавьте чеснок, тимьян и томатную пасту и жарьте минуту до аромата.</li><li>Влейте бульон, добавьте нарезанные вяленые томаты, сыр и сливки. Варите на слабом огне 10 минут, пока соус немного не уменьшится.</li><li>Отварите пасту в подсоленной воде на минуту меньше, чем указано на упаковке. Оставьте стакан воды после варки.</li><li>Добавьте в соус нарезанную курицу и прогрейте 2 минуты. Переложите пасту в соус, влейте лимонный сок, посолите и поперчите, перемешайте, при необходимости разбавьте соус водой от пасты.</li></ol><p><em>При подаче добавьте немного воды от варки пасты, если соус получился густым.</em></p>', CURRENT_TIMESTAMP),
  ('e24fbff3-ec9c-53b3-bd3d-c3056a8b1e97', 'd68268e7-1130-5462-89c1-f61c7a886714', 'en', 'Creamy sun-dried tomato chicken pasta', 'Fusilli with chicken in a creamy cheese sauce with sun-dried tomatoes, garlic and thyme. A good way to use up leftover roast chicken or turkey.', '<ol><li>Heat the oil in a deep pan and fry the onion with a pinch of salt for 5 minutes until soft. Add the garlic, thyme and tomato paste and fry for 1 minute until fragrant.</li><li>Pour in the stock, then add the sliced sun-dried tomatoes, cheese and cream. Simmer for 10 minutes until slightly reduced.</li><li>Cook the pasta in salted boiling water for 1 minute less than the pack says. Keep a cup of the pasta water.</li><li>Stir the chopped chicken into the sauce and warm for 2 minutes. Toss in the pasta with the lemon juice and seasoning, adding a little pasta water if needed.</li></ol><p><em>Loosen the sauce with a splash of pasta water if it gets too thick.</em></p>', CURRENT_TIMESTAMP),
  ('ddc4b30f-338f-5a54-a205-cedb9ab31a7d', 'e6fb5ac7-f0c3-52eb-8aeb-aaebc8d5ea73', 'ru', 'Тосты-корзинки с ветчиной, яйцом и сырным соусом', 'Хлебные корзинки в форме для маффинов с ветчиной, яйцом и сырным соусом бешамель, запечённые в духовке. Вариант крок-мадам на завтрак.', '<ol><li>Разогрейте духовку до 180 °C. Срежьте корочку с хлеба и раскатайте ломтики скалкой. Вдавите их в большие формы для маффинов, чтобы получились чашки, и подсушите в духовке 5 минут, не допуская румянца.</li><li>Для соуса растопите сливочное масло, всыпьте муку и перемешайте в пасту. Влейте половину молока, взбивайте до загустения, затем добавьте остальное молоко, горчицу, мускатный орех, соль и перец. Взбивайте 1,5–2 минуты до густоты.</li><li>Снимите соус с огня, остудите 5 минут и вмешайте сыр.</li><li>Смажьте края хлебных чашек растопленным маслом, положите в каждую ветчину, аккуратно разбейте яйцо, залейте соусом и посыпьте сыром.</li><li>Выпекайте 18 минут для жидкого желтка или 23 минуты для плотного. Дайте постоять несколько минут и посыпьте петрушкой.</li></ol><p><em>Подавайте сразу, посыпав петрушкой и свежемолотым мускатным орехом.</em></p>', CURRENT_TIMESTAMP),
  ('2c313aeb-db65-5bf0-9382-655f5fb6fa60', 'e6fb5ac7-f0c3-52eb-8aeb-aaebc8d5ea73', 'en', 'Ham, egg and cheese sauce toast cups', 'Bread cups baked in a muffin tin with ham, an egg and cheesy béchamel on top. A breakfast take on croque madame.', '<ol><li>Heat the oven to 180°C. Cut the crusts off the bread and flatten the slices with a rolling pin. Press them into large muffin tins to make cups and dry in the oven for 5 minutes, without browning.</li><li>For the sauce melt the butter, stir in the flour to a paste, whisk in half the milk until thick, then add the remaining milk, mustard, nutmeg, salt and pepper. Whisk for 1½–2 minutes until thick.</li><li>Take the sauce off the heat, cool for 5 minutes and stir in the cheese.</li><li>Brush the edges of the toast cups with melted butter, put ham in each, crack in an egg, spoon over the sauce and sprinkle with cheese.</li><li>Bake for 18 minutes for runny yolks or 23 minutes for firm ones. Rest a few minutes and top with parsley.</li></ol><p><em>Serve at once, sprinkled with parsley and freshly grated nutmeg.</em></p>', CURRENT_TIMESTAMP),
  ('f2d6a620-6e04-5e8f-a70c-4571eb82cc3e', 'f5c6eb85-b329-585f-8352-7ba3d377646e', 'ru', 'Капрезе с запечёнными баклажанами', 'Слои запечённых баклажанов, помидоров, моцареллы и базилика с базиликовой заправкой. Тёплая сытная закуска.', '<ol><li>Разогрейте духовку до 220 °C. Нарежьте баклажан кружками толщиной около 1 см, обильно посолите и оставьте на 30 минут, затем промокните бумажным полотенцем.</li><li>Выложите баклажаны и кружки помидоров на противень, сбрызните маслом и запекайте 10–15 минут. Духовку не выключайте.</li><li>Слегка остудите овощи и плотными рядами уложите в небольшую форму, чередуя баклажан, помидор, ломтики моцареллы и листья базилика.</li><li>Поставьте форму в духовку на 7–10 минут, пока сыр слегка не расплавится.</li><li>Для заправки измельчите в блендере чеснок, базилик, оливковое масло, сок лайма и специи. Полейте закуску частью заправки, остальную подайте отдельно.</li></ol><p><em>Подавайте с ломтиками хрустящего хлеба и отдельно с заправкой.</em></p>', CURRENT_TIMESTAMP),
  ('7eeeb93b-be04-5dbd-9c4b-cdf9008f05ee', 'f5c6eb85-b329-585f-8352-7ba3d377646e', 'en', 'Roasted eggplant caprese', 'Layers of roasted eggplant, tomato, mozzarella and basil with a fresh basil dressing. A warm, filling starter.', '<ol><li>Heat the oven to 220°C. Cut the eggplant into rounds about 1 cm thick, salt generously and leave for 30 minutes, then pat dry.</li><li>Spread the eggplant and tomato rounds on a baking sheet, drizzle with oil and roast for 10–15 minutes. Leave the oven on.</li><li>Cool the vegetables a little and layer them in tight rows in a small dish, alternating eggplant, tomato, mozzarella slices and basil leaves.</li><li>Return the dish to the oven for 7–10 minutes until the cheese just melts.</li><li>For the dressing blend the garlic, basil, olive oil, lime juice and spices. Spoon some over the dish and serve the rest on the side.</li></ol><p><em>Serve with slices of crusty bread and the extra dressing on the side.</em></p>', CURRENT_TIMESTAMP),
  ('775e97f2-ef33-5c30-aa2d-44dc26f60295', 'f483f3b2-1284-5d5b-a5e3-02a20999b15a', 'ru', 'Большая картофельная оладья (хэш-браун)', 'Хрустящая золотистая лепёшка из тёртого картофеля, обжаренная на сковороде с двух сторон. Подходит на завтрак или как гарнир.', '<ol><li>Очистите картофель и натрите, сразу складывая в миску с холодной водой, чтобы он не темнел.</li><li>Промойте картофель в дуршлаге, пока вода не станет прозрачной, затем небольшими порциями отожмите лишнюю влагу. Смешайте с 1 ст. л. масла, солью и перцем.</li><li>Разогрейте в антипригарной сковороде диаметром 22 см 2 ст. л. масла, выложите картофель слоем около 1,5 см и слегка прижмите. Жарьте 5–8 минут до золотистой корочки.</li><li>Переверните оладью с помощью большой тарелки, добавьте по краям оставшуюся 1 ст. л. масла и жарьте ещё 4–6 минут до хруста. Нарежьте секторами.</li></ol><p><em>Нарежьте на секторы и посыпьте рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('7d8da1f1-91e5-53e9-b4be-999fdd5574aa', 'f483f3b2-1284-5d5b-a5e3-02a20999b15a', 'en', 'Giant hash brown', 'One big crispy golden cake of grated potato, pan-fried on both sides. Works as breakfast or a side dish.', '<ol><li>Peel and grate the potatoes, dropping them straight into a bowl of cold water so they don''t darken.</li><li>Rinse the potato in a colander until the water runs clear, then squeeze out the excess moisture a handful at a time. Mix with 1 tbsp oil, the salt and pepper.</li><li>Heat 2 tbsp oil in a 22 cm non-stick pan, add the potato in a layer about 1.5 cm thick and pat it down lightly. Cook for 5–8 minutes until golden and crisp.</li><li>Flip the hash brown using a large plate, drizzle the remaining 1 tbsp oil around the edges and cook another 4–6 minutes until crisp. Cut into wedges.</li></ol><p><em>Cut into wedges and sprinkle with chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('ad399214-9384-5a5d-b7c4-887187058003', '475d6252-08e8-5b65-b73a-2978487495d8', 'ru', 'Мини-гренки с клубникой', 'Маленькие сладкие гренки из багета в яично-молочной смеси, обжаренные на масле и поданные с клубникой и кленовым сиропом.', '<ol><li>Смешайте нарезанную клубнику с сахаром и оставьте, чтобы она пустила сок.</li><li>Слегка взбейте яйца с молоком и солью в неглубокой миске.</li><li>Растопите масло на сковороде на средне-сильном огне. Обмакните ломтики багета с каждой стороны на 3 секунды в яичную смесь.</li><li>Обжаривайте гренки по 2,5 минуты с каждой стороны до румяной корочки. Подавайте с клубникой и её соком, кленовым сиропом и сахарной пудрой.</li></ol><p><em>Полейте кленовым сиропом, украсьте клубникой и присыпьте сахарной пудрой.</em></p>', CURRENT_TIMESTAMP),
  ('96d7e06f-cc2f-59df-80ab-33a3b66ed063', '475d6252-08e8-5b65-b73a-2978487495d8', 'en', 'Mini strawberry French toast', 'Small slices of baguette soaked in egg and milk, fried in butter and served with strawberries and maple syrup.', '<ol><li>Toss the sliced strawberries with the sugar and leave them to release their juice.</li><li>Lightly whisk the eggs, milk and salt in a shallow bowl.</li><li>Melt the butter in a pan over medium-high heat. Dip each baguette slice in the egg mixture for about 3 seconds per side.</li><li>Fry the slices for 2½ minutes per side until nicely browned. Serve with the strawberries and their juice, maple syrup and icing sugar.</li></ol><p><em>Drizzle with maple syrup, top with strawberries and dust with icing sugar.</em></p>', CURRENT_TIMESTAMP),
  ('90a48b98-b6b2-5093-a205-176f9f8a69cf', 'ebe3a7bf-38bc-5c41-b384-5f1598aabe20', 'ru', 'Уэвос-ранчерос в лепёшках-мисочках', 'Яйца, запечённые в томатном соусе с фасолью и сладким перцем, поданные в подрумяненных пшеничных лепёшках. Сытный мексиканский завтрак.', '<ol><li>Разогрейте сковороду на сильном огне. Подрумяньте каждую лепёшку по 30 секунд с каждой стороны, затем уложите в миску или форму, чтобы она остыла в виде чаши.</li><li>Разогрейте в сковороде масло, 2 минуты обжарьте чеснок и лук, затем добавьте нарезанный сладкий перец и жарьте ещё 2 минуты.</li><li>Добавьте томаты, фасоль, паприку, зиру, соль, перец и большую часть кинзы. Доведите до кипения, проварите минуту и уменьшите огонь.</li><li>Сделайте ложкой три углубления, разбейте в них яйца, накройте крышкой и готовьте около 3 минут, проверяя готовность с 2-й минуты.</li><li>Разложите томатную смесь с яйцами по лепёшкам-мисочкам и посыпьте оставшейся кинзой.</li></ol><p><em>Подавайте сразу с кинзой, кубиками авокадо, сметаной и тёртым сыром по желанию.</em></p>', CURRENT_TIMESTAMP),
  ('68da5295-af5e-53f2-b4b0-5d131604089e', 'ebe3a7bf-38bc-5c41-b384-5f1598aabe20', 'en', 'Huevos rancheros tortilla bowls', 'Eggs poached in a tomato sauce with black beans and sweet pepper, served in charred flour tortilla bowls. A hearty Mexican-style breakfast.', '<ol><li>Heat a pan over high heat. Char each tortilla for 30 seconds per side, then press into a bowl or dish so it cools into a bowl shape.</li><li>Heat the oil in a pan, sauté the garlic and onion for 2 minutes, then add the diced pepper and cook 2 more minutes.</li><li>Add the tomatoes, beans, paprika, cumin, salt, pepper and most of the coriander. Bring to a simmer, cook for 1 minute, then lower the heat.</li><li>Make three wells with a spoon, crack an egg into each, cover and cook for about 3 minutes, checking from the 2-minute mark.</li><li>Spoon the tomato mixture and eggs into the tortilla bowls and top with the remaining coriander.</li></ol><p><em>Serve at once with coriander and optional diced avocado, sour cream and grated cheese.</em></p>', CURRENT_TIMESTAMP),
  ('5d5a656c-1c46-59f2-a774-40e753916ed7', '1f3f4a8f-f68f-5b47-a0b7-5a5c6d3740bf', 'ru', 'Кошари', 'Египетское блюдо из риса с чечевицей, пасты и нута под пряным томатным соусом с хрустящим жареным луком. Сытное и постное.', '<ol><li>Тонкие кольца крупного лука посолите, обваляйте в муке и стряхните лишнее. Жарьте в разогретом масле на среднем-сильном огне 15–20 минут, часто помешивая, до хруста и золотисто-коричневого цвета без подгорания.</li><li>Для соуса обжарьте на масле тёртый лук до золотистого цвета, добавьте чеснок, кориандр и хлопья перца и жарьте 30–45 секунд. Влейте томатный соус, посолите и варите около 15 минут до загустения, затем добавьте уксус и держите на слабом огне под крышкой.</li><li>Залейте чечевицу 1 л воды, доведите до кипения и варите на слабом огне 15–17 минут, пока она почти готова, но ещё упругая. Слейте воду и слегка посолите.</li><li>Смешайте в кастрюле чечевицу и промытый, замоченный на 15 минут рис с 1 ст. л. масла, солью, перцем и кориандром, прогрейте 3 минуты. Залейте тёплой водой выше уровня на 3–4 см (около 750 мл), доведите до кипения, накройте и готовьте 20 минут до впитывания воды. Оставьте под крышкой на 5 минут.</li><li>Отдельно отварите макароны до состояния аль денте в подсоленной воде с каплей масла и откиньте. Нут прогрейте.</li><li>Рыхлый рис с чечевицей выложите на блюдо, сверху распределите макароны, половину соуса, нут и половину хрустящего лука. Остальной соус и лук подайте отдельно.</li></ol><p><em>Подайте соус и жареный лук отдельно, чтобы каждый добавил по вкусу.</em></p>', CURRENT_TIMESTAMP),
  ('d5d96660-68de-531c-b0e4-e811cce737c2', '1f3f4a8f-f68f-5b47-a0b7-5a5c6d3740bf', 'en', 'Koshari', 'Egyptian dish of rice and lentils with pasta and chickpeas, topped with spiced tomato sauce and crispy fried onions. Filling and fully plant-based.', '<ol><li>Salt the onion rings, toss in flour and shake off the excess. Fry in hot oil over medium-high heat for 15–20 minutes, stirring often, until crisp and deep golden but not burnt.</li><li>For the sauce cook the grated onion in oil until golden, add the garlic, coriander and chilli flakes and fry for 30–45 seconds. Pour in the tomato sauce, season and simmer for about 15 minutes until thick, then stir in the vinegar and keep warm on low heat, covered.</li><li>Cover the lentils with about 1 litre of water, bring to a boil and simmer for 15–17 minutes until just tender but still firm. Drain and lightly salt.</li><li>Combine the lentils and the rice (rinsed and soaked for 15 minutes) in a pot with 1 tbsp oil, salt, pepper and coriander and stir for 3 minutes. Add warm water to about 3–4 cm above the level (around 750 ml), boil, cover and cook for 20 minutes until absorbed. Leave covered for 5 minutes.</li><li>Separately cook the pasta al dente in salted water with a little oil and drain. Warm the chickpeas.</li><li>Fluff the rice and lentils onto a platter and top with the pasta, half of the sauce, the chickpeas and half of the crispy onions. Serve the remaining sauce and onions separately.</li></ol><p><em>Serve the sauce and crispy onions on the side so everyone can add their own.</em></p>', CURRENT_TIMESTAMP),
  ('ed33cd38-3a15-5d53-8c43-153b4027f91e', 'a9373702-f0ab-50b7-bf96-c3d22bae9187', 'ru', 'Тушёная говядина с зелёной фасолью (фасолия)', 'Близневосточное рагу из говядины с зелёной фасолью и помидорами, приправленное душистым перцем, корицей и кориандром.', '<ol><li>Посолите и поперчите кубики говядины, слегка обваляйте в муке.</li><li>В кастрюле с толстым дном или утятнице разогрейте масло и обжарьте мясо со всех сторон, затем переложите на тарелку.</li><li>В том же горшке коротко обжарьте лук с чесноком, добавьте помидоры, томатную пасту, душистый перец, паприку, корицу, кориандр, соль и перец. Готовьте около 3 минут.</li><li>Верните мясо, влейте воду, добавьте лавровый лист, доведите до кипения на 5 минут, затем накройте и тушите на слабом огне 1,5 часа.</li><li>Добавьте замороженную фасоль и немного соли, перемешайте, накройте и тушите ещё 45 минут. Выньте лавровый лист.</li><li>Разложите рагу по тарелкам и посыпьте обжаренными кедровыми орешками и петрушкой.</li></ol><p><em>Подавайте с рисом или хлебом, посыпав кедровыми орешками и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('e7d975d5-7259-5bbd-ab6d-fd9eb1bfb15d', 'a9373702-f0ab-50b7-bf96-c3d22bae9187', 'en', 'Beef and green bean stew (fasolia)', 'A Middle Eastern stew of beef, green beans and tomatoes seasoned with allspice, cinnamon and coriander.', '<ol><li>Season the beef cubes with salt and pepper and coat lightly in flour.</li><li>Heat the oil in a heavy pot or Dutch oven and brown the beef on all sides, then set it aside.</li><li>In the same pot briefly cook the onion and garlic, then add the tomatoes, tomato paste, allspice, paprika, cinnamon, coriander, salt and pepper and cook for about 3 minutes.</li><li>Return the beef, pour in the water, add the bay leaf, boil for 5 minutes, then cover and simmer on low for 1½ hours.</li><li>Stir in the frozen green beans and a little salt, cover and simmer for another 45 minutes. Discard the bay leaf.</li><li>Ladle into bowls and top with toasted pine nuts and parsley.</li></ol><p><em>Serve over rice or with bread, topped with pine nuts and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('5a9e1af3-b935-5a39-930f-52a1d87f88ac', '6cbbfc64-b2ee-5638-9599-75af7d07c1e6', 'ru', 'Паста карбонара с печёными томатами', 'Лёгкий вариант карбонары: лингвини в сливочном соусе из яиц и сыра с запечёнными с чесноком и орегано помидорами и свежей зеленью.', '<ol><li>Разогрейте духовку до 230 °C. Выложите половинки помидоров на противень, полейте маслом, посолите, поперчите, добавьте паприку, 1 ч. л. орегано и 2 измельчённых зубчика чеснока, перемешайте и разложите в один слой.</li><li>Запекайте около 20 минут, пока помидоры не станут мягкими и не осядут.</li><li>Пока томаты запекаются, взбейте яйца и желток с 2 ст. л. масла, тёртыми сырами, петрушкой, базиликом, оставшимся орегано, перцем и оставшимся чесноком.</li><li>Отварите пасту в подсоленной воде. Слейте её в дуршлаг над большой миской, чтобы прогреть миску горячей водой. Оставьте 1 стакан воды от варки, остальное вылейте.</li><li>Быстро смешайте горячую пасту, ½ стакана воды от варки и яичную смесь в тёплой миске за 1–2 минуты, добавляя воду по необходимости. Вмешайте томаты с соком и подавайте сразу.</li></ol><p><em>Подавайте сразу с тёртым сыром, базиликом и хлопьями перца; по желанию добавьте тонкие ломтики прошутто.</em></p>', CURRENT_TIMESTAMP),
  ('adff5749-9e1d-52aa-a796-1622bab1de24', '6cbbfc64-b2ee-5638-9599-75af7d07c1e6', 'en', 'Carbonara with roasted tomatoes', 'A lighter carbonara: linguine in a creamy egg and cheese sauce with tomatoes roasted with garlic and oregano and fresh herbs.', '<ol><li>Heat the oven to 230°C. Put the halved tomatoes on a baking sheet, drizzle with oil, season with salt, pepper, paprika, 1 tsp oregano and 2 minced garlic cloves, toss and spread in a single layer.</li><li>Roast for about 20 minutes until the tomatoes are soft and collapsed.</li><li>While the tomatoes roast, whisk the eggs and yolk with 2 tbsp oil, the grated cheeses, parsley, basil, remaining oregano, pepper and remaining garlic.</li><li>Cook the pasta in salted water. Drain it over a large bowl so the hot water warms the bowl. Keep 1 cup of the cooking water and discard the rest.</li><li>Quickly toss the hot pasta, ½ cup pasta water and the egg mixture in the warm bowl for 1–2 minutes, adding more water as needed. Fold in the roasted tomatoes with their juices and serve immediately.</li></ol><p><em>Serve immediately with extra grated cheese, basil and chilli flakes; add thin ribbons of prosciutto if you like.</em></p>', CURRENT_TIMESTAMP),
  ('06fe7c67-dcc7-54fe-b61d-b1d6667c484d', '9fabe559-177b-51d7-9928-a3477f08f5cf', 'ru', 'Фрикадельки в томатном соусе со спагетти', 'Сочные мясные шарики из говяжьего фарша и колбасного мяса, обжаренные и протушенные в томатном соусе с чесноком. Подаются со спагетти и пармезаном.', '<ol><li>Выдавите мясо из колбасок в большую миску, добавьте говяжий фарш, чеснок, половину петрушки, сухари и яйцо, посолите, поперчите и хорошо вымесите.</li><li>Посыпьте доску мукой. Формируйте шарики из столовых ложек фарша (руки можно смазать маслом) и обваливайте в муке.</li><li>Обжарьте фрикадельки партиями в 3 ст. л. масла со всех сторон, переложите на тарелку. Слейте лишний жир, сковороду вытрите.</li><li>Для соуса разогрейте 1 ст. л. масла, на несколько секунд обжарьте чеснок, добавьте томаты и разомните их. Варите 5 минут на среднем-сильном огне до загустения, посолите, поперчите и добавьте щепотку сахара.</li><li>Верните фрикадельки в соус, накройте крышкой и тушите на слабом огне около 30 минут, иногда поливая соусом. За 15 минут до конца отварите спагетти.</li><li>Добавьте в соус большую часть оставшейся петрушки, выложите фрикадельки с соусом на спагетти и посыпьте зеленью.</li></ol><p><em>Посыпьте рубленой петрушкой, тёртый пармезан подайте отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('b8a04b6c-ccb1-5553-a57f-ca1c34fc0fdf', '9fabe559-177b-51d7-9928-a3477f08f5cf', 'en', 'Meatballs in tomato sauce with spaghetti', 'Juicy meatballs made from beef mince and sausage meat, browned and simmered in a garlicky tomato sauce. Served over spaghetti with Parmesan.', '<ol><li>Squeeze the meat out of the sausages into a large bowl, add the beef mince, garlic, half the parsley, breadcrumbs and egg, season with salt and pepper and mix well.</li><li>Dust a board with flour. Roll spoonfuls of the mixture into balls (oil your hands if it helps) and coat them in flour.</li><li>Brown the meatballs in batches in 3 tbsp oil on all sides and set aside. Pour off excess fat and wipe the pan.</li><li>For the sauce heat 1 tbsp oil, fry the garlic for a few seconds, add the tomatoes and break them down. Cook for 5 minutes over medium-high heat until thickened, then season with salt, pepper and a pinch of sugar.</li><li>Return the meatballs to the sauce, cover and simmer on low heat for about 30 minutes, spooning the sauce over now and then. Cook the spaghetti for the last 15 minutes.</li><li>Stir most of the remaining parsley into the sauce, spoon the meatballs and sauce over the spaghetti and scatter with parsley.</li></ol><p><em>Sprinkle with chopped parsley and serve grated Parmesan on the side.</em></p>', CURRENT_TIMESTAMP),
  ('4c5f9731-432f-5215-958b-92c5c5af54d2', 'c69264ef-e64a-5743-9aee-d891d1cf3c88', 'ru', 'Сармале (голубцы в листьях квашеной капусты)', 'Румынские голубцы: листья квашеной капусты с начинкой из свиного фарша, риса и лука, долго тушатся в томатно-пряном бульоне с копчёной грудинкой.', '<ol><li>Обжаривайте лук в масле на среднем огне около 20 минут до мягкости и золотистого цвета, при необходимости подливая воды. Переложите в большую миску и остудите.</li><li>Отварите рис 10–12 минут до состояния аль денте, откиньте и добавьте к луку. Хлеб без корки замочите на 5 минут, отожмите и добавьте туда же.</li><li>Добавьте фарш, тимьян, паприку, 1 ч. л. соли и 1 ч. л. перца, хорошо вымесите руками и уберите в холодильник.</li><li>Разверните листья капусты и ополосните холодной водой. Срежьте толстую часть черешка. Нужно около 34–36 хороших листьев; обрезки и лишние листья отложите.</li><li>Выложите на широкий край листа около 1 ст. л. фарша, сформируйте колбаску длиной 5 см, плотно закрутите, подверните края и дозаверните. Уложите швом вниз.</li><li>Покройте дно широкой жаропрочной кастрюли нашинкованными обрезками и листьями. Плотно уложите голубцы по кругу, между ними разместите кубики грудинки, сверху накройте оставшейся капустой.</li><li>Смешайте томатную пасту, паприку и сушёный укроп, постепенно влейте 750 мл воды. Залейте голубцы, накройте крышкой, доведите до кипения, затем тушите на самом слабом огне около 3 часов до мягкости, периодически встряхивая кастрюлю.</li></ol><p><em>Подавайте со сметаной, свежим укропом и мамалыгой или картофельным пюре. На следующий день вкуснее.</em></p>', CURRENT_TIMESTAMP),
  ('74793b2b-7f6f-5428-aed1-548a3e01c4b3', 'c69264ef-e64a-5743-9aee-d891d1cf3c88', 'en', 'Sarmale (stuffed sauerkraut rolls)', 'Romanian stuffed cabbage: sauerkraut leaves filled with pork, rice and onion and slowly braised in a tomato and spice broth with smoked pancetta.', '<ol><li>Cook the onion in oil over medium heat for about 20 minutes until soft and golden, adding a splash of water if it starts to burn. Tip into a large bowl and cool.</li><li>Boil the rice for 10–12 minutes until al dente, drain and add to the onion. Soak the crustless bread for 5 minutes, squeeze it dry and add it too.</li><li>Add the pork mince, thyme, paprika, 1 tsp salt and 1 tsp pepper, mix well by hand and chill.</li><li>Unroll the cabbage leaves and rinse under cold water. Trim away the thick stem at the base. You need about 34–36 good leaves; keep the trimmings and spare leaves.</li><li>Put about 1 tbsp of filling at the wide end of each leaf, shape into a 5 cm log, roll tightly, fold in the sides and finish rolling. Place seam-side down.</li><li>Cover the base of a wide, heavy pot with shredded trimmings and leaves. Pack the rolls in a circle, tuck the pancetta between them and top with the remaining shredded cabbage.</li><li>Whisk together the tomato paste, paprika and dried dill, then gradually add 750 ml water. Pour over the rolls, cover, bring to a boil and then simmer on the lowest heat for about 3 hours until very tender, shaking the pan occasionally.</li></ol><p><em>Serve with soured cream, fresh dill and polenta or mashed potatoes. Even better the next day.</em></p>', CURRENT_TIMESTAMP),
  ('aee92cf8-3d1e-5aa9-8f31-bf49446833c8', '428426c1-c77a-5578-b7f4-c2a41f08991d', 'ru', 'Крем-суп из лука-порея и картофеля (вишисуаз)', 'Нежный бархатистый суп-пюре из картофеля, лука-порея и лука со сливками и молоком. Подаётся горячим или холодным.', '<ol><li>В кастрюле с толстым дном растопите 50 г масла. Когда оно запенится, добавьте кубики картофеля, лук и нарезанный порей и перемешайте, чтобы овощи покрылись маслом.</li><li>Посолите и поперчите, накройте овощи кружком пергамента и крышкой и томите на слабом огне 10 минут, пока овощи не станут мягкими, не меняя цвета.</li><li>Снимите пергамент, влейте 850 мл бульона, доведите до кипения и варите около 5 минут, пока овощи не будут готовы. Не переваривайте.</li><li>Пюрируйте суп до гладкости, при необходимости порциями. Верните в кастрюлю, влейте примерно три четверти сливок и молоко.</li><li>Тонко нашинкуйте белую часть порея и на небольшом количестве масла томите несколько минут без окраски. Прогрейте суп до слабого кипения, разлейте по тарелкам, добавьте оставшиеся сливки, порей и шнитт-лук.</li></ol><p><em>Украсьте обжаренными в масле тонкими полосками порея, рубленым шнитт-луком и чёрным перцем.</em></p>', CURRENT_TIMESTAMP),
  ('0defe4cb-0e45-5286-a252-9bd19c9bcb86', '428426c1-c77a-5578-b7f4-c2a41f08991d', 'en', 'Leek and potato soup (vichyssoise)', 'A smooth, velvety purée of potatoes, leeks and onion finished with cream and milk. Delicious hot or chilled.', '<ol><li>Melt 50 g of the butter in a heavy saucepan. When it foams, add the potato cubes, onion and sliced leeks and toss to coat them in the butter.</li><li>Season with salt and pepper, cover the vegetables with a disc of baking paper and a lid and sweat over low heat for 10 minutes until soft but not coloured.</li><li>Remove the paper, pour in 850 ml stock, bring to a boil and simmer for about 5 minutes until the vegetables are just cooked. Don''t overcook.</li><li>Purée the soup until silky smooth, in batches if needed. Return to the pan and stir in about three quarters of the cream and the milk.</li><li>Thinly shred the white part of a leek and soften it in a little butter for a few minutes without colouring. Reheat the soup to a gentle simmer, ladle into bowls and top with the remaining cream, buttered leeks and chives.</li></ol><p><em>Top with thin leek strips softened in butter, chopped chives and black pepper.</em></p>', CURRENT_TIMESTAMP),
  ('791495a2-c7e3-5bc2-ae4e-c3c3aa9657fe', '75063660-1b3b-5d3e-85b0-ff48fdfec8be', 'ru', 'Бефстроганов из говяжьего фарша с пастой', 'Быстрый вариант бефстроганова: говяжий фарш с шампиньонами и луком в сливочно-сметанном соусе с паприкой. Подаётся с широкой пастой.', '<ol><li>Разогрейте масло в глубокой сковороде на сильном огне. Выложите фарш, разровняйте лопаткой и оставьте на 4–5 минут, чтобы подрумянился, затем переверните и обжарьте с другой стороны. Переложите в миску, жир оставьте в сковороде.</li><li>Обжарьте лук 5–6 минут до мягкости, добавьте грибы и жарьте 7–8 минут, часто помешивая, пока не испарится вся жидкость и грибы не потемнеют.</li><li>Добавьте чеснок и паприку на 30 секунд, всыпьте муку и перемешайте. Постепенно влейте бульон, помешивая до гладкого густого соуса. Доведите до кипения, уменьшите огонь, влейте сливки и сметану, посолите и поперчите.</li><li>Верните фарш в сковороду, добавьте уксус, вустерский и соевый соусы, прогрейте несколько минут и посыпьте петрушкой. Подавайте с отваренной пастой.</li></ol><p><em>Подавайте с широкими лентами пасты, картофельным пюре или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('1169479d-79e6-512b-bc65-9ce07261a2c3', '75063660-1b3b-5d3e-85b0-ff48fdfec8be', 'en', 'Ground beef stroganoff with pasta', 'A quick weeknight stroganoff: beef mince with mushrooms and onion in a creamy paprika sauce, served over wide pasta ribbons.', '<ol><li>Heat the oil in a large deep pan over high heat. Crumble in the mince, flatten it and leave for 4–5 minutes to brown, then stir and brown the other side. Remove to a bowl, leaving the fat behind.</li><li>Cook the onion for 5–6 minutes until soft, then add the mushrooms and cook 7–8 minutes, stirring often, until their liquid has evaporated and they are golden.</li><li>Stir in the garlic and paprika for 30 seconds, then add the flour and stir to coat. Gradually pour in the stock, stirring to a smooth thick sauce. Bring to a boil, reduce to a bare simmer, add the cream and soured cream and season.</li><li>Return the mince to the pan with the vinegar, Worcestershire and soy sauces, cook for a few minutes and stir in the parsley. Serve with cooked pasta.</li></ol><p><em>Serve over wide pasta ribbons, mashed potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('23f182b0-d414-5f62-a811-68290ee22a5a', 'f3fe709d-a1fe-599f-8fdb-062c49cf6148', 'ru', 'Тонкие блинчики на молоке', 'Простые тонкие блинчики из муки, яиц и молока, которые легко печь на сковороде. Хороши с лимоном и сахаром или с любой начинкой.', '<ol><li>Взбейте в миске или кувшине муку, яйца, молоко, 1 ст. л. масла и щепотку соли до гладкого жидкого теста, по густоте как жидкие сливки.</li><li>По возможности дайте тесту постоять 30 минут, можно печь сразу.</li><li>Разогрейте сковороду на среднем огне и протрите её бумажным полотенцем, смоченным маслом.</li><li>Выливайте около половины половника теста и жарьте блинчик по 1 минуте с каждой стороны до золотистого цвета. Готовые блинчики держите тёплыми в слабо нагретой духовке.</li></ol><p><em>Подавайте с лимоном и сахаром, сметаной, вареньем или любой начинкой. Остывшие блинчики можно заморозить, перекладывая пергаментом.</em></p>', CURRENT_TIMESTAMP),
  ('d09c5b04-61e5-56f0-9acb-52cbca19ea1c', 'f3fe709d-a1fe-599f-8fdb-062c49cf6148', 'en', 'Easy thin pancakes (crêpes)', 'Simple thin pancakes from flour, eggs and milk, cooked in a frying pan. Delicious with lemon and sugar or any filling.', '<ol><li>Whisk the flour, eggs, milk, 1 tbsp oil and a pinch of salt in a bowl or jug into a smooth batter, about the consistency of single cream.</li><li>If you have time, rest the batter for 30 minutes, or start cooking straight away.</li><li>Heat a frying pan over medium heat and wipe it with oiled kitchen paper.</li><li>Pour in about half a ladle of batter per pancake and cook for 1 minute on each side until golden. Keep cooked pancakes warm in a low oven.</li></ol><p><em>Serve with lemon and sugar, jam or any filling. Cooled pancakes can be frozen layered with baking parchment.</em></p>', CURRENT_TIMESTAMP),
  ('bca2d981-4e43-5b54-9345-9a7c4c8a6932', '48432976-c76b-59be-a332-97c56a737ff4', 'ru', 'Борщ с говядиной', 'Классический борщ на говяжьем бульоне со свёклой, капустой, картофелем, морковью и помидорами. Заправка из тушёной свёклы и овощей придаёт яркий цвет и вкус.', '<ol><li>Промойте говядину, нарежьте кусочками по 2,5 см, залейте в большой кастрюле холодной водой, посолите и доведите до кипения. Сразу снимите пену, убавьте огонь и варите под неплотно закрытой крышкой 45–60 минут, периодически снимая пену.</li><li>Натрите свёклу на крупной тёрке. Обжаривайте её на большой сковороде с 4 ст. л. масла и уксусом 5 минут, затем убавьте огонь, добавьте сахар и томатный соус и тушите около 10 минут до мягкости. Переложите в миску.</li><li>В той же сковороде обжарьте лук в масле 2 минуты, добавьте тёртую морковь и готовьте ещё около 5 минут до мягкости, при необходимости подлив масла.</li><li>Когда мясо варится не менее 45 минут, добавьте нарезанный картофель и варите 10 минут. Затем положите капусту, свёклу, лук с морковью и нарезанные помидоры и варите ещё 10 минут, пока картофель не станет мягким.</li><li>Добавьте лавровый лист, перец и соль по вкусу. Положите рубленую петрушку и выдавленный чеснок, накройте крышкой, снимите с огня и оставьте на 20 минут настояться.</li></ol><p><em>Подавайте горячим со сметаной, свежей петрушкой или укропом.</em></p>', CURRENT_TIMESTAMP),
  ('fda8219f-aee5-57e9-8908-533b1f6e8922', '48432976-c76b-59be-a332-97c56a737ff4', 'en', 'Beef borscht', 'Classic borscht cooked in a beef broth with beets, cabbage, potatoes, carrots and tomatoes. A sautéed beet and vegetable base gives it its colour and flavour.', '<ol><li>Rinse the beef, cut into 2.5 cm pieces, put in a large pot with the cold water and salt and bring to a boil. Skim the foam at once, reduce the heat and simmer partly covered for 45–60 minutes, skimming from time to time.</li><li>Grate the beets on the large holes. Sauté them in a large skillet with 4 tbsp oil and the vinegar for 5 minutes, then lower the heat, add the sugar and tomato sauce and cook for about 10 minutes until starting to soften. Set aside.</li><li>In the same skillet fry the onion in butter for 2 minutes, add the grated carrot and cook about 5 more minutes until softened, adding oil if too dry.</li><li>Once the meat has cooked for at least 45 minutes, add the potatoes and cook for 10 minutes. Then add the cabbage, beets, onion and carrot and chopped tomatoes and cook another 10 minutes until the potatoes are tender.</li><li>Add the bay leaves, pepper and salt to taste. Stir in the chopped parsley and pressed garlic, cover, remove from the heat and let stand for 20 minutes.</li></ol><p><em>Serve hot with sour cream and fresh parsley or dill.</em></p>', CURRENT_TIMESTAMP),
  ('e9d49ad1-2efd-5f21-8b3e-cc9e938d7b53', '0aea3343-19de-5bfd-bf8a-5ea3afa71dcc', 'ru', 'Пельмени с курицей домашние', 'Домашние пельмени из мягкого теста на кефире и яйцах с сочной начинкой из куриного фарша, лука и чеснока. Можно сразу сварить или заморозить впрок.', '<ol><li>Для теста взбейте кефир, сметану, тёплую воду, яйца и соль до однородности. Подсыпайте муку по частям (сначала 4 стакана, затем по одному), каждый раз вымешивая. В конце добавляйте муку по ложке, пока тесто не перестанет липнуть, и вымешивайте ещё 5 минут. Тесто должно быть мягким и эластичным. Накройте плёнкой. Можно замешивать миксером с крюком или руками.</li><li>Для начинки обжарьте на масле лук 4–5 минут до золотистого цвета, добавьте чеснок на минуту и снимите с огня.</li><li>Смешайте куриный фарш с обжаренным луком и чесноком, солью, перцем и рубленой петрушкой.</li><li>Лепите вручную: из куска теста скатайте колбаску толщиной 3–5 см, нарезайте кусочки, раскатывайте в кружки диаметром около 4 см, на каждый кладите чайную ложку фарша, защипывайте полукругом, а затем соедините концы. Или используйте форму для пельменей: уложите раскатанное тесто, заполните ячейки по ½ ч. л. фарша, накройте вторым слоем теста и прокатайте скалкой.</li><li>Выложите пельмени на хорошо посыпанную мукой доску, присыпьте мукой и варите сразу или заморозьте на доске, а затем переложите в пакеты.</li><li>Доведите до кипения подсоленную воду, опустите свежие или замороженные (не размораживать) пельмени и верните до кипения. Когда всплывут, варите ещё 3 минуты. Откиньте и заправьте маслом и укропом.</li></ol><p><em>Подавайте горячими с растопленным маслом, сметаной, уксусом или кетчупом и укропом.</em></p>', CURRENT_TIMESTAMP),
  ('efa5ad53-bbf5-512e-a301-40914bf1f6f3', '0aea3343-19de-5bfd-bf8a-5ea3afa71dcc', 'en', 'Homemade chicken pelmeni', 'Homemade dumplings from a soft egg and buttermilk dough filled with juicy ground chicken, onion and garlic. Cook right away or freeze for later.', '<ol><li>For the dough whisk the buttermilk or kefir, sour cream, warm water, eggs and salt until blended. Add the flour in portions (4 cups first, then one cup at a time), mixing each time. Finally add flour a spoonful at a time until the dough stops sticking and knead 5 more minutes until soft and elastic. Cover with film. A stand mixer with a dough hook or your hands both work.</li><li>For the filling fry the onion in oil for 4–5 minutes until golden, add the garlic for a minute and remove from the heat.</li><li>Mix the ground chicken with the fried onion and garlic, salt, pepper and chopped parsley.</li><li>To shape by hand roll the dough into a log 3–5 cm thick, cut into pieces, roll each into a circle about 4 cm wide, put 1 tsp of filling in the centre, fold into a half-moon, pinch tightly and join the two corners. Or use a pelmeni mould: lay rolled dough on it, fill each pocket with ½ tsp filling, cover with a second sheet of dough and roll with a rolling pin.</li><li>Place the pelmeni on a well-floured board, dust with flour and cook straight away, or freeze on the board and then transfer to freezer bags.</li><li>Bring salted water to a boil, add fresh or frozen (do not defrost) pelmeni and return to a boil. When they float, cook 3 more minutes. Drain and toss with butter and dill.</li></ol><p><em>Serve hot with melted butter, sour cream, vinegar or ketchup and dill.</em></p>', CURRENT_TIMESTAMP),
  ('2996ecc3-1c45-5c5e-9ccf-113d821db868', 'a38154c3-a919-5379-a62d-869b58094a94', 'ru', 'Куриные котлеты на сковороде', 'Сочные котлеты из куриного фарша с тёртым луком, сметаной и сухарями, обжаренные до золотистой корочки.', '<ol><li>Залейте сухари молоком и оставьте на 5 минут.</li><li>Добавьте куриный фарш, сметану, соль, перец, яйцо и тёртый лук и хорошо перемешайте. Масса будет мягкой и влажной.</li><li>Мокрыми руками сформируйте овальные котлеты и обваляйте с двух сторон в муке.</li><li>Разогрейте на антипригарной сковороде на среднем огне 2–3 ст. л. масла, выложите котлеты, оставляя промежутки. Жарьте под крышкой около 5 минут с первой стороны и 3 минуты со второй, подливая масло между партиями.</li></ol><p><em>Подайте с картофельным пюре, гречкой или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('64477997-d715-5e3a-b140-39558f001cd7', 'a38154c3-a919-5379-a62d-869b58094a94', 'en', 'Pan-fried chicken kotleti', 'Juicy ground chicken patties with grated onion, sour cream and breadcrumbs, pan-fried until golden.', '<ol><li>Soak the breadcrumbs in the milk for 5 minutes.</li><li>Add the ground chicken, sour cream, salt, pepper, egg and grated onion and mix well. The mixture will be soft and moist.</li><li>With wet hands shape the mixture into oval patties and coat both sides in flour.</li><li>Heat 2–3 tbsp oil in a non-stick skillet over medium heat and add the patties, leaving space between them. Cover and cook about 5 minutes on the first side and 3 on the second, adding oil between batches.</li></ol><p><em>Serve with mashed potatoes, buckwheat or a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('c93b4d9e-7659-576a-baef-94f0b13d28f7', '3613ffb1-7316-5383-9433-5cfe2e220f34', 'ru', 'Сырники из творога', 'Румяные сырники из творога с яйцом и мукой, по желанию с изюмом. Мягкие внутри и с золотистой корочкой снаружи.', '<ol><li>Смешайте творог, яйца, 80 г муки, сахар и соль. Если масса слишком жидкая, чтобы брать ложкой, добавьте ещё немного муки.</li><li>Соду погасите уксусом, как только она зашипит, добавьте в творожную массу. Взбейте миксером до однородности, добавьте изюм, если используете.</li><li>Насыпьте оставшуюся муку в миску. Выкладывайте столовой ложкой массу в муку, обсыпьте сверху и обминайте в ладонях в небольшие лепёшки, стряхивая лишнюю муку.</li><li>Разогрейте на среднем огне сковороду с маслом и жарьте сырники по 3–4 минуты с каждой стороны до золотистого цвета, один раз переворачивая.</li></ol><p><em>Подавайте со сметаной, свежими ягодами, вареньем или сахарной пудрой.</em></p>', CURRENT_TIMESTAMP),
  ('e1497808-a232-5547-bb95-bed16a09b841', '3613ffb1-7316-5383-9433-5cfe2e220f34', 'en', 'Syrniki (cottage cheese pancakes)', 'Golden pancakes of farmers cheese with egg and flour, optionally with raisins. Soft inside and crisp outside.', '<ol><li>Mix the cheese, eggs, 80 g flour, sugar and salt. If the mixture is too loose to scoop, add a little more flour.</li><li>Mix the baking soda with the vinegar and, once it fizzes, stir into the cheese mixture. Beat with a hand mixer until uniform, then stir in the raisins if using.</li><li>Put the remaining flour in a bowl. Place a heaped spoonful of the mixture into the flour, sprinkle flour on top and pat into small patties between floured hands, shaking off the excess.</li><li>Heat the oil in a skillet over medium heat and fry the patties 3–4 minutes per side until golden, flipping once.</li></ol><p><em>Serve with sour cream, fresh berries, jam or powdered sugar.</em></p>', CURRENT_TIMESTAMP),
  ('38aea5ca-6c63-5496-b1fb-f8c23d0c8d84', '7ef4ab56-c8c2-5f06-9ed8-7c1cc5f1b952', 'ru', 'Жареная картошка с луком', 'Картофель, нарезанный дольками и обжаренный на сковороде с луком и сливочным маслом до румяной корочки. Простой домашний гарнир.', '<ol><li>Очистите картофель и нарежьте небольшими дольками или брусочками одинакового размера. Промойте, разложите и хорошо обсушите бумажным полотенцем.</li><li>Растопите на сковороде сливочное масло и 3 минуты обжаривайте нарезанный лук на среднем-сильном огне, часто помешивая.</li><li>Добавьте картофель и растительное масло, перемешайте, накройте крышкой и жарьте на среднем-сильном огне 4–5 минут до золотистого цвета.</li><li>Уменьшите огонь до среднего и готовьте около 15 минут, помешивая каждые 3–4 минуты. В конце посолите и поперчите. Картофель готов, когда крупный ломтик легко ломается.</li></ol><p><em>Подавайте горячей с квашеной капустой, солёными огурцами или котлетами.</em></p>', CURRENT_TIMESTAMP),
  ('03abbb2c-c87c-5990-9f15-f5052263f81b', '7ef4ab56-c8c2-5f06-9ed8-7c1cc5f1b952', 'en', 'Pan-fried potatoes with onion', 'Potato wedges fried in a skillet with onion and butter until golden. A simple home-style side dish.', '<ol><li>Peel the potatoes and cut into small wedges or sticks of even size. Rinse, spread out and pat dry thoroughly with paper towel.</li><li>Melt the butter in a pan and fry the diced onion for about 3 minutes over medium-high heat, stirring often.</li><li>Add the potatoes and oil, stir, cover and cook over medium-high heat for 4–5 minutes until golden.</li><li>Reduce to medium heat and cook for about 15 minutes, stirring every 3–4 minutes. Season with salt and pepper near the end. The potatoes are done when a larger piece breaks easily.</li></ol><p><em>Serve hot with sauerkraut, pickles or cutlets.</em></p>', CURRENT_TIMESTAMP),
  ('e094e520-fb88-5b35-bcd4-beedb16ee852', 'f307cf95-2e82-5f08-a86a-61255ca801ce', 'ru', 'Винегрет со свёклой и квашеной капустой', 'Классический русский салат из отварных свёклы, картофеля и моркови с солёными огурцами, квашеной капустой и луком, заправленный растительным маслом и уксусом.', '<ol><li>Варите свёклу в кастрюле около часа, пока нож не будет входить легко. Можно взять консервированную свёклу, её варить не нужно.</li><li>В другой кастрюле варите картофель и морковь около 30 минут, пока нож не будет свободно входить в картофель. Не переваривайте.</li><li>Слейте воду и полностью остудите овощи. Очистите свёклу, картофель и морковь.</li><li>Нарежьте кубиками огурцы, свёклу, картофель и морковь, мелко порубите лук. Свёклу переложите в отдельную миску и перемешайте с 1 ст. л. масла, чтобы она не красила остальные овощи.</li><li>Соедините все ингредиенты с квашеной капустой, оставшимся маслом и уксусом. При желании добавьте больше капусты или огурцов. Охладите до подачи.</li></ol><p><em>Хорошо охладите перед подачей; подойдёт как закуска или гарнир к рыбе и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('320e5358-838e-5e52-a9e4-240a960c12f1', 'f307cf95-2e82-5f08-a86a-61255ca801ce', 'en', 'Russian vinaigrette salad with beets and sauerkraut', 'Classic Russian salad of boiled beets, potatoes and carrots with pickles, sauerkraut and onion, dressed with vegetable oil and vinegar.', '<ol><li>Boil the beets for about an hour until a knife pierces them easily. You can use canned beets instead, which need no cooking.</li><li>In another pot boil the potatoes and carrots for about 30 minutes until a knife goes smoothly through the potatoes. Don''t overcook.</li><li>Drain the vegetables and let them cool completely, then peel the beets, potatoes and carrots.</li><li>Dice the pickles, beets, potatoes and carrots and finely chop the onion. Put the beets in a separate bowl and toss with 1 tbsp oil so they don''t colour the other vegetables.</li><li>Combine everything with the sauerkraut, the remaining oil and the vinegar. Add more sauerkraut or pickles to taste. Chill until serving.</li></ol><p><em>Serve well chilled as a starter or as a side for fish and meat.</em></p>', CURRENT_TIMESTAMP),
  ('3fbdc407-6736-523f-8e8f-9b08b71f4043', 'b19fc6c8-9503-5678-8c47-0c99496dfde8', 'ru', 'Грибной суп с картофелем и сливками', 'Сытный суп на курином бульоне с картофелем, морковью и шампиньонами, слегка сливочный и густоватый, с укропом.', '<ol><li>В большой кастрюле на среднем огне растопите сливочное масло, 5 минут обжаривайте морковь и зелёный лук.</li><li>Влейте бульон, добавьте соль, перец, укроп и лавровый лист. Положите нарезанный картофель, накройте крышкой и варите 15–20 минут, пока он не станет мягким, но не развалится.</li><li>На сковороде разогрейте оливковое масло и 5–7 минут обжаривайте грибы до лёгкого румянца, затем переложите в суп.</li><li>Смешайте сливки с мукой до гладкости, влейте тонкой струйкой в суп при помешивании и доведите до лёгкого кипения. Суп загустеет.</li></ol><p><em>Посыпьте свежим укропом и подайте с чёрным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('1f6d437a-30a5-5770-bc6c-2643945fe401', 'b19fc6c8-9503-5678-8c47-0c99496dfde8', 'en', 'Mushroom and potato cream soup', 'A hearty chicken-broth soup with potatoes, carrots and mushrooms, lightly creamy and slightly thick, seasoned with dill.', '<ol><li>Melt the butter in a large pot over medium heat and sauté the carrots and green onion for 5 minutes.</li><li>Pour in the broth and add the salt, pepper, dill and bay leaf. Add the diced potatoes, cover and cook for 15–20 minutes until tender but still firm.</li><li>Heat the olive oil in a skillet and sauté the mushrooms for 5–7 minutes until lightly browned, then add them to the soup.</li><li>Whisk the cream with the flour until smooth, stir slowly into the soup and bring to a gentle boil. The soup will thicken.</li></ol><p><em>Sprinkle with fresh dill and serve with dark bread.</em></p>', CURRENT_TIMESTAMP),
  ('6b7cf485-5a06-5256-a42f-da22707af38b', '3bea799e-9409-56cd-b0cc-49e4b509b539', 'ru', 'Фаршированные перцы с мясом и рисом', 'Болгарские перцы, начинённые смесью свиного и индюшиного фарша с рисом и морковью и протушенные в томатно-морковной подливе.', '<ol><li>Срежьте верхушки перцев и уберите семена. Вскипятите в большой кастрюле воду (не менее чем на две трети), добавьте 2 ст. л. уксуса и 1 ч. л. соли. Опустите перцы, накройте и доведите до кипения; через 3 минуты выключите огонь и оставьте под крышкой примерно на 45 минут, чтобы перцы размягчились. Сохраните 3 стакана (около 700 мл) этой воды.</li><li>На сковороде нагрейте 3 ст. л. масла и 1 ст. л. сливочного. Тушите 4 тёртые моркови до мягкости, добавьте половину томатного соуса и минуту перемешивайте. Снимите с огня.</li><li>В большой миске смешайте свиной и индюшиный фарш, отварной рис, яйца, морковную зажарку и 1 ст. л. соли.</li><li>Слейте воду с перцев. Наполните каждый перец фаршем доверху, не утрамбовывая. Плотно уложите перцы в ту же кастрюлю или в утятницу.</li><li>Для подливы обжарьте на 2 ст. л. масла 2 тёртые моркови до мягкости, добавьте сметану и оставшийся томатный соус, прогрейте минуту.</li><li>Вылейте подливу поверх перцев, добавьте 3 стакана сохранённой воды, доведите до слабого кипения, накройте и тушите 40 минут на среднем огне. Вместо плиты можно запекать закрытыми в утятнице при 230 °C 20–25 минут, затем 1 час при 180 °C.</li></ol><p><em>Подавайте горячими со сметаной и подливой из кастрюли.</em></p>', CURRENT_TIMESTAMP),
  ('20fc1e7a-5785-5d1b-91c6-ae4fa26fe36f', '3bea799e-9409-56cd-b0cc-49e4b509b539', 'en', 'Stuffed bell peppers with meat and rice', 'Bell peppers filled with a mix of ground pork, turkey, rice and carrots and simmered in a tomato and carrot gravy.', '<ol><li>Cut the tops off the peppers and remove the seeds. Boil a large pot of water (at least two-thirds full) with 2 tbsp vinegar and 1 tsp salt. Add the peppers, cover and bring to a boil; after 3 minutes turn off the heat and leave covered for about 45 minutes to soften. Reserve 3 cups (about 700 ml) of this water.</li><li>In a skillet heat 3 tbsp oil and 1 tbsp butter. Sauté 4 grated carrots until soft, add half of the tomato sauce and stir for 1 minute. Remove from the heat.</li><li>In a large bowl mix the ground pork, ground turkey, cooked rice, eggs, sautéed carrots and 1 tbsp salt.</li><li>Drain the peppers. Fill each one to the top with the meat mixture without pressing it down. Pack them snugly in the same pot or in a Dutch oven.</li><li>For the gravy sauté 2 grated carrots in 2 tbsp oil until soft, then add the sour cream and the remaining tomato sauce and warm for 1 minute.</li><li>Pour the gravy over the peppers, add the 3 cups of reserved water, bring to a light boil, cover and simmer for 40 minutes over medium heat. Alternatively bake covered in a Dutch oven at 230°C for 20–25 minutes, then 1 hour at 180°C.</li></ol><p><em>Serve hot with sour cream and the gravy from the pot.</em></p>', CURRENT_TIMESTAMP),
  ('bb62831c-a64c-596c-930a-01fa4867b38e', 'daca1cf3-33a4-559f-ad23-9f6c3ae111a4', 'ru', 'Ленивые голубцы в духовке', 'Те же вкусы голубцов без возни с листьями: котлеты из фарша с рисом и шинкованной капустой, запечённые в томатном соусе с луком и морковью.', '<ol><li>Разогрейте духовку до 220 °C, смажьте форму 23 × 33 см маслом. Нашинкуйте капусту тонкой соломкой, залейте кипятком в жаропрочной миске на 10 минут, слейте воду и отожмите.</li><li>Смешайте свиной и индюшиный фарш, капусту и охлаждённый отварной рис. Натрите в фарш половину лука, добавьте яйца, перец, соль и петрушку, хорошо вымесите. Сформируйте руками котлеты в виде «картофелин» (по ½ стакана массы) и уложите в форму.</li><li>Для соуса нагрейте масло и сливочное масло в кастрюле, 5 минут пассеруйте оставшийся мелко нарезанный лук, добавьте морковь и готовьте ещё 3 минуты. Влейте томатный соус и горячую воду, доведите до кипения, добавьте щепотку соли.</li><li>Залейте котлеты соусом почти полностью, накройте фольгой и запекайте на средней полке при 220 °C 40 минут.</li></ol><p><em>Подавайте по 2 штуки, полив соусом из формы и со сметаной или греческим йогуртом.</em></p>', CURRENT_TIMESTAMP),
  ('989f1d09-8ee4-53f8-8249-7e956cb4cde0', 'daca1cf3-33a4-559f-ad23-9f6c3ae111a4', 'en', 'Baked lazy cabbage rolls', 'All the flavours of stuffed cabbage without rolling leaves: patties of ground meat, rice and shredded cabbage baked in a tomato sauce with onion and carrot.', '<ol><li>Heat the oven to 220°C and oil a 23 × 33 cm baking dish. Slice the cabbage into thin strips, cover with boiling water in a heatproof bowl for 10 minutes, then drain and squeeze out the water.</li><li>Combine the ground pork, ground turkey, cabbage and cooled cooked rice. Grate half of the onion into the meat, add the eggs, pepper, salt and parsley and mix well. Shape into potato-shaped patties (about ½ cup each) and arrange in the dish.</li><li>For the sauce heat the oil and butter in a pot, soften the remaining finely diced onion for 5 minutes, add the carrot and cook 3 more minutes. Pour in the tomato sauce and hot water, bring to a boil and add a pinch of salt.</li><li>Pour the sauce over the patties until they are nearly covered, cover with foil and bake on the middle rack at 220°C for 40 minutes.</li></ol><p><em>Serve 2 patties per person, spooning the sauce from the dish over them, with sour cream or Greek yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('d2745896-889e-54c1-8743-05c79e31b1d1', '368967e0-4b55-55fd-8c4a-80db3b307eeb', 'ru', 'Плов с говядиной', 'Рассыпчатый плов с обжаренной говядиной, луком и морковью, приправленный зирой, паприкой и кориандром, с целой головкой чеснока.', '<ol><li>Обрежьте с говядины лишний жир и плёнки, обсушите бумажным полотенцем и нарежьте кусочками 1,5–2 см.</li><li>Сильно раскалите казан или кастрюлю с толстым дном, влейте масло и обжаривайте мясо 7 минут на сильном огне, часто помешивая. Сначала нужно хорошо разогреть посуду, иначе мясо пустит сок и будет сухим.</li><li>Убавьте огонь до среднего, добавьте лук и 5 минут обжаривайте до мягкости. Положите морковь, 1 ч. л. соли, перец, паприку, зиру и лавровый лист и готовьте ещё 5 минут.</li><li>Влейте 420 мл горячей воды, накройте крышкой и тушите на слабо-среднем огне 45 минут до мягкости мяса.</li><li>Тем временем промойте рис до прозрачной воды, чтобы он не слипался, и оставьте стекать.</li><li>Разровняйте рис по мясу, влейте 960 мл горячей воды, посыпьте 1,5 ч. л. соли и слегка перемешайте. Доведите до кипения, убавьте огонь и варите без крышки 10 минут, пока большая часть воды не впитается.</li><li>Срежьте у головки чеснока основание, воткните её срезом вниз в центр риса, посыпьте рис кориандром. Проткните рис в 7–10 местах, убавьте огонь, накройте крышкой и готовьте ещё 15 минут. Достаньте чеснок и лавровый лист и осторожно перемешайте.</li></ol><p><em>Хорошо разогревается: подрумяньте порцию на сковороде и подавайте с солёным огурцом.</em></p>', CURRENT_TIMESTAMP),
  ('2bd9b65c-8d9f-5477-a4ce-efa046c90221', '368967e0-4b55-55fd-8c4a-80db3b307eeb', 'en', 'Beef plov (rice pilaf)', 'Fluffy pilaf with browned beef, onion and carrot seasoned with cumin, paprika and coriander and a whole head of garlic in the rice.', '<ol><li>Trim the beef of excess fat and sinew, pat it dry and cut into 1.5–2 cm pieces.</li><li>Heat a Dutch oven or heavy pot over high heat, add the oil and sear the meat for 7 minutes, stirring often. Preheat the pot well first, otherwise the meat releases juice and turns dry.</li><li>Reduce the heat to medium, add the onion and cook 5 minutes until soft. Add the carrots, 1 tsp salt, pepper, paprika, cumin and bay leaves and cook 5 more minutes.</li><li>Add 420 ml hot water, cover and simmer over medium-low heat for 45 minutes until the meat is tender.</li><li>Meanwhile rinse the rice until the water runs clear so it doesn''t stick, then drain.</li><li>Spread the rice over the meat, pour in 960 ml hot water and sprinkle with 1½ tsp salt, stirring lightly. Bring to a boil, reduce the heat and cook uncovered for 10 minutes until most of the water is absorbed.</li><li>Cut the base off the garlic head and push it cut-side down into the centre of the rice, then sprinkle the rice with coriander. Poke 7–10 holes in the rice, turn the heat to low, cover and cook 15 more minutes. Remove the garlic and bay leaves and stir gently.</li></ol><p><em>It reheats well: crisp a portion in a skillet and serve with a pickle.</em></p>', CURRENT_TIMESTAMP),
  ('d283ff63-ea49-5ecc-a54b-4b85d7eefc86', 'e5afb7e1-bb57-5d46-b0f1-7f8eb8e59bbb', 'ru', 'Суп из квашеной капусты с беконом и фасолью (капустняк)', 'Сытный наваристый суп с квашеной капустой, картофелем, морковью, белой фасолью и обжаренным беконом, который придаёт лёгкий копчёный привкус.', '<ol><li>В большой кастрюле или утятнице разогрейте масло, обжарьте нарезанный бекон до румяности и переложите шумовкой в миску.</li><li>В тот же жир добавьте сельдерей и лук и пассеруйте около 5 минут до мягкости и золотистого цвета.</li><li>Добавьте морковь, картофель, бульон и воду, доведите до кипения, убавьте огонь и варите 15 минут.</li><li>Положите хорошо промытую и отжатую квашеную капусту, половину бекона, фасоль с её жидкостью и лавровый лист. Варите около 10 минут, пока картофель не станет мягким. Посолите и поперчите по вкусу, подайте с оставшимся беконом.</li></ol><p><em>Подавайте горячим со свежим хрустящим хлебом и по желанию со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('b7319890-b047-5a31-97a6-bddd51005394', 'e5afb7e1-bb57-5d46-b0f1-7f8eb8e59bbb', 'en', 'Sauerkraut soup with bacon and beans (kapustnyak)', 'A hearty soup of sauerkraut, potatoes, carrots, white beans and browned bacon that adds a subtle smokiness.', '<ol><li>Heat the oil in a large pot or Dutch oven, brown the chopped bacon and lift it out with a slotted spoon.</li><li>Add the celery and onion to the pot and cook about 5 minutes until soft and golden.</li><li>Add the carrots, potatoes, broth and water, bring to a boil, then reduce the heat and simmer 15 minutes.</li><li>Add the well-rinsed and drained sauerkraut, half of the bacon, the beans with their liquid and the bay leaf. Cook about 10 minutes until the potatoes are tender. Season with salt and pepper and top with the remaining bacon.</li></ol><p><em>Serve hot with crusty bread and sour cream if you like.</em></p>', CURRENT_TIMESTAMP),
  ('947c83bb-72d8-5287-a467-0911a57311d1', '5b497dbf-8fc0-5b24-9b59-6546663a6858', 'ru', 'Капустная запеканка с сыром и зеленью', 'Заливной капустный пирог без теста: много шинкованной капусты с укропом и зелёным луком под заливкой из яиц, сметаны и майонеза, с золотистой сырной корочкой.', '<ol><li>Разогрейте духовку до 190 °C и смажьте маслом круглую форму диаметром 23 см.</li><li>В миске взбейте яйца, сметану и майонез до однородности. В отдельной миске смешайте муку, разрыхлитель и крахмал, затем вмешайте сухую смесь в яичную до гладкости.</li><li>Тонко нашинкованную капусту посолите и 30 секунд разомните руками, чтобы она стала мягче. Добавьте зелёный лук и укроп.</li><li>Выложите капусту в форму, залейте равномерно тестом-заливкой, посыпьте тёртой моцареллой и выпекайте на средней полке около 35 минут до золотистой корочки.</li></ol><p><em>Подавайте горячей с зелёным луком, сметаной или салатом из свежих овощей.</em></p>', CURRENT_TIMESTAMP),
  ('832dbe2f-6ef7-586d-aade-ccd348adcbbe', '5b497dbf-8fc0-5b24-9b59-6546663a6858', 'en', 'Cabbage, egg and cheese casserole', 'A crustless cabbage pie: lots of shredded cabbage with dill and green onion under an egg, sour cream and mayonnaise batter with a golden cheesy top.', '<ol><li>Heat the oven to 190°C and butter a 23 cm round pie dish.</li><li>In a bowl whisk the eggs, sour cream and mayonnaise until blended. In a second bowl mix the flour, baking powder and cornstarch, then whisk this into the egg mixture until smooth.</li><li>Sprinkle the thinly sliced cabbage with salt and scrunch with your hands for 30 seconds to soften, then stir in the green onion and dill.</li><li>Spread the cabbage in the dish, pour the batter evenly over it, sprinkle with shredded mozzarella and bake on the middle rack for about 35 minutes until golden.</li></ol><p><em>Serve hot with green onion, sour cream or a fresh vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('5e68c3dd-d6e5-5de8-85e0-1f461c969887', '86dd3d1f-ac2b-5933-be5d-1912eb836700', 'ru', 'Уха с рыбой и креветками', 'Лёгкая, но ароматная уха с картофелем, морковью, белой рыбой и креветками и зажаркой из лука с сельдереем.', '<ol><li>В большой кастрюле на сильном огне смешайте воду, овощной бульон и 1 ст. л. соли. Добавьте нарезанный картофель, доведите до кипения и варите 10 минут.</li><li>Добавьте морковь и варите ещё 10 минут, пока готовите зажарку.</li><li>На сковороде на среднем-сильном огне нагрейте масло и 7 минут обжаривайте лук с сельдереем до мягкости и золотистого цвета. Переложите в кастрюлю.</li><li>Добавьте очищенные креветки, нарезанную рыбу, лавровый лист, перец и петрушку. Доведите до кипения и варите 5 минут до готовности рыбы и креветок. При необходимости досолите.</li></ol><p><em>Подавайте горячей с веточкой петрушки или укропа.</em></p>', CURRENT_TIMESTAMP),
  ('3b64ee1a-d525-5c49-8960-4939de79d16a', '86dd3d1f-ac2b-5933-be5d-1912eb836700', 'en', 'Fish and shrimp soup (ukha)', 'A light but flavourful soup with potatoes, carrots, white fish and shrimp and a fried onion and celery base.', '<ol><li>In a large pot over high heat combine the water, vegetable broth and 1 tbsp salt. Add the diced potatoes, bring to a boil and cook for 10 minutes.</li><li>Add the carrots and cook another 10 minutes while you make the sauté.</li><li>Heat the oil in a skillet over medium-high heat and sauté the onion and celery for 7 minutes until soft and golden. Add to the pot.</li><li>Add the peeled shrimp, chopped fish, bay leaves, pepper and parsley. Return to a boil and cook 5 minutes until the fish and shrimp are cooked through. Adjust the salt if needed.</li></ol><p><em>Serve hot with a sprig of parsley or dill.</em></p>', CURRENT_TIMESTAMP),
  ('77ccea3e-9537-5e65-b08c-b495d5e945ed', '670e2fc4-7b54-5ef2-a77f-d4df7a132a4e', 'ru', 'Быстрые чебуреки с мясом на тортильях', 'Упрощённые чебуреки: сырые пшеничные тортильи с сочной начинкой из говяжьего и свиного фарша с кинзой, петрушкой и зелёным луком, обжаренные на сковороде.', '<ol><li>Смешайте говяжий и свиной фарш миксером с лопаткой или руками.</li><li>Добавьте кинзу, петрушку и зелёный лук, посолите, поперчите и влейте молоко.</li><li>Выложите на половину тортильи около столовой ложки с горкой фарша, распределив по половине лепёшки и оставив по краю 2,5 см. Края смажьте водой, чтобы они хорошо склеились.</li><li>Сложите лепёшку пополам, прижмите края и проложите по ним вилкой, затем переверните и заделайте вилкой с другой стороны.</li><li>Нагрейте на среднем огне большую антипригарную сковороду с маслом, покрывающим дно. Жарьте чебуреки по 3 минуты с каждой стороны, при необходимости регулируя огонь. Выложите на бумажные полотенца. Для скорости используйте две сковороды.</li></ol><p><em>Остудите на бумажных полотенцах; осторожно откусывайте, внутри много сока. Подавайте со свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('9606b731-6398-5743-9616-0bbd1b9e396e', '670e2fc4-7b54-5ef2-a77f-d4df7a132a4e', 'en', 'Quick meat chebureki with tortillas', 'Simplified chebureki: raw flour tortillas filled with juicy beef and pork mince, cilantro, parsley and green onion and pan-fried.', '<ol><li>Mix the ground beef and ground pork with a stand mixer paddle or by hand.</li><li>Stir in the cilantro, parsley and green onion, then add the salt, pepper and milk.</li><li>Put a heaped tablespoon of filling on half of each tortilla, spreading it over that half and leaving a 2.5 cm border. Brush the border generously with water so it seals.</li><li>Fold the tortilla in half, press the edges together and seal with a fork, then flip and seal the other side too.</li><li>Heat a large non-stick skillet over medium heat with enough oil to cover the bottom. Fry the chebureki 3 minutes per side, adjusting the heat as needed, and drain on paper towels. Use two pans to go faster.</li></ol><p><em>Drain on paper towels and bite carefully, they are very juicy inside. Serve with fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('90e2401b-3ea9-525e-8789-5373e689d230', 'd744d9a4-50f7-5b9d-8432-495ed9aaa178', 'ru', 'Картофельные котлеты с сыром из пюре', 'Румяные оладьи из картофельного пюре с моцареллой, яйцом и шнитт-луком, обваляные в сухарях и обжаренные до золотистой корочки. Отлично использовать остатки пюре.', '<ol><li>Очистите картофель, разрежьте на четвертинки и варите в подсоленной воде до мягкости. Слейте воду, разомните с маслом в пюре и остудите до комнатной температуры. Пюре можно приготовить за 1–3 дня до этого.</li><li>Смешайте пюре с моцареллой, яйцом, мукой и частью шнитт-лука. Если масса слишком жидкая и не держит форму, добавляйте муку по столовой ложке.</li><li>Сформируйте из столовой ложки массы лепёшки толщиной около 8 мм и обваляйте с обеих сторон в сухарях.</li><li>Разогрейте на антипригарной сковороде на среднем огне масло, чтобы оно слегка покрывало дно. Обжаривайте котлеты в один слой по 3–4 минуты с каждой стороны до золотистого цвета, добавляя масло по мере необходимости.</li></ol><p><em>Подавайте горячими со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('b26d90b6-f2a5-5074-9ae5-4108d8afb881', 'd744d9a4-50f7-5b9d-8432-495ed9aaa178', 'en', 'Cheesy mashed potato pancakes', 'Golden patties of mashed potatoes with mozzarella, egg and chives, coated in breadcrumbs and pan-fried. A great way to use up leftover mash.', '<ol><li>Peel the potatoes, quarter them and boil in salted water until easily pierced with a fork. Drain, mash with the butter and cool to room temperature. The mash can be made 1–3 days ahead.</li><li>Combine the mashed potatoes with the mozzarella, egg, flour and most of the chives. If the mixture is too loose to hold a shape, add flour a tablespoon at a time.</li><li>Shape a heaped spoonful of the mixture into a round patty about 8 mm thick and coat both sides in breadcrumbs.</li><li>Heat enough oil to lightly cover the bottom of a non-stick pan over medium heat. Fry the patties in a single layer 3–4 minutes per side until golden, adding oil as needed.</li></ol><p><em>Serve hot with sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('c7f24c33-3442-5410-9e23-baffcf2650d0', 'cf7c6dcf-730e-5df8-97d0-fffdc8dba61d', 'ru', 'Крабовый салат с кукурузой и горошком', 'Классический праздничный салат из крабовых палочек, варёных яиц, лука, консервированных кукурузы и зелёного горошка с майонезом и каплей хрена.', '<ol><li>Сварите яйца вкрутую (около 10 минут), остудите и очистите.</li><li>Нарежьте крабовые палочки и яйца кубиками, мелко порубите лук. Сложите в большую миску вместе с хорошо отжатой кукурузой.</li><li>Добавьте майонез и хрен, перемешайте. В последнюю очередь осторожно вмешайте горошек, чтобы он не раздавился.</li></ol><p><em>Подавайте охлаждённым. В холодильнике салат хорошо хранится 2–3 дня.</em></p>', CURRENT_TIMESTAMP),
  ('f774115a-f65b-5cfc-9615-76b4c28ef1a2', 'cf7c6dcf-730e-5df8-97d0-fffdc8dba61d', 'en', 'Russian crab stick salad with corn and peas', 'Classic festive salad of imitation crab, hard-boiled eggs, onion, canned corn and peas dressed with mayonnaise and a touch of horseradish.', '<ol><li>Hard-boil the eggs (about 10 minutes), cool and peel them.</li><li>Dice the crab sticks and the eggs and finely chop the onion. Put them in a large bowl with the well-drained corn.</li><li>Add the mayonnaise and horseradish and mix. Fold in the peas last so they don''t break.</li></ol><p><em>Serve chilled. It keeps well in the fridge for 2–3 days.</em></p>', CURRENT_TIMESTAMP),
  ('a491f87b-352b-5366-be80-1300f2f5fa6c', '88e4fc11-bb75-5631-aded-692c6cf66fbe', 'ru', 'Картофельный салат с огурцом, редисом и яйцом', 'Сливочный картофельный салат с хрустящими огурцом, редисом и сельдереем, варёными яйцами и зеленью в заправке из майонеза, сметаны и горчицы.', '<ol><li>Положите картофель в кожуре в кастрюлю, залейте водой, доведите до кипения, добавьте соль и варите на среднем кипении около 25 минут, пока вилка не будет входить легко. Не переваривайте.</li><li>Достаньте картофель, полностью остудите, очистите и нарежьте кубиками перед добавлением в салат. Сварите яйца вкрутую, остудите и нарежьте.</li><li>Смешайте майонез, сметану, горчицу, соль и перец и уберите заправку в холодильник.</li><li>Аккуратно перемешайте в большой миске картофель, огурец, тонко нарезанный редис, сельдерей, яйца и лук. Добавьте заправку по вкусу, при необходимости досолите и поперчите.</li></ol><p><em>Посыпьте рубленым шнитт-луком и свежемолотым перцем. Подавайте охлаждённым.</em></p>', CURRENT_TIMESTAMP),
  ('866707a6-80a9-5b67-be1a-97b76df5b990', '88e4fc11-bb75-5631-aded-692c6cf66fbe', 'en', 'Creamy potato salad with cucumber, radish and egg', 'Creamy potato salad with crunchy cucumber, radishes and celery, hard-boiled eggs and herbs in a mayonnaise, sour cream and mustard dressing.', '<ol><li>Put the unpeeled potatoes in a pot, cover with water, bring to a boil, add salt and cook at a medium boil for about 25 minutes until easily pierced with a fork. Don''t overcook.</li><li>Lift out the potatoes, cool completely, then peel and dice just before adding to the salad. Hard-boil, cool and dice the eggs.</li><li>Stir together the mayonnaise, sour cream, mustard, salt and pepper and refrigerate the dressing.</li><li>Gently toss the potatoes, cucumber, thinly sliced radishes, celery, eggs and green onion in a large bowl. Add dressing to taste and adjust the salt and pepper.</li></ol><p><em>Garnish with chopped chives and freshly cracked pepper. Serve chilled.</em></p>', CURRENT_TIMESTAMP),
  ('0b9d7dcd-78e3-557b-9e97-8ad8407165f6', '57eeef5c-5cc2-51d9-b520-1c439186b244', 'ru', 'Шакшука с картофелем и баклажанами', 'Яйца, запечённые в густом томатном соусе с луком и перцем, с хрустящим печёным картофелем и баклажанами. Блюдо на завтрак, обед или ужин.', '<ol><li>Разогрейте духовку до 230 °C, выстелите два противня пергаментом. Нарежьте картофель кусочками 2,5–4 см, ополосните и обсушите. Посолите, поперчите, смешайте с 2 ст. л. оливкового масла, разложите на первом противне и запекайте 25–30 минут до хрустящей золотистой корочки.</li><li>Баклажан нарежьте кусочками примерно 2,5 × 5 см, посолите, поперчите, сбрызните 3 ст. л. масла и разложите на втором противне. Запекайте около 15 минут до мягкости и румяных краёв, затем уберите и остудите.</li><li>Разведите куриный бульонный концентрат небольшим количеством тёплой воды до пасты. В глубокой сковороде или утятнице на среднем огне нагрейте 2 ст. л. масла, 2 минуты обжарьте лук, добавьте перец и жарьте 5 минут, часто помешивая.</li><li>Влейте томатный соус, нарезанные помидоры и воду и доведите до кипения (будьте осторожны, брызгает). Добавьте чеснок, халапеньо, 1 ч. л. соли, ½ ч. л. перца и пасту из бульона, хорошо перемешайте и прогрейте пару минут на сильном огне.</li><li>Разбейте яйца по одному в небольшую миску и вылейте в соус, начиная от краёв. Слегка посолите и поперчите. Положите вокруг яиц запечённые баклажаны и картофель.</li><li>Убавьте огонь до средне-слабого, накройте крышкой и готовьте 6–8 минут, проверяя яйца каждые 1–2 минуты, пока белок не схватится, а желток не достигнет нужной степени готовности.</li></ol><p><em>Подавайте прямо в сковороде со свежим мягким хлебом, чтобы макать в соус.</em></p>', CURRENT_TIMESTAMP),
  ('540f9a5f-b8c1-5f45-9b6a-06eb2f8515a7', '57eeef5c-5cc2-51d9-b520-1c439186b244', 'en', 'Shakshuka with potatoes and eggplant', 'Eggs poached in a thick tomato sauce with onion and peppers, with crisp baked potatoes and eggplant. Good for breakfast, lunch or dinner.', '<ol><li>Heat the oven to 230°C and line two baking sheets with parchment. Cut the potatoes into 2.5–4 cm pieces, rinse and dry. Season, toss with 2 tbsp olive oil, spread on the first sheet and bake 25–30 minutes until golden and crisp.</li><li>Cut the eggplant into pieces of about 2.5 × 5 cm, season, drizzle with 3 tbsp oil and spread on the second sheet. Bake about 15 minutes until soft and browning, then take out and let cool.</li><li>Mix the chicken bouillon with a little warm water to make a paste. In a deep pan or Dutch oven over medium heat heat 2 tbsp oil, cook the onion for 2 minutes, add the peppers and cook 5 minutes, stirring often.</li><li>Add the tomato sauce, diced tomatoes and water and bring to a boil (careful, it splatters). Stir in the garlic, jalapeño, 1 tsp salt, ½ tsp pepper and bouillon paste, mix well and cook a couple of minutes over high heat.</li><li>Crack the eggs one at a time into a small bowl and slide them into the sauce, starting at the edges. Lightly season. Arrange the baked eggplant and potatoes around the eggs.</li><li>Reduce to medium-low, cover and cook 6–8 minutes, checking the eggs every 1–2 minutes until the whites are set and the yolks are as you like them.</li></ol><p><em>Serve straight from the pan with soft fresh bread for dipping in the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('f8d72753-c2a9-5a9b-abe2-306b8ad8e114', '2588f7fe-7279-5f65-9dad-2a035d84cc58', 'ru', 'Маринованный салат из капусты со свёклой и чесноком', 'Хрустящая капуста с тёртой свёклой и чесноком, маринованная в сладко-кислой заливке с маслом. Готовится заранее и хранится в холодильнике около недели.', '<ol><li>Для маринада в кастрюле смешайте воду, масло, уксус, сахар и соль, доведите до кипения, снимите с огня и остудите до комнатной температуры.</li><li>Мелко нашинкуйте капусту (удобно на тёрке-мандолине, используйте защитную перчатку) и сложите в самую большую миску. Натрите свёклу или нарежьте соломкой, добавьте в миску, мелко нарежьте чеснок и тоже добавьте.</li><li>Залейте овощи остывшим маринадом и перемешайте. Придавите грузом (большая тарелка и ёмкость с водой), чтобы маринад поднялся на поверхность. Оставьте в прохладном месте или в холодильнике на 7–10 часов или на ночь.</li><li>Переложите салат в большую стеклянную банку и держите в холодильнике до подачи. В холодильнике он хранится около недели.</li></ol><p><em>Достаточно выдержать 7–10 часов или ночь под гнётом. Подавайте как холодную закуску или гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('4cb8047e-2523-5467-a4cc-1c779bf8cbb8', '2588f7fe-7279-5f65-9dad-2a035d84cc58', 'en', 'Marinated cabbage and beet salad with garlic', 'Crisp shredded cabbage with grated beets and garlic marinated in a sweet and sour oil dressing. Made ahead and keeps in the fridge for about a week.', '<ol><li>For the marinade combine the water, oil, vinegar, sugar and salt in a saucepan, bring to a boil, remove from the heat and cool to room temperature.</li><li>Finely shred the cabbage (a mandoline is easiest, use a cut-resistant glove) and put it in your largest bowl. Grate the beets or cut into matchsticks and add them, then finely dice the garlic and add it as well.</li><li>Pour the cooled marinade over the vegetables and stir. Weigh the cabbage down (a large plate and a bowl of water) so the marinade rises to the surface. Leave in a cool place or the fridge for 7–10 hours or overnight.</li><li>Transfer the salad to a large glass jar and keep refrigerated until serving. It keeps in the fridge for about a week.</li></ol><p><em>Leave it weighted down for 7–10 hours or overnight. Serve cold as a starter or side.</em></p>', CURRENT_TIMESTAMP),
  ('51432b89-48e4-56e8-a763-8211195061c7', '3eb0d63c-e042-5fdf-bc24-6b967ada138d', 'ru', 'Баклажанная икра', 'Закуска из обжаренных до мягкости баклажанов с луком, морковью, чесноком и томатной сальсой. Намазывают на тосты или хлеб.', '<ol><li>На сковороде нагрейте 2–3 ст. л. масла на среднем-сильном огне, 7 минут обжаривайте лук и морковь до мягкости, часто помешивая. Добавьте чеснок и жарьте 1–2 минуты, постоянно помешивая. Отставьте.</li><li>Мелко нарежьте баклажаны кубиками (так икра лучше намазывается). В другой большой сковороде нагрейте 4–5 ст. л. масла на среднем-сильном огне, выложите баклажаны, посолите, поперчите и жарьте без крышки около 10 минут, часто помешивая, до полной мягкости. При прилипании добавьте масла.</li><li>Влейте сальсу и добавьте овощи с луком и морковью, перемешайте и прогрейте минуту. Подавайте с подсушенным хлебом или крекерами.</li></ol><p><em>Подавайте тёплой или холодной на тостах, хлебе или крекерах.</em></p>', CURRENT_TIMESTAMP),
  ('d4c92880-62c8-52f1-bb10-736064ef8fbc', '3eb0d63c-e042-5fdf-bc24-6b967ada138d', 'en', 'Eggplant caviar spread', 'An appetizer of eggplant fried until very soft with onion, carrot, garlic and tomato salsa. Spread on toast or bread.', '<ol><li>Heat 2–3 tbsp oil in a skillet over medium-high heat and cook the onion and carrot for 7 minutes until soft, stirring often. Add the garlic and cook 1–2 minutes, stirring constantly. Set aside.</li><li>Finely dice the eggplants (this makes the spread easier to spread). Heat 4–5 tbsp oil in a second large skillet over medium-high heat, add the eggplant with the salt and pepper and cook uncovered for about 10 minutes, stirring often, until very soft. Add oil if it sticks.</li><li>Stir in the salsa and the onion and carrot mixture, mix well and heat for a minute. Serve with toasted bread or crackers.</li></ol><p><em>Serve warm or cold on toast, bread or crackers.</em></p>', CURRENT_TIMESTAMP),
  ('4a481980-7716-564e-bf8d-d07ac089a2a1', '716fcfee-b6f3-5142-a6f2-3486b15439d3', 'ru', 'Куриный салат с укропом и сельдереем', 'Быстрый салат из готовой курицы с сельдереем, зелёным луком и укропом в горчично-майонезной заправке.', '<ol><li>Разберите готовую курицу на волокна, смешайте с нарезанным зелёным луком, сельдереем и рубленым укропом.</li><li>Смешайте майонез, дижонскую горчицу, цедру и сок лимона, добавьте щепотку соли и перца.</li><li>Заправьте курицу соусом, перемешайте и при необходимости досолите.</li></ol><p><em>Подавайте на ломтиках хлеба или с листьями салата.</em></p>', CURRENT_TIMESTAMP),
  ('9b396292-0dce-5d7a-9be5-16304e574252', '716fcfee-b6f3-5142-a6f2-3486b15439d3', 'en', 'Chicken, celery and dill salad', 'A quick salad of cooked chicken, celery, spring onions and dill in a mustard-mayonnaise dressing.', '<ol><li>Shred the cooked chicken and mix it with sliced spring onions, celery and chopped dill.</li><li>Stir together the mayonnaise, Dijon mustard and lemon zest and juice, then add a pinch of salt and pepper.</li><li>Toss the chicken mixture with the dressing and adjust the seasoning.</li></ol><p><em>Serve on slices of bread or with salad leaves.</em></p>', CURRENT_TIMESTAMP),
  ('f48e6bac-8da1-5ce1-a2a6-e7b1088673d1', '4e7d21ad-4f71-5977-8084-47c3f318c600', 'ru', 'Кабачки на сковороде с бальзамической глазурью', 'Обжаренные в оливковом масле кружочки кабачка с густой бальзамической глазурью, кунжутом и сушёной мятой.', '<ol><li>Для глазури прогрейте в кастрюле бальзамический уксус с коричневым сахаром, доведите до кипения и томите на среднем огне около 20 минут. Снимите с огня и остудите 10 минут: глазурь загустеет.</li><li>Пока варится глазурь, разогрейте на сковороде оливковое масло. Выложите кабачки кружочками толщиной около 6 мм, посолите, поперчите и посыпьте паприкой.</li><li>Обжаривайте на среднем и сильном огне, помешивая, 7–10 минут, пока кабачки не станут мягкими и не подрумянятся с обеих сторон.</li><li>Переложите кабачки на блюдо, полейте глазурью, посыпьте кунжутом и сушёной мятой.</li></ol><p><em>Подавайте тёплыми или комнатной температуры к мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('4ee14756-ffb6-5868-b682-78637945e8a0', '4e7d21ad-4f71-5977-8084-47c3f318c600', 'en', 'Skillet zucchini with balsamic glaze', 'Zucchini rounds sauteed in olive oil and drizzled with a thick balsamic glaze, sesame seeds and dried mint.', '<ol><li>For the glaze, heat the balsamic vinegar with the brown sugar, bring to a boil and simmer over medium-low heat for about 20 minutes. Take off the heat and cool for 10 minutes; it will thicken.</li><li>Meanwhile, heat the olive oil in a large skillet. Add the zucchini rounds, about 6 mm thick, and season with salt, pepper and paprika.</li><li>Saute over medium-high heat, tossing occasionally, for 7–10 minutes until softened and golden on both sides.</li><li>Transfer the zucchini to a platter, drizzle with the glaze and sprinkle with sesame seeds and dried mint.</li></ol><p><em>Serve warm or at room temperature with meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('b4eb56b9-54c8-5272-a3c4-d380d1464b0f', '7b7c19c9-be90-5b9f-809a-110f0bff8d36', 'ru', 'Салат из арбуза с фетой и мятой', 'Освежающий летний салат из сочного арбуза, красного лука, феты и мяты с оливковой заправкой.', '<ol><li>Срежьте мякоть арбуза, удалите косточки и нарежьте кусочками. Лук очистите и тонко нарежьте.</li><li>Смешайте винный уксус с солью и перцем до растворения соли, затем тонкой струйкой вмешайте оливковое масло. Добавьте рубленую мяту.</li><li>Соедините арбуз, лук и раскрошенную фету, полейте заправкой и аккуратно перемешайте. Украсьте веточками мяты.</li></ol><p><em>Хорошо подходит к шашлыку и другим блюдам на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('3122da0f-f0b9-5308-91a7-cb5b4bfb5194', '7b7c19c9-be90-5b9f-809a-110f0bff8d36', 'en', 'Watermelon, feta and mint salad', 'A refreshing summer salad of juicy watermelon, red onion, feta and mint with an olive oil dressing.', '<ol><li>Cut the flesh from the watermelon, remove the seeds and cube it. Peel the onion and slice it thinly.</li><li>Whisk the vinegar with salt and pepper until the salt dissolves, then slowly whisk in the olive oil. Stir in the chopped mint.</li><li>Combine the watermelon, onion and crumbled feta, pour over the dressing and toss gently. Garnish with mint sprigs.</li></ol><p><em>Great alongside barbecue and grilled dishes.</em></p>', CURRENT_TIMESTAMP),
  ('0bdf3756-a4b0-5336-b4ac-23cdecc8d664', '66f728a3-4384-59d3-8d20-0b78667bbc0e', 'ru', 'Окрошка с ветчиной на сметане', 'Холодный летний суп из варёного картофеля, яиц, огурцов и ветчины на воде со сметаной и уксусом. Освежает в жару и готовится без масла.', '<ol><li>Очистите картофель, нарежьте мелкими кубиками, залейте водой, добавьте 1 ст. л. уксуса и варите около 10 минут, пока не станет мягким, но не развалится. Слейте воду и остудите, при желании сполосните холодной водой.</li><li>Пока варится картофель, сварите яйца вкрутую и остудите их в ледяной воде.</li><li>Нарежьте кубиками яйца, огурцы и ветчину, мелко порубите укроп и зелёный лук. Сложите всё в большую кастрюлю вместе с картофелем.</li><li>В отдельной миске взбейте холодную воду со сметаной, оставшимся уксусом и солью. Влейте в кастрюлю, перемешайте и подавайте охлаждённой.</li></ol><p><em>Подавайте охлаждённой, по желанию добавьте ложку сметаны.</em></p>', CURRENT_TIMESTAMP),
  ('f5b4902b-2b6c-5937-b0ab-7d4a277183ec', '66f728a3-4384-59d3-8d20-0b78667bbc0e', 'en', 'Okroshka with ham and sour cream', 'A chilled Russian summer soup of boiled potatoes, eggs, cucumbers and ham in a tangy sour cream and vinegar broth. Refreshing on a hot day and made without any oil.', '<ol><li>Peel the potatoes, dice them small, cover with water, add 1 tbsp vinegar and boil about 10 minutes until tender but not falling apart. Drain and cool, rinsing with cold water if you want it faster.</li><li>While the potatoes cook, hard-boil the eggs and cool them in ice water.</li><li>Dice the eggs, cucumbers and ham, and finely chop the dill and green onions. Put everything into a large pot together with the potatoes.</li><li>In a separate bowl whisk the cold water with the sour cream, the rest of the vinegar and the salt. Pour into the pot, stir and serve chilled.</li></ol><p><em>Serve well chilled, with an extra spoonful of sour cream if you like.</em></p>', CURRENT_TIMESTAMP),
  ('a0b0525b-c40d-5855-9cdc-bbb11ed5136b', 'a2f15aca-915f-517c-b87c-ecbddedcc978', 'ru', 'Суп-голубцы с говяжьим фаршем', 'Густой томатный суп с обжаренным говяжьим фаршем, капустой и овощами. По вкусу напоминает голубцы, но готовится гораздо проще.', '<ol><li>В жаровне или глубокой кастрюле разогрейте 1 ст. л. масла на среднем огне и обжарьте фарш 4–5 минут, разбивая лопаткой, до готовности. Посолите и поперчите.</li><li>Добавьте ещё 1 ст. л. масла и лук, готовьте 2–3 минуты до мягкости. Добавьте чеснок на 30 секунд.</li><li>Добавьте капусту, морковь, сельдерей, томаты, томатный соус, бульон, сахар, соль, перец и лавровый лист. Доведите до кипения, убавьте огонь, накройте крышкой и варите 30 минут.</li><li>Выньте лавровый лист, добавьте рубленую зелень и при необходимости досолите.</li></ol><p><em>Подавайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('1a2baf31-cdcb-5bb7-9369-3832207300ac', 'a2f15aca-915f-517c-b87c-ecbddedcc978', 'en', 'Cabbage roll soup with ground beef', 'A thick tomato soup with browned ground beef, cabbage and vegetables. It tastes like stuffed cabbage rolls without the fuss.', '<ol><li>Heat 1 tbsp oil in a Dutch oven over medium-high heat and brown the beef for 4-5 minutes, breaking it up with a spatula, until cooked through. Season with a little salt and pepper.</li><li>Add another 1 tbsp oil and the onion and cook 2-3 minutes until tender. Add the garlic for 30 seconds.</li><li>Add the cabbage, carrot, celery, tomatoes, tomato sauce, broth, sugar, salt, pepper and bay leaves. Bring to a boil, reduce to a simmer, cover and cook 30 minutes.</li><li>Remove the bay leaves, stir in the chopped herbs and adjust the seasoning.</li></ol><p><em>Serve with a dollop of sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('3f71fb2e-9361-5f78-a1d7-c18910bf2203', 'a4a2c5fe-c29e-5c44-b3ed-5fe0b139c587', 'ru', 'Овощной суп с картофелем и стручковой фасолью', 'Постный овощной суп на томатной основе с морковью, сельдереем, картофелем, фасолью, кукурузой и горошком. Готовится меньше часа.', '<ol><li>Разогрейте в кастрюле с толстым дном оливковое масло на среднем огне. Обжарьте лук и морковь 6–8 минут, помешивая, до золотистого цвета.</li><li>Добавьте сельдерей, томаты с соком, бульон, картофель, стручковую фасоль, лавровый лист, соль и перец. Доведите до кипения, убавьте огонь и варите 25 минут.</li><li>Когда овощи станут мягкими, добавьте кукурузу, горошек, зелёный лук и петрушку. Варите ещё 5–8 минут, досолите и подавайте.</li></ol><p><em>Подавайте горячим с хлебом или сухариками.</em></p>', CURRENT_TIMESTAMP),
  ('876f5d29-a969-5696-9a9d-07d2cb4b3cc3', 'a4a2c5fe-c29e-5c44-b3ed-5fe0b139c587', 'en', 'Vegetable soup with potatoes and green beans', 'A hearty tomato-based vegetable soup with carrots, celery, potatoes, green beans, corn and peas. Ready in under an hour.', '<ol><li>Heat the olive oil in a heavy pot over medium heat. Sauté the onion and carrots 6-8 minutes, stirring occasionally, until golden.</li><li>Add the celery, tomatoes with juice, broth, potatoes, green beans, bay leaves, salt and pepper. Bring to a boil, reduce the heat and simmer 25 minutes.</li><li>When the vegetables are tender, add the corn, peas, green onion and parsley. Simmer 5-8 more minutes, adjust the salt and serve.</li></ol><p><em>Serve hot with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('0ed43a57-bc40-513c-9fff-3fa31a789c51', 'f25e59ff-7fc1-5598-9c88-e2b24001d2d5', 'ru', 'Говяжье рагу в красном вине, запечённое в духовке', 'Говядина с беконом, грибами, морковью и картофелем, медленно томлёная в духовке в винно-томатном бульоне. Мясо получается очень мягким.', '<ol><li>В жаропрочной кастрюле на среднем огне обжарьте нарезанный бекон до золотистого цвета. Шумовкой переложите бекон в миску, жир оставьте.</li><li>Посолите и поперчите говядину, обваляйте в муке. Обжаривайте в два захода в беконовом жире на среднем-сильном огне по 3 минуты с каждой стороны, при необходимости добавьте оливковое масло. Переложите к бекону.</li><li>Влейте в кастрюлю вино, доведите до кипения, соскребая со дна румяные кусочки. Добавьте нарезанные грибы и варите на среднем огне около 10 минут.</li><li>Тем временем на сковороде разогрейте 2 ст. л. оливкового масла и 4 минуты обжарьте морковь, лук и чеснок. Добавьте томатную пасту и готовьте ещё минуту. Переложите овощи в кастрюлю.</li><li>Влейте бульон, добавьте лавровый лист, тимьян, соль и перец. Верните в кастрюлю мясо с беконом и положите картофель так, чтобы он был покрыт жидкостью. Накройте крышкой и запекайте при 165 °C (325 °F) 1 час 45 минут.</li></ol><p><em>Подавайте со свежим хлебом или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('035d2b81-b329-53d6-a1bd-5b115700e2f9', 'f25e59ff-7fc1-5598-9c88-e2b24001d2d5', 'en', 'Oven beef stew with red wine', 'Beef with bacon, mushrooms, carrots and potatoes, slowly braised in the oven in a red wine and tomato broth until very tender.', '<ol><li>In an oven-safe pot over medium heat, cook the chopped bacon until golden. Lift it out with a slotted spoon into a bowl, leaving the fat in the pot.</li><li>Season the beef with salt and pepper and toss with the flour. Brown it in two batches in the bacon fat over medium-high heat, about 3 minutes per side, adding olive oil if needed. Move it to the bowl with the bacon.</li><li>Pour the wine into the pot, bring to a boil and scrape up the browned bits from the bottom. Add the sliced mushrooms and simmer over medium heat about 10 minutes.</li><li>Meanwhile, heat 2 tbsp olive oil in a skillet and sauté the carrots, onion and garlic for 4 minutes. Add the tomato paste and cook another minute. Transfer the vegetables to the pot.</li><li>Add the broth, bay leaves, thyme, salt and pepper. Return the beef and bacon to the pot and add the potatoes, making sure they are submerged. Cover and bake at 165 °C (325 °F) for 1 hour 45 minutes.</li></ol><p><em>Serve with fresh bread or over mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('d76f1cd8-4ef2-52b0-8e8a-881fb3b8bf55', 'e98a185c-7628-5087-bc6c-be9c4b242727', 'ru', 'Суп с фрикадельками из свинины', 'Сытный домашний суп с картофелем, морковью, вермишелью и свиными фрикадельками, с обжаренными луком и сельдереем и свежим укропом.', '<ol><li>Влейте в большую кастрюлю воду и куриный бульон, добавьте 2 ч. л. соли и нарезанный кубиками картофель. Доведите до кипения и варите 10 минут.</li><li>Нарежьте морковь тонкими кружочками и добавьте в суп. Всыпьте вермишель, поломанную на кусочки примерно по 1 см.</li><li>Смешайте фарш с половиной нарезанного лука, перцем, 2 ч. л. соли и одним яйцом. Скатайте небольшие фрикадельки и по мере готовности опускайте в кипящий суп.</li><li>Варите ещё минимум 10 минут, пока фрикадельки не будут готовы и не всплывут.</li><li>На сковороде разогрейте масло и обжарьте оставшийся лук с мелко нарезанным сельдереем до мягкости и золотистого цвета. Добавьте в суп.</li><li>По желанию влейте взбитое яйцо тонкой струйкой, постоянно помешивая, чтобы не было комков. Добавьте укроп, посолите и поперчите по вкусу.</li></ol><p><em>Подавайте горячим со сметаной и свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('eb8b102f-11ba-5139-8861-952d81a67022', 'e98a185c-7628-5087-bc6c-be9c4b242727', 'en', 'Pork meatball soup', 'A hearty family soup with potatoes, carrots, thin pasta and pork meatballs, finished with sautéed onion and celery and fresh dill.', '<ol><li>Pour the water and chicken stock into a large pot, add 2 tsp salt and the cubed potatoes. Bring to a boil and cook 10 minutes.</li><li>Slice the carrots thinly and add them to the pot. Add the spaghetti broken into roughly 1 cm pieces.</li><li>Mix the ground pork with half of the diced onion, pepper, 2 tsp salt and one egg. Roll small meatballs and drop them into the simmering soup as you go.</li><li>Cook at least 10 more minutes, until the meatballs are cooked through and float to the top.</li><li>Heat the oil in a skillet and sauté the remaining onion and the finely diced celery until soft and golden. Add to the soup.</li><li>If you like, pour in a beaten egg in a thin stream, stirring constantly to avoid clumps. Stir in the dill and season with salt and pepper to taste.</li></ol><p><em>Serve hot with sour cream and fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('96f53a43-a73b-5886-bbdd-679517b23280', '0b8eb281-9bed-58b0-b958-66bfb3c93e4e', 'ru', 'Куриный суп с яичной лапшой на домашнем бульоне', 'Наваристый суп на бульоне из курицы на кости с овощами, зеленью и яичной лапшой. Классическая еда для утешения в холодный день.', '<ol><li>Разделите курицу на части (крылья, голени и т. д.), кожу оставьте, лишний жир срежьте. Тяжёлым ножом рассеките кости вдоль, чтобы бульон получился насыщеннее.</li><li>В большой кастрюле (не менее 8 л) соедините курицу, половинку лука, лавровый лист, проколотые зубчики чеснока и тимьян. Залейте водой, доведите до кипения и снимите пену. Убавьте огонь до слабого и варите под неплотной крышкой 1,5 часа.</li><li>Выньте курицу, дайте немного остыть и снимите мясо с костей, кости выбросьте. Накройте мясо, чтобы не обветрилось. Процедите бульон через сито, застеленное бумажным полотенцем.</li><li>Ополосните кастрюлю и поставьте на средний огонь. Разогрейте 2 ст. л. оливкового масла и 5 минут обжаривайте сельдерей, морковь и лук до мягкости.</li><li>Влейте бульон, добавьте соль и перец и варите на лёгком кипении ещё 15 минут.</li><li>Добавьте мясо и лапшу и варите до готовности лапши по инструкции (около 20 минут). Снимите с огня, добавьте петрушку и укроп и разлейте по тарелкам.</li></ol><p><em>Подавайте горячим, с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('7914d283-691d-516f-8d9c-dbed5d7fd07e', '0b8eb281-9bed-58b0-b958-66bfb3c93e4e', 'en', 'Homemade chicken noodle soup with egg noodles', 'A rich soup built on a homemade bone-in chicken broth with vegetables, fresh herbs and plump egg noodles. Classic comfort food.', '<ol><li>Separate the chicken into pieces (wings, drumsticks, etc.), leave the skin on and trim excess fat. Chop through the bones with a heavy knife so more flavor goes into the broth.</li><li>In a large pot (at least 8 qt) combine the chicken, halved onion, bay leaves, pierced garlic cloves and thyme. Add the water, bring to a boil and skim off the foam. Reduce to a very low simmer and cook partially covered for 1½ hours.</li><li>Remove the chicken, let it cool a little and pull the meat off the bones, discarding the bones. Cover the meat so it stays moist. Strain the broth through a sieve lined with a paper towel.</li><li>Rinse the pot and set it over medium heat. Heat 2 tbsp olive oil and sauté the celery, carrots and diced onion for 5 minutes until softened.</li><li>Return the broth to the pot, season with salt and pepper and simmer lightly for another 15 minutes.</li><li>Add the shredded chicken and noodles and cook until the noodles are done according to the package (about 20 minutes). Remove from the heat, stir in the parsley and dill and ladle into bowls.</li></ol><p><em>Serve hot with bread.</em></p>', CURRENT_TIMESTAMP),
  ('ca859220-8f41-5c7e-8d8b-519a65bb1249', '96cfa5dc-98b9-5118-be9d-681767cceb02', 'ru', 'Курица с рисом в сливочном соусе в одной кастрюле', 'Курица, рис и овощи с чесноком, томлёные в бульоне и белом вине. В конце добавляются сливочное масло и пармезан, благодаря чему блюдо получается нежным и сливочным.', '<ol><li>В жаровне или кастрюле с плотной крышкой разогрейте на среднем-сильном огне оливковое масло и 2 ст. л. сливочного. Добавьте лук, морковь и 1 ч. л. соли, обжаривайте 8–10 минут до мягкости и золотистого цвета.</li><li>Добавьте куриные бёдра, нарезанные кусочками по 2,5 см, лавровый лист, ещё 1 ч. л. соли и перец. Обжарьте, помешивая, до золотистого цвета (около 5 минут).</li><li>Сделайте огонь сильным, влейте вино и упарьте почти полностью, соскребая со дна румяные кусочки. Влейте горячий бульон и всыпьте рис.</li><li>Срежьте верхушку головки чеснока, чтобы открылись зубчики, корень не отделяйте. Поставьте чеснок срезом вниз в центр риса. Доведите до кипения, убавьте огонь до слабого, накройте и варите 15 минут до готовности риса.</li><li>Снимите с огня, выньте чеснок (зубчики можно выдавить в рис). Быстро вмешайте оставшиеся 2 ст. л. сливочного масла, затем петрушку и пармезан до кремовой текстуры. Подавайте сразу.</li></ol><p><em>Посыпьте свежей петрушкой и тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('4a935fde-4654-5e93-81d2-3f442d0f776e', '96cfa5dc-98b9-5118-be9d-681767cceb02', 'en', 'One-pot creamy chicken and rice', 'Chicken thighs, rice, vegetables and garlic simmered in broth and white wine, finished with butter and Parmesan for a creamy texture.', '<ol><li>In a Dutch oven or heavy pot with a tight lid, heat the olive oil and 2 tbsp butter over medium-high heat. Add the onion, carrots and 1 tsp salt and sauté 8-10 minutes until soft and golden.</li><li>Add the chicken thighs cut into 1 inch pieces, bay leaves, another 1 tsp salt and the pepper. Sauté, stirring now and then, until golden on all sides (about 5 minutes).</li><li>Turn the heat to high, add the wine and boil it down almost completely, scraping the bottom. Pour in the hot broth and stir in the rice.</li><li>Slice the top off the head of garlic to expose the cloves, keeping the root end intact. Set it cut-side down in the center of the rice. Bring to a rolling boil, reduce to low, cover and simmer 15 minutes until the rice is cooked.</li><li>Take off the heat and remove the garlic (squeeze the cloves into the rice if you like). Quickly stir in the remaining 2 tbsp butter, then the parsley and Parmesan until creamy. Serve right away.</li></ol><p><em>Top with fresh parsley and extra grated Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('b292a9ac-1e6a-5fa7-a55a-46b2c6c0f232', 'eabfdd15-4e0c-5649-a9aa-e69641c0ad6c', 'ru', 'Мясной рулет из говяжьего фарша с кетчуповой глазурью', 'Запечённый хлебец из говяжьего фарша с луком, чесноком и зеленью, покрытый сладко-кисловатой глазурью. Хорошо сочетается с картофельным пюре и овощами.', '<ol><li>Застелите противень с бортиками пергаментом или фольгой. Разогрейте духовку до 175 °C.</li><li>На сковороде на среднем огне разогрейте масло и обжарьте лук 5–7 минут до мягкости и золотистого цвета. Переложите на тарелку и остудите.</li><li>Смешайте в большой миске все ингредиенты для мясной массы вместе с остывшим луком, перемешивайте только до однородности, лучше руками.</li><li>Выложите фарш на противень и сформируйте буханку примерно 20 см в длину, 10 см в ширину и 7 см в высоту. Запекайте без крышки при 175 °C 40 минут.</li><li>Смешайте ингредиенты глазури. Покройте ею рулет и верните в духовку ещё на 20 минут, пока температура внутри не достигнет 71 °C. Дайте отдохнуть 10–15 минут и нарежьте.</li></ol><p><em>Дайте отдохнуть 10–15 минут перед нарезкой. Подавайте с пюре и запечённой брокколи.</em></p>', CURRENT_TIMESTAMP),
  ('bf65727f-f546-5657-846f-9258d4294bb9', 'eabfdd15-4e0c-5649-a9aa-e69641c0ad6c', 'en', 'Beef meatloaf with ketchup glaze', 'A baked loaf of ground beef with onion, garlic and parsley, topped with a sweet and tangy ketchup glaze. Goes well with mashed potatoes and roasted vegetables.', '<ol><li>Line a rimmed baking sheet with parchment or foil. Preheat the oven to 175 °C (350 °F).</li><li>Heat the oil in a skillet over medium heat and sauté the onion 5-7 minutes until soft and golden. Move to a plate to cool.</li><li>In a large bowl combine all the meatloaf ingredients with the cooled onion and mix just until combined, ideally by hand.</li><li>Shape the meat on the pan into a loaf about 8 in long, 4 in wide and 3 in tall. Bake uncovered at 175 °C (350 °F) for 40 minutes.</li><li>Stir the glaze ingredients together. Spread it over the loaf and bake another 20 minutes, until the internal temperature reaches 71 °C (160 °F). Rest 10-15 minutes, then slice.</li></ol><p><em>Rest 10-15 minutes before slicing. Serve with mashed potatoes and roasted broccoli.</em></p>', CURRENT_TIMESTAMP),
  ('008c024b-efc0-5019-adbe-5f1772c9f8c1', '9c979096-72e5-55bf-9fdc-cee5e1b7de64', 'ru', 'Свиной шницель в сухарях панко', 'Свиные отбивные отбивают до тонких пластов, панируют и обжаривают до хрустящей корочки и сочной серединки. Обязательно подавайте с дольками лимона.', '<ol><li>Срежьте лишний жир со свинины и нарежьте её на пласты толщиной около 1,3 см. Положите между двумя слоями плёнки и отбейте молотком до толщины примерно 6 мм.</li><li>Приготовьте три миски: в первой смешайте муку, чесночную соль, паприку и перец, во второй взбейте яйца, в третью насыпьте панко.</li><li>Обваляйте каждый пласт с двух сторон в муке, стряхните излишки, обмакните в яйцо и плотно обваляйте в панко. Выложите в один слой на противень.</li><li>Налейте в большую сковороду масло слоем около 3 мм и разогрейте на среднем-сильном огне примерно до 175 °C (крошка панко должна сразу шипеть, но не гореть). Жарьте порциями по 2–3 минуты с каждой стороны до золотистого цвета, пока внутри не будет 63 °C. Если румянится слишком быстро, убавьте огонь.</li><li>Переложите шницели на решётку, посыпьте солью, дайте 3 минуты отдохнуть и подавайте с лимоном.</li></ol><p><em>Подавайте с дольками лимона, картофелем или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e4fff4df-6707-58f9-9fa3-6f774fb238a1', '9c979096-72e5-55bf-9fdc-cee5e1b7de64', 'en', 'Pork schnitzel with panko crust', 'Pork chops pounded into thin cutlets, breaded and pan-fried for a crispy crust and juicy center. Always serve with lemon wedges.', '<ol><li>Trim excess fat from the pork and slice it into cutlets about ½ inch thick. Place between two sheets of plastic wrap and pound with a mallet to an even ¼ inch (6 mm).</li><li>Set up three shallow bowls: flour mixed with garlic salt, paprika and pepper in the first, beaten eggs in the second, panko in the third.</li><li>Coat both sides of each cutlet in the seasoned flour and shake off the excess, dip in the egg and press into the panko. Lay the cutlets in a single layer on a baking sheet.</li><li>Pour oil into a large skillet to coat the bottom by about 1/8 inch and heat over medium to medium-high to about 175 °C (350 °F). A breadcrumb should sizzle without burning. Fry the cutlets in batches, 2-3 minutes per side, until golden and the pork reaches 63 °C (145 °F). Lower the heat if they brown too fast.</li><li>Move the cutlets to a wire rack, sprinkle with salt, rest 3 minutes and serve with lemon wedges.</li></ol><p><em>Serve with lemon wedges, potatoes or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('8dadcadd-4cc7-55c2-b6e8-06a052dbea98', 'e9af7b59-91da-57f4-8310-677d6ad7998e', 'ru', 'Свиные котлеты с размоченным чёрным хлебом', 'Очень сочные котлеты из постного свиного фарша с размоченным чёрным хлебом, жареным луком и майонезом, обжаренные в панировке. По-украински их подают с картофелем и салатом.', '<ol><li>Подсушите ломтики чёрного хлеба (в духовке при 175 °C около 25 минут или просто дайте зачерстветь), затем замочите в воде на 10 минут, отожмите и тщательно откиньте на дуршлаг. Разомните хлеб в крошку.</li><li>Обжарьте лук на сковороде на среднем-сильном огне до золотистого цвета и отложите.</li><li>В большой миске соедините фарш, размоченный хлеб, обжаренный лук, взбитое яйцо, соль, перец и майонез. Хорошо перемешайте.</li><li>Сформируйте шарики диаметром около 4 см, слегка приплюсните и обваляйте в панировочных сухарях.</li><li>В большой сковороде разогрейте на среднем огне 2 ст. л. масла. Жарьте котлеты порциями по 2–3 минуты с каждой стороны, подливая масло по мере необходимости, до золотистой корочки и полной готовности. Выложите на бумажное полотенце.</li></ol><p><em>Подавайте с картофелем и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('1ccd2a57-e3b0-5392-bb0c-d2f35a719b02', 'e9af7b59-91da-57f4-8310-677d6ad7998e', 'en', 'Juicy pork kotlety with rye bread', 'Very juicy cutlets of lean ground pork with soaked dark bread, sautéed onion and a spoonful of mayonnaise, breaded and pan-fried. In Ukraine they are served with potatoes and a salad.', '<ol><li>Dry the dark bread slices (about 25 minutes in a 175 °C / 350 °F oven, or use stale bread), then soak in water for 10 minutes, squeeze out and drain very well. Break it into crumbs.</li><li>Sauté the onion in a pan over medium-high heat until golden and set aside.</li><li>In a large bowl combine the ground pork, soaked bread, sautéed onion, beaten egg, salt, pepper and mayonnaise. Mix well.</li><li>Form 1½ inch (4 cm) balls, flatten them slightly and roll in bread crumbs.</li><li>Heat 2 tbsp oil in a large skillet over medium heat. Fry the patties in batches, 2-3 minutes per side, adding more oil as needed, until golden outside and cooked through. Drain on a paper towel.</li></ol><p><em>Serve with potatoes and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('2e1ffc0d-5975-5e00-bc29-1d7f854068e6', 'e9236a94-d269-5aed-94d1-c3409d3a5273', 'ru', 'Рассольник с перловкой', 'Лёгкий домашний суп с солёными огурцами, картофелем и перловой крупой на курином бульоне.', '<ol><li>Доведите куриный бульон до кипения.</li><li>Добавьте нарезанный мелким кубиком картофель и промытую перловку, убавьте огонь и варите под крышкой.</li><li>На сковороде растопите масло и 5 минут обжарьте лук с тёртой морковью, посолив и поперчив. Переложите зажарку в суп.</li><li>Натрите огурцы на крупной тёрке и добавьте в суп, по желанию влейте немного рассола.</li><li>Варите 30–40 минут, пока картофель и крупа не станут мягкими. При необходимости досолите.</li><li>Посыпьте мелко рубленным укропом и подавайте со сметаной.</li></ol><p><em>Подавайте со сметаной и свежим укропом.</em></p>', CURRENT_TIMESTAMP),
  ('dbf84f95-4bcb-5917-89f7-b9a6b685db94', 'e9236a94-d269-5aed-94d1-c3409d3a5273', 'en', 'Rasolnik (pickle and barley soup)', 'A light, comforting Russian soup of dill pickles, potatoes and pearl barley in chicken broth.', '<ol><li>Bring the chicken broth to a boil.</li><li>Add the diced potatoes and rinsed pearl barley, reduce the heat and simmer covered.</li><li>Melt the butter in a skillet and cook the onion and grated carrot with salt and pepper for about 5 minutes until soft. Add to the soup.</li><li>Grate the pickles on a box grater and add them to the soup, optionally with a little pickle brine.</li><li>Cook for 30–40 minutes until the potatoes and barley are tender. Adjust the salt if needed.</li><li>Sprinkle with finely chopped dill and serve with sour cream.</li></ol><p><em>Serve with sour cream and fresh dill.</em></p>', CURRENT_TIMESTAMP),
  ('a8e52ad7-8912-5bb2-8e58-f2e422c52950', '9cba0400-ade9-5178-be8d-514c9b65887e', 'ru', 'Уха из целой рыбы', 'Прозрачный рыбный суп на бульоне из целой рыбы с картофелем, морковью, луком, сельдереем и зеленью.', '<ol><li>Положите целую очищенную рыбу в большую кастрюлю, залейте водой, добавьте горошины перца, лавровый лист и соль. Доведите до кипения, убавьте огонь и варите под крышкой около 20 минут до готовности рыбы.</li><li>Пока варится бульон, очистите и нарежьте лук, картофель, морковь и сельдерей, нарубите зелень.</li><li>Достаньте рыбу и дайте немного остыть. Процедите бульон через мелкое сито. Снимите мякоть с костей и отложите, кожу, кости и голову выбросьте.</li><li>Верните бульон в кастрюлю, добавьте все овощи, кроме зелени. Если нужно, разбавьте водой и досолите.</li><li>Доведите до кипения и варите под крышкой 15–20 минут, пока картофель и морковь не станут мягкими.</li><li>Добавьте в суп мякоть рыбы, посыпьте петрушкой и укропом и подавайте горячим.</li></ol><p><em>Подавайте горячей со свежей зеленью и ломтем хлеба.</em></p>', CURRENT_TIMESTAMP),
  ('af7c1290-09fb-58a7-9784-eb6d66e0ed04', '9cba0400-ade9-5178-be8d-514c9b65887e', 'en', 'Ukha (Russian fish soup)', 'A clear fish soup made from a whole fish with potatoes, carrots, onion, celery and fresh herbs.', '<ol><li>Place the cleaned whole fish in a large pot with the water, peppercorns, bay leaves and salt. Bring to a boil, reduce to a simmer and cook covered for about 20 minutes until the fish is cooked.</li><li>While the broth cooks, peel and chop the onion, potatoes, carrots and celery and chop the herbs.</li><li>Remove the fish and let it cool slightly. Strain the broth through a fine sieve. Pick the meat off the bones and set it aside; discard the skin, bones and head.</li><li>Return the broth to the pot and add all the vegetables except the herbs. Add more water if you want a thinner soup and adjust the seasoning.</li><li>Bring to a boil and simmer covered for 15–20 minutes until the potatoes and carrots are tender.</li><li>Add the fish meat back to the soup, sprinkle with parsley and dill and serve hot.</li></ol><p><em>Serve hot with fresh herbs and a slice of bread.</em></p>', CURRENT_TIMESTAMP),
  ('0b2520f7-cee0-5b04-9254-28e129c4fa71', '5a7f701c-6b93-54ce-9868-f8ac27782ad5', 'ru', 'Фаршированные перцы с говядиной и рисом в томатно-сливочном соусе', 'Сладкие перцы, начинённые говяжьим фаршем с рисом и овощами и запечённые в томатном соусе со сливками и сыром.', '<ol><li>Разогрейте духовку до 200–220 °C. У перцев срежьте верхушки (оставьте их), удалите семена, выложите на противень и запекайте 10–15 минут до мягкости. Затем снизьте температуру до 200 °C.</li><li>Отварите рис до готовности на три четверти.</li><li>В глубокой сковороде разогрейте масло и 6–8 минут обжарьте полторы луковицы с морковью и сельдереем, посолив и поперчив, до мягкости и лёгкой золотистости. Половину луковицы отложите для соуса.</li><li>Добавьте фарш и жарьте на сильном огне 6–8 минут, пока он не изменит цвет. Жирный фарш обжарьте отдельно и слейте лишний жир.</li><li>Смешайте рис, мясо с овощами, половину сыра, петрушку, яйцо и 120 г томатов без сока. Начините перцы.</li><li>Для соуса в той же сковороде растопите масло и 6–8 минут пассеруйте оставшийся лук, морковь, сельдерей и чеснок. Влейте остальные томаты, готовьте 5 минут, затем добавьте бульон и сливки.</li><li>Добавьте петрушку и по желанию измельчите соус блендером до нужной консистенции.</li><li>Половину соуса вылейте в форму, поставьте перцы и залейте остальным соусом. Накройте перцы их верхушками и посыпьте оставшимся сыром.</li><li>Запекайте при 200 °C 30–50 минут, пока соус не запузырится, перцы не станут мягкими, а сыр не расплавится. Подайте со сметаной.</li></ol><p><em>Подавайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('62f4aada-1437-54e9-9a72-44390e93075f', '5a7f701c-6b93-54ce-9868-f8ac27782ad5', 'en', 'Beef and rice stuffed peppers in tomato cream sauce', 'Sweet bell peppers filled with beef, rice and vegetables and baked in a tomato-cream sauce with cheese.', '<ol><li>Preheat the oven to 200–220 °C. Cut the tops off the peppers (keep them), remove the seeds, set the peppers on a baking sheet and bake for 10–15 minutes until softened. Then lower the heat to 200 °C.</li><li>Cook the rice until it is about three-quarters done.</li><li>Heat the butter in a large deep skillet and cook one and a half onions with the carrots and celery, seasoned with salt and pepper, for 6–8 minutes until soft and lightly golden. Keep half an onion for the sauce.</li><li>Add the ground beef and cook over high heat for 6–8 minutes until no longer pink. If the beef is fatty, brown it separately and drain off the excess fat.</li><li>Mix the rice, the beef and vegetables, half of the cheese, parsley, egg and 120 g of the tomatoes without juice. Fill the peppers.</li><li>For the sauce, melt the butter in the same skillet and cook the remaining onion, carrot, celery and garlic for 6–8 minutes. Add the rest of the tomatoes, cook for 5 minutes, then pour in the broth and cream.</li><li>Stir in the parsley and, if you like, blend the sauce to your preferred consistency.</li><li>Pour half of the sauce into a baking dish, set the peppers in it and cover with the rest of the sauce. Top the peppers with their caps and sprinkle with the remaining cheese.</li><li>Bake at 200 °C for 30–50 minutes until the sauce bubbles, the peppers are tender and the cheese has melted. Serve with sour cream.</li></ol><p><em>Serve with sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('f48285dd-0ae5-5cf3-9b19-8fdd0c446fe7', '047047e6-34f8-5163-ac3f-5ddb99b3e10a', 'ru', 'Ежики с рисом в сливочно-томатном соусе', 'Мясные шарики из говядины и свинины с рисом, запечённые в сливочно-томатном соусе с морковью и луком.', '<ol><li>Разогрейте духовку до 200 °C. Рис отварите 5–7 минут до полуготовности, слейте воду и слегка остудите.</li><li>Смешайте в большой миске оба фарша, рис, мелко нарезанный лук, яйцо, воду, соль и перец. Сформируйте шарики по 2 столовые ложки и уложите в форму примерно 23×33 см. Руки периодически смачивайте водой, чтобы фарш не липнул.</li><li>Для соуса растопите в большой сковороде масло, обжарьте лук 5 минут, посолив и поперчив.</li><li>Добавьте морковь и чеснок, посолите, поперчите и готовьте под крышкой ещё 5 минут до мягкости моркови. Сдвиньте овощи, положите в центр томатную пасту и муку и прогревайте 1–2 минуты, затем перемешайте с овощами.</li><li>Влейте часть тёплого бульона и размешайте венчиком, затем добавьте остальной. Доведите до кипения, убавьте огонь и варите около 15 минут, пока соус не загустеет.</li><li>Снимите с огня, влейте сливки, приправьте солью, перцем и сушёными травами.</li><li>Залейте соусом фрикадельки, накройте форму фольгой и запекайте 45–60 минут до готовности. Посыпьте свежей зеленью.</li></ol><p><em>Подавайте с картофельным пюре, рисом или пастой, посыпав зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('d8289de1-d8db-543e-88d0-885dad7b121a', '047047e6-34f8-5163-ac3f-5ddb99b3e10a', 'en', 'Porcupine meatballs in creamy tomato sauce', 'Beef and pork meatballs with rice baked in a creamy tomato sauce with carrots and onions.', '<ol><li>Preheat the oven to 200 °C. Boil the rice for 5–7 minutes until partially cooked, drain and let it cool slightly.</li><li>In a large bowl mix both kinds of mince, the rice, finely chopped onion, egg, water, salt and pepper. Shape into balls of about 2 tablespoons each and place them in a 23×33 cm baking dish. Wet your hands now and then so the mixture does not stick.</li><li>For the sauce, melt the butter in a large skillet and cook the onions with salt and pepper for about 5 minutes.</li><li>Add the carrots and garlic, season, and cook covered for another 5 minutes until the carrots soften. Push the vegetables aside, put the tomato paste and flour in the centre, cook for 1–2 minutes and then stir into the vegetables.</li><li>Pour in part of the warm stock and whisk, then gradually add the rest. Bring to a boil, reduce the heat and simmer for about 15 minutes until the sauce thickens.</li><li>Take off the heat, stir in the cream and season with salt, pepper and dried herbs.</li><li>Pour the sauce over the meatballs, cover the dish with foil and bake for 45–60 minutes until cooked through. Garnish with fresh herbs.</li></ol><p><em>Serve over mashed potatoes, rice or pasta, sprinkled with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('bf47b7bb-381a-5dbb-878f-1c422deb2977', 'b73da933-c7ab-5e55-97d0-89ba2641624e', 'ru', 'Тушёная картошка со свининой', 'Домашнее блюдо в одной кастрюле: обжаренная свинина с морковью, луком и чесноком и мягкий картофель, потушенный сверху.', '<ol><li>Обсушите мясо. В кастрюле разогрейте столовую ложку масла и порциями обжарьте свинину на сильном огне с солью и перцем до корочки с двух сторон, не трогая кусочки, пока они не отстанут сами. Переложите мясо на тарелку.</li><li>Слейте лишний жир, оставив около столовой ложки, добавьте лук и тушите 3 минуты на среднем огне, соскребая прилипшее ко дну.</li><li>Добавьте морковь на 3 минуты, затем чеснок на 30 секунд. Верните мясо в кастрюлю, перемешайте, добавьте соль, перец, лавровый лист и по желанию сушёные травы.</li><li>Нарежьте картофель кубиками 4–5 см, посолите и поперчите. Выложите сверху на мясо, не перемешивая.</li><li>Влейте воду так, чтобы она едва покрыла картофель, доведите до кипения, убавьте огонь и тушите под крышкой 25–30 минут до готовности картофеля.</li><li>Аккуратно перемешайте и посыпьте свежей зеленью.</li></ol><p><em>Подавайте с солёными огурцами или квашеной капустой.</em></p>', CURRENT_TIMESTAMP),
  ('c0e0b290-a8a1-5f13-812c-318a8c57c297', 'b73da933-c7ab-5e55-97d0-89ba2641624e', 'en', 'Braised potatoes with pork', 'A one-pot family dish: browned pork with carrots, onion and garlic, topped with potatoes that braise until tender.', '<ol><li>Pat the pork dry. Heat a tablespoon of oil in a pot and brown the pork in batches over high heat with salt and pepper, without moving the pieces until they release. Set the meat aside.</li><li>Drain the excess fat, leaving about a tablespoon, add the onions and cook for 3 minutes over medium heat, scraping up the browned bits.</li><li>Add the carrots for 3 minutes, then the garlic for 30 seconds. Return the meat to the pot, stir and season with salt, pepper, bay leaf and optional dried herbs.</li><li>Cut the potatoes into 4–5 cm cubes, season with salt and pepper and lay them on top of the meat without mixing.</li><li>Pour in water to barely cover the potatoes, bring to a boil, reduce the heat and simmer covered for 25–30 minutes until the potatoes are cooked.</li><li>Stir gently and garnish with fresh herbs.</li></ol><p><em>Serve with pickles or sauerkraut.</em></p>', CURRENT_TIMESTAMP),
  ('3368df51-4e88-5041-bc78-03fa7be48c93', '21609969-5075-54d0-9328-af7d4e28cda9', 'ru', 'Курица под гнётом с лимоном и чесноком', 'Распластанная курица, прижатая гнётом на сковороде до хрустящей корочки и доведённая в духовке; сверху чесночно-лимонная заливка.', '<ol><li>Удалите у курицы хребет кухонными ножницами, распластайте тушку и придавите грудку, чтобы она стала плоской. Разогрейте духовку до 220 °C.</li><li>Щедро посолите и поперчите курицу с обеих сторон.</li><li>В большой чугунной сковороде разогрейте немного масла на среднем огне и положите курицу грудкой вниз. Сверху поставьте гнёт (кирпич, завёрнутый в фольгу, или тяжёлую кастрюлю).</li><li>Жарьте 15–20 минут до золотистой корочки, проверяя каждые 5–7 минут, чтобы не подгорело. Переверните, снова придавите и жарьте 8–12 минут.</li><li>Уберите гнёт, переложите курицу в духовку и запекайте до температуры 71–74 °C в грудке и 77–80 °C в бедре, примерно 15 минут.</li><li>Смешайте масло (или соки со сковороды), чеснок, лимонный сок и сушёные травы. Распределите по курице и верните в духовку ещё на 10 минут до готовности.</li><li>Дайте курице отдохнуть 10–15 минут, посыпьте лимонной цедрой и петрушкой.</li></ol><p><em>Подавайте с картофелем и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('6ee74908-0b96-57eb-8d29-9338189605ed', '21609969-5075-54d0-9328-af7d4e28cda9', 'en', 'Chicken under a brick with lemon and garlic', 'A butterflied chicken pressed under a weight in a skillet for crisp skin and finished in the oven with a lemon-garlic topping.', '<ol><li>Remove the chicken''s backbone with kitchen shears, flatten the bird by pressing on the breastbone, and preheat the oven to 220 °C.</li><li>Season the chicken generously with salt and pepper on both sides.</li><li>Heat a little oil in a large cast-iron skillet over medium heat and place the chicken breast side down. Set a weight on top (a brick wrapped in foil or a heavy pot).</li><li>Cook for 15–20 minutes until golden, checking every 5–7 minutes so it does not burn. Flip, press down again and cook for another 8–12 minutes.</li><li>Remove the weight and roast in the oven until the breast reaches 71–74 °C and the thigh 77–80 °C, about 15 minutes.</li><li>Mix the oil (or pan juices), garlic, lemon juice and dried herbs. Spoon over the chicken and return to the oven for about 10 minutes until fully cooked.</li><li>Let the chicken rest for 10–15 minutes, then sprinkle with lemon zest and parsley.</li></ol><p><em>Serve with potatoes and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('4d011945-9efd-54af-a1ad-0cdf0277bf65', 'c90a6c8e-7398-58b1-b55f-1699ebb1d1ae', 'ru', 'Ленивые вареники с рикоттой', 'Мягкие творожные клёцки из рикотты, яиц и муки, сваренные в подсоленной воде и политые маслом. Готовятся быстро и без раскатки начинки.', '<ol><li>В миске взбейте яйца с сахаром, ½ ч. л. соли и рикоттой до однородности.</li><li>Лопаткой вмешайте муку, добавляя понемногу, пока тесто не соберётся в шар. Не перемешивайте долго, иначе тесто станет жёстким.</li><li>Разделите тесто на 4 части и на присыпанной мукой доске раскатайте каждую в жгут толщиной около 1,3 см. Нарежьте наискосок кусочками 0,6–1,3 см.</li><li>Доведите до кипения воду с 1½ ч. л. соли. Осторожно опустите клёцки, лучше низко над водой, чтобы не брызгало. Варите на слабом кипении около 2 минут без помешивания, пока не всплывут.</li><li>Шумовкой переложите в дуршлаг, слегка ополосните холодной водой и смешайте с мягким или растопленным сливочным маслом. Подавайте со сметаной.</li></ol><p><em>Подавайте со сметаной. Остатки хороши обжаренными до золотистой корочки.</em></p>', CURRENT_TIMESTAMP),
  ('04bd8d43-437c-5aa7-aeb6-6c433e25be6a', 'c90a6c8e-7398-58b1-b55f-1699ebb1d1ae', 'en', 'Lazy cheese dumplings with ricotta', 'Soft cheese dumplings made from ricotta, eggs and flour, boiled in salted water and tossed with butter. Quick to make with no filling to roll.', '<ol><li>In a bowl whisk the eggs with the sugar, ½ tsp salt and the ricotta until well blended.</li><li>Fold in the flour with a spatula, adding a little at a time, just until the dough comes together into a ball. Do not overmix or the dough turns tough.</li><li>Divide the dough into quarters and roll each on a floured board into a ½ inch thick rope. Cut diagonally into ¼–½ inch pieces.</li><li>Bring a pot of water with 1½ tsp salt to a boil. Drop in the dumplings carefully, close to the water level to avoid splashing. Boil lightly for about 2 minutes without stirring, until they float.</li><li>Lift out with a slotted spoon into a colander, rinse lightly with cold water, then toss with soft or melted butter. Serve with sour cream.</li></ol><p><em>Serve with sour cream. Leftovers are great pan-fried until golden.</em></p>', CURRENT_TIMESTAMP),
  ('2fd120c2-3287-5c05-a6ad-8738bb236833', 'a88578a8-6a8e-583b-a43b-43eba5ca9d55', 'ru', 'Вареники с картофелем и сыром и беконом', 'Тонкое тесто на сметане с начинкой из картофельного пюре с моцареллой и сливочным сыром. Отварные вареники поливают маслом с хрустящим беконом.', '<ol><li>Для начинки сварите очищенный картофель в воде до мягкости (около 25 минут). Слейте воду, остудите 5 минут и разомните в гладкое пюре.</li><li>Вмешайте в пюре ½ ч. л. соли, 2 ст. л. растопленного масла, сливочный сыр и моцареллу. Прикройте и отставьте, пока готовится тесто.</li><li>Для теста смешайте в чаше миксера или большой миске тёплую воду, молоко, сметану, яйцо, масло и 1½ ч. л. соли. Добавьте 2 стакана муки и перемешайте, затем досыпайте остальную муку порциями, пока тесто не перестанет липнуть к стенкам и рукам. Месите 2–3 минуты до гладкости и эластичности, накройте плёнкой и оставьте на 30 минут.</li><li>Разделите тесто на две части (вторую накройте). Тонко раскатайте первую на присыпанной мукой поверхности, меньше чем на 3 мм. Вырежьте кружки диаметром 7–8 см, обрезки соберите и накройте.</li><li>Выложите на каждый кружок по ½ ст. л. начинки, сложите края и плотно защипните. Для надёжности защипните второй раз с подкруткой. Сразу варите или заморозьте.</li><li>Пока не варите вареники, приготовьте заправку: на сковороде обжарьте бекон до хруста, добавьте 2 ст. л. масла, растопите и снимите с огня.</li><li>Доведите до кипения воду, добавьте 1 ст. л. соли. Опускайте свежие или замороженные вареники порциями и варите около 2 минут, пока вода снова закипит и они не всплывут. Перекладывайте в миску слоями, поливая маслом с беконом.</li></ol><p><em>Подавайте со сметаной. В одной порции около 5 штук.</em></p>', CURRENT_TIMESTAMP),
  ('b885e385-c203-54b9-a780-d73c42259d94', 'a88578a8-6a8e-583b-a43b-43eba5ca9d55', 'en', 'Potato and cheese pierogi with bacon', 'Thin dumpling dough made with sour cream, filled with mashed potato, mozzarella and cream cheese. The boiled pierogi are tossed with buttery crisp bacon.', '<ol><li>For the filling, boil the peeled potatoes in water until easily pierced with a fork (about 25 minutes). Drain, cool 5 minutes and mash until smooth.</li><li>Mash in ½ tsp salt, 2 tbsp melted butter, the cream cheese and the mozzarella. Cover partly and set aside while you make the dough.</li><li>For the dough, mix the warm water, milk, sour cream, egg, oil and 1½ tsp salt in a mixer bowl or large bowl. Add 2 cups flour and mix, then add the rest in portions until the dough stops sticking to the bowl and your hands. Knead 2-3 minutes until smooth and elastic, cover with plastic wrap and rest 30 minutes.</li><li>Divide the dough into 2 pieces (keep one covered). Roll the first out thinly on a floured surface to just under 1/8 inch. Cut 3 inch circles, gathering and covering the scraps to reuse.</li><li>Put ½ tbsp filling on each circle, fold over and pinch the edges firmly. Crimp a second time with a twisting pinch for a tight seal. Cook right away or freeze.</li><li>Before boiling, make the topping: crisp the bacon in a skillet, melt in 2 tbsp butter and take off the heat.</li><li>Bring a pot of water to a rolling boil and add 1 tbsp salt. Add fresh or frozen pierogi in batches and cook about 2 minutes, until the water returns to a boil and they float. Transfer to a bowl, drizzling the bacon butter between layers.</li></ol><p><em>Serve with sour cream. A portion is about 5 pierogi.</em></p>', CURRENT_TIMESTAMP),
  ('4bf2e0f0-c692-543f-b6fe-7acc704cbfdc', '7a801cfa-4bf9-5d51-b0fe-6872bf5cf5da', 'ru', 'Салат из свёклы с майонезом и красным луком', 'Простой салат из варёной свёклы соломкой с красным луком, уксусом и майонезом. Готовится из нескольких продуктов.', '<ol><li>Варите свёклу в кожуре около часа, пока не станет мягкой (молодая свёкла готова за 45 минут, крупная и старая варится дольше). Остудите в холодной воде или на воздухе и очистите, потерев кожуру руками. Лучше работать в перчатках.</li><li>Нарежьте свёклу тонкой соломкой (удобно на мандолине) и сложите в большую миску. Добавьте мелко нарезанный красный лук.</li><li>Добавьте соль, сахар, уксус и майонез по вкусу, перемешайте. Посыпьте шнитт-луком.</li></ol><p><em>Посыпьте шнитт-луком для цвета.</em></p>', CURRENT_TIMESTAMP),
  ('71d70214-c766-53c0-b795-d28759908eef', '7a801cfa-4bf9-5d51-b0fe-6872bf5cf5da', 'en', 'Creamy beet salad with mayonnaise and red onion', 'A simple salad of boiled julienned beets with red onion, a splash of vinegar and mayonnaise. Made from just a few ingredients.', '<ol><li>Boil the beets with the skin on for about an hour until easily pierced with a fork (young beets may take 45 minutes, large old ones longer). Cool in cold water or at room temperature and rub off the skins. Wear gloves to avoid stained hands.</li><li>Cut the beets into thin matchsticks (easiest on a mandoline) and put them in a large bowl. Add the finely diced red onion.</li><li>Add the salt, sugar, vinegar and mayonnaise to taste and stir together. Sprinkle with chives.</li></ol><p><em>Sprinkle with chives for a pop of color.</em></p>', CURRENT_TIMESTAMP),
  ('bd949eb0-9d76-5003-b314-627e29005ec0', '1dd8ce8d-26d1-57c4-9ce1-3c27bf0e0f6c', 'ru', 'Солёная форель по-домашнему (как селёдка)', 'Рыбные стейки, выдержанные 12 часов в пряном рассоле и уложенные в банку с луком и маслом. Вкус напоминает слабосолёную селёдку.', '<ol><li>Вскипятите 960 мл воды и снимите с огня. Добавьте соль, сахар, кориандр, перец горошком и лавровый лист. Размешайте до растворения соли и сахара и остудите до комнатной температуры.</li><li>Нарежьте рыбу стейками толщиной 2,5 см (голову и хвост уберите), крупные стейки можно разрезать пополам. Сложите в большую посуду и залейте рассолом. Придавите тарелкой, чтобы рыба была под рассолом, накройте и уберите в холодильник на 12–14 часов.</li><li>Достаньте стейки из рассола и плотно уложите в банку, перекладывая кольцами лука. Залейте маслом так, чтобы оно покрыло рыбу. Храните в холодильнике.</li></ol><p><em>Подавайте с чёрным хлебом, отварной картошкой и луком.</em></p>', CURRENT_TIMESTAMP),
  ('61af72fa-698a-58da-b4b5-bae15c483aa1', '1dd8ce8d-26d1-57c4-9ce1-3c27bf0e0f6c', 'en', 'Homemade salted trout (selyodka-style pickled fish)', 'Fish steaks cured for 12 hours in a spiced brine, then packed in a jar with onions and oil. The taste is similar to lightly salted herring.', '<ol><li>Bring 4 cups (960 ml) of water to a boil and remove from the heat. Add the salt, sugar, coriander, peppercorns and bay leaves. Stir until the salt and sugar dissolve and cool to room temperature.</li><li>Slice the fish into 1 inch steaks (discard heads and tails), cutting large steaks in half if you like. Put them in a large bowl and pour the brine over. Weigh down with a plate so the fish stays submerged, cover and refrigerate for 12-14 hours.</li><li>Take the steaks out of the brine and pack them tightly into a jar, layering with sliced onion. Pour in enough oil to fill the gaps and cover the fish. Keep refrigerated.</li></ol><p><em>Serve with dark bread, boiled potatoes and onion.</em></p>', CURRENT_TIMESTAMP),
  ('2b70dc0b-4cec-5934-b724-c7cf718297e5', '373b2606-15b0-5d0c-b720-b279d60046aa', 'ru', 'Котлета по-киевски с чесночно-лимонным маслом', 'Куриное филе с карманом, в который заложено масло с чесноком, лимонным соком и петрушкой, в хрустящей панировке из панко. При разрезании вытекает горячее ароматное масло.', '<ol><li>Для масла разомните вилкой мягкое масло с чесноком, лимонным соком, петрушкой, солью и перцем, пока лимонный сок не впитается.</li><li>Разрежьте каждое куриное филе вдоль пополам на две равные части. В каждой части острым тонким ножом сделайте глубокий карман сбоку, не прорезая насквозь (около 5 × 7 см). Положите в карман 1 ст. л. масла, прижмите, распределяя масло, и защипните отверстие. Посолите и поперчите с двух сторон.</li><li>Приготовьте три ёмкости: с мукой, со взбитыми яйцами, с панко. Обваляйте курицу в муке, стряхните лишнее, обмакните в яйцо, дайте стечь излишкам и обваляйте в сухарях. Выложите на блюдо.</li><li>В глубокую сковороду налейте масло слоем около 6 мм и разогрейте на среднем огне до 175 °C (крошка должна шипеть). Жарьте в один слой по 4 минуты с каждой стороны до золотистого цвета, пока внутри не будет 74 °C. Если румянится слишком быстро, убавьте огонь. Приготовьте вторую партию.</li><li>Посыпьте горячую курицу солью, украсьте петрушкой и сбрызните лимоном. Подавайте сразу.</li></ol><p><em>Посыпьте солью и петрушкой, сбрызните лимоном. Разрезайте осторожно: масло брызгает.</em></p>', CURRENT_TIMESTAMP),
  ('e55e94e5-26f2-544a-8672-002415c40176', '373b2606-15b0-5d0c-b720-b279d60046aa', 'en', 'Chicken Kiev with lemon-garlic butter', 'Chicken breast halves stuffed with garlic, lemon and parsley butter and coated in a crisp panko crust. Cutting into it releases a stream of hot herby butter.', '<ol><li>For the butter, mash the soft butter with the garlic, lemon juice, parsley, salt and pepper with a fork until the lemon juice is absorbed.</li><li>Cut each chicken breast in half lengthwise into two equal pieces. With a sharp slim knife cut a pocket into the side of each piece, as deep and wide as possible without cutting through (about 2 × 3 in). Fill each with 1 tbsp of the butter, press to spread it and pinch the opening shut. Season both sides with salt and pepper.</li><li>Set up three dishes: flour, beaten eggs and panko. Dredge the chicken in flour and dust off the excess, dip in egg letting the extra drip off, then coat in panko. Place on a platter.</li><li>Pour ¼ inch of oil into a large deep skillet over medium heat and bring to 175 °C (350 °F) (a crumb should sizzle). Fry in a single layer 4 minutes per side until golden and the inside reaches 74 °C (165 °F). Lower the heat if it browns too fast. Cook the second batch.</li><li>Sprinkle the hot chicken with salt, garnish with parsley and squeeze lemon over. Serve immediately.</li></ol><p><em>Sprinkle with salt and parsley and squeeze lemon over. Cut carefully: the butter spurts out.</em></p>', CURRENT_TIMESTAMP),
  ('4e30af5f-6cae-581c-bdb0-b8c9c92a459c', 'c6ed9ad3-0266-5ea9-9103-342a6a6fed12', 'ru', 'Пельмени домашние со свининой и индейкой', 'Пельмени из эластичного теста на кефире с начинкой из свиного и индюшиного фарша, жареного лука и чеснока. Хорошо замораживаются, поэтому их удобно лепить большой партией.', '<ol><li>Для теста взбейте в миксере кефир, сметану, яйца, тёплую воду и соль до однородности. Замените насадку на крюк, добавьте 4 стакана муки и перемешайте на малой скорости.</li><li>Добавляйте ещё 3 стакана муки по одному, дожидаясь однородности после каждого. Затем досыпайте остальную муку по столовой ложке, пока тесто не перестанет липнуть к стенкам чаши, и месите ещё 5 минут. Всего замес занимает около 20 минут. Выложите тесто на слегка присыпанную мукой поверхность.</li><li>Для начинки разогрейте на сковороде масло и обжарьте лук до золотистого цвета и мягкости, добавьте чеснок на минуту. Соедините со свиным и индюшиным фаршем, солью и перцем, перемешайте.</li><li>Скатайте из теста жгут толщиной 2,5–5 см, нарезайте кусочки размером с жевательную конфету и раскатывайте в кружки диаметром около 4 см, подсыпая муку при необходимости. На середину каждого положите около 1 ч. л. начинки, соедините края и защипните, а затем соедините уголки. Либо раскатайте тесто пластом и сформируйте пельмени в специальной форме.</li><li>Выложите пельмени на хорошо присыпанную мукой доску, посыпьте мукой и заморозьте. Когда они полностью замёрзнут, пересыпьте в пакеты для заморозки.</li><li>Доведите до кипения воду в большой кастрюле, посолите (1 ст. л. на большую кастрюлю). Опустите замороженные пельмени, дождитесь повторного кипения и когда они всплывут, варите ещё 3 минуты до готовности мяса.</li><li>Слейте воду, переложите пельмени в миску, смешайте с растопленным сливочным маслом и посыпьте укропом. Подавайте горячими.</li></ol><p><em>Подавайте со сливочным маслом, сметаной или уксусом, посыпьте укропом.</em></p>', CURRENT_TIMESTAMP),
  ('72d02378-e294-5681-9baa-f9fec67e9704', 'c6ed9ad3-0266-5ea9-9103-342a6a6fed12', 'en', 'Homemade pelmeni with pork and turkey', 'Dumplings made from an elastic dough with kefir and a filling of ground pork and turkey with sautéed onion and garlic. They freeze well, so it makes sense to shape a big batch.', '<ol><li>For the dough, whisk the kefir, sour cream, eggs, warm water and salt in a stand mixer until blended. Switch to the dough hook, add 4 cups of flour and mix on low speed.</li><li>Add 3 more cups of flour one cup at a time, waiting until each is blended in. Add the remaining flour a tablespoon at a time until the dough no longer sticks to the bowl, then knead 5 more minutes. Total mixing time is about 20 minutes. Turn the dough onto a lightly floured surface.</li><li>For the filling, heat the oil in a skillet, sauté the onion until golden and soft and add the garlic for another minute. Combine with the ground pork, ground turkey, salt and pepper and mix well.</li><li>Roll the dough into a 1-2 inch thick log, cut off gum-ball sized pieces and roll each into a 1.5 inch circle, dusting with flour as needed. Put about 1 tsp filling in the center, close and pinch the edges, then pinch the corners together. Alternatively roll the dough into sheets and use a pelmeni mold.</li><li>Place the pelmeni on a well-floured board, sprinkle with flour and freeze. Once frozen solid, transfer to freezer bags.</li><li>Bring a large pot of water to a boil and add the salt (1 tbsp for a big pot). Add frozen pelmeni, return to a boil and, once they float, cook 3 minutes more until the meat is done.</li><li>Drain, move the pelmeni to a clean bowl, toss with melted butter and sprinkle with dill. Serve warm.</li></ol><p><em>Serve with melted butter, sour cream or vinegar and sprinkle with dill.</em></p>', CURRENT_TIMESTAMP),
  ('21adfaca-2897-5bb6-a614-a1121cedf8ab', '91e39a48-bb15-56f6-9f8a-2a5676dece29', 'ru', 'Салат из огурцов и помидоров с укропом', 'Свежий салат из спелых помидоров, огурцов и красного лука с укропом и простой заправкой из масла и уксуса. Готовится за 10 минут.', '<ol><li>Нарежьте огурцы, помидоры и лук, сложите в большую салатницу вместе с укропом.</li><li>В маленькой миске взбейте оливковое масло, уксус, соль и перец.</li><li>Перед подачей полейте салат заправкой и осторожно перемешайте. Попробуйте, при необходимости досолите и украсьте укропом. Подавайте сразу.</li></ol><p><em>Заправляйте непосредственно перед подачей. Подходит к любому основному блюду.</em></p>', CURRENT_TIMESTAMP),
  ('900f3b32-6564-599e-8da9-1026b7ff8649', '91e39a48-bb15-56f6-9f8a-2a5676dece29', 'en', 'Cucumber and tomato salad with dill', 'A fresh salad of ripe tomatoes, cucumber and red onion with dill and a simple oil and vinegar dressing. Ready in 10 minutes.', '<ol><li>Cut the cucumbers, tomatoes and onion and add them to a large serving bowl with the dill.</li><li>In a small bowl whisk the olive oil, vinegar, salt and pepper.</li><li>Just before serving, pour the dressing over the salad and toss gently. Taste, adjust the salt and garnish with more dill. Serve immediately.</li></ol><p><em>Dress just before serving. Pairs with almost any main dish.</em></p>', CURRENT_TIMESTAMP),
  ('7a016928-30e0-5dfa-a932-b837e1f01e10', '27c97faa-df18-54a1-b6c5-4f9f9f639c0e', 'ru', 'Рисовая запеканка с петрушкой и чеддером', 'Запечённый рис с яйцами, молоком, тёртым луком, большим количеством петрушки и сыром чеддер. Сытный гарнир, который подходит к мясу и птице.', '<ol><li>Рис варите в 480 мл воды с ½ ч. л. соли и 1 ст. л. сливочного масла на слабом огне 15–20 минут.</li><li>Пока варится рис, в большой миске слегка взбейте вилкой яйца. Добавьте мелко натёртый лук, рубленую петрушку и тёртый чеддер.</li><li>Добавьте 1 ч. л. соли, сухую горчицу, молоко и растительное масло и перемешайте.</li><li>Вмешайте в смесь сваренный рис и перемешайте до однородности.</li><li>Смажьте маслом форму примерно 23 × 28 см, выложите рисовую массу и запекайте 1 час при 175 °C.</li></ol><p><em>Подавайте горячим как гарнир к мясу или курице.</em></p>', CURRENT_TIMESTAMP),
  ('debe7c72-e3ef-5ceb-9a72-f7300372c351', '27c97faa-df18-54a1-b6c5-4f9f9f639c0e', 'en', 'Baked parsley rice with cheddar', 'Rice baked with eggs, milk, grated onion, a generous amount of parsley and cheddar cheese. A hearty side that goes well with meat and poultry.', '<ol><li>Simmer the rice in 2 cups (480 ml) of water with ½ tsp salt and 1 tbsp butter for 15-20 minutes.</li><li>While the rice cooks, lightly beat the eggs with a fork in a medium bowl. Add the finely grated onion, chopped parsley and shredded cheddar.</li><li>Add 1 tsp salt, the dry mustard, the milk and the oil and stir together.</li><li>Stir the cooked rice into the mixture until combined.</li><li>Grease a 9 × 11 inch baking dish with butter, pour in the rice mixture and bake for 1 hour at 175 °C (350 °F).</li></ol><p><em>Serve hot as a side with meat or chicken.</em></p>', CURRENT_TIMESTAMP),
  ('054d4a08-fdd7-5271-96fe-e4dd933e15ef', '786b2b1a-77e3-5224-ad78-af453ba36431', 'ru', 'Картофельное пюре на молоке и сливочном масле', 'Нежное воздушное пюре всего из четырёх продуктов: картофеля, горячего молока, мягкого сливочного масла и соли.', '<ol><li>Очистите картофель и промойте холодной водой (очень крупные клубни разрежьте пополам). Для самого гладкого пюре удалите глазки. Сложите в большую кастрюлю (от 5 л), залейте холодной водой, доведите до кипения и варите под неплотной крышкой 20–25 минут до мягкости, не переваривайте.</li><li>Хорошо слейте воду и переложите картофель в чашу миксера. Слегка разомните вручную, затем взбивайте венчиком на малой скорости 30 секунд, переключите на среднюю и тонкой струйкой влейте горячее молоко до нужной консистенции (достаточно 240–300 мл). Можно размять картофель и толкушкой.</li><li>Не выключая миксер, добавляйте мягкое масло по столовой ложке с паузой в несколько секунд. Пюре станет воздушным. В конце посолите по вкусу.</li></ol><p><em>Посыпьте рубленой петрушкой или шнитт-луком. Подходит к котлетам, мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('4e6e9128-5a6a-56ff-b93b-3ba643045baa', '786b2b1a-77e3-5224-ad78-af453ba36431', 'en', 'Creamy mashed potatoes with milk and butter', 'Velvety, fluffy mashed potatoes made from just four ingredients: potatoes, hot milk, softened butter and salt.', '<ol><li>Peel the potatoes and rinse in cold water (halve very large ones). For the smoothest mash remove any eyes. Place in a large pot (5 qt+), cover with cold water, bring to a boil and cook partially covered 20-25 minutes until easily pierced with a knife. Do not overcook.</li><li>Drain well and transfer to the bowl of a stand mixer. Lightly mash by hand, then whip with the whisk on low for 30 seconds, increase to medium and slowly drizzle in the hot milk until you reach the texture you like (240-300 ml is enough). You can also mash with a potato masher.</li><li>With the mixer running, add the softened butter 1 tbsp at a time, pausing a few seconds between additions. The potatoes will become fluffy. Finish with salt to taste.</li></ol><p><em>Garnish with chopped parsley or chives. Great with cutlets, meat and fish.</em></p>', CURRENT_TIMESTAMP),
  ('7960d765-6299-5487-8329-b3fc46df86c6', '868863ae-a617-5bee-b049-49f9448f3537', 'ru', 'Гуляш из говядины с морковью и паприкой', 'Домашний гуляш: обжаренная говядина, тушёная с луком, морковью и томатной пастой в густой подливе.', '<ol><li>Нарежьте говядину кубиками около 1,5 см. Разогрейте 1,5 столовой ложки масла в сковороде на сильном огне и обжаривайте мясо порциями в один слой до румяной корочки.</li><li>Добавьте лук, посолите, накройте и тушите на среднем огне до мягкости. Затем добавьте тёртую морковь, соль и перец и тушите до мягкости моркови.</li><li>Добавьте томатную пасту, чеснок, паприку и чили, прогрейте минуту, всыпьте муку и перемешайте до полного впитывания.</li><li>Понемногу вливайте бульон или воду, соскребая всё со дна и размешивая, чтобы не было комков. Добавьте лавровый лист.</li><li>Накройте крышкой и тушите на слабом огне около 1,5 часа, пока мясо не станет мягким. При необходимости досолите и поперчите.</li></ol><p><em>Подавайте с картофельным пюре, гречкой или макаронами.</em></p>', CURRENT_TIMESTAMP),
  ('de5f727e-879a-5b01-92da-1640b2b42f34', '868863ae-a617-5bee-b049-49f9448f3537', 'en', 'Beef goulash with carrots and paprika', 'Home-style goulash: browned beef stewed with onion, carrots and tomato paste in a thick gravy.', '<ol><li>Cut the beef into about 1.5 cm cubes. Heat 1.5 tablespoons of oil in a skillet over high heat and brown the beef in batches in a single layer.</li><li>Add the onion, season with salt, cover and cook over medium heat until soft. Then add the grated carrots with salt and pepper and cook covered until tender.</li><li>Add the tomato paste, garlic, paprika and chili, cook for a minute, sprinkle in the flour and stir until fully absorbed.</li><li>Gradually pour in the stock or water, scraping the bottom and stirring to avoid lumps. Add the bay leaf.</li><li>Cover and simmer over low heat for about 1.5 hours until the meat is fork-tender. Adjust the seasoning if needed.</li></ol><p><em>Serve with mashed potatoes, buckwheat or pasta.</em></p>', CURRENT_TIMESTAMP),
  ('04f9309e-d48a-5688-87b6-a421e4a03cc3', 'ea2ce79a-4011-5334-bb74-305bcf585bfa', 'ru', 'Фрикадельки в грибном соусе по-строгановски', 'Маленькие мясные фрикадельки из говядины и свинины в соусе из шампиньонов со сметаной и сливками.', '<ol><li>Залейте панировочные сухари молоком. Смешайте с обоими видами фарша, яйцом, луком, солью и перцем.</li><li>Скатайте шарики по столовой ложке (получится около 50 штук).</li><li>В толстостенной сковороде разогрейте масло и обжарьте фрикадельки в два захода до золотистой корочки. Внутри они могут быть сыроватыми, дойдут в соусе. Отложите.</li><li>Оставьте в сковороде около 1,5 ст. л. жира, обжарьте лук 3 минуты, затем добавьте грибы и чеснок, посолите, поперчите и жарьте около 8 минут до золотистого цвета, соскребая румяную корочку со дна.</li><li>Добавьте сливочное масло и муку, перемешайте. Постепенно влейте вино (по желанию) и бульон, помешивая венчиком, и варите около 5 минут до загустения.</li><li>Введите сметану и сливки, размешайте до однородности, верните фрикадельки и варите ещё около 5 минут до готовности. Посыпьте петрушкой и укропом.</li></ol><p><em>Подавайте с картофельным пюре, лапшой или рисом и посыпьте зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('678225ab-5f94-5f4a-bc08-3a551e568735', 'ea2ce79a-4011-5334-bb74-305bcf585bfa', 'en', 'Stroganoff meatballs in mushroom gravy', 'Small beef and pork meatballs in a creamy mushroom sauce with sour cream.', '<ol><li>Pour the milk over the breadcrumbs. Mix with both kinds of mince, the egg, onion, salt and pepper.</li><li>Shape into 1-tablespoon meatballs (about 50).</li><li>Heat the oil in a heavy skillet and brown the meatballs in two batches until golden. They do not have to be cooked through, as they finish in the sauce. Set aside.</li><li>Leave about 1.5 tbsp of fat in the pan, cook the onion for 3 minutes, then add the mushrooms and garlic with salt and pepper and cook for about 8 minutes until golden, scraping up the browned bits.</li><li>Add the butter and flour and stir. Gradually whisk in the wine (optional) and stock and simmer for about 5 minutes until thickened.</li><li>Whisk in the sour cream and cream until smooth, return the meatballs and simmer for about 5 more minutes until cooked through. Garnish with parsley and dill.</li></ol><p><em>Serve over mashed potatoes, noodles or rice with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('e9039732-f2f0-5882-bbeb-fa6865343944', '3ad5256a-eeb1-53eb-8ab5-216b35cde5c7', 'ru', 'Курица с картофелем, перцем и шалотом в духовке', 'Куриная грудка на кости запекается на решётке над картофелем, болгарским перцем, шалотом и чесноком, всё готовится одновременно.', '<ol><li>Разогрейте духовку до 200 °C. Нарежьте картофель кусками 3–4 см, перец — кусочками 2,5 см, шалот — крупными дольками. Перец и шалот положите в большую миску.</li><li>Залейте картофель водой, доведите до кипения и варите около 3 минут, пока он не станет мягким снаружи. Слейте воду.</li><li>Добавьте картофель в миску с перцем и шалотом, всыпьте сушёные травы, чеснок, соль, перец и влейте 2–3 ст. л. оливкового масла. Перемешайте.</li><li>Посолите и поперчите курицу, смажьте оставшимся маслом. Выложите овощи ровным слоем в противень с бортами, сверху поставьте решётку, на неё — грудки.</li><li>Запекайте 35–50 минут, пока температура в толще грудки не достигнет 74 °C. Если картофель не подрумянился, добавьте 5 минут с грилем или при 260 °C.</li><li>Дайте курице отдохнуть минимум 5 минут, снимите мясо с кости и нарежьте. Посыпьте картофель зеленью и подавайте.</li></ol><p><em>Подавайте с зеленью и свежим овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('18d8621d-2568-51e8-a255-744ddbd9a8ac', '3ad5256a-eeb1-53eb-8ab5-216b35cde5c7', 'en', 'One-pan roasted chicken with potatoes, peppers and shallots', 'Bone-in chicken breasts roast on a rack over potatoes, bell pepper, shallots and garlic, so the whole dinner cooks at once.', '<ol><li>Preheat the oven to 200 °C. Cut the potatoes into 3–4 cm pieces, the pepper into 2.5 cm pieces and the shallots into large chunks. Put the pepper and shallots in a large bowl.</li><li>Cover the potatoes with water, bring to a boil and cook for about 3 minutes until the outside softens. Drain.</li><li>Add the potatoes to the bowl with the pepper and shallots, then the dried herbs, garlic, salt, pepper and 2–3 tbsp of olive oil. Toss to combine.</li><li>Season the chicken with salt and pepper and rub with the remaining oil. Spread the vegetables in an even layer in a rimmed baking dish, set a wire rack on top and put the chicken on it.</li><li>Roast for 35–50 minutes until the chicken reaches 74 °C. If the potatoes are not crisp enough, give them another 5 minutes under the grill or at 260 °C.</li><li>Rest the chicken for at least 5 minutes, then slice the meat off the bone. Sprinkle the potatoes with herbs and serve.</li></ol><p><em>Serve with fresh herbs and a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('9478643b-e67b-59ca-a230-e7809150711d', '1f1bbc0f-3cea-5377-acf7-b5bcfd13e1d8', 'ru', 'Треска, запечённая в фольге с кабачком и помидорами', 'Филе трески запекается в пакетиках из фольги на подушке из кабачка под помидорами, чесноком и зеленью.', '<ol><li>Разогрейте духовку до 200 °C. Нарежьте кабачки кружочками 6 мм, посыпьте половиной чайной ложки соли и оставьте в дуршлаге на полчаса.</li><li>Смешайте нарезанные помидоры без семян с петрушкой и чесноком, посолите и поперчите. Отожмите кабачки бумажными полотенцами.</li><li>На кусок фольги выложите четверть кабачков внахлёст, сбрызните столовой ложкой вина, сверху положите посоленную и поперчённую треску и накройте помидорами.</li><li>Накройте вторым куском фольги и плотно запечатайте края. Так сделайте четыре пакетика.</li><li>Выложите пакетики на противень и запекайте 15 минут. Раскройте и подавайте.</li></ol><p><em>Каждый гость раскрывает свой пакетик за столом.</em></p>', CURRENT_TIMESTAMP),
  ('ca738aa8-46ac-54c3-882a-30da40dad7b5', '1f1bbc0f-3cea-5377-acf7-b5bcfd13e1d8', 'en', 'Cod baked in foil with zucchini and tomatoes', 'Cod fillets baked in individual foil packets on a bed of zucchini and topped with tomatoes, garlic and parsley.', '<ol><li>Preheat the oven to 200 °C. Slice the zucchini into 6 mm rounds, toss with half a teaspoon of salt and leave in a colander for 30 minutes.</li><li>Combine the seeded, chopped tomatoes with the parsley and garlic, and season. Blot the zucchini dry with paper towels.</li><li>On a sheet of foil lay a quarter of the zucchini slightly overlapping, drizzle with a tablespoon of wine, then top with the seasoned cod and the tomato mixture.</li><li>Cover with a second sheet of foil and seal the edges tightly. Make four packets this way.</li><li>Place the packets on a baking sheet and bake for 15 minutes. Open and serve.</li></ol><p><em>Let each guest open their own packet at the table.</em></p>', CURRENT_TIMESTAMP),
  ('dac3ab10-aec5-5b38-a139-a75adcd14466', '84fbe261-88b9-5712-9e67-b3c9de41b9a7', 'ru', 'Белая рыба, запечённая под овощами', 'Сочная белая рыба, обжаренная и запечённая между слоями тушёных лука, моркови, сельдерея, перца и помидоров.', '<ol><li>Нарежьте рыбу порционными кусками и промокните бумажным полотенцем. Разогрейте 1/2–1 ст. л. масла на антипригарной сковороде, посолите и поперчите рыбу.</li><li>Обжарьте рыбу порциями по 2–3 минуты с каждой стороны: в центре она должна остаться недожаренной. Переложите на тарелку.</li><li>Разогрейте духовку до 175 °C. Лук нарежьте полукольцами, морковь натрите, сельдерей нарежьте, перец — соломкой, чеснок измельчите. Помидоры очистите от семян и натрите на тёрке.</li><li>В сковороде разогрейте ещё ложку масла и 5–7 минут тушите лук, морковь и сельдерей с солью и перцем до мягкости.</li><li>Добавьте перец, помидоры и чеснок, приправьте и готовьте ещё 8–10 минут. Снимите с огня и добавьте зелень.</li><li>В форму выложите половину овощей, затем рыбу, сверху — остальные овощи. По желанию смажьте тонким слоем майонеза.</li><li>Накройте крышкой или фольгой и запекайте около 30–40 минут, пока рыба не будет готова.</li></ol><p><em>Подавайте с отварным картофелем или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('ea655803-9c78-58c0-a49c-f090ae6b8914', '84fbe261-88b9-5712-9e67-b3c9de41b9a7', 'en', 'Baked white fish with vegetables', 'Juicy white fish seared and baked between layers of braised onion, carrot, celery, pepper and tomato.', '<ol><li>Cut the fish into smaller pieces and blot dry. Heat 1/2–1 tbsp oil in a nonstick skillet and season the fish with salt and pepper.</li><li>Sear the fish in batches for 2–3 minutes per side; the centre should still be partly raw. Transfer to a plate.</li><li>Preheat the oven to 175 °C. Slice the onions, grate the carrots, slice the celery, julienne the pepper, mince the garlic. Seed the tomatoes and grate them.</li><li>Heat another tablespoon of oil in the skillet and cook the onions, carrots and celery with salt and pepper for 5–7 minutes until soft.</li><li>Add the pepper, tomatoes and garlic, season and cook for another 8–10 minutes. Off the heat, stir in the herbs.</li><li>Spread half of the vegetables in a baking dish, add the fish, then top with the remaining vegetables. Optionally spread with a thin layer of mayonnaise.</li><li>Cover with a lid or foil and bake for about 30–40 minutes until the fish is cooked.</li></ol><p><em>Serve with boiled potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('5648037e-a38e-511f-b013-0db2c426f33d', '88dda959-d1d2-5af4-b208-5b9e037562a1', 'ru', 'Курица с брокколи, цветной капустой и морковью в нежном соусе', 'Быстрый ужин на одной сковороде: куриные бёдра с овощами в бархатистом соусе на курином бульоне.', '<ol><li>Нарежьте курицу кусочками 2,5 см, посолите и поперчите. Разогрейте в большой сковороде ложку масла и обжарьте мясо 5–7 минут на средне-сильном огне до золотистого цвета. Отложите.</li><li>Убавьте огонь, добавьте лук и чеснок, посолите и готовьте 3 минуты до прозрачности, соскребая со дна румяные остатки.</li><li>Добавьте морковь и готовьте около 5 минут, пока она не начнёт размягчаться. Всыпьте муку и перемешайте до полного впитывания (если сковорода сухая, добавьте немного масла).</li><li>Постепенно влейте бульон, размешивая венчиком, чтобы не было комков, и доведите до кипения.</li><li>Добавьте соцветия брокколи и цветной капусты, посолите, накройте и варите на слабом огне 5–10 минут до нужной мягкости.</li><li>Верните курицу в сковороду и прогрейте минуту. Посыпьте петрушкой и подайте с гарниром.</li></ol><p><em>Подавайте с пастой, рисом, кускусом или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('94a864d8-1f60-53c0-af38-c0eb704e6be6', '88dda959-d1d2-5af4-b208-5b9e037562a1', 'en', 'Chicken with broccoli, cauliflower and carrots in a velvety sauce', 'A quick one-skillet dinner of chicken thighs and vegetables in a smooth chicken-stock sauce.', '<ol><li>Cut the chicken into 2.5 cm pieces and season. Heat a tablespoon of oil in a large skillet and brown the chicken over medium-high heat for 5–7 minutes. Set aside.</li><li>Lower the heat, add the onion and garlic with salt and pepper and cook for 3 minutes until translucent, scraping up the browned bits.</li><li>Add the carrots and cook for about 5 minutes until they start to soften. Stir in the flour until absorbed (add a little oil if the pan is dry).</li><li>Gradually whisk in the stock to avoid lumps and bring to a boil.</li><li>Add the broccoli and cauliflower florets, season, cover and simmer for 5–10 minutes until as tender as you like.</li><li>Return the chicken to the skillet and heat through for a minute. Sprinkle with parsley and serve with a side.</li></ol><p><em>Serve with pasta, rice, couscous or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('5607f083-e9cb-517a-b73d-beb3ab5ded0c', '9098ce8a-f512-5727-9910-161198497930', 'ru', 'Картофельные зразы с сыром и творогом', 'Румяные картофельные лепёшки из пюре и тёртого сырого картофеля с начинкой из творога, моцареллы и зелени.', '<ol><li>Половину картофеля (около 600 г) отварите до мягкости и разомните в пюре. Остальной картофель очистите, натрите на крупной тёрке и тщательно отожмите через марлю или полотенце.</li><li>Смешайте пюре с тёртым картофелем, добавьте 1 ч. л. соли и 1/2 ч. л. перца.</li><li>Для начинки смешайте творог, тёртую моцареллу, нарубленные зелень и лук-резанец, влейте столько сливок, чтобы масса стала однородной. Посолите и поперчите.</li><li>Возьмите около 1/4 стакана картофельной массы, сформируйте лепёшку, положите в центр ложку начинки и заверните края, придав овальную форму.</li><li>Разогрейте масло на антипригарной сковороде и обжаривайте зразы на среднем огне по 5–7 минут с каждой стороны до золотистого цвета. Промокните бумажным полотенцем и подавайте тёплыми.</li></ol><p><em>Подавайте горячими со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('bfbc151a-2f96-514f-85f8-a8bf44fd5e1a', '9098ce8a-f512-5727-9910-161198497930', 'en', 'Potato zrazy with cheese filling', 'Golden potato cakes made from mashed and grated raw potatoes, filled with farmer''s cheese, mozzarella and herbs.', '<ol><li>Boil about half of the potatoes (600 g) until tender and mash. Peel and grate the rest on a box grater and squeeze out all the moisture through cheesecloth or a towel.</li><li>Combine the mash with the grated potatoes, 1 tsp salt and 1/2 tsp pepper.</li><li>For the filling mix the farmer''s cheese, grated mozzarella, minced parsley and chives, adding just enough cream to bring it together. Season with salt and pepper.</li><li>Take about 1/4 cup of the potato mixture, flatten it, put a spoonful of filling in the middle and fold the edges over into an oval.</li><li>Heat the oil in a nonstick skillet and fry the cakes over medium heat for 5–7 minutes per side until golden. Drain on paper towels and serve warm.</li></ol><p><em>Serve hot with sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('758d9cf4-621c-595c-97d0-9357f087a849', 'bd8871ba-9f20-5426-9829-75c0ff7db4d7', 'ru', 'Сливочный томатный суп с базиликом и пармезаном', 'Быстрый томатный суп из консервированных помидоров с жареным луком, базиликом, сливками и пармезаном. Сливки и сыр смягчают кислинку томатов.', '<ol><li>Растопите в кастрюле с толстым дном (не алюминиевой) сливочное масло на среднем огне, добавьте лук и обжаривайте 10–12 минут, помешивая, до мягкости и золотистого цвета. Добавьте чеснок на 1 минуту.</li><li>Добавьте измельчённые томаты с соком, куриный бульон, нарезанный базилик, сахар и перец. Доведите до кипения, убавьте огонь и варите под неплотной крышкой 10 минут.</li><li>Суп можно оставить с кусочками или пробить погружным блендером прямо в кастрюле до нужной консистенции (либо партиями в обычном блендере, не наполняя чашу горячим доверху). Верните в кастрюлю на средний огонь.</li><li>Влейте сливки, добавьте тёртый пармезан и снова доведите до лёгкого кипения. Попробуйте, при необходимости посолите и поперчите, выключите огонь.</li><li>Разлейте суп по горячим тарелкам и посыпьте пармезаном и свежим базиликом.</li></ol><p><em>Посыпьте пармезаном и свежим базиликом. Хорош с тостами с сыром.</em></p>', CURRENT_TIMESTAMP),
  ('160751be-0a38-50a2-ad92-797155a54eff', 'bd8871ba-9f20-5426-9829-75c0ff7db4d7', 'en', 'Creamy tomato basil soup with Parmesan', 'A quick soup of canned tomatoes with sautéed onion, basil, cream and Parmesan. The cream and cheese balance the acidity of the tomatoes.', '<ol><li>Melt the butter in a nonreactive heavy pot over medium heat, add the onions and sauté 10-12 minutes, stirring, until soft and golden. Add the garlic for 1 minute until fragrant.</li><li>Add the crushed tomatoes with their juice, chicken stock, chopped basil, sugar and pepper. Bring to a boil, reduce the heat and simmer partly covered for 10 minutes.</li><li>Leave the soup chunky or blend it with an immersion blender in the pot to the consistency you like (or in batches in a regular blender, never filling it to the top with hot liquid). Return to the pot over medium heat.</li><li>Stir in the cream and the grated Parmesan and return to a simmer. Season with salt and pepper to taste and turn off the heat.</li><li>Ladle into warm bowls and top with more Parmesan and fresh basil.</li></ol><p><em>Top with Parmesan and fresh basil. Great with grilled cheese sandwiches.</em></p>', CURRENT_TIMESTAMP),
  ('92f53c4c-b03c-56ab-98d9-89bab0126f6e', '620d172e-eaa2-57a3-82fc-c63874b1acab', 'ru', 'Курица с овощами и кешью в соево-медовом соусе', 'Куриные бёдра с брокколи, кабачком, грибами, перцем и морковью в соусе из сои, мёда, чеснока и имбиря. Быстрое блюдо на ужин, овощи можно менять.', '<ol><li>Срежьте с бёдер лишний жир и нарежьте мясо небольшими кусочками. Овощи нарежьте примерно того же размера.</li><li>Для соуса соедините в миске бульон, воду, соевый соус, мёд и кукурузный крахмал.</li><li>В большой сковороде или воке на среднем-сильном огне разогрейте 1 ст. л. масла. Выложите курицу одним слоем и обжарьте до румяности, перемешивая. Переложите на тарелку.</li><li>В ту же сковороду добавьте оставшееся масло и сливочное масло, затем брокколи, кабачок, грибы, перец, лук и морковь. Готовьте, часто помешивая, до состояния «аль денте».</li><li>Верните курицу в сковороду, добавьте чеснок и имбирь и готовьте 1 минуту, помешивая.</li><li>Ещё раз взбейте соус (крахмал оседает). Добавьте кешью и влейте соус, доведите до кипения. Убавьте огонь и тушите, пока соус не загустеет и не обволакивает ингредиенты. При желании посыпьте зелёным луком и кунжутом.</li></ol><p><em>Подавайте с отварным рисом, посыпав зелёным луком и кунжутом.</em></p>', CURRENT_TIMESTAMP),
  ('ef67bc85-7b4d-5a86-aa9f-2df08994bcb9', '620d172e-eaa2-57a3-82fc-c63874b1acab', 'en', 'Chicken stir fry with cashews, soy sauce and honey', 'Chicken thighs with broccoli, zucchini, mushrooms, pepper and carrot in a sauce of soy, honey, garlic and ginger. A quick weeknight dish where the vegetables are easy to swap.', '<ol><li>Trim excess fat from the chicken thighs and cut them into bite-sized pieces. Cut the vegetables to a similar size.</li><li>For the sauce, mix the broth, water, soy sauce, honey and cornstarch in a bowl.</li><li>Heat 1 tbsp oil in a large pan or wok over medium-high heat. Add the chicken in a single layer and cook until browned, stirring as needed. Remove to a plate.</li><li>Add the remaining oil and the butter to the pan with the broccoli, zucchini, mushrooms, pepper, onion and carrot. Cook, stirring often, until crisp-tender.</li><li>Return the chicken to the pan, add the garlic and ginger and cook for 1 minute, stirring.</li><li>Whisk the sauce again because the cornstarch settles. Add the cashews, pour in the sauce and bring to a boil. Turn the heat down and simmer until the sauce thickens and coats everything. Garnish with green onion and sesame seeds if you like.</li></ol><p><em>Serve over rice, garnished with green onion and sesame seeds.</em></p>', CURRENT_TIMESTAMP),
  ('6d0ae433-53c7-529d-93c0-f1f588dbf690', '5c544f42-a480-5f91-9e0a-0bed2176b350', 'ru', 'Шакшука с колбасками и пармезаном', 'Яйца, запечённые в густом томатном соусе с луком, чесноком и обжаренными колбасками. Готовится на одной сковороде и подходит и на завтрак, и на ужин.', '<ol><li>В большой сковороде (около 30 см, не алюминиевой) на среднем огне разогрейте оливковое масло и обжарьте колбаски 5 минут, разбивая лопаткой, до румяности. Переложите на тарелку.</li><li>Растопите в сковороде сливочное масло, обжарьте лук 4–5 минут до мягкости и золотистого цвета. Добавьте чеснок на 30 секунд.</li><li>Добавьте томаты с соком и разомните их лопаткой. Добавьте соль и сахар, убавьте огонь и тушите без крышки 15 минут, иногда помешивая и разминая томаты, пока соус не загустеет настолько, что в нём можно сделать лунки.</li><li>Разбейте яйца в лунки и слегка посолите каждое. Разложите вокруг яиц обжаренные колбаски и посыпьте петрушкой.</li><li>Накройте крышкой и готовьте на слабом огне 5–8 минут (проверьте на 5-й), пока белки не схватятся, а желтки останутся мягкими. Подавайте с пармезаном и жареным хлебом.</li></ol><p><em>Посыпьте тёртым пармезаном и подавайте с поджаренным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('aca22a5e-269e-5d46-947a-22702f6104e3', '5c544f42-a480-5f91-9e0a-0bed2176b350', 'en', 'Shakshuka with sausage and Parmesan', 'Eggs poached in a thick tomato sauce with onion, garlic and browned sausage. A one-skillet meal for breakfast or dinner.', '<ol><li>In a large 12-inch nonreactive skillet over medium heat, heat the olive oil and sauté the sausage for 5 minutes, breaking it up, until browned. Move to a plate.</li><li>Melt the butter in the skillet and sauté the onion 4-5 minutes until soft and golden. Add the garlic for 30 seconds.</li><li>Add the tomatoes with their juice and break them up with a spatula. Stir in the salt and sugar, reduce the heat and simmer uncovered for 15 minutes, stirring now and then, until the sauce is thick enough to make wells for the eggs.</li><li>Crack the eggs into the wells and lightly salt each one. Scatter the cooked sausage around the eggs and top with parsley.</li><li>Cover and cook on low for 5-8 minutes (check at 5), until the whites are set and the yolks still soft. Serve with Parmesan and toasted bread.</li></ol><p><em>Top with grated Parmesan and serve with toasted bread.</em></p>', CURRENT_TIMESTAMP),
  ('e9753f6d-5546-5d87-8552-2253fd59f94b', '3c8968f2-d61c-5fba-974a-f287383f38f9', 'ru', 'Крем-суп из цветной капусты с беконом и кукурузой', 'Густой суп-пюре из цветной капусты и картофеля со сливками, который подают с хрустящим беконом, варёной кукурузой и петрушкой.', '<ol><li>В кастрюле или жаровне с толстым дном на среднем-сильном огне обжарьте бекон до золотистого цвета. Шумовкой переложите на бумажное полотенце.</li><li>Слейте бекон-жир в миску, верните в кастрюлю 3 ст. л., остальной выбросьте. Обжарьте нарезанный лук 5 минут до мягкости.</li><li>Добавьте картофель, соцветия цветной капусты, куриный бульон, тёплую воду, соль, чёрный и красный перец. Перемешайте и доведите до кипения. Влейте сливки, убавьте огонь, накройте и варите около 15 минут, пока картофель не станет мягким.</li><li>Пока варится суп, отварите кукурузу, слейте воду и накройте, чтобы не остыла.</li><li>Пюрируйте суп порциями в блендере до полной гладкости, оставляя в крышке отверстие для выхода пара. Верните в кастрюлю и доведите до вкуса (для взрослых можно добавить ещё ½ ч. л. красного перца).</li><li>Разлейте по горячим тарелкам и щедро посыпьте кусочками бекона, кукурузой и петрушкой.</li></ol><p><em>Подавайте с кусочками бекона, зёрнами кукурузы и свежей петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('107b48e4-d179-57cf-8199-57529bec9c45', '3c8968f2-d61c-5fba-974a-f287383f38f9', 'en', 'Creamy cauliflower soup with bacon and corn', 'A thick puréed soup of cauliflower and potatoes with cream, served topped with crisp bacon, cooked corn and parsley.', '<ol><li>Cook the bacon in a heavy-bottomed soup pot or Dutch oven over medium-high heat until browned. Remove with a slotted spoon to a paper towel-lined plate.</li><li>Pour the bacon fat into a bowl, return 3 tbsp to the pot and discard the rest. Sauté the diced onion 5 minutes until soft.</li><li>Add the potatoes, cauliflower, chicken stock, warm water, salt, black pepper and cayenne. Stir and bring to a boil. Add the cream, reduce to a simmer, cover and cook about 15 minutes until the potatoes are cooked through.</li><li>Meanwhile cook the corn, drain and cover to keep warm.</li><li>Puree the soup in batches in a blender until completely smooth, leaving a vent in the lid so steam can escape. Return it to the pot and adjust the seasoning (for an adult version add another ½ tsp cayenne).</li><li>Ladle into warm bowls and garnish generously with bacon bits, corn and parsley.</li></ol><p><em>Garnish with bacon bits, corn kernels and fresh parsley.</em></p>', CURRENT_TIMESTAMP),
  ('59aee17b-2387-5c62-bb0d-18b1963fd6a3', 'bf9c2286-1d56-55f4-b848-508fd9475538', 'ru', 'Фриттата с моцареллой, перцем и рукколой', 'Запечённый омлет из яиц со сливками, моцареллой, сладким перцем, черри и рукколой. Всё готовится на одной сковороде, а овощи легко менять.', '<ol><li>Разогрейте духовку до 205 °C. Взбейте яйца со сливками и солью до однородности.</li><li>Растопите масло и смажьте им стенки чугунной сковороды или формы для запекания. Равномерно разложите на дне овощи и рукколу.</li><li>Залейте яичной смесью, посыпьте сыром и вилкой слегка перемешайте его с яйцами. Запекайте 15–17 минут, пока края и середина не схватятся, а верх не зарумянится (внутри должно быть 71 °C).</li></ol><p><em>Посыпьте свежей зеленью. Хорошо подходит и к завтраку, и к лёгкому ужину.</em></p>', CURRENT_TIMESTAMP),
  ('bf217f38-58b0-5693-ac3c-11fd56f02d2f', 'bf9c2286-1d56-55f4-b848-508fd9475538', 'en', 'Frittata with mozzarella, peppers and arugula', 'A baked egg dish with cream, mozzarella, sweet pepper, cherry tomatoes and arugula. It cooks in one pan and the vegetables are easy to swap.', '<ol><li>Preheat the oven to 205 °C (400 °F). Whisk the eggs, cream and salt until smooth and even.</li><li>Melt the butter and coat the sides of a cast-iron skillet or baking dish with it. Spread the vegetables and arugula evenly on the bottom.</li><li>Pour the egg mixture over, sprinkle the cheese on top and use a fork to work it lightly into the eggs. Bake 15-17 minutes, until the edges and center are set and the top is golden (internal temperature 71 °C / 160 °F).</li></ol><p><em>Sprinkle with fresh herbs. Works for breakfast and a light dinner alike.</em></p>', CURRENT_TIMESTAMP),
  ('7f9a26ab-b4ea-567f-9dcf-8f8a02483e90', 'f4245b0e-8db9-5568-8f65-24e409bc78fd', 'ru', 'Котлеты из индейки с кабачком и рикоттой', 'Сочные котлеты наполовину из мяса, наполовину из кабачка, с рикоттой, чесноком и зелёным луком.', '<ol><li>Натрите кабачки, посыпьте 1 ч. л. соли и оставьте на 10 минут. Отожмите сок как можно тщательнее и переложите кабачки в большую миску.</li><li>Добавьте фарш из индейки или курицы, 1 ч. л. соли, перец, зелёный лук, яйцо, пропущенный через пресс чеснок и рикотту. Перемешайте.</li><li>Разогрейте в большой антипригарной сковороде 3–4 ст. л. масла на среднем огне. Сформируйте из полной столовой ложки массы круглые котлеты толщиной около 8 мм.</li><li>Жарьте без крышки 3 минуты, переверните, накройте крышкой и жарьте ещё 3–4 минуты до готовности. Для следующих порций при необходимости подливайте масло.</li></ol><p><em>Подавайте со сметаной и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('f67261df-1288-55c6-ad49-a09fd9f893a1', 'f4245b0e-8db9-5568-8f65-24e409bc78fd', 'en', 'Turkey and zucchini patties with ricotta', 'Juicy patties that are half meat and half zucchini, with ricotta, garlic and green onion.', '<ol><li>Grate the zucchini, sprinkle with 1 tsp salt and leave for 10 minutes. Squeeze out as much juice as you can and transfer to a large bowl.</li><li>Add the ground turkey or chicken, 1 tsp salt, pepper, green onion, egg, pressed garlic and ricotta. Mix well.</li><li>Heat 3–4 tbsp of oil in a large nonstick skillet over medium heat. Shape a heaped tablespoon of the mixture into round patties about 8 mm thick.</li><li>Cook uncovered for 3 minutes, flip, cover and cook for 3–4 minutes more until done. Add more oil for later batches if needed.</li></ol><p><em>Serve with sour cream and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('043fff7b-0f48-55f6-b70c-8b798da1a360', 'a2ea4d3f-6fd4-5533-8c5c-20faecd930d5', 'ru', 'Треска в томатном соусе', 'Обжаренные в муке кусочки трески в густом томатном соусе с луком, лимоном, каперсами и мёдом, как в детстве на Украине.', '<ol><li>В тяжёлой сковороде растопите сливочное масло и 5 минут пассеруйте мелко нарезанный лук до мягкости. Добавьте чеснок и томатную пасту и готовьте ещё 5 минут, помешивая, пока паста не начнёт темнеть.</li><li>Влейте овощной бульон, положите специи (лавровый лист, перец горошком, душистый перец и гвоздику, завёрнутые в марлю или в чайный ёрш). Доведите до слабого кипения, накройте, убавьте огонь и варите 20 минут.</li><li>Пока варится соус, обсушите рыбу, нарежьте кусками по 7–8 см. Смешайте муку, соль и перец, обваляйте рыбу и обжарьте в горячем масле порциями по 3 минуты с каждой стороны до золотистого цвета.</li><li>Выньте мешочек со специями. Добавьте лимонный сок, каперсы и мёд и прогрейте 2 минуты. Положите рыбу в соус, переверните пару раз и прогрейте. Посыпьте петрушкой.</li></ol><p><em>Подавайте тёплой или холодной с картофельным пюре или отварным картофелем и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('333054b2-4224-50c8-abc6-2ea8a40949ba', 'a2ea4d3f-6fd4-5533-8c5c-20faecd930d5', 'en', 'Cod in tomato sauce', 'Flour-dusted cod pieces in a thick tomato sauce with onion, lemon, capers and honey, inspired by Ukrainian sardines in tomato.', '<ol><li>In a heavy-bottomed pan melt the butter and cook the finely chopped onion for 5 minutes until soft. Add the garlic and tomato paste and cook for 5 more minutes, stirring, until the paste begins to brown.</li><li>Pour in the vegetable stock and add the spices (bay leaf, peppercorns, allspice berries and cloves in a cheesecloth bundle or tea infuser). Bring to a gentle boil, cover, reduce the heat and simmer for 20 minutes.</li><li>Meanwhile pat the fish dry and cut it into 7–8 cm pieces. Mix the flour, salt and pepper, dredge the fish and fry in hot oil in batches for 3 minutes per side until golden and cooked through.</li><li>Discard the spice bundle. Stir in the lemon juice, capers and honey and cook for 2 minutes. Add the fish to the sauce, turn it a couple of times to coat and heat through. Sprinkle with parsley.</li></ol><p><em>Serve warm or cold with mashed or boiled potatoes and herbs.</em></p>', CURRENT_TIMESTAMP),
  ('f62e9ff5-3758-59a7-9409-9d3c6d4e48d5', '2c289aea-5919-57f1-b733-84a2558bf3ee', 'ru', 'Блинчики с индейкой и грибами', 'Тонкие блины с мясной начинкой из индейки, обжаренных шампиньонов, лука и моркови. Подаются со сметаной, хороший способ использовать остатки запечённой индейки.', '<ol><li>Для блинов взбейте в блендере в указанном порядке воду, молоко, яйца, растопленное масло, муку и соль до гладкого теста.</li><li>На среднем огне растопите на большой антипригарной сковороде кусочек масла. Влейте 2–3 ст. л. теста (в большую сковороду 3 ст. л.) и сразу крутите сковороду, чтобы тесто растеклось по дну. Первый блин может получиться неидеальным, это нормально.</li><li>Когда низ слегка зарумянится (меньше минуты), переверните блин тонкой лопаткой. На хорошей сковороде масло для следующих блинов добавлять не нужно. Остудите блины на доске несколько минут, потом сложите стопкой.</li><li>Для начинки разогрейте на среднем-сильном огне масло и обжаривайте шампиньоны, тёртую морковь и лук 7–10 минут до мягкости, иногда помешивая. Посолите и поперчите.</li><li>Пропустите индейку вместе с овощами через мясорубку с крупной решёткой (можно измельчить кухонным комбайном или мелко порубить ножом). Перемешайте. Если начинка слишком сухая, добавьте 1 ст. л. масла и 1 ст. л. воды.</li><li>Намажьте на каждый блин около 2 ст. л. начинки до краёв. Сверните трубочкой или сложите дважды в треугольник. Подавайте со сметаной.</li></ol><p><em>Подавайте с щедрой ложкой сметаны. Блины можно свернуть трубочкой или сложить треугольником.</em></p>', CURRENT_TIMESTAMP),
  ('dabc0553-aba5-5340-89a7-f6f2f31b1ac3', '2c289aea-5919-57f1-b733-84a2558bf3ee', 'en', 'Savory crepes with turkey and mushrooms', 'Thin crepes filled with a mixture of turkey, sautéed mushrooms, onion and carrot. Served with sour cream, and a good way to use leftover roast turkey.', '<ol><li>For the crepes, blend the water, milk, eggs, melted butter, flour and salt in that order until you have a smooth batter.</li><li>Melt a dab of butter in a large non-stick skillet over medium heat. Pour in 2-3 tbsp batter (3 tbsp for a large skillet) and swirl at once to coat the bottom. The first crepe may turn out ugly, which is normal.</li><li>When the underside is lightly golden (under a minute), flip with a thin spatula. In a good non-stick pan you will not need more butter for the rest. Cool the crepes on a cutting board for a few minutes before stacking.</li><li>For the filling, heat the oil over medium-high heat and sauté the mushrooms, grated carrot and onion for 7-10 minutes until soft, stirring now and then. Season with salt and pepper.</li><li>Grind the turkey together with the vegetable mixture in a meat grinder with the large plate (a food processor or fine chopping by knife also works). Stir to combine. If the mixture is too dry to spread, add 1 tbsp oil and 1 tbsp water.</li><li>Spread about 2 tbsp of the filling over each crepe to the edges. Roll up like a log or fold in half twice into a triangle. Serve with sour cream.</li></ol><p><em>Serve with a generous dollop of sour cream. Roll them up or fold into triangles.</em></p>', CURRENT_TIMESTAMP),
  ('600d967e-0135-5d3a-b89c-83d6ce410848', '868d55e2-d5f2-5a9b-af09-5a48dd533b3c', 'ru', 'Запеканка из картофеля и кабачков со сливками и пармезаном', 'Слои тонко нарезанного картофеля и кабачка, запечённые в сливочно-чесночном соусе с пармезаном. Простой и сытный гарнир.', '<ol><li>Разогрейте духовку до 205 °C. Смешайте в миске сливки, 100 г пармезана, чеснок и зелёный лук.</li><li>Нарежьте кабачки колечками толщиной около 6 мм (они должны быть толще картофеля), а картофель нарежьте очень тонко, примерно 1,5 мм. Переложите в большую миску, посолите, поперчите и посыпьте орегано.</li><li>Выложите овощи слоями в форму 23 × 33 см, чередуя кабачок и картофель. Картофеля будет больше, местами его можно класть в два слоя.</li><li>Равномерно залейте сливочной смесью и посыпьте оставшимся пармезаном. Запекайте без крышки 40–45 минут, пока картофель не станет мягким. Дайте постоять не менее 10 минут, украсьте зелёным луком и подавайте.</li></ol><p><em>Дайте запеканке постоять 10 минут и посыпьте зелёным луком. Подходит как гарнир к мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('7f79431b-b33f-5c61-89c1-7323e799922d', '868d55e2-d5f2-5a9b-af09-5a48dd533b3c', 'en', 'Zucchini and potato gratin with cream and Parmesan', 'Layers of thinly sliced potatoes and zucchini baked in a garlicky cream and Parmesan sauce. A simple, hearty side dish.', '<ol><li>Preheat the oven to 205 °C (400 °F). In a bowl mix the cream, 100 g of the Parmesan, the garlic and the chives.</li><li>Slice the zucchini into ¼ inch rings (thicker than the potatoes) and the potatoes very thinly, about 1/16 inch. Place in a large bowl and season with the salt, pepper and oregano.</li><li>Layer the vegetables in a 9 × 13 inch dish, alternating zucchini and potatoes. There will be more potato slices, so double them up here and there.</li><li>Pour the cream mixture evenly over the top and sprinkle with the remaining Parmesan. Bake uncovered 40-45 minutes until the potatoes are soft. Rest at least 10 minutes, garnish with more chives and serve.</li></ol><p><em>Rest for 10 minutes and garnish with chives. Goes with meat and fish.</em></p>', CURRENT_TIMESTAMP),
  ('ceb33f4f-322c-5a35-bdd7-24b97baa950f', '90386554-a8b4-55b9-8308-fbfece7aa566', 'ru', 'Салат с грибами и яйцом, укропом и майонезом', 'Обжаренные шампиньоны и лук с варёными яйцами, укропом и заправкой из майонеза, дижонской горчицы и лимонного сока. Не требует разогрева, удобен для обеда.', '<ol><li>Разогрейте большую сковороду на среднем-сильном огне, добавьте 2–3 ст. л. масла и мелко нарезанные шампиньоны. Жарьте 12–15 минут до золотистого цвета, пока не выпарится вся жидкость. Переложите в миску.</li><li>Одновременно на второй антипригарной сковороде на среднем огне с 2 ст. л. масла обжарьте лук 10–13 минут до золотистого цвета, добавьте чеснок и жарьте ещё 1–2 минуты. Переложите к грибам, добавьте нарезанные кубиками варёные яйца и укроп.</li><li>Смешайте майонез, дижонскую горчицу и лимонный сок, заправьте салат до равномерного покрытия. Слегка посолите и поперчите. Подавайте при комнатной температуре или охлаждённым.</li></ol><p><em>Подавайте при комнатной температуре или охлаждённым, можно на хлебе как открытые бутерброды с солёным огурцом.</em></p>', CURRENT_TIMESTAMP),
  ('59d9b9a0-e391-5a74-b185-85823b06bb0f', '90386554-a8b4-55b9-8308-fbfece7aa566', 'en', 'Mushroom and egg salad with dill and mayonnaise', 'Sautéed mushrooms and onion mixed with boiled eggs, dill and a dressing of mayonnaise, Dijon mustard and lemon juice. No reheating needed, so it suits a packed lunch.', '<ol><li>Heat a large skillet over medium-high heat, add 2-3 tbsp olive oil and the diced mushrooms. Sauté 12-15 minutes until golden brown and no liquid remains. Transfer to a mixing bowl.</li><li>At the same time, in a second non-stick pan over medium heat with 2 tbsp olive oil, sauté the onion 10-13 minutes until golden, then add the garlic and cook 1-2 more minutes. Add to the bowl along with the diced hard-boiled eggs and dill.</li><li>Stir together the mayonnaise, Dijon mustard and lemon juice and mix the dressing into the salad. Season lightly with salt and pepper and serve at room temperature or chilled.</li></ol><p><em>Serve at room temperature or chilled, or on bread as open-faced sandwiches with a pickle.</em></p>', CURRENT_TIMESTAMP),
  ('bc1ac74e-19c8-5b78-90cf-05b6c889d861', 'a48f0215-e7bc-5985-ae2d-6098057525f3', 'ru', 'Рагу из баранины с грибами и красным вином', 'Наваристое рагу из баранины с беконом, шампиньонами, картофелем и морковью, томлёное в духовке до мягкости.', '<ol><li>В чугунной кастрюле (около 5 л) обжарьте нарезанный полосками бекон на среднем огне, пока не вытопится жир и он не подрумянится. Переложите бекон шумовкой на тарелку.</li><li>Посолите и поперчите баранину, посыпьте мукой и перемешайте. Обжарьте в бекониевом жире в два захода по 3–4 минуты с каждой стороны, переложите к бекону.</li><li>Обжарьте лук 2 минуты, добавьте чеснок на минуту. Влейте вино, соскребая всё со дна, добавьте грибы, доведите до кипения и варите без крышки 10 минут. Разогрейте духовку до 160 °C.</li><li>Верните бекон и баранину в кастрюлю, влейте бульон, добавьте томатную пасту, соль, перец, тимьян и лавровый лист. Положите картофель и морковь так, чтобы картофель почти весь был покрыт жидкостью.</li><li>Доведите до кипения, накройте крышкой и поставьте в духовку на 1 час 45 минут, пока мясо и картофель не станут очень мягкими. Посыпьте петрушкой.</li></ol><p><em>Подавайте горячим с рубленой петрушкой и свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('7a75b539-af72-5840-a432-33a115a0102d', 'a48f0215-e7bc-5985-ae2d-6098057525f3', 'en', 'Lamb stew with mushrooms and red wine', 'A hearty lamb stew with bacon, mushrooms, potatoes and carrots slowly braised in the oven until tender.', '<ol><li>In a 5-quart Dutch oven cook the chopped bacon over medium heat until browned and the fat has rendered. Move to a plate with a slotted spoon.</li><li>Season the lamb with salt and pepper, sprinkle with the flour and toss. Brown in the bacon fat in two batches, 3–4 minutes per side, and transfer to the bacon.</li><li>Cook the onion for 2 minutes, then the garlic for a minute. Pour in the wine, scraping the bottom, add the mushrooms, bring to a simmer and cook uncovered for 10 minutes. Preheat the oven to 160 °C.</li><li>Return the bacon and lamb to the pot, add the stock, tomato paste, salt, pepper, thyme and bay leaves. Stir in the potatoes and carrots so the potatoes are mostly submerged.</li><li>Bring to a boil, cover and transfer to the oven for 1 hour 45 minutes until the lamb and potatoes are very tender. Sprinkle with parsley.</li></ol><p><em>Serve hot with chopped parsley and fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('24ba7a96-7344-53ee-bd95-816ed4905dbc', '391a4cea-0bb8-5785-a7a5-40d10a7a851b', 'ru', 'Котлеты из лосося с луком и болгарским перцем', 'Хрустящие снаружи котлеты из запечённого лосося с луком, перцем и сухарями, обжаренные на сливочном масле.', '<ol><li>Разогрейте духовку до 220 °C. Выложите лосось кожей вниз на противень с пергаментом, смажьте маслом, посыпьте чесночной солью и перцем. Запекайте 10–15 минут до готовности.</li><li>Накройте фольгой и дайте отдохнуть 10 минут. Снимите кожу, разберите рыбу вилкой, уберите кости и остудите до комнатной температуры.</li><li>На сковороде на среднем огне прогрейте ложку масла и 1 ст. л. сливочного масла, 7–9 минут обжарьте мелко нарезанные лук и перец до мягкости и золотистого цвета. Снимите с огня.</li><li>Смешайте лосось, лук с перцем, панировочные сухари, яйца, майонез, вустерский соус, чесночную соль, перец и петрушку. Сформируйте 13–14 котлет толщиной 8–12 мм.</li><li>На большой сковороде прогрейте ложку масла и ложку сливочного. Обжаривайте половину котлет по 3,5–4 минуты с каждой стороны до золотистой корочки; если подгорают, убавьте огонь. Переложите на бумажное полотенце. Так же поджарьте вторую партию.</li></ol><p><em>Подавайте с соусом тартар или сметанным соусом с зеленью и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('10b2f619-fbfe-5169-ad62-07c8a67ba875', '391a4cea-0bb8-5785-a7a5-40d10a7a851b', 'en', 'Salmon cakes with onion and bell pepper', 'Crisp-edged cakes of baked flaked salmon with onion, bell pepper and panko, pan-fried in butter.', '<ol><li>Preheat the oven to 220 °C. Place the salmon skin side down on a parchment-lined baking sheet, brush with oil and season with garlic salt and pepper. Bake for 10–15 minutes until just cooked.</li><li>Cover with foil and rest for 10 minutes. Discard the skin, flake the fish with forks, remove any bones and cool to room temperature.</li><li>Heat 1 tbsp oil and 1 tbsp butter in a skillet over medium heat and saute the finely diced onion and pepper for 7–9 minutes until soft and golden. Remove from the heat.</li><li>Combine the flaked salmon, onion and pepper, breadcrumbs, eggs, mayonnaise, Worcestershire sauce, garlic salt, pepper and parsley. Form 13–14 patties 8–12 mm thick.</li><li>In a large pan heat 1 tbsp oil and 1 tbsp butter and cook half of the cakes 3.5–4 minutes per side until golden and cooked through, reducing the heat if they brown too fast. Drain on paper towels and repeat with the remaining cakes.</li></ol><p><em>Serve with tartar sauce or a herby sour cream sauce and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('5b949e02-6511-5fcf-a894-70dd120b955b', '9b65f4b1-380b-5b30-a38d-0f0eaaf31cc6', 'ru', 'Хрустящий молодой картофель на сковороде с зеленью', 'Мелкий картофель в кожуре, обжаренный половинками до золотистой хрустящей корочки, с зелёным луком.', '<ol><li>Разогрейте на среднем огне большую сковороду с 1 ст. л. сливочного и 2 ст. л. оливкового масла. Выложите картофель (разрезанный на куски толщиной около 2 см) срезом вниз в один слой и жарьте без крышки, не трогая, 8–10 минут до золотистой корочки.</li><li>Переверните, накройте крышкой и жарьте ещё 5 минут до золотистого цвета со второй стороны. Открывайте крышку осторожно: брызги.</li><li>Снова переверните, накройте и готовьте ещё 5 минут, пока картофель не станет легко прокалываться ножом.</li><li>Снимите с огня, посолите, поперчите и перемешайте с половиной зелёного лука. Перед подачей посыпьте оставшимся.</li></ol><p><em>Подавайте к мясу, рыбе или с яичницей.</em></p>', CURRENT_TIMESTAMP),
  ('b282351e-1813-5ac6-be08-2caccc5308fc', '9b65f4b1-380b-5b30-a38d-0f0eaaf31cc6', 'en', 'Crisp sautéed baby potatoes with chives', 'Small unpeeled potatoes pan-fried cut side down until golden and crisp, tossed with chives.', '<ol><li>Heat a large skillet over medium heat with 1 tbsp butter and 2 tbsp olive oil. Arrange the potatoes (cut into 2 cm thick pieces) cut side down in one layer and cook uncovered and undisturbed for 8–10 minutes until a golden crust forms.</li><li>Turn the potatoes, cover and cook for another 5 minutes until golden on the second side. Lift the lid carefully, as it can splatter.</li><li>Turn again, cover and cook another 5 minutes until easily pierced with a knife.</li><li>Remove from the heat, season with salt and pepper and toss with half of the chives. Sprinkle with more just before serving.</li></ol><p><em>Serve with meat, fish or fried eggs.</em></p>', CURRENT_TIMESTAMP),
  ('ed39530d-4b47-5c16-aaa9-9e61c06ba25d', 'd279898a-b535-54df-bab2-5d70e51dc08a', 'ru', 'Шашлык из говядины в лимонно-укропном маринаде', 'Нежные кусочки говядины, замаринованные в масле с лимонным соком, чесноком и укропом, на шпажках с перцем и луком.', '<ol><li>В стеклянной или пластиковой (не алюминиевой) миске смешайте оливковое масло, лимонный сок, соль, перец, чеснок, укроп и лавровый лист.</li><li>Нарежьте говядину кусками около 4 см, добавьте в маринад и перемешайте. Маринуйте в холодильнике 4–6 часов, несколько раз помешивая. Если масло загустело, подержите мясо 30 минут при комнатной температуре.</li><li>Замочите деревянные шпажки минимум на 30 минут. Нарежьте перец и лук кусками около 4 см и нанижите на шпажки вперемешку с мясом. Полейте оставшимся маринадом.</li><li>Жарьте на гриле на среднем и сильном огне 8–10 минут до нужной прожарки, переворачивая каждые 2–3 минуты. Дайте отдохнуть минимум 5 минут, иначе сок вытечет.</li></ol><p><em>Дайте мясу отдохнуть 5 минут и подавайте со свежими овощами и любимым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('3dc6b312-2588-53ba-b44f-fa88d2503dab', 'd279898a-b535-54df-bab2-5d70e51dc08a', 'en', 'Beef shashlik with lemon and dill marinade', 'Tender beef cubes marinated in oil, lemon, garlic and dill and grilled on skewers with peppers and onion.', '<ol><li>In a glass or plastic (not aluminum) bowl combine the olive oil, lemon juice, salt, pepper, garlic, dill and bay leaves.</li><li>Cut the beef into pieces of about 4 cm, add to the marinade and mix. Marinate in the refrigerator for 4–6 hours, stirring a few times. If the oil has firmed up, leave the meat at room temperature for 30 minutes.</li><li>Soak wooden skewers for at least 30 minutes. Cut the peppers and onion into 4 cm pieces and thread them onto skewers with the meat. Brush with the remaining marinade.</li><li>Grill over medium-high heat for 8–10 minutes to your preferred doneness, turning every 2–3 minutes. Rest for at least 5 minutes, or the juices will run out.</li></ol><p><em>Rest the skewers for 5 minutes and serve with fresh vegetables and your favourite sauce.</em></p>', CURRENT_TIMESTAMP),
  ('5d70f6bb-4c50-5252-9e0a-a5d86a63927a', '40b7f095-b6ee-5708-be4f-c095107d406f', 'ru', 'Салат из огурцов с фетой и лимонно-бальзамической заправкой', 'Хрустящий салат из огурцов, красного лука и болгарского перца с брынзой-фетой, заправленный маслом, лимоном и бальзамическим уксусом.', '<ol><li>В небольшой миске смешайте оливковое масло, бальзамический уксус, лимонный сок, соль и перец до растворения соли.</li><li>Нарежьте огурцы кольцами, перец соломкой, лук тонкими полукольцами и сложите в миску.</li><li>Перед подачей полейте заправкой, щедро посыпьте раскрошенной фетой и перемешайте. При желании досолите.</li></ol><p><em>Заправляйте непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('c246ed7d-d2b6-5811-92bc-b652a390cb22', '40b7f095-b6ee-5708-be4f-c095107d406f', 'en', 'Cucumber salad with feta and lemon-balsamic dressing', 'A crisp salad of cucumbers, red onion and bell pepper with feta and a dressing of olive oil, lemon and balsamic vinegar.', '<ol><li>In a small bowl stir together the olive oil, balsamic vinegar, lemon juice, salt and pepper until the salt dissolves.</li><li>Slice the cucumbers into rings, the pepper into strips and the onion thinly, and place in a mixing bowl.</li><li>Just before serving, drizzle with the dressing, sprinkle with plenty of feta and toss. Add more salt if desired.</li></ol><p><em>Dress just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('0d413082-e9b9-5811-a843-cbd00ec5dd82', '5ff0aa22-3d99-5b86-ac1d-b7ef667a6124', 'ru', 'Суп с говядиной и овощами на томатном бульоне', 'Наваристый суп из мягкой говядины с картофелем, морковью, сельдереем и стручковой фасолью в томатно-говяжьем бульоне. Готовится в одной кастрюле.', '<ol><li>Разогрейте в жаровне или толстостенной кастрюле масло на среднем-сильном огне. Обжарьте говядину одним слоем до румяной корочки со всех сторон, при необходимости порциями.</li><li>Добавьте лук и готовьте около 3 минут до мягкости и лёгкой золотистости.</li><li>Влейте бульон, добавьте томаты, лавровый лист, соль и перец. Доведите до кипения, убавьте огонь и варите под неплотной крышкой 55–75 минут, пока говядина не станет мягкой.</li><li>Добавьте картофель, морковь и сельдерей и варите около 20 минут.</li><li>Добавьте стручковую фасоль и зелёный лук и варите ещё 10 минут. Добавьте петрушку, посолите и поперчите по вкусу и снимите с огня.</li></ol><p><em>Подавайте горячим со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('ce7b0497-34eb-56c5-a667-94a216b9c01f', '5ff0aa22-3d99-5b86-ac1d-b7ef667a6124', 'en', 'Vegetable beef soup in tomato broth', 'A hearty soup of tender beef with potatoes, carrots, celery and green beans in a tomato and beef broth. Made in one pot.', '<ol><li>Heat the oil in a heavy soup pot or Dutch oven over medium-high heat. Brown the beef in a single layer on all sides, in batches if needed, for a good sear.</li><li>Add the onion and cook about 3 minutes until softened and lightly golden.</li><li>Add the broth, tomatoes, bay leaves, salt and pepper. Bring to a boil, reduce to a simmer and cook partially covered 55-75 minutes until the beef is tender.</li><li>Add the potatoes, carrots and celery and cook about 20 minutes.</li><li>Add the green beans and green onion and simmer 10 more minutes. Stir in the parsley, season to taste and take off the heat.</li></ol><p><em>Serve hot with fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('5322c1ad-11c6-5aa6-9993-f08f70bf8c7d', '3c96a25d-3159-550f-8ccb-c250e73e52d2', 'ru', 'Пастуший пирог с говядиной и картофельным пюре с пармезаном', 'Запеканка из мясного фарша с овощами в винном соусе под шапкой из сливочного картофельного пюре с пармезаном. Сытное блюдо для большой семьи, хорошо разогревается на следующий день.', '<ol><li>Картофель нарежьте кусочками по 2,5 см, залейте холодной водой, доведите до кипения и варите 12–15 минут до мягкости, не переваривайте. Слейте воду и разомните картофель в той же кастрюле.</li><li>Добавьте тёплые сливки и ½ ч. л. соли и разомните до гладкости. В конце вмешайте пармезан и взбитое яйцо.</li><li>Разогрейте духовку до 205 °C, решётка в центре. В большой сковороде на среднем огне разогрейте масло, выложите фарш, разбейте лопаткой, посолите (1 ч. л.) и поперчите (½ ч. л.), готовьте около 5 минут до исчезновения розового цвета.</li><li>Добавьте лук и готовьте 3 минуты до мягкости, затем чеснок на минуту. Посыпьте мукой и помешивайте 1 минуту, на дне сковороды появится плёнка.</li><li>Влейте вино, соскребая со дна сковороды, и готовьте минуту. Добавьте бульон, томатную пасту и вустерский соус.</li><li>Добавьте замороженные овощи и доведите до лёгкого кипения. Посолите (ещё ½ ч. л.) и поперчите (¼ ч. л.), убавьте огонь, накройте и варите 10 минут, пока соус слегка не загустеет.</li><li>Переложите мясную начинку в глубокую форму (28 × 18 см или 23 × 23 см). Выложите сверху пюре и разровняйте, закрывая края, чтобы начинка не выливалась. Смажьте верх растопленным маслом.</li><li>Поставьте под форму лист фольги, чтобы собрать стекающий сок, и запекайте на центральной решётке при 205 °C 25–30 минут, пока картофель не начнёт золотиться. Остудите 15 минут перед подачей.</li></ol><p><em>Дайте остыть 15 минут перед подачей и посыпьте петрушкой или шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('c4662028-2987-5c16-ae0a-6d567dceee5f', '3c96a25d-3159-550f-8ccb-c250e73e52d2', 'en', 'Shepherd''s pie with beef and Parmesan mashed potatoes', 'A casserole of ground meat and vegetables in a red wine gravy under a crown of creamy Parmesan mashed potatoes. Hearty for a crowd and great reheated the next day.', '<ol><li>Cut the potatoes into 1 inch pieces, cover with cold water, bring to a boil and cook 12-15 minutes until tender without overcooking. Drain and mash in the same pot.</li><li>Add the warm cream and ½ tsp salt and mash until smooth. Finally mash in the Parmesan and the beaten egg.</li><li>Preheat the oven to 205 °C (400 °F) with the rack in the center. Heat the oil in a large skillet over medium heat, add the ground meat, break it up, season with 1 tsp salt and ½ tsp pepper and cook about 5 minutes until no longer pink.</li><li>Add the onion and cook 3 minutes until soft, then the garlic for a minute. Sprinkle with the flour and stir 1 minute; a film forms on the bottom of the pan.</li><li>Pour in the wine, scraping up the bottom of the pan, and cook a minute. Add the broth, tomato paste and Worcestershire sauce.</li><li>Add the frozen vegetables and bring to a light boil. Season with another ½ tsp salt and ¼ tsp pepper, reduce to a simmer, cover and cook 10 minutes until the sauce thickens slightly.</li><li>Transfer the meat filling to a deep pie dish or an 11 × 7 or 9 × 9 inch casserole. Scoop the mashed potatoes on top and spread evenly, sealing to the edge of the dish so the filling does not bubble up. Drizzle with the melted butter.</li><li>Put a sheet of foil under the casserole to catch drips and bake on the center rack at 205 °C (400 °F) for 25-30 minutes until the potatoes start to turn golden. Cool 15 minutes before serving.</li></ol><p><em>Cool 15 minutes before serving and sprinkle with parsley or chives.</em></p>', CURRENT_TIMESTAMP),
  ('f81f4bfe-8a34-55fc-bdfd-a9eeb3935776', '3153dc17-4e6d-5f5d-9276-aa45a59308a2', 'ru', 'Паста со сливочным соусом, грибами и луком-пореем', 'Паста с нежным сливочным соусом из лука-порея, шампиньонов, чеснока и укропа. Порей даёт лёгкую сладость и приятную текстуру.', '<ol><li>Подготовьте порей: срежьте корешки и большую часть зелёных стеблей (их можно оставить для бульона). Разрежьте вдоль на четыре части, мелко нарежьте и промойте в холодной воде, чтобы смыть песок. Хорошо обсушите.</li><li>Сварите пасту в подсоленной воде по инструкции на упаковке, слейте воду.</li><li>В большой сковороде на среднем-сильном огне разогрейте масло и 2 минуты обжарьте порей.</li><li>Нарежьте грибы половинками или четвертинками, добавьте с чесноком к лук-порею и жарьте без крышки, часто помешивая, 8 минут до мягкости.</li><li>Влейте бульон и сливки, добавьте укроп, соль и перец и варите без крышки ещё 5 минут, пока соус немного не загустеет. Полейте им пасту и посыпьте пармезаном.</li></ol><p><em>Посыпьте тёртым пармезаном. Подойдёт любая паста, автор берёт тонкие спагетти.</em></p>', CURRENT_TIMESTAMP),
  ('67955527-d7ba-53b1-be6f-fe5af9edd2ea', '3153dc17-4e6d-5f5d-9276-aa45a59308a2', 'en', 'Creamy pasta with mushrooms and leeks', 'Pasta in a tender cream sauce with leeks, mushrooms, garlic and dill. The leeks add a mild sweetness and a pleasant texture.', '<ol><li>Prep the leeks: cut off the roots and most of the green tops (save them for stock). Halve lengthwise and halve again into long quarters, slice finely and rinse in cold water to remove dirt. Drain well.</li><li>Cook the pasta in salted water according to the package directions and drain.</li><li>Heat the oil in a large pan over medium-high heat and sauté the leeks for 2 minutes.</li><li>Halve or quarter the mushrooms, add them with the garlic to the leeks and sauté uncovered, stirring often, for 8 minutes until soft.</li><li>Pour in the broth and cream, add the dill, salt and pepper and simmer uncovered 5 more minutes until the sauce thickens a little. Pour over the pasta and sprinkle with Parmesan.</li></ol><p><em>Sprinkle with grated Parmesan. Any pasta works; angel hair is the author''s favorite.</em></p>', CURRENT_TIMESTAMP),
  ('5330f46e-5169-5b64-ad98-1ec1e9983fb3', 'a1c07e17-5c43-57b5-9464-3e7bae4fa6ad', 'ru', 'Суп с колбасками, кейлом и белой фасолью', 'Сытный суп в одной кастрюле: обжаренные колбаски, лук, морковь, помидор, белая фасоль и капуста кейл в курином бульоне. Колбаски заменяют мясные шарики и придают бульону вкус.', '<ol><li>Разогрейте в большой кастрюле с толстым дном масло на средне-сильном огне. Нарежьте колбаски кружками толщиной 1,3 см и обжаривайте 5 минут до золотистого цвета.</li><li>Добавьте нарезанный лук и обжарьте ещё 3 минуты. Добавьте морковь и помидор и готовьте 5 минут до мягкости.</li><li>Добавьте чеснок на минуту, пока не появится аромат, влейте бульон и доведите до кипения.</li><li>Добавьте фасоль и капусту кейл и варите около 5 минут, пока кейл не станет мягким. Посолите и поперчите по вкусу, снимите с огня и подавайте с пармезаном.</li></ol><p><em>Посыпьте пармезаном и подавайте с хрустящим хлебом. Порция около 400–500 мл.</em></p>', CURRENT_TIMESTAMP),
  ('73168f7a-ea74-53eb-8a35-5bcf6f990fc5', 'a1c07e17-5c43-57b5-9464-3e7bae4fa6ad', 'en', 'Sausage, kale and white bean soup', 'A hearty one-pot soup of browned sausages, onion, carrots, tomato, white beans and kale in chicken broth. The sausages act like easy meatballs and flavor the broth.', '<ol><li>Heat the olive oil in a large heavy-bottomed pot over medium-high heat. Slice the sausages into ½ inch rings and sauté 5 minutes until golden brown.</li><li>Add the chopped onion and sauté 3 more minutes. Add the carrots and tomato and cook 5 minutes until softened.</li><li>Add the garlic and stir for a minute until fragrant, then pour in the broth and bring to a boil.</li><li>Stir in the beans and kale and cook about 5 minutes until the kale is tender. Season with salt and pepper, remove from the heat and serve with Parmesan.</li></ol><p><em>Sprinkle with Parmesan and serve with crusty bread. A serving is about 1½-2 cups.</em></p>', CURRENT_TIMESTAMP),
  ('6220249d-0558-51ea-acf5-a2d4bad8d9a1', 'cdfaf0ec-493d-532e-ad97-7c36a606fead', 'ru', 'Драники с мясной начинкой', 'Золотистые хрустящие картофельные оладьи из тёртого картофеля и лука с прослойкой из мясного фарша.', '<ol><li>Натрите картофель и половину лука на самой мелкой тёрке или измельчите в комбайне до мелкой консистенции.</li><li>Ложкой снимите лишнюю жидкость, но не всю: масса не должна быть сухой. Добавьте яйцо, муку, сметану, соль и перец и перемешайте.</li><li>Для начинки натрите вторую половину лука в фарш, добавьте соль, перец, воду и любимые специи, перемешайте.</li><li>Разогрейте в антипригарной сковороде около ложки масла на среднем огне. Столовой ложкой выложите четыре оладьи.</li><li>Влажными руками сформируйте из 1–2 ст. л. фарша тонкую котлетку и положите на каждую оладью, затем накройте сверху картофельной массой.</li><li>Жарьте на среднем огне по 4–6 минут с каждой стороны до золотистого цвета и готовности мяса. Получится около 12 драников. Подавайте сразу.</li></ol><p><em>Подавайте горячими со сметаной, сливочным маслом или яблочным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('85f8c081-dace-5729-ad91-3a52c05da881', 'cdfaf0ec-493d-532e-ad97-7c36a606fead', 'en', 'Potato pancakes (draniki) with meat filling', 'Golden crisp pancakes of finely grated potato and onion with a layer of seasoned ground meat inside.', '<ol><li>Grate the potatoes and half of the onion on the finest holes of a box grater, or pulse in a food processor until fine.</li><li>Spoon off most of the excess liquid but not all of it, so the batter is not dry. Mix in the egg, flour, sour cream, salt and pepper.</li><li>For the filling, grate the remaining onion into the ground meat, add salt, pepper, water and any seasonings you like, and mix.</li><li>Heat about a tablespoon of oil in a nonstick skillet over medium heat and spoon out four pancakes.</li><li>With damp hands shape 1–2 tbsp of the meat into a thin patty and place it on each pancake, then cover with more potato batter.</li><li>Cook over medium heat for 4–6 minutes per side until golden and the meat is cooked. You will get about 12 pancakes. Serve right away.</li></ol><p><em>Serve hot with sour cream, butter or applesauce.</em></p>', CURRENT_TIMESTAMP),
  ('1462612a-5a4a-5f37-838b-0f3fe0d46edd', 'bc2f88d0-e9ad-5419-8aaa-d0acc2e61139', 'ru', 'Витаминный салат из капусты и овощей', 'Хрустящий салат из капусты, моркови, огурцов, перца, редиса, сельдерея и яблока с заправкой из масла и уксуса вместо майонеза.', '<ol><li>Нашинкуйте капусту, натрите морковь, нарежьте огурцы, перец и редис соломкой, сельдерей — тонкими ломтиками.</li><li>Яблоко нарежьте соломкой непосредственно перед подачей или опустите в воду с лимонным соком, если готовите заранее.</li><li>Смешайте овощи, посолите, поперчите, добавьте сахар. Добавьте зелень, масло и уксус и перемешайте.</li><li>Охладите и подавайте холодным или комнатной температуры.</li></ol><p><em>Яблоко режьте перед подачей, чтобы не потемнело.</em></p>', CURRENT_TIMESTAMP),
  ('fe2d6222-74f6-54fd-ae63-62148cdbabd6', 'bc2f88d0-e9ad-5419-8aaa-d0acc2e61139', 'en', 'Vitamin cabbage and vegetable salad', 'A crunchy salad of cabbage, carrot, cucumber, pepper, radish, celery and apple dressed with oil and vinegar instead of mayo.', '<ol><li>Shred the cabbage, grate the carrot, julienne the cucumbers, pepper and radishes, and thinly slice the celery.</li><li>Julienne the apple right before serving, or hold it in water with lemon juice if preparing ahead.</li><li>Combine the vegetables, season with salt, pepper and sugar, then add the herbs, oil and vinegar and toss.</li><li>Refrigerate and serve cold or at room temperature.</li></ol><p><em>Cut the apple just before serving so it does not darken.</em></p>', CURRENT_TIMESTAMP),
  ('fc4ee475-6be9-5c40-92f0-03d5b8637d98', '6c60cb2f-42a1-5ed0-880e-c3178fc342c1', 'ru', 'Гречневая каша с грибами и беконом', 'Рассыпчатая гречка, обжаренная с сушёными грибами, луком и хрустящим беконом.', '<ol><li>Обжарьте гречку на сухой сковороде на среднем огне до золотистого цвета.</li><li>Залейте сушёные грибы горячей водой и оставьте на 10 минут.</li><li>В кастрюле на среднем огне обжарьте нарезанный бекон до хруста, переложите на бумажное полотенце. Слейте жир, оставив 1 ст. л.</li><li>В том же жире под крышкой 5–8 минут тушите лук с солью до мягкости и лёгкой золотистости.</li><li>Отожмите, промойте и нарубите грибы. Добавьте к луку масло, грибы и гречку и обжаривайте 2–4 минуты, пока крупа не станет ароматной.</li><li>Влейте кипяток, посолите, доведите до кипения, убавьте огонь до минимума и варите около 30 минут до готовности крупы. Бекон добавьте в кашу вместе с водой или в конце.</li></ol><p><em>Добавьте кусочек сливочного масла в горячую кашу при подаче.</em></p>', CURRENT_TIMESTAMP),
  ('a9510693-a62a-5af5-9f5e-f8e6c56cd5b7', '6c60cb2f-42a1-5ed0-880e-c3178fc342c1', 'en', 'Buckwheat kasha with mushrooms and bacon', 'Fluffy toasted buckwheat cooked with dried mushrooms, onion and crispy bacon.', '<ol><li>Toast the buckwheat in a dry skillet over medium heat until golden brown.</li><li>Cover the dried mushrooms with hot water and let stand for about 10 minutes.</li><li>Cook the chopped bacon in a pot over medium heat until crispy and drain on a paper towel. Pour off the fat, leaving 1 tbsp.</li><li>In the same fat cook the onion with salt covered for 5–8 minutes until soft and beginning to brown.</li><li>Drain, rinse and chop the mushrooms. Add the butter, mushrooms and buckwheat to the onion and toast for 2–4 minutes until fragrant.</li><li>Pour in the boiling water, season with salt, bring to a boil, reduce to low and cook for about 30 minutes until the buckwheat is done. Add the bacon with the water or stir it in at the end.</li></ol><p><em>Add a pat of butter to the hot kasha when serving.</em></p>', CURRENT_TIMESTAMP),
  ('b25604c6-5ec3-58f5-a92d-964ea1871137', '0cc80072-fe5c-5641-b522-e15cf769075e', 'ru', 'Рыба с овощами, запечённая в пергаменте', 'Филе рыбы на подушке из тонкой соломки кабачка, моркови, сельдерея и перца запекается в пергаментных пакетиках с лимоном и сливочным маслом.', '<ol><li>Разогрейте духовку до 200 °C. Нарежьте все овощи тонкой соломкой или натрите.</li><li>Приправьте рыбу цедрой половины лимона, 2 ст. л. оливкового масла, половиной зелени, 1–2 зубчиками чеснока, солью и перцем.</li><li>Овощи посолите, поперчите и смешайте с оставшимся чесноком, 2 ст. л. масла, остатками цедры, 1 ст. л. лимонного сока и оставшейся зеленью.</li><li>На каждый кусок пергамента выложите четверть овощей, сверху — филе, затем кусочек сливочного масла. Заверните края плотными складками (или зашейте пакет степлером), чтобы получился герметичный пакетик. Так сделайте четыре пакета.</li><li>Выложите пакеты на противень и запекайте 10–15 минут (15–18 минут для больших кусков или толстой нарезки).</li><li>Вскройте пакеты и подавайте, сбрызнув рыбу свежим лимонным соком.</li></ol><p><em>Каждый гость раскрывает свой пакетик за столом и поливает рыбу лимонным соком.</em></p>', CURRENT_TIMESTAMP),
  ('f4b2f28b-1e70-5459-be44-0ee07057de33', '0cc80072-fe5c-5641-b522-e15cf769075e', 'en', 'Fish and vegetables en papillote', 'Fish fillets on a bed of thin zucchini, carrot, celery and pepper matchsticks baked in parchment packets with lemon and butter.', '<ol><li>Preheat the oven to 200 °C. Cut all the vegetables into thin matchsticks or grate them.</li><li>Season the fish with the zest of half a lemon, 2 tbsp olive oil, half of the herbs, 1–2 cloves of garlic, salt and pepper.</li><li>Season the vegetables with salt and pepper and mix with the remaining garlic, 2 tbsp oil, the remaining zest, 1 tbsp lemon juice and the rest of the herbs.</li><li>On each sheet of parchment place a quarter of the vegetables, a fish fillet and a pat of butter. Fold the edges into tight pleats (or staple the bag shut) for a tight seal. Make four packets.</li><li>Place the packets on a rimmed baking sheet and bake for 10–15 minutes (15–18 for larger fillets or thicker cuts).</li><li>Open the packets and serve, squeezing fresh lemon juice over the fish.</li></ol><p><em>Let each guest open their packet at the table and squeeze lemon over the fish.</em></p>', CURRENT_TIMESTAMP),
  ('f83e1bc3-b9da-56ef-a551-5b554da04cce', 'd83f5759-0fa0-5f6b-a59a-eec33739ac5b', 'ru', 'Куриные котлеты с грибной начинкой', 'Сочные овальные котлеты из куриного фарша с начинкой из шампиньонов и белых сушёных грибов, обжаренные на сковороде.', '<ol><li>Сначала сделайте начинку, чтобы она успела остыть. Залейте сушёные грибы кипятком и оставьте размокать.</li><li>Мелко нарубьте свежие грибы и шалот. Отожмите размоченные грибы, тщательно промойте и мелко нарубьте.</li><li>Разогрейте на сковороде масло, добавьте все грибы и шалот, посолите, поперчите и приправьте. Готовьте на среднем огне, пока грибы не станут мягкими, а вся жидкость не выпарится. Остудите.</li><li>Залейте панировочные сухари молоком до размягчения. Натрите лук на средней тёрке.</li><li>В большой миске смешайте куриный фарш, размоченные сухари, лук, яйцо, сметану, соль, перец и сушёные приправы до однородности.</li><li>Смачивая руки, возьмите порцию фарша, сформируйте шарик и сделайте в центре углубление, положите туда полную столовую ложку грибов, закройте фаршем и придайте овальную форму. Получится 14–16 котлет.</li><li>Разогрейте масло в антипригарной сковороде на среднем огне и жарьте котлеты порциями под крышкой примерно по 5 минут с каждой стороны до золотистого цвета.</li></ol><p><em>Подавайте с картофельным пюре или гречкой и сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('0680df11-b825-5c88-adcb-3756f766faf6', 'd83f5759-0fa0-5f6b-a59a-eec33739ac5b', 'en', 'Chicken kotleti with mushroom filling', 'Juicy oval chicken patties stuffed with a filling of fresh button and dried porcini mushrooms, pan-fried until golden.', '<ol><li>Make the filling first so it can cool. Pour boiling water over the dried mushrooms to rehydrate them.</li><li>Finely chop the fresh mushrooms and the shallot. Drain the rehydrated mushrooms, wash well and chop finely.</li><li>Heat the butter in a large skillet, add all the mushrooms and the shallot, season with salt, pepper and herbs. Cook over medium heat until soft and all the liquid has cooked off. Let cool.</li><li>Pour the milk over the breadcrumbs until softened. Grate the onion on the medium holes of a grater.</li><li>In a large bowl combine the ground chicken, soaked breadcrumbs, onion, egg, sour cream, salt, pepper and dry seasonings until evenly mixed.</li><li>With damp hands take a portion of meat, shape it into a ball and make a dent in the centre, add a heaping tablespoon of mushroom filling, cover with more meat and shape into an oval. You will get 14–16 patties.</li><li>Heat oil in a nonstick skillet over medium heat and cook the patties in batches, covered, about 5 minutes per side until golden.</li></ol><p><em>Serve with mashed potatoes or buckwheat and sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('755e2de9-67d9-5de5-bf28-3b5b70aa13ab', '9b320724-925c-5abd-9f70-82850e2c314b', 'ru', 'Маринованный салат из огурцов с укропом и красным луком', 'Тонко нарезанные огурцы и красный лук, выдержанные 20 минут в заправке из винного уксуса, мёда и соли, с большим количеством укропа. Лёгкая закуска к мясу и рыбе.', '<ol><li>В миске смешайте винный уксус, мёд и соль. Добавьте тонко нарезанные огурец и лук, перемешайте и оставьте на 20 минут, чтобы они слегка промариновались и отдали сок.</li><li>Слейте лишнюю жидкость и перемешайте с рубленым укропом. Подавайте с чёрным перцем и укропом сверху.</li></ol><p><em>Подавайте с чёрным молотым перцем и свежим укропом, как гарнир к жареному мясу или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('0a6117bc-d409-5838-8b03-dc208c011508', '9b320724-925c-5abd-9f70-82850e2c314b', 'en', 'Quick-pickled cucumber salad with dill and red onion', 'Thinly sliced cucumber and red onion left for 20 minutes in a wine vinegar, honey and salt dressing, with plenty of dill. A light side for meat and fish.', '<ol><li>Whisk the vinegar, honey and salt together in a bowl. Add the finely sliced cucumber and onion and toss to coat. Leave for 20 minutes to pickle lightly and release liquid.</li><li>Drain off any liquid and toss through the dill. Serve with black pepper and extra dill on top.</li></ol><p><em>Serve with black pepper and extra dill alongside grilled meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('9d46ee8b-72dc-57bb-b9fd-c849134b5a7e', 'ff730c15-32c4-5764-8d04-c4d249cf28cc', 'ru', 'Хрустящая рыба в рисовой бумаге с пятью специями', 'Кусочки белой рыбы, приправленные китайской смесью пяти специй, заворачивают в рисовую бумагу с листиками кинзы и обжаривают до хрустящей золотистой корочки. Минимум ингредиентов.', '<ol><li>Нарежьте рыбу брусочками примерно 5 × 3 см, получится около 16 кусочков.</li><li>Смешайте китайскую смесь пяти специй, соль и перец и посыпьте этой смесью рыбу.</li><li>Налейте в большую миску горячую воду из-под крана. Опустите лист рисовой бумаги в воду на 3 секунды и положите на рабочую поверхность.</li><li>Положите кусочек рыбы у нижнего края листа, сверху два листика кинзы и плотно заверните рыбу в бумагу. Повторите с остальной рыбой.</li><li>Разогрейте масло в сковороде на средне-сильном огне. Жарьте рулетики по 2 минуты с каждой стороны до тёмно-золотистой хрустящей корочки (в 2 захода). Выложите на бумажное полотенце и сразу подавайте.</li></ol><p><em>Подавайте сразу, пока горячие и хрустящие.</em></p>', CURRENT_TIMESTAMP),
  ('e7782b7b-f925-5980-b3a9-11535afaca0e', 'ff730c15-32c4-5764-8d04-c4d249cf28cc', 'en', 'Crispy rice paper wrapped fish with five spice', 'Pieces of firm white fish seasoned with Chinese five spice, wrapped in rice paper with coriander leaves and fried until crisp and golden. Only a handful of ingredients.', '<ol><li>Cut the fish into pieces about 2 inch (5 cm) long and 1 inch (3 cm) wide, about 16 pieces.</li><li>Mix the Chinese five spice, salt and pepper and sprinkle over the fish.</li><li>Fill a large bowl with hot tap water. Dunk a rice paper sheet in the water for 3 seconds and lay it on a work surface.</li><li>Place a piece of fish at the bottom of the sheet, top with 2 coriander leaves and roll up tightly to enclose the fish. Repeat with the rest.</li><li>Heat the oil in a skillet over medium-high heat. Fry the wrapped fish 2 minutes per side until dark golden and crispy (in 2 batches). Drain on a paper towel and serve at once.</li></ol><p><em>Serve immediately while hot and crispy.</em></p>', CURRENT_TIMESTAMP),
  ('3e6d41f5-b04f-52a5-aafc-1600906b2380', '8435446e-43cb-5a6e-9c9c-6ba1871c49a4', 'ru', 'Говяжья грудинка в мультиварке с грибами и луком', 'Грудинка, обжаренная и томлёная 7–8 часов с карамелизованным луком, грибами, чесноком и вустерским соусом, пока не начнёт распадаться на волокна. Подаётся с пюре или в бутербродах.', '<ol><li>Щедро посолите и поперчите грудинку. В большой тяжёлой сковороде разогрейте на сильном огне 1 ст. л. масла, выложите мясо жиром вниз и обжарьте по 4–5 минут с каждой стороны до румяной корочки. Переложите в мультиварку жиром вверх.</li><li>В той же сковороде обжарьте лук с 1 ст. л. масла 5–7 минут до карамелизации и выложите на мясо. Затем добавьте масла и обжарьте грибы 5 минут до мягкости, выложите в мультиварку и посыпьте нарезанным чесноком.</li><li>Смешайте бульон с вустерским соусом и залейте мясо.</li><li>Накройте крышкой и готовьте на слабом режиме 7–8 часов, пока мясо не станет мягким и не начнёт легко распадаться вилкой. Выключите и дайте постоять 15 минут под крышкой. Снимите лишний жир сверху, разберите мясо вилками на волокна и оставьте в соку, чтобы оно пропиталось. Подавайте с грибами, поливая соком.</li></ol><p><em>Подавайте с картофельным пюре, поливая соком из чаши, или в булочках.</em></p>', CURRENT_TIMESTAMP),
  ('ad34bccc-811d-5b4a-bd54-9f4d4b0a161e', '8435446e-43cb-5a6e-9c9c-6ba1871c49a4', 'en', 'Slow cooker beef brisket with mushrooms and onions', 'Brisket seared and slow-cooked for 7-8 hours with caramelized onions, mushrooms, garlic and Worcestershire sauce until it pulls apart. Serve with mashed potatoes or in sandwiches.', '<ol><li>Generously season the brisket with the salt and pepper. Heat 1 tbsp oil in a large heavy skillet or cast-iron pan over high heat and sear the brisket fat-side down 4-5 minutes per side until browned. Transfer to the slow cooker, fat side up.</li><li>In the same pan sauté the onions with 1 tbsp oil for 5-7 minutes until caramelized and place over the brisket. Add more oil and sauté the mushrooms 5 minutes until soft, put them in the slow cooker and sprinkle with the chopped garlic.</li><li>Combine the broth with the Worcestershire sauce and pour over the meat.</li><li>Cover and cook on low 7-8 hours until the beef is cooked through and easy to pull apart with forks. Turn off and rest 15 minutes with the lid on. Skim off excess fat from the top, pull the beef apart with forks and keep it in the juices so it stays tender. Serve with the mushrooms, spooning the juices over.</li></ol><p><em>Serve with mashed potatoes, spooning the cooking juices over, or in buns.</em></p>', CURRENT_TIMESTAMP),
  ('c5cfa819-3597-511c-b57a-95ea422289cb', '1c7eb450-240d-59c4-a423-18eb35c61c55', 'ru', 'Тушёная курица с картошкой в мультиварке-скороварке', 'Куриные бёдра с луком, морковью, чесноком и картофелем, приготовленные целиком в одном приборе под давлением.', '<ol><li>Нарежьте курицу кусками около 4 см, картофель — кусками 4–5 см. Приправьте то и другое солью, перцем и сушёными травами. Лук нарубите, морковь нарежьте соломкой, чеснок измельчите.</li><li>Включите режим «Жарка» на максимум, разогрейте масло и обжарьте курицу в 2–3 захода до золотистого цвета с двух сторон. Мясо внутри ещё сырое. Отложите.</li><li>Добавьте лук, посолите и поперчите, соскребите всё со дна и готовьте 3–5 минут до мягкости. Освободите центр, добавьте чеснок на минуту, затем морковь.</li><li>Верните курицу в чашу, сверху, не перемешивая, выложите картофель, добавьте лавровый лист и влейте горячую воду или бульон (холодная вода значительно удлинит набор давления).</li><li>Закройте крышку, установите клапан в положение «Закрыто» и готовьте 6 минут на высоком давлении.</li><li>Сразу же сбросьте давление вручную: если оставить на естественный сброс, картофель разварится. Посыпьте свежей зеленью и подавайте.</li></ol><p><em>Подавайте горячим со свежей зеленью и солёными огурцами.</em></p>', CURRENT_TIMESTAMP),
  ('df5b476c-06d6-565f-804c-f0c9cb9fa002', '1c7eb450-240d-59c4-a423-18eb35c61c55', 'en', 'Braised chicken and potatoes in the pressure cooker', 'Chicken thighs with onion, carrots, garlic and potatoes cooked entirely in one electric pressure cooker.', '<ol><li>Cut the chicken into 4 cm pieces and the potatoes into 4–5 cm pieces and season both with salt, pepper and dried herbs. Chop the onion, julienne the carrots and mince the garlic.</li><li>Switch the cooker to the highest Saute setting, heat the oil and brown the chicken in 2–3 batches until golden on both sides. It will not be cooked through. Set aside.</li><li>Add the onion with salt and pepper, scrape up the browned bits and cook for 3–5 minutes until soft. Clear a space in the centre, add the garlic for a minute, then the carrots.</li><li>Return the chicken to the pot, lay the potatoes on top without stirring, add the bay leaves and pour in hot water or broth (cold water would make it take much longer to reach pressure).</li><li>Close the lid, set the valve to Sealing and cook at high pressure for 6 minutes.</li><li>Quick-release the pressure right away; natural release will make the potatoes mushy. Garnish with fresh herbs and serve.</li></ol><p><em>Serve hot with fresh herbs and pickles.</em></p>', CURRENT_TIMESTAMP),
  ('b52017af-dc6c-5b3b-aaf6-afe25b4478f3', '759c639c-0820-55dc-bfab-2ff9a69ced0e', 'ru', 'Куриные фрикадельки, запечённые под сыром', 'Сочные куриные фрикадельки, запечённые в духовке с каплей майонеза и золотистой сырной шапочкой.', '<ol><li>Разогрейте духовку до 220 °C и застелите противень пергаментом. Лук натрите на мелкой тёрке, панировочные сухари залейте молоком.</li><li>Смешайте куриный фарш, лук, размоченные сухари, сметану, яйцо, соль, перец, чесночный порошок и сушёные травы до однородности.</li><li>Сформируйте около 30 фрикаделек по 1,5 ст. л. и разложите на противне на расстоянии 1–2 см.</li><li>Выдавите на каждую каплю майонеза из пакета с проколотым уголком и посыпьте тёртым сыром.</li><li>Запекайте без крышки около 10 минут, затем включите гриль (230 °C) и запекайте ещё 3–5 минут, пока сыр не станет золотистым и пузырящимся. Подавайте тёплыми.</li></ol><p><em>Подавайте с картофельным пюре, макаронами или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('7f68439b-3a36-5887-a9c8-33e67744acd3', '759c639c-0820-55dc-bfab-2ff9a69ced0e', 'en', 'Baked cheesy chicken meatballs', 'Juicy chicken meatballs baked in the oven with a dot of mayonnaise and a golden cheese topping.', '<ol><li>Preheat the oven to 220 °C and line a baking sheet with parchment. Grate the onion on the fine holes and pour the milk over the breadcrumbs.</li><li>Mix the ground chicken, onion, soaked breadcrumbs, sour cream, egg, salt, pepper, garlic powder and dry herbs until evenly combined.</li><li>Shape about 30 meatballs of 1.5 tbsp each and set them 1–2 cm apart on the baking sheet.</li><li>Pipe a small dot of mayonnaise from a bag with a tiny cut corner onto each meatball and top with grated cheese.</li><li>Bake uncovered for about 10 minutes, then switch on the broiler (230 °C) and bake for another 3–5 minutes until the cheese is bubbling and golden. Serve warm.</li></ol><p><em>Serve with mashed potatoes, pasta or a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('6de32fcd-b9dd-5e85-84e6-67f22f37db11', '8cd6acd2-4b32-5cf6-8af1-ca9cec9dd03d', 'ru', 'Куриные оладьи с картофелем', 'Золотистые оладьи из мелко нарубленной курицы, тёртого картофеля и лука на яичном тесте.', '<ol><li>Очень мелко нарубите курицу, переложите в большую миску. Добавьте взбитые яйца, майонез, крахмал, соль, перец, чесночный и луковый порошок и сушёные травы, перемешайте.</li><li>Картофель натрите тонкой соломкой на средней тёрке, лук мелко нарубите. Добавьте в смесь и тщательно перемешайте.</li><li>Разогрейте масло в сковороде, затем убавьте огонь до средне-слабого. Столовой ложкой выкладывайте массу в виде круглых или овальных оладий.</li><li>Жарьте под крышкой 3–5 минут с одной стороны, переверните и жарьте ещё 2–3 минуты до золотистого цвета. Так приготовьте всё порциями (получится около 30 оладий).</li></ol><p><em>Подавайте тёплыми со сметаной и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('9057003e-0111-5c22-9893-559aa60fb289', '8cd6acd2-4b32-5cf6-8af1-ca9cec9dd03d', 'en', 'Chicken and potato fritters', 'Golden fritters of finely chopped chicken, grated potato and minced onion in an egg batter.', '<ol><li>Chop the chicken very finely and place in a large bowl. Add the beaten eggs, mayonnaise, cornstarch, salt, pepper, garlic and onion powder and dry herbs and mix.</li><li>Grate the potato into fine shreds on the medium holes and mince the onion. Add to the chicken batter and mix until evenly incorporated.</li><li>Heat oil in a skillet until shimmering, then reduce to medium-low. Spoon the batter into round or oval fritters.</li><li>Cook covered for 3–5 minutes on the first side, flip and cook 2–3 minutes more until golden. Continue in batches (about 30 fritters).</li></ol><p><em>Serve warm with sour cream and herbs.</em></p>', CURRENT_TIMESTAMP),
  ('ff83606f-14ec-556e-aa6c-57de88d3d6ae', 'ec9ec412-0519-585d-89a1-718353aff5ac', 'ru', 'Салат из брокколи и цветной капусты с помидорами и огурцами', 'Хрустящий салат из сырых соцветий брокколи и цветной капусты, помидоров черри и огурцов со сметанно-майонезной заправкой и зеленью.', '<ol><li>Разделите брокколи и цветную капусту на небольшие соцветия.</li><li>Помидоры разрежьте пополам, огурцы нарежьте тонкими половинками или четвертинками кружков, зелень измельчите. Сложите овощи в большую миску.</li><li>Смешайте майонез и сметану до гладкости, посолите и поперчите.</li><li>Заправьте овощи, сначала добавив 1/2–3/4 соуса, затем при необходимости остальное. Подавайте сразу или храните в холодильнике.</li></ol><p><em>Перемешайте перед подачей; на следующий день добавьте немного заправки.</em></p>', CURRENT_TIMESTAMP),
  ('0b8686f5-e726-5b47-b1e1-fa421a0d1f8a', 'ec9ec412-0519-585d-89a1-718353aff5ac', 'en', 'Broccoli and cauliflower salad with tomatoes and cucumbers', 'A crunchy salad of raw broccoli and cauliflower florets, cherry tomatoes and cucumbers in a creamy sour cream and mayonnaise dressing with herbs.', '<ol><li>Cut the broccoli and cauliflower into bite-sized florets.</li><li>Halve the tomatoes, slice the cucumbers into thin half or quarter rounds and chop the herbs. Put all the vegetables in a large bowl.</li><li>Stir the mayonnaise and sour cream together until smooth and season with salt and pepper.</li><li>Toss the vegetables with the dressing, starting with 1/2–3/4 and adding the rest if needed. Serve right away or refrigerate.</li></ol><p><em>Mix well before serving; add a little more dressing the next day.</em></p>', CURRENT_TIMESTAMP),
  ('45f5734b-b8ed-5b17-87dd-bd2fcebc2d9e', 'f4033b94-387c-5449-9994-0b9e7f0465b4', 'ru', 'Кускус с кабачком', 'Рассыпчатый кускус с мягким кабачком, луком, чесноком и зеленью, приготовленный на курином бульоне.', '<ol><li>Доведите куриный бульон до кипения в небольшой кастрюле и держите горячим.</li><li>В глубокой сковороде растопите 1,5 ст. л. масла на среднем огне, 5 минут обжарьте лук и чеснок с солью и перцем до мягкости.</li><li>Добавьте мелко нарезанный кабачок, посолите и поперчите, готовьте ещё 3 минуты.</li><li>Влейте вино (по желанию) и проварите минуту, всыпьте кускус и 3 минуты обжаривайте, часто помешивая.</li><li>Влейте горячий бульон, доведите до кипения и сразу снимите с огня. Накройте крышкой и оставьте на 5 минут.</li><li>Добавьте оставшиеся 1,5 ст. л. масла и зелень, разрыхлите кускус вилкой.</li></ol><p><em>Хорошо сочетается с курицей, рыбой или запечёнными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('9d41f74b-5d3e-59d1-b568-9a1bdbae7371', 'f4033b94-387c-5449-9994-0b9e7f0465b4', 'en', 'Zucchini couscous', 'Fluffy couscous with tender zucchini, onion, garlic and fresh herbs cooked in chicken broth.', '<ol><li>Bring the chicken broth to a boil in a small saucepan and keep it hot.</li><li>Melt 1.5 tbsp butter in a deep skillet over medium heat and cook the onion and garlic with salt and pepper for about 5 minutes until soft.</li><li>Add the finely chopped zucchini, season, and cook for another 3 minutes.</li><li>Pour in the wine (optional) and simmer for a minute, then add the couscous and toast, stirring frequently, for about 3 minutes.</li><li>Pour in the hot broth, bring to a boil, and immediately remove from the heat. Cover and let stand for 5 minutes.</li><li>Add the remaining 1.5 tbsp butter and the herbs and fluff the couscous with a fork.</li></ol><p><em>Great with chicken, seafood or roasted vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('9de9323e-4f4f-54c3-81ea-01191e57ee13', '238ce143-33ec-54ef-a6ba-e2703e446a9a', 'ru', 'Жареный рис с яйцом, беконом и овощами', 'Быстрый рис по-китайски: вчерашний варёный рис обжаривают с беконом, овощами и яйцом на сильном огне и заправляют устричным и соевым соусом.', '<ol><li>В воке разогрейте 1½ ст. л. масла (или 2 ст. л. в сковороде) на сильном огне до лёгкого дымка.</li><li>Добавьте лук, чеснок и бекон и обжаривайте около 1,5 минут до светло-золотистого цвета бекона.</li><li>Добавьте овощи (можно прямо из морозилки) и готовьте 2 минуты, пока они не разморозятся и вода не испарится.</li><li>Добавьте рис и соусные ингредиенты (вино, устричный и соевый соусы, кунжутное масло, белый перец) и готовьте около 1,5 минут, пока жидкость не испарится.</li><li>Сдвиньте рис в сторону, на освободившееся место добавьте ½ ст. л. масла и влейте взбитые яйца. Хорошо прожарьте, помешивая, не оставляйте их полужидкими.</li><li>Добавьте зелёный лук, перемешайте яйцо с рисом, снимите с огня и сразу подавайте.</li></ol><p><em>Подавайте сразу из вока или сковороды, как основное блюдо или гарнир к китайским блюдам.</em></p>', CURRENT_TIMESTAMP),
  ('3137bc72-57fa-5c08-b756-bb744f14f071', '238ce143-33ec-54ef-a6ba-e2703e446a9a', 'en', 'Egg fried rice with bacon and vegetables', 'A quick Chinese-style fried rice: day-old cooked rice stir-fried over high heat with bacon, vegetables and egg and seasoned with oyster and soy sauce.', '<ol><li>Heat about 1½ tbsp oil in a wok (or 2 tbsp in a skillet) over high heat until smoking.</li><li>Add the onion, garlic and bacon and cook about 1½ minutes until the bacon is light golden.</li><li>Add the vegetables (still frozen is fine) and cook 2 minutes until they defrost and the water evaporates.</li><li>Add the rice and the sauce ingredients (wine, oyster and soy sauce, sesame oil, white pepper) and cook about 1½ minutes until the liquid evaporates.</li><li>Push the rice to the side, add ½ tbsp oil into the cleared space and pour in the beaten eggs. Scramble until fully cooked, not soft-scrambled.</li><li>Add the green onion, stir the egg into the rice, remove from the heat and serve immediately.</li></ol><p><em>Serve right away from the wok or skillet, as a main or alongside Chinese dishes.</em></p>', CURRENT_TIMESTAMP),
  ('577f6a1c-b37a-5fa2-b021-24d51b55045b', 'dca730bd-6584-583d-bd4b-adde8dc52770', 'ru', 'Куриное карри с кокосовым молоком и горошком', 'Простое мягкое карри в западном стиле: куриные бёдра в соусе из кокосового молока, бульона и порошка карри с имбирём и чесноком. Не острое.', '<ol><li>В сковороде разогрейте масло на средне-сильном огне. Обжаривайте чеснок, имбирь и лук 3 минуты, пока лук не станет прозрачным.</li><li>Добавьте нарезанную курицу и готовьте, пока она не поменяет цвет с розового на белый.</li><li>Добавьте порошок карри и готовьте 2 минуты.</li><li>Влейте кокосовое молоко и бульон, перемешайте, убавьте огонь до среднего и варите на активном кипении 10 минут, пока соус не уменьшится и не загустеет.</li><li>Добавьте горошек и соль, готовьте ещё 2 минуты, проверьте вкус и при необходимости досолите. Посыпьте кинзой.</li></ol><p><em>Подавайте с рисом, лапшой или картофельным пюре, посыпав кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('f9140794-6599-52a5-87ea-dc0be4570d15', 'dca730bd-6584-583d-bd4b-adde8dc52770', 'en', 'Easy chicken curry with coconut milk and peas', 'A simple mild Western-style curry: chicken thighs in a sauce of coconut milk, stock and curry powder with ginger and garlic. Not spicy.', '<ol><li>Heat the oil in a skillet over medium-high heat. Cook the garlic, ginger and onion for 3 minutes until the onion is translucent.</li><li>Add the sliced chicken and cook until it changes from pink to white.</li><li>Add the curry powder and cook for 2 minutes.</li><li>Add the coconut milk and stock, stir, lower the heat to medium and simmer rapidly for 10 minutes until the sauce reduces and thickens.</li><li>Add the peas and salt and cook 2 more minutes, then taste and add more salt if needed. Garnish with cilantro.</li></ol><p><em>Serve over rice, noodles or mashed potato, topped with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('715d2312-fe10-5ecd-b4c1-ab928fed0043', 'febda62d-81a4-521e-bda3-f5e2508bc481', 'ru', 'Шведские фрикадельки в сливочном соусе', 'Сочные фрикадельки из говяжьего и свиного фарша с хлебом, размоченным в луковом соке, и пряностями (мускат, душистый перец) в нежном сливочном соусе на основе бульона.', '<ol><li>Натрите лук на крупной тёрке. Переложите лук с соком в миску, добавьте хлеб без корки, нарезанный мелкими кубиками, и перемешайте, чтобы хлеб пропитался. Если нужно, добавьте капельку молока. Оставьте на 1 минуту.</li><li>Добавьте оба вида фарша, яйцо, мускатный орех, душистый перец, чёрный перец и соль, хорошо перемешайте.</li><li>Скатайте 25–30 шариков, отмеряя порции столовой ложкой с горкой или ложкой для мороженого.</li><li>В сковороде на средне-сильном огне разогрейте масло. Обжарьте половину фрикаделек со всех сторон (внутри они останутся сырыми), около 3 минут. Переложите на тарелку, затем обжарьте остальные. Слейте излишки масла и убавьте огонь до среднего.</li><li>Для соуса растопите в той же сковороде масло, всыпьте муку и перемешайте, готовьте 1 минуту. Постепенно добавьте бульон: сначала около четверти (соус быстро загустеет), затем остальное, помешивая, при необходимости венчиком, чтобы не было комков.</li><li>Когда соус закипит, верните фрикадельки вместе с соком с тарелки. Сделайте огонь чуть сильнее и варите на активном кипении 8–10 минут, пока соус не загустеет до жидкой подливки, иногда помешивая.</li><li>Влейте сливки, варите ещё 2 минуты и снимите с плиты. Подавайте на картофельном пюре.</li></ol><p><em>Подавайте на картофельном пюре, для аутентичности добавьте брусничный джем.</em></p>', CURRENT_TIMESTAMP),
  ('d3bc99ea-9d06-5992-a173-b2cfe028619d', 'febda62d-81a4-521e-bda3-f5e2508bc481', 'en', 'Swedish meatballs in cream gravy', 'Juicy beef and pork meatballs with bread soaked in onion juice and warm spices (nutmeg, allspice) in a creamy broth gravy.', '<ol><li>Grate the onion on a box grater. Scrape the onion and juices into a bowl, add the crustless bread cut into small cubes and mix so the bread gets soggy (add a tiny splash of milk if needed). Set aside for 1 minute.</li><li>Add the ground beef and pork, egg, nutmeg, allspice, black pepper and salt and mix well.</li><li>Roll 25-30 meatballs, portioning with a heaped tablespoon or an ice cream scoop.</li><li>Heat the oil in a skillet over medium-high heat. Brown half the meatballs all over (still raw inside), about 3 minutes. Move to a plate, then brown the rest. Pour off excess oil and lower the heat to medium.</li><li>For the gravy, melt the butter in the same skillet, stir in the flour and cook 1 minute. Add about ¼ of the broth first (it thickens quickly), then gradually the rest, stirring, switching to a whisk if needed to keep it lump-free.</li><li>When the liquid simmers, add the meatballs and the juices from the plate. Turn the heat up slightly to keep a rapid simmer and cook 8-10 minutes until the gravy thickens thinly, stirring occasionally.</li><li>Add the cream, simmer 2 more minutes and remove from the heat. Serve over mashed potato.</li></ol><p><em>Serve over mashed potato, and add a spoon of lingonberry jam for the authentic touch.</em></p>', CURRENT_TIMESTAMP),
  ('0f03bc24-0544-597d-9258-471a1580bdb1', '83803682-898a-5af5-993f-541e69ca7195', 'ru', 'Испанская тортилья с картофелем и луком', 'Плотный омлет из яиц, картофеля и лука. Картофель томят в оливковом масле до нежности, как конфи. Подаётся тёплым или комнатной температуры, в том числе как тапас.', '<ol><li>Разогрейте масло в антипригарной сковороде на среднем огне. Добавьте лук и картофель и перемешайте. Накройте крышкой и томите около 20 минут, 3–4 раза переворачивая лопаткой, пока картофель не станет мягким. Если он шипит и румянится, убавьте огонь.</li><li>Тем временем взбейте яйца, посолите и поперчите.</li><li>Выньте картофель шумовкой в дуршлаг, чтобы стекло лишнее масло. Слейте из сковороды почти всё масло, оставив 1½–2 ст. л.</li><li>Сделайте огонь средне-сильным. Верните картофель в сковороду, залейте яйцами и готовьте 5 минут, пока низ не станет светло-золотистым.</li><li>Если середина ещё жидкая (так обычно и бывает), поставьте тортилью на пару минут под гриль духовки, пока середина не схватится, либо аккуратно переверните её с помощью тарелки и обжарьте вторую сторону. Дайте постоять несколько минут, переверните на блюдо и подавайте тёплой или комнатной температуры.</li></ol><p><em>Подавайте тёплой или комнатной температуры, нарезав клиньями, с салатом или хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('5447a4cb-3151-5da9-8049-3e9ae0274d36', '83803682-898a-5af5-993f-541e69ca7195', 'en', 'Spanish tortilla with potato and onion', 'A thick omelette of eggs, potato and onion where the potato is gently stewed in olive oil until creamy, almost confit. Served warm or at room temperature, including as tapas.', '<ol><li>Heat the oil in a non-stick pan over medium heat. Add the onion and potatoes and turn to coat. Cover and stew gently about 20 minutes, turning 3-4 times with a spatula, until soft and cooked through. If the potatoes sizzle and brown, turn the heat down.</li><li>Meanwhile whisk the eggs and season with salt and pepper.</li><li>Lift the potatoes with a slotted spoon into a colander so the excess oil drains. Pour most of the oil out of the pan, leaving 1½-2 tbsp.</li><li>Turn the heat to medium-high. Return the potatoes to the pan, pour over the eggs and cook 5 minutes until the underside is light golden.</li><li>If the centre is still runny (as it usually is), put the omelette under the broiler for a couple of minutes until just set, or flip it with a plate and cook the other side. Rest a few minutes, turn out onto a platter and serve warm or at room temperature.</li></ol><p><em>Serve warm or at room temperature, cut into wedges, with a salad or bread.</em></p>', CURRENT_TIMESTAMP),
  ('dea21b0f-46a4-5523-9073-3b702ab03466', 'd97e1003-cfa7-5121-a611-42bb62aab212', 'ru', 'Свиные отбивные в духовке с картофелем и глазурью', 'Свиные отбивные, обмазанные пикантной сладко-солёной смесью из кетчупа, соевого и вустерского соусов, сахара и чеснока, запекают на одном противне с картофелем до золотистой карамельной корочки.', '<ol><li>Разогрейте духовку до 220 °C (200 °C с конвекцией).</li><li>Перемешайте картофель с 1 ст. л. масла, посолите, поперчите и разложите на противне. Поставьте в духовку на 15 минут, чтобы он начал готовиться раньше мяса.</li><li>Тем временем смешайте в миске все ингредиенты для обмазки: вустерский соус, кетчуп, соевый соус, сахар, 1 ст. л. масла, чеснок и яблочный уксус.</li><li>Щедро смажьте отбивные с обеих сторон, оставив немного обмазки для поливки. Достаньте противень, перемешайте картофель и сдвиньте к краю, положите свинину. Запекайте 15 минут.</li><li>Включите гриль на максимум (противень на расстоянии около 20 см от нагревателя). Переверните мясо, полейте оставшейся обмазкой и запекайте под грилем 7–10 минут до хорошей карамелизации.</li><li>Достаньте противень, кисточкой соберите золотистый сок с противня и смажьте им мясо (это важно для вкуса и цвета) и на пару минут верните под гриль. Подавайте, полив соком с противня.</li></ol><p><em>Полейте мясо соком с противня и посыпьте петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('279679f9-5130-5a0b-ae72-9ea4a147c202', 'd97e1003-cfa7-5121-a611-42bb62aab212', 'en', 'Oven baked pork chops with potatoes and sticky glaze', 'Pork chops slathered with a savoury, slightly sweet rub of ketchup, soy and Worcestershire sauce, sugar and garlic, baked on one tray with potatoes until golden and caramelised.', '<ol><li>Preheat the oven to 220 °C (200 °C fan-forced).</li><li>Toss the potatoes with 1 tbsp oil, season with salt and pepper and scatter on a baking tray. Bake for 15 minutes to give them a head start.</li><li>Meanwhile mix the rub ingredients in a small bowl: Worcestershire sauce, ketchup, soy sauce, sugar, 1 tbsp oil, garlic and apple cider vinegar.</li><li>Slather the pork chops with the rub on both sides, keeping some for basting. Take the tray out, toss the potatoes and push them to the edge, add the pork and bake 15 minutes.</li><li>Switch the oven to the broiler on high (shelf about 8 in from the heat). Flip the pork, spoon over the reserved rub and broil 7-10 minutes until well caramelised.</li><li>Take the tray out, brush the golden juices from the tray over the pork (key for flavour and colour) and return it under the broiler for a couple of minutes. Serve, spooning the tray juices over the pork.</li></ol><p><em>Spoon the pan juices over the pork and garnish with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('68c2ad0e-14f6-5a44-832a-7535b22cd515', '2582aca3-2914-53c0-8254-4237a1bf138a', 'ru', 'Тыквенный крем-суп со сливками', 'Простой суп-пюре из тыквы, лука и чеснока на бульоне, который доводят до бархатистой консистенции блендером и добавляют немного сливок. Подходит любая тыква или butternut.', '<ol><li>Нарежьте тыкву ломтями по 3 см, срежьте кожуру и выскоблите семена. Нарежьте кусочками примерно по 4 см.</li><li>Сложите в кастрюлю тыкву, лук, целые зубчики чеснока, бульон и воду (жидкость покроет тыкву не полностью). Доведите до кипения без крышки, убавьте огонь и варите на активном кипении около 10 минут до мягкости тыквы.</li><li>Снимите с огня и пробейте погружным блендером до гладкости (или переложите в обычный блендер порциями).</li><li>Посолите и поперчите, влейте сливки. После добавления сливок суп не кипятите, иначе сливки свернутся. Разлейте по тарелкам и подавайте.</li></ol><p><em>Подавайте с хрустящим хлебом, полив ложкой сливок и посыпав перцем и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('3ebe1576-0c5c-57f6-807e-022b242fe945', '2582aca3-2914-53c0-8254-4237a1bf138a', 'en', 'Classic creamy pumpkin soup', 'A simple puréed soup of pumpkin, onion and garlic simmered in stock, blended velvety and finished with a little cream. Any pumpkin or butternut squash works.', '<ol><li>Cut the pumpkin into 2¼ inch (3 cm) slices, cut off the skin and scrape out the seeds. Cut into 1½ inch (4 cm) chunks.</li><li>Put the pumpkin, onion, whole garlic cloves, stock and water in a pot (the liquid will not quite cover the pumpkin). Bring to a boil uncovered, reduce and simmer rapidly about 10 minutes until the pumpkin is tender.</li><li>Remove from the heat and blend until smooth with a stick blender (or transfer to a regular blender in batches).</li><li>Season with salt and pepper and stir through the cream. Never boil the soup after adding the cream or it will split. Ladle into bowls and serve.</li></ol><p><em>Serve with crusty bread, drizzled with cream and sprinkled with pepper and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('c0b9bf35-a622-5388-9c75-ca5664827e5d', '060c44ef-af1b-571a-b9f7-7ed79e4b0df6', 'ru', 'Курица с картофелем и беконом в медово-горчичном соусе', 'Куриные бёдра на кости с картофелем и беконом, запечённые в одной сковороде в соусе из дижонской горчицы, мёда, белого вина и куриного сока. Достаточно просто для будней и красиво для гостей.', '<ol><li>Отварите картофель в кипящей воде 5 минут и слейте воду. Посыпьте солью и перцем и сбрызните оливковым маслом.</li><li>Разогрейте духовку до 190 °C. Посолите и поперчите курицу.</li><li>В большой сковороде на средне-сильном огне обжарьте половину бекона до лёгкой золотистости и переложите на бумажное полотенце.</li><li>Убавьте огонь до среднего. Выложите курицу кожей вниз и жарьте 3 минуты, пока она слегка не зарумянится и жир не вытопится. Переверните, жарьте 2 минуты и переложите на тарелку.</li><li>Полейте картофель 1 ст. л. жира из сковороды, остальной слейте. Верните сковороду на плиту, добавьте чеснок и лук и обжарьте около 2 минут до прозрачности.</li><li>Влейте вино, соскребая румяные кусочки со дна, и варите около 2 минут, пока не исчезнет запах алкоголя.</li><li>Добавьте остальные ингредиенты соуса (горчицу, мёд, тимьян, молоко, воду) и обжаренный бекон, перемешайте. Верните в сковороду курицу и картофель, посыпьте оставшимся беконом.</li><li>Запекайте без крышки 40–50 минут, пока курица и картофель не станут золотистыми. Дайте постоять 5 минут и подавайте с тимьяном или петрушкой.</li></ol><p><em>Дайте постоять 5 минут и посыпьте свежим тимьяном или петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('ca4fec77-274f-5ca6-99f2-75ff0e857951', '060c44ef-af1b-571a-b9f7-7ed79e4b0df6', 'en', 'Honey mustard baked chicken with potatoes and bacon', 'Bone-in chicken thighs with potatoes and bacon baked in one pan in a sauce of Dijon mustard, honey, white wine and chicken juices. Easy enough for a weeknight and fancy enough for guests.', '<ol><li>Boil the potatoes in water for 5 minutes and drain. Sprinkle with salt and pepper and drizzle with olive oil.</li><li>Preheat the oven to 190 °C (375 °F). Sprinkle the chicken with salt and pepper.</li><li>Heat a large skillet over medium-high heat and cook HALF the bacon until lightly browned. Transfer to a paper towel-lined plate.</li><li>Lower to medium. Add the chicken skin-side down and cook 3 minutes until very lightly browned and the fat has melted into the pan. Turn and cook 2 minutes, then move to a plate.</li><li>Drizzle 1 tbsp of the fat from the pan over the potatoes and pour off the rest. Return the pan to the stove, add the garlic and onion and cook about 2 minutes until translucent.</li><li>Add the wine, scraping the browned bits off the bottom, and simmer about 2 minutes until you can no longer smell alcohol.</li><li>Add the remaining sauce ingredients (mustard, honey, thyme, milk, water) and the cooked bacon and stir. Return the chicken and potatoes to the pan and sprinkle with the remaining bacon.</li><li>Bake uncovered 40-50 minutes until the chicken and potatoes are golden brown. Rest 5 minutes and serve with thyme or parsley.</li></ol><p><em>Rest 5 minutes and garnish with fresh thyme or parsley.</em></p>', CURRENT_TIMESTAMP),
  ('b51705ef-e04b-5d7c-8e9a-3b71abb8accb', '578f459f-05fd-50ae-8ebf-dda03896bc99', 'ru', 'Лёгкий крем-суп из брокколи с картофелем', 'Быстрый суп-пюре из брокколи, картофеля, лука и чеснока на овощном бульоне с молоком. Лёгкий, без сливок и масла.', '<ol><li>Разделите брокколи на соцветия размером с половину мячика для гольфа. Основную часть стебля нарежьте кусочками с палец, а толстый центральный стебель выбросьте или используйте для другого блюда.</li><li>Положите в кастрюлю все ингредиенты, кроме молока, соли и перца. Накройте крышкой, доведите до кипения, убавьте до среднего огня и варите на активном кипении 8–10 минут.</li><li>Снимите крышку, влейте молоко, снова доведите до кипения, снимите с огня и пробейте погружным блендером. Для большей густоты подержите суп на среднем огне подольше.</li><li>Посолите и поперчите. Для сухариков нарежьте черствый хлеб кубиками, сбрызните маслом и подсушите в духовке 3–5 минут, посолите и положите в суп.</li></ol><p><em>Подавайте с домашними сухариками.</em></p>', CURRENT_TIMESTAMP),
  ('29ca4c64-d22a-5e86-b733-a85f7508825f', '578f459f-05fd-50ae-8ebf-dda03896bc99', 'en', 'Light creamy broccoli and potato soup', 'A quick puréed soup of broccoli, potato, onion and garlic in vegetable stock with milk. Light, with no cream or butter.', '<ol><li>Break the broccoli into florets about half the size of a golf ball. Cut most of the stem (except the thick main stem) into thumb-sized pieces and discard or save the main stem.</li><li>Put all the ingredients except the milk, salt and pepper in a pot, cover, bring to a boil, turn down to medium and simmer rapidly for 8-10 minutes.</li><li>Remove the lid, add the milk, bring back to a boil, take off the heat and blend with a hand blender. For a thicker soup cook it longer over medium-low heat.</li><li>Season with salt and pepper. For croutons, cube stale bread, lightly spray with olive oil, bake 3-5 minutes, sprinkle with salt and add on top of the soup.</li></ol><p><em>Serve with homemade croutons.</em></p>', CURRENT_TIMESTAMP),
  ('24482503-977e-5812-b37c-ee2a59d7eead', 'd33a897a-42a1-5752-9a37-6f9c8167337a', 'ru', 'Меджадра: рис с чечевицей и жареным луком', 'Ароматный ближневосточный плов с чечевицей, зирой, кориандром, корицей и хрустящим жареным луком.', '<ol><li>Очень тонко нарежьте лук. Нагрейте растительное масло в средней кастрюле на среднем и сильном огне и порциями (примерно по трети) обжаривайте лук по 5 минут до золотистого и хрустящего состояния. Откидывайте на бумажные полотенца.</li><li>В другой кастрюле прогрейте оливковое масло с зирой и кориандром пару минут до аромата.</li><li>Добавьте рис и перемешайте, чтобы он покрылся маслом и специями. Влейте воду, добавьте чечевицу, куркуму, корицу, сахар, соль и перец.</li><li>Доведите до кипения, убавьте огонь, накройте крышкой и варите 10–12 минут, пока жидкость почти не впитается. Снимите с огня и оставьте под крышкой на 10 минут.</li><li>Взрыхлите рис вилкой, при необходимости досолите. Перед подачей смешайте с большей частью жареного лука, остальным посыпьте сверху.</li></ol><p><em>Подавайте тёплым, посыпав кинзой, с йогуртом или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('4d43a897-2ec3-5753-8ac6-81f4662a085e', 'd33a897a-42a1-5752-9a37-6f9c8167337a', 'en', 'Mejadra (rice with lentils and crispy onions)', 'A fragrant Middle Eastern pilaf with lentils, cumin, coriander, cinnamon and crunchy fried onions.', '<ol><li>Slice the onions very finely. Heat the vegetable oil in a medium saucepan over medium-high heat and fry the onions in three batches, about 5 minutes each, until golden and crispy. Drain on paper towels.</li><li>In another saucepan warm the olive oil with the cumin and coriander for a couple of minutes until fragrant.</li><li>Add the rice and stir to coat in the oil and spices. Pour in the water, then add the lentils, turmeric, cinnamon, sugar, salt and pepper.</li><li>Bring to a boil, reduce the heat, cover and cook for 10–12 minutes until most of the liquid is absorbed. Remove from the heat and rest covered for 10 minutes.</li><li>Fluff the rice with a fork and adjust the salt. Just before serving, stir through most of the fried onions and scatter the rest on top.</li></ol><p><em>Serve warm, sprinkled with coriander, with yogurt or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('127a596a-50d5-568f-8bf0-b783df73e503', 'c2549bf6-513c-523d-8b7c-12563cc2bea9', 'ru', 'Курица в кунжутной панировке с медово-соевым соусом', 'Запечённые в духовке кусочки куриных бёдер с хрустящей кунжутной корочкой в густом сладком соусе с мёдом и соей.', '<ol><li>Разогрейте духовку до 200 °C, поставьте решётку на верхний уровень. Смажьте противень маслом.</li><li>Смешайте тахини и 2 ч. л. соевого соуса, добавьте куриные бёдра, нарезанные ломтиками по 1,2 см, соль и кунжут. Обваляйте кусочки в муке, стряхните лишнее и разложите на противне.</li><li>Запекайте 12 минут. Затем включите максимальный гриль, поставьте противень на расстоянии около 15 см от нагревателя, переверните курицу и запекайте ещё 5 минут до золотистой хрустящей корочки.</li><li>Тем временем смешайте ингредиенты для соуса (бульон, уксус, мёд, соевый соус, кунжутное масло) в одной миске, а крахмал с водой — в другой.</li><li>На сковороде на среднем огне прогрейте масло, 30 секунд обжарьте чеснок. Влейте соус, доведите до кипения, добавьте раствор крахмала и варите 30 секунд до густоты сиропа. Сразу снимите с огня.</li><li>Полейте курицу соусом, перемешайте, посыпьте кунжутом и зелёным луком. Подавайте с рисом.</li></ol><p><em>Подавайте с отварным рисом, посыпав кунжутом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('9b6bdf0c-d0b9-518c-bb62-d06e364537e2', 'c2549bf6-513c-523d-8b7c-12563cc2bea9', 'en', 'Oven-baked honey sesame chicken', 'Oven-baked chicken thigh pieces with a crisp sesame crust tossed in a sticky honey-soy sauce.', '<ol><li>Preheat the oven to 200 °C with the shelf on the top level and oil a baking tray.</li><li>Mix the tahini and 2 tsp soy sauce, add the chicken slices (1.2 cm), salt and sesame seeds. Coat the pieces in flour, shake off the excess and place on the tray.</li><li>Bake for 12 minutes. Then switch to the highest grill setting with the tray about 15 cm from the heat, turn the chicken and grill for 5 minutes until golden and crispy.</li><li>Meanwhile mix the sauce ingredients (stock, vinegar, honey, soy sauce, sesame oil) in one bowl and the cornstarch with water in another.</li><li>Heat the oil in a skillet over medium heat and cook the garlic for 30 seconds. Add the sauce and bring to a bubble, add the cornstarch mixture and cook for 30 seconds until it thickens to a syrup. Remove from the heat immediately.</li><li>Pour the sauce over the chicken, toss, and sprinkle with sesame seeds and spring onion. Serve with rice.</li></ol><p><em>Serve with steamed rice, topped with sesame seeds and spring onion.</em></p>', CURRENT_TIMESTAMP),
  ('4747fb17-a359-5f59-9ea5-56b4e3b46f0a', '7c86abe0-1dfb-53d6-befa-2c6d889fb643', 'ru', 'Вегетарианский чоу-мейн с тофу и овощами', 'Быстрая жареная лапша с тофу, пекинской капустой, морковью, ростками фасоли и соусом из сои и хойсина.', '<ol><li>Подготовьте лапшу по инструкции на упаковке (обычно заливают кипятком).</li><li>Смешайте нарезанный тофу с 1/2 ст. л. соевого соуса и 1 ст. л. воды и оставьте на 5 минут. В небольшой миске смешайте ингредиенты соуса.</li><li>Разогрейте масло в воке на сильном огне, 10 секунд обжарьте чеснок. Добавьте тофу и жарьте около минуты, осторожно, чтобы он не развалился, до карамелизации.</li><li>Добавьте капусту и морковь и жарьте, пока капуста не начнёт вянуть.</li><li>Добавьте лапшу, зелёный лук, ростки фасоли и соус и жарьте около минуты, пока лапша не прогреется и не покроется соусом. Ростки должны остаться хрустящими. Подавайте сразу.</li></ol><p><em>Подавайте сразу, пока ростки хрустят.</em></p>', CURRENT_TIMESTAMP),
  ('dcfd458f-d16d-51dd-af8c-4ac86e3be059', '7c86abe0-1dfb-53d6-befa-2c6d889fb643', 'en', 'Vegetarian chow mein with tofu and vegetables', 'Quick stir-fried noodles with tofu, Chinese cabbage, carrot, bean sprouts and a soy-hoisin sauce.', '<ol><li>Prepare the noodles according to the packet instructions (usually soaked in boiling water).</li><li>Combine the sliced tofu with 1/2 tbsp soy sauce and 1 tbsp water and set aside for 5 minutes. Mix the sauce ingredients in a small bowl.</li><li>Heat the oil in a wok over high heat and stir-fry the garlic for 10 seconds. Add the tofu and stir-fry gently for about 1 minute until it starts to caramelise.</li><li>Add the cabbage and carrot and stir-fry until the cabbage begins to wilt.</li><li>Add the noodles, spring onions, bean sprouts and sauce and stir-fry for about a minute until the noodles are warm and coated. The sprouts should stay crisp. Serve immediately.</li></ol><p><em>Serve immediately while the bean sprouts are still crisp.</em></p>', CURRENT_TIMESTAMP),
  ('a5907e1b-b028-5a3f-bfff-bf9053381716', '25103696-1b38-5bb7-bb1c-d37268f12877', 'ru', 'Морковь, глазированная на сковороде с мёдом', 'Морковные палочки, обжаренные до золотистого цвета и карамелизованные с мёдом на сковороде, как будто запечены.', '<ol><li>Очистите морковь, разрежьте каждую вдоль на четыре части, затем пополам. Разогрейте масло в очень большой сковороде на среднем и сильном огне.</li><li>Выложите морковь срезом вниз (почти вся) и жарьте 5–7 минут, не помешивая, до золотистого цвета.</li><li>Добавьте мёд, воду, соль и перец, один раз перемешайте и готовьте около 3 минут, пока вода не выпарится и морковь не начнёт карамелизоваться.</li><li>Перемешайте ещё раз-два до карамели, переложите на блюдо и посыпьте петрушкой.</li></ol><p><em>Подавайте тёплой с мясом или птицей.</em></p>', CURRENT_TIMESTAMP),
  ('1493b0ad-2cc9-56f5-a68a-9af842bcd935', '25103696-1b38-5bb7-bb1c-d37268f12877', 'en', 'Honey-glazed stovetop carrots', 'Carrot sticks pan-browned and caramelised with honey on the stove so they taste roasted.', '<ol><li>Peel the carrots, cut each lengthwise into quarters, then in half. Heat the oil in a very large skillet over medium-high heat.</li><li>Add the carrots and shake the pan so they are almost all cut side down. Cook for 5–7 minutes without stirring until golden.</li><li>Add the honey, water, salt and pepper, stir once and cook for about 3 minutes until the water evaporates and the carrots start to caramelise.</li><li>Stir once or twice until caramelised, transfer to a dish and sprinkle with parsley.</li></ol><p><em>Serve warm with meat or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('43f6386f-9346-5e24-99da-bec213e64843', 'fa167891-9209-50f1-ac00-87ecfe71fa85', 'ru', 'Авголемоно: греческий куриный суп с лимоном и рисом', 'Шелковистый суп из куриного бульона с рисом, овощами и курицей, заправленный греческим соусом из яиц и лимонного сока. Готовится чуть больше получаса.', '<ol><li>В большой кастрюле с толстым дном разогрейте 1 ст. л. оливкового масла на средне-сильном огне. Быстро обжарьте морковь, сельдерей, зелёный лук и чеснок.</li><li>Влейте куриный бульон, добавьте лавровый лист и сделайте огонь сильным. Когда бульон закипит, всыпьте рис, посолите и поперчите. Убавьте огонь до средне-слабого и варите 20 минут, пока рис не станет мягким. Добавьте варёную курицу.</li><li>Для яично-лимонного соуса взбейте в миске лимонный сок с яйцами. Продолжая взбивать, влейте 2 половника горячего бульона из кастрюли (чтобы яйца не свернулись). Затем добавьте соус в суп и перемешайте. Сразу снимите с огня.</li><li>Посыпьте петрушкой и подавайте горячим с хлебом.</li></ol><p><em>Посыпьте петрушкой и подавайте горячим с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('3abd8c46-d454-57a8-8f91-3207b8ba6fbb', 'fa167891-9209-50f1-ac00-87ecfe71fa85', 'en', 'Avgolemono: Greek lemon chicken and rice soup', 'A silky soup of chicken broth with rice, vegetables and chicken, finished with a Greek egg and lemon sauce. Ready in just over half an hour.', '<ol><li>In a large heavy pot heat 1 tbsp olive oil over medium-high. Briefly sauté the carrots, celery, green onions and garlic.</li><li>Add the chicken broth and bay leaves and raise the heat to high. At a rolling boil add the rice, salt and pepper. Turn to medium-low and simmer 20 minutes until the rice is tender. Stir in the cooked chicken.</li><li>For the egg-lemon sauce, whisk the lemon juice and eggs in a medium bowl. While whisking, add 2 ladles of hot broth from the pot to temper the eggs. Stir the sauce into the soup and remove from the heat immediately.</li><li>Garnish with parsley and serve hot with bread.</li></ol><p><em>Garnish with parsley and serve hot with bread.</em></p>', CURRENT_TIMESTAMP),
  ('eda7177a-ac61-510c-a626-4473d95cef05', '63b7c916-8ca5-5bab-a586-be23a6d82fe6', 'ru', 'Турецкие запечённые фрикадельки в йогуртовом соусе', 'Запечённые говяжьи фрикадельки с петрушкой, зирой и кориандром в тёплом густом йогуртовом соусе на бульоне. Подаются с пряным оливковым маслом.', '<ol><li>Поставьте решётку в центр духовки и разогрейте её до 220 °C.</li><li>Подсушите ломтик хлеба в тостере или на сковороде до золотистого цвета, залейте водой и размочите до мягкости. Хорошо отожмите и разорвите на мелкие кусочки.</li><li>В большой миске смешайте хлеб, фарш, лук, чеснок, петрушку и яйцо. Добавьте зиру, кориандр, красный перец, соль и чёрный перец. Аккуратно, но тщательно перемешайте руками.</li><li>Застелите противень пергаментом. Скатайте из порций около 2 ст. л. примерно 18–20 фрикаделек и выложите на противень.</li><li>Запекайте на центральной решётке 15–20 минут, пока фрикадельки не пропекутся и внутри не исчезнет розовый цвет.</li><li>Пока готовятся фрикадельки, смешайте крахмал с водой до растворения. Добавьте яйцо и йогурт, щепотку соли и перца, взбейте.</li><li>В небольшой кастрюле доведите бульон до кипения, убавьте до слабого и тонкой струйкой влейте йогуртовую смесь, постоянно взбивая. Варите, помешивая, около минуты до загустения, выключите огонь. Соус должен остаться тёплым.</li><li>Для пряного масла прогрейте в сковороде на среднем огне оливковое масло, добавьте хлопья чили и слегка покрутите, пока масло не станет янтарным. Снимите с огня. Подавайте фрикадельки с соусом, луком и маслом.</li></ol><p><em>Выложите фрикадельки в неглубокую миску, залейте соусом, добавьте маринованный красный лук и сбрызните пряным маслом.</em></p>', CURRENT_TIMESTAMP),
  ('2aaa404c-4df6-5497-b996-4321b2b4ebfa', '63b7c916-8ca5-5bab-a586-be23a6d82fe6', 'en', 'Baked Turkish meatballs in yogurt sauce', 'Baked beef meatballs with parsley, cumin and coriander in a warm, creamy yogurt and broth sauce, drizzled with spicy chili olive oil.', '<ol><li>Position a rack in the center of the oven and preheat to 220 °C (425 °F).</li><li>Toast the bread until golden, cover it with water and soak until very soft. Wring it as dry as possible and tear into small pieces.</li><li>In a large bowl combine the bread, meat, onion, garlic, parsley and egg. Season with cumin, coriander, chili, salt and black pepper. Mix gently but thoroughly by hand.</li><li>Line a baking sheet with parchment. Form about 2 tbsp portions into 18-20 meatballs and arrange on the sheet.</li><li>Bake on the center rack 15-20 minutes until cooked through and no longer pink inside.</li><li>While they bake, whisk the cornstarch with the water until dissolved. Add the egg and yogurt, a pinch of salt and pepper and whisk until smooth.</li><li>Bring the broth to a boil in a small saucepan, reduce to a low simmer and pour in the yogurt mixture in a slow stream, whisking constantly. Cook, whisking, about a minute until thickened and turn the heat off. The sauce should stay warm.</li><li>For the spicy oil, warm the olive oil in a small skillet over medium heat, stir in the chili flakes and swirl until the oil turns amber. Remove from the heat. Serve the meatballs with the sauce, onions and oil.</li></ol><p><em>Arrange the meatballs in a shallow bowl, pour the sauce over, add pickled red onions and drizzle with the chili oil.</em></p>', CURRENT_TIMESTAMP),
  ('07d3fa81-6c56-5992-863b-26f570d3c99b', 'f861eb78-a589-5cb5-82c5-fa78a9ced969', 'ru', 'Египетская запеканка из картофеля с морковью, перцем и мясным соусом', 'Картофельные дольки с морковью и болгарским перцем, запечённые под пряным томатным соусом с говяжьим или индюшиным фаршем (душистый перец и кориандр).', '<ol><li>Разогрейте духовку до 190 °C.</li><li>Для мясного соуса разогрейте в большой антипригарной сковороде 2 ст. л. оливкового масла, обжарьте лук до прозрачности, добавьте чеснок на 30 секунд.</li><li>Добавьте фарш и разбейте его деревянной ложкой. Приправьте пряностями (душистый перец, кориандр, паприка), солью и перцем, и жарьте, помешивая, до румяности. Добавьте томаты и воду, разомните томаты ложкой, доведите до кипения, убавьте огонь, накройте и тушите 10 минут. При необходимости добавьте воды, подправьте вкус.</li><li>В форме 23 × 33 см разложите картофельные дольки, морковь и перец, посолите, поперчите и посыпьте душистым перцем и кориандром. Перемешайте, добавьте около 180 мл воды и выложите сверху мясной соус.</li><li>Накройте форму фольгой и запекайте около 30 минут, затем снимите фольгу и запекайте ещё 10–15 минут, пока картофель не станет мягким. Посыпьте свежей петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте с рисом и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('2124eb10-c786-5c06-8b22-93e970b69dfa', 'f861eb78-a589-5cb5-82c5-fa78a9ced969', 'en', 'Egyptian-style potato casserole with beef and carrots', 'Potato wedges with carrots and bell pepper baked under a spiced tomato meat sauce made with lean ground beef or turkey, flavored with allspice and coriander.', '<ol><li>Heat the oven to 190 °C (375 °F).</li><li>For the meat sauce, heat 2 tbsp olive oil in a large non-stick skillet, cook the onions until translucent, then add the garlic for about 30 seconds.</li><li>Add the ground meat and break it up with a wooden spoon. Season with the spices (allspice, coriander, paprika), salt and pepper and cook, stirring, until fully browned. Add the tomatoes and water, crush the tomatoes a little, bring to a boil, lower the heat, cover and simmer 10 minutes. Add a little water if needed and adjust the seasoning.</li><li>In a 9 × 13 inch baking pan arrange the potato wedges, carrots and peppers, season with salt and pepper and sprinkle with allspice and coriander. Toss, add about ¾ cup (180 ml) water and top with the meat sauce.</li><li>Cover the pan with foil and bake about 30 minutes, then uncover and bake another 10-15 minutes until the potatoes are tender. Top with fresh parsley.</li></ol><p><em>Top with parsley and serve with rice and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('5e81eeff-7fd1-5d92-898c-22b403046442', '933d434c-0d34-5e6b-9455-81af1f052be5', 'ru', 'Курица по-охотничьи (качиаторе) с грибами и перцем', 'Курица на кости, тушёная в томатном соусе с красным вином, грибами, болгарским перцем, сельдереем и итальянскими травами. Мясо получается очень нежным.', '<ol><li>Обсушите курицу бумажным полотенцем и посолите, поперчите с обеих сторон и под кожей.</li><li>В большой сковороде или жаровне с крышкой разогрейте 2 ст. л. оливкового масла на средне-сильном огне. Обжарьте курицу сначала кожей вниз, затем с другой стороны, всего около 8 минут до золотистого цвета. Переложите на тарелку.</li><li>В ту же посуду добавьте лук, сельдерей, перцы, грибы и чеснок. Готовьте на среднем огне, помешивая. Добавьте соль, перец, орегано, тимьян, петрушку и хлопья перца и готовьте 5–6 минут до мягкости овощей.</li><li>Влейте вино и уварите примерно наполовину, затем добавьте томаты и готовьте 5–10 минут на среднем огне, иногда помешивая.</li><li>Верните курицу в посуду, убавьте огонь до средне-слабого, накройте и готовьте 30 минут до готовности. Посыпьте петрушкой.</li></ol><p><em>Подавайте с хлебом, пастой, полентой или рисом, посыпав петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('4524e69c-5d18-5bf9-bde5-53742406ac34', '933d434c-0d34-5e6b-9455-81af1f052be5', 'en', 'Chicken cacciatore with mushrooms, peppers and red wine', 'Bone-in chicken braised in a tomato and red wine sauce with mushrooms, bell peppers, celery and Italian herbs. The meat turns fall-apart tender.', '<ol><li>Pat the chicken dry and season with salt and pepper on both sides and under the skin.</li><li>In a large pan or braiser with a lid heat 2 tbsp olive oil over medium-high. Brown the chicken skin side down first, then on the other side, about 8 minutes total. Set aside on a plate.</li><li>To the same pan add the onions, celery, peppers, mushrooms and garlic. Cook over medium heat, tossing regularly. Add salt, pepper, oregano, thyme, parsley and red pepper flakes and cook 5-6 minutes until the vegetables are tender.</li><li>Add the red wine and reduce by about half, then add the tomatoes and cook 5-10 minutes over medium heat, stirring occasionally.</li><li>Return the chicken to the pan, reduce to medium-low, cover and cook 30 minutes until cooked through. Garnish with parsley.</li></ol><p><em>Serve with crusty bread, pasta, polenta or rice, garnished with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('51b5572b-6285-5ee7-b06c-85f892b60981', 'c6889e96-362e-53d2-b780-716065db1ea0', 'ru', 'Постный тыквенный суп с красной чечевицей и специями', 'Густой суп-пюре из тыквы и красной чечевицы с луком, чесноком, кориандром, зирой и куркумой, с лимонным соком в конце. Без молока и глютена, готовится быстро.', '<ol><li>В кастрюле с толстым дном на средне-сильном огне разогрейте 2 ст. л. оливкового масла. Обжаривайте лук, часто помешивая, до золотистого цвета и прозрачности. Добавьте чеснок, томатную пасту, кориандр, зиру и куркуму, убавьте огонь до среднего и готовьте около 4 минут до аромата.</li><li>Добавьте чечевицу, тыкву, бульон и немного соли, перемешайте.</li><li>Включите сильный огонь и кипятите 5 минут, затем убавьте до средне-слабого, накройте крышкой не полностью и варите ещё около 20 минут, иногда помешивая, пока чечевица не станет полностью мягкой.</li><li>Снимите с огня, немного остудите и аккуратно пробейте суп в кухонном комбайне или блендере до гладкости. Верните в кастрюлю на средний огонь и прогрейте, при необходимости добавьте жидкости.</li><li>Добавьте изюм и лимонный сок и готовьте ещё около 4 минут, помешивая. Попробуйте и при необходимости досолите. Разлейте по тарелкам, сверху положите изюм и поджаренные кедровые орехи, по желанию ломтики халапеньо.</li></ol><p><em>Подавайте горячим с тёплой питой или хрустящим хлебом, по желанию с изюмом, кедровыми орехами и ломтиками халапеньо.</em></p>', CURRENT_TIMESTAMP),
  ('8d3e3370-be32-51ed-a75a-54c915bf4bb7', 'c6889e96-362e-53d2-b780-716065db1ea0', 'en', 'Vegan red lentil and pumpkin soup with warm spices', 'A thick puréed soup of pumpkin and red lentils with onion, garlic, coriander, cumin and turmeric, finished with lemon juice. Dairy-free, gluten-free and quick to make.', '<ol><li>In a heavy pot over medium-high heat warm 2 tbsp olive oil until shimmering. Cook the onions, tossing regularly, until golden and translucent. Stir in the garlic, tomato paste, coriander, cumin and turmeric, lower to medium and cook, stirring, about 4 minutes until fragrant.</li><li>Add the lentils, pumpkin, broth and a little salt and stir to combine.</li><li>Turn the heat to high and boil 5 minutes, then reduce to medium-low, partly cover and cook another 20 minutes, stirring occasionally, until the lentils are fully cooked.</li><li>Remove from the heat to cool slightly and carefully purée the soup in a food processor or blender. Return to the pot over medium heat to warm through, adding liquid if needed.</li><li>Stir in the raisins and lemon juice and cook another 4 minutes, stirring. Taste and adjust the salt. Divide among bowls and top with more raisins, toasted pine nuts and jalapeño slices if you like heat.</li></ol><p><em>Serve hot with warm pita or crusty bread, topped if you like with raisins, pine nuts and jalapeño slices.</em></p>', CURRENT_TIMESTAMP),
  ('40936702-7cdf-530e-abe0-c4a5e1ed7061', 'a3be69df-87c2-5bba-a737-96c8849f0df9', 'ru', 'Спагетти болоньезе', 'Классический густой мясной соус с беконом, овощами, томатами и красным вином, томлёный больше часа и поданный со спагетти и пармезаном.', '<ol><li>В большой кастрюле на среднем огне разогрейте оливковое масло, добавьте мелко нарезанный бекон и жарьте 10 минут до золотистого цвета и хруста.</li><li>Убавьте огонь, добавьте мелко нарезанные лук, морковь, сельдерей, чеснок и листья розмарина и 10 минут тушите, часто помешивая, пока овощи не станут мягкими.</li><li>Прибавьте огонь, всыпьте фарш и 3–4 минуты обжаривайте, помешивая, пока он не побуреет.</li><li>Добавьте помидоры в собственном соку, нарубленный базилик, орегано, лавровый лист, томатную пасту, бульонный кубик, чили (по желанию), вино и половинки помидоров черри. Перемешайте, разминая помидоры ложкой.</li><li>Доведите до кипения, убавьте огонь, накройте крышкой и варите 1 час 15 минут, иногда помешивая, пока соус не станет густым и насыщенным.</li><li>Добавьте тёртый пармезан, попробуйте и приправьте. Когда соус почти готов, отварите спагетти по инструкции на упаковке.</li><li>Слейте воду со спагетти и либо смешайте с соусом, либо выложите соус сверху. Подавайте с пармезаном, листьями базилика и хлебом.</li></ol><p><em>Посыпьте пармезаном и листьями базилика, подайте со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('df522215-373c-5b8a-931a-92ee7e77635f', 'a3be69df-87c2-5bba-a737-96c8849f0df9', 'en', 'Spaghetti bolognese', 'A classic thick meat sauce with bacon, vegetables, tomatoes and red wine, slowly simmered and served with spaghetti and Parmesan.', '<ol><li>Heat the olive oil in a large saucepan over medium heat, add the finely chopped bacon and fry for 10 minutes until golden and crisp.</li><li>Reduce the heat, add the finely chopped onions, carrots, celery, garlic and rosemary leaves and cook for 10 minutes, stirring often, until soft.</li><li>Turn the heat to medium-high, add the beef mince and cook, stirring, for 3–4 minutes until browned all over.</li><li>Add the plum tomatoes, chopped basil, oregano, bay leaves, tomato purée, stock cube, chilli (if using), wine and halved cherry tomatoes. Stir, breaking up the tomatoes.</li><li>Bring to the boil, reduce to a gentle simmer, cover and cook for 1 hour 15 minutes, stirring occasionally, until rich and thick.</li><li>Stir in the grated Parmesan and check the seasoning. When the sauce is nearly done, cook the spaghetti following the pack instructions.</li><li>Drain the spaghetti and stir it into the sauce or serve the sauce on top. Serve with extra Parmesan, basil leaves and bread.</li></ol><p><em>Top with grated Parmesan and basil leaves and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('f2914fc5-adb8-5a43-b8e0-0d83411bd7d9', 'a2c46b89-7066-5d16-9e7b-47b28c30b8a6', 'ru', 'Пастуший пирог с говядиной и картофельным пюре', 'Классическая британская запеканка: говяжий фарш с овощами в густом соусе под слоем картофельного пюре с чеддером.', '<ol><li>В большой кастрюле разогрейте 1 ст. л. масла и порциями обжарьте фарш до румяности. Откладывайте готовое.</li><li>Влейте остальное масло, добавьте мелко нарезанные лук, морковь и сельдерей и на слабом огне тушите около 20 минут до мягкости.</li><li>Добавьте чеснок, муку и томатную пасту, прибавьте огонь и готовьте несколько минут, затем верните в кастрюлю мясо.</li><li>Влейте вино (по желанию) и немного упарьте, затем добавьте бульон, вустерский соус, тимьян и лавровый лист. Варите без крышки 45 минут до густой подливы. При необходимости посолите, достаньте лавровый лист и стебли тимьяна.</li><li>Тем временем очистите и нарежьте картофель, залейте солёной холодной водой, доведите до кипения и варите до мягкости. Слейте воду, дайте паровой сушке несколько минут.</li><li>Разомните картофель с молоком, маслом и тремя четвертями сыра, приправьте мускатным орехом, солью и перцем.</li><li>Разложите мясо по двум жаропрочным формам, сверху распределите пюре и посыпьте оставшимся сыром.</li><li>Запекайте при 200 °C (с конвекцией) 25–30 минут до золотистой корочки.</li></ol><p><em>Подавайте с зелёным горошком или тушёной капустой.</em></p>', CURRENT_TIMESTAMP),
  ('5278001f-ba5d-54ee-a9a5-5a233cd5c73a', 'a2c46b89-7066-5d16-9e7b-47b28c30b8a6', 'en', 'Beef cottage pie with cheesy mash', 'The classic British bake: beef mince and vegetables in a thick gravy under cheddar mashed potato.', '<ol><li>Heat 1 tbsp of the oil in a large saucepan and brown the mince in batches, setting it aside as it browns.</li><li>Add the remaining oil, the chopped onions, carrots and celery and cook gently for about 20 minutes until soft.</li><li>Add the garlic, flour and tomato purée, increase the heat and cook for a few minutes, then return the beef to the pan.</li><li>Pour in the wine (optional) and reduce slightly, then add the stock, Worcestershire sauce, thyme and bay leaves. Simmer uncovered for 45 minutes until the gravy is thick and coats the meat. Season and discard the bay leaves and thyme stalks.</li><li>Meanwhile peel and chop the potatoes, cover with salted cold water, bring to the boil and simmer until tender. Drain and let them steam-dry for a few minutes.</li><li>Mash the potatoes with the milk, butter and three-quarters of the cheddar and season with nutmeg, salt and pepper.</li><li>Spoon the meat into two ovenproof dishes, cover with the mash and sprinkle with the remaining cheese.</li><li>Bake at 200 °C (fan) for 25–30 minutes until the topping is golden.</li></ol><p><em>Serve with peas or braised cabbage.</em></p>', CURRENT_TIMESTAMP),
  ('448caa2f-6dc9-5476-856f-f914d37f10b3', '95d3fe51-69a6-53f6-9a8c-394972e27826', 'ru', 'Чили кон карне с красной фасолью', 'Густое острое рагу из говяжьего фарша с красной фасолью, томатами, паприкой и зирой, которое подают с рисом и сметаной.', '<ol><li>Мелко нарежьте лук кубиками около 5 мм, перец очистите от семян и нарежьте, чеснок измельчите.</li><li>Разогрейте масло в кастрюле на среднем огне 1–2 минуты, добавьте лук и готовьте около 5 минут до мягкости и полупрозрачности.</li><li>Добавьте чеснок, перец, острый перец чили, паприку и зиру, перемешайте и готовьте ещё 5 минут.</li><li>Прибавьте огонь, добавьте фарш и разбивайте ложкой не менее 5 минут, пока он не станет коричневым без розовых кусочков и будет жариться, а не тушиться.</li><li>Растворите бульонный кубик в 300 мл горячей воды и влейте в кастрюлю. Добавьте томаты, майоран, сахар, соль, перец и томатную пасту, хорошо перемешайте.</li><li>Доведите до кипения, накройте крышкой, убавьте огонь и варите на слабом огне 20 минут, периодически помешивая и при необходимости подливая воду.</li><li>Промойте красную фасоль на сите, добавьте в чили, доведите до кипения и варите без крышки ещё 10 минут.</li><li>Приправьте по вкусу, накройте крышкой, выключите огонь и дайте постоять 10 минут. Подавайте с рисом и сметаной.</li></ol><p><em>Подавайте с отварным рисом и сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('f21a826a-5f10-560c-9c3b-d57663b538a4', '95d3fe51-69a6-53f6-9a8c-394972e27826', 'en', 'Chilli con carne with kidney beans', 'A thick spicy beef mince stew with red kidney beans, tomatoes, paprika and cumin, served with rice and soured cream.', '<ol><li>Dice the onion into 5 mm pieces, deseed and chop the pepper and finely chop the garlic.</li><li>Heat the oil in a pan over medium heat for 1–2 minutes, add the onion and cook for about 5 minutes until soft and slightly translucent.</li><li>Add the garlic, pepper, chilli powder, paprika and cumin, stir and cook for another 5 minutes.</li><li>Turn up the heat, add the mince and break it up with a spoon for at least 5 minutes until browned all over with no pink bits, frying rather than stewing.</li><li>Dissolve the stock cube in 300 ml hot water and pour into the pan. Add the tomatoes, marjoram, sugar, seasoning and tomato purée and stir well.</li><li>Bring to the boil, cover, reduce the heat and cook gently for 20 minutes, stirring now and then and adding a little water if it dries out.</li><li>Drain and rinse the kidney beans, stir them in, bring to the boil and cook uncovered for another 10 minutes.</li><li>Season to taste, put the lid back on, turn off the heat and leave for 10 minutes. Serve with rice and soured cream.</li></ol><p><em>Serve with boiled rice and soured cream.</em></p>', CURRENT_TIMESTAMP),
  ('b8a65c8b-2f99-5b97-8a4e-c4ff0d3ac7ac', '6aef11a5-7c58-5034-bd64-6b20db85ff4d', 'ru', 'Фрикасе из курицы со сливочным соусом и горошком', 'Куриные ножки, сваренные с овощами, в бархатистом соусе на бульоне со сливками, белым вином, лимоном и зелёным горошком.', '<ol><li>Выложите в большую кастрюлю нарезанные морковь, порей, сельдерей, лук, чеснок и куриные ножки, добавьте горошины перца и соль. Залейте 700–800 мл холодной воды, чтобы всё было покрыто.</li><li>Доведите до кипения на среднем огне, снимите пену, убавьте огонь и варите 30 минут. Выньте курицу на тарелку и дайте остыть.</li><li>Процедите бульон через мелкое сито, морковь и другие овощи отложите. Мясо снимите с костей и нарвите кусочками.</li><li>Для соуса растопите масло на среднем огне до пены, всыпьте муку, перемешайте и прогрейте 1–2 минуты до бледного цвета.</li><li>Влейте вино и дайте ему полностью выпариться, затем понемногу влейте бульон, постоянно помешивая, добавьте сливки и лавровый лист.</li><li>Варите 5 минут до гладкости, приправьте лимонным соком, перцем и мускатным орехом. Добавьте курицу, горошек и морковь и мягко прогрейте несколько минут. Посыпьте петрушкой.</li></ol><p><em>Подавайте с рисом и отварными овощами из бульона.</em></p>', CURRENT_TIMESTAMP),
  ('0defb5d6-d2fe-502b-b9a9-a12881cc14e5', '6aef11a5-7c58-5034-bd64-6b20db85ff4d', 'en', 'Chicken fricassee with cream sauce and peas', 'Chicken legs simmered with vegetables and finished in a velvety cream sauce made with the broth, white wine, lemon and green peas.', '<ol><li>Put the chopped vegetables, garlic and chicken legs in a large pan, add the peppercorns and salt and cover with 700–800 ml of cold water.</li><li>Bring to the boil over medium heat, skim off the scum, reduce the heat and simmer for 30 minutes. Remove the chicken to a plate to cool.</li><li>Strain the broth through a fine sieve, reserving the carrot and other vegetables. Pull the chicken off the bones into pieces.</li><li>For the sauce, melt the butter over medium heat until foaming, add the flour, stir and cook for 1–2 minutes until pale.</li><li>Pour in the wine and let it reduce completely, then slowly pour in the broth, stirring well, and add the cream and bay leaf.</li><li>Simmer for 5 minutes until smooth, season with lemon juice, pepper and nutmeg. Stir in the chicken, peas and cooked carrots and warm through gently. Sprinkle with parsley.</li></ol><p><em>Serve with rice and the reserved vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('bfaf38db-2cf8-5f27-9b8f-6b1c39f4b22c', '33e171d9-ec47-5313-b29a-0fb12ed71d4e', 'ru', 'Куриный шницель с салатом из капусты, моркови и яблока', 'Отбитое куриное филе в сухарях с пармезаном, обжаренное до золотистой корочки, и йогуртовый салат из капусты с морковью и яблоком.', '<ol><li>Для салата смешайте в большой миске нашинкованную капусту, тёртую морковь, зелёный лук, тёртое яблоко, йогурт, лимонный сок и горчицу, слегка приправьте и отставьте.</li><li>Положите куриное филе между двумя слоями плёнки и отбейте скалкой до толщины 2–3 мм.</li><li>На одну тарелку насыпьте приправленную муку, на другую вылейте взбитое яйцо. В неглубокой миске смешайте сухари с пармезаном.</li><li>Обваляйте курицу в муке, затем в яйце и полностью в сухарях с пармезаном. Если не жарите сразу, уберите в холодильник.</li><li>Разогрейте масло на сковороде на довольно сильном огне и жарьте шницели по два, по 2–3 минуты с каждой стороны до золотистого цвета. Выложите на бумажное полотенце, держите тёплыми в слабо нагретой духовке. Подавайте с салатом.</li></ol><p><em>Подавайте шницели горячими со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('6ba31070-20df-5e6f-bec2-86a9d4941e88', '33e171d9-ec47-5313-b29a-0fb12ed71d4e', 'en', 'Chicken schnitzel with apple coleslaw', 'Flattened chicken breast coated in Parmesan breadcrumbs and fried until golden, with a yogurt coleslaw of cabbage, carrot and apple.', '<ol><li>For the coleslaw, mix the shredded cabbage, grated carrot, spring onions, grated apple, yogurt, lemon juice and mustard in a large bowl, season lightly and set aside.</li><li>Place the chicken fillets between two layers of cling film and bash with a rolling pin to 2–3 mm thick.</li><li>Put the seasoned flour on one plate and the beaten egg on another. In a shallow bowl mix the breadcrumbs with the Parmesan.</li><li>Dip the chicken in the flour, then the egg, then coat completely in the breadcrumb mixture. Chill if not cooking right away.</li><li>Heat the oil in a large frying pan over fairly high heat and cook the schnitzels two at a time for 2–3 minutes per side until golden. Drain on kitchen paper and keep warm in a low oven. Serve with the coleslaw.</li></ol><p><em>Serve the schnitzels hot with the fresh coleslaw.</em></p>', CURRENT_TIMESTAMP),
  ('26a40013-7e87-5a7b-b096-5c7f2a071d0b', 'f8ab61b7-c27e-57d1-a0e2-af8ea54b698a', 'ru', 'Постное рагу из нута с запечённой цветной капустой и морковью', 'Сытное веганское рагу с нутом, томатами, запечённой цветной капустой и морковью на смеси тёплых специй: куркума, зира, корица, паприка и кориандр.', '<ol><li>Разогрейте духовку до 245 °C. Смешайте в миске все специи.</li><li>Выложите соцветия цветной капусты и морковь на слегка смазанный маслом противень. Посолите и поперчите, добавьте чуть больше половины смеси специй, щедро сбрызните оливковым маслом и перемешайте, чтобы специи покрыли овощи.</li><li>Запекайте при 245 °C 20 минут, пока овощи не смягчатся и не приобретут цвет. Выньте и отложите, духовку выключите.</li><li>В большой жаровне или чугунной кастрюле разогрейте 2 ст. л. масла. Обжарьте лук 3 минуты, добавьте чеснок и оставшиеся специи и готовьте 2–3 минуты на средне-сильном огне, постоянно помешивая.</li><li>Добавьте нут и томаты с соком, посолите и поперчите. Вмешайте запечённые цветную капусту и морковь. Доведите до кипения, убавьте огонь до средне-слабого, накройте не полностью и готовьте ещё 20 минут, иногда помешивая и при необходимости подливая воды.</li><li>Разложите по тарелкам, украсьте петрушкой и поджаренными орехами (по желанию).</li></ol><p><em>Подавайте горячим с быстрым кускусом или тёплой питой, посыпав петрушкой и поджаренными орехами.</em></p>', CURRENT_TIMESTAMP),
  ('9f0edf3b-caa5-59d4-80d5-4f2bfc6810fd', 'f8ab61b7-c27e-57d1-a0e2-af8ea54b698a', 'en', 'Roasted cauliflower and chickpea stew', 'A hearty vegan stew of chickpeas, tomatoes, roasted cauliflower and carrots with a warm spice mix of turmeric, cumin, cinnamon, paprika and coriander.', '<ol><li>Preheat the oven to 245 °C (475 °F). Mix all the spices together in a small bowl.</li><li>Put the cauliflower florets and carrots on a large lightly oiled baking sheet. Season with salt and pepper, add a little more than half of the spice mix, drizzle generously with olive oil and toss so the spices coat the vegetables evenly.</li><li>Bake at 245 °C (475 °F) for 20 minutes until the vegetables soften and gain some colour. Remove, set aside and turn the oven off.</li><li>In a large cast iron pot or Dutch oven heat 2 tbsp olive oil. Sauté the onions for 3 minutes, then add the garlic and the remaining spices and cook on medium-high 2-3 more minutes, stirring constantly.</li><li>Add the chickpeas and tomatoes, season with salt and pepper and stir in the roasted cauliflower and carrots. Bring to a boil, reduce to medium-low, partly cover and cook another 20 minutes, stirring occasionally and adding a little water if needed.</li><li>Serve in bowls garnished with parsley and toasted nuts if you like.</li></ol><p><em>Serve hot over quick-cooked couscous or with warm pita, topped with parsley and toasted nuts.</em></p>', CURRENT_TIMESTAMP),
  ('a9345bbc-0be7-570b-ac9a-c0d5d0f7d34f', '3d36c416-3b39-5a03-ab3e-51fdb4607775', 'ru', 'Ливанский рис хашве с говядиной, орехами и изюмом', 'Ароматный плов-пилав: рис, сваренный поверх обжаренного говяжьего фарша с корицей, душистым перцем и гвоздикой. Подаётся перевёрнутым, с поджаренными кедровыми орехами, миндалём и изюмом.', '<ol><li>Замочите рис в холодной воде на 15 минут, пока зёрнышко не начнёт легко ломаться между пальцами. Хорошо слейте воду.</li><li>Тем временем разогрейте 1 ст. л. масла в кастрюле с толстым дном. Коротко обжарьте красный лук на средне-сильном огне, добавьте фарш. Приправьте 1¼ ч. л. душистого перца, чесноком, ½ ч. л. гвоздики, ½ ч. л. корицы, солью и перцем. Перемешайте и жарьте 8–10 минут до полной готовности фарша. Слейте лишний жир.</li><li>Выложите рис поверх мяса. Приправьте рис солью и оставшимися душистым перцем, гвоздикой и корицей. Влейте 600 мл воды и добавьте 1 ст. л. масла, чтобы покрыть рис.</li><li>Сделайте огонь сильным и доведите до кипения. Кипятите, пока жидкость не уменьшится значительно. Затем убавьте огонь до минимума, накройте крышкой и готовьте 20 минут, пока вся влага не впитается, а рис не станет рассыпчатым. Снимите с огня и оставьте на 10 минут.</li><li>Накройте кастрюлю большим круглым блюдом и аккуратно переверните, чтобы слой мяса оказался сверху. Посыпьте петрушкой, поджаренными кедровыми орехами, миндалём и изюмом.</li></ol><p><em>Переверните кастрюлю на блюдо, чтобы мясо оказалось сверху, и посыпьте петрушкой, орехами и изюмом.</em></p>', CURRENT_TIMESTAMP),
  ('0821789c-7f3a-5dbc-b909-42799bba8e43', '3d36c416-3b39-5a03-ab3e-51fdb4607775', 'en', 'Lebanese rice hashweh with beef, nuts and raisins', 'A fragrant pilaf: rice cooked over browned ground beef seasoned with cinnamon, allspice and cloves, flipped onto a platter and topped with toasted pine nuts, almonds and raisins.', '<ol><li>Soak the rice in cold water for 15 minutes, until a grain breaks easily between your fingers. Drain well.</li><li>Meanwhile heat 1 tbsp olive oil in a heavy pot. Cook the red onion briefly over medium-high, then add the ground beef. Season with 1¼ tsp allspice, garlic, ½ tsp cloves, ½ tsp cinnamon, salt and pepper. Toss and cook until fully browned, 8-10 minutes. Drain off excess fat.</li><li>Top the meat with the rice. Season the rice with a little salt and the remaining allspice, cloves and cinnamon. Add 2½ cups (600 ml) water and 1 tbsp olive oil to cover the rice.</li><li>Turn the heat to high and bring to a rolling boil. Boil until the liquid has reduced significantly. Then turn to low, cover and cook 20 minutes until all the moisture is absorbed and the rice is neither hard nor sticky. Remove from the heat and rest 10 minutes.</li><li>Place a large round platter over the pot and carefully flip it so the meat layer is on top. Garnish with parsley, toasted pine nuts, almonds and raisins.</li></ol><p><em>Flip the pot onto a platter so the meat is on top and garnish with parsley, nuts and raisins.</em></p>', CURRENT_TIMESTAMP),
  ('e68d61bf-69cd-58c7-9134-2ddcee325f3c', 'f62c5d5a-aee0-5fe4-a941-91038b507902', 'ru', 'Куриный сувлаки по-гречески на шпажках', 'Кубики куриной грудки, замаринованные в оливковом масле с чесноком, орегано, розмарином, лимоном и белым вином, обжаренные на шпажках. Классически подаётся в питах с овощами, оливками и цацики.', '<ol><li>Для маринада измельчите в небольшом комбайне или блендере (или потолките) чеснок, орегано, розмарин, паприку, соль, перец, оливковое масло, вино и лимонный сок. Лавровый лист пока не добавляйте.</li><li>Положите курицу в большую миску с лавровым листом, залейте маринадом и перемешайте. Плотно накройте и уберите в холодильник минимум на 2 часа или на ночь.</li><li>Замочите 10–12 деревянных шпажек в воде на 30–45 минут. Тем временем приготовьте цацики и остальные добавки.</li><li>Нанижите кусочки курицы на шпажки.</li><li>Смажьте решётку гриля (или сковороду-гриль) маслом и разогрейте на средне-сильном огне. Жарьте шпажки до хорошего румянца, пока внутри не будет 71 °C (мясо дойдёт до 74 °C при отдыхе), равномерно переворачивая, около 5 минут. В процессе слегка смазывайте оставшимся маринадом, остаток маринада выбросьте.</li><li>Переложите курицу на блюдо и дайте отдохнуть 3 минуты. Быстро подогрейте питы на гриле. Соберите: намажьте питу цацики, положите курицу, овощи и оливки.</li></ol><p><em>Снимите курицу со шпажек и заверните в тёплую питу с цацики, помидором, огурцом, луком и оливками.</em></p>', CURRENT_TIMESTAMP),
  ('fd87f6b4-bd50-53da-8816-e38efab338d8', 'f62c5d5a-aee0-5fe4-a941-91038b507902', 'en', 'Greek chicken souvlaki skewers', 'Cubes of chicken breast marinated in olive oil with garlic, oregano, rosemary, lemon and white wine and grilled on skewers. Classically served in pitas with vegetables, olives and tzatziki.', '<ol><li>For the marinade, pulse the garlic, oregano, rosemary, paprika, salt, pepper, olive oil, wine and lemon juice in a small food processor or blender (or pound by hand) until combined. Do not add the bay leaves yet.</li><li>Put the chicken in a large bowl with the bay leaves, pour the marinade over and toss to coat. Cover tightly and refrigerate at least 2 hours or overnight.</li><li>Soak 10-12 wooden skewers in water for 30-45 minutes. Meanwhile prepare the tzatziki and other fixings.</li><li>Thread the marinated chicken pieces onto the skewers.</li><li>Brush the grates of a grill (or a grill pan) with a little oil and heat over medium-high. Cook the skewers until well browned and the inside reaches 71 °C (160 °F), turning evenly, about 5 minutes. Lightly brush with the marinade while grilling and discard any leftover marinade.</li><li>Transfer the chicken to a platter and rest 3 minutes. Briefly grill the pitas. Assemble: spread tzatziki on the pita, add chicken, then vegetables and olives.</li></ol><p><em>Slide the chicken off the skewers into warm pita with tzatziki, tomato, cucumber, onion and olives.</em></p>', CURRENT_TIMESTAMP),
  ('d46e1f3e-1be5-532f-86ed-4bf227812153', 'e53e651e-0eb5-531d-bc5b-63822e3df368', 'ru', 'Куриное рагу с овощами и томатами', 'Тушёные куриные бёдра с луком, морковью, перцем, кабачком, картофелем и томатами с паприкой, кориандром и орегано. Хорошо хранится, на следующий день становится ещё вкуснее, и замораживается.', '<ol><li>Обсушите курицу бумажным полотенцем и посолите и поперчите с одной стороны.</li><li>В жаровне или большой кастрюле разогрейте масло на средне-сильном огне до лёгкого шипения. Выложите курицу посоленной стороной вниз, посолите и поперчите верх. Жарьте до румяной корочки около 4 минут, переверните и жарьте ещё 3 минуты. Переложите на тарелку.</li><li>На том же огне добавьте лук, чеснок, морковь, перец, кабачок и картофель. Приправьте паприкой, кориандром, орегано, щепоткой соли и перца. Готовьте, иногда помешивая, 7–8 минут, пока овощи не смягчатся и слегка не подгорят по краям.</li><li>Влейте томаты, бульон и положите веточки тимьяна. Деревянной ложкой раздавите томаты на куски.</li><li>Доведите до кипения, верните курицу в кастрюлю и варите на сильном огне 5 минут, иногда помешивая. Убавьте огонь до средне-слабого, накройте не полностью и тушите 20–30 минут, пока рагу не загустеет, а курица не станет мягкой.</li><li>Выключите огонь, выньте тимьян, добавьте уксус и свежую петрушку, перемешайте и подавайте.</li></ol><p><em>Подавайте горячим с хлебом, посыпав петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('4a5c478b-798d-5808-b557-a8dda38bf20f', 'e53e651e-0eb5-531d-bc5b-63822e3df368', 'en', 'Chicken and vegetable stew in tomato sauce', 'Chicken thighs braised with onion, carrots, bell pepper, zucchini, potato and tomatoes, flavored with paprika, coriander and oregano. Keeps well, tastes better the next day and freezes exceptionally well.', '<ol><li>Pat the chicken dry and season one side with a good pinch of salt and pepper.</li><li>In a Dutch oven or large pot heat the olive oil over medium-high until shimmering. Add the chicken seasoned side down, then season the top. Cook until browned on the bottom, about 4 minutes, flip and cook 3 minutes more. Set aside on a plate.</li><li>Keeping the heat on medium-high, add the onion, garlic, carrot, bell pepper, zucchini and potato. Season with the paprika, coriander, oregano and a pinch of salt and pepper. Cook, stirring occasionally, until the vegetables soften and lightly char, about 7-8 minutes.</li><li>Stir in the tomatoes, chicken broth and thyme sprigs. Use a wooden spoon to break up the tomatoes into chunks.</li><li>Bring to a boil, return the chicken to the pot and cook on high 5 minutes, stirring occasionally. Lower to medium-low, partly cover and simmer 20-30 minutes until the stew thickens and the chicken is tender.</li><li>Turn off the heat, remove the thyme sprigs, stir in the vinegar and fresh parsley and serve.</li></ol><p><em>Serve hot with bread, topped with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('f9dc4ddb-8472-55b0-97ff-7fac267ac82a', '0c48cbea-12dc-5828-bd7d-6620d11f1ca1', 'ru', 'Фарш индейки на сковороде со шпинатом, помидорами, белой фасолью и сухариками', 'Быстрый ужин в одной сковороде: фарш индейки с луком, фенхелем, орегано, черри и печёным красным перцем, со шпинатом, белой фасолью и хрустящими домашними сухариками.', '<ol><li>Для сухариков разогрейте в большой сковороде 2 ст. л. масла на средне-сильном огне. Добавьте кубики хлеба, 1 ч. л. соли и перец и обжаривайте, помешивая, 3–4 минуты до лёгкой золотистости и хруста снаружи при мягкой середине. Переложите на тарелку, сковороду верните на огонь.</li><li>Добавьте в сковороду оставшуюся ложку масла и лук, обжарьте около 5 минут до прозрачности. Добавьте чеснок, фарш, фенхель, орегано, тимьян, красный перец, ½ ч. л. соли и чёрный перец. Разбейте индейку на мелкие кусочки, добавьте помидоры и готовьте 15 минут, пока фарш не зарумянится, а помидоры не лопнут (если не лопаются, проколите ножом).</li><li>Добавьте нарезанный печёный перец, шпинат и фасоль и перемешайте, пока всё не прогреется, а шпинат не опадёт. Влейте уксус, добавьте сухарики и перемешайте. Попробуйте и при необходимости досолите и поперчите. Разложите по тарелкам.</li></ol><p><em>Разложите по тарелкам сразу, пока сухарики хрустят.</em></p>', CURRENT_TIMESTAMP),
  ('8d866f8f-1cd2-50f1-92fc-8c4795b28b8b', '0c48cbea-12dc-5828-bd7d-6620d11f1ca1', 'en', 'Ground turkey skillet with spinach, tomatoes, white beans and croutons', 'A quick one-skillet dinner of ground turkey with onion, fennel, oregano, cherry tomatoes and roasted red peppers, finished with spinach, white beans and crunchy homemade croutons.', '<ol><li>For the croutons, heat 2 tbsp oil in a large skillet over medium-high heat. Add the bread cubes, 1 tsp salt and pepper and toast, stirring, 3-4 minutes until lightly browned and mostly crisp (crunchy outside, chewy inside). Move to a plate and return the skillet to the stove.</li><li>Add the remaining tbsp of oil to the pan with the onion and sauté about 5 minutes until translucent. Add the garlic, ground turkey, fennel, oregano, thyme, red pepper, ½ tsp salt and black pepper. Break the turkey into small bits, add the tomatoes and cook 15 minutes until the turkey is browned and the tomatoes burst and blister (puncture them with a knife if they do not collapse).</li><li>Add the chopped roasted peppers, spinach and beans and stir until warmed through and the spinach wilts. Add the vinegar and the croutons and stir. Taste, add salt and pepper if you like and serve in bowls.</li></ol><p><em>Serve right away while the croutons are still crisp.</em></p>', CURRENT_TIMESTAMP),
  ('121186e2-0296-5f13-95d4-f4771b4409ed', '9066b353-8b80-5801-a8fe-c2d7ca30c34e', 'ru', 'Спагетти с томатами, базиликом и запечённой курицей', 'Спагетти в соусе из черри, чеснока, зелёного лука и белого вина с базиликом, сверху — курица в пряном рубе, запечённая в духовке.', '<ol><li>Разогрейте духовку до 200 °C. Обсушите куриное филе, посолите и поперчите. Смешайте орегано, кориандр, паприку и мускатный орех и натрите смесью курицу с обеих сторон.</li><li>В жаропрочной сковороде разогрейте 2 ст. л. оливкового масла и обжарьте курицу 4–5 минут до тёмной корочки с обеих сторон. Выключите огонь, влейте воду и половину лимонного сока.</li><li>Поставьте сковороду в духовку на 20–25 минут, один раз перевернув курицу, до температуры 74 °C в самой толстой части.</li><li>Пока курица запекается, отварите спагетти по инструкции (около 9 минут) в подсоленной воде и слейте воду.</li><li>В большой сковороде прогрейте оставшееся оливковое масло, добавьте хлопья чили, половинки помидоров, чеснок и зелёный лук, посолите, поперчите и готовьте 5–7 минут на среднем и сильном огне.</li><li>Влейте вино и оставшийся лимонный сок, доведите до кипения и немного упарьте, затем убавьте огонь, накройте и тушите 7–10 минут, пока помидоры не станут мягкими и не приобретут рыжий цвет.</li><li>Добавьте спагетти в соус и перемешайте. Когда паста прогреется, добавьте рваный базилик, пармезан и кедровые орешки. Разложите по тарелкам и сверху положите курицу.</li></ol><p><em>Подавайте со свежим салатом и тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('517964dc-5801-54e6-ae3b-6d4eb5bc6880', '9066b353-8b80-5801-a8fe-c2d7ca30c34e', 'en', 'Tomato-basil spaghetti with spiced baked chicken', 'Spaghetti tossed with a sauce of cherry tomatoes, garlic, green onions and white wine plus basil, topped with spice-rubbed oven-baked chicken breast.', '<ol><li>Preheat the oven to 200 °C. Pat the chicken dry, season with salt and pepper, mix the oregano, coriander, paprika and nutmeg and rub the mixture on both sides.</li><li>In an oven-safe skillet heat 2 tbsp of olive oil and brown the chicken deeply on both sides, 4–5 minutes in total. Turn off the heat and add the water and half the lemon juice.</li><li>Transfer to the oven for 20–25 minutes, turning once, until the thickest part reaches 74 °C.</li><li>While the chicken bakes, cook the spaghetti in salted water according to the package (about 9 minutes) and drain.</li><li>In a large skillet heat the remaining olive oil, add the chilli flakes, halved tomatoes, garlic and green onions, season and cook for 5–7 minutes over medium-high heat.</li><li>Add the wine and the remaining lemon juice, bring to a boil and reduce slightly, then lower the heat, cover and simmer for 7–10 minutes until the tomatoes soften and turn rusty orange.</li><li>Add the spaghetti to the tomato sauce and toss. When heated through, stir in the basil, Parmesan and pine nuts. Serve in bowls topped with the baked chicken.</li></ol><p><em>Serve with a fresh salad and grated Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('b78ac578-458f-5b3f-9e0e-27e2ff5a695e', '446e1749-695c-5575-a77a-1357c12ae2d8', 'ru', 'Курица с овощами на противне по-итальянски', 'Кусочки куриного филе с кабачком, болгарским перцем, брокколи и красным луком, запечённые с чесноком, орегано и лимоном.', '<ol><li>Разогрейте духовку до 200 °C. Нарежьте овощи и сложите в большую миску.</li><li>Добавьте куски курицы и чеснок, посолите, поперчите, всыпьте орегано, паприку и кориандр. Добавьте цедру и сок лимона, уксус и щедрую порцию оливкового масла, хорошо перемешайте.</li><li>Выложите курицу и овощи одним слоем на большой противень и запекайте около 20 минут до полной готовности курицы. Для румяной корочки на пару минут включите гриль.</li><li>По желанию посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте с хлебом или рисом; хорошо подходит для заготовки на несколько обедов.</em></p>', CURRENT_TIMESTAMP),
  ('b3f645d0-a657-52d4-b33f-1b8f357e4d78', '446e1749-695c-5575-a77a-1357c12ae2d8', 'en', 'Italian-style sheet pan chicken with vegetables', 'Bite-size chicken breast with zucchini, bell pepper, broccoli and red onion roasted with garlic, oregano and lemon.', '<ol><li>Heat the oven to 200 °C. Cut the vegetables and place them in a large bowl.</li><li>Add the chicken pieces and garlic, season with salt and pepper and add the oregano, paprika and coriander. Add the lemon zest and juice, vinegar and a generous drizzle of olive oil and toss well.</li><li>Spread the chicken and vegetables in one layer on a large sheet pan and bake for about 20 minutes until the chicken is cooked through. For more colour, grill briefly.</li><li>Garnish with parsley if you like.</li></ol><p><em>Sprinkle with parsley and serve with bread or rice; great for meal prep.</em></p>', CURRENT_TIMESTAMP),
  ('39fd8426-e051-5b64-823b-90b92ddb0378', '1de10c2f-85bd-5a0f-8d4a-f6267ca45582', 'ru', 'Запечённые тефтели с картофелем и перцем в томатном соусе', 'Говяжьи тефтели с петрушкой, мятой и пармезаном запекаются на одном противне с мелким картофелем, луком, перцем и томатами.', '<ol><li>Разогрейте духовку до 200 °C, поставьте решётку по центру.</li><li>В большой миске смешайте красный лук, четвертинки картофеля, перец брусочками, чеснок, орегано, соль и перец, добавьте 2 ст. л. оливкового масла и перемешайте. Выложите на слегка смазанный противень.</li><li>В той же миске смешайте фарш, мелко нарезанный лук, чеснок, петрушку, орегано, мяту, пармезан, сухари и яйцо. Посолите, поперчите, добавьте около 1 ст. л. масла и хорошо вымешайте. Скатайте шарики по 2,5 см и слегка придавите центр большим пальцем.</li><li>Выложите тефтели на противень к овощам, залейте всё томатами с соком, посолите и обильно сбрызните оливковым маслом.</li><li>Накройте противень фольгой и запекайте около 15 минут, затем снимите фольгу и запекайте ещё 4–5 минут до полной готовности тефтелей.</li></ol><p><em>Подавайте с хлебом или салатом из свежих овощей.</em></p>', CURRENT_TIMESTAMP),
  ('1cfbdf52-17bb-5969-934c-9b75ae80de11', '1de10c2f-85bd-5a0f-8d4a-f6267ca45582', 'en', 'Sheet pan baked meatballs with potatoes and peppers in tomato sauce', 'Beef meatballs with parsley, mint and Parmesan baked on one pan with baby potatoes, onion, peppers and tomatoes.', '<ol><li>Heat the oven to 200 °C and position a rack in the center.</li><li>In a large bowl combine the red onion, quartered potatoes, pepper batons, garlic, oregano, salt and pepper, add 2 tbsp olive oil and toss. Spread on a lightly oiled sheet pan.</li><li>In the same bowl combine the beef, finely chopped onion, garlic, parsley, oregano, mint, Parmesan, breadcrumbs and egg. Season, add about 1 tbsp of oil and mix well. Form 1-inch meatballs and lightly press the centre with your thumb.</li><li>Arrange the meatballs on the pan with the vegetables, pour the tomatoes with their juices over everything, season with salt and drizzle generously with olive oil.</li><li>Cover the pan with foil and bake for about 15 minutes, then uncover and bake for another 4–5 minutes until the meatballs are cooked through.</li></ol><p><em>Serve with bread or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('d6646e20-7c05-528d-bf4d-7278df44d2c9', 'fdc89c86-a96b-5935-ab01-134b4dfaa938', 'ru', 'Курица, тушёная с грибами, шалотом и инжиром в вине', 'Куриные бёдра в ароматной смеси специй, тушёные в духовке в соусе из вина, томатной пасты и шалота с шампиньонами и сушёным инжиром.', '<ol><li>Разогрейте духовку до 175 °C. Смешайте розмарин, паприку, кориандр, перец, душистый перец и мускатный орех.</li><li>Тщательно обсушите бёдра, посолите с двух сторон и натрите смесью специй, в том числе под кожей. Оставьте на 20 минут (или на 2 часа в холодильнике без крышки).</li><li>В большой жаровне или кастрюле с толстым дном на среднем и сильном огне разогрейте тонкий слой масла. Выложите курицу кожей вниз и жарьте 8 минут до золотистой корочки, затем 3 минуты с другой стороны. Переложите на тарелку.</li><li>Обжарьте шалот с чесноком 3 минуты. Добавьте томатную пасту, вино, бульон, лавровый лист, розмарин и щепотку соли, доведите до кипения и упарьте минут на 4.</li><li>Верните курицу в жидкость так, чтобы она покрывала примерно три четверти бёдер и оставляла кожу сверху. Добавьте инжир и доведите до кипения.</li><li>Поставьте в духовку без крышки на 40–45 минут, пока курица не станет совсем мягкой, а жидкость не уварится примерно наполовину. При необходимости подлейте горячий бульон или воду.</li><li>Тем временем обжарьте шампиньоны на масле на среднем и сильном огне около 7 минут до золотистого цвета и добавьте в сковороду за 10 минут до готовности.</li><li>Влейте лимонный сок, посыпьте петрушкой и подавайте, поливая соусом.</li></ol><p><em>Подавайте горячей с соусом из сковороды, пюре, рисом или кускусом.</em></p>', CURRENT_TIMESTAMP),
  ('9813984b-dc90-52bf-84cc-7f8844253c61', 'fdc89c86-a96b-5935-ab01-134b4dfaa938', 'en', 'Braised chicken thighs with mushrooms and dried figs', 'Spice-rubbed chicken thighs braised in the oven in a sauce of wine, tomato paste and shallots with mushrooms and dried figs.', '<ol><li>Preheat the oven to 175 °C. Mix the rosemary, paprika, coriander, pepper, allspice and nutmeg.</li><li>Pat the chicken very dry, salt both sides and rub with the spice mix, including under the skin. Leave for 20 minutes (or uncovered in the fridge for up to 2 hours).</li><li>Coat a large braiser or Dutch oven with a thin layer of olive oil over medium-high heat. Add the chicken skin side down and cook for 8 minutes until golden, then 3 minutes on the other side. Set aside.</li><li>Cook the shallots and garlic for 3 minutes. Add the tomato paste, wine, stock, bay leaves, rosemary and a pinch of salt, bring to a simmer and reduce for about 4 minutes.</li><li>Return the chicken to the pan so the liquid covers about three-quarters of the thighs, leaving the skin exposed. Add the figs and bring to a simmer.</li><li>Braise in the oven uncovered for 40–45 minutes until the chicken is tender and the liquid has reduced by about half, adding hot stock or water if needed.</li><li>Meanwhile saute the mushrooms in olive oil over medium-high heat for about 7 minutes until golden and add them to the pan for the last 10 minutes.</li><li>Finish with lemon juice and parsley and serve with the pan sauce spooned over the top.</li></ol><p><em>Serve hot with the pan sauce over mash, rice or couscous.</em></p>', CURRENT_TIMESTAMP),
  ('952bc5e1-e048-50e4-b56c-b82635e5acd1', '51ded73a-3a5a-5f32-bc15-1b4b6d4e4f72', 'ru', 'Вегетарианская мусака с чечевицей и соусом бешамель', 'Слои запечённых баклажанов, картофеля и кабачков с томатно-чечевичным соусом под нежным бешамелем.', '<ol><li>Разогрейте духовку до 200 °C. Баклажаны частично очистите и нарежьте вдоль ломтиками, выложите на бумажное полотенце, посолите и оставьте на 20–30 минут, затем промокните.</li><li>Бешамель: в кастрюле на среднем и сильном огне разогрейте масло, всыпьте муку, соль и перец и прогрейте до золотистого цвета. Понемногу влейте тёплое молоко, постоянно взбивая, и варите 5–7 минут. Добавьте мускатный орех.</li><li>Взбейте яйца с небольшим количеством горячего соуса, верните в кастрюлю и доведите до слабого кипения, постоянно взбивая, ещё на 2 минуты. Снимите с огня, остудите и дайте загустеть.</li><li>Соус: разогрейте ложку масла, 3–4 минуты обжарьте лук и чеснок. Добавьте отваренную чечевицу, томаты и бульон или воду, посолите, добавьте орегано, мускатный орех и щепотку корицы. Доведите до кипения, убавьте огонь, накройте не полностью и варите 15–20 минут.</li><li>Выложите ломтики картофеля, кабачков и баклажанов на смазанные противни, смажьте оливковым маслом и запекайте 15–20 минут до мягкости.</li><li>Соберите мусаку: на дно формы вылейте немного чечевичного соуса, сверху уложите овощи, затем остальной соус и в конце ровным слоем бешамель.</li><li>Запекайте на средней полке 45 минут до золотистого бешамеля (при необходимости ненадолго включите гриль). Дайте постоять не менее 20 минут и нарежьте на 12 квадратов.</li></ol><p><em>Дайте остыть минимум 20 минут перед нарезкой на 12 порций и подавайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('634f92cd-f0ab-502b-b7e0-1b255470b5fe', '51ded73a-3a5a-5f32-bc15-1b4b6d4e4f72', 'en', 'Vegetarian moussaka with lentils and béchamel', 'Layers of roasted eggplant, potatoes and zucchini with a chunky tomato-lentil sauce under a creamy béchamel.', '<ol><li>Heat the oven to 200 °C. Partially peel the eggplants and slice lengthwise, spread on paper towels, sprinkle with salt and leave for 20–30 minutes, then pat dry.</li><li>Béchamel: heat the oil in a saucepan over medium-high heat, stir in the flour, salt and pepper and cook until golden. Gradually whisk in the warmed milk and cook for 5–7 minutes. Add the nutmeg.</li><li>Whisk the eggs with a little of the hot sauce, return to the pan and bring to a gentle boil, whisking, for 2 minutes more. Remove from the heat and let it cool and thicken.</li><li>Sauce: heat a tablespoon of oil and cook the onion and garlic for 3–4 minutes. Stir in the cooked lentils, tomatoes and stock or water, season, and add oregano, nutmeg and a pinch of cinnamon. Bring to a boil, lower the heat, partially cover and simmer for 15–20 minutes.</li><li>Arrange the sliced potatoes, zucchini and eggplant on lightly oiled baking sheets, brush with olive oil and bake for 15–20 minutes until tender.</li><li>Assemble: spread a little lentil sauce in the baking dish, layer the vegetables on top, add the rest of the sauce and finish with an even layer of béchamel.</li><li>Bake on the middle rack for 45 minutes until the béchamel is golden (briefly grill if needed). Let it rest for at least 20 minutes and cut into 12 squares.</li></ol><p><em>Let it rest for at least 20 minutes before cutting into 12 pieces and serve with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('e5b7ba21-e620-5465-a22d-4eacab4794e6', '59c72bc5-cb79-55f3-8325-f734cd36edac', 'ru', 'Огуречный салат с редисом, шалотом и укропом', 'Свежий салат из огурцов, редиса и шалота с укропом и лёгкой лимонно-винной заправкой на оливковом масле.', '<ol><li>Нарежьте огурцы кружочками, добавьте тонко нарезанные шалот и редис и рубленый укроп в большую миску.</li><li>В маленькой миске или банке взбейте (или встряхните) оливковое масло, винный уксус, лимонный сок, орегано, соль и перец.</li><li>Полейте салат заправкой и хорошо перемешайте.</li></ol><p><em>Хорошо подходит к жареному мясу, рыбе и птице.</em></p>', CURRENT_TIMESTAMP),
  ('a886982f-9243-5562-adbc-c498617d0394', '59c72bc5-cb79-55f3-8325-f734cd36edac', 'en', 'Cucumber, radish, shallot and dill salad', 'A fresh salad of cucumbers, radishes and shallots with dill and a light lemon-vinegar olive oil dressing.', '<ol><li>Place the sliced cucumbers, thinly sliced shallots and radishes and chopped dill in a large bowl.</li><li>In a small bowl or jar whisk (or shake) the olive oil, vinegar, lemon juice, oregano, salt and pepper.</li><li>Pour the dressing over the salad and toss until well coated.</li></ol><p><em>Great with grilled meat, fish and poultry.</em></p>', CURRENT_TIMESTAMP),
  ('8654bae5-fcde-5e91-8d02-7271ea61aeae', '05b2dab8-1e3d-5027-9b1d-784a71513cff', 'ru', 'Овощной суп минестроне с фасолью и пастой', 'Классический итальянский постный суп: овощи с томатной пастой и травами, консервированные томаты, белая фасоль, мелкая паста и зелень. Без сыра он ещё и веганский.', '<ol><li>В большой жаровне или кастрюле на среднем огне разогрейте 3 ст. л. оливкового масла. Добавьте лук, морковь, сельдерей, томатную пасту и щепотку соли. Готовьте, часто помешивая, 7–10 минут, пока овощи не смягчатся, а лук не станет прозрачным.</li><li>Добавьте сезонные овощи (у нас картофель), чеснок, орегано и тимьян и готовьте около 2 минут, часто помешивая, до аромата.</li><li>Влейте томаты с соком, бульон и воду. Добавьте соль, лавровый лист, хлопья красного перца и щедро свежемолотого перца.</li><li>Сделайте огонь средне-сильным и доведите до кипения. Накройте крышкой, оставив щель около 2,5 см для пара, и убавьте огонь, чтобы суп слабо кипел. Варите 15 минут.</li><li>Снимите крышку, добавьте пасту, фасоль и зелень. Продолжайте варить без крышки около 20 минут, пока паста не станет «аль денте», а зелень не станет мягкой.</li><li>Снимите с огня, выньте лавровый лист, добавьте лимонный сок и оставшуюся ложку масла. Попробуйте и при необходимости досолите и поперчите. Разлейте по тарелкам и посыпьте пармезаном, если хотите.</li></ol><p><em>Посыпьте тёртым пармезаном по желанию. Хорошо хранится и замораживается.</em></p>', CURRENT_TIMESTAMP),
  ('0c5f4972-1450-5b6b-9872-3735bd4ffe44', '05b2dab8-1e3d-5027-9b1d-784a71513cff', 'en', 'Classic vegetarian minestrone with beans and pasta', 'A classic Italian meatless soup: vegetables with tomato paste and herbs, canned tomatoes, white beans, small pasta and greens. Vegan too if you skip the cheese.', '<ol><li>Warm 3 tbsp of the olive oil in a large Dutch oven or stockpot over medium heat. Add the onion, carrot, celery, tomato paste and a pinch of salt. Cook, stirring often, 7-10 minutes until the vegetables soften and the onion turns translucent.</li><li>Add the seasonal vegetables (potatoes here), garlic, oregano and thyme and cook about 2 minutes, stirring often, until fragrant.</li><li>Pour in the diced tomatoes with their juices, the broth and water. Add the salt, bay leaves and red pepper flakes and plenty of freshly ground pepper.</li><li>Raise the heat to medium-high and bring to a boil, then partly cover the pot, leaving a 1 inch gap for steam, and reduce the heat to keep a gentle simmer. Cook 15 minutes.</li><li>Remove the lid and add the pasta, beans and greens. Keep simmering uncovered about 20 minutes until the pasta is al dente and the greens are tender.</li><li>Remove from the heat and take out the bay leaves. Stir in the lemon juice and remaining tablespoon of olive oil. Taste and adjust the salt and pepper. Garnish bowls with grated Parmesan if you like.</li></ol><p><em>Top with grated Parmesan if you like. Keeps well and freezes.</em></p>', CURRENT_TIMESTAMP),
  ('0b7c845a-625f-588d-9242-13a2df61216e', '68e11979-1c1e-57d9-8b1a-d76f7de566cf', 'ru', 'Быстрый дал макхани из чечевицы и красной фасоли', 'Густое пряное индийское блюдо из чечевицы и красной фасоли с томатами, имбирём, чесноком и гарам масалой. Часть блюда пробивают блендером, чтобы получить сливочную текстуру без сливок.', '<ol><li>В большой кастрюле на средне-сильном огне разогрейте масло. Обжаривайте лук, чеснок, имбирь и халапеньо 4–6 минут, иногда помешивая, до мягкости.</li><li>Добавьте гарам масалу, зиру, кориандр и соль, щедро поперчите. Жарьте, помешивая, 1 минуту.</li><li>Добавьте томаты и готовьте ещё минуту. Добавьте чечевицу, фасоль, воду и лавровый лист. Доведите до кипения на средне-сильном огне, убавьте до средне-слабого и варите около 35 минут, иногда помешивая, пока чечевица не станет мягкой.</li><li>Выньте лавровый лист. Переложите 2 стакана смеси (вместе с жидкостью) в блендер, плотно закройте крышку и взбейте до гладкости около минуты, осторожно: пар горячий.</li><li>Верните пюре в кастрюлю и перемешайте. Добавьте сок лайма, посолите и поперчите по вкусу. Для большей сливочности можно влить немного кокосового молока.</li><li>Подавайте в тарелках с кинзой и долькой лайма, при желании с рисом или лепёшкой. В холодильнике хранится до 5 дней.</li></ol><p><em>Подавайте с кинзой и долькой лайма, с рисом басмати или лепёшкой.</em></p>', CURRENT_TIMESTAMP),
  ('aadc52bc-3a2c-5859-988b-48bb1c030e7c', '68e11979-1c1e-57d9-8b1a-d76f7de566cf', 'en', 'Quick dal makhani with lentils and kidney beans', 'A thick spiced Indian dish of lentils and kidney beans with tomatoes, ginger, garlic and garam masala. A portion is blended to make it creamy without cream.', '<ol><li>In a large pot over medium-high heat warm the oil until shimmering. Cook the onion, garlic, ginger and jalapeño, stirring occasionally, about 4-6 minutes until soft.</li><li>Stir in the garam masala, cumin, coriander and salt and season generously with pepper. Cook, stirring, for 1 minute.</li><li>Add the tomatoes and cook 1 more minute. Add the lentils, kidney beans, water and bay leaf. Bring to a simmer over medium-high, reduce to medium-low and simmer about 35 minutes, stirring occasionally, until the lentils are tender.</li><li>Remove the bay leaf. Transfer 2 cups of the mixture (with some liquid) to a blender, fasten the lid securely and blend until smooth, about 1 minute, avoiding the hot steam.</li><li>Return the blended mixture to the pot and stir. Add the lime juice and season to taste with salt and pepper. For extra creaminess stir in a splash of coconut milk.</li><li>Serve in bowls with chopped cilantro and a lime wedge, with rice or naan on the side if you like. Keeps in the fridge up to 5 days.</li></ol><p><em>Serve topped with cilantro and a lime wedge, with basmati rice or naan.</em></p>', CURRENT_TIMESTAMP),
  ('a3cd6f4d-543b-52dd-906c-4c3dd1dfe336', '2e7de8fb-ad1f-5f4c-bbd1-ef6f129af93a', 'ru', 'Запечённый хрустящий фалафель из нута с зеленью', 'Фалафель из замоченного сырого нута, петрушки, кинзы, чеснока и специй, который запекают в духовке на оливковом масле до глубокой золотистой корочки. В порции 3 штуки.', '<ol><li>Заранее замочите сухой нут в холодной воде не менее чем на 4 часа, лучше на ночь в холодильнике. Затем слейте воду.</li><li>Разогрейте духовку до 190 °C с решёткой в середине. Налейте ¼ стакана оливкового масла на большой противень с бортиками и покрутите, чтобы масло покрыло дно.</li><li>В кухонном комбайне измельчите замоченный нут, лук, петрушку, кинзу, чеснок, соль, перец, зиру, корицу и оставшуюся ложку масла до гладкости, около минуты.</li><li>Берите руками по 2 ст. л. смеси и формуйте небольшие лепёшки диаметром около 5 см и толщиной 1,3 см. Выкладывайте на смазанный маслом противень.</li><li>Запекайте 25–30 минут, перевернув на середине, до глубокого золотистого цвета с обеих сторон. В холодильнике фалафель хранится до 4 дней, в морозилке несколько месяцев.</li></ol><p><em>Подавайте в питах с хумусом, овощами и тахини или с салатом.</em></p>', CURRENT_TIMESTAMP),
  ('373db927-9b98-5dbe-b669-fa39f9589523', '2e7de8fb-ad1f-5f4c-bbd1-ef6f129af93a', 'en', 'Crispy baked falafel with chickpeas and herbs', 'Falafel made from soaked raw chickpeas, parsley, cilantro, garlic and spices, baked in olive oil until deeply golden. A serving is 3 falafels.', '<ol><li>Ahead of time, soak the dried chickpeas in cold water for at least 4 hours, preferably overnight in the fridge, then drain.</li><li>Preheat the oven to 190 °C (375 °F) with a rack in the middle. Pour ¼ cup of the olive oil onto a large rimmed baking sheet and tilt to coat the bottom.</li><li>In a food processor combine the soaked chickpeas, onion, parsley, cilantro, garlic, salt, pepper, cumin, cinnamon and the remaining 1 tbsp olive oil and process until smooth, about 1 minute.</li><li>Using your hands, scoop about 2 tbsp of mixture at a time and shape into small patties about 2 inches wide and ½ inch thick. Place each on the oiled pan.</li><li>Bake 25-30 minutes, carefully flipping halfway, until deeply golden on both sides. Falafel keeps in the fridge up to 4 days or the freezer for several months.</li></ol><p><em>Serve in pita with hummus, vegetables and tahini sauce or alongside a salad.</em></p>', CURRENT_TIMESTAMP),
  ('be766536-39b4-5514-bd1c-fc5b525dca7c', '198d8458-33c8-5425-939b-ef0baa36f514', 'ru', 'Жареный рис с овощами и яйцом из бурого риса', 'Простой сытный ужин: бурый рис, обжаренный с морковью, луком, брокколи, горошком, яйцом, имбирём и чесноком, с соевым соусом и кунжутным маслом в конце.', '<ol><li>Заранее подготовьте все ингредиенты и поставьте рядом с плитой, а также пустую миску для готовых яиц и овощей. Начинайте на средне-сильном огне, а если почувствуете запах гари, убавьте огонь.</li><li>Разогрейте большую чугунную или стальную сковороду на средне-сильном огне, пока капли воды не будут испаряться за пару секунд. Влейте 1½ ч. л. масла, покрутите, влейте взбитые яйца и распределите по дну. Готовьте, помешивая или переворачивая, пока яйца слегка не схватятся. Переложите в миску, сковороду вытрите.</li><li>Верните сковороду на огонь, влейте 1 ст. л. масла, добавьте лук и морковь и готовьте, часто помешивая, 3–5 минут, пока лук не станет прозрачным, а морковь мягкой.</li><li>Добавьте остальные овощи и соль. Продолжайте готовить, помешивая не слишком часто, чтобы овощи подрумянились по краям, ещё 3–5 минут. Разбейте яйца в миске на мелкие кусочки.</li><li>Переложите содержимое сковороды к яйцам. Верните сковороду на огонь, добавьте оставшуюся 1 ст. л. масла, имбирь, чеснок и хлопья перца, готовьте около 30 секунд, постоянно помешивая. Добавьте рис, перемешайте и готовьте 3–5 минут, пока рис не прогреется и не начнёт золотиться по краям.</li><li>Добавьте зелень и зелёный лук, затем вернуть овощи с яйцами и перемешать. Снимите с огня, добавьте соевый соус и кунжутное масло. Попробуйте и при необходимости добавьте соли или соуса. Разложите по тарелкам и сразу подавайте.</li></ol><p><em>Подавайте сразу, по желанию с соусом чили или шрирача.</em></p>', CURRENT_TIMESTAMP),
  ('5107c5c0-614e-5aea-95e3-1c061d28739c', '198d8458-33c8-5425-939b-ef0baa36f514', 'en', 'Extra vegetable fried rice with brown rice and egg', 'A simple, satisfying dinner of brown rice stir-fried with carrots, onion, broccoli, peas, egg, ginger and garlic and finished with soy sauce and sesame oil.', '<ol><li>Prep all the ingredients and keep them within reach of the stove, with an empty bowl for the cooked eggs and vegetables. Start over medium-high heat and reduce to medium if you smell anything burning.</li><li>Warm a large cast iron or stainless skillet over medium-high until drops of water evaporate within a couple of seconds. Add 1½ tsp oil, swirl, add the whisked eggs and swirl to cover the bottom. Cook, flipping or stirring, until just lightly set. Transfer to a bowl and wipe out the pan.</li><li>Return the pan to the heat, add 1 tbsp oil, then the onion and carrots and cook, stirring often, 3-5 minutes until the onion is translucent and the carrots tender.</li><li>Add the remaining vegetables and the salt. Keep cooking, stirring occasionally (not too often, so the edges turn golden), 3-5 more minutes. Meanwhile break the scrambled eggs into smaller pieces.</li><li>Move the contents of the pan to the bowl with the eggs. Return the pan to the heat with the remaining 1 tbsp oil, add the ginger, garlic and red pepper flakes and stir constantly about 30 seconds. Add the rice and mix; cook, stirring occasionally, 3-5 minutes until hot and golden on the edges.</li><li>Add the greens and green onions, then the cooked vegetables and eggs, and stir to combine. Remove from the heat and stir in the soy sauce and sesame oil. Taste and add a little more soy sauce or salt if needed. Divide into bowls and serve immediately.</li></ol><p><em>Serve right away, with chili-garlic sauce or sriracha if you like.</em></p>', CURRENT_TIMESTAMP),
  ('f9c194af-5f00-50fc-96c7-855854b8cc32', '2928e0cc-9fd0-55be-afdc-889b0d397e45', 'ru', 'Паста с запечёнными черри, нутом и козьим сыром', 'Паста с запечёнными помидорами черри, нутом, чесноком, козьим сыром, оливками и свежим базиликом. Свежие средиземноморские вкусы, лёгкий вегетарианский ужин.', '<ol><li>Разогрейте духовку до 220 °C, решётку поставьте в верхнюю треть. Сварите пасту в подсоленной воде до готовности по инструкции, слейте воду и хорошо промойте холодной водой.</li><li>Положите козий сыр в центр формы 23 × 33 см, в уголок сложите зубчики чеснока. Вокруг сыра выложите нут, помидоры и оливки (в таком порядке), полейте оливковым маслом, посыпьте солью, перцем и хлопьями перца.</li><li>Запекайте 20 минут на верхней решётке, достаньте форму, осторожно размешайте козий сыр с помидорами и утопите чеснок на дно.</li><li>Верните в духовку ещё на 12–15 минут, пока помидоры не станут сочными и сморщенными, а сыр не начнёт золотиться сверху.</li><li>Достаньте форму, найдите вилкой четыре зубчика чеснока и раздавите о стенку формы. Осторожно перемешайте сыр с помидорами и переложите всё к пасте. Попробуйте, при необходимости досолите, посыпьте базиликом.</li></ol><p><em>Подавайте тёплой или остудите до комнатной температуры. В холодильнике хранится до 4 дней.</em></p>', CURRENT_TIMESTAMP),
  ('0e197ce4-0a95-5f37-afc2-13364c4ed31c', '2928e0cc-9fd0-55be-afdc-889b0d397e45', 'en', 'Pasta with roasted cherry tomatoes, chickpeas and goat cheese', 'Pasta tossed with roasted cherry tomatoes, chickpeas, garlic, goat cheese, olives and fresh basil. Fresh Mediterranean flavors for an easy vegetarian dinner.', '<ol><li>Preheat the oven to 220 °C (425 °F) with a rack in the upper third. Bring a large pot of salted water to a boil, cook the pasta until tender per package directions, drain and rinse well with cool water.</li><li>Place the goat cheese in the center of a 9 × 13 inch baking dish and arrange the garlic cloves in one corner. Add the chickpeas, tomatoes and olives around the cheese, in that order, drizzle with the olive oil and sprinkle with salt, pepper and red pepper flakes.</li><li>Bake 20 minutes on the upper rack, then take the dish out, gently stir the goat cheese into the tomatoes and tuck the garlic cloves back down.</li><li>Return to the oven for 12-15 more minutes until the tomatoes are juicy and shriveling and the cheese starts to turn golden on top.</li><li>Take the dish out, find the four garlic cloves with a fork and smash each against the side of the pan. Gently swirl the cheese and tomatoes together and transfer to the pasta. Taste, add salt if needed and sprinkle with basil.</li></ol><p><em>Serve warm or let cool to room temperature. Keeps up to 4 days in the fridge.</em></p>', CURRENT_TIMESTAMP),
  ('194e93fd-2b25-50f1-b968-17a7bce781a6', '8483e61e-6e8c-5f20-bfb7-808eb7a4791c', 'ru', 'Запечённая белая рыба в томатном соусе с каперсами и изюмом', 'Филе трески или палтуса, запечённое под ароматным соусом из помидоров, чеснока, каперсов и золотистого изюма с лимонной цедрой.', '<ol><li>Для соуса разогрейте в кастрюле оливковое масло на среднем и сильном огне, добавьте мелко нарезанный лук и 3 минуты обжаривайте до золотистого цвета.</li><li>Добавьте помидоры, чеснок, кориандр, паприку, зиру, кайенский перец, каперсы, изюм, немного соли и перца. Доведите до кипения, убавьте огонь до средне-слабого и варите около 15 минут.</li><li>Разогрейте духовку до 200 °C. Обсушите рыбу и посолите и поперчите с двух сторон.</li><li>Половину соуса вылейте на дно формы примерно 24×33 см, выложите рыбу, сбрызните лимонным соком, посыпьте цедрой и накройте остатками соуса.</li><li>Запекайте 15–18 минут, пока рыба не будет готова и не начнёт распадаться на хлопья (не пересушивайте). Посыпьте петрушкой или мятой.</li></ol><p><em>Подавайте горячей с рисом, жареными кабачками или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('95238e8c-aab8-525f-91cf-1b229341a6cd', '8483e61e-6e8c-5f20-bfb7-808eb7a4791c', 'en', 'Baked white fish in tomato-caper sauce with raisins', 'Cod or halibut fillets baked under a fragrant sauce of tomatoes, garlic, capers and golden raisins with lemon zest.', '<ol><li>For the sauce heat the olive oil in a saucepan over medium-high heat, add the finely chopped onion and cook for 3 minutes until golden.</li><li>Add the tomatoes, garlic, coriander, paprika, cumin, cayenne, capers, raisins, a little salt and pepper. Bring to a boil, lower to medium-low and simmer for about 15 minutes.</li><li>Heat the oven to 200 °C. Pat the fish dry and season both sides with salt and pepper.</li><li>Pour half of the sauce into a 24×33 cm baking dish, arrange the fish on top, add the lemon juice and zest and cover with the remaining sauce.</li><li>Bake for 15–18 minutes until the fish is cooked and flakes easily (do not overcook). Garnish with parsley or mint.</li></ol><p><em>Serve hot with rice, grilled zucchini or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('3b08e626-21eb-5440-ae10-3729eb1bd461', 'b6831952-88f1-56e5-8a78-4a5d3f86f8be', 'ru', 'Фаршированные кабачки и помидоры с рисом и говядиной', 'Кабачки и помидоры, начинённые мясом с рисом, зеленью и душистым перцем и тушёные в томатном соусе.', '<ol><li>Смешайте руками в большой миске начинку: промытый рис, фарш, тёртый лук, петрушку, укроп, резаные томаты с соком, воду, оливковое масло, душистый перец, чесночный порошок, соль и перец.</li><li>У трёх помидоров срежьте верхушки и удалите сердцевину, чтобы освободить место для начинки.</li><li>Кабачки слегка очистите, срежьте кончики и разрежьте каждый пополам. Специальным ножом-выемкой или ложкой выньте мякоть, не прорывая дна, оставляя стенки около 6 мм.</li><li>Смажьте дно глубокой кастрюли маслом, выложите нарезанный четвёртый помидор, кольца лука и сердцевину кабачков. Слегка посолите и поперчите.</li><li>Аккуратно наполните помидоры начинкой, кабачки начиняйте неплотно, примерно на три четверти (рис разбухает). Поставьте помидоры в центр кастрюли, а кабачки вокруг, слегка наклонив.</li><li>Влейте томатный соус и воду, слегка посолите и поперчите. Доведите до кипения на среднем и сильном огне, затем убавьте огонь, накройте крышкой и тушите около 50 минут, пока кабачки не станут мягкими, а рис не приготовится.</li><li>Выложите на блюдо или в тарелки и полейте соусом из кастрюли.</li></ol><p><em>Подавайте горячими, полив соусом из кастрюли.</em></p>', CURRENT_TIMESTAMP),
  ('d9ca7425-6449-588b-a1bb-6bb41007556d', 'b6831952-88f1-56e5-8a78-4a5d3f86f8be', 'en', 'Stuffed zucchini and tomatoes with rice and beef', 'Zucchini and tomatoes filled with a spiced rice and beef mixture with fresh herbs and simmered in tomato sauce.', '<ol><li>In a large bowl mix by hand the stuffing: rinsed rice, ground beef, shredded onion, parsley, dill, diced tomatoes with juice, water, olive oil, allspice, garlic powder, salt and pepper.</li><li>Cut the tops off three tomatoes and core them to make room for the stuffing.</li><li>Lightly peel the zucchini, trim the ends and halve each one. Using a corer or spoon hollow them out without piercing the bottom, leaving a rim of about 6 mm.</li><li>Lightly oil the bottom of a large deep pan, spread the sliced fourth tomato, the onion rounds and the zucchini cores over it and season lightly.</li><li>Gently fill the tomatoes with the stuffing, and loosely fill the zucchini about three-quarters full since the rice swells. Put the tomatoes in the centre of the pan and the zucchini around them, slightly tilted.</li><li>Pour in the tomato sauce and water and season lightly. Bring to a boil over medium-high heat, then lower the heat, cover and simmer for about 50 minutes until the zucchini is tender and the rice is cooked.</li><li>Transfer to a platter or bowls and spoon the sauce over the top.</li></ol><p><em>Serve hot, spooning the sauce from the pan over the top.</em></p>', CURRENT_TIMESTAMP),
  ('0fe3c209-7948-5270-b28a-664ed8f40284', '97939a43-1b38-5ad5-9ebd-8eff4a5b4dd1', 'ru', 'Орзо с кабачком, нутом и томатами', 'Паста орзо в густом чесночном томатном соусе с кабачком и нутом, с мятой и поджаренными кедровыми орешками.', '<ol><li>Отварите орзо в подсоленной воде по инструкции (около 9 минут). Слейте воду, оставив полстакана отвара.</li><li>В большой сковороде с толстым дном разогрейте 4 ст. л. оливкового масла и около 5 минут обжаривайте кабачок, слегка посолив.</li><li>Добавьте чеснок, помидоры, нут, специи и отвар от пасты. Перемешайте, доведите до кипения на 5 минут, затем убавьте огонь, накройте и тушите 10–15 минут, при необходимости подливая жидкость.</li><li>Откройте крышку, вмешайте готовое орзо и лимонный сок и прогрейте 1–2 минуты.</li><li>Снимите с огня, добавьте мяту и щедро посыпьте обжаренными кедровыми орешками.</li></ol><p><em>Подавайте как вегетарианское основное блюдо или гарнир к мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('766dcbf3-43cf-5765-9a19-5841f52418aa', '97939a43-1b38-5ad5-9ebd-8eff4a5b4dd1', 'en', 'Orzo with zucchini, chickpeas and tomato sauce', 'Orzo pasta in a chunky garlicky tomato sauce with zucchini and chickpeas, finished with mint and toasted pine nuts.', '<ol><li>Cook the orzo in salted boiling water according to the package (about 9 minutes). Drain, keeping about 1/2 cup of the cooking water.</li><li>In a large heavy pan heat 4 tbsp of olive oil and saute the zucchini for about 5 minutes with a little salt.</li><li>Add the garlic, tomatoes, chickpeas, spices and the reserved pasta water. Stir, boil for 5 minutes, then lower the heat, cover and simmer for 10–15 minutes, adding liquid if needed.</li><li>Uncover, stir in the cooked orzo and lemon juice and warm through for a minute or two.</li><li>Remove from the heat, stir in the mint and top with plenty of toasted pine nuts.</li></ol><p><em>Serve as a vegetarian main or a side next to your favourite protein.</em></p>', CURRENT_TIMESTAMP),
  ('503f8cbf-15a9-5795-859b-93744bb21572', '67107eba-f7a0-5215-bc1c-93b5c1238275', 'ru', 'Ливанские тефтели с корицей в томатном соусе', 'Нежные говяжьи тефтели с корицей, душистым перцем и кардамоном, тушёные в соусе из томатов, лука и моркови.', '<ol><li>Разогрейте духовку до 190 °C и застелите противень пергаментом.</li><li>Подсушите тост до золотистого цвета, залейте молоком и оставьте на 15 минут, затем хорошо отожмите.</li><li>В большой миске руками перемешайте хлеб, говяжий фарш, яйцо, тёртый лук, чеснок, петрушку, корицу, душистый перец, кардамон, перец чили, соль и перец.</li><li>Скатайте шарики размером с столовую ложку, разложите в один слой на противне и запекайте 11–14 минут. Они могут быть ещё не готовы внутри.</li><li>Для соуса разогрейте 2 ст. л. масла в глубокой сковороде, 4–5 минут обжаривайте тёртый лук до золотистого цвета, добавьте чеснок на 30 секунд.</li><li>Добавьте тёртую морковь, измельчённые томаты, воду, гранатовый соус (по желанию), лавровый лист, корицу, душистый перец, соль, перец и хлопья чили. Кипятите около 5 минут, затем убавьте огонь.</li><li>Положите тефтели в соус, накройте крышкой и тушите около 20 минут до полной готовности. По желанию посыпьте петрушкой.</li></ol><p><em>Подавайте с рисом или тёплой лепёшкой пита и салатом из свежих овощей.</em></p>', CURRENT_TIMESTAMP),
  ('f07a969e-ce5a-5c65-940b-9e1a370d2afc', '67107eba-f7a0-5215-bc1c-93b5c1238275', 'en', 'Lebanese cinnamon meatballs in tomato sauce', 'Tender beef meatballs with cinnamon, allspice and cardamom braised in a tomato, onion and carrot sauce.', '<ol><li>Preheat the oven to 190 °C and line a baking sheet with parchment.</li><li>Toast the bread until golden, cover with the milk and let it soak for about 15 minutes until very soft, then squeeze out the milk.</li><li>In a large bowl knead together the bread, ground beef, egg, grated onion, garlic, parsley, cinnamon, allspice, cardamom, chilli, salt and pepper.</li><li>Form tablespoon-size meatballs, arrange in one layer on the baking sheet and bake for 11–14 minutes. They do not need to be fully cooked yet.</li><li>For the sauce heat 2 tbsp olive oil in a deep pan, cook the grated onion for 4–5 minutes until golden, then add the garlic for 30 seconds.</li><li>Add the grated carrot, crushed tomatoes, water, pomegranate molasses (optional), bay leaves, cinnamon, allspice, salt, pepper and chilli flakes. Boil for about 5 minutes, then lower the heat.</li><li>Add the meatballs to the sauce, cover and simmer for about 20 minutes until cooked through. Garnish with parsley if you like.</li></ol><p><em>Serve with rice or warm pita and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('a196d596-b95a-5262-9bcd-7780f36289ae', '49b8df04-c4f5-579a-bb70-ee66e455b7aa', 'ru', 'Шотландский суп из красной чечевицы с овощами', 'Густой постный суп из красной чечевицы, моркови, лука, брюквы и картофеля на овощном бульоне. Чечевица разваривается и придаёт супу плотность.', '<ol><li>Влейте бульон в большую кастрюлю, добавьте морковь, лук, брюкву и чечевицу. Посолите и поперчите, доведите до кипения и варите на среднем огне около 40 минут.</li><li>Добавьте картофель и варите ещё 20 минут, пока картофель не станет мягким, а чечевица не развалится.</li><li>Попробуйте и при необходимости досолите. Посыпьте рубленой петрушкой и подавайте с хрустящим хлебом.</li></ol><p><em>Посыпьте петрушкой и подавайте с хрустящим хлебом. Для сытности можно добавить варёную ветчинную рульку.</em></p>', CURRENT_TIMESTAMP),
  ('c17e11cb-4482-5df8-bbce-15a1f1946b91', '49b8df04-c4f5-579a-bb70-ee66e455b7aa', 'en', 'Scottish red lentil and vegetable soup', 'A thick meatless soup of red lentils, carrots, onion, swede and potatoes in vegetable stock. The lentils collapse and give the soup body.', '<ol><li>Pour the stock into a large saucepan with the carrots, onion, swede and lentils. Season well and simmer over medium heat for about 40 minutes.</li><li>Add the potatoes and cook a further 20 minutes until the potatoes are cooked through and the lentils have collapsed.</li><li>Season to taste, scatter with chopped parsley and serve with crusty bread.</li></ol><p><em>Sprinkle with parsley and serve with crusty bread. For a heartier soup add cooked ham hock.</em></p>', CURRENT_TIMESTAMP),
  ('5f707b5a-97fb-5b4a-983a-5061ac31fb07', '3f928f3e-ebe6-5b04-a1d5-946fa692fe88', 'ru', 'Белая рыба с картофелем, перцем и помидорами черри на противне', 'Простое семейное блюдо на одном противне: картофель, лук, сладкий перец, томаты и филе белой рыбы с травами и лимоном. Мало жира, хорошо подходит для будней.', '<ol><li>Разогрейте духовку до 200 °C (180 °C с конвекцией). Положите картофель в жаропрочную форму, полейте 1 ст. л. масла и запекайте 20 минут.</li><li>Добавьте лук и перцы, перемешайте, посолите и поперчите, добавьте травы и полейте ещё 1 ст. л. масла. Запекайте 15 минут.</li><li>Вмешайте консервированные помидоры, сверху разложите свежие черри. Утопите в овощах филе рыбы, полейте оставшимся маслом, посолите, поперчите и выложите сверху ломтики лимона.</li><li>Запекайте ещё 15–20 минут, пока рыба не будет готова. Подавайте с дольками лимона.</li></ol><p><em>Подавайте с дольками лимона, чтобы сбрызнуть рыбу.</em></p>', CURRENT_TIMESTAMP),
  ('23092cdf-ee69-5641-9278-1a9f200912c3', '3f928f3e-ebe6-5b04-a1d5-946fa692fe88', 'en', 'White fish traybake with potatoes, peppers and cherry tomatoes', 'An easy one-tray family meal of potatoes, onion, sweet peppers, tomatoes and white fish fillets with herbs and lemon. Low in fat and great for weeknights.', '<ol><li>Heat the oven to 200 °C (180 °C fan). Tip the potatoes into an ovenproof dish, drizzle over 1 tbsp oil and cook 20 minutes.</li><li>Add the onion and peppers, mix, season well, add the herbs and drizzle with another 1 tbsp oil. Cook 15 minutes.</li><li>Stir in the canned tomatoes and dot the fresh tomatoes on top. Nestle in the fish, drizzle over the remaining oil, season and lay the lemon slices over the fish.</li><li>Cook a further 15-20 minutes until the fish is cooked through. Serve with lemon wedges for squeezing over.</li></ol><p><em>Serve with lemon wedges for squeezing over the fish.</em></p>', CURRENT_TIMESTAMP),
  ('44bf5aab-ee18-5158-8f63-42dd9efaaaec', '994efa5f-bb32-5740-9704-21d630155e9e', 'ru', 'Картофельный крем-суп со сметаной', 'Нежный суп-пюре из картофеля, лука и чеснока на бульоне и молоке, с небольшим количеством муки и сметаной. Готовится за полчаса.', '<ol><li>Растопите в большой кастрюле на среднем огне сливочное масло с растительным и обжаривайте лук 8 минут до мягкости. Добавьте чеснок и муку и жарьте ещё 15 секунд до аромата.</li><li>Влейте горячий бульон и молоко. Когда закипит, добавьте картофель, накройте крышкой и варите 15 минут, пока картофель не станет мягким и легко не прокалывается ножом.</li><li>Добавьте сметану, посолите и поперчите. Пробейте суп погружным блендером до гладкости. Подавайте со сметаной, перцем и шнитт-луком.</li></ol><p><em>Подавайте со сметаной, чёрным перцем и рубленым шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('14a3985a-55dd-55b0-83c0-b90c972195b9', '994efa5f-bb32-5740-9704-21d630155e9e', 'en', 'Creamy potato soup with soured cream', 'A smooth puréed soup of potatoes, onion and garlic in stock and milk, thickened lightly with flour and enriched with soured cream. Ready in half an hour.', '<ol><li>Heat the butter and oil in a large saucepan over medium heat and fry the onions for 8 minutes until softened. Add the garlic and flour and fry 15 seconds more until fragrant.</li><li>Mix in the stock and milk and, once simmering, add the potatoes. Cover and simmer 15 minutes until the potatoes are soft and easily pierced with a knife.</li><li>Stir through the soured cream and season generously with salt and pepper. Blitz with a hand blender until smooth and serve topped with more soured cream, pepper and chives.</li></ol><p><em>Top with extra soured cream, black pepper and chopped chives.</em></p>', CURRENT_TIMESTAMP),
  ('88c3af0b-5a06-509a-b5bb-58eed3489d2d', '0345f7d3-97c9-57e7-9ef8-93bfad886345', 'ru', 'Салат из моркови и яблока с клюквой', 'Быстрый хрустящий салат из тёртой моркови, яблока и сушёной клюквы с луком и лимонно-майонезной заправкой.', '<ol><li>В небольшой миске смешайте майонез, лимонный сок, сахар, соль и перец.</li><li>Натрите морковь на крупной тёрке (быстро получается в комбайне) и переложите в большую миску. Добавьте нарезанное кубиками яблоко, мелко нарезанный лук и клюкву.</li><li>Перед подачей добавьте заправку по вкусу и перемешайте.</li></ol><p><em>Заправляйте перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('cc19a403-fb01-5aa8-b998-a969d33c3d6c', '0345f7d3-97c9-57e7-9ef8-93bfad886345', 'en', 'Carrot and apple salad with cranberries', 'A quick crunchy salad of grated carrot, apple and dried cranberries with onion and a lemony mayo dressing.', '<ol><li>In a small bowl stir together the mayonnaise, lemon juice, sugar, salt and pepper.</li><li>Coarsely grate the carrots (fast in a food processor) and put them in a large bowl. Add the diced apple, finely diced onion and cranberries.</li><li>When ready to serve, add the dressing to taste and stir.</li></ol><p><em>Dress just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('b7c6fb5a-13cd-59cc-b5db-a033dc7a112e', '9a4e9741-2695-5d0f-a7bb-fa00c003815e', 'ru', 'Салат из капусты, брокколи и болгарского перца с укропом', 'Хрустящий салат из тонко нашинкованной капусты, брокколи, сладкого перца и зелёного лука с лимонной заправкой с подсолнечным маслом, майонезом и сметаной.', '<ol><li>Заправка: смешайте лимонный сок, подсолнечное масло, майонез, сметану, сахар, чесночный порошок, соль, укроп и петрушку. Уберите в холодильник.</li><li>Вымойте овощи. Тонко нашинкуйте капусту на мандолине или ножом и переложите в большую миску.</li><li>Разделите брокколи на мелкие соцветия, нарежьте перец небольшими полосками, нарежьте зелёный лук и добавьте всё в миску.</li><li>Перед подачей полейте заправкой и хорошо перемешайте, чтобы овощи равномерно покрылись соусом.</li></ol><p><em>Заправляйте непосредственно перед подачей; овощи и заправку можно подготовить за несколько часов.</em></p>', CURRENT_TIMESTAMP),
  ('c3642118-5506-5781-af15-548b0f26dde4', '9a4e9741-2695-5d0f-a7bb-fa00c003815e', 'en', 'Cabbage, broccoli and bell pepper salad with dill', 'A crunchy salad of thinly sliced cabbage, broccoli, sweet pepper and green onion with a lemon, sunflower oil, mayo and sour cream dressing.', '<ol><li>Dressing: mix the lemon juice, sunflower oil, mayonnaise, sour cream, sugar, garlic powder, salt, dill and parsley. Refrigerate.</li><li>Wash the vegetables. Thinly slice the cabbage with a mandoline or a knife and put it in a large bowl.</li><li>Cut the broccoli into small florets, slice the pepper into small strips, dice the green onion and add everything to the bowl.</li><li>When ready to serve, pour the dressing over the salad and mix well until everything is evenly coated.</li></ol><p><em>Dress right before serving; the vegetables and dressing can be prepared hours ahead.</em></p>', CURRENT_TIMESTAMP),
  ('a566f4e4-c3fe-5563-9acd-24dafe3553ac', '235ebff5-ca7f-56e0-bab9-5b937caba1f5', 'ru', 'Стручковая фасоль с грибами, соевым соусом и кунжутным маслом', 'Отварная стручковая фасоль, обжаренная с шампиньонами и луком и заправленная соевым соусом и кунжутным маслом.', '<ol><li>Свежую фасоль очистите от кончиков. Доведите до кипения кастрюлю воды на две трети объёма и варите фасоль 6–7 минут до состояния «аль денте». Замороженную готовьте по инструкции на упаковке.</li><li>Сразу слейте воду и охладите фасоль холодной водой, чтобы остановить варку.</li><li>На сковороде на среднем и сильном огне разогрейте оливковое и сливочное масло, 3–5 минут обжаривайте шампиньоны и лук до мягкости.</li><li>Добавьте фасоль, сбрызните соевым соусом и кунжутным маслом, при необходимости посолите и поперчите. Перемешайте и обжаривайте ещё минуту.</li></ol><p><em>Подавайте горячей к мясу, рыбе или с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('4dd3b08f-5e34-5503-8ff0-6d8679b8144b', '235ebff5-ca7f-56e0-bab9-5b937caba1f5', 'en', 'Green beans with mushrooms, soy sauce and sesame oil', 'Boiled green beans sauteed with button mushrooms and onion and finished with soy sauce and sesame oil.', '<ol><li>Trim fresh green beans. Boil a pot two-thirds full of water and cook the beans for 6–7 minutes until crisp-tender. Cook frozen beans according to the package.</li><li>Drain immediately and rinse with cold water to stop the cooking.</li><li>Heat the olive oil and butter in a skillet over medium-high heat and saute the mushrooms and onion for 3–5 minutes until tender.</li><li>Add the beans, drizzle with the soy sauce and sesame oil and season if needed. Stir and cook for one more minute.</li></ol><p><em>Serve hot with meat, fish or rice.</em></p>', CURRENT_TIMESTAMP),
  ('48278539-405b-53a0-af7b-d79eecd4dc88', 'fbdade90-7970-52b5-92c3-fb1211427721', 'ru', 'Оладьи на греческом йогурте', 'Нежные слегка сладкие оладьи на йогурте с хрустящими краями, которые хорошо сочетаются со свежими ягодами.', '<ol><li>Взбейте яйца с йогуртом и 2 ст. л. молока.</li><li>Смешайте муку с разрыхлителем и добавьте к жидким ингредиентам. Если тесто слишком густое, подлейте молока.</li><li>Разогрейте масло на антипригарной сковороде на среднем огне, выкладывайте тесто полными столовыми ложками и жарьте по 2 минуты с каждой стороны до золотистого цвета (получится 9–11 оладий).</li></ol><p><em>Подавайте со свежими ягодами, мёдом или джемом.</em></p>', CURRENT_TIMESTAMP),
  ('9d7d4247-b633-5c2a-9b02-0ee3c6fe38f4', 'fbdade90-7970-52b5-92c3-fb1211427721', 'en', 'Greek yogurt pancakes', 'Delicate, lightly sweet pancakes made with yogurt, crisp at the edges and great with fresh berries.', '<ol><li>Whisk the eggs with the yogurt and 2 tbsp of the milk.</li><li>Stir the baking powder into the flour and add to the wet ingredients. Add more milk if the batter is too thick.</li><li>Heat the oil in a nonstick pan over medium heat, add heaped tablespoons of batter and cook 2 minutes per side until golden (9–11 pancakes).</li></ol><p><em>Serve with fresh berries, honey or jam.</em></p>', CURRENT_TIMESTAMP),
  ('41bcbef3-dbb2-5a65-9e85-0c5768c24fe8', '8d4b175e-7617-5c70-8d4f-d74640221260', 'ru', 'Овсяная каша из цельной овсяной крупы с кленовым сиропом, корицей и фруктами', 'Настоящая овсянка из цельной овсяной крупы, обжаренной на масле и сваренной на воде с молоком и кефиром, с корицей, кленовым сиропом и свежими ягодами.', '<ol><li>В средней кастрюле на среднем огне растопите масло, всыпьте овсяную крупу и 2 минуты подсушивайте, иногда помешивая.</li><li>Влейте кипяток, убавьте огонь до слабого, накройте крышкой и варите 20 минут, не помешивая.</li><li>Смешайте молоко с кефиром, влейте в кашу, добавьте соль и перемешайте. Варите ещё 10 минут без крышки, осторожно размешав один-два раза.</li><li>Добавьте корицу и кленовый сироп по вкусу, разложите по четырём мискам и украсьте ягодами или фруктами, корицей и сиропом.</li></ol><p><em>Подавайте горячей с ягодами и каплей кленового сиропа.</em></p>', CURRENT_TIMESTAMP),
  ('957f9716-18da-5131-a49b-1f6fb85ab37c', '8d4b175e-7617-5c70-8d4f-d74640221260', 'en', 'Maple cinnamon steel-cut oatmeal with fruit', 'Real oatmeal from steel-cut oats, toasted in butter, simmered in water with milk and buttermilk, with cinnamon, maple syrup and fresh berries.', '<ol><li>Melt the butter in a medium saucepan over medium heat, add the oats and toast for 2 minutes, stirring occasionally.</li><li>Pour in the boiling water, reduce to a simmer, cover and cook on low for 20 minutes without stirring.</li><li>Combine the milk with the kefir (buttermilk), pour over the oatmeal, add the salt and stir just until combined. Cook uncovered for another 10 minutes, stirring gently once or twice.</li><li>Stir in the cinnamon and maple syrup to taste, divide among four bowls and top each with fruit or berries, cinnamon and a drizzle of syrup.</li></ol><p><em>Serve hot with berries and a drizzle of maple syrup.</em></p>', CURRENT_TIMESTAMP),
  ('a6aceedd-9e40-556a-9b81-d08c8ce5b5a3', '892fb43a-cb2a-512e-8937-059415de6505', 'ru', 'Салат из макарон с овощами, горошком и йогуртово-майонезной заправкой', 'Сытный холодный салат из макарон с перцем, сельдереем, красным луком, горошком и зеленью в заправке из майонеза, йогурта, огурцов и дижонской горчицы. Хорошо хранится, подходит для ланча.', '<ol><li>Сварите макароны в подсоленной кипящей воде до состояния «аль денте» (6–7 минут), слейте воду и слегка остудите под холодной водой.</li><li>Тем временем в небольшой миске смешайте майонез, йогурт, огурцы, яблочный уксус, горчицу, сахар и по 1 ч. л. соли и перца. Переложите макароны в большую миску, залейте заправкой и хорошо перемешайте, попробуйте на соль.</li><li>Добавьте нарезанные овощи, горошек и зелень (тунец, ветчину или курицу, если используете, добавляйте сейчас), перемешайте и подавайте. В закрытом контейнере в холодильнике хранится до недели.</li></ol><p><em>К салату можно добавить тунец, ветчину или варёную курицу.</em></p>', CURRENT_TIMESTAMP),
  ('8b621482-b0b3-56ac-bb67-96cc9b3f78e6', '892fb43a-cb2a-512e-8937-059415de6505', 'en', 'Deli macaroni salad with peppers, peas and a creamy dressing', 'A hearty cold macaroni salad with peppers, celery, red onion, peas and herbs in a dressing of mayonnaise, yogurt, pickles and Dijon mustard. Keeps well and is ideal for lunches.', '<ol><li>Cook the macaroni in boiling salted water until al dente, about 6-7 minutes. Drain and rinse under cold running water to cool slightly.</li><li>Meanwhile mix the mayonnaise, yogurt, pickles, cider vinegar, mustard, sugar and 1 tsp each salt and pepper in a small bowl. Tip the cooked macaroni into a large bowl, pour over the dressing, mix well and taste for seasoning.</li><li>Add the remaining chopped veg, peas and herbs (add any tuna, ham or chicken now), toss and serve. Keeps chilled in an airtight container for up to a week.</li></ol><p><em>Add tuna, chopped ham or diced chicken if you want it heartier.</em></p>', CURRENT_TIMESTAMP),
  ('0450f20b-168f-5a74-b5ce-8dccfa76f14f', 'bdfe50d1-9557-59c0-8f23-7e003fbe681e', 'ru', 'Хрустящие куриные полоски в панировке со специями, запечённые в духовке', 'Куриное филе, замаринованное в кефире и обваленное в смеси муки, панко, кукурузной муки и 10 специй, запекается в духовке до золотистого хруста без фритюра. По вкусу похоже на куриные стрипсы из фастфуда.', '<ol><li>Смешайте в миске все специи для смеси (соль, сельдерейную соль, чесночный порошок, тимьян, базилик, орегано, перец, горчичный порошок, паприку, имбирь и кайенский перец по желанию).</li><li>Положите в пакет 1 ст. л. смеси специй, курицу и кефир. Оставьте мариноваться минимум на 2 часа, лучше на 3 или на ночь в холодильнике.</li><li>Разогрейте духовку до 200 °C. Положите масла на большой противень с бортиками и поставьте в духовку на несколько минут, пока сливочное масло не растопится. Выньте и покачайте, чтобы жир покрыл дно.</li><li>Смешайте оставшиеся специи, муку, панко и кукурузную муку, половину переложите в большой пакет. Отцедите курицу от лишнего маринада.</li><li>Переложите половину курицы в пакет с панировкой, закройте с воздухом, как шарик, встряхните, чтобы покрыть курицу, и прижмите панировку через пакет. Выложите на противень. Повторите с оставшейся смесью и курицей.</li><li>Сбрызните верх маслом из спрея и запекайте 12 минут, затем переверните, снова сбрызните и запекайте ещё 8–10 минут до золотистого цвета. Не запекайте дольше 25 минут, иначе курица пересохнет. Подавайте с соусом.</li></ol><p><em>Подавайте с медово-горчичным или любым другим соусом.</em></p>', CURRENT_TIMESTAMP),
  ('71b94f5f-8129-528b-930f-d7927a8378b5', 'bdfe50d1-9557-59c0-8f23-7e003fbe681e', 'en', 'Crispy oven-baked chicken tenders with spice coating', 'Chicken tenderloins marinated in buttermilk and coated in a mix of flour, panko, cornmeal and about ten spices, baked in the oven to a golden crunch without deep frying. They taste like fast-food style chicken strips.', '<ol><li>Combine the spice mix ingredients (salt, celery salt, garlic powder, thyme, basil, oregano, pepper, mustard powder, paprika, ginger and optional cayenne) in a bowl.</li><li>Put 1 tbsp of the spice mix in a zip bag with the chicken and buttermilk (kefir). Marinate at least 2 hours, ideally 3 or overnight in the fridge.</li><li>Preheat the oven to 200 °C (400 °F). Put the butter and oil on a large rimmed baking tray and place in the oven for a few minutes until the butter melts. Remove and tilt to spread the fat over the tray.</li><li>Mix the remaining spice mix, flour, panko and cornmeal and put half in a large zip bag. Drain the chicken of excess marinade in a colander.</li><li>Add half the chicken to the bag, seal with air so it puffs like a balloon, and shake to coat. Press through the bag so the coating sticks. Place on the tray. Repeat with the remaining coating and chicken.</li><li>Spray the tops with oil and bake 12 minutes, then turn, spray again and bake another 8-10 minutes until golden. Do not bake longer than 25 minutes or the chicken dries out. Serve with a dipping sauce.</li></ol><p><em>Serve with honey mustard or any dipping sauce.</em></p>', CURRENT_TIMESTAMP),
  ('0450f522-b149-56fe-bac9-740e7751d74c', '0b2ff93e-2397-51af-b263-44cdd7e25d0a', 'ru', 'Грибы с шалотом и чесноком, тушёные с корицей и тимьяном', 'Шампиньоны, тушёные с шалотом и целыми зубчиками чеснока на оливковом масле и топлёном масле с тимьяном, палочкой корицы и паприкой. Подойдёт как гарнир или тёплая закуска, а с рисом это уже вегетарианский обед.', '<ol><li>В большой сковороде на среднем огне разогрейте оливковое масло и топлёное масло до лёгкого шипения. Добавьте шалот, чеснок, веточки тимьяна и палочки корицы. Готовьте 10–12 минут, иногда помешивая, пока шалот не начнёт мягчеть.</li><li>Сделайте огонь средне-сильным и добавьте оба вида грибов (возможно, понадобится ещё немного масла). Готовьте, иногда помешивая, 5 минут. Посолите, поперчите, добавьте щепотку паприки или смеси харисса.</li><li>Влейте бульон и тушите на сильном кипении около 10 минут, пока жидкость почти не выпарится (но не совсем).</li><li>Вмешайте свежую петрушку и снимите с огня. Для ricotta-соуса взбейте рикотту с лимонной цедрой и каплей оливкового масла.</li><li>Подавайте грибы как гарнир с ложкой рикотты и хлебом, либо на кускусе или рисе.</li></ol><p><em>Подавайте с ложкой рикотты с лимонной цедрой и хлебом, либо поверх кускуса или риса.</em></p>', CURRENT_TIMESTAMP),
  ('ae5844eb-67ed-56a7-b908-33e68ddbe3fd', '0b2ff93e-2397-51af-b263-44cdd7e25d0a', 'en', 'Braised shallot and garlic mushrooms with cinnamon and thyme', 'Mushrooms braised with shallots and whole garlic cloves in olive oil and ghee with thyme, a cinnamon stick and paprika. A rich side or warm appetizer, and with rice a vegetarian lunch.', '<ol><li>In a large skillet over medium heat warm the olive oil and ghee until shimmering. Add the shallots, garlic, thyme sprigs and cinnamon sticks. Cook 10-12 minutes, stirring occasionally, until the shallots begin to soften.</li><li>Raise the heat to medium-high and add both kinds of mushrooms (you may need a drizzle more olive oil). Cook, tossing occasionally, 5 minutes. Season with salt, pepper and a pinch of sweet paprika or harissa spice.</li><li>Add the broth and simmer hard about 10 minutes until the liquid has reduced a lot (almost gone, but not quite).</li><li>Stir in the fresh parsley and take off the heat. For the ricotta topping whisk the ricotta with the lemon zest and a drizzle of olive oil.</li><li>Serve the mushrooms as a side with a dollop of ricotta topping and bread, or over couscous or rice.</li></ol><p><em>Serve with a dollop of lemon-zest ricotta and crusty bread, or over couscous or rice.</em></p>', CURRENT_TIMESTAMP),
  ('a862e0a8-4ee6-5cd4-ae85-9799aac65a06', 'fd487261-07c7-506b-bb97-2f50894d75c1', 'ru', 'Французский морковный салат с зирой и нутом', 'Свежий салат из тёртой моркови с зеленью и необязательным нутом в заправке из оливкового масла, лимона, мёда, дижонской горчицы и зиры.', '<ol><li>Морковь очистите и натрите на крупной тёрке, на тёрке для корейской моркови или в комбайне (получится около 3 стаканов).</li><li>Выложите морковь в миску, добавьте шнитт-лук или зелёный лук, петрушку и (по желанию) нут.</li><li>Взбейте в небольшой миске оливковое масло, лимонный сок, мёд, горчицу, зиру и соль.</li><li>Залейте салат заправкой и перемешайте. Для лучшего вкуса оставьте на 20 минут и снова перемешайте перед подачей.</li></ol><p><em>Дайте салату настояться 20 минут и перемешайте перед подачей; в холодильнике хранится около 4 дней.</em></p>', CURRENT_TIMESTAMP),
  ('162a139d-d971-5040-a657-6a2c4ffb0532', 'fd487261-07c7-506b-bb97-2f50894d75c1', 'en', 'French carrot salad with cumin and chickpeas', 'A fresh salad of grated carrots with herbs and optional chickpeas in a dressing of olive oil, lemon, honey, Dijon and cumin.', '<ol><li>Peel the carrots and grate on the large holes of a box grater, with a julienne peeler or in a food processor (about 3 cups).</li><li>Put the carrots in a bowl and add the chives or green onion, parsley and the optional chickpeas.</li><li>Whisk the olive oil, lemon juice, honey, mustard, cumin and salt together in a small bowl.</li><li>Pour the dressing over the salad and stir. For the best flavour let it marinate for 20 minutes and toss again before serving.</li></ol><p><em>Let it marinate for 20 minutes and toss before serving; keeps about 4 days in the fridge.</em></p>', CURRENT_TIMESTAMP),
  ('cc49e927-a488-5065-afc5-d9d2827f0812', '24486c7a-7b96-5680-be14-2090a82a28e6', 'ru', 'Брокколи, запечённая с пармезаном и бальзамическим соусом', 'Соцветия брокколи, запечённые до золотистых краёв с сыром пармезан, с каплей бальзамического уксуса, лимонной цедрой и хлопьями чили.', '<ol><li>Разогрейте духовку до 200 °C. Застелите большой противень с бортами пергаментом, чтобы сыр не прилип.</li><li>На противне перемешайте брокколи с маслом, разложите ровным слоем и слегка посолите.</li><li>Запекайте 15 минут, затем достаньте, перемешайте, снова разложите ровным слоем и посыпьте пармезаном. Верните в духовку ещё на 10 минут, пока соцветия не станут золотистыми по краям, а сыр не зарумянится.</li><li>Сбрызните бальзамическим уксусом, натрите сверху лимонную цедру, посыпьте хлопьями чили и щепоткой крупной соли.</li></ol><p><em>Лучше всего подавать тёплой; остатки можно хранить в холодильнике несколько дней.</em></p>', CURRENT_TIMESTAMP),
  ('148a2f47-21ce-5030-a6ac-d2c9d7501ddd', '24486c7a-7b96-5680-be14-2090a82a28e6', 'en', 'Parmesan roasted broccoli with balsamic drizzle', 'Broccoli florets roasted until golden at the edges with Parmesan, finished with balsamic vinegar, lemon zest and chilli flakes.', '<ol><li>Preheat the oven to 200 °C. Line a large rimmed baking sheet with parchment so the cheese does not stick.</li><li>On the baking sheet toss the broccoli with the oil, spread in an even layer and sprinkle lightly with salt.</li><li>Bake for 15 minutes, then take out, toss, spread out again and sprinkle with Parmesan. Return to the oven for 10 more minutes until the florets are deeply golden at the edges and the Parmesan is golden and bubbly.</li><li>Drizzle lightly with balsamic, grate lemon zest on top and sprinkle with chilli flakes and a pinch of flaky salt.</li></ol><p><em>Best served warm; leftovers keep in the fridge for several days.</em></p>', CURRENT_TIMESTAMP),
  ('b51a3e38-b116-5b97-82c6-3a0232ad6c86', '38914f7e-1681-5452-b723-d2c890bbbc88', 'ru', 'Хрустящий раздавленный картофель в духовке', 'Мелкий картофель, сваренный до мягкости, слегка раздавленный и запечённый с оливковым маслом и специями до хрустящей золотистой корочки.', '<ol><li>Вымойте картофель, при необходимости почистите щёткой, срежьте глазки. Сложите в большую кастрюлю.</li><li>Залейте водой так, чтобы она покрывала картофель на 2,5 см, добавьте 1 ст. л. соли. Доведите до кипения и варите до состояния, когда картофель легко прокалывается вилкой (мелкий около 20 минут, средний около 25).</li><li>Пока картофель варится, разогрейте духовку до 220 °C и равномерно смажьте большой противень с бортами 1 ст. л. оливкового масла.</li><li>Слейте воду и дайте картофелю остыть около 5 минут. Разложите на противне и аккуратно раздавите каждую картофелину толкушкой или вилкой до толщины около 1,2 см.</li><li>Полейте оставшимися 3 ст. л. масла, посыпьте чесночным и луковым порошком, оставшейся солью и перцем. Запекайте 25–30 минут до золотистых хрустящих краёв. Посыпьте свежей зеленью.</li></ol><p><em>Подавайте горячим, посыпав зеленью, к мясу, рыбе или овощам.</em></p>', CURRENT_TIMESTAMP),
  ('bc90bb15-fc9d-5234-9392-b133a2bc68a7', '38914f7e-1681-5452-b723-d2c890bbbc88', 'en', 'Crispy baked smashed potatoes', 'Small potatoes boiled until tender, lightly smashed and roasted with olive oil and seasoning until crisp and golden.', '<ol><li>Scrub the potatoes clean, rinse and remove any sprouting spots. Place in a large pot.</li><li>Cover with water by 1 inch (2.5 cm) and add 1 tbsp of salt. Bring to a boil and cook until the potatoes are easily pierced with a fork (about 20 minutes for small, 25 for medium).</li><li>While the potatoes cook, preheat the oven to 220 °C and brush a large rimmed baking sheet evenly with 1 tbsp of olive oil.</li><li>Drain and let the potatoes cool for about 5 minutes. Spread them on the baking sheet and gently smash each one to a height of about 1/2 inch with a masher or fork.</li><li>Drizzle with the remaining 3 tbsp of oil and sprinkle with garlic powder, onion powder, the remaining salt and pepper. Bake for 25–30 minutes until golden at the edges. Sprinkle with fresh herbs.</li></ol><p><em>Serve hot sprinkled with herbs next to meat, fish or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('50850845-3658-5af0-a725-43948556d05c', 'e31c5b94-cce0-5ff3-8ce0-520f6fe4e719', 'ru', 'Паста алла Норма с запечёнными баклажанами', 'Сицилийская паста с запечёнными (не жареными) баклажанами, томатным соусом, базиликом и тёртым сыром.', '<ol><li>Если соус готовый, прогрейте его в кастрюле на среднем и слабом огне, пока варится паста.</li><li>Разогрейте духовку до 220 °C, расположите решётки в верхней и нижней трети, застелите два противня пергаментом.</li><li>Овощечисткой срежьте с баклажанов полосками кожуру через одну, чтобы получился полосатый рисунок. Нарежьте кружками толщиной 1,2 см, концы выбросьте.</li><li>Выложите на противни, смажьте маслом с обеих сторон, посолите и поперчите. Запекайте 35–45 минут до золотистого цвета и мягкости, перевернув через 20 минут.</li><li>Отварите пасту до состояния «аль денте» в подсоленной воде. Оставьте около 120 мл отвара, затем слейте воду и верните пасту в кастрюлю.</li><li>Аккуратно вмешайте запечённые баклажаны в соус, добавьте 1 ч. л. масла, нарубленный базилик, хлопья чили и растёртое между пальцами орегано.</li><li>Добавьте пасту в соус с парой ложек отвара, аккуратно перемешайте, добавьте около двух третей сыра, посолите и поперчите. При необходимости подлейте отвар.</li><li>Разложите по четырём мискам, сверху посыпьте оставшимся сыром и свежим базиликом.</li></ol><p><em>По желанию сбрызните порцию оливковым маслом и посыпьте свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('a2df6cb6-905d-55b8-9e05-21d7b0c5da9a', 'e31c5b94-cce0-5ff3-8ce0-520f6fe4e719', 'en', 'Pasta alla Norma with roasted eggplant', 'Sicilian pasta with roasted (not fried) eggplant, tomato sauce, basil and grated cheese.', '<ol><li>If using store-bought sauce, warm it in a pot over medium-low heat while the pasta cooks.</li><li>Preheat the oven to 220 °C with racks in the upper and lower thirds and line two baking sheets with parchment.</li><li>With a vegetable peeler remove alternating strips of peel so the eggplants look striped. Slice into 1.2 cm rounds, discarding the ends.</li><li>Place on the baking sheets, brush with olive oil on both sides and season with salt and pepper. Roast for 35–45 minutes until deeply golden and tender, flipping after 20 minutes.</li><li>Cook the pasta until al dente in salted water. Reserve about 1/2 cup of the cooking water, drain and return the pasta to the pot.</li><li>Gently stir the roasted eggplant into the sauce, add 1 tsp olive oil, the chopped basil, chilli flakes and the oregano crushed between your fingers.</li><li>Add the pasta to the sauce with a couple of tablespoons of the cooking water and stir gently. Add about two-thirds of the cheese, season, and loosen with more cooking water if desired.</li><li>Divide between four bowls and top with the remaining cheese and fresh basil.</li></ol><p><em>Drizzle each portion with olive oil and add extra basil if you like.</em></p>', CURRENT_TIMESTAMP),
  ('9ce4a96e-9003-562f-a747-847cff49d918', '6676248f-e1b8-575f-a809-7de6f934864d', 'ru', 'Французские тосты (гренки в яично-молочной смеси)', 'Воздушные и нежные сладковатые тосты из черствоватого хлеба, вымоченного в смеси из молока, желтков, масла, кленового сиропа, ванили и корицы, обжаренные до золотистого цвета.', '<ol><li>Нарежьте хлеб ломтиками толщиной около 2 см (8 больших или 12 средних). Если хлеб свежий, выложите ломтики на решётку на противне и подсушите в духовке при 150 °C 8–16 минут, один раз перевернув: нужен «вчерашний» хлеб, а не сухарики. Остудите.</li><li>Слегка подогрейте молоко (чтобы растопленное масло не свернулось).</li><li>Взбейте желтки, влейте тёплое молоко, растопленное масло, кленовый сироп, ваниль, корицу и соль и взбейте. Вылейте смесь в широкую форму.</li><li>Вымачивайте ломтики по очереди, пока низ не впитает смесь примерно на 6 мм, затем переверните и повторите. Смесь периодически перемешивайте, чтобы корица не оседала.</li><li>Разогрейте сковороду (лучше чугунную) или гриль на среднем и слабом огне; жир не нужен, масла в смеси достаточно. Жарьте ломтики по 3–4 минуты с каждой стороны до золотистого цвета, при необходимости уменьшая огонь.</li></ol><p><em>Подавайте с кленовым сиропом, сливочным маслом, свежими ягодами или йогуртом.</em></p>', CURRENT_TIMESTAMP),
  ('3eb5351d-72c9-5c02-bf56-403ae9cb638e', '6676248f-e1b8-575f-a809-7de6f934864d', 'en', 'Foolproof French toast', 'Fluffy, tender, lightly sweet toast from slightly stale bread soaked in a milk, yolk, butter, maple, vanilla and cinnamon custard and browned until golden.', '<ol><li>Cut the bread into about 2 cm slices (8 large or 12 medium). If the bread is fresh and soft, dry the slices on a rack on a baking sheet in a 150 °C oven for 8–16 minutes, flipping once, until stale but not crisp. Let cool.</li><li>Gently warm the milk so the melted butter will not clump.</li><li>Whisk the yolks, then add the warm milk, melted butter, maple syrup, vanilla, cinnamon and salt and whisk. Pour into a wide baking dish.</li><li>Soak the slices, one side at a time, until each side absorbs about 1/4 inch of custard, then flip. Whisk the mixture between batches to redistribute the cinnamon.</li><li>Heat a skillet (ideally cast iron) or griddle over medium-low heat; no extra fat is needed since the batter contains butter. Cook the slices 3–4 minutes per side until golden, lowering the heat if they brown too fast.</li></ol><p><em>Serve with maple syrup, butter, fresh berries or yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('76a30bc1-077b-5e51-98a4-05181c4d7cd3', 'b78419af-14c3-56d2-8d3f-815cb6f89829', 'ru', 'Салат из запечённой свёклы с козьим сыром и фисташками', 'Запечённая свёкла с руколой, козьим сыром, фисташками, редисом и зелёным луком под горчично-медовой заправкой.', '<ol><li>Разогрейте духовку до 190 °C, застелите противень пергаментом. Хорошо вымойте свёклу щёткой (чистить не нужно).</li><li>Срежьте у каждой свёклины основание и тонкий кончик, разрежьте пополам и затем на дольки толщиной около 1,2–2 см.</li><li>Выложите дольки на противень, сбрызните маслом, посолите, перемешайте и разложите в один слой. Запекайте 35–40 минут, перемешав на полпути, до мягкости.</li><li>Пока свёкла запекается, взбейте масло, винный уксус, мёд, горчицу и соль, щедро поперчите.</li><li>Выложите на блюдо руколу, сверху запечённую свёклу, раскрошенный козий сыр, нарубленные фисташки, редис и зелёный лук.</li><li>Перед подачей полейте заправкой (может понадобиться не вся) и аккуратно перемешайте.</li></ol><p><em>Заправляйте порцию перед подачей; салат и заправку храните отдельно до 4 дней.</em></p>', CURRENT_TIMESTAMP),
  ('75ea73f8-ed5c-5953-bf94-9293bb85c0a5', 'b78419af-14c3-56d2-8d3f-815cb6f89829', 'en', 'Roasted beet salad with goat cheese and pistachios', 'Roasted beets with arugula, goat cheese, pistachios, radishes and green onion in a Dijon-honey dressing.', '<ol><li>Preheat the oven to 190 °C and line a baking sheet with parchment. Scrub the beets well (no need to peel).</li><li>Slice off the base and the pointy end of each beet, halve it and cut into wedges about 1.2–2 cm thick.</li><li>Place the wedges on the pan, drizzle with oil, sprinkle with salt, toss and spread in a single layer. Roast for 35–40 minutes, tossing halfway, until tender.</li><li>Meanwhile whisk the olive oil, vinegar, honey, mustard and salt and season generously with pepper.</li><li>Put the arugula on a platter and top with the roasted beets, crumbled goat cheese, chopped pistachios, radishes and green onion.</li><li>Just before serving, drizzle over the dressing (you may not need all of it) and toss gently.</li></ol><p><em>Dress each portion just before serving; keep salad and dressing separate for up to 4 days.</em></p>', CURRENT_TIMESTAMP),
  ('a87df48e-cdd0-5cf2-b0f0-8c5f1bb518d0', 'a408ac18-1e9a-5561-a0c4-e7460426cc33', 'ru', 'Целая курица, томлёная в молоке с лимоном, шалфеем и чесноком', 'Целая курица, обжаренная и запечённая в горшке в молоке с лимонной цедрой, шалфеем, корицей и целыми зубчиками чеснока. Получается очень нежное мясо с хрустящей кожей и соусом со сладковатым чесноком.', '<ol><li>Разогрейте духовку до 190 °C. Промойте курицу и хорошо обсушите бумажными полотенцами.</li><li>Натрите курицу солью и перцем, особенно сверху и с боков.</li><li>В тяжёлой жаропрочной кастрюле с крышкой разогрейте масло на сильном огне. Обжарьте курицу со всех сторон, насколько получится (удобно переворачивать щипцами и деревянной ложкой, чтобы не порвать кожу).</li><li>Слейте лишний жир из кастрюли (или переложите курицу на тарелку и слейте жир). Добавьте остальные ингредиенты: корицу, шалфей, цедру лимонов, чеснок в кожуре и молоко. Верните курицу в кастрюлю.</li><li>Запекайте под крышкой 40 минут, затем без крышки ещё 50 минут (всего 1,5 часа).</li><li>Оставьте на 5 минут, переложите курицу на блюдо, а соус подайте отдельно. Соус лучше не процеживать: творожные крошки молока, чеснок и шалфей придают вкус.</li></ol><p><em>Дайте постоять 5 минут и подавайте с соусом отдельно (его не процеживают). Запечённый чеснок можно выдавить из кожуры к мясу или на хлеб.</em></p>', CURRENT_TIMESTAMP),
  ('42290a6b-4d16-57f9-a88c-330b4a8d4a75', 'a408ac18-1e9a-5561-a0c4-e7460426cc33', 'en', 'Whole chicken braised in milk with lemon, sage and garlic', 'A whole chicken browned and then baked in a pot in milk with lemon zest, sage, cinnamon and whole garlic cloves. Very tender meat with crisp skin and a sauce with soft, sweet garlic.', '<ol><li>Preheat the oven to 190 °C (375 °F). Rinse the chicken and pat dry with paper towels.</li><li>Rub the salt and pepper over the chicken, concentrating on the top and sides.</li><li>Heat the oil in a heavy ovenproof pot with a lid over high heat. Brown the chicken all over as best you can (tongs and a wooden spoon help turning it without tearing the skin).</li><li>Pour off the excess fat (or lift the chicken onto a plate first). Add the remaining ingredients: cinnamon, sage, lemon zest, whole garlic cloves in the skin and milk. Return the chicken to the pot.</li><li>Bake covered for 40 minutes, then uncovered for 50 minutes (1½ hours in total).</li><li>Let stand about 5 minutes, then transfer the chicken to a platter and serve the sauce on the side. It is best not strained, as the milk curds, garlic and sage add flavour.</li></ol><p><em>Rest 5 minutes and serve with the sauce on the side (do not strain it). Squeeze the soft garlic out of the skin onto the meat or toast.</em></p>', CURRENT_TIMESTAMP),
  ('21692fe6-21ac-5d16-8239-71cc42fd4773', '17d9d218-33b7-591b-9ab0-98ef2f435fe5', 'ru', 'Средиземноморская лепёшка с хумусом, рукколой, помидорами и копчёным лососем', 'Тонкая запечённая лепёшка из пиццы-теста с заатаром, покрытая хумусом, рукколой, черри, копчёным лососем, оливками и фетой. Подходит как лёгкий ужин или закуска для компании.', '<ol><li>Разогрейте духовку до 230 °C. Смажьте большой противень оливковым маслом и посыпьте дно 2–3 ст. л. кукурузной муки.</li><li>На слегка присыпанной мукой поверхности раскатайте и растяните тесто (при комнатной температуре) в прямоугольник или овал примерно 30 × 20 см. Переложите на подготовленный противень.</li><li>Слегка смажьте тесто маслом, посыпьте орегано и заатаром. Запекайте 15–20 минут, пока тесто не станет золотистым, а низ слегка хрустящим. Достаньте.</li><li>В миске соедините рукколу и помидоры, сбрызните маслом, посолите, поперчите и добавьте щепотку заатара.</li><li>Тонко намажьте на лепёшку хумус, сверху выложите рукколу с помидорами, затем остальные ингредиенты (лосось, оливки, фета, по желанию кедровые орехи). Посыпьте ещё заатаром и орегано и нарежьте.</li></ol><p><em>Нарежьте на небольшие прямоугольники как закуску или подавайте крупными кусками как основное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('8c653372-c5c6-56c1-85be-f43f42ac11d0', '17d9d218-33b7-591b-9ab0-98ef2f435fe5', 'en', 'Mediterranean flatbread with hummus, arugula, tomatoes and smoked salmon', 'A thin baked flatbread of pizza dough with za''atar, topped with hummus, arugula, cherry tomatoes, smoked salmon, olives and feta. A light dinner or an appetizer for a crowd.', '<ol><li>Preheat the oven to 230 °C (450 °F). Brush a large sheet pan with olive oil and sprinkle the bottom with 2-3 tbsp cornmeal.</li><li>On a lightly floured surface roll and stretch the dough (at room temperature) into a 12 × 8 inch rectangle or oval. Transfer to the prepared pan.</li><li>Lightly brush the dough with olive oil and sprinkle with oregano and za''atar. Bake 15-20 minutes until golden and slightly crisp on the bottom. Remove from the oven.</li><li>In a bowl combine the arugula and tomatoes, drizzle with a little olive oil and season with salt, pepper and a dash of za''atar.</li><li>Spread a thin layer of hummus over the crust, top with the arugula and tomato mixture, then arrange the remaining ingredients (salmon, olives, feta, optional pine nuts). Sprinkle with a little more za''atar and oregano and slice.</li></ol><p><em>Cut into small rectangles as an appetizer or serve in larger pieces as a meal.</em></p>', CURRENT_TIMESTAMP),
  ('9160fc08-9f36-57ac-9152-6443057d2cab', '4bc4a978-276e-586b-8a39-9578b19385b0', 'ru', 'Овощи стир-фрай со спаржей и морковью в соево-медовом соусе', 'Быстрый гарнир из моркови, красного лука и спаржи, обжаренных на сильном огне и политых соусом из соевого соуса, мёда, имбиря и чеснока. С рисом и яйцом или тофу превращается в полноценный ужин.', '<ol><li>В мерном стакане смешайте соевый соус, мёд, крахмал, имбирь, чеснок и хлопья красного перца до однородности. Отставьте.</li><li>Разогрейте масло на среднем огне. Добавьте лук, морковь и щепотку соли. Сделайте огонь средне-сильным и готовьте, помешивая каждые 30 секунд, 4–5 минут, пока лук не смягчится. Если почувствуете запах гари, убавьте огонь.</li><li>Добавьте спаржу и готовьте, помешивая каждые 30 секунд, 3–4 минуты, пока морковь не начнёт карамелизоваться по краям и легко прокалываться вилкой.</li><li>Влейте соус и готовьте, постоянно помешивая, 20–60 секунд, пока он не загустеет. Снимите с огня и подавайте.</li></ol><p><em>Подавайте как гарнир или с бурым рисом и жареным яйцом или тофу.</em></p>', CURRENT_TIMESTAMP),
  ('282a1728-dd68-5291-9d3c-164b54181ced', '4bc4a978-276e-586b-8a39-9578b19385b0', 'en', 'Spring veggie stir-fry with asparagus and carrots in soy-honey sauce', 'A quick side of carrots, red onion and asparagus stir-fried over high heat and glazed with a sauce of soy sauce, honey, ginger and garlic. Served with rice and an egg or tofu it becomes a full dinner.', '<ol><li>In a liquid measuring cup whisk together the soy sauce, honey, starch, ginger, garlic and red pepper flakes until blended. Set aside.</li><li>Warm the oil over medium heat until shimmering. Add the onion, carrots and a pinch of salt. Raise to medium-high and cook, stirring every 30 seconds, 4-5 minutes until the onions soften. If you smell burning, turn the heat down a bit.</li><li>Add the asparagus and cook, stirring every 30 seconds, 3-4 minutes until the carrots start to caramelize on the edges and are easily pierced with a fork.</li><li>Pour in the sauce and cook, stirring constantly, 20-60 seconds until thickened. Remove from the heat and serve.</li></ol><p><em>Serve as a side, or with brown rice and a fried egg or tofu.</em></p>', CURRENT_TIMESTAMP),
  ('6734491d-dfa7-5016-96eb-da42000d8f7d', 'd709c149-5a03-5fb5-94d2-83b07e7df8ca', 'ru', 'Запечённая грудка индейки на кости с травяным маслом', 'Грудка индейки с кожей, намазанная под кожей и сверху маслом с чесноком, розмарином, тимьяном и шалфеем, запечённая до золотистой корочки и сочного мяса.', '<ol><li>Разогрейте духовку до 175 °C. В небольшой миске разотрите мягкое сливочное масло с чесноком, солью, перцем, розмарином, тимьяном и шалфеем в пасту.</li><li>Хорошо обсушите грудку бумажным полотенцем со всех сторон. Аккуратно отделите рукой кожу от мяса, оставив её по бокам, чтобы получился карман для масла.</li><li>Заложите около трети масла под кожу, остальным обмажьте кожу сверху и всю грудку снаружи.</li><li>Выложите грудку в смазанную форму с высокими бортами или противень. Запекайте около 1,5 часов, пока температура внутри не достигнет 74 °C (у автора готово за 1 час 20 минут). Каждые 30 минут поливайте соком из формы. Проверять температуру начинайте через час.</li><li>Если верх слишком румянится, неплотно накройте фольгой. Измеряйте температуру в самой толстой части, не касаясь кости. Оставьте индейку отдохнуть минимум на 10 минут перед нарезкой.</li></ol><p><em>Дайте постоять не менее 10 минут перед нарезкой и подавайте с соусом и любимым гарниром.</em></p>', CURRENT_TIMESTAMP),
  ('a3daf591-b9f0-5554-90e8-d183b31d3fb1', 'd709c149-5a03-5fb5-94d2-83b07e7df8ca', 'en', 'Roasted bone-in turkey breast with herb butter', 'A skin-on turkey breast rubbed under and over the skin with garlic, rosemary, thyme and sage butter and roasted until golden with juicy meat.', '<ol><li>Preheat the oven to 175 °C (350 °F). In a small bowl mix the room temperature butter with the garlic, salt, pepper, rosemary, thyme and sage into a paste.</li><li>Dry the turkey breast very well with a paper towel on all sides. Carefully separate the skin from the meat with your hand, leaving it intact on the sides, to make a pocket for the herb butter.</li><li>Spread about ⅓ of the herb butter under the skin and the rest on top of the skin and over the whole outside of the breast.</li><li>Place the breast in a greased deep casserole or roasting pan. Roast about 1½ hours until the internal temperature reaches 74 °C (165 °F) (the author''s was ready in 1 hour 20 minutes). Baste with the pan drippings every 30 minutes and start checking the temperature after 1 hour.</li><li>If the top browns too much, loosely cover with foil. Measure the temperature in the thickest part without touching the bone. Rest the turkey at least 10 minutes before slicing.</li></ol><p><em>Rest at least 10 minutes before slicing and serve with gravy and your favorite sides.</em></p>', CURRENT_TIMESTAMP),
  ('2a1f4f14-2de4-53d8-86a8-f908a82768cb', 'db243780-6a29-51cc-9747-3621f89970da', 'ru', 'Сирийская курица в томатном бульоне с шафраном и рисом', 'Куриные бёдра на кости с хрустящей кожей в специях, запечённые в густом томатном бульоне с имбирём, чесноком, чили, зирой и шафраном. В конце добавляют лимонный сок, мяту и кинзу. Подаётся на рисе.', '<ol><li>Разогрейте духовку до 180 °C. Выложите курицу в миску, посыпьте зирой, корицей, солью и перцем и обмажьте руками.</li><li>В большой жаропрочной сковороде на сильном огне разогрейте масло. Обжарьте курицу кожей вниз до румяной корочки, переверните и обжарьте с другой стороны. Переложите курицу на тарелку, лишнее масло слейте.</li><li>В ту же сковороду добавьте лук, чеснок, имбирь и чили и обжаривайте около 2 минут, пока лук не станет прозрачным и не начнёт румяниться.</li><li>Добавьте томаты, бульон, шафран, зиру и тимьян. Доведите до кипения и выключите огонь. Уложите курицу в томатный бульон, накройте фольгой или крышкой и запекайте 25–35 минут.</li><li>Тем временем сварите рис по инструкции на упаковке.</li><li>Когда курица станет тёмно-золотистой и готовой, выньте из духовки. Вмешайте в соус изюм (если используете), лимонный сок и половину мяты и кинзы. Посыпьте остальной зеленью. Подавайте на рисе с ложкой йогурта.</li></ol><p><em>Подавайте на варёном рисе (в оригинале — крупный кускус) с ложкой йогурта. Для менее острого блюда уберите чили.</em></p>', CURRENT_TIMESTAMP),
  ('11b05db3-cacd-5511-8ef1-0fe66400efd4', 'db243780-6a29-51cc-9747-3621f89970da', 'en', 'Syrian chicken in tomato saffron broth with rice', 'Bone-in chicken thighs with spiced crispy skin baked in a rich tomato broth with ginger, garlic, chili, cumin and saffron, finished with lemon juice, mint and coriander. Served over rice.', '<ol><li>Preheat the oven to 180 °C (350 °F). Put the chicken in a bowl, sprinkle with the cumin, cinnamon, salt and pepper and rub to coat.</li><li>Heat the oil in a large ovenproof pan over high heat. Sear the chicken skin side down until nicely browned, turn and brown the other side. Remove the chicken and drain off the excess oil.</li><li>Add the onion, garlic, ginger and chili to the pan and sauté about 2 minutes until the onion is translucent and starting to brown.</li><li>Add the tomato, stock, saffron, cumin and thyme. Bring to a simmer, then turn the stove off. Nestle the chicken into the tomato broth, cover with foil or a lid and bake 25-35 minutes.</li><li>Meanwhile cook the rice according to the package directions.</li><li>When the chicken is dark golden brown and cooked, remove from the oven. Stir in the currants (if using), lemon juice and half the mint and coriander. Sprinkle over the rest. Serve on the rice with a dollop of yogurt.</li></ol><p><em>Serve on cooked rice (giant couscous in the original) with a dollop of yogurt. Omit the chili for a milder dish.</em></p>', CURRENT_TIMESTAMP),
  ('fab52ec1-779f-59e9-b854-62b64064fe8c', 'd07a89ef-e3b8-50dc-8cea-a431d26477da', 'ru', 'Куриные голени, запечённые в медово-соевой глазури', 'Куриные голени, замаринованные в смеси мёда, соевого соуса, апельсинового сока, дижонской горчицы, чеснока и имбиря, запечённые в духовке и покрытые густой блестящей глазурью из уваренного маринада.', '<ol><li>В небольшой миске взбейте все ингредиенты маринада: мёд, соевый соус, апельсиновый сок, горчицу, чеснок и имбирь. Отлейте 2/3 стакана маринада и уберите в холодильник.</li><li>Положите голени в большой пакет, залейте остальным маринадом, выпустите воздух и закройте. Уберите в холодильник на 6 часов или на ночь, несколько раз переворачивая пакет.</li><li>Разогрейте духовку до 200 °C, решётка в центре. Застелите противень с бортиками или форму пергаментом.</li><li>Выложите голени кожей вверх, чтобы они не касались друг друга. Влейте немного маринада, чтобы покрыть дно противня, остальное из пакета выбросьте. Запекайте 25 минут, переверните кожей вниз и запекайте ещё 20 минут. Для карамелизированной кожи переверните снова кожей вверх и подержите под грилем на сильном огне 3–4 минуты.</li><li>Пока курица запекается, влейте отложенный маринад в небольшую кастрюлю, доведите до кипения, убавьте огонь и варите около 7 минут, пока глазурь не загустеет до состояния сиропа. Смажьте голени глазурью и посыпьте кунжутом и шнитт-луком.</li></ol><p><em>Посыпьте кунжутом и шнитт-луком. Подавайте с рисом или картофелем и салатом, по 2 голени на порцию.</em></p>', CURRENT_TIMESTAMP),
  ('c319d09b-3e6b-5407-9b79-9bc60fe11807', 'd07a89ef-e3b8-50dc-8cea-a431d26477da', 'en', 'Baked honey-soy glazed chicken drumsticks', 'Chicken drumsticks marinated in honey, soy sauce, orange juice, Dijon mustard, garlic and ginger, baked in the oven and brushed with a thick glossy glaze made from the reduced marinade.', '<ol><li>Whisk the marinade ingredients (honey, soy sauce, orange juice, mustard, garlic and ginger) in a small bowl. Reserve ⅔ cup of the marinade and refrigerate it.</li><li>Put the drumsticks in a large zip bag, pour the remaining marinade over, press out the air and seal. Refrigerate 6 hours or overnight, turning the bag a few times.</li><li>Preheat the oven to 200 °C (400 °F) with the rack in the center. Line a rimmed baking sheet or roasting pan with parchment.</li><li>Arrange the drumsticks skin-side up so they do not touch. Add just enough marinade to coat the bottom of the pan and discard the rest from the bag. Bake 25 minutes, turn skin-side down and bake 20 more. For caramelized skin turn them skin-side up again and broil on high 3-4 minutes.</li><li>While the chicken bakes, pour the reserved marinade into a small saucepan, bring to a boil, reduce the heat and simmer about 7 minutes until syrupy. Brush the glaze over the drumsticks and garnish with sesame seeds and chives.</li></ol><p><em>Garnish with sesame seeds and chives. Serve with rice or potatoes and a salad, 2 drumsticks per serving.</em></p>', CURRENT_TIMESTAMP),
  ('475f742f-7cae-5dba-8867-f4404b45a328', '2231bb7a-444e-5e05-ab6f-b2b5149a043a', 'ru', 'Мексиканский коричневый рис с томатами и халапеньо', 'Рассыпчатый бурый рис, запечённый в духовке в томатно-луковом соусе с халапеньо и кинзой.', '<ol><li>Разогрейте духовку до 190 °C. В блендере или комбайне пюрируйте помидоры, лук и чеснок до гладкости. Отмерьте 2 стакана (480 мл) смеси, остальное не нужно.</li><li>В жаропрочной кастрюле с толстым дном разогрейте оливковое масло на среднем огне, добавьте неразмоченный и непромытый рис и халапеньо и жарьте, помешивая, 2–3 минуты.</li><li>Влейте бульон (осторожно, брызги), томатное пюре, добавьте томатную пасту и соль, перемешайте, прибавьте огонь и доведите до кипения.</li><li>Накройте крышкой и переставьте в духовку. Запекайте 1 час 15–30 минут, пока жидкость не впитается и рис не станет мягким, перемешав на середине.</li><li>Вмешайте кинзу, при необходимости досолите, добавьте щепотку хлопьев чили для остроты. Подавайте с дольками лайма.</li></ol><p><em>Подавайте с дольками лайма к тортильям, бобам и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('9a70bfc1-1063-52a1-91df-e05db18398cd', '2231bb7a-444e-5e05-ab6f-b2b5149a043a', 'en', 'Mexican brown rice with tomato and jalapeño', 'Fluffy brown rice baked in the oven in a tomato-onion sauce with jalapeño and cilantro.', '<ol><li>Preheat the oven to 190 °C. Blend the tomatoes, onion and garlic until smooth in a blender or food processor. Measure out 2 cups (480 ml) of the mixture and discard the rest.</li><li>Warm the olive oil in a medium Dutch oven over medium heat, add the unrinsed rice and jalapeño and cook, stirring, for 2–3 minutes.</li><li>Pour in the vegetable broth (careful of splatters), the tomato mixture, tomato paste and salt, stir, increase the heat and bring to a boil.</li><li>Cover with the lid and transfer to the oven. Bake for 1 hour 15–30 minutes until the liquid is absorbed and the rice is tender, stirring halfway.</li><li>Stir in the cilantro, adjust the salt and add a pinch of chilli flakes for more heat. Serve with lime wedges.</li></ol><p><em>Serve with lime wedges alongside tortillas, beans or meat.</em></p>', CURRENT_TIMESTAMP),
  ('7f0bc68a-6217-5b5f-9711-c8c466e09424', '79e579f7-d699-5adf-b3f1-bea519d7db1e', 'ru', 'Средиземноморский салат из красной фасоли и нута', 'Хрустящий и сытный салат из красной фасоли, нута, красного лука, сельдерея, огурца и свежей зелени с лимонно-чесночной заправкой.', '<ol><li>В салатнике соедините промытую красную фасоль, нут, нарезанный красный лук, сельдерей, нарезанный кубиками огурец (очищенный, без семян), петрушку и укроп.</li><li>Заправка: взбейте оливковое масло, лимонный сок, чеснок, соль и хлопья чили. Залейте салат и перемешайте.</li><li>Подавайте сразу или накройте и оставьте в холодильнике на пару часов. Хранится до 4 дней; при необходимости освежите щепоткой соли или лимонным соком.</li></ol><p><em>Подавайте сразу или оставьте мариноваться в холодильнике на пару часов.</em></p>', CURRENT_TIMESTAMP),
  ('b8f36e2d-e679-52cb-b2cc-737da8c555a5', '79e579f7-d699-5adf-b3f1-bea519d7db1e', 'en', 'Mediterranean kidney bean and chickpea salad', 'A crisp, hearty salad of kidney beans, chickpeas, red onion, celery, cucumber and fresh herbs with a lemon-garlic dressing.', '<ol><li>In a serving bowl combine the rinsed kidney beans, chickpeas, diced onion, celery, peeled and seeded cucumber, parsley and dill.</li><li>Dressing: whisk the olive oil, lemon juice, garlic, salt and chilli flakes. Pour over the salad and stir.</li><li>Serve immediately or cover and marinate in the fridge for a couple of hours. Keeps up to 4 days; refresh with a pinch of salt or a squeeze of lemon if needed.</li></ol><p><em>Serve right away or let it marinate in the fridge for a couple of hours.</em></p>', CURRENT_TIMESTAMP),
  ('6d0096b5-e9d7-598b-9a08-e8bb31042663', '83f82858-ca16-5e16-ba96-b4efbfe40f5a', 'ru', 'Греческий салат с ромэном, фетой и оливками', 'Нарезанный салат ромэн с помидорами черри, огурцом, перцем, красным луком, петрушкой, каламатой и фетой под греческой винегретной заправкой.', '<ol><li>В большой миске соедините нарезанный ромэн, четвертинки помидоров, огурец без семян, перец, лук, петрушку, оливки и кубики феты. Перемешайте и отставьте.</li><li>Заправка: взбейте оливковое масло, винный уксус, чеснок, орегано, мёд, соль, перец и хлопья чили. Попробуйте и при желании добавьте уксус для кислинки или мёд для мягкости.</li><li>Перед подачей полейте салат заправкой, слегка покрыв овощи, и перемешайте. Остаток заправки можно хранить отдельно.</li></ol><p><em>Если хранить салат и заправку отдельно, они сохранятся до 4 дней; перед подачей заправку взбейте.</em></p>', CURRENT_TIMESTAMP),
  ('056fb333-8ad5-5cf0-9f07-6f37db7f4f54', '83f82858-ca16-5e16-ba96-b4efbfe40f5a', 'en', 'Chopped Greek salad with romaine, feta and olives', 'Chopped romaine with cherry tomatoes, cucumber, pepper, red onion, parsley, Kalamata olives and feta with a Greek vinaigrette.', '<ol><li>In a large bowl combine the chopped romaine, quartered tomatoes, seeded cucumber, pepper, onion, parsley, olives and feta cubes. Toss and set aside.</li><li>Dressing: whisk the olive oil, vinegar, garlic, oregano, honey, salt, pepper and chilli flakes. Taste and add more vinegar for tang or honey to soften.</li><li>Just before serving drizzle enough dressing to coat the salad lightly and toss. Store any extra dressing separately.</li></ol><p><em>Stored separately from the dressing the salad keeps up to 4 days; whisk the dressing again before serving.</em></p>', CURRENT_TIMESTAMP),
  ('f2fb6ab8-100f-5dec-97fd-c91b6da23b8b', '8e3ba6c6-0472-5ce0-b3f7-356333856198', 'ru', 'Овощной суп с томатами, кейлом и карри', 'Лёгкий ароматный суп из лука, моркови, сельдерея, сезонных овощей и томатов с чесноком, карри, тимьяном и зелёной капустой кейл.', '<ol><li>В большой кастрюле на среднем огне разогрейте 3 ст. л. оливкового масла, добавьте лук, морковь, сельдерей, нарезанные сезонные овощи и 1/2 ч. л. соли. Готовьте, часто помешивая, 6–8 минут, пока лук не станет мягким и прозрачным.</li><li>Добавьте чеснок, карри и тимьян, около минуты обжаривайте до аромата. Влейте томаты с соком и готовьте ещё несколько минут.</li><li>Влейте бульон и воду, добавьте ещё 1/2 ч. л. соли, лавровый лист, хлопья чили и щедро молотого перца. Доведите до кипения, неплотно накройте крышкой и поддерживайте слабое кипение.</li><li>Варите 25 минут, затем откройте, добавьте нарезанный кейл и варите ещё 5 минут или дольше до нужной мягкости.</li><li>Снимите с огня, выньте лавровый лист, добавьте лимонный сок и оставшуюся ложку масла. Попробуйте и при необходимости досолите и поперчите.</li></ol><p><em>Хорошо хранится в холодильнике и замораживается порциями.</em></p>', CURRENT_TIMESTAMP),
  ('b78960d0-4590-5abe-a182-2f522f1596ff', '8e3ba6c6-0472-5ce0-b3f7-356333856198', 'en', 'Vegetable soup with tomatoes, kale and curry', 'A light, fragrant soup of onion, carrot, celery, seasonal vegetables and tomatoes with garlic, curry powder, thyme and kale.', '<ol><li>In a large pot warm 3 tbsp olive oil over medium heat, add the onion, carrot, celery, seasonal vegetables and 1/2 tsp salt. Cook, stirring often, 6–8 minutes until the onion is soft and translucent.</li><li>Add the garlic, curry powder and thyme and cook about a minute until fragrant. Pour in the tomatoes with their juices and cook a few more minutes.</li><li>Pour in the broth and water, add 1/2 tsp more salt, the bay leaves, chilli flakes and plenty of black pepper. Bring to a boil, partially cover and keep at a gentle simmer.</li><li>Cook for 25 minutes, then uncover, add the chopped kale and simmer 5 minutes or more until as soft as you like.</li><li>Remove from the heat, discard the bay leaves and stir in the lemon juice and remaining tablespoon of oil. Taste and adjust the seasoning.</li></ol><p><em>Keeps well in the fridge and freezes in portions.</em></p>', CURRENT_TIMESTAMP),
  ('a05a34c1-be1f-5d48-a6e6-87adedd1693c', 'd101ec8c-f3dc-5384-8530-d7c0cc259e9c', 'ru', 'Паста э фаджоли: итальянский суп с фасолью и макаронами', 'Густой вегетарианский суп-рагу с белой фасолью, мелкой пастой, томатами и кейлом, часть фасоли пюрируется для насыщенности.', '<ol><li>В большой кастрюле на среднем огне разогрейте 3 ст. л. масла, добавьте мелко нарезанные лук, морковь, сельдерей, 1/2 ч. л. соли и перец. Готовьте, часто помешивая, 6–10 минут до мягкости и прозрачности лука.</li><li>Добавьте чеснок на 30 секунд, затем томаты, и готовьте, пока они не начнут булькать. Влейте бульон и воду, добавьте лавровый лист, орегано и хлопья чили.</li><li>Прибавьте огонь, доведите до кипения и варите 10 минут, при необходимости уменьшая огонь.</li><li>Перелейте около 360 мл супа (без лаврового листа) в блендер, добавьте примерно 3/4 стакана фасоли и пюрируйте до гладкости (осторожно с горячим паром). Верните в суп.</li><li>Добавьте остальную фасоль, пасту, кейл и петрушку. Варите около 20 минут, часто помешивая, пока паста и зелень не станут мягкими.</li><li>Снимите с огня, выньте лавровый лист, добавьте лимонный сок, остаток масла и соль, при необходимости досолите и поперчите.</li></ol><p><em>Посыпьте петрушкой, чёрным перцем и сбрызните оливковым маслом; можно добавить тёртый пармезан.</em></p>', CURRENT_TIMESTAMP),
  ('8fdf965a-fbe6-5bce-8f2d-573b60b518a5', 'd101ec8c-f3dc-5384-8530-d7c0cc259e9c', 'en', 'Pasta e fagioli (Italian pasta and beans)', 'A hearty vegetarian soup-stew with white beans, small pasta, tomatoes and kale, with part of the beans blended for richness.', '<ol><li>Warm 3 tbsp of olive oil in a large pot over medium heat, add the finely chopped onion, carrot, celery, 1/2 tsp salt and pepper. Cook, stirring often, 6–10 minutes until softened and the onion is translucent.</li><li>Add the garlic for 30 seconds, then the tomatoes, and cook until bubbling. Add the broth, water, bay leaves, oregano and chilli flakes.</li><li>Raise the heat to medium-high, bring to a simmer and cook for 10 minutes, reducing the heat as needed.</li><li>Transfer about 1 1/2 cups of the soup (without the bay leaves) to a blender with about 3/4 cup of the beans and blend until smooth, mindful of hot steam. Pour back into the soup.</li><li>Add the remaining beans, pasta, kale and parsley. Cook for about 20 minutes, stirring often, until the pasta and greens are tender.</li><li>Remove from the heat, discard the bay leaves, stir in the lemon juice, remaining olive oil and salt, and adjust the seasoning.</li></ol><p><em>Garnish with parsley, black pepper and a drizzle of olive oil; Parmesan is optional.</em></p>', CURRENT_TIMESTAMP),
  ('c6e48a65-b988-5117-8838-b9bc3d42a0fd', '23014d50-e87c-572f-a3d9-060bfa52654a', 'ru', 'Стручковая фасоль с миндалём и шалотом', 'Тушёная стручковая фасоль с хрустящими миндальными лепестками, обжаренными на сливочном масле, нежным шалотом и каплей лимонного сока.', '<ol><li>В большой сковороде на среднем и слабом огне растопите масло. Добавьте миндальные лепестки и 7–8 минут жарьте, постоянно помешивая, пока масло не потемнеет, а миндаль не начнёт золотиться.</li><li>Добавьте шалот и минуту жарьте, помешивая. Влейте лимонный сок и 1 ст. л. воды и варите ещё около минуты, пока жидкость не загустеет.</li><li>Переложите смесь в миску. В ту же сковороду добавьте фасоль, 120 мл воды и соль, накройте и тушите на среднем огне, иногда помешивая, 9–10 минут до почти готовности.</li><li>Снимите крышку и выпарите жидкость на среднем и сильном огне 2–4 минуты.</li><li>Снимите с огня, добавьте миндальную смесь, перемешайте, посолите и поперчите и подавайте.</li></ol><p><em>Подавайте горячей к мясу, птице или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('16676072-c80a-5277-b51c-e0ef0661cd6b', '23014d50-e87c-572f-a3d9-060bfa52654a', 'en', 'Green beans amandine with shallot and lemon', 'Braised green beans with buttery toasted sliced almonds, tender shallot and a squeeze of lemon.', '<ol><li>In a large skillet over medium-low heat melt the butter, add the almonds and cook, stirring constantly, for 7–8 minutes until the butter has browned and the almonds start to brown.</li><li>Add the shallot and cook, stirring, for 1 minute. Stir in the lemon juice and 1 tbsp water and cook about 1 minute more until the liquid thickens.</li><li>Scoop the mixture into a bowl. In the same skillet add the green beans, 1/2 cup water and salt, cover and cook over medium heat, stirring occasionally, 9–10 minutes until nearly tender.</li><li>Remove the lid and cook over medium-high heat for 2–4 minutes until the liquid evaporates.</li><li>Off the heat add the almond mixture, toss, season with salt and pepper and serve.</li></ol><p><em>Serve hot with meat, poultry or fish.</em></p>', CURRENT_TIMESTAMP),
  ('7b242a08-b38d-55a8-afd2-d7b39499570d', '027da78a-a56d-54ca-b736-d6b43041b0ed', 'ru', 'Самса из слоёного теста филло с курицей и картофелем', 'Треугольные пирожки из тонкого теста филло с начинкой из рубленой курицы, картофеля, лука, чеснока, зиры и кориандра, запечённые до хруста. Всего получается около 18 штук, порция примерно 3 штуки.', '<ol><li>Выстелите два больших противня пергаментом. Смешайте в миске зиру, кориандр, соль и перец и отставьте.</li><li>Срежьте с курицы жир и нарежьте мелкими кубиками. Мелко нарежьте лук, измельчите чеснок, картофель нарежьте мелкими кубиками. Охлаждённое сливочное масло натрите на тёрке. Если используете зелень, мелко порубите.</li><li>Смешайте в миске курицу, лук, чеснок, зелень и картофель. Добавьте смесь специй, майонез и тёртое масло и перемешайте.</li><li>Разверните тесто филло и возьмите 3–4 листа. Положите один лист на рабочую поверхность и слегка смажьте растопленным маслом, повторите со всеми листами. Разрежьте стопку пополам вдоль на две равные полосы.</li><li>Положите щедрую порцию начинки в угол полосы, оставив свободное место по краям. Заверните треугольником и прижмите края, чтобы начинка не вытекала. Продолжайте складывать до конца полосы, так чтобы край теста оказался внизу треугольника. Повторите с остальным тестом и начинкой.</li><li>Смажьте верх маслом и посыпьте кунжутом. Выложите на противень и накройте фольгой.</li><li>Разогрейте духовку до 200 °C. Запекайте под фольгой 18 минут, затем снимите фольгу и запекайте ещё 10–12 минут до золотистого цвета.</li></ol><p><em>Подавайте горячими с кефиром, сметаной или свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('06d8993f-28f2-53a0-8716-507885c48000', '027da78a-a56d-54ca-b736-d6b43041b0ed', 'en', 'Uzbek samsa with chicken and potato in phyllo', 'Triangle pies of thin phyllo pastry filled with chopped chicken, potato, onion, garlic, cumin and coriander, baked until crisp. The batch makes about 18 pieces, roughly 3 per serving.', '<ol><li>Line 2 large baking sheets with parchment paper. Combine the cumin, coriander, salt and pepper in a bowl and set aside.</li><li>Trim the fat off the chicken and cut into small cubes. Finely chop the onion, mince the garlic and finely cube the potatoes. Grate the cold butter. Finely chop herbs if using.</li><li>In a bowl combine the chicken, onion, garlic, herbs and potatoes. Add the seasoning mixture, mayonnaise and grated butter and mix.</li><li>Unroll the phyllo dough and take 3 to 4 sheets. Lay one sheet on the work surface and lightly brush with melted butter, repeating with all the sheets. Cut the stack in half lengthwise into two equal strips.</li><li>Place a generous portion of filling at the corner end of each strip, leaving room around it. Fold over into a triangle and press the edges to seal. Keep folding to the end of the strip, tucking the dough edge on the bottom of the triangle. Repeat with the remaining dough and filling.</li><li>Brush the tops with butter and sprinkle with sesame seeds. Place on the baking sheet and cover with foil.</li><li>Preheat the oven to 200 °C (400 °F). Bake covered 18 minutes, then remove the foil and bake another 10-12 minutes until golden.</li></ol><p><em>Serve hot with kefir, sour cream or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('699a5224-d065-5bd4-bc9a-7aa511de088f', '8c8c7b11-0e71-5f2b-9d02-d7992cff2fb2', 'ru', 'Щи с говядиной, картофелем и свежей капустой', 'Наваристый суп с кусочками говядины, свежей капустой, картофелем и зажаркой из лука, моркови и помидоров с ложкой сметаны. Мясо заранее приправляют и выдерживают в холодильнике для более насыщенного вкуса.', '<ol><li>Нарежьте говядину кусочками. Посолите, поперчите, добавьте нарезанный чеснок и разломанный лавровый лист, перемешайте и уберите в холодильник минимум на сутки (до 5 суток) для насыщенного вкуса.</li><li>Доведите воду до кипения. Ополосните мясо, чтобы смыть лавровый лист и чеснок, и опустите в кипящую воду. Варите на средне-сильном огне 35–40 минут, пока мясо не станет мягким.</li><li>Тем временем мелко нарежьте лук, морковь натрите. Картофель нарежьте кубиками и залейте холодной водой. Капусту нашинкуйте.</li><li>Пассеруйте лук с 2 ч. л. масла 5 минут до мягкости, добавьте морковь и ещё 3 ч. л. масла и жарьте около 6 минут. Снимите с помидоров кожицу, нарежьте и добавьте к овощам. Добавьте кетчуп и сметану, перемешайте, томите минуту и снимите с огня.</li><li>Когда мясо станет мягким, добавьте слитый картофель, 2 ч. л. соли и ¼ ч. л. перца и варите 10 минут на средне-сильном огне.</li><li>Добавьте капусту и варите ещё 10–15 минут до готовности картофеля. Добавьте зажарку и зелень и варите ещё 2–3 минуты. Подавайте со сметаной.</li></ol><p><em>Подавайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('1af562e4-c2c6-51d9-af68-2cebe2912a5f', '8c8c7b11-0e71-5f2b-9d02-d7992cff2fb2', 'en', 'Russian-style beef, cabbage and potato soup', 'A hearty soup of beef chunks, fresh cabbage and potatoes with a sautéed onion, carrot and tomato base finished with a spoonful of sour cream. The meat is seasoned and rested in the fridge beforehand for a richer flavor.', '<ol><li>Cut the beef into bite-size pieces. Season with salt and pepper, add the sliced garlic and a broken bay leaf, mix and refrigerate at least one day (up to 5) for a deeper flavor.</li><li>Bring the water to a boil. Rinse the seasoned meat (just to remove the bay leaf and garlic), add to the boiling water and boil on medium-high 35-40 minutes until tender.</li><li>Meanwhile finely chop the onion and shred the carrots. Cube the potatoes and cover with cold water. Shred the cabbage.</li><li>Sauté the onion with 2 tsp oil about 5 minutes until soft, add the carrots and 3 tsp more oil and sauté about 6 minutes. Peel and chop the tomatoes and add. Stir in the ketchup and sour cream, simmer a minute and remove from the heat.</li><li>When the meat is tender, add the drained potatoes, 2 tsp salt and ¼ tsp pepper and cook 10 minutes over medium-high.</li><li>Add the cabbage and cook another 10-15 minutes until the potatoes are cooked. Add the sautéed vegetables and fresh herbs and cook 2-3 more minutes. Serve with sour cream.</li></ol><p><em>Serve with sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('d03203d6-ad46-56b8-8bbc-ced164ee8c68', '5506c4e5-56a1-51bd-b7a1-4169468e14ee', 'ru', 'Куриные шашлычки с овощами и грибами в медово-майонезном маринаде', 'Кусочки куриной грудки с разноцветным болгарским перцем, красным луком и шампиньонами в маринаде из майонеза, мёда, масла, чеснока и паприки, приготовленные на шпажках на гриле.', '<ol><li>Нарежьте курицу кусочками 2,5–4 см. Перец и лук нарежьте кусочками того же размера.</li><li>В одной миске смешайте сухие специи: паприку, соль и перец. В другой миске приготовьте маринад: майонез, масло, острый соус, чеснок и мёд.</li><li>Соедините овощи, целые грибы и курицу. Перемешайте с маринадом, посыпьте сухими специями и снова перемешайте. Мариновать от 30 минут до 4 часов (или на ночь).</li><li>Нанижите курицу и овощи на шпажки.</li><li>Жарьте на гриле на среднем огне 12–15 минут, переворачивая, чтобы все стороны прожарились (время зависит от гриля и размера кусочков).</li></ol><p><em>Подавайте с рисом или картофелем и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('d29c98b2-df7c-5e71-b49b-2308b026ad53', '5506c4e5-56a1-51bd-b7a1-4169468e14ee', 'en', 'Grilled chicken and vegetable kebabs in honey-mayo marinade', 'Chunks of chicken breast with colorful bell peppers, red onion and mushrooms marinated in mayonnaise, honey, oil, garlic and paprika and grilled on skewers.', '<ol><li>Cut the chicken into 1-1½ inch pieces. Cube the peppers and onion into pieces about the same size.</li><li>In one bowl mix the dry seasonings: paprika, salt and pepper. In another bowl make the marinade: mayo, oil, hot sauce, minced garlic and honey.</li><li>Combine the cut vegetables, whole mushrooms and chicken. Toss in the wet marinade, sprinkle with the dry seasonings and toss again. Marinate 30 minutes to 4 hours (or overnight).</li><li>Thread the chicken and vegetables onto skewers.</li><li>Grill over medium heat 12-15 minutes, turning so all sides cook (time depends on the grill and the size of the pieces).</li></ol><p><em>Serve with rice or potatoes and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('597adf6c-a4eb-5a51-985d-0214be31fcde', 'acabae95-858c-561c-b601-e827fd2437b8', 'ru', 'Кускус на гарнир: быстрый способ', 'Рассыпчатый кускус, который заваривается за 10 минут в кипящей воде или бульоне с каплей масла, быстрая замена рису и пасте.', '<ol><li>В кастрюле доведите воду или бульон до кипения. Когда закипит, добавьте оливковое масло или сливочное масло и соль (если используете воду).</li><li>Всыпьте кускус в кипяток и перемешайте, чтобы он распределился равномерно.</li><li>Сразу снимите с огня, плотно накройте крышкой и оставьте на 5–10 минут, пока кускус не впитает всю жидкость.</li><li>Разрыхлите кускус вилкой, чтобы зёрна не слипались.</li></ol><p><em>Подавайте к мясу, рыбе или тушёным овощам.</em></p>', CURRENT_TIMESTAMP),
  ('70bc41e4-2000-588b-beff-c1c604b3fee7', 'acabae95-858c-561c-b601-e827fd2437b8', 'en', 'Fluffy couscous side dish', 'Fluffy couscous steeped in boiling water or broth with a little oil in about 10 minutes, a quick alternative to rice or pasta.', '<ol><li>Bring the water or broth to a boil in a pot. Once boiling add the olive oil or butter and salt if using water.</li><li>Add the couscous to the boiling liquid and stir so it is evenly distributed.</li><li>Immediately take off the heat, cover tightly with a lid and leave for 5–10 minutes until all the liquid is absorbed.</li><li>Fluff the couscous with a fork to separate the grains.</li></ol><p><em>Serve with meat, fish or braised vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('fec721bf-1cc6-5c57-b68a-1b4d75ef71ba', '436dcdcc-b505-55a7-be3f-3bba9d8dfaab', 'ru', 'Картофельный гратен с сыром, молоком и чесноком', 'Запеканка из тонких ломтиков картофеля слоями с молочно-луковой смесью с чесноком и чеддером, с золотистой пармезанной корочкой.', '<ol><li>Разогрейте духовку до 190 °C, поставьте решётку по центру. Смажьте форму 23×33 см маслом.</li><li>В кастрюле или глубокой сковороде на среднем и слабом огне растопите масло, 8–10 минут тушите лук до прозрачности, часто помешивая. Добавьте чеснок на минуту и выключите огонь.</li><li>Влейте молоко, добавьте 1 ч. л. соли и перец, оставьте остывать.</li><li>Очистите картофель и очень тонко нарежьте на мандолине или острым ножом (3–6 мм, чем тоньше, тем лучше). Посыпьте мукой и оставшейся солью и руками перемешайте до равномерного покрытия.</li><li>Выложите треть картофеля на дно формы, полейте 1 стаканом молочной смеси, посыпьте 1/2 стакана чеддера. Повторите ещё два раза, закончив сыром.</li><li>Накройте форму смазанной фольгой и запекайте 35 минут, затем снимите фольгу и запекайте ещё 25 минут до мягкости картофеля.</li><li>Достаньте, посыпьте пармезаном и включите гриль на 1–3 минуты, пока сыр не станет золотистым и пузырящимся (не отходите, чтобы не подгорело).</li><li>Оставьте при комнатной температуре на 20–25 минут, чтобы соус загустел, затем подавайте.</li></ol><p><em>Дайте запеканке постоять 20–25 минут, чтобы соус загустел; можно приготовить заранее.</em></p>', CURRENT_TIMESTAMP),
  ('31fd0cfc-d24c-5e9f-a57d-b81e83d8f8f9', '436dcdcc-b505-55a7-be3f-3bba9d8dfaab', 'en', 'Cheesy scalloped potatoes with garlic and milk', 'A bake of thinly sliced potatoes layered with a garlicky onion-milk mixture and cheddar, finished with a golden Parmesan crust.', '<ol><li>Place a rack in the center of the oven and preheat to 190 °C. Grease a 9×13-inch casserole dish.</li><li>In a pot or deep skillet melt the butter over medium-low heat and cook the onion for 8–10 minutes until translucent, stirring often. Add the garlic for about 1 minute and turn off the heat.</li><li>Stir in the milk, 1 tsp of the salt and the pepper and set aside to cool.</li><li>Peel the potatoes and slice very thinly (1/8–1/4 inch) with a mandoline or sharp knife, the thinner the better. Sprinkle with the flour and remaining salt and toss with your hands to coat evenly.</li><li>Spread a third of the potatoes in the dish, spoon over 1 cup of the milk mixture and sprinkle with 1/2 cup cheddar. Repeat twice more, finishing with cheese.</li><li>Cover the dish with greased foil and bake for 35 minutes, then uncover and bake for another 25 minutes until the potatoes are tender.</li><li>Remove, sprinkle with Parmesan and switch on the broiler for 1–3 minutes until golden and bubbly; do not walk away.</li><li>Let stand at room temperature for 20–25 minutes so the sauce thickens, then serve.</li></ol><p><em>Let the dish stand 20–25 minutes so the sauce sets; can be made ahead.</em></p>', CURRENT_TIMESTAMP),
  ('a7f623fe-3ba0-560b-a327-4a64cdb5adc6', 'ce5f421f-7069-52e4-8cad-f7eddeb91d4a', 'ru', 'Бургеры из индейки по-итальянски с сыром и жареным перцем', 'Сочные котлеты из фарша индейки и индюшачьих колбасок с итальянскими травами и сыром асьяго и моцарелла на булочках с обжаренными луком и перцем.', '<ol><li>Разогрейте гриль до среднего и сильного нагрева. В большой миске соедините фарш индейки, индюшачьи колбаски без оболочки, панировочные сухари, базилик, орегано, семена фенхеля, чесночный порошок, соль, перец и хлопья чили.</li><li>Аккуратно перемешайте пальцами до равномерного распределения, не уплотняя мясо. Сформируйте 6 котлет.</li><li>Жарьте на гриле на среднем и сильном огне около 5 минут до румяности снизу, затем переверните и жарьте ещё около 5 минут до готовности. Когда котлеты почти готовы, выложите сверху моцареллу и асьяго.</li><li>Тем временем смешайте нарезанные красный лук и зелёный и красный перец с маслом, солью и перцем. Обжарьте на гриле в специальной корзине около 8 минут, часто переворачивая, до мягкости и лёгкого обугливания.</li><li>Подсушите булочки по желанию, выложите котлеты на булочки, сверху овощи. Подавайте сразу.</li></ol><p><em>Подавайте сразу на тёплых булочках с овощами.</em></p>', CURRENT_TIMESTAMP),
  ('168cbc4a-5788-5901-b630-311d9cb5bc4a', 'ce5f421f-7069-52e4-8cad-f7eddeb91d4a', 'en', 'Italian turkey burgers with cheese and grilled peppers', 'Juicy patties of ground turkey and turkey sausage with Italian herbs, topped with Asiago and mozzarella on buns with grilled onion and peppers.', '<ol><li>Preheat a grill to medium-high. In a large bowl combine the ground turkey, turkey sausage without casings, breadcrumbs, basil, oregano, fennel seeds, garlic powder, salt, pepper and chilli flakes.</li><li>Gently mix with your fingers until fairly evenly incorporated, without compacting the meat. Shape into 6 patties.</li><li>Grill on medium-high until browned on the bottom, about 5 minutes, then flip and grill about 5 minutes more until cooked through. When almost ready, top with mozzarella and Asiago.</li><li>Meanwhile toss the sliced red onion and the green and red bell peppers with olive oil, salt and pepper. Grill in a basket for about 8 minutes, turning often, until softened and lightly charred.</li><li>Toast the buns if you like, put the burgers on the buns and top with the grilled vegetables. Serve immediately.</li></ol><p><em>Serve right away on warm buns with the grilled vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('92c74eb4-4717-5590-920e-79cd0dce7efe', '52e0235e-26ae-51a2-beb4-b03b09a6e7ad', 'ru', 'Куриные отбивные в сливочно-грибном соусе с тимьяном', 'Обжаренные в муке куриные отбивные в соусе из грибов, шалота, бульона и сливок с горчицей и тимьяном.', '<ol><li>Каждую грудку разрежьте вдоль пополам, чтобы получились два тонких куска, при необходимости отбейте до толщины около 1,2 см. Посолите и поперчите с двух сторон.</li><li>Слегка обваляйте куски в муке с двух сторон.</li><li>На толстой сковороде на среднем и сильном огне разогрейте 1 ст. л. масла и обжарьте по 2 куска по 2–3 минуты с каждой стороны до золотистого цвета (внутри 71 °C). Переложите на тарелку и накройте фольгой. Так же поджарьте остальные, добавив масло.</li><li>Убавьте огонь до среднего, добавьте сливочное масло, грибы, шалот, чеснок и соль. Готовьте около 10 минут, пока грибы не отдадут влагу, жидкость не выпарится и они не начнут подрумяниваться. Переложите грибы на тарелку.</li><li>Влейте бульон, соскребая всё со дна, добавьте горчицу и уксус. Варите, помешивая, пока жидкость не уменьшится вдвое, около 3 минут.</li><li>Тонкой струйкой влейте сливки, постоянно взбивая. Верните курицу и грибы в сковороду, прогрейте минуту-две, переворачивая курицу в соусе. Посыпьте тимьяном и подавайте.</li></ol><p><em>Подавайте с картофельным пюре или рисом, полив грибным соусом.</em></p>', CURRENT_TIMESTAMP),
  ('ef3cb203-0773-56f3-8880-375c21e223a9', '52e0235e-26ae-51a2-beb4-b03b09a6e7ad', 'en', 'Creamy mushroom chicken cutlets with thyme', 'Flour-dredged chicken cutlets seared and smothered in a sauce of mushrooms, shallot, broth and cream with mustard and thyme.', '<ol><li>Slice each breast horizontally in half to make two thinner cutlets and pound to about 1.2 cm if needed. Season both sides with salt and pepper.</li><li>Lightly dredge each piece in the flour on both sides.</li><li>In a heavy skillet over medium-high heat warm 1 tbsp of oil and sear 2 pieces for 2–3 minutes per side until golden (71 °C inside). Move to a plate and tent with foil. Repeat with the rest, adding oil.</li><li>Reduce the heat to medium, add the butter, mushrooms, shallot, garlic and salt and cook about 10 minutes until the mushrooms release their liquid, it evaporates and they begin to brown. Remove the mushrooms.</li><li>Pour in the broth, scraping up the stuck bits, and whisk in the mustard and vinegar. Simmer, whisking, until reduced by half, about 3 minutes.</li><li>Slowly pour in the cream while whisking. Return the chicken and mushrooms to the pan, warm for a minute or two turning the chicken in the sauce. Sprinkle with thyme and serve.</li></ol><p><em>Serve with mashed potatoes or rice, spooning the mushroom sauce over the top.</em></p>', CURRENT_TIMESTAMP),
  ('69493c5c-28dc-5ca7-9887-28c1235263ff', '5eb482e0-7e9a-5212-990a-d0fbe7cc2fc8', 'ru', 'Овощной ло мейн с яйцом, соевым соусом и имбирём', 'Лапша с яичным омлетом, грибами, сахарным горошком, болгарским перцем и ароматной заправкой из сои, имбиря и чеснока.', '<ol><li>Отварите лапшу до состояния «аль денте» в подсоленной воде по инструкции. Слейте воду, добавьте немного оливкового масла, чтобы не слиплась, и отставьте.</li><li>Разогрейте широкую глубокую сковороду или вок на среднем огне. Взбейте яйца. Добавьте в горячую сковороду 2 ч. л. кунжутного масла, влейте яйца и дайте распределиться тонким слоем. Готовьте без помешивания 2–3 минуты до схватывания.</li><li>Переложите омлет на доску, слегка остудите и нарежьте кусочками или полосками.</li><li>Верните сковороду на огонь, добавьте 2 ст. л. оливкового масла. Быстро обжарьте две трети зелёного лука, чеснок, имбирь и хлопья чили до сильного аромата, около 30 секунд. Добавьте грибы и 1 ст. л. соевого соуса и жарьте минуту.</li><li>Добавьте сахарный горошек и перец, увеличьте огонь и жарьте около 5 минут до состояния «хрустящий и мягкий».</li><li>Добавьте лапшу и омлет, полейте оставшимся соевым соусом и 1 ч. л. кунжутного масла, аккуратно перемешайте. Подавайте сразу с оставшимся зелёным луком.</li></ol><p><em>Подавайте сразу, посыпав зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('24867cac-560c-5389-b12b-9c0141f339ed', '5eb482e0-7e9a-5212-990a-d0fbe7cc2fc8', 'en', 'Vegetable lo mein with egg, soy and ginger', 'Noodles with an egg omelette, mushrooms, sugar snap peas, bell peppers and a fragrant sauce of soy, ginger and garlic.', '<ol><li>Cook the noodles until al dente in salted water according to the package. Drain, toss with a little olive oil to prevent sticking and set aside.</li><li>Heat a wide, deep skillet or wok over medium heat and beat the eggs. Add 2 tsp sesame oil to the hot pan, pour in the eggs and let them form a thin layer. Cook without stirring 2–3 minutes until just set.</li><li>Slide the omelette onto a board, let cool slightly and cut into pieces or strips.</li><li>Return the pan to the heat and add 2 tbsp olive oil. Quickly cook two thirds of the green onions, the garlic, ginger and chilli flakes until very fragrant, about 30 seconds. Add the mushrooms and 1 tbsp soy sauce and cook for 1 minute.</li><li>Add the snap peas and bell peppers, increase the heat and cook about 5 minutes until crisp-tender.</li><li>Add the noodles and eggs, drizzle with the remaining soy sauce and 1 tsp sesame oil and toss gently. Serve immediately garnished with the remaining green onions.</li></ol><p><em>Serve immediately topped with green onions.</em></p>', CURRENT_TIMESTAMP),
  ('534596aa-a1d1-557f-b86b-e433b1187bde', 'f5474c02-8229-56f0-abf9-4dee2c75a754', 'ru', 'Картофельное пюре со сливочным сыром и йогуртом', 'Очень нежное картофельное пюре со сливочным маслом, бульоном, молоком, сливочным сыром и греческим йогуртом.', '<ol><li>Очистите картофель и нарежьте кусками по 5 см примерно одного размера, чтобы он сварился равномерно. Сложите в большую кастрюлю и залейте холодной водой на 2,5 см выше.</li><li>Добавьте соль, доведите до кипения на сильном огне, затем убавьте и варите на слабом огне 20–30 минут, пока картофель не станет мягким и легко не прокалывается вилкой, но не разваливается.</li><li>Слейте воду и коротко сполосните картофель тёплой водой, чтобы удалить лишний крахмал. Оставьте в тепле.</li><li>В небольшой кастрюле на среднем огне нагрейте масло, бульон и молоко, пока масло не растает. Снимите с огня и добавьте размягчённый сливочный сыр кубиками.</li><li>Пока картофель ещё тёплый (не давайте ему остыть, иначе пюре будет клейким), пропустите его через картофелемялку (ricer) в большую миску или разомните толкушкой в кастрюле примерно наполовину.</li><li>Посыпьте картофель солью и перцем, добавьте йогурт и влейте тёплую масляную смесь. Аккуратно перемешайте до гладкости, не перетирая. Попробуйте и при необходимости досолите.</li></ol><p><em>Подавайте тёплым к котлетам, курице и подливам; остатки можно разогреть.</em></p>', CURRENT_TIMESTAMP),
  ('e93e393e-e570-5103-bbc1-12a66210bd3a', 'f5474c02-8229-56f0-abf9-4dee2c75a754', 'en', 'Creamy mashed potatoes with cream cheese and yogurt', 'Very creamy mashed potatoes with butter, chicken broth, milk, cream cheese and Greek yogurt.', '<ol><li>Peel the potatoes and cut into 2-inch (5 cm) chunks of similar size so they cook evenly. Place in a large pot and cover with cool water by 1 inch.</li><li>Add the salt and bring to a boil over high heat, then reduce and simmer gently for 20–30 minutes until tender and easily pierced with a fork but not falling apart.</li><li>Drain the potatoes and briefly rinse with warm water to remove excess starch. Keep them handy.</li><li>In a saucepan heat the butter, broth and milk over medium heat until the butter melts. Remove from the heat and add the softened cubes of cream cheese.</li><li>While the potatoes are still warm (do not let them cool or they will be gummy) pass them through a potato ricer into a large bowl, or mash them halfway with a masher in the pot.</li><li>Sprinkle the potatoes with salt and pepper, add the yogurt and pour over the warm butter mixture. Stir gently until smooth, without overworking. Taste and adjust the seasoning.</li></ol><p><em>Serve warm with cutlets, chicken and gravy; leftovers reheat well.</em></p>', CURRENT_TIMESTAMP),
  ('09803fcc-409d-577c-9f45-266875240241', 'fa0b72d6-9463-5cad-bc63-b097faed8888', 'ru', 'Упрощённый борщ без мяса со свёклой, капустой и картофелем', 'Лёгкий вариант классического борща без мяса: свёкла, капуста, картофель, морковь, сельдерей, помидоры и зелень на курином бульоне с каплей лимонного сока в конце.', '<ol><li>Мелко нарежьте лук, морковь натрите на тёрке.</li><li>В жаровне или кастрюле на среднем огне разогрейте масло со сливочным маслом, обжарьте лук и морковь около 5 минут до мягкости.</li><li>Тем временем мелко нарежьте сельдерей, перец нарежьте кубиками, свёклу натрите, помидоры нарежьте. Добавьте к овощам и готовьте ещё 5 минут, помешивая. Добавьте чеснок.</li><li>Влейте бульон и воду, добавьте лавровый лист и картофель и доведите до слабого кипения.</li><li>Нашинкуйте капусту, добавьте в суп вместе с солью, перцем и сахаром и варите 12–15 минут.</li><li>Когда картофель и капуста станут мягкими, добавьте лимонный сок и измельчённую зелень.</li></ol><p><em>Подавайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('b220f9aa-49eb-5a2e-bd71-a89532f91fdb', 'fa0b72d6-9463-5cad-bc63-b097faed8888', 'en', 'Simplified meatless borscht with beets, cabbage and potatoes', 'An easier version of classic borscht without meat: beets, cabbage, potatoes, carrots, celery, tomatoes and herbs in chicken broth, finished with a touch of lemon juice.', '<ol><li>Finely chop the onion and shred the carrots.</li><li>In a Dutch oven over medium heat warm the oil and butter. Sauté the onions and carrots about 5 minutes until tender.</li><li>Meanwhile finely chop the celery, cube the pepper, grate the beets and dice the tomatoes. Add to the pot and sauté another 5 minutes, stirring. Mix in the garlic.</li><li>Add the broth, water, bay leaves and potatoes and bring to a soft boil.</li><li>Shred the cabbage and add it to the soup with the salt, pepper and sugar. Cook 12-15 minutes.</li><li>Once the potatoes and cabbage are tender, add the lemon juice and chopped herbs.</li></ol><p><em>Serve with sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('77aa3d61-6c66-5b1d-81d4-453061b3d7fc', '02d7b6c8-6444-50cd-8424-807cec0f83da', 'ru', 'Говяжьи фрикадельки, запечённые в томатном соусе с базиликом', 'Сочные фрикадельки из говяжьего фарша с тёртым луком, яйцом, пармезаном и базиликом, обжаренные и запечённые в духовке под томатным соусом с чесноком и травами.', '<ol><li>Смешайте руками все ингредиенты для фрикаделек в миске. Смочите руки водой и скатайте шарики одинакового размера.</li><li>В горячую сковороду влейте масло и обжарьте фрикадельки со всех сторон до корочки. Переложите их в большую форму для запекания.</li><li>Для соуса в кастрюле растопите оливковое масло со сливочным, обжарьте лук до прозрачности. Добавьте томаты, воду, чеснок, соль и перец. Варите 5 минут, при желании пробейте погружным блендером. Добавьте базилик, орегано и петрушку и варите ещё пару минут.</li><li>Залейте фрикадельки соусом в форме, накройте фольгой и запекайте при 190 °C 45 минут, затем снимите фольгу и запекайте ещё 3 минуты.</li></ol><p><em>Подавайте с пастой, пюре или хлебом, посыпав свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('e933feba-cce3-52fb-ae90-7647c3e0b5a2', '02d7b6c8-6444-50cd-8424-807cec0f83da', 'en', 'Baked beef meatballs in tomato basil sauce', 'Juicy beef meatballs with grated onion, egg, Parmesan and basil, seared and baked in the oven under a tomato sauce with garlic and herbs.', '<ol><li>Combine the meatball ingredients in a bowl and mix with your hands. Wet your hands and shape the mixture into equal-sized meatballs.</li><li>Add oil to a hot pan and sear the meatballs on all sides. Transfer to a large casserole dish.</li><li>For the sauce, melt the olive oil and butter in a saucepan and cook the onion until translucent. Add the tomatoes, water, garlic, salt and pepper. Simmer 5 minutes, using an immersion blender if you like. Stir in the basil, oregano and parsley and simmer a couple more minutes.</li><li>Pour the sauce over the meatballs in the dish, cover with foil and bake at 190 °C (375 °F) for 45 minutes, then remove the foil and bake 3 more minutes.</li></ol><p><em>Serve with pasta, mashed potatoes or bread and sprinkle with fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('3c01da04-834c-572a-807d-359dba725ffe', 'b052e857-21b1-58e0-be56-388073fdcd50', 'ru', 'Куриная шаурма из бёдер на гриле с овощами в пите', 'Куриные бёдра, замаринованные с луком, чесноком, зирой, кориандром, паприкой, куркумой и лимонным соком, обжаренные на гриле и поданные в пите со свежими овощами.', '<ol><li>В небольшой миске смешайте ингредиенты маринада: масло, чеснок, специи, соль, перец и лимонный сок.</li><li>В большой миске соедините бёдра, тонко нарезанный лук и маринад. Оставьте мариноваться минимум на полчаса (или на ночь).</li><li>Разогрейте гриль. Выложите курицу и жарьте по 6–7 минут с каждой стороны до готовности.</li><li>Нарежьте огурец, помидоры, салат и красный лук. При желании приготовьте половину порции соуса цацики.</li><li>Возьмите питу, положите в неё курицу, сверху овощи и соус.</li></ol><p><em>Заверните курицу в питу с огурцом, помидорами, ромэном, красным луком и соусом цацики.</em></p>', CURRENT_TIMESTAMP),
  ('968de5ae-41dd-5abb-95ed-18103635528a', 'b052e857-21b1-58e0-be56-388073fdcd50', 'en', 'Grilled chicken thigh shawarma in pita with vegetables', 'Chicken thighs marinated with onion, garlic, cumin, coriander, paprika, turmeric and lemon juice, grilled and served in pita with fresh vegetables.', '<ol><li>In a small bowl combine the marinade ingredients: oil, garlic, spices, salt, pepper and lemon juice.</li><li>In a large bowl combine the chicken thighs, thinly sliced onion and marinade. Marinate at least half an hour (or overnight).</li><li>Heat the grill. Add the chicken and cook 6-7 minutes per side until cooked through.</li><li>Slice and cube the cucumber, tomatoes, romaine and red onion. Make half a portion of tzatziki sauce if you like.</li><li>Take a pita, add the cooked chicken and top with the vegetables and tzatziki sauce.</li></ol><p><em>Fill the pita with the chicken, cucumber, tomatoes, romaine, red onion and tzatziki.</em></p>', CURRENT_TIMESTAMP),
  ('bb0da63b-9554-5c6f-b127-fc996139ac47', 'ac36ea5c-9789-51aa-85c8-98417f2f556a', 'ru', 'Бифштексы из говяжьего фарша в грибном соусе (салисбери)', 'Котлеты из говяжьего фарша с луком, чесноком и итальянскими травами, обжаренные и протушенные в густом соусе с шампиньонами на говяжьем бульоне. Ужин готов меньше чем за полчаса.', '<ol><li>Смешайте в миске все ингредиенты для котлет и сформируйте круглые лепёшки.</li><li>Разогрейте в сковороде 1 ст. л. масла и обжарьте котлеты до полной готовности, перевернув на середине. Снимите их и накройте, чтобы не остыли.</li><li>В той же сковороде обжарьте лук до мягкости. Добавьте чеснок и сливочное масло и жарьте до аромата. Добавьте грибы и обжарьте до румяности, слегка посолите и поперчите.</li><li>Для соуса взбейте муку, бульон, воду, вустерский соус, горчицу, кетчуп, соль и перец и влейте к грибам. Варите на слабо-среднем огне до загустения.</li><li>Верните котлеты в сковороду, покройте соусом с грибами и прогрейте.</li></ol><p><em>Подавайте с картофельным пюре, рисом или лапшой, полив соусом.</em></p>', CURRENT_TIMESTAMP),
  ('cb5d3209-0fb0-5a06-9898-7ff33a95ce0a', 'ac36ea5c-9789-51aa-85c8-98417f2f556a', 'en', 'Salisbury steak: beef patties in mushroom gravy', 'Beef patties with onion, garlic and Italian seasoning, pan-fried and simmered in a thick beef broth gravy with mushrooms. Dinner is ready in under half an hour.', '<ol><li>In a bowl combine all the patty ingredients and shape into round disks.</li><li>Heat 1 tbsp oil in a skillet and cook the patties until fully cooked, flipping halfway. Remove and cover to keep warm.</li><li>In the same skillet sauté the onion until tender. Add the garlic and butter and cook until fragrant. Add the mushrooms and sauté until brown, seasoning lightly with salt and pepper.</li><li>Whisk together the flour, broth, water, Worcestershire, mustard, ketchup, salt and pepper and pour over the mushrooms. Cook over low-medium heat until it thickens.</li><li>Return the patties to the pan, coat them in the gravy and mushrooms and heat through.</li></ol><p><em>Serve with mashed potatoes, rice or noodles and spoon the gravy over.</em></p>', CURRENT_TIMESTAMP),
  ('f71123e5-fd83-55f7-bf72-61d3015b423d', '599a924a-3853-563c-9d9f-5da841a02cfc', 'ru', 'Сливочный овощной суп с беконом, брокколи, кукурузой и чеддером', 'Густой суп на курином бульоне и молоке с картофелем, морковью, брокколи и кукурузой, хрустящим беконом и тёртым сыром чеддер. Простой и очень сытный.', '<ol><li>Нарежьте бекон и обжарьте в жаровне на среднем огне до хруста. Выньте бекон, жир оставьте в кастрюле.</li><li>Очистите картофель, нарежьте кубиками и залейте холодной водой.</li><li>В кастрюлю с жиром добавьте морковь и лук и готовьте несколько минут до мягкости. Добавьте чеснок до аромата.</li><li>Влейте бульон и воду, добавьте картофель, доведите до кипения, убавьте огонь и варите 10 минут.</li><li>Добавьте соцветия брокколи и кукурузу и готовьте несколько минут.</li><li>В миске взбейте молоко с мукой до отсутствия комков, влейте в суп, добавьте соль, перец и бекон.</li><li>Убавьте огонь до минимума и добавляйте сыр по горсти, помешивая после каждой, пока он не растает. Подавайте.</li></ol><p><em>Подавайте горячим с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('2f684530-86fd-5a30-b04e-d369d371faac', '599a924a-3853-563c-9d9f-5da841a02cfc', 'en', 'Creamy vegetable soup with bacon, broccoli, corn and cheddar', 'A thick soup of chicken broth and milk with potatoes, carrots, broccoli and corn, crisp bacon and shredded cheddar. Simple and very filling.', '<ol><li>Chop the bacon and cook in a Dutch oven over medium heat until crisp. Remove the bacon and leave the grease in the pot.</li><li>Peel and cube the potatoes and cover with cold water.</li><li>To the pot add the carrots and onion and cook a few minutes until soft. Add the garlic and cook until fragrant.</li><li>Pour in the broth and water, add the potatoes, bring to a boil, lower the heat and simmer 10 minutes.</li><li>Stir in the broccoli florets and corn and cook a few minutes.</li><li>Whisk the milk with the flour in a bowl to remove lumps, add to the pot with the salt and pepper and return the bacon.</li><li>Turn the heat to low and add the shredded cheese a handful at a time, stirring after each until melted. Serve.</li></ol><p><em>Serve hot with bread.</em></p>', CURRENT_TIMESTAMP),
  ('f782453c-2d2f-5b3b-8dd9-eb17f35381b9', 'd04d2784-5b0b-5fe8-a94a-b217fe25f904', 'ru', 'Запечённые овощи: картофель, тыква, морковь, кабачок и перец', 'Осенний гарнир из запечённых овощей с чесноком и сыром: жёсткие овощи запекаются на 10 минут дольше, остальные добавляются позже.', '<ol><li>Разогрейте духовку до 230 °C, решётку поставьте по центру. Застелите два противня фольгой и щедро смажьте маслом.</li><li>Картофель (в кожуре), тыкву, морковь и половину чеснока смешайте в большой миске с 2 ст. л. масла, перцем и 2 ч. л. соли с чесночным порошком. Разделите между двумя противнями и запекайте без крышки 10 минут.</li><li>В той же миске смешайте кабачок, перец, оставшийся чеснок, 1 ст. л. масла, перец и остаток приправы.</li><li>Достаньте противни, быстро распределите смесь сверху и запекайте ещё 20–25 минут, пока картофель и тыква не станут мягкими.</li><li>Посыпьте тёртым сыром и на 1–2 минуты поставьте под гриль, пока сыр не расплавится.</li></ol><p><em>Подавайте горячими к мясу, птице или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('0f3fdce5-79ff-55f0-844e-b21cc95bccbf', 'd04d2784-5b0b-5fe8-a94a-b217fe25f904', 'en', 'Roasted vegetables: potato, butternut squash, carrot, zucchini and pepper', 'An autumn side of oven-roasted vegetables with garlic and cheese; the firmer vegetables roast 10 minutes longer before the softer ones are added.', '<ol><li>Preheat the oven to 230 °C with the rack in the center. Line two baking pans with foil and grease them generously with oil.</li><li>Toss the unpeeled potatoes, squash, carrots and half of the garlic in a large bowl with 2 tbsp oil, pepper and salt with garlic powder. Divide between the pans and roast uncovered for 10 minutes.</li><li>In the same bowl mix the zucchini, bell pepper, remaining garlic, 1 tbsp oil, pepper and the rest of the seasoning.</li><li>Take out the pans, quickly spread the mixture over the top and roast another 20–25 minutes until the potatoes and squash are tender.</li><li>Sprinkle with shredded cheese and broil for 1–2 minutes until melted.</li></ol><p><em>Serve hot with meat, poultry or fish.</em></p>', CURRENT_TIMESTAMP),
  ('d838cf9e-4021-5a2c-8939-9ae92f49bc68', '416c7fbb-86aa-5d23-8857-0955e43b5493', 'ru', 'Куриные полоски в сухарях из духовки с медово-горчичным соусом', 'Куриное филе в горчично-майонезно-чесночной маринаде и сухарях, запечённое до хрустящей золотистой корочки, с медово-горчичным соусом.', '<ol><li>Разогрейте духовку до 230 °C и застелите большой противень фольгой.</li><li>В большой миске взбейте дижонскую горчицу, майонез и пропущенный через пресс чеснок и дайте настояться, пока готовите курицу. Сухари высыпьте во вторую миску.</li><li>Промойте и обсушите филе, срежьте лишний жир и нарежьте полосками толщиной 2,5 см. Слегка посолите и поперчите.</li><li>Обмакните полоски в маринад, перемешайте, затем несколько раз обваляйте в сухарях и выложите на противень, не тесня, чтобы корочка получилась хрустящей.</li><li>Запекайте при 230 °C 15–17 минут до готовности курицы и золотистой корочки.</li><li>Соус: смешайте в миске (или блендере) горчицу, мёд и майонез, добавьте мак при желании. Охладите до подачи.</li></ol><p><em>Подавайте тёплыми с медово-горчичным соусом, кетчупом или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('5b7d1066-71f7-50eb-993a-565364b64176', '416c7fbb-86aa-5d23-8857-0955e43b5493', 'en', 'Baked breaded chicken strips with honey mustard dip', 'Chicken breast strips in a mustard-mayo-garlic coating and breadcrumbs, baked until crisp and golden, with a honey mustard dip.', '<ol><li>Preheat the oven to 230 °C and line a large rimmed baking sheet with foil.</li><li>In a large bowl whisk the Dijon, mayonnaise and pressed garlic and leave to infuse while you prep the chicken. Put the breadcrumbs in a second bowl.</li><li>Rinse and pat the chicken dry, trim excess fat and cut into 1-inch (2.5 cm) strips. Lightly season with salt and pepper.</li><li>Coat the strips in the marinade, then roll in the breadcrumbs a couple of times and place on the pan without crowding for a crisp crust.</li><li>Bake at 230 °C for 15–17 minutes until cooked through and golden.</li><li>Dip: mix the mustard, honey and mayonnaise in a bowl or blender, stir in poppy seeds if using, and refrigerate until serving.</li></ol><p><em>Serve warm with the honey mustard dip, ketchup or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('74a0c037-69f2-5cfe-ad6c-67a954b1d609', '77fe1291-887e-5be4-9a8e-ac00acb31360', 'ru', 'Лосось терияки, запечённый в духовке', 'Кусочки лосося в сладко-солёном маринаде из терияки, хойсина, сои и имбиря, запечённые и политые загустевшим соусом.', '<ol><li>Разогрейте духовку до 200 °C, застелите противень фольгой и смажьте маслом. Нарежьте лосось полосками шириной 5 см.</li><li>Смешайте соусы терияки, хойсин и соевый, уксус, кунжутное масло, коричневый сахар, чеснок и имбирь до растворения сахара.</li><li>Залейте лосось соусом, накройте плёнкой и маринуйте 20 минут при комнатной температуре или в холодильнике.</li><li>Переложите лосось на противень (маринад сохраните) и запекайте 12–16 минут до расслаивания и готовности, в зависимости от толщины.</li><li>Пока лосось печётся, вылейте остатки маринада в ковшик, доведите до кипения и варите на слабом огне 3–4 минуты до небольшого загустения.</li><li>Смажьте готового лосося сиропом и посыпьте зелёным луком и кунжутом.</li></ol><p><em>Подавайте с рисом и овощами, посыпав кунжутом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('db021028-04f0-5b59-8e92-164e934e058d', '77fe1291-887e-5be4-9a8e-ac00acb31360', 'en', 'Baked teriyaki salmon with hoisin glaze', 'Salmon pieces in a sweet-salty teriyaki, hoisin, soy and ginger marinade, baked and brushed with the thickened sauce.', '<ol><li>Preheat the oven to 200 °C and line a baking sheet with greased foil. Cut the salmon into 2-inch (5 cm) wide pieces.</li><li>Stir together the teriyaki, hoisin and soy sauces, vinegar, sesame oil, brown sugar, garlic and ginger until the sugar dissolves.</li><li>Pour the sauce over the salmon, cover and marinate 20 minutes at room temperature or in the fridge.</li><li>Transfer the salmon to the pan (keep the marinade) and bake 12–16 minutes until flaky and cooked through, depending on thickness.</li><li>Meanwhile pour the leftover marinade into a small saucepan, bring to a boil and simmer 3–4 minutes until slightly thickened.</li><li>Brush the baked salmon with the syrup and sprinkle with green onion and sesame seeds.</li></ol><p><em>Serve with rice and vegetables, topped with sesame seeds and green onion.</em></p>', CURRENT_TIMESTAMP),
  ('266876c2-bc60-5a5d-bf7e-ab8c68751119', '62a4ca40-06e5-5f46-a4ae-0cc1d9e53b7f', 'ru', 'Куриные бёдра в чесночно-горчичном маринаде с брюссельской капустой', 'Куриные бёдра, замаринованные в чесноке, лимоне и дижонской горчице, запекаются на одном противне с брюссельской капустой.', '<ol><li>Смешайте оливковое масло, чеснок, петрушку, лимонный сок, горчицу, соль и перец. Выложите бёдра в миску или пакет, добавьте маринад и перемешайте. Маринуйте не менее 6 часов, лучше на ночь.</li><li>Разогрейте духовку до 200 °C. Брюссельскую капусту обрежьте и разрежьте пополам, выложите на противень с пергаментом, посолите, поперчите, сбрызните маслом, перемешайте и разложите по краям одним слоем.</li><li>В центр противня выложите маринованные бёдра кожей вверх на расстоянии около 1,2 см. Запекайте без крышки 25 минут (30 минут для бёдер на кости). Для хрустящей кожи включите гриль на 2–4 минуты.</li></ol><p><em>Маринуйте не менее 6 часов или на ночь; подавайте горячими с зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('951ad13a-5cc5-548c-bbb6-b70bc3772dd5', '62a4ca40-06e5-5f46-a4ae-0cc1d9e53b7f', 'en', 'Garlic Dijon chicken thighs with brussels sprouts', 'Chicken thighs marinated in garlic, lemon and Dijon, roasted on one pan with brussels sprouts that baste in the drippings.', '<ol><li>Mix the olive oil, garlic, parsley, lemon juice, mustard, salt and pepper. Put the thighs in a bowl or bag, add the marinade and toss. Marinate at least 6 hours, preferably overnight.</li><li>Preheat the oven to 200 °C. Trim and halve the brussels sprouts, put them on a parchment-lined pan, season with salt, pepper and oil, toss and scoot to the edges in a single layer.</li><li>Place the marinated thighs skin side up in the centre of the pan about 1/2 inch apart. Bake uncovered for 25 minutes (30 for bone-in). For crispier skin broil 2–4 minutes.</li></ol><p><em>Marinate at least 6 hours or overnight; serve hot with herbs.</em></p>', CURRENT_TIMESTAMP),
  ('901d5ac1-0ab2-5a85-846a-c9d5e517fada', '2ea11185-ba1d-5a19-a3c4-647e4a87934c', 'ru', 'Хрустящая курица в кисло-сладком соусе чили с рисом', 'Кусочки куриных бёдер в кляре из крахмала, паприки и яиц, обжаренные до хруста и обвалянные в сладко-остром соусе с имбирём, чесноком, мёдом и рисовым уксусом. Подаётся с варёным рисом.', '<ol><li>В большой миске взбейте до гладкости крахмал, паприку, чесночный порошок, яйца и 1½ ч. л. соевого соуса. Добавьте нарезанную курицу и перемешайте, чтобы она покрылась кляром.</li><li>Налейте в большую кастрюлю масла слоем около 3 см (не больше трети объёма). Разогрейте на среднем огне, пока капля кляра не начнёт сразу шипеть. Жарьте курицу в один слой порциями по 3–4 минуты с каждой стороны до золотистой хрустящей корочки и готовности (70 °C внутри). Выкладывайте на бумажное полотенце.</li><li>Для соуса разогрейте кунжутное масло в большой сковороде на слабо-среднем огне и несколько минут томите чеснок и имбирь до мягкости, но не до золотистого цвета.</li><li>Добавьте тёмный соевый соус, рисовое вино, рисовый уксус и соус чили. Доведите до кипения, добавьте 1 ст. л. мёда и попробуйте, при необходимости добавьте ещё. Соус должен быть сладким и острым с лёгкой кислинкой.</li><li>Добавьте обжаренную курицу и перемешайте, чтобы покрыть её соусом. Посыпьте кунжутом и зелёным луком и подавайте с рисом.</li></ol><p><em>Посыпьте кунжутом и зелёным луком, подавайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('ee674cf6-639f-5464-9ce0-99b9dd5825bd', '2ea11185-ba1d-5a19-a3c4-647e4a87934c', 'en', 'Crispy sweet chilli chicken with rice', 'Chicken thigh pieces in a cornflour, paprika and egg batter, fried until crisp and tossed in a sweet-spicy sauce with ginger, garlic, honey and rice vinegar. Served over cooked rice.', '<ol><li>In a large bowl beat the cornflour, paprika, garlic granules, eggs and 1½ tsp soy sauce until smooth. Add the chopped chicken and mix to coat in the batter.</li><li>Pour about 3 cm of oil into a large pan (no more than a third full). Heat over medium until a pinch of batter sizzles immediately. Fry the chicken in a single layer in batches, 3-4 minutes per side, until crisp, golden and cooked through (70 °C). Drain on kitchen paper.</li><li>For the sauce heat the sesame oil in a large pan over medium-low and cook the garlic and ginger a few minutes until softened but not golden.</li><li>Stir in the dark soy sauce, rice wine, rice vinegar and sweet chilli sauce. Bring to a simmer, add 1 tbsp honey and taste, adding more if needed. It should be sweet and spicy with a little zing.</li><li>Stir in the cooked chicken so it is completely coated. Scatter with sesame seeds and spring onions and serve with rice.</li></ol><p><em>Garnish with sesame seeds and spring onions and serve with rice.</em></p>', CURRENT_TIMESTAMP),
  ('d9e781db-2c9e-5c72-a36b-b62a7e90657c', 'aeaf2a4f-951b-550a-bf51-473f967aac2f', 'ru', 'Свиные отбивные с лимонным перцем, обжаренными овощами и кускусом с фетой', 'Свиные отбивные на кости с лимонным перцем, обжаренные на сильном огне, с кускусом, цукини, красным перцем, луком, мятой и фетой. Полноценный ужин за 15 минут.', '<ol><li>Залейте кускус кипятком (или бульоном) в миске, накройте плёнкой и оставьте на 5 минут.</li><li>Посыпьте отбивные с двух сторон лимонным перцем и прижмите, чтобы приправа держалась.</li><li>Разогрейте 1 ст. л. масла в сковороде на сильном огне. Жарьте свинину 2 минуты с одной стороны и 1,5 минуты с другой, до желаемой прожарки. Переложите на тарелку, неплотно накройте фольгой и дайте отдохнуть.</li><li>В той же сковороде на сильном огне разогрейте оставшуюся ложку масла. Обжарьте лук и перец 1 минуту, добавьте цукини и готовьте, пока овощи не подгорят по краям и не станут почти готовыми.</li><li>Разрыхлите кускус вилкой, добавьте овощи и мяту, сбрызните лимонным соком, посолите и поперчите. Разложите на тарелки, посыпьте фетой, сверху положите свинину и полейте соком.</li></ol><p><em>Выложите кускус на тарелки, посыпьте фетой, сверху положите отбивную и полейте соком, подайте с лимоном.</em></p>', CURRENT_TIMESTAMP),
  ('d995bc50-6651-5cd0-a291-576a8de62b18', 'aeaf2a4f-951b-550a-bf51-473f967aac2f', 'en', 'Lemon pepper pork cutlets with grilled vegetables and feta couscous', 'Bone-in pork cutlets seasoned with lemon pepper and seared hot, served with couscous, charred zucchini, red pepper and onion, mint and feta. A complete dinner in 15 minutes.', '<ol><li>Combine the couscous and boiling water (or stock) in a bowl, cover with cling wrap and set aside 5 minutes.</li><li>Sprinkle lemon pepper on both sides of each cutlet and pat it on.</li><li>Heat 1 tbsp oil in a pan over high heat. Cook the pork 2 minutes on the first side and 1½ minutes on the second, to your liking. Move to a plate, cover loosely with foil and rest.</li><li>Heat the remaining 1 tbsp oil in the pan over high heat. Sauté the onion and pepper 1 minute, add the zucchini and cook until charred and just cooked through.</li><li>Fluff the couscous with a fork, add the vegetables and mint, squeeze over lemon juice and season. Divide between plates, scatter over the feta, top with the pork and drizzle the juices.</li></ol><p><em>Divide the couscous between plates, scatter with feta, top with the pork and drizzle over the resting juices. Serve with lemon wedges.</em></p>', CURRENT_TIMESTAMP),
  ('91e0d2dd-a33f-50f1-ae8a-77b0dd6c7e8f', '505155d1-89fe-51f3-a4c7-13b1fcf72e87', 'ru', 'Салат БЛТ с беконом, помидорами, салатом и сухариками', 'Салат из свежего салата, помидоров, хрустящего бекона и сухариков со сметанно-майонезной заправкой с чесноком и шнитт-луком. Как основное блюдо на 4 порции.', '<ol><li>Сначала приготовьте заправку: смешайте майонез, сметану, выдавленный чеснок, шнитт-лук, перец и соль, добавьте 1–2 ст. л. молока до нужной густоты. Накройте и уберите в холодильник.</li><li>В большой миске соедините нарванный салат, нарезанные помидоры, бекон и сухарики. Перед подачей полейте заправкой по вкусу и перемешайте.</li></ol><p><em>Заправляйте непосредственно перед подачей. Как гарнир хватит на 6 порций.</em></p>', CURRENT_TIMESTAMP),
  ('7f1743ce-9e53-5c2b-ad23-3e8693bfdaee', '505155d1-89fe-51f3-a4c7-13b1fcf72e87', 'en', 'BLT salad with bacon, tomatoes, croutons and garlic dressing', 'Lettuce, tomatoes, crispy bacon and croutons with a creamy mayo and sour cream dressing with garlic and chives. Serves 4 as a main or 6 as a side.', '<ol><li>Make the dressing first so the flavors meld: combine the mayo, sour cream, pressed garlic, chives, pepper and salt, then stir in 1-2 tbsp milk to the desired consistency. Cover and refrigerate.</li><li>In a large bowl combine the chopped lettuce, sliced tomatoes, bacon and croutons. Just before serving drizzle with dressing to taste and toss.</li></ol><p><em>Dress just before serving. Makes 6 portions as a side salad.</em></p>', CURRENT_TIMESTAMP),
  ('8f994de8-eb21-555d-abb2-feb7c2612bac', '22918f50-e5be-5f06-b6aa-8a2870e6dab6', 'ru', 'Хрустящая брюссельская капуста, обжаренная на оливковом масле с луком и пармезаном', 'Половинки брюссельской капусты, обжаренные до хрустящей корочки на оливковом масле, с карамелизованным красным луком и чесноком, посыпанные пармезаном и кедровыми орехами.', '<ol><li>В большой чугунной сковороде ненадолго разогрейте 2 ст. л. оливкового масла на среднем огне. Обжарьте лук 5–7 минут до мягкости и карамелизации, добавьте чеснок на 30 секунд. Переложите лук с чесноком на тарелку.</li><li>Добавьте оставшееся масло и разогрейте на средне-сильном огне до шипения, но не дыма. Выложите капусту срезом вниз и не трогайте, пока низ не станет золотистым или даже слегка обугленным. Переверните и жарьте ещё 5–6 минут до хруста.</li><li>Верните лук с чесноком, щедро посолите. Переложите на блюдо, посыпьте пармезаном и кедровыми орехами и сразу подавайте.</li></ol><p><em>Подавайте сразу, как гарнир к мясу или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('a54dbfa8-c885-5c33-9a17-f4dd8985e111', '22918f50-e5be-5f06-b6aa-8a2870e6dab6', 'en', 'Crispy olive oil fried Brussels sprouts with onions and Parmesan', 'Halved Brussels sprouts pan-fried in olive oil until crisp with caramelized red onions and garlic, finished with grated Parmesan and toasted pine nuts.', '<ol><li>In a large cast iron skillet heat 2 tbsp olive oil briefly over medium heat. Sauté the onions 5-7 minutes until soft and caramelized, add the garlic for 30 seconds and move both to a side plate.</li><li>Add the remaining olive oil and heat over medium-high until shimmering but not smoking. Place the sprouts flat-side down and leave undisturbed until the bottoms turn golden brown or even charred. Turn over and cook another 5-6 minutes until crisp.</li><li>Toss in the cooked onions and garlic and add a generous sprinkle of salt. Transfer to a dish, finish with Parmesan and pine nuts and serve immediately.</li></ol><p><em>Serve immediately as a side for meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('65d6be6f-8a0e-5ab7-bbda-bda08fed4ef0', '1259b737-f234-5837-866b-cd4427e9806d', 'ru', 'Свежие вьетнамские роллы с овощами и арахисовым соусом', 'Не жареные спринг-роллы из рисовой бумаги с рисовой лапшой, салатом, капустой, морковью, огурцом, халапеньо и свежей зеленью, с кремовым арахисовым соусом. Закуска или лёгкий обед; рецепт на 8 роллов.', '<ol><li>Отварите рисовую лапшу до «аль денте» по инструкции, слейте воду, промойте холодной водой, верните в кастрюлю и вне огня смешайте с кунжутным маслом и солью. Отставьте.</li><li>Налейте в неглубокую форму слой воды около 2,5 см. Рядом положите сложенное вдвое полотенце. Приготовьте начинки. Смешайте зелёный лук, кинзу и мяту в небольшой миске.</li><li>Опустите лист рисовой бумаги в воду примерно на 20 секунд, пока он не станет гибким, но не слишком мягким, и аккуратно разложите на полотенце.</li><li>Оставьте по краям около 2,5 см. На нижнюю треть листа выложите салат, немного лапши, капусту, морковь, огурец и халапеньо, щедро посыпьте смесью трав.</li><li>Подверните нижний край на начинку, закатайте до плотного закрытия начинки, подверните боковые стороны, как у буррито, и сверните до конца. Повторите с остальными листами.</li><li>Для соуса взбейте арахисовую пасту, рисовый уксус, соевый соус, мёд, кунжутное масло и чеснок, добавьте 2–3 ст. л. воды до кремовой консистенции. Подавайте роллы с соусом.</li></ol><p><em>Подавайте целыми или разрезанными по диагонали, соус отдельно. В порции 2 ролла.</em></p>', CURRENT_TIMESTAMP),
  ('8e6dc569-200d-520c-b054-10171e4f1b3e', '1259b737-f234-5837-866b-cd4427e9806d', 'en', 'Fresh Vietnamese spring rolls with peanut sauce', 'Fresh, not fried, spring rolls of rice paper with rice noodles, lettuce, cabbage, carrot, cucumber, jalapeño and fresh herbs, with a creamy peanut sauce. An appetizer or light meal; the recipe makes 8 rolls.', '<ol><li>Boil the noodles just until al dente per package directions, drain, rinse under cool water and return to the pot. Off the heat toss with the sesame oil and salt and set aside.</li><li>Fill a shallow pan with an inch of water. Place a folded lint-free tea towel next to it. Have the fillings within reach and combine the green onion, cilantro and mint in a small bowl.</li><li>Place one rice paper in the water for about 20 seconds until pliable but not super floppy and lay it flat on the towel.</li><li>Leaving about 1 inch around the edges, cover the lower third with lettuce, a small handful of noodles, cabbage, carrot, cucumber and jalapeño and sprinkle generously with the herb mix.</li><li>Fold the lower edge up over the fillings and roll just until compactly enclosed, fold in the short sides like a burrito and roll up. Repeat with the remaining ingredients.</li><li>For the sauce whisk the peanut butter, rice vinegar, tamari, honey, sesame oil and garlic and add 2-3 tbsp water for a creamy dippable sauce. Serve the rolls with the sauce.</li></ol><p><em>Serve whole or sliced diagonally with the sauce on the side. A serving is 2 rolls.</em></p>', CURRENT_TIMESTAMP),
  ('394d85f0-3790-5b6a-8e7b-eeb157db62b7', '0d4471e5-d74c-540a-971e-c9a2631cbf4d', 'ru', 'Лосось на пару с лимоном и зеленью', 'Нежный лосось, приготовленный в пергаменте на луковой подушке со специями, чесноком, лимоном и зеленью. Готовится быстро и почти без хлопот.', '<ol><li>Выстелите дно глубокой сковороды или сотейника с крышкой большим листом пергамента, чтобы его края свисали наружу. Нарежьте лук полукольцами, зелёный лук — длинными полосками.</li><li>Выложите на пергамент лук и часть зелёного лука, сверху положите кусочки лосося кожей вниз, посолите и поперчите.</li><li>Смешайте кориандр, зиру и алеппо, натрите рыбу смесью и сбрызните маслом. Сверху разложите чеснок, петрушку, остальной зелёный лук и кружки лимона.</li><li>Влейте вино (или воду, или бульон), накройте рыбу краями пергамента и закройте сотейник крышкой.</li><li>Готовьте на сильном нагреве 5 минут, не открывая крышку, затем убавьте огонь до среднего и готовьте ещё около 8 минут.</li><li>Снимите с огня и оставьте под крышкой на 5 минут, затем подавайте прямо из сотейника.</li></ol><p><em>Подайте с рисом, булгуром или свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('9e8d0f85-b14e-52d4-b5c1-9b1f82ab12df', '0d4471e5-d74c-540a-971e-c9a2631cbf4d', 'en', 'Steamed salmon with lemon and herbs', 'Tender salmon steamed in parchment over onions with spices, garlic, lemon and fresh herbs. Quick to make and very forgiving.', '<ol><li>Line the bottom of a deep pan or braiser that has a lid with a large sheet of parchment, leaving the edges hanging over. Slice the onion into half-rings and the green onions lengthwise.</li><li>Spread the onion and part of the green onions on the parchment, set the salmon pieces on top skin-side down, then season with salt and pepper.</li><li>Mix the coriander, cumin and Aleppo pepper, rub the mixture over the salmon and drizzle with oil. Top with garlic, parsley, the remaining green onions and lemon slices.</li><li>Pour in the wine (or water or stock), fold the parchment over the fish and cover the pan with its lid.</li><li>Cook over medium-high heat for 5 minutes without lifting the lid, then reduce to medium and cook for about 8 minutes more.</li><li>Take off the heat and leave covered for 5 minutes, then serve straight from the pan.</li></ol><p><em>Serve with rice, bulgur or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('62f3e097-ee55-57a0-b261-674ad5ce60ba', '5d863eb7-4ab9-5793-880e-2ccdd8029923', 'ru', 'Баклажаны «Огонёк»', 'Жареные кусочки баклажана, маринованные в чесноке, остром перце и уксусе. Закуска только улучшается после ночи в холодильнике.', '<ol><li>Нарежьте баклажаны кусочками по 4–5 см.</li><li>Налейте в кастрюлю масла примерно на треть и хорошо разогрейте на сильном-среднем огне: кусочек баклажана должен шипеть и пузыриться.</li><li>Жарьте баклажаны в 2–3 приёма, чтобы они почти полностью были в масле, 15–20 минут до золотистого цвета. Вынимайте шумовкой.</li><li>Переложите в дуршлаг над миской, чтобы стекло лишнее масло, и оставьте, пока баклажаны не станут чуть тёплыми. Затем пересыпьте в большую миску.</li><li>Смешайте уксус, пропущенный через пресс чеснок, мелко нарубленный халапеньо без семян и соль. Полейте баклажаны и перемешайте.</li><li>Можно есть сразу, но лучше убрать в холодильник хотя бы на несколько часов: вкус раскроется.</li></ol><p><em>Подайте с чёрным хлебом или как гарнир к картофелю и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('b15768ba-97c5-5bd5-aa92-480776b343f1', '5d863eb7-4ab9-5793-880e-2ccdd8029923', 'en', 'Spicy eggplant Ogoniok', 'Fried eggplant pieces marinated in garlic, hot pepper and vinegar. The flavours get better after a night in the fridge.', '<ol><li>Cut the eggplants into 4–5 cm pieces.</li><li>Fill about a third of a pot with oil and heat it over medium-high until a piece of eggplant sizzles and bubbles right away.</li><li>Fry the eggplant in 2–3 batches, keeping the pieces mostly submerged, for 15–20 minutes until golden. Lift out with a slotted spoon.</li><li>Drain in a colander set over a bowl until the eggplant is just barely warm, then move it into a large bowl.</li><li>Stir together the vinegar, pressed garlic, minced seeded jalapeño and salt. Pour over the eggplant and toss.</li><li>Serve right away, or chill for a few hours so the flavours develop.</li></ol><p><em>Serve with rye bread or as a side with potatoes and meat.</em></p>', CURRENT_TIMESTAMP),
  ('892fa733-8f8b-55c6-a828-3d93d737f179', '8377dee4-e2da-5637-a12f-61617b968bdf', 'ru', 'Лосось в специях с гранатовой сальсой', 'Лосось в тёплой смеси специй, запечённый под грилем, с лимоном и свежей сальсой из помидоров черри, граната и мяты.', '<ol><li>Смешайте в миске ингредиенты сальсы и отставьте.</li><li>Поставьте решётку духовки примерно в 15 см от верхнего нагревателя и включите гриль. Смешайте все специи в мисочке.</li><li>Хорошо обсушите лосось бумажным полотенцем, посолите, поперчите и натрите смесью специй со стороны мякоти.</li><li>Выложите рыбу на слегка смазанную маслом чугунную сковороду или противень и запекайте под грилем около 5 минут до румяной корочки, когда в центре будет 50–55 °C. Если сверху уже тёмно, а внутри сыровато, выключите гриль и допеките при 220 °C ещё 1–2 минуты.</li><li>Пока готовится рыба, обжарьте половинки лимона срезом вниз на сухой сковороде до румяности.</li><li>Сбрызните лосось соком обжаренного лимона и подавайте с гранатовой сальсой.</li></ol><p><em>Подайте с рисом или другим гарниром из злаков.</em></p>', CURRENT_TIMESTAMP),
  ('ff3eef6f-a324-5c5f-b4d9-35901f7f15f3', '8377dee4-e2da-5637-a12f-61617b968bdf', 'en', 'Blackened salmon with pomegranate salsa', 'Salmon coated in a warm spice blend and broiled, served with lemon and a fresh salsa of cherry tomatoes, pomegranate and mint.', '<ol><li>Combine the salsa ingredients in a bowl and set aside.</li><li>Place the oven rack about 15 cm below the broiler and turn the broiler on. Mix all the spices in a small bowl.</li><li>Pat the salmon very dry, season with salt and pepper and rub the spice mix over the flesh side.</li><li>Put the salmon on a lightly oiled cast iron skillet or sheet pan and broil about 5 minutes until browned and the centre reaches 115–125 °F (46–52 °C). If the top is dark but the middle underdone, switch the broiler off and finish at 425 °F (220 °C) for 1–2 minutes.</li><li>While the fish cooks, char the lemon halves cut-side down in a dry skillet.</li><li>Squeeze the grilled lemon over the salmon and serve with the pomegranate salsa.</li></ol><p><em>Serve with rice or another grain side.</em></p>', CURRENT_TIMESTAMP),
  ('0f946a3d-d246-5834-ae2f-f3892744911b', '0054761b-18e2-548d-bb8d-4798cedcdf29', 'ru', 'Боул с рисом и овощами в стиле суши', 'Бурый рис с рисовым уксусом и нори, эдамаме, морковь, огурец и авокадо под острым майонезным соусом. Вкус как у вегетарианских роллов, но проще в сборке.', '<ol><li>Промытый бурый рис всыпьте в кипящую воду, варите 30 минут, затем слейте воду. Верните рис в кастрюлю, накройте крышкой и оставьте на 10 минут, затем взрыхлите вилкой.</li><li>В маленьком ковшике нагрейте рисовый уксус, соевый соус, сахар и соль, помешивая до растворения сахара. Смешайте с готовым рисом.</li><li>Подсушите лист нори на сухой сковороде на небольшом огне около 5 минут, пока он не станет хрупким. Раскрошите над рисом и перемешайте. Дайте рису остыть.</li><li>Отварите замороженный эдамаме в кипящей воде около 5 минут до прогрева, слейте воду.</li><li>Смешайте майонез с шрирачей до однородности, остроту подберите по вкусу.</li><li>Разрежьте огурец вдоль, выньте ложкой семена и нарежьте соломкой. Морковь нарежьте лентами овощечисткой, авокадо — полосками.</li><li>Разложите рис по четырём мискам, сверху выложите эдамаме, морковь, авокадо и огурец. Полейте острым майонезом, посыпайте кунжутом.</li></ol><p><em>Посыпьте кунжутом и подайте с маринованным имбирём.</em></p>', CURRENT_TIMESTAMP),
  ('3ec37123-f065-5b22-a4f1-9798fc8fe82f', '0054761b-18e2-548d-bb8d-4798cedcdf29', 'en', 'Veggie sushi bowls', 'Brown rice seasoned with rice vinegar and nori, topped with edamame, carrot, cucumber and avocado and a spicy mayo sauce. Tastes like vegetarian sushi rolls in an easy bowl.', '<ol><li>Add the rinsed brown rice to a pot of boiling water and boil 30 minutes, then drain. Return to the pot, cover and steam 10 minutes, then fluff with a fork.</li><li>Warm the rice vinegar, soy sauce, sugar and salt in a small saucepan, stirring until the sugar dissolves. Toss with the cooked rice.</li><li>Toast the nori sheet in a dry skillet over medium-low heat about 5 minutes until crisp. Crumble it over the rice and stir in, then let the rice cool.</li><li>Simmer the frozen edamame in boiling water about 5 minutes until warmed through, then drain.</li><li>Whisk the mayonnaise with sriracha until smooth, adding more for extra heat.</li><li>Halve the cucumber lengthwise, scoop out the seeds and cut into matchsticks. Peel the carrots into ribbons and slice the avocado into strips.</li><li>Divide the rice among four bowls and top with edamame, carrot, avocado and cucumber. Drizzle with the spicy mayo and sprinkle with sesame seeds.</li></ol><p><em>Sprinkle with sesame seeds and serve with pickled ginger.</em></p>', CURRENT_TIMESTAMP),
  ('fbdb6e06-9f5f-5b92-b929-059d8b0c16dd', '1ee57cb4-47d4-5669-9548-2ae5664b8804', 'ru', 'Борщ с фасолью', 'Классический красный борщ на курином бульоне со свёклой, картофелем и белой фасолью. Заправка из овощей с кетчупом придаёт насыщенный вкус.', '<ol><li>Очистите овощи: свёклу натрите на тёрке, морковь нарежьте тонкими кружками, картофель кубиками (картофель держите в холодной воде, чтобы не темнел).</li><li>В большой кастрюле разогрейте 2 ст. л. масла на средне-сильном огне и 10 минут тушите тёртую свёклу, время от времени помешивая, пока она не станет мягкой.</li><li>Влейте бульон и воду, добавьте картофель и морковь и варите 10–15 минут, пока овощи не станут мягкими.</li><li>Пока варится суп, на сковороде разогрейте оставшееся масло и 7–8 минут обжаривайте лук, сельдерей и болгарский перец до мягкости и лёгкой золотистости. Добавьте кетчуп, прогрейте 30 секунд и переложите зажарку в кастрюлю.</li><li>Когда картофель и морковь дойдут, добавьте фасоль вместе с жидкостью, лавровый лист, уксус, соль, перец, давленый чеснок и укроп. Томите ещё 2–3 минуты и при необходимости досолите или добавьте уксус.</li></ol><p><em>Подавайте со сметаной и свежим укропом.</em></p>', CURRENT_TIMESTAMP),
  ('f7834dff-dbd4-5dc9-8e34-9f24281d29c8', '1ee57cb4-47d4-5669-9548-2ae5664b8804', 'en', 'Classic borscht with beans', 'Traditional red beet soup in chicken broth with potatoes and white beans. A quick sautéed vegetable base adds depth.', '<ol><li>Peel the vegetables: grate the beets, thinly slice the carrots and cut the potatoes into bite-sized pieces, keeping them in cold water so they don''t darken.</li><li>Heat 2 tbsp of the oil in a large pot over medium-high heat and sauté the grated beets for 10 minutes, stirring now and then, until softened.</li><li>Pour in the broth and water, add the potatoes and carrots and cook for 10–15 minutes until tender.</li><li>Meanwhile, heat the remaining oil in a skillet and sauté the onion, celery and bell pepper for 7–8 minutes until soft and lightly golden. Stir in the ketchup for 30 seconds, then add the mixture to the soup.</li><li>When the potatoes and carrots are tender, add the beans with their liquid, bay leaves, vinegar, salt, pepper, pressed garlic and dill. Simmer 2–3 more minutes and adjust salt and vinegar to taste.</li></ol><p><em>Serve with a spoonful of sour cream and fresh dill.</em></p>', CURRENT_TIMESTAMP),
  ('9bf90bd6-28db-560a-b011-b48c12bf94ec', '0790fe0d-796f-5eff-ad95-02e03d0130e4', 'ru', 'Плов с говядиной в мультиварке-скороварке', 'Рассыпчатый плов из бурого риса с говядиной, морковью и зирой, приготовленный под давлением в одной чаше. Мясо и рис получаются сочными.', '<ol><li>Промойте рис и обсушите. Включите режим обжарки на максимум, налейте оливковое масло и обжарьте говядину в один слой до лёгкой корочки, около 5 минут.</li><li>Добавьте сливочное масло и лук, 3 минуты помешивайте до мягкости. Всыпьте морковь и все специи, обжаривайте ещё 5 минут.</li><li>Ровным слоем выложите рис, не перемешивая. Вдавите половинки головки чеснока срезом вниз. Влейте горячую воду прямо на чеснок, чтобы не сбить рис, и деревянной ложкой проделайте 5–7 отверстий до дна.</li><li>Закройте крышку и готовьте на высоком давлении 30 минут (режим «Злаки»). Дайте давлению 10 минут сбрасываться естественно, затем полностью выпустите пар.</li><li>Достаньте чеснок, хорошо перемешайте плов и выдавите мягкий чеснок обратно в рис.</li></ol><p><em>Подавайте с салатом из свежих овощей или солёными огурцами.</em></p>', CURRENT_TIMESTAMP),
  ('f38a6972-36d1-549e-a1f2-d9427a692d29', '0790fe0d-796f-5eff-ad95-02e03d0130e4', 'en', 'Beef plov in a pressure cooker', 'Fluffy brown-rice plov with beef, carrots and warm spices, cooked under pressure in a single pot. The meat and rice come out juicy.', '<ol><li>Rinse and drain the rice. Set the pot to sauté on high, heat the olive oil and brown the beef in a single layer for about 5 minutes.</li><li>Add the butter and onion and stir for 3 minutes until soft. Add the carrots and all the spices and sauté 5 more minutes.</li><li>Spread the rice evenly on top without stirring. Press the garlic halves cut-side down halfway into the rice. Pour hot water over the garlic so the rice isn''t disturbed, then poke 5–7 holes to the bottom with a wooden spoon.</li><li>Close the lid and cook at high pressure for 30 minutes (multigrain setting). Let the pressure drop naturally for 10 minutes, then release the remaining steam fully.</li><li>Remove the garlic, stir the plov well and squeeze the soft garlic cloves back into the rice.</li></ol><p><em>Serve with a fresh vegetable salad or pickles.</em></p>', CURRENT_TIMESTAMP),
  ('1b8b4d04-72ec-5dd8-b968-4ae8f8644f6c', '6c518313-57ee-503a-a8fe-d00daec2ebe8', 'ru', 'Мясные тефтели из говядины и свинины', 'Сочные тефтели из смешанного фарша с размоченным хлебом, пармезаном и чесноком. Можно обжарить на сковороде или запечь в духовке.', '<ol><li>Нарежьте хлеб без корок кубиками, залейте молоком или холодной водой на 5 минут и разомните вилкой.</li><li>Добавьте в миску говяжий и свиной фарш, пармезан, яйцо, чеснок, петрушку, соль и перец. Перемешайте руками, только до однородности, не вымешивая долго.</li><li>Смоченными руками скатайте шарики диаметром около 4 см (по 2 ст. л. фарша) и выложите на застеленный противень.</li><li>Вариант на сковороде: разогрейте масло на среднем огне и обжаривайте тефтели партиями, переворачивая каждые 2 минуты, 6–8 минут, пока внутри не будет 71 °C.</li><li>Вариант в духовке: выложите тефтели на противень на расстоянии 5 см и запекайте при 200 °C 20–23 минуты до готовности. Для золотистой корочки включите гриль на последние 2–3 минуты.</li></ol><p><em>Хороши с пастой, картофельным пюре или в томатном соусе.</em></p>', CURRENT_TIMESTAMP),
  ('afaca76a-fa2e-5285-808b-2356c692cec1', '6c518313-57ee-503a-a8fe-d00daec2ebe8', 'en', 'Juicy beef and pork meatballs', 'Tender meatballs made from mixed beef and pork with soaked bread, parmesan and garlic. Pan-sear them or bake in the oven.', '<ol><li>Dice the crustless bread, soak it in milk or cold water for 5 minutes, then mash with a fork.</li><li>Add the ground beef, ground pork, parmesan, egg, garlic, parsley, salt and pepper. Mix by hand just until combined; don''t overmix.</li><li>With wet hands roll the mixture into balls about 4 cm (1½ in) wide, using roughly 2 tbsp each, and place them on a lined baking sheet.</li><li>Pan option: heat the oil over medium heat and sear the meatballs in batches, turning every 2 minutes, for 6–8 minutes total, until the center reaches 160 °F (71 °C).</li><li>Oven option: place the meatballs 2 in (5 cm) apart and bake at 400 °F (200 °C) for 20–23 minutes until cooked through. Broil for the last 2–3 minutes for a golden crust.</li></ol><p><em>Serve with pasta, mashed potatoes or in tomato sauce.</em></p>', CURRENT_TIMESTAMP),
  ('e46aa5b0-ec16-58fb-a84d-0af71afddc8b', '251f5e0f-d40d-5a63-9e28-2faf76a0bb6a', 'ru', 'Салат из капусты и огурцов', 'Хрустящий салат из белокочанной и краснокочанной капусты со свежим огурцом и зелёным луком. Заправляется подсолнечным маслом с уксусом.', '<ol><li>Вымойте овощи. Тонко нашинкуйте белокочанную и краснокочанную капусту (ножом или тёркой-мандолиной) и сложите в большую миску.</li><li>Огурец очистите и нарежьте тонкой соломкой, зелёный лук мелко порубите. Добавьте к капусте.</li><li>В отдельной миске вилкой смешайте масло, уксус и соль. Влейте заправку в салат по вкусу (количество зависит от размера кочанов) и перемешайте.</li></ol><p><em>Хорош как гарнир к жареному мясу, котлетам и картофелю.</em></p>', CURRENT_TIMESTAMP),
  ('b0470354-1590-5fa6-8d6f-c01170a8f86f', '251f5e0f-d40d-5a63-9e28-2faf76a0bb6a', 'en', 'Cabbage and cucumber salad', 'Crunchy white and red cabbage salad with fresh cucumber and green onion, dressed with sunflower oil and vinegar.', '<ol><li>Wash the vegetables. Thinly shred the white and red cabbage with a knife or mandoline and put it in a large bowl.</li><li>Peel the cucumber and cut it into thin strips, finely chop the green onion and add both to the cabbage.</li><li>In a small bowl whisk the oil, vinegar and salt with a fork. Pour the dressing over the salad to taste (the amount depends on the size of the cabbages) and toss.</li></ol><p><em>Serve alongside grilled meat, cutlets or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('93dfb800-7ed3-507d-9cc4-1951d5df1d68', '544a880b-1d7d-5ece-9eb5-ebbbc9057bca', 'ru', 'Картофельное пюре со сметаной', 'Нежное картофельное пюре на молоке и сливочном масле с добавлением сметаны. Подходит как гарнир к мясу, котлетам и рыбе.', '<ol><li>Очистите картофель и нарежьте кусками около 2,5 см, до варки держите в холодной воде. Переложите в кастрюлю, залейте холодной водой на 2,5 см выше картофеля и доведите до кипения. Варите на слабом кипении 10–12 минут, пока вилка не будет входить без сопротивления.</li><li>Пока варится картофель, в небольшой кастрюле нагрейте молоко со сливочным маслом, пока масло не растает и не пойдёт пар (не кипятите). Накройте крышкой.</li><li>Слейте воду, верните картофель в кастрюлю и на минуту поставьте на самый слабый огонь, чтобы испарилась влага. Сразу начните разминать толкушкой или миксером, пока картофель не стал клейким.</li><li>Выключите огонь и, продолжая разминать, тонкой струйкой влейте горячее молоко с маслом до желаемой густоты. Не взбивайте слишком долго, иначе пюре станет клейким.</li><li>Вмешайте сметану и соль, по вкусу досолите. Держите под крышкой до подачи, посыпьте шнитт-луком и чёрным перцем.</li></ol><p><em>Сверху добавьте кусочек сливочного масла и зелёный лук или шнитт-лук.</em></p>', CURRENT_TIMESTAMP),
  ('73a1d657-ebc0-53e7-83aa-59ee4d8c7192', '544a880b-1d7d-5ece-9eb5-ebbbc9057bca', 'en', 'Sour cream mashed potatoes', 'Creamy mashed potatoes made with warm milk and butter and finished with sour cream. A classic side for meat, cutlets and fish.', '<ol><li>Peel the potatoes and cut them into 1-inch (2.5 cm) chunks, keeping them in cold water until needed. Put them in a pot, cover with cold water by 1 inch and bring to a boil, then cook at a low boil for 10–12 minutes until a fork slides in easily.</li><li>Meanwhile, warm the milk with the butter in a small saucepan until the butter melts and the milk starts to steam, without boiling. Keep it covered.</li><li>Drain the potatoes, return them to the pot over very low heat for 1 minute to steam off excess moisture, then start mashing right away with a masher or hand mixer before they turn gummy.</li><li>Turn off the heat and, while mashing, drizzle in the hot milk and butter to the texture you like. Don''t overbeat or the potatoes will turn gluey.</li><li>Mix in the sour cream and salt and add more salt if needed. Keep covered until serving, then sprinkle with chives and black pepper.</li></ol><p><em>Top with a knob of butter and chopped chives.</em></p>', CURRENT_TIMESTAMP),
  ('4da2cda9-76da-52e3-93c4-d554afe82902', '2bed0940-bc36-59c7-95be-5ded8a17c2f6', 'ru', 'Куриные голени в панировке в духовке', 'Хрустящие снаружи и нежные внутри голени в панировочных сухарях с горчично-чесночной обмазкой. Мариновать не нужно.', '<ol><li>Разогрейте духовку до 175 °C. Застелите противень фольгой, чтобы проще было мыть.</li><li>Ополосните голени холодной водой, обсушите бумажными полотенцами и посолите и поперчите со всех сторон.</li><li>В миске смешайте дижонскую горчицу, майонез и выдавленный чеснок. В другую широкую миску насыпьте панировочные сухари.</li><li>Обмажьте каждую голень горчичной смесью со всех сторон и хорошо обваляйте в сухарях.</li><li>Выложите голени на противень, не сдвигая слишком плотно (лучше на решётке поверх противня). Запекайте при 175 °C 50–60 минут до готовности. Для хрустящей корочки на 3 минуты включите гриль.</li></ol><p><em>Подавайте с картофельным пюре или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('c6ca3422-9d12-5c54-b554-f3301bfbb966', '2bed0940-bc36-59c7-95be-5ded8a17c2f6', 'en', 'Breaded baked chicken drumsticks', 'Crispy on the outside and tender inside, these drumsticks are coated in a garlic-mustard mayo and breadcrumbs. No marinating needed.', '<ol><li>Preheat the oven to 350 °F (175 °C) and line a baking sheet with foil for easier cleanup.</li><li>Rinse the drumsticks in cold water, pat them dry and season on all sides with salt and pepper.</li><li>In a bowl whisk the Dijon mustard, mayonnaise and pressed garlic. Put the breadcrumbs in another wide bowl.</li><li>Coat each drumstick all over with the mustard mixture, then roll it in the breadcrumbs until well covered.</li><li>Arrange the drumsticks on the baking sheet without crowding them (ideally on a wire rack set in the sheet). Bake at 350 °F (175 °C) for 50–60 minutes until cooked through, then broil about 3 minutes for a crisp crust.</li></ol><p><em>Serve with mashed potatoes or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('e126cb5a-f91c-5699-9bc6-966dd123175a', '8b9f5140-2dbf-541f-80ef-3b0806420e54', 'ru', 'Бефстроганов в мультиварке', 'Говядина, часами томлённая с луком, грибами, паприкой и горчицей в густом сливочном соусе. Мясо получается очень мягким.', '<ol><li>Нарежьте говядину кусочками размером с грецкий орех. Разогрейте на сильном огне 1 ст. л. масла и обжарьте мясо порциями до глубокого румяного цвета, подливая остальное масло, когда сковорода сухая. Переложите мясо в чашу мультиварки.</li><li>В той же сковороде обжарьте лук с щепоткой соли на среднем огне 5–8 минут, добавьте грибы и готовьте ещё 5 минут до лёгкой румяности. Положите чеснок и прогрейте минуту.</li><li>Всыпьте муку и паприку, жарьте 1–2 минуты. Добавьте томатную пасту и прогрейте до липкой массы, затем влейте горчицу и вустерский соус. Постепенно влейте бульон, размешивая до гладкости, и доведите до кипения.</li><li>Вылейте соус к мясу в мультиварку и перемешайте. Готовьте под крышкой на низком режиме 6–8 часов (на среднем 4–5 часов, на высоком 2–3 часа), пока мясо не станет очень мягким, а соус не загустеет. Если нужно погуще, последние 10–15 минут готовьте без крышки.</li><li>Вмешайте сметану, попробуйте и при необходимости досолите, добавьте паприки. Подавайте с гарниром.</li></ol><p><em>Подайте с картофельным пюре, рисом или макаронами с маслом.</em></p>', CURRENT_TIMESTAMP),
  ('d1315884-59ca-5f57-9761-e8931d1c20d8', '8b9f5140-2dbf-541f-80ef-3b0806420e54', 'en', 'Slow cooker beef stroganoff', 'Beef slow-cooked with onions, mushrooms, paprika and mustard in a rich creamy sauce until meltingly tender.', '<ol><li>Cut the beef into walnut-sized pieces. Heat 1 tbsp of the oil over high heat and brown the beef well in batches, adding the remaining oil when the pan dries. Transfer to the slow cooker.</li><li>In the same pan, cook the onions with a pinch of salt over medium heat for 5–8 minutes, add the mushrooms and cook 5 minutes more until browning. Stir in the garlic for a minute.</li><li>Sprinkle in the flour and paprika and cook 1–2 minutes. Add the tomato paste until the mixture turns sticky, then stir in the mustard and Worcestershire sauce. Gradually pour in the stock, stirring until smooth, and bring to a simmer.</li><li>Pour the sauce over the beef in the slow cooker and stir. Cook covered on low for 6–8 hours (medium 4–5 hours, high 2–3 hours) until the beef is very tender and the sauce has thickened. For a thicker sauce, cook uncovered for the last 10–15 minutes.</li><li>Stir in the sour cream, taste and adjust the seasoning, adding more paprika if you like. Serve with a side.</li></ol><p><em>Serve over mashed potatoes, rice or buttered pasta.</em></p>', CURRENT_TIMESTAMP),
  ('cb2f8c46-6094-504e-b035-ce4d5cd27ef0', '5e934521-c9c0-56fa-b399-daabf2b461e3', 'ru', 'Нутовый суп с овощами и специями', 'Густой постный суп из нута, моркови, болгарского перца и томатов с зирой, кориандром и лимоном. Готовится в мультиварке под давлением или на плите.', '<ol><li>Залейте нут большим количеством воды и оставьте на ночь. Затем хорошо слейте воду.</li><li>Включите режим жарки на сильном нагреве, разогрейте 2 ст. л. оливкового масла. Обжарьте лук с чесноком и щепоткой соли 3 минуты.</li><li>Добавьте морковь, болгарский перец и все специи, готовьте ещё около 4 минут до слегка мягких овощей.</li><li>Положите нут, томаты вместе с соком и влейте бульон. Закройте крышку и готовьте под высоким давлением 15 минут (для более мягкого нута 20–25 минут). Без скороварки: варите на плите под крышкой на слабом огне 1–1,5 часа до мягкости нута.</li><li>Дайте давлению сойти само или через 10 минут выпустите пар. Откройте крышку, добавьте лимонный сок и кинзу, при необходимости досолите.</li><li>Разлейте по тарелкам и сбрызните оливковым маслом.</li></ol><p><em>Подайте с хрустящим хлебом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('477432b0-49e5-5cc3-a24f-e8027f0cd454', '5e934521-c9c0-56fa-b399-daabf2b461e3', 'en', 'Chickpea vegetable soup', 'A hearty vegan soup of chickpeas, carrots, bell pepper and tomatoes with cumin, coriander and lemon, made in a pressure cooker or on the stove.', '<ol><li>Cover the chickpeas with plenty of water and soak overnight, then drain well.</li><li>Set the pot to sauté on high and heat 2 tbsp of olive oil. Cook the onion and garlic with a pinch of salt for 3 minutes.</li><li>Add the carrots, bell pepper and all the spices and cook about 4 minutes more until the vegetables soften a little.</li><li>Add the chickpeas, tomatoes with their juice and the broth. Lock the lid and pressure cook on high for 15 minutes (20–25 for creamier chickpeas). Without a pressure cooker, simmer covered on the stove for 1–1.5 hours until the chickpeas are tender.</li><li>Let the pressure release naturally, or quick-release after 10 minutes. Open the lid, stir in the lemon juice and cilantro and adjust the seasoning.</li><li>Ladle into bowls and drizzle with olive oil.</li></ol><p><em>Serve with crusty bread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('c8b5cbfc-7280-509f-8fd0-c36c926a0a5c', 'bd89f7f4-518d-575f-a3dc-c4ea40d84fb6', 'ru', 'Запечённая морковь с чесночным маслом', 'Морковь, запечённая в духовке до мягкости, с чесночно-петрушечным маслом перед подачей. Простой гарнир из доступных продуктов.', '<ol><li>Разогрейте духовку до 220 °C. Очистите или хорошо вымойте морковь, при желании разрежьте крупные морковины.</li><li>Выложите морковь на противень, сбрызните маслом, посыпьте солью и перцем и перемешайте.</li><li>Запекайте около 20 минут, пока морковь не станет мягкой от прокола вилкой.</li><li>Пока морковь запекается, смешайте измельчённый чеснок с оливковым маслом и рубленой петрушкой. Полейте морковь этой смесью перед подачей.</li></ol><p><em>Подходит к курице, рыбе и мясным блюдам.</em></p>', CURRENT_TIMESTAMP),
  ('6e60df29-7add-5df5-a591-20fb0572b023', 'bd89f7f4-518d-575f-a3dc-c4ea40d84fb6', 'en', 'Roasted carrots with garlic oil', 'Carrots roasted in the oven until fork tender and drizzled with garlic-parsley oil just before serving. A simple side from pantry staples.', '<ol><li>Preheat the oven to 425 °F (220 °C). Peel or scrub the carrots and cut larger ones if desired.</li><li>Place the carrots on a baking sheet, drizzle with oil, season with salt and pepper and toss to coat.</li><li>Roast for about 20 minutes until fork tender.</li><li>While the carrots roast, mix minced garlic with olive oil and chopped parsley. Drizzle over the carrots just before serving.</li></ol><p><em>Serve with chicken, fish or roast meat.</em></p>', CURRENT_TIMESTAMP),
  ('cfe20e31-0569-5e95-9d81-aabcd84e7b17', '008e2f1f-7349-58ed-bd5a-2667f59967cc', 'ru', 'Салат из сырой цветной капусты с огурцом и помидорами', 'Свежий хрустящий салат из мелко нарубленной сырой цветной капусты, огурца и помидоров черри с чесночной заправкой на майонезе и сметане.', '<ol><li>Мелко нарубите цветную капусту кусочками 0,5–1 см и сложите в большую миску.</li><li>Огурец нарежьте кубиками, помидоры разрежьте пополам или на четвертинки и добавьте в миску. Выдавите туда чеснок.</li><li>Смешайте майонез со сметаной, заправьте салат, хорошо перемешайте и поставьте в холодильник до подачи.</li></ol><p><em>Дайте салату немного постоять в холодильнике перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('30d85336-7b42-56ef-88ae-a84532d37544', '008e2f1f-7349-58ed-bd5a-2667f59967cc', 'en', 'Raw cauliflower, cucumber and tomato salad', 'A crunchy fresh salad of finely chopped raw cauliflower, cucumber and cherry tomatoes in a garlicky mayo and sour cream dressing.', '<ol><li>Chop the cauliflower into small ¼–½ in (0.5–1 cm) pieces and place in a large bowl.</li><li>Dice the cucumber, halve or quarter the tomatoes and add both to the bowl. Press the garlic over the vegetables.</li><li>Mix the mayonnaise with the sour cream, dress the salad, toss well and refrigerate until serving.</li></ol><p><em>Chill for a short while before serving.</em></p>', CURRENT_TIMESTAMP),
  ('67627605-55fe-59be-ab2b-799fd4bd9aa8', 'a3db08c0-69ab-5c26-a3c0-82035ce8022f', 'ru', 'Салат из помидоров и огурцов с фетой', 'Свежий салат с помидорами, огурцами, красным луком и фетой в заправке из оливкового масла, лимонного сока, чеснока и зиры.', '<ol><li>В маленькой миске смешайте оливковое масло, лимонный сок, выдавленный чеснок, соль, перец и зиру.</li><li>В большой миске соедините нарезанные помидоры, огурец кружочками, крупно раскрошенную фету, тонко нарезанный красный лук и рубленую кинзу.</li><li>Перед подачей полейте салат заправкой, аккуратно перемешайте и при необходимости досолите.</li></ol><p><em>Заправляйте непосредственно перед подачей, чтобы овощи не пустили сок.</em></p>', CURRENT_TIMESTAMP),
  ('a7d349bc-37d6-57f6-8c20-e800c3326794', 'a3db08c0-69ab-5c26-a3c0-82035ce8022f', 'en', 'Tomato, cucumber and feta salad', 'A fresh salad of tomatoes, cucumbers, red onion and feta in a dressing of olive oil, lemon juice, garlic and cumin.', '<ol><li>In a small bowl stir together the olive oil, lemon juice, pressed garlic, salt, pepper and cumin.</li><li>In a large bowl combine the chopped tomatoes, sliced cucumber, large feta crumbles, sliced red onion and chopped cilantro.</li><li>Just before serving, drizzle with the dressing, toss gently and add salt if needed.</li></ol><p><em>Dress it right before serving so the vegetables don''t release water.</em></p>', CURRENT_TIMESTAMP),
  ('dec0069e-877a-5559-a66d-b6942fb5e21b', '2de5d5eb-8945-5895-a995-f5468bd80c23', 'ru', 'Суп с говяжьим фаршем, картофелем и томатами', 'Сытный суп с говяжьим фаршем, морковью, сельдереем, картофелем и консервированными томатами. Готовится в одной кастрюле за 45 минут.', '<ol><li>Разогрейте в кастрюле с толстым дном оливковое масло на среднем огне, обжарьте лук, морковь и сельдерей до мягкости.</li><li>Добавьте говяжий фарш, разламывая его лопаткой, и обжарьте до золотистого цвета.</li><li>Положите томаты, чеснок, томатную пасту и картофель, влейте бульон. Приправьте итальянскими травами, солью и перцем.</li><li>Доведите до кипения, убавьте огонь и варите 30 минут, пока картофель не станет мягким. Попробуйте, при необходимости досолите, подайте с рубленой петрушкой.</li></ol><p><em>Посыпьте свежей петрушкой и подавайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('9b7d46eb-748e-5f43-a0d5-7346bd9cf9f3', '2de5d5eb-8945-5895-a995-f5468bd80c23', 'en', 'Ground beef vegetable soup (hamburger soup)', 'Hearty soup with ground beef, carrots, celery, potatoes and canned tomatoes, made in one pot in 45 minutes.', '<ol><li>Heat the olive oil in a heavy soup pot over medium heat and sauté the onion, carrot and celery until softened.</li><li>Add the ground beef, breaking it apart, and cook until golden brown.</li><li>Stir in the tomatoes, garlic, tomato paste and potatoes, pour in the broth and season with Italian seasoning, salt and pepper.</li><li>Bring to a boil, reduce the heat and simmer for 30 minutes until the potatoes are tender. Adjust the seasoning and serve garnished with chopped parsley.</li></ol><p><em>Garnish with fresh parsley and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('90b06a71-b678-578d-aea3-5d7890da1776', 'c8c6b719-898e-5fe4-afd3-9bf07b58f253', 'ru', 'Курица в пармезане с лимонно-сливочным соусом', 'Куриное филе в хрустящей панировке из пармезана и яйца, политое быстрым соусом из сливочного масла, лимонного сока и чеснока.', '<ol><li>Разрежьте куриные грудки вдоль пополам и слегка отбейте молоточком до одинаковой толщины.</li><li>В одной миске взбейте яйца с чесноком, итальянскими травами, солью и перцем. В другой смешайте пармезан с мукой. Обмакните курицу в яичную смесь, затем обваляйте в пармезане, стряхнув излишки.</li><li>В большой антипригарной сковороде разогрейте масло. Жарьте курицу по 4–5 минут с каждой стороны до золотистой хрустящей корочки и 74 °C внутри; если румянится слишком быстро, убавьте огонь.</li><li>Пока жарится курица, в небольшой кастрюле растопите сливочное масло с чесноком до аромата. Влейте бульон и лимонный сок, добавьте перец и варите около 2 минут.</li><li>Полейте курицу соусом, переверните, чтобы покрылась им со всех сторон, украсьте ломтиками лимона и петрушкой.</li></ol><p><em>Подайте с рисом, пастой или овощами на пару.</em></p>', CURRENT_TIMESTAMP),
  ('55b2bbf0-8945-5a2a-90c8-597c215291e0', 'c8c6b719-898e-5fe4-afd3-9bf07b58f253', 'en', 'Lemon parmesan chicken with butter sauce', 'Chicken breast in a crisp parmesan and egg coating, finished with a quick lemon, garlic and butter sauce.', '<ol><li>Cut the chicken breasts in half lengthwise and gently pound to an even thickness.</li><li>In one bowl whisk the eggs with garlic, Italian seasoning, salt and pepper. In another mix the parmesan with the flour. Dip the chicken in the egg mixture, then coat in the parmesan, shaking off the excess.</li><li>Heat the oil in a large non-stick skillet. Cook the chicken 4–5 minutes per side until crisp, golden and 165 °F (74 °C) inside, lowering the heat if it browns too quickly.</li><li>Meanwhile melt the butter with the garlic in a saucepan until fragrant. Add the broth, lemon juice and pepper and cook for about 2 minutes.</li><li>Pour the sauce over the chicken, turn to coat and garnish with lemon slices and parsley.</li></ol><p><em>Serve with rice, pasta or steamed vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('61753c2e-93e0-5ea1-b36a-db34904dc446', '19d856de-de7c-52c5-8203-5f5133a37438', 'ru', 'Суп из лосося с картофелем', 'Лёгкий и ароматный суп со свежим лососем, картофелем, сладким перцем и зеленью. Сливки по желанию делают его нежнее.', '<ol><li>Нарежьте лук, натрите морковь, тонко нарежьте сельдерей, мелко нарежьте перцы и помидоры без семян. Картофель очистите и нарежьте кубиками, лосось — кусочками по 5 см.</li><li>Разогрейте масло в большой кастрюле, обжарьте лук с солью и перцем 3–5 минут на среднем огне до мягкости.</li><li>Добавьте морковь и сельдерей, готовьте ещё 3–5 минут. Положите перцы и прогрейте 1–2 минуты, затем помидоры с чесноком ещё на 1–2 минуты.</li><li>Добавьте лавровый лист, влейте воду или бульон, доведите до кипения и посолите. Положите картофель и варите на слабом огне около 15 минут до готовности.</li><li>В самом конце положите лосось (свежий или замороженный, не размораживая) и варите: свежий около 5 минут, замороженный около 7.</li><li>Снимите с огня, влейте сливки, посыпьте зеленью и подавайте горячим.</li></ol><p><em>Посыпьте укропом и зелёным луком, подайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('e11fd0c9-1a30-5b22-bbb3-365004ecbc5d', '19d856de-de7c-52c5-8203-5f5133a37438', 'en', 'Salmon and potato soup', 'A light, aromatic soup of fresh salmon, potatoes, sweet pepper and herbs, made richer with an optional splash of cream.', '<ol><li>Chop the onion, grate the carrot, thinly slice the celery, finely chop the peppers and seeded tomatoes. Peel and cube the potatoes and cut the salmon into 5 cm pieces.</li><li>Heat the butter in a large pot and cook the onion with salt and pepper over medium heat for 3–5 minutes until soft.</li><li>Add the carrot and celery and cook another 3–5 minutes. Stir in the peppers for 1–2 minutes, then the tomatoes and garlic for 1–2 minutes more.</li><li>Add the bay leaves, pour in the water or broth, bring to the boil and salt. Add the potatoes and simmer about 15 minutes until cooked through.</li><li>At the very end add the salmon (fresh or frozen, no need to thaw) and cook about 5 minutes if fresh, about 7 if frozen.</li><li>Take off the heat, stir in the cream, sprinkle with herbs and serve hot.</li></ol><p><em>Garnish with dill and green onion and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('825338d6-0709-5f76-9ad1-75f6d8cdf581', '8c02122a-2351-583f-bcc6-ed0f7a7c40a0', 'ru', 'Суп зуппа тоскана с колбасками и капустой кейл', 'Сытный сливочный суп с жареными колбасками, беконом, картофелем и кейлом. Пармезан и сливки добавляются в самом конце.', '<ol><li>Разогрейте в большой кастрюле немного масла на средне-сильном огне, обжарьте колбасный фарш без оболочки, разбивая комки, пока не уйдёт розовый цвет. Отложите, при жирности промокните бумажным полотенцем.</li><li>В той же кастрюле обжарьте мелко нарубленный бекон до золотистого цвета, отложите на бумажное полотенце. Слейте жир, оставив около 2 ст. л.</li><li>Обжарьте лук с солью и перцем под крышкой на среднем огне до мягкости и лёгкой румяности, добавьте чеснок на 30 секунд.</li><li>Влейте бульон, доведите до кипения, убавьте огонь, добавьте картофель и варите до мягкости.</li><li>Добавьте кейл и варите 5–10 минут, пока он слегка не увянет, но останется ярко-зелёным.</li><li>Снимите с огня, вмешайте сливки, пармезан и колбасу. Посолите и поперчите, подавайте с беконом и пармезаном.</li></ol><p><em>Посыпьте хрустящим беконом и пармезаном; кейл можно заменить шпинатом.</em></p>', CURRENT_TIMESTAMP),
  ('1544bd86-2502-527c-9518-b10012a1266c', '8c02122a-2351-583f-bcc6-ed0f7a7c40a0', 'en', 'Zuppa Toscana', 'A hearty creamy soup with browned sausage, bacon, potatoes and kale, finished with cream and Parmesan.', '<ol><li>Heat a little oil in a large pot over medium-high heat and cook the sausage meat, breaking up lumps, until no longer pink. Set aside and blot with paper towels if greasy.</li><li>In the same pot, cook the finely chopped bacon until golden and crispy and set aside on paper towels. Pour off all but about 2 tbsp of fat.</li><li>Cook the onions with salt and pepper, covered, over medium heat until soft and beginning to brown, then add the garlic for 30 seconds.</li><li>Pour in the broth, bring to the boil, reduce to a simmer, add the potatoes and cook until tender.</li><li>Add the kale and cook 5–10 minutes, just until slightly wilted but still bright green.</li><li>Remove from the heat and stir in the cream, Parmesan and sausage. Season with salt and pepper and serve topped with bacon and more Parmesan.</li></ol><p><em>Top with crispy bacon and more Parmesan; spinach works in place of kale.</em></p>', CURRENT_TIMESTAMP),
  ('eb6b9eef-864d-5cc4-b5a1-f0d3e9995de9', 'ded3dc49-e459-5ee1-85be-d0868d815418', 'ru', 'Зелёный борщ со щавелем', 'Кисловатый весенний суп на курином бульоне со щавелем, картофелем, морковью, варёными яйцами и сметаной. Щавель можно заменить шпинатом с лимонным соком.', '<ol><li>Нарежьте лук, морковь и картофель кубиками, щавель нашинкуйте.</li><li>Сварите яйца вкрутую (около 10 минут), остудите, очистите и нарежьте.</li><li>Доведите бульон до кипения, добавьте лук, морковь и картофель. Снова закипятите, убавьте огонь и варите под крышкой около 15 минут до готовности картофеля.</li><li>Добавьте щавель (если вместо него шпинат, то и лимонный сок) и варите всего 2–5 минут. В конце положите варёную курицу, чтобы только прогрелась.</li><li>Разлейте суп по тарелкам, посыпьте рубленым яйцом и добавьте ложку сметаны. Подавайте горячим.</li></ol><p><em>Подайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('9a61c1c0-c0bf-5c6c-9eae-4f64d1ae4a5e', 'ded3dc49-e459-5ee1-85be-d0868d815418', 'en', 'Green borsch with sorrel', 'A tangy spring soup in chicken broth with sorrel, potatoes, carrots, boiled eggs and sour cream. Spinach with lemon juice can replace the sorrel.', '<ol><li>Dice the onion, carrots and potatoes and slice the sorrel.</li><li>Hard-boil the eggs (about 10 minutes), cool, peel and chop them.</li><li>Bring the broth to the boil, add the onion, carrots and potatoes. Return to a boil, reduce the heat and simmer covered about 15 minutes until the potatoes are cooked.</li><li>Add the sorrel (with the lemon juice if using spinach) and cook only 2–5 minutes. Add the cooked chicken at the very end, just to heat through.</li><li>Ladle into bowls, top with chopped egg and a dollop of sour cream and serve hot.</li></ol><p><em>Serve with a spoonful of sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('6e42e6fb-340f-5030-a967-0430371700c6', '5e6d926b-df5f-5e0f-9f99-b38e3ecea8e7', 'ru', 'Томатный суп с куриными фрикадельками и пастой', 'Лёгкий томатный суп на бульоне с овощами, нежными куриными фрикадельками и мелкой пастой. Быстрый и сытный ужин.', '<ol><li>Мелко нарежьте лук, морковь и сельдерей, чеснок измельчите.</li><li>Разогрейте в кастрюле масло, добавьте овощи и чеснок, посолите и поперчите. Готовьте около 5 минут на среднем огне до мягкости.</li><li>Влейте бульон. Измельчите консервированные томаты вместе с соком блендером и добавьте в кастрюлю. Доведите до кипения и приправьте по вкусу.</li><li>Для фрикаделек залейте сухари молоком на 5 минут, чтобы они размякли. Смешайте их с фаршем, яйцом, петрушкой, пармезаном, солью, перцем и чесночным порошком до однородности.</li><li>Влажными руками формуйте шарики размером с половину столовой ложки и опускайте в кипящий суп.</li><li>Добавьте пасту и варите до нужной мягкости. При желании влейте ещё бульона. Подавайте с пармезаном и зеленью.</li></ol><p><em>Посыпьте пармезаном и свежей петрушкой или базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('d9c42ca0-470b-53ef-ae8b-cfd86375b746', '5e6d926b-df5f-5e0f-9f99-b38e3ecea8e7', 'en', 'Tomato meatball soup with pasta', 'A light, brothy tomato soup with aromatic vegetables, tender chicken meatballs and small pasta. A quick, satisfying dinner.', '<ol><li>Finely chop the onion, carrots and celery and mince the garlic.</li><li>Heat the butter in a pot, add the vegetables and garlic, season with salt and pepper and cook about 5 minutes over medium heat until softened.</li><li>Pour in the broth. Puree the canned tomatoes with their liquid and add to the pot. Bring to the boil and season to taste.</li><li>For the meatballs, soak the breadcrumbs in the milk for about 5 minutes until soft. Mix them with the ground chicken, egg, parsley, Parmesan, salt, pepper and garlic powder until well combined.</li><li>With damp hands, shape the mixture into balls about half a tablespoon each and drop them into the simmering soup.</li><li>Add the pasta and cook to your liking. Add more broth if you want a thinner soup. Serve with Parmesan and herbs.</li></ol><p><em>Garnish with Parmesan and fresh parsley or basil.</em></p>', CURRENT_TIMESTAMP),
  ('3db92437-6b79-58fe-89ea-dfdaf82c261c', 'c32feec6-aa46-50a6-888d-ac95486a1149', 'ru', 'Запечённая форель целиком с лимоном и зеленью', 'Целая форель, начинённая лимоном, луком, чесноком и зеленью, запекается в духовке до золотистой корочки. Мякоть получается сочной и ароматной.', '<ol><li>Разогрейте духовку до 230 °C, застелите противень пергаментом.</li><li>Сделайте на обеих сторонах рыбы косые надрезы. Выложите форель на противень, посолите и поперчите снаружи и внутри.</li><li>Начините брюшко кружками лимона, чесноком, тонкими кольцами лука и зеленью. Смажьте рыбу сверху оливковым маслом.</li><li>Запекайте 10–15 минут, затем включите гриль и запекайте ещё 5–7 минут до золотистой корочки и лёгких подпалин.</li><li>Подавайте целиком, сбрызнув оливковым маслом и свежевыжатым лимонным соком.</li></ol><p><em>Подайте с отварным картофелем или салатом и долькой лимона.</em></p>', CURRENT_TIMESTAMP),
  ('a367dc0c-7a66-5d72-b24a-f9077dbbd441', 'c32feec6-aa46-50a6-888d-ac95486a1149', 'en', 'Roasted whole trout with lemon and herbs', 'Whole trout stuffed with lemon, onion, garlic and fresh herbs and roasted until golden. The flesh turns juicy and fragrant.', '<ol><li>Preheat the oven to 450 °F (230 °C) and line a rimmed baking sheet with parchment.</li><li>Cut diagonal slashes on both sides of each fish. Set the trout on the sheet and season with salt and pepper outside and inside.</li><li>Stuff the cavities with lemon slices, garlic, thinly sliced onion and herbs. Rub the tops with olive oil.</li><li>Roast for 10–15 minutes, then switch on the broiler and roast 5–7 minutes more until golden and lightly charred in places.</li><li>Serve whole, with a little more olive oil and a squeeze of fresh lemon juice.</li></ol><p><em>Serve with boiled potatoes or a salad and a lemon wedge.</em></p>', CURRENT_TIMESTAMP),
  ('2f9ec61c-8d36-54b7-8911-99ae83f04e94', '0332c8f6-2ebb-599b-b02b-c13c70352761', 'ru', 'Салат оливье с варёной колбасой', 'Классический праздничный салат из варёных картофеля, моркови и яиц с колбасой, солёными огурцами, зелёным горошком и майонезом.', '<ol><li>Тщательно вымойте картофель и морковь и варите в кожуре в большой кастрюле с водой 20–25 минут, пока картофель не станет мягким от прокола ножом.</li><li>В отдельной кастрюле доведите яйца до кипения и варите на слабом огне 8–10 минут, затем остудите в ледяной воде и очистите.</li><li>Остывшие картофель и морковь очистите. Нарежьте кубиками яйца, картофель, морковь, колбасу, солёные огурцы, лук и свежий огурец.</li><li>Сложите всё в большую миску, добавьте замороженный горошек и майонез. Перемешайте, приправьте солью, перцем, сахаром и рубленым укропом и перемешайте ещё раз.</li><li>Уберите салат в холодильник до подачи.</li></ol><p><em>Дайте салату постоять в холодильнике пару часов и посыпьте свежим укропом.</em></p>', CURRENT_TIMESTAMP),
  ('c5e28fcc-3d59-50ba-947c-33446722975f', '0332c8f6-2ebb-599b-b02b-c13c70352761', 'en', 'Olivier salad with boiled sausage', 'Classic Russian potato salad with boiled potatoes, carrots and eggs, bologna, pickles, peas and mayonnaise.', '<ol><li>Scrub the potatoes and carrots and boil them in their skins in a large pot of water for 20–25 minutes, until a knife pierces the potatoes easily.</li><li>In a small pot bring the eggs to a boil, simmer for 8–10 minutes, then cool in an ice bath and peel.</li><li>Peel the cooled potatoes and carrots. Dice the eggs, potatoes, carrots, sausage, pickles, onion and fresh cucumber.</li><li>Put everything in a large bowl with the frozen peas and mayonnaise. Stir, season with salt, pepper, sugar and chopped dill, and mix again.</li><li>Refrigerate until ready to serve.</li></ol><p><em>Chill for a couple of hours and sprinkle with fresh dill before serving.</em></p>', CURRENT_TIMESTAMP),
  ('bbfcc052-978f-5668-b388-f7af53a80e16', 'c4e1cf57-180a-5981-9416-569180855759', 'ru', 'Морковь по-корейски', 'Хрустящая морковная соломка, замаринованная в горячем масле с луком, чесноком, кориандром и уксусом. Классическая закуска славянского стола.', '<ol><li>Очищенную морковь натрите на тёрке для корейской моркови или нарежьте тонкой соломкой. Переложите в миску и перемешайте с половиной ч. л. соли.</li><li>Разогрейте масло на сковороде (оно не должно дымиться) и пассеруйте лук до мягкости. Снимите с огня и добавьте измельчённый чеснок.</li><li>Когда лук слегка остынет, добавьте паприку, чили, кориандр, чёрный перец, оставшуюся соль, сахар и уксус.</li><li>Вылейте масляную смесь на морковь, тщательно перемешайте, накройте и уберите в холодильник минимум на 2 часа.</li><li>Перед подачей посыпьте рубленой зеленью.</li></ol><p><em>Выдержите в холодильнике не менее 2 часов, посыпьте зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('4c6d0de3-714e-5f24-aaf4-735d0c49b40e', 'c4e1cf57-180a-5981-9416-569180855759', 'en', 'Korean-style carrot salad', 'Crunchy julienned carrots marinated in warm garlic-onion oil with coriander and vinegar, a staple of Slavic tables.', '<ol><li>Julienne or shred the peeled carrots, place them in a large bowl and toss with ½ tsp salt.</li><li>Heat the oil in a skillet (not smoking) and cook the onion until tender. Remove from the heat and stir in the minced garlic.</li><li>Once the onion has cooled slightly, stir in the paprika, chili, coriander, black pepper, remaining salt, sugar and vinegar.</li><li>Pour the oil mixture over the carrots, toss thoroughly, cover and refrigerate for at least 2 hours.</li><li>Garnish with chopped fresh herbs before serving.</li></ol><p><em>Chill for at least 2 hours and garnish with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('664f9709-b946-5c70-af3d-ccae06312451', '54da33df-6ad6-559a-93f6-323514cb6cae', 'ru', 'Рассольник с говядиной и перловкой', 'Наваристый суп с говядиной, перловой крупой, картофелем и солёными огурцами с рассолом. Заправка из лука, моркови и томатов придаёт насыщенный вкус.', '<ol><li>Залейте сушёные грибы горячей водой и оставьте набухать. Говядину посыпьте солью и перцем, добавьте раздавленные лавровые листья и нарезанный чеснок; по возможности оставьте в холодильнике на несколько часов или на ночь.</li><li>В большой кастрюле или казане доведите до кипения бульон с водой. Добавьте промытую говядину, отжатые грибы, промытую перловку, тёртые огурцы, рассол и лавровый лист. Готовьте на слабом огне 30 минут, снимая пену.</li><li>На сковороде пассеруйте лук в масле около 3 минут, добавьте тёртую морковь и доведите до мягкости. Положите чеснок, помидоры и кетчуп и прогрейте до пузырьков.</li><li>Переложите зажарку и картофель в суп, посолите и поперчите и варите ещё 10–12 минут до мягкости картофеля.</li><li>Добавьте свежую зелень, перемешайте и подавайте.</li></ol><p><em>Подавайте со сметаной и свежим укропом.</em></p>', CURRENT_TIMESTAMP),
  ('dc561768-2719-5518-84f0-4125fc29ff2e', '54da33df-6ad6-559a-93f6-323514cb6cae', 'en', 'Beef and barley dill pickle soup (rassolnik)', 'Hearty soup with beef, pearl barley, potatoes and grated pickles with a splash of pickle brine, finished with a sautéed vegetable base.', '<ol><li>Soak the dried mushrooms in hot water. Season the beef with salt, pepper, crushed bay leaves and sliced garlic and leave in the fridge, ideally for several hours or overnight.</li><li>In a large pot or Dutch oven bring the broth and water to a boil. Add the rinsed beef, drained mushrooms, rinsed barley, grated pickles, brine and a bay leaf, then simmer for 30 minutes, skimming the scum.</li><li>In a skillet sauté the onion in oil for about 3 minutes, add the grated carrot and cook until tender. Add the garlic, tomatoes and ketchup and heat until bubbling.</li><li>Add the sautéed vegetables and potatoes to the pot, season and cook another 10–12 minutes until the potatoes are tender.</li><li>Stir in the fresh herbs and serve.</li></ol><p><em>Serve with sour cream and fresh dill.</em></p>', CURRENT_TIMESTAMP),
  ('1c9bcf85-ad61-5a43-a26d-cd3a13b15115', 'f3411800-aec4-535d-bc6b-a5ca9454a577', 'ru', 'Огурцы со сметаной и укропом', 'Свежий салат из тонко нарезанных огурцов и красного лука в заправке из майонеза, сметаны, лимонного сока и чеснока с укропом.', '<ol><li>В миске смешайте майонез, сметану, лимонный сок, чеснок, соль и перец.</li><li>Добавьте тонко нарезанные огурцы, лук и мелко рубленый укроп и аккуратно перемешайте. Подавайте сразу или охладите.</li></ol><p><em>Хорош к жареному мясу, картофелю и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('e661e422-b724-5bec-9a3b-5519d8291979', 'f3411800-aec4-535d-bc6b-a5ca9454a577', 'en', 'Creamy cucumber dill salad', 'Thinly sliced cucumbers and red onion in a creamy dressing of mayonnaise, sour cream, lemon, garlic and fresh dill.', '<ol><li>In a bowl combine the mayonnaise, sour cream, lemon juice, garlic, salt and pepper.</li><li>Add the thinly sliced cucumbers, onion and finely chopped dill and toss to combine. Serve right away or chilled.</li></ol><p><em>A good side for grilled meat, potatoes or fish.</em></p>', CURRENT_TIMESTAMP),
  ('9ab3839a-ed82-5499-84cd-2e83c9fb45f1', '73295215-c80a-5d07-8933-478c86378e17', 'ru', 'Бефстроганов с грибами и сметаной', 'Тонкие полоски говядины с луком и шампиньонами в сливочно-сметанном соусе. Готовится быстро, за 25 минут.', '<ol><li>Разогрейте на большой сковороде масло. Обжарьте половину полосок говядины по 2 минуты с каждой стороны, пока мясо не будет готово наполовину. Посолите и поперчите и переложите на тарелку. Так же обжарьте остальное мясо и накройте, чтобы не остыло.</li><li>В ту же сковороду положите лук и грибы и готовьте до мягкости.</li><li>Добавьте сливочное масло и чеснок, всыпьте муку и перемешайте до исчезновения комочков.</li><li>В отдельной миске смешайте бульон, сметану и горчицу. Влейте в сковороду, доведите до слабого кипения, посолите и поперчите по вкусу.</li><li>Верните мясо в соус, прогрейте и подавайте.</li></ol><p><em>Подавайте с картофельным пюре, макаронами или гречкой.</em></p>', CURRENT_TIMESTAMP),
  ('80ff794a-1fd1-5125-b917-5aeb4e65e20a', '73295215-c80a-5d07-8933-478c86378e17', 'en', 'Beef stroganoff with mushrooms', 'Thin strips of beef with onion and mushrooms in a creamy sour cream sauce, ready in about 25 minutes.', '<ol><li>Heat the oil in a large skillet. Sear half of the beef strips for 2 minutes per side until half cooked, season with salt and pepper and remove. Repeat with the rest and keep covered.</li><li>Add the onion and mushrooms to the same pan and cook until tender.</li><li>Add the butter and garlic, sprinkle in the flour and stir until no clumps remain.</li><li>In a separate bowl whisk the broth, sour cream and mustard. Pour into the pan, bring to a simmer and season to taste.</li><li>Return the beef to the sauce, heat through and serve.</li></ol><p><em>Serve over mashed potatoes, noodles or buckwheat.</em></p>', CURRENT_TIMESTAMP),
  ('e41d5f36-05ce-5046-aaaa-174a180404de', 'f19a7219-a1d6-5338-985f-c9d9b464c52e', 'ru', 'Оладьи с творогом', 'Пышные оладьи на твороге и яйцах с небольшим количеством сахара. Сытный завтрак с белком.', '<ol><li>В большой миске смешайте творог, яйца, сахар, ваниль и молоко. Добавьте муку с разрыхлителем и перемешайте до однородного теста.</li><li>Разогрейте большую сковороду на среднем огне, добавьте половину масла и половину сливочного масла.</li><li>Выкладывайте тесто порциями по ¼ стакана. Жарьте около минуты, пока края не подсохнут и на поверхности не появятся пузырьки.</li><li>Переверните и жарьте ещё 2–3 минуты до румяной корочки и готовой середины. Остальные оладьи жарьте так же, добавляя остаток масла. Подавайте тёплыми.</li></ol><p><em>Подавайте со сметаной, ягодами или мёдом.</em></p>', CURRENT_TIMESTAMP),
  ('88a8e6c2-3ca8-572d-9242-c641b65e253c', 'f19a7219-a1d6-5338-985f-c9d9b464c52e', 'en', 'Cottage cheese pancakes', 'Fluffy pancakes made with cottage cheese and eggs and only a little sugar, a protein-rich breakfast.', '<ol><li>In a large bowl combine the cottage cheese, eggs, sugar, vanilla and milk. Add the flour and baking powder and stir until just combined.</li><li>Heat a large skillet over medium heat and add half of the oil and half of the butter.</li><li>Scoop the batter in ¼-cup portions and cook for about a minute, until the edges set and bubbles form on the surface.</li><li>Flip and cook 2–3 more minutes until golden and cooked through. Cook the remaining pancakes the same way with the rest of the fat and serve warm.</li></ol><p><em>Serve with berries, sour cream or honey.</em></p>', CURRENT_TIMESTAMP),
  ('c2b2cc03-b9b3-5609-8c3e-0cd5ef3bf227', '0d3137c5-15ae-5c73-97d2-fbdd46e20d78', 'ru', 'Куриные эскалопы с прошутто (сальтимбокка)', 'Тонкие куриные эскалопы в муке, накрытые ломтиками прошутто и обжаренные до хрустящей корочки. Готовятся за 15 минут.', '<ol><li>Разрежьте каждую грудку вдоль пополам, затем верхнюю половину разрежьте ещё раз пополам: всего получится 9 тонких кусочков.</li><li>Посолите и поперчите одну сторону курицы, обваляйте в муке. На несолёную сторону положите ломтик прошутто.</li><li>Хорошо разогрейте в обычной (не антипригарной) сковороде 1–2 ст. л. масла на сильно-среднем огне и выложите курицу стороной с прошутто вниз.</li><li>Жарьте около 2 минут, пока прошутто не станет золотистым и хрустящим и не начнёт легко отделяться от сковороды. Переверните и жарьте ещё 1–2 минуты.</li></ol><p><em>Подайте с салатом, пастой или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('de67612b-8f0d-549f-bbb2-e58392ace59e', '0d3137c5-15ae-5c73-97d2-fbdd46e20d78', 'en', 'Chicken saltimbocca with prosciutto', 'Thin floured chicken cutlets topped with prosciutto and pan-fried until the ham is crisp. Ready in about 15 minutes.', '<ol><li>Slice each chicken breast in half horizontally, then cut the top half in two again to make 9 thin cutlets in all.</li><li>Season one side of the chicken with salt and pepper and dredge in flour. Lay a slice of prosciutto on the unseasoned side of each cutlet.</li><li>Heat 1–2 tbsp of oil in a regular (not non-stick) skillet over medium-high until very hot and place the chicken in prosciutto-side down.</li><li>Cook about 2 minutes, until the prosciutto is golden and crisp and releases easily. Flip and cook 1–2 minutes more.</li></ol><p><em>Serve with a salad, pasta or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('effc2508-d4d2-5e0c-8576-7c6bcb827188', '8819f64a-9870-50b7-88df-15564cc07e09', 'ru', 'Лосось, запечённый с луком и сыром', 'Цельное филе лосося под слоем тонкого лука и румяной сырной корочкой на майонезно-горчичной заправке. Эффектное и простое праздничное блюдо.', '<ol><li>Разогрейте духовку до 200 °C и застелите противень фольгой.</li><li>Выложите лосось на противень, посолите и поперчите. Сверху плотно разложите очень тонко нарезанный лук.</li><li>Смешайте майонез, лимонный сок, горчицу и чеснок, чтобы смесь легко намазывалась. Распределите по луку, посыпьте мелко натёртыми пармезаном и моцареллой.</li><li>Запекайте 15–20 минут, затем включите гриль на 2–5 минут, чтобы сыр стал золотистым.</li></ol><p><em>Подайте с отварным картофелем, рисом или свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('4c71b3f8-81a5-5991-857b-92aaf04e7b88', '8819f64a-9870-50b7-88df-15564cc07e09', 'en', 'Cheesy baked salmon with onion', 'A whole salmon fillet baked under thin onion slices, a creamy mustard-mayo layer and a golden cheese crust. Impressive yet easy.', '<ol><li>Preheat the oven to 400 °F (200 °C) and line a rimmed baking sheet with foil.</li><li>Put the salmon on the sheet and season with salt and pepper. Cover the surface completely with very thinly sliced onion.</li><li>Mix the mayonnaise, lemon juice, mustard and garlic into a spreadable sauce. Spread it over the onions and top with the finely grated Parmesan and mozzarella.</li><li>Bake for 15–20 minutes, then broil for 2–5 minutes until the cheese is golden brown.</li></ol><p><em>Serve with boiled potatoes, rice or fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('599c5896-a9e4-57d7-9f4b-e9afcb9d9993', '7e26f7c1-1098-5ffa-9dda-050816773f3a', 'ru', 'Рис с кабачком, кукурузой и чёрной фасолью', 'Рассыпчатый рис с овощами, кукурузой и чёрной фасолью, с лаймом, кинзой и мягкой остротой перца. Подходит и как самостоятельное блюдо, и как гарнир.', '<ol><li>Вскипятите воду. Нарежьте лук, мелко нарубите перец, чеснок, кабачок нарежьте тонкой соломкой (или натрите).</li><li>Разогрейте масло в глубокой сковороде или сотейнике, обжарьте лук, перец и чеснок с солью и перцем около 3 минут.</li><li>Добавьте кабачок и готовьте около 2 минут. Всыпьте кукурузу, рис, цедру лайма и 1 ч. л. соли, перемешивайте около минуты, пока рис не покроется овощами.</li><li>Влейте половину сока лайма и кипяток, накройте крышкой, сразу убавьте огонь до слабого и варите 10 минут. Выключите.</li><li>Оставьте под крышкой на 5 минут, взрыхлите вилкой, аккуратно вмешайте фасоль, кинзу и зелёный лук. При необходимости добавьте остальной сок лайма.</li></ol><p><em>Подайте с ломтиком лайма и сметаной или йогуртом.</em></p>', CURRENT_TIMESTAMP),
  ('de1960cb-d3f9-562e-a517-e83b1848fcf2', '7e26f7c1-1098-5ffa-9dda-050816773f3a', 'en', 'Zucchini, corn and black bean rice', 'Fluffy rice cooked with vegetables, corn and black beans, brightened with lime and cilantro. Works as a light main or a side.', '<ol><li>Put the water on to boil. Chop the onion, mince the pepper and garlic and cut the zucchini into thin julienne (or grate it).</li><li>Heat the oil in a deep skillet or Dutch oven and cook the onion, pepper and garlic with salt and pepper for about 3 minutes.</li><li>Add the zucchini and cook about 2 minutes. Stir in the corn, rice, lime zest and 1 tsp salt and mix for about a minute until the rice is coated.</li><li>Add half the lime juice and the boiling water, cover, immediately reduce to a low simmer and cook 10 minutes, then turn off the heat.</li><li>Let stand covered for 5 minutes, fluff with a fork and gently fold in the beans, cilantro and green onion. Add the rest of the lime juice if needed.</li></ol><p><em>Serve with a lime wedge and sour cream or yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('fcfe5fe7-60bd-524d-9bc8-78e7db89995a', '84c02257-e51f-54ef-a21a-6b8e6baeda6c', 'ru', 'Картофельный суп с беконом и чеддером', 'Густой картофельный суп, томлёный в мультиварке, со сливками, сыром чеддер и хрустящим беконом.', '<ol><li>Нарежьте бекон небольшими кусочками и обжарьте на среднем огне до золотистого цвета. Переложите на бумажное полотенце и отложите для подачи. В сковороде оставьте 1–2 ст. л. жира.</li><li>Добавьте лук, чеснок и тимьян, посолите щепоткой и готовьте до мягкости и лёгкой золотистости. Всыпьте муку и жарьте минуту.</li><li>Влейте около стакана бульона и вымешайте венчиком до загустения, затем добавьте остальной бульон, доведите до кипения и перелейте в чашу мультиварки.</li><li>Нарежьте картофель кубиками по 1,5 см, добавьте в мультиварку, закройте крышку и готовьте на низком режиме 4–6 часов.</li><li>Выньте около 2 стаканов картофеля с частью жидкости и разомните толкушкой, верните в суп. Добавьте сливки и тёртый сыр, выньте ветки тимьяна.</li><li>Разогрейте бекон, разлейте суп по тарелкам и посыпьте беконом, шнитт-луком и сыром.</li></ol><p><em>Посыпьте беконом, шнитт-луком, сыром и добавьте ложку сметаны.</em></p>', CURRENT_TIMESTAMP),
  ('6a858b7e-2a51-50e0-b7c1-760407bb2b34', '84c02257-e51f-54ef-a21a-6b8e6baeda6c', 'en', 'Loaded baked potato soup', 'A thick potato soup slow-cooked with cream, cheddar and crispy bacon, topped like a loaded baked potato.', '<ol><li>Cut the bacon into small pieces and cook over medium heat until golden and crisp. Drain on paper towels and set aside for garnish. Leave 1–2 tbsp of the fat in the pan.</li><li>Add the onion, garlic and thyme with a pinch of salt and cook until soft and slightly golden. Stir in the flour and cook for a minute.</li><li>Pour in about a cup of the broth and whisk until thickened, then add the rest, bring to a boil and pour into the slow cooker.</li><li>Cut the potatoes into 1.5 cm cubes, add to the slow cooker, cover and cook on low for 4–6 hours.</li><li>Take out about 2 cups of the potatoes with some liquid, mash with a potato masher and return to the soup. Stir in the cream and shredded cheese and remove the thyme sprigs.</li><li>Warm the bacon, ladle the soup into bowls and garnish with bacon, chives and cheese.</li></ol><p><em>Top with bacon, chives, cheese and a spoonful of sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('e0464a2a-0d43-5240-9626-7e2fb085e8dd', 'efc110ff-3d5f-5a5e-bf0c-b725a38c4586', 'ru', 'Паста с песто, куриными полосками в сухарях и черри', 'Паста в сливочно-базиликовом соусе песто с шалотом и помидорами черри, к которой подаются золотистые куриные полоски в панировке.', '<ol><li>Для песто подсушите кедровые орехи и неочищенный чеснок на сухой сковороде. Орехи снимите, когда зарумянятся, чеснок держите до золотистых пятен, затем остудите.</li><li>Очистите чеснок, измельчите в кухонном комбайне с орехами, базиликом, шпинатом и пармезаном. Не выключая, тонкой струёй влейте оливковое масло. Можно взять готовое песто.</li><li>Обмакните куриные полоски во взбитое яйцо, затем плотно запанируйте в сухарях, прижимая руками.</li><li>Отварите пасту в подсоленной воде до нужной мягкости, оставив 1 стакан отвара.</li><li>Тем временем разогрейте 2 ст. л. масла и обжарьте курицу порциями по 2–4 минуты с каждой стороны до золотистого цвета. Держите тёплой под фольгой.</li><li>В другой сковороде в оставшемся масле 2 минуты потушите шалот, добавьте помидоры, чеснок, острый перец, соль и перец, готовьте минуту.</li><li>Добавьте песто и прогрейте минуту, влейте сливки. Положите пасту, перемешайте и постепенно подливайте отвар до нужной консистенции.</li><li>Подавайте сразу вместе с куриными полосками.</li></ol><p><em>Посыпьте тёртым пармезаном и подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('12954e0b-7e28-5c29-a97a-5764ae8753fb', 'efc110ff-3d5f-5a5e-bf0c-b725a38c4586', 'en', 'Pesto pasta with breaded chicken tenders and cherry tomatoes', 'Pasta in a creamy homemade basil-spinach pesto with shallots and cherry tomatoes, served with golden breaded chicken tenders.', '<ol><li>For the pesto, toast the pine nuts and unpeeled garlic in a dry skillet. Take off the nuts when golden and keep toasting the garlic until golden and spotty, then cool slightly.</li><li>Peel the garlic and pulse it in a food processor with the nuts, basil, spinach and Parmesan. With the machine running, slowly pour in the olive oil. Store-bought pesto works too.</li><li>Dip the chicken strips in the beaten egg, then press them firmly into the breadcrumbs.</li><li>Cook the pasta in salted boiling water to your liking, reserving about 1 cup of the cooking water.</li><li>Meanwhile heat 2 tbsp of the oil and fry the chicken in two batches, 2–4 minutes per side, until golden. Keep warm under foil.</li><li>In another skillet, soften the shallots in the remaining oil for 2 minutes, add the tomatoes, garlic, chilli, salt and pepper and cook for 1 minute.</li><li>Stir in the pesto and heat for a minute, then add the cream. Toss in the pasta and gradually add the pasta water until the sauce is the right consistency.</li><li>Serve immediately with the chicken tenders.</li></ol><p><em>Sprinkle with grated Parmesan and serve at once.</em></p>', CURRENT_TIMESTAMP),
  ('95a35c2b-28ef-5b7e-8487-d3a9f402fb53', 'dc2f57a5-7bde-5638-8b00-ca8f87d7415f', 'ru', 'Паста с говяжьим фаршем и сыром на сковороде', 'Сливочная сырная паста с говяжьим фаршем, луком и томатным соусом, всё готовится в одной сковороде. Вкус как у чизбургера.', '<ol><li>Разогрейте масло в большой сковороде, обжарьте говяжий фарш на средне-сильном огне до румяного цвета. Лишний жир слейте.</li><li>Добавьте лук, чеснок и острый перец, посолите и поперчите. Готовьте на среднем огне 5–7 минут, пока лук не станет мягким.</li><li>Влейте томатный соус, положите тимьян, добавьте воду или бульон и молоко и доведите до кипения.</li><li>Всыпьте пасту и варите на слабом огне без крышки около 10 минут до готовности. Если густо, добавьте жидкости. Уберите стебли тимьяна.</li><li>Снимите с огня, вмешайте тёртый сыр. Подавайте с зеленью и дополнительным сыром.</li></ol><p><em>Подайте с солёными огурцами и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('3749fc69-9600-5c1d-9292-9152af408084', 'dc2f57a5-7bde-5638-8b00-ca8f87d7415f', 'en', 'Skillet cheeseburger pasta', 'Creamy, cheesy one-skillet pasta with ground beef, onion and tomato sauce that tastes like a cheeseburger.', '<ol><li>Heat the oil in a large skillet and brown the ground beef over medium-high heat. Drain off excess fat.</li><li>Add the onion, garlic and chilli flakes, season with salt and pepper and cook over medium heat for 5–7 minutes until the onion is tender.</li><li>Add the tomato sauce and thyme, pour in the broth and milk and bring to the boil.</li><li>Add the pasta and simmer uncovered for about 10 minutes until cooked. Add more liquid if it gets too thick and discard the thyme stems.</li><li>Off the heat, stir in the shredded cheese. Serve with herbs and extra cheese.</li></ol><p><em>Serve with pickles on the side and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('a706eb97-c966-5fcf-82ba-dca768179c78', 'd7afbc85-18ba-5aa9-bcb2-347687510bfc', 'ru', 'Сливочный картофельный суп с беконом и чеддером', 'Густой суп-пюре из картофеля на молоке и курином бульоне со сметаной, сыром чеддер и хрустящим беконом.', '<ol><li>Очистите картофель, нарежьте мелкими кубиками и держите в холодной воде.</li><li>В толстостенной кастрюле обжарьте бекон до хруста. Выньте бекон, оставив в кастрюле около 1 ст. л. жира.</li><li>Добавьте сливочное масло и обжарьте лук до прозрачности, затем положите чеснок. Всыпьте муку и готовьте около минуты, помешивая.</li><li>Влейте молоко и бульон, доведите до слабого кипения, добавьте картофель и варите на слабом огне около 10 минут, пока он не станет мягким. Слегка разомните картофель толкушкой или блендером для кремовой текстуры, посолите и поперчите.</li><li>Вмешайте сметану и тёртый чеддер, верните большую часть бекона, доведите до кипения и выключите огонь. Подавайте с оставшимся беконом, сыром и зелёным луком.</li></ol><p><em>Посыпьте беконом, тёртым сыром и зелёным луком, добавьте ложку сметаны.</em></p>', CURRENT_TIMESTAMP),
  ('04c4b39f-ea37-5784-96b7-3a15e5e74b1b', 'd7afbc85-18ba-5aa9-bcb2-347687510bfc', 'en', 'Creamy potato soup with bacon and cheddar', 'Thick, creamy potato soup made with milk and chicken broth, finished with sour cream, cheddar and crispy bacon.', '<ol><li>Peel the potatoes, cut them into small cubes and keep them in cold water.</li><li>In a Dutch oven fry the bacon until crisp. Remove it, leaving about 1 tbsp of fat in the pot.</li><li>Add the butter and sauté the onion until translucent, then add the garlic. Whisk in the flour and cook for about a minute.</li><li>Pour in the milk and broth, bring to a soft boil, add the potatoes and simmer about 10 minutes until fork tender. Lightly mash the potatoes with a masher or use an immersion blender for a creamier texture, then season.</li><li>Stir in the sour cream and cheddar and return most of the bacon, bring to a boil and turn off the heat. Serve topped with the remaining bacon, cheese and green onions.</li></ol><p><em>Top with bacon, shredded cheese, green onion and a spoon of sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('b5abd5b0-3bdc-5fdc-aaf9-6e2ef1e20cd7', 'e3da2b2c-5b8f-5556-a702-4386dc1545f0', 'ru', 'Макароны с говяжьим фаршем в томатном соусе (американский гуляш)', 'Сытное блюдо из рожков в томатном соусе с говяжьим фаршем, болгарским перцем и сыром. Готовится на сковороде за 35 минут.', '<ol><li>Отварите макароны в подсоленной воде до состояния аль денте, слейте воду и отложите.</li><li>В глубокой сковороде обжарьте фарш, разбивая комочки. Когда мясо начнёт румяниться, добавьте лук и перец и готовьте до мягкости овощей.</li><li>Добавьте чеснок, посолите и поперчите. Влейте консервированные помидоры, томатный соус, кетчуп и вустерский соус, положите лавровый лист и итальянские травы.</li><li>Доведите до кипения и томите на слабом огне 10 минут, иногда помешивая.</li><li>Выньте лавровый лист, добавьте макароны и горстями вмешайте сыр до расплавления.</li></ol><p><em>Посыпьте зеленью и подавайте с овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('7c23cc73-ecda-5f0d-a30d-42ff81848cbd', 'e3da2b2c-5b8f-5556-a702-4386dc1545f0', 'en', 'American goulash with beef and macaroni', 'Hearty pot of elbow macaroni in a tomato sauce with ground beef, bell pepper and melted cheese, made in about 35 minutes.', '<ol><li>Cook the macaroni in salted water until al dente, drain and set aside.</li><li>Brown the ground beef in a deep skillet, breaking it up. When it starts to brown add the onion and bell pepper and cook until softened.</li><li>Add the garlic, salt and pepper. Stir in the diced tomatoes, tomato sauce, ketchup and Worcestershire, then add the bay leaves and Italian seasoning.</li><li>Bring to a simmer and cook on low heat for 10 minutes, stirring occasionally.</li><li>Remove the bay leaves, add the pasta and stir in the cheese a handful at a time until melted.</li></ol><p><em>Garnish with herbs and serve with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('6de7d473-2f18-5f29-b82d-7dd4c26db699', '12719cbe-3894-5682-9ad1-5802cf9e8256', 'ru', 'Гороховый суп с курицей и картофелем', 'Наваристый гороховый суп на курином бульоне с кусочками куриных бёдер, картофелем и овощами. Свежий укроп и петрушка в конце.', '<ol><li>Разогрейте 1 ст. л. масла в кастрюле с толстым дном, обжарьте кубики курицы с приправами до готовности и переложите на тарелку.</li><li>Влейте оставшиеся 2 ст. л. масла, обжарьте лук, морковь и сельдерей до мягкости, затем добавьте чеснок на минуту.</li><li>Влейте бульон, добавьте лавровый лист и промытый горох. Доведите до слабого кипения и варите на среднем-слабом огне 35–40 минут, пока горох почти не станет мягким.</li><li>Добавьте картофель кубиками и обжаренную курицу и варите ещё 10–12 минут до мягкости картофеля и гороха.</li><li>Попробуйте, при необходимости досолите, добавьте рубленые укроп и петрушку и подавайте.</li></ol><p><em>Подавайте с чёрным хлебом или гренками.</em></p>', CURRENT_TIMESTAMP),
  ('bc7b0495-d88d-522d-acbc-2fe519e215db', '12719cbe-3894-5682-9ad1-5802cf9e8256', 'en', 'Split pea soup with chicken and potatoes', 'Hearty split pea soup in chicken broth with tender chicken thigh pieces, potatoes and vegetables, finished with fresh dill and parsley.', '<ol><li>Heat 1 tbsp oil in a Dutch oven and cook the cubed chicken thighs with seasoning until done. Set aside.</li><li>Add the remaining 2 tbsp oil, sauté the onion, carrots and celery until they begin to soften, then add the garlic for 1 minute.</li><li>Add the broth, bay leaves and rinsed split peas. Bring to a gentle simmer and cook over medium-low heat for 35–40 minutes until the peas are almost tender.</li><li>Add the cubed potatoes and cooked chicken and cook another 10–12 minutes until the potatoes and peas are tender.</li><li>Taste and adjust the seasoning, stir in the chopped dill and parsley and serve.</li></ol><p><em>Serve with rye bread or croutons.</em></p>', CURRENT_TIMESTAMP),
  ('8fb2094a-40e0-5205-a2d8-0238a1fbe0d1', '16241237-37f3-5907-b28c-331f66e2ea30', 'ru', 'Сливочный грибной суп из шампиньонов', 'Густой суп с обжаренными шампиньонами, луком и чесноком на курином бульоне со сливками. Готовится в одной кастрюле меньше чем за 40 минут.', '<ol><li>Разогрейте в большой кастрюле масло, выложите нарезанные шампиньоны и обжарьте до золотистого цвета. Переложите грибы на тарелку.</li><li>Растопите в той же кастрюле сливочное масло, обжарьте лук до мягкости, затем добавьте чеснок.</li><li>Верните грибы, всыпьте муку и помешивайте, пока она не прогреется.</li><li>Влейте бульон, добавьте соль и перец и варите на среднем огне 10–12 минут.</li><li>Влейте сливки и прогрейте до лёгкого кипения. Подавайте горячим.</li></ol><p><em>Подавайте с гренками или свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('3606a4cc-3074-56aa-b066-60934e67f028', '16241237-37f3-5907-b28c-331f66e2ea30', 'en', 'Creamy mushroom soup', 'Rich soup of golden sautéed mushrooms, onion and garlic simmered in chicken broth and finished with cream, made in one pot.', '<ol><li>Heat the oil in a large Dutch oven, add the sliced mushrooms and cook until golden brown. Remove them from the pot.</li><li>Melt the butter in the same pot, sauté the onion until soft, then add the garlic.</li><li>Return the mushrooms, add the flour and whisk until the flour is cooked off.</li><li>Pour in the chicken broth, season with salt and pepper and cook on medium for 10–12 minutes.</li><li>Pour in the cream and heat to a light simmer. Serve hot.</li></ol><p><em>Serve with croutons or fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('6d8dbf2c-bb9b-53c2-96a5-75aa0e9422fb', '8c3ede2a-7c9d-53fa-bad4-61bc314c0078', 'ru', 'Салат из помидоров черри с моцареллой', 'Лёгкий салат из сладких помидоров черри и мини-шариков моцареллы с красным луком и заправкой из масла, уксуса и чеснока.', '<ol><li>В миске смешайте масло, уксус и измельчённый чеснок.</li><li>В салатницу выложите нарезанные пополам помидоры черри, шарики моцареллы, тонкие кольца красного лука и зелень.</li><li>Полейте заправкой, посолите, поперчите, аккуратно перемешайте и подавайте.</li></ol><p><em>Посыпьте свежим базиликом или петрушкой и подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('5f733bb4-2342-5bd2-a470-14141c53e1c5', '8c3ede2a-7c9d-53fa-bad4-61bc314c0078', 'en', 'Cherry tomato and mozzarella salad', 'A light salad of ripe cherry tomatoes and mini mozzarella balls with red onion, dressed with oil, vinegar and garlic.', '<ol><li>In a bowl mix the oil, vinegar and minced garlic.</li><li>Put the halved cherry tomatoes, mozzarella balls, thinly sliced red onion and fresh herbs in a salad bowl.</li><li>Pour over the dressing, season with salt and pepper, toss gently and serve.</li></ol><p><em>Sprinkle with fresh basil or parsley and serve right away.</em></p>', CURRENT_TIMESTAMP),
  ('47c1edc2-105d-5a56-a06f-c7275fcd0d94', 'a401c2e6-8d0c-5cd5-bce6-b849368fae5e', 'ru', 'Запеканка с говяжьим фаршем и картофельным пюре (пастуший пирог)', 'Фарш с овощами в густом соусе под слоем картофельного пюре, запечённый до золотистой корочки.', '<ol><li>Очистите картофель, разрежьте на четвертинки, отварите до мягкости и разомните в пюре с маслом, молоком и солью.</li><li>Разогрейте духовку до 190 °C. В сковороде разогрейте масло и обжарьте фарш с луком, разбивая комочки.</li><li>Добавьте чеснок, затем муку и лавровый лист и влейте бульон. Когда смесь загустеет, положите помидоры и кетчуп, посолите и поперчите и доведите до кипения.</li><li>Добавьте овощи и снова доведите до лёгкого кипения. Выложите мясную смесь в форму для запекания, предварительно убрав лавровый лист.</li><li>Сверху распределите пюре и сделайте рисунок вилкой. Запекайте 25–30 минут, пока пюре не зарумянится.</li></ol><p><em>Подавайте с зелёным горошком или свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('479ab4ee-67da-598a-9135-de4ecef77301', 'a401c2e6-8d0c-5cd5-bce6-b849368fae5e', 'en', 'Beef shepherd''s pie', 'Ground beef and vegetables in a thick gravy topped with mashed potatoes and baked until golden.', '<ol><li>Peel and quarter the potatoes, boil until soft and mash with the butter, milk and salt.</li><li>Preheat the oven to 375 °F (190 °C). Heat the oil in a skillet and brown the beef with the onion, breaking it apart.</li><li>Stir in the garlic, then the flour and bay leaves, and pour in the broth. When thickened, add the tomatoes and ketchup, season with salt and pepper and bring to a simmer.</li><li>Add the vegetables and simmer again. Transfer the meat mixture to a baking dish, discarding the bay leaves.</li><li>Spread the mashed potatoes on top and mark with a fork. Bake 25–30 minutes until the potatoes turn golden.</li></ol><p><em>Serve with green peas or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('7dfecf4e-c855-5bf8-b31a-603899dbfab1', '2eada94e-5611-54ee-9c26-98baebf7bb4d', 'ru', 'Перец, фаршированный говядиной и рисом', 'Сладкий перец, начинённый сырым говяжьим фаршем с рисом и морковью с луком, запечённый в томатном соусе до мягкости.', '<ol><li>Вымойте перцы, срежьте верх и удалите семена. Рис залейте 360 мл воды, доведите до кипения и варите под крышкой на слабом огне 10 минут (рис должен остаться недоваренным).</li><li>Пока варится рис, около 10 минут обжарьте лук и тёртую морковь на растительном масле.</li><li>В большой миске смешайте рис, сырой фарш, соль и перец. Добавьте половину обжаренных овощей и перемешайте.</li><li>Оставшиеся овощи верните на огонь, добавьте томатный соус, разведённый стаканом воды, соль и перец и прогрейте до слабого кипения.</li><li>Начините перцы горкой смеси из мяса и риса и поставьте в форму. Залейте томатным соусом с овощами.</li><li>Запекайте при 175 °C от 1,5 до 2 часов до мягкости перцев и готовности мяса. Подавайте со сметаной.</li></ol><p><em>Подайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('08982985-c124-5f04-826d-1c98c18c5d46', '2eada94e-5611-54ee-9c26-98baebf7bb4d', 'en', 'Stuffed peppers with beef and rice', 'Sweet bell peppers filled with raw ground beef, rice, carrots and onions and baked in tomato sauce until tender.', '<ol><li>Wash the peppers, cut off the tops and remove the seeds. Bring the rice and 1½ cups (360 ml) of water to a boil, cover and simmer on low for 10 minutes; it will be only part-cooked.</li><li>While the rice cooks, sauté the onions and grated carrots in oil for about 10 minutes.</li><li>In a large bowl combine the rice, raw ground beef, salt and pepper. Add half of the sautéed vegetables and mix.</li><li>Return the remaining vegetables to the heat, add the tomato sauce diluted with 1 cup of water, salt and pepper and bring to a gentle simmer.</li><li>Fill each pepper with a mound of the meat and rice mixture and stand them in a baking dish. Pour the tomato sauce mixture evenly over the top.</li><li>Bake at 350 °F (175 °C) for 1½ to 2 hours until the peppers are tender and the filling is cooked. Serve with sour cream.</li></ol><p><em>Serve with sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('6d27b845-5edc-5062-87b3-eb7076b413ad', 'ed5cc77b-a5d6-5542-964c-8bac8ebc1328', 'ru', 'Овощное рагу из баклажанов с рисом', 'Баклажаны, помидоры, сладкий перец и морковь, тушёные с рисом в одной сковороде. Подаётся тёплым как гарнир или холодным как салат.', '<ol><li>Нарежьте баклажаны кусочками, помидоры и перец — кубиками, лук нарежьте, чеснок разомните, морковь натрите. Промойте рис.</li><li>Разогрейте в глубокой сковороде на среднем огне оливковое масло, добавьте все овощи, рис, уксус, соль, сахар и халапеньо. Готовьте около 8 минут, помешивая, пока овощи не пустят сок и смесь не забулькает.</li><li>Накройте крышкой, убавьте огонь до слабого и тушите около 30 минут, изредка помешивая.</li><li>Подавайте тёплым прямо из сковороды или остудите и уберите в холодильник как салат.</li></ol><p><em>Подайте тёплым с мясом или холодным как закуску с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('d05db900-9b91-5d6a-91e3-6467ed8efbed', 'ed5cc77b-a5d6-5542-964c-8bac8ebc1328', 'en', 'Eggplant and vegetable rice stew', 'Eggplant, tomatoes, bell pepper and carrots braised with rice in one skillet. Serve warm as a side or chilled as a salad.', '<ol><li>Chop the eggplant into bite-sized pieces, dice the tomatoes, peppers and onion, crush the garlic and grate the carrots. Rinse the rice.</li><li>Heat the olive oil in a deep skillet over medium heat, then add all the vegetables, rice, vinegar, salt, sugar and jalapeños. Sauté about 8 minutes, stirring often, until the vegetables release liquid and the mixture bubbles.</li><li>Cover, reduce the heat to low and braise for about 30 minutes, stirring occasionally.</li><li>Serve warm from the skillet, or cool and refrigerate to serve as a salad.</li></ol><p><em>Serve warm alongside meat or chilled as an appetizer with bread.</em></p>', CURRENT_TIMESTAMP),
  ('26388c79-da61-5593-ac6b-09c46eb3c7c9', '227e2608-1ac8-5efe-9281-ea6cb4c8afe5', 'ru', 'Спагетти с мясным соусом и сыром', 'Быстрая паста с говяжьим фаршем в томатном соусе, посыпанная моцареллой и пармезаном, которые плавятся под крышкой.', '<ol><li>Сварите спагетти 13–14 минут в подсоленной воде, слейте воду, смешайте с 2 ст. л. масла и верните в кастрюлю.</li><li>Тем временем обжарьте говяжий фарш в сковороде до исчезновения розового цвета, разбивая комки.</li><li>Влейте томатный соус и воду, тушите на слабом огне около минуты.</li><li>Выложите соус на спагетти, посыпьте моцареллой и пармезаном, накройте крышкой, пока сыр не расплавится, и подавайте.</li></ol><p><em>Подайте с зеленью и салатом из свежих овощей.</em></p>', CURRENT_TIMESTAMP),
  ('1dcf0daf-77db-5f80-82d1-eb4ed7e77064', '227e2608-1ac8-5efe-9281-ea6cb4c8afe5', 'en', 'Spaghetti with meat sauce and cheese', 'A quick pasta with browned ground beef in tomato sauce, topped with mozzarella and Parmesan melted under a lid.', '<ol><li>Cook the spaghetti in salted water for 13–14 minutes, drain, toss with 2 tbsp of oil and return to the pot.</li><li>Meanwhile brown the ground beef in a skillet until no longer pink, breaking up any lumps.</li><li>Add the tomato sauce and water and simmer gently over low heat for about a minute.</li><li>Spoon the sauce over the spaghetti, sprinkle with mozzarella and Parmesan, cover with a lid until the cheese melts and serve.</li></ol><p><em>Serve with fresh herbs and a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('4bfefdf4-bec7-52f7-badf-937856abda05', 'f201f014-1d08-50f3-880d-f2302a7c4a79', 'ru', 'Запечённый раздавленный картофель с пармезаном', 'Мелкий картофель, отваренный, слегка раздавленный и запечённый до хрустящей золотистой корочки с чесночной солью и пармезаном.', '<ol><li>Доведите до кипения подсоленную воду, опустите целый мелкий картофель и варите на слабом кипении 25–30 минут, пока он не станет мягким.</li><li>Разогрейте духовку до 230 °C. Слейте воду, переложите картофель на смазанный маслом противень с бортами и дайте обсохнуть 5 минут. Раздавите каждую картофелину толкушкой или донышком стакана до толщины около 1,5 см.</li><li>Сбрызните половиной оливкового масла, посыпьте чесночной солью и перцем и запекайте 15 минут до появления золотистого цвета.</li><li>Переверните картофель, сбрызните второй стороной оставшимся маслом, добавьте приправы и запекайте ещё 12–15 минут до хрустящих румяных краёв.</li><li>Щедро посыпьте пармезаном и верните в духовку на 2–3 минуты до расплавления. Посыпьте петрушкой.</li></ol><p><em>Подавайте горячим как гарнир или как закуску с соусом для макания.</em></p>', CURRENT_TIMESTAMP),
  ('a2c04941-46c8-5d65-8a44-ddf9a15fa324', 'f201f014-1d08-50f3-880d-f2302a7c4a79', 'en', 'Crispy smashed potatoes with parmesan', 'Small potatoes boiled, smashed and roasted until crisp and golden with garlic salt and a melted parmesan crust.', '<ol><li>Bring salted water to a boil, add the whole small potatoes and cook at a low boil for 25–30 minutes until tender.</li><li>Preheat the oven to 450 °F (230 °C). Drain the potatoes, place on an oiled rimmed baking sheet and let dry for 5 minutes. Smash each one with a masher or the bottom of a glass to about ½ in (1.5 cm) thick.</li><li>Drizzle with half of the olive oil, sprinkle with garlic salt and pepper and bake for 15 minutes until starting to turn golden.</li><li>Flip the potatoes, drizzle with the remaining oil, season again and bake another 12–15 minutes until crisp with golden edges.</li><li>Sprinkle generously with parmesan and return to the oven for 2–3 minutes until melted. Garnish with parsley.</li></ol><p><em>Serve warm as a side or as a finger food with a dipping sauce.</em></p>', CURRENT_TIMESTAMP),
  ('27098b2c-cd8e-5d07-8a6b-553bc8753891', '412423c8-3d31-5f88-b84c-994c4ee80c09', 'ru', 'Шакшука с колбасками', 'Яйца, запечённые в густом томатном соусе с луком, чесноком и колбасным фаршем на одной сковороде.', '<ol><li>В большой сковороде на среднем-сильном огне обжарьте колбасный фарш с луком, разбивая мясо на кусочки.</li><li>Добавьте чеснок и готовьте ещё минуту. Убавьте огонь, влейте сок из банки с помидорами, добавьте мелко нарубленные помидоры, соль, перец и итальянские травы.</li><li>Томите без крышки 10 минут, иногда помешивая.</li><li>Сделайте в соусе ямки и аккуратно разбейте в них яйца. Накройте крышкой и готовьте на слабом огне 4–6 минут до желаемой готовности яиц.</li><li>Посыпьте рубленой зеленью и подавайте.</li></ol><p><em>Посыпьте зеленью и подавайте со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('d317eac9-e4d5-596a-a0fa-90f912f5b1e7', '412423c8-3d31-5f88-b84c-994c4ee80c09', 'en', 'Sausage shakshuka', 'Eggs poached in a thick tomato sauce with onion, garlic and crumbled sausage, all in one skillet.', '<ol><li>In a large skillet over medium-high heat cook the sausage with the onion, breaking the meat up as it browns.</li><li>Add the garlic and cook one more minute. Lower the heat, add the juices from the can, the finely chopped tomatoes, salt, pepper and Italian seasoning.</li><li>Simmer uncovered for 10 minutes, stirring as needed.</li><li>Make wells in the sauce and gently crack in the eggs. Cover and cook on low heat 4–6 minutes until the eggs are done to your liking.</li><li>Sprinkle with chopped herbs and serve.</li></ol><p><em>Sprinkle with fresh herbs and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('b50ecb44-6d96-5321-954c-576fd0d5fd75', 'bd4d47fb-c355-58f2-84b2-94e1efcb16ce', 'ru', 'Тилапия в пряной обжарке', 'Нежное филе тилапии в смеси паприки, чеснока и трав, обжаренное на сковороде за 15 минут. Быстрый ужин с минимумом углеводов.', '<ol><li>В небольшой миске смешайте все специи: паприку, чесночный и луковый порошок, соль, перец, чили и итальянские травы.</li><li>Обсушите филе бумажным полотенцем и натрите смесью специй с обеих сторон.</li><li>Разогрейте масло в большой сковороде на среднем-сильном огне и жарьте рыбу по 2–4 минуты с каждой стороны, пока она не станет легко расслаиваться.</li></ol><p><em>Подайте с лимоном, рисом или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('decb3f0c-7493-57e3-b18e-4885c7848cc6', 'bd4d47fb-c355-58f2-84b2-94e1efcb16ce', 'en', 'Blackened tilapia', 'Tender tilapia fillets coated in a paprika, garlic and herb spice blend and pan-seared in under 15 minutes.', '<ol><li>In a small bowl mix all the spices: paprika, garlic and onion powder, salt, pepper, chili and Italian seasoning.</li><li>Pat the fillets dry and coat both sides with the spice mix.</li><li>Heat the oil in a large skillet over medium-high heat and cook the fillets 2–4 minutes per side until they flake easily.</li></ol><p><em>Serve with lemon, rice or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('af505a92-2055-5956-a047-99cca0669031', '0b2bab15-dfb9-5c94-8f28-30c8fc8ade98', 'ru', 'Свиные отбивные в чесночном масле', 'Отбитые свиные отбивные без кости, обжаренные до золотистой корочки и запечённые с чесночным сливочным маслом.', '<ol><li>В небольшой миске смешайте соль, перец и паприку.</li><li>Отбейте каждую отбивную молотком до тонкого ровного слоя и посыпьте смесью специй.</li><li>Разогрейте 1 ст. л. сливочного масла на среднем огне в жаропрочной сковороде, добавьте растительное масло и обжаривайте отбивные по 3–4 минуты с каждой стороны до золотистого цвета.</li><li>Смешайте мягкое сливочное масло с солью, чесноком и зеленью. Положите на каждую отбивную, накройте крышкой.</li><li>Запекайте в духовке при 170 °C 10–15 минут (зависит от толщины). Перед подачей полейте отбивные маслом из сковороды.</li></ol><p><em>Подавайте с картофельным пюре или тушёными овощами, полив маслом из сковороды.</em></p>', CURRENT_TIMESTAMP),
  ('555ac9ed-0e53-5d8f-ad33-d6b3d6a3dc96', '0b2bab15-dfb9-5c94-8f28-30c8fc8ade98', 'en', 'Garlic butter pork chops', 'Boneless pork chops pounded thin, seared until golden and baked with garlic herb butter.', '<ol><li>Mix the salt, pepper and paprika in a small bowl.</li><li>Pound each pork chop to a thin, even thickness and rub with the spice mix.</li><li>Melt 1 tbsp butter in an oven-safe skillet over medium heat, add the oil and sear the chops 3–4 minutes per side until golden.</li><li>Mix the softened butter with the salt, garlic and herbs. Put some on each chop and cover with a lid.</li><li>Bake at 340 °F (170 °C) for 10–15 minutes depending on thickness. Spoon the pan butter over the chops before serving.</li></ol><p><em>Serve with mashed potatoes or roasted vegetables, spooning the pan butter over the top.</em></p>', CURRENT_TIMESTAMP),
  ('dd0dc5f3-1aeb-5012-b150-e35d24fc2a4d', '8b47b505-77c3-5682-bb98-934a378c5626', 'ru', 'Салат из свежих помидоров с луком и зеленью', 'Быстрый летний салат из нарезанных помидоров, красного лука и свежей зелени с лёгкой заправкой из масла, уксуса и чеснока.', '<ol><li>Нарежьте помидоры и красный лук и сложите в салатницу.</li><li>В небольшой миске смешайте масло, уксус, чеснок, соль и перец.</li><li>Добавьте рубленую зелень, полейте заправкой, перемешайте и подавайте.</li></ol><p><em>Хорош к шашлыку, жареной рыбе и картофелю.</em></p>', CURRENT_TIMESTAMP),
  ('d7ea014f-9790-5077-b0ef-c2ece01e7253', '8b47b505-77c3-5682-bb98-934a378c5626', 'en', 'Fresh tomato and onion salad', 'A quick summer salad of sliced tomatoes, red onion and fresh herbs in a light oil, vinegar and garlic dressing.', '<ol><li>Slice the tomatoes and onion and add to a salad bowl.</li><li>In a small bowl combine the oil, vinegar, garlic, salt and pepper.</li><li>Add the chopped herbs, toss with the dressing and serve.</li></ol><p><em>A great side for grilled meat, fish and potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('675831c7-a627-51fc-8637-25388c3e897b', 'f096bb0f-113d-589f-877f-cc886bd6d437', 'ru', 'Треска на сковороде-гриль с лимонно-базиликовым соусом', 'Филе трески в смеси орегано, кориандра, зиры и сумаха, обжаренное на сковороде и политое лимонно-базиликовым соусом.', '<ol><li>В небольшой миске смешайте орегано, кориандр, зиру, чесночный порошок и сумах.</li><li>Обсушите треску, посолите и поперчите с обеих сторон и натрите смесью специй.</li><li>Для соуса смешайте в небольшой миске оливковое масло, лимонный сок, чеснок, рубленый базилик, соль и перец.</li><li>Смажьте сковороду маслом и разогрейте до лёгкого шипения масла, не доводя до дыма. Выложите рыбу и жарьте около 3 минут без перемешивания, до золотистой корочки.</li><li>Переверните рыбу рыбной лопаткой и жарьте ещё 3 минуты, пока она не станет непрозрачной и не начнёт легко расслаиваться. Подавайте, полив лимонным соусом.</li></ol><p><em>Подайте с овощным салатом или заверните в лепёшку с цацики, как гирос.</em></p>', CURRENT_TIMESTAMP),
  ('6ca3e906-a151-5649-b98d-029f7b36b0c6', 'f096bb0f-113d-589f-877f-cc886bd6d437', 'en', 'Pan-grilled cod with lemon basil sauce', 'Cod fillets rubbed with oregano, coriander, cumin and sumac, pan-grilled and served with a bright lemon basil sauce.', '<ol><li>In a small bowl mix the oregano, coriander, cumin, garlic powder and sumac.</li><li>Pat the cod dry, season both sides with salt and pepper and rub with the spice mix.</li><li>For the sauce whisk together the olive oil, lemon juice, garlic, chopped basil, salt and pepper.</li><li>Coat a large skillet with olive oil and warm over medium-high until shimmering but not smoking. Add the fish and cook about 3 minutes undisturbed until golden underneath.</li><li>Flip with a fish spatula and cook another 3 minutes until opaque and flaking easily. Serve with the lemon basil sauce drizzled on top.</li></ol><p><em>Serve with a vegetable salad or wrap in warm pita with tzatziki, gyro-style.</em></p>', CURRENT_TIMESTAMP),
  ('2ffc6d94-0934-59da-9d95-e616471f64c0', '2859bbc0-c43b-53d4-b560-77565691a3cb', 'ru', 'Треска, запечённая с луком и морковью', 'Обжаренные в муке кусочки трески, запечённые под слоем карамелизованного лука и моркови с кетчупом. Рыба получается сочной и мягкой.', '<ol><li>Щедро посолите и поперчите филе трески, обваляйте в муке. Обжарьте с каждой стороны в 4 ст. л. масла до румяности, отложите (рыба будет готова не до конца). Сковороду протрите.</li><li>В той же сковороде на среднем огне обжарьте лук и морковь соломкой в оставшихся 4 ст. л. масла до мягкости и карамельного цвета. Добавьте кетчуп и прогрейте.</li><li>Разогрейте духовку до 190 °C. Половину овощей выложите на дно формы, сверху положите рыбу и накройте остальными овощами.</li><li>Залейте кипятком, накройте фольгой или крышкой и запекайте 15 минут.</li></ol><p><em>Подайте с картофельным пюре или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('bfbcd93f-06ba-5b16-87f5-424c3755821a', '2859bbc0-c43b-53d4-b560-77565691a3cb', 'en', 'Baked cod with onion and carrots', 'Floured cod fillets seared and baked under caramelised onions and carrots in a light ketchup sauce. Juicy and tender.', '<ol><li>Season the cod generously with salt and pepper and dredge in flour. Sear each side in 4 tbsp of oil until nicely browned and set aside partially cooked. Wipe the skillet clean.</li><li>In the same skillet over medium heat, sauté the sliced onion and julienned carrots in the remaining 4 tbsp of oil until soft and caramelised. Stir in the ketchup and heat through.</li><li>Preheat the oven to 375 °F (190 °C). Layer half the vegetables in a baking dish, set the fish on top and cover with the remaining vegetables.</li><li>Pour boiling water over the top, cover and bake for 15 minutes.</li></ol><p><em>Serve with mashed potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('97eb2929-e935-5079-82ec-ca2d0e81cb28', '7da600a8-418d-53e0-8ed3-1e5671ba4691', 'ru', 'Салат из капусты с помидорами и кинзой', 'Хрустящая белокочанная капуста с помидорами, зелёным луком и кинзой под простой заправкой из масла и уксуса.', '<ol><li>Разрежьте кочан пополам и тонко нашинкуйте ножом или на тёрке-слайсере. Переложите в большую миску.</li><li>Нарежьте помидоры кубиками, зелёный лук кольцами и измельчите кинзу, добавьте к капусте.</li><li>Соедините масло, уксус и соль, полейте салат и перемешайте. Подавайте.</li></ol><p><em>Хорошо подходит к мясу, картофелю и жареной рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('d7c2d3db-fb97-5901-8670-e829a7d70e0b', '7da600a8-418d-53e0-8ed3-1e5671ba4691', 'en', 'Cabbage and tomato salad with oil-vinegar dressing', 'Crunchy white cabbage with tomatoes, green onions and cilantro in a simple oil and vinegar dressing.', '<ol><li>Halve the head of cabbage and slice it thinly with a knife or a mandoline. Put it in a large bowl.</li><li>Dice the tomatoes, slice the green onions and chop the cilantro, then add them to the cabbage.</li><li>Whisk the oil, vinegar and salt, pour over the salad, toss to coat and serve.</li></ol><p><em>Goes well with meat, potatoes and fried fish.</em></p>', CURRENT_TIMESTAMP)
ON CONFLICT ("foodId", "language") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "content" = EXCLUDED."content", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "food_translations" ("id", "foodId", "language", "name", "description", "content", "updatedAt") VALUES
  ('69d52638-2dc8-5b21-abf6-998b5889a48c', 'a1976974-646c-5917-b884-c56c3975bc17', 'ru', 'Картофельное пюре с топлёным сливочным маслом', 'Воздушное сливочное картофельное пюре со сливками и ореховым ароматом подрумяненного масла.', '<ol><li>Очистите картофель, нарежьте кубиками по 2,5 см и держите в холодной воде, чтобы не темнел.</li><li>Выложите картофель в большую кастрюлю, добавьте 1 ст. л. соли и 2 л воды. Доведите до кипения и варите под крышкой на среднем огне около 15 минут до мягкости.</li><li>Слейте воду, переложите картофель в миску миксера и добавьте половину масла. Дайте паре минут постоять, чтобы масло растаяло.</li><li>Взбейте на малой скорости 15 секунд, затем понемногу вливайте сливки, добавьте соль и белый перец. Взбивайте около 5 минут до воздушной консистенции. Можно размять толкушкой.</li><li>Растопите оставшееся масло на среднем огне и помешивайте около 8 минут до золотисто-коричневого цвета с ореховым запахом. Следите, оно быстро подгорает. Полейте пюре перед подачей.</li></ol><p><em>Подайте к котлетам, запечённой птице или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('9b0f3866-69b0-5a39-b164-22d06fdd43e7', 'a1976974-646c-5917-b884-c56c3975bc17', 'en', 'Brown butter mashed potatoes', 'Fluffy, creamy mashed potatoes made with half-and-half and finished with nutty browned butter.', '<ol><li>Peel the potatoes, cut into even 1-inch (2.5 cm) chunks and keep in cold water so they do not darken.</li><li>Put the potatoes in a large pot with 1 tbsp salt and 2 quarts of water. Bring to a boil and cook covered over medium heat about 15 minutes until tender.</li><li>Drain, transfer the potatoes to the bowl of a stand mixer and add half of the butter. Let it steam for a couple of minutes so the butter melts.</li><li>Mix on low for 15 seconds, then gradually add the half-and-half with the salt and white pepper. Beat about 5 minutes until airy. A potato masher works too.</li><li>Melt the remaining butter over medium heat and keep stirring about 8 minutes until medium brown and nutty with brown flecks. Watch closely, it burns fast. Pour over the potatoes before serving.</li></ol><p><em>Serve with meatballs, roast poultry or fish.</em></p>', CURRENT_TIMESTAMP),
  ('c2f27346-3125-5efa-8bc3-5d8b0a053aed', 'b3edc682-d72d-5c94-8b3b-f352eb58b6e8', 'ru', 'Быстрый томатный суп-пюре со сливками', 'Нежный томатный суп из консервированных помидоров с чесноком, базиликом и сливками. Готовится в одной кастрюле за 20 минут.', '<ol><li>В кастрюле обжарьте чеснок на оливковом масле около минуты до аромата. Добавьте помидоры вместе с соком и слегка разомните.</li><li>Влейте бульон, добавьте соль, перец и сахар, доведите до кипения и варите на слабом огне 15 минут.</li><li>Пробейте суп погружным блендером до нужной консистенции. Добавьте базилик и сливки, перемешайте.</li><li>Разлейте по тарелкам, посыпьте пармезаном и подавайте.</li></ol><p><em>Посыпьте пармезаном и подайте с гренками или сырным сэндвичем.</em></p>', CURRENT_TIMESTAMP),
  ('ce5a0a97-07a3-5ea8-8eed-681e3beaf2c9', 'b3edc682-d72d-5c94-8b3b-f352eb58b6e8', 'en', 'Quick creamy tomato soup', 'A smooth tomato soup from canned tomatoes with garlic, basil and cream, made in one pot in about 20 minutes.', '<ol><li>In a pot, sauté the garlic in olive oil for about a minute until fragrant. Add the tomatoes with their juice and break them up slightly.</li><li>Pour in the stock, add the salt, pepper and sugar, bring to a boil and simmer for 15 minutes.</li><li>Blend the soup with an immersion blender to the desired texture. Stir in the basil and cream.</li><li>Ladle into bowls, garnish with Parmesan and serve.</li></ol><p><em>Top with Parmesan and serve with croutons or a grilled cheese sandwich.</em></p>', CURRENT_TIMESTAMP),
  ('84894c08-3e90-515c-b816-3c1f2389ba1c', 'dbc20de9-290a-5bfa-bc92-26d813eafdd9', 'ru', 'Скумбрия, маринованная кусочками', 'Нежная холодная рыба в солёно-сладком уксусном рассоле с лавровым листом и перцем, выдержанная 12 часов и залитая маслом. Классическая славянская закуска.', '<ol><li>Почистите рыбу от чешуи, разрежьте брюшко, удалите голову и внутренности. Промойте и оставьте в воде на 1 час.</li><li>Смешайте воду, уксус, соль, сахар, перец горошком и лавровый лист, доведите до кипения, помешивая, и полностью остудите.</li><li>Нарежьте рыбу кусками по 2,5 см, хвост выбросьте, ополосните и держите в холодной воде. Обсушите бумажным полотенцем.</li><li>Положите рыбу в ХОЛОДНЫЙ рассол, придавите тарелкой, чтобы она была полностью покрыта, накройте и уберите в холодильник на 12 часов.</li><li>Выньте рыбу из рассола, уложите в банку и залейте маслом до покрытия. Храните в холодильнике до двух недель.</li></ol><p><em>Подайте с отварным картофелем, чёрным хлебом и луком.</em></p>', CURRENT_TIMESTAMP),
  ('5f0cae1d-1adf-566b-b394-95edab29b835', 'dbc20de9-290a-5bfa-bc92-26d813eafdd9', 'en', 'Marinated mackerel pieces', 'Tender cold fish marinated for 12 hours in a salty-sweet vinegar brine with bay leaf and pepper, then kept under oil. A classic Slavic appetizer.', '<ol><li>Scale the fish, slit the belly, discard the head and entrails, rinse and soak in cold water for 1 hour.</li><li>Combine the water, vinegar, salt, sugar, peppercorns and bay leaves, bring to a boil whisking, and cool completely.</li><li>Cut the fish into 1-inch (2.5 cm) pieces, discarding the tail, rinse and keep in cold water until needed. Pat dry.</li><li>Put the fish in the COLD marinade, weigh it down with a plate so it stays submerged, cover and refrigerate for 12 hours.</li><li>Lift the fish from the marinade, pack it into a jar and cover with oil. Keep refrigerated for up to two weeks.</li></ol><p><em>Serve with boiled potatoes, rye bread and onions.</em></p>', CURRENT_TIMESTAMP),
  ('241da4ce-2c2d-57e5-bbd6-16d074f31b78', '9870f9a8-b235-5d24-894c-b9f6d9bee664', 'ru', 'Жареный рис с яйцом и горошком', 'Вчерашний рис, обжаренный на сильном огне с луком, яйцами, соевым соусом и горошком. Подходит как гарнир или основное блюдо с курицей или креветками.', '<ol><li>Разогрейте масло в большом воке или сковороде на сильном огне и обжарьте лук 1 минуту.</li><li>Добавьте охлаждённый варёный рис, яйца и горошек и перемешайте.</li><li>Влейте соевый соус, посыпьте сахаром и жарьте, помешивая, 4–5 минут до карамельного оттенка. Подавайте горячим.</li></ol><p><em>Добавьте курицу или креветки, чтобы получилось полноценное основное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('88734543-ceef-5aee-adf7-3bf97e44c32f', '9870f9a8-b235-5d24-894c-b9f6d9bee664', 'en', 'Egg fried rice with peas', 'Day-old rice stir-fried over high heat with onion, eggs, soy sauce and peas. Works as a side or, with chicken or shrimp, a main dish.', '<ol><li>Heat the oil in a large wok or skillet over high heat and fry the onion for 1 minute.</li><li>Add the chilled cooked rice, eggs and peas and stir together.</li><li>Pour in the soy sauce, sprinkle with sugar and stir-fry for 4–5 minutes until caramelised. Serve hot.</li></ol><p><em>Stir in chicken or shrimp to make it a full meal.</em></p>', CURRENT_TIMESTAMP),
  ('3625c2ad-e0c2-5dbc-b43e-755b75abb0bc', '422de4cd-5aa1-5f0f-b377-bd7a0fbe39ea', 'ru', 'Запечённый картофель с мясной начинкой и пюре', 'Крупные картофелины, начинённые мясным фаршем с овощами в густом соусе и покрытые картофельным пюре, запечённые до румяных гребешков.', '<ol><li>Разогрейте духовку до 180 °C. Проколите вымытый картофель вилкой около 6 раз и запекайте в микроволновке 5 минут, переверните и ещё 5 минут. Проверьте готовность ножом.</li><li>Срежьте верхушки и ложкой выньте мякоть, оставив стенки около 5 мм.</li><li>Разомните мякоть толкушкой с молоком, маслом и солью до гладкости. Можно выложить в кондитерский мешок с насадкой «звезда».</li><li>В большой сковороде разогрейте масло, 2 минуты пассеруйте лук с чесноком. Добавьте фарш на сильном огне и обжарьте около 3 минут, разбивая комки.</li><li>Посыпьте мукой и перемешайте, добавьте овощи, бульон, воду, соль, травы и перец. Доведите до кипения и помешивайте около 2 минут, пока соус не загустеет.</li><li>Наполните картофелины начинкой с горкой, уплотните и сверху выложите пюре. Запекайте 15–20 минут до румяных гребешков.</li></ol><p><em>Подайте сразу, остатки пюре положите рядом.</em></p>', CURRENT_TIMESTAMP),
  ('935693bb-2f08-5bac-9be6-42cb572be3bb', '422de4cd-5aa1-5f0f-b377-bd7a0fbe39ea', 'en', 'Shepherd''s pie potato skins', 'Large baked potatoes filled with a savoury mince and vegetable gravy, topped with the mashed potato and baked until browned.', '<ol><li>Preheat the oven to 350 °F (180 °C). Prick the scrubbed potatoes about 6 times each with a fork and microwave on high for 5 minutes, turn and microwave 5 minutes more. Check doneness with a knife.</li><li>Cut off the tops and scoop out the flesh with a spoon, leaving walls about 0.5 cm thick.</li><li>Mash the scooped potato with the milk, butter and salt until smooth. You can pipe it with a large star tip.</li><li>Heat the oil in a large pan and sauté the onion and garlic for 2 minutes. Turn the heat to high, add the mince and brown it for about 3 minutes, breaking it up.</li><li>Sprinkle over the flour and stir, then add the vegetables, stock, water, salt, herbs and pepper. Bring to a simmer and stir about 2 minutes until the sauce is thick and glossy.</li><li>Fill each potato with a heaped portion of filling, press lightly, and top with the mash. Bake for 15–20 minutes until the ridges brown.</li></ol><p><em>Serve right away with any leftover mash on the side.</em></p>', CURRENT_TIMESTAMP),
  ('5759b383-73d2-56f0-aee6-553bdb5f5375', 'd6d95aab-608b-5758-94f7-41b5bfb0bca0', 'ru', 'Салат из нута с яйцами и свежей зеленью', 'Сытный салат из нута, сельдерея, огурца, красной капусты, петрушки и мяты с варёными яйцами и лимонной заправкой с сумахом.', '<ol><li>Сварите яйца вкрутую (около 10 минут), остудите, очистите и нарежьте кружочками.</li><li>Для заправки смешайте горчицу, цедру и сок лимона, оливковое масло, чеснок, сумах, кориандр, кайенский перец, соль и перец.</li><li>В большой миске смешайте нут, сельдерей, огурец, зелёный лук, красную капусту, халапеньо, петрушку и мяту.</li><li>Взбейте заправку, полейте салат и перемешайте. Осторожно добавьте яйца, попробуйте и откорректируйте соль и сумах. Дайте постоять несколько минут.</li></ol><p><em>Подайте с лавашом или как начинку для сэндвичей.</em></p>', CURRENT_TIMESTAMP),
  ('28044afe-7589-5ed1-ad5a-9d2569eb767a', 'd6d95aab-608b-5758-94f7-41b5bfb0bca0', 'en', 'Mediterranean chickpea egg salad', 'A filling salad of chickpeas, celery, cucumber, red cabbage, parsley and mint with hard-boiled eggs and a lemony sumac dressing.', '<ol><li>Hard-boil the eggs (about 10 minutes), cool, peel and slice them.</li><li>For the dressing, mix the mustard, lemon zest and juice, olive oil, garlic, sumac, coriander, cayenne, salt and pepper.</li><li>In a large bowl, combine the chickpeas, celery, cucumber, green onions, red cabbage, jalapeños, parsley and mint.</li><li>Whisk the dressing, pour it over the salad and mix. Gently fold in the eggs, taste, adjust the seasoning and sumac, and let sit a few minutes.</li></ol><p><em>Serve with flatbread or use as a sandwich filling.</em></p>', CURRENT_TIMESTAMP),
  ('1503af2d-0c53-5252-9d91-66dcf2669b7d', '7c6f325f-d8fd-564a-9064-9ff3dde0bbc2', 'ru', 'Паста со шпинатом и артишоками в сливочном соусе', 'Пенне в соусе из сливочного сыра, сметаны и пармезана со шпинатом, артишоками и чесноком. Ужин за полчаса.', '<ol><li>Сварите пасту в подсоленной воде до нужной мягкости. Слейте воду, оставив около стакана отвара.</li><li>В большой кастрюле растопите 2 ст. л. масла, добавьте шпинат и мешайте около минуты, пока он не уменьшится. Переложите в дуршлаг, чтобы стекла жидкость.</li><li>В ту же кастрюлю положите оставшиеся 4 ст. л. масла, кусочки сливочного сыра, сметану и пармезан. Помешивайте, пока всё не растопится и не начнёт пузыриться.</li><li>Добавьте хорошо отжатые артишоки и прогревайте 1–2 минуты, затем шпинат, чеснок и халапеньо. Нагрейте и смешайте с пастой, при желании влейте отвар для нежной консистенции.</li></ol><p><em>При подаче добавьте немного отвара от пасты, чтобы соус был нежнее.</em></p>', CURRENT_TIMESTAMP),
  ('12f38a51-fdc7-5248-b673-43fcce1e9cfa', '7c6f325f-d8fd-564a-9064-9ff3dde0bbc2', 'en', 'Spinach and artichoke pasta', 'Penne in a creamy cream cheese, sour cream and Parmesan sauce with spinach, artichokes and garlic. A 30-minute dinner.', '<ol><li>Cook the pasta in salted water to your liking. Drain, reserving about 1 cup of the pasta water.</li><li>Melt 2 tbsp of butter in a large pot, add the spinach and stir about a minute until it wilts. Transfer to a colander to drain.</li><li>In the same pot, add the remaining 4 tbsp of butter with the cream cheese pieces, sour cream and Parmesan and stir until melted and bubbling.</li><li>Stir in the well-drained artichokes for 1–2 minutes, then the spinach, garlic and jalapeños. Heat through, toss with the pasta and add the pasta water if you like a looser sauce.</li></ol><p><em>Add a splash of pasta water to keep the sauce silky when reheating.</em></p>', CURRENT_TIMESTAMP),
  ('86acdbfc-db98-5372-853d-8ece6ff43ab7', '7c41599d-93e8-5b7a-b1c1-d7ac80401d23', 'ru', 'Тайское красное карри с курицей', 'Куриные бёдра в соусе из красной карри-пасты и кокосового молока с тыквой и стручковой фасолью. Подаётся с жасминовым рисом.', '<ol><li>Разогрейте масло в глубокой сковороде на среднем-сильном огне. Добавьте пасту карри, чеснок, имбирь и лемонграсс и обжаривайте около 2 минут, пока масса не подсохнет.</li><li>Влейте куриный бульон, размешайте пасту и на сильном огне уварите жидкость вдвое, примерно 3 минуты.</li><li>Добавьте кокосовое молоко, листья каффир-лайма, сахар и рыбный соус. Выложите ломтики курицы, доведите до кипения и варите на среднем огне 8–10 минут, пока курица не приготовится и соус не загустеет.</li><li>Попробуйте и при необходимости добавьте рыбный соус или сахар. Положите тыкву и фасоль и готовьте 3 минуты до мягкости тыквы.</li><li>Снимите с огня, добавьте листья базилика и подавайте с рисом, красным чили и кинзой.</li></ol><p><em>Посыпьте тайским базиликом и кинзой и подайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('12d5a49f-3a05-5154-8bc7-70a1dab3d35d', '7c41599d-93e8-5b7a-b1c1-d7ac80401d23', 'en', 'Thai red curry with chicken', 'Chicken thighs simmered in red curry paste and coconut milk with pumpkin and green beans, served over jasmine rice.', '<ol><li>Heat the oil in a large skillet over medium-high heat. Add the curry paste, garlic, ginger and lemongrass and cook about 2 minutes until the paste dries out.</li><li>Pour in the chicken broth, stir to dissolve the paste and boil rapidly for about 3 minutes until reduced by half.</li><li>Add the coconut milk, lime leaves, sugar and fish sauce, then the sliced chicken. Bring to a simmer and cook on medium for 8–10 minutes until the chicken is cooked and the sauce has thickened.</li><li>Taste and add more fish sauce or sugar if needed. Add the pumpkin and green beans and cook 3 minutes until the pumpkin is just tender.</li><li>Remove from the heat, stir in the basil and serve over rice with sliced red chilli and cilantro.</li></ol><p><em>Finish with Thai basil and cilantro and serve over steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('80e48b7d-081b-5b6e-ae85-5d6a734b3779', '4f4bd50e-2a1c-5dde-8646-620dc6e0cbd4', 'ru', 'Наси горенг с курицей и яйцом', 'Индонезийский жареный рис с курицей, чесноком, луком и сладким соевым соусом кецап манис, подаётся с яичницей и свежими овощами.', '<ol><li>Нагрейте в сковороде или воке 1 ст. л. масла на сильном огне. Обжарьте тонко нарезанную курицу с 1 ст. л. кецап манис до румяности и готовности, затем переложите на тарелку.</li><li>В ту же сковороду влейте остальное масло, 10 секунд обжарьте чили и чеснок, добавьте лук и готовьте минуту.</li><li>Верните курицу, добавьте холодный варёный рис и 2 ст. л. кецап манис. Жарьте, постоянно помешивая, около 2 минут, пока зёрна риса не начнут карамелизироваться.</li><li>Отдельно пожарьте яйца по вкусу. Подавайте рис с яйцом, зелёным луком, дольками помидора и огурца.</li></ol><p><em>Подайте с глазуньей, дольками помидора и огурца.</em></p>', CURRENT_TIMESTAMP),
  ('d270ff3a-1404-5d43-a1db-d6b7f7fe0b8a', '4f4bd50e-2a1c-5dde-8646-620dc6e0cbd4', 'en', 'Nasi goreng with chicken and fried egg', 'Indonesian fried rice with chicken, garlic, onion and sweet soy sauce, served with a fried egg and fresh vegetables.', '<ol><li>Heat 1 tbsp oil in a large skillet or wok over high heat. Cook the thinly sliced chicken with 1 tbsp kecap manis until caramelised and cooked through, then set aside.</li><li>Add the remaining oil to the pan, stir the chilli and garlic for 10 seconds, then add the onion and cook for 1 minute.</li><li>Return the chicken, add the cold cooked rice and 2 tbsp kecap manis. Stir-fry constantly for about 2 minutes until the rice grains begin to caramelise.</li><li>Fry the eggs separately to taste. Serve the rice topped with an egg, green onion and tomato and cucumber wedges.</li></ol><p><em>Serve with a sunny-side-up egg and tomato and cucumber wedges.</em></p>', CURRENT_TIMESTAMP),
  ('4ec90753-4ec9-51cc-af98-ee10c0c47822', 'f8631d56-510d-53a6-b813-689d0156427a', 'ru', 'Фаттуш (ливанский салат с хрустящей питой)', 'Салат из ромэна, огурцов, помидоров, редиса и мяты с хрустящими кусочками запечённой питы и лимонно-гранатовой заправкой с сумахом.', '<ol><li>Разогрейте духовку до 220 °C. Разделите питу на 2 тонких слоя и нарежьте квадратиками по 3 см.</li><li>Выложите на противень, сбрызните маслом, посыпьте солью и перемешайте. Запекайте 5 минут до хруста, затем остудите прямо на противне.</li><li>Заправка: встряхните в банке оливковое масло, лимонный сок, гранатовый соус, чеснок, сумах и соль.</li><li>Сложите в миску листья ромэна, огурцы, помидоры, красный лук, редис, мяту и петрушку, полейте половиной заправки и перемешайте.</li><li>Добавьте большую часть хрустящей питы, остальную заправку и перемешайте. Сверху положите оставшуюся питу и подавайте сразу.</li></ol><p><em>Заправляйте и добавляйте питу прямо перед подачей, чтобы она оставалась хрустящей.</em></p>', CURRENT_TIMESTAMP),
  ('2158559b-34e5-59d4-b333-a4c69b77fe76', 'f8631d56-510d-53a6-b813-689d0156427a', 'en', 'Lebanese fattoush salad', 'Romaine, cucumber, tomato, radish and mint tossed with crispy baked pita pieces in a tangy lemon dressing with pomegranate molasses and sumac.', '<ol><li>Preheat the oven to 425 °F (220 °C). Split the pita into 2 thin sheets and cut into 1.2 in (3 cm) squares.</li><li>Pile on a tray, drizzle with olive oil, sprinkle with salt and toss. Bake 5 minutes until crisp, then cool on the tray.</li><li>Dressing: shake the olive oil, lemon juice, pomegranate molasses, garlic, sumac and salt in a jar.</li><li>In a large bowl combine the romaine, cucumbers, tomatoes, red onion, radish, mint and parsley, add half the dressing and toss.</li><li>Add most of the pita chips and the remaining dressing and toss again. Top with the remaining pita and serve immediately.</li></ol><p><em>Dress and add the pita just before serving to keep it crisp.</em></p>', CURRENT_TIMESTAMP),
  ('91a42417-29fb-516d-b0f7-d1fd80a61140', '86d2ba9a-db80-5e2c-bc1c-1f99dbe37bdc', 'ru', 'Гороховый суп с копчёной рулькой', 'Густой гороховый суп, сваренный на копчёной свиной рульке с луком, морковью и сельдереем. Мясо отделяется от кости и возвращается в суп.', '<ol><li>Выложите горох в кастрюлю или чашу мультиварки, положите рульку, добавьте лук, морковь, сельдерей, чеснок, лавровый лист, соль и перец и залейте водой.</li><li>Варите под крышкой на плите на слабом огне около 2,5 часов, пока горох не разварится. В мультиварке на режиме тушения: 8–10 часов на низком режиме или 6 часов на высоком.</li><li>Достаньте рульку, снимите мясо с кости и разберите на волокна. Кость и жирную кожу выбросьте. Выньте лавровый лист.</li><li>Прогоните суп блендером 2–3 раза, чтобы он стал гуще, но не превратился в пюре. Верните мясо в суп, перемешайте, при необходимости досолите (ветчина уже солёная).</li><li>Подавайте горячим, посыпав рубленой петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте с хрустящим хлебом или сухариками.</em></p>', CURRENT_TIMESTAMP),
  ('39e2aa51-d954-503a-87bb-cc4252850c0d', '86d2ba9a-db80-5e2c-bc1c-1f99dbe37bdc', 'en', 'Pea and ham hock soup', 'Thick split pea soup simmered with a smoked ham hock, onion, carrot and celery; the shredded ham goes back into the soup.', '<ol><li>Put the split peas in a pot or slow cooker, add the ham hock, onion, carrot, celery, garlic, bay leaves, salt and pepper and pour in the water.</li><li>Simmer covered on the stove on low heat about 2½ hours until the peas are soft. In a slow cooker cook 8–10 hours on low or 6 hours on high.</li><li>Remove the ham hock, shred the meat and discard the bone and fatty skin. Take out the bay leaves.</li><li>Blitz the soup with a stick blender 2 or 3 times to thicken without making it completely smooth. Return the ham, stir and add salt if needed (the ham is already salty).</li><li>Serve hot, garnished with chopped parsley.</li></ol><p><em>Garnish with parsley and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('79c13e6f-bca8-53a5-b535-aa89152d8fc1', '5179d5ef-80d8-5c57-a1e6-8014ee2bb344', 'ru', 'Курица в кисло-сладком соусе, запечённая в духовке', 'Кусочки куриной грудки в крахмале и яйце, быстро обжаренные и затем запечённые в домашнем кисло-сладком соусе. Мясо получается сочным.', '<ol><li>Разогрейте духовку до 160 °C. Нарежьте куриное филе кусочками по 2,5 см, посолите и поперчите.</li><li>Обваляйте курицу в кукурузном крахмале (удобно в пакете). Взбейте яйца в неглубокой миске.</li><li>Сильно разогрейте масло в глубокой кастрюле с толстым дном. Окунайте кусочки в яйцо и обжаривайте по 30 секунд с каждой стороны только до золотистого цвета, не до готовности. Перекладывайте в форму 23×33 см, при необходимости подливайте масло.</li><li>Смешайте уксус, кетчуп, соевый соус, сахар и чесночную соль (соль и чесночный порошок). Полейте курицу и перемешайте.</li><li>Запекайте без крышки 1 час, дважды перемешав курицу, чтобы она пропиталась соусом. Подавайте горячей с рисом.</li></ol><p><em>Подайте с отварным рисом и брокколи.</em></p>', CURRENT_TIMESTAMP),
  ('fb3d5c5e-b5d9-5b6b-af8d-ada500f6cf9c', '5179d5ef-80d8-5c57-a1e6-8014ee2bb344', 'en', 'Baked sweet and sour chicken', 'Chicken breast pieces in cornstarch and egg, quickly browned and then baked in a homemade sweet and sour sauce until juicy.', '<ol><li>Preheat the oven to 325 °F (160 °C). Cut the chicken breasts into 1-inch pieces and season with salt and pepper.</li><li>Toss the chicken in the cornstarch (a zip bag works well). Whisk the eggs in a shallow dish.</li><li>Heat the oil very hot in a tall heavy pot. Dip the starched pieces in the egg and fry about 30 seconds per side just until golden, not cooked through. Move them to a 9×13 inch baking dish, adding more oil as needed.</li><li>Stir together the vinegar, ketchup, soy sauce, sugar and garlic salt. Pour over the chicken and toss to coat.</li><li>Bake uncovered for 1 hour, turning the chicken twice to coat in the sauce. Serve hot over rice.</li></ol><p><em>Serve over steamed rice with broccoli.</em></p>', CURRENT_TIMESTAMP),
  ('715182dc-5a93-5623-be80-5ada252251c3', 'e7cbba76-59b4-5c0a-a347-3ec0bc7737a3', 'ru', 'Салат из сырой цветной капусты с огурцом и сметаной', 'Свежий хрустящий салат из мелко нарубленной цветной капусты, огурца и зелёного лука со сметанно-йогуртовой заправкой.', '<ol><li>Мелко нарежьте цветную капусту и переложите в салатник.</li><li>Огурец разрежьте вдоль и тонко нарежьте полукружками, добавьте в миску. Мелко нарежьте зелёный лук или шнитт-лук и посыпьте сверху.</li><li>Смешайте сметану, йогурт, соль и перец (по желанию добавьте чеснок). Заправьте салат, попробуйте и досолите.</li></ol><p><em>Лучше есть в течение нескольких часов после заправки; украсьте укропом или петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('85e8f464-d503-5e0d-b8cb-6bed697f69f7', 'e7cbba76-59b4-5c0a-a347-3ec0bc7737a3', 'en', 'Raw cauliflower and cucumber salad with sour cream', 'A fresh, crunchy salad of finely chopped raw cauliflower, cucumber and green onions in a sour cream and yogurt dressing.', '<ol><li>Finely dice the cauliflower and put it in a salad bowl.</li><li>Halve the cucumber lengthwise and slice into thin half circles, then add to the bowl. Finely slice the chives or green onions and sprinkle on top.</li><li>Mix the sour cream, yogurt, salt and pepper (add garlic if you like). Dress the salad, taste and add more salt if needed.</li></ol><p><em>Best eaten within a few hours of dressing; garnish with dill or parsley.</em></p>', CURRENT_TIMESTAMP),
  ('67f35f5d-a76e-506d-9297-54de3aedca05', 'a4ce5f96-29bf-5663-8cba-1010c572b55d', 'ru', 'Овощной тиан с картофелем, кабачком и помидорами', 'Слои картофеля, кабачка и помидоров на луково-чесночной основе, запечённые с тимьяном, укропом и пармезаном.', '<ol><li>Разогрейте духовку до 190 °C. Нарежьте кабачки и помидоры кружками толщиной 6 мм, картофель очистите и нарежьте так же. Лук нарубите, чеснок очистите.</li><li>В сковороде на среднем огне разогрейте 2 ст. л. масла и 5 минут пассеруйте лук до мягкости и золотистого цвета. Добавьте чеснок через пресс на 2 минуты и переложите в форму.</li><li>Смешайте соль, перец, тимьян, укроп и 2 ст. л. масла. Полейте картофель и кабачок в миске и перемешайте.</li><li>Выложите овощи в форму рядами, чередуя картофель, помидоры и кабачок. Накройте фольгой и запекайте 35 минут.</li><li>Снимите фольгу, посыпьте пармезаном и запекайте ещё 30 минут до румяной корочки.</li></ol><p><em>Подайте как гарнир к мясу или рыбе, либо как лёгкий ужин.</em></p>', CURRENT_TIMESTAMP),
  ('ac758afa-79c4-5d73-afc8-7d2d7a39ec1e', 'a4ce5f96-29bf-5663-8cba-1010c572b55d', 'en', 'Vegetable tian with potatoes, zucchini and tomatoes', 'Layers of potato, zucchini and tomato over a soft onion and garlic base, baked with thyme, dill and Parmesan.', '<ol><li>Preheat the oven to 375 °F (190 °C). Slice the zucchini and tomatoes about ¼ inch (6 mm) thick, peel and slice the potatoes, chop the onion and peel the garlic.</li><li>Heat 2 tbsp of oil in a skillet over medium and cook the onion for 5 minutes until soft and lightly browned. Press in the garlic, stir for 2 minutes and move it all to a baking dish.</li><li>Mix the salt, pepper, thyme, dill and 2 tbsp of oil. Toss the potatoes and zucchini with the mixture in a large bowl.</li><li>Arrange the vegetables in the dish, alternating potatoes, tomatoes and zucchini. Cover with foil and bake for 35 minutes.</li><li>Remove the foil, sprinkle with Parmesan and bake 30 minutes more until golden.</li></ol><p><em>Serve as a side with meat or fish, or as a light supper.</em></p>', CURRENT_TIMESTAMP),
  ('2d0cb9ee-7c3b-5f46-bd19-288df127960d', '9614aae6-b71f-5e1d-9448-136738242f78', 'ru', 'Маринованный салат из капусты с морковью и клюквой', 'Хрустящая капуста с морковью, перцем и сушёной клюквой, замаринованная в сладко-кислой заливке с чесноком. Хранится в холодильнике несколько дней.', '<ol><li>Вскипятите воду и снимите с огня. Добавьте соль, сахар, уксус и масло, размешайте до растворения. В конце положите чеснок через пресс (в кипящую воду его не кладите, он посинеет).</li><li>Тонко нашинкуйте капусту, перец нарежьте полосками, морковь натрите. Смешайте овощи с клюквой в большой миске.</li><li>Переложите овощи в стеклянную банку и залейте заливкой (она может быть тёплой). Плотно утрамбуйте, чтобы капуста была под жидкостью.</li><li>Уберите в холодильник на 4–5 часов. Салат будет готов, а хранится до недели.</li></ol><p><em>Хорошо подходит к картофелю, рису и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('e380e2bd-e149-55da-972c-e5c542a10c2d', '9614aae6-b71f-5e1d-9448-136738242f78', 'en', 'Marinated cabbage, carrot and cranberry salad', 'Crisp cabbage with carrots, bell pepper and dried cranberries marinated in a sweet-sour garlic brine. Keeps well in the fridge for days.', '<ol><li>Boil the water and remove from the heat. Stir in the salt, sugar, vinegar and oil until dissolved. Add the pressed garlic last, off the heat, since garlic turns blue in boiling water.</li><li>Finely shred the cabbage, cut the pepper into thin strips and grate the carrots. Toss the vegetables with the cranberries in a large bowl.</li><li>Pack the vegetables into a glass jar and pour over the marinade (it can still be warm). Press down firmly so the cabbage is covered by liquid.</li><li>Refrigerate for 4–5 hours. The salad is then ready and keeps up to a week.</li></ol><p><em>Great with potatoes, rice and meat.</em></p>', CURRENT_TIMESTAMP),
  ('c60d1ab4-cbb3-5b3f-ae51-f7c152bfd609', '7ba1b968-b969-5a39-a02c-199c96deeb63', 'ru', 'Салат из крабовых палочек с огурцом и помидорами', 'Быстрый салат из измельчённых крабовых палочек, свежего огурца, помидоров и зелёного лука с чесночным майонезом.', '<ol><li>Нарежьте или разберите крабовые палочки на небольшие волокна, чтобы заправка лучше их покрыла.</li><li>Помидоры нарежьте небольшими кубиками и слейте лишний сок (можно удалить семена, чтобы салат не стал водянистым). Огурец нарежьте мелкими кубиками.</li><li>Смешайте в миске краба, помидоры, огурец и зелёный лук. Смешайте майонез с чесноком, заправьте салат по вкусу и уберите в холодильник до подачи.</li></ol><p><em>Подавайте охлаждённым, лучше сразу после приготовления.</em></p>', CURRENT_TIMESTAMP),
  ('d35f778a-e42a-5750-8ce6-0d26ccd443f1', '7ba1b968-b969-5a39-a02c-199c96deeb63', 'en', 'Crab stick salad with cucumber and tomato', 'A quick salad of shredded imitation crab sticks, fresh cucumber, tomatoes and green onions in a garlic mayonnaise dressing.', '<ol><li>Chop or shred the crab sticks into small pieces so the dressing coats them well.</li><li>Dice the tomatoes small and drain off excess juice (seeding them helps keep the salad from getting watery). Dice the cucumber small.</li><li>Combine the crab, tomatoes, cucumber and green onion in a large bowl. Mix the mayonnaise with the garlic, dress the salad to taste and refrigerate until serving.</li></ol><p><em>Serve chilled, ideally the same day.</em></p>', CURRENT_TIMESTAMP),
  ('c0bb9908-9c73-53cf-98e2-f45a5a2eb282', '69388b15-d717-5a58-8614-44ee477f56fa', 'ru', 'Свежий огуречный салат с укропом и чесноком', 'Простой летний салат из огурцов с чесноком, рубленым укропом, маслом и уксусом.', '<ol><li>Вымойте огурцы, разрежьте вдоль пополам, каждую половину ещё на 3–4 полоски, затем поперёк пополам. Переложите в миску.</li><li>Нарубите укроп, пропустите чеснок через пресс и добавьте к огурцам.</li><li>Добавьте масло, уксус, щепотку соли и перца, перемешайте. Подавайте сразу или уберите в холодильник (солить лучше перед подачей).</li></ol><p><em>Хорошо сочетается с картофелем, мясом и жареной рыбой.</em></p>', CURRENT_TIMESTAMP),
  ('283d79cb-79b6-5e11-8ea7-0b0755e1923f', '69388b15-d717-5a58-8614-44ee477f56fa', 'en', 'Fresh cucumber salad with dill and garlic', 'A simple summer salad of cucumbers with garlic, chopped dill, oil and vinegar.', '<ol><li>Wash the cucumbers, halve them lengthwise, cut each half into 3–4 strips, then cut the strips in half. Put them in a bowl.</li><li>Chop the dill, press the garlic and add both to the cucumbers.</li><li>Add the oil, vinegar and a pinch of salt and pepper and mix. Serve at once or refrigerate, salting just before serving.</li></ol><p><em>Pairs well with potatoes, meat and fried fish.</em></p>', CURRENT_TIMESTAMP),
  ('e3532836-4ba7-59d1-9deb-cc3488e870c3', 'e87de3ff-0e8d-5209-a1fe-bb56553f20ff', 'ru', 'Картофельная фриттата с зеленью и пряностями', 'Пышный омлет с обжаренным картофелем, укропом, петрушкой и мягкими восточными специями, доведённый до готовности в духовке.', '<ol><li>Поставьте решётку в середину духовки и разогрейте до 190 °C.</li><li>В жаропрочной сковороде диаметром 25 см разогрейте около 2 ст. л. оливкового масла до лёгкого шипения. Добавьте картофель кубиками, зелёный лук и чеснок, посолите и добавьте кориандр, чили, паприку и куркуму. Жарьте, часто помешивая, 5–10 минут до мягкости картофеля, следя, чтобы чеснок не подгорел.</li><li>Взбейте яйца с рубленой зеленью, щепоткой соли и, по желанию, разрыхлителем.</li><li>Влейте яичную смесь на картофель и 3–4 минуты подождите, пока края и дно схватятся.</li><li>Переставьте сковороду в духовку и выпекайте 8–10 минут, пока яйца полностью не загустеют и верх не перестанет быть жидким.</li></ol><p><em>Подавайте тёплой или комнатной температуры с салатом из огурцов и помидоров.</em></p>', CURRENT_TIMESTAMP),
  ('dd73c127-6a51-50e6-92f7-6555d912b829', 'e87de3ff-0e8d-5209-a1fe-bb56553f20ff', 'en', 'Potato frittata with fresh herbs and warm spices', 'Fluffy baked omelet with sautéed potatoes, dill, parsley and warm Middle Eastern spices.', '<ol><li>Place a rack in the middle of the oven and preheat to 375 °F (190 °C).</li><li>In a 10-inch oven-safe skillet heat about 2 tbsp olive oil until shimmering. Add the cubed potatoes, green onions and garlic, season with salt, coriander, chili, paprika and turmeric and cook, tossing often, 5–10 minutes until tender, making sure the garlic doesn''t burn.</li><li>Whisk the eggs with the chopped herbs, a good pinch of salt and, if you like, the baking powder.</li><li>Pour the egg mixture over the potatoes and let the edges and bottom set for 3–4 minutes.</li><li>Transfer the skillet to the oven and bake 8–10 minutes until the eggs are fully cooked and the top is no longer runny.</li></ol><p><em>Serve warm or at room temperature with a cucumber and tomato salad.</em></p>', CURRENT_TIMESTAMP),
  ('81b571dd-e5ca-50d9-9f5b-516cbb98f27c', '8872aa5e-6047-534a-800c-02326a49527f', 'ru', 'Густой чечевичный суп с овощами', 'Постный суп с чечевицей, морковью, сельдереем, картофелем, кабачком и томатами со специями и свежей петрушкой. Готовится в одной кастрюле.', '<ol><li>Промойте чечевицу, замочите на 10 минут и слейте воду.</li><li>В толстостенной кастрюле разогрейте 2 ст. л. масла и 4–5 минут обжаривайте лук, морковь, сельдерей и картофель.</li><li>Добавьте чеснок и кабачок и готовьте ещё 5 минут.</li><li>Всыпьте чечевицу, соль, перец, кориандр, зиру, куркуму, корицу и кайенский перец, перемешайте и влейте помидоры с водой.</li><li>Кипятите 5 минут, убавьте огонь, накройте крышкой и варите около 20 минут до мягкости овощей и чечевицы, при необходимости подливая воду.</li><li>Снимите с огня, добавьте петрушку и лимонный сок, разлейте по тарелкам и сбрызните оливковым маслом.</li></ol><p><em>Сбрызните оливковым маслом и подавайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('7f59d01f-88ab-5659-b97c-6bf8dbf4b94a', '8872aa5e-6047-534a-800c-02326a49527f', 'en', 'Hearty one-pot lentil and vegetable stew', 'Vegan stew of green lentils with carrot, celery, potato, zucchini and tomatoes, warmed with spices and finished with fresh parsley and lemon.', '<ol><li>Rinse the lentils, soak for about 10 minutes and drain well.</li><li>Heat 2 tbsp oil in a heavy pot and sauté the onion, carrot, celery and potato for 4–5 minutes, stirring.</li><li>Add the garlic and zucchini and cook 5 more minutes.</li><li>Add the lentils, salt, pepper, coriander, cumin, turmeric, cinnamon and cayenne, stir and pour in the tomatoes and water.</li><li>Boil for 5 minutes, reduce the heat, cover and simmer about 20 minutes until the vegetables and lentils are tender, adding water if needed.</li><li>Remove from the heat, stir in the parsley and lemon juice, ladle into bowls and drizzle with olive oil.</li></ol><p><em>Drizzle with olive oil and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('89b781fc-f4af-5589-bea1-5b3ad8363acc', '06a3b775-473f-5076-9f56-c0fef1804286', 'ru', 'Крем-суп из запечённой цветной капусты с укропом', 'Нежный суп из запечённой цветной капусты с луком, чесноком, зирой, паприкой и сумахом, на овощном бульоне и молоке. Готовится 75 минут, из них половина — запекание.', '<ol><li>Разогрейте духовку до 220 °C. Разрежьте кочаны пополам, разберите на соцветия, крупные нарежьте на меньшие части.</li><li>Выложите капусту на большой противень (или два), посолите, поперчите, щедро сбрызните оливковым маслом и перемешайте. Запекайте около 45 минут, перевернув на 25-й минуте, до мягкости и тёмно-золотистых краёв.</li><li>В большой кастрюле разогрейте 2 ст. л. масла, около 7 минут обжаривайте лук до прозрачности. Добавьте чеснок, зиру, паприку, сумах и куркуму и прогрейте минуту.</li><li>Положите ¾ запечённой капусты, перемешайте со специями, влейте бульон и стакан воды. Доведите до кипения и варите под неплотной крышкой 5–7 минут.</li><li>Снимите с огня и измельчите блендером до нужной консистенции (можно оставить немного кусочков).</li><li>Верните на средний огонь, влейте молоко, лимонный сок и добавьте оставшуюся капусту. Прогрейте, посолите по вкусу, добавьте укроп и подавайте.</li></ol><p><em>Подавайте горячим со свежим укропом и тостами.</em></p>', CURRENT_TIMESTAMP),
  ('b936db64-bd7a-505e-a87b-0e9a6e6ba81a', '06a3b775-473f-5076-9f56-c0fef1804286', 'en', 'Roasted cauliflower soup with dill', 'Creamy soup of oven-roasted cauliflower with onion, garlic, cumin, paprika and sumac in vegetable broth and milk.', '<ol><li>Preheat the oven to 425 °F (220 °C). Halve the cauliflower heads, cut off the florets and cut larger ones smaller so they are all similar in size.</li><li>Spread the cauliflower on a large sheet pan (or two), season with salt and pepper, drizzle generously with olive oil and toss. Roast about 45 minutes, turning at 25 minutes, until tender and deeply browned in places.</li><li>In a large pot heat 2 tbsp oil and cook the onion about 7 minutes until translucent. Add the garlic, cumin, paprika, sumac and turmeric and stir for 1 minute.</li><li>Add ¾ of the roasted cauliflower, coat with the spices, then add the broth and 1 cup water. Bring to a boil, then simmer partly covered for 5–7 minutes.</li><li>Remove from the heat and purée with an immersion blender to your preferred texture, leaving it a little chunky if you like.</li><li>Return to medium heat, stir in the milk, lemon juice and the reserved cauliflower, warm through, adjust the salt, add the dill and serve.</li></ol><p><em>Serve hot with fresh dill and toasted bread.</em></p>', CURRENT_TIMESTAMP),
  ('0c4df401-3a13-58c6-b7f3-611c6d7eefab', '8f82aea7-56f9-5e75-abd0-29541b0d90a3', 'ru', 'Куриные бёдра в чесночно-горчичном соусе в духовке', 'Куриные бёдра без кожи, запечённые с луком в соусе из дижонской горчицы, мёда, оливкового масла, чеснока и специй. Готовится за 30 минут.', '<ol><li>Разогрейте духовку до 220 °C. Достаньте курицу из холодильника, обсушите и посолите и поперчите с обеих сторон.</li><li>В большой миске смешайте дижонскую горчицу, мёд, оливковое масло, чеснок, кориандр, паприку, чёрный и кайенский перец и щепотку соли.</li><li>Обваляйте куриные бёдра в соусе по несколько штук, выложите на слегка смазанную маслом чугунную сковороду или противень, сверху вылейте оставшийся соус и добавьте нарезанный лук.</li><li>Запекайте 25–30 минут, пока внутри не будет 74 °C. Посыпьте свежей петрушкой и подавайте.</li></ol><p><em>Посыпьте петрушкой, подайте с рисом, картофелем или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('dffa5e06-40bf-5628-baaf-b48c138f9f9e', '8f82aea7-56f9-5e75-abd0-29541b0d90a3', 'en', 'Baked garlic Dijon chicken thighs', 'Boneless chicken thighs baked with onion in a Dijon, honey, olive oil, garlic and spice sauce, ready in 30 minutes.', '<ol><li>Preheat the oven to 425 °F (220 °C). Take the chicken out of the fridge, pat dry and season both sides with salt and pepper.</li><li>In a large bowl mix the Dijon, honey, olive oil, garlic, coriander, paprika, black pepper, cayenne and a pinch of salt.</li><li>Coat the chicken in the sauce a few pieces at a time, arrange in a lightly oiled cast iron skillet or on a baking sheet, scrape the remaining sauce over the top and add the onion.</li><li>Bake 25–30 minutes until the internal temperature reaches 165 °F (74 °C). Garnish with fresh parsley and serve.</li></ol><p><em>Garnish with parsley and serve with rice, potatoes or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('b366c725-83b4-5e3a-9603-8005b13f80c7', '3d546213-dfaf-5e29-a060-8a3f7a7a5c71', 'ru', 'Фриттата со шпинатом и фетой', 'Яичная запеканка со шпинатом, фетой, луком, петрушкой и мятой, вдохновлённая греческой спанакопитой. Без муки и теста.', '<ol><li>Разогрейте духовку до 190 °C.</li><li>В большой миске взбейте яйца с орегано, укропом, перцем, паприкой, разрыхлителем и щепоткой соли.</li><li>Добавьте отжатый шпинат, лук, петрушку, мяту, чеснок, фету и молоко и хорошо перемешайте.</li><li>В жаропрочной сковороде диаметром 30 см разогрейте оливковое масло на среднем-сильном огне и влейте яичную смесь. Покачайте сковороду, чтобы масса распределилась, и готовьте около 4 минут, пока не схватится низ.</li><li>Переставьте в духовку на 8 минут, пока верх не загустеет и перестанет дрожать. Дайте постоять несколько минут, нарежьте и подавайте.</li></ol><p><em>Нарежьте на порции и подайте с салатом из огурцов и помидоров.</em></p>', CURRENT_TIMESTAMP),
  ('fc2aedb5-7f4d-5d7a-9d30-9539458b9548', '3d546213-dfaf-5e29-a060-8a3f7a7a5c71', 'en', 'Spinach and feta frittata', 'A baked egg frittata with spinach, feta, onion, parsley and mint, inspired by Greek spanakopita and naturally gluten-free.', '<ol><li>Preheat the oven to 375 °F (190 °C).</li><li>In a large bowl whisk the eggs with the oregano, dill, pepper, paprika, baking powder and a pinch of salt.</li><li>Add the squeezed spinach, onion, parsley, mint, garlic, feta and milk and mix well.</li><li>In a 12-inch oven-safe skillet heat the olive oil over medium-high heat and pour in the egg mixture. Shake the pan gently to spread it and cook about 4 minutes until the bottom sets.</li><li>Transfer to the oven for about 8 minutes until the top is firm and no longer jiggles. Rest a few minutes, then slice and serve.</li></ol><p><em>Slice and serve with a cucumber and tomato salad.</em></p>', CURRENT_TIMESTAMP),
  ('9e29bd68-d568-51d5-971f-cee3c1ff2337', '5b2e2c8d-15a1-56ed-b03c-b9c543e2a6b5', 'ru', 'Курица, запечённая в йогуртовом маринаде', 'Куриные кусочки маринуются в йогурте с лимоном, чесноком и пряностями, затем запекаются до золотистой корочки. Мясо получается очень нежным.', '<ol><li>В большой миске с крышкой смешайте йогурт, лимонную цедру и сок, масло, чеснок, орегано, мяту, зиру, кориандр, паприку, мускатный орех, перец и щепотку соли.</li><li>Курицу, разделённую на части, обсушите и хорошо посолите, в том числе под кожей. Переложите в маринад, приподнимая кожу, чтобы маринад покрыл мясо. Накройте и уберите в холодильник на ночь (до 24 часов).</li><li>Разогрейте духовку до 220 °C. Смажьте маслом противень с бортами. Стряхните лишний маринад с кусочков и выложите их на противень, оставляя промежутки.</li><li>Запекайте 35–40 минут до золотистой корочки и 74 °C внутри грудки или бедра. Посыпьте петрушкой и подавайте.</li></ol><p><em>Посыпьте петрушкой, подайте с рисом, картофелем или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('d36c9dc0-b42d-5123-91ee-acf7ba75b491', '5b2e2c8d-15a1-56ed-b03c-b9c543e2a6b5', 'en', 'Yogurt-marinated roast chicken', 'Chicken pieces marinated overnight in spiced yogurt with lemon and garlic, then roasted until golden and very tender.', '<ol><li>In a large bowl with a lid whisk the yogurt, lemon zest and juice, olive oil, garlic, oregano, mint, cumin, coriander, paprika, nutmeg, pepper and a small pinch of salt.</li><li>Pat the chicken pieces dry and season well with salt, also under the skin. Add to the marinade, lifting the skin so the marinade coats the meat. Cover and refrigerate overnight, up to 24 hours.</li><li>Heat the oven to 425 °F (220 °C). Lightly oil a rimmed baking sheet. Shake off excess marinade and arrange the pieces on the pan, leaving space between them.</li><li>Roast 35–40 minutes until browned and cooked through (165 °F / 74 °C in the breast or thigh). Garnish with chopped parsley and serve.</li></ol><p><em>Garnish with parsley and serve with rice, potatoes or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('6d5f2698-2965-524c-9169-9261b36b683c', '0eb7af8d-7cc1-56ac-954d-ec8f13401018', 'ru', 'Домашние пельмени со свининой и курицей', 'Классические пельмени из тонкого яично-молочного теста с сочной начинкой из свиного и куриного фарша, лука, чеснока и укропа.', '<ol><li>Для теста смешайте молоко, соль, яйцо и воду, добавляя муку по стакану при включённом миксере с крюком (или замесите вручную), пока тесто не станет гладким и не перестанет липнуть к рукам.</li><li>Накройте тесто и оставьте отдохнуть 15–30 минут, чтобы оно стало эластичным.</li><li>Смешайте свиной и куриный фарш с тёртым луком, чесноком, солью, перцем, уксусом, водой и рубленым укропом. Накройте и уберите до лепки.</li><li>Разделите тесто на три части и тонко раскатайте. Лепите вручную: вырежьте кружки или квадраты, положите по чайной ложке фарша, сложите и плотно защипните края. Или используйте форму для пельменей: уложите пласт теста, заполните ячейки фаршем, накройте вторым пластом и прокатайте скалкой.</li><li>Вскипятите большую кастрюлю подсоленной воды. Опускайте пельмени порциями и варите 2–3 минуты после всплытия. Не переваривайте, иначе они развалятся.</li></ol><p><em>Подайте со сметаной, сливочным маслом, уксусом или горчицей; сырые пельмени можно заморозить.</em></p>', CURRENT_TIMESTAMP),
  ('08cf1c46-e043-508e-925d-d6a51435a2fb', '0eb7af8d-7cc1-56ac-954d-ec8f13401018', 'en', 'Homemade pork and chicken pelmeni', 'Classic Russian dumplings in a thin milk-and-egg dough, filled with juicy pork and chicken, onion, garlic and dill.', '<ol><li>For the dough, mix the milk, salt, egg and water, then add the flour one cup at a time with a dough hook running (or knead by hand) until smooth and no longer sticky.</li><li>Cover the dough and rest it for 15–30 minutes so it becomes stretchy.</li><li>Combine the pork and chicken with grated onion, garlic, salt, pepper, vinegar, water and chopped dill. Cover and set aside until you shape the dumplings.</li><li>Divide the dough in three and roll each very thin. Shape by hand: cut rounds or squares, add a teaspoon of filling, fold and pinch the edges tightly. Or use a pelmeni mold: lay a sheet of dough, fill the holes with meat, cover with a second sheet and roll over it with a rolling pin.</li><li>Bring a large pot of salted water to a boil. Add the pelmeni in batches and cook 2–3 minutes after they float. Do not overcook or they will fall apart.</li></ol><p><em>Serve with sour cream, butter, vinegar or mustard. Raw pelmeni freeze well.</em></p>', CURRENT_TIMESTAMP),
  ('a9967729-3ca5-581d-bcd5-388daa64c227', 'a6728c89-a828-5662-90a3-ae42b31e0c1f', 'ru', 'Треска в сливочно-винном соусе с помидорами черри', 'Сочное филе трески в специях, обжаренное в соусе из сливочного масла, белого вина, бульона и лопнувших помидоров черри. Готовится за 20 минут.', '<ol><li>Смешайте в мисочке соль, перец, зиру, паприку, чесночный порошок и чили. Натрите смесью треску со всех сторон.</li><li>В сковороде на среднем огне влейте бульон и вино, добавьте помидоры черри и готовьте около 5 минут, пока помидоры не лопнут и не отдадут сок.</li><li>Добавьте сливочное масло и помешивайте до растворения. Положите треску и готовьте на среднем-сильном огне по 3–4 минуты с каждой стороны, не пересушивая рыбу.</li><li>Полейте рыбу соусом, посыпьте свежей зеленью и подавайте.</li></ol><p><em>Посыпьте рубленой зеленью и подайте с рисом или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('36ac1edd-6f70-5ee7-a8e1-d0679086b503', 'a6728c89-a828-5662-90a3-ae42b31e0c1f', 'en', 'Cod in butter wine sauce with cherry tomatoes', 'Spice-rubbed cod fillets cooked in a sauce of butter, white wine, broth and burst cherry tomatoes, ready in about 20 minutes.', '<ol><li>Combine the salt, pepper, cumin, paprika, garlic powder and chili powder in a small bowl. Rub the mixture over the cod on all sides.</li><li>In a skillet over medium heat, add the broth, wine and cherry tomatoes and cook about 5 minutes until the tomatoes burst and release their juices.</li><li>Add the butter and stir until melted. Add the cod and cook over medium-high heat 3–4 minutes per side, taking care not to overcook it.</li><li>Spoon the sauce over the fish, add fresh herbs and serve.</li></ol><p><em>Top with chopped herbs and serve with rice or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('9a91018d-851a-55d5-af48-8746a84908ce', '441de262-90e8-50fc-98e1-8c35d8ab82a5', 'ru', 'Фриттата с сыром и зеленью', 'Пышный яичный омлет-запеканка со сливками, тёртым сыром и зеленью. К базе можно добавить овощи и мясо.', '<ol><li>Взбейте яйца со сливками, солью, перцем, тёртым сыром и рубленой зеленью до однородности.</li><li>На плите: смажьте сковороду маслом, влейте смесь, накройте крышкой и готовьте на среднем огне 10–12 минут.</li><li>В духовке: смажьте форму диаметром 23–25 см и выпекайте при 190 °C 20–25 минут (или при 175 °C 30–35 минут). Для маффинов — 190 °C, 12–15 минут.</li></ol><p><em>Подайте с тостами и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('1ddddadd-a770-5be3-b5d0-1e7db281679d', '441de262-90e8-50fc-98e1-8c35d8ab82a5', 'en', 'Cheese and herb frittata', 'A fluffy baked or pan-cooked egg dish with half-and-half, shredded cheese and herbs. Easy to customise with vegetables and meat.', '<ol><li>Whisk the eggs with the half-and-half, salt, pepper, shredded cheese and herbs until combined.</li><li>On the stovetop: grease a skillet with butter, pour in the egg mixture, cover and cook over medium heat for 10–12 minutes.</li><li>In the oven: grease a 9–10 inch pie dish and bake at 375 °F (190 °C) for 20–25 minutes, or 350 °F (175 °C) for 30–35 minutes. For muffins, bake at 375 °F for 12–15 minutes.</li></ol><p><em>Serve with toast and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('5d186575-94b2-50bc-a2b2-31e888ea8a18', '40707efc-491e-5758-bfe8-5cc2c6ee5b68', 'ru', 'Лосось, запечённый в специях, с авокадо-сальсой', 'Запечённое филе лосося с чесноком, паприкой и перцем, поданное с освежающей сальсой из авокадо, помидоров, красного лука и кинзы.', '<ol><li>Разогрейте духовку до 220 °C. Нарежьте лосось на 4–5 порций.</li><li>Смешайте оливковое масло, чеснок, паприку, чили, перец и соль и натрите рыбу со всех сторон.</li><li>Запекайте 12–15 минут в зависимости от толщины филе.</li><li>Пока запекается рыба, мелко нарежьте красный лук, кинзу и халапеньо, измельчите чеснок, нарежьте кубиками помидоры и авокадо. Смешайте всё с лимонным соком в небольшой миске.</li><li>Переложите лосось на блюдо, сверху выложите сальсу и подавайте сразу.</li></ol><p><em>Подайте сразу, пока рыба тёплая, с рисом или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('7bcb9b64-063a-516c-b8be-bdb103451c46', '40707efc-491e-5758-bfe8-5cc2c6ee5b68', 'en', 'Baked salmon with avocado salsa', 'Oven-baked salmon rubbed with garlic, paprika and chili, topped with a fresh avocado, tomato, red onion and cilantro salsa.', '<ol><li>Preheat the oven to 425 °F (220 °C). Cut the salmon into 4 to 5 fillets.</li><li>Mix the olive oil, garlic, paprika, chili powder, pepper and salt and rub it all over the salmon.</li><li>Bake for 12–15 minutes, depending on the thickness of the fillets.</li><li>While the fish bakes, finely chop the onion, cilantro and jalapeños, mince the garlic and cube the tomatoes and avocado. Toss everything with the lemon juice in a small bowl.</li><li>Transfer the salmon to a platter, top with the salsa and serve immediately.</li></ol><p><em>Serve right away with rice or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('5f9596e0-d845-5a88-810b-28eba1103e21', 'f4a7f233-b441-5659-a4ed-481d91fee4fd', 'ru', 'Говядина с грибами и яичной лапшой', 'Кусочки говядины в густом грибном соусе с луком и чесноком, смешанные с яичной лапшой. Готовится в одной кастрюле.', '<ol><li>Сварите яичную лапшу до состояния аль денте в кастрюле, слейте воду, накройте, чтобы осталась тёплой.</li><li>В той же кастрюле разогрейте оливковое масло, обжарьте кубики говядины, посолив и поперчив половиной приправ, до золотистого цвета. Переложите на тарелку и накройте.</li><li>Добавьте масло и обжарьте грибы с луком до золотистых грибов. Положите чеснок и прогрейте до аромата.</li><li>Верните мясо в кастрюлю, всыпьте кукурузный крахмал, быстро размешайте, влейте бульон и вустерский соус, добавьте лавровый лист и оставшуюся соль и перец.</li><li>Варите на слабом огне 10 минут, пока соус не загустеет. Выньте лавровый лист, добавьте лапшу, перемешайте и подавайте.</li></ol><p><em>Посыпьте свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('cadb1a42-f631-5180-8d17-9d0c9dc3b301', 'f4a7f233-b441-5659-a4ed-481d91fee4fd', 'en', 'Beef tips and mushrooms with egg noodles', 'Tender beef pieces in a rich mushroom, onion and garlic sauce tossed with egg noodles, all made in one pot.', '<ol><li>Cook the egg noodles al dente in a Dutch oven, drain and cover to keep warm.</li><li>In the same pot, heat the oil and brown the beef cubes with half the salt and pepper until golden. Remove and cover to keep warm.</li><li>Add the butter and cook the mushrooms and onion until the mushrooms are golden. Stir in the garlic until fragrant.</li><li>Return the beef to the pot, whisk in the cornstarch quickly, then add the broth, Worcestershire sauce, bay leaves and the remaining salt and pepper.</li><li>Simmer about 10 minutes until the sauce thickens. Remove the bay leaves, stir in the noodles and serve.</li></ol><p><em>Sprinkle with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('0e561c08-18fb-520c-b9d7-87bfcf6324a7', '2780a9bf-f1c4-5700-8171-e0636a6e5b99', 'ru', 'Белая рыба, запечённая с лимоном и укропом', 'Филе палтуса или другой плотной белой рыбы, запечённое в духовке с итальянскими травами, чесноком, лимоном и свежим укропом. Готовится за 15 минут.', '<ol><li>Разогрейте духовку до 220 °C, поставив решётку посередине. Слегка смажьте противень оливковым маслом.</li><li>Посыпьте рыбу со всех сторон солью, перцем, итальянскими травами, чесночным порошком и хлопьями чили. Выложите на противень.</li><li>Сбрызните рыбу оливковым маслом и положите сверху тонкие ломтики половины лимона. Запекайте на средней решётке 10–15 минут, пока в самой толстой части мясо не начнёт легко расслаиваться вилкой.</li><li>Достаньте из духовки, выжмите на рыбу сок оставшейся половины лимона, посыпьте укропом и подавайте сразу.</li></ol><p><em>Подайте с отварным картофелем, рисом или свежим овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('23e52fd9-fef7-54c6-9eb4-7e0559580f1e', '2780a9bf-f1c4-5700-8171-e0636a6e5b99', 'en', 'Baked white fish with lemon and dill', 'Halibut or another sturdy white fish baked with Italian seasoning, garlic, lemon and fresh dill, ready in 15 minutes.', '<ol><li>Set a rack in the middle of the oven and preheat to 425 °F (220 °C). Lightly brush a sheet pan with olive oil.</li><li>Season the fish all over with salt, pepper, Italian seasoning, garlic powder and chili flakes, then arrange on the pan.</li><li>Drizzle with olive oil and top with thin slices of half the lemon. Bake on the middle rack for 10–15 minutes until the thickest part flakes easily with a fork.</li><li>Remove from the oven, squeeze the remaining lemon half over the fish, sprinkle with dill and serve immediately.</li></ol><p><em>Serve with boiled potatoes, rice or a fresh vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('747d9d7c-e8b1-518a-8a4f-4be86bc4cc65', 'acdd90cd-7645-5190-913f-8db35b0c4f6e', 'ru', 'Лосось в фольге с лимоном и чесноком', 'Крупный кусок филе лосося, запечённый в фольге с лимонно-чесночным соусом, орегано и паприкой, а в конце слегка подрумяненный под грилем.', '<ol><li>Поставьте одну решётку в центр духовки, а вторую в 15 см от гриля. Разогрейте до 190 °C. Застелите противень большим листом фольги, чтобы им можно было накрыть рыбу, и смажьте фольгу маслом.</li><li>Для соуса натрите цедру одного лимона, добавьте сок двух лимонов, оливковое масло, чеснок, орегано, паприку и перец и взбейте.</li><li>Обсушите лосось и хорошо посолите с обеих сторон. Положите кожей вниз на фольгу, загните края фольги и вылейте соус. Равномерно распределите соус по рыбе и выложите сверху кружки лимона.</li><li>Накройте рыбу фольгой «шатром» так, чтобы оставался воздушный зазор, и защипните края. Запекайте 15–20 минут, пока рыба почти не приготовится в самой толстой части.</li><li>Аккуратно откройте фольгу, включите гриль на максимум и подержите рыбу под ним около 3 минут, пока верх слегка не подрумянится. Следите, чтобы лимон и чеснок не подгорели.</li><li>Посыпьте рубленой петрушкой и подавайте с дольками лимона.</li></ol><p><em>Подайте с рисом басмати и большим овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e0845494-1402-5ed4-a127-9244879e799d', 'acdd90cd-7645-5190-913f-8db35b0c4f6e', 'en', 'Lemon garlic salmon baked in foil', 'A large salmon fillet baked in foil with lemon-garlic sauce, oregano and paprika, finished briefly under the broiler.', '<ol><li>Position one rack in the center of the oven and one about 6 inches from the broiler. Preheat to 375 °F (190 °C). Line a sheet pan with a large piece of foil that can fold over the fish and brush with olive oil.</li><li>For the sauce zest one lemon, add the juice of two lemons, the olive oil, garlic, oregano, paprika and pepper and whisk.</li><li>Pat the salmon dry and salt both sides well. Place it skin-side down on the foil, bend the foil edges up and pour the sauce over. Spread evenly and top with lemon rounds.</li><li>Fold the foil over the salmon like a tent, leaving an air pocket, and crimp the edges closed. Bake 15–20 minutes until almost cooked through at the thickest part.</li><li>Carefully open the foil, turn the broiler to high and broil about 3 minutes until the top is lightly browned, watching so the lemon and garlic don''t burn.</li><li>Sprinkle with chopped parsley and serve with lemon wedges.</li></ol><p><em>Serve with basmati rice and a big salad.</em></p>', CURRENT_TIMESTAMP),
  ('e348cce8-a193-5a53-b4fd-dad37377b9f3', 'b4154d3a-5d8d-5291-8e09-cc8e0bc2bcd1', 'ru', 'Фарро с грибами, горошком и пармезаном', 'Рассыпчатая крупа фарро, тушённая на одной сковороде с шампиньонами, зелёным горошком, чесноком, тимьяном и мятой, с пармезаном в конце.', '<ol><li>В глубокой сковороде с крышкой нагрейте 2 ст. л. оливкового масла на среднем-сильном огне.</li><li>Добавьте зелёный лук, грибы и горошек и обжаривайте 3–4 минуты. Положите чеснок и помешивайте, пока он не запахнет.</li><li>Добавьте фарро, паприку, тимьян, немного соли и перца и готовьте 4–5 минут, регулярно помешивая.</li><li>В отдельной кастрюле доведите бульон до кипения и влейте в сковороду. Доведите до кипения, убавьте огонь до средне-слабого, накройте крышкой и готовьте около 20 минут, пока жидкость не впитается.</li><li>Снимите с огня, добавьте тёртый пармезан и рубленую мяту и подавайте тёплым.</li></ol><p><em>Хороша как гарнир к курице или рыбе, а с овощным салатом — самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('216de68e-ccd6-5501-9539-b90f6051a39b', 'b4154d3a-5d8d-5291-8e09-cc8e0bc2bcd1', 'en', 'One-pan farro with mushrooms, peas and parmesan', 'Chewy farro cooked in one skillet with mushrooms, green peas, garlic, thyme and fresh mint, finished with parmesan.', '<ol><li>In a deep skillet with a lid heat 2 tbsp olive oil over medium-high heat.</li><li>Add the green onions, mushrooms and peas and sauté 3–4 minutes. Add the garlic and stir until fragrant.</li><li>Add the farro, paprika, thyme and a little salt and pepper and cook 4–5 minutes, stirring regularly.</li><li>Boil the broth in a separate pot and pour it into the skillet. Bring to a boil, lower to medium-low, cover and cook about 20 minutes until the liquid is absorbed.</li><li>Remove from the heat, stir in the grated parmesan and chopped mint and serve warm.</li></ol><p><em>Serve as a side with chicken or fish, or as a light meal with a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('cfcd28b9-6ca6-5618-90b2-528c1366a2c7', 'bb657197-6c44-5c85-8bd6-579cdef66afd', 'ru', 'Шашлык из говядины с овощами на шпажках', 'Кубики говяжьей вырезки в маринаде из красного вина, лимона и оливкового масла с пряностями, пожаренные на гриле с болгарским перцем и луком.', '<ol><li>В большой миске смешайте чесночный порошок, мускатный орех, кардамон, душистый перец, паприку, щедрую щепотку соли и перца.</li><li>Добавьте нарезанную кубиками говядину и вотрите в неё специи.</li><li>В глубокой посуде смешайте тонко нарезанный красный лук, лимонный сок, оливковое масло и красное вино, добавьте мясо и перемешайте руками. Накройте и уберите в холодильник минимум на 30 минут (лучше на 2–4 часа или на ночь).</li><li>За час до жарки достаньте мясо из холодильника. Деревянные шпажки замочите в воде. Нарежьте лук и перцы кусками размером с кубик мяса.</li><li>Разогрейте смазанную маслом решётку гриля на сильном огне 10 минут. Нанижите на шпажки мясо, лук и перцы по очереди (примерно по 4 куска мяса), посыпьте свежемолотым перцем. Маринад отложите.</li><li>Жарьте шашлыки 8–10 минут, периодически переворачивая и несколько раз смазывая маринадом, до желаемой прожарки. Дайте 5 минут отдохнуть и подавайте.</li></ol><p><em>Подайте с рисом, лепёшками и салатом из помидоров с огурцами.</em></p>', CURRENT_TIMESTAMP),
  ('3c86359b-a722-50dc-bd76-302255452586', 'bb657197-6c44-5c85-8bd6-579cdef66afd', 'en', 'Beef shish kabobs with vegetables', 'Cubes of sirloin or tenderloin marinated in red wine, lemon and olive oil with warm spices, grilled on skewers with bell peppers and onion.', '<ol><li>In a large bowl mix the garlic powder, nutmeg, cardamom, allspice, paprika and a generous pinch each of salt and pepper.</li><li>Add the cubed beef and rub the spices into the meat.</li><li>In a deep dish combine the sliced red onion, lemon juice, olive oil and red wine, add the meat and work the marinade in. Cover and refrigerate at least 30 minutes (ideally 2–4 hours or overnight).</li><li>Take the meat out of the fridge an hour before grilling. Soak wooden skewers in water. Cut the onion and peppers into pieces about the size of the meat cubes.</li><li>Lightly oil the grill grates and heat on high for 10 minutes. Thread the meat, onion and peppers onto the skewers (about 4 pieces of meat each) and season with black pepper. Keep the marinade.</li><li>Grill the kabobs 8–10 minutes, turning occasionally and brushing with the marinade a couple of times, until done to your liking. Rest 5 minutes and serve.</li></ol><p><em>Serve with rice, flatbread and a tomato cucumber salad.</em></p>', CURRENT_TIMESTAMP),
  ('94f4eb6f-82f8-5b4f-9d79-e23c55d49215', '801d2255-41fe-5de1-9dce-85f2a3d70e8e', 'ru', 'Куриные колбаски с перцем, луком и помидорами на противне', 'Готовые куриные колбаски, запечённые под грилем на одном противне с болгарским перцем, красным луком, помидорами черри, чесноком и травами.', '<ol><li>Включите в духовке режим гриля и поставьте решётку примерно в 15 см от нагревателя.</li><li>Сделайте на колбасках несколько надрезов, не прорезая насквозь.</li><li>Смешайте в миске перцы, лук и помидоры с чесноком, тимьяном, орегано, паприкой, солью и перцем. Влейте 3–4 ст. л. оливкового масла и перемешайте, чтобы овощи покрылись маслом.</li><li>Разложите овощи в один слой на большом противне, между ними положите колбаски.</li><li>Запекайте под грилем 8–10 минут, внимательно следя, пока овощи не станут мягкими, а колбаски не подрумянятся.</li></ol><p><em>Подавайте с хлебом, рисом или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('946e89b1-c9ac-5db5-958d-0e2e598a2a1f', '801d2255-41fe-5de1-9dce-85f2a3d70e8e', 'en', 'Sheet pan chicken sausage with peppers and onions', 'Fully cooked chicken sausages broiled on one sheet pan with bell peppers, red onion, cherry tomatoes, garlic and herbs.', '<ol><li>Set the oven to broil and arrange a rack about 6 inches from the heat source.</li><li>Score the sausage links in several places without cutting all the way through.</li><li>In a bowl toss the peppers, onion and tomatoes with the garlic, thyme, oregano, paprika, salt and pepper. Add 3–4 tbsp olive oil and toss to coat.</li><li>Spread the vegetables in a single layer on a large baking sheet and nestle the sausages between them.</li><li>Broil 8–10 minutes, watching closely, until the vegetables are soft and the sausages nicely charred.</li></ol><p><em>Serve with bread, rice or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('4687a75f-31be-5597-adf3-6b3c1e5bd074', '3c8bd75f-e625-5e52-bc50-214a5aa6af5d', 'ru', 'Салат из зелёной фасоли по-гречески с фетой и оливками', 'Нежная стручковая фасоль, дважды отваренная и охлаждённая во льду, с чесночно-лимонной заправкой, укропом, фетой и оливками.', '<ol><li>Доведите большую кастрюлю воды до кипения. Приготовьте миску с ледяной водой.</li><li>Заправка: взбейте оливковое масло, лимонный сок, чеснок, укроп, паприку, щепотку соли и перца.</li><li>Варите фасоль 5 минут, щипцами переложите в ледяную воду на 5 минут. Затем верните в кипящую воду и варите ещё около 10 минут до мягкости. Слейте воду и обсушите полотенцем.</li><li>Переложите ещё тёплую фасоль в миску, посолите и поперчите, залейте заправкой и перемешайте.</li><li>Выложите на блюдо, посыпьте хлопьями чили и раскрошенной фетой, сверху положите рубленые оливки. Подавайте при комнатной температуре.</li></ol><p><em>Подавайте при комнатной температуре как гарнир к рыбе или мясу.</em></p>', CURRENT_TIMESTAMP),
  ('a29e4dcc-ef7d-5b43-afcd-d1e0bc1a9c0f', '3c8bd75f-e625-5e52-bc50-214a5aa6af5d', 'en', 'Greek green bean salad with feta and olives', 'Tender green beans, double-boiled and chilled in an ice bath, tossed with a garlicky lemon dressing and dill, topped with feta and olives.', '<ol><li>Bring a large pot of water to a boil and set a large bowl of ice water nearby.</li><li>Dressing: whisk together the olive oil, lemon juice, garlic, dill, paprika and a pinch of salt and pepper.</li><li>Boil the green beans for 5 minutes, transfer with tongs to the ice bath for 5 minutes, then return to the boiling water for about 10 more minutes until tender. Drain and pat dry with a towel.</li><li>Put the warm beans in a bowl, season with salt and pepper, pour over the dressing and toss.</li><li>Transfer to a platter, sprinkle with chili flakes and crumbled feta and top with chopped olives. Serve at room temperature.</li></ol><p><em>Serve at room temperature as a side for fish or meat.</em></p>', CURRENT_TIMESTAMP),
  ('85ae6610-ea4c-51da-bdad-27f2d93defba', '6522833c-ff72-5bcd-85d9-93505c18e074', 'ru', 'Куриное филе в медово-лимонном соусе', 'Тонкие стейки из куриной грудки в муке, обжаренные до золотистой корочки, в блестящем соусе из мёда, лимона и чеснока. Ужин за 15 минут.', '<ol><li>Разрежьте каждую грудку вдоль пополам, получится 4 стейка. При желании слегка отбейте до толщины 1 см. Посолите и поперчите с обеих сторон.</li><li>Обваляйте курицу в муке, стряхните лишнее. 1 ч. л. муки смешайте с водой и отложите.</li><li>Разогрейте в сковороде масло со сливочным, обжарьте курицу по 2 минуты с каждой стороны до золотистого цвета, переложите на тарелку.</li><li>В той же сковороде 20 секунд обжарьте чеснок, влейте бульон и соскребите пригоревшие кусочки со дна.</li><li>Добавьте мёд, лимонный сок, соевый соус и мучную смесь, варите 2–3 минуты до консистенции сиропа. Полейте курицу соусом, украсьте петрушкой и лимоном.</li></ol><p><em>Подайте с рисом, картофельным пюре или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('9ad23ea2-4848-5f1b-88e5-ed95e2fa0030', '6522833c-ff72-5bcd-85d9-93505c18e074', 'en', 'Honey lemon chicken', 'Thin floured chicken breast steaks pan-fried until golden and glazed in a glossy honey, lemon and garlic sauce. Ready in about 15 minutes.', '<ol><li>Slice each breast horizontally to make 4 steaks. Optionally pound to about 1 cm thick. Season both sides with salt and pepper.</li><li>Dredge the chicken in flour and shake off the excess. Mix 1 tsp of the flour with the water and set aside.</li><li>Heat the butter and oil in a skillet over medium-high heat and brown the chicken for about 2 minutes per side. Transfer to a plate.</li><li>In the same skillet stir the garlic for 20 seconds, add the stock and scrape up the browned bits from the bottom.</li><li>Add the honey, lemon juice, soy sauce and flour-water mixture and simmer 2–3 minutes until syrupy. Pour over the chicken and garnish with parsley and lemon.</li></ol><p><em>Serve with rice, mashed potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('3afb38f0-4de5-5d79-a54e-8f2014b36863', 'a9b10719-8346-5c5b-b588-00051b823d70', 'ru', 'Паста орзо с грибами и шпинатом в сливочном соусе', 'Паста орзо, сваренная в одной сковороде в соусе из молока и бульона с шампиньонами, шпинатом и пармезаном. Кремовая текстура без сливок.', '<ol><li>Разогрейте оливковое масло в большой сковороде на сильном огне, обжарьте нарезанные шампиньоны около 3 минут до мягкости. Переложите в миску.</li><li>Убавьте огонь до среднего, растопите масло, пассеруйте чеснок и лук около 3 минут до прозрачности. Всыпьте муку и перемешивайте минуту.</li><li>Влейте молоко и бульон, размешивая венчиком. Добавьте орзо, соль и перец, перемешайте, накройте крышкой и варите на среднем огне 8–10 минут, пока паста не станет почти готовой, а соус останется жидким.</li><li>Размелите размороженный отжатый шпинат пальцами. Снимите сковороду с огня, вмешайте пармезан, шпинат и грибы, проверьте соль и перец. Подавайте сразу.</li></ol><p><em>Посыпьте пармезаном и рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('e2b37848-7498-59fe-b9ab-e272c7e5586c', 'a9b10719-8346-5c5b-b588-00051b823d70', 'en', 'Creamy mushroom and spinach orzo', 'Orzo pasta cooked in one pan in a milk-and-stock sauce with mushrooms, spinach and Parmesan. Creamy without any cream.', '<ol><li>Heat the olive oil in a large pan over high heat and cook the sliced mushrooms about 3 minutes until softened. Remove to a bowl.</li><li>Lower the heat to medium, melt the butter and cook the garlic and onion about 3 minutes until translucent. Stir in the flour and cook for 1 minute.</li><li>Pour in the milk and stock, whisking. Add the orzo, salt and pepper, stir once, cover and simmer 8–10 minutes until the orzo is cooked but slightly firm and still saucy.</li><li>Break the thawed, squeezed spinach into small pieces. Remove the pan from the heat and stir in the Parmesan, spinach and mushrooms. Adjust the seasoning and serve right away.</li></ol><p><em>Garnish with extra Parmesan and chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('f91b21bb-7b89-5ade-8f03-af5d23482be8', 'ff1ecdcd-2223-59c0-a2cc-da723356a0bc', 'ru', 'Плов с бараниной, чечевицей и шпинатом', 'Ароматный рис с бараньим фаршем, чечевицей и шпинатом, приправленный кориандром, зирой и корицей. Подавайте со свежими помидорами.', '<ol><li>В большой кастрюле разогрейте масло на среднем-сильном огне, 2–3 минуты обжарьте лук с чесноком до золотистого цвета.</li><li>Прибавьте огонь, добавьте баранину и жарьте, разбивая комки, до румяности. Всыпьте специи (кориандр, зиру, корицу, чили, соль, перец, сахар) и прогрейте 30 секунд.</li><li>Добавьте рис, воду и чечевицу, перемешайте. Доведите до кипения, накройте крышкой, убавьте огонь до средне-слабого и готовьте 10–12 минут, пока вода не впитается.</li><li>Снимите с огня, откройте крышку, быстро выложите сверху шпинат и снова накройте. Оставьте на 10 минут.</li><li>Перемешайте шпинат с рисом, взрыхлите вилкой, переложите на блюдо и подавайте с нарезанными помидорами.</li></ol><p><em>Подайте с ломтиками свежих помидоров без заправки.</em></p>', CURRENT_TIMESTAMP),
  ('313e0d98-937b-5e0a-9e5c-f1a0fec26c29', 'ff1ecdcd-2223-59c0-a2cc-da723356a0bc', 'en', 'Middle Eastern lamb, lentil and spinach rice pilaf', 'Fragrant rice cooked with minced lamb, lentils and spinach and seasoned with coriander, cumin and cinnamon. Served with sliced fresh tomatoes.', '<ol><li>Heat the oil in a large pot over medium-high heat and sauté the garlic and onion for 2–3 minutes until golden.</li><li>Turn the heat to high, add the lamb and brown it, breaking it up. Add the spices (coriander, cumin, cinnamon, chilli, salt, pepper, sugar) and cook 30 seconds until fragrant.</li><li>Add the rice, water and lentils and stir. Bring to a simmer, cover, reduce to medium-low and cook 10–12 minutes until the water is absorbed.</li><li>Remove from the heat, lift the lid, quickly spread the spinach over the rice and cover again. Rest for 10 minutes.</li><li>Stir the spinach through the rice, fluff with a fork, transfer to a dish and serve with sliced tomatoes.</li></ol><p><em>Serve with plain sliced tomatoes on the side.</em></p>', CURRENT_TIMESTAMP),
  ('be12004f-4ad0-569c-bf34-978e81e97b54', '45cdba2e-1e97-53c4-a70d-998ae7696544', 'ru', 'Запечённые баклажаны с чермулой и кускусом', 'Половинки баклажанов под пряной пастой с чесноком, зирой и лимоном, запечённые до мягкости и заполненные кускусом с изюмом, оливками, миндалём и зеленью.', '<ol><li>Разогрейте духовку до 180 °C. Разрежьте баклажаны вдоль и сделайте глубокие диагональные надрезы крест-накрест, не прорезая кожицу.</li><li>Для чермулы смешайте чеснок, зиру, кориандр, хлопья чили, паприку, цедру лимона, 4 ст. л. масла и ½ ч. л. соли. Щедро намажьте баклажаны.</li><li>Выложите срезом вверх на противень и запекайте около 40 минут до полной мягкости (время зависит от размера).</li><li>Залейте кускус с солью и изюмом кипятком, накройте на 5 минут, затем взрыхлите вилкой.</li><li>Добавьте к кускусу оливки, подсушенный миндаль, зелёный лук, кинзу и мяту, лимонный сок, масло и перец. Выложите горкой на баклажаны, добавьте ложку йогурта и кинзу.</li></ol><p><em>Подайте с ложкой йогурта и простым салатом.</em></p>', CURRENT_TIMESTAMP),
  ('a722b73d-92fd-5431-a314-30cbe5dbca50', '45cdba2e-1e97-53c4-a70d-998ae7696544', 'en', 'Roasted eggplant with chermoula and couscous', 'Eggplant halves slathered in a fragrant chermoula paste and roasted until soft, piled with couscous with raisins, olives, almonds and herbs.', '<ol><li>Preheat the oven to 350 °F (180 °C). Halve the eggplants lengthwise and score the flesh deeply in a criss-cross pattern without cutting through the skin.</li><li>For the chermoula, mix the garlic, cumin, coriander, chilli flakes, paprika, lemon zest, 4 tbsp of oil and ½ tsp salt. Slather it over the eggplant.</li><li>Place cut-side up on a baking tray and roast about 40 minutes until completely soft, depending on size.</li><li>Put the couscous, salt and raisins in a bowl, add the boiling water and cover for 5 minutes, then fluff with a fork.</li><li>Toss the olives, toasted almonds, scallions, cilantro and mint, lemon juice, olive oil and pepper through the couscous. Pile it onto the eggplants and finish with a dollop of yoghurt and cilantro.</li></ol><p><em>Finish with a spoon of yoghurt and a simple side salad.</em></p>', CURRENT_TIMESTAMP),
  ('35fad008-fff1-52e9-acff-eaeddbe89628', '121123eb-4618-5847-ac91-20bc363d29e1', 'ru', 'Салат фаттуш с хрустящими полосками лепёшки', 'Ближневосточный салат из помидоров, огурцов, красного лука, мяты и кинзы с лимонно-сумаховой заправкой и поджаренными в духовке полосками питы.', '<ol><li>Разогрейте духовку до 180 °C. Сверните лепёшки, нарежьте тонкими лентами и разрыхлите пальцами.</li><li>Выложите на противень, сбрызните маслом, посолите и перемешайте руками. Выпекайте 3 минуты, перемешайте, выключите духовку и оставьте на пару минут, чтобы ленты стали хрустящими.</li><li>Красный лук смешайте с 1 ст. л. лимонного сока и щепоткой соли, оставьте мариноваться.</li><li>Смешайте ингредиенты заправки. В миске соедините помидоры, огурцы, мяту, кинзу и лук, полейте заправкой по вкусу и аккуратно перемешайте.</li><li>Переложите на блюдо, сверху выложите хрустящие ленты лепёшки и посыпьте сумахом.</li></ol><p><em>Хрустящие полоски кладите на салат прямо перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('d64f6a63-41ee-5029-b851-0f45fba51d7e', '121123eb-4618-5847-ac91-20bc363d29e1', 'en', 'Fattoush with crunchy flatbread ribbons', 'A Middle Eastern salad of tomatoes, cucumbers, red onion, mint and coriander with a lemony sumac dressing, topped with oven-crisped flatbread ribbons.', '<ol><li>Preheat the oven to 350 °F (180 °C). Roll up the flatbreads, slice into thin strips and loosen into ribbons.</li><li>Pile onto a baking tray, drizzle with oil, add salt and toss by hand. Bake 3 minutes, stir, turn the oven off and leave a couple of minutes more until crisp.</li><li>Toss the red onion with 1 tbsp of lemon juice and a pinch of salt and leave it to lightly pickle.</li><li>Combine the dressing ingredients. In a bowl mix the tomatoes, cucumbers, mint, coriander and onion, pour over dressing to taste and toss gently.</li><li>Transfer to a platter, pile on the crunchy flatbread and sprinkle with extra sumac.</li></ol><p><em>Add the crunchy flatbread right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('5e890545-85bc-5aff-8eb3-42549789e8ec', '182703f5-ac92-5d84-8bb1-40e586eb57ef', 'ru', 'Курица шаурма с рисом и нутом в одной сковороде', 'Куриные бёдра в пряной шаурмовой смеси, запечённые на рисовом пилаве с нутом, корицей и кардамоном. Всё готовится в одной жаропрочной сковороде.', '<ol><li>Разогрейте духовку до 180 °C. Смешайте чеснок, кориандр, зиру, кардамон, паприку, кайенский перец, соль, перец и лимонный сок и натрите смесью куриные бёдра с обеих сторон. По желанию оставьте мариноваться на 1–24 часа.</li><li>Разогрейте масло в большой жаропрочной сковороде, обжарьте курицу кожей вниз по 5 минут с каждой стороны до золотистого цвета. Переложите на тарелку, лишний жир слейте, оставив немного для лука.</li><li>Добавьте чеснок и лук, 2 минуты до прозрачности. Всыпьте рис и перемешайте, чтобы зёрна покрылись маслом.</li><li>Добавьте бульон, воду, соль, перец, кардамон, корицу, нут и изюм. Сверху выложите курицу так, чтобы она была наполовину погружена, а кожа сверху. Влейте сок с тарелки.</li><li>Доведите до кипения, накройте крышкой или фольгой и поставьте в духовку на 35 минут, затем снимите крышку и запекайте ещё 10 минут. Дайте постоять 5 минут.</li><li>Выньте курицу, быстро перемешайте рис и подавайте с йогуртом, кинзой и петрушкой.</li></ol><p><em>Подайте с натуральным йогуртом и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('fe6c3669-3b02-5646-8f4c-af734521d947', '182703f5-ac92-5d84-8bb1-40e586eb57ef', 'en', 'One-skillet baked chicken shawarma with rice pilaf', 'Chicken thighs in a shawarma spice rub baked on top of a rice pilaf with chickpeas, cinnamon and cardamom, all in one ovenproof skillet.', '<ol><li>Preheat the oven to 350 °F (180 °C). Mix the garlic, coriander, cumin, cardamom, paprika, cayenne, salt, pepper and lemon juice and rub over both sides of the chicken. Marinate 1–24 hours if you have time.</li><li>Heat the oil in a large ovenproof skillet and brown the chicken skin-side down for 5 minutes per side. Remove to a plate and pour off excess fat, leaving a little for the onion.</li><li>Add the garlic and onion and cook 2 minutes until translucent. Add the rice and stir to coat the grains in oil.</li><li>Add the stock, water, salt, pepper, cardamom, cinnamon, chickpeas and raisins. Set the chicken on top, half submerged, skin above the liquid, and pour in the plate juices.</li><li>Bring to a simmer, cover with a lid or foil and bake for 35 minutes, then uncover and bake 10 minutes more. Rest for 5 minutes.</li><li>Lift out the chicken, quickly stir the rice and serve with yoghurt, cilantro and parsley.</li></ol><p><em>Serve with plain yoghurt and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('bcd284b9-8b4a-5feb-a956-2f9f8068a8b4', '573c1b1a-ad40-54be-a874-85f4f0a82931', 'ru', 'Форель или лосось, запечённые с шалотом, лимоном и укропом', 'Целое филе форели или лосося, запечённое с маслом, шалотом, чесноком, лимонной цедрой и свежим укропом. Просто готовится и выглядит празднично.', '<ol><li>Разогрейте духовку до 230 °C. Застелите противень с бортами фольгой или пергаментом.</li><li>Растопите масло в сковороде или небольшой кастрюле, добавьте шалот и готовьте на среднем огне около 3 минут до мягкости.</li><li>Добавьте чеснок и лимонную цедру, готовьте ещё минуту и слегка остудите. Выжмите в масло половину лимонного сока.</li><li>Выложите рыбу на противень (если она большая, положите по диагонали), посолите и поперчите. Полейте маслом с шалотом и посыпьте половиной укропа.</li><li>Запекайте 12–17 минут в зависимости от толщины, пока рыба легко не будет расслаиваться вилкой.</li><li>Переложите рыбу на блюдо несколькими лопатками (или порежьте на части), сбрызните оставшимся лимонным соком и посыпьте оставшимся укропом.</li></ol><p><em>Подавайте с картофелем, рисом или свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('97f8d736-fb9d-55f8-80d5-ed937b435708', '573c1b1a-ad40-54be-a874-85f4f0a82931', 'en', 'Baked trout or salmon fillet with shallot, lemon and dill', 'A whole steelhead trout or salmon fillet roasted with shallot lemon butter, garlic and fresh dill. Simple but impressive.', '<ol><li>Preheat the oven to 450 °F (230 °C). Line a rimmed baking sheet with foil or parchment.</li><li>Melt the butter in a skillet or small saucepan, add the shallot and cook over medium heat about 3 minutes until softened.</li><li>Add the garlic and lemon zest, cook another minute and let cool slightly. Squeeze in half of the lemon juice.</li><li>Place the fish on the pan (diagonally if it is large), season with salt and pepper, spoon the shallot butter over it and sprinkle with half of the dill.</li><li>Roast 12–17 minutes depending on thickness, until the fish flakes easily with a fork.</li><li>Lift the fish onto a platter with several spatulas (or cut it into sections), squeeze the remaining lemon juice over it and sprinkle with more dill.</li></ol><p><em>Serve with potatoes, rice or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('9087d083-ffd7-528f-ae95-97cd5c76ad9a', 'bac0eae4-1637-51d5-9df8-d6a71ae949bd', 'ru', 'Запечённый лосось с йогуртово-укропным соусом', 'Сочное филе лосося, запечённое на раскалённом противне, с прохладным соусом из йогурта, укропа, зелёного лука, чеснока и лимона.', '<ol><li>Соус: смешайте йогурт, лимонный сок, укроп и зелёный лук. Чеснок слегка раздавите, добавьте в соус и перед подачей достаньте (так вкус будет мягким) или натрите для более яркого вкуса. Посолите и поперчите.</li><li>Разогрейте духовку до 260 °C, поставив в неё пустой противень с бортами на 10 минут.</li><li>Посолите и поперчите филе и натрите маслом со всех сторон.</li><li>Выложите лосось кожей вниз на раскалённый противень (кожа сразу зашипит). Верните в духовку, понизьте температуру до 120 °C и запекайте 12–15 минут.</li><li>Подавайте лосось с йогуртовым соусом.</li></ol><p><em>Подавайте с отварным картофелем или салатом. В соус можно добавить мелко нарубленные каперсы.</em></p>', CURRENT_TIMESTAMP),
  ('d11bd93f-5690-5906-9ee4-5c2254db6eee', 'bac0eae4-1637-51d5-9df8-d6a71ae949bd', 'en', 'Roasted salmon with yogurt dill sauce', 'Tender salmon fillets roasted on a hot sheet pan and served with a cool yogurt sauce with dill, chives, garlic and lemon.', '<ol><li>Sauce: stir together the yogurt, lemon juice, dill and chives. Lightly smash the garlic and add it, removing it before serving for a mild flavor, or grate it for a stronger taste. Season with salt and pepper.</li><li>Preheat the oven to 500 °F (260 °C) with an empty rimmed baking sheet inside for about 10 minutes.</li><li>Season each fillet with salt and pepper and rub with oil all over.</li><li>Place the salmon skin-side down on the hot sheet (it will sizzle). Return to the oven, reduce the heat to 250 °F (120 °C) and roast 12–15 minutes.</li><li>Serve the salmon with the yogurt sauce.</li></ol><p><em>Serve with boiled potatoes or a salad. Minced capers are a good addition to the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('a2feccc0-5676-54d9-b8a4-8611d8145b5f', '57fb74f7-e3d7-5650-94e7-d7b1c4abde96', 'ru', 'Орзо с кабачком, грибами и пармезаном', 'Мелкая паста орзо с обжаренными луком, шампиньонами и кабачком, чесноком, петрушкой и тёртым пармезаном.', '<ol><li>Доведите до кипения большую кастрюлю подсоленной воды и отварите орзо до желаемой мягкости (необязательно по времени на упаковке).</li><li>Пока варится паста, растопите масло на сковороде и 3–5 минут обжаривайте лук с солью и перцем до мягкости.</li><li>Добавьте грибы и чеснок, посолите и поперчите и готовьте 5–8 минут, пока вся жидкость не выпарится и грибы не станут золотистыми.</li><li>Положите кабачок и готовьте всего 3 минуты, чтобы он остался плотным и не развалился.</li><li>Слейте воду с орзо, смешайте с овощами и грибами, добавьте пармезан и петрушку и подавайте горячим.</li></ol><p><em>Хороша как гарнир, а с курицей или креветками превращается в полноценный ужин.</em></p>', CURRENT_TIMESTAMP),
  ('3c0915b5-f42f-5be1-9521-cacb68bb0ebe', '57fb74f7-e3d7-5650-94e7-d7b1c4abde96', 'en', 'Zucchini and mushroom orzo with parmesan', 'Orzo pasta tossed with sautéed onion, mushrooms and zucchini, garlic, fresh parsley and grated parmesan.', '<ol><li>Bring a large pot of salted water to a boil and cook the orzo to your preferred doneness, not necessarily by the package time.</li><li>Meanwhile melt the butter in a skillet and cook the onion with salt and pepper 3–5 minutes until soft.</li><li>Add the mushrooms and garlic, season and cook 5–8 minutes until the liquid cooks off and the mushrooms turn golden.</li><li>Add the zucchini and cook only about 3 minutes so it stays firm and doesn''t get watery.</li><li>Drain the orzo, combine with the vegetables and mushrooms, stir in the parmesan and parsley and serve hot.</li></ol><p><em>Serve as a side, or add chicken or shrimp for a complete meal.</em></p>', CURRENT_TIMESTAMP),
  ('60dbfbfa-f672-5dd3-9471-e378d5b808ad', '34a10b5e-5fb1-51ef-8fa6-525c83d6f6a8', 'ru', 'Сливочный суп-пюре из спаржи с картофелем', 'Нежный суп-пюре из свежей спаржи и картофеля на курином бульоне со сливками. Верхушки спаржи обжариваются отдельно для подачи.', '<ol><li>Обломайте у спаржи жёсткие нижние концы (она ломается в нужном месте) и отрежьте по первой обломанной стеблине. Отделите верхушки, остальное нарежьте кусочками по 5 см.</li><li>В кастрюле растопите масло, обжарьте лук с солью около 5 минут до мягкости и золотистого цвета, затем добавьте чеснок на 30 секунд.</li><li>Добавьте спаржу (кроме верхушек) и картофель, готовьте около 3 минут, затем влейте бульон и варите около 20 минут до мягкости картофеля.</li><li>Тем временем на сковороде обжарьте верхушки спаржи в небольшом количестве масла до лёгкого золотистого цвета, влейте пару ложек бульона или воды, накройте и готовьте 2–3 минуты, пока жидкость не испарится.</li><li>Пюрируйте суп блендером порциями, верните в кастрюлю, добавьте сливки, посолите и поперчите. Подавайте с обжаренными верхушками.</li></ol><p><em>Подавайте с вершинками спаржи, гренками и щепоткой пармезана.</em></p>', CURRENT_TIMESTAMP),
  ('75637391-cda9-5ef1-bcd6-99f4e5d2c0f2', '34a10b5e-5fb1-51ef-8fa6-525c83d6f6a8', 'en', 'Creamy asparagus and potato soup', 'Velvety purée of fresh asparagus and potato in chicken broth finished with cream, garnished with sautéed asparagus tips.', '<ol><li>Snap off the woody ends of the asparagus and use the first stalk as a guide to trim the rest. Cut off the tips and save them, cut the remaining stalks into 2-inch pieces.</li><li>Melt the butter in a pot and cook the onion with salt about 5 minutes until tender and lightly golden, then add the garlic for 30 seconds.</li><li>Add the asparagus (except the tips) and potatoes, cook about 3 minutes, then pour in the broth and cook about 20 minutes until the potatoes are tender.</li><li>Meanwhile sauté the asparagus tips in a little oil until slightly golden, add a few tablespoons broth or water, cover and cook 2–3 minutes until the liquid evaporates.</li><li>Purée the soup in batches in a blender, return to the pot, add the cream and season to taste. Serve garnished with the asparagus tips.</li></ol><p><em>Garnish with the asparagus tips, croutons and a little parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('61f8a430-2e66-59b8-b4db-4dcbe734126b', '7e39c2fe-eb18-57b6-9dca-fe31361c2a7c', 'ru', 'Сливочный томатный суп-пюре из запечённых помидоров', 'Густой суп-пюре из запечённых с чесноком и травами помидоров, обжаренных лука, томатной пасты и муки на бульоне со сливками.', '<ol><li>Разогрейте духовку до 200 °C, застелите противень с бортами фольгой. Слейте сок из консервированных помидоров (сок сохраните), помидоры разложите на противне.</li><li>Посыпьте коричневым сахаром, итальянскими травами, луковой солью, солью и перцем, добавьте половину чеснока и сбрызните оливковым маслом. Запекайте 30–45 минут, пока помидоры не станут тёмно-золотистыми и почти подгоревшими в местах.</li><li>В кастрюле растопите масло, обжарьте лук с солью около 5 минут до мягкости, добавьте оставшийся чеснок на 30 секунд. Положите томатную пасту и муку и перемешайте, готовьте минуту.</li><li>Понемногу влейте часть бульона (или сока из банки), энергично размешивая, чтобы не было комков. Затем влейте остальной бульон, добавьте запечённые помидоры, доведите до кипения и варите на слабом огне 15 минут.</li><li>Пюрируйте суп блендером порциями, верните в кастрюлю, влейте сливки и прогрейте. Подавайте с рубленой петрушкой и базиликом.</li></ol><p><em>Посыпьте свежей петрушкой и базиликом и подайте с гренками или сэндвичем с сыром.</em></p>', CURRENT_TIMESTAMP),
  ('9a3dcf07-9cf1-579e-88a9-481870120349', '7e39c2fe-eb18-57b6-9dca-fe31361c2a7c', 'en', 'Creamy roasted tomato soup', 'Thick tomato soup made from oven-roasted tomatoes with garlic and herbs, sautéed onion, tomato paste and flour, simmered in broth and finished with cream.', '<ol><li>Preheat the oven to 400 °F (200 °C) and line a rimmed baking sheet with foil. Drain the canned tomatoes, saving the juice, and spread them on the pan.</li><li>Sprinkle with the brown sugar, dried herbs, onion salt, salt and pepper, add half the garlic and drizzle with olive oil. Roast 30–45 minutes until dark gold and almost charred in spots.</li><li>Melt the butter in a pot and cook the onion with salt about 5 minutes until tender, add the remaining garlic for 30 seconds, then stir in the tomato paste and flour and cook 1 minute.</li><li>Add a little of the broth or reserved tomato juice, whisking vigorously to prevent lumps, then pour in the rest with the roasted tomatoes. Bring to a boil and simmer 15 minutes.</li><li>Purée the soup in batches, return to the pot, stir in the cream and warm through. Serve garnished with parsley and basil.</li></ol><p><em>Garnish with parsley and basil and serve with croutons or a grilled cheese sandwich.</em></p>', CURRENT_TIMESTAMP),
  ('e59932b9-93e5-5275-8cda-87539c512a77', '5c0c22ee-da78-5216-9e0d-d069b570430f', 'ru', 'Кукурузный суп-чаудер с картофелем и сметаной', 'Густой овощной суп с кукурузой, картофелем, красным перцем и сельдереем. Часть супа пюрируют с маслом, а в конце добавляют сметану, кинзу и лайм.', '<ol><li>В кастрюле с толстым дном разогрейте оливковое масло на среднем огне. Добавьте кукурузу, картофель, лук, перцы, сельдерей, ½ ч. л. соли и ½ ч. л. чили и готовьте 7–10 минут до мягкости лука, помешивая.</li><li>Добавьте чеснок на 30–60 секунд, влейте бульон и воду, положите лавровый лист.</li><li>Доведите до кипения, убавьте огонь и варите 20–25 минут, пока картофель не станет полностью мягким.</li><li>Снимите с огня, выньте лавровый лист. Около 3 стаканов супа (половина жидкости, половина овощей) переложите в блендер, взбейте до гладкости, добавьте сливочное масло и взбейте ещё раз.</li><li>Верните пюре в кастрюлю, добавьте кинзу, сметану и сок лайма. Досолите оставшейся солью, поперчите, при желании добавьте чили. Разлейте по тарелкам и украсьте.</li></ol><p><em>Посыпьте тёртым сыром, зелёным луком и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('b3e499b6-4f54-5308-b57e-12a279270e32', '5c0c22ee-da78-5216-9e0d-d069b570430f', 'en', 'Southwestern vegetarian corn chowder', 'Hearty vegetable soup with sweet corn, potatoes, red pepper and celery, partly puréed with butter and finished with sour cream, cilantro and lime.', '<ol><li>In a Dutch oven warm the olive oil over medium heat. Add the corn, potatoes, onion, peppers, celery, ½ tsp of the salt and ½ tsp chili powder and cook 7–10 minutes, stirring, until the onion is tender.</li><li>Add the garlic for 30–60 seconds, then pour in the broth and water and add the bay leaf.</li><li>Bring to a boil, reduce to a gentle simmer and cook 20–25 minutes until the potatoes are fully tender.</li><li>Remove from the heat and take out the bay leaf. Blend about 3 cups of the soup (half liquid, half solids) until smooth, add the butter and blend again.</li><li>Pour the purée back into the pot, add the cilantro, sour cream and lime juice, season with the remaining salt and pepper (and more chili if you like) and serve with your chosen garnishes.</li></ol><p><em>Top with shredded cheddar, green onion and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('0b656149-afd7-530e-bfdf-f006491579b6', 'a0f73231-963c-505a-86d6-b2672bdb4e36', 'ru', 'Чечевичный салат с морковью, укропом и тахини', 'Салат из чёрной чечевицы с тёртой морковью, сельдереем, зеленью и маринованным перцем в заправке из оливкового масла, лимона, укропа и тахини.', '<ol><li>Доведите до кипения кастрюлю воды. Промойте чечевицу под проточной водой в мелком сите до прозрачной воды.</li><li>Всыпьте чечевицу, добавьте лавровый лист и соль и варите около 16 минут на активном кипении, пока она не станет мягкой, но не разваренной. Слейте воду и выбросьте лавровый лист.</li><li>Пока варится чечевица, взбейте в блендере оливковое масло, лимонный сок, укроп, тахини, чеснок, соль, хлопья чили и чёрный перец до гладкости.</li><li>Переложите чечевицу в миску, залейте заправкой. Добавьте тёртую морковь, петрушку, оставшийся укроп, сельдерей, зелёный лук и маринованный перец и перемешайте. Попробуйте и добавьте соль, перец или лимонный сок.</li></ol><p><em>Дайте салату постоять 20 минут перед подачей. Хранится в холодильнике до 4 дней.</em></p>', CURRENT_TIMESTAMP),
  ('1cba0482-c31b-548d-9971-b6dbb6be7f9a', 'a0f73231-963c-505a-86d6-b2672bdb4e36', 'en', 'Tangy lentil salad with carrot, dill and tahini dressing', 'Black lentil salad with grated carrots, celery, fresh herbs and pickled pepperoncini in an olive oil, lemon, dill and tahini dressing.', '<ol><li>Bring a saucepan of water to a boil. Meanwhile, sort and rinse the lentils in a fine-mesh sieve until the water runs clear.</li><li>Add the lentils, bay leaf and salt and cook about 16 minutes at a lively simmer until tender but not mushy. Drain and discard the bay leaf.</li><li>While the lentils cook, blend the olive oil, lemon juice, dill, tahini, garlic, salt, chili flakes and black pepper until smooth.</li><li>Place the lentils in a bowl, pour in the dressing and add the grated carrots, parsley, remaining dill, celery, green onion and pepperoncini. Stir and adjust salt, pepper and lemon juice to taste.</li></ol><p><em>Rest 20 minutes before serving. Keeps up to 4 days in the fridge.</em></p>', CURRENT_TIMESTAMP),
  ('f0d4a694-744b-5dfa-a906-0b03a3e27760', '289cbe3b-1a7b-5858-9ac5-e09be756234f', 'ru', 'Лёгкий крем-суп из брокколи', 'Бархатистый суп-пюре из брокколи с луком и чесноком на сливочном масле. Без муки и сливок, с лёгкой лимонной кислинкой.', '<ol><li>В кастрюле растопите 3 ст. л. масла на средне-слабом огне. Добавьте лук, чеснок, ¼ ч. л. соли и перец, накройте и тушите 8–10 минут, пока лук не станет мягким и слегка золотистым.</li><li>Тем временем срежьте жёсткие концы стеблей брокколи, очистите стебли от кожицы и нарежьте кусочками по 2–4 см. Соцветия отделите и отложите.</li><li>Положите в кастрюлю стебли, влейте воду, добавьте оставшуюся соль. Доведите до кипения, убавьте огонь, накройте и варите 20–25 минут, пока стебли не станут мягкими.</li><li>Мелко порубите соцветия и добавьте в суп. Варите под крышкой 4–7 минут, пока они не станут ярко-зелёными и мягкими. Снимите с огня и добавьте оставшуюся ложку масла.</li><li>Пюрируйте суп порциями в блендере (или погружным блендером) до однородности и верните в кастрюлю. Добавьте лимонный сок и при необходимости соль и перец.</li></ol><p><em>Подавайте с каплей сливок и рубленым зелёным луком или шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('70d127d8-6cd1-532f-a54f-439d35f84d03', '289cbe3b-1a7b-5858-9ac5-e09be756234f', 'en', 'Light cream of broccoli soup', 'Velvety broccoli purée soup with onion and garlic cooked in butter, with no flour or cream needed and a squeeze of lemon.', '<ol><li>Melt 3 tbsp of the butter in a large pot over medium-low heat. Add the onion, garlic, ¼ tsp salt and pepper, cover and cook 8–10 minutes until the onion is soft and just turning golden.</li><li>Meanwhile trim and peel the broccoli stalks and cut them into 1–2 inch pieces. Cut off the florets and set aside.</li><li>Add the stalks to the pot with the water and remaining salt. Bring to a boil, reduce the heat, cover and simmer 20–25 minutes until the stalks are tender.</li><li>Chop the florets small and add them to the soup. Cook covered 4–7 minutes until bright green and tender, then remove from the heat and stir in the last tablespoon of butter.</li><li>Purée the soup in batches in a blender (or with an immersion blender) until smooth and return to the pot. Add the lemon juice and adjust salt and pepper.</li></ol><p><em>Garnish with a drizzle of cream and snipped chives.</em></p>', CURRENT_TIMESTAMP),
  ('ad336b92-ca28-55e3-8030-6632919a613b', '33237379-4696-516e-babb-e625fbf4332b', 'ru', 'Крем-суп из запечённой моркови', 'Насыщенный суп-пюре из карамелизованной в духовке моркови с луком, чесноком, кориандром и зирой. Кремовая текстура получается без сливок.', '<ol><li>Разогрейте духовку до 200 °C. Очистите морковь и нарежьте по диагонали кусочками толщиной около 1,3 см.</li><li>Выложите морковь на противень, добавьте 2 ст. л. масла и ½ ч. л. соли, перемешайте и разложите в один слой. Запекайте 25–40 минут, перемешав на середине, пока морковь не карамелизуется по краям и не станет мягкой.</li><li>Когда морковь почти готова, разогрейте оставшуюся ложку масла в кастрюле, обжарьте лук с ¼ ч. л. соли 5–7 минут до прозрачности. Добавьте чеснок, кориандр и зиру на 30–60 секунд.</li><li>Влейте бульон и воду, соскребая налёт со дна, добавьте запечённую морковь и варите на слабом огне 15 минут.</li><li>Дайте супу немного остыть, затем пюрируйте порциями в блендере с маслом, лимонным соком и перцем до гладкости. Досолите и подавайте.</li></ol><p><em>Подайте с гренками или хлебом с семечками.</em></p>', CURRENT_TIMESTAMP),
  ('5a37475e-80ce-5129-b29d-650dc7fb3066', '33237379-4696-516e-babb-e625fbf4332b', 'en', 'Creamy roasted carrot soup', 'Rich roasted carrot soup with onion, garlic, coriander and cumin, ultra creamy without any cream.', '<ol><li>Preheat the oven to 400 °F (200 °C). Peel the carrots and cut them on the diagonal about ½ inch thick.</li><li>Spread the carrots on a baking sheet with 2 tbsp oil and ½ tsp salt, toss and arrange in a single layer. Roast 25–40 minutes, tossing halfway, until caramelized at the edges and tender.</li><li>When the carrots are almost done warm the remaining tablespoon of oil in a pot and cook the onion with ¼ tsp salt 5–7 minutes until translucent. Add the garlic, coriander and cumin for 30–60 seconds.</li><li>Pour in the broth and water, scraping up the browned bits, add the roasted carrots and simmer 15 minutes.</li><li>Let the soup cool a few minutes, then blend in batches with the butter, lemon juice and pepper until completely smooth. Adjust salt and serve.</li></ol><p><em>Serve with croutons or seeded bread.</em></p>', CURRENT_TIMESTAMP),
  ('7e7a27a1-5a76-5cbb-8a36-c76404e30b91', '99023390-25f0-547b-bdfa-6366732db0f7', 'ru', 'Картофельный гратен по-дофински со сливками и грюйером', 'Запеканка из тонко нарезанного картофеля, сливок с чесноком и мускатным орехом и тёртого сыра грюйер, запечённая до румяной корочки.', '<ol><li>Разогрейте духовку до 220 °C. Очистите картофель и нарежьте как можно тоньше, ломтиками около 3 мм.</li><li>В мерной кружке взбейте сливки с чесноком, солью, перцем и мускатным орехом.</li><li>Выложите треть картофеля чешуйками в квадратную форму 23 см, полейте третью сливочной смеси (предварительно взбив) и посыпьте ⅙ частью сыра. Повторите ещё дважды, оставшийся сыр выложите сверху.</li><li>Запекайте 40 минут, затем накройте фольгой или пергаментом, чтобы верх не пересох, и запекайте ещё 5–10 минут, пока вилка не будет проходить через картофель без усилий.</li><li>Дайте остыть минимум 20 минут, посыпьте шнитт-луком и подавайте тёплым.</li></ol><p><em>Дайте остыть 20 минут, подавайте как гарнир к мясу или птице.</em></p>', CURRENT_TIMESTAMP),
  ('8e3014bb-8c25-5ad0-8c45-2974634a95fe', '99023390-25f0-547b-bdfa-6366732db0f7', 'en', 'Potato gratin dauphinois with Gruyère', 'Thinly sliced potatoes layered with garlic-nutmeg cream and grated Gruyère, baked until golden and bubbling.', '<ol><li>Preheat the oven to 425 °F (220 °C). Peel the potatoes and slice them as thinly as possible, about ⅛ inch (3 mm).</li><li>In a liquid measuring cup whisk the cream with the garlic, salt, pepper and nutmeg.</li><li>Arrange a third of the potatoes in an overlapping fish-scale pattern in a 9-inch square dish, pour over a third of the cream mixture (re-whisked) and sprinkle with some of the cheese. Repeat twice more and top with all the remaining cheese.</li><li>Bake 40 minutes, then cover with parchment or foil to prevent over-browning and bake 5–10 more minutes until a fork goes through the potatoes easily.</li><li>Let cool at least 20 minutes, sprinkle with chives and serve warm.</li></ol><p><em>Let it cool 20 minutes and serve as a side for meat or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('fb687f26-4bf1-5a62-92bd-28faf6102a24', '715a1f3b-5180-5831-8c03-a6a5799995da', 'ru', 'Запечённая морковь с фарро, нутом и сметанным соусом с травами', 'Тёплое блюдо из фарро с нутом, запечённой в духовке молодой моркови, пряных тыквенных семечек и сметанной заправки с петрушкой.', '<ol><li>Промытое фарро залейте водой с запасом на несколько сантиметров, доведите до кипения и варите на слабом огне около 15 минут (шлифованное) до мягкости, но с упругостью. Слейте воду.</li><li>Верните фарро в кастрюлю, добавьте 1 ч. л. масла, лимонный сок, чеснок и ½ ч. л. соли, перемешайте и добавьте нут. Накройте и отложите.</li><li>Разогрейте духовку до 220 °C. Выложите морковь на противень с пергаментом, сбрызните 1 ст. л. масла, посыпьте зирой, солью и перцем и перемешайте. Запекайте 20–35 минут, пока морковь не станет мягкой (тонкие достаньте раньше).</li><li>Обжарьте тыквенные семечки в небольшой сковороде с ½ ч. л. масла, щепоткой зиры, чили и соли, помешивая, до золотистых краёв и лёгкого потрескивания. Остудите.</li><li>Смешайте сметану с 1 ст. л. петрушки, водой, солью и перцем. Выложите фарро с нутом на блюдо, сверху морковь, полейте соусом и посыпьте семечками и оставшейся петрушкой.</li></ol><p><em>Подойдёт как основное блюдо на ужин или как гарнир на праздничном столе.</em></p>', CURRENT_TIMESTAMP),
  ('1030cebd-34b6-563e-b498-59092daf7a99', '715a1f3b-5180-5831-8c03-a6a5799995da', 'en', 'Roasted carrots with farro, chickpeas and herbed crème fraîche', 'Warm farro and chickpeas topped with oven-roasted carrots, spiced toasted pepitas and a herbed sour cream drizzle.', '<ol><li>Cover the rinsed farro with water by a couple of inches, bring to a boil, then simmer about 15 minutes (pearled) until tender but still chewy. Drain.</li><li>Return the farro to the pot, mix with 1 tsp olive oil, the lemon juice, garlic and ½ tsp salt, then stir in the chickpeas. Cover and set aside.</li><li>Preheat the oven to 425 °F (220 °C). Put the carrots on a parchment-lined baking sheet, drizzle with 1 tbsp oil, sprinkle with cumin, salt and pepper and toss. Roast 20–35 minutes until tender, taking out thinner ones sooner.</li><li>Toast the pepitas in a small skillet with ½ tsp oil and pinches of cumin, chili powder and salt, stirring, until golden at the edges and starting to pop. Cool.</li><li>Stir the sour cream with 1 tbsp parsley, water, salt and pepper. Pile the farro and chickpeas on a platter, arrange the carrots on top, drizzle with the sauce and sprinkle with the pepitas and remaining parsley.</li></ol><p><em>Works as a vegetarian main for dinner or a side on a holiday table.</em></p>', CURRENT_TIMESTAMP),
  ('71e8c55d-645b-5e69-b8c7-6e4222cbb429', 'f7f9b84d-d25f-5347-aae9-cf47f5ff8dcd', 'ru', 'Курица по-мароккански с оливками, лимоном и сухофруктами', 'Нежная курица на кости, тушёная с рас-эль-ханутом, луком, чесноком, лимоном, оливками, изюмом и курагой в томатном бульоне.', '<ol><li>Смешайте рас-эль-ханут, корицу, паприку, имбирь и перец для натирания.</li><li>Обсушите курицу, слегка посолите и натрите смесью специй со всех сторон (и под кожей). Оставьте на 40–45 минут при комнатной температуре или на 2 часа – ночь в холодильнике.</li><li>В глубокой сковороде или сотейнике разогрейте 2 ст. л. масла на средне-сильном огне. Обжарьте курицу кожей вниз 5 минут, затем с другой стороны около 3 минут.</li><li>Убавьте огонь до средне-слабого, добавьте лук, чеснок и кинзу, накройте и готовьте 3 минуты. Положите ломтики лимона, оливки, изюм и курагу.</li><li>Смешайте томатную пасту с бульоном и вылейте поверх курицы. Доведите до слабого кипения на 5 минут, затем под крышкой тушите на медленном огне 30–45 минут, пока курица не станет мягкой (80 °C и выше внутри).</li><li>Посыпьте кинзой и миндалём и подавайте с кускусом.</li></ol><p><em>Подайте с кускусом, посыпав кинзой и подсушенным миндалём.</em></p>', CURRENT_TIMESTAMP),
  ('88bffe18-bfca-58b1-b504-28ccafd6bede', 'f7f9b84d-d25f-5347-aae9-cf47f5ff8dcd', 'en', 'Moroccan chicken with olives, lemon and dried fruit', 'Fall-off-the-bone chicken stewed with ras el hanout, onion, garlic, lemon, olives, raisins and dried apricots in a tomato broth.', '<ol><li>Mix the ras el hanout, cinnamon, paprika, ginger and pepper into a rub.</li><li>Pat the chicken dry, season lightly with salt and rub all over with the spices (under the skin too). Leave 40–45 minutes at room temperature, or 2 hours to overnight in the fridge.</li><li>In a deep pan heat 2 tbsp of oil over medium-high. Brown the chicken skin-side down for 5 minutes, then about 3 minutes on the other side.</li><li>Lower the heat to medium-low, add the onion, garlic and cilantro, cover and cook 3 minutes. Add the lemon slices, olives, raisins and apricots.</li><li>Mix the tomato paste with the broth and pour over the chicken. Simmer 5 minutes, then cover and cook on medium-low 30–45 minutes until tender and cooked through (at least 165 °F / 74 °C inside).</li><li>Garnish with cilantro and almonds and serve with couscous.</li></ol><p><em>Serve over couscous with cilantro and toasted almonds.</em></p>', CURRENT_TIMESTAMP),
  ('477cc918-00a3-5aa2-a675-760879ca35e3', '023ecb16-d150-5c89-b312-0702bc21cd70', 'ru', 'Харира — марокканский суп с чечевицей и нутом', 'Густой пряный постный суп из двух видов чечевицы, нута, томатов, кинзы и риса с корицей, куркумой и зирой. На следующий день ещё вкуснее.', '<ol><li>В большой кастрюле с толстым дном разогрейте 4 ст. л. оливкового масла на среднем огне. Обжарьте лук, сельдерей и морковь с щепоткой соли около 5 минут до мягкости.</li><li>Добавьте чеснок и специи и готовьте 1–2 минуты, помешивая.</li><li>Положите измельчённые томаты, томатную пасту, кинзу, обе чечевицы и нут. Посолите и готовьте 5 минут, помешивая.</li><li>Влейте бульон, доведите до кипения на 5 минут, затем убавьте огонь, накройте и варите около 45 минут, пока бобовые не станут очень мягкими. При необходимости добавляйте бульон или воду: суп густой, но должен переливаться.</li><li>Добавьте рис и варите ещё около 15 минут до готовности. Подавайте с лимоном.</li></ol><p><em>Подайте с дольками лимона и тёплой питой.</em></p>', CURRENT_TIMESTAMP),
  ('7eaef24a-6ca6-58c4-a1c2-66dddac5583b', '023ecb16-d150-5c89-b312-0702bc21cd70', 'en', 'Harira (Moroccan lentil and chickpea soup)', 'A thick, warmly spiced vegan soup of two kinds of lentils, chickpeas, tomatoes, cilantro and rice with cinnamon, turmeric and cumin. Even better the next day.', '<ol><li>In a large Dutch oven heat 4 tbsp of olive oil over medium heat. Sauté the onion, celery and carrot with a pinch of salt for about 5 minutes until softened.</li><li>Add the garlic and spices and cook 1–2 minutes, stirring.</li><li>Add the crushed tomatoes, tomato paste, cilantro, both lentils and the chickpeas. Add salt and cook 5 minutes, stirring.</li><li>Pour in the stock, boil 5 minutes, then reduce the heat, cover and simmer about 45 minutes until the legumes are very tender. Add more stock or water if needed: the soup should be thick but pourable.</li><li>Stir in the rice and cook another 15 minutes until done. Serve with lemon wedges.</li></ol><p><em>Serve with lemon wedges and warm pita.</em></p>', CURRENT_TIMESTAMP),
  ('1a115f14-82f4-535a-a24c-dc426733460a', 'caf770a0-73e1-5888-822b-c3307d5a3465', 'ru', 'Минестроне с итальянскими колбасками', 'Сытный суп с острыми колбасками, стручковой фасолью, артишоками, нутом, томатами и мелкой пастой, с базиликом и пармезаном.', '<ol><li>Обжарьте колбасный фарш без оболочки на сковороде на средне-сильном огне до полной готовности, отложите.</li><li>В большой кастрюле разогрейте 2 ст. л. масла, 2–3 минуты обжарьте лук и сельдерей, добавьте чеснок на несколько секунд.</li><li>Добавьте стручковую фасоль, артишоки, томаты, орегано, соль и перец, готовьте 5 минут. Верните колбасу, влейте бульон и варите на сильном огне ещё 10 минут.</li><li>Убавьте огонь, накройте и варите 15 минут. Откройте, добавьте пасту, нут и петрушку, усильте огонь и варите без крышки 8–9 минут до состояния аль денте.</li><li>Снимите с огня, вмешайте базилик. Разлейте по тарелкам и посыпьте пармезаном.</li></ol><p><em>Подайте со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('a1ac234c-6313-5dbd-9a99-cb34b95e55d5', 'caf770a0-73e1-5888-822b-c3307d5a3465', 'en', 'Italian sausage minestrone', 'A hearty soup of spicy sausage, green beans, artichokes, chickpeas, tomatoes and small pasta, finished with basil and Parmesan.', '<ol><li>Brown the sausage meat without casings in a pan over medium-high heat until fully cooked and set aside.</li><li>In a large pot heat 2 tbsp of oil and sauté the onion and celery 2–3 minutes, then add the garlic for a few seconds.</li><li>Add the green beans, artichokes, tomatoes, oregano, salt and pepper and cook 5 minutes. Return the sausage, add the broth and cook on medium-high for 10 more minutes.</li><li>Lower the heat, cover and simmer 15 minutes. Uncover, add the pasta, chickpeas and parsley, raise the heat and cook uncovered 8–9 minutes until al dente.</li><li>Remove from the heat and stir in the basil. Ladle into bowls and top with Parmesan.</li></ol><p><em>Serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('7922143e-8720-564a-88f4-6e11b22bcc3e', 'e45a1812-2ce3-5ed5-a879-775dfc84fa51', 'ru', 'Паста э фаджоли — суп с пастой и двумя видами фасоли', 'Густой рустикальный итальянский суп с мелкой пастой, белой и красной фасолью, копчёными томатами, овощами и базиликом. Ужин за 35 минут из доступных продуктов.', '<ol><li>Отварите пасту в подсоленной воде по инструкции на упаковке, хорошо слейте воду и отложите.</li><li>В кастрюле разогрейте 2 ст. л. масла на средне-сильном огне, 4 минуты обжарьте лук, сельдерей и морковь до мягкости. Добавьте чеснок, лавровый лист и орегано, ещё 2 минуты.</li><li>Добавьте томаты, бульон, обе фасоли, соль и перец. Доведите до кипения, убавьте огонь и варите под неплотно закрытой крышкой 10–15 минут.</li><li>Добавьте пасту и прогрейте. Снимите с огня, вмешайте базилик, выньте лавровый лист. Подавайте с пармезаном и острым перцем по желанию.</li></ol><p><em>Посыпьте пармезаном и подайте с итальянским хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('b92503ef-91b6-5e55-8776-c84d5e0983a6', 'e45a1812-2ce3-5ed5-a879-775dfc84fa51', 'en', 'Pasta fagioli with two beans', 'A hearty, rustic Italian soup of small pasta, white and red beans, fire-roasted tomatoes, vegetables and basil. Ready in about 35 minutes from pantry staples.', '<ol><li>Cook the pasta in boiling salted water according to the package, drain well and set aside.</li><li>Heat 2 tbsp of oil in a Dutch oven over medium-high and sauté the onion, celery and carrots about 4 minutes until softening. Add the garlic, bay leaf and oregano for another 2 minutes.</li><li>Add the tomatoes, broth, both beans, salt and pepper. Bring to a boil, reduce to a simmer and cook with the lid slightly ajar for 10–15 minutes.</li><li>Stir in the pasta to warm through. Remove from the heat, add the basil and discard the bay leaf. Serve with Parmesan and crushed red pepper if you like.</li></ol><p><em>Top with grated Parmesan and serve with Italian bread.</em></p>', CURRENT_TIMESTAMP),
  ('205c119a-8109-5f79-a1b8-86a322964fa5', '4bad6ddf-1046-5dba-a1cf-567370d0c9d6', 'ru', 'Картофельный салат с тунцом и стручковой фасолью', 'Тёплый салат из молодого картофеля, стручковой фасоли, помидоров и тунца с копчёной паприкой, зирой и уксусной заправкой на оливковом масле. Напоминает нисуаз.', '<ol><li>Положите мелкий картофель в кастрюлю, залейте водой и варите около 10 минут до мягкости. Выньте шумовкой, воду не выливайте.</li><li>В кипящую воду положите стручковую фасоль на 4 минуты, затем сразу перенесите в ледяную воду, чтобы сохранить цвет. Обсушите.</li><li>Разрежьте картофель пополам и переложите в большую миску. Добавьте фасоль, помидоры, лук, раскрошенный тунец и чеснок.</li><li>Приправьте солью, перцем, паприкой, зирой и хлопьями чили. Смешайте масло с уксусом, добавьте в салат и аккуратно перемешайте. Попробуйте и откорректируйте специи.</li><li>Выложите на блюдо с зелёными листьями и подавайте.</li></ol><p><em>Выложите на подушку из салатных листьев.</em></p>', CURRENT_TIMESTAMP),
  ('83db507f-cca3-57ea-b666-dda410aefbe7', '4bad6ddf-1046-5dba-a1cf-567370d0c9d6', 'en', 'Potato salad with tuna and green beans', 'A flavour-packed salad of baby potatoes, green beans, tomatoes and tuna with smoked paprika, cumin and an olive oil and vinegar dressing. Reminiscent of Niçoise.', '<ol><li>Put the small potatoes in a pot, cover with water and boil about 10 minutes until a fork goes through. Lift out with a slotted spoon and keep the water.</li><li>Add the green beans to the boiling water for about 4 minutes, then move straight to an ice bath to keep the colour. Pat dry.</li><li>Halve the potatoes and put them in a large bowl. Add the beans, tomatoes, onions, crumbled tuna and garlic.</li><li>Season with salt, pepper, paprika, cumin and chilli flakes. Whisk the oil and vinegar, pour over and toss gently. Taste and adjust the seasoning.</li><li>Arrange on a platter of salad greens and serve.</li></ol><p><em>Serve on a bed of lettuce or spring greens.</em></p>', CURRENT_TIMESTAMP),
  ('df41645d-e831-5f7d-9c1e-b6ac00d47d1e', 'cad90ff4-2e6b-5c64-b026-9035e83b8a6c', 'ru', 'Менемен — турецкая яичница с помидорами и перцем', 'Нежная яичница-болтунья с помидорами, болгарским перцем и луком, приготовленная в одной сковороде за 25 минут.', '<ol><li>В сковороде диаметром 25 см на среднем огне разогрейте масло. Обжарьте лук и перец с солью 4–5 минут до мягкости, не давая луку подрумяниться.</li><li>Добавьте помидоры и томатную пасту, соль, перец, орегано и алеппо. Готовьте 5–7 минут, пока помидоры не станут мягкими, но сохранят форму.</li><li>Сдвиньте овощи в сторону, убавьте огонь, влейте взбитые яйца и мягко помешивайте, пока они едва схватятся. Перемешайте с овощами.</li><li>Сбрызните маслом, добавьте алеппо и хлопья чили по желанию и сразу подавайте с хлебом.</li></ol><p><em>Подайте с толстыми ломтями хлеба.</em></p>', CURRENT_TIMESTAMP),
  ('88179f48-4ab5-5055-bf64-2b07abcd6007', 'cad90ff4-2e6b-5c64-b026-9035e83b8a6c', 'en', 'Menemen (Turkish scrambled eggs with tomatoes)', 'Soft scrambled eggs with tomatoes, bell peppers and onions, made in one pan in about 25 minutes.', '<ol><li>In a 10-inch skillet heat the oil over medium. Cook the onion and pepper with salt for 4–5 minutes until softened, without browning the onion.</li><li>Add the tomatoes and tomato paste, salt, pepper, oregano and Aleppo pepper. Cook 5–7 minutes until the tomatoes soften but hold their shape.</li><li>Push the vegetables to one side, lower the heat, add the beaten eggs and stir gently until just set. Fold in the vegetables.</li><li>Finish with a little oil, more Aleppo pepper and chilli flakes if you like, and serve immediately with bread.</li></ol><p><em>Serve with thick slices of crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('1a90f06a-c22e-52d3-b968-664f4f9f60b1', '6d8b3648-85b6-5b48-9bf3-50e712603afa', 'ru', 'Оладьи из цветной капусты с зирой и мятным йогуртом', 'Пышные оладьи из отварной цветной капусты с петрушкой, луком и тёплыми специями, обжаренные в масле. Подаются с йогуртом с мятой и лимоном.', '<ol><li>Для соуса смешайте йогурт, сушёную мяту, лимонный сок, масло и соль, уберите в холодильник.</li><li>Разберите цветную капусту на соцветия по 4 см, варите в подсоленной воде 4 минуты. Слейте воду в дуршлаг, оставив 3–4 ст. л. отвара.</li><li>Разомните капусту вилкой или толкушкой, переложите в миску. Добавьте муку, петрушку, лук, яйца, специи, разрыхлитель, соль, перец и 3 ст. л. отвара, хорошо перемешайте.</li><li>Разогрейте масло в большой сковороде. Выкладывайте ложкой по 2–3 ст. л. теста порциями по 4–5 оладий, обжаривая по 2 минуты с каждой стороны до золотистого цвета.</li><li>Перекладывайте на бумажное полотенце. Подавайте с йогуртом.</li></ol><p><em>Подайте тёплыми или комнатной температуры с мятным йогуртом.</em></p>', CURRENT_TIMESTAMP),
  ('18b147a3-508f-5dbd-a589-f5495bfd67a9', '6d8b3648-85b6-5b48-9bf3-50e712603afa', 'en', 'Cauliflower fritters with cumin and mint yogurt', 'Fluffy fritters of boiled mashed cauliflower with parsley, onion and warm spices, pan-fried and served with a lemony mint yogurt.', '<ol><li>For the sauce, mix the yogurt, dried mint, lemon juice, oil and salt and refrigerate.</li><li>Cut the cauliflower into 4 cm florets and simmer in salted water for 4 minutes. Drain, reserving 3–4 tbsp of the cooking water.</li><li>Mash the cauliflower with a fork or potato masher in a large bowl. Add the flour, parsley, onion, eggs, spices, baking powder, salt and pepper and 3 tbsp of the cooking water, and mix well.</li><li>Heat the oil in a large pan. Spoon in 2–3 tbsp of batter per fritter, 4–5 at a time, and fry about 2 minutes per side until golden.</li><li>Drain on paper towels and serve with the mint yogurt.</li></ol><p><em>Serve warm or at room temperature with the mint yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('a2128d27-6aa4-5728-9638-1cada4537f4f', '5ada8f1a-abce-55e5-88f7-320c1e4abc44', 'ru', 'Джуджех-кебаб — персидский куриный шашлык с шафраном и йогуртом', 'Сочные кубики куриной грудки, замаринованные на ночь в йогурте с шафраном, лимоном, луком и куркумой, обжаренные на шпажках.', '<ol><li>Разотрите шафран в порошок и разведите ¼ ч. л. в 3 ст. л. воды, оставьте на 10 минут.</li><li>В большой миске смешайте нарезанный лук, чеснок, лимонный сок, йогурт, масло, томатное пюре, куркуму и шафрановую воду.</li><li>Нарежьте курицу кубиками по 5 см, добавьте в маринад, посолите и поперчите, хорошо вотрите маринад. Накройте и оставьте в холодильнике на ночь.</li><li>Стряхните маринад (лук и жидкость выбросьте) и нанижите курицу на замоченные шпажки.</li><li>Слегка смажьте маслом и разогрейте гриль или сковороду-гриль до средне-сильного нагрева. Жарьте шашлыки без крышки около 10–12 минут, пока внутри не будет 74 °C. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подайте с рисом или лавашом и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('cb5ed99c-7af7-500c-bf83-9ddfc4e577b1', '5ada8f1a-abce-55e5-88f7-320c1e4abc44', 'en', 'Joojeh kabob (Persian saffron and yogurt chicken kabobs)', 'Juicy cubes of chicken breast marinated overnight in yogurt with saffron, lemon, onion and turmeric, then grilled on skewers.', '<ol><li>Grind the saffron to a fine powder and stir ¼ tsp into 3 tbsp of water; let it bloom for 10 minutes.</li><li>In a large bowl combine the sliced onion, garlic, lemon juice, yogurt, oil, tomato purée, turmeric and the saffron water.</li><li>Cut the chicken into 2-inch cubes, add to the marinade, season with salt and pepper and massage in well. Cover and refrigerate overnight.</li><li>Shake off excess marinade (discard the onions and liquid) and thread the chicken onto soaked skewers.</li><li>Lightly oil and heat a grill or griddle to medium-high. Cook the kabobs uncovered for about 10–12 minutes until the internal temperature is 165 °F (74 °C). Sprinkle with parsley.</li></ol><p><em>Sprinkle with parsley and serve with rice or flatbread and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('ab75f62d-8c2b-5ea8-9a91-ace343edf95d', '01d9c218-8f92-58ea-867a-a57c72c7ecf0', 'ru', 'Пышные американские блинчики', 'Толстые воздушные оладьи на молоке с яйцами и разрыхлителем. Подаются стопкой с кленовым сиропом, фруктами или беконом.', '<ol><li>В большой миске смешайте муку, разрыхлитель, сахар и щепотку соли.</li><li>Сделайте в центре углубление, влейте яйца, растопленное масло и молоко. Взбейте венчиком или миксером до гладкости и перелейте в кувшин.</li><li>На среднем огне в большой антипригарной сковороде нагрейте кусочек масла и 1 ч. л. растительного. Когда масло запенится, лейте тесто кружками диаметром около 8 см, оставляя место между ними.</li><li>Жарьте около 1–2 минут, пока на поверхности не появятся и не лопнут пузырьки, переверните и жарьте ещё минуту. Повторите с остатком теста.</li><li>Подавайте стопкой с кленовым сиропом и любимыми добавками.</li></ol><p><em>Подайте с кленовым сиропом, ягодами или хрустящим беконом.</em></p>', CURRENT_TIMESTAMP),
  ('fd29050c-3b09-5193-8a37-9ba6339139ae', '01d9c218-8f92-58ea-867a-a57c72c7ecf0', 'en', 'Fluffy American pancakes', 'Thick, fluffy milk-and-egg pancakes raised with baking powder, stacked and served with maple syrup, fruit or bacon.', '<ol><li>In a large bowl mix the flour, baking powder, sugar and a pinch of salt.</li><li>Make a well in the centre and add the eggs, melted butter and milk. Whisk by hand or with electric beaters until smooth and pour into a jug.</li><li>Heat a small knob of butter and 1 tsp of oil in a large non-stick pan over medium heat. When the butter foams, pour in rounds of batter about 8 cm wide, leaving space between them.</li><li>Cook about 1–2 minutes until bubbles appear and pop on the surface, flip and cook another minute. Repeat with the remaining batter.</li><li>Serve stacked with maple syrup and your favourite toppings.</li></ol><p><em>Serve with maple syrup, berries or crispy bacon.</em></p>', CURRENT_TIMESTAMP),
  ('180cc439-15b4-5ebb-bd65-a77528fcb2b9', '04440662-cfa4-5ece-bda8-bba571890c82', 'ru', 'Классический омлет из трёх яиц', 'Нежный французский омлет на сливочном масле, который можно наполнить сыром, ветчиной, зеленью, грибами или лососем.', '<ol><li>Взбейте яйца, хорошо посолите и поперчите. Нагрейте на небольшом огне в антипригарной сковороде масло, пока сливочное не растопится и не запенится.</li><li>Влейте яйца, слегка наклоняя сковороду, чтобы они растеклись. Через 20 секунд проведите лопаткой линию по центру.</li><li>Снова наклоните сковороду, чтобы жидкое яйцо растеклось, и повторите ещё раз-два, пока яйцо чуть схватится.</li><li>Положите начинку, аккуратно сложите омлет пополам и переложите на тарелку.</li></ol><p><em>Начините сыром, зеленью, грибами или копчёным лососем.</em></p>', CURRENT_TIMESTAMP),
  ('c7b00c01-40a0-50de-be1b-4877318827a1', '04440662-cfa4-5ece-bda8-bba571890c82', 'en', 'Classic three-egg omelette', 'A tender French-style omelette cooked in butter, which you can fill with cheese, ham, herbs, mushrooms or smoked salmon.', '<ol><li>Season the beaten eggs well with salt and pepper. Heat the oil and butter in a non-stick pan over medium-low until the butter foams.</li><li>Pour in the eggs and tilt the pan slightly so they cover the surface. After about 20 seconds scrape a line through the middle with a spatula.</li><li>Tilt the pan again to let the runny egg fill back in and repeat once or twice until just set.</li><li>Scatter on the filling, fold the omelette gently in half and slide it onto a plate.</li></ol><p><em>Fill with cheese, herbs, mushrooms or smoked salmon.</em></p>', CURRENT_TIMESTAMP),
  ('f95536f6-d8f2-5e1e-b515-15646de9d928', '95033379-e7e6-5334-8d80-f9492e2b1b3d', 'ru', 'Белковые оладьи из творога и овсяных хлопьев', 'Небольшие оладьи из творога, овсянки и яиц, взбитых в блендере. Подаются сладкими с ягодами или с яйцом-пашот и печёными помидорами.', '<ol><li>Положите в блендер все ингредиенты, кроме масла (ваниль и сироп кладите только для сладких оладий). Взбейте до гладкого теста.</li><li>Разогрейте немного масла в антипригарной сковороде на среднем огне и выкладывайте по несколько столовых ложек теста, формируя небольшие оладьи. Жарьте порциями.</li><li>Жарьте 2–3 минуты, пока на поверхности не появятся пузырьки и верх не схватится, затем переверните ещё на 1–2 минуты до золотистого цвета. Держите готовые тёплыми.</li><li>Подавайте с яйцом-пашот и печёными помидорами или с ягодами и сиропом.</li></ol><p><em>Подайте с ягодами и кленовым сиропом или с яйцом-пашот и запечёнными помидорами.</em></p>', CURRENT_TIMESTAMP),
  ('e7acfbb9-bbc7-5aef-837d-5b4a714fef67', '95033379-e7e6-5334-8d80-f9492e2b1b3d', 'en', 'Cottage cheese and oat pancakes', 'Small high-protein pancakes of cottage cheese, oats and eggs blended into a batter. Serve sweet with berries or savoury with a poached egg and roasted tomatoes.', '<ol><li>Put all the ingredients except the oil in a blender (use the vanilla and maple syrup only for sweet pancakes) and blitz to a smooth batter.</li><li>Heat a little oil in a non-stick pan over medium heat and spoon in a few tablespoons of batter per pancake. Cook in batches.</li><li>Cook 2–3 minutes until bubbles appear and the top looks set, flip and cook 1–2 minutes more until golden. Keep warm while you cook the rest.</li><li>Serve with a poached egg and roasted tomatoes, or with fresh berries and maple syrup.</li></ol><p><em>Top with berries and maple syrup, or a poached egg and roasted tomatoes.</em></p>', CURRENT_TIMESTAMP),
  ('d5e0575c-711b-5fed-aa35-3bb08dcae30e', '9795b463-00bc-5c35-a9bf-95fad46a1056', 'ru', 'Хэш из картофеля с беконом, перцем и яйцами', 'Обжаренный картофель с беконом и сладким перцем, на котором запекаются яйца с кусочками феты. Сытный завтрак или ужин из шести ингредиентов.', '<ol><li>Выложите кубики картофеля в кастрюлю с холодной подсоленной водой, доведите до кипения и варите 10 минут до мягкости. Слейте воду и оставьте обсохнуть.</li><li>В жаропрочной сковороде диаметром 30 см обжарьте бекон на среднем огне по 3–4 минуты с каждой стороны. Переложите на тарелку, жир оставьте в сковороде. Остывший бекон нарежьте полосками. Разогрейте духовку до 200 °C.</li><li>Выложите картофель в жир, перемешайте и жарьте 3–5 минут, не трогая. Добавьте перец, посолите и поперчите, жарьте ещё 3 минуты, затем перемешайте и жарьте 2–4 минуты до золотистого цвета. Верните бекон и прогрейте 2 минуты.</li><li>Снимите с огня, сделайте ложкой четыре углубления, разбейте в каждое по яйцу и посыпьте фетой. Запекайте в духовке 6–8 минут до нужной степени готовности яиц. Посыпьте петрушкой.</li></ol><p><em>Посыпьте рубленой петрушкой, подайте прямо на сковороде.</em></p>', CURRENT_TIMESTAMP),
  ('7c67cdf7-75d2-58a6-8180-c61b6ed02083', '9795b463-00bc-5c35-a9bf-95fad46a1056', 'en', 'Potato, bacon, pepper and egg breakfast hash', 'Pan-fried potatoes with bacon and red pepper, topped with baked eggs and crumbled feta. A hearty breakfast or supper from six ingredients.', '<ol><li>Put the potato cubes in a pan of cold salted water, bring to the boil and simmer 10 minutes until tender. Drain well and leave to steam-dry.</li><li>In a 30 cm ovenproof pan fry the bacon over medium heat 3–4 minutes per side until almost crisp. Move to a plate, leaving the fat. Cut the cooled bacon into strips. Heat the oven to 400 °F (200 °C).</li><li>Add the potatoes to the fat, stir, and cook undisturbed 3–5 minutes. Add the pepper, season well and cook 3 minutes, then stir and cook 2–4 minutes more until lightly browned. Stir in the bacon and cook 2 minutes.</li><li>Remove from the heat, make four hollows with a spoon, crack an egg into each and scatter with feta. Bake 6–8 minutes until the eggs are cooked to your liking. Sprinkle with parsley.</li></ol><p><em>Scatter with chopped parsley and serve straight from the pan.</em></p>', CURRENT_TIMESTAMP),
  ('06a6eac5-cd50-5e4a-8add-ff1b8f900185', '41553c60-7275-5dac-bbfe-770f0959fd71', 'ru', 'Запечённая овсянка с бананом и ягодами', 'Воздушная овсяная запеканка в формочках из овсяных хлопьев, банана, яиц и мёда с черникой, малиной или шоколадом. Готовится в духовке или аэрогриле.', '<ol><li>Разогрейте духовку до 180 °C (160 °C с конвекцией). Измельчите овсяные хлопья в блендере короткими импульсами до состояния муки.</li><li>Добавьте разрыхлитель, нарезанный банан, мёд или кленовый сироп, яйца и корицу, взбейте до гладкости. Вмешайте ягоды или шоколадную крошку.</li><li>Слегка смажьте маслом 4 жаропрочные формочки и разложите тесто. В духовке выпекайте 20–25 минут, в аэрогриле (при 180 °C, прогретом 4 минуты) 8–10 минут, пока запеканка не поднимется и не станет пружинить при нажатии.</li><li>Посыпьте ягодами и подавайте тёплой.</li></ol><p><em>Подайте тёплой с ягодами сверху.</em></p>', CURRENT_TIMESTAMP),
  ('914259ca-afaf-51c0-adbe-4a3af3bbcf10', '41553c60-7275-5dac-bbfe-770f0959fd71', 'en', 'Banana baked oats', 'Light oven- or air-fryer-baked oat cups made from oats, banana, eggs and honey with blueberries, raspberries or chocolate chips.', '<ol><li>Heat the oven to 350 °F (180 °C; 160 °C fan). Pulse the oats in a blender a few times until they look like flour.</li><li>Add the baking powder, chopped banana, honey or maple syrup, eggs and cinnamon and blend until smooth. Stir in the berries or chocolate chips.</li><li>Lightly oil four heatproof ramekins and divide the batter between them. Bake 20–25 minutes in the oven, or 8–10 minutes in an air fryer at 180 °C (preheated 4 minutes), until well risen and springy.</li><li>Top with extra berries and serve warm.</li></ol><p><em>Serve warm with extra fruit on top.</em></p>', CURRENT_TIMESTAMP),
  ('47bfc9c7-cc17-53a9-9bb6-adcd9310c4d3', '189131b4-0d73-5ec5-a2d4-18f7e2f58944', 'ru', 'Фриттата с чоризо, картофелем, горошком и шпинатом', 'Сытная фриттата из шести яиц с копчёной колбасой чоризо, картофелем, зелёным горошком и шпинатом. Готовится за 25 минут в одной сковороде.', '<ol><li>Включите гриль на высокую мощность. Нагрейте масло в сковороде диаметром 20 см на среднем огне и жарьте кружки чоризо 5–6 минут, пока они не выделят масло и не зарумянятся по краям.</li><li>Добавьте горошек и картофель, перемешайте в масле. Кладите шпинат горстями, дожидаясь, пока он осядет. Посолите и поперчите.</li><li>Взбейте яйца с солью и перцем и залейте содержимое сковороды. Готовьте на слабом огне 6–7 минут, пока края не схватятся.</li><li>Аккуратно поставьте под гриль на 4–5 минут, пока верх не зарумянится и немного поднимется.</li></ol><p><em>Подайте с салатом или хлебом; в холодильнике хранится до двух дней.</em></p>', CURRENT_TIMESTAMP),
  ('2cc63445-0b2b-5385-8bae-5d25879a4965', '189131b4-0d73-5ec5-a2d4-18f7e2f58944', 'en', 'Chorizo, potato, pea and spinach frittata', 'A filling six-egg frittata with chorizo, potatoes, green peas and spinach, made in one pan in about 25 minutes.', '<ol><li>Heat the grill to high. Heat the oil in a 20 cm pan over medium heat and fry the chorizo rounds 5–6 minutes until they release their oil and begin to crisp at the edges.</li><li>Add the peas and potatoes and stir in the oil. Add the spinach a handful at a time, letting each wilt. Season well.</li><li>Whisk the eggs with salt and pepper and pour over the pan so everything is covered. Cook on low for 6–7 minutes until the edges are set.</li><li>Carefully put under the grill for 4–5 minutes until cooked through, golden and slightly puffed.</li></ol><p><em>Serve with a salad or bread; keeps chilled for two days.</em></p>', CURRENT_TIMESTAMP),
  ('4106cf1a-4a9a-5135-baf1-2667d01af005', 'f4b4a6f6-f622-5ca8-9678-eb34965bc50d', 'ru', 'Дачч-бэби — запечённый немецкий блин', 'Большой блин из яичного теста, который в раскалённой сковороде в духовке вздувается, как йоркширский пудинг. Подаётся со сладкими или солёными добавками.', '<ol><li>Всыпьте муку в миску, сделайте углубление, разбейте яйца, влейте молоко и ваниль. Взбейте венчиком до гладкого теста и отставьте.</li><li>Разогрейте духовку до 220 °C. Налейте масло в жаропрочную сковороду диаметром около 20 см и поставьте на среднюю полку (верхнюю полку лучше убрать, блин сильно поднимается).</li><li>Достаньте горячую сковороду, влейте тесто (оно должно зашипеть) и быстро закройте духовку. Выпекайте 20–25 минут до глубокого золотистого цвета, не открывая дверцу, иначе блин осядет.</li><li>Подавайте прямо в сковороде с любыми сладкими или солёными добавками.</li></ol><p><em>Подайте в сковороде с ягодами и сахарной пудрой или с сыром и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('409bf9f6-3b54-53fb-a690-242eaf7e0256', 'f4b4a6f6-f622-5ca8-9678-eb34965bc50d', 'en', 'Dutch baby (German pancake)', 'A big egg-batter pancake baked in a hot pan until it puffs up like a giant Yorkshire pudding. Serve with sweet or savoury toppings.', '<ol><li>Tip the flour into a bowl, make a well, crack in the eggs and add the milk and vanilla. Whisk to a smooth batter and set aside.</li><li>Heat the oven to 425 °F (220 °C). Pour the oil into a 20 cm ovenproof skillet and put it on the middle shelf to heat up; remove the top shelf so the pancake can rise.</li><li>Pull out the hot pan and pour in the batter; it should sizzle. Close the oven quickly and bake 20–25 minutes until deep golden brown. Do not open the door early or it will sink.</li><li>Serve in the pan with sweet or savoury toppings.</li></ol><p><em>Serve in the pan with berries and icing sugar or with cheese and herbs.</em></p>', CURRENT_TIMESTAMP),
  ('b2c00fdc-b43d-5a08-aa78-bf83d8636af7', 'b72eb43c-cbbf-53e6-80d3-322f005f7bb2', 'ru', 'Говядина, томлёная в мультиварке с картофелем и морковью', 'Кусок говядины, обжаренный и томлёный 8 часов в мультиварке с луком, чесноком, розмарином, картофелем и морковью, с густым соусом из жидкости для тушения.', '<ol><li>Обсушите мясо и посолите и поперчите со всех сторон. Разогрейте 1 ст. л. масла в большой сковороде на среднем-сильном огне и обжаривайте мясо без перемешивания около 4 минут до корочки, затем переверните и обжарьте ещё 3–4 минуты. Переложите в чашу мультиварки объёмом от 6 л.</li><li>Добавьте в сковороду оставшиеся полложки масла, обжарьте лук 2–3 минуты до цвета, затем добавьте чеснок на 30 секунд.</li><li>Влейте бульон, соскребая налёт со дна. Добавьте веточки розмарина, томатный соус и вустерский соус, доведите до быстрого кипения на 30 секунд и снимите с огня.</li><li>Положите на мясо картофель и морковь, залейте смесью из сковороды и посыпьте рубленым розмарином.</li><li>Готовьте под крышкой на низком режиме около 8 часов, пока мясо не начнёт разваливаться, а овощи не станут мягкими. Переложите мясо и овощи на блюдо, удалите крупные куски жира.</li><li>Для соуса процедите жидкость в кастрюлю. Смешайте крахмал с водой, влейте в жидкость и варите на среднем-сильном огне, постоянно помешивая, около минуты до лёгкого загустения. Полейте мясо и овощи соусом и посыпьте петрушкой.</li></ol><p><em>Подавайте горячим с соусом и рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('de1ddba3-c648-5d42-a604-0c82cd36beaa', 'b72eb43c-cbbf-53e6-80d3-322f005f7bb2', 'en', 'Slow cooker pot roast with potatoes and carrots', 'Seared beef chuck slow-cooked for 8 hours with onion, garlic, rosemary, potatoes and carrots, served with gravy made from the cooking juices.', '<ol><li>Pat the roast dry and season all over with salt and pepper. Heat 1 tbsp oil in a large skillet over medium-high heat and sear the roast without moving it about 4 minutes, then flip and brown 3–4 minutes more. Transfer to a 6-quart or larger slow cooker.</li><li>Add the remaining ½ tbsp oil to the skillet, cook the onion 2–3 minutes until it begins to color, then stir in the garlic for 30 seconds.</li><li>Pour in the broth, scraping up the browned bits. Add the rosemary sprigs, tomato sauce and Worcestershire, bring to a rapid simmer for 30 seconds and remove from the heat.</li><li>Arrange the potatoes and carrots over the beef, pour the pan mixture on top and sprinkle with chopped rosemary.</li><li>Cover and cook on LOW about 8 hours until the beef is fall-apart tender and the vegetables are soft. Transfer the meat and vegetables to a platter and discard any large pieces of fat.</li><li>For the gravy strain the cooking liquid into a saucepan. Whisk the cornstarch with the water, add to the liquid and simmer over medium-high heat, whisking, about 1 minute until slightly thickened. Spoon over the beef and vegetables and sprinkle with parsley.</li></ol><p><em>Serve hot with the gravy and chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('b3a88161-fc69-56f1-a450-0620dee9a2da', 'ce0f182b-78f9-5356-810c-9becdb4ad06d', 'ru', 'Курица в соусе марсала с грибами', 'Тонкие куриные эскалопы в муке, обжаренные до золотистой корочки и поданные в соусе из вина марсала с шалотом, шампиньонами и тимьяном. Без сливок.', '<ol><li>Разрежьте каждую грудку вдоль пополам на два тонких куска и слегка отбейте до толщины около 6 мм. Посолите и поперчите и обваляйте в муке.</li><li>Разогрейте 1 ст. л. масла в глубокой сковороде на среднем-сильном огне. Обжарьте 2 куска по 2–3 минуты с каждой стороны до золотистого цвета и готовности, переложите на тарелку и накройте фольгой. Добавьте остальное масло и обжарьте оставшиеся 2 куска.</li><li>Добавьте в сковороду 2 ст. л. масла, шалот, чеснок, грибы и оставшуюся соль и готовьте 6–8 минут, пока грибы не станут мягкими и не начнут золотиться.</li><li>Влейте марсалу и уксус, соскребая налёт со дна, и уварите вдвое, около 3 минут.</li><li>Добавьте бульон и варите минуту. Вмешайте оставшуюся ложку масла, попробуйте и посолите. Верните курицу в сковороду на 30–60 секунд, посыпьте тимьяном и подавайте сразу.</li></ol><p><em>Подавайте с пюре, пастой или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('6ad6a90f-d95d-5d8f-ac51-83ce2e2e42c4', 'ce0f182b-78f9-5356-810c-9becdb4ad06d', 'en', 'Chicken Marsala with mushrooms', 'Thin floured chicken cutlets seared golden and served in a Marsala wine sauce with shallot, mushrooms and thyme, with no cream.', '<ol><li>Split each chicken breast in half horizontally into two cutlets and pound to about ¼ inch thick. Season with half of the salt and the pepper and dredge in flour.</li><li>Heat 1 tbsp oil in a large high-sided skillet over medium-high. Cook 2 cutlets 2–3 minutes per side until golden and cooked through, set aside covered with foil, then add the remaining oil and cook the other 2.</li><li>Add 2 tbsp butter, the shallot, garlic, mushrooms and remaining salt to the skillet and cook 6–8 minutes until the mushrooms soften and begin to brown.</li><li>Pour in the Marsala and vinegar, scrape the pan and reduce by half, about 3 minutes.</li><li>Add the broth and simmer 1 minute. Stir in the last tablespoon of butter and adjust seasoning. Return the chicken to the pan to warm through 30–60 seconds, sprinkle with thyme and serve immediately.</li></ol><p><em>Serve with mashed potatoes, pasta or rice.</em></p>', CURRENT_TIMESTAMP),
  ('e9e48b4d-e332-5995-a61e-455ef9f7cdbb', '9f600559-d8df-5759-a5ed-7adb24ac6bb6', 'ru', 'Запеканка из брокколи с сыром и хрустящей панировкой', 'Отваренная брокколи в сливочно-сырном соусе из молока и чеддера, запечённая под корочкой из панировочных сухарей и пармезана.', '<ol><li>Разогрейте духовку до 200 °C. В жаропрочной сковороде растопите 1 ст. л. масла, слейте в миску и смешайте с панировочными сухарями и пармезаном.</li><li>Варите соцветия брокколи в кипящей воде около 3 минут до состояния «хрустящие», слейте воду.</li><li>В той же сковороде растопите оставшееся масло, всыпьте муку и 1 минуту помешивайте до лёгкого золотистого цвета. Тонкой струйкой влейте молоко, постоянно взбивая, и варите около 3 минут, пока соус не загустеет. Добавьте чесночный порошок, соль, горчицу, перец и кайенский перец, снимите с огня и вмешайте чеддер до гладкости.</li><li>Добавьте брокколи в соус, перемешайте и разровняйте. Посыпьте сверху смесью с сухарями.</li><li>Запекайте 20–25 минут до горячего состояния и золотистой хрустящей корочки. Для большей хрусткости на пару минут включите гриль. Дайте постоять 5 минут и подавайте.</li></ol><p><em>Подавайте как гарнир к курице или мясу.</em></p>', CURRENT_TIMESTAMP),
  ('1df43c80-bdae-5c35-b07a-6191a185daa2', '9f600559-d8df-5759-a5ed-7adb24ac6bb6', 'en', 'Cheesy broccoli casserole with crispy panko topping', 'Blanched broccoli in a creamy milk and cheddar sauce, baked under a crunchy panko and parmesan topping.', '<ol><li>Preheat the oven to 400 °F (200 °C). Melt 1 tbsp butter in an ovenproof skillet, pour into a bowl and mix with the panko and parmesan.</li><li>Boil the broccoli florets about 3 minutes until crisp-tender and drain.</li><li>Melt the remaining butter in the same skillet, sprinkle in the flour and whisk 1 minute until lightly golden. Slowly whisk in the milk and cook about 3 minutes until thickened. Stir in the garlic powder, salt, mustard, pepper and cayenne, remove from the heat and stir in the cheddar until smooth.</li><li>Stir the broccoli into the sauce, pat into an even layer and sprinkle with the panko mixture.</li><li>Bake 20–25 minutes until hot with a crisp golden topping (broil a few minutes for extra crunch). Let stand 5 minutes and serve.</li></ol><p><em>Serve as a side with chicken or meat.</em></p>', CURRENT_TIMESTAMP),
  ('3500eb12-5f5f-526c-b17e-abe19b0c1a5e', '63eb5564-0f07-5dd7-85b6-548675b43ac9', 'ru', 'Крем-суп из запечённой тыквы со специями', 'Густой суп-пюре из запечённой в духовке тыквы с луком, чесноком, имбирём, корицей и ложкой мёда, со сливками в конце.', '<ol><li>Разогрейте духовку до 180 °C и застелите противень пергаментом. Разрежьте тыкву пополам от плодоножки до низа, ложкой удалите семена. Смажьте мякоть 1 ст. л. масла, посолите, поперчите и разотрите. Выложите срезом вниз и проколите кожуру вилкой.</li><li>Запекайте 45–55 минут, пока мякоть не станет мягкой, и остудите.</li><li>В кастрюле с толстым дном растопите масло с оставшейся ложкой растительного масла, добавьте лук с ½ ч. л. соли и готовьте 8–10 минут до прозрачности. Добавьте чеснок, имбирь, корицу, душистый и кайенский перец на 30 секунд.</li><li>Выложите мякоть тыквы в кастрюлю (кожуру выбросьте), разомните, влейте бульон, доведите до кипения и варите под неплотной крышкой 15 минут.</li><li>Снимите с огня, влейте сливки и мёд и пюрируйте погружным блендером до гладкости. Посолите и поперчите по вкусу. Подавайте горячим.</li></ol><p><em>Подавайте с ложкой греческого йогурта и обжаренными тыквенными семечками.</em></p>', CURRENT_TIMESTAMP),
  ('913920ae-af22-5119-9f7b-27a12c11838b', '63eb5564-0f07-5dd7-85b6-548675b43ac9', 'en', 'Creamy roasted pumpkin soup with warm spices', 'Thick oven-roasted pumpkin purée soup with onion, garlic, ginger, cinnamon and a touch of honey, finished with cream.', '<ol><li>Preheat the oven to 350 °F (180 °C) and line a baking sheet with parchment. Halve the pumpkin from stem to base and scoop out the seeds. Drizzle the flesh with 1 tbsp oil, season with salt and pepper and rub in. Place cut-side down and pierce the skin with a fork.</li><li>Roast 45–55 minutes until the flesh is fork tender, then let cool.</li><li>In a Dutch oven melt the butter with the remaining oil, add the onion and ½ tsp salt and cook 8–10 minutes until translucent. Stir in the garlic, ginger, cinnamon, allspice and cayenne for 30 seconds.</li><li>Scoop the pumpkin flesh into the pot (discard the skins), mash, pour in the broth, bring to a boil and simmer partly covered for 15 minutes.</li><li>Remove from the heat, stir in the cream and honey and purée with an immersion blender until very smooth. Adjust salt and pepper and serve hot.</li></ol><p><em>Top with Greek yogurt and toasted pepitas.</em></p>', CURRENT_TIMESTAMP),
  ('d875cf0c-e2cf-56bb-ac52-10714383b100', '6a14281c-2b1e-517c-840e-c8242514f5b4', 'ru', 'Котлеты из консервированного лосося', 'Быстрые рыбные котлеты из консервированного лосося, яйца, панировочных сухарей и йогурта с горчицей и специями. Получается 6 котлет.', '<ol><li>В большой миске слегка взбейте яйцо. Добавьте слитый лосось, панировочные сухари, йогурт, горчицу, уксус, луковый и чесночный порошок и кайенский перец.</li><li>Вилкой слегка перемешайте, разделяя лосось на мелкие кусочки, и осторожно вмешайте петрушку.</li><li>Сформуйте 6 котлет толщиной около 1,3 см, по ⅓ стакана массы на каждую, и выложите на тарелку.</li><li>В тяжёлой сковороде нагрейте масло на среднем огне. Жарьте котлеты с двух сторон 5–6 минут до глубокого золотистого цвета и готовности, переворачивая осторожно длинной гибкой лопаткой.</li><li>Подавайте с йогуртом, лимоном и петрушкой.</li></ol><p><em>Подавайте с греческим йогуртом или сметаной, лимоном и зеленью. Порция — 2 котлеты.</em></p>', CURRENT_TIMESTAMP),
  ('8f049149-f1a4-579f-a94c-d4a251b974a8', '6a14281c-2b1e-517c-840e-c8242514f5b4', 'en', 'Canned salmon patties', 'Quick salmon patties made from canned salmon, egg, breadcrumbs and yogurt seasoned with mustard and spices. Makes 6 patties.', '<ol><li>In a large bowl lightly beat the egg. Add the drained salmon, breadcrumbs, yogurt, mustard, vinegar, onion powder, garlic powder and cayenne.</li><li>Mix lightly with a fork, breaking the salmon up further, and gently stir in the parsley.</li><li>Scoop ⅓ cup portions and shape into 6 patties about ½ inch thick; arrange on a plate.</li><li>Heat the oil in a heavy skillet over medium. Brown the patties on both sides 5–6 minutes total until deep golden and cooked through, flipping gently with a flexible spatula.</li><li>Serve with yogurt, a squeeze of lemon and parsley.</li></ol><p><em>Serve with Greek yogurt or sour cream, lemon and fresh herbs. A serving is 2 patties.</em></p>', CURRENT_TIMESTAMP),
  ('da5bc906-a625-5146-ab32-3ded7ebbb9af', '71994821-ef23-58c5-8a12-46807a34f39f', 'ru', 'Веганский чили с бататом и бобами', 'Густое постное блюдо из чёрной фасоли, пинто, батата и болгарского перца с копчёной паприкой, зирой и какао. Готовится в одной кастрюле.', '<ol><li>В большой кастрюле разогрейте оливковое масло на среднем огне. Добавьте лук, красный и зелёный перец и батат кубиками и готовьте около 10 минут, помешивая, пока лук не станет прозрачным, а перец не начнёт размягчаться.</li><li>Убавьте огонь, добавьте чеснок, томатную пасту, порошок чили, зиру, копчёную паприку, какао, соль и кайенский перец и готовьте минуту до сильного аромата.</li><li>Добавьте помидоры с соком, фасоль и овощной бульон. Доведите до кипения, накройте неплотно, убавьте огонь и варите на слабом огне 30 минут, иногда помешивая.</li><li>Снимите с огня. Чтобы чили стало гуще, разомните толкушкой часть бобов и батата прямо в кастрюле (или слегка пюрируйте погружным блендером), оставив много кусочков.</li><li>Добавьте уксус и кленовый сироп, попробуйте и при необходимости досолите. Подавайте горячим с любимыми добавками.</li></ol><p><em>Подавайте с ломтиками авокадо, кинзой, лаймом и лепёшками.</em></p>', CURRENT_TIMESTAMP),
  ('2474ce0d-9318-547f-b52c-b884c331e967', '71994821-ef23-58c5-8a12-46807a34f39f', 'en', 'Vegan sweet potato and black bean chili', 'Hearty plant-based chili of black beans, pinto beans, sweet potatoes and bell peppers with smoked paprika, cumin and a little cocoa, made in one pot.', '<ol><li>In a large Dutch oven heat the olive oil over medium. Add the onion, red and green peppers and sweet potatoes and cook about 10 minutes, stirring, until the onion is translucent and the peppers soften.</li><li>Reduce the heat to medium-low and add the garlic, tomato paste, chili powder, cumin, smoked paprika, cocoa, salt and cayenne. Cook and stir 1 minute until very fragrant.</li><li>Stir in the tomatoes with their juices, beans and vegetable broth. Bring to a boil, partially cover, reduce the heat and simmer 30 minutes, stirring now and then.</li><li>Remove from the heat. To thicken, mash some of the beans and sweet potato in the pot with a masher (or give it a few pulses with an immersion blender) leaving plenty chunky.</li><li>Stir in the vinegar and maple syrup, adjust the seasoning and serve hot with your favorite toppings.</li></ol><p><em>Serve with avocado slices, cilantro, lime wedges and tortilla chips.</em></p>', CURRENT_TIMESTAMP),
  ('94264011-88d3-5d25-a2ff-775356019b2b', 'ab70bae7-e62e-52b0-9806-89139accf0ee', 'ru', 'Суп с фасолью, пастой и говяжьим фаршем (паста э фаджоли)', 'Сытный итальянский суп с говяжьим фаршем, красной фасолью, мелкой пастой, овощами и томатами. Готовится за 30 минут.', '<ol><li>В кастрюле с толстым дном разогрейте 1 ст. л. масла и обжарьте фарш, разбивая комочки, до румяности.</li><li>Добавьте лук и готовьте до мягкости, затем сельдерей и морковь с половиной соли и ¼ ч. л. перца и тушите 6–8 минут.</li><li>Добавьте помидоры, бульон, кетчуп, чеснок, остальные соль и перец, итальянские травы, лавровый лист и пасту. Варите 15 минут до мягкости пасты.</li><li>Положите шпинат и фасоль, доведите до кипения и варите ещё 2 минуты. Подавайте горячим.</li></ol><p><em>Посыпьте тёртым пармезаном и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('982a6d6c-47dd-57ad-b25b-4f6b753a9ad9', 'ab70bae7-e62e-52b0-9806-89139accf0ee', 'en', 'Pasta fagioli soup with ground beef', 'Hearty Italian soup with ground beef, kidney beans, small pasta, vegetables and tomatoes in broth, ready in 30 minutes.', '<ol><li>In a Dutch oven heat 1 tbsp olive oil and brown the ground beef, breaking it up.</li><li>Add the onion and cook until tender, then the celery and carrots with half the salt and ¼ tsp pepper, and cook 6–8 minutes until soft.</li><li>Stir in the tomatoes, broth, ketchup, garlic, remaining salt and pepper, Italian seasoning, bay leaf and pasta. Cook 15 minutes until the pasta is tender.</li><li>Add the spinach and beans, bring to a simmer and cook 2 more minutes. Serve hot.</li></ol><p><em>Top with grated parmesan and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('d1c8fd42-cd5b-5723-aae3-6a9c10d977be', 'af5c5ccc-99b7-5f67-b17a-6e6ba59cb924', 'ru', 'Классическая лазанья с говяжьим фаршем и тремя сырами', 'Слои лазаньи с мясным томатным соусом, творожной смесью из рикотты, пармезана и яйца и тёртой моцареллой, запечённые до золотистой корочки.', '<ol><li>Разогрейте духовку до 190 °C. Смажьте или сбрызните маслом форму 23×33 см.</li><li>Отварите листы лазаньи до состояния аль денте, промойте холодной водой и отложите.</li><li>В большой сковороде разогрейте масло, обжарьте фарш с луком, разбивая мясо. Добавьте чеснок на 30 секунд. Влейте томатный соус, добавьте итальянские травы, соль и перец, доведите до слабого кипения и снимите с огня.</li><li>В миске смешайте рикотту, пармезан, яйцо, чеснок, соль и перец.</li><li>Соберите лазанью: тонкий слой соуса на дно, 3 листа, слой сырной смеси, мясной соус и моцарелла. Повторите до четырёх слоёв, сверху — соус и сыр.</li><li>Накройте фольгой и запекайте 35 минут, затем снимите фольгу и запекайте ещё 10–15 минут до пузырящегося золотистого верха. Накройте и дайте постоять 5 минут.</li></ol><p><em>Дайте постоять 5 минут перед нарезкой и подавайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('cf3f2e6f-601c-5f44-9f65-166377947cc2', 'af5c5ccc-99b7-5f67-b17a-6e6ba59cb924', 'en', 'Classic beef lasagna with three cheeses', 'Layers of lasagna noodles, meaty tomato sauce, a ricotta-parmesan-egg filling and shredded mozzarella, baked until bubbly and golden.', '<ol><li>Preheat the oven to 375 °F (190 °C). Grease a 9×13 in baking dish.</li><li>Cook the lasagna noodles al dente, rinse under cold water and set aside.</li><li>Heat the oil in a large skillet and brown the beef with the onion, breaking it up. Add the garlic for 30 seconds, pour in the marinara, add Italian seasoning, salt and pepper, bring to a soft boil and remove from the heat.</li><li>Mix the ricotta, parmesan, egg, garlic, salt and pepper in a bowl.</li><li>Assemble: a thin layer of sauce, 3 noodles, the cheese mixture, meat sauce and mozzarella. Repeat for four layers, finishing with sauce and cheese.</li><li>Cover with foil and bake 35 minutes, then uncover and bake 10–15 more until bubbly and golden. Re-cover and let rest 5 minutes.</li></ol><p><em>Rest 5 minutes before slicing and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('437c89f6-c5d8-5010-906c-4e498e9cdc0b', '72206d70-4aec-569f-a1a8-3e781ef635b8', 'ru', 'Цветная капуста в хрустящей панировке с пармезаном, запечённая', 'Соцветия цветной капусты, обмакнутые в масло со специями, обваленные в сухарях с пармезаном и запечённые до хруста. Подходит как гарнир или закуска.', '<ol><li>Разогрейте духовку до 220 °C и застелите противень пергаментом.</li><li>В первой миске смешайте растопленное масло, соль, перец и чесночный порошок. Во второй смешайте обычные и панировочные сухари панко, пармезан, паприку и итальянские травы.</li><li>Обмакните соцветия в масло, затем обваляйте в сухарях, придавливая панировку. Выложите на противень на расстоянии друг от друга.</li><li>Запекайте 16–18 минут, пока капуста не станет золотистой и хрустящей.</li></ol><p><em>Подавайте горячей или холодной с соусом из авокадо или сметаны с чесноком.</em></p>', CURRENT_TIMESTAMP),
  ('bf3bdcee-9119-56b6-99c8-46a830a28844', '72206d70-4aec-569f-a1a8-3e781ef635b8', 'en', 'Crispy breaded roasted cauliflower with parmesan', 'Cauliflower florets dipped in seasoned butter, coated in breadcrumbs and parmesan and baked until crunchy. A side dish or appetizer.', '<ol><li>Preheat the oven to 425 °F (220 °C) and line a baking sheet with parchment.</li><li>In bowl 1 mix the melted butter, salt, pepper and garlic powder. In bowl 2 combine the plain and panko breadcrumbs, parmesan, paprika and Italian seasoning.</li><li>Dip the florets in the butter mixture, then dredge in the breadcrumbs, patting the coating on. Arrange evenly on the baking sheet.</li><li>Bake 16–18 minutes until golden and crispy.</li></ol><p><em>Serve hot or cold with an avocado or garlic sour cream dip.</em></p>', CURRENT_TIMESTAMP),
  ('c8b261e3-993d-576e-bf3a-b95fda32d48a', '1c893403-066b-59ae-a65e-deb3d7f16e2d', 'ru', 'Куриный суп-пюре с морковью, горошком и чесночным йогуртом', 'Лёгкий суп из остатков запечённой курицы с луком, морковью, тимьяном и зелёным горошком, наполовину измельчённый блендером. Подаётся с йогуртом с чесноком и лимоном.', '<ol><li>В большой кастрюле с толстым дном разогрейте оливковое масло, добавьте лук, морковь и тимьян и медленно обжаривайте 15 минут.</li><li>Влейте бульон, доведите до кипения, накройте крышкой и варите на слабом огне 10 минут.</li><li>Добавьте курицу, половину содержимого кастрюли отлейте и измельчите погружным блендером. Верните пюре в суп, добавьте горошек, посолите и поперчите и прогрейте 5 минут.</li><li>Смешайте йогурт, чеснок и лимонный сок. Разлейте суп по тарелкам и добавьте ложку чесночного йогурта.</li></ol><p><em>Подайте с гренками или сырными лепёшками.</em></p>', CURRENT_TIMESTAMP),
  ('3bd09fe3-1bf4-53ad-ae85-559913487d44', '1c893403-066b-59ae-a65e-deb3d7f16e2d', 'en', 'Chicken, pea and carrot soup with garlic yogurt', 'A light soup made from leftover roast chicken, onions, carrots, thyme and peas, half of it blended, swirled with garlicky lemon yogurt.', '<ol><li>Heat the olive oil in a large heavy-based pan, add the onions, carrots and thyme and fry gently for 15 minutes.</li><li>Pour in the stock, bring to a boil, cover and simmer for 10 minutes.</li><li>Add the chicken, take out half the mixture and purée it with a stick blender. Return it to the pan with the peas and seasoning and simmer 5 minutes until hot.</li><li>Mix the yogurt, garlic and lemon juice. Ladle the soup into bowls and swirl in the garlic yogurt.</li></ol><p><em>Serve with toast or cheese scones.</em></p>', CURRENT_TIMESTAMP),
  ('1f35e7bb-7e86-512b-b702-31fdcfe39eb9', 'fab366c6-910e-5a48-b954-145233b8fd75', 'ru', 'Итальянский свадебный суп с мясными фрикадельками', 'Сытный суп на курином бульоне с говяжье-свиными фрикадельками, овощами, мелкой пастой и шпинатом, посыпанный пармезаном.', '<ol><li>Смешайте руками говяжий и свиной фарш, сухари, петрушку, пармезан, яйцо, соль и перец. Скатайте шарики диаметром около 2 см.</li><li>Разогрейте 1 ст. л. масла в большой сковороде на сильном огне и обжарьте фрикадельки 6–8 минут до золотистого цвета. Переложите на тарелку.</li><li>В кастрюле на среднем огне 8 минут обжарьте морковь, лук и сельдерей на оставшемся масле до мягкости.</li><li>Влейте бульон, доведите до слабого кипения, добавьте пасту и фрикадельки и варите 5 минут, пока паста не станет мягкой, а фрикадельки готовыми. Добавьте шпинат на 30 секунд и разлейте по тарелкам.</li></ol><p><em>Посыпьте пармезаном и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('f8da4cd1-0889-5515-a5ea-8b03af1dfa3b', 'fab366c6-910e-5a48-b954-145233b8fd75', 'en', 'Italian wedding soup with meatballs', 'A filling chicken-broth soup with beef and pork meatballs, vegetables, small pasta and spinach, topped with Parmesan.', '<ol><li>Mix the beef and pork mince with the breadcrumbs, parsley, Parmesan, egg, salt and pepper by hand and roll into balls about 2 cm wide.</li><li>Heat 1 tbsp of oil in a large pan over high heat and fry the meatballs 6–8 minutes until golden. Remove to a plate.</li><li>In a pot, fry the carrots, onions and celery in the remaining oil over medium heat for 8 minutes until soft.</li><li>Add the stock and bring to a simmer. Add the pasta and meatballs and cook 5 minutes until the pasta is tender and the meatballs cooked through. Add the spinach for 30 seconds to wilt, then ladle into bowls.</li></ol><p><em>Top with Parmesan and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('684fccec-51b5-5edc-9bb3-54bbff912206', 'c1a96521-c646-5af6-aec0-fd3f00750952', 'ru', 'Куриный кордон блю с ветчиной и сыром под сырным соусом', 'Отбитая куриная грудка с ветчиной и сыром, свёрнутая рулетом, запанированная и запечённая до хрустящей корочки. Подаётся с горчично-сырным соусом.', '<ol><li>Каждую грудку надрежьте вдоль с толстого края почти до конца и раскройте, как книжку. Отбейте между листами пергамента до толщины 3–4 мм.</li><li>Положите на каждую грудку ломтик ветчины, посыпьте сыром, сверните плотным рулетом (при необходимости скрепите шпажкой) и охладите 30 минут.</li><li>Поставьте в духовку два противня и разогрейте её до 200 °C. Смешайте сухари, растопленное масло и приправы. Муку приправьте и насыпьте в миску, яйца взбейте.</li><li>Обваляйте каждый рулет в муке, затем в яйце и в сухарях. Выложите на горячие противни с пергаментом и запекайте 25 минут до золотистого цвета.</li><li>Для соуса растопите масло на слабом огне, всыпьте муку и готовьте пару минут. Постепенно влейте молоко, непрерывно помешивая, и на среднем огне загустите. Снимите с огня, добавьте горчицу, сыр, соль и перец. Подавайте с курицей.</li></ol><p><em>Подайте с салатом из кресс-салата или с картофелем и зелёными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('2ef874c4-687d-5906-abb2-5bd23e3fc8d8', 'c1a96521-c646-5af6-aec0-fd3f00750952', 'en', 'Chicken cordon bleu with cheese sauce', 'Pounded chicken breasts rolled around ham and cheese, breaded and baked until crisp, served with a creamy mustard-cheese sauce.', '<ol><li>Slice each chicken breast horizontally from the thick end almost through and open it like a book. Bash between two sheets of parchment until 3–4 mm thick.</li><li>Lay a slice of ham on each breast, sprinkle with cheese, roll up into a chunky cylinder (secure with a cocktail stick if needed) and chill for 30 minutes.</li><li>Put two baking trays in the oven and heat it to 400 °F (200 °C). Mix the breadcrumbs, melted butter and seasoning in a shallow bowl, season the flour in another and beat the eggs in a third.</li><li>Coat each roll in flour, then egg, then the breadcrumbs. Arrange on the hot parchment-lined trays and bake 25 minutes until golden and cooked through.</li><li>For the sauce melt the butter over low heat, stir in the flour and cook a couple of minutes. Gradually add the milk, stirring continuously, and thicken over medium heat. Off the heat stir in the mustard, cheese and seasoning, and serve over the chicken.</li></ol><p><em>Serve with a watercress salad or chunky chips and buttered greens.</em></p>', CURRENT_TIMESTAMP),
  ('86d9dea1-a0a5-5454-b41e-1ce937db0a62', 'b0407743-a676-561a-85fe-217b25c77e43', 'ru', 'Суп из красной чечевицы с морковью и пореем', 'Простой постный суп-пюре из красной чечевицы, моркови и лука-порея. Мало калорий и жира, много клетчатки.', '<ol><li>Нагрейте бульон в большой кастрюле, всыпьте чечевицу.</li><li>Доведите до кипения и варите несколько минут, пока чечевица не размякнет.</li><li>Добавьте нарезанную морковь и порей, приправьте перцем (не солите, если бульон солёный). Доведите до кипения, убавьте огонь, накройте и варите 45–60 минут, пока чечевица не разварится.</li><li>Посыпьте петрушкой и подавайте.</li></ol><p><em>Посыпьте петрушкой и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('8045bb02-d699-5a57-bb2f-8723b4d225f9', 'b0407743-a676-561a-85fe-217b25c77e43', 'en', 'Red lentil, carrot and leek soup', 'A simple vegan soup of red lentils, carrots and leeks that breaks down as it cooks. Low in calories and fat, high in fibre.', '<ol><li>Heat the stock in a large pan and add the lentils.</li><li>Bring to a boil and let the lentils soften for a few minutes.</li><li>Add the carrots and leeks and season with pepper (do not add salt if the stock is salty). Bring to a boil, reduce the heat, cover and simmer 45–60 minutes until the lentils have broken down.</li><li>Scatter with parsley and serve.</li></ol><p><em>Scatter with parsley and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('48a6ac68-2cfb-5919-af20-5e1ae164895c', '447a686f-1a63-5661-8ff6-6a6328993b83', 'ru', 'Крем-суп из запечённой цветной капусты', 'Нежный суп-пюре из запечённой с зирой и тимьяном цветной капусты, лука и сельдерея со сливками. Лёгкий обед или ужин.', '<ol><li>Разогрейте духовку до 220 °C. Смешайте соцветия цветной капусты в форме с 1 ст. л. масла, зирой и тимьяном и запекайте 15 минут до золотистого цвета и мягкости. Выбросьте тимьян.</li><li>В кастрюле на среднем огне 10 минут обжарьте лук и сельдерей на оставшемся масле до мягкости, добавьте чеснок на минуту.</li><li>Добавьте большую часть капусты (немного оставьте для подачи) и 750 мл бульона, доведите до кипения и варите 10 минут.</li><li>Измельчите суп погружным блендером или комбайном до гладкости, влейте сливки, посолите и поперчите, при необходимости разбавьте бульоном.</li><li>Разлейте по тарелкам и украсьте петрушкой, оставленной капустой и каплей оливкового масла.</li></ol><p><em>Посыпьте петрушкой и запечёнными соцветиями, добавьте масла и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('140071fb-f5f2-54a7-983f-690662f1ad1a', '447a686f-1a63-5661-8ff6-6a6328993b83', 'en', 'Roasted cauliflower cream soup', 'A smooth soup of cauliflower roasted with cumin and thyme, onion and celery, finished with cream. A light lunch or supper.', '<ol><li>Heat the oven to 425 °F (220 °C). Toss the cauliflower florets in a roasting tin with 1 tbsp of oil, the cumin and thyme and roast 15 minutes until golden and tender. Discard the thyme.</li><li>In a saucepan fry the onion and celery in the remaining oil over medium heat for 10 minutes until softened, then add the garlic for 1 minute.</li><li>Add most of the cauliflower, keeping some for topping, and 750 ml of the stock; bring to a simmer and cook for 10 minutes.</li><li>Blitz the soup until smooth with a hand blender or food processor, stir in the cream, season and add more stock if you like it thinner.</li><li>Ladle into bowls and top with the parsley, reserved cauliflower and a drizzle of olive oil.</li></ol><p><em>Top with parsley, reserved roasted florets and a drizzle of olive oil, and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('2c3ccdb4-0653-514a-85ab-8473b8ca59b2', '5badd961-223f-5c62-a37a-308f304197df', 'ru', 'Говяжьи фрикадельки в соусе строганов с грибами', 'Запечённые говяжьи фрикадельки в сметанном соусе с грибами, паприкой и горчицей. Подаются с картофельным пюре и шпинатом.', '<ol><li>Разогрейте духовку до 220 °C и смажьте противень маслом. Смешайте говяжий фарш, яйцо, 1 ст. л. муки, соль и перец.</li><li>Ложкой для мороженого выкладывайте фарш на противень и запекайте 10–12 минут до румяного цвета.</li><li>Для соуса в небольшой кастрюле на среднем огне несколько минут обжарьте грибы до золотистого цвета. Добавьте оставшуюся муку, паприку, горчицу и томатную пасту и перемешайте.</li><li>Влейте бульон, посолите и поперчите, варите 5–6 минут до лёгкого загустения. Убавьте огонь, добавьте сметану на минуту, затем положите фрикадельки и покройте соусом.</li></ol><p><em>Подайте с картофельным пюре и тушёным шпинатом.</em></p>', CURRENT_TIMESTAMP),
  ('60ae2cab-4a6a-5d04-809b-f2171bc1ff35', '5badd961-223f-5c62-a37a-308f304197df', 'en', 'Beef meatballs in stroganoff sauce', 'Oven-baked beef meatballs in a creamy mushroom sauce with paprika and mustard, served with mash and wilted spinach.', '<ol><li>Heat the oven to 425 °F (220 °C) and oil a baking tray. Mix the beef mince, egg, 1 tbsp of the flour and a pinch of salt and pepper.</li><li>Scoop the mixture onto the tray with an ice-cream scoop and bake 10–12 minutes until evenly browned.</li><li>For the sauce, cook the mushrooms in a small pan over medium heat for a few minutes until slightly golden. Stir in the remaining flour, paprika, mustard and tomato purée to coat.</li><li>Pour in the stock, season and simmer 5–6 minutes until slightly thickened. Reduce the heat, stir in the soured cream for 1 minute, then add the meatballs and coat them in the sauce.</li></ol><p><em>Serve with mashed potatoes and wilted spinach.</em></p>', CURRENT_TIMESTAMP),
  ('9683c532-a914-570b-a5d3-39e1841f4450', '3006b26f-5549-5013-bdc9-fde2c08dda9b', 'ru', 'Курица с картофелем, лимоном и заатаром на противне', 'Куриные бёдра, картофельные дольки, красный лук и оливки в пасте из заатара, сумаха, лимонного сока и чеснока, запечённые на одном противне.', '<ol><li>Нарежьте картофель дольками, залейте холодной подсоленной водой, доведите до кипения и варите 3 минуты. Слейте воду и дайте остыть.</li><li>В большой миске смешайте масло, заатар, сумах, паприку, чеснок, сок 1 лимона и 1 ч. л. соли. Добавьте курицу, красный лук, оливки и ломтики второго лимона, затем остывший картофель и хорошо перемешайте.</li><li>Разогрейте духовку до 200 °C. Выложите всё на противень, курицу сверху, и запекайте 35–40 минут до золотистого цвета.</li><li>Посыпьте петрушкой и подавайте с йогуртом.</li></ol><p><em>Посыпьте петрушкой и подайте с натуральным йогуртом.</em></p>', CURRENT_TIMESTAMP),
  ('72db97ed-075a-575d-9af7-fd0172544000', '3006b26f-5549-5013-bdc9-fde2c08dda9b', 'en', 'Za''atar and lemon chicken potato traybake', 'Chicken thighs, potato wedges, red onion and olives tossed in a paste of za''atar, sumac, lemon juice and garlic and roasted on one tray.', '<ol><li>Put the potato wedges in cold salted water, bring to the boil and cook 3 minutes. Drain and leave to cool.</li><li>In a large bowl mix the oil, za''atar, sumac, paprika, garlic, juice of 1 lemon and 1 tsp salt into a paste. Add the chicken, red onion, olives and sliced lemon, then the cooled potatoes, and toss well.</li><li>Heat the oven to 400 °F (200 °C). Tip everything onto a baking tray with the chicken on top and bake 35–40 minutes until golden.</li><li>Scatter with parsley and serve with yogurt.</li></ol><p><em>Scatter with parsley and serve with natural yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('977aa948-b0d3-5721-921b-9f6e0c06bec0', '1b4c4cf7-551c-5511-9e0a-eb95a8785552', 'ru', 'Мексиканский кускус с фасолью и кукурузой', 'Очень быстрое блюдо: кускус, заваренный кипятком со специями, с томатной пастой, чёрной фасолью, кукурузой, помидором, авокадо и кинзой. Готово за 10 минут без плиты.', '<ol><li>Смешайте в миске соль, зиру, луковый порошок и кускус.</li><li>Залейте кипятком, накройте и оставьте на 5 минут.</li><li>Взрыхлите вилкой, добавьте томатную пасту и перемешайте, чтобы она равномерно обволокла кускус.</li><li>Добавьте фасоль, кукурузу, халапеньо, зелёный лук, кинзу, помидор и авокадо и перемешайте. Подавайте с добавками по желанию.</li></ol><p><em>По желанию подайте со сметаной, тёртым сыром или чипсами из тортильи.</em></p>', CURRENT_TIMESTAMP),
  ('787a66a9-d9a3-539b-9b64-63eea894b2a9', '1b4c4cf7-551c-5511-9e0a-eb95a8785552', 'en', 'Mexican couscous with black beans and corn', 'An express meal: couscous steeped with spices, tossed with tomato paste, black beans, corn, tomato, avocado and cilantro. Ready in 10 minutes without a stove.', '<ol><li>Toss the salt, cumin, onion powder and couscous together in a bowl.</li><li>Pour over the boiling water, cover and leave for 5 minutes.</li><li>Fluff with a fork, add the tomato paste and stir to coat the couscous evenly.</li><li>Stir in the beans, corn, jalapeño, scallions, cilantro, tomato and avocado and serve with optional toppings.</li></ol><p><em>Top with sour cream, grated cheese or tortilla chips if you like.</em></p>', CURRENT_TIMESTAMP),
  ('a6f14133-4b3a-5712-8bc7-581d1b21dd6f', '3e67a942-bc6f-5d5f-8d2d-fb184c01c280', 'ru', 'Омлет по-средиземноморски с помидорами, оливками и фетой', 'Пышный омлет с паприкой и душистым перцем, начинённый помидорами черри, оливками, артишоками, травами и фетой. Подходит на завтрак или лёгкий ужин.', '<ol><li>В миске энергично взбейте яйца с молоком, разрыхлителем, специями, солью и перцем.</li><li>Разогрейте в антипригарной сковороде диаметром 25 см оливковое масло до лёгкого шипения, наклоняя сковороду, чтобы покрыть дно.</li><li>Влейте яйца и 5 секунд активно помешивайте лопаткой. Затем сдвигайте схватившиеся края к центру, наклоняя сковороду, чтобы жидкость растекалась по краям. Готовьте около минуты, пока омлет почти не схватится, а низ не станет светло-золотистым.</li><li>Снимите сковороду с огня. Выложите большую часть начинки на среднюю треть омлета и сложите. Сверху добавьте остальную начинку и свежую зелень.</li><li>Разрежьте омлет пополам и подавайте горячим.</li></ol><p><em>Подайте с тёплой питой и соусом цацики.</em></p>', CURRENT_TIMESTAMP),
  ('fe202854-312e-5f38-ac35-48b735ccd41c', '3e67a942-bc6f-5d5f-8d2d-fb184c01c280', 'en', 'Loaded Mediterranean omelette', 'A fluffy omelette seasoned with paprika and allspice and filled with cherry tomatoes, olives, artichoke hearts, fresh herbs and feta.', '<ol><li>In a bowl vigorously whisk the eggs with the milk, baking powder, spices, salt and pepper.</li><li>Heat the olive oil in a 10-inch non-stick skillet until shimmering, tilting the pan to coat the bottom.</li><li>Pour in the eggs and stir with a spatula for 5 seconds, then push the set edges to the center, tilting the pan to let raw egg flow outward. Cook about 1 minute until almost set and lightly golden underneath.</li><li>Remove from the heat. Spoon most of the toppings on the middle third of the omelette and fold. Add the remaining toppings and fresh herbs on top.</li><li>Slice into two halves and serve hot.</li></ol><p><em>Serve with warm pita and tzatziki for lunch or a light dinner.</em></p>', CURRENT_TIMESTAMP),
  ('4538ffef-70d5-5196-82f0-ab0ff891a59b', '6440e3c8-d2d8-50ff-8bdb-e7e0a69d8beb', 'ru', 'Лингвини с креветками и артишоками в лимонно-чесночном соусе', 'Паста с обжаренными в чесночном масле креветками, артишоками, петрушкой и лимонным соком, с пармезаном при подаче. Готовится за 25 минут.', '<ol><li>Натрите цедру с одного лимона и выжмите сок из обоих. Артишоки слейте, нарежьте на четвертинки и промокните бумажным полотенцем.</li><li>Отварите лингвини в большой кастрюле подсоленной воды 8–10 минут. Сохраните 1 стакан воды от варки, слейте пасту (промывать не нужно).</li><li>Тем временем в большой толстодонной сковороде растопите сливочное масло с оливковым на среднем огне. Добавьте чеснок на минуту, затем выложите креветки в один слой, посолите и поперчите. Обжаривайте по 1–2 минуты с каждой стороны до розового цвета.</li><li>Добавьте артишоки и прогрейте 2 минуты. Снимите с огня, вмешайте петрушку, цедру и лимонный сок.</li><li>Выложите креветок с артишоками на пасту и перемешайте, при желании добавьте воду от варки. Подавайте с пармезаном.</li></ol><p><em>Посыпьте тёртым пармезаном и при желании добавьте немного воды от варки пасты для сочности.</em></p>', CURRENT_TIMESTAMP),
  ('3813fef3-3917-5d88-9f04-c66323295e81', '6440e3c8-d2d8-50ff-8bdb-e7e0a69d8beb', 'en', 'Shrimp and artichoke linguine with lemon garlic sauce', 'Linguine tossed with garlic-butter shrimp, artichoke hearts, parsley and lemon, finished with parmesan. Ready in 25 minutes.', '<ol><li>Zest one lemon and juice both. Drain the artichoke hearts, quarter them and pat dry.</li><li>Cook the linguine in a large pot of salted water 8–10 minutes. Reserve 1 cup of the cooking liquid and drain the pasta without rinsing.</li><li>Meanwhile in a large heavy pan melt the butter with the olive oil over medium heat. Add the garlic for a minute, then the shrimp in one layer with salt and pepper. Sauté 1–2 minutes per side until pink and opaque.</li><li>Add the artichokes and warm through 2 minutes. Remove from the heat and stir in the parsley, lemon zest and juice.</li><li>Pour the shrimp and artichokes over the pasta and toss, adding some pasta water if desired. Serve with parmesan.</li></ol><p><em>Sprinkle with grated parmesan and add a splash of pasta water for juicier pasta.</em></p>', CURRENT_TIMESTAMP),
  ('4481f85c-051a-5558-8aa6-4a7e688ad6e6', 'c931b18b-c1a4-5654-836d-89d189f96e2e', 'ru', 'Фуль медамес (египетские бобы с чесноком и лимоном)', 'Тёплое пюре из консервированных конских бобов с зирой, острым чесночно-лимонным соусом, петрушкой и помидорами. Постное и питательное блюдо.', '<ol><li>В чугунной сковороде или кастрюле прогрейте бобы с ½ стакана воды на среднем-сильном огне, посолите, добавьте зиру и разомните толкушкой или вилкой.</li><li>В ступке разотрите острый перец с чесноком, добавьте сок лимона и перемешайте.</li><li>Полейте бобы чесночно-лимонным соусом и щедро оливковым маслом. Сверху выложите рубленую петрушку, помидоры и кружочки острого перца.</li><li>Подавайте с питой, овощами и оливками.</li></ol><p><em>Подавайте с тёплой питой, овощами и оливками.</em></p>', CURRENT_TIMESTAMP),
  ('078d2d3e-7a7c-5653-b392-2227fd33764a', 'c931b18b-c1a4-5654-836d-89d189f96e2e', 'en', 'Foul mudammas (Egyptian fava beans)', 'Warm mashed canned fava beans with cumin, a zippy lemon-garlic-chili sauce, parsley and tomato. A hearty vegan dish.', '<ol><li>Warm the fava beans with ½ cup water in a skillet over medium-high heat, season with salt and cumin and mash with a potato masher or fork.</li><li>In a mortar crush the hot peppers with the garlic, then stir in the lemon juice.</li><li>Pour the garlic-pepper sauce over the beans and drizzle generously with olive oil. Top with parsley, diced tomatoes and sliced hot pepper.</li><li>Serve with pita, sliced vegetables and olives.</li></ol><p><em>Serve with warm pita, sliced vegetables and olives.</em></p>', CURRENT_TIMESTAMP),
  ('1136f1c9-7c11-5129-9dd9-cccb6e120310', '36901abb-ab12-5c06-b065-df21315f241f', 'ru', 'Веганская паста с сырным соусом из кешью и картофеля', 'Макароны в кремовом соусе из кешью, картофеля, лука и пищевых дрожжей, который по вкусу напоминает сырный. С брокколи по желанию.', '<ol><li>Доведите до кипения кастрюлю подсоленной воды и отварите макароны по инструкции. За 2–3 минуты до готовности добавьте брокколи. Слейте воду и переложите в большую миску.</li><li>Тем временем в кастрюле разогрейте масло на среднем огне, обжарьте лук с щепоткой соли около 5 минут до прозрачности.</li><li>Добавьте тёртый картофель, чеснок, чесночный и луковый порошок, горчичный порошок, соль и хлопья чили и около минуты помешивайте.</li><li>Добавьте кешью и воду, доведите до слабого кипения и готовьте 5–8 минут, часто помешивая, пока картофель не станет совсем мягким.</li><li>Осторожно перелейте в блендер, добавьте пищевые дрожжи и 2 ч. л. уксуса и взбивайте около 2 минут до полной гладкости, при необходимости добавляя воду по ¼ стакана. Попробуйте, досолите, при желании добавьте уксус.</li><li>Влейте соус в миску с макаронами, перемешайте и подавайте сразу.</li></ol><p><em>Подавайте сразу, остатки хранятся в холодильнике до 4 дней.</em></p>', CURRENT_TIMESTAMP),
  ('b94c1533-ddba-5a1e-b672-c020584e36d7', '36901abb-ab12-5c06-b065-df21315f241f', 'en', 'Vegan mac and cheese with cashew potato sauce', 'Elbow macaroni in a creamy cheese-like sauce blended from cashews, potato, onion and nutritional yeast, with broccoli if you like.', '<ol><li>Boil salted water and cook the pasta per package directions, adding the broccoli for the last 2–3 minutes. Drain and transfer to a large bowl.</li><li>Meanwhile warm the oil in a saucepan over medium heat and cook the onion with a pinch of salt about 5 minutes until translucent.</li><li>Add the grated potato, garlic, garlic powder, onion powder, mustard powder, salt and red pepper flakes and stir for about 1 minute.</li><li>Add the cashews and water, bring to a simmer and cook 5–8 minutes, stirring often, until the potatoes are completely tender.</li><li>Carefully pour into a blender, add the nutritional yeast and 2 tsp vinegar and blend about 2 minutes until completely smooth, adding water ¼ cup at a time if needed. Adjust salt and vinegar.</li><li>Pour the sauce over the pasta, stir to combine and serve immediately.</li></ol><p><em>Serve right away; leftovers keep 3 to 4 days refrigerated.</em></p>', CURRENT_TIMESTAMP),
  ('65751fee-1d94-54a2-bb4d-c1ecea676820', 'c956b28f-fd38-5698-b2b0-67f728a1e902', 'ru', 'Куриная грудка в беконе с соусом барбекю и сыром, с пюре и овощами', 'Куриное филе под ломтиками бекона запекается и покрывается соусом барбекю и пармезаном. Подаётся с картофельным пюре с луком, морковью и стручковой фасолью.', '<ol><li>Разогрейте духовку до 200 °C. Смажьте противень маслом, выложите куриные грудки, посолите и поперчите и накройте каждую двумя ломтиками бекона. Запекайте 20–25 минут до готовности.</li><li>Пока курица запекается, обжарьте красный лук в 1 ст. л. масла до золотистого цвета и мягкости, отставьте.</li><li>Отварите картофель в кипящей воде 10–15 минут до мягкости. В другой кастрюле по очереди отварите стручковую фасоль и морковь по 8–10 минут, чтобы остались слегка упругими.</li><li>Слейте картофель, добавьте молоко и сливочный сыр, посолите и разомните до гладкости, вмешайте жареный лук.</li><li>Полейте готовую курицу соусом барбекю, посыпьте пармезаном и верните в духовку на 2 минуты, пока сыр не расплавится. Подавайте с пюре, морковью и фасолью.</li></ol><p><em>Подайте с пюре, морковью и зелёной фасолью.</em></p>', CURRENT_TIMESTAMP),
  ('daa3df04-1db0-5140-81cf-2efdaa4e00d2', 'c956b28f-fd38-5698-b2b0-67f728a1e902', 'en', 'Hunter''s chicken with bacon, BBQ sauce and mash', 'Chicken breasts wrapped in bacon, baked and topped with BBQ sauce and Parmesan, served with onion mash, carrots and green beans.', '<ol><li>Heat the oven to 400 °F (200 °C). Oil a tray, set the chicken breasts on it, season and cover each with two bacon rashers. Bake 20–25 minutes until cooked through.</li><li>While the chicken bakes, fry the red onion in 1 tbsp of oil until golden and soft; set aside.</li><li>Boil the potatoes 10–15 minutes until soft. In another pan cook the green beans and carrots, one after the other, 8–10 minutes each until soft with a little bite.</li><li>Drain the potatoes, add the milk and soft cheese, season and mash until smooth, then stir through the fried onions.</li><li>Pour the BBQ sauce over the cooked chicken, scatter with Parmesan and return to the oven for 2 minutes until melted. Serve with the mash, carrots and beans.</li></ol><p><em>Serve with the mash, carrots and runner beans.</em></p>', CURRENT_TIMESTAMP),
  ('a19bd49f-b5ef-5d61-a030-936815f87297', '433a3dd2-1ba8-58c0-816c-114cb817541a', 'ru', 'Паста пенне с курицей и грибами в сливочном соусе с вином', 'Пенне с куриными бёдрами и шампиньонами в густом соусе из белого вина, бульона и сливок с чесноком и тимьяном. Уютный ужин на каждый день.', '<ol><li>Отварите пасту по инструкции, слейте воду, оставив стакан отвара.</li><li>Пока варится паста, обжаривайте шампиньоны на сухой сковороде на среднем огне около 10 минут, пока не выпарится жидкость. Добавьте масло, сливочное масло и нарезанных куриных бёдер и жарьте ещё 6–8 минут до золотистого цвета.</li><li>Добавьте чеснок и тимьян, посолите и поперчите, готовьте минуту. Влейте вино и уварите наполовину за 2–3 минуты, затем влейте бульон и готовьте 8–10 минут до готовности курицы.</li><li>Влейте сливки и прогрейте несколько минут. Смешайте с пастой, при необходимости добавьте отвар. Посыпьте пармезаном и петрушкой.</li></ol><p><em>Посыпьте пармезаном и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('34a5fe9c-f2a0-535b-9742-b13a3ce14e48', '433a3dd2-1ba8-58c0-816c-114cb817541a', 'en', 'Chicken and mushroom penne in white wine cream sauce', 'Penne with chicken thighs and mushrooms in a rich garlic and thyme sauce of white wine, stock and double cream. A comforting weeknight dinner.', '<ol><li>Cook the pasta following the pack instructions, drain and keep a cupful of the water.</li><li>Meanwhile fry the mushrooms in a dry pan over medium heat about 10 minutes until their liquid evaporates. Add the oil, butter and chopped chicken thighs and cook 6–8 minutes more until golden.</li><li>Add the garlic and thyme, season and cook a minute. Pour in the wine and reduce by half for 2–3 minutes, then add the stock and cook 8–10 minutes until the chicken is cooked.</li><li>Pour in the cream and heat for a few minutes. Toss in the pasta, adding pasta water if needed. Top with Parmesan and parsley.</li></ol><p><em>Finish with grated Parmesan and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('29714134-3841-5078-87ed-cece228dc5ce', 'cf21264a-176e-5e21-99b4-b4d4a354e09d', 'ru', 'Суп-пюре из батата с морковью и зирой', 'Мягкий, слегка пряный сливочный суп из батата, моркови и лука с зирой, кориандром и чесноком.', '<ol><li>В большой кастрюле на слабом-среднем огне разогрейте масло, добавьте лук и щепотку соли и жарьте 10–12 минут до мягкости без золотистого цвета.</li><li>Добавьте семена зиры, кориандр и чеснок на минуту, затем морковь на несколько минут. Положите батат и готовьте ещё несколько минут.</li><li>Влейте бульон, доведите до кипения и варите 20–25 минут до мягкости овощей.</li><li>Измельчите суп блендером до гладкости, влейте сливки, посолите и поперчите. Подавайте с хлебом.</li></ol><p><em>Подайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('46ca0eaa-4ea9-5a08-84c7-9b64ff2ffefb', 'cf21264a-176e-5e21-99b4-b4d4a354e09d', 'en', 'Sweet potato, carrot and cumin soup', 'A smooth, gently spiced soup of sweet potato, carrots and onions with cumin, coriander and garlic, finished with cream.', '<ol><li>Heat the oil in a large pan over medium-low, add the onions and a pinch of salt and fry 10–12 minutes until soft but not golden.</li><li>Add the cumin seeds, coriander and garlic for a minute until fragrant, then the carrots for a few minutes. Stir in the sweet potatoes and cook a few minutes more.</li><li>Pour in the stock, bring to a simmer and cook 20–25 minutes until the vegetables are tender.</li><li>Blitz until smooth with a hand or jug blender, stir in the cream and season. Serve with bread.</li></ol><p><em>Serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('37140e8c-afe6-5ecb-987c-0e302a0e3a8f', '876cbc87-8373-574e-9f69-d296a34e7b71', 'ru', 'Суп из порея с картофелем в мультиварке', 'Классический нежный суп-пюре из порея, лука и картофеля, томлёный в мультиварке и заправленный сметаной.', '<ol><li>Растопите масло в чаше мультиварки (на режиме жарки) или в сковороде. Обжарьте лук, порей и лавровый лист с щепоткой соли и перца 10–15 минут до мягкости. Если жарили на сковороде, переложите овощи в мультиварку.</li><li>Добавьте картофель кусочками и бульон, перемешайте, накройте и готовьте на низком режиме 6–7 часов (на высоком 3–4 часа) до полной мягкости картофеля.</li><li>Выньте лавровый лист, добавьте сметану и измельчите суп блендером до гладкости. Попробуйте и доведите по вкусу до нужной остроты и солёности.</li></ol><p><em>Посыпьте хрустящим пореем и чёрным перцем, подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('dbd09997-5a5f-5066-ba64-e7807346c112', '876cbc87-8373-574e-9f69-d296a34e7b71', 'en', 'Slow cooker leek and potato soup', 'A classic smooth soup of leeks, onion and potato slow-cooked until soft and finished with crème fraîche.', '<ol><li>Melt the butter in the slow cooker on sauté, or in a frying pan. Cook the onion, leeks and bay leaf with a pinch of salt and pepper for 10–15 minutes until soft. If using a pan, transfer the vegetables to the slow cooker.</li><li>Add the chopped potato and stock, stir, cover and cook on low for 6–7 hours or on high for 3–4 hours until the potato is completely soft.</li><li>Remove the bay leaf, stir in the crème fraîche and blitz until smooth with a hand blender. Taste and adjust the seasoning.</li></ol><p><em>Top with crispy leeks and black pepper and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('d7df59b0-17ef-5674-9368-9849bc87c19d', '46e585ba-cd92-5458-883f-b3e68c43cdf9', 'ru', 'Запечённый картофель слоями в молоке с луком', 'Тонко нарезанный картофель, слоями с луком, мукой и маслом, запечённый в горячем молоке с мускатным орехом до мягкости и румяных краёв.', '<ol><li>Разогрейте духовку до 200 °C. Смажьте маслом форму 28×18 см. Выложите слой картофеля с небольшим нахлёстом (четверть), посыпьте четвертью лука, посолите, поперчите, добавьте щепотку мускатного ореха и 1 ст. л. муки, разложите кусочки масла.</li><li>Повторите слои ещё три раза, в последнем слое муку не кладите.</li><li>Подогрейте молоко до первых пузырьков по краям и залейте картофель. Накройте и запекайте 30 минут, затем без крышки ещё 1–1 час 10 минут до мягкости картофеля и золотистых краёв.</li><li>Дайте постоять 5–10 минут, посыпьте петрушкой и подавайте горячим.</li></ol><p><em>Подайте как гарнир к мясу или курице, посыпав петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('7b28751f-dbf2-5918-b4b1-4588627772eb', '46e585ba-cd92-5458-883f-b3e68c43cdf9', 'en', 'Scalloped potatoes with milk and onion', 'Thinly sliced potatoes layered with onion, flour and butter and baked in warm milk with nutmeg until tender with golden edges.', '<ol><li>Heat the oven to 400 °F (200 °C). Butter a 28 × 18 cm dish. Lay a quarter of the potatoes in overlapping slices, sprinkle a quarter of the onion, then season with salt, pepper, a pinch of nutmeg and 1 tbsp of flour and dot with butter.</li><li>Repeat the layers three more times, leaving the flour out of the final layer.</li><li>Warm the milk until bubbles just form at the edges and pour it over the potatoes. Cover and bake 30 minutes, then uncover and bake 1 hour to 1 hour 10 minutes more until tender with golden edges.</li><li>Let stand 5–10 minutes, sprinkle with parsley and serve hot.</li></ol><p><em>Serve as a side with meat or poultry, sprinkled with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('9578bf24-a5e4-5e4a-a38e-d4a7fa2eb9a3', '1b0c7206-d0a4-5af5-9bd3-d0812137cf2d', 'ru', 'Запечённый картофель, фаршированный беконом, сметаной и чеддером', 'Печёные картофелины с мякотью, смешанной с хрустящим беконом, шнитт-луком, сметаной и сыром чеддер, запечённые повторно до румяной корочки.', '<ol><li>Разогрейте духовку до 200 °C. Сделайте на картофелинах несколько надрезов, выложите на противень с пергаментом и запекайте 45–50 минут, перевернув на полпути, пока внутри не станет мягко, а снаружи золотисто.</li><li>Разрежьте картофель вдоль пополам, вынимайте мякоть в миску, оставляя тонкий слой у кожуры. Кожуру верните на противень.</li><li>Добавьте к мякоти нарезанный бекон, шнитт-лук, сметану и сыр и разомните вместе, посолите и поперчите.</li><li>Плотно набейте начинкой кожуру, посыпьте сверху сыром и запекайте 20 минут до золотистого цвета. Подавайте с беконом и шнитт-луком.</li></ol><p><em>Посыпьте беконом и шнитт-луком, подайте с салатом.</em></p>', CURRENT_TIMESTAMP),
  ('5275dced-ff7e-55f5-8f80-081c1d4d4c6e', '1b0c7206-d0a4-5af5-9bd3-d0812137cf2d', 'en', 'Twice-baked potatoes with bacon and cheddar', 'Baked potato skins filled with the mashed flesh mixed with crispy bacon, chives, soured cream and cheddar, then baked again until golden and bubbling.', '<ol><li>Heat the oven to 400 °F (200 °C). Make a few small cuts in each potato, set on a parchment-lined tray and bake 45–50 minutes, turning halfway, until soft inside and golden outside.</li><li>Halve the potatoes lengthways and scoop the flesh into a bowl, leaving a slim border in the skins. Put the skins back on the tray.</li><li>Add the chopped bacon, chives, soured cream and cheddar to the potato flesh, mash everything together and season.</li><li>Pack the filling into the skins, top with extra cheese and bake 20 minutes until golden. Serve with bacon and chives.</li></ol><p><em>Top with extra bacon and chives and serve with a salad.</em></p>', CURRENT_TIMESTAMP),
  ('e749306e-a99c-5449-8654-67322431faef', '9bb3be5f-02ca-50df-99dc-6d507a5cc2d7', 'ru', 'Кима из куриного фарша с горошком и карри', 'Бюджетное индийское блюдо: куриный фарш, обжаренный с луком, чесноком, карри и зелёным горошком. Готовится за 25 минут.', '<ol><li>Разогрейте масло в глубокой сковороде на средне-сильном огне. Добавьте куриный фарш, лук, чеснок, карри, горошек и крошеный бульонный кубик и готовьте 5 минут, разбивая фарш, пока он не побелеет.</li><li>Влейте 120 мл кипятка и готовьте ещё 15 минут, регулярно помешивая. Посолите по вкусу.</li><li>Разложите по тарелкам и подавайте с отварным рисом.</li></ol><p><em>Подайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('dbe65ba5-9653-5747-bee7-294bc8549373', '9bb3be5f-02ca-50df-99dc-6d507a5cc2d7', 'en', 'Chicken keema with peas', 'A budget Indian-style dish of chicken mince cooked with onion, garlic, curry powder and green peas, ready in 25 minutes.', '<ol><li>Heat the oil in a large deep pan over medium-high heat. Add the chicken mince, onion, garlic, curry powder, peas and crumbled stock cube and cook 5 minutes, breaking up the mince, until browned.</li><li>Pour in 120 ml of boiling water and continue cooking 15 minutes, stirring regularly. Season to taste.</li><li>Divide between bowls and serve with steamed rice.</li></ol><p><em>Serve with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('d192e0ba-306d-58b3-92ea-bf29eed9c7db', 'c082c528-3a23-5d59-82a1-d9c776c47222', 'ru', 'Колбасные фрикадельки с фенхелем и фасолью в сливочно-томатном соусе', 'Сочные фрикадельки из колбасного фарша с рикоттой и фенхелем, запечённые на белой фасоли в сливочно-томатном соусе.', '<ol><li>В кастрюле разогрейте масло на среднем огне, обжарьте чеснок 1 минуту, добавьте томатное пюре на минуту. Влейте томаты (ополосните банку водой и добавьте её), положите фасоль и варите 10 минут.</li><li>Смешайте руками колбасный фарш, семена фенхеля, рикотту, пармезан и панировочные сухари, поперчите. Скатайте 12 шариков.</li><li>Снимите соус с огня, влейте сливки, посолите по вкусу. Разогрейте духовку до 200 °C.</li><li>Вылейте фасоль в соусе в неглубокую форму, сверху выложите фрикадельки и запекайте 25–30 минут. Посыпьте пармезаном и базиликом.</li></ol><p><em>Посыпьте пармезаном и свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('1518822c-0c5f-536f-8e0a-8ced86be15e2', 'c082c528-3a23-5d59-82a1-d9c776c47222', 'en', 'Sausage and fennel meatballs with creamy tomato butter beans', 'Juicy meatballs made from sausagemeat, ricotta and fennel seeds, baked on top of butter beans in a creamy tomato sauce.', '<ol><li>Heat the oil in a pan over medium, cook the garlic 1 minute, then the tomato purée for 1 minute. Add the tomatoes (swill out the can with water and add that too) and the beans and simmer for 10 minutes.</li><li>Mix the sausagemeat, fennel seeds, ricotta, Parmesan and breadcrumbs with pepper by hand and shape into 12 balls.</li><li>Take the sauce off the heat, stir in the cream and season to taste. Heat the oven to 400 °F (200 °C).</li><li>Pour the creamy beans into a shallow baking dish, place the meatballs on top and bake 25–30 minutes. Top with Parmesan and basil.</li></ol><p><em>Top with extra Parmesan and fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('0b39c07f-aeea-5756-8728-d048eaca425b', '66bbabe2-8cc9-5694-8ff0-09f516b66f5c', 'ru', 'Паста с брокколи, чесноком и пармезаном', 'Простое блюдо в одной кастрюле: паста и брокколи варятся вместе, затем обжариваются с золотистым чесноком, оливковым маслом и сыром. Готово за 15 минут.', '<ol><li>Доведите до кипения большую кастрюлю подсоленной воды.</li><li>Положите в кипяток пасту и брокколи одновременно и варите до состояния аль денте по инструкции на пачке.</li><li>Перед концом варки отлейте около стакана воды из кастрюли, затем слейте воду с пасты и брокколи.</li><li>Верните кастрюлю на сильный огонь, влейте 1 ст. л. масла и обжарьте чеснок до золотистого цвета. Убавьте огонь до слабого и верните пасту.</li><li>Перемешайте, добавьте остальное масло, тёртый сыр, соль и перец, разминая крупные кусочки брокколи. Влейте ½ стакана воды от варки, при необходимости добавьте ещё, и подавайте.</li></ol><p><em>Подавайте с дополнительным тёртым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('9205967e-45e6-574b-9db7-f3b121922234', '66bbabe2-8cc9-5694-8ff0-09f516b66f5c', 'en', 'Pasta with broccoli, garlic and parmesan', 'A simple one-pot dinner: pasta and broccoli cook together, then are tossed with golden garlic, olive oil and grated cheese. Ready in 15 minutes.', '<ol><li>Bring a large pot of salted water to a boil.</li><li>Add the pasta and broccoli at the same time and cook until the pasta is al dente per package directions.</li><li>Near the end reserve about 1 cup of the cooking water, then drain the pasta and broccoli.</li><li>Return the pot to high heat, add 1 tbsp olive oil and cook the garlic until golden. Reduce to low and add the pasta back.</li><li>Mix in the remaining oil, cheese, salt and pepper, smashing large broccoli pieces. Add ½ cup of the pasta water, more if needed, and serve.</li></ol><p><em>Serve with extra grated cheese on the side.</em></p>', CURRENT_TIMESTAMP),
  ('66c58690-e6a2-5417-82d2-8ee1445ef86b', 'ee31ffa8-21ec-50b5-b18f-750b1764f312', 'ru', 'Быстрый чили с говядиной и чёрной фасолью', 'Густое блюдо из нежирного говяжьего фарша, чёрной фасоли, помидоров, красного перца и томатного соуса со специями. Готовится под давлением, на плите или в мультиварке.', '<ol><li>Включите режим обжарки в мультиварке-скороварке, обжарьте фарш с солью около 5 минут, разбивая на кусочки 2 см.</li><li>Добавьте лук и перец на 1–2 минуты, затем фасоль, помидоры, томатный соус, бульон и специи.</li><li>Закройте крышку и готовьте на высоком давлении 20 минут, затем дайте давлению снизиться само. Попробуйте, досолите. На плите: накройте и готовьте на слабом огне не меньше часа, периодически помешивая. В мультиварке на медленном режиме: 8 часов.</li></ol><p><em>Подавайте с красным луком, кинзой, лаймом и авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('c869cd1a-b4cc-5686-a0f2-d37f0b70b782', 'ee31ffa8-21ec-50b5-b18f-750b1764f312', 'en', 'Quick beef chili with black beans', 'Hearty chili with lean ground beef, black beans, tomatoes, red bell pepper and tomato sauce, made in a pressure cooker, on the stove or in a slow cooker.', '<ol><li>Set the pressure cooker to sauté, brown the beef with the salt for 5 minutes, breaking it into ¾-inch crumbles.</li><li>Add the onion and pepper for 1–2 minutes, then the beans, tomatoes, tomato sauce, broth and spices.</li><li>Cover and cook on high pressure 20 minutes with a natural release. Taste and adjust the salt. On the stove: cover and simmer on low at least an hour, stirring. In a slow cooker: cook on low 8 hours.</li></ol><p><em>Serve with red onion, cilantro, lime and avocado.</em></p>', CURRENT_TIMESTAMP),
  ('a81493cf-2733-5b93-b5ee-cb2ca183a4d9', 'c07e9ac3-12a0-5c74-a420-135b79b1d199', 'ru', 'Салат с рукколой, арбузом, фетой и оливками', 'Летний салат из рукколы, кубиков арбуза, феты и оливок каламата с заправкой из оливкового масла, шалота и хересного уксуса.', '<ol><li>В миске соедините рукколу, кубики арбуза, фету и оливки.</li><li>Заправка: взбейте оливковое масло, шалот, уксус, щедрую щепотку соли и перец. Попробуйте и при необходимости досолите, помня, что в салате есть солёные ингредиенты.</li><li>Перед подачей снова взбейте заправку, полейте салат примерно половиной, аккуратно перемешайте и при необходимости добавьте ещё. Подавайте сразу.</li></ol><p><em>Заправляйте непосредственно перед подачей, чтобы руккола не завяла.</em></p>', CURRENT_TIMESTAMP),
  ('eeb01f0b-225a-582e-b3f5-c1b77ba0b7b9', 'c07e9ac3-12a0-5c74-a420-135b79b1d199', 'en', 'Arugula, watermelon and feta salad', 'Summer salad of peppery arugula, juicy watermelon cubes, feta and Kalamata olives with a shallot and sherry vinegar vinaigrette.', '<ol><li>In a serving bowl combine the arugula, watermelon, feta and olives.</li><li>Vinaigrette: whisk the olive oil, shallot, vinegar, a hefty pinch of salt and pepper. Taste and adjust, keeping in mind the salad has salty ingredients.</li><li>Right before serving whisk again, drizzle about half over the salad, toss gently and add more if needed. Serve immediately.</li></ol><p><em>Dress it just before serving so the arugula doesn''t wilt.</em></p>', CURRENT_TIMESTAMP),
  ('d2f5e3fe-2b87-5988-a73f-7af60a2c89ad', '02b15865-bd13-5a8b-98dd-5efc3d02bce3', 'ru', 'Бургеры из индейки', 'Сочные котлеты из фарша индейки с панировочными сухарями, луком, кетчупом и горчицей в булочке. Готовятся на сковороде, гриле или в аэрогриле.', '<ol><li>В большой миске смешайте фарш индейки, сухари, сушёный лук, кетчуп, горчицу, вустерский соус, чеснок и соль.</li><li>Сформуйте 4 одинаковые котлеты толщиной около 1,3 см, слегка придавив, чтобы они прожарились до середины.</li><li>На плите: разогрейте антипригарную сковороду на среднем-слабом огне, слегка смажьте маслом, выложите котлеты и убавьте огонь. Жарьте по 4–5 минут с каждой стороны до румяности и готовности. На гриле: по 5 минут с каждой стороны до 74 °C внутри. В аэрогриле: при 200 °C по 4–5 минут с каждой стороны.</li><li>Пока готовятся котлеты, подготовьте булочки (при желании подсушите) и начинки. Выложите котлеты в булочки с добавками и подавайте сразу.</li></ol><p><em>Подавайте с помидором, красным луком, салатом и любимым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('289f9324-4007-592f-bc90-546f7a8db6d3', '02b15865-bd13-5a8b-98dd-5efc3d02bce3', 'en', 'Turkey burgers', 'Juicy ground turkey patties with breadcrumbs, onion, ketchup and mustard, served on buns. Cooked on the stove, grill or in an air fryer.', '<ol><li>In a large bowl combine the ground turkey, breadcrumbs, dried onion, ketchup, mustard, Worcestershire, garlic and salt.</li><li>Shape 4 equal patties about ½ inch thick, pressing down so they cook through in the center.</li><li>On the stove: heat a nonstick skillet over medium-low, lightly oil it, add the patties and reduce to low; cook 4–5 minutes per side until browned and cooked through. On a grill: about 5 minutes per side to 165 °F (74 °C). In an air fryer: 400 °F (200 °C) 4–5 minutes per side.</li><li>While the patties cook prepare the buns (toast if you like) and toppings. Assemble the burgers and serve immediately.</li></ol><p><em>Serve with tomato, red onion, lettuce and your favorite sauce.</em></p>', CURRENT_TIMESTAMP),
  ('e317e339-49e5-5d6a-b8e3-f402f368f26f', 'b00dc5a9-bfb6-5abf-b48e-5cb56ade65d0', 'ru', 'Щи из свежей и квашеной капусты с сушёными грибами', 'Традиционный русский суп из белокочанной и квашеной капусты с картофелем, морковью, луком и сушёными грибами на курином бульоне. В скороварке готовится заметно быстрее.', '<ol><li>Залейте сушёные грибы стаканом кипятка и оставьте размокать.</li><li>Включите режим жарки в скороварке, разогрейте масло и 5–7 минут обжарьте лук и тёртую морковь с солью и перцем до мягкости.</li><li>Промойте размокшие грибы, жидкость сохраните. Добавьте грибы к овощам, процедите настой через сито с бумажным полотенцем и влейте в кастрюлю. Влейте бульон, посолите и поперчите.</li><li>Закройте крышку, клапан в положении «закрыт», режим высокого давления на 15 минут. Сбросьте давление вручную.</li><li>Добавьте картофель, свежую и квашеную капусту, снова закройте и готовьте под давлением ещё 15 минут. Сбросьте давление. Если овощи недостаточно мягкие, готовьте ещё. Без скороварки варите на плите под крышкой около 40 минут.</li><li>Подавайте со свежей зеленью и сметаной.</li></ol><p><em>Подайте со сметаной и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('89d612e3-2543-57ec-a4dd-d700562620fe', 'b00dc5a9-bfb6-5abf-b48e-5cb56ade65d0', 'en', 'Shchi: fresh and sauerkraut cabbage soup with dried mushrooms', 'A traditional Russian soup of fresh cabbage and sauerkraut with potatoes, carrot, onion and dried mushrooms in chicken broth. Much quicker in a pressure cooker.', '<ol><li>Cover the dried mushrooms with 1 cup of boiling water and leave to rehydrate.</li><li>Set the pressure cooker to sauté, heat the butter or oil and cook the onion and grated carrot with salt and pepper for 5–7 minutes until soft.</li><li>Rinse the rehydrated mushrooms, keeping the liquid. Add them to the vegetables, strain the soaking liquid through a paper-towel-lined sieve into the pot and pour in the broth. Season.</li><li>Close the lid with the valve on Sealing and cook at high pressure for 15 minutes. Release the pressure manually.</li><li>Add the potatoes, fresh cabbage and sauerkraut, close again and pressure cook 15 more minutes, then release the pressure. Cook longer if not tender. Without a pressure cooker, simmer covered on the stove about 40 minutes.</li><li>Serve with fresh herbs and sour cream.</li></ol><p><em>Serve with sour cream and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('4205f1ca-838d-5186-82d9-ee7cf1df48de', 'c5538d99-6096-5477-a4b3-e490c7da42f0', 'ru', 'Манная каша на молоке', 'Нежная жидкая манная каша на половине молока и половине воды со сливочным маслом и сахаром. Любимый детский завтрак.', '<ol><li>Влейте молоко и воду в кастрюльку, всыпьте манную крупу и перемешайте.</li><li>Доведите на среднем-сильном огне до кипения, часто помешивая венчиком, чтобы не было комков. Убавьте огонь и варите 1–2 минуты, пока каша не загустеет.</li><li>Добавьте масло, соль и сахар по вкусу и подавайте тёплой.</li></ol><p><em>Подайте тёплой с кусочком масла, вареньем или свежими ягодами.</em></p>', CURRENT_TIMESTAMP),
  ('2a6b983d-1777-5680-a3b3-cb6fd37f97f7', 'c5538d99-6096-5477-a4b3-e490c7da42f0', 'en', 'Semolina porridge (mannaya kasha) with milk and butter', 'A creamy semolina (cream of wheat) porridge cooked in half milk and half water with butter and a little sugar. A classic children''s breakfast.', '<ol><li>Pour the milk and water into a small pot, add the semolina and stir.</li><li>Bring to a boil over medium-high heat, whisking often to prevent lumps. Reduce to a simmer and cook 1–2 minutes until thickened.</li><li>Add the butter, salt and sugar to taste and serve warm.</li></ol><p><em>Serve warm with butter, jam or fresh berries.</em></p>', CURRENT_TIMESTAMP),
  ('0f7f207a-4c9a-5c0b-a67c-5ed8bba9d450', '8489e0eb-5d0a-52ac-92e9-afde2ef933a2', 'ru', 'Запеканка из гречки с грибами и курицей под сыром', 'Гречневая каша с луком, свежими и сушёными грибами, на ней куриное филе под сметаной и расплавленным сыром, запечённое в духовке.', '<ol><li>Разогрейте духовку до 175 °C и щедро смажьте маслом форму на 2 л.</li><li>Залейте сушёные грибы кипятком на 10 минут. Отожмите, настой процедите через сито с бумажным полотенцем, чтобы убрать песок, и долейте горячей водой до 360 мл. Грибы мелко нарубите.</li><li>В глубокой сковороде на среднем огне обжарьте лук с солью и перцем 3–5 минут. Добавьте свежие и сушёные грибы и чеснок и жарьте 6–8 минут до золотистого цвета.</li><li>Всыпьте гречку и обжаривайте с грибами около 2 минут, влейте грибной настой, доведите до кипения, накройте и варите на слабом огне около 10 минут, пока почти вся жидкость не впитается. Переложите в форму ровным слоем.</li><li>Разрежьте каждую грудку вдоль пополам, затем ещё пополам, посолите и поперчите. Уложите на гречку, смажьте сметаной и посыпьте тёртым сыром.</li><li>Запекайте около 25 минут, пока курица не приготовится, а сыр не станет золотистым и пузырящимся.</li></ol><p><em>Подайте со свежим салатом или солёными огурцами.</em></p>', CURRENT_TIMESTAMP),
  ('48baae81-a8d3-5e81-a849-0310ab9066f7', '8489e0eb-5d0a-52ac-92e9-afde2ef933a2', 'en', 'Chicken, mushroom and buckwheat casserole', 'Buckwheat cooked with onion, fresh and dried mushrooms, topped with chicken breast, sour cream and melted cheese and baked in the oven.', '<ol><li>Heat the oven to 350 °F (175 °C) and generously butter a 2-quart casserole dish.</li><li>Cover the dried mushrooms with boiling water for 10 minutes. Strain the liquid through a paper-towel-lined sieve to remove grit and top up with hot water to 1½ cups (360 ml). Finely chop the mushrooms.</li><li>In a large deep skillet over medium heat cook the onion with salt and pepper 3–5 minutes. Add the fresh and dried mushrooms and garlic and cook 6–8 minutes until golden.</li><li>Add the buckwheat and toast with the mushrooms about 2 minutes, pour in the mushroom liquid, bring to a boil, cover and simmer about 10 minutes until most of the liquid is absorbed. Spread in the casserole dish.</li><li>Cut each chicken breast in half horizontally, then in half again, and season with salt and pepper. Arrange over the buckwheat, spread with sour cream and top with the grated cheese.</li><li>Bake about 25 minutes until the chicken is cooked through and the cheese is bubbly and golden.</li></ol><p><em>Serve with a fresh salad or pickles.</em></p>', CURRENT_TIMESTAMP),
  ('727c9a97-7a05-5f59-82c1-4fae948bbb19', 'c0d3c95e-a3a5-5296-ac36-60181ea2528d', 'ru', 'Суп из жёлтой свёклы с овощами', 'Лёгкий прозрачный суп вроде борща, но из золотистой свёклы, с картофелем, морковью, кабачком, сладким перцем и зеленью.', '<ol><li>В толстостенной кастрюле разогрейте масло, посолите порей и жарьте около 3 минут до мягкости.</li><li>Добавьте морковь, сельдерей и чеснок, посолите и поперчите, жарьте 3–5 минут до мягкости моркови. Добавьте свёклу и готовьте ещё 3–5 минут.</li><li>Влейте стакан бульона, доведите до кипения, убавьте огонь и тушите под крышкой 10–15 минут, чтобы свёкла успела размякнуть.</li><li>Влейте остальной бульон и воду (количество воды по густоте), доведите до кипения. Добавьте картофель и варите 5–7 минут, затем болгарский перец и варите до готовности картофеля и свёклы.</li><li>Добавьте кабачок и варите 3–5 минут. Посыпьте зеленью, подавайте со сметаной или с лимонным соком.</li></ol><p><em>Подайте со сметаной и свежей зеленью; без сметаны добавьте немного лимонного сока.</em></p>', CURRENT_TIMESTAMP),
  ('10bafe86-2dc7-5e02-8dd9-c7e3d70731a6', 'c0d3c95e-a3a5-5296-ac36-60181ea2528d', 'en', 'Golden beet and vegetable soup', 'A light brothy soup like borscht but made from golden beets, with potatoes, carrots, zucchini, sweet pepper and herbs.', '<ol><li>Heat the oil in a heavy pot, add the leeks with salt and cook about 3 minutes until tender.</li><li>Add the carrots, celery and garlic with salt and pepper and cook 3–5 minutes until the carrots soften. Add the beet and cook 3–5 minutes more.</li><li>Pour in 1 cup of the broth, bring to a boil, reduce the heat and simmer covered 10–15 minutes so the beet gets a head start.</li><li>Add the remaining broth and the water (adjust to your taste for thickness) and bring to a boil. Add the potatoes and cook 5–7 minutes, then the bell pepper and cook until the potatoes and beet are done.</li><li>Add the zucchini and cook 3–5 minutes. Garnish with herbs and serve with sour cream or a splash of lemon juice.</li></ol><p><em>Serve with sour cream and fresh herbs; add a little lemon juice if serving without cream.</em></p>', CURRENT_TIMESTAMP),
  ('f69c916e-b98c-54c3-ae76-c93cef089eb7', 'dab89417-57db-5b92-9c76-b24f51470e37', 'ru', 'Суп с картофелем, кейлом и колбасками из индейки', 'Сытный лёгкий суп с картофелем, морковью, листовой капустой кейл и итальянскими колбасками из индейки или курицы на курином бульоне.', '<ol><li>В большой кастрюле обжарьте колбаски на среднем-слабом огне около 10 минут до румяности. Выложите, остудите и нарежьте тонкими ломтиками.</li><li>Добавьте в кастрюлю масло, лук и морковь и готовьте на среднем огне около 5 минут до мягкости, затем чеснок на 1 минуту.</li><li>Влейте бульон и воду, добавьте перец, колбаски, картофель и хлопья чили и доведите до кипения. Варите под крышкой 10–15 минут.</li><li>Положите кейл и готовьте под неплотной крышкой 5–6 минут до мягкости картофеля. При необходимости досолите.</li></ol><p><em>Подавайте горячим со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('13fa8e7e-68e0-5ac5-89fb-78bfefef41dc', 'dab89417-57db-5b92-9c76-b24f51470e37', 'en', 'Kale and potato soup with turkey sausage', 'Hearty, light soup with potatoes, carrots, kale and Italian turkey or chicken sausage in chicken broth.', '<ol><li>In a large pot cook the sausage over medium-low heat about 10 minutes until browned. Remove, cool and slice thinly.</li><li>Add the oil, onion and carrot and cook on medium about 5 minutes until soft, then the garlic for 1 more minute.</li><li>Add the broth, water, black pepper, sausage, potatoes and red pepper flakes and bring to a boil. Cook covered 10–15 minutes.</li><li>Add the kale and cook partially covered 5–6 minutes until the potatoes are tender. Adjust the salt.</li></ol><p><em>Serve hot with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('02fe0bef-672e-5059-97e0-eef2714903d4', '9987a976-5653-5a03-aa3c-f2b0dbfda430', 'ru', 'Колбаса из индейки с овощами на противне', 'Копчёная колбаса из индейки со спаржей, помидорами и болгарским перцем, запечённая на одном противне. Мало углеводов, без глютена.', '<ol><li>Разогрейте духовку до 200 °C. Застелите противень фольгой и хорошо смажьте маслом.</li><li>Выложите колбасу ломтиками толщиной 1,3 см в один слой. Запекайте 12–15 минут, пока низ не подрумянится.</li><li>Тем временем смешайте в миске овощи. В небольшой миске взбейте масло, соль, итальянские травы, паприку, чесночный порошок и перец, полейте овощи и перемешайте.</li><li>Выньте противень, переверните колбасу и сдвиньте на одну сторону. Выложите овощи в один слой на свободную часть противня.</li><li>Запекайте ещё 18–20 минут, пока овощи не станут мягкими, а колбаса не подрумянится сильнее.</li></ol><p><em>Подавайте горячим как есть или с горчицей.</em></p>', CURRENT_TIMESTAMP),
  ('65d18be0-2e9b-52e4-9368-ba4f351521a5', '9987a976-5653-5a03-aa3c-f2b0dbfda430', 'en', 'Turkey kielbasa and veggie sheet pan dinner', 'Turkey kielbasa roasted with asparagus, tomatoes and bell pepper on one sheet pan. Low carb and gluten-free.', '<ol><li>Preheat the oven to 400 °F (200 °C). Line a large baking sheet with foil and grease well.</li><li>Arrange the kielbasa slices (½ in thick) in a single layer and roast 12–15 minutes until browned underneath.</li><li>Meanwhile toss the vegetables in a large bowl. Whisk the oil, salt, Italian seasoning, paprika, garlic powder and pepper and pour over the vegetables, tossing to coat.</li><li>Remove the pan, flip the kielbasa and push it to one side, then spread the vegetables in a single layer on the other side.</li><li>Roast another 18–20 minutes until the vegetables are tender and the kielbasa is browned.</li></ol><p><em>Serve hot as is or with mustard.</em></p>', CURRENT_TIMESTAMP),
  ('ebfe9672-343b-5dfd-ab31-56752324f9da', '6a754904-989d-5ba8-be63-3666880af7f9', 'ru', 'Лёгкий суп-пюре из тыквы с шалфеем', 'Нежный низкокалорийный суп из мускатной тыквы, моркови, сельдерея и лука с шалфеем и каплей молока. Готовится в одной кастрюле.', '<ol><li>Очистите тыкву от кожуры и семян и нарежьте средними кубиками. Очистите морковь.</li><li>В большой кастрюле соедините тыкву, морковь, сельдерей, лук, чеснок, шалфей и бульон и доведите до кипения. Накройте и варите на слабом огне около 40 минут до мягкости тыквы.</li><li>Выньте шалфей и пюрируйте суп погружным блендером.</li><li>Влейте молоко, посолите и поперчите по вкусу. Подавайте горячим.</li></ol><p><em>Хорош с тёртым пармезаном и гренками.</em></p>', CURRENT_TIMESTAMP),
  ('9a82f41d-086d-516e-a8e2-ecc8ab262fce', '6a754904-989d-5ba8-be63-3666880af7f9', 'en', 'Light butternut squash soup with sage', 'Silky low-calorie soup of butternut squash, carrot, celery and onion simmered with sage and finished with a splash of milk.', '<ol><li>Peel and seed the squash and cut it into medium cubes. Peel the carrot.</li><li>In a large heavy pot combine the squash, carrot, celery, onion, garlic, sage and broth and bring to a boil. Cover and simmer on low about 40 minutes until the squash is tender.</li><li>Discard the sage and purée the soup with an immersion blender.</li><li>Stir in the milk, adjust the salt and pepper and serve hot.</li></ol><p><em>Great topped with grated parmesan and croutons.</em></p>', CURRENT_TIMESTAMP),
  ('babcc5e3-d2b8-5e48-b3a0-538087d0a7a3', '54cef863-5bca-5564-ba69-fd825e297312', 'ru', 'Куриные голени с лимоном, орегано и фетой', 'Куриные голени без кожи, запечённые с лимонным соком, чесноком и орегано и посыпанные фетой, которая подрумянивается под грилем.', '<ol><li>Разогрейте духовку до 190 °C.</li><li>Посыпьте голени солью, перцем, чесночным порошком и орегано и сбрызните лимонным соком.</li><li>Выложите в форму и запекайте 40–45 минут, пока мясо у кости не перестанет быть розовым.</li><li>Достаньте, посыпьте тёртой фетой и поставьте под слабый гриль на 2–3 минуты до золотистого цвета сыра, следя, чтобы не подгорел.</li></ol><p><em>Подавайте с рисом, картофелем или греческим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e597794f-5842-5cc3-b70f-1bf6b225856e', '54cef863-5bca-5564-ba69-fd825e297312', 'en', 'Lemon feta baked chicken drumsticks with oregano', 'Skinless chicken drumsticks baked with lemon juice, garlic and oregano and topped with feta that browns under the broiler.', '<ol><li>Preheat the oven to 375 °F (190 °C).</li><li>Season the drumsticks with salt, pepper, garlic powder and oregano and sprinkle with the lemon juice.</li><li>Place in a roasting pan and bake 40–45 minutes until no longer pink near the bone.</li><li>Remove, sprinkle with the feta and broil on low 2–3 minutes until the cheese is golden, watching so it doesn''t burn.</li></ol><p><em>Serve with rice, potatoes or a Greek salad.</em></p>', CURRENT_TIMESTAMP),
  ('bd091cd5-6a1d-5e93-aeca-fd71f1b063e0', '9f9e999c-3309-5ec4-a43e-c8f0dc10b381', 'ru', 'Свиные отбивные с кабачком, запечёнными помидорами, оливками и фетой', 'Тонкие свиные отбивные без кости, обжаренные на сковороде и поданные с соломкой из кабачка, запечёнными помидорами с чесноком, оливками, лимоном и фетой.', '<ol><li>Разогрейте духовку до 230 °C. Посолите, поперчите отбивные и посыпьте чесночным порошком.</li><li>Нарежьте кабачок тонкой соломкой (на мандолине или тёркой для моркови по-корейски).</li><li>Смешайте помидоры с половиной ст. л. масла, щепоткой соли, перцем и орегано. Выложите срезом вверх на смазанный противень и запекайте 10 минут. Добавьте чеснок ломтиками и запекайте ещё 5 минут. Переложите в миску.</li><li>Понизьте температуру духовки до 95 °C. На сковороде разогрейте оставшееся масло и жарьте кабачок с щепоткой соли около 5 минут до мягкости. Добавьте к помидорам и поставьте в тёплую духовку.</li><li>Обжарьте отбивные в два приёма на среднем-сильном огне по 1,5–2 минуты с каждой стороны (они тонкие, пересушить легко). Переложите на блюдо.</li><li>Достаньте овощи, смешайте с оливками, лимонным соком и цедрой. Выложите на мясо и посыпьте фетой.</li></ol><p><em>Выложите овощи поверх мяса и посыпьте фетой.</em></p>', CURRENT_TIMESTAMP),
  ('d20d87d4-ae97-5fe9-bd89-047451059980', '9f9e999c-3309-5ec4-a43e-c8f0dc10b381', 'en', 'Mediterranean boneless pork chops with zucchini, tomatoes and feta', 'Thin boneless pork chops pan-seared and served over julienned zucchini with roasted tomatoes, garlic, olives, lemon and feta.', '<ol><li>Preheat the oven to 450 °F (230 °C). Season the pork chops with salt, pepper and garlic powder.</li><li>Cut the zucchini into thin julienne strips with a mandoline or spiralizer.</li><li>Toss the tomatoes with ½ tbsp oil, a pinch of salt, pepper and oregano. Place cut-side up on a greased baking sheet and roast 10 minutes, add the sliced garlic and roast 5 more minutes. Transfer to a bowl.</li><li>Lower the oven to 200 °F (95 °C). Heat the remaining oil in a large non-stick skillet and sauté the zucchini with a pinch of salt about 5 minutes until tender. Add to the tomatoes and keep warm in the oven.</li><li>Cook the pork chops in two batches over medium-high heat 1½–2 minutes per side (they are thin and easily overcooked). Set aside on a platter.</li><li>Remove the vegetables, toss with the olives, lemon juice and zest, serve over the pork and top with feta.</li></ol><p><em>Pile the vegetables over the chops and top with feta.</em></p>', CURRENT_TIMESTAMP),
  ('b1e51f0a-6c8d-5784-b8a0-b5094376b02b', '7dbb8427-ff1f-5fe2-96f6-e350402e78cc', 'ru', 'Куриная грудка с пармезаном и брокколи на одном противне', 'Куриные грудки, запечённые на противне с брокколи и покрытые чесночно-пармезановой смесью с петрушкой, которая запекается до золотистой корочки.', '<ol><li>Разогрейте духовку до 220 °C. Смажьте противень 1 ст. л. оливкового масла.</li><li>Выложите куриные грудки в центр противня, а брокколи вокруг.</li><li>Сбрызните брокколи оставшимся маслом и посыпьте всё солью и чесночным порошком.</li><li>Запекайте 25–30 минут, пока термометр в самой толстой части грудки не покажет 71 °C.</li><li>Смешайте чеснок, пармезан и петрушку, выложите на грудки и поставьте под гриль на 3 минуты, пока сыр не расплавится, а брокколи не подрумянится.</li><li>Накройте фольгой и оставьте на 5 минут, затем подавайте.</li></ol><p><em>Дайте отдохнуть 5 минут под фольгой и подавайте тёплым.</em></p>', CURRENT_TIMESTAMP),
  ('5c7b2de8-632b-52a7-b46b-893119d6f4e8', '7dbb8427-ff1f-5fe2-96f6-e350402e78cc', 'en', 'One-pan parmesan chicken with broccoli', 'Chicken breasts roasted on one sheet pan with broccoli and topped with a garlic parmesan and parsley mixture broiled until golden.', '<ol><li>Preheat the oven to 425 °F (220 °C). Grease a rimmed baking sheet with 1 tbsp olive oil.</li><li>Place the chicken breasts in the center of the pan and arrange the broccoli around them.</li><li>Drizzle the broccoli with the remaining oil and sprinkle everything with salt and garlic powder.</li><li>Bake 25–30 minutes until a thermometer in the thickest part of the chicken reads 160 °F (71 °C).</li><li>Mix the garlic, parmesan and parsley, spoon over the chicken and broil about 3 minutes until the cheese melts and the broccoli is deeply browned.</li><li>Tent with foil and rest 5 minutes before serving.</li></ol><p><em>Rest 5 minutes tented with foil and serve warm.</em></p>', CURRENT_TIMESTAMP),
  ('3091585e-43db-54fb-9e86-78afeca6c38d', '691e7c7b-9bfe-5bf0-92cc-8358bbaccab5', 'ru', 'Постный суп-лапша с нутом и овощами', 'Лёгкий овощной суп с нутом вместо курицы, морковью, сельдереем, куркумой и макаронами-спиральками. Хорош при простуде и для спокойного ужина.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло, добавьте лук, сельдерей, морковь и ¼ ч. л. соли. Готовьте 5–7 минут, часто помешивая, пока лук не станет прозрачным.</li><li>Добавьте куркуму и карри на 30 секунд, затем лавровый лист, нут, макароны, петрушку и бульон.</li><li>Доведите до кипения на сильном огне, убавьте до средне-слабого и варите 10–20 минут, пока макароны не станут мягкими.</li><li>Снимите с огня, поперчите, при необходимости досолите. Подавайте горячим с петрушкой.</li></ol><p><em>Посыпьте петрушкой и чёрным перцем.</em></p>', CURRENT_TIMESTAMP),
  ('24c91997-54bb-5acf-8e4d-f0f33f40dbca', '691e7c7b-9bfe-5bf0-92cc-8358bbaccab5', 'en', 'Chickpea noodle vegetable soup', 'A light meatless noodle soup with chickpeas instead of chicken, carrots, celery, turmeric and spiral pasta. Great for a cold day or a calm dinner.', '<ol><li>Warm the olive oil in a large pot over medium heat, add the onion, celery, carrots and ¼ tsp salt and cook, stirring often, 5–7 minutes until the onion turns translucent.</li><li>Add the turmeric and curry powder for 30 seconds, then the bay leaf, chickpeas, pasta, parsley and broth.</li><li>Bring to a simmer over high heat, reduce to medium-low and simmer 10–20 minutes until the pasta is tender.</li><li>Remove from the heat, season with pepper and more salt if needed and serve hot with parsley.</li></ol><p><em>Garnish with parsley and black pepper.</em></p>', CURRENT_TIMESTAMP),
  ('2f8ef7f6-8441-5f95-a1e2-db73dfe57d17', '856ea57d-3c5c-511d-ac84-030bdfa76540', 'ru', 'Овощной суп с киноа, фасолью и кейлом', 'Густой овощной суп с морковью, сельдереем, томатами, киноа, белой фасолью и зеленью. Хорошо хранится и вкусен на следующий день.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло. Добавьте лук, морковь, сельдерей, остальные овощи и щепотку соли и готовьте 6–8 минут, пока лук не станет прозрачным.</li><li>Добавьте чеснок и тимьян на минуту, затем томаты вместе с соком и готовьте ещё несколько минут.</li><li>Добавьте киноа, бульон, воду, 1 ч. л. соли, лавровый лист и острый перец, поперчите. Доведите до кипения, затем накройте не полностью и варите на слабом огне 25 минут.</li><li>Откройте крышку, добавьте фасоль и нарезанную зелень и варите ещё 5 минут, пока зелень не станет мягкой. Выньте лавровый лист, добавьте лимонный сок, попробуйте и отрегулируйте соль.</li></ol><p><em>Посыпьте тёртым пармезаном, если не нужен веганский вариант.</em></p>', CURRENT_TIMESTAMP),
  ('6177a145-6dce-5741-8dcd-254b1dfd9396', '856ea57d-3c5c-511d-ac84-030bdfa76540', 'en', 'Quinoa vegetable soup with beans and kale', 'A thick vegetable soup of carrots, celery, tomatoes, quinoa, white beans and greens. Keeps well and tastes even better the next day.', '<ol><li>Warm the olive oil in a large pot over medium heat. Add the onion, carrots, celery, other vegetables and a pinch of salt and cook 6–8 minutes until the onion is translucent.</li><li>Add the garlic and thyme for a minute, then the tomatoes with their juices and cook a few minutes more.</li><li>Add the quinoa, broth, water, 1 tsp salt, bay leaves and red pepper flakes and season with pepper. Bring to a boil, then partially cover and simmer gently for 25 minutes.</li><li>Uncover and add the beans and chopped greens and simmer 5 more minutes until soft. Remove the bay leaves, stir in the lemon juice, taste and adjust the salt.</li></ol><p><em>Top with grated Parmesan if you don''t need it vegan.</em></p>', CURRENT_TIMESTAMP),
  ('a0520a59-4057-5047-94d1-903a5f0c8b4e', '80501c59-9c7f-587d-b72e-8c1ccdb9cec7', 'ru', 'Макароны с сыром чеддер на плите', 'Кремовые макароны в соусе из сливок и настоящего чеддера со щепоткой горчицы и чесночного порошка. Готовятся за 20 минут.', '<ol><li>Доведите воду до кипения, добавьте соль и макароны, варите до состояния аль денте по инструкции. Пока варятся макароны, смешайте сухие специи в мисочке.</li><li>Слейте воду, макароны оставьте в дуршлаге. Верните пустую кастрюлю на средний огонь, влейте сливки и доведите до кипения, затем варите ровно 1 минуту.</li><li>Добавьте весь сыр и специи, помешивайте до полного растворения сыра и кремового соуса. Верните макароны, перемешайте и снимите с огня.</li><li>Попробуйте, при необходимости досолите, и подавайте сразу.</li></ol><p><em>Подайте сразу с салатом или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('5ccadb60-15a8-5f53-a39a-a998588ea36b', '80501c59-9c7f-587d-b72e-8c1ccdb9cec7', 'en', 'Stovetop mac and cheese with cheddar', 'Creamy macaroni in a sauce of cream and real sharp cheddar with a touch of mustard and garlic powder, ready in 20 minutes.', '<ol><li>Bring a pot of water to a boil, add the salt and noodles and cook al dente according to the package. Meanwhile combine the dry spices in a small bowl.</li><li>Drain the pasta and leave it in the colander. Return the empty pot to medium heat, add the cream and bring to a boil, then boil exactly 1 minute.</li><li>Add all the cheese and the spices and stir until the cheese melts into a creamy sauce. Add the pasta, stir to coat and take off the heat.</li><li>Taste, add salt if needed and serve immediately.</li></ol><p><em>Serve immediately with a salad or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('a8cebf79-abd8-50bf-b5f2-8fc6774b1796', 'f44a342f-29fa-53bc-bbe4-af8e7f175a78', 'ru', 'Сырный суп-пюре с брокколи и картофелем', 'Густой суп из брокколи, лука и чеснока, сливочный за счёт картофеля и сыра чеддер, без сливок и муки.', '<ol><li>Растопите масло в большой кастрюле на слабом-среднем огне. Добавьте лук, чеснок, острый перец, ¼ ч. л. соли и чёрный перец, накройте и готовьте 8–10 минут, пока лук не станет мягким и чуть золотистым.</li><li>Срежьте жёсткие концы стеблей брокколи, очистите кожицу, нарежьте стебли кусочками по 2–5 см. Соцветия срежьте у основания и отложите.</li><li>Добавьте в кастрюлю стебли брокколи и картофель кусками, влейте 1,4 л воды, добавьте оставшуюся соль. Доведите до кипения, убавьте огонь, накройте и варите 20–25 минут до мягкости.</li><li>Добавьте половину мелко нарезанных соцветий на 3–5 минут, пока они не позеленеют. Порциями измельчите несколько стаканов супа блендером до гладкости (или погружным блендером прямо в кастрюле) и верните в кастрюлю.</li><li>Верните кастрюлю на огонь, добавьте остальные соцветия и готовьте 4–7 минут. Вмешайте почти весь сыр до однородности, добавьте соль и перец по вкусу. Подавайте с сыром и зелёным луком.</li></ol><p><em>Посыпьте сыром и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('efd48098-d73b-51f0-bf38-0dded7086740', 'f44a342f-29fa-53bc-bbe4-af8e7f175a78', 'en', 'Broccoli cheddar potato soup', 'A thick soup of broccoli, onion and garlic made creamy with potato and cheddar, with no cream and no flour.', '<ol><li>Melt the butter in a large pot over medium-low heat. Add the onion, garlic, red pepper flakes, ¼ tsp salt and black pepper, cover and cook 8–10 minutes until soft and just turning golden.</li><li>Trim the tough ends from the broccoli stalks, peel the skin and cut into 1–2 inch pieces. Cut the florets off close to the base and set aside.</li><li>Add the broccoli stalks and potato chunks, pour in 6 cups of water and the remaining salt. Bring to a boil, reduce the heat, cover and simmer 20–25 minutes until tender.</li><li>Add half of the chopped florets for 3–5 minutes until bright green. Blend several cups of soup, in batches, until completely smooth (or use an immersion blender in the pot) and return to the pot.</li><li>Return to medium heat and add the remaining florets for 4–7 minutes. Stir in almost all the cheese until smooth and adjust salt and pepper. Serve with cheese and green onions.</li></ol><p><em>Top with cheese and green onions.</em></p>', CURRENT_TIMESTAMP),
  ('ba802c1a-50d1-5063-a7c9-8d7e6d7a525a', '124fca29-85a8-552f-a9c3-12a6e9e06620', 'ru', 'Картофель, запечённый с перцем и луком, по-деревенски', 'Хрустящие кусочки картофеля с болгарским перцем и луком, запечённые в духовке с оливковым маслом и чесночным порошком. Менее жирно, чем жареный.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>На большом противне смешайте картофель кусочками по 2 см, красный перец квадратиками и лук дольками. Сбрызните маслом, посыпьте чесночным порошком, солью и перцем, перемешайте до равномерного покрытия и разровняйте в один слой.</li><li>Запекайте 45–50 минут, перемешивая каждые 15 минут, пока овощи не станут мягкими и румяными по краям. Подавайте сразу.</li></ol><p><em>Подайте сразу с яйцами, колбасками или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('db7652c4-6ffc-5428-a5b5-c44cab216c9a', '124fca29-85a8-552f-a9c3-12a6e9e06620', 'en', 'Oven-roasted breakfast potatoes with peppers and onion', 'Crispy potato pieces with bell pepper and onion roasted in the oven with olive oil and garlic powder, less greasy than skillet potatoes.', '<ol><li>Preheat the oven to 425 °F (220 °C).</li><li>On a large rimmed sheet combine the potatoes cut into ¾ inch pieces, red pepper squares and onion wedges. Drizzle with oil, sprinkle with garlic powder, salt and pepper, toss to coat and spread in one layer.</li><li>Bake 45–50 minutes, stirring every 15 minutes, until tender and deeply golden on the edges. Serve immediately.</li></ol><p><em>Serve right away with eggs, sausages or a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('4d77552a-5006-5c87-a766-1f8a3d1c205e', 'c248eedd-cacb-59ef-a723-9289affa77b2', 'ru', 'Овсяная каша с обжаренными хлопьями', 'Рассыпчатая ароматная овсянка: хлопья сначала подсушиваются в сливочном масле, затем варятся на воде с молоком и доходят под крышкой.', '<ol><li>Растопите масло в кастрюле на среднем огне, всыпьте хлопья и перемешайте. Обжаривайте, иногда помешивая, 4–6 минут, пока не появится ореховый запах и хлопья слегка не позолотятся.</li><li>Осторожно влейте воду и молоко, добавьте соль и корицу, перемешайте. Доведите до активного кипения по краям и варите около 3 минут, пока пузыри не дойдут к центру.</li><li>Накройте крышкой, выключите огонь и оставьте на 7 минут. Если каша влажная, накройте ещё на 1–2 минуты. Подавайте с любыми добавками.</li></ol><p><em>Добавьте ягоды, фрукты, мёд или орехи.</em></p>', CURRENT_TIMESTAMP),
  ('c690a612-988d-52a9-a5df-5806659b47ed', 'c248eedd-cacb-59ef-a723-9289affa77b2', 'en', 'Toasted rolled oats porridge', 'Fluffy, flavourful oatmeal: the oats are toasted in butter first, then cooked in water and milk and finished off the heat under a lid.', '<ol><li>Melt the butter in a saucepan over medium heat, add the oats and stir to coat. Cook, stirring occasionally, 4–6 minutes until toasty and lightly golden.</li><li>Carefully pour in the water and milk, add the salt and cinnamon and stir. Bring to a rapid bubble around the edges and cook about 3 minutes until the bubbles spread toward the centre.</li><li>Cover, turn off the heat and let it rest 7 minutes. If still wet, cover for 1–2 minutes more. Serve with your favourite toppings.</li></ol><p><em>Top with berries, fruit, honey or nuts.</em></p>', CURRENT_TIMESTAMP),
  ('a31df742-0a85-5d22-8dfd-624fe4953ad2', 'd89de1d6-d4e7-57c6-ad7c-e5c6ad5e840b', 'ru', 'Яичная запеканка со шпинатом, перцем и фетой', 'Пышная запеканка из 12 яиц со сладким перцем, зелёным луком, шпинатом и фетой. Подойдёт на завтрак, обед и для праздничного стола.', '<ol><li>Разогрейте духовку до 175 °C и смажьте форму 23×33 см сливочным маслом (спрей не подходит).</li><li>В большой сковороде на среднем огне разогрейте масло и 8–10 минут тушите перец и зелёный лук. Добавьте шпинат и мешайте около 2 минут до увядания. Дайте слегка остыть.</li><li>Разбейте яйца в миску, добавьте сливки, соль и перец и слегка взбейте. Вмешайте половину феты и слегка остывшие овощи.</li><li>Вылейте в форму, сверху рассыпьте остальную фету. Запекайте 25–35 минут, пока яйца не поднимутся и центр лишь слегка не колышется, а вилка не будет выходить чистой.</li><li>Остудите на решётке несколько минут, нарежьте и подавайте.</li></ol><p><em>Подайте тёплой, холодной или слегка разогретой, нарезав порциями.</em></p>', CURRENT_TIMESTAMP),
  ('a522803e-cc60-5b12-a0e7-8d8d78a61fce', 'd89de1d6-d4e7-57c6-ad7c-e5c6ad5e840b', 'en', 'Spinach, pepper and feta egg bake', 'A fluffy twelve-egg casserole with red bell peppers, green onions, spinach and feta. Good for breakfast, lunch or a holiday table.', '<ol><li>Preheat the oven to 350 °F (175 °C) and grease a 9 × 13 inch pan with butter (cooking spray does not work as well).</li><li>Warm the oil in a large skillet over medium heat and cook the pepper and green onion 8–10 minutes until tender. Add the spinach and stir about 2 minutes until wilted. Cool slightly.</li><li>Crack the eggs into a bowl, add the cream, salt and pepper and whisk just to blend. Stir in half the feta and the cooled vegetables.</li><li>Pour into the pan and scatter the remaining feta on top. Bake 25–35 minutes until puffed with the centre barely jiggling and a fork coming out clean.</li><li>Cool on a rack a few minutes, then slice and serve.</li></ol><p><em>Serve warm, cold or gently reheated, cut into portions.</em></p>', CURRENT_TIMESTAMP),
  ('eb8ad368-0d28-5471-adde-06c210cbf9ef', '8009ce8c-490b-57cd-af3e-f338792dee7a', 'ru', 'Тайский суп-пюре из моркови и батата с ореховой пастой', 'Согревающий суп из моркови и батата с красной тайской пастой карри, имбирём, чесноком и миндальным маслом, подаётся с кинзой и лаймом.', '<ol><li>В большой кастрюле на среднем огне растопите масло. Обжарьте лук, чеснок и имбирь 5–6 минут до прозрачности лука.</li><li>Вмешайте пасту карри. Разведите миндальное масло в небольшом количестве бульона, влейте в кастрюлю, добавьте морковь, батат, соль и остальной бульон, перемешайте.</li><li>Доведите до кипения, убавьте огонь, накройте и варите 15–20 минут, пока морковь и батат не станут мягкими.</li><li>Измельчите суп порциями в блендере до гладкости (или погружным блендером в кастрюле). Посолите, поперчите, при желании добавьте кайенский перец. Если густо, разбавьте бульоном.</li><li>Разлейте по тарелкам, добавьте кинзу и сок лайма.</li></ol><p><em>Добавьте сок лайма и свежую кинзу.</em></p>', CURRENT_TIMESTAMP),
  ('c0740a63-9912-548f-96c4-84f9859ca86b', '8009ce8c-490b-57cd-af3e-f338792dee7a', 'en', 'Thai carrot and sweet potato soup with nut butter', 'A warming soup of carrots and sweet potatoes with red Thai curry paste, ginger, garlic and almond butter, served with cilantro and lime.', '<ol><li>In a large pot melt the oil over medium heat. Sauté the onion, garlic and ginger 5–6 minutes until the onion is translucent.</li><li>Stir in the curry paste. Whisk the almond butter with a little of the broth until smooth and add it to the pot with the carrots, sweet potatoes, salt and the remaining broth.</li><li>Bring to a low boil, reduce the heat to medium-low, cover and simmer 15–20 minutes until the carrots and sweet potatoes are fork-tender.</li><li>Blend in batches until completely smooth (or use an immersion blender in the pot). Season with salt and pepper, add cayenne if you like, and thin with broth if too thick.</li><li>Ladle into bowls and top with cilantro and a squeeze of lime juice.</li></ol><p><em>Finish with lime juice and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('de74f547-0449-53e5-994d-4f98a4f21606', 'f469464d-da88-5ef4-8366-2364d672f13c', 'ru', 'Фаршированный перец с индейкой и бурым рисом', 'Половинки болгарского перца с начинкой из фарша индейки, бурого риса, лука, чеснока и зиры, запечённые под сыром в бульоне.', '<ol><li>Разогрейте духовку до 200 °C. В антипригарной сковороде на среднем огне слегка смажьте маслом и 2 минуты обжарьте лук, чеснок и кинзу.</li><li>Добавьте фарш индейки, соль, чесночный порошок и зиру и готовьте 4–5 минут до полной готовности мяса.</li><li>Влейте томатный соус и ½ стакана бульона, перемешайте и тушите на слабом огне около 5 минут. Смешайте мясо с отварным рисом.</li><li>Разрежьте перцы пополам вдоль, удалите семена. Разложите начинку (по ⅔ стакана) по половинкам, поставьте в форму 23×33 см и посыпьте каждую 1 ст. л. сыра.</li><li>Влейте оставшийся бульон на дно формы, плотно накройте фольгой и запекайте около 45 минут до мягкости перцев. Снимите фольгу и подавайте сразу.</li></ol><p><em>Подавайте горячим с зеленью и сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('6e9b1019-5472-50c9-b017-37059115bcfa', 'f469464d-da88-5ef4-8366-2364d672f13c', 'en', 'Turkey and brown rice stuffed bell peppers', 'Bell pepper halves stuffed with ground turkey, brown rice, onion, garlic and cumin and baked under cheese in broth.', '<ol><li>Preheat the oven to 400 °F (200 °C). In a nonstick skillet lightly oiled over medium heat sauté the onion, garlic and cilantro about 2 minutes.</li><li>Add the ground turkey, salt, garlic powder and cumin and cook 4–5 minutes until completely cooked through.</li><li>Stir in the tomato sauce and ½ cup broth and simmer on low about 5 minutes, then combine the meat with the cooked rice.</li><li>Halve the peppers lengthwise and remove the seeds. Spoon about ⅔ cup of filling into each half, place in a 9×13 dish and top each with 1 tbsp cheese.</li><li>Pour the remaining broth into the bottom of the dish, cover tightly with foil and bake about 45 minutes until the peppers are tender. Remove the foil and serve right away.</li></ol><p><em>Serve hot with fresh herbs and sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('890c6bdb-3435-5acf-bf56-056a941d9868', '3185954d-8909-500c-a034-bdf107b5fbe9', 'ru', 'Тефтели из говядины и индейки в грибном соусе', 'Мясные шарики из смеси говяжьего фарша и фарша индейки в густом грибном соусе с томатной пастой и вустерским соусом. Можно готовить на плите, в мультиварке или скороварке.', '<ol><li>Мелко порубите 30 г грибов. В кастрюле с толстым дном (или в режиме обжарки) обжарьте лук с 1 ч. л. масла 4–5 минут до золотистого цвета. Разделите лук пополам.</li><li>В миске смешайте половину лука с говяжьим фаршем, фаршем индейки, рублеными грибами, сухарями, яйцом, 1 ст. л. томатной пасты, ¼ стакана бульона, солью и перцем.</li><li>Для соуса растворите муку в 1 стакане бульона, добавьте оставшийся лук, томатную пасту, уксус, вустерский и горчичный порошок. Сформуйте около 20 небольших тефтелей.</li><li>Разогрейте оставшееся масло в глубокой сковороде и обжарьте тефтели порциями по 2 минуты с каждой стороны. Добавьте грибы, соль и перец, залейте соусом, накройте и тушите на слабом огне 25 минут. В скороварке: готовьте 10 минут под высоким давлением. В мультиварке: 6–8 часов на низком режиме.</li><li>Посыпьте рубленой петрушкой и подавайте.</li></ol><p><em>Подавайте с картофельным пюре, гречкой или лапшой.</em></p>', CURRENT_TIMESTAMP),
  ('40b6f1aa-39b9-5803-8196-8010ed98d2d5', '3185954d-8909-500c-a034-bdf107b5fbe9', 'en', 'Salisbury steak meatballs in mushroom gravy', 'Beef and turkey meatballs simmered in a mushroom gravy with tomato paste and Worcestershire, made on the stove, in a slow cooker or pressure cooker.', '<ol><li>Finely chop 1 oz of the mushrooms. Sauté the onion in 1 tsp oil in a heavy pot (or pressure cooker on sauté) 4–5 minutes until golden, then divide in half.</li><li>In a bowl combine half of the onion with the beef, turkey, chopped mushroom, breadcrumbs, egg, 1 tbsp tomato paste, ¼ cup of the broth, salt and pepper.</li><li>For the sauce whisk the flour into 1 cup broth and mix in the remaining onion, tomato paste, vinegar, Worcestershire and mustard powder. Shape the meat into about 20 small meatballs.</li><li>Heat the remaining oil in a deep skillet and brown the meatballs in batches, 2 minutes per side. Add the mushrooms, salt and pepper, pour the sauce over, cover and simmer on low 25 minutes. Pressure cooker: 10 minutes on high. Slow cooker: 6–8 hours on low.</li><li>Garnish with chopped parsley and serve.</li></ol><p><em>Serve over mashed potatoes, buckwheat or noodles.</em></p>', CURRENT_TIMESTAMP),
  ('db685c30-d377-588e-8391-56596bab65fb', 'c92b4793-10f9-5f0d-a564-69eb9708be6a', 'ru', 'Свиные отбивные в хрустящей панировке из панко и кукурузных хлопьев, запечённые', 'Свиные отбивные без кости в яйце и панировке из сухарей, измельчённых кукурузных хлопьев и пармезана со специями. Запекаются в духовке, без фритюра.', '<ol><li>Разогрейте духовку до 220 °C и слегка сбрызните маслом большой противень.</li><li>Посолите отбивные с двух сторон ½ ч. л. соли.</li><li>В неглубокой миске смешайте сухари панко, кукурузные хлопья, пармезан, оставшуюся соль, паприку, чесночный и луковый порошок, чили и перец. Яйцо взбейте в другой миске.</li><li>Обмакните каждую отбивную в яйцо, затем обваляйте в панировке и выложите на противень. Сбрызните сверху ещё немного маслом.</li><li>Запекайте 20 минут, пока корочка не станет золотистой, а мясо — готовым.</li></ol><p><em>Подавайте с картофельным пюре или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('77260ecf-7ddf-59e9-b860-1d089b3083c1', 'c92b4793-10f9-5f0d-a564-69eb9708be6a', 'en', 'Oven-baked breaded pork chops with panko and cornflakes', 'Boneless pork chops dipped in egg and coated with panko, crushed cornflakes, parmesan and spices, then baked until crisp instead of fried.', '<ol><li>Preheat the oven to 425 °F (220 °C) and lightly spray a large baking sheet with oil.</li><li>Season the pork chops on both sides with ½ tsp salt.</li><li>In a shallow bowl combine the panko, cornflake crumbs, parmesan, remaining salt, paprika, garlic powder, onion powder, chili powder and pepper. Beat the egg in another bowl.</li><li>Dip each chop in the egg, then the crumb mixture and place on the baking sheet. Spray a little more oil on top.</li><li>Bake 20 minutes until the coating is golden and the pork is cooked through.</li></ol><p><em>Serve with mashed potatoes or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('97ad023e-afe9-50d3-aee9-a0bd780ae41d', '762b3fce-e13b-5b96-954a-eec1df6ca175', 'ru', 'Суп с мини-фрикадельками из индейки и овощами', 'Лёгкий суп из томатов, моркови, сельдерея и кабачка с запечёнными фрикадельками из индейки с пармезаном, шпинатом и травами.', '<ol><li>Разогрейте духовку до 200 °C. В большой миске смешайте фарш индейки, сухари, яйцо, петрушку, лук, чеснок, соль и сыр, аккуратно, не перемешивая лишнего.</li><li>Сформуйте маленькие фрикадельки по 1 ст. л. фарша (около 40 штук) и запекайте около 12 минут.</li><li>Тем временем разогрейте масло в кастрюле на среднем-сильном огне. Тушите лук, морковь, сельдерей и чеснок около 15 минут до мягкости и аромата.</li><li>Добавьте бульон, помидоры, соль и перец, затем розмарин, лавровый лист, базилик и петрушку. Накройте и варите на слабом огне 40 минут.</li><li>Выньте розмарин и лавровый лист, положите фрикадельки, кабачок и шпинат, накройте и варите 8–10 минут до мягкости кабачка. Посолите и поперчите по вкусу.</li></ol><p><em>Подавайте с тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('dfb03eca-b4cc-5448-94be-b41b7e7bf12a', '762b3fce-e13b-5b96-954a-eec1df6ca175', 'en', 'Mini turkey meatball vegetable soup', 'Light tomato soup with carrots, celery, zucchini and spinach, with baked mini turkey and parmesan meatballs and herbs.', '<ol><li>Preheat the oven to 400 °F (200 °C). In a large bowl gently mix the ground turkey, breadcrumbs, egg, parsley, onion, garlic, salt and cheese.</li><li>Form meatballs of about 1 tbsp each (about 42) and bake about 12 minutes.</li><li>Meanwhile heat the oil in a large pot over medium-high heat and sauté the onion, carrots, celery and garlic about 15 minutes until tender and fragrant.</li><li>Add the broth, tomatoes, salt and pepper, then the rosemary, bay leaves, basil and parsley. Cover and cook on low 40 minutes.</li><li>Remove the rosemary and bay leaves, add the meatballs, zucchini and spinach, cover and simmer 8–10 minutes until the zucchini is tender. Season to taste.</li></ol><p><em>Serve with extra grated parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('fe862523-3ad1-5f11-a3ad-7633dd3b428f', 'b23b5daa-140e-5afb-a669-f3868552fd68', 'ru', 'Минестроне с белой фасолью и пастой', 'Итальянский овощной суп с белой фасолью, томатами, кабачком, шпинатом и мелкой пастой на курином бульоне. Богат клетчаткой.', '<ol><li>Пюрируйте фасоль в блендере с 1 стаканом бульона.</li><li>В большой кастрюле на среднем-сильном огне разогрейте масло и около 15 минут тушите морковь, сельдерей, лук и чеснок до мягкости и аромата.</li><li>Добавьте остальной бульон, помидоры, пюре из фасоли, соль и перец, затем розмарин, лавровый лист, базилик и петрушку. Доведите до кипения, накройте и варите на слабом огне 40 минут.</li><li>Добавьте кабачок и шпинат, накройте и варите 8–10 минут до мягкости кабачка. Выньте розмарин и лавровый лист, посолите и поперчите.</li><li>Разложите суп по тарелкам, добавив в каждую по ¼ стакана отварной пасты и по желанию пармезан.</li></ol><p><em>Подавайте с тёртым пармезаном и хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('b3b5af80-7ae2-5187-83ef-f7667cb02a1c', 'b23b5daa-140e-5afb-a669-f3868552fd68', 'en', 'Minestrone with white beans and pasta', 'Hearty Italian vegetable soup with white beans, tomatoes, zucchini, spinach and small pasta in chicken broth, rich in fiber.', '<ol><li>Purée the beans in a blender with 1 cup of the broth.</li><li>Heat the oil in a large pot over medium-high heat and sauté the carrots, celery, onion and garlic about 15 minutes until tender and fragrant.</li><li>Add the remaining broth, tomatoes, bean purée, salt and pepper, then the rosemary, bay leaves, basil and parsley. Bring to a boil, cover and cook on low 40 minutes.</li><li>Add the zucchini and spinach, cover and simmer 8–10 minutes until the zucchini is tender. Remove the rosemary and bay leaves and season to taste.</li><li>Ladle into bowls with ¼ cup cooked pasta in each and top with parmesan if desired.</li></ol><p><em>Top with grated parmesan and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('ff1bb72c-fe61-545e-822d-ca3e0e76d10d', '256fb66c-1882-55c2-8efc-7af8561b40b4', 'ru', 'Говяжий фарш с брокколи в соевом соусе', 'Быстрый ужин: говяжий фарш с луком и брокколи в соусе из соевого соуса, мёда, чеснока и имбиря. Готовится за 13 минут.', '<ol><li>В небольшой миске взбейте соевый соус, мёд, чеснок, имбирь и крахмал.</li><li>Разогрейте кунжутное масло в глубокой сковороде на среднем-сильном огне. Обжарьте фарш с луком, помешивая, около 5 минут, пока мясо почти не будет готово.</li><li>Влейте соус, перемешайте и готовьте минуту. Добавьте бланшированную брокколи и готовьте ещё минуту.</li><li>Разложите по тарелкам (на рис, если подаёте с ним), посыпьте кунжутом и зелёным луком.</li></ol><p><em>Подавайте на варёном рисе, посыпав кунжутом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('a2216fb6-0cb7-5eda-beb5-81c9e3016049', '256fb66c-1882-55c2-8efc-7af8561b40b4', 'en', 'Ground beef and broccoli stir fry', 'A quick weeknight dinner of ground beef, onion and broccoli in a soy, honey, garlic and ginger sauce, ready in 13 minutes.', '<ol><li>In a small bowl whisk the soy sauce, honey, garlic, ginger and cornstarch.</li><li>Heat the sesame oil in a large deep skillet over medium-high heat. Cook the beef and onion, stirring, about 5 minutes until the meat is nearly cooked through.</li><li>Pour in the sauce, stir and cook for 1 minute, then add the blanched broccoli and cook 1 more minute.</li><li>Divide among plates (over rice if using) and top with sesame seeds and scallions.</li></ol><p><em>Serve over rice topped with sesame seeds and scallions.</em></p>', CURRENT_TIMESTAMP),
  ('86a0909e-737e-57b8-ab85-f05babfbf47e', '099f72c1-519b-5385-b897-8f56c3fea817', 'ru', 'Овсяная каша без варки на ночь с мёдом и арахисовой пастой', 'Цельная овсяная крупа, замоченная в молоке с мёдом и арахисовой пастой на ночь в холодильнике. Готовый завтрак на несколько дней.', '<ol><li>В миске взбейте молоко, мёд и арахисовую пасту до гладкости.</li><li>Добавьте овсяную крупу и соль, перемешайте. Плотно накройте и уберите в холодильник на ночь или до 5 дней.</li><li>Перед подачей перемешайте, разложите по мискам и добавьте свежие фрукты, орехи или другие добавки. Подавайте холодной.</li></ol><p><em>Добавьте свежие ягоды, орехи или сухофрукты перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('15f2ca5d-3dd3-5d0d-afaf-fe739edc8aa5', '099f72c1-519b-5385-b897-8f56c3fea817', 'en', 'Overnight steel-cut oats with honey and peanut butter', 'Steel-cut oats soaked overnight in the fridge in milk with honey and peanut butter. A no-cook breakfast that keeps all week.', '<ol><li>In a bowl whisk the milk, honey and peanut butter until smooth.</li><li>Stir in the steel-cut oats and salt. Cover tightly and refrigerate overnight or up to 5 days.</li><li>Stir before serving, portion into bowls and top with fruit, nuts or other toppings. Serve cold.</li></ol><p><em>Top with fresh berries, nuts or dried fruit before serving.</em></p>', CURRENT_TIMESTAMP),
  ('45385a22-1ea4-5f57-8849-6cb53767c9d6', '839543d0-7d69-5bba-bf72-2e5682fda190', 'ru', 'Запечённый батат целиком', 'Простой способ запечь батат в духовке до мягкой сладкой мякоти. Подаётся с маслом, солью и перцем, а также как основа для начинки.', '<ol><li>Поставьте решётку в центр духовки и разогрейте до 220 °C. Застелите противень пергаментом или фольгой.</li><li>Вымойте и обсушите батат, проколите вилкой со всех сторон и выложите на противень. Запекайте 45–60 минут (в зависимости от размера), пока кожица не подрумянится, а мякоть не станет очень мягкой.</li><li>Дайте немного остыть, сделайте продольный надрез и взрыхлите мякоть вилкой. Посолите, поперчите и подавайте тёплыми с маслом.</li></ol><p><em>Подайте с кусочком масла, солью и перцем или с начинкой из фасоли и овощей.</em></p>', CURRENT_TIMESTAMP),
  ('00dab08b-3f98-5877-8e1d-f6402321339f', '839543d0-7d69-5bba-bf72-2e5682fda190', 'en', 'Baked whole sweet potatoes', 'A foolproof way to bake sweet potatoes in the oven until tender and sweet inside. Serve with butter, salt and pepper or use as a base for toppings.', '<ol><li>Set a rack in the centre of the oven and preheat to 425 °F (220 °C). Line a baking sheet with parchment or foil.</li><li>Scrub and dry the sweet potatoes, prick all over with a fork and set on the tray. Bake 45–60 minutes depending on size until very tender and the skins are lightly browned.</li><li>Let cool slightly, cut a slit in the top and fluff the flesh with a fork. Season with salt and pepper and serve warm with butter.</li></ol><p><em>Serve with butter, salt and pepper, or with a bean and vegetable topping.</em></p>', CURRENT_TIMESTAMP),
  ('8e93cd44-578e-5dda-9e8e-c76e0cc67574', 'df7a3ed2-d34a-5f09-bad9-9e05ba1df5e9', 'ru', 'Буррито на завтрак с картофелем, колбасками и творожными яйцами', 'Запечённый картофель с перцем, луком и куриными колбасками, залитый яйцами, взбитыми с творогом, и сыром. Нарезается и заворачивается в тортильи; идеально для заморозки.', '<ol><li>Разогрейте духовку до 200 °C. В форме 23×33 см смешайте картофель, перец и лук, сбрызните маслом, посыпьте итальянскими травами, солью и кайенским перцем, перемешайте и разровняйте. Запекайте 15 минут.</li><li>Добавьте нарезанные колбаски, перемешайте, разровняйте и запекайте ещё 15 минут, пока картофель не станет мягким.</li><li>Взбейте в блендере творог с яйцами до гладкости.</li><li>Залейте овощи яичной смесью, посыпьте чеддером и запекайте 10–15 минут, пока центр не поднимется, края не подрумянятся, а яйца не пропекутся. Остудите.</li><li>Нарежьте начинку на 10 прямоугольников. На каждую тортилью положите кусок, заверните конвертом и плотно закатайте в фольгу или пергамент.</li><li>Храните в холодильнике до 3 дней или заморозьте до 3 месяцев. Перед едой разморозьте и прогрейте в микроволновке 1–2 минуты или обжарьте на сковороде по 3–4 минуты с каждой стороны.</li></ol><p><em>Разогрейте в микроволновке и при желании обжарьте до хрустящей корочки на сковороде.</em></p>', CURRENT_TIMESTAMP),
  ('66a0579a-96b7-59c2-9a33-4cac9b47fef5', 'df7a3ed2-d34a-5f09-bad9-9e05ba1df5e9', 'en', 'Freezer breakfast burritos with potatoes, sausage and cottage cheese eggs', 'Roasted potatoes, peppers and onion with chicken sausage, baked in a cottage cheese and egg custard with cheddar, then sliced and wrapped in tortillas. Ideal for freezing.', '<ol><li>Heat the oven to 400 °F (200 °C). In a 9×13 inch dish toss the potatoes, peppers and onion with the oil, Italian seasoning, salt and cayenne, spread into one layer and roast 15 minutes.</li><li>Add the sausage, toss, spread back out and bake 15 more minutes until the potatoes are fork tender.</li><li>Blend the cottage cheese and eggs until smooth in a blender.</li><li>Pour the eggs over the vegetables, sprinkle with cheddar and bake 10–15 minutes until puffed in the centre, golden at the edges and cooked through. Cool.</li><li>Cut the filling into 10 rectangles. Set a slice on each tortilla, fold in the ends and roll into a tight burrito, wrapping in foil or parchment.</li><li>Refrigerate up to 3 days or freeze up to 3 months. To serve, thaw and microwave 1–2 minutes or crisp 3–4 minutes per side in a skillet.</li></ol><p><em>Reheat in the microwave and, if you like, crisp in a skillet.</em></p>', CURRENT_TIMESTAMP),
  ('7d56de07-e399-5906-9f71-b5704dbeae72', 'a6f2f231-3eba-5e96-9b25-aa80fe33ac47', 'ru', 'Тёплый салат из батата с беконом и горчичной заправкой', 'Отварной батат с хрустящим беконом, сельдереем, зелёным луком и халапеньо под заправкой из зернистой горчицы, рисового уксуса и масла вместо майонеза.', '<ol><li>Вскипятите кастрюлю подсоленной воды, добавьте нарезанный кусочками батат и варите 10–15 минут до мягкости. Слейте, быстро ополосните холодной водой и отставьте.</li><li>Обжарьте бекон до хруста, остудите и покрошите в большую миску. Добавьте сельдерей и зелёный лук.</li><li>Для заправки взбейте халапеньо, горчицу, чеснок, уксус, масло, соль и перец.</li><li>Добавьте батат в миску, полейте заправкой и осторожно перемешайте. Попробуйте и подсолите по вкусу.</li></ol><p><em>Подайте тёплым, охлаждённым или комнатной температуры.</em></p>', CURRENT_TIMESTAMP),
  ('64e03f01-a560-5c5d-abaa-b0e4d694d678', 'a6f2f231-3eba-5e96-9b25-aa80fe33ac47', 'en', 'Warm sweet potato salad with bacon and mustard dressing', 'Boiled sweet potatoes with crispy bacon, celery, green onions and jalapeño in a whole-grain mustard, rice vinegar and olive oil dressing instead of mayo.', '<ol><li>Bring a pot of salted water to a boil, add the sweet potato chunks and simmer 10–15 minutes until fork tender. Drain, quickly rinse with cold water and set aside.</li><li>Cook the bacon until crisp, cool and crumble into a large bowl. Add the celery and green onions.</li><li>For the dressing whisk together the jalapeño, mustard, garlic, vinegar, olive oil, salt and pepper.</li><li>Add the sweet potatoes to the bowl, drizzle with the dressing and toss gently. Taste and adjust the seasoning.</li></ol><p><em>Serve warm, chilled or at room temperature.</em></p>', CURRENT_TIMESTAMP),
  ('eb553025-de5d-5ee5-8b52-c50d508b7214', '9633cfee-1cfd-5450-8e1b-f7e76d6a18ea', 'ru', 'Тостады с чёрной фасолью и сальсой из духовки', 'Хрустящие кукурузные лепёшки, запечённые в духовке, с тёплым пюре из чёрной фасоли, лука и сальсы. Любые свежие добавки сверху.', '<ol><li>Разогрейте духовку до 200 °C. В кастрюле на средне-сильном огне разогрейте масло, добавьте нарезанный лук и соль и жарьте 2 минуты до начала мягкости.</li><li>Добавьте фасоль и сальсу, перемешайте и прогревайте около 4 минут, периодически помешивая. Слегка разомните и отставьте.</li><li>Разложите тортильи в один слой на противне и запекайте около 6 минут до хруста, перевернув один раз.</li><li>Выложите фасоль на хрустящие лепёшки, добавьте начинки и сразу подавайте.</li></ol><p><em>Добавьте авокадо, капусту, сметану, помидоры, кинзу и сок лайма.</em></p>', CURRENT_TIMESTAMP),
  ('b72de654-c88c-5c6a-8fc3-00505a751c19', '9633cfee-1cfd-5450-8e1b-f7e76d6a18ea', 'en', 'Baked black bean tostadas with salsa', 'Oven-crisped corn tortillas topped with a warm mash of black beans, onion and salsa and any fresh toppings you like.', '<ol><li>Preheat the oven to 400 °F (200 °C). In a saucepan heat the olive oil over medium-high, add the diced onion and salt and cook 2 minutes until just softening.</li><li>Add the black beans and salsa, stir to coat and heat about 4 minutes, stirring occasionally. Mash lightly and set aside.</li><li>Spread the tortillas in a single layer on a baking sheet and bake about 6 minutes until crisp, flipping once.</li><li>Spoon the beans over the crisp tortillas, pile on the toppings and serve right away.</li></ol><p><em>Top with avocado, cabbage, sour cream, tomatoes, cilantro and a squeeze of lime.</em></p>', CURRENT_TIMESTAMP),
  ('aa4e138f-a947-5273-bd9f-ab3ef93758c0', 'e1b0e32f-4967-5c8b-8f51-f4d1463819fe', 'ru', 'Сэндвичи «Сэмми Джо» с говяжьим фаршем в сладко-кислом соусе', 'Булочки для бургеров с начинкой из говяжьего фарша, лука, перца и тёртой моркови в соусе из кетчупа, вустерского соуса и коричневого сахара. Готовится из продуктов, которые есть в кладовке.', '<ol><li>В большой сковороде на среднем огне разогрейте масло. Обжарьте лук и перец 5 минут, помешивая, затем добавьте морковь и готовьте ещё около 3 минут до мягкости.</li><li>Добавьте фарш, чили, соль, чесночный порошок и горчицу. Готовьте 6–8 минут, разбивая комки, пока мясо не будет готово, а овощи не станут совсем мягкими.</li><li>Добавьте томатную пасту и жарьте минуту, постоянно помешивая.</li><li>Смешайте кетчуп, вустерский соус, коричневый сахар, уксус и воду, влейте в сковороду и варите на слабом огне около 5 минут, пока соус не загустеет.</li><li>Выложите начинку на нижние половинки булочек, добавьте сыр, накройте верхней половинкой и сразу подавайте.</li></ol><p><em>Добавьте ломтик сыра и подайте с салатом или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('e84f03c8-2cd0-51ab-89f7-2c70383b2770', 'e1b0e32f-4967-5c8b-8f51-f4d1463819fe', 'en', 'Sloppy joes with beef and vegetables', 'Hamburger buns piled with a sweet-and-tangy ground beef filling with onion, pepper and grated carrot in a ketchup, Worcestershire and brown sugar sauce, made from pantry ingredients.', '<ol><li>In a large skillet heat the oil over medium. Cook the onion and pepper for 5 minutes, stirring, then add the carrot and cook about 3 minutes more until softened.</li><li>Add the beef, chili powder, salt, garlic powder and mustard. Cook 6–8 minutes, breaking up the beef, until cooked through and the vegetables are very soft.</li><li>Add the tomato paste and cook, stirring constantly, for a full minute.</li><li>Whisk the ketchup, Worcestershire sauce, brown sugar, vinegar and water, pour over the beef and simmer about 5 minutes until thickened.</li><li>Spoon the filling onto the bottom buns, add the cheese, top with the bun tops and serve immediately.</li></ol><p><em>Add a slice of cheese and serve with a salad or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('2e93b685-cd03-5c88-ad3d-80938d0b603a', 'ff2af4c8-4c77-547e-b4b9-f40817eef1d8', 'ru', 'Куриные наггетсы из фарша с цветной капустой', 'Домашние наггетсы из куриного фарша с незаметной цветной капустой в хрустящей панировке из сухарей. Запекаются в духовке или готовятся в аэрогриле.', '<ol><li>В большой миске хорошо смешайте куриный фарш, цветную капусту, соль, луковый и чесночный порошок и перец. Сформуйте 30 круглых плоских наггетсов по 25 г.</li><li>Взбейте яйцо в одной миске, насыпьте сухари в другую. Обмакните наггетсы в яйцо, затем обваляйте в сухарях.</li><li>В духовке: разогрейте до 230 °C, выложите на смазанный маслом противень и сбрызните маслом. Запекайте 10 минут, переверните, снова сбрызните и запекайте ещё около 6 минут до золотистого цвета и готовности.</li><li>В аэрогриле: выкладывайте в один слой партиями, сбрызните маслом и готовьте при 200 °C 8–9 минут, перевернув на середине и сбрызнув маслом.</li></ol><p><em>Подавайте с кетчупом, горчично-медовым или любимым соусом и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('7bbd82af-66ab-51e6-97c1-867d9a35596c', 'ff2af4c8-4c77-547e-b4b9-f40817eef1d8', 'en', 'Baked ground chicken nuggets with hidden cauliflower', 'Homemade nuggets from ground chicken with hidden cauliflower rice, coated in crispy breadcrumbs and baked or air fried.', '<ol><li>In a large bowl mix the ground chicken, cauliflower rice, salt, onion powder, garlic powder and pepper well. Shape into 30 flat round nuggets, about 25 g each.</li><li>Beat the egg in one bowl and put the breadcrumbs in another. Dip the nuggets in the egg, then in the crumbs.</li><li>Oven: preheat to 450 °F (230 °C), place on an oiled sheet pan and spray with oil. Bake 10 minutes, flip, spray again and bake about 6 more minutes until golden and cooked through.</li><li>Air fryer: arrange in a single layer in batches, spray with oil and cook at 400 °F (200 °C) 8–9 minutes, flipping halfway and spraying again.</li></ol><p><em>Serve with ketchup, honey mustard or your favorite dip and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('e6c84482-0c98-5e54-a531-c7ff2e23cf0e', 'e2a95650-85c6-5af8-ba72-0c35e97ad4fd', 'ru', 'Лосось медленного запекания со сметанно-горчичным соусом и укропом', 'Целый пласт филе лосося, медленно запечённый при низкой температуре до нежной сочной текстуры, с соусом из сметаны, дижонской горчицы, каперсов и укропа.', '<ol><li>Разогрейте духовку до 135 °C, застелите противень пергаментом. Достаньте лосось из холодильника, чтобы он немного согрелся.</li><li>Смешайте сметану, горчицу, укроп, каперсы с рассолом, соль и перец, добавьте цедру и сок половины лимона. Соус должен быть густым, но стекающим с ложки; при необходимости добавьте воды или лимонного сока.</li><li>Обсушите лосось и выложите кожей вниз на противень. Намажьте тонким слоем примерно 3 ст. л. соуса.</li><li>Запекайте 35–50 минут в зависимости от формы куска, пока рыба не будет едва готова и не начнёт расслаиваться (57 °C внутри).</li><li>Дайте рыбе постоять 5 минут, полейте оставшимся соусом или подайте его отдельно, украсьте укропом.</li></ol><p><em>Полейте оставшимся соусом, украсьте веточками укропа, подайте с картофелем или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('6e46d278-3866-5ee9-a1d4-66649e1dbd53', 'e2a95650-85c6-5af8-ba72-0c35e97ad4fd', 'en', 'Slow-roasted salmon with creamy mustard dill sauce', 'A whole side of salmon roasted low and slow until meltingly tender, with a sour cream, Dijon, caper and dill sauce.', '<ol><li>Preheat the oven to 275 °F (135 °C) and line a rimmed baking sheet with parchment. Take the salmon out of the fridge to lose some chill.</li><li>Combine the sour cream, mustard, dill, capers with their brine, salt and pepper, and add the zest and juice of half a lemon. The sauce should be thick but drizzle-able; add a splash of water or more lemon juice if needed.</li><li>Pat the salmon dry and place skin-side down on the pan. Spread about 3 tbsp of the sauce in a thin layer over the fish.</li><li>Roast 35–50 minutes depending on the shape until the salmon is just cooked through, very moist and flakes easily (135 °F / 57 °C inside).</li><li>Rest 5 minutes, drizzle with the remaining sauce or serve it on the side and garnish with dill.</li></ol><p><em>Drizzle with the remaining sauce, garnish with dill sprigs and serve with potatoes or salad.</em></p>', CURRENT_TIMESTAMP),
  ('ba57cb88-5029-5ee1-822b-7449cfd62d51', 'a00e0589-73ba-545c-8de4-ce3986fcd590', 'ru', 'Куриные отбивные в панировке из аэрогриля', 'Тонкие куриные отбивные, маринованные в оливковом масле с уксусом и травами, в панировке с пармезаном. Получаются хрустящими и сочными.', '<ol><li>Разрежьте грудки вдоль пополам, чтобы получилось 4 эскалопа, и отбейте до толщины около 6 мм.</li><li>Посолите, посыпьте чесночным порошком и половиной итальянских трав, залейте смесью оливкового масла и уксуса и мариновать минимум 1 час.</li><li>Смешайте сухари, пармезан и остальные травы в одной миске, а в другую влейте взбитое яйцо. Обмакните отбивные в яйцо, затем в сухари, сбрызните с двух сторон маслом.</li><li>Выложите в один слой в корзину аэрогриля (партиями) и готовьте при 200 °C 4 минуты до золотистого верха, переверните, сбрызните маслом и готовьте ещё 3–4 минуты. Можно запекать в духовке при 220 °C около 15 минут.</li></ol><p><em>Подавайте с овощами, салатом или пастой.</em></p>', CURRENT_TIMESTAMP),
  ('0c8360c7-7a7f-5f54-b931-af7ee8b15c9a', 'a00e0589-73ba-545c-8de4-ce3986fcd590', 'en', 'Air fryer breaded chicken cutlets', 'Thin chicken cutlets marinated in an olive oil and vinegar herb dressing, coated with breadcrumbs and parmesan and cooked crisp and juicy in the air fryer.', '<ol><li>Slice the chicken breasts in half lengthwise into 4 cutlets and pound to ¼ inch thick.</li><li>Season with the salt, garlic powder and half the Italian seasoning, pour over the olive oil and vinegar mixture and marinate at least 1 hour.</li><li>Mix the breadcrumbs, parmesan and remaining herbs in one bowl and put the beaten egg in another. Dip each cutlet in egg then crumbs and spray both sides with oil.</li><li>Place in a single layer in the air fryer basket (in batches) and cook at 400 °F (200 °C) 4 minutes until golden, flip, spray and cook 3–4 more minutes. Alternatively bake in a 425 °F (220 °C) oven about 15 minutes.</li></ol><p><em>Serve with vegetables, a salad or pasta.</em></p>', CURRENT_TIMESTAMP),
  ('a2568fdc-025e-5b8a-860a-b9da5c2fd018', 'fe259556-338f-520c-a90b-f89174d29c62', 'ru', 'Чечевичный суп с тыквой и кейлом', 'Постный овощной суп с зелёной чечевицей, мускатной тыквой, луком-пореем, морковью и листовой капустой кейл на овощном бульоне.', '<ol><li>Разогрейте кастрюлю с толстым дном на среднем огне, добавьте масло, затем лук, морковь, лук-порей и сельдерей. Убавьте огонь и готовьте 4–5 минут, помешивая.</li><li>Добавьте томатную пасту и готовьте 2 минуты, помешивая.</li><li>Влейте бульон, положите лавровый лист и чечевицу, доведите до кипения. Убавьте огонь, накройте и варите 20 минут, пока чечевица не будет готова наполовину.</li><li>Добавьте тыкву и варите около 15 минут до мягкости. Выньте лавровый лист, посолите и поперчите.</li><li>Положите кейл и варите ещё 7 минут до мягкости.</li></ol><p><em>Хорош с ломтиком цельнозернового хлеба.</em></p>', CURRENT_TIMESTAMP),
  ('e3e943ba-0ef1-5209-b32a-a6ef4c5a8501', 'fe259556-338f-520c-a90b-f89174d29c62', 'en', 'Butternut squash and lentil soup with kale', 'Vegan vegetable soup with green lentils, butternut squash, leeks, carrot and kale in vegetable broth.', '<ol><li>Heat a heavy pot over medium, add the oil, then the onion, carrot, leeks and celery; reduce the heat and cook 4–5 minutes, stirring.</li><li>Add the tomato paste and cook 2 minutes, stirring.</li><li>Pour in the broth, add the bay leaf and lentils and bring to a boil. Reduce, cover and simmer 20 minutes until halfway cooked.</li><li>Add the butternut and cook about 15 minutes until tender. Discard the bay leaf, season with salt and pepper.</li><li>Add the kale and cook 7 more minutes until tender.</li></ol><p><em>Serve with a slice of whole-grain bread.</em></p>', CURRENT_TIMESTAMP),
  ('0dba7872-4535-504a-a3ba-fbc60c814ca2', 'ab682eab-4d69-542d-88ad-bcadcb5075e3', 'ru', 'Курица по-охотничьи (какчиаторе) с макаронами', 'Куриные бёдра, тушённые с болгарским перцем, грибами и луком в густом томатном соусе с орегано и базиликом, с макаронами из цельнозерновой муки.', '<ol><li>Посолите и поперчите курицу.</li><li>В глубокой сковороде на среднем-сильном огне слегка смажьте маслом и обжарьте курицу по 3–4 минуты с каждой стороны до румяности. Отложите.</li><li>В той же сковороде обжарьте перец, лук и чеснок на среднем огне 3–4 минуты до мягкости лука, затем добавьте грибы на 2–3 минуты. Посолите и поперчите.</li><li>Добавьте помидоры, курицу, бульон и орегано, накройте и доведите до кипения. Тушите на слабом огне 35–45 минут до мягкости курицы. Базилик добавьте за 5 минут до конца.</li><li>Отварите макароны по инструкции и подайте курицу с соусом на порции пасты.</li></ol><p><em>Подавайте на отварных макаронах, посыпав свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('59b15f52-0b20-5803-afc6-e15a37e71339', 'ab682eab-4d69-542d-88ad-bcadcb5075e3', 'en', 'Chicken cacciatore with whole wheat pasta', 'Chicken thighs slowly simmered with bell pepper, mushrooms and onion in a rich tomato sauce with oregano and basil, served over whole wheat pasta.', '<ol><li>Season the chicken with salt and pepper.</li><li>Heat a large heavy sauté pan over medium-high, lightly oil it and brown the chicken 3–4 minutes per side. Set aside.</li><li>Sauté the pepper, onion and garlic in the same pan 3–4 minutes until the onion is tender, add the mushrooms for 2–3 minutes and season.</li><li>Add the tomatoes, chicken, broth and oregano, cover and bring to a simmer. Simmer on low 35–45 minutes until the chicken is tender, adding the basil 5 minutes before the end.</li><li>Cook the pasta per package directions and serve the chicken and sauce over it.</li></ol><p><em>Serve over cooked pasta with fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('96fa6f0d-eb85-5ee8-92cc-b13df35c40d1', 'ac15c9f1-09b6-5f45-83d4-7a4080495296', 'ru', 'Мясной хлеб из индейки с кабачком и овсяными хлопьями', 'Сочный запечённый рулет из фарша индейки с тёртым кабачком, овсянкой, яйцом и майораном под кетчупово-вустерской глазурью.', '<ol><li>Разогрейте духовку до 175 °C.</li><li>Смешайте в небольшой миске 2 ст. л. кетчупа с вустерским соусом.</li><li>В миске соедините фарш индейки, отжатый кабачок, сушёный лук, овсяные хлопья, яйцо, оставшийся кетчуп (¼ стакана), соль и майоран.</li><li>Сформуйте хлеб, выложите на противень и полейте сверху приготовленным соусом.</li><li>Запекайте без крышки 55–60 минут, затем дайте постоять 5 минут и нарежьте.</li></ol><p><em>Дайте отдохнуть 5 минут перед нарезкой, подавайте с пюре или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('dcda1e16-80ac-5d5a-b944-3a333d9657eb', 'ac15c9f1-09b6-5f45-83d4-7a4080495296', 'en', 'Turkey meatloaf with zucchini and oats', 'Juicy baked meatloaf of ground turkey with grated zucchini, oats, egg and marjoram under a ketchup and Worcestershire glaze.', '<ol><li>Preheat the oven to 350 °F (175 °C).</li><li>In a small bowl combine 2 tbsp of the ketchup with the Worcestershire sauce.</li><li>In a bowl mix the turkey, squeezed zucchini, dried onion, oats, egg, ¼ cup ketchup, salt and marjoram.</li><li>Shape into a loaf, place on a baking sheet and spoon the sauce on top.</li><li>Bake uncovered 55–60 minutes, rest 5 minutes and slice.</li></ol><p><em>Rest 5 minutes before slicing and serve with mashed potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('66a568f8-cea1-5386-bf4d-2d00b0d81e4c', '1ce15074-19e9-53cd-b245-554ad33a2b97', 'ru', 'Запечённая целая курица с розмарином и лимоном', 'Курица, натёртая травами и фаршированная лимоном, луком, чесноком и розмарином, запеченная до золотистой корочки и мягкого сочного мяса.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>Натрите курицу снаружи и внутри солью, перцем и прованскими травами.</li><li>Выжмите на курицу сок половины лимона, а остатки лимона вместе с луком, чесноком и ветками розмарина положите внутрь. Свяжите ножки кулинарной ниткой и подоткните кончики крыльев.</li><li>Запекайте на противне 50–60 минут, пока сок не станет прозрачным, а внутри (между бедром и ножкой) не будет 71 °C.</li><li>Накройте фольгой и дайте отдохнуть 10 минут перед нарезкой.</li></ol><p><em>Дайте отдохнуть 10 минут под фольгой, нарежьте и подавайте с картофелем или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('0f546829-f163-5356-b779-5dc437f1697b', '1ce15074-19e9-53cd-b245-554ad33a2b97', 'en', 'Roast whole chicken with rosemary and lemon', 'A whole chicken rubbed with herbs and stuffed with lemon, onion, garlic and rosemary, roasted until golden with tender juicy meat.', '<ol><li>Heat the oven to 425 °F (220 °C).</li><li>Season the chicken inside and out with salt, pepper and herbes de Provence.</li><li>Squeeze half the lemon over the chicken and stuff the rest of the lemon with the onion, garlic and rosemary inside. Tie the legs together with kitchen twine and tuck the wing tips.</li><li>Roast on a sheet pan 50–60 minutes until the juices run clear and the internal temperature between thigh and leg is 160 °F (71 °C).</li><li>Tent with foil and rest 10 minutes before carving.</li></ol><p><em>Rest 10 minutes tented with foil, carve and serve with potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('9684a54d-519e-5c9a-bee7-1c69b088329f', 'a9f763fe-3fb7-5fe7-9531-9f8bcb5c8a06', 'ru', 'Куриные бёдра с пастой орзо в томатном соусе в одной сковороде', 'Хрустящие куриные бёдра запекаются прямо поверх орзо в чесночно-томатном бульоне с базиликом. Готовится в одной жаропрочной сковороде.', '<ol><li>Разогрейте духовку до 190 °C. Посолите бёдра ¾ ч. л. соли, дайте им согреться до комнатной температуры и хорошо обсушите кожу бумажным полотенцем.</li><li>Разогрейте масло в большой жаропрочной сковороде на среднем-слабом огне и обжаривайте бёдра кожей вниз 12–15 минут до золотистой хрустящей корочки. Переложите на тарелку.</li><li>В той же сковороде обжарьте лук с оставшейся солью 4–5 минут, добавьте орзо и поджаривайте 4–5 минут до золотистого цвета и ореховому аромату.</li><li>Добавьте чеснок и томатную пасту и готовьте 2–3 минуты до карамелизации. Влейте бульон и доведите до кипения.</li><li>Уложите бёдра на орзо мякотью вниз так, чтобы кожа была над жидкостью, и запекайте 20–25 минут до готовности орзо. Подавайте в сковороде с сыром и базиликом.</li></ol><p><em>Посыпьте тёртым сыром и базиликом и подайте с овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('93f7d0db-2b41-5eb2-ae03-667bc20e2bcd', 'a9f763fe-3fb7-5fe7-9531-9f8bcb5c8a06', 'en', 'One-pot chicken thighs with orzo in tomato sauce', 'Crispy chicken thighs bake right on top of orzo cooked in a garlicky tomato broth with basil, all in one oven-safe skillet.', '<ol><li>Preheat the oven to 375 °F (190 °C). Season the thighs with ¾ tsp salt, bring to room temperature and pat the skin very dry.</li><li>Heat the oil in a large oven-safe skillet over medium-low and render the thighs skin-side down 12–15 minutes until golden and crisp. Remove.</li><li>In the same pan sauté the onion with the remaining salt 4–5 minutes, then add the orzo and toast 4–5 minutes until golden and nutty.</li><li>Stir in the garlic and tomato paste and cook 2–3 minutes to caramelize, then pour in the broth and bring to a boil.</li><li>Nestle the thighs, flesh-side down, into the orzo with the skin above the liquid and bake 20–25 minutes until the orzo is cooked. Serve from the pan with cheese and basil.</li></ol><p><em>Top with grated cheese and basil and serve with a side salad.</em></p>', CURRENT_TIMESTAMP),
  ('8f550b1d-a9e3-5ea2-ab9b-164fcfd68981', 'fe16fa00-4544-5ab9-877d-5ea9d719e965', 'ru', 'Фаршированные кабачки с индейкой и пармезаном', 'Лодочки из кабачков с начинкой из фарша индейки, лука, чеснока и пармезана под хрустящими сухарями, запечённые в бульоне.', '<ol><li>Разогрейте духовку до 200 °C. Разрежьте кабачки вдоль и ложкой вычерпайте мякоть, оставив стенки толщиной около 6 мм. Выложите половинки в форму. Мякоть мелко порубите.</li><li>В большой сковороде растопите масло, 2–3 минуты на среднем-слабом огне обжарьте лук, шалот и чеснок до прозрачности. Добавьте мякоть кабачка и щепотку соли на 2–3 минуты, затем вино и дайте ему выпариться.</li><li>Добавьте фарш индейки, посолите и поперчите и готовьте около 5 минут, разбивая на кусочки, до готовности. Всыпьте паприку, чесночный порошок и итальянские травы, перемешайте и готовьте ещё минуту. Остудите.</li><li>В остывшую начинку добавьте пармезан и белок, перемешайте. Начините кабачки, плотно утрамбовывая, посыпьте сухарями. Влейте бульон на дно формы и плотно накройте фольгой.</li><li>Запекайте 35 минут и подавайте сразу.</li></ol><p><em>Подавайте горячими с салатом или томатным соусом.</em></p>', CURRENT_TIMESTAMP),
  ('ff8b9273-7c05-5cb9-a958-611619b690bd', 'fe16fa00-4544-5ab9-877d-5ea9d719e965', 'en', 'Turkey stuffed zucchini boats with parmesan', 'Zucchini boats filled with ground turkey, onion, garlic and parmesan, topped with breadcrumbs and baked in broth.', '<ol><li>Preheat the oven to 400 °F (200 °C). Halve the zucchini lengthwise and scoop out the flesh with a spoon, leaving ¼-inch walls; arrange in a baking dish and chop the scooped flesh.</li><li>In a large skillet melt the butter and cook the onion, shallot and garlic on medium-low 2–3 minutes until translucent. Add the chopped zucchini and a pinch of salt for 2–3 minutes, then the wine and cook until reduced.</li><li>Add the turkey with salt and pepper and cook about 5 minutes, breaking it up, until cooked through. Stir in the paprika, garlic powder and Italian seasoning and cook 1 more minute; let cool.</li><li>Stir the parmesan and egg white into the cooled filling. Fill the zucchini, pressing firmly, and top with breadcrumbs. Pour the broth into the bottom of the dish and cover tightly with foil.</li><li>Bake 35 minutes and serve right away.</li></ol><p><em>Serve hot with a salad or tomato sauce.</em></p>', CURRENT_TIMESTAMP),
  ('553c171b-1ffe-5ae8-8468-876e08c41258', 'b3ec40c5-3158-5214-9dee-6b3a15fe28df', 'ru', 'Запечённые пенне с колбасным фаршем, томатным соусом и тремя видами сыра', 'Паста с колбасным фаршем в домашнем томатном соусе, прослоённая рикоттой, сметаной и пармезаном и запечённая под слоем моцареллы.', '<ol><li>Разогрейте духовку до 190 °C и смажьте маслом форму 22×33 см. В большой кастрюле разогрейте 1 ст. л. масла на средне-сильном огне и обжарьте колбасный фарш 8–10 минут, разбивая комки, пока он не приготовится и не зарумянится. Переложите в миску, лишний жир слейте.</li><li>В той же кастрюле на слабом огне растопите оставшееся масло со сливочным. Добавьте орегано, хлопья чили и томатную пасту на минуту до потемнения, затем чеснок на 30–60 секунд.</li><li>Влейте томаты и 1 ч. л. соли, разомните томаты ложкой (или погружным блендером для гладкого соуса). Доведите до кипения, убавьте огонь, верните колбасу и варите 20–30 минут, иногда помешивая.</li><li>Смешайте рикотту, сметану, пармезан, ½ ч. л. соли и перец. Отварите пасту на 3 минуты меньше, чем указано, слейте, верните в кастрюлю, смешайте с половиной соуса и аккуратно вмешайте сырную смесь.</li><li>Тонко намажьте дно формы остатком соуса, выложите половину пасты, посыпьте половиной моцареллы. Повторите слои и закончите моцареллой.</li><li>Запекайте 20–30 минут, пока верх не зарумянится, а края не забулькают. Дайте постоять 10–15 минут.</li></ol><p><em>Дайте постоять 10–15 минут, посыпьте петрушкой и подайте со свежим зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('f9d49ad5-5d96-5ae1-98bc-0894f7587d89', 'b3ec40c5-3158-5214-9dee-6b3a15fe28df', 'en', 'Baked ziti with sausage and three cheeses', 'Pasta with sausagemeat in a homemade tomato sauce, layered with ricotta, soured cream and Parmesan and baked under a blanket of mozzarella.', '<ol><li>Heat the oven to 375 °F (190 °C) and butter a 22 × 33 cm dish. Heat 1 tbsp of the oil in a large pot over medium-high heat and cook the sausagemeat 8–10 minutes, breaking it up, until cooked and browning. Transfer to a bowl and pour off excess fat.</li><li>In the same pot over low heat melt the remaining oil with the butter. Add the oregano, chilli flakes and tomato purée for a minute until darkened, then the garlic for 30–60 seconds.</li><li>Add the tomatoes and 1 tsp salt and break up the tomatoes (or blend for a smooth sauce). Bring to a boil, reduce to low, return the sausagemeat and simmer 20–30 minutes, stirring occasionally.</li><li>Mix the ricotta, soured cream, Parmesan, ½ tsp salt and pepper. Cook the pasta 3 minutes less than the pack says, drain, return to the pan, stir in half the sauce and gently fold in the ricotta mixture.</li><li>Spread a thin layer of the reserved sauce in the dish, add half the pasta mixture and half the mozzarella. Repeat the layers and finish with mozzarella.</li><li>Bake 20–30 minutes until golden and bubbling at the edges. Let stand 10–15 minutes.</li></ol><p><em>Rest 10–15 minutes, sprinkle with parsley and serve with a crisp green salad.</em></p>', CURRENT_TIMESTAMP),
  ('596ce0dd-ab4d-5fc9-8465-610765184a0d', '194d684d-66be-5657-80d1-0fe79bbd378d', 'ru', 'Салат из кускуса с песто, фетой и овощами за 10 минут', 'Кускус, запаренный в овощном бульоне, с красным перцем, огурцом, зелёным луком, фетой, песто и кедровыми орехами. Подходит для ланчбокса.', '<ol><li>Высыпьте кускус в миску, залейте горячим овощным бульоном, накройте и оставьте на 10 минут, пока он не станет рассыпчатым, а бульон не впитается.</li><li>Пока кускус настаивается, нарежьте зелёный лук и перец, огурец нарежьте кубиками и добавьте к кускусу.</li><li>Вмешайте вилкой песто, раскрошите фету и посыпьте кедровыми орехами.</li></ol><p><em>Хорошо хранится в холодильнике, берите с собой на обед.</em></p>', CURRENT_TIMESTAMP),
  ('b6265a5a-185d-593b-aa55-a288a47620b0', '194d684d-66be-5657-80d1-0fe79bbd378d', 'en', '10-minute couscous salad with pesto and feta', 'Couscous steeped in vegetable stock and tossed with red pepper, cucumber, spring onions, feta, pesto and pine nuts. A great lunchbox filler.', '<ol><li>Tip the couscous into a bowl and pour over the hot stock. Cover and leave 10 minutes until fluffy and all the stock is absorbed.</li><li>Meanwhile slice the spring onions and pepper, dice the cucumber and add them to the couscous.</li><li>Fork through the pesto, crumble in the feta and scatter over the pine nuts.</li></ol><p><em>Keeps well in the fridge; take it for lunch.</em></p>', CURRENT_TIMESTAMP),
  ('affab96e-eccc-591d-b6c2-4e2870dc8007', '9a971a26-33e6-54ff-9bec-b97cd02eb80b', 'ru', 'Салат с курицей-гриль, булгуром, авокадо и зеленью', 'Сытный салат из жареной куриной грудки, булгура, стручковой фасоли, огурцов, авокадо, зелёного салата и трав с горчично-яблочной заправкой и сыром.', '<ol><li>Натрите куриные грудки маслом, посолите и поперчите. Обжарьте на разогретой сковороде-гриль 10–15 минут с каждой стороны до готовности и полос от гриля. Отставьте.</li><li>Отварите булгур по инструкции и остудите. Стручковую фасоль варите в кипящей воде 2–3 минуты до мягкости.</li><li>Для заправки измельчите в небольшом комбайне масло, уксус, сыр, горчицу и стебли укропа и петрушки до однородности.</li><li>В большой миске или на блюде соедините листья трав, шнитт-лук, салат, огурцы, авокадо, булгур и фасоль. Полейте заправкой и перемешайте. Нарежьте курицу, выложите сверху и посыпьте тёртым сыром.</li></ol><p><em>Нарежьте курицу и уложите сверху, посыпав тёртым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('2011d5b1-edde-5135-8794-b7212a0ef04f', '9a971a26-33e6-54ff-9bec-b97cd02eb80b', 'en', 'Chicken, bulgur and avocado green salad', 'A filling salad of griddled chicken breast, bulgur, green beans, cucumber, avocado, lettuce and herbs in a mustard-cider dressing finished with cheese.', '<ol><li>Rub the chicken with the oil and season well. Cook on a hot griddle pan about 10–15 minutes per side until cooked through with char lines. Set aside.</li><li>Cook the bulgur following the pack instructions and cool. Boil the green beans 2–3 minutes until tender.</li><li>For the dressing blitz the oil, vinegar, cheese, mustard and the dill and parsley stalks in a small food processor until combined.</li><li>In a large bowl or on a platter combine the herb leaves, chives, lettuce, cucumber, avocado, bulgur and beans. Drizzle with the dressing and toss. Slice the chicken on top and scatter with more grated cheese.</li></ol><p><em>Slice the chicken over the top and scatter with more grated cheese.</em></p>', CURRENT_TIMESTAMP),
  ('89e4266e-a6f9-538d-95b8-41a6c963244a', '325b5771-3fff-599a-9517-10b459db1a63', 'ru', 'Оладьи из кабачка, киноа и феты с зелёным луком', 'Румяные оладьи из тёртого кабачка, варёной киноа, феты, вяленых томатов и трав на яйце и муке. Подходят на завтрак, обед или ужин.', '<ol><li>Разогрейте 2 ст. л. масла в сковороде на среднем огне, 6–8 минут тушите зелёный лук с щепоткой соли до мягкости.</li><li>Отожмите натёртый кабачок в чистом полотенце. Смешайте в миске кабачок, лук, киноа, фету, вяленые томаты, паприку, чесночный порошок, мяту, большую часть укропа, яйца и муку, посолите и поперчите.</li><li>Налейте в сковороду 1 ст. л. масла на среднем огне. Выкладывайте по 2 полные ложки смеси, разравнивая, и жарьте порциями 6–8 минут, переворачивая, до хруста и румяности, подливая масло по необходимости.</li><li>Подавайте тёплыми с йогуртом, лимоном и джемом чили, посыпав оставшимся укропом.</li></ol><p><em>Подайте с йогуртом, лимоном и острым джемом чили.</em></p>', CURRENT_TIMESTAMP),
  ('cce02eaa-e4ce-54e3-9a5a-9218a1fd1b7a', '325b5771-3fff-599a-9517-10b459db1a63', 'en', 'Feta, zucchini and quinoa fritters with spring onion', 'Golden fritters of grated zucchini, cooked quinoa, feta, sun-dried tomatoes and herbs bound with egg and flour. Good for breakfast, lunch or dinner.', '<ol><li>Heat 2 tbsp of the oil in a pan over medium and cook the spring onions with a pinch of salt for 6–8 minutes until softened.</li><li>Squeeze the grated zucchini dry in a clean tea towel. Combine it with the onions, quinoa, feta, tomatoes, paprika, garlic, mint, most of the dill, eggs and flour, season and mix well.</li><li>Add 1 tbsp of the oil to the pan over medium heat. Spoon in 2 heaped tbsp of the mixture per fritter, flatten and fry in batches 6–8 minutes, turning, until crisp and brown, adding more oil as needed.</li><li>Serve warm with yogurt, lemon wedges and chilli jam, garnished with the remaining dill.</li></ol><p><em>Serve with yogurt, lemon wedges and chilli jam.</em></p>', CURRENT_TIMESTAMP),
  ('80a264d7-0f6e-552d-b539-cb7e5abb3ba6', '05d2c38e-f7b2-51fe-bc6f-553e7f0004ce', 'ru', 'Оладьи из зелёного горошка с рикоттой и укропом', 'Нежные оладьи из горошка, рикотты, яиц и муки с зелёным луком, укропом, петрушкой и лимонной цедрой. Подаются с йогуртом, авокадо и яйцом-пашот.', '<ol><li>Отварите замороженный горошек 3 минуты до мягкости, слейте, 30 секунд подержите под холодной водой и дайте остыть.</li><li>Взбейте муку, яйца и лимонную цедру до гладкости, вмешайте рикотту. Осторожно добавьте горошек, зелёный лук, укроп и петрушку.</li><li>В большой сковороде на слабом-среднем огне разогрейте 1 ч. л. масла. Выкладывайте по одной восьмой части теста и формируйте диск, жарьте по 3–4 минуты до золотистого низа, переверните и жарьте ещё 2–3 минуты. Держите тёплыми, пока жарите остальные.</li><li>Подавайте с йогуртом, авокадо и яйцом-пашот.</li></ol><p><em>Подайте с йогуртом, авокадо и яйцом-пашот.</em></p>', CURRENT_TIMESTAMP),
  ('f9a83071-a669-5e6b-b4d7-7c7d10cad45a', '05d2c38e-f7b2-51fe-bc6f-553e7f0004ce', 'en', 'Pea and ricotta fritters with dill', 'Creamy fritters of peas, ricotta, eggs and flour with spring onions, dill, parsley and lemon zest, served with yogurt, avocado and a poached egg.', '<ol><li>Cook the frozen peas 3 minutes until tender, drain, run under cold water for 30 seconds and let cool.</li><li>Beat the flour, eggs and lemon zest until smooth, then mix in the ricotta. Fold in the peas, spring onions, dill and parsley.</li><li>Heat 1 tsp of oil in a large pan over medium-low. Spoon in one eighth of the batter, shape into a disc and cook 3–4 minutes until golden underneath, then flip and cook 2–3 minutes more. Keep warm while you cook the rest.</li><li>Serve with yogurt, avocado and a poached egg.</li></ol><p><em>Serve with yogurt, avocado and a poached egg.</em></p>', CURRENT_TIMESTAMP),
  ('96f892ba-d0ba-515f-86ec-cc1c629b177b', '038d6566-6ec9-5fc8-9681-3f3bb58b48de', 'ru', 'Салат из кукурузы, сладкого перца и помидоров с лаймом', 'Яркий летний салат из зёрен кукурузы, красного и жёлтого перца, красного лука, помидоров черри и кинзы с заправкой из лайма и оливкового масла.', '<ol><li>Срежьте зёрна с початков и высыпьте в большую миску. Добавьте мелко нарезанные перцы, красный лук, четвертинки помидоров черри и кинзу.</li><li>Взбейте сок лайма, масло, щепотку соли и перец, при желании добавьте мелко нарезанный чили.</li><li>Полейте салат заправкой и перемешайте. Оставьте на 15–20 минут в холодильнике или подавайте сразу при комнатной температуре.</li></ol><p><em>Хорош к шашлыку и мясу на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('e2ee24d6-6d43-56b6-8301-afde0b002e6c', '038d6566-6ec9-5fc8-9681-3f3bb58b48de', 'en', 'Sweetcorn, pepper and lime confetti salad', 'A colourful summer salad of sweetcorn kernels, red and yellow peppers, red onion, cherry tomatoes and coriander in a lime and olive oil dressing.', '<ol><li>Cut the kernels off the cobs into a large bowl. Add the finely chopped peppers, red onion, quartered cherry tomatoes and coriander.</li><li>Whisk the lime juice, olive oil, a pinch of salt and pepper, adding the chopped chilli if using.</li><li>Pour the dressing over and toss. Chill 15–20 minutes or serve at once at room temperature.</li></ol><p><em>Great alongside barbecued meat.</em></p>', CURRENT_TIMESTAMP),
  ('b4680c99-688b-5532-a42f-3dbdf3f4536f', '3dc83598-be6a-5d69-9cf9-05dc6aae050f', 'ru', 'Курица джалфрези со шпинатом, бурым рисом и киноа', 'Лёгкая версия индийского карри: курица в томатном соусе со специями, цветным перцем и шпинатом, с гарниром из бурого риса и киноа.', '<ol><li>Промойте бурый рис, всыпьте в кипящую подсоленную воду, убавьте огонь и варите 20 минут, затем добавьте киноа и варите ещё 10 минут.</li><li>Тем временем в большой кастрюле на среднем огне разогрейте масло и обжарьте лук до лёгкой румяности. Добавьте полоски курицы и обжарьте до золотистого цвета, затем зиру, чеснок и имбирь на минуту.</li><li>Добавьте томатную пасту, куркуму, кориандр, чили и щепотку соли, перемешайте.</li><li>Влейте 300 мл кипятка и варите около 10 минут, пока соус не станет насыщенно-красным. Добавьте гарам масалу, перец и шпинат, накройте и готовьте несколько минут на среднем огне, пока шпинат не увянет, а перец не останется слегка хрустящим. При необходимости добавьте воды.</li><li>Слейте рис с киноа и подавайте с курицей, посыпав кинзой.</li></ol><p><em>Посыпьте свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('1bee4093-21c1-5203-83fa-0218115e6abc', '3dc83598-be6a-5d69-9cf9-05dc6aae050f', 'en', 'Chicken jalfrezi with spinach, brown rice and quinoa', 'A lighter take on the Indian curry: chicken in a spiced tomato sauce with colourful peppers and spinach, served with brown rice and quinoa.', '<ol><li>Rinse the brown rice well, add it to boiling salted water, reduce the heat and simmer 20 minutes, then add the quinoa and cook 10 minutes more.</li><li>Meanwhile heat the oil in a large pan over medium heat and fry the onion until just turning brown. Add the chicken strips and brown, then the cumin seeds, garlic and ginger for a minute.</li><li>Add the tomato purée, turmeric, coriander, chilli powder and a pinch of salt and mix well.</li><li>Pour in 300 ml of boiling water and simmer about 10 minutes until the sauce turns rich red. Stir in the garam masala, peppers and spinach, cover and cook a few minutes on medium until the spinach wilts and the peppers keep a little bite. Add water to adjust.</li><li>Drain the rice and quinoa and serve with the chicken, sprinkled with coriander.</li></ol><p><em>Sprinkle with fresh coriander.</em></p>', CURRENT_TIMESTAMP),
  ('953754cf-cac3-5ec9-a628-60767a38f287', '2038919f-f596-5c98-ac71-30e16be467b1', 'ru', 'Марокканские фрикадельки кефта в томатном соусе с оливками', 'Говяжьи фрикадельки со специями (паприка, зира, корица), тушённые в мультиварке или скороварке в томатном соусе с луком и зелёными оливками.', '<ol><li>Лук для соуса нарежьте и 2 минуты прогрейте в микроволновке (или обжарьте на сковороде или в режиме обжарки мультиварки 3–5 минут до мягкости).</li><li>Выложите в чашу лук, помидоры, паприку, зиру, соль, острую паприку, перец и оливки и перемешайте.</li><li>Смешайте все ингредиенты для фрикаделек, оставив 2 ст. л. кинзы. Аккуратно, не утрамбовывая, сформуйте около 20 небольших фрикаделек.</li><li>Выложите фрикадельки на соус, накройте и готовьте на низком режиме 4–6 часов (или 2–3 часа на высоком). В скороварке: 15 минут под высоким давлением и естественный сброс.</li><li>Посыпьте оставшейся кинзой и подавайте с рисом.</li></ol><p><em>Подавайте с бурым рисом или цветной капустой «рисом», посыпав кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('e0fadfba-c963-5476-9504-b18fad7000ae', '2038919f-f596-5c98-ac71-30e16be467b1', 'en', 'Moroccan kefta meatballs in tomato olive sauce', 'Spiced beef meatballs (paprika, cumin, cinnamon) simmered in a slow cooker or pressure cooker in a tomato and green olive sauce.', '<ol><li>Soften the sauce onion by microwaving it about 2 minutes (or sauté it 3–5 minutes on the stove or pressure cooker sauté setting).</li><li>Put the onion, tomatoes, paprika, cumin, salt, hot paprika, pepper and olives in the pot and stir.</li><li>Combine all the meatball ingredients, saving 2 tbsp cilantro. Gently, without packing tight, form about 20 small meatballs.</li><li>Place the meatballs on the sauce, cover and cook on low 4–6 hours (or high 2–3 hours). Pressure cooker: 15 minutes on high pressure with a natural release.</li><li>Top with the remaining cilantro and serve over rice.</li></ol><p><em>Serve with brown rice or cauliflower rice, garnished with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('5f36cba8-117a-5625-bfd5-01395e1ed460', 'f0aa8b84-b2bd-5444-892d-e18f9d87e614', 'ru', 'Яйца с кабачком и фетой на сковороде', 'Быстрый завтрак или лёгкий ужин: тёртый кабачок и лук, обжаренные до золотистого цвета, с расплавленной фетой и яйцами, приготовленными под крышкой.', '<ol><li>В небольшой антипригарной сковороде разогрейте масло и на среднем огне обжарьте тёртый лук и отжатый кабачок до мягкости и золотистого цвета.</li><li>Равномерно посыпьте кабачок фетой и прогрейте 30 секунд до размягчения.</li><li>Аккуратно вбейте яйца, накройте крышкой и готовьте на слабом огне, пока белок не схватится (желток по желанию жидкий или плотный). Посыпьте хлопьями перца.</li></ol><p><em>Посыпьте хлопьями красного перца и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('0999d1c8-4f27-5a94-8412-d510a325403b', 'f0aa8b84-b2bd-5444-892d-e18f9d87e614', 'en', 'Feta eggs with zucchini', 'A quick breakfast or light dinner of grated zucchini and onion sautéed until golden, topped with melted feta and eggs cooked under a lid.', '<ol><li>In a small nonstick skillet heat the oil and cook the grated onion and squeezed zucchini on medium until soft and golden.</li><li>Sprinkle the feta evenly over the zucchini and cook 30 seconds until melted.</li><li>Carefully crack in the eggs, cover and cook on low until the whites set and the yolks are runny or cooked to your liking. Sprinkle with red pepper flakes.</li></ol><p><em>Sprinkle with red pepper flakes and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('f476635a-4454-5a3e-901d-701f1c050223', 'ed3881ee-6cef-5b36-be69-a2160ebd0133', 'ru', 'Картофель в фольге с лимоном и петрушкой', 'Дольки молодого картофеля с оливковым маслом и чесночным порошком, запечённые в фольговых пакетах на гриле или в духовке, с лимонной цедрой и петрушкой.', '<ol><li>В большой миске перемешайте картофель с маслом, чесночным порошком, ½ ч. л. соли и перцем.</li><li>Выложите картофель в центр листа плотной фольги 45×45 см. Соедините короткие края и дважды сложите, запечатав пакет так, чтобы внутри оставалось место для пара.</li><li>На гриле: готовьте под крышкой на среднем огне 30 минут, встряхивая пакет каждые 10 минут. В духовке: запекайте при 200 °C 35–40 минут, встряхнув на середине.</li><li>Осторожно откройте пакет, добавьте оставшуюся соль, лимонную цедру и петрушку.</li></ol><p><em>Откройте пакет осторожно (пар горячий) и подайте к мясу или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('9dd1b22e-08f5-5c57-bcb7-973b088d8281', 'ed3881ee-6cef-5b36-be69-a2160ebd0133', 'en', 'Lemon-parsley potatoes in foil packets', 'Quartered baby potatoes tossed with olive oil and garlic powder, steamed in foil packets on the grill or in the oven and finished with lemon zest and parsley.', '<ol><li>In a large bowl toss the potatoes with the olive oil, garlic powder, ½ tsp salt and pepper.</li><li>Place the potatoes in the center of an 18×18 in heavy-duty foil sheet. Bring the short ends together and fold twice to seal, leaving room for steam.</li><li>Grill covered over medium heat 30 minutes, shaking every 10 minutes; or bake in a 400 °F (200 °C) oven 35–40 minutes, shaking halfway.</li><li>Open carefully and top with the remaining salt, lemon zest and parsley.</li></ol><p><em>Open the packet carefully (hot steam) and serve with meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('a51e3d7f-45e4-5ada-b8cf-c82a9db03461', '3bd0366b-371a-5ed7-ac80-aadf47449706', 'ru', 'Жареный рис с лососем, яйцом и цветной капустой (на одну порцию)', 'Быстрое блюдо на одного: рис, цветная капуста «рис», яйцо и кусочки лосося с зелёным луком и соевым соусом.', '<ol><li>Обжарьте лосось на сковороде на среднем-сильном огне по 5 минут с каждой стороны. Остудите и разделите вилкой на кусочки. Протрите сковороду.</li><li>Разогрейте ½ ч. л. кунжутного масла и обжарьте белые части зелёного лука около минуты до аромата.</li><li>Выложите рис ровным слоем и 2–3 минуты не перемешивайте, чтобы низ слегка подрумянился. Добавьте цветную капусту и готовьте 2–3 минуты, иногда помешивая.</li><li>Сдвиньте рис в сторону, вбейте яйцо и помешивайте 30–60 секунд до готовности. Перемешайте всё, добавьте соевый соус и оставшееся масло.</li><li>Аккуратно добавьте лосось, перемешайте и подавайте, посыпав зелёным луком.</li></ol><p><em>Подавайте сразу с зелёным луком и по вкусу острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('f4fb0322-21e7-5351-9022-d6f60a7cacd4', '3bd0366b-371a-5ed7-ac80-aadf47449706', 'en', 'Salmon fried rice with cauliflower rice (single serving)', 'A quick meal for one: rice, cauliflower rice, egg and flaked salmon with scallions and soy sauce.', '<ol><li>Cook the salmon in a skillet over medium-high 5 minutes per side. Flake with a fork and wipe the skillet.</li><li>Heat ½ tsp sesame oil and cook the scallion whites about 1 minute until fragrant.</li><li>Add the rice in an even layer and leave it 2–3 minutes until the bottom crisps; add the cauliflower rice and cook 2–3 minutes, stirring occasionally.</li><li>Push the rice aside, crack in the egg and stir 30–60 seconds until cooked, then mix everything and add the soy sauce and remaining sesame oil.</li><li>Gently fold in the salmon and serve garnished with scallion greens.</li></ol><p><em>Serve immediately with scallion greens and sriracha if you like.</em></p>', CURRENT_TIMESTAMP),
  ('a82c0e36-4c12-5db9-85e1-d0b5c84f7de2', 'f5ca718c-95d5-5990-8f40-cab9dd1c990f', 'ru', 'Куриное филе с грибами в чесночно-винном соусе', 'Куриное филе (тендерлойны) в муке, обжаренное до готовности, с шампиньонами, чесноком и соусом из белого вина, бульона и петрушки. Готовится за 20 минут.', '<ol><li>Посолите и поперчите куриное филе и слегка обваляйте в муке.</li><li>Разогрейте большую сковороду на среднем огне, добавьте 1 ч. л. масла сливочного и 1 ч. л. оливкового. Жарьте курицу по 5 минут с каждой стороны до готовности. Отложите в тёплое место.</li><li>Добавьте в сковороду остаток масел, чеснок на несколько секунд, затем грибы с солью и перцем и готовьте около 5 минут до золотистого цвета.</li><li>Влейте вино и бульон, добавьте петрушку и, соскребая налёт со дна, уварите жидкость вдвое. Полейте курицу соусом с грибами.</li></ol><p><em>Подавайте с бурым рисом, пастой, киноа или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('a9a87eec-33b7-5ec0-860e-6ebed39ae181', 'f5ca718c-95d5-5990-8f40-cab9dd1c990f', 'en', 'Chicken and mushrooms in garlic white wine sauce', 'Floured chicken tenderloins cooked golden, served with mushrooms and garlic in a quick white wine, broth and parsley sauce. Ready in 20 minutes.', '<ol><li>Season the chicken with salt and pepper and lightly dredge in flour.</li><li>Heat a large skillet on medium and add 1 tsp butter and 1 tsp olive oil. Cook the chicken about 5 minutes per side until no longer pink; keep warm.</li><li>Add the remaining butter and oil, the garlic for a few seconds, then the mushrooms with salt and pepper and cook about 5 minutes until golden.</li><li>Add the wine, broth and parsley, scraping the pan, and reduce the liquid by half. Top the chicken with the mushroom sauce.</li></ol><p><em>Serve with brown rice, pasta, quinoa or roasted vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('64bc31c4-b46f-567f-8107-bcbca81a7e43', '5eb10542-8245-5459-b44d-6c30f201bf07', 'ru', 'Свинина, томлёная в мультиварке, с грибами и поленой', 'Свиная корейка, 8 часов томлёная в соевом соусе, бульоне, бальзамическом уксусе, мёде и чесноке, разобранная на волокна и поданная с грибами и кремовой поленой.', '<ol><li>Слегка смажьте сковороду маслом и обжарьте свинину со всех сторон на среднем-сильном огне 7–8 минут.</li><li>В чаше мультиварки смешайте бульон, соевый соус, бальзамический уксус, мёд и чеснок. Положите свинину и готовьте на низком режиме 8 часов.</li><li>За 30 минут до конца достаньте мясо и дайте отдохнуть не менее 10 минут. Положите в чашу грибы и готовьте ещё 30 минут.</li><li>Пока готовятся грибы, вскипятите воду с солью, всыпьте поленту и убавьте огонь. Варите около 5 минут, помешивая, пока жидкость не впитается. Снимите с огня и накройте на 1–2 минуты.</li><li>Разберите свинину вилками, верните в чашу и перемешайте с грибами. Подавайте на поленте, посыпав петрушкой.</li></ol><p><em>Выложите на поленту порцию мяса с грибами и посыпьте петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('1fca53c4-327c-57fa-a320-8fa39c76272b', '5eb10542-8245-5459-b44d-6c30f201bf07', 'en', 'Slow cooker pork roast with mushrooms and polenta', 'Lean pork roast slow-cooked 8 hours in soy sauce, broth, balsamic vinegar, honey and garlic, shredded and served with mushrooms over creamy polenta.', '<ol><li>Lightly oil a large skillet and brown the pork on all sides over medium-high, about 7–8 minutes.</li><li>In the slow cooker mix the broth, soy sauce, balsamic vinegar, honey and garlic, add the pork and cook on low 8 hours.</li><li>30 minutes before the timer ends, remove the pork to rest at least 10 minutes and add the mushrooms to the pot for the last 30 minutes.</li><li>Meanwhile boil the water with the salt, add the polenta, reduce to low and cook about 5 minutes, stirring, until the liquid is absorbed. Cover off the heat 1–2 minutes.</li><li>Shred the pork with two forks, return to the pot and mix with the mushrooms. Serve over the polenta with parsley.</li></ol><p><em>Spoon pork and mushrooms over the polenta and garnish with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('a3b7a49a-55f1-50ec-871f-f6ebce05d3a7', '1d665910-8d2b-5486-8706-c6f4742d070a', 'ru', 'Салат из краснокочанной капусты, моркови и мяты', 'Хрустящий яркий салат из тонко нашинкованной краснокочанной капусты и моркови с мятой, лимонным соком и оливковым маслом.', '<ol><li>В миске соедините тонко нашинкованную капусту, морковь соломкой и рубленую мяту.</li><li>Добавьте лимонный сок, оливковое масло, соль и перец и хорошо перемешайте.</li></ol><p><em>Хорош как гарнир к мясу и рыбе или в лавашах с шаурмой.</em></p>', CURRENT_TIMESTAMP),
  ('8c800d4e-581e-55e3-a1c1-a888b5c1b182', '1d665910-8d2b-5486-8706-c6f4742d070a', 'en', 'Shredded red cabbage, carrot and mint salad', 'A colourful crunchy salad of finely shredded red cabbage and carrot with fresh mint, lemon juice and olive oil.', '<ol><li>In a bowl combine the finely shredded cabbage, julienned carrot and chopped mint.</li><li>Add the lemon juice, olive oil, salt and pepper and toss well.</li></ol><p><em>Serve as a side with meat and fish or tuck into wraps.</em></p>', CURRENT_TIMESTAMP),
  ('0a2e49df-6aac-5e48-ae0a-d3ec2202fb1b', '26c86159-57b9-572d-9225-f834512cee58', 'ru', 'Салат из айсберга с укропом, кинзой и красной капустой', 'Лёгкий освежающий салат из листьев айсберга с укропом, кинзой, шалотом, красной капустой и горошком, заправленный лимоном и оливковым маслом.', '<ol><li>Взбейте в банке с крышкой лимонный сок, масло, цедру, сахар, горчичный порошок, соль и перец.</li><li>Смешайте в салатнике шалот, укроп и кинзу и за 20 минут до подачи полейте третью заправки.</li><li>Сверху выложите порванный айсберг, красную капусту и горошек. Перед подачей добавьте остальную заправку и перемешайте.</li></ol><p><em>Заправляйте в два приёма: травы с шалотом за 20 минут до подачи, остальное перед самой подачей.</em></p>', CURRENT_TIMESTAMP),
  ('c058f8f9-f635-5323-935e-afefebb73b83', '26c86159-57b9-572d-9225-f834512cee58', 'en', 'Iceberg lettuce, dill and cilantro salad', 'Light refreshing salad of iceberg lettuce with lots of dill, cilantro, shallot, red cabbage and snow peas, in a lemony olive oil dressing.', '<ol><li>Shake the lemon juice, olive oil, zest, sugar, mustard powder, salt and pepper in a screw-top jar.</li><li>Mix the shallot, dill and cilantro in the salad bowl and drizzle with a third of the dressing about 20 minutes before serving.</li><li>Lay the torn iceberg, red cabbage and snow peas on top. Just before serving add the remaining dressing and toss.</li></ol><p><em>Dress in two stages: herbs and shallot 20 minutes before serving, the rest just before.</em></p>', CURRENT_TIMESTAMP),
  ('d59b9758-e31f-53f5-9ed1-684656293385', 'dd24ebd2-b712-560a-8118-7aa60425e0b2', 'ru', 'Салат с жемчужным кускусом, огурцами, помидорами и зеленью', 'Тёплый на вкус салат из крупного (израильского) кускуса с огурцами, помидорами черри, шпинатом, укропом, кинзой и лимонной заправкой с горчицей.', '<ol><li>В кастрюле на среднем-сильном огне разогрейте масло, обжарьте лук с чесноком до прозрачности и лёгкой золотистости.</li><li>Всыпьте кускус и прогрейте минуту, влейте бульон с водой, доведите до кипения, накройте и варите на слабом огне 10 минут, пока жидкость не впитается, а кускус не станет мягким, но упругим.</li><li>Разрыхлите вилкой и переложите в большую миску остывать.</li><li>Взбейте в банке цедру, лимонный сок, масло, горчицу, чеснок, сахар, соль и перец.</li><li>Добавьте к кускусу огурцы, помидоры, шпинат, кинзу и укроп, полейте заправкой и перемешайте.</li></ol><p><em>Подавайте при комнатной температуре как самостоятельное блюдо или гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('7171de7f-5c98-5cf5-a6ca-869503916cfa', 'dd24ebd2-b712-560a-8118-7aa60425e0b2', 'en', 'Pearl couscous salad with cucumber, tomato and herbs', 'Chewy pearl (Israeli) couscous tossed with cucumber, cherry tomatoes, spinach, dill and cilantro in a lemon Dijon dressing.', '<ol><li>Heat the oil in a saucepan over medium-high and sauté the onion and garlic until translucent and starting to brown.</li><li>Add the couscous and toast for a minute, pour in the broth and water, bring to a simmer, cover and cook gently 10 minutes until the liquid is absorbed and the couscous is tender but firm.</li><li>Fluff with a fork and transfer to a large bowl to cool.</li><li>Shake the lemon zest, juice, olive oil, Dijon, garlic, sugar, salt and pepper in a jar.</li><li>Add the cucumbers, tomatoes, spinach, cilantro and dill to the couscous, pour over the dressing and toss.</li></ol><p><em>Serve at room temperature as a meal or a side.</em></p>', CURRENT_TIMESTAMP),
  ('b4124893-9261-5e1f-a4a3-2709d94653c5', '10659421-b29e-545c-8695-df63dc4e67a5', 'ru', 'Зелёная шакшука с кейлом, брюссельской капустой и шпинатом', 'Современная версия шакшуки: тушёная зелень со специями и яйца, запечённые прямо в сковороде. Готовится в одной сковороде за 40 минут.', '<ol><li>В глубокой сковороде с крышкой разогрейте масло на среднем-сильном огне. Обжарьте тонко нарезанную брюссельскую капусту с щепоткой соли 5–6 минут до мягкости и румяности.</li><li>Убавьте огонь до среднего, добавьте лук и чеснок на 3–4 минуты, затем кейл порциями на 5 минут и в конце шпинат.</li><li>Добавьте специи и полстакана воды, накройте и тушите на средне-слабом огне 8–10 минут, пока кейл не станет мягким. Влейте лимонный сок.</li><li>Ложкой сделайте 4 углубления, разбейте в каждое по яйцу, слегка посолите, накройте и готовьте около 4 минут, пока яйца не схватятся по вкусу.</li><li>Сбрызните маслом, посыпьте зелёным луком, петрушкой и фетой и подавайте сразу.</li></ol><p><em>Посыпьте фетой и зеленью и подайте с хлебом или тёплой питой.</em></p>', CURRENT_TIMESTAMP),
  ('d7751db7-24b3-5d57-ad16-69cea765c5ea', '10659421-b29e-545c-8695-df63dc4e67a5', 'en', 'Green shakshuka with kale, Brussels sprouts and spinach', 'A modern take on shakshuka: braised spiced greens with eggs poached right in the pan, made in one skillet in about 40 minutes.', '<ol><li>In a lidded skillet heat the oil over medium-high. Cook the thinly sliced Brussels sprouts with a pinch of salt 5–6 minutes until softened and browned.</li><li>Lower the heat to medium and cook the onion and garlic 3–4 minutes, then add the kale in stages for 5 minutes and finally the spinach.</li><li>Add the spices and ½ cup of water, cover and cook on medium-low 8–10 minutes until the kale is wilted. Stir in the lemon juice.</li><li>Make 4 wells with a spoon, crack an egg into each, season with salt, cover and cook about 4 minutes until the eggs are done to your liking.</li><li>Drizzle with oil, garnish with green onion, parsley and feta and serve at once.</li></ol><p><em>Top with feta and herbs and serve with bread or warm pita.</em></p>', CURRENT_TIMESTAMP),
  ('671f92ee-acd2-5e41-8b7a-44150ceee577', '8f038082-6e68-52b3-8663-225e52f775e7', 'ru', 'Жареные баклажаны с зелёным перцем и помидорами и сумахом', 'Слои обжаренных баклажанов и зелёного перца со тушёными помидорами, чесноком и уксусом, присыпанные сумахом и зеленью. Подаётся тёплым или комнатной температуры.', '<ol><li>Выложите кружки баклажана на бумажные полотенца, щедро посолите и оставьте на 30 минут, чтобы вышла горечь. Промокните насухо.</li><li>Хорошо разогрейте масло на средне-сильном огне. Обжарьте полоски зелёного перца кожицей вниз до мягкости и коричневой кожицы. Выложите на полотенце, посолите и присыпьте сумахом.</li><li>В том же горячем масле обжарьте баклажаны с двух сторон до золотистого цвета, чтобы они не впитали слишком много масла. Откиньте на полотенце и щедро присыпьте сумахом.</li><li>При необходимости добавьте масла, обжарьте помидоры 2 минуты, добавьте чеснок и готовьте 4–5 минут. Убавьте огонь, влейте уксус, посолите, добавьте сумах и тушите, пока помидоры не станут мягкими и не отдадут сок.</li><li>Выложите на блюдо слоями баклажаны, перец и томатный соус. Украсьте мятой и грецкими орехами.</li></ol><p><em>Подайте с питой или рисом, посыпав мятой и грецкими орехами.</em></p>', CURRENT_TIMESTAMP),
  ('d178219a-05c5-5701-a40c-fa2bb527ac68', '8f038082-6e68-52b3-8663-225e52f775e7', 'en', 'Fried eggplant with green peppers, tomatoes and sumac', 'Layers of fried eggplant and green peppers with sautéed tomatoes, garlic and vinegar, dusted with sumac and herbs, served warm or at room temperature.', '<ol><li>Spread the eggplant rounds on paper towels, salt generously and leave 30 minutes to draw out bitterness. Pat dry.</li><li>Heat the oil well over medium-high. Fry the green pepper strips skin-side down until tender and browned. Drain on paper towels, salt and sprinkle with sumac.</li><li>In the same hot oil fry the eggplant on both sides until golden, keeping the oil hot so it does not soak up too much. Drain and sprinkle generously with sumac.</li><li>Add a little oil if needed, fry the tomatoes 2 minutes, add the garlic and cook 4–5 minutes. Lower the heat, add the vinegar, salt and sumac and cook until the tomatoes are tender and juicy.</li><li>Layer the eggplant, peppers and saucy tomatoes on a platter. Garnish with mint and walnuts.</li></ol><p><em>Serve with pita or rice, topped with mint and walnuts.</em></p>', CURRENT_TIMESTAMP),
  ('88e72ec0-982e-5a2e-be3a-67a446b481af', 'c99d4df9-6443-5cab-981b-9c82aa4e3e94', 'ru', 'Тёплый салат из запечённой тыквы с чечевицей и киноа', 'Запечённая в специях мускатная тыква, смешанная с отварной чёрной чечевицей, киноа, зелёным луком, петрушкой и лимонным соком. Вегетарианское основное блюдо или гарнир.', '<ol><li>Разогрейте духовку до 220 °C. Очистите тыкву от кожуры и семян (для удобства сначала прогрейте в микроволновке 2–3 минуты) и нарежьте кубиками.</li><li>Выложите тыкву на противень, посолите, посыпьте половиной специй (по 1 ч. л. корицы и душистого перца, ½ ч. л. кориандра и паприки, ¼ ч. л. зиры), обильно сбрызните маслом и перемешайте.</li><li>Запекайте 15 минут, добавьте чеснок, сбрызните маслом, перемешайте и запекайте ещё 10 минут.</li><li>Тем временем варите чёрную чечевицу в 3 стаканах подсоленной воды 20–25 минут и слейте. Киноа промойте и варите в 2 стаканах подсоленной воды под крышкой 15–20 минут до впитывания воды.</li><li>Смешайте чечевицу и киноа с оставшимися специями и солью, добавьте тыкву, нарубленный запечённый чеснок, зелёный лук и петрушку. Заправьте лимонным соком (начните с 2 ч. л.) и маслом, попробуйте. Посыпьте миндалём.</li></ol><p><em>Подайте тёплым или комнатной температуры, посыпав миндалём.</em></p>', CURRENT_TIMESTAMP),
  ('791328b4-c265-5437-a249-3a177c41ff30', 'c99d4df9-6443-5cab-981b-9c82aa4e3e94', 'en', 'Warm roasted butternut squash, lentil and quinoa salad', 'Spiced roasted butternut squash tossed with cooked black lentils, quinoa, scallions, parsley and lemon juice. A vegan main or side.', '<ol><li>Heat the oven to 425 °F (220 °C). Peel and seed the squash (microwave it 2–3 minutes first to make this easier) and cut into cubes.</li><li>Spread the squash on a baking sheet, salt, sprinkle with half the spices (1 tsp each cinnamon and allspice, ½ tsp each coriander and paprika, ¼ tsp cumin), drizzle generously with oil and toss.</li><li>Roast 15 minutes, add the garlic cloves with a little oil, toss and roast 10 minutes more.</li><li>Meanwhile simmer the black lentils in 3 cups of salted water 20–25 minutes and drain. Cook the rinsed quinoa in 2 cups salted water, covered, 15–20 minutes until absorbed.</li><li>Toss the lentils and quinoa with the remaining spices and salt, add the squash, chopped roasted garlic, scallions and parsley. Season with lemon juice (start with 2 tsp) and oil, taste and top with almonds.</li></ol><p><em>Serve warm or at room temperature, topped with toasted almonds.</em></p>', CURRENT_TIMESTAMP),
  ('5c782396-d368-5118-a8ec-1192aee0bb1f', '8bb33574-c56a-5a70-a142-269fc7d5bd9a', 'ru', 'Адас-поло — персидский рис с чечевицей, карамелизованным луком, финиками и изюмом', 'Парадный рис басмати, пропаренный с чечевицей, корицей и шафраном, с золотистым хрустящим тахдигом снизу и сладким луком, изюмом и финиками сверху.', '<ol><li>Промойте рис до прозрачной воды, залейте холодной водой с запасом на 2 пальца и оставьте минимум на 30 минут (лучше на ночь), затем слейте.</li><li>Разотрите шафран в порошок и разведите ½ ч. л. в 1/3 стакана воды.</li><li>Залейте чечевицу водой с запасом на 5 см, доведите до кипения и варите около 20 минут, пока снаружи не размякнет, а внутри останется чуть твёрдой. Слейте, смешайте с корицей и 1 ст. л. масла.</li><li>На сильном огне разогрейте 3 ст. л. масла и жарьте лук 20 минут до золотистого и хрустящего. Выложите на бумажное полотенце. В этом же масле на слабом огне прогрейте изюм около минуты.</li><li>Доведите до кипения 2 л воды с солью, варите рис 5–7 минут, пока он не станет слегка мягким, но упругим. Слейте и смешайте с чечевицей. В кастрюлю влейте нейтральное масло.</li><li>Смешайте 1 стакан риса с чечевицей и 1 ст. л. шафрановой воды, выложите в кастрюлю ровным слоем для тахдига. Сверху насыпьте остальной рис без утрамбовки, затем лук, изюм, финики и немного шафрановой воды. Проткните 5 отверстий до дна.</li><li>Закройте крышкой на сильном огне, когда пойдёт пар, убавьте до слабого. Оберните крышку полотенцем и готовьте на слабом огне около 1 часа. Аккуратно перемешайте рис, переложите, а тахдиг подайте отдельно.</li></ol><p><em>Хрустящую корочку тахдиг подайте отдельно, вместе с мясом или курицей.</em></p>', CURRENT_TIMESTAMP),
  ('d572200b-27e7-525e-a00f-ffb84fb3933a', '8bb33574-c56a-5a70-a142-269fc7d5bd9a', 'en', 'Adas polo (Persian rice and lentils with caramelized onions, dates and raisins)', 'A showpiece basmati rice steamed with lentils, cinnamon and saffron, with a golden crispy tahdig base and sweet onions, raisins and dates on top.', '<ol><li>Rinse the rice until the water runs clear, cover with 2 inches of cold water and soak at least 30 minutes (ideally overnight), then drain.</li><li>Grind the saffron to a powder and stir ½ tsp into ⅓ cup of water to bloom.</li><li>Cover the lentils with 2 inches of water, boil about 20 minutes until tender outside and slightly firm inside, drain and stir with the cinnamon and 1 tbsp of oil.</li><li>Heat the remaining 3 tbsp of oil over medium-high and fry the onions about 20 minutes until golden and crisp; drain on paper towels. In the same oil over low heat warm the raisins for a minute.</li><li>Bring 8 cups of salted water to a boil, parboil the rice 5–7 minutes until slightly softened but firm, drain and mix with the lentils. Pour the neutral oil into the clean pot.</li><li>Mix 1 cup of the rice and lentils with 1 tbsp of saffron water and press into an even layer in the pot for the tahdig. Add the remaining rice without pressing, top with the onions, raisins, dates and the rest of the saffron water and poke 5 holes to the bottom.</li><li>Cover and heat on high; when steam rises reduce to low. Wrap the lid in a tea towel and steam over low heat for about 1 hour. Fluff the rice into a dish and serve the crispy tahdig separately.</li></ol><p><em>Serve the crispy tahdig separately with meat or chicken.</em></p>', CURRENT_TIMESTAMP),
  ('3103b9e7-5dfe-5e48-bd17-4063037be0d5', '9fc20af0-b76c-5498-8955-6593878b2965', 'ru', 'Ширазский салат из огурцов и помидоров с зеленью и лаймом', 'Персидский салат без листьев: мелко нарезанные помидоры, огурцы и лук с укропом, петрушкой, кинзой, мятой, соком лайма и оливковым маслом.', '<ol><li>Выложите нарезанные мелкими кубиками помидоры в дуршлаг на несколько минут, чтобы стёк лишний сок.</li><li>В большой миске смешайте помидоры, огурцы, лук и болгарский перец.</li><li>Добавьте свежую зелень, сушёную мяту, соль, перец и сумах. Влейте сок лайма и оливковое масло и перемешайте. При возможности охладите 30–60 минут.</li></ol><p><em>Хорош к мясу, рису и кебабам; перед подачей охладите 30–60 минут.</em></p>', CURRENT_TIMESTAMP),
  ('f9d72248-64aa-5eb6-8671-2a9638f674d3', '9fc20af0-b76c-5498-8955-6593878b2965', 'en', 'Shirazi salad (Persian cucumber and tomato salad)', 'A leafless Persian salad of finely diced tomatoes, cucumbers and onion with dill, parsley, cilantro and mint, dressed in lime juice and olive oil.', '<ol><li>Place the small-diced tomatoes in a colander for a few minutes to drain excess liquid.</li><li>In a large bowl combine the tomatoes, cucumbers, onion and bell pepper.</li><li>Add the fresh herbs, dried mint, salt, pepper and sumac. Pour in the lime juice and olive oil and toss. If you have time, chill 30–60 minutes.</li></ol><p><em>Goes with meat, rice and kebabs; chill 30–60 minutes before serving.</em></p>', CURRENT_TIMESTAMP),
  ('4a671381-9531-5ad2-a768-a7eed0d98d51', '514da7f5-2789-52a9-a6fc-069e25e629b4', 'ru', 'Креветки с рисом, горошком и специями в одной сковороде', 'Рассыпчатый рис басмати с красным луком, перцем, зелёным горошком и специями, на котором в конце запекаются креветки. Готовится в одной сковороде с крышкой.', '<ol><li>Промойте рис, залейте водой и оставьте на 15–20 минут, пока зёрнышко не будет легко ломаться. Хорошо слейте воду.</li><li>В глубокой сковороде с крышкой разогрейте масло на среднем огне. Добавьте лук, перец, чеснок, горошек и петрушку с солью и готовьте 3 минуты. Добавьте специи и готовьте ещё 2–3 минуты.</li><li>Положите рис, щепотку соли и влейте воду. Доведите до кипения и уварите примерно наполовину, затем убавьте огонь, накройте и готовьте 15–20 минут до готовности риса.</li><li>Обсушите креветки и посолите. Откройте сковороду, утопите креветки в рисе, накройте и готовьте 3–5 минут, пока они не порозовеют. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('fb32dfbd-ab6c-5f34-92c4-34647f42e922', '514da7f5-2789-52a9-a6fc-069e25e629b4', 'en', 'One-pan shrimp and rice with peas and spices', 'Fluffy basmati rice with red onion, pepper, green peas and spices, topped near the end with shrimp that steam on top. Made in one lidded pan.', '<ol><li>Rinse the rice and soak in water 15–20 minutes until a grain breaks easily. Drain well.</li><li>In a deep lidded pan heat the oil over medium. Add the onion, pepper, garlic, peas and parsley with salt and cook 3 minutes, then the spices for 2–3 minutes more.</li><li>Add the drained rice, a pinch of salt and the water. Boil until the liquid has reduced by half, then reduce the heat, cover and cook 15–20 minutes until the rice is done.</li><li>Pat the shrimp dry and salt them. Uncover, nestle the shrimp into the rice, cover and cook 3–5 minutes until pink. Garnish with parsley.</li></ol><p><em>Garnish with parsley and serve with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('ef41fb63-64f6-57f0-a91a-a9b038c74c65', '72455b55-0428-5614-9940-9571ee4ae351', 'ru', 'Ребол­лита — тосканский суп с белой фасолью, кейлом и хлебом', 'Густой суп из белой фасоли, томатов, овощей и кейла с подсушенным хлебом, которому дают пропитаться. С рёбрышком пармезана для аромата.', '<ol><li>Разогрейте духовку до 200 °C. Порвите хлеб кусками, смешайте с оливковым маслом, разложите на противне и подсушите около 10 минут до золотистого цвета.</li><li>В кастрюле разогрейте 3 ст. л. масла, обжарьте лук, сельдерей и морковь с солью до мягкости, добавьте чеснок на минуту.</li><li>Добавьте томаты, вино и бульон, разомните томаты ложкой. Взбейте в блендере примерно ½ стакана томатной жидкости с 1 стаканом фасоли.</li><li>Положите рёбрышко пармезана, тимьян, лавровый лист, орегано, чили и щепотку соли, варите на среднем огне около 20 минут.</li><li>Добавьте целую и пюрированную фасоль и кейл, варите несколько минут. Вмешайте половину хлеба и варите, пока кейл не станет мягким, а хлеб не пропитается.</li><li>Выньте остатки корки, лавровый лист и тимьян. Положите сверху оставшийся хлеб, сбрызните маслом и посыпьте пармезаном.</li></ol><p><em>Сбрызните оливковым маслом и посыпьте пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('051aac12-7a3a-5089-a577-9ea8449b1745', '72455b55-0428-5614-9940-9571ee4ae351', 'en', 'Ribollita (Tuscan white bean, kale and bread soup)', 'A thick Tuscan soup of white beans, tomatoes, vegetables and kale with toasted day-old bread soaked into it, flavoured with a Parmesan rind.', '<ol><li>Heat the oven to 400 °F (200 °C). Tear the bread into large pieces, toss with olive oil, spread on a tray and toast about 10 minutes until golden.</li><li>Heat 3 tbsp of oil in a pot and cook the onion, celery and carrots with salt until soft, then add the garlic for a minute.</li><li>Add the tomatoes, wine and broth, breaking up the tomatoes with a spoon. Puree about ½ cup of the tomato liquid with 1 cup of the beans in a food processor.</li><li>Add the Parmesan rind, thyme, bay leaf, oregano, chilli and a pinch of salt and simmer on medium about 20 minutes.</li><li>Add the whole and pureed beans and the kale and cook a few minutes. Stir in half the bread and simmer until the kale is cooked and the bread has softened and absorbed the liquid.</li><li>Remove the rind, bay leaf and thyme. Top with the remaining bread, a drizzle of oil and some Parmesan.</li></ol><p><em>Finish with olive oil and grated Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('7d5e7339-ba8b-5c0f-ac3e-7078a8ec5673', '3f5add9d-7d24-5f43-93c2-68e1f39d06c3', 'ru', 'Сырный суп с брокколи и чеддером', 'Густой сливочный суп с брокколи, морковью и сельдереем на молоке и курином бульоне с чеддером и пармезаном. Без сливок.', '<ol><li>Измельчите лук, морковь, сельдерей и чеснок в чопере или мини-комбайне.</li><li>В большой кастрюле растопите масло, добавьте овощи, соль и перец и тушите на слабом огне около 5 минут до мягкости.</li><li>Всыпьте муку и 2 минуты прогревайте. Постепенно вливайте бульон, помешивая, чтобы не было комков, затем молоко. Доведите до кипения на сильном огне.</li><li>Добавьте брокколи и пармезан, перемешайте и варите без крышки на слабом огне около 10 минут до готовности брокколи.</li><li>Пробейте часть супа погружным блендером на секунду-две для густоты (или перелейте 1–2 стакана в блендер и верните). Мягко вмешайте чеддер до расплавления и подавайте горячим.</li></ol><p><em>Посыпьте дополнительным тёртым чеддером и подавайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('b18c05e1-5a75-5e42-b773-80a9e3f77f12', '3f5add9d-7d24-5f43-93c2-68e1f39d06c3', 'en', 'Broccoli cheddar soup', 'Creamy soup of broccoli, carrot and celery in milk and chicken broth with melted cheddar and parmesan, made without cream.', '<ol><li>Chop the onion, carrot, celery and garlic in a chopper or mini food processor.</li><li>Melt the butter in a large pot, add the vegetables, salt and pepper and sauté on low about 5 minutes until soft.</li><li>Stir in the flour and cook 2 minutes, then gradually whisk in the broth until smooth and add the milk. Bring to a boil over high heat.</li><li>Add the broccoli and parmesan, stir and cook uncovered on low about 10 minutes until the broccoli is tender.</li><li>Blend part of the soup with an immersion blender for a second or two (or blend 1–2 cups separately and return) to thicken it. Gently stir in the cheddar until melted and serve hot.</li></ol><p><em>Garnish with extra shredded cheddar and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('abb4bd64-3a04-576b-8176-7f1bfba6e19e', '436979dc-f453-58b2-b3cf-dfb7397471ed', 'ru', 'Греческий суп авголемоно с курицей и рисом', 'Шелковистый куриный суп с рисом и укропом, загущённый лимонно-яичной смесью. Лёгкий, но сытный.', '<ol><li>Отделите укроп от стеблей; ½ стакана листьев отложите для подачи.</li><li>В кастрюле соедините стебли укропа, куриные бёдра, рис и бульон, доведите до кипения на сильном огне.</li><li>Убавьте огонь, накройте и варите 25 минут до мягкости курицы. Выньте курицу и стебли ложкой с отверстиями, стебли выбросьте, курицу разберите вилками.</li><li>Доведите бульон до активного кипения. В жаропрочной миске энергично взбейте яйца до пены, добавьте лимонный сок и тонкой струйкой влейте около стакана горячего бульона, взбивая.</li><li>Влейте лимонно-яичную смесь в кастрюлю, сразу снимите с огня и добавьте курицу. Посолите, поперчите, при желании добавьте лимонный сок. Подавайте с укропом и оливковым маслом.</li></ol><p><em>Посыпьте свежим укропом и чёрным перцем и сбрызните оливковым маслом.</em></p>', CURRENT_TIMESTAMP),
  ('bfc080d7-1346-5eb5-9110-dfd3d0a0beb2', '436979dc-f453-58b2-b3cf-dfb7397471ed', 'en', 'Avgolemono chicken and rice soup', 'Silky Greek soup with chicken, rice and dill, thickened with a lemon-egg mixture. Light yet filling.', '<ol><li>Pull the dill fronds from the stems and reserve ½ cup fronds for garnish.</li><li>In a pot combine the dill stems, chicken thighs, rice and broth and bring to a boil over high heat.</li><li>Lower to medium-low, cover and cook 25 minutes until the chicken is tender. Remove the chicken and stems, discard the stems and shred the chicken with two forks.</li><li>Bring the broth to an active simmer. In a heatproof bowl whisk the eggs until frothy, add the lemon juice and gradually whisk in about a cup of the hot broth.</li><li>Pour the lemon-egg mixture into the pot, immediately remove from the heat and stir in the chicken. Season, add more lemon juice if needed and serve with dill and olive oil.</li></ol><p><em>Garnish with fresh dill, black pepper and a drizzle of olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('4ea7746b-9380-576d-aaff-5cc3c517e85a', 'abccbaed-1de1-5738-8f14-e5f86c472ec6', 'ru', 'Лёгкое картофельное пюре с чесноком', 'Нежное пюре с запечённым в кипятке чесноком на небольшом количестве молока, сметаны и бульона. Намного легче классического.', '<ol><li>Выложите картофель и чеснок в кастрюлю, посолите, залейте водой и доведите до кипения.</li><li>Накройте крышкой, убавьте огонь и варите около 20 минут до мягкости картофеля.</li><li>Слейте воду, верните картофель с чесноком в кастрюлю на слабый огонь, добавьте сметану, бульон, молоко и масло и разомните толкушкой до однородности. Если пюре жидкое, прогрейте несколько минут.</li><li>Посолите и поперчите по вкусу и посыпьте зеленью.</li></ol><p><em>Посыпьте петрушкой или шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('106ccc85-0fbb-5d5d-84fe-73871c7c3449', 'abccbaed-1de1-5738-8f14-e5f86c472ec6', 'en', 'Light garlic mashed potatoes', 'Creamy mashed potatoes with boiled garlic, a little milk, light sour cream and broth, much lighter than traditional mash.', '<ol><li>Put the potatoes and garlic in a large pot with salt and enough water to cover and bring to a boil.</li><li>Cover, reduce the heat and simmer about 20 minutes until the potatoes are tender.</li><li>Drain and return the potatoes and garlic to the pot over low heat. Add the sour cream, broth, milk and butter and mash until smooth; if watery, cook a few minutes to thicken.</li><li>Season with salt and pepper and garnish with herbs.</li></ol><p><em>Garnish with parsley or chives.</em></p>', CURRENT_TIMESTAMP),
  ('d8c0cd59-ab6e-550e-a185-7008813fdb8d', '6c81c697-b2a5-5deb-bf3a-78bcfc8c734d', 'ru', 'Картофельный суп-пюре с луком-пореем', 'Нежный суп-пюре из картофеля и лука-порея на курином бульоне с молоком вместо сливок. Готовится за 30 минут.', '<ol><li>Тщательно вымойте лук-порей, разрезав его и разобрав на кольца, чтобы удалить весь песок, затем крупно нарежьте.</li><li>В кастрюле на слабом огне растопите масло, добавьте муку и хорошо перемешайте деревянной ложкой.</li><li>Влейте бульон, добавьте порей, лук и картофель и доведите до кипения. Накройте и варите на слабом огне 20–25 минут до мягкости картофеля.</li><li>Пюрируйте суп погружным блендером до гладкости, влейте молоко, посолите и поперчите по вкусу. Подавайте сразу.</li></ol><p><em>Посыпьте свежим шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('3e133dc2-398f-530b-8e31-46c1f8f15ad5', '6c81c697-b2a5-5deb-bf3a-78bcfc8c734d', 'en', 'Potato leek soup', 'Rich, creamy purée of potatoes and leeks in chicken broth finished with milk instead of cream, ready in 30 minutes.', '<ol><li>Wash the leeks carefully, separating the rings to remove all grit, then chop coarsely.</li><li>In a pot on low heat melt the butter, add the flour and mix well with a wooden spoon.</li><li>Add the broth, leeks, onion and potatoes and bring to a boil. Cover and simmer on low 20–25 minutes until the potatoes are soft.</li><li>Purée with an immersion blender until smooth, stir in the milk and season to taste. Serve immediately.</li></ol><p><em>Garnish with fresh chives.</em></p>', CURRENT_TIMESTAMP),
  ('a52aac9c-b09a-596a-91c5-6f65de5d67ab', '2c3b7954-191a-57bc-bb40-d7f3de7507f2', 'ru', 'Куриный строганов из фарша с грибами в сметанном соусе', 'Куриный фарш с шампиньонами, луком и томатной пастой в сметанном соусе с паприкой. Подаётся с лапшой, пастой или овощной лапшой.', '<ol><li>В блендере взбейте до гладкости воду, сметану, муку, куриный бульонный концентрат и паприку.</li><li>Разогрейте глубокую антипригарную сковороду на сильном огне, слегка смажьте маслом и обжарьте фарш с солью около 5 минут, разбивая на мелкие кусочки.</li><li>Убавьте огонь до среднего, добавьте лук и томатную пасту и готовьте 4–5 минут до мягкости. Положите грибы, тимьян и вустерский соус.</li><li>Влейте приготовленный соус, доведите до кипения, накройте и тушите на слабом огне 35–45 минут. Выньте тимьян, посыпьте петрушкой и подавайте на лапше.</li></ol><p><em>Посыпьте петрушкой и подайте с яичной лапшой или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('b20618c5-39f1-511b-87f7-ad78003a1ae8', '2c3b7954-191a-57bc-bb40-d7f3de7507f2', 'en', 'Ground chicken stroganoff with mushrooms', 'Ground chicken with cremini mushrooms, onion and tomato paste in a creamy paprika sour cream sauce, served over noodles or pasta.', '<ol><li>In a blender blend the water, sour cream, flour, bouillon and paprika until smooth.</li><li>Heat a large deep nonstick skillet on high, spray with oil and cook the chicken with the salt about 5 minutes, breaking it into small pieces.</li><li>Reduce to medium, add the onion and tomato paste and cook 4–5 minutes until soft, then add the mushrooms, thyme and Worcestershire.</li><li>Pour in the sauce, bring to a boil, cover and cook on low 35–45 minutes. Discard the thyme, garnish with parsley and serve over noodles.</li></ol><p><em>Garnish with parsley and serve over egg noodles or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('8036fa57-3579-5932-b7dd-c4d6f8bc183c', 'ef5b2cc6-cb7c-583f-9c80-50e53f24241c', 'ru', 'Брокколи, запечённая с чесноком', 'Брокколи с раздавленным чесноком и оливковым маслом, запечённая в духовке до золотистых краёв. Простой гарнир из 5 ингредиентов.', '<ol><li>Разогрейте духовку до 220 °C и застелите противень пергаментом.</li><li>На противне перемешайте соцветия брокколи (с частью ножки) с чесноком, оливковым маслом, солью и перцем.</li><li>Разложите в один слой и запекайте в середине духовки 15–20 минут, пока брокколи не станет золотистой, а ножки — хрустяще-мягкими.</li></ol><p><em>Хорош к курице, свиным отбивным, стейкам. Сверху можно посыпать пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('64348b26-d490-5b52-94d1-e5b7123b22e8', 'ef5b2cc6-cb7c-583f-9c80-50e53f24241c', 'en', 'Roasted broccoli with smashed garlic', 'Broccoli florets tossed with smashed garlic and olive oil and roasted until golden. A simple 5-ingredient side dish.', '<ol><li>Preheat the oven to 425 °F (220 °C) and line a baking sheet with parchment.</li><li>On the baking sheet toss the broccoli florets (with part of the stem) with the garlic, olive oil, salt and pepper.</li><li>Spread in a single layer and roast in the center of the oven 15–20 minutes until golden and the stems are crisp-tender.</li></ol><p><em>Serve with chicken, pork chops or steak; shaved parmesan on top is optional.</em></p>', CURRENT_TIMESTAMP),
  ('431cce96-fadc-50c9-9a9a-125f81a083ce', '776d0cfd-f536-5f59-84f3-65ddea17e268', 'ru', 'Холодный огуречный суп с йогуртом, укропом и мятой', 'Освежающий холодный суп-пюре из огурцов с греческим йогуртом, шалотом, укропом, мятой и лимонным соком. Подаётся с хрустящими огурцами и грецкими орехами.', '<ol><li>От одного огурца отрежьте кусок 10 см, разрежьте вдоль, удалите семена и мелко нарежьте (с кожурой, для подачи).</li><li>Остальные огурцы очистите, удалите семена и крупно нарежьте.</li><li>В блендере соедините очищенные огурцы, йогурт, шалот, укроп, мяту, лимонный сок, 3 ч. л. масла, соль и перец и взбейте до абсолютной гладкости. Если огурцы слишком сухие, добавьте воды по 1 ч. л.</li><li>Уберите суп в холодильник на 4 часа (не дольше суток, иначе станет горчить).</li><li>Перед подачей размешайте суп. Смешайте оставленный огурец с орехами, оставшимся маслом и щепоткой соли. Разлейте суп по тарелкам, сверху выложите смесь и укроп.</li></ol><p><em>Выдержите в холодильнике 4 часа, подавайте с укропом.</em></p>', CURRENT_TIMESTAMP),
  ('dd4e2037-2a83-5e30-8cde-0923ffb87548', '776d0cfd-f536-5f59-84f3-65ddea17e268', 'en', 'Cold cucumber yogurt soup with dill and mint', 'Refreshing no-cook cold soup of blended cucumbers, Greek yogurt, shallot, dill, mint and lemon, topped with crunchy diced cucumber and toasted walnuts.', '<ol><li>Cut a 4-inch piece off one cucumber, halve and seed it and finely chop (keep the skin) for garnish.</li><li>Peel the remaining cucumbers, seed and roughly chop them.</li><li>In a blender combine the peeled cucumbers, yogurt, shallot, dill, mint, lemon juice, 3 tsp oil, salt and pepper and blend completely smooth; add water 1 tsp at a time only if needed.</li><li>Refrigerate covered for 4 hours (no longer than 24 or it turns bitter).</li><li>Before serving stir the soup. Toss the reserved cucumber with the walnuts, remaining oil and a pinch of salt. Ladle the soup into bowls and top with the mixture and dill.</li></ol><p><em>Chill 4 hours and serve garnished with fresh dill.</em></p>', CURRENT_TIMESTAMP),
  ('11301467-6353-56a8-b824-1de9bdaca68e', '42c113c5-0533-5595-9355-fe4e379413b6', 'ru', 'Стручковая фасоль с чесноком на оливковом масле', 'Быстрый гарнир: стручковая фасоль, приготовленная на пару до хрустящей мягкости и обжаренная с золотистым чесноком.', '<ol><li>Вскипятите в кастрюле воду на 2,5 см. Установите над ней паровую корзину с фасолью, плотно накройте и готовьте на пару 4–5 минут, чтобы фасоль осталась хрустящей. Слейте воду.</li><li>В сковороде разогрейте масло, обжарьте нарезанный чеснок до золотистого цвета.</li><li>Добавьте фасоль, соль и перец, хорошо перемешайте и подавайте.</li></ol><p><em>Хорош к рыбе, курице и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('2657a35a-3b75-5e1c-98fc-991867a11887', '42c113c5-0533-5595-9355-fe4e379413b6', 'en', 'Green beans with garlic and olive oil', 'A quick side of steamed green beans cooked tender-crisp and tossed with golden garlic in olive oil.', '<ol><li>Bring an inch of water to a boil in a pot, set a steamer basket of beans over it, cover tightly and steam 4–5 minutes until tender-crisp. Drain.</li><li>Heat the oil in a sauté pan and cook the sliced garlic until golden.</li><li>Add the beans, salt and pepper, toss well and serve.</li></ol><p><em>Serve with fish, chicken or meat.</em></p>', CURRENT_TIMESTAMP),
  ('0ce9839f-dcc8-500f-9e8b-944ae8ef2904', '5c25b102-5129-5a6e-a74e-ccf1eb6a5295', 'ru', 'Суп с колбасками, картофелем и белой фасолью', 'Сытный суп без молочного: кремовую текстуру даёт пюре из белой фасоли. С итальянскими колбасками из индейки или курицы, картофелем и шпинатом.', '<ol><li>Разогрейте кастрюлю на среднем-сильном огне, слегка смажьте маслом, обжарьте разломанные на кусочки колбаски около 7 минут до румяности и переложите в миску.</li><li>Добавьте 1 ч. л. масла, лук и чеснок и готовьте около 5 минут до мягкости. Добавьте итальянские травы, затем фасоль и бульон.</li><li>Пробейте суп погружным блендером до кремовой консистенции.</li><li>Верните колбаски, добавьте картофель, соль и перец и доведите до кипения. Убавьте огонь, накройте и варите около 30 минут до мягкости картофеля.</li><li>Положите шпинат, проварите минуту и подавайте.</li></ol><p><em>Подавайте горячим с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('7c9b0956-c06f-52dc-84e7-2e1d59c1af9b', '5c25b102-5129-5a6e-a74e-ccf1eb6a5295', 'en', 'Creamy sausage, potato and white bean soup', 'Hearty dairy-free soup made creamy by puréed cannellini beans, with Italian turkey or chicken sausage, potatoes and spinach.', '<ol><li>Heat a large pot over medium-high, spray with oil and cook the crumbled sausage about 7 minutes until browned; transfer to a bowl.</li><li>Add 1 tsp oil, the onion and garlic and cook about 5 minutes until soft, stir in the Italian seasoning, then add the beans and broth.</li><li>Purée the soup with an immersion blender until creamy.</li><li>Return the sausage, add the potatoes, salt and pepper and bring to a boil. Reduce, cover and simmer about 30 minutes until the potatoes are tender.</li><li>Add the spinach, simmer 1 minute and serve.</li></ol><p><em>Serve hot with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('31eaceda-f877-5f12-bfb0-713becc6ba66', '97a55fa7-0dba-5e0a-9c48-0cd1d147a8ba', 'ru', 'Вегетарианский чили из чёрной фасоли с пряным йогуртом', 'Быстрый чили с чёрной фасолью, кукурузой, перцем, томатами и специями. Подаётся с йогуртом, приправленным теми же специями.', '<ol><li>Смешайте специи в небольшой миске. 1½ ч. л. смеси отложите и добавьте в йогурт.</li><li>Одну банку фасоли вместе с жидкостью взбейте в блендере с ½ стакана воды. Вторую банку слейте.</li><li>В большой кастрюле разогрейте масло на среднем огне и 3–4 минуты обжарьте лук, перец и халапеньо.</li><li>Добавьте помидоры, кукурузу, фасоль, пюре из фасоли, томатный соус, бульон и оставшиеся специи. Доведите до кипения, накройте и варите на слабом огне около 15 минут до загустения.</li><li>Подавайте с пряным йогуртом и любимыми добавками.</li></ol><p><em>Добавьте тёртый сыр, красный лук, кинзу и авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('5bf2a113-d638-5318-982e-dc14c67bbde1', '97a55fa7-0dba-5e0a-9c48-0cd1d147a8ba', 'en', 'Easy black bean vegetarian chili with spiced yogurt', 'Quick chili with black beans, corn, peppers, tomatoes and warm spices, topped with yogurt seasoned with the same spice mix.', '<ol><li>Mix the spices in a small bowl. Set aside 1½ tsp and stir into the yogurt.</li><li>Blend one can of beans with its liquid and ½ cup water in a blender; drain the second can.</li><li>Heat the oil in a large pot over medium and cook the onion, bell pepper and jalapeño 3–4 minutes.</li><li>Add the tomatoes, corn, beans, bean purée, tomato sauce, broth and remaining spices. Bring to a boil, cover and simmer about 15 minutes until thickened.</li><li>Serve topped with the spiced yogurt and your favorite toppings.</li></ol><p><em>Top with shredded cheddar, red onion, cilantro and avocado.</em></p>', CURRENT_TIMESTAMP),
  ('2beabab8-2889-528d-afcf-00332b12ceff', '02fa6af2-ec95-57bf-bf20-712bdb0ad8ce', 'ru', 'Лосось, запечённый под корочкой из пармезана и трав', 'Нежное филе лосося, запечённое с обмазкой из лёгкого майонеза, пармезана, чеснока и свежих трав. Подходит для гостей и для будней.', '<ol><li>Разогрейте духовку до 220 °C, застелите противень пергаментом или фольгой.</li><li>В небольшой миске смешайте майонез, пармезан, чеснок и рубленые травы.</li><li>Выложите лосось кожей вниз на противень, накройте вторым листом пергамента или фольги и запекайте 8 минут.</li><li>Снимите верхний лист, распределите по рыбе смесь с пармезаном и верните в духовку без накрытия.</li><li>Запекайте 15–18 минут (при толщине 4 см), пока верх не зарумянится, а рыба не будет легко расслаиваться (57 °C внутри).</li></ol><p><em>Подавайте с картофелем или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('3409e62e-50ca-52eb-bced-8d9bfee521a5', '02fa6af2-ec95-57bf-bf20-712bdb0ad8ce', 'en', 'Parmesan herb crusted baked salmon', 'Tender salmon fillet baked with a light mayo, parmesan, garlic and fresh herb topping. Great for company or busy weeknights.', '<ol><li>Preheat the oven to 425 °F (220 °C) and line a rimmed baking sheet with parchment or foil.</li><li>In a small bowl combine the mayo, parmesan, garlic and chopped herbs.</li><li>Place the salmon skin-side down on the sheet, cover with another piece of parchment or foil and bake 8 minutes.</li><li>Remove the top sheet, spread the parmesan herb mixture over the fish and return to the oven uncovered.</li><li>Bake about 15–18 minutes for 1½-inch-thick fish until the top is browned and the salmon flakes easily (135 °F / 57 °C).</li></ol><p><em>Serve with potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('4c8ec04d-17f8-5b93-9217-769bc5800d9a', 'fd6a705d-bb37-51b4-8838-b610942267f5', 'ru', 'Запечённые говяжьи фрикадельки в медово-чесночной глазури', 'Сочные маленькие фрикадельки из говяжьего фарша, запечённые и доведённые в сладко-солёном соусе из мёда, кетчупа, соевого соуса и чеснока.', '<ol><li>Разогрейте духовку до 200 °C, застелите два противня пергаментом. Замочите панировочные сухари в молоке, пока оно не впитается.</li><li>Смешайте фарш с размоченными сухарями, луком, яйцами, солью, перцем и травами. Скатайте шарики по 1 ст. л. и выложите на противни.</li><li>Запекайте 12–14 минут, не пересушивая, иначе они будут жёсткими.</li><li>Для соуса растопите масло, обжарьте чеснок 30 секунд, добавьте мёд, кетчуп и соевый соус и варите на слабом огне около 5 минут.</li><li>Положите фрикадельки в соус и томите 7–10 минут до готовности.</li></ol><p><em>Подайте с рисом, макаронами или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('d6cbf30c-7014-5763-a099-caba86ec76f1', 'fd6a705d-bb37-51b4-8838-b610942267f5', 'en', 'Baked honey garlic glazed beef meatballs', 'Juicy little beef meatballs baked and finished in a sweet and savoury sauce of honey, ketchup, soy sauce and garlic.', '<ol><li>Heat the oven to 400 °F (200 °C) and line two baking sheets with parchment. Soak the breadcrumbs in the milk until fully absorbed.</li><li>Combine the beef with the soaked crumbs, onion, eggs, salt, pepper and herbs. Shape into 1-tablespoon meatballs and set on the sheets.</li><li>Bake 12–14 minutes without overcooking, or they turn tough.</li><li>For the sauce melt the butter, cook the garlic 30 seconds, add the honey, ketchup and soy sauce and simmer about 5 minutes.</li><li>Add the meatballs to the sauce and simmer 7–10 minutes until cooked through.</li></ol><p><em>Serve with rice, pasta or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('5efe42cb-7cec-53ea-a1a8-5abf13ea5d2f', '23d40832-a798-5b9b-a4c8-366993233dd5', 'ru', 'Курица с брокколи и болгарским перцем в медово-соевом соусе', 'Золотистые кусочки куриного бедра в крахмале и соевом соусе с брокколи, сладким перцем и луком в блестящем медово-соевом соусе.', '<ol><li>Нарежьте курицу кусочками 3–4 см, смешайте с 2 ст. л. масла, 2 ст. л. соевого соуса и 2 ст. л. крахмала и отставьте. Нарежьте овощи, взбейте ингредиенты соуса.</li><li>Разогрейте оставшееся масло в антипригарной сковороде на сильном огне. Обжарьте курицу двумя порциями до золотистого цвета, не переворачивая раньше времени. Переложите на бумажное полотенце.</li><li>В той же сковороде 3 минуты обжарьте перец и лук на средне-сильном огне до золотистых краёв, добавьте брокколи ещё на 2–3 минуты.</li><li>Сдвиньте овощи, в центр добавьте каплю масла, чеснок и хлопья чили на 30 секунд. Влейте соус, доведите до кипения, убавьте огонь, накройте и готовьте 3–5 минут до нужной мягкости брокколи. Верните курицу и прогрейте.</li></ol><p><em>Подайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('4010a771-40d9-5d46-b0e1-242635b259b9', '23d40832-a798-5b9b-a4c8-366993233dd5', 'en', 'Chicken and broccoli stir-fry with honey soy sauce', 'Golden pieces of marinated chicken thigh with broccoli, sweet pepper and onion in a glossy honey and soy sauce.', '<ol><li>Cut the chicken into 1–1½ inch pieces and mix with 2 tbsp of the oil, 2 tbsp soy sauce and 2 tbsp cornstarch. Set aside. Cut the vegetables and whisk the sauce ingredients.</li><li>Heat the remaining oil in a nonstick skillet on high. Fry the chicken in two batches until golden before turning. Drain on paper towels.</li><li>In the same skillet cook the pepper and onion 3 minutes on medium-high until golden at the edges, then add the broccoli for 2–3 minutes.</li><li>Push the vegetables aside, add a splash of oil, the garlic and chilli flakes for 30 seconds. Pour in the sauce, bring to a boil, reduce, cover and cook 3–5 minutes until the broccoli is as tender as you like. Return the chicken and heat through.</li></ol><p><em>Serve over steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('14bbbbd9-0118-5579-bca6-8a96190a4d09', '3a2136e2-68e7-5639-9264-5393e42d7f4d', 'ru', 'Паста с курицей, морковью и горошком в сливочном соусе', 'Паста в шелковистом соусе на бульоне со сливками, с кусочками запечённой курицы, морковью, луком, сельдереем и зелёным горошком. Вкус как у куриного пирога.', '<ol><li>Разогрейте духовку до 200 °C, посолите и поперчите куриные бёдра и запекайте 30–45 минут до готовности. Снимите кожу, разберите мясо на кусочки, кости выбросьте.</li><li>Отварите пасту в подсоленной воде до нужной мягкости, оставив стакан отвара.</li><li>В большой сковороде на масле 3 минуты обжарьте лук, добавьте морковь, сельдерей и чеснок, посолите и готовьте 5–7 минут до готовности моркови.</li><li>Всыпьте муку и мешайте минуту. Понемногу влейте бульон, постоянно взбивая, доведите до кипения и варите около 5 минут до загустения.</li><li>Влейте сливки, при необходимости досолите, выключите огонь и вмешайте курицу. Добавьте соус, слегка разморозенный горошек и петрушку к пасте, перемешайте, при желании разбавьте отваром.</li></ol><p><em>Посыпьте петрушкой и подайте горячей.</em></p>', CURRENT_TIMESTAMP),
  ('75797608-aecc-5a7c-9e7a-ec7361461cae', '3a2136e2-68e7-5639-9264-5393e42d7f4d', 'en', 'Chicken pot pie pasta with carrots and peas', 'Pasta in a silky broth-and-cream sauce with roasted shredded chicken, carrots, onion, celery and peas, tasting like chicken pot pie.', '<ol><li>Heat the oven to 400 °F (200 °C), season the chicken thighs and roast 30–45 minutes until cooked through. Discard the skin and bones and shred the meat.</li><li>Cook the pasta in salted water to your liking, saving a cup of the starchy water.</li><li>In a large skillet cook the onion in the fat for 3 minutes, add the carrots, celery and garlic, season and cook 5–7 minutes until the carrots are done.</li><li>Sprinkle in the flour and stir for a minute. Slowly pour in the broth, whisking constantly, bring to a boil and simmer about 5 minutes until thickened.</li><li>Pour in the cream, season, turn off the heat and stir in the chicken. Toss the sauce, thawed peas and parsley with the pasta, loosening with pasta water if needed.</li></ol><p><em>Sprinkle with parsley and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('a276f0c0-0529-5fc7-a921-c9306436c752', '320dacda-9159-5d6d-8651-eaf72b50ef42', 'ru', 'Картофель с колбасками, сладким перцем и луком в скороварке', 'Тушёная картошка с колбасками, луком, перцем и чесноком, готовая в мультиварке-скороварке за 35 минут. Картофель пропитывается ароматным бульоном.', '<ol><li>Очистите картофель и нарежьте кусками 4–5 см, колбасу — небольшими кусочками. Нарежьте лук и перец, измельчите чеснок. Вскипятите воду или бульон. Приправьте картофель солью, перцем и сухими травами.</li><li>Включите режим жарки, разогрейте масло, обжарьте колбасу и лук с солью и перцем до мягкости и лёгкой золотистости. Добавьте чеснок на минуту.</li><li>Добавьте перец, лавровый лист и паприку, сверху выложите картофель (не перемешивая) и влейте кипяток или бульон так, чтобы он почти покрывал картофель.</li><li>Готовьте под высоким давлением 5–7 минут, оставьте на 5 минут и осторожно сбросьте давление вручную. Посыпьте зеленью и подавайте. Без скороварки тушите под крышкой на плите около 30 минут.</li></ol><p><em>Посыпьте свежей зеленью: петрушкой, укропом или зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('463e3c0b-b389-5cb2-b56a-4baabfaeb0a5', '320dacda-9159-5d6d-8651-eaf72b50ef42', 'en', 'Pressure cooker potatoes with sausage, peppers and onion', 'Braised potatoes with sausage, onion, bell pepper and garlic made in a pressure cooker in 35 minutes, the potatoes soaking up the savoury broth.', '<ol><li>Peel the potatoes into 1½–2 inch chunks, cut the sausage into bite-sized pieces, chop the onion and pepper, mince the garlic and boil the water or broth. Season the potatoes with salt, pepper and dry herbs.</li><li>Switch on sauté, heat the oil and cook the sausage and onion with salt and pepper until the onion is soft and slightly golden. Add the garlic for a minute.</li><li>Add the pepper, bay leaves and paprika, layer the potatoes on top without stirring and pour in boiling water or broth to almost cover them.</li><li>Pressure cook on high 5–7 minutes, rest 5 minutes and carefully release the pressure. Garnish with herbs. Without a pressure cooker, simmer covered on the stove about 30 minutes.</li></ol><p><em>Garnish with fresh herbs such as parsley, dill or green onions.</em></p>', CURRENT_TIMESTAMP),
  ('05f4386e-3eca-55fc-82db-4169853bc5c5', 'e1c1efae-3d5d-5ae3-9094-a1a15e492bbe', 'ru', 'Молодой картофель с зелёным горошком, укропом и сливочным маслом', 'Отварной молодой картофель со сливочным маслом, поджаренным луком, зелёным горошком, укропом и зелёным луком. Простой гарнир почти к любому блюду.', '<ol><li>Очистите картофель (можно оставить в кожуре), залейте водой, посолите, доведите до кипения и варите около 15 минут до мягкости. Слейте воду.</li><li>Тем временем в большой сковороде растопите масло и 5 минут обжарьте лук с солью и перцем до прозрачности.</li><li>Добавьте замороженный горошек на 1–2 минуты, затем укроп, зелёный лук и картофель. Аккуратно перемешайте и сразу подавайте.</li></ol><p><em>Подайте сразу, к мясу, рыбе или котлетам.</em></p>', CURRENT_TIMESTAMP),
  ('f8e81bcc-91c9-5488-baa8-a4a95a9c9bb6', 'e1c1efae-3d5d-5ae3-9094-a1a15e492bbe', 'en', 'New potatoes with peas, dill and butter', 'Boiled baby potatoes tossed with butter-sautéed onion, green peas, dill and spring onions. A simple side for almost anything.', '<ol><li>Peel the potatoes (or leave the skins on), cover with salted water, bring to a boil and cook about 15 minutes until tender in the centre. Drain.</li><li>Meanwhile melt the butter in a large skillet and cook the onion with salt and pepper about 5 minutes until translucent.</li><li>Add the frozen peas for 1–2 minutes, then the dill, green onions and potatoes. Mix gently and serve at once.</li></ol><p><em>Serve immediately with meat, fish or cutlets.</em></p>', CURRENT_TIMESTAMP),
  ('837fda79-0246-5f4a-a68f-165a01e8b98e', '994a75a3-d84a-55f3-9ffb-c48515d78b34', 'ru', 'Салат из помидоров, огурцов, редиса и зелени со сметаной', 'Свежий хрустящий весенний салат из помидоров, огурцов, редиса, листового салата и зелени, заправленный сметаной.', '<ol><li>Удалите из помидоров семена и нарежьте кубиками (или разрежьте пополам черри).</li><li>Нарежьте огурцы кружками, редис тонкими ломтиками, салат тонко нашинкуйте. Добавьте мелко нарубленную зелень.</li><li>Добавьте сметану или греческий йогурт, соль и перец, аккуратно перемешайте и сразу подавайте.</li></ol><p><em>Подавайте сразу после заправки.</em></p>', CURRENT_TIMESTAMP),
  ('2633a8bf-0cc6-53ff-9f35-fc25ee691710', '994a75a3-d84a-55f3-9ffb-c48515d78b34', 'en', 'Spring garden salad with sour cream', 'A fresh, crunchy spring salad of tomatoes, cucumbers, radishes, lettuce and herbs dressed with sour cream.', '<ol><li>Seed the tomatoes and chop into cubes, or halve grape tomatoes.</li><li>Slice the cucumbers, thinly slice the radishes and finely shred the lettuce. Add the minced herbs.</li><li>Add the sour cream or Greek yogurt, salt and pepper, mix gently and serve immediately.</li></ol><p><em>Serve right after dressing.</em></p>', CURRENT_TIMESTAMP),
  ('e40cbd63-8556-5e8e-b192-6c77d8443b70', '166fdf3b-f2d3-5263-b91d-4689838baf1f', 'ru', 'Банановые оладьи на яйцах без муки и сахара', 'Нежные оладьи из трёх ингредиентов: банана, яиц и щепотки разрыхлителя. Без муки и сахара, нравятся детям.', '<ol><li>Разомните бананы вилкой, толкушкой или миксером.</li><li>Добавьте яйца и разрыхлитель и перемешайте до однородности.</li><li>Смажьте сковороду маслом на среднем огне. Выкладывайте ложкой небольшие оладьи диаметром около 7 см и жарьте до золотистого цвета с двух сторон (получится около 18 штук).</li></ol><p><em>Подайте сами по себе или с кленовым сиропом и ягодами.</em></p>', CURRENT_TIMESTAMP),
  ('3d252048-1386-5464-b028-66611016dd5f', '166fdf3b-f2d3-5263-b91d-4689838baf1f', 'en', 'Flourless banana egg pancakes', 'Tender three-ingredient pancakes of banana, eggs and a pinch of baking powder, with no flour or added sugar. A hit with kids.', '<ol><li>Mash the bananas with a fork, masher or mixer.</li><li>Add the eggs and baking powder and mix until evenly combined.</li><li>Grease a skillet with a little butter or oil over medium heat. Spoon out small 3-inch pancakes and cook until golden on both sides (about 18).</li></ol><p><em>Serve plain or with maple syrup and berries.</em></p>', CURRENT_TIMESTAMP),
  ('d186c403-1772-555c-b9d4-e5837082c8e8', 'dbe483a9-4430-577a-9ef5-50e98a9619ea', 'ru', 'Яйца, запечённые в формочках с ветчиной, сыром и овощами', 'Яйца, запечённые в порционных формочках с ветчиной, тёртым сыром, помидорами и печёным красным перцем. Готовятся за 15 минут.', '<ol><li>Разогрейте духовку до 190 °C. Растопите масло и смажьте две формочки.</li><li>В каждую формочку разбейте по 2 яйца. Посыпьте сыром, зеленью и ветчиной, добавьте помидоры и красный перец, посолите и поперчите.</li><li>Запекайте 5–10 минут: меньше для жидкого желтка, больше для плотного.</li></ol><p><em>Подайте с тостами или свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('69181c09-5efa-537d-bfd5-f5e5d51f8b94', 'dbe483a9-4430-577a-9ef5-50e98a9619ea', 'en', 'Ham and cheese baked eggs in ramekins', 'Eggs baked in individual dishes with ham, grated cheese, tomatoes and roasted red pepper, ready in 15 minutes.', '<ol><li>Preheat the oven to 375 °F (190 °C). Melt the butter and grease two baking dishes.</li><li>Crack 2 eggs into each dish. Sprinkle with cheese, herbs and ham, add the tomatoes and red pepper and season with salt and pepper.</li><li>Bake 5–10 minutes: less for runny yolks, more for firm ones.</li></ol><p><em>Serve with toast or fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('527fd43c-2e72-58c6-b4fd-dd5bd2d1c56b', 'd3e33b85-b261-5e00-bb59-527111589250', 'ru', 'Пышные оладьи из рикотты', 'Нежные воздушные оладьи из рикотты, молока, муки и взбитых белков. Праздничный завтрак, который легко приготовить.', '<ol><li>Отделите белки от желтков. Взбейте белки миксером на средней, затем на высокой скорости до устойчивых пиков.</li><li>В другой миске смешайте желтки, рикотту, сахар, молоко и ваниль до гладкости. Добавьте муку, разрыхлитель и соль и перемешайте только до исчезновения муки.</li><li>Осторожно вмешайте белки, сохраняя воздушность теста.</li><li>Разогрейте сковороду с маслом. Выкладывайте тесто четвертью стакана и жарьте на среднем огне до золотистого цвета с обеих сторон. Подавайте сразу.</li></ol><p><em>Подайте сразу с ягодами, сметаной или мёдом.</em></p>', CURRENT_TIMESTAMP),
  ('14964d77-8d32-5f8d-9108-1604c675910a', 'd3e33b85-b261-5e00-bb59-527111589250', 'en', 'Fluffy ricotta pancakes', 'Tender, light pancakes of ricotta, milk, flour and whipped egg whites. A special breakfast that is easy to make.', '<ol><li>Separate the eggs. Whip the whites on medium and then high speed until stiff peaks form.</li><li>In another bowl mix the yolks, ricotta, sugar, milk and vanilla until smooth. Add the flour, baking powder and salt and mix just until combined.</li><li>Gently fold in the egg whites to keep the batter light.</li><li>Heat a skillet with butter or oil. Pour ¼ cup of batter per pancake and cook on medium until golden on both sides. Serve right away.</li></ol><p><em>Serve right away with berries, sour cream or honey.</em></p>', CURRENT_TIMESTAMP),
  ('b6d50b6b-adcf-5c8f-80cd-8e6333be4d62', '99466af8-4d64-5129-a0eb-52549d1f05d5', 'ru', 'Креветки с кабачком, перцем и красным луком на противне', 'Сочные креветки, запечённые на одном противне с цветными овощами. Овощи нарезаны по-разному, чтобы приготовиться одновременно.', '<ol><li>Разогрейте духовку до 245 °C, поставьте в неё большой противень. Нарежьте кабачок брусочками толщиной 1,2 см, перец полосками 8 мм, лук кольцами 6 мм: так овощи приготовятся одновременно.</li><li>Смешайте овощи с 1 ст. л. масла, щепоткой соли и перца. В другой миске смешайте креветки с чесноком, зеленью, паприкой, 1,5 ст. л. масла, лимонным соком, солью и перцем.</li><li>Выложите овощи на горячий противень (они зашипят) и запекайте 10–15 минут, перевернув на полпути. Выложите в миску и накройте.</li><li>На тот же горячий противень выложите креветки, запекайте 3–5 минут, затем включите гриль на 2–3 минуты. Соедините с овощами, добавьте масла, лимонного сока и зелени.</li></ol><p><em>Сбрызните оливковым маслом и лимоном, посыпьте зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('b12dd257-7c14-5f21-a6d7-e28ef1ac9a25', '99466af8-4d64-5129-a0eb-52549d1f05d5', 'en', 'Sheet pan shrimp with zucchini, peppers and red onion', 'Juicy shrimp roasted on one sheet pan with colourful vegetables, cut to different sizes so they finish at the same time.', '<ol><li>Heat the oven to 475 °F (245 °C) with a large rimmed sheet inside. Cut the zucchini into ½ inch slices, the pepper into ⅓ inch strips and the onion into ¼ inch slices so they cook at the same time.</li><li>Toss the vegetables with 1 tbsp of oil, a little salt and pepper. In another bowl mix the shrimp with the garlic, herbs, paprika, 1½ tbsp oil, lemon juice, salt and pepper.</li><li>Spread the vegetables on the hot pan (they should sizzle) and roast 10–15 minutes, turning halfway. Move to a bowl and cover.</li><li>Put the shrimp on the same hot pan, roast 3–5 minutes, then broil 2–3 minutes. Combine with the vegetables and finish with oil, lemon and herbs.</li></ol><p><em>Finish with a splash of olive oil, lemon and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('ed589de7-c349-525d-99bc-26f269a51410', '2ce50bee-535b-553e-89e9-c32aa0128232', 'ru', 'Куриная грудка пиката в лимонно-каперсовом соусе', 'Тонкие куриные эскалопы в муке, обжаренные до золотистого цвета и политые лёгким соусом из белого вина, лимонного сока, каперсов и масла.', '<ol><li>Разрежьте грудки вдоль пополам на 6 эскалопов, посолите и поперчите с двух сторон.</li><li>Обваляйте эскалопы в муке, стряхнув излишки, и выложите в один слой на тарелку.</li><li>На сильном-среднем огне разогрейте в большой сковороде 2 ст. л. масла и 2 ст. л. сливочного. Обжарьте по 3 куска по 2–4 минуты с каждой стороны до 74 °C внутри. Переложите на блюдо, добавьте ещё ложку масла и ложку сливочного и обжарьте остальное.</li><li>В той же сковороде, не убавляя огня, влейте вино, лимонный сок, добавьте ложку масла и каперсы, кипятите минуту. Макните эскалопы в соус и верните на блюдо. Ещё 2 минуты уварите соус и полейте им курицу.</li><li>Украсьте кольцами лимона и петрушкой.</li></ol><p><em>Украсьте дольками лимона и петрушкой, подайте с пастой или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('84752c6a-23eb-5db1-8a3e-dc58fdfc9831', '2ce50bee-535b-553e-89e9-c32aa0128232', 'en', 'Chicken piccata with lemon caper sauce', 'Thin floured chicken cutlets pan-seared until golden and served in a light white wine, lemon, caper and butter sauce.', '<ol><li>Cut the chicken breasts in half lengthwise into 6 cutlets and season both sides with salt and pepper.</li><li>Dredge the cutlets in flour, shaking off the excess, and set in a single layer on a plate.</li><li>Over medium-high heat warm 2 tbsp oil and 2 tbsp butter in a large skillet. Cook 3 cutlets 2–4 minutes per side until 165 °F (74 °C) inside, transfer to a platter, add 1 tbsp oil and 1 tbsp butter and cook the rest.</li><li>In the same skillet add the wine, lemon juice, 1 tbsp butter and capers and simmer 1 minute, dip the cutlets in the sauce and return to the platter, then simmer the sauce 2 more minutes and drizzle over the chicken.</li><li>Garnish with lemon rings and parsley.</li></ol><p><em>Garnish with lemon slices and parsley and serve with pasta or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('00fcb306-4114-55c0-91ee-87af9898e35b', 'bbbdd2ee-d4a4-5c1b-b4d8-abdfd7636829', 'ru', 'Паста примавера с овощами в лимонно-масляном соусе', 'Пенне с болгарским перцем, кабачком, грибами и красным луком в лёгком соусе из сливочного масла, чеснока, лимонного сока и пармезана.', '<ol><li>Отварите пасту в подсоленной воде до состояния аль денте, слейте воду и накройте, чтобы не остыла.</li><li>Пока варится паста, разогрейте масло в глубокой сковороде на среднем-сильном огне и 6–8 минут обжаривайте перец, кабачок, грибы и красный лук, часто перемешивая, пока овощи не станут хрустяще-мягкими. Посолите и поперчите.</li><li>Убавьте огонь до среднего, добавьте сливочное масло и чеснок и готовьте около минуты до аромата.</li><li>Добавьте пасту, лимонный сок и пармезан, перемешайте и прогрейте. Досолите, посыпьте петрушкой и пармезаном и подавайте.</li></ol><p><em>Посыпьте петрушкой и тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('60468a0d-6028-54a6-8a81-be81f28e0cfd', 'bbbdd2ee-d4a4-5c1b-b4d8-abdfd7636829', 'en', 'Pasta primavera with lemon butter sauce', 'Penne with bell pepper, zucchini, mushrooms and red onion in a light butter, garlic, lemon and parmesan sauce.', '<ol><li>Cook the pasta in salted water until al dente, drain and cover to keep warm.</li><li>Meanwhile heat the oil in a large deep skillet over medium-high and sauté the bell pepper, zucchini, mushrooms and red onion 6–8 minutes, stirring often, until crisp-tender; season with salt and pepper.</li><li>Reduce to medium, add the butter and garlic and cook about 1 minute until fragrant.</li><li>Add the pasta, lemon juice and parmesan, toss and heat through. Adjust seasoning and garnish with parsley and more parmesan.</li></ol><p><em>Garnish with parsley and extra grated parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('33c3770e-22b6-5844-8c54-c0ed83e3458e', 'fa2426cd-1901-5c0b-8b07-0a3ce7b1133a', 'ru', 'Фаршированные ракушки с рикоттой и моцареллой в томатном соусе', 'Крупные ракушки-конкильони с начинкой из рикотты, пармезана, моцареллы и петрушки, запечённые в томатном соусе маринара под расплавленным сыром.', '<ol><li>Разогрейте духовку до 190 °C. Отварите ракушки по инструкции, часто помешивая, слейте воду и залейте холодной водой, чтобы не слиплись.</li><li>Соус: обжарьте лук в масле 3–5 минут, добавьте чеснок, соль, перец и орегано на минуту. Влейте маринару, доведите до кипения, варите 2 минуты и вылейте на дно формы 23×33 см.</li><li>Начинка: смешайте рикотту, 2 стакана моцареллы, пармезан, яйцо, петрушку, соль и перец.</li><li>Наполните ракушки начинкой (не переполняйте), уложите на соус в один слой и посыпьте оставшейся моцареллой.</li><li>Накройте фольгой и запекайте 30 минут, пока соус не запузырится по краям. Снимите фольгу и 2–4 минуты подержите под грилем до золотистого сыра. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('5f6fd69e-925e-5abb-81f5-a151f2252696', 'fa2426cd-1901-5c0b-8b07-0a3ce7b1133a', 'en', 'Cheesy stuffed pasta shells with ricotta in marinara', 'Jumbo pasta shells filled with ricotta, parmesan, mozzarella and parsley and baked in marinara sauce under melted cheese.', '<ol><li>Preheat the oven to 375 °F (190 °C). Cook the shells per package, stirring, drain and cover with cold water to keep them from sticking.</li><li>Sauce: sauté the onion in oil 3–5 minutes, add the garlic, salt, pepper and oregano for 1 minute, pour in the marinara, bring to a boil, simmer 2 minutes and pour into a 9×13 dish.</li><li>Filling: combine the ricotta, 2 cups mozzarella, parmesan, egg, parsley, salt and pepper.</li><li>Fill the shells (don''t overstuff), set them in a single layer over the sauce and top with the remaining mozzarella.</li><li>Cover with foil and bake 30 minutes until bubbling at the edges, then uncover and broil 2–4 minutes until lightly browned. Garnish with parsley.</li></ol><p><em>Garnish with parsley and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('3453eb1e-820b-544c-a054-ac34a7008e77', '64b87dae-45a0-51a2-a766-a16afcc2b841', 'ru', 'Жареный рис с креветками, яйцом, морковью и горошком', 'Жареный рис из остывшего риса с креветками, омлетом, морковью с горошком и зелёным луком в соевом соусе с кунжутным маслом. Готовится за 30 минут в одной сковороде.', '<ol><li>Смешайте креветки с крахмалом, солью и перцем и оставьте на 10 минут.</li><li>Разогрейте большую антипригарную сковороду на сильном-среднем огне, влейте 2 ст. л. масла и обжарьте креветки в один слой по минуте с каждой стороны до непрозрачности. Переложите в миску.</li><li>На среднем огне вылейте в сковороду взбитые яйца и разбивайте лопаткой, пока не схватятся. Переложите в миску.</li><li>Протрите сковороду, на сильном огне влейте 1 ст. л. масла и 30 секунд обжарьте зелёный лук. Всыпьте рис, разровняйте и 1–2 минуты не трогайте, затем перемешайте и жарьте ещё 1–2 минуты.</li><li>Влейте соевый соус и кунжутное масло, добавьте оттаявшие морковь с горошком, затем креветки и яйца. Перемешивайте, пока рис не станет горячим и не зашипит.</li></ol><p><em>Подавайте горячим, добавив соевый соус по вкусу.</em></p>', CURRENT_TIMESTAMP),
  ('55002cd9-d5ae-5d3b-963f-162d734ecb1c', '64b87dae-45a0-51a2-a766-a16afcc2b841', 'en', 'Shrimp fried rice with egg, peas and carrots', 'Fried rice from leftover chilled rice with shrimp, scrambled eggs, carrots and peas and green onion in soy sauce and sesame oil, made in one pan in 30 minutes.', '<ol><li>Toss the shrimp with the cornstarch, salt and pepper and let marinate 10 minutes.</li><li>Heat a large nonstick skillet over medium-high, swirl in 2 tbsp oil and cook the shrimp in a single layer 1 minute per side until opaque. Remove to a bowl.</li><li>On medium heat pour in the beaten eggs and break them up with a spatula until set; remove to a bowl.</li><li>Wipe the skillet, heat 1 tbsp oil over medium-high and cook the green onions 30 seconds. Add the rice, spread it and leave 1–2 minutes, then stir and sauté another 1–2 minutes.</li><li>Add the soy sauce, sesame oil and thawed vegetables, then the shrimp and eggs and stir until the rice is hot and sizzling.</li></ol><p><em>Serve hot with extra soy sauce to taste.</em></p>', CURRENT_TIMESTAMP),
  ('d558fbc6-a61b-5e13-9aa1-588184ec1159', 'f8937d6f-7e16-5d11-b255-e4a949250d59', 'ru', 'Домашние картофельные ньокки с рикоттой', 'Нежные ньокки из запечённого или отварного картофеля, муки, яйца и рикотты. Подаются с беконом и сметаной, томатным соусом с пармезаном или песто.', '<ol><li>Вымойте картофель, проколите вилкой и запеките или отварите до мягкости. Остудите до тёплого состояния, очистите, нарежьте на 4 части и продавите по кусочку через пресс для картофеля на рабочую поверхность.</li><li>Полейте картофель взбитым яйцом и разложите сверху кусочки рикотты.</li><li>Смешайте соль и перец с мукой и просейте на картофель. Лёгкими движениями соедините, затем аккуратно вымесите мягкое гладкое тесто, подсыпая муку. Не перемешивайте долго.</li><li>Разделите тесто на 8 частей, раскатайте каждую в жгут толщиной около 1,3 см и нарежьте кусочками по 2,5 см. При желании прокатите по вилке или доске для ньокки. Выложите в один слой на присыпанный мукой противень.</li><li>Варите ньокки в подсоленной воде 3–4 партиями: как только они всплывут, готовьте ещё минуту, достаньте шумовкой и переложите в тёплый соус или обжарьте на сковороде.</li></ol><p><em>Обжарьте ньокки на сковороде или подайте с томатным соусом и пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('2200c6ed-d619-50d7-aa09-bf6adc2d2dda', 'f8937d6f-7e16-5d11-b255-e4a949250d59', 'en', 'Homemade potato gnocchi with ricotta', 'Light gnocchi made from baked or boiled potatoes, flour, egg and ricotta, served with bacon and sour cream, marinara and parmesan, or pesto.', '<ol><li>Wash the potatoes, pierce with a fork and bake or boil until tender. Let cool until handleable, peel, cut each into 4 slices and press through a potato ricer onto a clean work surface.</li><li>Drizzle the beaten egg over the potatoes and dot with bits of ricotta.</li><li>Mix the salt and pepper into the flour and sift it over the potatoes. Lightly combine, then gently knead into a soft smooth dough, dusting with flour; don''t over-knead.</li><li>Divide the dough into 8 pieces, roll each into a ½-inch rope and cut into 1-inch pieces. Roll over a floured fork or gnocchi paddle if you like and place in a single layer on a floured tray.</li><li>Cook in salted water in 3–4 batches: when they float cook one more minute, lift out with a sieve and transfer to warm sauce or finish in a skillet.</li></ol><p><em>Pan-fry the gnocchi or toss them in marinara with parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('fb07419e-1b35-5f07-8f13-4d530f2e7a9d', 'e605544a-8849-5563-a2d2-fe452ce55a3b', 'ru', 'Лазанья с кабачками вместо листов, с мясным соусом и рикоттой', 'Лазанья без макаронных листов: слои обжаренных кабачков, мясного томатного соуса, сырной смеси из рикотты и пармезана и моцареллы. Меньше углеводов и без глютена.', '<ol><li>Нарежьте кабачки вдоль ломтиками толщиной 6 мм. Смажьте маслом с двух сторон, посолите и поперчите и обжарьте на гриле или сковороде-гриль по 2 минуты с каждой стороны до хрустяще-мягкого состояния.</li><li>Разогрейте духовку до 190 °C. В глубокой кастрюле обжарьте фарш с маслом 5 минут, слейте лишний жир (оставьте 2 ст. л.), добавьте лук на 5 минут, затем чеснок. Влейте соус, добавьте половину зелени, соль и перец и томите без крышки 10 минут.</li><li>Смешайте 1 стакан моцареллы, рикотту, пармезан, яйцо, остальную зелень и соль.</li><li>В форме 23×33 см распределите ½ стакана мясного соуса, затем слоями выложите кабачки, соус, моцареллу и сырную смесь. Повторите до 3 слоёв кабачков, разделив ингредиенты поровну.</li><li>Накройте фольгой (воткнув зубочистки, чтобы не прилипла к сыру) и запекайте 40–45 минут. Снимите фольгу и 3–4 минуты подержите под грилем. Дайте отдохнуть 15 минут.</li></ol><p><em>Дайте отдохнуть 15 минут перед нарезкой, посыпьте базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('cee3d404-1323-50ad-b9c2-7d84e223d0a8', 'e605544a-8849-5563-a2d2-fe452ce55a3b', 'en', 'Zucchini lasagna with meat sauce and ricotta', 'Lasagna with grilled zucchini instead of noodles, layered with beef tomato sauce, a ricotta parmesan egg filling and mozzarella. Lower in carbs and gluten-free.', '<ol><li>Slice the zucchini lengthwise ¼ inch thick, brush both sides with oil, season and grill on a grill or grill pan over medium-high 2 minutes per side until crisp-tender.</li><li>Preheat the oven to 375 °F (190 °C). In a deep pot brown the beef with oil 5 minutes, drain all but 2 tbsp fat, cook the onion 5 minutes, then the garlic. Add the sauce, half the basil, salt and pepper and simmer uncovered 10 minutes.</li><li>Mix 1 cup mozzarella with the ricotta, parmesan, egg, remaining herbs and salt.</li><li>Spread ½ cup meat sauce in a 9×13 dish, then layer zucchini, meat sauce, mozzarella and the cheese mixture, repeating for 3 layers of zucchini.</li><li>Cover with foil (use toothpicks so it doesn''t stick) and bake 40–45 minutes, then uncover and broil 3–4 minutes. Rest 15 minutes before slicing.</li></ol><p><em>Rest 15 minutes before slicing and garnish with basil.</em></p>', CURRENT_TIMESTAMP),
  ('c9b3e659-dd5c-5573-9c37-af719c42b105', '6078944b-5fa6-517c-91ff-4809260a2b3c', 'ru', 'Плов с курицей и зелёными овощами в одной кастрюле', 'Лёгкий рис с курицей, кабачком, спаржей и зелёным горошком, готовый в одной кастрюле. С фетой, лимоном и петрушкой.', '<ol><li>В большой кастрюле разогрейте масло на среднем-сильном огне и около 2 минут обжарьте лук с чесноком до мягкости и лёгкого румянца.</li><li>Добавьте рис, перемешайте, влейте бульон, доведите до кипения и убавьте огонь. Положите курицу сверху (она должна быть наполовину в жидкости), накройте и готовьте 5 минут.</li><li>Откройте, не перемешивая, рассыпьте горошек и кабачок, накройте и готовьте ещё 5–8 минут, пока почти вся вода не впитается и рис не станет чуть недоваренным.</li><li>Выньте курицу и дайте отдохнуть. Положите сверху спаржу, накройте и готовьте 1–2 минуты. Снимите с огня и оставьте на 5 минут.</li><li>Разберите курицу вилкой и верните в кастрюлю. Посолите, поперчите, выжмите лимон, аккуратно перемешайте. Подавайте с фетой, петрушкой и дольками лимона.</li></ol><p><em>Посыпьте фетой и петрушкой, подайте с дольками лимона.</em></p>', CURRENT_TIMESTAMP),
  ('046d3de0-26d5-5660-9e56-a8f29d416646', '6078944b-5fa6-517c-91ff-4809260a2b3c', 'en', 'One-pot chicken and green vegetable rice pilaf', 'A light one-pot rice dish with chicken, zucchini, asparagus and peas, finished with feta, lemon and parsley.', '<ol><li>Heat the oil in a large pot over medium-high and sauté the onion and garlic about 2 minutes until softened and starting to brown.</li><li>Add the rice and stir to coat, pour in the stock, bring to a simmer and reduce the heat. Lay the chicken on top, partly submerged, cover and cook 5 minutes.</li><li>Uncover and scatter the peas and zucchini on top without stirring, cover and cook 5–8 minutes more until most of the water is absorbed and the rice is slightly undercooked.</li><li>Remove the chicken to rest. Scatter the asparagus on top, cover and cook 1–2 minutes, then take off the heat and stand 5 minutes.</li><li>Shred the chicken and return it to the pot. Season, squeeze over the lemon and gently toss. Serve with feta, parsley and lemon wedges.</li></ol><p><em>Scatter with feta and parsley and serve with lemon wedges.</em></p>', CURRENT_TIMESTAMP),
  ('cfecf5b9-c3f2-5ef3-b8e1-61486e2ba04c', '09a98834-33b0-5026-8d3a-fa291912d570', 'ru', 'Куриный бефстроганов с грибами и сметаной', 'Обжаренные куриные бёдра в сливочно-грибном соусе из сметаны и дижонской горчицы. Готовится быстро в одной сковороде.', '<ol><li>Посыпьте курицу чесночным порошком, солью и перцем с обеих сторон. Разогрейте масло в большой сковороде на среднем огне.</li><li>Выложите курицу гладкой стороной вниз, слегка прижмите лопаткой и жарьте 4 минуты до золотистого цвета. Переверните, прижмите и жарьте 2 минуты. Переложите на тарелку.</li><li>Прибавьте огонь, растопите масло, обжарьте лук минуту, добавьте грибы и жарьте до золотистого цвета, соскребая со дна румяные кусочки.</li><li>Всыпьте муку и жарьте минуту. Влейте половину бульона, перемешайте, затем остальное. Добавьте сметану и горчицу и размешайте (сметана «растает» при нагреве).</li><li>Доведите до кипения, убавьте огонь и варите около 3 минут до консистенции жидких сливок. Верните курицу с соком, прогрейте минуту и подавайте.</li></ol><p><em>Подайте с макаронами, яичной лапшой или картофельным пюре, посыпав зеленью. Значения КБЖУ даны без гарнира.</em></p>', CURRENT_TIMESTAMP),
  ('fd0e4576-4d4b-5dc8-a292-09262121448d', '09a98834-33b0-5026-8d3a-fa291912d570', 'en', 'Chicken stroganoff with mushrooms and sour cream', 'Seared chicken thighs in a creamy mushroom gravy of sour cream and Dijon mustard, made quickly in one skillet.', '<ol><li>Sprinkle the chicken on both sides with garlic powder, salt and pepper. Heat the oil in a large skillet over medium.</li><li>Place the chicken smooth-side down, press lightly with a spatula and cook 4 minutes until golden. Turn, press and cook 2 minutes. Remove to a plate.</li><li>Turn up the heat to medium-high, melt the butter, cook the onion 1 minute, add the mushrooms and cook until golden, scraping up the browned bits.</li><li>Add the flour and cook 1 minute. Pour in half the broth, stir, then add the rest. Stir in the sour cream and mustard until incorporated; it melts as it heats.</li><li>Bring to a simmer, reduce the heat and cook about 3 minutes until it reaches the consistency of pouring cream. Return the chicken with its juices, simmer 1 minute and serve.</li></ol><p><em>Serve over pasta, egg noodles or mash with parsley. Nutrition is given without the side.</em></p>', CURRENT_TIMESTAMP),
  ('d450402b-92cb-50d7-ad44-9649f3a85ff4', '8d4c5f59-6972-5245-a398-82ff034cbf89', 'ru', 'Салат из капусты, зелёного горошка, мяты и пармезана', 'Свежий салат из тонко нарезанной капусты, бланшированного горошка, редиса, мяты и петрушки с пармезаном, лимонным соком и оливковым маслом.', '<ol><li>Бланшируйте горошек в кипятке 1–2 минуты и остудите. Отложите 1 ст. л. пармезана для украшения.</li><li>Смешайте в миске горошек, капусту, мяту, петрушку, редис, пармезан, лимонный сок, масло, соль и перец. Дайте постоять 5 минут.</li><li>Попробуйте, при необходимости добавьте соль и перец, посыпьте оставленным пармезаном и подавайте.</li></ol><p><em>Дайте постоять 5 минут, чтобы капуста слегка размякла.</em></p>', CURRENT_TIMESTAMP),
  ('5daa37e2-8500-59da-b89e-c675032ae234', '8d4c5f59-6972-5245-a398-82ff034cbf89', 'en', 'Pea, cabbage, Parmesan and mint salad', 'A fresh salad of finely sliced cabbage, blanched peas, radishes, mint and parsley with Parmesan, lemon juice and olive oil.', '<ol><li>Blanch the peas in boiling water 1–2 minutes and cool. Reserve 1 tbsp of the Parmesan for garnish.</li><li>Toss the peas, cabbage, mint, parsley, radishes, Parmesan, lemon juice, oil, salt and pepper in a bowl. Let sit 5 minutes.</li><li>Adjust the seasoning, garnish with the reserved Parmesan and serve.</li></ol><p><em>Let it sit 5 minutes so the cabbage wilts slightly.</em></p>', CURRENT_TIMESTAMP),
  ('d4023cf1-9bda-5f17-9362-16db464501b0', '716341b9-0428-5851-97cc-85b825a5aca9', 'ru', 'Паста с цветной капустой, чесночным маслом и хрустящими сухариками', 'Феттучине с обжаренной в чесночном сливочном масле цветной капустой, красным луком и чили, с лимоном и золотистыми сухариками (панграттато).', '<ol><li>Для панграттато мелко нарежьте хлеб без корок, сбрызните маслом и около 2 минут обжарьте на сильном огне до золотистого цвета. Посолите.</li><li>В той же сковороде растопите масло, добавьте оливковое и раздавленный чеснок, жарьте минуту. Положите цветную капусту на 3 минуты, затем красный лук, соль и перец и готовьте ещё около 5 минут до золотистого цвета, но чтобы капуста оставалась упругой. Выньте чеснок.</li><li>Тем временем отварите пасту на минуту меньше, чем указано, оставив полстакана отвара.</li><li>Переложите пасту в сковороду, влейте отвар, добавьте хлопья чили, соль и перец и перемешивайте 1–2 минуты, пока вода не выпарится и не образуется глянцевый соус.</li><li>Снимите с огня, добавьте цедру и сок лимона. Подавайте с панграттато, пармезаном и петрушкой.</li></ol><p><em>Посыпьте сухариками, тёртым пармезаном и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('7b5e5b9b-69c1-5b34-a4eb-b32753ee78a8', '716341b9-0428-5851-97cc-85b825a5aca9', 'en', 'Garlic butter cauliflower pasta with crispy breadcrumbs', 'Fettuccine with cauliflower sautéed in garlic butter, red onion and chilli, brightened with lemon and finished with golden toasted breadcrumbs (pangrattato).', '<ol><li>For the pangrattato dice the crustless bread small, spray or toss with oil and fry on medium-high about 2 minutes until golden. Salt it.</li><li>In the same skillet melt the butter, add the olive oil and smashed garlic and cook 1 minute. Add the cauliflower 3 minutes, then the red onion, salt and pepper and cook about 5 minutes until golden but still a bit firm. Remove the garlic.</li><li>Meanwhile cook the pasta 1 minute less than the pack says, reserving ½ cup of the water.</li><li>Move the pasta to the skillet, add the pasta water, chilli flakes, salt and pepper and toss 1–2 minutes until the water evaporates into a glossy sauce.</li><li>Remove from the heat, add the lemon zest and juice and serve with the pangrattato, Parmesan and parsley.</li></ol><p><em>Top with the breadcrumbs, grated Parmesan and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('af884526-1905-52a0-b117-04cb33936e09', 'e3f95546-20e8-529a-a563-90669540c3be', 'ru', 'Мексиканский жареный рис с чёрной фасолью и кукурузой', 'Быстрый ужин: готовый рис, обжаренный с луком, перцем, чёрной фасолью, кукурузой и соусом энчилада со специями.', '<ol><li>Смешайте соус энчилада с водой и специями в маленькой миске.</li><li>Разогрейте масло в сковороде на сильном огне, 10 секунд обжарьте чеснок, затем лук и перец около 2 минут до прозрачности лука.</li><li>Добавьте фасоль и кукурузу и прогрейте минуту. Положите рис и соус и быстро перемешайте, чтобы рис равномерно окрасился.</li><li>Попробуйте, подсолите по вкусу и поперчите. Подавайте сразу.</li></ol><p><em>Добавьте варёное или жареное мясо или яичницу, посыпьте кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('2599c0dc-00d9-5255-9cf8-7b9be66381d9', 'e3f95546-20e8-529a-a563-90669540c3be', 'en', 'Mexican fried rice with black beans and corn', 'A fast dinner of cooked rice stir-fried with onion, pepper, black beans, corn and enchilada sauce with spices.', '<ol><li>Mix the enchilada sauce with the water and spices in a small bowl.</li><li>Heat the oil in a pan over high heat, cook the garlic 10 seconds, then the onion and pepper about 2 minutes until the onion turns translucent.</li><li>Add the beans and corn and heat through for 1 minute. Add the rice and sauce and stir quickly to coat evenly.</li><li>Taste, add salt as needed and season with pepper. Serve immediately.</li></ol><p><em>Add shredded or diced cooked meat or a fried egg and sprinkle with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('bb0b2301-2053-5c37-9261-64a35940e012', 'ba068998-17e9-5a9e-a74a-a882b4367611', 'ru', 'Итальянский мясной рулет из говядины и свинины в томатном соусе', 'Сочный рулет из говяжьего и свиного фарша с фенхелем, паприкой и печёным перцем, который допекается прямо в томатном соусе с травами.', '<ol><li>Разогрейте духовку до 180 °C, выстелите форму для хлеба пергаментом с запасом по краям. Хорошо обжарьте красный перец в масле на сильном огне около 2 минут, чтобы он слегка подгорел. Отложите.</li><li>Размочите хлеб в миске с натёртым луком и сливками, разомните руками. Добавьте остальные ингредиенты рулета и перец и перемешайте, пока всё просто не соединится.</li><li>Выложите в форму, сбрызните маслом и запекайте 30 минут. Тем временем для соуса в жаропрочной сковороде обжарьте лук и чеснок 3 минуты, добавьте томаты, воду, травы, чили, соль и перец и варите 5 минут.</li><li>Выньте рулет за края пергамента и переложите в сковороду с соусом, влейте сок из формы. Верните в духовку на 30–40 минут.</li><li>Дайте постоять 5 минут, нарежьте и подавайте с соусом и пармезаном.</li></ol><p><em>Подайте с картофельным пюре или пастой, посыпав пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('1e3796c9-7d80-5801-992e-e7244509f934', 'ba068998-17e9-5a9e-a74a-a882b4367611', 'en', 'Italian meatloaf with pork, beef and marinara sauce', 'A juicy loaf of beef and pork mince with fennel, paprika and charred pepper, finished by baking right in a herby tomato sauce.', '<ol><li>Heat the oven to 350 °F (180 °C) and line a loaf pan with parchment leaving an overhang. Char the diced pepper in the oil over high heat about 2 minutes. Set aside.</li><li>Soak the diced bread in a bowl with the grated onion and cream, squishing with your hands. Add the remaining meatloaf ingredients and the pepper and mix just until combined.</li><li>Press into the pan, drizzle with oil and bake 30 minutes. Meanwhile for the sauce cook the onion and garlic in an ovenproof skillet 3 minutes, then add the tomatoes, water, herbs, chilli, salt and pepper and simmer 5 minutes.</li><li>Lift the meatloaf out by the parchment into the skillet with the sauce and pour in the pan juices. Return to the oven for 30–40 minutes.</li><li>Rest 5 minutes, slice and serve with the sauce and Parmesan.</li></ol><p><em>Serve with mashed potatoes or pasta, topped with Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('7beb3653-79ae-5aaf-9b85-eb1bb9c3c44c', 'e736e797-cff3-580a-996a-f70f018c7100', 'ru', 'Спагетти с креветками, лимоном и помидорами черри', 'Спагетти в глянцевом соусе из оливкового масла, крахмальной воды и бульона, сваренного из панцирей креветок, с лимоном, петрушкой и помидорами черри.', '<ol><li>Очистите креветки, оставив хвостики, удалите вену. Панцири и головы отложите для бульона. Крупные креветки разрежьте вдоль пополам, смешайте с 2 зубчиками чеснока и 2 ст. л. масла и оставьте.</li><li>Для бульона положите панцири в кастрюлю, добавьте бульон, воду и лук, доведите до кипения и варите на сильном огне, время от времени разминая панцири толкушкой. Когда останется 1–1,5 стакана, процедите и держите тёплым под крышкой. Белое вино можно добавить вместо части воды.</li><li>Отварите спагетти в подсоленной воде чуть меньше, чем указано. В большой сковороде на сильном огне обжарьте креветки по минуте с каждой стороны, переложите на тарелку.</li><li>В ту же сковороду влейте 3 ст. л. масла и добавьте чеснок с остатками маринада. Обжарьте до аромата, переложите щипцами пасту, влейте 180 мл отвара и добавьте помидоры. Перемешивайте около минуты до глянцевого соуса.</li><li>Добавьте цедру и сок лимона, петрушку, чили и креветки, быстро перемешайте, влейте креветочный бульон, посолите и поперчите. Сразу снимите с огня и подавайте.</li></ol><p><em>Сбрызните оливковым маслом, подайте с долькой лимона и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('23abd8c9-af77-50fb-995e-3ff9ef968662', 'e736e797-cff3-580a-996a-f70f018c7100', 'en', 'Lemon shrimp spaghetti with cherry tomatoes', 'Spaghetti in a glossy sauce of olive oil, starchy water and a quick stock made from the shrimp shells, with lemon, parsley and cherry tomatoes.', '<ol><li>Peel and devein the shrimp, leaving the tails on, and keep the shells and heads for stock. Halve large shrimp lengthwise, toss with 2 minced garlic cloves and 2 tbsp oil and set aside.</li><li>For the stock put the shells in a pot with the broth, water and onion, bring to a boil and simmer rapidly, crushing the shells with a masher now and then. When reduced to 1–1½ cups, strain and keep warm covered. Dry white wine can replace part of the water.</li><li>Cook the spaghetti in salted water slightly less than the pack says. In a large pan on high heat sear the shrimp 1 minute per side and set aside.</li><li>Add 3 tbsp oil and the minced garlic with the marinade leftovers to the pan and cook until fragrant. Transfer the pasta with tongs, add ¾ cup of the pasta water and the tomatoes and toss about a minute until the sauce turns glossy.</li><li>Add the lemon zest and juice, parsley, chilli and shrimp, toss quickly, pour over the shrimp stock, season and take off the heat immediately.</li></ol><p><em>Drizzle with olive oil and serve with lemon wedges and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('4c8cfbcc-2d95-5afc-a379-d9235770f9d4', '21f88e6d-739f-5729-8503-83967a98811f', 'ru', 'Курица терияки с домашним соусом', 'Кусочки курицы, обжаренные и политые густым соусом терияки из соевого соуса, коричневого сахара, чеснока и имбиря. Готовится за 20 минут.', '<ol><li>Для соуса соедините в кастрюле соевый соус, воду, чеснок, имбирь, крахмал, хлопья чили и коричневый сахар, доведите до кипения и варите до загустения.</li><li>Нарежьте курицу кусочками и обжарьте в сковороде с 1 ст. л. масла, посолив и поперчив, до лёгкой румяности и готовности.</li><li>Влейте соус к курице и прогрейте, перемешивая, пока он не обволочёт кусочки. Подавайте с рисом.</li></ol><p><em>Подавайте с рисом и брокколи.</em></p>', CURRENT_TIMESTAMP),
  ('6d5acbc1-1d9a-5f51-b27c-d75aa935ea72', '21f88e6d-739f-5729-8503-83967a98811f', 'en', 'Chicken teriyaki with homemade sauce', 'Pan-seared bite-sized chicken tossed in a thick homemade teriyaki sauce of soy, brown sugar, garlic and ginger, ready in 20 minutes.', '<ol><li>For the sauce combine the soy sauce, water, garlic, ginger, cornstarch, red pepper flakes and brown sugar in a pan, bring to a simmer and cook until thickened.</li><li>Cut the chicken into bite-sized pieces and sauté in a pan with 1 tbsp oil, seasoned with salt and pepper, until lightly browned and cooked through.</li><li>Add the sauce to the chicken and heat, stirring, until it coats the pieces. Serve with rice.</li></ol><p><em>Serve with rice and broccoli.</em></p>', CURRENT_TIMESTAMP),
  ('c59e2b42-6aba-5ea0-97ce-e8e6f7c1e1bd', 'fc93acff-a017-5da8-a1f2-b9f20fa01a7f', 'ru', 'Курица по-тоскански в сливочном соусе со шпинатом и вялеными томатами', 'Куриные грудки в муке, обжаренные до золотистой корочки и поданные в сливочном соусе с чесноком, вялеными томатами, пармезаном и шпинатом. Готовится за 30 минут.', '<ol><li>Разрежьте грудки вдоль пополам и отбейте толстую часть до равной толщины.</li><li>Смешайте ¾ ч. л. итальянских трав, 1 ч. л. соли и ¼ ч. л. перца, натрите курицу и обваляйте в муке, стряхнув излишки.</li><li>Разогрейте в большой сковороде на сильном огне масло и 1 ст. л. сливочного. Обжаривайте курицу по 3–4 минуты с каждой стороны до 68 °C в толстой части, затем накройте — она дойдёт до 74 °C на остаточном жаре.</li><li>В той же сковороде растопите оставшееся масло, на минуту добавьте чеснок и вяленые томаты, соскребая налёт со дна.</li><li>Влейте сливки и бульон, добавьте пармезан и оставшиеся травы, соль и перец. Убавьте огонь и варите, пока соус не начнёт густеть. Положите шпинат и курицу и греите, пока шпинат не завянет.</li></ol><p><em>Подавайте с пастой или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('7e0202ec-e160-5c39-bf51-05cb16ebc1db', 'fc93acff-a017-5da8-a1f2-b9f20fa01a7f', 'en', 'Creamy Tuscan chicken with spinach and sun-dried tomatoes', 'Floured chicken breasts seared until golden and served in a creamy garlic sauce with sun-dried tomatoes, parmesan and spinach. Ready in 30 minutes.', '<ol><li>Cut the chicken breasts in half lengthwise and pound the thick part to an even thickness.</li><li>Mix ¾ tsp Italian seasoning, 1 tsp salt and ¼ tsp pepper, season the chicken and coat in flour, shaking off the excess.</li><li>Heat the oil and 1 tbsp butter in a large skillet over high heat and cook the chicken 3–4 minutes per side until 155 °F (68 °C) in the thickest part; cover to keep warm, it will reach 165 °F (74 °C) from residual heat.</li><li>In the same skillet melt the remaining butter and cook the garlic and sun-dried tomatoes 1 minute, scraping up the browned bits.</li><li>Stir in the cream, broth, parmesan and remaining Italian seasoning, salt and pepper, lower the heat and cook until the sauce thickens. Add the spinach and chicken and cook until the spinach wilts and the chicken is warm.</li></ol><p><em>Serve with pasta or rice.</em></p>', CURRENT_TIMESTAMP),
  ('e2ed5c0a-2480-56ce-b699-c8b782aa3104', '12b7e821-a285-594b-9e81-ffeee8a0dbf9', 'ru', 'Спагетти карбонара с курицей, креветками и беконом в сливочном соусе', 'Упрощённая карбонара: спагетти с хрустящим беконом, обжаренными куриными эскалопами и креветками в сливочном соусе с пармезаном, луком и помидорами.', '<ol><li>Отварите спагетти аль денте, слейте воду и отложите.</li><li>Бекон мелко нарежьте и обжарьте в холодной сковороде на среднем огне, вытопив жир. Выложите бекон, оставив 2 ст. л. жира.</li><li>Разрежьте куриные грудки вдоль на эскалопы. Смешайте муку, 2 ст. л. пармезана, чесночный порошок, соль, перец и паприку и обваляйте курицу. Обжарьте в 1 ст. л. жира и 1 ст. л. масла по 4 минуты с каждой стороны до золотистого цвета, нарежьте полосками.</li><li>В той же сковороде с 1 ст. л. масла обжарьте креветки на сильном огне по 1–2 минуты с каждой стороны и отложите.</li><li>Для соуса растопите 1 ст. л. масла с оставшимся жиром, обжарьте лук, затем чеснок и помидоры 2 минуты. Влейте бульон и сливки, прогрейте без кипения, постепенно вмешайте пармезан, посолите и поперчите. Дайте загустеть.</li><li>Добавьте в соус пасту, курицу и бекон, перемешайте. Перед подачей добавьте креветок.</li></ol><p><em>Креветки добавляйте в самом конце, чтобы они не пересохли.</em></p>', CURRENT_TIMESTAMP),
  ('58e57430-58c5-545c-bf35-a937d972ba3e', '12b7e821-a285-594b-9e81-ffeee8a0dbf9', 'en', 'Chicken and shrimp carbonara spaghetti', 'A simplified carbonara: spaghetti with crisp bacon, golden chicken cutlets and shrimp in a creamy parmesan sauce with onion and tomatoes.', '<ol><li>Boil the spaghetti al dente, drain and set aside.</li><li>Chop the bacon, start it in a cold pan over medium heat and render the fat. Remove the bacon, saving 2 tbsp of the grease.</li><li>Cut the chicken into cutlets, mix the flour, 2 tbsp parmesan, garlic powder, salt, pepper and paprika and dredge. Cook in 1 tbsp bacon grease and 1 tbsp butter about 4 minutes per side until golden, then cut into strips.</li><li>In the same pan with 1 tbsp butter cook the shrimp on high 1–2 minutes per side and set aside.</li><li>For the sauce melt 1 tbsp butter with the remaining grease, cook the onion, then the garlic and tomatoes 2 minutes. Add the broth and cream, heat without boiling, gradually stir in the parmesan and season; simmer until thick.</li><li>Add the pasta, chicken and bacon to the sauce and toss, then stir in the shrimp right before serving.</li></ol><p><em>Add the shrimp at the very end so they don''t overcook.</em></p>', CURRENT_TIMESTAMP),
  ('174d6c51-2a39-53a7-a859-afa459b68190', 'b3dc830a-e34c-5187-b75d-86ab9aa18419', 'ru', 'Куриные грудки, фаршированные брокколи и сыром, в сливочно-винном соусе', 'Куриные грудки с карманом, начинённые брокколи, сыром и помидорами, обжаренные и запечённые в соусе из белого вина, бульона и сливок.', '<ol><li>Разогрейте духовку до 190 °C. Отбейте грудки до одинаковой толщины и сделайте в каждой карман, не прорезая насквозь.</li><li>Смешайте брокколи, сыр и помидоры, посолите и поперчите, начините грудки и закрепите зубочистками.</li><li>Разогрейте масло в большой жаропрочной сковороде и обжарьте грудки по 3–4 минуты с каждой стороны до румяности. Достаньте, выньте зубочистки и накройте.</li><li>В той же сковороде растопите масло, обжарьте ломтики лука до мягкости и уберите их. Добавьте чеснок до аромата, всыпьте муку и перемешайте, влейте вино и готовьте 2 минуты, затем бульон и сливки, посолите и поперчите и варите 2–3 минуты до загустения.</li><li>Верните грудки в сковороду, полейте соусом, накройте фольгой и запекайте 15–20 минут до 74 °C внутри.</li></ol><p><em>Подавайте с рисом или картофельным пюре, полив соусом.</em></p>', CURRENT_TIMESTAMP),
  ('a9f6ee99-59a0-5724-8bc5-a6527cd4d6eb', 'b3dc830a-e34c-5187-b75d-86ab9aa18419', 'en', 'Broccoli and cheese stuffed chicken breast in wine cream sauce', 'Butterflied chicken breasts stuffed with broccoli, cheese and tomatoes, seared and baked in a white wine, broth and cream sauce.', '<ol><li>Preheat the oven to 375 °F (190 °C). Pound the breasts to an even thickness and butterfly each to make a pocket without cutting through.</li><li>Mix the broccoli, cheese and tomatoes, season, stuff the chicken and secure with toothpicks.</li><li>Heat the oil in a large oven-safe skillet and sear the chicken 3–4 minutes per side. Remove, take out the toothpicks and keep warm.</li><li>In the same skillet melt the butter, cook the onion slices until tender and discard them. Add the garlic, whisk in the flour, add the wine and cook 2 minutes, then the broth and cream, season and cook 2–3 minutes until thickened.</li><li>Return the chicken to the skillet, pour the sauce over, cover with foil and bake 15–20 minutes until 165 °F (74 °C) inside.</li></ol><p><em>Serve with rice or mashed potatoes, spooning over the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('2a915f14-473a-5ee8-8b3c-03072a7aad0d', 'e58d941f-d0d2-5a0b-be8d-3bf55bc2c959', 'ru', 'Говядина с овощами в соевом соусе с имбирём', 'Тонкие ломтики говядины, обжаренные с перцем, шампиньонами, брокколи и морковью, в соусе из соевого соуса, имбиря, чеснока и коричневого сахара.', '<ol><li>Нарежьте стейк тонкими ломтиками.</li><li>В большой сковороде или воке разогрейте 1 ст. л. масла на сильном огне и обжарьте говядину до готовности, посолите и поперчите. Отложите и накройте.</li><li>В той же сковороде на среднем огне разогрейте оставшееся масло и обжарьте овощи до желаемой мягкости. Смешайте в миске ингредиенты соуса.</li><li>Добавьте к овощам сливочное масло, чеснок и имбирь, затем верните мясо. Влейте соус и готовьте, пока он не загустеет.</li></ol><p><em>Подавайте с рисом или лапшой.</em></p>', CURRENT_TIMESTAMP),
  ('96cdcb64-b69e-5f1c-9336-295766e4315e', 'e58d941f-d0d2-5a0b-be8d-3bf55bc2c959', 'en', 'Beef and vegetable stir fry with soy ginger sauce', 'Thin sliced steak sautéed with bell pepper, mushrooms, broccoli and carrot in a soy, ginger, garlic and brown sugar sauce.', '<ol><li>Slice the steak thinly.</li><li>Heat 1 tbsp oil in a large skillet or wok over high heat and cook the steak until fully cooked, season and set aside covered.</li><li>In the same skillet heat the remaining oil over medium and sauté the vegetables to your liking. Whisk the sauce ingredients in a bowl.</li><li>Add the butter, garlic and ginger to the vegetables, return the beef, pour in the sauce and cook until thickened.</li></ol><p><em>Serve over rice or noodles.</em></p>', CURRENT_TIMESTAMP),
  ('66bd6245-68c0-592a-950c-d8168ae63af2', 'a4673624-4798-5da4-83fa-ea6e0a7ae35f', 'ru', 'Картофельные котлеты из пюре с беконом и сыром', 'Жареные котлеты из холодного картофельного пюре с беконом, расплавленным сыром и зелёным луком в хрустящей панировке. Хороший способ использовать остатки пюре. Получается 12 штук.', '<ol><li>Обжарьте нарезанный бекон до хруста и дайте стечь жиру на бумажном полотенце.</li><li>В миске смешайте холодное пюре, яйцо, муку, тёртый сыр, бекон, зелёный лук, соль и перец, только до однородности.</li><li>Насыпьте панировочные сухари на большую тарелку. Выкладывайте порции пюре по ¼ стакана на сухари, прижимайте до толщины около 1,5 см и обваливайте с обеих сторон.</li><li>Разогрейте половину масла на сковороде на среднем-сильном огне и жарьте по 6 котлет примерно по 2 минуты с каждой стороны до золотистого цвета. Остальное масло используйте для второй порции. Выложите на бумажное полотенце и подавайте горячими.</li></ol><p><em>Подавайте горячими с кислым йогуртом или сметаной и салатом. Порция — 3 котлеты.</em></p>', CURRENT_TIMESTAMP),
  ('b2a62b35-8268-5981-b577-398fc5c2c1db', 'a4673624-4798-5da4-83fa-ea6e0a7ae35f', 'en', 'Leftover mashed potato, cheese and bacon cakes', 'Pan-fried cakes of cold mashed potato with bacon, melting cheese and scallions in a crunchy crumb coating. A great way to use leftover mash. Makes 12; a serving is 3 cakes.', '<ol><li>Cook the diced bacon until crisp and drain on paper towels.</li><li>In a bowl mix the cold mashed potato, egg, flour, grated cheese, bacon, scallions, salt and pepper until just combined.</li><li>Spread the panko on a large plate. Drop ¼-cup portions of the mixture onto it, pat into patties about ⅔ inch (1.5 cm) thick and coat both sides.</li><li>Heat half the oil in a large skillet over medium-high and cook 6 cakes about 2 minutes per side until golden. Use the rest of the oil for the second batch, drain on paper towels and serve hot.</li></ol><p><em>Serve hot with sour cream or yogurt and a salad.</em></p>', CURRENT_TIMESTAMP),
  ('f1abf97e-1ed2-5d86-8895-4d7554f635d0', 'e1813fc4-fb27-50e5-b613-141d942174e9', 'ru', 'Лахмаджун: тонкие лепёшки с бараньим фаршем и пряной томатной начинкой', 'Турецко-армянская тонкая «пицца»: готовое тесто, раскатанное в диски и запечённое с начинкой из баранины или говядины, красного перца, шалота, петрушки и специй. Сокращённый вариант.', '<ol><li>Разогрейте духовку до 230 °C, поставьте решётку посередине. Подготовьте два противня с пергаментом.</li><li>В чаше комбайна с ножом измельчите (несколькими импульсами) красный перец, шалот, чеснок и петрушку. Добавьте фарш, специи, соль, томатную пасту и масло и взбейте импульсами до однородности (8–10 раз).</li><li>Разделите тесто на 4 шарика (около 55 г). Каждый раскатайте на присыпанной мукой поверхности как можно тоньше в диск диаметром 20–23 см и переложите на противень.</li><li>Выложите на каждый диск 3–4 ст. л. начинки, равномерно распределив до краёв и оставив узкий бортик.</li><li>Выпекайте 5–7 минут (партиями) до готового мяса и слегка хрустящих краёв теста. Сбрызните лимонным соком и подавайте горячими или тёплыми.</li></ol><p><em>Сбрызните лимонным соком, добавьте свежие овощи и зелень и сверните рулетом.</em></p>', CURRENT_TIMESTAMP),
  ('864b17f4-5c85-5f41-a4a0-2bc8506dc2d7', 'e1813fc4-fb27-50e5-b613-141d942174e9', 'en', 'Lahmacun lamb flatbreads', 'Turkish and Armenian thin crispy flatbreads made from ready pizza dough topped with ground lamb or beef, red pepper, shallot, parsley and warm spices.', '<ol><li>Heat the oven to 450 °F (230 °C) with a rack in the middle and line two baking sheets with parchment.</li><li>In a food processor with the blade pulse the red pepper, shallot, garlic and parsley to chop. Add the lamb, spices, salt, tomato paste and oil and pulse 8–10 times until well combined.</li><li>Divide the dough into 4 balls (about 2 oz each) and roll each out as thin as possible on a floured surface into a 8–9 inch (20–23 cm) disk; place on the pan.</li><li>Spoon 3–4 tbsp of the topping onto each disk and spread evenly to the edges leaving a thin border.</li><li>Bake 5–7 minutes (in batches) until the meat is cooked and the dough edges are a little crusty. Squeeze lemon on top and serve hot or at room temperature.</li></ol><p><em>Squeeze lemon over, add fresh vegetables and herbs and roll up.</em></p>', CURRENT_TIMESTAMP),
  ('c8e2a803-d238-56e9-acd2-b9e4d070279c', 'cd757f57-39b9-55dd-990f-dee779beffcd', 'ru', 'Салат с диким рисом, рукколой, фетой, вишней и миндалём', 'Сытный салат из дикого риса с рукколой, базиликом, сушёной вишней, обжаренным миндалём и фетой в лимонной заправке с горчицей и мёдом. Без глютена.', '<ol><li>Доведите до кипения большую кастрюлю воды, всыпьте промытый дикий рис и варите 40–55 минут до мягкости с лёгким сопротивлением. Слейте воду, верните рис в кастрюлю, накройте на 10 минут и остудите.</li><li>Прогрейте 1 ч. л. масла на слабом огне, добавьте миндаль и щепотку соли и обжаривайте 4–5 минут до лёгкой золотистости, помешивая. Остудите.</li><li>Взбейте заправку: масло, лимонный сок, горчицу, мёд, чеснок, соль и перец.</li><li>В большой миске соедините остывший рис, рукколу, базилик, миндаль, вишню и фету, влейте заправку, перемешайте и досолите. Оставьте на 10 минут.</li></ol><p><em>Дайте настояться 10 минут перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('10e2e35b-8dc1-5753-ac45-4e0d7c92ff32', 'cd757f57-39b9-55dd-990f-dee779beffcd', 'en', 'Arugula and wild rice salad with feta, cherries and almonds', 'A hearty gluten-free wild rice salad with arugula, basil, dried tart cherries, toasted almonds and feta in a zippy lemon-Dijon dressing.', '<ol><li>Boil a large pot of water, add the rinsed wild rice and boil 40–55 minutes until tender with a light bite. Drain, return to the pot, cover for 10 minutes, then cool.</li><li>Warm 1 tsp oil over medium-low, add the almonds and a pinch of salt and toast 4–5 minutes, stirring, until lightly golden; cool.</li><li>Whisk the dressing: olive oil, lemon juice, Dijon, honey, garlic, salt and pepper.</li><li>In a large bowl combine the cooled rice, arugula, basil, almonds, cherries and feta, toss with the dressing and adjust the seasoning. Let rest 10 minutes.</li></ol><p><em>Let it rest 10 minutes before serving.</em></p>', CURRENT_TIMESTAMP),
  ('73133645-6d48-5caf-9022-56de2d6fc818', '909126c2-9c4e-57b8-80ec-cfd7181022c5', 'ru', 'Колбаски с картофелем и морковью в медово-горчичной глазури на противне', 'Колбаски, картофель и морковь, запечённые на одном противне с мёдом и зернистой горчицей. Ужин в одной посуде из простых продуктов.', '<ol><li>Разогрейте духовку до 190 °C. На большом противне смешайте колбаски, картофель, нарезанную кусками морковь, мёд, горчицу, масло, соль и перец.</li><li>Запекайте 35 минут, пока колбаски не прожарятся, а картофель не станет золотистым. Подавайте с горошком.</li></ol><p><em>Подайте с зелёным горошком.</em></p>', CURRENT_TIMESTAMP),
  ('0b218591-3d2e-59d5-9d5a-9c9022564f09', '909126c2-9c4e-57b8-80ec-cfd7181022c5', 'en', 'Honey mustard sausage, potato and carrot traybake', 'Sausages, potatoes and carrots roasted on one tray in a honey and wholegrain mustard glaze. An easy one-pan dinner from cheap ingredients.', '<ol><li>Heat the oven to 375 °F (190 °C). Toss the sausages, potatoes, chopped carrots, honey, mustard, oil and plenty of seasoning together on a large tray.</li><li>Roast 35 minutes until the sausages are cooked through and the potatoes golden. Serve with peas.</li></ol><p><em>Serve with green peas.</em></p>', CURRENT_TIMESTAMP),
  ('014b5c61-d56c-55bd-a607-096794982469', 'd8c0d16c-525a-5ee8-bdad-a57725bc2a0e', 'ru', 'Курица пири-пири с перцем и картофелем из батата на противне', 'Куриные бёдра, сладкий перец и красный лук в маринаде из паприки, зиры, мёда, лайма и чеснока, запечённые с хрустящими палочками батата.', '<ol><li>Разогрейте духовку до 200 °C. Смешайте в большой миске специи, мёд, цедру и сок лайма, уксус, чеснок и масло, посолите и поперчите.</li><li>Обваляйте в маринаде куриные бёдра, перец и красный лук. Если есть время, оставьте мариноваться на 1 час в холодильнике.</li><li>Выложите курицу и овощи на одну половину большого противня и запекайте 25 минут.</li><li>Высыпьте картофель на другую половину и запекайте ещё 20–25 минут, пока курица не приготовится, овощи не станут мягкими с лёгкой подпалиной, а картофель — хрустящим.</li><li>Перед подачей аккуратно смешайте курицу и овощи с картофелем. Посыпьте кинзой, добавьте йогурт и лайм.</li></ol><p><em>Смешайте курицу и овощи с картофелем перед подачей, добавьте кинзу, йогурт и дольки лайма.</em></p>', CURRENT_TIMESTAMP),
  ('103ebc04-9312-564f-b53f-055df750bbac', 'd8c0d16c-525a-5ee8-bdad-a57725bc2a0e', 'en', 'Piri-piri chicken and sweet potato fry traybake', 'Chicken thighs, peppers and red onion in a paprika, cumin, honey, lime and garlic marinade, roasted with crisp sweet potato fries on one tray.', '<ol><li>Heat the oven to 400 °F (200 °C). Mix the spices, honey, lime zest and juice, vinegar, garlic and oil in a large bowl and season.</li><li>Toss the chicken thighs, peppers and red onion in the marinade. Chill 1 hour to marinate if you have time.</li><li>Arrange the chicken and veg over one side of a large tray and bake 25 minutes.</li><li>Tip the sweet potato fries onto the other side and roast another 20–25 minutes until the chicken is cooked, the veg softened and lightly charred and the fries crisp.</li><li>Just before serving gently mix the chicken and veg into the fries. Top with coriander, yogurt and lime wedges.</li></ol><p><em>Toss the chicken and veg with the fries just before serving, with coriander, yogurt and lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('4920c3d8-61cb-5900-a09b-6e111d02c18f', '78111775-7e6d-5528-aa7f-0b88fd4be820', 'ru', 'Мексиканский суп-тако с говяжьим фаршем и фасолью', 'Густой суп с говяжьим фаршем, чёрной и смешанной фасолью, кукурузой, томатами и мексиканскими специями. Добавки подаются отдельно.', '<ol><li>В глубокой кастрюле на среднем-сильном огне разогрейте 2 ст. л. масла. Обжарьте фарш со всеми специями и орегано 5–7 минут, разбивая комки, переложите в миску.</li><li>Убавьте огонь до среднего, влейте остальное масло и обжарьте лук 6–8 минут. Добавьте чеснок, стебли кинзы и томатную пасту на 3–4 минуты, пока паста не потемнеет.</li><li>Верните фарш, добавьте халапеньо, бульон, томаты, обе фасоли, кукурузу и кукурузную муку. Перемешайте, доведите до слабого кипения и варите 25–30 минут до небольшого уваривания.</li><li>Посолите, посыпьте листьями кинзы и подавайте с гарнирами.</li></ol><p><em>Подайте со сметаной, авокадо, красным луком, тёртым сыром и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('8cf1ed39-9a35-5baf-adb5-b193a7081458', '78111775-7e6d-5528-aa7f-0b88fd4be820', 'en', 'Beef and bean taco soup', 'A hearty soup of beef mince, black and mixed beans, sweetcorn, tomatoes and Mexican spices, with the toppings served on the side.', '<ol><li>Heat 2 tbsp of the oil in a large deep pot over medium-high. Brown the beef with all the spices and oregano for 5–7 minutes, breaking it up, and move to a bowl.</li><li>Reduce to medium, add the remaining oil and cook the onion 6–8 minutes until soft. Add the garlic, coriander stems and tomato purée for 3–4 minutes until the purée darkens.</li><li>Return the beef and add the jalapeños, stock, tomatoes, both beans, sweetcorn and cornmeal. Stir, bring to a gentle simmer and cook 25–30 minutes until slightly reduced.</li><li>Season, scatter with coriander leaves and serve with the toppings.</li></ol><p><em>Serve with sour cream, avocado, red onion, grated cheddar and coriander.</em></p>', CURRENT_TIMESTAMP),
  ('9fbe2e0b-33ab-5c4e-9635-cc45417584c7', 'e4de17c9-0778-5a2e-9619-cd70b4e7e783', 'ru', 'Салат из раздавленного запечённого картофеля с фетой, укропом и маринованным луком', 'Отварной и запечённый до хруста мелкий картофель с фетой, укропом, горчичной заправкой и маринованным красным луком. Тёплый гарнир к мясу и рыбе.', '<ol><li>Залейте тонко нарезанный лук уксусом, сахаром, щепоткой соли и 2 ст. л. кипятка, накройте и оставьте мариноваться минимум на 30 минут.</li><li>Варите картофель в подсоленной воде 15–20 минут до мягкости, слейте. Разогрейте духовку до 200 °C.</li><li>Выложите картофель на противень, придавите донышком смазанного маслом стакана, чтобы раздавить, в один слой. Полейте 4 ст. л. масла, посолите и запекайте 20–25 минут до золотистых хрустящих краёв.</li><li>Слейте жидкость с лука, взбейте её с нерафинированным маслом, горчицей и большей частью укропа. Выложите картофель на блюдо, раскрошите фету, полейте заправкой, посыпьте остатками укропа и маринованным луком.</li></ol><p><em>Подайте как гарнир к мясу или рыбе на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('b20fc521-02f1-5ee5-9a8f-ab67926fa247', 'e4de17c9-0778-5a2e-9619-cd70b4e7e783', 'en', 'Smashed baby potato, feta and dill salad with pickled red onion', 'Boiled then roasted-until-crisp baby potatoes with feta, dill, a mustard dressing and pickled red onion, a warm side for grilled meat or fish.', '<ol><li>Put the sliced onion in a bowl with the vinegar, sugar, a pinch of salt and 2 tbsp boiling water, cover and pickle at least 30 minutes.</li><li>Boil the potatoes in salted water 15–20 minutes until tender and drain. Heat the oven to 400 °F (200 °C).</li><li>Tip onto a tray and press with the oiled base of a glass to squash in a single layer. Drizzle with 4 tbsp oil, season and roast 20–25 minutes until golden and crisp.</li><li>Drain the onions, reserving the liquid, and whisk it with the extra virgin oil, mustard and most of the dill. Pile the potatoes on a platter, crumble over the feta, pour over the dressing and scatter with the remaining dill and the onions.</li></ol><p><em>Serve alongside grilled meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('56cbf4e4-3db6-5a37-9a7d-333b8807d3d2', '66b0cab0-667b-5655-ab1f-2bde3e06e3a5', 'ru', 'Острый салат из фасоли с кукурузой и лаймом', 'Консервированная фасоль с помидорами черри, кукурузой, красным луком, огурцом, петрушкой и мятой в остро-лаймовой заправке. Берите на обед или как гарнир к барбекю.', '<ol><li>Снимите цедру с одного лайма в небольшую миску, у обоих лаймов срежьте кожуру с белой частью и нарежьте дольки в большую миску. Выжмите сок из остатков в миску с цедрой, добавьте масло и чили или таджин.</li><li>К дольками лайма добавьте фасоль, помидоры, кукурузу, лук, огурец, петрушку и мяту и перемешайте, посолите и поперчите.</li><li>Подавайте, смешав с заправкой, посыпав ломтиками халапеньо. Для обеда с собой налейте заправку на дно контейнера, сверху фасолевую смесь, чипсы и халапеньо.</li></ol><p><em>Добавьте кукурузные чипсы и ломтики халапеньо перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('5b4dd2cd-34c0-5fd5-9037-5dd683385d44', '66b0cab0-667b-5655-ab1f-2bde3e06e3a5', 'en', 'Spicy lime and mixed bean salad', 'Canned beans with cherry tomatoes, sweetcorn, red onion, cucumber, parsley and mint in a spicy lime dressing. Good for a lunchbox or a barbecue side.', '<ol><li>Zest one lime into a small bowl, peel both limes and cut out the segments into a large bowl. Squeeze the juice from the leftovers into the zest bowl and mix in the oil and chilli powder or tajín.</li><li>Add the beans, tomatoes, sweetcorn, onion, cucumber, parsley and mint to the lime segments, mix, and season.</li><li>Toss with the dressing and top with jalapeño slices. For a packed lunch, layer the dressing, the bean mixture and the jalapeños in a container and shake before serving.</li></ol><p><em>Add corn tortilla chips and jalapeño slices before serving.</em></p>', CURRENT_TIMESTAMP),
  ('3027c505-31bc-5052-a37a-bc245ba84c18', '3f0730db-07d5-5c44-9960-c891f56f9d42', 'ru', 'Тушёная курица с бататом, перцем и арахисовой пастой', 'Сытное рагу из куриных бёдер, батата и сладкого перца в соусе из лука, имбиря, чеснока, зиры, томатов и арахисовой пасты. Хорошо замораживается.', '<ol><li>В большой глубокой сковороде на среднем огне разогрейте масло и около 5 минут обжарьте куриные бёдра со всех сторон. Переложите на тарелку.</li><li>Убавьте огонь, обжарьте лук 10–12 минут до мягкости без золотистого цвета. Добавьте имбирь и чеснок на минуту, затем зиру ещё на минуту.</li><li>Добавьте батат и обжаривайте несколько минут. Вмешайте арахисовую пасту, влейте бульон и томаты (ополосните банку водой и добавьте).</li><li>Добавьте замороженный перец, верните курицу и готовьте без крышки 25–35 минут, регулярно помешивая, пока курица не приготовится, а соус не загустеет.</li><li>Посыпьте кинзой и арахисом и подавайте.</li></ol><p><em>Посыпьте кинзой и рублеными арахисом.</em></p>', CURRENT_TIMESTAMP),
  ('f11f0bbf-414d-5b84-95a0-6813e198de48', '3f0730db-07d5-5c44-9960-c891f56f9d42', 'en', 'Chicken, sweet potato and peanut stew', 'A filling stew of chicken thighs, sweet potato and peppers in a sauce of onion, ginger, garlic, cumin, tomatoes and peanut butter. Freezes well.', '<ol><li>Heat the oil in a large deep pan over medium heat and brown the chicken thighs all over, about 5 minutes. Remove, leaving the oil.</li><li>Reduce the heat and cook the onions 10–12 minutes until soft but not golden. Add the ginger and garlic for a minute, then the cumin for another minute.</li><li>Add the sweet potatoes and fry a few minutes. Stir in the peanut butter and pour in the stock and tomatoes, swilling out the can with water.</li><li>Add the frozen peppers, return the chicken and cook uncovered 25–35 minutes, stirring regularly, until the chicken is cooked and the sauce thickened.</li><li>Scatter with coriander and peanuts and serve.</li></ol><p><em>Scatter with coriander and chopped peanuts.</em></p>', CURRENT_TIMESTAMP),
  ('49578bd1-9d5d-5da4-bf3c-edb715c12d26', 'a098502c-0945-5426-913a-333fe00b4acd', 'ru', 'Говядина с брокколи в соево-медовом соусе', 'Быстрая замена доставки: тонкие ломтики говяжьего стейка и брокколи в глянцевом соусе из соевого соуса, мёда, кунжутного масла, чеснока и имбиря.', '<ol><li>Разогрейте половину оливкового масла в большой сковороде на средне-сильном огне и 2 минуты обжарьте брокколи. Добавьте немного воды, накройте и готовьте 3 минуты до мягкости. Переложите в миску.</li><li>Смешайте соевый соус, мёд, кунжутное масло, чеснок, имбирь и кукурузный крахмал.</li><li>Разогрейте остальное масло на сильном огне и жарьте тонко нарезанный стейк 4 минуты, помешивая, до румяного цвета. Влейте соус и готовьте ещё 2 минуты, пока он не загустеет и не покроет мясо.</li><li>Добавьте брокколи, перемешайте с соусом и подавайте с рисом и кунжутом.</li></ol><p><em>Подайте с отварным рисом, посыпав кунжутом (КБЖУ без риса).</em></p>', CURRENT_TIMESTAMP),
  ('43694a95-e7bc-51e2-a13b-dd2d5742bb2b', 'a098502c-0945-5426-913a-333fe00b4acd', 'en', 'Beef and broccoli in soy honey sauce', 'A 20-minute takeaway swap: thin slices of steak and broccoli in a glossy sauce of soy, honey, sesame oil, garlic and ginger.', '<ol><li>Heat half the olive oil in a large pan over medium-high and fry the broccoli 2 minutes. Add a splash of water, cover and cook 3 minutes until soft. Move to a bowl.</li><li>Whisk together the soy sauce, honey, sesame oil, garlic, ginger and cornflour.</li><li>Heat the remaining oil on high and fry the thinly sliced steak 4 minutes, turning, until browned. Pour in the sauce and cook 2 minutes more until reduced and thick enough to coat the steak.</li><li>Toss in the broccoli to coat in the sauce and serve with rice and sesame seeds.</li></ol><p><em>Serve with steamed rice and sesame seeds (nutrition is without rice).</em></p>', CURRENT_TIMESTAMP),
  ('2619e2bf-9375-556a-9476-382fb2a23642', 'b72ebc28-2789-59c9-9d7a-a60312baadec', 'ru', 'Китайский яичный суп с зелёным луком', 'Прозрачный куриный бульон с ароматом лука, чеснока и кунжутного масла и нежными яичными нитями.', '<ol><li>Доведите бульон до кипения, убавьте огонь до среднего и добавьте белые части зелёного лука, чеснок, кунжутное масло, ½ ч. л. соли, сахар и белый перец. Варите 10 минут, затем выньте лук и чеснок.</li><li>Разведите 2 ст. л. кукурузного крахмала в 2 ст. л. холодной воды и вмешайте в суп.</li><li>Взбейте яйца с 1 ч. л. крахмала. Размешайте суп круговыми движениями, чтобы получился водоворот, и тонкой струйкой влейте яйца, постоянно помешивая: яйцо схватывается нитями.</li><li>Разлейте по тарелкам и посыпьте зелёным луком.</li></ol><p><em>Посыпьте зелёным луком и подавайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('f437507b-c50f-5900-910d-34490fd27f7f', 'b72ebc28-2789-59c9-9d7a-a60312baadec', 'en', 'Chinese egg drop soup with scallions', 'A clear chicken broth scented with spring onion, garlic and sesame oil, with soft ribbons of egg.', '<ol><li>Bring the stock to the boil, reduce to medium and add the spring onion whites, garlic, sesame oil, ½ tsp salt, sugar and white pepper. Simmer 10 minutes, then remove the onion and garlic.</li><li>Mix 2 tbsp of cornflour with 2 tbsp of cold water into a loose paste and stir it into the soup.</li><li>Whisk the eggs with the remaining 1 tsp of cornflour. Swirl the soup in circles and drizzle in the egg mixture in a thin stream, stirring continuously so it sets in ribbons.</li><li>Ladle into bowls and scatter with the spring onion greens.</li></ol><p><em>Scatter with the green onion tops and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('61051d90-12cb-5721-9b92-dbb2773289d1', 'ac23a1d4-adb2-5154-93c4-c01e6ab0dd7c', 'ru', 'Курица тикка масала в томатно-йогуртовом соусе', 'Кусочки куриной грудки в ароматном соусе из томатов, молока и йогурта с имбирём, чесноком, зирой и гарам масалой. Облегчённая версия.', '<ol><li>Разогрейте масло в глубокой сковороде на среднем огне и около 3 минут обжарьте лук до золотистого цвета.</li><li>Добавьте имбирь на минуту, затем чеснок ещё на минуту. Всыпьте зиру, гарам масалу, куркуму, чили и соль и перемешивайте около 2 минут до аромата.</li><li>Влейте томаты и молоко и томите на слабом огне около 10 минут до загустения.</li><li>Смешайте йогурт с ½ стакана соуса, чтобы он не свернулся, и вмешайте в сковороду.</li><li>Добавьте кусочки курицы и варите на слабом огне 10–15 минут до готовности. Посыпьте кинзой и подавайте с рисом или наан.</li></ol><p><em>Подавайте с рисом басмати или лепёшкой наан, посыпав кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('9e6731da-9ae9-5696-bdb1-ba3236f29e8d', 'ac23a1d4-adb2-5154-93c4-c01e6ab0dd7c', 'en', 'Light chicken tikka masala', 'Tender chunks of chicken breast in an aromatic yogurt, tomato and milk sauce with ginger, garlic, cumin and garam masala. A lightened version.', '<ol><li>Heat the oil in a large heavy skillet over medium and cook the onion about 3 minutes until golden.</li><li>Stir in the ginger for 1 minute, then the garlic for another minute; add the cumin, garam masala, turmeric, chili powder and salt and stir about 2 minutes until fragrant.</li><li>Stir in the tomatoes and milk and simmer on low about 10 minutes until the sauce thickens.</li><li>Temper the yogurt by mixing it with ½ cup of the sauce, then stir it into the pan.</li><li>Add the chicken and simmer 10–15 minutes until cooked through. Top with cilantro and serve with rice or naan.</li></ol><p><em>Serve with basmati rice or naan, topped with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('d9a4f7d1-42b4-5236-8412-a75291fcf951', 'e61f4d7e-3dc0-56b7-a02b-25747afcd5ef', 'ru', 'Суп-пюре из зелёного горошка с мятой и лимонным йогуртом', 'Быстрый свежий суп из зелёного горошка с зелёным луком, мятой и базиликом, поданный с ложкой йогурта с лимонной цедрой и кориандром.', '<ol><li>В кастрюле на среднем огне разогрейте масло, 4 минуты тушите зелёный лук с базиликом до мягкости.</li><li>Добавьте горошек на минуту, влейте бульон, доведите до кипения и варите 4–5 минут до мягкости горошка.</li><li>Снимите с огня и пюрируйте порциями в блендере вместе с мятой до гладкости.</li><li>Верните суп в кастрюлю, добавьте 2 ст. л. лимонного сока, посолите и поперчите. Держите тёплым.</li><li>Смешайте йогурт с лимонной цедрой, кориандром и щепоткой соли и перед подачей добавьте ложку в каждую тарелку.</li></ol><p><em>Подавайте горячим или тёплым с йогуртовой заправкой.</em></p>', CURRENT_TIMESTAMP),
  ('95adf219-4d7f-5779-a28a-b5acfed3d5f5', 'e61f4d7e-3dc0-56b7-a02b-25747afcd5ef', 'en', 'Green pea soup with mint and lemon yogurt', 'A quick fresh green pea soup with scallions, mint and basil, finished with a dollop of yogurt with lemon zest and coriander.', '<ol><li>Heat the oil in a medium pot over medium and cook the scallions and basil 4 minutes until softened.</li><li>Add the peas for 1 minute, pour in the broth, bring to a simmer and cook 4–5 minutes until the peas are tender.</li><li>Remove from the heat and purée in batches in a blender with the mint until smooth.</li><li>Return to the pot, stir in 2 tbsp lemon juice, season with salt and pepper and keep warm.</li><li>Mix the yogurt with the lemon zest, coriander and a pinch of salt and dollop onto each bowl before serving.</li></ol><p><em>Serve hot or warm with the yogurt topping.</em></p>', CURRENT_TIMESTAMP),
  ('b3210071-2ab2-5181-9092-787e74fb9b5d', '3e47e5e3-3349-5b9e-8bbd-ae7cf1b80ac0', 'ru', 'Куриные бёдра с овощами и итальянскими травами на противне', 'Куриные бёдра без костей с кабачком, морковью, болгарским перцем и красным луком, замаринованные в итальянских травах с оливковым маслом и запечённые на противне.', '<ol><li>В большой миске смешайте соль, луковый порошок, орегано, базилик, тимьян, сахар, перец, чеснок, масло и уксус. Посолите курицу ½ ч. л. соли, добавьте её и нарезанные овощи и хорошо перемешайте. Маринуйте 30 минут или до ночи.</li><li>Разогрейте духовку до 230 °C, смажьте два противня или застелите пергаментом.</li><li>Разложите курицу и овощи по противням в один слой так, чтобы они не касались друг друга.</li><li>Запекайте около 20 минут, переверните и запекайте ещё 10 минут до золотистых мягких овощей и готовой курицы. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте горячими.</em></p>', CURRENT_TIMESTAMP),
  ('6102150f-cf1c-53e3-8755-17775de1053b', '3e47e5e3-3349-5b9e-8bbd-ae7cf1b80ac0', 'en', 'Sheet pan Italian chicken thighs and vegetables', 'Boneless chicken thighs with zucchini, carrots, bell peppers and red onion marinated in Italian herbs and olive oil and roasted on a sheet pan.', '<ol><li>In a large bowl mix the salt, onion powder, oregano, basil, thyme, sugar, pepper, garlic, oil and vinegar. Season the chicken with ½ tsp salt, add it with the vegetables and toss well. Marinate 30 minutes up to overnight.</li><li>Preheat the oven to 450 °F (230 °C) and oil two sheet pans or line with parchment.</li><li>Arrange the chicken and vegetables on the pans in a single layer without touching.</li><li>Bake about 20 minutes, turn and bake 10 more until roasted and tender. Sprinkle with parsley.</li></ol><p><em>Sprinkle with parsley and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('1e3eba6b-5a0d-5fca-a678-f13874e04da0', 'b3374b0b-c155-5835-8aff-b6f6e792d84a', 'ru', 'Салат нисуаз с запечённым лососем, картофелем, фасолью и яйцом', 'Сытный салат: запечённый под горчицей лосось, молодой картофель, стручковая фасоль, варёные яйца, оливки и артишоки на листьях салата с горчичной заправкой.', '<ol><li>Разогрейте духовку до 160 °C. Смешайте луковый порошок, горчицу, ½ ч. л. соли и ¼ ч. л. перца. Намажьте 1 ст. л. смеси на каждый кусок лосося, остальное отложите. Запекайте рыбу 15–20 минут, остудите и разделите на крупные куски.</li><li>Оставшуюся горчичную смесь смешайте с белым винным уксусом и оливковым маслом — это заправка.</li><li>Варите картофель в подсоленной воде 20–25 минут до мягкости, за последние 5 минут добавьте стручковую фасоль. Слейте воду, ополосните холодной водой. Картофель разрежьте пополам, охладите.</li><li>Выложите листья салата на блюдо, сверху — группами лосось, картофель, фасоль, яйца, оливки и артишоки. Полейте заправкой.</li></ol><p><em>Выкладывайте компоненты отдельными группами и поливайте заправкой.</em></p>', CURRENT_TIMESTAMP),
  ('6003f788-18bc-5415-9027-071d2a865bff', 'b3374b0b-c155-5835-8aff-b6f6e792d84a', 'en', 'Salmon Niçoise salad with potatoes, green beans and eggs', 'A hearty composed salad of mustard-baked salmon, baby potatoes, green beans, boiled eggs, olives and artichokes on lettuce with a whole-grain mustard vinaigrette.', '<ol><li>Preheat the oven to 325 °F (160 °C). Mix the onion powder, mustard, ½ tsp salt and ¼ tsp pepper, spread 1 tbsp on each salmon fillet and reserve the rest. Bake 15–20 minutes, cool and flake into large pieces.</li><li>Mix the remaining mustard mixture with the white wine vinegar and olive oil for the vinaigrette.</li><li>Boil the potatoes in salted water 20–25 minutes until tender, adding the green beans for the last 5 minutes. Drain and rinse with cold water, halve the potatoes and cool.</li><li>Lay the lettuce on a platter and top in groups with the salmon, potatoes, green beans, eggs, olives and artichokes. Drizzle with the vinaigrette.</li></ol><p><em>Arrange the components in groups and drizzle with the vinaigrette.</em></p>', CURRENT_TIMESTAMP),
  ('ac4e99f5-5ad9-506d-b0f9-a6c837d403f2', '97000f3f-fe55-58aa-83c2-3013df2edd14', 'ru', 'Морковный суп-пюре с имбирём и сметаной', 'Нежный суп из моркови и лука с имбирём, пюрированный со сметаной. Легче большинства сливочных супов.', '<ol><li>В кастрюле на среднем огне растопите масло и 5–6 минут тушите лук до мягкости.</li><li>Добавьте бульон, морковь и имбирь, накройте, доведите до кипения, убавьте огонь и варите около 30 минут до мягкости моркови. (В скороварке: 15 минут под высоким давлением.)</li><li>Добавьте сметану и пюрируйте блендером до гладкости. Доведите до кипения, посолите и поперчите.</li></ol><p><em>Подавайте со ложкой сметаны и шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('da3209a2-a17b-5556-8a03-40804328e9ba', '97000f3f-fe55-58aa-83c2-3013df2edd14', 'en', 'Carrot ginger soup with a touch of sour cream', 'Silky soup of carrots and onion with fresh ginger, blended with a little sour cream. Lighter than most creamy soups.', '<ol><li>In a pot melt the butter over medium and cook the onion 5–6 minutes until soft.</li><li>Add the broth, carrots and ginger, cover, bring to a boil, reduce and simmer about 30 minutes until the carrots are soft (pressure cooker: 15 minutes on high).</li><li>Add the sour cream and blend until smooth, bring back to a boil and season with salt and white pepper.</li></ol><p><em>Garnish with a spoon of sour cream and chives.</em></p>', CURRENT_TIMESTAMP),
  ('955d43a8-375e-561a-ae46-b9ef4daee8ce', 'c50d26c4-6570-5825-b95d-0857b05fc92e', 'ru', 'Куриные голени и бёдра с куркумой и бататом в духовке', 'Куриные голени и бёдра запекаются на подушке из карамелизованных батата и шалота с куркумой, имбирём и лимонным соком, с каплей белого вина.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>В большой миске перемешайте шалот и батат с чесноком, 1 ч. л. куркумы, чесночным порошком, имбирём, 1 ч. л. соли и маслом. Выложите ровным слоем в форму 23×33 см.</li><li>В той же миске приправьте голени и бёдра лимонным соком, оставшейся солью и куркумой и прованскими травами. Выложите курицу на овощи, добавьте остатки маринада и влейте вино по краям формы.</li><li>Накройте фольгой и запекайте 45 минут, затем переверните курицу и батат и запекайте ещё около 15 минут без фольги до мягкости курицы и батата. Полейте соусом из формы.</li></ol><p><em>Полейте мясо соком из формы и подавайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('98bf54e0-29b7-5b38-b897-48f45d19823f', 'c50d26c4-6570-5825-b95d-0857b05fc92e', 'en', 'Turmeric roasted chicken legs and thighs with sweet potatoes', 'Chicken drumsticks and thighs roasted on a bed of caramelized sweet potatoes and shallots with turmeric, ginger and lemon, with a splash of white wine.', '<ol><li>Preheat the oven to 425 °F (220 °C).</li><li>In a large bowl toss the shallots and sweet potatoes with the garlic, 1 tsp turmeric, garlic powder, ginger, 1 tsp salt and the oil. Spread in a 9×13 baking dish.</li><li>In the same bowl season the chicken with lemon juice, the remaining salt and turmeric and the herbs, place it over the vegetables, drizzle with any leftover marinade and pour the wine around the sides.</li><li>Cover with foil and roast 45 minutes, then turn the chicken and potatoes and roast uncovered about 15 more minutes until fork-tender. Spoon the sauce over.</li></ol><p><em>Spoon the pan sauce over the chicken and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('309e84b8-d91f-51c7-942c-5c3930d04468', 'ad1fc76a-9c49-56c2-8ef3-fcaf5eed605a', 'ru', 'Курица с брокколи, спаржей и морковью в апельсиново-соевом соусе', 'Стир-фрай из кусочков куриных бёдер с овощами в ароматном соусе из апельсинового сока, мёда, соевого соуса, имбиря и чеснока.', '<ol><li>Взбейте холодную воду с крахмалом, добавьте апельсиновый сок, соевый соус, кунжутное масло, имбирь, чеснок и мёд. Четверть смеси влейте в нарезанную кусочками курицу и оставьте на 15–30 минут.</li><li>В большой сковороде или воке на сильном огне вскипятите стакан воды, добавьте брокколи, морковь и спаржу, накройте и готовьте на пару 2 минуты до яркого цвета и хруста. Переложите овощи в миску, сковороду протрите.</li><li>Разогрейте масло на сильном огне и минуту обжарьте лук, затем выложите маринованную курицу в один слой и не трогайте 2 минуты до румяности, затем переверните.</li><li>Когда курица почти готова, влейте оставшийся соус и варите 3 минуты до загустения. Верните овощи и готовьте ещё минуту. Посыпьте кунжутом и подавайте с рисом.</li></ol><p><em>Подайте на горячем рисе, посыпав обжаренным кунжутом (КБЖУ без риса).</em></p>', CURRENT_TIMESTAMP),
  ('268094c9-f455-509e-977f-cb831b4943b0', 'ad1fc76a-9c49-56c2-8ef3-fcaf5eed605a', 'en', 'Orange chicken with broccoli, asparagus and carrots', 'A stir-fry of chicken thigh pieces and vegetables in a fragrant sauce of orange juice, honey, soy sauce, ginger and garlic.', '<ol><li>Whisk the cold water with the starch, then the orange juice, soy sauce, sesame oil, ginger, garlic and honey. Pour a quarter over the chicken pieces and marinate 15–30 minutes.</li><li>In a wok or large pan on high heat bring ½ cup of water to a boil, add the broccoli, carrot and asparagus, cover and steam 2 minutes until crisp-tender and bright green. Move to a bowl and wipe the pan.</li><li>Heat the oil on high, cook the onion 1 minute, then add the marinated chicken in a single layer and leave 2 minutes to brown before stirring.</li><li>When the chicken is almost cooked, pour in the reserved sauce and simmer 3 minutes until thickened. Stir in the vegetables and cook another minute. Sprinkle with sesame seeds and serve over rice.</li></ol><p><em>Serve over hot rice with toasted sesame seeds (nutrition is without rice).</em></p>', CURRENT_TIMESTAMP),
  ('1ee964fc-b465-5322-8107-c08b5504cfa9', '2c6cf3c7-2b03-5d29-886b-712146d1e5c9', 'ru', 'Запечённые фрикадельки из индейки в соусе терияки', 'Нежные фрикадельки из фарша индейки с имбирём и зелёным луком, запечённые и политые домашним сладко-солёным соусом терияки.', '<ol><li>Разогрейте духовку до 200 °C, застелите противень пергаментом.</li><li>Смешайте фарш с панировочными сухарями, зелёным луком, яйцом, имбирём, чесноком, кунжутным маслом, солью и перцем только до однородности. Масса должна быть влажной; если суховата, добавьте воды или молока по 1 ст. л.</li><li>Скатайте шарики диаметром 3–4 см (около 28 штук) и запекайте 13–18 минут до прозрачного сока (165 °C внутри).</li><li>Пока запекаются, на слабом огне 3–5 минут проварите ингредиенты соуса, часто помешивая, до лёгкого загустения.</li><li>Переложите тёплые фрикадельки в миску, полейте горячим соусом и перемешайте. Подавайте с рисом.</li></ol><p><em>Подайте с рисом, посыпав кунжутом и зелёным луком. Годятся и как закуска на шпажках.</em></p>', CURRENT_TIMESTAMP),
  ('b6369d06-d035-5a55-81e9-1d5fc17af92d', '2c6cf3c7-2b03-5d29-886b-712146d1e5c9', 'en', 'Baked turkey meatballs in teriyaki sauce', 'Tender turkey meatballs with ginger and green onion, baked and tossed in an easy homemade sweet-savoury teriyaki sauce.', '<ol><li>Preheat the oven to 400 °F (200 °C) and line a baking sheet with parchment.</li><li>Mix the turkey, panko, green onion, egg, ginger, garlic, sesame oil, salt and pepper just until combined. It should feel moist; add milk or water by the tablespoon if dry.</li><li>Roll into 1¼–1½ inch balls (about 28) and bake 13–18 minutes until the juices run clear (165 °F inside).</li><li>Meanwhile simmer the sauce ingredients 3–5 minutes, stirring often, until slightly thickened.</li><li>Toss the warm meatballs with the warm sauce and serve over rice.</li></ol><p><em>Serve over rice with sesame seeds and green onion, or on toothpicks as an appetizer.</em></p>', CURRENT_TIMESTAMP),
  ('3061d2cb-ae65-5434-9daa-a38c950ec934', '4213bc6f-5f9b-5b7b-93d8-7c91518456ca', 'ru', 'Шампиньоны, фаршированные курицей, сливочным сыром и моцареллой', 'Шляпки шампиньонов с начинкой из курицы, сливочного сыра, обжаренного лука и ножек грибов, запечённые под тёртой моцареллой.', '<ol><li>Протрите шляпки влажным бумажным полотенцем, удалите ножки и выньте часть мякоти. Ножки и мякоть мелко нарубите. Разогрейте духовку до 200 °C.</li><li>Мелко нарежьте лук. На среднем-сильном огне 10–12 минут обжарьте на масле лук с нарубленными грибами до мягкости и золотистости, добавьте ½ ч. л. соли.</li><li>В миске разомните вилкой сливочный сыр с хорошо отжатой курицей и перцем, вмешайте горячую грибную смесь.</li><li>Начините шляпки горкой, посыпьте щепоткой моцареллы и запекайте 10–12 минут до мягкости и лёгкого сока. Не пересушивайте, иначе грибы станут водянистыми.</li></ol><p><em>Подавайте горячими; остатки начинки получаются отличной закуской-пастой.</em></p>', CURRENT_TIMESTAMP),
  ('ca451bd9-67be-5e05-bf9c-8aa8998666b2', '4213bc6f-5f9b-5b7b-93d8-7c91518456ca', 'en', 'Chicken and cream cheese stuffed mushrooms', 'Mushroom caps stuffed with chicken, cream cheese, sautéed onion and chopped mushroom stems, baked under grated mozzarella.', '<ol><li>Wipe the mushrooms with a damp paper towel, remove the stems and scoop out some of the centre. Finely chop the stems and scooped pieces. Preheat the oven to 400 °F (200 °C).</li><li>Finely chop the onion. Sauté it with the chopped mushrooms in the butter over medium-high 10–12 minutes until soft and starting to turn golden, adding ½ tsp salt.</li><li>Mash the cream cheese with the well-drained chicken and pepper using a fork, then stir in the hot mushroom mixture.</li><li>Fill the caps with a dome of filling, top each with a pinch of mozzarella and bake 10–12 minutes until soft and just starting to look juicy. Do not overbake.</li></ol><p><em>Serve hot; leftover filling makes an excellent dip.</em></p>', CURRENT_TIMESTAMP),
  ('5763fb23-f369-5ec2-8653-cf19ce2350f4', '9d18ad0e-2c65-509a-b3d3-ccffd2670b83', 'ru', 'Жареный рис с капустой, морковью и соевым соусом', 'Быстрый гарнир: обжаренная капуста, морковь и лук, смешанные с вчерашним жасминовым рисом, сливочным маслом, соевым соусом и кунжутным маслом.', '<ol><li>Если нет готового риса, промойте 1 стакан риса несколько раз, сварите с 1 ст. л. масла и ½ ч. л. соли и остудите.</li><li>Тонко нашинкуйте капусту, мелко нарежьте лук, натрите морковь.</li><li>В очень горячем воке или тяжёлой сковороде на масле 7–10 минут обжаривайте капусту, морковь и лук, постоянно помешивая, пока капуста не уменьшится в 2–3 раза и не станет золотистой.</li><li>Добавьте сливочное масло и 3 стакана варёного риса, перемешайте, влейте соевый соус и кунжутное масло, при необходимости посолите и поперчите. Подавайте.</li></ol><p><em>Подайте с мясом, котлетами или как самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('df0edada-05dc-5f01-b118-3f793431a632', '9d18ad0e-2c65-509a-b3d3-ccffd2670b83', 'en', 'Cabbage and carrot fried rice with soy sauce', 'A quick side of sautéed cabbage, carrot and onion tossed with day-old jasmine rice, butter, soy sauce and sesame oil.', '<ol><li>If you have no cooked rice, rinse 1 cup of rice several times and cook it with 1 tbsp butter and ½ tsp salt, then cool.</li><li>Finely slice the cabbage, dice the onion and grate the carrot.</li><li>In a very hot wok or heavy skillet sauté the cabbage, carrot and onion in the oil 7–10 minutes, stirring constantly, until the cabbage shrinks to a third or half and turns golden.</li><li>Add the butter and 3 cups of cooked rice and stir, then the soy sauce and sesame oil, with salt and pepper to taste. Serve.</li></ol><p><em>Serve with meat or cutlets, or on its own.</em></p>', CURRENT_TIMESTAMP),
  ('4035f225-dc2f-55b5-8c0b-25578fcd781b', '4436d99c-306e-546a-a3f7-96486bc7dbf6', 'ru', 'Салат из краснокочанной капусты с авокадо, укропом и апельсиновой заправкой', 'Тонко нашинкованная краснокочанная капуста с авокадо, укропом и петрушкой под заправкой из масла, апельсинового и лимонного сока.', '<ol><li>Тонко нашинкуйте капусту (слайсером или острым ножом) и переложите в салатник.</li><li>Разрежьте авокадо, выньте мякоть ложкой, нарежьте кубиками и выложите на капусту.</li><li>Смешайте укроп, петрушку, масло, апельсиновый и лимонный сок, соль и перец. Перед подачей полейте салат заправкой и перемешайте.</li></ol><p><em>Заправьте непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('b71d0be5-797a-57c1-b7bb-ffbaa469d74b', '4436d99c-306e-546a-a3f7-96486bc7dbf6', 'en', 'Red cabbage and avocado salad with orange dressing', 'Finely shredded purple cabbage with diced avocado, dill and parsley in a dressing of oil, orange and lemon juice.', '<ol><li>Finely slice the cabbage with a mandoline or a sharp knife and put it in a salad bowl.</li><li>Halve the avocado, scoop out the flesh, dice it and put it over the cabbage.</li><li>Mix the dill, parsley, oil, orange and lemon juice, salt and pepper. Just before serving pour over the salad and toss.</li></ol><p><em>Dress it right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('fe79321c-1c09-5a7e-8199-45f19ee63337', '803c3477-f16c-51cc-a4a4-21ab255b6a64', 'ru', 'Салат из огурцов и авокадо с зелёным луком и лаймом', 'Пятиминутный салат из огурцов, авокадо и зелёного лука с простой заправкой из лайма и оливкового масла.', '<ol><li>В салатнике соедините нарезанные огурцы, авокадо ломтиками и нарубленный зелёный лук.</li><li>Полейте соком лайма и маслом, посолите и поперчите, аккуратно перемешайте и подавайте.</li></ol><p><em>Подавайте сразу как гарнир к мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('96278a67-ca50-58fb-8eb3-ea020b8effd3', '803c3477-f16c-51cc-a4a4-21ab255b6a64', 'en', 'Avocado cucumber salad with green onion and lime', 'A five-minute salad of cucumber, avocado and green onion with a simple lime and olive oil dressing.', '<ol><li>In a bowl combine the sliced cucumbers, avocado slices and chopped green onion.</li><li>Drizzle with the lime juice and oil, season with salt and pepper, toss gently and serve.</li></ol><p><em>Serve immediately as a side with meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('f750de78-fb88-5e67-84fc-fa02faae4e8d', '005d889d-3609-5364-9c39-40f97d5229df', 'ru', 'Фетучини альфредо с креветками в сливочном соусе', 'Паста в густом сливочном соусе с пармезаном и белым вином со сочными обжаренными креветками. Готовится за 30 минут.', '<ol><li>Отварите фетучини в подсоленной воде по инструкции, слейте и не промывайте, чтобы соус лучше держался.</li><li>Слегка посолите, поперчите и присыпьте креветки паприкой. На сильном-среднем огне разогрейте масло и обжарьте креветки в один слой по 1–2 минуты с каждой стороны до розового цвета. Переложите в миску.</li><li>В той же сковороде обжарьте на сливочном масле лук до золотистого цвета, добавьте чеснок на минуту, влейте вино и уварите на 3/4, соскребая осадок.</li><li>Влейте сливки, варите 2 минуты, добавьте пармезан и размешайте до гладкости. Не кипятите, чтобы сыр не отделился. Добавьте паприку, соль и перец.</li><li>Добавьте креветки и пасту, перемешайте и подавайте с зеленью.</li></ol><p><em>Посыпьте петрушкой или базиликом и ещё пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('dc68e01e-2e4a-5443-b6dd-98d046fbd995', '005d889d-3609-5364-9c39-40f97d5229df', 'en', 'Creamy shrimp fettuccine Alfredo', 'Pasta in a rich cream sauce with Parmesan and white wine, topped with tender seared shrimp, ready in 30 minutes.', '<ol><li>Cook the fettuccine in salted water according to the package, drain and do not rinse, so the sauce clings better.</li><li>Lightly season the shrimp with salt, pepper and paprika. Heat the oil on medium-high and sear the shrimp in one layer 1–2 minutes per side until pink. Move to a bowl.</li><li>In the same pan sauté the onion in the butter until golden, add the garlic for a minute, then pour in the wine and reduce by three quarters, scraping up the bits.</li><li>Pour in the cream, simmer 2 minutes, add the Parmesan and stir until smooth. Do not boil or the cheese will separate. Add the paprika, salt and pepper.</li><li>Add the shrimp and drained pasta, toss and serve with herbs.</li></ol><p><em>Garnish with parsley or basil and extra Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('7d42b263-7441-55f1-9e88-de71f37c4836', '103d0790-089b-53ed-82fd-3f78efbb175c', 'ru', 'Курица марбелла с черносливом, оливками и каперсами', 'Куриные бёдра на кости, томлёные с черносливом, зелёными оливками, каперсами, чесноком и орегано в бульоне с красным винным уксусом. Сладко-солёный средиземноморский вкус.', '<ol><li>Разогрейте масло в большой сковороде на сильном огне. Выложите бёдра кожей вниз, накройте и жарьте около 10 минут до тёмно-золотистого цвета.</li><li>Переверните, накройте и жарьте ещё около 5 минут. Добавьте чеснок и минуту прогрейте.</li><li>Равномерно разложите чернослив, оливки, каперсы с рассолом, лавровый лист и орегано. Посыпьте коричневым сахаром, солью и перцем, влейте бульон и уксус и доведите до кипения.</li><li>Убавьте огонь, накройте и тушите 15–20 минут до готовности курицы.</li><li>Переложите курицу на блюдо, уварите соус на сильном огне около 5 минут до лёгкого загустения и полейте мясо.</li></ol><p><em>Полейте соусом из сковороды и подайте с рисом или кускусом.</em></p>', CURRENT_TIMESTAMP),
  ('d91692fb-9439-5e55-8190-f546175a88fc', '103d0790-089b-53ed-82fd-3f78efbb175c', 'en', 'Chicken Marbella with prunes, olives and capers', 'Bone-in chicken thighs simmered with prunes, green olives, capers, garlic and oregano in broth and red wine vinegar for a sweet-salty Mediterranean flavor.', '<ol><li>Heat the oil in a large skillet over high heat, add the thighs, cover and cook about 10 minutes until deep golden brown.</li><li>Flip, cover and cook about 5 more minutes, then add the garlic for 1 minute.</li><li>Arrange the prunes, olives, capers and brine, bay leaves and oregano around the chicken. Season with brown sugar, salt and pepper, pour over the broth and vinegar and bring to a boil.</li><li>Reduce to low, cover and simmer 15–20 minutes until the chicken is cooked through.</li><li>Move the chicken to a platter, boil the sauce on high about 5 minutes until slightly thickened and spoon over the chicken.</li></ol><p><em>Spoon the pan sauce over the chicken and serve with rice or couscous.</em></p>', CURRENT_TIMESTAMP),
  ('185f0861-faf9-5710-80ba-41eaceda661a', '62de6daf-912a-5504-b659-eb0bea21e3ef', 'ru', 'Курица с тайским базиликом и чили (пад крапау)', 'Очень быстрая тайская курица: тонкие полоски грудки в устричном и соевом соусе с чесноком, острым перцем и большим количеством базилика.', '<ol><li>Смешайте курицу с устричным и соевым соусом и мариновать 10 минут.</li><li>Разогрейте сковороду или вок на средне-сильном огне, добавьте масло, чеснок и перец чили и 30 секунд обжарьте до аромата.</li><li>Увеличьте огонь до сильного, добавьте курицу и жарьте, помешивая, около 4 минут до готовности. Положите базилик и готовьте минуту, пока он не завянет.</li><li>Подавайте с рисом.</li></ol><p><em>Подавайте на варёном рисе жасмин.</em></p>', CURRENT_TIMESTAMP),
  ('f5369113-4922-5d95-9454-ff677d200275', '62de6daf-912a-5504-b659-eb0bea21e3ef', 'en', 'Thai basil chicken (pad krapow)', 'A very quick Thai dish of thin chicken breast strips in oyster and soy sauce with garlic, chili and lots of basil.', '<ol><li>Marinate the chicken with the oyster and soy sauce for 10 minutes.</li><li>Heat a nonstick skillet or wok over medium-high, add the oil, garlic and chili and cook about 30 seconds until fragrant.</li><li>Increase to high, add the chicken and stir-fry about 4 minutes until just cooked, then add the basil and cook 1 minute until wilted.</li><li>Serve over rice.</li></ol><p><em>Serve over jasmine rice.</em></p>', CURRENT_TIMESTAMP),
  ('29c1babb-4b27-57c2-a1fc-6b14d2667aa8', 'ef71ff2c-b889-5000-8503-6d16774a3d64', 'ru', 'Креветки с куркумой и чесноком с салатом из капусты и манго', 'Креветки, обжаренные с куркумой, зирой и чесноком, подаются со свежим салатом из красной капусты, манго, красного лука и кинзы с лаймом.', '<ol><li>Смешайте 1 ст. л. масла, сок 1 лайма, ¾ ч. л. соли и перец. Заправьте этой смесью капусту, красный лук, манго и 1 ст. л. кинзы.</li><li>Смешайте креветки с оставшейся солью, куркумой, хлопьями красного перца и зирой.</li><li>В большой антипригарной сковороде на средне-сильном огне разогрейте ½ ч. л. масла и обжарьте половину креветок по 1½–2 минуты с каждой стороны до непрозрачности. Отложите.</li><li>Добавьте оставшееся масло и креветки, в последнюю минуту добавьте чеснок. Верните все креветки в сковороду и перемешайте.</li><li>Снимите с огня, выжмите второй лайм, посыпьте кинзой и разложите креветки и салат по 4 тарелкам.</li></ol><p><em>Выжмите лайм на креветки перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('5a04b537-b02d-5ec3-88c0-71753ca3b625', 'ef71ff2c-b889-5000-8503-6d16774a3d64', 'en', 'Turmeric garlic shrimp with cabbage-mango slaw', 'Shrimp seared with turmeric, cumin and garlic, served over a fresh slaw of red cabbage, mango, red onion and cilantro with lime.', '<ol><li>Combine 1 tbsp oil, the juice of 1 lime, ¾ tsp salt and pepper and toss with the cabbage, red onion, mango and 1 tbsp cilantro.</li><li>Toss the shrimp with the remaining salt, turmeric, red pepper flakes and cumin.</li><li>In a large nonstick pan over medium-high heat warm ½ tsp oil and cook half the shrimp 1½–2 minutes per side until opaque; set aside.</li><li>Add the remaining oil and shrimp, adding the garlic for the last minute, then return all shrimp to the pan and stir.</li><li>Remove from the heat, squeeze the second lime over, toss with cilantro and divide the shrimp and slaw among 4 plates.</li></ol><p><em>Squeeze lime over the shrimp just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('c644589e-0acd-5a59-bda8-0f42735a5043', 'af16206a-631e-5f30-9939-753da1dc8d63', 'ru', 'Куриная грудка с кинзой и лаймом на гриле или в аэрогриле', 'Куриные грудки, замаринованные в лаймовом соке и цедре с оливковым маслом, чесноком и кинзой, и приготовленные на гриле или в аэрогриле. Хороши для заготовки на неделю.', '<ol><li>Отбейте толстую часть грудок молотком до одинаковой толщины.</li><li>В глубокой посуде соедините сок и цедру лайма, масло, половину кинзы, чеснок и соль, добавьте курицу, хорошо обмажьте и мариновать в холодильнике от 1 часа до ночи, перевернув на половине срока.</li><li>На гриле: смажьте решётку или сковороду-гриль маслом на среднем-сильном огне и жарьте по 5 минут с каждой стороны до румяных полос и готовности. В аэрогриле: готовьте в один слой при 190 °C по 5 минут с каждой стороны.</li><li>Переложите на блюдо, выжмите лайм и посыпьте оставшейся кинзой.</li></ol><p><em>Выжмите свежий лайм и посыпьте кинзой, подайте с рисом и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('c1280d10-01f4-5312-9252-b876e28d6b40', 'af16206a-631e-5f30-9939-753da1dc8d63', 'en', 'Cilantro lime chicken breast (grilled or air fryer)', 'Chicken breasts marinated in lime juice and zest with olive oil, garlic and cilantro and cooked on the grill or in the air fryer. Great for meal prep.', '<ol><li>Pound the thicker end of each chicken breast so it is even.</li><li>In a large container combine the lime juice and zest, olive oil, half the cilantro, garlic and salt, add the chicken, coat well and marinate in the fridge at least 1 hour up to overnight, turning halfway.</li><li>Grill: oil a grill or grill pan over medium to medium-high and cook about 5 minutes per side until charred and cooked through. Air fryer: single layer at 380 °F (190 °C) 5 minutes per side.</li><li>Set on a platter, squeeze the lime over and garnish with the remaining cilantro.</li></ol><p><em>Squeeze fresh lime over, scatter with cilantro and serve with rice and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('ecd0c9fe-2b5a-59a1-b05c-4258b6f5540f', '11954f00-0ff7-5c20-a654-4adae0c3377d', 'ru', 'Целая курица, маринованная в кефире, из аэрогриля или духовки', 'Целая курица, выдержанная ночь в кефире или пахте с солью, запечённая до золотистой хрустящей корочки. Всего три ингредиента, мясо получается очень сочным.', '<ol><li>За день до готовки хорошо посолите курицу 2 ч. л. соли и оставьте на 30 минут. По желанию свяжите ножки ниткой.</li><li>Положите курицу в большую посуду, залейте кефиром (пахтой), плотно накройте и уберите в холодильник на ночь, на середине срока перевернув.</li><li>За час до готовки достаньте курицу из холодильника, стряхните излишки маринада.</li><li>В аэрогриле (от 6 л): положите курицу грудкой вниз, посолите сверху ½ ч. л. соли и готовьте при 175 °C около 25 минут до румяности, затем переверните, посолите оставшейся солью и ещё 25 минут до золотистой хрустящей корочки (сок прозрачный, нож у кости между бедром и ножкой). В духовке: 200 °C около 1 часа.</li><li>Переложите на блюдо и дайте отдохнуть 10 минут перед нарезкой.</li></ol><p><em>Дайте отдохнуть 10 минут и нарежьте. Подайте с картофелем или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('01ae3ed0-4945-5ce2-ad7d-460e00f492d2', '11954f00-0ff7-5c20-a654-4adae0c3377d', 'en', 'Buttermilk (kefir) marinated whole roast chicken', 'A whole chicken brined overnight in buttermilk or kefir with salt and roasted in the air fryer or oven until golden and crisp. Just three ingredients and extremely juicy.', '<ol><li>The day before, season the chicken generously with 2 tsp salt and let sit 30 minutes; optionally tie the legs with twine.</li><li>Place the chicken in a large bowl, pour in the kefir or buttermilk, cover tightly and refrigerate overnight, rotating halfway.</li><li>An hour before cooking take the chicken out of the fridge and shake off excess marinade.</li><li>Air fryer (6 qt+): place the chicken breast-side down, season the top with ½ tsp salt and cook at 350 °F (175 °C) about 25 minutes until browned, then flip, salt and cook 25 more minutes until golden and crisp with clear juices. Oven: 400 °F (200 °C) about 1 hour.</li><li>Transfer to a platter and rest 10 minutes before carving.</li></ol><p><em>Rest 10 minutes before carving; serve with potatoes or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('54a511cd-e626-50de-850c-aa148347b3da', 'd06f0de7-cf74-58a4-b87a-02c69d26a55d', 'ru', 'Густой суп с говядиной, картофелем и киноа', 'Сытный суп в одной кастрюле: небольшие кусочки говядины, картофель, морковь, киноа, томат и зелёный лук с зирой и кинзой.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло и около 3 минут обжарьте зелёный лук и чеснок до мягкости.</li><li>Добавьте помидор, зиру, паприку и ¼ стакана кинзы и готовьте ещё 2 минуты.</li><li>Положите говядину, влейте воду, добавьте бульонный кубик, морковь, перец и соль и доведите до кипения.</li><li>Накройте и варите на слабом огне около 1,5 часа до мягкости мяса (в скороварке: 45 минут).</li><li>Добавьте картофель и отваренную киноа и варите ещё 25 минут (в скороварке — 10). Добавьте оставшуюся кинзу и подавайте.</li></ol><p><em>Подавайте с кинзой и ломтиками авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('433a4603-8359-5aea-b227-406500a7ed8f', 'd06f0de7-cf74-58a4-b87a-02c69d26a55d', 'en', 'Hearty beef, potato and quinoa soup', 'A nourishing one-pot soup with small pieces of beef, potatoes, carrot, quinoa, tomato and scallions flavored with cumin and cilantro.', '<ol><li>In a large pot heat the oil over medium and sauté the scallions and garlic about 3 minutes until soft.</li><li>Add the tomato, cumin, paprika and ¼ cup cilantro and cook 2 more minutes.</li><li>Add the beef, water, bouillon, carrot, bell pepper and salt and bring to a boil.</li><li>Cover and simmer on low about 1½ hours until the meat is tender (pressure cooker: 45 minutes).</li><li>Add the potatoes and cooked quinoa and cook 25 more minutes (pressure cooker: 10). Stir in the remaining cilantro and serve.</li></ol><p><em>Serve with cilantro and avocado slices.</em></p>', CURRENT_TIMESTAMP),
  ('08829b9f-147c-5c90-8b95-844407073bf6', 'b5d026de-c7ed-532d-b93c-29f989eb3640', 'ru', 'Тонкие спагетти в соусе из сливочного сыра с гренками', 'Самая простая паста: тонкая паста в гладком соусе из двух ингредиентов, сливочного сыра и куриного бульона, посыпанная поджаренными сухариками.', '<ol><li>Отварите пасту по инструкции, слейте и отставьте.</li><li>В небольшой кастрюле на сильном огне взбейте половину бульона со сливочным сыром до гладкости, затем влейте остальной бульон и перемешайте.</li><li>Полейте пасту соусом, перемешайте и посыпьте поджаренными сухариками.</li></ol><p><em>Подайте сразу со свежими овощами или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('4bcca589-de8d-55ff-9e39-7776232997e4', 'b5d026de-c7ed-532d-b93c-29f989eb3640', 'en', 'Angel hair pasta in cream cheese sauce with toasted breadcrumbs', 'The easiest pasta: thin noodles in a smooth two-ingredient sauce of cream cheese and chicken broth, topped with toasted breadcrumbs.', '<ol><li>Cook the pasta according to the package, drain and set aside.</li><li>In a small saucepan over high heat whisk half the broth with the cream cheese until smooth, then add the remaining broth and stir just to combine.</li><li>Pour the sauce over the pasta, toss and garnish with toasted breadcrumbs.</li></ol><p><em>Serve at once with fresh vegetables or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('c31b4c58-1390-5e0b-8173-85d91a27a10e', '30be37b9-1a85-53aa-97d0-d020574914a9', 'ru', 'Тонкие спагетти со сливками, чесноком и пармезаном в одной кастрюле', 'Паста сварена прямо в чесночном бульоне, а в конце заправлена сливками и пармезаном. Готовится за 10–12 минут; можно добавить курицу или креветки.', '<ol><li>В глубокой сковороде на средне-сильном огне 30 секунд прогрейте чеснок в масле.</li><li>Влейте бульон, добавьте соль и перец и доведите до кипения.</li><li>Положите разломанную пасту, доведите до слабого кипения, накройте и варите на средне-слабом огне 6 минут.</li><li>Снимите с огня, вмешайте пармезан и сливки, посыпьте петрушкой и подавайте.</li></ol><p><em>Посыпьте сушёной петрушкой и подайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('857d1737-3be4-5aaa-9e75-5c07981c5aa9', '30be37b9-1a85-53aa-97d0-d020574914a9', 'en', 'One-pot creamy garlic Parmesan angel hair pasta', 'Pasta cooked right in garlicky broth and finished with cream and Parmesan. Ready in about 12 minutes; add chicken or shrimp for a heartier meal.', '<ol><li>In a deep pan over medium-high heat cook the garlic in the oil for 30 seconds.</li><li>Pour in the broth, add salt and pepper and bring to the boil.</li><li>Add the broken pasta, bring to a simmer, cover and cook on medium-low 6 minutes.</li><li>Remove from the heat, stir in the Parmesan and cream, garnish with parsley and serve.</li></ol><p><em>Garnish with dried parsley and serve at once.</em></p>', CURRENT_TIMESTAMP),
  ('846179a5-b0a6-5560-8289-d2b1b6e30e3f', '1b3c8c1a-58ed-5e6f-b67a-e03952aa4cef', 'ru', 'Курица по-тоскански в сливочном соусе с вялеными томатами и сыром', 'Обжаренное куриное филе в густом сливочном соусе с чесноком, вялеными томатами, моцареллой и сыром монтерей джек, со свежим базиликом.', '<ol><li>Разрежьте грудки поперёк пополам, посолите, поперчите и посыпьте паприкой.</li><li>Обжарьте курицу на сильном огне в 2 ст. л. масла от вяленых томатов по 2–3 минуты с каждой стороны до румяной корочки. Отложите.</li><li>В той же сковороде 30 секунд обжарьте чеснок и вяленые томаты в 1 ст. л. масла и сливочном масле. Всыпьте муку, влейте сливки и воду, доведите до кипения и варите 2 минуты. Добавьте оба сыра.</li><li>Верните курицу в сковороду, добавьте свежий базилик и прогрейте. Подавайте с пастой или овощами.</li></ol><p><em>Подайте с пастой или паровыми овощами.</em></p>', CURRENT_TIMESTAMP),
  ('595f78d6-af90-5300-86a2-87328966372d', '1b3c8c1a-58ed-5e6f-b67a-e03952aa4cef', 'en', 'Creamy Tuscan chicken with sun-dried tomatoes and cheese', 'Seared chicken breast in a thick cream sauce with garlic, sun-dried tomatoes, mozzarella and Monterey Jack, finished with fresh basil.', '<ol><li>Slice the chicken breasts in half crosswise and season with salt, pepper and paprika.</li><li>Sear the chicken on high heat in 2 tbsp of the sun-dried tomato oil 2–3 minutes per side until nicely browned. Set aside.</li><li>In the same pan cook the garlic and sun-dried tomatoes in 1 tbsp of the oil and the butter for 30 seconds. Whisk in the flour, then add the cream and water, bring to a boil and simmer 2 minutes. Stir in both cheeses.</li><li>Return the chicken with the fresh basil and heat through. Serve over pasta or with vegetables.</li></ol><p><em>Serve over pasta or with steamed vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('4b648646-126d-50a1-8a25-9e1e21d94563', '10fa5b22-6cc6-5ebe-81e2-96b80d2647a2', 'ru', 'Куриный суп с галушками на кефире, укропом и чесноком', 'Бульон с обжаренной курицей и луком, в котором варятся пышные галушки из кефирного теста. В конце — много укропа и чеснока.', '<ol><li>В большой кастрюле на масле обжарьте нарезанную курицу и лук с 1 ч. л. соли и ½ ч. л. перца до прозрачного лука.</li><li>Влейте бульон и доведите до слабого кипения на средне-слабом огне.</li><li>Для клёцек смешайте кефир (или пахту), соду, 1 ч. л. соли и муку и замесите тесто. Выложите на подпылённый мукой стол (тесто липкое), разделите на 6 частей и раскатайте жгуты по 55 см, нарежьте кусочками по 2,5 см.</li><li>Опустите галушки в кипящий суп и варите 5–7 минут. Выключите огонь, добавьте укроп и раздавленный чеснок.</li></ol><p><em>Подайте горячим со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('59a45770-c06c-5413-97ea-a9ad1ea3271e', '10fa5b22-6cc6-5ebe-81e2-96b80d2647a2', 'en', 'Chicken soup with kefir dumplings, dill and garlic', 'A chicken and onion broth with plump dumplings made from a buttermilk (kefir) dough, finished with lots of dill and garlic.', '<ol><li>In a large pot sauté the diced chicken and onion in the oil with 1 tsp salt and ½ tsp pepper until the onion is translucent.</li><li>Pour in the broth and bring to a simmer over medium-low heat.</li><li>For the dumplings mix the kefir (buttermilk), baking soda, 1 tsp salt and flour into a dough. Turn out on a floured surface (it is tacky), divide into 6 pieces, roll each into a log about 22 inches long and cut into 1 inch pieces.</li><li>Drop the dumplings into the boiling soup and cook 5–7 minutes. Turn off the heat and add the dill and crushed garlic.</li></ol><p><em>Serve hot with a spoonful of sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('2ef82916-77a9-50d2-8e35-7e2bcef114f9', 'a66de747-57c9-5029-a6f8-aab39b593971', 'ru', 'Курица в сладко-кислом апельсиновом соусе', 'Кусочки куриной грудки в муке, обжаренные во фритюре и уваренные в простом сладко-кислом соусе из сахара, уксуса, соевого соуса и апельсинового сока.', '<ol><li>Нарежьте курицу кубиками, смешайте с апельсиновым соком, добавьте муку, паприку, соль и чесночный порошок и обваляйте.</li><li>Разогрейте на сильном огне около 180 мл масла и жарьте курицу порциями по 5–6 минут, один раз переворачивая. Перекладывайте в большую кастрюлю.</li><li>Смешайте сахар, воду, уксус, соль и соевый соус и залейте курицу.</li><li>Кипятите без крышки на сильном огне около 12 минут, пока соус не уварится и не загустеет.</li></ol><p><em>Подайте с рисом и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('4aa5df31-b4e6-5460-b747-108dc0cf0627', 'a66de747-57c9-5029-a6f8-aab39b593971', 'en', 'Easy orange chicken in sweet and sour sauce', 'Floured chicken breast pieces pan-fried and simmered in a simple sweet-sour sauce of sugar, vinegar, soy sauce and orange juice.', '<ol><li>Cube the chicken, toss with the orange juice, then add the flour, paprika, salt and garlic powder and toss to coat.</li><li>Heat about ¾ cup of oil over high heat and fry the chicken in batches 5–6 minutes, turning once. Move each batch to a large pot.</li><li>Combine the sugar, water, vinegar, salt and soy sauce and pour over the chicken.</li><li>Boil uncovered over high heat about 12 minutes until the sauce reduces and thickens.</li></ol><p><em>Serve with rice and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('a4dccc06-2808-53b7-8a9c-5783286c66d2', 'f4ca3116-fef6-5aac-8715-cb0c12732866', 'ru', 'Треска по-мароккански с нутом', 'Филе трески, тушёное в густом соусе из томатов, сладкого перца и нута с пряностями рас-эль-ханут, паприкой и зирой.', '<ol><li>Разогрейте в глубокой сковороде с крышкой 2 ст. л. оливкового масла на среднем огне. Добавьте измельчённый чеснок (4 зубчика) и пару мгновений обжарьте до аромата.</li><li>Добавьте томатную пасту, нарезанные помидоры и сладкий перец, готовьте 3–4 минуты, часто помешивая.</li><li>Всыпьте нут, влейте воду, добавьте кинзу, нарезанные пластинками 4 зубчика чеснока, соль, перец и ½ ч. л. рас-эль-ханута. Доведите до кипения, убавьте огонь и тушите под неплотной крышкой около 20 минут, при необходимости подливая воду.</li><li>Пока соус тушится, смешайте оставшийся рас-эль-ханут с зирой и паприкой. Посолите и поперчите рыбу, натрите смесью специй с обеих сторон и сбрызните оливковым маслом.</li><li>Уложите рыбу в соус, полейте сверху соусом, добавьте лимонный сок и кружочки лимона. Тушите ещё 10–15 минут на небольшом огне, пока рыба не станет непрозрачной и не начнёт разделяться на пласты. Посыпьте свежей кинзой.</li></ol><p><em>Подайте с рисом, кускусом или свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('a9b0cbe5-cc39-57f8-8d4d-15e6f08c8a2f', 'f4ca3116-fef6-5aac-8715-cb0c12732866', 'en', 'Moroccan cod with chickpeas and tomato', 'Cod fillets braised in a saucy mix of tomatoes, bell pepper and chickpeas, seasoned with ras el hanout, paprika and cumin.', '<ol><li>Heat 2 tbsp of olive oil in a large lidded pan over medium heat. Add the minced garlic (4 cloves) and cook briefly until fragrant.</li><li>Add the tomato paste, diced tomatoes and bell pepper and cook for 3–4 minutes, stirring often.</li><li>Add the chickpeas, water, cilantro, the 4 sliced garlic cloves, salt, pepper and ½ tsp ras el hanout. Bring to a boil, reduce the heat and simmer partly covered for about 20 minutes, adding a little water if needed.</li><li>While the sauce simmers, mix the remaining ras el hanout with the cumin and paprika. Season the fish with salt and pepper, rub it with the spice mix on both sides and drizzle with olive oil.</li><li>Nestle the fish into the sauce and spoon some sauce over it. Add the lemon juice and lemon slices and cook another 10–15 minutes over medium-low heat until the fish is opaque and flaky. Garnish with fresh cilantro.</li></ol><p><em>Serve with rice, couscous or crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('e0d96c19-3960-589a-8efe-d6b10a3c206e', '44d73fad-a26d-5d16-8c17-22c4615ccfd0', 'ru', 'Капуста маринованная быстрая с морковью', 'Нарезанная капуста с морковью и чесноком, залитая горячим маринадом с уксусом и маслом. Готова за сутки в холодильнике.', '<ol><li>Снимите верхние листья капусты, разрежьте её на четвертинки, удалите кочерыжку и тонко нашинкуйте. Переложите в большую миску.</li><li>Натрите морковь на крупной тёрке, чеснок мелко нарежьте. Добавьте к капусте.</li><li>В кастрюле смешайте воду, сахар, соль, горошины перца, гвоздику и лавровый лист. Доведите до кипения и варите 10 минут. Влейте масло и уксус, снимите с огня и остудите 10 минут.</li><li>Выньте из маринада перец и лавровый лист, залейте им овощи и перемешайте. Прижмите овощи тарелкой с грузом и оставьте до полного остывания.</li><li>Переложите капусту вместе с маринадом в большую банку так, чтобы она была покрыта жидкостью, закройте крышкой и уберите в холодильник на 24 часа.</li></ol><p><em>Хороша к картофельному пюре, гречке и жареному мясу.</em></p>', CURRENT_TIMESTAMP),
  ('89ef4a19-7448-5b9e-b908-05eba4421983', '44d73fad-a26d-5d16-8c17-22c4615ccfd0', 'en', 'Quick marinated cabbage with carrots', 'Shredded cabbage with carrots and garlic in a hot vinegar and oil marinade, ready after a day in the fridge.', '<ol><li>Remove the outer cabbage leaves, quarter the heads, cut out the cores and shred the cabbage finely. Put it in a large bowl.</li><li>Grate the carrots, finely chop the garlic and add both to the cabbage.</li><li>In a pot combine the water, sugar, salt, peppercorns, cloves and bay leaves. Bring to a boil and simmer for 10 minutes. Stir in the oil and vinegar, remove from the heat and cool for 10 minutes.</li><li>Remove the peppercorns and bay leaves, pour the marinade over the vegetables and mix. Weigh the vegetables down with a plate and a weight and let them cool completely.</li><li>Transfer the cabbage with all the liquid to a large jar so it is fully covered, close the lid and refrigerate for 24 hours.</li></ol><p><em>Serve with mashed potatoes, buckwheat or roasted meat.</em></p>', CURRENT_TIMESTAMP),
  ('4b715e97-0549-55a7-866f-77c367c82ff9', '773a022c-3483-5f4c-ba33-6e54618bcc0a', 'ru', 'Креветки скампи в чесночно-масляном соусе', 'Быстро обжаренные креветки в соусе из сливочного масла, чеснока, белого вина и лимонного сока.', '<ol><li>Смешайте соль, перец и паприку, обваляйте в смеси очищенные креветки.</li><li>Разогрейте на сковороде масло и обжарьте креветки на среднем и сильном огне по 1–2 минуты с каждой стороны. Снимите их со сковороды и накройте, чтобы не остыли.</li><li>В той же сковороде растопите сливочное масло, добавьте чеснок и прогрейте до аромата.</li><li>Влейте вино и бульон, варите на слабом огне 3–4 минуты. Верните креветки в соус и прогрейте.</li><li>Посыпьте рубленой петрушкой и сбрызните лимонным соком.</li></ol><p><em>Подайте с пастой, рисом или свежим хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('032b9ff5-afe5-53d8-a828-01a62e761445', '773a022c-3483-5f4c-ba33-6e54618bcc0a', 'en', 'Garlic butter shrimp scampi', 'Quickly seared shrimp in a sauce of butter, garlic, dry white wine and lemon juice.', '<ol><li>Mix the salt, pepper and paprika and toss the peeled shrimp in the seasoning.</li><li>Heat the oil in a skillet and sear the shrimp over medium-high heat for 1–2 minutes per side. Remove them from the pan and cover to keep warm.</li><li>In the same skillet melt the butter with the garlic and cook until fragrant.</li><li>Pour in the wine and broth and simmer for 3–4 minutes. Return the shrimp to the pan and warm through.</li><li>Finish with chopped parsley and lemon juice.</li></ol><p><em>Serve with pasta, rice or crusty bread to mop up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('6684687a-d506-5fb2-8508-38cc7acbc4e9', '89311341-4385-598b-b53c-2fb0005cd32d', 'ru', 'Запечённая паста зити с говяжьим фаршем и рикоттой', 'Паста в томатном соусе с говяжьим фаршем, прослоённая рикоттой и моцареллой и запечённая до румяной сырной корочки.', '<ol><li>Отварите пасту до состояния al dente по инструкции на упаковке и слейте воду. Разогрейте духовку до 175 °C.</li><li>Обжарьте на большой сковороде говяжий фарш с луком на среднем и сильном огне, разбивая комочки, до готовности мяса.</li><li>Добавьте чеснок, итальянские травы, соль и перец, перемешайте. Влейте томатный соус и измельчённые томаты, доведите до слабого кипения и смешайте с пастой.</li><li>Выложите в форму размером примерно 23×33 см половину пасты, распределите половину рикотты и посыпьте половиной моцареллы и пармезана. Добавьте оставшуюся пасту и закончите слоем остального сыра.</li><li>Накройте фольгой и запекайте 20–25 минут, затем снимите фольгу и допеките ещё 10–15 минут, пока сыр не запузырится.</li></ol><p><em>Подайте со свежим салатом из зелени.</em></p>', CURRENT_TIMESTAMP),
  ('d5fd2e82-acba-5007-b5bf-856dd4b4e335', '89311341-4385-598b-b53c-2fb0005cd32d', 'en', 'Baked ziti with beef, ricotta and mozzarella', 'Pasta in a meaty tomato sauce layered with ricotta and mozzarella and baked until bubbly and golden.', '<ol><li>Cook the pasta until al dente according to the package directions and drain. Heat the oven to 175°C (350°F).</li><li>Brown the ground beef with the onion in a large skillet over medium-high heat, breaking it up, until mostly cooked through.</li><li>Add the garlic, Italian seasoning, salt and pepper and stir. Pour in the tomato sauce and crushed tomatoes, bring to a gentle simmer and combine with the pasta.</li><li>In a 9x13-inch baking dish layer half of the pasta, half of the ricotta and half of the mozzarella and parmesan. Top with the remaining pasta and finish with the rest of the cheese.</li><li>Cover with foil and bake for 20–25 minutes, then uncover and bake another 10–15 minutes until the cheese bubbles.</li></ol><p><em>Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('33aa41b9-5908-5491-853e-3d6fdfbce0a9', '101040a0-191b-54f6-a9f7-cd71c74e0d5c', 'ru', 'Жареный рис с курицей, морковью и яйцом', 'Рассыпчатый рис басмати, обжаренный с куриной грудкой, морковью, яйцом и чесноком в соевой заправке.', '<ol><li>Смешайте рис с водой в жаропрочной форме, накройте и готовьте в духовке при 200 °C 25–30 минут, пока рис не станет рассыпчатым. Разрыхлите вилкой и остудите.</li><li>Нарежьте курицу кусочками и обжарьте в растительном масле до золотистой корочки и полной готовности, слегка посолив и поперчив. Выложите на тарелку.</li><li>В ту же сковороду добавьте половину сливочного масла и тёртую морковь, обжарьте до мягкости и переложите к курице.</li><li>Добавьте оставшееся масло, влейте взбитые яйца и приготовьте скрэмбл, помешивая.</li><li>Верните в сковороду курицу и морковь, добавьте чеснок, перемешайте, затем всыпьте рис.</li><li>Смешайте соевый соус, кунжутное масло и воду, влейте в сковороду, добавьте зелёный лук и обжаривайте ещё 2–3 минуты, помешивая.</li></ol><p><em>Посыпьте зелёным луком; к рису подойдёт свежий огуречный салат.</em></p>', CURRENT_TIMESTAMP),
  ('7e24bb46-b87d-538a-a462-e5ae45b290b2', '101040a0-191b-54f6-a9f7-cd71c74e0d5c', 'en', 'Chicken fried rice with carrots and egg', 'Fluffy basmati rice stir-fried with chicken breast, carrots, egg and garlic in a soy-sesame sauce.', '<ol><li>Combine the rice and water in a baking dish, cover and bake at 200°C (400°F) for 25–30 minutes until fluffy. Fluff with a fork and let cool.</li><li>Cut the chicken into pieces and cook in oil until golden and cooked through, lightly seasoning with salt and pepper. Remove to a plate.</li><li>In the same pan melt half the butter, sauté the grated carrots until soft and add them to the chicken.</li><li>Add the remaining butter and scramble the eggs, stirring as needed.</li><li>Return the chicken and carrots to the pan with the garlic, stir, then add the rice.</li><li>Mix the soy sauce, sesame oil and water, pour into the pan, add the green onion and fry another 2–3 minutes, stirring.</li></ol><p><em>Top with green onion and serve with a crisp cucumber salad.</em></p>', CURRENT_TIMESTAMP),
  ('fc1d63eb-7f51-5082-a19c-1adad441da58', '85a1de50-a39f-5535-b50f-617c600f22b1', 'ru', 'Говяжья лопатка в мультиварке с овощами', 'Кусок говядины, обжаренный и томлённый много часов с морковью и картофелем, пока не станет разделяться на волокна. Подходит для большой семьи.', '<ol><li>Включите мультиварку на прогрев. Разогрейте масло на сковороде и обжарьте мясо со всех сторон до корочки.</li><li>Посолите и поперчите мясо, посыпьте сушёным луком и чесноком и обваляйте в муке.</li><li>Переложите мясо в мультиварку, добавьте томатную пасту, бульон, вустерский соус, морковь, картофель и тимьян. Поперчите ещё раз.</li><li>Закройте крышку и готовьте на высоком режиме 4–5 часов (или на низком около 8), пока мясо не начнёт легко разделяться вилкой.</li><li>Достаньте мясо и разберите крупными кусками двумя вилками. Выложите на блюдо с овощами, а жидкость слейте в кувшин и снимите лишний жир.</li></ol><p><em>Подавайте мясо с овощами и соусом, который остался в чаше.</em></p>', CURRENT_TIMESTAMP),
  ('accfb0d7-c6be-597a-9ea6-8cf5cda06b1a', '85a1de50-a39f-5535-b50f-617c600f22b1', 'en', 'Slow cooker chuck roast with vegetables', 'Beef chuck seared and slow-cooked for hours with carrots and potatoes until it pulls apart into tender chunks. Feeds a crowd.', '<ol><li>Switch on the slow cooker to warm up. Heat the oil in a large frying pan and sear the beef on all sides until browned.</li><li>Season the beef with salt, pepper, onion and garlic powder, then dust with the flour.</li><li>Put the beef in the slow cooker with the tomato paste, stock, Worcestershire sauce, carrots, potatoes and thyme. Add more pepper.</li><li>Cover and cook on high for 4-5 hours (or low for about 8) until the meat is fork-tender.</li><li>Lift out the meat and tear it into chunks with two forks. Arrange it on a platter with the vegetables, pour the cooking liquid into a jug and skim off the excess fat.</li></ol><p><em>Serve the meat with the vegetables and the cooking juices.</em></p>', CURRENT_TIMESTAMP),
  ('b1832af0-26f2-5d3d-a35d-888b689d2801', 'dd844492-4ad9-5527-add8-345055d9e526', 'ru', 'Рыба-меч на гриле с чесноком и зирой', 'Стейки из рыбы-меча в быстром маринаде из чеснока, лимона, зиры и кориандра. Готовятся на гриле за несколько минут.', '<ol><li>Взбейте в блендере или кухонном комбайне чеснок, лимонный сок, масло, специи, соль и перец примерно 3 минуты до густого гладкого маринада.</li><li>Обсушите стейки, выложите в посуду с бортиками и щедро обмажьте маринадом с обеих сторон. Оставьте на 15 минут, пока разогревается гриль.</li><li>Разогрейте гриль на сильном огне и смажьте решётку маслом. Жарьте стейки 5–6 минут с одной стороны, переверните и готовьте ещё около 3 минут: рыба должна легко расслаиваться, внутри допустим лёгкий розовый оттенок.</li><li>Сбрызните лимонным соком и при желании посыпьте хлопьями острого перца.</li></ol><p><em>Подайте с лимоном и свежим овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('924a06b9-b2c2-576b-800f-fab3869f0598', 'dd844492-4ad9-5527-add8-345055d9e526', 'en', 'Grilled swordfish with cumin and garlic', 'Swordfish steaks in a quick marinade of garlic, lemon, cumin and coriander, grilled for just a few minutes.', '<ol><li>Blend the garlic, lemon juice, olive oil, spices, salt and pepper for about 3 minutes into a thick, smooth marinade.</li><li>Pat the steaks dry, place them in a dish and coat generously with the marinade on both sides. Leave for 15 minutes while the grill heats.</li><li>Heat the grill to high and oil the grates. Grill the steaks 5-6 minutes on one side, turn once and cook about 3 minutes more until the fish flakes easily; a hint of pink inside is fine.</li><li>Finish with a squeeze of lemon juice and a sprinkle of chilli flakes if you like some heat.</li></ol><p><em>Serve with lemon wedges and a fresh vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('d52fd24c-a52f-58ad-9b7c-9397963a6fed', '0fa4d754-5b30-550c-8dae-c3fdac3ca16c', 'ru', 'Тёплая закуска из кабачков и помидоров со сливочным сыром', 'Тушёные кабачки с помидорами и базиликом, в которые вмешан сливочный сыр. Получается нежная густая намазка, которую едят горячей.', '<ol><li>Крупно измельчите помидоры в комбайне или нарежьте мелким кубиком вручную.</li><li>Поставьте на средний огонь широкую сковороду с толстым дном, добавьте помидоры, чеснок и 2 ст. л. базилика. Тушите под крышкой 10 минут, помешивая и разминая крупные кусочки, пока масса не станет похожа на соус.</li><li>Срежьте у кабачков концы и натрите их на крупной тёрке. Добавьте к томатам и перемешайте.</li><li>Прибавьте огонь до средне-сильного, накройте крышкой и готовьте 20–23 минуты, изредка помешивая, пока кабачки полностью не станут мягкими.</li><li>Добавьте кусочки сливочного сыра и мешайте, пока он не растворится. Если масса густая, разведите горячей водой. Посолите, поперчите и подавайте горячей.</li></ol><p><em>Подавайте с крекерами, чипсами или ломтиками багета.</em></p>', CURRENT_TIMESTAMP),
  ('eb87b13c-315b-570f-aa04-4086bfa62281', '0fa4d754-5b30-550c-8dae-c3fdac3ca16c', 'en', 'Hot zucchini and tomato cream cheese dip', 'Zucchini simmered with tomatoes and basil, then melted together with cream cheese into a thick, creamy warm dip.', '<ol><li>Coarsely chop the tomatoes in a food processor, or dice them finely by hand.</li><li>Set a large heavy pan over medium heat and add the tomatoes, garlic and 2 tbsp basil. Simmer covered for 10 minutes, stirring and pressing larger pieces, until it looks like a sauce.</li><li>Trim the zucchini and grate them on the large holes of a grater. Stir them into the tomatoes.</li><li>Raise the heat to medium-high, cover and cook 20-23 minutes, stirring now and then, until the zucchini is fully soft.</li><li>Add the cream cheese in pieces and stir until it melts into a creamy mixture; thin with hot water if too thick. Season with salt and pepper and serve hot.</li></ol><p><em>Serve with crackers, chips or slices of French bread.</em></p>', CURRENT_TIMESTAMP),
  ('6bfc5045-9bb4-5ebc-b6cf-2742d809cb26', 'f4704cae-4669-5e25-a9d7-3fb5589c7d7a', 'ru', 'Курица Мадейра с грибами и спаржей', 'Отбивные из куриной грудки под соусом из мадеры и сливок, с шампиньонами и спаржей, запечённые под расплавленной моцареллой.', '<ol><li>Бланшируйте спаржу: обломайте жёсткие концы, опустите в кипящую подсоленную воду на 2–3 минуты до яркого цвета и лёгкой хрусткости, выньте и отложите.</li><li>В большой жаропрочной сковороде растопите 2 ст. л. сливочного масла с 1 ст. л. оливкового. Обжарьте шампиньоны 5 минут, добавьте лук, через 3 минуты чеснок, соль, перец и петрушку. Готовьте ещё 2 минуты и переложите на тарелку, сковороду протрите.</li><li>Разрежьте грудки вдоль пополам и отбейте до толщины не более 6 мм. Посолите и поперчите. В той же сковороде на оставшемся масле жарьте куриные пласты по 3–4 минуты с каждой стороны до золотистого цвета, переложите к грибам.</li><li>Влейте в сковороду мадеру и кипятите примерно 5 минут, пока объём не уменьшится вдвое, соскабливая румяные частицы со дна. Добавьте говяжий бульон и выпаривайте около 10 минут до четверти объёма. Убавьте огонь, влейте сливки и варите 2 минуты до загустения. Посолите и поперчите.</li><li>Верните курицу в соус, переверните, чтобы покрылась им, сверху выложите грибы и спаржу и посыпьте тёртой моцареллой. Поставьте под гриль духовки на 3–4 минуты, пока сыр не расплавится. Посыпьте петрушкой.</li></ol><p><em>Хорошо сочетается с картофельным пюре или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('382b088a-fcac-5ecb-accc-ef43c3f5d021', 'f4704cae-4669-5e25-a9d7-3fb5589c7d7a', 'en', 'Chicken Madeira with mushrooms and asparagus', 'Pounded chicken breast in a Madeira and cream sauce with mushrooms and asparagus, finished under melted mozzarella.', '<ol><li>Blanch the asparagus: snap off the woody ends, boil in salted water 2-3 minutes until bright green and crisp-tender, then set aside.</li><li>In a large oven-safe pan melt 2 tbsp butter with 1 tbsp olive oil. Cook the mushrooms 5 minutes, add the onion for 3 minutes, then garlic, salt, pepper and parsley for 2 more minutes. Move to a plate and wipe the pan clean.</li><li>Slice the chicken breasts in half lengthwise and pound to no more than 6 mm thick. Season, then sauté in the remaining butter and oil 3-4 minutes per side until golden and cooked through. Move to the plate with the mushrooms.</li><li>Pour the Madeira into the pan and boil about 5 minutes until reduced by half, scraping up the browned bits. Add the beef stock and boil about 10 minutes until down to a quarter. Lower the heat, add the cream and simmer 2 minutes until thickened. Season to taste.</li><li>Return the chicken to the sauce, turn to coat, then top with the mushrooms, asparagus and shredded mozzarella. Broil 3-4 minutes until the cheese melts. Garnish with parsley.</li></ol><p><em>Serve with mashed potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('f363491d-d531-5cc8-9707-041ef8da6eb6', '597a297c-5acc-5dfd-a6f9-7c6987329fe1', 'ru', 'Чили с говяжьим фаршем и фасолью', 'Густое блюдо из говяжьего фарша, красной фасоли, томатов и овощей с чили и зирой. Готовится в одной кастрюле меньше чем за полчаса.', '<ol><li>Обжарьте фарш в кастрюле с толстым дном на средне-сильном огне, разминая комочки.</li><li>Добавьте лук и готовьте до мягкости, затем морковь, перец и чеснок. Тушите до мягкости овощей и слейте лишний жир.</li><li>Влейте томаты с соком, добавьте фасоль, бульон и специи, перемешайте.</li><li>Убавьте огонь до слабого кипения и варите 15–20 минут, изредка помешивая (дольше, если овощи и мясо должны быть мягче). Снимите с огня и дайте постоять 5 минут.</li></ol><p><em>Подавайте со сметаной, тёртым сыром и хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('baa27d43-ff7b-5335-ae2d-86ac74b4a1ce', '597a297c-5acc-5dfd-a6f9-7c6987329fe1', 'en', 'Beef chili with beans and tomatoes', 'A thick, hearty pot of ground beef, kidney beans, tomatoes and vegetables seasoned with chili powder and cumin. Made in one pot in under 30 minutes.', '<ol><li>Brown the ground beef in a Dutch oven over medium-high heat, breaking it up as it cooks.</li><li>Add the onion and cook until tender, then the carrot, bell pepper and garlic. Cook until the vegetables soften and drain off excess fat.</li><li>Stir in the tomatoes with their juice, beans, stock and seasonings.</li><li>Reduce to a gentle boil and cook 15-20 minutes, stirring now and then (longer for softer meat and vegetables). Take off the heat and rest 5 minutes.</li></ol><p><em>Top with sour cream and shredded cheese and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('b64d6b02-6498-5d97-9d32-b2dbdefe4e9a', '8d031445-4513-539f-a8a5-3d80e02ed1b8', 'ru', 'Фахитас с курицей и болгарским перцем', 'Курица в маринаде из лайма и специй, обжаренная с цветным перцем и луком и поданная в тёплых тортильях.', '<ol><li>В миске смешайте 2 ст. л. масла, лаймовый сок, чили, зиру, паприку, лук и чеснок сушёные, соль и перец.</li><li>Разрежьте грудки вдоль пополам, обваляйте в маринаде и оставьте, пока готовите овощи (можно до 4 часов).</li><li>Нарежьте перцы и лук тонкими полосками толщиной около 6 мм.</li><li>На средне разогретой чугунной сковороде с 1 ст. л. масла жарьте курицу в один слой по 3–5 минут с каждой стороны до румяности и готовности (внутри не меньше 74 °C). Переложите на доску и дайте отдохнуть.</li><li>В той же сковороде на 1 ст. л. масла обжаривайте лук и перцы 5–6 минут, часто помешивая, до мягкости и румяных пятен. Посолите.</li><li>Нарежьте курицу полосками поперёк волокон, верните в сковороду, перемешайте и снимите с огня. Подавайте в тёплых тортильях с соком лайма, кинзой и любыми добавками.</li></ol><p><em>Добавьте сметану, сальсу, гуакамоле или авокадо и сыр.</em></p>', CURRENT_TIMESTAMP),
  ('e3b0cb83-5f89-51d6-b657-e4b8feb059e0', '8d031445-4513-539f-a8a5-3d80e02ed1b8', 'en', 'Chicken fajitas with peppers', 'Chicken in a lime and spice marinade, seared with colourful bell peppers and onion and served in warm tortillas.', '<ol><li>In a bowl mix 2 tbsp oil, the lime juice, chili powder, cumin, paprika, onion and garlic powder, salt and pepper.</li><li>Cut the chicken breasts in half lengthwise, coat in the marinade and set aside while you prep the vegetables (up to 4 hours is fine).</li><li>Slice the peppers and onion into strips about 6 mm thick.</li><li>In a heavy skillet (cast iron works well) over medium heat with 1 tbsp oil, sear the chicken in a single layer 3-5 minutes per side until browned and cooked through (74°C inside). Transfer to a board to rest.</li><li>In the same skillet with 1 tbsp oil, sauté the onion and peppers 5-6 minutes, stirring often, until soft and browned in spots. Season with salt.</li><li>Slice the chicken into strips across the grain, return it to the pan, toss and remove from the heat. Serve in warm tortillas with lime juice, cilantro and toppings.</li></ol><p><em>Add sour cream, salsa, guacamole or sliced avocado and cheese.</em></p>', CURRENT_TIMESTAMP),
  ('0896ab49-fc55-5149-bf05-dc67cfdee357', '7142f9d1-3fe4-503c-bdef-d41d1d7e5ddb', 'ru', 'Креветки скампи в чесночно-винном соусе', 'Креветки, обжаренные на сливочном и оливковом масле, с чесноком, белым вином и лимонным соком. Готовятся на одной сковороде за 10 минут.', '<ol><li>Обсушите креветки бумажным полотенцем, посолите и поперчите.</li><li>Разогрейте в большой сковороде 1 ст. л. оливкового и 1 ст. л. сливочного масла на средне-сильном огне. Выложите креветки в один слой и жарьте по 1–2 минуты с каждой стороны до непрозрачности. Сразу переложите на тарелку, чтобы не пересушить.</li><li>Убавьте огонь до среднего, добавьте остальные масла, чеснок и хлопья перца и жарьте около 30 секунд до аромата. Влейте вино и уварите вдвое за 2 минуты. Добавьте лимонный сок.</li><li>Верните креветки вместе с соком с тарелки, перемешайте в соусе и снимите с огня. Добавьте петрушку, при необходимости досолите.</li></ol><p><em>Подавайте с пастой или хрустящим хлебом, чтобы макать в соус.</em></p>', CURRENT_TIMESTAMP),
  ('ac4ecbca-b915-5d3f-94a4-7dbaed2f9ba2', '7142f9d1-3fe4-503c-bdef-d41d1d7e5ddb', 'en', 'Shrimp scampi in garlic white wine sauce', 'Shrimp seared in butter and olive oil, then tossed in a sauce of garlic, white wine and lemon. A one-pan dinner in about 10 minutes.', '<ol><li>Pat the shrimp dry and season with salt and pepper.</li><li>Heat 1 tbsp olive oil and 1 tbsp butter in a large skillet over medium-high heat. Cook the shrimp in a single layer 1-2 minutes per side until just opaque, then remove to a plate right away so they don''t overcook.</li><li>Lower the heat to medium and add the remaining oil and butter, garlic and chilli flakes; sauté about 30 seconds until fragrant. Add the wine and reduce by half, about 2 minutes, then stir in the lemon juice.</li><li>Return the shrimp with their juices to the pan, toss to coat and remove from the heat. Stir in the parsley and adjust the seasoning.</li></ol><p><em>Serve over pasta or with crusty bread for dipping.</em></p>', CURRENT_TIMESTAMP),
  ('e7af6a34-74a8-524e-8f6b-b6775297d20a', '814c1c9d-429e-5538-9703-52bd7ef7d80a', 'ru', 'Суп-пюре из запечённой тыквы с беконом', 'Тыква, запечённая до карамельного вкуса, и обжаренный лук с беконом, сваренные с бульоном и пряностями и пюрированные до кремовой консистенции. Подаётся с хрустящим беконом и тыквенными семечками.', '<ol><li>Разогрейте духовку до 220 °C. Вымойте тыквы, срежьте хвостик, разрежьте на четвертины и выньте семена. Выложите срезом вниз на противень с пергаментом, смазав маслом, и запекайте 35–40 минут до мягкости. Снимите кожуру.</li><li>В большой кастрюле с толстым дном обжарьте нарезанный бекон 5–6 минут до хруста. Переложите его на тарелку для подачи, а в кастрюле оставьте около 3 ст. л. жира.</li><li>Обжарьте лук 6–7 минут до мягкости, добавьте чеснок, соль, перец и пряности и готовьте ещё около минуты до аромата.</li><li>Добавьте мякоть тыквы и бульон, доведите до кипения, убавьте огонь и варите 15 минут, закрыв крышку не полностью.</li><li>Пробейте суп блендером до гладкости: погружным прямо в кастрюле или порциями в стационарном.</li><li>Влейте кокосовое молоко (или сливки), доведите до кипения, добавьте кленовый сироп, соль и перец по вкусу. Подавайте с беконом и семечками, обжаренными на сухой сковороде до золотистого цвета.</li></ol><p><em>Посыпьте беконом и поджаренными тыквенными семечками.</em></p>', CURRENT_TIMESTAMP),
  ('f5eabb56-4425-5da5-8790-063078a51d8a', '814c1c9d-429e-5538-9703-52bd7ef7d80a', 'en', 'Roasted pumpkin soup with bacon and seeds', 'Pumpkin roasted until caramelised, then simmered with onion, bacon, broth and warm spices and blended until creamy. Topped with crispy bacon and toasted pumpkin seeds.', '<ol><li>Heat the oven to 220°C (425°F). Wash the pumpkins, trim the stems, quarter them and scoop out the seeds. Roast cut side down on a parchment-lined tray with a little oil for 35-40 minutes until soft, then peel off the skin.</li><li>In a large heavy pot cook the chopped bacon 5-6 minutes until crisp. Move it to a dish for garnish and leave about 3 tbsp of the fat in the pot.</li><li>Sauté the onion 6-7 minutes until soft, then add the garlic, salt, pepper and spices and cook about a minute until fragrant.</li><li>Add the pumpkin flesh and broth, bring to a boil, reduce to a simmer and cook 15 minutes with the lid ajar.</li><li>Blend the soup until smooth, using an immersion blender in the pot or a standing blender in batches.</li><li>Stir in the coconut milk (or cream) and bring back to a boil, then add maple syrup, salt and pepper to taste. Serve topped with the bacon and pumpkin seeds toasted in a dry skillet until golden.</li></ol><p><em>Garnish with the crispy bacon and toasted pepitas.</em></p>', CURRENT_TIMESTAMP),
  ('3b638af2-4a18-59c7-9849-963b8246fc2a', '3f33c145-d688-5f6f-80af-858b40e100f4', 'ru', 'Мексиканский суп с курицей, фасолью и тортильей', 'Томатный суп с курицей, чёрной фасолью и кукурузой, который подают с хрустящими полосками тортильи и авокадо.', '<ol><li>Нарежьте тортильи тонкими полосками. Разогрейте в сковороде масло на средне-сильном огне и обжарьте полоски порциями до хруста, выложите на бумажное полотенце.</li><li>В кастрюле или жаровне разогрейте оливковое масло и обжарьте лук и халапеньо до мягкости. Добавьте чеснок на 30–60 секунд до аромата.</li><li>Добавьте бульон, измельчённые томаты, куриную грудку, кукурузу, фасоль, чили, зиру и соль. Доведите до кипения и варите около 20 минут, пока курица не будет готова и легко не расползётся.</li><li>Достаньте курицу, разберите двумя вилками на волокна и верните в суп. Варите ещё 5 минут.</li><li>Снимите с огня, добавьте кинзу и лаймовый сок. Подавайте с хрустящими полосками, авокадо и дольками лайма.</li></ol><p><em>Посыпьте хрустящей тортильей, кинзой и авокадо, подайте с лаймом.</em></p>', CURRENT_TIMESTAMP),
  ('80349458-9093-59b4-ae70-560d45f1e2f8', '3f33c145-d688-5f6f-80af-858b40e100f4', 'en', 'Chicken tortilla soup with black beans and avocado', 'A tomato-based soup with chicken, black beans and corn, served with crispy tortilla strips and diced avocado.', '<ol><li>Cut the tortillas into thin strips. Heat the oil in a pan over medium-high heat and fry the strips in batches until crisp, draining on paper towels.</li><li>In a pot or Dutch oven heat the olive oil and sauté the onion and jalapeño until soft. Add the garlic for 30-60 seconds until fragrant.</li><li>Add the broth, crushed tomatoes, chicken breast, corn, beans, chili powder, cumin and salt. Bring to a boil and simmer about 20 minutes until the chicken is cooked and shreds easily.</li><li>Lift out the chicken, shred it with two forks and return it to the soup. Simmer another 5 minutes.</li><li>Remove from the heat and stir in the cilantro and lime juice. Serve with the tortilla strips, diced avocado and lime wedges.</li></ol><p><em>Top with the tortilla strips, cilantro and avocado, and serve with lime.</em></p>', CURRENT_TIMESTAMP),
  ('2ad492c9-ded1-5df5-bead-3bb388cbc929', '6526b31c-45f5-5d69-a0ad-aff8170d809b', 'ru', 'Греческий салат с ромэном и авокадо', 'Нарезанный салат из ромэна, огурца, помидоров, перца, красного лука, оливок, феты и авокадо с лимонной заправкой на оливковом масле.', '<ol><li>Вымойте, нарежьте и обсушите ромэн, переложите в большую салатницу.</li><li>Добавьте красный лук, перец, помидоры черри, огурец, авокадо, оливки и фету.</li><li>Взболтайте в банке масло, лимонный сок, чеснок, соль и перец. Перед подачей полейте салат заправкой по вкусу и перемешайте.</li></ol><p><em>Заправляйте непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('98575ba0-b4a8-545c-ac2c-d3cad27b757b', '6526b31c-45f5-5d69-a0ad-aff8170d809b', 'en', 'Chopped Greek salad with romaine and avocado', 'A chopped salad of romaine, cucumber, tomatoes, peppers, red onion, olives, feta and avocado with a lemon and olive oil dressing.', '<ol><li>Rinse, chop and spin dry the romaine and put it in a large salad bowl.</li><li>Add the red onion, bell pepper, cherry tomatoes, cucumber, avocado, olives and feta.</li><li>Shake the olive oil, lemon juice, garlic, salt and pepper in a jar. Just before serving drizzle over the salad to taste and toss.</li></ol><p><em>Dress it just before serving.</em></p>', CURRENT_TIMESTAMP)
ON CONFLICT ("foodId", "language") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "content" = EXCLUDED."content", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "food_translations" ("id", "foodId", "language", "name", "description", "content", "updatedAt") VALUES
  ('b69b858d-a3a7-583f-9603-a27cb5e46121', '2e95df27-abe9-561f-acc4-2fc52f329b33', 'ru', 'Сливочный куриный суп с лапшой и укропом', 'Куриный суп с овощами, кукурузой и макаронами, который заправлен мучной засмаской со сливками. Получается густым и нежным.', '<ol><li>В большой кастрюле смешайте бульон, воду и соль, доведите до кипения. Положите куриные бёдра и варите без крышки 20 минут, снимая пену.</li><li>Пока варится курица, обжарьте в сковороде на масле лук 5 минут до мягкости, добавьте тёртую морковь и нарезанный сельдерей и готовьте 5–7 минут до золотистого цвета. Переложите в суп.</li><li>Достаньте курицу, остудите, разберите на волокна, выбросьте кости и жир. Верните мясо в кастрюлю.</li><li>Положите макароны, морковь кружочками и кукурузу. Варите на слабом кипении 15 минут до нужной мягкости пасты. При желании снимите лишний жир.</li><li>В отдельном ковшике растопите масло, всыпьте муку и прогревайте, помешивая, 1–2 минуты до лёгкого золотистого цвета. Влейте 1 половник горячего бульона, тщательно размешайте, добавьте сливки и перелейте смесь в суп.</li><li>Досолите, добавьте укроп, доведите до кипения и выключите огонь.</li></ol><p><em>Подавайте горячим со свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('3b19723d-7d42-5299-a3a7-be5da0e80ad3', '2e95df27-abe9-561f-acc4-2fc52f329b33', 'en', 'Creamy chicken noodle soup with dill', 'Chicken soup with vegetables, corn and pasta, enriched with a butter-flour roux and cream for a thick, mellow broth.', '<ol><li>In a large pot combine the broth, water and salt and bring to a boil. Add the chicken thighs and boil uncovered for 20 minutes, skimming off the foam.</li><li>Meanwhile sauté the onion in oil for 5 minutes, then add the grated carrot and chopped celery and cook 5-7 minutes until soft and golden. Transfer to the soup pot.</li><li>Remove the chicken, let it cool slightly, shred it and discard the bones and fat. Return the meat to the pot.</li><li>Add the pasta, sliced carrot and corn and cook at a low boil 15 minutes until the pasta is as soft as you like. Skim off excess fat if desired.</li><li>In a saucepan melt the butter, whisk in the flour and cook, stirring, 1-2 minutes until barely golden. Whisk in a ladle of hot broth, then the cream, and pour the mixture into the soup.</li><li>Season with more salt if needed, add the dill, bring back to a boil and turn off the heat.</li></ol><p><em>Serve hot with fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('ff2a2507-24ce-50c3-9c11-f9a1ff2534de', '355588a4-6704-5180-b1c2-817b576f3997', 'ru', 'Томатное рагу из баранины с картофелем (бредди)', 'Кейп-малайское рагу: баранина, долго томлёная в томатах с мягкими пряностями, с картофелем в конце.', '<ol><li>Обжарьте на сухой сковороде кориандр, гвоздику, душистый перец, корицу, перец горошком и хлопья чили до аромата. Остудите и завяжите в марлевый мешочек.</li><li>В большой кастрюле с толстым дном хорошо обжарьте баранину кусками на сильном огне в растительном масле. Выложите мясо и слейте лишний вытопившийся жир.</li><li>Добавьте лук, целый острый перец и лавровый лист, готовьте до мягкости лука, соскребая со дна румяные кусочки. Если лук темнеет слишком быстро, подлейте немного воды.</li><li>Добавьте соль, чеснок и томатную пасту и прогрейте, пока не исчезнет сырой запах пасты.</li><li>Верните мясо, добавьте томаты, сахар, мешочек со специями и воду так, чтобы жидкость покрывала мясо. Доведите до слабого кипения.</li><li>Накройте крышкой и тушите на малом огне 1–2 часа до мягкости мяса, при необходимости подливая воду. Духовка при 150 °C даёт тот же результат.</li><li>Добавьте картофель, четвертованный, и долейте воды при необходимости. Готовьте под крышкой ещё 20–30 минут, пока картофель не станет мягким. Выньте мешочек со специями, попробуйте и доведите по вкусу.</li></ol><p><em>Подайте с отварным рисом или свежим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('495d3a86-8f89-52c6-8adb-2d667a72da8e', '355588a4-6704-5180-b1c2-817b576f3997', 'en', 'Tomato bredie (South African lamb and potato stew)', 'A Cape Malay stew of lamb slowly simmered in tomatoes and mild spices, finished with potatoes.', '<ol><li>Toast the coriander seeds, cloves, allspice, cinnamon, peppercorns and chilli flakes in a dry pan until fragrant. Let cool and tie them in a piece of muslin.</li><li>In a large heavy pot brown the lamb chunks well in oil over high heat. Remove the meat and pour off excess rendered fat.</li><li>Add the onion, whole chilli and bay leaves and cook until the onion is soft, scraping up the browned bits from the bottom. Add a splash of water if the onion colours too fast.</li><li>Stir in the salt, garlic and tomato paste and cook until the raw smell of the paste disappears.</li><li>Return the meat, add the tomatoes, sugar, spice bag and enough water to cover. Bring to a gentle simmer.</li><li>Cover and simmer over low heat for 1–2 hours until the meat is tender, adding water as needed. The oven at 150°C works the same way.</li><li>Add the quartered potatoes, topping up the liquid if needed, and cook covered another 20–30 minutes until tender. Remove the spice bag, taste and adjust the seasoning.</li></ol><p><em>Serve with steamed rice or fresh bread.</em></p>', CURRENT_TIMESTAMP),
  ('365fce3a-e463-5bab-8e20-a863698f19d9', 'ae656f0c-e191-5102-a107-0b97b177d384', 'ru', 'Боботи: запечённый пряный фарш под яичной заливкой с жёлтым рисом', 'Южноафриканская запеканка из говяжьего фарша с луком, изюмом, карри и абрикосовым чатни, залитая молочно-яичной смесью. Подаётся с рисом с куркумой.', '<ol><li>Мелко нарежьте лук. Если изюм жёсткий, замочите его в тёплой воде.</li><li>Разогрейте сковороду на сильном огне и обжарьте говяжий фарш порциями до румяности, чтобы мясо не тушилось в собственном соку. Отцедите жир через сито.</li><li>Обжарьте лук с чесноком и имбирём на сливочном масле на малом огне до мягкости, не давая ему карамелизоваться.</li><li>Добавьте карри, куркуму, соль и изюм, перемешайте. Положите томатную пасту, чатни, вустерский соус и коричневый сахар, прогрейте минуту. Добавьте молотый имбирь и фарш и тушите несколько минут на малом огне, пока масса не соберётся.</li><li>Разогрейте духовку до 180 °C. Выложите фарш в жаропрочную форму, не утрамбовывая. Взбейте яйца с молоком и залейте сверху. По традиции украсьте лавровыми листьями.</li><li>Поставьте форму в противень с горячей водой и запекайте 35 минут, пока заливка не схватится.</li><li>Для риса промойте басмати до прозрачной воды, добавьте воду, соль, масло и куркуму, доведите до кипения, накройте крышкой и варите на минимальном огне 15 минут. Оставьте под крышкой на 3 минуты.</li></ol><p><em>Хорошо сочетается с свежим салатом из помидоров и лука.</em></p>', CURRENT_TIMESTAMP),
  ('61bf7101-437b-55a4-9261-7d7e799b1657', 'ae656f0c-e191-5102-a107-0b97b177d384', 'en', 'Bobotie (South African spiced beef bake) with yellow rice', 'A South African bake of spiced beef mince with onion, raisins, curry and apricot chutney, topped with an egg and milk custard and served with turmeric rice.', '<ol><li>Finely chop the onion. Soak the raisins in warm water if they are hard.</li><li>Heat a pan over high heat and brown the mince in batches so it does not stew in its own juices. Drain off the fat through a sieve.</li><li>Cook the onion with the garlic and ginger in butter over low heat until soft, without caramelising.</li><li>Stir in the curry powder, turmeric, salt and raisins. Add the tomato paste, chutney, Worcestershire sauce and brown sugar and cook for a minute. Add the ground ginger and the mince and cook a few more minutes over low heat until it comes together.</li><li>Heat the oven to 180°C. Spread the filling in a baking dish without pressing it down. Whisk the eggs with the milk, pour over the top and decorate with bay leaves as is traditional.</li><li>Set the dish in a tray of hot water and bake for 35 minutes until the custard is set.</li><li>For the rice, wash the basmati until the water runs clear, add the water, salt, butter and turmeric, bring to a boil, cover and cook on the lowest heat for 15 minutes. Rest covered for 3 minutes.</li></ol><p><em>Serve with a fresh tomato and onion salad.</em></p>', CURRENT_TIMESTAMP),
  ('a9c0161b-a6ea-5016-a9c9-475447e2feaa', '81f10721-cb47-5ec7-851c-549dc9647acf', 'ru', 'Салат оливье по-персидски с курицей', 'Сытный салат из картофеля, куриных бёдер, яиц, зелёного горошка и корнишонов, заправленный майонезом и оливковым маслом.', '<ol><li>Отварите картофель в подсоленной воде до мягкости. Сварите яйца вкрутую, остудите и очистите.</li><li>Пока варится картофель, запеките куриные бёдра с оливковым маслом, луком и чесноком при 160 °C до готовности. Разберите мясо на волокна, сок сохраните.</li><li>Мелко нарежьте корнишоны. Очищенный картофель грубо разомните вилкой. Горошек залейте кипятком и слейте воду. Яйца натрите на крупной тёрке.</li><li>Соедините курицу, картофель, горошек, корнишоны и яйца в большой миске, добавьте майонез и оливковое масло, посолите, поперчите и аккуратно перемешайте до пышной кремовой массы.</li><li>Выложите на блюдо, украсьте оливками и корнишонами, сбрызните оливковым маслом.</li></ol><p><em>Подайте с тёплым лавашем или лепёшкой, украсив оливками и корнишонами.</em></p>', CURRENT_TIMESTAMP),
  ('62e49257-8bac-5903-ae05-5530af591f57', '81f10721-cb47-5ec7-851c-549dc9647acf', 'en', 'Persian olivieh chicken and potato salad', 'A hearty salad of potatoes, chicken thighs, eggs, peas and cornichons dressed with mayonnaise and olive oil.', '<ol><li>Boil the potatoes in salted water until fork-tender. Hard-boil the eggs, cool and peel them.</li><li>While the potatoes cook, bake the chicken thighs with a little olive oil, the onion and garlic at 160°C until cooked through. Shred the meat and keep the juices.</li><li>Finely chop the cornichons. Peel the potatoes and roughly mash them with a fork. Defrost the peas in boiling water and drain. Coarsely grate the eggs.</li><li>Combine the chicken, potatoes, peas, cornichons and eggs in a large bowl, add the mayonnaise and olive oil, season with salt and pepper and mix gently until creamy and fluffy.</li><li>Spoon onto a platter, garnish with olives and cornichons and drizzle with olive oil.</li></ol><p><em>Serve with warm lavash or flatbread, garnished with olives and cornichons.</em></p>', CURRENT_TIMESTAMP),
  ('74b2e31e-bf15-50c7-97f9-85f6da3229c3', 'd844b098-afd4-5e85-93ff-b013fb0dfde1', 'ru', 'Маклюба: перевёрнутый рис с курицей, баклажаном и цветной капустой', 'Слоёное арабское блюдо: курица, запечённые баклажаны и цветная капуста, рис басмати с корицей и душистым перцем. Готовится в кастрюле и переворачивается на блюдо.', '<ol><li>Промойте рис до прозрачной воды, залейте холодной водой с 1 ч. л. соли на 10 минут и хорошо слейте.</li><li>Нарежьте баклажан кружками толщиной около 2 см, посолите с обеих сторон и оставьте на 20–30 минут, затем промокните бумажным полотенцем.</li><li>Разогрейте духовку до 220 °C. Смажьте два противня маслом. Цветную капусту, разобранную на соцветия, перемешайте с солью и ¼ стакана масла и выложите на один противень, баклажан — на другой. Запекайте баклажан 15–20 минут до мягкости и достаньте. Капусту продолжайте печь при 230 °C ещё 30–40 минут до мягкости и подрумянивания.</li><li>Приправьте курицу солью, перцем, 1 ч. л. душистого перца и ½ ч. л. корицы. В кастрюле с крышкой разогрейте 3 ст. л. масла и обжарьте курицу с луком на среднем и сильном огне 8–10 минут, пока курица не зарумянится, а лук не станет мягким.</li><li>Добавьте чеснок, лавровый лист, кардамон, воду и щепотку соли. Доведите до кипения, накройте и тушите на среднем и слабом огне 20 минут. Выньте курицу, бульон процедите и отложите.</li><li>Вытрите кастрюлю, влейте 2 ст. л. масла и выложите слоями: кружки помидора, баклажан, цветную капусту, курицу. Сверху насыпьте рис, посыпьте куркумой, оставшимися душистым перцем и корицей. Залейте 2 стаканами (около 480 мл) бульона и слегка прижмите.</li><li>Доведите до кипения на среднем огне и варите 10 минут. Убавьте огонь до минимума, накройте и готовьте около 30 минут, пока рис не впитает жидкость. Выключите огонь и оставьте под крышкой на 15–20 минут.</li><li>Обжарьте миндаль на 1 ст. л. масла 3–4 минуты до золотистого цвета. Накройте кастрюлю большим блюдом, быстро переверните, слегка постучите по дну и снимите кастрюлю. Посыпьте миндалём и петрушкой.</li></ol><p><em>Посыпьте обжаренным миндалём и петрушкой, подайте с йогуртом или салатом из огурцов.</em></p>', CURRENT_TIMESTAMP),
  ('794b9bee-75d7-55a4-af19-c631881d3ae4', 'd844b098-afd4-5e85-93ff-b013fb0dfde1', 'en', 'Maqluba (upside-down chicken, rice, eggplant and cauliflower)', 'A layered Levantine dish of chicken, roasted eggplant and cauliflower and spiced basmati rice, cooked in one pot and flipped onto a platter.', '<ol><li>Rinse the rice until the water runs clear, soak it in cold water with 1 tsp of salt for 10 minutes and drain well.</li><li>Cut the eggplant into rounds about ¾ inch (2 cm) thick, salt both sides, leave for 20–30 minutes and pat dry.</li><li>Heat the oven to 425°F (220°C). Oil two sheet pans. Toss the cauliflower florets with salt and ¼ cup of the oil and spread on one pan, and put the eggplant on the other. Roast the eggplant 15–20 minutes until soft and remove it. Raise the heat to 450°F (230°C) and roast the cauliflower another 30–40 minutes until soft and charred in spots.</li><li>Season the chicken with salt, pepper, 1 tsp of allspice and ½ tsp of cinnamon. In a lidded pot heat 3 tbsp of oil and brown the chicken with the onion over medium-high heat for 8–10 minutes until the onion is tender.</li><li>Add the garlic, bay leaves, cardamom, water and a pinch of salt. Bring to a boil, cover and simmer over medium-low heat for 20 minutes. Remove the chicken and strain the broth, reserving it.</li><li>Wipe out the pot, add 2 tbsp of oil and layer the tomato slices, eggplant, cauliflower and chicken. Pour the rice on top and sprinkle with turmeric and the remaining allspice and cinnamon. Add 2 cups (about 480 ml) of the reserved broth and gently press down.</li><li>Bring to a simmer over medium-high heat and cook 10 minutes. Reduce to low, cover and cook about 30 minutes until the rice absorbs the liquid. Turn off the heat and rest covered for 15–20 minutes.</li><li>Toast the almonds in 1 tbsp of oil for 3–4 minutes until golden. Place a large platter over the pot, flip it quickly, tap the bottom and lift off the pot. Top with the almonds and parsley.</li></ol><p><em>Top with toasted almonds and parsley and serve with yogurt or a cucumber salad.</em></p>', CURRENT_TIMESTAMP),
  ('fbdfde08-556e-50cb-a51e-85f360418296', 'b2852808-bec8-5af1-bad7-82b20601c475', 'ru', 'Греческие фрикадельки кефтедес в лимонном соусе', 'Сочные говяжьи фрикадельки с бараниной, мятой и специями, обжаренные в муке и доведённые в лимонном соусе с яичным желтком.', '<ol><li>Нарежьте хлеб кубиками, залейте молоком и оставьте на 5 минут.</li><li>В большой сковороде на среднем огне прогрейте 2 ст. л. масла и обжарьте тёртый лук с чесноком до золотистого и прозрачного. Переложите в миску и остудите, сковороду отставьте.</li><li>Отожмите хлеб и добавьте в миску с луком. Добавьте говяжий и бараний фарш, целое яйцо, мяту, специи, 1 ст. л. лимонной цедры, соль и перец. Вымесите руками до однородности.</li><li>Сформируйте шарики размером с полную столовую ложку (около 32 штук), слегка обваляйте в муке и выложите на поднос.</li><li>В той же сковороде разогрейте оставшееся масло (¼ стакана), убавьте огонь до среднего и жарьте фрикадельки порциями, переворачивая, около 10 минут до готовности и румяной корочки.</li><li>Переложите фрикадельки на бумажные полотенца. Взбейте желток с бульоном, лимонным соком и оставшейся цедрой. Слейте почти весь жир из сковороды, влейте лимонную смесь, верните фрикадельки и готовьте на среднем огне около 5 минут, пока соус не загустеет.</li></ol><p><em>Подайте с лепёшкой пита, греческим салатом и цацики.</em></p>', CURRENT_TIMESTAMP),
  ('a51ac84a-cd6c-540a-95f2-1952f08f825b', 'b2852808-bec8-5af1-bad7-82b20601c475', 'en', 'Greek meatballs (keftedes) in lemon sauce', 'Juicy beef and lamb meatballs with mint and warm spices, pan-fried in flour and finished in a lemon-egg-yolk sauce.', '<ol><li>Cube the bread, cover it with the milk and set aside for 5 minutes.</li><li>In a large skillet over medium heat warm 2 tbsp of the oil and cook the grated onion and garlic until golden and translucent. Transfer to a large bowl to cool and set the skillet aside.</li><li>Squeeze the bread dry and add it to the bowl with the onion. Add the ground beef and lamb, the whole egg, mint, spices, 1 tbsp of lemon zest, salt and pepper. Mix by hand until combined.</li><li>Shape into heaping-tablespoon-sized balls (about 32), roll lightly in flour and set on a tray.</li><li>Heat the remaining ¼ cup oil in the same skillet over medium-high, reduce to medium and fry the meatballs in batches, turning, for about 10 minutes until cooked through and crusted.</li><li>Drain the meatballs on paper towels. Whisk the egg yolk with the broth, lemon juice and remaining zest. Pour off most of the fat, add the lemon mixture to the skillet, return the meatballs and cook over medium heat about 5 minutes until the sauce thickens.</li></ol><p><em>Serve with pita, Greek salad and tzatziki.</em></p>', CURRENT_TIMESTAMP),
  ('131d0bf9-2000-5c78-a6b7-bc59ade59a97', 'e7a0948a-4a02-5d97-8cd2-7db9bcf2bf91', 'ru', 'Курица с брокколи на сковороде с лимоном и чесноком', 'Куриные грудки, обжаренные с травами и лимонной цедрой, и брокколи с чесноком. Всё доводится до готовности под крышкой в одной сковороде.', '<ol><li>Смажьте куриные грудки 2 ст. л. оливкового масла и приправьте 1 ч. л. соли, хлопьями чили, тимьяном, орегано и лимонной цедрой.</li><li>В большой сковороде разогрейте на среднем и сильном огне оставшиеся 2 ст. л. масла и обжарьте грудки по 4 минуты с каждой стороны до румяности. Они не должны быть готовы полностью. Переложите на тарелку.</li><li>В ту же сковороду добавьте чеснок, соцветия брокколи и оставшиеся ½ ч. л. соли и обжаривайте около 2 минут, пока овощи слегка не поменяют цвет.</li><li>Верните курицу в сковороду, раздвинув брокколи, влейте воду, накройте крышкой и готовьте 10 минут до готовности курицы.</li><li>Снимите с огня, сбрызните лимонным соком, при желании посыпьте пармезаном. Добавьте чёрный перец и при необходимости соль.</li></ol><p><em>Подайте с рисом, киноа или ломтём хлеба.</em></p>', CURRENT_TIMESTAMP),
  ('76ea3101-b41b-5a3a-9c8c-73d0aa4160ab', 'e7a0948a-4a02-5d97-8cd2-7db9bcf2bf91', 'en', 'Skillet chicken and broccoli with lemon and garlic', 'Chicken breasts seared with herbs and lemon zest, then finished with garlicky broccoli, all in one skillet.', '<ol><li>Coat the chicken breasts with 2 tbsp of olive oil and season with 1 tsp of salt, red pepper flakes, thyme, oregano and lemon zest.</li><li>Heat the remaining 2 tbsp of oil in a large skillet over medium-high heat and sear the breasts about 4 minutes per side until browned. They do not need to be cooked through. Set aside on a plate.</li><li>Add the garlic, broccoli florets and the remaining ½ tsp of salt to the same pan and sauté about 2 minutes until they pick up a little color.</li><li>Nestle the chicken back among the broccoli, pour in the water, cover and cook for 10 minutes until the chicken is cooked through.</li><li>Remove from the heat, squeeze over the lemon juice and, if you like, sprinkle with parmesan. Add black pepper and extra salt to taste.</li></ol><p><em>Serve with rice, quinoa or crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('1fba7293-b14c-5637-8f2e-45e8f492b1c8', 'c7e27bd8-0b10-5b76-9a7f-c4bcfbfcab49', 'ru', 'Рататуй из баклажанов, кабачков и томатов', 'Овощное рагу из баклажанов, кабачков, сладкого перца и помидоров с чесноком, красным вином и травами. Тушится в одной кастрюле.', '<ol><li>Нарежьте баклажан кубиками по 2,5 см, посыпьте солью, оставьте в дуршлаге на 20 минут, затем промокните от влаги.</li><li>В толстостенной кастрюле разогрейте 2 ст. л. оливкового масла и готовьте лук около 5 минут до прозрачности. Добавьте перец и готовьте ещё 4 минуты, помешивая.</li><li>Добавьте чеснок, помидоры с соком, кабачки, баклажан, вино и тимьян. Всыпьте чёрный перец, паприку, розмарин и посолите.</li><li>Доведите до кипения на среднем и сильном огне и варите 5 минут, пару раз перемешав. Убавьте огонь, накройте крышкой и тушите около 20 минут.</li><li>Снимите с огня, попробуйте и досолите. Добавьте хересный уксус, обильно сбрызните оливковым маслом и посыпьте базиликом. По возможности дайте постоять под крышкой около часа.</li></ol><p><em>Хорош тёплым, комнатной температуры и холодным. Подайте с глазуньей и хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('a2a8a542-f8e9-5f27-9ee1-80d32f868305', 'c7e27bd8-0b10-5b76-9a7f-c4bcfbfcab49', 'en', 'One-pot ratatouille (vegetable stew)', 'A stew of eggplant, zucchini, bell pepper and tomatoes with garlic, red wine and herbs, simmered in a single pot.', '<ol><li>Cut the eggplant into 1-inch cubes, sprinkle with salt, leave in a colander for 20 minutes and pat dry.</li><li>In a heavy pot heat 2 tbsp of olive oil over medium heat and cook the onion about 5 minutes until translucent. Add the bell peppers and cook another 4 minutes, stirring.</li><li>Add the garlic, tomatoes with their juices, zucchini, eggplant, wine and thyme. Stir in the black pepper, paprika and rosemary and season with salt.</li><li>Bring to a boil over medium-high heat for 5 minutes, stirring once or twice. Reduce the heat, cover and simmer about 20 minutes.</li><li>Remove from the heat, taste and adjust the salt. Add the sherry vinegar, drizzle generously with olive oil and top with basil. If you have time, let it rest covered for about an hour.</li></ol><p><em>Delicious warm, at room temperature or cold. Top with a fried egg and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('94503d7d-491e-540f-a7ff-d5a97cd23956', '78167ffa-19c2-5f2d-8ed2-2ce850415b55', 'ru', 'Креветки саганаки в томатном соусе с феттой', 'Креветки, тушёные в томатном соусе с луком, чесноком и травами, со свежей мятой, петрушкой, сыром фета и оливками.', '<ol><li>Обсушите креветки и смешайте с ½ ч. л. орегано, ½ ч. л. сушёного укропа, 1 зубчиком чеснока, солью, перцем и хлопьями чили. Добавьте немного оливкового масла и перемешайте.</li><li>В большой сковороде на среднем огне разогрейте около 2 ст. л. масла, добавьте лук и оставшийся чеснок и прогрейте до аромата. Влейте томаты, слив примерно половину жидкости из банки, и лимонный сок. Посолите, поперчите, добавьте оставшиеся орегано и укроп. Доведите до кипения, убавьте огонь и варите 15 минут.</li><li>Добавьте креветки и готовьте 5–7 минут, иногда помешивая, пока они не порозовеют. Не передерживайте.</li><li>Добавьте мяту и петрушку, посыпьте фетой и рублеными оливками. Доведите по вкусу лимонным соком, солью и хлопьями чили.</li></ol><p><em>Подайте с орзо, рисом или хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('11b10a27-54b3-5607-b935-cf1f8b7ec38b', '78167ffa-19c2-5f2d-8ed2-2ce850415b55', 'en', 'Shrimp saganaki with tomato and feta', 'Shrimp simmered in a tomato sauce with onion, garlic and herbs, finished with fresh mint, parsley, feta and olives.', '<ol><li>Pat the shrimp dry and toss with ½ tsp each of oregano and dried dill, 1 minced garlic clove, salt, pepper and red pepper flakes. Add a drizzle of olive oil and mix.</li><li>In a large skillet heat about 2 tbsp of oil over medium, add the onion and the rest of the garlic and stir until fragrant. Add the tomatoes (draining about half the canned liquid) and the lemon juice. Season with salt, pepper and the remaining oregano and dill. Bring to a boil, reduce the heat and simmer 15 minutes.</li><li>Add the shrimp and cook, stirring occasionally, 5–7 minutes until pink. Do not overcook.</li><li>Stir in the mint and parsley and sprinkle with feta and chopped olives. Adjust with more lemon juice, salt or red pepper flakes.</li></ol><p><em>Serve with orzo, rice or crusty bread to soak up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('2760b907-4908-57cd-a236-db5edf8aadd1', '93bf8f73-ddf9-567c-afe3-cdaae8743068', 'ru', 'Болоньезе из красной чечевицы с пастой', 'Густой веганский соус из красной чечевицы, томатов, моркови, фенхеля и белого вина. Подаётся с пастой.', '<ol><li>В большой кастрюле на среднем огне разогрейте оливковое масло, обжарьте лук, морковь и фенхель 10 минут, помешивая, до мягкости и лёгкого румянца.</li><li>Добавьте томатную пасту и жарьте 2–3 минуты, пока она не потемнеет и не начнёт прилипать ко дну. Добавьте чеснок и хлопья чили на минуту.</li><li>Влейте вино, соскребите прилипшие кусочки и выпарите вино.</li><li>Добавьте овощной бульон, томаты, чечевицу и соль. Доведите до кипения, убавьте огонь и варите под неплотной крышкой около 30 минут, пока чечевица не развалится. Параллельно отварите пасту по инструкции.</li><li>Пробейте соус погружным блендером до густой, слегка рубленой консистенции. Посолите по вкусу и подайте с пастой.</li></ol><p><em>Посыпьте свежим базиликом; подойдёт к любой пасте.</em></p>', CURRENT_TIMESTAMP),
  ('9ea58796-5b64-52b2-93bb-29fb9682e575', '93bf8f73-ddf9-567c-afe3-cdaae8743068', 'en', 'Red lentil bolognese with pasta', 'A thick vegan ragù of red lentils, tomatoes, carrot, fennel and white wine served over pasta.', '<ol><li>In a large pot over medium heat warm the olive oil and cook the onion, carrot and fennel, stirring, about 10 minutes until softened and lightly browning.</li><li>Add the tomato paste and cook 2–3 minutes until it darkens and starts to stick to the bottom. Add the garlic and chilli flakes for a minute.</li><li>Pour in the wine, scrape up the browned bits and let it evaporate.</li><li>Add the vegetable broth, tomatoes, lentils and salt. Bring to a boil, reduce the heat and simmer partly covered about 30 minutes until the lentils fall apart. Meanwhile cook the pasta according to the package.</li><li>Blend the sauce with an immersion blender until thick and a bit chunky. Season with salt and serve over the pasta.</li></ol><p><em>Top with fresh basil; works with any pasta shape.</em></p>', CURRENT_TIMESTAMP),
  ('cf9145ae-80f0-5970-9073-3fd4dee1c625', '207d48ac-4a64-5fd4-8a02-6de175aa9ba5', 'ru', 'Запечённые фрикадельки из индейки с фетой и шпинатом', 'Сочные фрикадельки из фарша индейки со шпинатом, фетой, петрушкой и сушёной мятой. Запекаются на противне, не разваливаются.', '<ol><li>Разогрейте духовку до 200 °C, слегка смажьте противень маслом.</li><li>Подсушите хлеб в тостере до румяности, залейте водой на 5 минут, пока не станет очень мягким, слейте воду и хорошо отожмите. Раскрошите в сухую миску.</li><li>Разогрейте масло в сковороде на среднем огне и ненадолго обжарьте шпинат до увядания. Слегка остудите.</li><li>В миску с хлебом добавьте фарш индейки, тёртый лук, чеснок, раскрошенную фету, яйцо, петрушку, мяту и шпинат. Посолите, поперчите и хорошо перемешайте.</li><li>Сформируйте шарики размером с мяч для гольфа, выложите на противень и запекайте около 30 минут до готовности.</li><li>Для румяной корочки переставьте на верхнюю полку и на пару минут включите гриль, следя, чтобы не подгорело.</li></ol><p><em>Подайте с салатом, рисом или пастой в томатном соусе.</em></p>', CURRENT_TIMESTAMP),
  ('356df6ec-ede6-5f35-9d04-dc64cd624f24', '207d48ac-4a64-5fd4-8a02-6de175aa9ba5', 'en', 'Baked turkey meatballs with feta and spinach', 'Juicy ground turkey meatballs with spinach, feta, parsley and dried mint, baked on a sheet pan.', '<ol><li>Heat the oven to 200°C (400°F) and lightly oil a large sheet pan.</li><li>Toast the bread until just brown, cover with water for about 5 minutes until very tender, drain and squeeze very dry. Crumble into a dry bowl.</li><li>Heat the oil in a skillet over medium heat and cook the spinach briefly until just wilted. Let it cool a little.</li><li>Add the ground turkey, grated onion, garlic, crumbled feta, egg, parsley, mint and spinach to the bowl with the bread. Season with salt and pepper and mix well.</li><li>Form golf-ball-sized balls, arrange on the pan and bake about 30 minutes until cooked through.</li><li>For browned tops move to the top rack and broil for a couple of minutes, watching closely so they do not burn.</li></ol><p><em>Serve with a salad, rice, or pasta in tomato sauce.</em></p>', CURRENT_TIMESTAMP),
  ('7e871982-4f15-5729-b257-9a1b00efbc20', 'a02a1320-aac6-557c-a209-5c31c408f32b', 'ru', 'Треска, запечённая с лимоном и чесноком', 'Филе трески в лимонно-масляном соусе, обвалянное в муке со специями, слегка обжаренное и доведённое в духовке с чесноком и петрушкой.', '<ol><li>Разогрейте духовку до 200 °C.</li><li>В неглубокой миске смешайте лимонный сок, оливковое масло (5 ст. л.) и растопленное сливочное масло, чеснок пока не добавляйте.</li><li>В другой миске смешайте муку, кориандр, паприку, зиру, соль и перец.</li><li>Обсушите рыбу, обмакните в лимонную смесь, затем обваляйте в муке со специями и стряхните лишнее. Лимонную смесь сохраните.</li><li>В чугунной или жаропрочной сковороде разогрейте 2 ст. л. масла на среднем и сильном огне и обжарьте рыбу по 2 минуты с каждой стороны, только для цвета. Снимите с огня.</li><li>В оставшуюся лимонную смесь добавьте чеснок и полейте рыбу. Запекайте около 10 минут, пока рыба не начнёт легко разделяться вилкой. Посыпьте петрушкой и подавайте сразу.</li></ol><p><em>Подайте с рисом, картофелем или овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e615a121-48d9-5e69-afb5-411e4ce4a4ab', 'a02a1320-aac6-557c-a209-5c31c408f32b', 'en', 'Baked cod with lemon and garlic', 'Cod fillets dipped in lemon-butter-oil sauce and spiced flour, seared briefly and finished in the oven with garlic and parsley.', '<ol><li>Heat the oven to 200°C (400°F).</li><li>In a shallow bowl mix the lemon juice, 5 tbsp of the olive oil and the melted butter, without the garlic yet.</li><li>In another bowl mix the flour, coriander, paprika, cumin, salt and pepper.</li><li>Pat the fish dry, dip in the lemon mixture, then dredge in the spiced flour and shake off the excess. Reserve the lemon mixture.</li><li>Heat 2 tbsp of oil in a cast iron or ovenproof skillet over medium-high and sear the fish about 2 minutes per side, just for color. Remove from the heat.</li><li>Stir the garlic into the leftover lemon mixture and drizzle it over the fish. Bake about 10 minutes until the fish flakes easily with a fork. Sprinkle with parsley and serve immediately.</li></ol><p><em>Serve with rice, potatoes or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('0f271e32-f803-5ead-998c-6ae8c85fb8c4', 'b0280d4a-6b03-5ac6-9eaf-c23dbc89e0c3', 'ru', 'Курица в сливочном соусе с марсалой и грибами', 'Куриные отбивные в муке, обжаренные до золотистой корочки, под соусом из вина марсала, бульона и сливок с шампиньонами.', '<ol><li>Разрежьте грудки вдоль пополам, получится 4 пласта. Отбейте через плёнку до толщины около 8 мм, посолите, поперчите и обваляйте в муке, стряхнув лишнюю.</li><li>Разогрейте в большой сковороде с толстым дном оливковое и сливочное масло на среднем огне. Обжаривайте курицу по 3–4 минуты с каждой стороны до золотистого цвета (внутри 74 °C). Отложите и накройте фольгой.</li><li>При необходимости добавьте в сковороду масла, обжарьте шампиньоны 5 минут, пока не испарится жидкость и они не зарумянятся. Добавьте сушёный лук и чеснок на 30 секунд.</li><li>Влейте марсалу, соскребая румяные частицы со дна, и увеличьте огонь: выпаривайте 4–5 минут почти досуха. Добавьте бульон и тонкой струйкой сливки, убавьте огонь и уваривайте ещё 4–5 минут до лёгкого загустения. Посолите.</li><li>Верните курицу в сковороду, посыпьте петрушкой и полейте соусом. Прогрейте 2 минуты, пока соус не загустеет до нужной консистенции.</li></ol><p><em>Подавайте с пюре, пастой или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('7a50c69c-901a-5c17-9edc-c47c9d17dc5f', 'b0280d4a-6b03-5ac6-9eaf-c23dbc89e0c3', 'en', 'Creamy chicken marsala with mushrooms', 'Floured chicken cutlets pan-fried until golden and served in a sauce of marsala wine, stock and cream with mushrooms.', '<ol><li>Cut the chicken breasts in half lengthwise to make 4 cutlets. Pound between plastic wrap to about 8 mm thick, season with salt and pepper and dredge in flour, shaking off the excess.</li><li>Heat the olive oil and butter in a large heavy pan over medium heat. Cook the chicken 3-4 minutes per side until golden and cooked through (74°C inside). Set aside and tent with foil.</li><li>Add a little more oil if needed and sauté the mushrooms 5 minutes until the liquid evaporates and they turn golden. Add the onion powder and garlic for 30 seconds.</li><li>Pour in the marsala, scraping the pan bottom, and boil 4-5 minutes until mostly reduced. Add the stock and a steady stream of cream, lower the heat and simmer 4-5 minutes more until slightly thickened. Season with salt.</li><li>Return the chicken to the pan, sprinkle with parsley and spoon the sauce over. Heat 2 more minutes until the sauce reaches the thickness you like.</li></ol><p><em>Serve with mashed potatoes, pasta or rice.</em></p>', CURRENT_TIMESTAMP),
  ('b7b00dca-b46a-5281-b221-6820ec4b9aa2', '1e7e173f-5d30-50b6-9fa6-eb550784e023', 'ru', 'Чили из индейки с тремя видами фасоли и кукурузой', 'Сытное жаркое из фарша индейки, томатов, чёрной, красной и пинто-фасоли и кукурузы с чили и зирой. Делается в одной кастрюле или в мультиварке.', '<ol><li>В кастрюле на 5 л разогрейте масло на средне-сильном огне и обжарьте фарш индейки до готовности, около 5 минут.</li><li>Добавьте нарезанный лук, чили, зиру, чесночный порошок, орегано, соль и перец. Готовьте 5 минут до мягкости лука.</li><li>Добавьте томаты с соком, томатный соус, всю фасоль, чили из банки и кукурузу.</li><li>Перемешайте, доведите до кипения, убавьте огонь и варите 20 минут, не полностью закрыв крышкой, иногда помешивая. Для более жидкой консистенции в конце влейте бульон или воду. В конце попробуйте и досолите.</li></ol><p><em>Подавайте с тортильей или поверх печёного картофеля.</em></p>', CURRENT_TIMESTAMP),
  ('3f7fbce4-b1c2-5b2c-b98b-cdeeab37f929', '1e7e173f-5d30-50b6-9fa6-eb550784e023', 'en', 'Turkey chili with three beans and corn', 'A filling pot of ground turkey, tomatoes, black, kidney and pinto beans and corn seasoned with chili powder and cumin. Made in one pot or in a slow cooker.', '<ol><li>In a 5-quart pot over medium-high heat, heat the oil and cook the ground turkey until done, about 5 minutes.</li><li>Add the diced onion, chili powder, cumin, garlic powder, oregano, salt and pepper. Cook 5 minutes until the onion softens.</li><li>Add the tomatoes with their juice, tomato sauce, all the beans, the diced chilis and the corn.</li><li>Stir, bring to a boil, then reduce and simmer partially covered 20 minutes, stirring occasionally. Thin with stock or water at the end if you like, and adjust the seasoning.</li></ol><p><em>Serve with tortilla chips or over baked potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('21d1ef6c-5e09-59e3-8983-fd8c92fe0959', 'fa3072a9-d40c-507b-b202-512b553c6eff', 'ru', 'Энчилада с курицей и сливочным сыром', 'Пшеничные лепёшки с начинкой из курицы, сыра и сливочно-томатного соуса, запечённые под слоем сыра. Хорошо готовить заранее.', '<ol><li>Разогрейте духовку до 200 °C и смажьте форму 23×33 см. Если нет готовой курицы, залейте мясо водой в кастрюле, посолите и варите 8–10 минут до готовности, затем разберите вилками на волокна.</li><li>Взбейте сливочный сыр. Добавьте сметану, зелёные чили, соус энчилада, соль, перец, чесночный порошок и паприку и взбейте до однородности.</li><li>Разделите соус: две трети переложите в большую миску, а одну треть отложите для верха.</li><li>Смешайте курицу и 2 стакана сыра с соусом в большой миске.</li><li>Выложите начинку в центр каждой лепёшки, плотно сверните и уложите швом вниз в форму.</li><li>Полейте энчилады оставшимся соусом и посыпьте оставшимся сыром.</li><li>Накройте фольгой и выпекайте при 200 °C 30 минут, затем снимите фольгу и запекайте ещё 10 минут, пока сыр не расплавится.</li></ol><p><em>Подавайте со сметаной, зеленью и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('2f3f456a-e5b2-5dd1-b366-eb0606da8c34', 'fa3072a9-d40c-507b-b202-512b553c6eff', 'en', 'Creamy chicken enchiladas', 'Flour tortillas rolled around chicken, cheese and a creamy red enchilada sauce, then baked under more cheese. A good make-ahead dinner.', '<ol><li>Heat the oven to 200°C (400°F) and grease a 9x13-inch dish. If you don''t have cooked chicken, cover it with salted water in a saucepan and cook 8-10 minutes until done, then shred with two forks.</li><li>Beat the cream cheese, then add the sour cream, green chilis, enchilada sauce, salt, pepper, garlic powder and paprika and mix until smooth.</li><li>Divide the sauce: two thirds into a large bowl, one third set aside for the top.</li><li>Mix the chicken and 2 cups of cheese with the larger portion of sauce.</li><li>Spoon filling into the center of each tortilla, roll up tightly and place seam-side down in the dish.</li><li>Pour the reserved sauce over the tortillas and sprinkle with the remaining cheese.</li><li>Cover with foil and bake at 200°C for 30 minutes, then uncover and bake another 10 minutes until the cheese melts.</li></ol><p><em>Serve with sour cream, herbs and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('30555247-bff0-5f38-9db1-3f382a112e03', '9e9b90eb-5fce-5f6e-bdbe-04ba63695142', 'ru', 'Говядина с овощами и грибами в соевом соусе с кленовым сиропом', 'Быстрое жаркое из тонко нарезанной говядины с кабачком, перцем, луком и грибами в простом соусе из соевого соуса, кленового сиропа и барбекю.', '<ol><li>Смешайте три ингредиента соуса: соевый соус, кленовый сироп и барбекю. Отложите.</li><li>Разогрейте большую сковороду или вок на сильном огне с 1 ст. л. масла. Выложите говядину одним слоем и жарьте без помешивания 2–3 минуты, затем помешайте и готовьте ещё около 2 минут. Слегка посолите, поперчите, добавьте имбирь и чеснок на 1 минуту.</li><li>Влейте часть соуса и жарьте ещё минуту до готовности мяса. Переложите мясо на тарелку и накройте, сковороду вытрите бумажным полотенцем.</li><li>Разогрейте в чистой сковороде ещё 1 ст. л. масла и обжарьте грибы 5 минут до золотистого цвета, слегка посолив и поперчив. Переложите к мясу.</li><li>Добавьте последнюю столовую ложку масла, лук, кабачок и перец и жарьте около 8 минут до мягкости и золотистого цвета.</li><li>Верните мясо и грибы к овощам, добавьте остальной соус по вкусу и прогрейте. Подавайте с рисом, посыпав кунжутом.</li></ol><p><em>Подавайте с горячим рисом.</em></p>', CURRENT_TIMESTAMP),
  ('4e24c768-2ee2-583b-bc8a-7f904ef8c885', '9e9b90eb-5fce-5f6e-bdbe-04ba63695142', 'en', 'Beef stir-fry with zucchini, mushrooms and soy-maple sauce', 'A quick stir-fry of thinly sliced beef with zucchini, bell pepper, onion and mushrooms in an easy sauce of soy, maple syrup and BBQ sauce.', '<ol><li>Stir together the soy sauce, maple syrup and BBQ sauce and set aside.</li><li>Heat a large heavy pan or wok over high heat with 1 tbsp oil. Add the beef in a single layer and sear undisturbed 2-3 minutes, then stir and cook about 2 minutes more. Season lightly, add the ginger and garlic and cook 1 minute.</li><li>Drizzle in some of the sauce and stir-fry another minute until the beef is cooked. Move the beef to a plate, cover, and wipe the pan clean.</li><li>Heat 1 tbsp oil in the clean pan and stir-fry the mushrooms 5 minutes until golden, lightly seasoned. Add them to the beef.</li><li>Add the last tablespoon of oil, then the onion, zucchini and pepper and stir-fry about 8 minutes until soft and golden.</li><li>Combine the vegetables with the beef and mushrooms, add more sauce to taste and heat through. Serve over rice, sprinkled with sesame seeds.</li></ol><p><em>Serve over hot steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('22b6294e-3072-5ccd-ad99-f5425a412923', '9cc3a187-4eb6-57b8-a863-48658dae7cba', 'ru', 'Лосось по-тоскански со сливками, вялеными томатами и шпинатом', 'Лосось, обжаренный до хрустящих краёв, под сливочным соусом с чесноком, вялеными томатами, пармезаном и шпинатом.', '<ol><li>Посолите и поперчите филе лосося, посыпьте чесночным порошком.</li><li>Растопите масла на большой сковороде на среднем огне. Когда сливочное масло перестанет пениться, выложите лосось кожей вверх и жарьте по 3–5 минут с каждой стороны до готовности (145 °F / 63 °C в самом толстом месте). Переложите на блюдо и накройте фольгой.</li><li>В той же сковороде обжарьте вяленые томаты, зелёный лук и чеснок около минуты, помешивая.</li><li>Влейте сливки, посыпьте пармезаном, доведите до лёгкого кипения и варите около минуты, пока соус слегка не загустеет.</li><li>Добавьте шпинат и помешивайте 30 секунд, пока он не завянет. Попробуйте и при необходимости досолите.</li><li>Снимите с огня, верните лосось в сковороду и полейте тёплым соусом.</li></ol><p><em>Хорошо подойдёт с пюре, рисом, пастой или киноа.</em></p>', CURRENT_TIMESTAMP),
  ('66cfeffc-27c9-5d58-9494-c9daf03275fc', '9cc3a187-4eb6-57b8-a863-48658dae7cba', 'en', 'Tuscan salmon with sun-dried tomato cream and spinach', 'Pan-seared salmon with crisp edges in a garlicky cream sauce with sun-dried tomatoes, parmesan and spinach.', '<ol><li>Season the salmon with salt, pepper and garlic powder.</li><li>Melt the oil and butter in a large skillet over medium heat. When the butter stops foaming, add the salmon skin side up and cook 3-5 minutes per side until cooked through (63°C / 145°F at the thickest part). Move to a platter and tent with foil.</li><li>In the same pan sauté the sun-dried tomatoes, green onion and garlic for about a minute, stirring constantly.</li><li>Pour in the cream, sprinkle with parmesan, bring to a light boil and simmer about a minute until slightly thickened.</li><li>Add the spinach and stir 30 seconds until just wilted. Season to taste.</li><li>Take the pan off the heat, return the salmon and spoon the warm sauce over it.</li></ol><p><em>Pair with mashed potatoes, rice, pasta or quinoa.</em></p>', CURRENT_TIMESTAMP),
  ('3bacb84c-823c-504b-89cd-dc8abbe3ad8b', 'a0916725-fbad-5868-9346-92ee8bfa282a', 'ru', 'Говяжий фарш с капустой и морковью по-азиатски', 'Начинка для спринг-ролла без теста: обжаренный фарш с капустой, морковью и луком в соусе из соевого соуса, имбиря и кунжутного масла.', '<ol><li>Разогрейте масло на большой сковороде на средне-сильном огне и обжарьте фарш около 5 минут, разбивая лопаткой, пока он не потеряет розовый цвет. Посолите и поперчите.</li><li>Добавьте лук и морковь и жарьте 5–7 минут до мягкости лука. Положите чеснок на 30 секунд, помешивая.</li><li>Добавьте капусту, имбирь, соевый соус, кунжутное масло и сахар. Жарьте ещё 5–7 минут до мягкости капусты.</li><li>Подавайте, посыпав зелёным луком и кунжутом.</li></ol><p><em>Посыпьте зелёным луком и кунжутом, подайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('437409bd-4025-50df-bb99-63da0adaa41a', 'a0916725-fbad-5868-9346-92ee8bfa282a', 'en', 'Egg roll bowl with beef and cabbage', 'The filling of an egg roll without the wrapper: browned ground beef with cabbage, carrot and onion in a soy, ginger and sesame sauce.', '<ol><li>Heat the oil in a large skillet over medium-high heat and brown the beef about 5 minutes, breaking it up with a spatula, until no longer pink. Season with salt and pepper.</li><li>Add the onion and carrot and sauté 5-7 minutes until the onion is tender. Stir in the garlic for 30 seconds.</li><li>Add the cabbage, ginger, soy sauce, sesame oil and sugar. Keep cooking 5-7 minutes until the cabbage is tender.</li><li>Serve garnished with green onion and sesame seeds.</li></ol><p><em>Garnish with green onion and sesame seeds, and serve with rice if you like.</em></p>', CURRENT_TIMESTAMP),
  ('8038ea1f-2533-5ff1-9477-96f1387381af', '130e7f33-e6ef-5fe5-b502-ee77e3273956', 'ru', 'Суп-лазанья с итальянской колбаской и рикоттой', 'Густой томатный суп с крупно поломанными листами лазаньи, колбасным фаршем, пармезаном и сливками. Подаётся с ложкой рикотты.', '<ol><li>Доведите до кипения кастрюлю подсоленной воды, отварите поломанные листы лазаньи на 2 минуты меньше, чем указано на упаковке. Слейте воду, сбрызните маслом и отложите.</li><li>В кастрюле с толстым дном на среднем огне обжарьте колбасный фарш, разбивая лопаткой на мелкие кусочки. Добавьте лук и готовьте до прозрачности. Добавьте чеснок и орегано на 30 секунд.</li><li>Добавьте томатную пасту, бульон и измельчённые томаты, доведите до кипения, убавьте огонь, прикройте крышкой и варите 15 минут.</li><li>На слабом огне добавьте лазанью, сливки, пармезан и базилик. Проварите ещё несколько минут и приправьте по вкусу.</li><li>Подавайте сразу, добавив в тарелку ложку рикотты и немного свежего базилика.</li></ol><p><em>Положите ложку рикотты и посыпьте свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('d0d0b6b9-fa5d-5c41-80f6-4f8b4d23563c', '130e7f33-e6ef-5fe5-b502-ee77e3273956', 'en', 'Lasagna soup with Italian sausage and ricotta', 'A hearty tomato soup with broken lasagna noodles, sausage, parmesan and cream, topped with a spoonful of ricotta.', '<ol><li>Bring a large pot of salted water to a boil and cook the broken lasagna noodles 2 minutes less than the package says. Drain, toss with oil and set aside.</li><li>In a heavy pot over medium heat brown the sausage, breaking it into small pieces. Add the onion and cook until translucent, then the garlic and oregano for 30 seconds.</li><li>Stir in the tomato paste, broth and crushed tomatoes, bring to a boil, reduce the heat, partially cover and simmer 15 minutes.</li><li>Keep at a simmer and add the noodles, half and half, parmesan and basil. Simmer a few more minutes and season to taste.</li><li>Serve right away with a spoonful of ricotta and a sprinkle of fresh basil.</li></ol><p><em>Top with a spoonful of ricotta and fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('58336cad-ad54-54ad-9e7b-b5c5ba968f2b', '29d74ee5-a7f4-5768-ba5f-f16c1f72f00a', 'ru', 'Картофельный гратен с сыром и сливками', 'Тонкие ломтики картофеля, запечённые слоями с сыром в сливочно-молочном соусе с луком и чесноком, до румяной корочки.', '<ol><li>Разогрейте духовку до 190 °C и смажьте маслом форму 23×33 см.</li><li>Нарежьте картофель тонкими кружками толщиной около 3 мм (удобно на мандолине) и сложите в миску с водой.</li><li>В кастрюле растопите масло и 5 минут пассеруйте лук до мягкости, добавьте чеснок на минуту. Влейте сливки и молоко и доведите до слабого кипения.</li><li>Слейте воду с картофеля и промокните его бумажным полотенцем. Уложите в форму половину ломтиков, посыпьте половиной смеси соли и перца и 1,5 стаканами сыра. Повторите со вторым слоем.</li><li>Залейте картофель горячей сливочной смесью и утопите ломтики вниз: полностью покрыты сливками они не будут, это нормально.</li><li>Накройте фольгой и запекайте на средней полке 1 час, затем снимите фольгу и запекайте ещё 30–45 минут, пока верх не станет золотистым, а большая часть жидкости не впитается. Если верх темнеет слишком быстро, накройте фольгой. Картофель должен легко прокалываться вилкой.</li></ol><p><em>Подавайте как гарнир к мясу или птице.</em></p>', CURRENT_TIMESTAMP),
  ('85a7e3fe-35ee-5342-bcc0-81f00e097b0c', '29d74ee5-a7f4-5768-ba5f-f16c1f72f00a', 'en', 'Cheesy scalloped potatoes with cream', 'Thin potato slices baked in layers with cheese in a creamy milk sauce with onion and garlic until golden and bubbly.', '<ol><li>Heat the oven to 190°C (375°F) and butter a 9x13-inch baking dish.</li><li>Slice the potatoes into rounds about 3 mm thick (a mandoline works best) and drop them into a bowl of water.</li><li>In a saucepan melt the butter and sauté the onion about 5 minutes until soft, add the garlic for a minute, then pour in the cream and milk and heat to a simmer.</li><li>Drain the potatoes and pat dry. Layer half in the dish, sprinkle with half the salt and pepper and 1.5 cups of cheese. Repeat with the remaining potatoes, seasoning and cheese.</li><li>Pour the hot cream mixture over the potatoes and press them down; they won''t be fully submerged and that''s fine.</li><li>Cover with foil and bake on the middle rack 1 hour, then uncover and bake another 30-45 minutes until golden and bubbly and most of the liquid is absorbed. Tent with foil if the top browns too fast. The potatoes should pierce easily with a fork.</li></ol><p><em>Serve as a side with meat or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('f0bdb6c1-f2ee-5e3f-8165-99758b29dee4', '1af1966e-8de9-534c-aee1-150724984242', 'ru', 'Запечённая свиная вырезка с пряной корочкой', 'Свиная вырезка с сухой смесью из итальянских трав, чеснока и кориандра: обжаривается до корочки и доводится в духовке. Получается сочной и нежной.', '<ol><li>Разогрейте духовку до 200 °C, решётка посередине.</li><li>Очистите вырезку от жира и серебристой плёнки и обсушите. Проколите мясо вилкой со всех сторон и смажьте 1 ст. л. масла.</li><li>Смешайте соль, перец, итальянские травы, чесночный порошок и кориандр. Натрите мясо смесью, втирая руками.</li><li>Разогрейте оставшееся масло в жаропрочной сковороде (чугунной) на средне-сильном огне и обжарьте вырезку со всех сторон около 6 минут.</li><li>Отправьте сковороду в духовку на 13–15 минут без крышки, перевернув мясо на середине. Готово, когда внутри не меньше 65 °C. Переложите на доску и дайте отдохнуть 5–10 минут, затем нарежьте медальонами.</li></ol><p><em>Дайте мясу отдохнуть и нарежьте медальонами. Подавайте с овощами или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('3e5df301-1096-5b74-8b2a-c85b664dc741', '1af1966e-8de9-534c-aee1-150724984242', 'en', 'Roasted pork tenderloin with a spice rub', 'Pork tenderloin rubbed with Italian herbs, garlic and coriander, seared for a crust and finished in the oven. Juicy and tender.', '<ol><li>Heat the oven to 200°C (400°F) with the rack in the middle.</li><li>Trim the tenderloin of fat and silver skin and pat dry. Pierce all over with a fork and rub with 1 tbsp oil.</li><li>Mix the salt, pepper, Italian seasoning, garlic powder and coriander and rub the mixture all over the pork.</li><li>Heat the remaining oil in an oven-safe pan over medium-high heat and brown the pork on all sides, about 6 minutes in total.</li><li>Roast uncovered 13-15 minutes, turning halfway, until the center reads at least 65°C (150°F). Transfer to a board, rest 5-10 minutes and slice into medallions.</li></ol><p><em>Rest the meat and slice into medallions. Serve with vegetables or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('3e1435ce-80c9-5ca1-97bf-f39ada829b10', '6ab4af70-ea72-555e-8134-7f83e8c248c3', 'ru', 'Курица по-марокански в маринаде из трав, на гриле', 'Куриное филе, замаринованное в смеси оливкового масла, лимонного сока, чеснока, петрушки, кинзы и пряностей, и обжаренное на гриле.', '<ol><li>Измельчите в комбайне или ножом чеснок с маслом, лимонным соком, кориандром, зирой, паприкой, чили, солью и перцем. Добавьте петрушку и кинзу и измельчите, не превращая в пюре.</li><li>Разрежьте каждую грудку вдоль пополам, чтобы получились тонкие куски. Переложите в пакет или миску, залейте маринадом и перемешайте. Мариновать минимум 4 часа или на ночь в холодильнике.</li><li>Жарьте на гриле или гриль-сковороде на среднем огне до полной готовности, по нескольку минут с каждой стороны.</li></ol><p><em>Подайте с цацики, рисом или свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('b8f6260a-1411-5122-a76a-46579277ea63', '6ab4af70-ea72-555e-8134-7f83e8c248c3', 'en', 'Grilled Moroccan chicken with herb marinade', 'Chicken breast marinated in olive oil, lemon juice, garlic, parsley, cilantro and warm spices, then grilled.', '<ol><li>Mince the garlic with the oil, lemon juice, coriander, cumin, paprika, chili, salt and pepper in a food processor or by hand. Add the parsley and cilantro and chop without pureeing.</li><li>Slice each breast in half lengthwise to make thinner pieces. Put them in a bag or bowl, add the marinade and toss to coat. Marinate at least 4 hours or overnight in the fridge.</li><li>Grill on a grill or grill pan over medium heat until cooked through, a few minutes per side.</li></ol><p><em>Serve with tzatziki, rice or a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('c234d965-ed90-52dd-b83f-cace784360ff', '38899a77-2006-5481-806b-7db89c3d1026', 'ru', 'Куриные грудки, фаршированные беконом, грибами и сыром, с медово-горчичным соусом', 'Грудки с карманом, набитым грибами, беконом и тёртым сыром, обжаренные на сковороде и допечённые под соусом из мёда, дижонской горчицы и майонеза.', '<ol><li>Смешайте майонез, сметану, мёд, дижонскую горчицу и паприку до однородного соуса. Разогрейте духовку до 175 °C.</li><li>Нарежьте бекон мелкими кусочками и обжарьте в большой сковороде до готовности, часто помешивая. Переложите на тарелку, оставив в сковороде 1 ч. л. жира.</li><li>Обжарьте грибы в оставшемся жире до румяности, слегка посолите и поперчите. Переложите и остудите.</li><li>В каждой грудке сделайте глубокий надрез-карман, посолите и поперчите. Начините сыром, грибами и частью бекона, закрепите зубочисткой.</li><li>Разогрейте в сковороде 1 ч. л. масла на среднем и сильном огне и обжарьте грудки по 4–5 минут с каждой стороны.</li><li>Выложите сверху оставшиеся бекон, грибы и сыр, полейте соусом, накройте фольгой и запекайте 15 минут. Снимите фольгу и допеките 2–3 минуты.</li></ol><p><em>Подайте с картофельным пюре или овощами на пару.</em></p>', CURRENT_TIMESTAMP),
  ('07cfae4f-c191-5326-afda-e54b5f2b0744', '38899a77-2006-5481-806b-7db89c3d1026', 'en', 'Bacon, mushroom and cheese stuffed chicken with honey mustard sauce', 'Chicken breasts with a pocket of mushrooms, bacon and cheese, pan-seared and finished in the oven under a honey mustard sauce.', '<ol><li>Mix the mayonnaise, sour cream, honey, Dijon mustard and paprika into a smooth sauce. Heat the oven to 175°C (350°F).</li><li>Cut the bacon into small pieces and cook in a large skillet, stirring often. Remove it, leaving 1 tsp of fat in the pan.</li><li>Sauté the mushrooms in the reserved fat until browned, lightly season with salt and pepper. Remove and let cool.</li><li>Cut a pocket into each chicken breast and season with salt and pepper. Stuff with cheese, mushrooms and part of the bacon and secure with a toothpick.</li><li>Heat 1 tsp of oil in the skillet over medium-high and sear the chicken 4–5 minutes per side.</li><li>Top with the remaining bacon, mushrooms and cheese, drizzle with the sauce, cover with foil and bake 15 minutes. Uncover and bake 2–3 more minutes.</li></ol><p><em>Serve with mashed potatoes or steamed vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('5e6578c3-8039-5fce-86d1-710bd59352ab', '10b1c01e-3fdf-5c20-b27b-b4b1c0448edf', 'ru', 'Жареный рис с ананасом и болгарским перцем', 'Быстрое вегетарианское блюдо из холодного варёного риса, обжаренного с ананасом, сладким перцем, имбирём и соевым соусом.', '<ol><li>Заранее сварите рис и полностью остудите (можно взять вчерашний). Горячий рис слипнется.</li><li>Нарежьте ананас, перец и лук кубиками, натрите имбирь, раздавите чеснок: во время жарки времени на нарезку не будет.</li><li>Разогрейте на среднем огне сковороду или вок с маслом, обжарьте лук около минуты, затем добавьте чеснок и имбирь ещё на минуту, помешивая.</li><li>Увеличьте огонь, добавьте перец и ананас и жарьте 3–5 минут до золотистого цвета.</li><li>Добавьте рис и соевый соус, перемешивайте ещё минуту. Снимите с огня, добавьте кунжутное масло, посыпьте зелёным луком и кунжутом.</li></ol><p><em>Посыпьте зелёным луком и кунжутом, подайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('08d30fc2-9c6f-5909-b299-1087b75cca44', '10b1c01e-3fdf-5c20-b27b-b4b1c0448edf', 'en', 'Pineapple fried rice with bell pepper', 'A quick vegetarian stir-fry of cold cooked rice with pineapple, sweet pepper, ginger and soy sauce.', '<ol><li>Cook the rice ahead and let it cool completely (leftover rice is ideal). Warm rice will turn sticky.</li><li>Dice the pineapple, pepper and onion, grate the ginger and press the garlic. There is no time to chop once cooking starts.</li><li>Heat oil in a skillet or wok over medium heat, cook the onion about 1 minute, then add the garlic and ginger for another minute, stirring.</li><li>Raise the heat, add the bell pepper and pineapple and sauté 3–5 minutes until golden.</li><li>Add the rice and soy sauce and stir another minute. Remove from the heat, stir in the sesame oil and top with green onions and sesame seeds.</li></ol><p><em>Top with green onions and sesame seeds and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('489d4cff-42bf-5536-a24f-e83487db773e', 'd4c2f5cc-44e2-538e-b5f4-21d06fe2f378', 'ru', 'Отварной картофель с маслом и петрушкой', 'Молодой картофель, сваренный в мундире с лавровым листом и политый растопленным сливочным маслом с обилием зелени.', '<ol><li>Хорошо вымойте картофель жёсткой губкой (чистить не нужно). Нарежьте кусками толщиной 2,5–4 см, переложите в кастрюлю, залейте тёплой водой чуть выше уровня картофеля, посолите (2 ч. л.), добавьте лавровый лист.</li><li>Доведите до кипения и варите под неполной крышкой около 15 минут, пока вилка не будет легко входить. Слейте воду.</li><li>Переложите в большую миску, полейте растопленным маслом и перемешайте. Посолите по вкусу, добавьте рубленую петрушку и снова перемешайте перед подачей.</li></ol><p><em>Хорош с селёдкой, солёными огурцами, мясом и рыбой.</em></p>', CURRENT_TIMESTAMP),
  ('cd12ea45-a3f1-5e55-8e28-76222fadce80', 'd4c2f5cc-44e2-538e-b5f4-21d06fe2f378', 'en', 'Buttered parsley potatoes', 'Yukon gold potatoes boiled with a bay leaf and tossed with melted butter and plenty of fresh parsley.', '<ol><li>Scrub the potatoes with a rough sponge (no need to peel). Slice into 1–1½ inch (2.5–4 cm) pieces, put in a pot, add warm water to barely cover, add 2 tsp of salt and the bay leaf.</li><li>Bring to a boil and cook partially covered about 15 minutes until easily pierced with a fork. Drain.</li><li>Transfer to a large bowl, drizzle with the melted butter and toss. Season with salt to taste, add the chopped parsley and toss again just before serving.</li></ol><p><em>Serve alongside roasted meat, fish or pickles.</em></p>', CURRENT_TIMESTAMP),
  ('2ed69cd5-002f-5bb8-96bd-15bb8edff331', 'a21f1779-c35e-5ba9-b15d-767ee716347b', 'ru', 'Салат из сырой брокколи и цветной капусты с клюквой и миндалём', 'Хрустящий салат из мелких соцветий брокколи и цветной капусты с сушёной клюквой, обжаренным миндалём и медово-лимонной заправкой с майонезом.', '<ol><li>Очистите ножку брокколи, срежьте сухое основание. Нарежьте соцветия мелко, ножку — кубиками.</li><li>Удалите у цветной капусты кочерыжку и листья, нарежьте мелкими кусочками.</li><li>Обжарьте миндаль на сухой сковороде на среднем и сильном огне, часто встряхивая, до аромата и золотистого цвета. Добавьте в миску с овощами вместе с клюквой.</li><li>Смешайте майонез, мёд и лимонный сок, заправьте салат и хорошо перемешайте.</li></ol><p><em>Дайте настояться 30 минут в холодильнике перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('5ba201c8-d7cd-55cf-b3f7-58f240c22fe4', 'a21f1779-c35e-5ba9-b15d-767ee716347b', 'en', 'Broccoli cauliflower salad with cranberries and almonds', 'A crunchy salad of raw broccoli and cauliflower with dried cranberries, toasted almonds and a creamy honey-lemon dressing.', '<ol><li>Peel the broccoli stem and trim the dry base. Chop the florets small and dice the stem.</li><li>Discard the cauliflower core and leaves and cut the rest into bite-size pieces.</li><li>Toast the almonds in a dry skillet over medium-high heat, tossing often, until golden and fragrant. Add to the bowl with the vegetables and the cranberries.</li><li>Whisk the mayonnaise, honey and lemon juice, dress the salad and toss well.</li></ol><p><em>Chill for 30 minutes before serving for better flavor.</em></p>', CURRENT_TIMESTAMP),
  ('4b909a8e-6d04-506d-bd44-88a3e635d147', 'ad457240-349e-5cac-b784-21ed5efb4e13', 'ru', 'Лазанья с курицей и шпинатом под белым соусом', 'Слои листов лазаньи, курицы, рикотты с моцареллой и сливочного соуса бешамель со шпинатом, запечённые под сырной корочкой.', '<ol><li>Разогрейте духовку до 190 °C. Отварите листы лазаньи до al dente, слейте воду и залейте холодной, чтобы не слиплись. Разберите курицу на волокна.</li><li>В кастрюле на среднем огне разогрейте оливковое масло, обжарьте лук 3–4 минуты. Добавьте сливочное масло, всыпьте муку и взбивайте венчиком около 3 минут до золотистого цвета.</li><li>Влейте бульон и сливки, добавьте соль и перец. Взбивайте до гладкости и варите 5 минут до консистенции лёгкого соуса. Добавьте чеснок и шпинат, перемешайте и снимите с огня.</li><li>Смешайте рикотту с яйцом, 2 стаканами моцареллы, пармезаном и петрушкой.</li><li>В форму 23×33 см налейте немного соуса, выложите 3 листа, половину рикотты, половину курицы и треть соуса. Повторите слой. Закончите 3 листами, оставшимся соусом и отложенной моцареллой.</li><li>Накройте фольгой (положите зубочистки, чтобы она не касалась сыра) и запекайте 45 минут. Снимите фольгу и 2–3 минуты подержите под грилем. Дайте постоять не менее 10 минут.</li></ol><p><em>Дайте постоять 10 минут перед нарезкой. Подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('6b36c466-99f1-5e9b-827c-975d5f71c57a', 'ad457240-349e-5cac-b784-21ed5efb4e13', 'en', 'Chicken and spinach white sauce lasagna', 'Layers of lasagna noodles, chicken, ricotta-mozzarella filling and a creamy spinach béchamel baked under a cheesy crust.', '<ol><li>Heat the oven to 375°F (190°C). Cook the lasagna noodles until al dente, drain and cover with cold water so they do not stick. Shred the chicken.</li><li>In a pot over medium heat warm the olive oil and cook the onion 3–4 minutes. Add the butter, whisk in the flour and keep whisking about 3 minutes until golden.</li><li>Pour in the broth and cream, add salt and pepper. Whisk until smooth and simmer 5 minutes until lightly thickened. Stir in the garlic and spinach and remove from the heat.</li><li>Whisk the ricotta with the egg, 2 cups of the mozzarella, the parmesan and the parsley.</li><li>In a 9x13-inch dish spread a little sauce, add 3 noodles, half the ricotta mixture, half the chicken and a third of the sauce. Repeat once. Finish with 3 noodles, the remaining sauce and the reserved mozzarella.</li><li>Cover with foil (use toothpicks so it doesn''t touch the cheese) and bake 45 minutes. Uncover and broil 2–3 minutes. Rest at least 10 minutes.</li></ol><p><em>Rest 10 minutes before slicing. Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('29e9cae5-d2bd-530b-9bd0-bba774bfc1d3', 'd4bf370e-22cf-59d2-87a1-49b802cb6e1f', 'ru', 'Салат с креветками каджун, авокадо и кукурузой', 'Ромэн с помидорами, огурцом, красным луком, авокадо и кукурузой, сверху креветки в пряностях каджун и заправка из лимона, кинзы и оливкового масла.', '<ol><li>Обсушите креветки, смешайте с каджун-приправой, чесноком и щепоткой соли.</li><li>Растопите в антипригарной сковороде на среднем и сильном огне сливочное масло и обжарьте креветки одним слоем по 2 минуты с каждой стороны до готовности. Переложите на тарелку.</li><li>Нарвите и обсушите ромэн, переложите в большую миску. Добавьте помидоры, красный лук, огурец, авокадо и сваренную кукурузу.</li><li>Смешайте лимонный сок, рубленую кинзу, оливковое масло, соль и перец. Заправьте салат, сверху выложите креветки.</li></ol><p><em>Заправляйте непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('4d64437b-bc56-55ac-8a56-9c0ad6f83dfc', 'd4bf370e-22cf-59d2-87a1-49b802cb6e1f', 'en', 'Cajun shrimp cobb salad with avocado and cilantro dressing', 'Romaine with tomatoes, cucumber, red onion, avocado and corn, topped with Cajun-spiced shrimp and a lemon-cilantro-olive oil dressing.', '<ol><li>Pat the shrimp dry and toss with the Cajun spice, garlic and a pinch of salt.</li><li>Melt the butter in a non-stick pan over medium-high heat and sauté the shrimp in a single layer 2 minutes per side until cooked. Transfer to a plate.</li><li>Chop, rinse and dry the romaine and put it in a large bowl. Add the tomatoes, red onion, cucumber, avocados and cooked corn.</li><li>Stir together the lemon juice, chopped cilantro, olive oil, salt and pepper. Dress the salad and top with the shrimp.</li></ol><p><em>Dress just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('158b13ce-393a-58e1-9bb7-739c588267e7', '77971e68-5f24-576c-8ad0-0e46ad99c2c5', 'ru', 'Курица пармиджана с томатным соусом и сыром', 'Куриные отбивные в хрустящей панировке из сухарей и пармезана, политые томатным соусом и запечённые под расплавленным сыром.', '<ol><li>Для соуса растопите в кастрюле масло с оливковым маслом и обжарьте мелко нарезанный лук до мягкости.</li><li>Добавьте чеснок, нарезанные томаты, итальянские травы, соль и перец и готовьте 2–3 минуты. При желании пробейте соус погружным блендером до гладкости. Накройте крышкой и держите на слабом огне.</li><li>Разрежьте грудки вдоль пополам, получится 4 пласта, и отбейте до равномерной толщины.</li><li>Приготовьте три миски: мука с солью и перцем, взбитые яйца, смесь панко, пармезана, муки, чесночного порошка, соли, паприки и итальянских трав. Каждый пласт обваляйте в муке, яйце и сухарях, плотно прижимая панировку.</li><li>Разогрейте в большой сковороде масло на средне-сильном огне и обжаривайте отбивные по 3 минуты с каждой стороны небольшими порциями, чтобы не переполнять сковороду. Выложите на противень с пергаментом.</li><li>Покройте каждую отбивную соусом и ломтиками сыра и поставьте под гриль духовки на слабом режиме на 4–6 минут до расплавления сыра. Посыпьте базиликом.</li></ol><p><em>Подавайте с пастой или с лёгким салатом.</em></p>', CURRENT_TIMESTAMP),
  ('1fd1139e-6f6e-5110-8b5f-3ca226b61f44', '77971e68-5f24-576c-8ad0-0e46ad99c2c5', 'en', 'Chicken parmesan with tomato sauce and provolone', 'Chicken cutlets coated in a crisp breadcrumb and parmesan crust, topped with tomato sauce and broiled under melted cheese.', '<ol><li>For the sauce, melt the butter with the olive oil in a saucepan and cook the finely chopped onion until soft.</li><li>Add the garlic, diced tomatoes, Italian seasoning, salt and pepper and cook 2-3 minutes. Optionally blend smooth with an immersion blender. Cover and keep on low heat.</li><li>Cut the chicken breasts in half lengthwise into 4 cutlets and pound to an even thickness.</li><li>Set up three bowls: flour with salt and pepper, beaten eggs, and a mix of panko, parmesan, flour, garlic powder, salt, paprika and Italian seasoning. Dredge each cutlet in flour, then egg, then the crumb mixture, pressing firmly.</li><li>Heat the oil in a large skillet over medium-high heat and fry the cutlets 3 minutes per side, in batches so the pan isn''t crowded. Place on a parchment-lined baking sheet.</li><li>Top each cutlet with sauce and cheese slices and broil on low for 4-6 minutes until the cheese melts. Garnish with basil.</li></ol><p><em>Serve over pasta or with a simple salad.</em></p>', CURRENT_TIMESTAMP),
  ('6cf986ff-2e7f-5d29-9103-a88424c61669', '5da68313-bbe5-512e-be35-444644aadb39', 'ru', 'Шведские фрикадельки из говядины и свинины в сливочном соусе', 'Сочные фрикадельки из говяжьего и свиного фарша в густом сливочном соусе на говяжьем бульоне с каплей горчицы.', '<ol><li>Залейте сухари молоком в миске и дайте набухнуть.</li><li>Добавьте оба вида фарша, тёртый лук, чеснок, яйцо, соль, перец, душистый перец и мускатный орех. Хорошо перемешайте.</li><li>Смочите руки водой и сформируйте из массы 24 одинаковые фрикадельки.</li><li>Разогрейте масло в большой сковороде на среднем огне и обжаривайте фрикадельки порциями со всех сторон до золотистой корочки и готовности, не переполняя сковороду. Между порциями при необходимости добавляйте масло. Переложите на тарелку и накройте.</li><li>В той же сковороде растопите сливочное масло, всыпьте муку и обжаривайте, постоянно помешивая, до золотистого цвета.</li><li>Постепенно влейте бульон и сливки, добавьте горчицу, соль и перец. Доведите до слабого кипения и варите до нужной густоты.</li><li>Верните фрикадельки в соус и прогрейте. Подавайте с зеленью и картофельным пюре.</li></ol><p><em>Подавайте с картофельным пюре, пастой или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('4f5280c7-dc8e-53cb-899f-f0828d5e4ce4', '5da68313-bbe5-512e-be35-444644aadb39', 'en', 'Swedish meatballs with beef, pork and cream gravy', 'Juicy beef and pork meatballs simmered in a thick, creamy beef gravy with a touch of Dijon.', '<ol><li>Combine the breadcrumbs and milk in a bowl and let them soak.</li><li>Add both kinds of meat, grated onion, garlic, egg, salt, pepper, allspice and nutmeg and mix until evenly combined.</li><li>With wet hands, shape the mixture into 24 evenly sized meatballs.</li><li>Heat the oil in a large skillet over medium heat and fry the meatballs in batches on all sides until golden and cooked through, without crowding the pan. Add oil between batches if needed. Keep warm covered.</li><li>In the same skillet melt the butter, whisk in the flour and cook, whisking constantly, until golden.</li><li>Slowly whisk in the broth and cream, then the mustard, salt and pepper. Bring to a gentle simmer and cook to the thickness you like.</li><li>Return the meatballs to the sauce and warm through. Garnish with herbs and serve over mashed potatoes.</li></ol><p><em>Serve over mashed potatoes, pasta or rice.</em></p>', CURRENT_TIMESTAMP),
  ('80971288-bb9b-5b32-829f-ac10a5cd8243', '8a14ae01-15c9-5db5-9fee-19756f2162e8', 'ru', 'Тако с жареной треской, капустным салатом и лаймовым соусом', 'Пшеничные тортильи с обжаренным в специях филе трески, хрустящим салатом из капусты и моркови и сметанно-майонезным соусом с лаймом.', '<ol><li>Нашинкуйте капусты и нарежьте морковь и лук тонкой соломкой, смешайте для салата.</li><li>Смешайте майонез, сметану, лаймовый сок и шрирачу для соуса.</li><li>Смешайте муку, паприку, зиру, чили, чесночный порошок, соль и перец. Обваляйте филе трески со всех сторон в этой смеси.</li><li>Разогрейте масло на сковороде и обжаривайте рыбу по 2–4 минуты с каждой стороны, пока она не станет золотистой и легко не расслоится.</li><li>Подогрейте тортильи. Выложите на каждую рыбу, салат, помидоры, кинзу и фету, полейте соусом и соком лайма.</li></ol><p><em>Добавьте дольку лайма, кинзу и помидоры.</em></p>', CURRENT_TIMESTAMP),
  ('a5e99582-05e1-52cb-b4b6-70506d4c2955', '8a14ae01-15c9-5db5-9fee-19756f2162e8', 'en', 'Cod fish tacos with cabbage slaw and lime sauce', 'Flour tortillas with spice-dusted pan-fried cod, a crunchy cabbage and carrot slaw and a creamy lime and sriracha sauce.', '<ol><li>Shred the cabbages and cut the carrot and onion into thin strips, and toss together for the slaw.</li><li>Whisk the mayonnaise, sour cream, lime juice and sriracha for the sauce.</li><li>Mix the flour, paprika, cumin, chili powder, garlic powder, salt and pepper and coat the cod fillets on all sides.</li><li>Heat the oil in a skillet and fry the fish 2-4 minutes per side until golden and flaking easily.</li><li>Warm the tortillas. Fill each with fish, slaw, tomatoes, cilantro and feta, then drizzle with the sauce and lime juice.</li></ol><p><em>Finish with a lime wedge, cilantro and tomatoes.</em></p>', CURRENT_TIMESTAMP),
  ('db06a8c8-2bf3-50e5-9bab-bff54ba1e81b', 'a8cfa81f-454b-5369-be2f-5594d4c418c9', 'ru', 'Говяжьи рёбрышки, томлёные в красном вине', 'Обжаренные говяжьи рёбра, которые 2,5–3 часа томятся в духовке в соусе из красного вина, бульона и овощей, пока мясо не начнёт отходить от кости.', '<ol><li>Разогрейте духовку до 160 °C. Обсушите рёбра бумажным полотенцем, посолите и поперчите со всех сторон.</li><li>Обваляйте рёбра в муке со всех сторон, оставшуюся муку не выбрасывайте.</li><li>Разогрейте масло в жаровне или кастрюле с толстым дном на средне-сильном огне и обжарьте рёбра по 3–4 минуты со всех сторон до корочки. Выньте мясо.</li><li>Добавьте сливочное масло, лук, морковь, сельдерей и чеснок и обжаривайте около 2 минут. Добавьте томатную пасту и красное вино, соскребая румяные частицы со дна, и нагрейте до лёгкого кипения.</li><li>Разведите оставшуюся муку в бульоне, влейте в кастрюлю и верните рёбра в соус.</li><li>Закройте крышкой и томите в духовке 2,5–3 часа, пока мясо не станет настолько мягким, что его можно разобрать вилкой.</li><li>Выньте мясо. Процедите соус, овощи выбросьте или оставьте на гарнир, верните мясо в соус и подавайте.</li></ol><p><em>Подавайте с картофельным пюре или полентой и соусом из кастрюли.</em></p>', CURRENT_TIMESTAMP),
  ('ed61f768-cbf9-58fe-a286-3fd94fd256da', 'a8cfa81f-454b-5369-be2f-5594d4c418c9', 'en', 'Red wine braised beef short ribs', 'Seared beef short ribs braised in the oven for 2.5 to 3 hours in a sauce of red wine, stock and vegetables until the meat falls off the bone.', '<ol><li>Heat the oven to 160°C (325°F). Pat the ribs dry and season on all sides with salt and pepper.</li><li>Coat the ribs in flour on all sides and keep the leftover flour.</li><li>Heat the oil in a Dutch oven over medium-high heat and sear the ribs 3-4 minutes on all sides. Remove them.</li><li>Add the butter, onion, carrot, celery and garlic and cook about 2 minutes. Add the tomato paste and wine, scraping up the browned bits, and heat until just bubbling.</li><li>Stir the leftover flour into the stock until dissolved, pour it into the pot and return the ribs.</li><li>Cover and braise in the oven 2.5 to 3 hours until the meat is tender enough to pull apart.</li><li>Remove the meat, strain the sauce (discard the vegetables or keep them as a side), return the meat to the sauce and serve.</li></ol><p><em>Serve with mashed potatoes or polenta and the pan sauce.</em></p>', CURRENT_TIMESTAMP),
  ('32a99716-8a56-50be-a345-f08f20726975', '3c62c31f-410c-5741-ba1b-912aa4429aef', 'ru', 'Лапша ло мейн с курицей и овощами в соево-медовом соусе', 'Яичная лапша с полосками курицы, морковью и перцем в соусе из соевого соуса, мёда, имбиря и чеснока. Готовится за 25 минут.', '<ol><li>Отварите лапшу по инструкции, промойте холодной водой, чтобы остановить приготовление, и отложите.</li><li>Нарежьте курицу полосками. Смешайте для соуса бульон, соевый соус, шрирачу, кунжутное масло, крахмал и мёд.</li><li>Разогрейте на сковороде 1 ст. л. растительного и 1 ст. л. сливочного масла, выложите курицу, посолите и поперчите. Пару минут не трогайте, затем аккуратно помешивайте до готовности. Переложите на тарелку.</li><li>Добавьте в сковороду ещё по 1 ст. л. масел, обжарьте морковь и перец до мягкости, затем чеснок и имбирь до аромата.</li><li>Добавьте лапшу, курицу и соус, прибавьте огонь и прогревайте, пока соус не загустеет, а лапша не нагреется. Подавайте с зелёным луком.</li></ol><p><em>Посыпьте зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('16fb8369-1d61-527e-ac4a-8fe8cdaae21d', '3c62c31f-410c-5741-ba1b-912aa4429aef', 'en', 'Chicken lo mein with vegetables in soy-honey sauce', 'Egg noodles tossed with chicken strips, carrot and bell pepper in a sauce of soy, honey, ginger and garlic. Ready in 25 minutes.', '<ol><li>Cook the noodles per the package, rinse under cold water to stop the cooking and set aside.</li><li>Cut the chicken into strips. Whisk together the broth, soy sauce, sriracha, sesame oil, cornstarch and honey for the sauce.</li><li>Heat 1 tbsp oil and 1 tbsp butter in a pan, add the chicken with salt and pepper and leave it for a couple of minutes before gently stirring until cooked. Remove to a plate.</li><li>Add another tablespoon each of oil and butter, sauté the carrot and pepper until tender, then the garlic and ginger until fragrant.</li><li>Add the noodles, chicken and sauce, turn up the heat and cook until the sauce thickens and the noodles are hot. Serve with green onion.</li></ol><p><em>Garnish with sliced green onion.</em></p>', CURRENT_TIMESTAMP),
  ('45545473-2188-5bdb-9c76-4294b66c44c0', '6b56638b-9e18-5740-9b42-1a87115dcced', 'ru', 'Камбала с тушёными овощами и паприкой', 'Нежное филе камбалы, обжаренное на сливочном масле, с морковью, луком, перцем и томатами, тушёными на той же сковороде.', '<ol><li>Смешайте соль, перец и паприку. Филе камбалы при желании разрежьте пополам и посыпьте около трёх четвертей смеси с обеих сторон.</li><li>Растопите на сковороде сливочное масло и жарьте рыбу 3–4 минуты, перевернув на середине. Переложите на тарелку и накройте.</li><li>В той же сковороде на оливковом масле обжарьте лук 2 минуты, добавьте морковь на 2 минуты, затем перец ещё на 3 минуты, помешивая.</li><li>Добавьте томаты, бульон, чеснок и оставшуюся приправу, тушите на среднем огне около 5 минут до мягкости овощей. Верните рыбу и прогрейте.</li></ol><p><em>Подавайте с картофелем или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('e0abac85-b1d0-5739-bc1f-85f2c917f9e3', '6b56638b-9e18-5740-9b42-1a87115dcced', 'en', 'Flounder with sautéed vegetables and paprika', 'Delicate flounder fillet pan-fried in butter, served with carrot, onion, bell pepper and tomatoes cooked down in the same pan.', '<ol><li>Mix the salt, pepper and paprika. Cut the fillet in half if you like and season both sides with about three quarters of the mix.</li><li>Melt the butter in a frying pan and cook the fish 3-4 minutes, flipping halfway. Move to a plate and cover to keep warm.</li><li>In the same pan sauté the onion in the olive oil for 2 minutes, add the carrot for 2 more, then the bell pepper for 3, stirring.</li><li>Add the tomatoes, broth, garlic and the remaining seasoning and simmer on medium about 5 minutes until the vegetables are tender. Return the fish and warm through.</li></ol><p><em>Serve with potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('a0cbd10a-4979-5563-b496-0c8b240fc928', '15dc5c9f-35aa-54b0-91d7-458f8d76ee17', 'ru', 'Курица в пармезанной корочке с лимонно-масляным соусом', 'Куриные отбивные в яйце, пармезане и муке, обжаренные до золотистой корочки, под соусом из масла, чеснока, бульона и лимонного сока.', '<ol><li>Обсушите грудки и разрежьте вдоль на 4 пласта. Отбейте до одинаковой толщины.</li><li>Взбейте яйца с чесноком, солью, перцем и итальянскими травами, положите в смесь куриные пласты.</li><li>Смешайте в плоской миске пармезан и муку. Разогрейте масло в глубокой сковороде, обваляйте каждую отбивную в смеси и выложите на сковороду.</li><li>Жарьте по 4–5 минут с каждой стороны до золотистого цвета. Переложите на тарелку и накройте.</li><li>Растопите в сковороде масло с чесноком до аромата. Влейте бульон и лимонный сок, добавьте перец, доведите до кипения и варите на среднем огне около 2 минут.</li><li>Верните отбивные в соус, прогрейте, посыпьте петрушкой и украсьте ломтиками лимона.</li></ol><p><em>Подавайте с лимоном, петрушкой и гарниром из пасты или овощей.</em></p>', CURRENT_TIMESTAMP),
  ('e9d0716d-650c-5aa4-a067-743078ba13e3', '15dc5c9f-35aa-54b0-91d7-458f8d76ee17', 'en', 'Lemon chicken in a parmesan crust with butter sauce', 'Chicken cutlets dipped in egg and a parmesan and flour coating, fried until golden and finished in a garlicky lemon butter sauce.', '<ol><li>Pat the chicken dry, slice lengthwise into four cutlets and pound to an even thickness.</li><li>Whisk the eggs with the garlic, Italian seasoning, salt and pepper and add the chicken.</li><li>Mix the parmesan and flour in a shallow bowl. Heat the oil in a deep skillet, then dredge each cutlet in the mixture and add it to the pan.</li><li>Cook 4-5 minutes per side until golden brown. Transfer to a plate and cover.</li><li>Melt the butter with the garlic in the pan until fragrant. Add the broth, lemon juice and pepper, bring to a simmer and cook on medium about 2 minutes.</li><li>Return the cutlets to the sauce to reheat, then garnish with parsley and lemon slices.</li></ol><p><em>Serve with lemon slices, parsley and pasta or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('338cb3c1-8ea3-5d62-b529-981232eb3aef', '6f23127a-680d-58b6-b968-2e3a07111ed5', 'ru', 'Запечённые овощи с соевым соусом, мёдом и имбирём', 'Цветная капуста, брокколи, морковь, перец, кабачок и красный лук, запечённые с соусом из соевого соуса, мёда, чеснока и имбиря. Быстрый гарнир.', '<ol><li>Разогрейте духовку до 220 °C и застелите противень пергаментом.</li><li>Нарежьте овощи одинаковыми по размеру кусками и перемешайте в большой миске.</li><li>Смешайте масло, соевый соус, мёд, чеснок, имбирь, соль и перец, залейте овощи и перемешайте, чтобы они покрылись соусом.</li><li>Разложите овощи на противне ровным слоем и запекайте 10 минут. Аккуратно перемешайте и готовьте ещё 5 минут, до желаемой мягкости.</li></ol><p><em>Подавайте как гарнир к мясу или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('5966dd0a-09ec-5d93-9354-29e419814d9e', '6f23127a-680d-58b6-b968-2e3a07111ed5', 'en', 'Roasted vegetables with soy, honey and ginger', 'Cauliflower, broccoli, carrot, bell pepper, zucchini and red onion roasted with a sauce of soy, honey, garlic and ginger. A quick side dish.', '<ol><li>Heat the oven to 220°C (425°F) and line a large baking sheet with parchment.</li><li>Cut the vegetables into evenly sized pieces and toss together in a large bowl.</li><li>Mix the oil, soy sauce, honey, garlic, ginger, salt and pepper, pour over the vegetables and toss to coat.</li><li>Spread the vegetables evenly on the tray and roast 10 minutes. Toss lightly and roast 5 more minutes to your preferred tenderness.</li></ol><p><em>Serve as a side with meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('de3193f4-775f-56cd-8060-7c811c65e6f2', '6da0ca27-e355-5eee-b137-7dbb700208d5', 'ru', 'Китайский суп с курицей и кукурузой', 'Густой сладковатый суп из сливочной кукурузы и куриного бульона с имбирём, чесноком, яичными нитями и кусочками курицы. Готовится за 10 минут.', '<ol><li>В кастрюле на сильном огне соедините бульон, сливочную кукурузу, соевый соус, китайское вино, имбирь, чеснок и крахмал, разведённый холодной водой.</li><li>Доведите до кипения, убавьте огонь до среднего и варите около 5 минут, изредка помешивая, пока суп слегка не загустеет.</li><li>Посолите, выключите огонь и тонкой струйкой вмешайте взбитое яйцо, чтобы оно свернулось лентами.</li><li>Добавьте курицу, приправьте белым перцем и подавайте, посыпав зелёным луком.</li></ol><p><em>Посыпьте зелёным луком и белым перцем.</em></p>', CURRENT_TIMESTAMP),
  ('c879b729-0a06-58d9-bc97-57234d1f301b', '6da0ca27-e355-5eee-b137-7dbb700208d5', 'en', 'Chinese chicken and corn soup', 'A thick, lightly sweet soup of creamed corn and chicken broth with ginger, garlic, egg ribbons and shredded chicken, ready in 10 minutes.', '<ol><li>In a saucepan over high heat combine the broth, creamed corn, soy sauce, cooking wine, ginger, garlic and the cornstarch mixed with a splash of cold water.</li><li>Bring to a boil, reduce to medium and cook about 5 minutes, stirring occasionally, until slightly thickened.</li><li>Season with salt, turn off the heat and slowly whisk in the beaten egg so it cooks in ribbons.</li><li>Add the chicken, season with white pepper and serve garnished with scallions.</li></ol><p><em>Garnish with scallions and white pepper.</em></p>', CURRENT_TIMESTAMP),
  ('8a212bcf-8386-57ef-90a7-2a6bc1935fcd', 'd4833647-823b-5875-b1d9-6f3b4b84b606', 'ru', 'Куриное рагу в духовке с овощами и картофелем', 'Куриные бёдра и голени с хрустящей кожей, томлёные в густом соусе с морковью, сельдереем, луком и картофелем.', '<ol><li>Разогрейте духовку до 180 °C. В большой жаропрочной кастрюле на сильном огне обжарьте куриные куски с двух сторон до светло-золотистого цвета, посолив и поперчив. Выложите на тарелку.</li><li>Слейте лишний жир, добавьте лук и чеснок на 2 минуты до прозрачности. Добавьте морковь и сельдерей на 1 минуту.</li><li>Влейте вино, соскребите прилипшее со дна и выпарите почти досуха. Посыпьте мукой и перемешайте.</li><li>Добавьте бульон, томатную пасту, вустерский соус, тимьян и лавровый лист и размешайте. Уложите курицу сверху кожей вверх, чтобы она оставалась над жидкостью. Доведите до кипения, накройте и запекайте 45 минут.</li><li>Снимите крышку, добавьте картофель, погрузив его в жидкость, а курицу выложите сверху. Запекайте без крышки ещё 40 минут, пока кожа не станет золотистой и хрустящей, картофель мягким, а соус густым. Посолите и поперчите по вкусу, посыпьте зеленью.</li></ol><p><em>Подайте с тёплым хлебом, чтобы макать в соус.</em></p>', CURRENT_TIMESTAMP),
  ('58dec1cb-7172-5363-bda0-9c25088376a9', 'd4833647-823b-5875-b1d9-6f3b4b84b606', 'en', 'Oven chicken stew with vegetables and potatoes', 'Bone-in chicken thighs and drumsticks with crisp skin, braised in a gravy-like sauce with carrots, celery, onion and baby potatoes.', '<ol><li>Heat the oven to 180°C (350°F). In a large ovenproof pot over high heat brown the chicken pieces on both sides, seasoning with salt and pepper. Set aside.</li><li>Pour off excess fat, add the onion and garlic for 2 minutes until translucent. Add the carrots and celery for 1 minute.</li><li>Add the wine, scrape the bottom and cook until mostly evaporated. Sprinkle with the flour and stir.</li><li>Add the broth, tomato paste, Worcestershire sauce, thyme and bay leaves and stir. Place the chicken on top, skin up and above the liquid. Bring to a simmer, cover and bake 45 minutes.</li><li>Uncover, add the potatoes, pushing them into the liquid, and set the chicken on top. Bake uncovered 40 more minutes until the skin is deep golden and crisp, the potatoes soft and the sauce thick. Adjust the seasoning and sprinkle with fresh herbs.</li></ol><p><em>Serve with warm crusty bread for dunking.</em></p>', CURRENT_TIMESTAMP),
  ('6cb66caa-b46f-507e-86bd-6f1d1d3a6fbb', '39eb5912-0529-5cee-88c2-66294982bc47', 'ru', 'Лосось по-японски в маринаде из мирина и соевого соуса', 'Филе лосося, замаринованное в соевом соусе, мирине и сакэ и обжаренное на сковороде до хрустящей кожи.', '<ol><li>Положите лосось, соевый соус, мирин и сакэ в пакет с замком, выпустите воздух и мариновайте в холодильнике от 3 часов до ночи.</li><li>Разогрейте масло на антипригарной сковороде на среднем огне (не сильнее: сахар в мирине быстро горит). Выложите лосось кожей вниз и жарьте 2–3 минуты до хрустящей кожи.</li><li>Полейте мякоть оставшимся маринадом, переверните и жарьте ещё около 2 минут. Дайте рыбе постоять пару минут, она дойдёт до готовности.</li></ol><p><em>Подайте с варёным рисом и овощами на пару.</em></p>', CURRENT_TIMESTAMP),
  ('cf89ed10-3ed9-5ef7-8403-0b06e388eefb', '39eb5912-0529-5cee-88c2-66294982bc47', 'en', 'Japanese pan-fried salmon with mirin and soy', 'Salmon fillets marinated in soy sauce, mirin and sake and pan-fried until the skin is crisp.', '<ol><li>Put the salmon, soy sauce, mirin and sake in a zip-top bag, press out the air and marinate in the fridge from 3 hours to overnight.</li><li>Heat the oil in a non-stick pan over medium heat (no higher, the sugar in the mirin burns quickly). Add the salmon skin side down and cook 2–3 minutes until crisp.</li><li>Drizzle the remaining marinade over the flesh, flip and cook about 2 more minutes. Rest for a couple of minutes while it finishes cooking.</li></ol><p><em>Serve with steamed rice and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('e8cf8895-681e-5185-9452-61b53fe95307', '0b901f16-eec2-5aff-b134-3a9c85d2fbf9', 'ru', 'Плов с нутом, зеленью и изюмом', 'Рассыпчатый рис басмати с обжаренным в специях нутом, петрушкой, кинзой, изюмом и хрустящим луком.', '<ol><li>Смешайте в кастрюле рис, воду и ½ ч. л. соли, доведите до кипения без крышки, затем накройте крышкой, убавьте огонь до среднего и слабого и варите 12 минут, не помешивая. Снимите с огня и оставьте под крышкой на 10 минут.</li><li>Пока варится рис, перемешайте нут с оставшейся солью, зирой и гарам масалой. Разогрейте масло на большой сковороде на сильном огне, добавьте нут и обжаривайте 1 минуту, встряхивая сковороду (или запеките 5 минут при 180 °C).</li><li>Смешайте рис с нутом, петрушкой, кинзой и изюмом, поперчите. При необходимости досолите. В конце добавьте хрустящий жареный лук и подавайте тёплым или комнатной температуры.</li></ol><p><em>Подайте к запечённой рыбе или овощам, или съешьте как самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('adb08faf-ee51-54d4-aeab-5dc243f9ffe6', '0b901f16-eec2-5aff-b134-3a9c85d2fbf9', 'en', 'Chickpea basmati pilaf with herbs and raisins', 'Fluffy basmati rice with spiced pan-toasted chickpeas, parsley, cilantro, sultanas and crispy fried shallots.', '<ol><li>Combine the rice, water and ½ tsp of salt in a saucepan, bring to a boil uncovered, then cover, reduce to medium-low and simmer 12 minutes without stirring. Remove from the heat and rest covered for 10 minutes.</li><li>While the rice cooks, toss the chickpeas with the remaining salt, cumin and garam masala. Heat the oil in a large pan over high heat, add the chickpeas and cook 1 minute, shaking the pan (or roast 5 minutes at 180°C).</li><li>Toss the rice with the chickpeas, parsley, cilantro, sultanas and black pepper. Adjust the salt, then fold through the crispy shallots at the end and serve warm or at room temperature.</li></ol><p><em>Serve with grilled fish or roasted vegetables, or enjoy on its own.</em></p>', CURRENT_TIMESTAMP),
  ('3686500e-9ac3-5c30-b39a-eaff274f937b', '56fee6d1-efdc-5d54-8349-b9e2f6d3e59d', 'ru', 'Паста с говяжьим фаршем в сливочно-томатном соусе в одной кастрюле', 'Короткая паста, сваренная прямо в соусе из говяжьего фарша, томатов, бульона и итальянских трав, с добавлением сливок.', '<ol><li>В большой кастрюле с толстым дном на сильном огне разогрейте масло, обжарьте чеснок с луком 1,5 минуты.</li><li>Добавьте фарш и жарьте, разбивая комочки, пока не исчезнет розовый цвет. Всыпьте итальянские травы на 30 секунд, затем томатную пасту на минуту.</li><li>Добавьте измельчённые томаты, бульон, соль, перец и хлопья чили, перемешайте и всыпьте пасту.</li><li>Доведите до кипения и варите 15 минут, перемешивая каждые пару минут, а к концу чаще, чтобы паста не прилипала ко дну, пока она почти не сварится.</li><li>Влейте сливки и прогрейте 1–2 минуты. Соус должен остаться жидковатым: паста впитает его. Подайте с пармезаном и петрушкой.</li></ol><p><em>Посыпьте тёртым пармезаном и рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('528259ad-b070-5d7b-828b-78a3cb459873', '56fee6d1-efdc-5d54-8349-b9e2f6d3e59d', 'en', 'One-pot creamy tomato beef pasta', 'Short pasta cooked right in a sauce of ground beef, tomatoes, stock and Italian herbs, finished with cream.', '<ol><li>In a large heavy pot over high heat warm the oil and cook the garlic and onion for 1½ minutes.</li><li>Add the beef and cook, breaking it up, until no red remains. Add the Italian herbs for 30 seconds, then the tomato paste for 1 minute.</li><li>Add the crushed tomatoes, stock, salt, pepper and chilli flakes, stir and add the pasta.</li><li>Bring to a simmer and cook 15 minutes, stirring every couple of minutes and more often toward the end so the pasta does not stick, until nearly cooked.</li><li>Add the cream and simmer 1–2 minutes. The sauce should still be saucy, as the pasta keeps absorbing it. Serve with parmesan and parsley.</li></ol><p><em>Top with grated parmesan and chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('67603f32-211a-5c44-b5ab-b27a0beadeb2', '5cf671c3-49b8-5efc-871d-5eda7a07b97d', 'ru', 'Чоу мейн с говяжьим фаршем, капустой и морковью', 'Яичная лапша с говяжьим фаршем, яйцом, капустой, морковью и ростками фасоли в соусе из соевого и устричного соусов.', '<ol><li>Смешайте светлый и тёмный соевые соусы, устричный соус, китайское вино, сахар и белый перец. В отдельной миске размешайте крахмал с водой.</li><li>Отварите лапшу по инструкции на упаковке и слейте воду.</li><li>В большой антипригарной сковороде на сильном огне 10 секунд прогрейте чеснок, добавьте фарш и жарьте до исчезновения розового цвета. Добавьте 1,5 ст. л. соуса и белую часть зелёного лука и жарьте ещё 2 минуты до карамелизации мяса.</li><li>В оставшийся соус вмешайте раствор крахмала. Вбейте в сковороду яйцо и перемешайте с мясом, чтобы оно слегка свернулось.</li><li>Добавьте морковь и капусту на минуту, пока капуста не начнёт вянуть. Добавьте ростки, лапшу и соус и хорошо перемешивайте 1 минуту. Всыпьте зелёную часть лука, перемешайте ещё минуту и подавайте.</li></ol><p><em>Подайте сразу, пока лапша горячая.</em></p>', CURRENT_TIMESTAMP),
  ('c935ec1c-036a-5646-b51d-b2c3f052eee2', '5cf671c3-49b8-5efc-871d-5eda7a07b97d', 'en', 'Beef chow mein with cabbage and carrot', 'Egg noodles stir-fried with ground beef, egg, cabbage, carrot and bean sprouts in a soy and oyster sauce.', '<ol><li>Mix the light and dark soy sauces, oyster sauce, Chinese cooking wine, sugar and white pepper. In a separate bowl stir the cornstarch with the water.</li><li>Cook the noodles according to the package and drain.</li><li>In a large non-stick pan over high heat cook the garlic 10 seconds, add the beef and cook until no longer pink. Add 1½ tbsp of the sauce and the white parts of the green onion and cook 2 more minutes until caramelised.</li><li>Stir the cornstarch mixture into the remaining sauce. Crack the egg into the pan and mix it through the beef so it scrambles.</li><li>Add the carrot and cabbage for 1 minute until the cabbage starts to wilt. Add the bean sprouts, noodles and sauce and toss well for 1 minute. Add the green onion tops, toss another minute and serve.</li></ol><p><em>Serve immediately while the noodles are hot.</em></p>', CURRENT_TIMESTAMP),
  ('33aca9f6-0dfa-569c-a84c-5967388d761c', '3b793c6a-2eae-5100-a5f2-3c7ed6f7e634', 'ru', 'Тайский салат с говядиной, лаймом и арахисом', 'Тонко нарезанный жареный стейк с зеленью, помидорами черри, огурцом, мятой и кинзой под острой заправкой из рыбного соуса, лайма и чили. Сверху арахис.', '<ol><li>В ступке разотрите чили, чеснок, стебли кинзы и щепотку соли в пасту. Добавьте сахар, рыбный соус, сок лайма и масло, попробуйте и подправьте баланс вкусов.</li><li>Сильно разогрейте сковороду. Сбрызните стейк маслом с двух сторон, посолите и поперчите. Жарьте по 2 минуты с каждой стороны для medium rare (по 2,5 минуты для medium).</li><li>Снимите говядину на тарелку, накройте фольгой и дайте отдохнуть 10 минут. Нарежьте тонкими ломтиками поперёк волокон.</li><li>Сбрызните салатные листья 1 ст. л. заправки. Смешайте говядину с помидорами, луком, огурцом, кинзой и мятой и заправьте большей частью оставшегося соуса.</li><li>Выложите листья на тарелку, сверху говядину с овощами. Посыпьте арахисом, украсьте зеленью и полейте остатками заправки.</li></ol><p><em>Подавайте сразу после заправки.</em></p>', CURRENT_TIMESTAMP),
  ('ba87ea1e-423c-5562-a834-d22804218b31', '3b793c6a-2eae-5100-a5f2-3c7ed6f7e634', 'en', 'Thai beef salad with lime dressing and peanuts', 'Thinly sliced seared steak with salad leaves, cherry tomatoes, cucumber, mint and cilantro in a spicy fish sauce, lime and chilli dressing, topped with peanuts.', '<ol><li>In a mortar grind the chilli, garlic, cilantro stems and a pinch of salt to a paste. Add the sugar, fish sauce, lime juice and oil and adjust the balance to taste.</li><li>Heat a skillet until smoking hot. Drizzle the steak with oil on both sides, season with salt and pepper and cook 2 minutes per side for medium rare (2½ minutes for medium).</li><li>Transfer the beef to a plate, tent with foil and rest 10 minutes. Slice thinly against the grain.</li><li>Toss the lettuce with 1 tbsp of the dressing. Combine the beef with the tomatoes, onion, cucumber, cilantro and mint and dress with most of the remaining dressing.</li><li>Pile the dressed lettuce on a plate and top with the beef mixture. Sprinkle with peanuts, garnish with extra herbs and drizzle with the remaining dressing.</li></ol><p><em>Serve immediately after dressing.</em></p>', CURRENT_TIMESTAMP),
  ('bfc07fdd-fbd7-5b08-85f6-f5c9e02b6fab', '8a146d35-4c6a-542d-9ccc-933cc07c274b', 'ru', 'Куриный суп с перловкой и овощами', 'Лёгкий, но сытный суп из курицы на кости, моркови, лука, сельдерея и перловой крупы. Хорош в холодную погоду.', '<ol><li>Разогрейте в большой кастрюле с толстым дном масло на среднем огне, добавьте морковь, лук, сельдерей и чеснок и перемешайте.</li><li>Добавьте курицу, бульон, петрушку и лавровый лист и доведите до кипения. Убавьте огонь, накройте крышкой и варите около 30 минут до мягкости курицы и овощей.</li><li>Достаньте курицу, разберите на волокна, кости выбросьте. Верните мясо в кастрюлю вместе с перловкой, при необходимости посолите и поперчите. Варите ещё около 30 минут до готовности крупы.</li><li>Выньте лавровый лист и подавайте суп горячим.</li></ol><p><em>Подавайте горячим с ржаным хлебом и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('830bdf16-b211-5a56-be42-ecdbc2449d50', '8a146d35-4c6a-542d-9ccc-933cc07c274b', 'en', 'Chicken barley soup with vegetables', 'A light but filling soup of bone-in chicken, carrots, onion, celery and pearl barley. Ideal for cold days.', '<ol><li>Heat the oil in a large heavy pot over medium heat, add the carrots, onion, celery and garlic and stir.</li><li>Add the chicken, broth, parsley and bay leaves and bring to a boil. Reduce the heat, cover and simmer about 30 minutes until the chicken and vegetables are tender.</li><li>Remove the chicken, shred the meat and discard the bones. Return it to the pot with the barley, season with salt and pepper if needed and simmer about 30 minutes more until the barley is cooked.</li><li>Discard the bay leaves and serve hot.</li></ol><p><em>Serve hot with rye bread and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('ba997c08-119e-5589-b6f9-324742b1e55e', 'f4d08152-f8d3-59bb-bde1-b297b513b13f', 'ru', 'Курица, тушёная с паприкой и болгарским перцем', 'Бёдра и голени на кости, тушёные в одной кастрюле с луком, перцем, чесноком и венгерской паприкой до мягкости и густого соуса.', '<ol><li>Посолите и поперчите курицу. Разогрейте масло в большой кастрюле или жаровне на средне-сильном огне.</li><li>Обжарьте лук и перцы на среднем огне 8–10 минут до мягкости, добавьте чеснок на 1–2 минуты.</li><li>Размешайте в миске муку и паприку с бульоном, влейте в кастрюлю и добавьте лавровый лист.</li><li>Положите курицу, аккуратно перемешайте и доведите до кипения, затем убавьте огонь до слабого.</li><li>Накройте крышкой и тушите 45–50 минут. Выньте лавровый лист и подавайте.</li></ol><p><em>Подавайте с отварным картофелем, рисом или клёцками.</em></p>', CURRENT_TIMESTAMP),
  ('4e2a4ee5-6939-5fde-badb-80b7b5bd3f78', 'f4d08152-f8d3-59bb-bde1-b297b513b13f', 'en', 'Paprika chicken stew with bell peppers', 'Bone-in thighs and drumsticks simmered in one pot with onion, bell peppers, garlic and Hungarian paprika until tender in a rich sauce.', '<ol><li>Season the chicken with salt and pepper. Heat the oil in a large pot or Dutch oven over medium-high heat.</li><li>Sauté the onion and peppers over medium heat 8-10 minutes until soft, then add the garlic for 1-2 minutes.</li><li>Whisk the flour and paprika with the broth in a bowl, pour it into the pot and add the bay leaves.</li><li>Add the chicken, stir gently and bring to a boil, then reduce the heat to low.</li><li>Cover and simmer 45-50 minutes. Discard the bay leaves and serve.</li></ol><p><em>Serve with boiled potatoes, rice or dumplings.</em></p>', CURRENT_TIMESTAMP),
  ('85ed46c2-86eb-508a-8959-0dba9282229e', '56f49da6-5b60-5f01-a03e-c55e5067b024', 'ru', 'Ливанский чечевичный суп с капустой кейл и бататом', 'Густой постный суп из чечевицы, моркови, сельдерея, батата и зелени с большим количеством чеснока, кинзы, имбиря и лимона.', '<ol><li>Выложите промытую чечевицу в большую кастрюлю, влейте бульон и воду. Доведите до кипения, накройте и варите на слабом огне 30 минут до мягкости чечевицы.</li><li>Отделите листья кейла от стеблей: стебли нарежьте мелкими кубиками, листья крупными кусками. Нарежьте кубиками 6 мм морковь, сельдерей и батат.</li><li>В сковороде разогрейте масло, меньше минуты обжарьте чеснок, не давая подгореть, затем добавьте кинзу и перемешайте до увядания. Сразу снимите с огня, зелень должна остаться ярко-зелёной.</li><li>Когда чечевица станет мягкой, добавьте сельдерей, морковь, батат, стебли кейла и имбирь. Варите 15 минут до мягкости овощей.</li><li>Добавьте обжаренный чеснок с кинзой, соль и лимонный сок и проварите 2–3 минуты на слабом огне.</li><li>Снимите с огня, добавьте листья кейла, накройте на 10 минут, затем перемешайте и подавайте.</li></ol><p><em>Подавайте с лимоном и лепёшкой.</em></p>', CURRENT_TIMESTAMP),
  ('2bb4bcbe-15bc-5ecb-af9a-1c8f34da290e', '56f49da6-5b60-5f01-a03e-c55e5067b024', 'en', 'Lebanese lentil soup with kale and sweet potato', 'A thick vegan soup of lentils, carrots, celery, sweet potato and greens, flavoured with lots of garlic, cilantro, ginger and lemon.', '<ol><li>Put the rinsed lentils in a large pot with the broth and water. Bring to a boil, cover and simmer 30 minutes until the lentils are tender.</li><li>Separate the kale leaves from the stems: cube the stems small and cut the leaves into large pieces. Dice the carrots, celery and sweet potato into 6 mm cubes.</li><li>In a skillet heat the oil and cook the garlic for under a minute without burning, then add the cilantro and stir until it softens. Remove from heat immediately; the cilantro should stay bright green.</li><li>When the lentils are soft add the celery, carrots, sweet potato, kale stems and ginger and cook 15 minutes until the vegetables are soft.</li><li>Stir in the garlic and cilantro mixture, salt and lemon juice and simmer 2-3 minutes.</li><li>Take off the heat, add the kale leaves, cover for 10 minutes, then stir and serve.</li></ol><p><em>Serve with lemon wedges and flatbread.</em></p>', CURRENT_TIMESTAMP),
  ('e7a09f02-898f-5c28-827a-a157d9a388b2', '57ed5cd4-9f44-52d1-8a3f-f7818f63f3f4', 'ru', 'Суп с говяжьим фаршем, капустой и томатами', 'Простой густой суп из говяжьего фарша, свежей капусты, моркови, сельдерея и томатов. Готовится на плите или в скороварке.', '<ol><li>Хорошо разогрейте кастрюлю (или скороварку в режиме обжарки). Обжарьте фарш с солью 3–4 минуты, разбивая на мелкие кусочки.</li><li>Добавьте лук, сельдерей и морковь и жарьте 4–5 минут.</li><li>Добавьте томаты, капусту, бульон и лавровый лист. Варите под крышкой на слабом огне около 40 минут (или 20 минут под высоким давлением в скороварке с естественным сбросом пара).</li><li>Выньте лавровый лист и подавайте.</li></ol><p><em>Подавайте со сметаной и чёрным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('f281564e-a603-5626-b4a2-5dae6275b993', '57ed5cd4-9f44-52d1-8a3f-f7818f63f3f4', 'en', 'Ground beef, cabbage and tomato soup', 'A simple, chunky soup of ground beef, fresh cabbage, carrot, celery and tomatoes. Cooks on the stove or in a pressure cooker.', '<ol><li>Heat a large pot (or the pressure cooker on sauté) until very hot. Brown the ground beef with the salt for 3-4 minutes, breaking it up.</li><li>Add the onion, celery and carrot and sauté 4-5 minutes.</li><li>Add the tomatoes, cabbage, stock and bay leaves. Simmer covered on low about 40 minutes (or 20 minutes at high pressure with natural release).</li><li>Remove the bay leaves and serve.</li></ol><p><em>Serve with sour cream and dark bread.</em></p>', CURRENT_TIMESTAMP),
  ('b416d096-1541-50b6-add2-5383fc510037', 'a69d5252-7ae0-54d7-9e58-83eeb7af0fa7', 'ru', 'Курица с лимоном, оливками и травами на сковороде', 'Куриные грудки, обжаренные на сковороде, а затем запечённые с белым вином, лимоном, чесноком, тимьяном и зелёными оливками.', '<ol><li>Разогрейте духовку до 200 °C, решётка посередине.</li><li>Разогрейте масло в чугунной сковороде диаметром 25 см на средне-сильном огне. Посолите и поперчите курицу и посыпьте мукой. Обжарьте по 3 минуты с каждой стороны.</li><li>Добавьте чеснок, вино, цедру и сок лимона, тимьян и оливки. При желании выложите сверху ломтики лимона.</li><li>Поставьте сковороду в духовку примерно на 10 минут, пока внутри курица не прогреется до 74 °C. Подавайте горячей с петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте с рисом, кускусом или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('e639ff11-2261-5382-8daa-e04cf5445f58', 'a69d5252-7ae0-54d7-9e58-83eeb7af0fa7', 'en', 'Skillet lemon chicken with green olives and herbs', 'Chicken breasts seared in a skillet then baked with white wine, lemon, garlic, thyme and green olives.', '<ol><li>Heat the oven to 200°C (400°F) with the rack in the center.</li><li>Heat the oil in a 10-inch cast iron skillet over medium-high heat. Season the chicken with salt and pepper and dust with flour, then sear about 3 minutes per side.</li><li>Add the garlic, wine, lemon zest and juice, thyme and olives. Top with lemon slices if you like.</li><li>Transfer the pan to the oven for about 10 minutes until the chicken reaches 74°C (165°F) inside. Serve hot topped with parsley.</li></ol><p><em>Top with parsley and serve with rice, couscous or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('eb3b5cc3-5825-5a40-badd-ab8e224cb0af', 'fd9fd48f-bd88-5ba0-bea7-cb30674029a5', 'ru', 'Запечённый кордон блю: курица с ветчиной и сыром', 'Тонкие куриные пласты, свёрнутые с ветчиной и швейцарским сыром, обваленные в яйце и сухарях с пармезаном и запечённые в духовке (или в аэрогриле).', '<ol><li>Разогрейте духовку до 230 °C и смажьте большой противень маслом или спреем.</li><li>Обсушите куриные пласты, слегка отбейте, чтобы стали тоньше, посолите и поперчите.</li><li>На каждый пласт положите ломтик ветчины, затем сыр, сверните рулетом и отложите швом вниз.</li><li>Взбейте яйцо и белки с водой. В другой миске смешайте сухари и пармезан. Обмакните рулеты в яйцо, затем в сухари.</li><li>Выложите рулеты швом вниз на противень, сбрызните маслом и запекайте около 25 минут до готовности. В аэрогриле готовьте при 200 °C двумя партиями по 12 минут, перевернув на середине.</li></ol><p><em>Подавайте с картофельным пюре и зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('17f291b3-a49f-5238-98be-8bdfc08030ae', 'fd9fd48f-bd88-5ba0-bea7-cb30674029a5', 'en', 'Baked chicken cordon bleu with ham and Swiss cheese', 'Thin chicken cutlets rolled with ham and Swiss cheese, dipped in egg and parmesan breadcrumbs and baked in the oven or air fryer.', '<ol><li>Heat the oven to 230°C (450°F) and grease a large non-stick baking sheet.</li><li>Dry the chicken cutlets, lightly pound them thinner and season with salt and pepper.</li><li>Lay a slice of ham, then cheese, on each cutlet, roll up and set aside seam side down.</li><li>Whisk the egg and whites with the water. In another bowl mix the breadcrumbs and parmesan. Dip the rolls in the egg, then in the crumbs.</li><li>Place seam side down on the sheet, spray with oil and bake about 25 minutes until cooked through. In an air fryer cook at 200°C in two batches for 12 minutes, turning halfway.</li></ol><p><em>Serve with mashed potatoes and a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('e0ded7ad-9699-528a-91b6-ddfe1d3eca2d', '43d38c2f-be1f-5346-900a-5a1cfa733c0a', 'ru', 'Куриные бёдра, тушёные с грибами и луком-пореем', 'Бёдра на кости, обжаренные и запечённые под крышкой в соусе из шампиньонов, лука-порея, бульона и хереса. Уютное блюдо для холодной погоды.', '<ol><li>Тщательно промойте порей, разделив слои, чтобы не осталось песка. Нарежьте полумесяцами толщиной 6 мм. Разогрейте духовку до 190 °C.</li><li>Смешайте 1¼ ч. л. соли, ¼ ч. л. перца и паприку и натрите курицу со всех сторон.</li><li>Разогрейте жаровню или жаропрочную сковороду на сильном огне, сбрызните маслом и порциями обжарьте курицу по 5 минут с каждой стороны. Отложите.</li><li>Убавьте огонь до средне-слабого, растопите масло и обжарьте порей 6–8 минут до мягкости. Добавьте шампиньоны и оставшуюся соль и готовьте под крышкой 5 минут, пока не пустят сок.</li><li>Посыпьте мукой, влейте бульон и херес и проварите 2–3 минуты.</li><li>Верните курицу, полейте соусом, накройте и тушите в духовке 40–50 минут до мягкости и готовности.</li></ol><p><em>Подавайте с картофельным пюре или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('0edbf7f5-9d07-5e6d-bfd9-0aa5259d6398', '43d38c2f-be1f-5346-900a-5a1cfa733c0a', 'en', 'Braised chicken thighs with mushrooms, leeks and sherry', 'Bone-in thighs browned and braised covered in the oven in a sauce of mushrooms, leeks, broth and sherry. Cosy cold-weather comfort food.', '<ol><li>Rinse the leeks well, separating the layers to remove all dirt, and slice into 6 mm half moons. Heat the oven to 190°C (375°F).</li><li>Mix 1¼ tsp salt, ¼ tsp pepper and the paprika and rub over all sides of the chicken.</li><li>Heat a Dutch oven or oven-safe skillet on high, spritz with oil and brown the chicken in batches, about 5 minutes per side. Set aside.</li><li>Lower the heat to medium-low, melt the butter and cook the leeks 6-8 minutes until soft. Add the mushrooms and remaining salt and cook covered 5 minutes until they release their juices.</li><li>Sprinkle with the flour, add the broth and sherry and simmer 2-3 minutes.</li><li>Return the chicken, spoon the sauce over it, cover and braise in the oven 40-50 minutes until tender and cooked through.</li></ol><p><em>Serve with mashed potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('2841b474-e717-58c2-b9e8-21b784ea665b', 'cd3066e1-2c4c-55e6-9be2-cfc265a57f41', 'ru', 'Свинина с овощами в азиатском стиле', 'Тонкие полоски свинины в соевом маринаде, обжаренные с имбирём, чесноком, стручками гороха, шиитаке и перцем в пикантном соусе с лаймом и шрирачей.', '<ol><li>Нарежьте свинину полосками длиной около 5 см и смешайте с крахмалом и 1½ ст. л. соевого соуса. Отложите.</li><li>В маленькой миске смешайте оставшийся соевый соус, лаймовый сок, мёд, кунжутное масло, уксус и шрирачу.</li><li>Разогрейте на сильном огне антипригарный вок или сковороду с 1 ч. л. масла и обжаривайте свинину 6–7 минут до румяности, переворачивая. Переложите на тарелку.</li><li>Добавьте оставшееся масло, имбирь, чеснок, стручки гороха, шиитаке и перец, перемешайте и влейте соус. Готовьте на слабом огне 2 минуты.</li><li>Верните свинину в вок, перемешайте и подавайте, посыпав зелёным луком.</li></ol><p><em>Подавайте с рисом и посыпьте зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('b759d8b2-2ee7-52da-bdff-7c0057e2620c', 'cd3066e1-2c4c-55e6-9be2-cfc265a57f41', 'en', 'Asian pork stir-fry with snow peas and shiitake', 'Thin strips of pork in a soy marinade, stir-fried with ginger, garlic, snow peas, shiitake and peppers in a zesty lime and sriracha sauce.', '<ol><li>Cut the pork into thin 5 cm strips and toss with the cornstarch and 1½ tbsp of the soy sauce. Set aside.</li><li>In a small bowl mix the remaining soy sauce, lime juice, honey, sesame oil, vinegar and sriracha.</li><li>Heat a large non-stick wok or pan on high with 1 tsp oil and cook the pork 6-7 minutes until browned, turning as it cooks. Transfer to a dish.</li><li>Add the remaining oil, ginger, garlic, snow peas, mushrooms and bell peppers, stir and pour in the sauce. Cook on low heat 2 minutes.</li><li>Return the pork to the wok, stir and serve topped with green onion.</li></ol><p><em>Serve over rice topped with sliced green onion.</em></p>', CURRENT_TIMESTAMP),
  ('a9969820-8cf6-571c-a3b6-23f0c5fafdfe', '64886e6b-e912-54df-bf82-4610127281c6', 'ru', 'Куриные рулетики со шпинатом, фетой и рикоттой', 'Тонкие куриные пласты с начинкой из шпината, феты и рикотты, обвалянные в сухарях и запечённые в духовке или аэрогриле.', '<ol><li>Разогрейте духовку до 175 °C и смажьте противень маслом.</li><li>Разогрейте масло в сковороде, около минуты обжарьте лук, чеснок и зелёный лук до аромата.</li><li>Добавьте шпинат, петрушку, укроп, соль и перец и прогрейте ещё минуту. Снимите с огня и смешайте с фетой и рикоттой.</li><li>Слегка посолите и поперчите куриные пласты. Выложите в центр каждого около ¼ стакана начинки и сверните рулетом швом вниз.</li><li>Взбейте яйцо с водой и щепоткой соли, в другую миску насыпьте сухари. Обмакните рулеты в яйцо, затем в сухари и выложите швом вниз на противень. Сбрызните маслом.</li><li>Запекайте около 25 минут до готовности. В аэрогриле готовьте при 200 °C двумя партиями по 12 минут, перевернув на середине.</li></ol><p><em>Подавайте по 1–2 рулета с овощным салатом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('5ff165f1-351a-5d0e-8eb0-677f550f16bf', '64886e6b-e912-54df-bf82-4610127281c6', 'en', 'Baked chicken rolls with spinach, feta and ricotta', 'Thin chicken cutlets stuffed with spinach, feta and ricotta, breaded and baked in the oven or air fryer.', '<ol><li>Heat the oven to 175°C (350°F) and grease a large baking sheet.</li><li>Heat the oil in a skillet and sauté the onion, garlic and green onion about 1 minute until fragrant.</li><li>Add the spinach, parsley, dill, salt and pepper and heat another minute. Remove from the heat and mix in the feta and ricotta.</li><li>Lightly season the chicken cutlets. Put about ¼ cup of filling in the center of each and roll up, seam side down.</li><li>Whisk the egg with the water and a pinch of salt and put the breadcrumbs in another bowl. Dip the rolls in the egg, then the crumbs, and place seam side down on the sheet. Spray with oil.</li><li>Bake about 25 minutes until cooked through. In an air fryer cook at 200°C in two batches for 12 minutes, turning halfway.</li></ol><p><em>Serve 1-2 rolls with a vegetable salad or rice.</em></p>', CURRENT_TIMESTAMP),
  ('2f8f7d4a-b750-5d00-b0a3-2cbbc15c7b13', '70ede688-4b81-5082-bf7d-02a5d4fb60b3', 'ru', 'Ростбиф с чесноком и розмарином', 'Постный кусок говядины, нашпигованный чесноком, натёртый солью, перцем и розмарином и запечённый до нужной степени прожарки.', '<ol><li>Достаньте мясо из холодильника за час до приготовления, чтобы оно согрелось. Срежьте весь жир. Острым ножом проколите кусок на глубину 1,5 см и вставьте в каждый надрез по пластинке чеснока.</li><li>Слегка смажьте мясо маслом, щедро посолите, поперчите и посыпьте розмарином. Вставьте термометр в центр куска.</li><li>Разогрейте духовку до 175 °C, поставьте мясо в форму для запекания и отправьте в духовку.</li><li>Запекайте до температуры внутри 54 °C для слабой прожарки, 60 °C для средней, 66 °C для средней-прожаренной и 68–71 °C для полной. Достаньте чуть раньше: за время отдыха температура вырастет примерно на 3 °C.</li><li>Дайте мясу отдохнуть 10–20 минут, нарежьте тонкими ломтиками и подавайте.</li></ol><p><em>Дайте мясу отдохнуть 10–20 минут и нарежьте тонкими ломтиками.</em></p>', CURRENT_TIMESTAMP),
  ('fe7560ee-ffd8-56f4-85c0-1d5dde4b28b0', '70ede688-4b81-5082-bf7d-02a5d4fb60b3', 'en', 'Garlic roast beef with rosemary', 'A lean beef roast studded with garlic, rubbed with salt, pepper and rosemary and roasted to your preferred doneness.', '<ol><li>Take the roast out of the fridge an hour before cooking and trim off all fat. With a sharp knife pierce the meat about 1.5 cm deep and push a sliver of garlic into each hole.</li><li>Lightly oil the meat and season generously with salt, pepper and rosemary. Insert the thermometer into the center.</li><li>Heat the oven to 175°C (350°F), put the roast in a roasting pan and place in the oven.</li><li>Roast until the center reaches 54°C for rare, 60°C medium-rare, 66°C medium, 68-71°C well done. Take it out slightly early, as it rises about 3°C while resting.</li><li>Rest the roast 10-20 minutes, then slice thin and serve.</li></ol><p><em>Let the meat rest 10-20 minutes and slice thin.</em></p>', CURRENT_TIMESTAMP),
  ('e90f29e9-8d45-53d4-ab55-b1a5c5cc9265', 'b0ccadcd-858c-5352-8d38-e9e19cd0f920', 'ru', 'Дал из нута-чана со шпинатом и чесночной тадкой', 'Густой индийский дал из колотого нута с томатом и шпинатом, заправленный пряной тадкой из гхи, сушёного чили, зиры и чеснока.', '<ol><li>Замочите чана-дал минимум на 2 часа или на ночь. Промойте, переложите в кастрюлю, залейте 1 л холодной воды, добавьте соду. Доведите до кипения, снимите пену и добавьте куркуму.</li><li>Варите на слабом кипении около 20 минут, пока зёрна не начнут легко раздавливаться пальцами. Добавьте томат и размороженный шпинат и готовьте ещё 15 минут, часто помешивая и разминая чечевицу о стенку для густоты. При необходимости подливайте горячую воду. Посолите.</li><li>Для тадки в маленькой сковороде растопите гхи на среднем и сильном огне, на несколько секунд положите сушёные чили, затем зиру, нарезанный чеснок и молотый чили. Работайте быстро, чтобы специи не сгорели.</li><li>Выключите огонь, вылейте тадку на дал. Немного дала верните в сковороду, чтобы собрать остатки специй, и вылейте обратно.</li></ol><p><em>Подайте с лепёшками наан или варёным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('acf914dd-f9da-54e5-a054-265998bb2efb', 'b0ccadcd-858c-5352-8d38-e9e19cd0f920', 'en', 'Spinach chana dal with garlic tadka', 'A thick Indian dal of split chickpeas with tomato and spinach, finished with a tadka of ghee, dried chilli, cumin and garlic.', '<ol><li>Soak the chana dal for at least 2 hours or overnight. Rinse, put in a pan with 1 litre of cold water and the baking soda. Bring to a boil, skim the foam and stir in the turmeric.</li><li>Simmer gently about 20 minutes until a lentil squashes easily between the fingers. Add the tomato and defrosted spinach and cook another 15 minutes, stirring often and mashing the lentils against the side to thicken. Add hot water if it gets dry and season with salt.</li><li>For the tadka melt the ghee in a small pan over medium-high heat, sizzle the dried chillies a few seconds, then add the cumin seeds, garlic and chilli powder. Work quickly so the spices do not burn.</li><li>Turn off the heat and pour the tadka over the dal. Spoon a little dal into the pan to collect any leftover tadka and tip it back.</li></ol><p><em>Serve with naan or steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('f6b28443-5852-546e-86d9-8d3c32e80417', '128ab73c-b48e-5170-97d7-dd150685b082', 'ru', 'Дал из красной чечевицы с кокосовым молоком и шпинатом', 'Нежный густой дал из красной чечевицы с томатами, кокосовым молоком, имбирём и специями. Шпинат и лимонный сок добавляются в конце.', '<ol><li>В кастрюле на слабом и среднем огне разогрейте кокосовое масло и обжарьте лук с зирой около 5 минут до мягкости. Добавьте чеснок и имбирь на 2–3 минуты.</li><li>Добавьте куркуму, кориандр, кайенский перец, томатную пасту, томаты, кокосовое молоко, чечевицу и бульон. Посолите, перемешайте и варите на слабом огне около 30 минут, иногда помешивая. Если слишком густо, добавьте воды.</li><li>Вмешайте шпинат до увядания, добавьте лимонный сок и рубленую кинзу.</li></ol><p><em>Подайте с рисом или лепёшкой наан и посыпьте кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('cb93d61d-46df-583e-b325-e2b04f57ffcc', '128ab73c-b48e-5170-97d7-dd150685b082', 'en', 'Creamy coconut red lentil dal with spinach', 'A creamy thick dal of red lentils with tomatoes, coconut milk, ginger and spices, finished with spinach and lemon juice.', '<ol><li>In a saucepan over low-medium heat warm the coconut oil and soften the onion with the cumin about 5 minutes. Add the garlic and ginger and cook another 2–3 minutes.</li><li>Stir in the turmeric, coriander, cayenne, tomato purée, tomatoes, coconut milk, lentils and stock. Season, stir and simmer gently about 30 minutes, stirring occasionally. Add a splash of water if too thick.</li><li>Stir through the spinach until wilted, then finish with lemon juice and chopped cilantro.</li></ol><p><em>Serve with rice or naan, topped with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('e9e89ae7-d8d6-54a1-bfa8-e5bde7809c9d', '7b7f2510-ac1f-5752-b14a-c5fabcee1392', 'ru', 'Карри с паниром, нутом и шпинатом в кокосовом молоке', 'Семейное вегетарианское карри: кубики панира и нут, тушёные со шпинатом в кокосовом молоке со специями и ложкой манго-чатни.', '<ol><li>Разогрейте масло в глубокой сковороде на среднем огне и готовьте лук 3–4 минуты до мягкости. Добавьте имбирь, чеснок, все специи и чили и жарьте 1–2 минуты до аромата.</li><li>Добавьте панир и нут, затем кокосовое молоко, шпинат и бульон. Доведите до кипения, убавьте огонь и варите 20 минут, пока соус не загустеет.</li><li>Вмешайте манго-чатни, добавьте соль, перец и лимонный сок. Подайте с рисом, кинзой и по желанию нарезанным чили.</li></ol><p><em>Подайте с рисом басмати и свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('7290b6d2-23b4-5752-ad0e-b850963e877e', '7b7f2510-ac1f-5752-b14a-c5fabcee1392', 'en', 'Paneer, chickpea and spinach coconut curry', 'A family-friendly vegetarian curry of paneer cubes and chickpeas simmered with spinach in spiced coconut milk and a spoonful of mango chutney.', '<ol><li>Heat the oil in a deep frying pan over medium heat and cook the onion 3–4 minutes until soft. Stir in the ginger, garlic, spices and chilli and cook 1–2 minutes until fragrant.</li><li>Stir in the paneer and chickpeas, then the coconut milk, spinach and stock. Bring to a boil, reduce to a simmer and cook 20 minutes until reduced and thickened.</li><li>Stir through the mango chutney and season with salt, pepper and lemon juice. Serve with rice, cilantro and sliced chilli if you like.</li></ol><p><em>Serve with basmati rice and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('a8863cb9-02df-5183-8b09-b2e1733b1e48', '882aed16-6233-5648-a0bb-744b18e01521', 'ru', 'Баранина карахи с томатами и имбирём', 'Баранина на кости, тушёная с томатами, чесноком и имбирём со специями зиры, фенхеля и перца. Подаётся со свежим имбирём, мятой и кинзой.', '<ol><li>В сухой кастрюле с крышкой на среднем огне готовьте баранину с 4 нарезанными помидорами, чесноком (4 зубчика) и тёртым имбирём 20–25 минут, пока помидоры не развалятся, а почти вся жидкость не испарится. Переложите в миску.</li><li>В ту же кастрюлю на среднем огне положите гхи и масло. Когда нагреются, всыпьте зиру, фенхель и перец горошком и жарьте минуту до аромата. Добавьте мелко нарезанный имбирь, чеснок, куркуму и большую щепоть соли на 30 секунд.</li><li>Верните мясо и жарьте минуту. Добавьте оставшиеся помидоры, молотый чили и кориандр, жарьте пару минут. Убавьте огонь до умеренно слабого, накройте и тушите около часа до полной мягкости мяса, пока масло не выступит на поверхность.</li><li>Перед подачей посыпьте кинзой, мятой, зелёным чили и соломкой из имбиря. Подайте с наан или рисом.</li></ol><p><em>Подайте с лепёшками наан или отварным рисом басмати.</em></p>', CURRENT_TIMESTAMP),
  ('27515ebc-a3bf-53ae-a630-a7e9196351a6', '882aed16-6233-5648-a0bb-744b18e01521', 'en', 'Lamb karahi with tomato and ginger', 'Bone-in lamb slow-cooked with tomatoes, garlic and ginger and spiced with cumin, fennel and pepper, finished with fresh ginger, mint and cilantro.', '<ol><li>In a dry lidded pan over medium heat cook the lamb with 4 of the chopped tomatoes, 4 garlic cloves and the grated ginger for 20–25 minutes until the tomatoes break down and most of the liquid evaporates. Transfer to a bowl.</li><li>Return the empty pan to medium heat and add the ghee and oil. When hot, add the cumin, fennel and peppercorns and fry 1 minute until fragrant. Add the chopped ginger, garlic, turmeric and a large pinch of salt for about 30 seconds.</li><li>Return the meat mixture and fry a minute. Add the remaining tomatoes, chilli powder and ground coriander and fry a couple of minutes. Reduce to medium-low, cover and cook about 1 hour until the lamb is completely tender and the oil sits on top.</li><li>To serve top with cilantro, mint, green chillies and ginger matchsticks. Serve with naan or rice.</li></ol><p><em>Serve with naan or boiled basmati rice.</em></p>', CURRENT_TIMESTAMP),
  ('3595fdac-38e4-524f-922c-cae56254a195', '80a5393f-428e-509d-b1da-a5ecdce258a6', 'ru', 'Батата харра: ливанский острый картофель с чесноком', 'Кубики картофеля, отваренные и запечённые до хруста, обжаренные с чесноком и пастой чили и приправленные лимонным соком и кинзой.', '<ol><li>Нарежьте картофель кубиками около 2,5 см, отварите в подсоленной воде 6–8 минут до мягкости. Слейте воду и дайте просохнуть в дуршлаге 5 минут.</li><li>Разогрейте духовку до 200 °C. Выложите картофель на противень с пергаментом, полейте 4 ст. л. масла и запекайте 40 минут до хруста (в аэрогриле при 180 °C 15–20 минут).</li><li>В большой сковороде разогрейте оставшиеся 2 ст. л. масла, обжарьте чеснок 2 минуты, добавьте пасту чили на минуту.</li><li>Переложите картофель в сковороду и хорошо перемешайте. Снимите с огня, сбрызните лимонным соком, посыпьте кинзой и солью.</li></ol><p><em>Хорош как гарнир к мясу и рыбе или как закуска в мезе.</em></p>', CURRENT_TIMESTAMP),
  ('9a4ec00b-2bac-566c-881e-c626394a7422', '80a5393f-428e-509d-b1da-a5ecdce258a6', 'en', 'Batata harra (Lebanese spicy potatoes)', 'Boiled then roasted potato cubes crisped up and tossed with garlic and chilli paste, finished with lemon juice and cilantro.', '<ol><li>Cut the potatoes into 2.5 cm cubes and boil in salted water for 6–8 minutes until tender. Drain and let steam-dry in the colander for 5 minutes.</li><li>Heat the oven to 200°C (180°C fan). Spread the potatoes on a parchment-lined tray, drizzle with 4 tbsp of the oil and roast 40 minutes until crispy (or air fry at 180°C for 15–20 minutes).</li><li>In a large skillet heat the remaining 2 tbsp of oil, cook the garlic 2 minutes, then stir in the chilli paste for a minute.</li><li>Add the potatoes to the skillet and toss well. Remove from the heat, squeeze over the lemon juice and sprinkle with cilantro and salt.</li></ol><p><em>Serve as a side with meat or fish or as part of a meze spread.</em></p>', CURRENT_TIMESTAMP),
  ('e78ca803-2b2a-52c6-a3b2-d4adb4d73d65', 'b6c91545-d50d-5564-9035-21e59c5c0086', 'ru', 'Запеканка из курицы и риса с грибами и пармезаном', 'Куриные бёдра с рисом и грибами в сливочном соусе с пармезаном, запечённые под хрустящей хлебной корочкой.', '<ol><li>Разогрейте духовку до 190 °C. В большой сковороде растопите 1 ст. л. масла на среднем и сильном огне, посолите курицу и обжарьте с двух сторон. Переложите на тарелку.</li><li>Растопите остальное масло, готовьте лук, сельдерей и чеснок с 1 ч. л. соли и перцем 6–7 минут. Добавьте грибы и тимьян на 2–3 минуты. Всыпьте муку и перемешивайте 2 минуты.</li><li>Понемногу влейте молоко и бульон, помешивая, пока соус не загустеет, около 2 минут. Снимите с огня и вмешайте пармезан.</li><li>Выложите курицу, рис и соус в форму примерно 33×23 см, перемешайте и запекайте 20 минут.</li><li>Смешайте хлебную крошку с маслом и приправами, посыпьте блюдо и запекайте ещё 10 минут до золотистой корочки. Посыпьте петрушкой.</li></ol><p><em>Подайте со свежим салатом или зелёными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('7c870ff8-573a-50ff-b5df-d1dc1a076124', 'b6c91545-d50d-5564-9035-21e59c5c0086', 'en', 'Baked chicken and rice casserole with mushrooms and parmesan', 'Chicken thighs with rice and mushrooms in a creamy parmesan sauce, baked under a crisp breadcrumb topping.', '<ol><li>Heat the oven to 190°C (170°C fan). Melt 1 tbsp of the butter in a large frying pan over medium-high heat, season the chicken and brown on both sides. Remove to a plate.</li><li>Melt the remaining butter and cook the onion, celery and garlic with 1 tsp salt and pepper for 6–7 minutes. Add the mushrooms and thyme for 2–3 minutes. Add the flour and stir for 2 minutes.</li><li>Slowly add the milk and stock, stirring until the sauce thickens, about 2 minutes. Remove from the heat and stir in the parmesan.</li><li>Put the chicken, rice and sauce in a roughly 33 x 23 cm baking dish, stir well and bake 20 minutes.</li><li>Mix the breadcrumbs with the oil and seasoning, scatter over the dish and bake another 10 minutes until golden. Sprinkle with parsley.</li></ol><p><em>Serve with a crisp salad or green vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('5c3e60fc-ee6f-5df1-b51c-9ada8e670bb2', 'b7b2287d-fa94-5999-a0ff-94af95eecfb1', 'ru', 'Запечённые спагетти с курицей в сырном соусе', 'Спагетти и куриные бёдра в сливочно-сырном соусе с чеддером, дижонской горчицей и помидорами, запечённые до золотистой корочки.', '<ol><li>В миске смешайте оливковое масло, итальянские травы и чесночный порошок, добавьте куриные бёдра, посолите, поперчите и перемешайте руками.</li><li>Разогрейте большую жаропрочную кастрюлю на среднем огне и обжаривайте курицу 7–8 минут, часто переворачивая, до золотистого цвета (внутри она может быть не готова). Выньте и нарежьте небольшими кусочками.</li><li>Отварите спагетти в большом количестве подсоленной воды. Разогрейте духовку до 200 °C. В кастрюле растопите масло, соскребая румяные частицы со дна, обжарьте лук 7–8 минут до мягкости, добавьте чеснок на 30 секунд.</li><li>Всыпьте муку и перемешайте в пасту, постепенно влейте молоко, затем бульон, помешивая до гладкости. Доведите до кипения, убавьте огонь и вмешайте 200 г сыра. Добавьте дижонскую горчицу, помидоры и курицу, посолите и поперчите.</li><li>Добавьте спагетти, перемешайте щипцами, переложите в глубокую форму, посыпьте оставшимся сыром и запекайте 25 минут до золотистой хрустящей корочки. Посыпьте шнитт-луком.</li></ol><p><em>Посыпьте шнитт-луком; подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('09b5b421-4766-58e2-8eaf-d4ecc770b477', 'b7b2287d-fa94-5999-a0ff-94af95eecfb1', 'en', 'Baked chicken spaghetti with cheddar and Dijon sauce', 'Spaghetti and chicken thighs in a creamy cheddar and Dijon sauce with tomatoes, baked until golden and bubbling.', '<ol><li>In a bowl mix the olive oil, Italian herbs and garlic granules, add the chicken thighs, season with salt and pepper and rub together.</li><li>Heat a large casserole dish over medium heat and cook the chicken 7–8 minutes, turning, until deeply golden (it need not be cooked through). Remove and cut into bite-size pieces.</li><li>Boil the spaghetti in plenty of salted water. Heat the oven to 200°C (180°C fan). Melt the butter in the casserole, scraping up the browned bits, and cook the onion 7–8 minutes until soft, then add the garlic for 30 seconds.</li><li>Stir in the flour to a paste, gradually pour in the milk, then the broth, stirring until smooth. Bring to a boil, reduce the heat and stir in 200 g of the cheese. Add the Dijon, tomatoes and chicken and season.</li><li>Add the spaghetti and toss with tongs, transfer to a deep dish, scatter over the remaining cheese and bake 25 minutes until golden and bubbling. Scatter with chives.</li></ol><p><em>Scatter with chives and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('04b3b477-a408-5c19-91ab-cfc3da6effda', 'f37e3231-8536-5b5a-a43a-4a6106618dda', 'ru', 'Крем-суп из чечевицы с зирой и картофелем', 'Нежный постный суп-пюре из чечевицы с помидором, зелёным луком, зирой и кинзой. Картофель добавляет густоту.', '<ol><li>Разогрейте в большой кастрюле масло на среднем огне, добавьте зелёный лук, чеснок и помидор, посолите и поперчите. Готовьте, помешивая, около 10 минут до мягкости.</li><li>Добавьте большую часть кинзы и зиру и готовьте ещё минуту.</li><li>Добавьте чечевицу, картофель, бульон и лавровый лист. Доведите до кипения, убавьте огонь до средне-слабого, накройте крышкой и варите около 30 минут до мягкости чечевицы.</li><li>Выньте лавровый лист и пробейте суп блендером до однородности, в два приёма, чтобы горячий суп не выплеснулся.</li><li>Досолите и поперчите по вкусу. Разлейте по тарелкам и добавьте сметану, зелёный лук и кинзу.</li></ol><p><em>Подайте со сметаной, зелёным луком и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('d8395d72-9fce-59ae-9764-18f2426a96a8', 'f37e3231-8536-5b5a-a43a-4a6106618dda', 'en', 'Creamy lentil soup with cumin and potato', 'A smooth, light puréed lentil soup with tomato, green onion, cumin and cilantro. A small potato makes it thick and creamy.', '<ol><li>Heat the oil in a large pot over medium heat, add the green onion, garlic and tomato and season with salt and pepper. Cook, stirring, about 10 minutes until soft.</li><li>Stir in most of the cilantro and the cumin and cook 1 more minute.</li><li>Add the lentils, potato, broth and bay leaf. Bring to a boil, reduce to medium-low, cover and cook about 30 minutes until the lentils are tender.</li><li>Discard the bay leaf and purée the soup in a blender until very smooth, in two batches so it doesn''t splash out.</li><li>Adjust the salt and pepper, ladle into bowls and top with sour cream, green onion and cilantro.</li></ol><p><em>Top with sour cream, green onion and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('d4f27d49-d650-5a90-b24b-67d93ff8e5a9', '275ee24e-58f9-5e0c-97d7-253686ce9761', 'ru', 'Карри из красной чечевицы с гарам масалой', 'Постное блюдо из красной чечевицы, томатов, лука и пряностей: гарам масала, карри, кориандр, зира и имбирь. Хорошо подходит к рису.', '<ol><li>Прогрейте в большой кастрюле на средне-сильном огне семена зиры около минуты до аромата и лёгкого потемнения.</li><li>Добавьте помидоры, лук, чеснок, гарам масалу, карри, кориандр, соль и имбирь. Готовьте 5 минут, иногда помешивая.</li><li>Добавьте промытую чечевицу и воду, доведите до кипения, накройте и варите на слабом огне 20–30 минут до мягкости чечевицы. В скороварке готовьте под давлением 20 минут и дайте пару сбросить естественно.</li><li>Подавайте с рисом, посыпав кинзой и выжав дольку лайма.</li></ol><p><em>Подавайте с отварным рисом, кинзой и долькой лайма.</em></p>', CURRENT_TIMESTAMP),
  ('344a711c-ae7f-5bb8-99f0-5e0765b666ce', '275ee24e-58f9-5e0c-97d7-253686ce9761', 'en', 'Red lentil curry with garam masala', 'A vegan dish of red lentils, tomatoes, onion and spices: garam masala, curry powder, coriander, cumin and ginger. Great over rice.', '<ol><li>Toast the cumin seeds in a large pot over medium-high heat about 1 minute until fragrant and browned.</li><li>Add the tomatoes, onion, garlic, garam masala, curry powder, coriander, salt and ginger and cook 5 minutes, stirring occasionally.</li><li>Stir in the rinsed lentils and water, bring to a boil, cover and simmer 20-30 minutes until tender. In a pressure cooker, cook 20 minutes and let the pressure release naturally.</li><li>Serve over rice topped with cilantro and a squeeze of lime.</li></ol><p><em>Serve over rice with cilantro and a squeeze of lime.</em></p>', CURRENT_TIMESTAMP),
  ('337d53c9-96f4-565c-9e65-12b08ca3c172', 'ba1a45fa-d578-5a03-9274-60ec729fa6fa', 'ru', 'Суп с говяжьим фаршем, перцем и рисом (как фаршированный перец)', 'Томатный суп из говяжьего фарша, болгарского перца и лука со вкусом фаршированных перцев. Подаётся с порцией варёного бурого риса.', '<ol><li>В большой кастрюле или жаровне обжарьте фарш на сильном огне, посолив. Слейте лишний жир, если он есть.</li><li>Убавьте огонь до средне-слабого, добавьте перцы, лук и чеснок и готовьте около 5 минут.</li><li>Добавьте томаты, томатный соус, бульон и майоран, посолите и поперчите. Накройте крышкой и варите на слабом огне 30 минут. В скороварке готовьте 15 минут под высоким давлением с естественным сбросом пара.</li><li>Разлейте по тарелкам по 1½ стакана супа и положите сверху по ½ стакана варёного риса.</li></ol><p><em>Положите в каждую тарелку по половине стакана варёного риса.</em></p>', CURRENT_TIMESTAMP),
  ('d24a6798-c2d2-5091-9617-ccbf38981ced', 'ba1a45fa-d578-5a03-9274-60ec729fa6fa', 'en', 'Stuffed pepper soup with ground beef and brown rice', 'A tomato soup of ground beef, bell peppers and onion that tastes like stuffed peppers, served over cooked brown rice.', '<ol><li>In a large pot or Dutch oven brown the ground beef over high heat with a little salt. Drain any fat.</li><li>Reduce the heat to medium-low, add the peppers, onion and garlic and cook about 5 minutes.</li><li>Add the tomatoes, tomato sauce, broth and marjoram, season with salt and pepper, cover and simmer on low 30 minutes. In a pressure cooker, cook 15 minutes at high pressure with natural release.</li><li>Ladle about 1½ cups of soup into each bowl and top with ½ cup cooked brown rice.</li></ol><p><em>Put about half a cup of cooked rice in each bowl.</em></p>', CURRENT_TIMESTAMP),
  ('e4076049-9ce8-55f2-8859-e344fb764bcc', '36af86f8-40dc-5ed8-82e1-2b60bb671c0f', 'ru', 'Картофельное пюре со сметаной и кефиром в скороварке', 'Нежное картофельное пюре, сваренное под давлением всего за 10 минут и заправленное маслом, сметаной и кефиром.', '<ol><li>Выложите очищенный картофель, разрезанный на четвертинки, в скороварку, залейте водой, чтобы едва покрыть, добавьте 1 ч. л. соли.</li><li>Закройте крышку и готовьте под высоким давлением 10 минут, затем быстро сбросьте пар. Картофель должен легко прокалываться ножом.</li><li>Слейте воду, оставив полстакана. Добавьте масло, сметану, кефир, оставшуюся соль и перец и разомните толкушкой.</li><li>Попробуйте и досолите. Если пюре стоит и подсохло, разведите оставленной водой. Посыпьте зеленью и подавайте.</li></ol><p><em>Подавайте сразу, посыпав рубленой зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('2ba447d5-17ab-57de-8aec-e4c9aa6263de', '36af86f8-40dc-5ed8-82e1-2b60bb671c0f', 'en', 'Pressure cooker mashed potatoes with kefir', 'Creamy mashed potatoes cooked under pressure in just 10 minutes and finished with butter, sour cream and kefir (a stand-in for buttermilk).', '<ol><li>Put the peeled, quartered potatoes in the pressure cooker, add just enough water to cover and 1 tsp of the salt.</li><li>Close the lid and cook at high pressure for 10 minutes, then quick release. The potatoes should be easily pierced with a knife.</li><li>Drain, reserving ½ cup of the cooking water. Add the butter, sour cream, kefir, remaining salt and pepper and mash with a masher.</li><li>Taste and adjust the salt. If the mash dries out, loosen it with the reserved water. Garnish with herbs and serve.</li></ol><p><em>Serve right away, sprinkled with chopped herbs.</em></p>', CURRENT_TIMESTAMP),
  ('484d3b74-1ae7-5dc4-b081-b12a709a8fe3', '7016c5a5-072f-5a70-919d-5e273f9be27a', 'ru', 'Суп-пюре из печёного красного перца с картофелем', 'Сладковатый суп-пюре из запечённых болгарских перцев, картофеля, моркови и лука с лёгкой сметаной и пармезаном.', '<ol><li>Запеките перцы: разогрейте духовку до 240 °C (или используйте режим гриль) и выпекайте целые перцы, переворачивая, пока кожица полностью не почернеет и не вздуется, примерно 25–30 минут.</li><li>Переложите перцы в миску, накройте фольгой на 10 минут, чтобы они пропарились. Снимите кожицу, удалите плодоножки и семена, грубо нарежьте.</li><li>В большой кастрюле разогрейте масло на среднем огне. Обжарьте лук, морковь, чеснок и травы 5–7 минут до мягкости лука.</li><li>Добавьте бульон, печёные перцы, нарезанный картофель, доведите до кипения, убавьте огонь, накройте и варите около 30 минут до полной мягкости картофеля.</li><li>Пробейте суп со сметаной погружным или обычным блендером порциями до гладкости. Посолите и поперчите, прогрейте пару минут.</li><li>Разлейте по тарелкам, посыпьте пармезаном и зеленью.</li></ol><p><em>Посыпьте пармезаном и зеленью, подайте с тостами.</em></p>', CURRENT_TIMESTAMP),
  ('c614a469-0eec-5681-82f0-17bfc7ed0c06', '7016c5a5-072f-5a70-919d-5e273f9be27a', 'en', 'Roasted red pepper and potato soup with parmesan', 'A sweet, smoky puréed soup of roasted red peppers, potato, carrot and onion, finished with light sour cream and parmesan.', '<ol><li>Roast the peppers: heat the oven to 240°C (or use the broiler) and roast whole peppers, turning, until the skins are fully blackened and blistered, about 25-30 minutes.</li><li>Put the peppers in a bowl and cover with foil for 10 minutes to steam. Peel off the skins, remove the stems and seeds and chop roughly.</li><li>Heat the oil in a large pot over medium heat and sauté the onion, carrot, garlic and herbs 5-7 minutes until the onion is translucent.</li><li>Add the broth, roasted peppers and chopped potato, bring to a boil, then reduce, cover and simmer about 30 minutes until the potato is very tender.</li><li>Purée the soup with the sour cream using an immersion or regular blender until smooth. Season with salt and pepper and heat through for a couple of minutes.</li><li>Ladle into bowls and top with parmesan and fresh herbs.</li></ol><p><em>Top with parmesan and fresh herbs and serve with toast.</em></p>', CURRENT_TIMESTAMP),
  ('d23ffaec-9666-5513-9605-99f9750665c2', 'a9d6e356-4e81-510c-aeca-9549e09d875a', 'ru', 'Тушёная говядина с тыквой', 'Говядина, медленно тушёная с луком, томатной пастой, красным вином и травами. Тыкву добавляют, когда мясо почти готово.', '<ol><li>В большой кастрюле или жаровне обжарьте лук на масле на среднем огне около 5 минут до мягкости, затем добавьте чеснок на 1 минуту.</li><li>Добавьте мясо и 1 ч. л. соли и обжаривайте 5–7 минут. Добавьте томатную пасту и готовьте ещё минуту.</li><li>Добавьте бульон, вино, орегано, тимьян и лавровый лист, накройте и тушите на слабом огне около 1,5 часов до мягкости мяса.</li><li>Добавьте тыкву и готовьте ещё 30–35 минут до её мягкости.</li><li>Попробуйте и при необходимости досолите. Выньте лавровый лист и подавайте.</li></ol><p><em>Подавайте с хрустящим хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('a52d3a1c-99be-52a9-98ae-17ff02c10c7f', 'a9d6e356-4e81-510c-aeca-9549e09d875a', 'en', 'Beef stew with pumpkin', 'Beef slowly simmered with onion, tomato paste, red wine and herbs, with pumpkin added once the meat is tender.', '<ol><li>In a large pot or Dutch oven sauté the onion in the oil over medium heat about 5 minutes until soft, then add the garlic for 1 minute.</li><li>Add the beef and 1 tsp salt and brown 5-7 minutes. Stir in the tomato paste and cook 1 minute.</li><li>Add the broth, wine, oregano, thyme and bay leaf, cover and cook on low about 1½ hours until the meat is tender.</li><li>Add the pumpkin and cook another 30-35 minutes until it is tender.</li><li>Taste and adjust the salt, discard the bay leaf and serve.</li></ol><p><em>Serve with crusty bread to soak up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('eb1f724d-fbd7-52f8-b8e0-3fc32b7eb593', '86a336af-b5ff-5c56-a080-b5807cf0633f', 'ru', 'Суп с курицей и чечевицей в мультиварке', 'Простой суп «всё в чашу»: чечевица, куриные бёдра, морковь и томаты с куркумой и зирой томятся в мультиварке без предварительной обжарки.', '<ol><li>Выложите в чашу мультиварки на 6 л все ингредиенты: чечевицу, куриные бёдра, бульон, томаты, морковь, лук, чеснок, перец, куркуму, зиру, соль и перец.</li><li>Готовьте на высоком режиме 4 часа или на низком 8 часов.</li><li>Разберите курицу двумя вилками на волокна, перемешайте с супом и при необходимости досолите.</li></ol><p><em>Хорош для заготовки на неделю, подавайте с зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('01b03fb6-062f-5d19-a4d1-a939b271f52d', '86a336af-b5ff-5c56-a080-b5807cf0633f', 'en', 'Slow cooker chicken and lentil soup with turmeric', 'An easy dump-and-go soup: lentils, chicken thighs, carrots and tomatoes with turmeric and cumin slowly cooked in the slow cooker with no sautéing.', '<ol><li>Put all the ingredients in a 6-quart slow cooker: lentils, chicken thighs, broth, tomatoes, carrots, onion, garlic, bell pepper, turmeric, cumin, salt and pepper.</li><li>Cook on high for 4 hours or on low for 8 hours.</li><li>Shred the chicken with two forks, stir it back into the soup and adjust the seasoning.</li></ol><p><em>Great for meal prep; serve with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('d1f3e9c5-70bc-5446-9f75-b3e0fbf6d410', 'cfdbbbd5-480d-5230-a9a4-460a954849cb', 'ru', 'Индейка с бататом, чёрной фасолью и кукурузой на сковороде', 'Быстрое блюдо в одной сковороде: фарш индейки с бататом, чёрной фасолью, кукурузой, помидорами и зирой. Хорошо подходит для заготовки на неделю.', '<ol><li>Смажьте большую сковороду маслом, разогрейте на сильном огне и обжарьте фарш индейки с 1 ч. л. соли и 1 ч. л. зиры, разбивая комочки, около 5 минут до готовности.</li><li>Сдвиньте мясо в сторону, добавьте лук и томатную пасту и готовьте 1 минуту.</li><li>Добавьте батат, фасоль, кукурузу, помидор, халапеньо, чеснок, кинзу и бульон. Всыпьте оставшуюся соль и зиру и перемешайте.</li><li>Накройте крышкой и тушите на слабом огне 12–14 минут, пока батат не станет мягким.</li><li>Подавайте с авокадо, дольками лайма и кинзой.</li></ol><p><em>Подавайте с авокадо, кинзой и дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('8e703d00-e35c-5f37-9086-fafecdb39075', 'cfdbbbd5-480d-5230-a9a4-460a954849cb', 'en', 'Ground turkey skillet with sweet potatoes, black beans and corn', 'A quick one-pan dinner of ground turkey with sweet potato, black beans, corn, tomatoes and cumin. Great for meal prep.', '<ol><li>Oil a large skillet over high heat and brown the turkey with 1 tsp salt and 1 tsp cumin, breaking it up, about 5 minutes until cooked through.</li><li>Push the meat to one side and cook the onion and tomato paste in the cleared space for 1 minute.</li><li>Add the sweet potato, black beans, corn, tomato, jalapeño, garlic, cilantro and broth. Add the remaining salt and cumin and stir.</li><li>Cover and cook on low 12-14 minutes until the sweet potato is tender.</li><li>Serve with avocado, lime wedges and extra cilantro.</li></ol><p><em>Serve with avocado, cilantro and lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('7b429131-39bd-54f2-8b59-dfa665102a39', '223da5a7-cb44-536d-80c5-927130820de7', 'ru', 'Куриные бёдра с рататуем из баклажанов, кабачков и томатов', 'Бёдра на кости, обжаренные и запечённые в овощном рататуе с баклажанами, кабачками, перцем и помидорами, с базиликом в конце.', '<ol><li>Разогрейте духовку до 200 °C.</li><li>Разогрейте жаровню на средне-сильном огне с ½ ст. л. масла. Обсушите курицу, посолите и поперчите и обжарьте, не трогая, около 5 минут, затем с другой стороны около 3 минут. Переложите на тарелку.</li><li>Убавьте огонь до среднего, добавьте остальное масло, лук, чеснок и щепотку соли и готовьте около 3 минут. Добавьте баклажан и ещё щепотку соли и готовьте около 5 минут до начала размягчения.</li><li>Добавьте томатную пасту и тимьян и готовьте, помешивая, 1 минуту. Затем добавьте кабачки, перец, помидоры, ещё соли и перца и тушите около 10 минут до мягкости овощей. Снимите с огня.</li><li>Частично погрузите курицу в овощи, поставьте жаровню в духовку без крышки на 20 минут, пока в самой толстой части не будет 71 °C.</li><li>Дайте постоять 10 минут, добавьте нарезанный базилик, перемешайте и подавайте.</li></ol><p><em>Дайте блюду постоять 10 минут и подайте с хлебом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('a1386239-a6ef-50f8-bb1b-2e36bd2b02b3', '223da5a7-cb44-536d-80c5-927130820de7', 'en', 'Ratatouille baked chicken thighs', 'Bone-in thighs browned and finished in the oven in a ratatouille of eggplant, zucchini, bell pepper and tomatoes, topped with basil.', '<ol><li>Heat the oven to 200°C (400°F).</li><li>Heat a Dutch oven over medium-high heat with ½ tbsp oil. Pat the chicken dry, season, and sear without moving about 5 minutes, then flip and brown about 3 minutes more. Move to a plate.</li><li>Reduce to medium and add the remaining oil, onion, garlic and a pinch of salt; cook about 3 minutes. Add the eggplant and another pinch of salt and cook about 5 minutes until it starts to soften.</li><li>Add the tomato paste and thyme and stir for 1 minute. Add the zucchini, pepper, tomatoes, more salt and pepper and cook about 10 minutes until all the vegetables are tender. Remove from the heat.</li><li>Partially nestle the chicken into the vegetables and bake uncovered about 20 minutes until the thickest part reaches 71°C (160°F).</li><li>Let it stand 10 minutes, stir in the chopped basil and serve.</li></ol><p><em>Let it stand 10 minutes and serve with bread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('067411d7-a521-5bb1-a175-7b162ac66d38', 'de6d63ae-c06f-5012-9a6e-3bb8c1e3ef2b', 'ru', 'Вегетарианский фо с шиитаке и рисовой лапшой', 'Ароматный вьетнамский суп на овощном бульоне с корицей, звёздчатым анисом, имбирём и гвоздикой, с рисовой лапшой, обжаренными шиитаке и свежей зеленью.', '<ol><li>В кастрюле на среднем огне 3–4 минуты прогревайте корицу, гвоздику и бадьян, пока не появится аромат. Добавьте лук, имбирь, овощной бульон, воду и соевый соус, доведите до кипения на сильном огне и варите на слабом кипении 30 минут.</li><li>Тем временем отварите рисовую лапшу по инструкции на упаковке и отложите.</li><li>Разогрейте масло в сковороде и 4–6 минут обжаривайте тонко нарезанные шиитаке с щепоткой соли до мягкости и лёгкого румянца.</li><li>Процедите бульон, удалив лук, имбирь и специи. Подправьте вкус соевым соусом или солью.</li><li>Разлейте бульон по мискам, добавьте лапшу, грибы и свежую зелень, лайм и халапеньо по вкусу. Подавайте сразу.</li></ol><p><em>Подавайте с ростками фасоли, базиликом, мятой, лаймом и ломтиками халапеньо.</em></p>', CURRENT_TIMESTAMP),
  ('cd08b63c-9984-52be-8552-b656d82a8b53', 'de6d63ae-c06f-5012-9a6e-3bb8c1e3ef2b', 'en', 'Vegetarian pho with shiitake and rice noodles', 'A fragrant Vietnamese soup in a spiced vegetable broth with cinnamon, star anise, ginger and cloves, with rice noodles, sautéed shiitake and fresh herbs.', '<ol><li>In a pot over medium heat toast the cinnamon sticks, cloves and star anise 3–4 minutes until fragrant. Add the onion, ginger, vegetable stock, water and soy sauce, bring to a boil on high, then simmer gently 30 minutes.</li><li>Meanwhile cook the rice noodles according to the package and set aside.</li><li>Warm the oil in a skillet and cook the thinly sliced shiitake with a pinch of salt 4–6 minutes until tender and lightly browned.</li><li>Strain the broth to remove the onion, ginger and spices. Adjust the flavour with more soy sauce or salt.</li><li>Ladle the broth into bowls, add the noodles, mushrooms and fresh garnishes, with lime and jalapeño to taste. Serve immediately.</li></ol><p><em>Serve with bean sprouts, basil, mint, lime wedges and sliced jalapeño.</em></p>', CURRENT_TIMESTAMP),
  ('072dfff3-79e3-5a45-bcc2-c1ecaf6af7ef', '0a2f57ed-61c3-5e20-8a95-f2cca7441c33', 'ru', 'Мексиканский густой суп с киноа и чёрной фасолью', 'Сытный овощной суп с киноа, чёрной фасолью, томатами, морковью, сельдереем и халапеньо, с зирой и кинзой.', '<ol><li>В кастрюле на среднем огне разогрейте масло и около 8 минут тушите лук, сельдерей, морковь, чеснок и халапеньо до мягкости овощей.</li><li>Добавьте воду, томаты, фасоль, зиру, соль, киноа, кинзу и кайенский перец. Поперчите и доведите до кипения.</li><li>Убавьте огонь, накройте и варите около 15 минут, пока киноа не станет мягким. Досолите по вкусу. При желании пробейте блендером пару половников супа для густоты.</li></ol><p><em>Подайте с авокадо, лаймом, кинзой и тортилья-чипсами.</em></p>', CURRENT_TIMESTAMP),
  ('542bece0-c20c-5160-ae48-f5ec49639be8', '0a2f57ed-61c3-5e20-8a95-f2cca7441c33', 'en', 'Mexican quinoa and black bean vegetable stew', 'A hearty vegetable soup with quinoa, black beans, tomatoes, carrots, celery and jalapeño, flavoured with cumin and cilantro.', '<ol><li>In a soup pot over medium heat warm the oil and sauté the onion, celery, carrots, garlic and jalapeños about 8 minutes until tender.</li><li>Add the water, tomatoes, beans, cumin, salt, quinoa, cilantro and cayenne. Season with pepper and bring to a boil.</li><li>Reduce the heat, cover and simmer about 15 minutes until the quinoa is tender. Adjust the salt. If you like, purée a couple of cups with an immersion blender to thicken it.</li></ol><p><em>Serve with avocado, lime, cilantro and crushed tortilla chips.</em></p>', CURRENT_TIMESTAMP),
  ('22eb82b9-296c-5eaa-948e-74e9ba64dc59', '391632c2-f99e-5495-ab9c-6a562f91a8ff', 'ru', 'Постный позоле с фасолью пинто и кукурузой хомини', 'Густой мексиканский суп без мяса: фасоль пинто и кукуруза хомини в бульоне с томатной пастой, зирой и обжаренными перцами гуахильо.', '<ol><li>Срежьте у перцев гуахильо плодоножки, вытряхните семена, ополосните и обсушите.</li><li>Прогрейте сухую кастрюлю на среднем огне, обжаривайте перцы, прижимая лопаткой на несколько секунд с каждой стороны до аромата. Переложите и отложите.</li><li>В той же кастрюле разогрейте масло, обжарьте лук с щепоткой соли 5 минут до прозрачности. Добавьте чеснок и зиру на минуту, затем томатную пасту ещё на минуту.</li><li>Добавьте обжаренные перцы, лавровый лист, хоминни, фасоль, бульон, воду и ½ ч. л. соли. Доведите до кипения и варите на слабом огне 25 минут.</li><li>Выньте перцы и лавровый лист. Добавьте половину кинзы и сок половины лайма, попробуйте и досолите. Разлейте по мискам с оставшейся кинзой и дольками лайма.</li></ol><p><em>Подайте с авокадо, шинкованной капустой, редисом, луком и лаймом.</em></p>', CURRENT_TIMESTAMP),
  ('fd3fca4a-c9cf-56f2-bc03-9ba12690a9f4', '391632c2-f99e-5495-ab9c-6a562f91a8ff', 'en', 'Vegan pinto bean and hominy posole', 'A hearty meatless Mexican soup of pinto beans and hominy in a broth with tomato paste, cumin and toasted guajillo chilies.', '<ol><li>Cut the stems off the guajillo chilies, shake out as many seeds as possible, rinse and pat dry.</li><li>Heat a dry pot over medium heat and toast the chilies, pressing them flat with a spatula a few seconds per side until fragrant. Set aside.</li><li>In the same pot warm the oil and cook the onion with a pinch of salt 5 minutes until translucent. Add the garlic and cumin for a minute, then the tomato paste for another minute.</li><li>Add the toasted chilies, bay leaf, hominy, beans, vegetable broth, water and ½ tsp salt. Bring to a simmer and cook 25 minutes.</li><li>Remove the chilies and bay leaf. Stir in half the cilantro and the juice of half a lime, taste and add salt if needed. Serve with the remaining cilantro and lime wedges.</li></ol><p><em>Garnish with avocado, shredded cabbage, radish, onion and lime.</em></p>', CURRENT_TIMESTAMP),
  ('774d164c-68b5-576e-b32a-e16d09278f47', 'e641df92-9da9-5142-8c81-f8fe583a27f7', 'ru', 'Соба с овощами и кунжутной заправкой', 'Лапша соба с краснокочанной капустой, морковью, сладким перцем, зелёным луком и кинзой под заправкой из соевого соуса, кунжутного масла, лайма и имбиря.', '<ol><li>Отварите лапшу по инструкции, слейте воду и хорошо промойте холодной. Переложите в большую миску.</li><li>Обжарьте кунжут на сухой сковороде на среднем огне, часто помешивая, до золотистого цвета и аромата. Сразу переложите в миску, чтобы не сгорел.</li><li>Взбейте соевый соус, кунжутное масло, сок лайма, имбирь, чеснок и хлопья чили.</li><li>К лапше добавьте капусту, морковь (нарезанную ленточками овощечисткой), перец, лук, кинзу и по желанию эдамаме. Полейте заправкой, добавьте кунжут и перемешайте щипцами. Подайте сразу или охладите.</li></ol><p><em>Для сытности добавьте отварной эдамаме. Подавайте холодной или комнатной температуры.</em></p>', CURRENT_TIMESTAMP),
  ('060b4e90-f189-57ff-af85-a39f87d9db47', 'e641df92-9da9-5142-8c81-f8fe583a27f7', 'en', 'Veggie sesame soba noodles', 'Soba noodles with red cabbage, carrots, bell pepper, green onions and cilantro in a soy, sesame oil, lime and ginger dressing.', '<ol><li>Cook the noodles per the package, drain, rinse well under cool water and put in a large serving bowl.</li><li>Toast the sesame seeds in a small dry skillet over medium heat, stirring often, until fragrant and golden. Transfer to a bowl right away so they do not burn.</li><li>Whisk together the soy sauce, sesame oil, lime juice, ginger, garlic and red pepper flakes.</li><li>Add the cabbage, carrots (cut into ribbons with a peeler), bell pepper, green onions, cilantro and optional edamame to the noodles. Pour over the dressing, add the sesame seeds and toss with tongs. Serve right away or refrigerate.</li></ol><p><em>Add steamed edamame to make it more filling. Serve cold or at room temperature.</em></p>', CURRENT_TIMESTAMP),
  ('10fd9754-90b4-59eb-bffa-b1b65fb8be88', '377ce4a9-295b-5a28-80ae-bda65d87668e', 'ru', 'Овощной стир-фрай с лапшой в соусе терияки', 'Обжаренные до золотистых краёв брокколи, морковь, перец и грибы с лапшой собой в соусе терияки, кунжутным маслом и кунжутом.', '<ol><li>Отварите лапшу до состояния al dente, слейте воду и хорошо промойте, чтобы убрать крахмал.</li><li>В большой сковороде на среднем огне разогрейте масло, добавьте лук и соль и готовьте 4–6 минут до мягкости.</li><li>Добавьте остальные нарезанные овощи и готовьте 10–15 минут, помешивая раз в минуту-две, пока они не станут мягкими и не зарумянятся по краям.</li><li>Добавьте лапшу и соус терияки, перемешайте и прогрейте около минуты. Снимите с огня, добавьте кунжутное масло и кунжут.</li><li>Разложите по мискам и посыпьте зелёным луком и кунжутом.</li></ol><p><em>Посыпьте зелёным луком и кунжутом. Любые овощи подойдут.</em></p>', CURRENT_TIMESTAMP),
  ('d30108ac-2400-5860-b4a6-e8d79ee2e5dc', '377ce4a9-295b-5a28-80ae-bda65d87668e', 'en', 'Veggie teriyaki stir-fry with soba noodles', 'Broccoli, carrot, bell pepper and mushrooms cooked until caramelised at the edges and tossed with soba noodles, teriyaki sauce, toasted sesame oil and sesame seeds.', '<ol><li>Cook the noodles until al dente, then drain and rinse well to remove excess starch.</li><li>In a large skillet over medium heat warm the oil, add the onion and salt and cook 4–6 minutes until tender.</li><li>Add the remaining sliced vegetables and cook 10–15 minutes, stirring every minute or two, until tender and caramelised at the edges.</li><li>Add the noodles and teriyaki sauce and stir until warmed through, about 1 minute. Remove from the heat and add the sesame oil and sesame seeds.</li><li>Divide into bowls and garnish with green onion and a little extra sesame seeds.</li></ol><p><em>Top with green onion and sesame seeds. Any vegetables work.</em></p>', CURRENT_TIMESTAMP),
  ('ad164a92-37fc-5f96-b314-ef2210fc3e49', '23bbf7f4-8e46-54c7-ae44-c54759b53202', 'ru', 'Салат с киноа, капустой и арахисовым соусом по-тайски', 'Хрустящий салат из киноа, красной капусты, моркови и сладкого горошка в густой арахисовой заправке с соевым соусом, лаймом и имбирём.', '<ol><li>Промойте киноа в мелком сите, залейте водой в кастрюле и на среднем огне доведите до слабого кипения. Убавьте огонь и варите 10–15 минут, пока вода не впитается. Накройте на 5 минут, разрыхлите вилкой и остудите.</li><li>Для соуса взбейте арахисовую пасту с соевым соусом до гладкости (при необходимости подогрейте в микроволновке до 30 секунд). Добавьте остальные ингредиенты соуса и взбейте. Если слишком густо, добавьте немного воды.</li><li>Смешайте в большой миске киноа, капусту, морковь, горошек, кинзу и зелёный лук. Влейте соус и перемешайте. При необходимости добавьте щепотку соли. Разложите по тарелкам и посыпьте арахисом.</li></ol><p><em>Арахис для посыпки храните отдельно и добавляйте перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('fb54b8c1-a4c6-5228-8646-dda7d3038af7', '23bbf7f4-8e46-54c7-ae44-c54759b53202', 'en', 'Crunchy Thai peanut and quinoa cabbage salad', 'A crunchy salad of quinoa, red cabbage, carrots and snow peas in a creamy peanut dressing with soy sauce, lime and ginger.', '<ol><li>Rinse the quinoa in a fine sieve, combine with the water in a pot and bring to a gentle boil over medium heat. Reduce to medium-low and simmer 10–15 minutes until the water is absorbed. Cover and rest 5 minutes, fluff with a fork and let cool.</li><li>For the sauce whisk the peanut butter and soy sauce until smooth (microwave up to 30 seconds if hard to mix). Add the remaining sauce ingredients and whisk. Loosen with a little water if too thick.</li><li>Combine the quinoa, cabbage, carrot, snow peas, cilantro and green onion in a large bowl. Pour in the sauce and toss. Add a pinch of salt if needed. Divide into bowls and garnish with peanuts.</li></ol><p><em>Keep the chopped peanuts separate and add them just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('8aed5aa7-f107-5293-a6a8-55d5dc353e37', '10aa3a38-e212-5521-a186-8ac2198ba736', 'ru', 'Запечённый батат, фаршированный рисом, фасолью, сальсой и гуакамоле', 'Целиком запечённый батат, наполненный рисом с чёрной фасолью и зирой, свежей сальсой из перца и помидоров и гуакамоле.', '<ol><li>Разогрейте духовку до 200 °C, застелите форму пергаментом. Уложите батат, наколите вилкой и запекайте около 45 минут (5–10 минут дольше для крупных) до полной мягкости.</li><li>В кастрюле смешайте рис, фасоль, зиру, чеснок, масло, томатную пасту и соль, влейте около 300 мл воды. Накройте, доведите до кипения, убавьте огонь и варите примерно 40 минут, пока вода не впитается. Держите под крышкой в тепле.</li><li>Для сальсы смешайте перец, черри, красный лук, сок лайма, кинзу и масло, посолите и поперчите.</li><li>Для гуакамоле разомните авокадо вилкой с чесноком, соком лайма, кинзой и щепоткой соли до крупной пасты.</li><li>Надрежьте каждый батат вдоль и разведите края. Заполните рисом с фасолью, сверху положите сальсу, гуакамоле и шинкованную капусту.</li></ol><p><em>Сверху добавьте шинкованную капусту и острый соус по желанию.</em></p>', CURRENT_TIMESTAMP),
  ('17332e55-bbe0-52f9-a804-bf7377925da3', '10aa3a38-e212-5521-a186-8ac2198ba736', 'en', 'Burrito-stuffed sweet potatoes with black beans, rice, salsa and guacamole', 'Whole baked sweet potatoes filled with cumin rice and black beans, fresh bell pepper and tomato salsa and guacamole.', '<ol><li>Heat the oven to 400°F (200°C) and line a baking dish with parchment. Prick the sweet potatoes with a fork and bake about 45 minutes (5–10 minutes more if larger) until very tender.</li><li>In a saucepan combine the rice, beans, cumin, garlic, oil, tomato paste and salt and add about 300 ml of water. Cover, bring to a boil, reduce and simmer about 40 minutes until the liquid is absorbed. Keep covered and warm.</li><li>For the salsa combine the bell pepper, cherry tomatoes, red onion, lime juice, cilantro and oil and season with salt and pepper.</li><li>For the guacamole mash the avocado with the garlic, lime juice, cilantro and a pinch of salt into a chunky paste.</li><li>Slit each sweet potato lengthwise and open it up. Fill with the rice and beans, then top with salsa, guacamole and shredded cabbage.</li></ol><p><em>Top with shredded cabbage and hot sauce if you like.</em></p>', CURRENT_TIMESTAMP),
  ('e091aa99-9398-536a-afa1-56916717ed9b', '567ef688-7846-58f2-ab9f-ed09ce6bcdd3', 'ru', 'Паста с запечённой брокколи, чесноком и пекорино', 'Паста с брокколи, запечённой с чесноком и оливковым маслом до румяной корочки, и тёртым сыром пекорино.', '<ol><li>Разогрейте духовку до 230 °C. В форме смешайте брокколи, оливковое масло, раздавленный чеснок, соль и перец.</li><li>Запекайте брокколи около 20 минут, на середине перемешав, до румяности и мягкости.</li><li>Тем временем отварите пасту в подсоленной воде до al dente. Перед тем как слить воду, отлейте стакан отвара.</li><li>Смешайте пасту с брокколи, влейте около ½ стакана отвара (больше при необходимости), добавьте пекорино, соль и перец по вкусу.</li></ol><p><em>Хороший способ приучить детей к брокколи. Добавьте щепотку хлопьев чили по вкусу.</em></p>', CURRENT_TIMESTAMP),
  ('23d1d7bf-aeac-5671-9e20-bcd39bee92f2', '567ef688-7846-58f2-ab9f-ed09ce6bcdd3', 'en', 'Pasta with roasted broccoli, garlic and pecorino', 'Pasta tossed with broccoli roasted with garlic and olive oil until browned, and grated Pecorino Romano.', '<ol><li>Heat the oven to 450°F (230°C). In a baking dish toss the broccoli with the olive oil, smashed garlic, salt and pepper.</li><li>Roast about 20 minutes, tossing halfway, until browned and tender.</li><li>Meanwhile cook the pasta in salted water until al dente. Before draining reserve 1 cup of the pasta water.</li><li>Toss the pasta with the broccoli, add about ½ cup of the reserved water (more if needed), the Pecorino Romano, salt and pepper to taste.</li></ol><p><em>A good way to win over picky eaters. Add a pinch of chilli flakes if you like.</em></p>', CURRENT_TIMESTAMP),
  ('8ab24f43-591d-550b-a548-b9d0f193405e', '9a1c13e7-e903-554b-b46e-d4bcb3bea1b7', 'ru', 'Суп с курицей, шиитаке и тремя видами риса', 'Сытный суп из куриных бёдер, моркови, сельдерея, грибов шиитаке, бурого, длиннозёрного и дикого риса с ложкой сметаны.', '<ol><li>В большой кастрюле на среднем огне растопите масло, обжарьте лук 3–4 минуты до мягкости без румянца. Всыпьте муку и готовьте ещё минуту.</li><li>Добавьте бульон, воду, морковь, чеснок, сельдерей, бурый рис и куриные бёдра. Накройте и варите 20 минут.</li><li>Добавьте дикий и длиннозёрный рис и шиитаке, накройте и варите на слабом огне 25 минут, иногда помешивая.</li><li>Выньте курицу, разберите вилками на волокна и верните в суп. Добавьте сметану, при необходимости воды, посолите и поперчите.</li></ol><p><em>При подаче добавьте свежий чёрный перец и немного зелени.</em></p>', CURRENT_TIMESTAMP),
  ('121d3c59-af62-507a-8d28-0c44a5b2dec1', '9a1c13e7-e903-554b-b46e-d4bcb3bea1b7', 'en', 'Chicken, shiitake and wild rice soup', 'A hearty soup of chicken thighs, carrots, celery, shiitake mushrooms and brown, long-grain and wild rice finished with a spoonful of sour cream.', '<ol><li>Melt the butter in a large pot over medium heat and sauté the onion 3–4 minutes until soft but not browned. Add the flour and cook another minute.</li><li>Add the chicken broth, water, carrots, garlic, celery, brown rice and chicken thighs, cover and simmer 20 minutes.</li><li>Add the wild rice and long-grain rice and the mushrooms, cover and simmer on low 25 minutes, stirring occasionally.</li><li>Remove the chicken, shred with two forks and return to the pot. Stir in the sour cream and more water if too thick, then season with salt and pepper.</li></ol><p><em>Finish with fresh black pepper and a few herbs.</em></p>', CURRENT_TIMESTAMP),
  ('cdfdc6eb-30f5-52e6-979c-dc72d3cb73e3', '147ddd90-830d-536b-8f26-b1c1fafef946', 'ru', 'Креветки по-креольски в томатном соусе', 'Креветки в томатном соусе с луком, сладким перцем и сельдереем, с кайенским перцем, каджун-приправой и вустерским соусом.', '<ol><li>В большой сковороде на среднем огне разогрейте масло, обжарьте лук, зелёный перец, сельдерей и чеснок до мягкости.</li><li>Добавьте томаты, томатный соус, кайенский перец, половину каджун-приправы и лавровый лист, доведите до кипения. Накройте, убавьте огонь и варите 20–30 минут.</li><li>Разведите муку водой и вмешайте в соус, прогрейте ещё 5 минут.</li><li>Слегка приправьте креветки оставшейся каджун-приправой и сразу добавьте в соус. Добавьте вустерский и острый соус, перемешайте и готовьте 5–6 минут, пока креветки не станут непрозрачными.</li><li>Выньте лавровый лист, при необходимости досолите, посыпьте зелёным луком и петрушкой.</li></ol><p><em>Подайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('e0cdc58c-c88d-5c05-918f-46931ebbd225', '147ddd90-830d-536b-8f26-b1c1fafef946', 'en', 'Shrimp creole in tomato sauce', 'Shrimp simmered in a tomato sauce with onion, bell pepper and celery, spiced with cayenne, Cajun seasoning and Worcestershire sauce.', '<ol><li>Heat the oil in a large skillet over medium heat and sauté the onion, green pepper, celery and garlic until tender.</li><li>Add the tomatoes, tomato sauce, cayenne, half of the Cajun seasoning and bay leaf and bring to a boil. Cover, reduce to low and simmer 20–30 minutes.</li><li>Make a slurry of the flour and water, stir it into the sauce and cook another 5 minutes.</li><li>Lightly season the shrimp with the remaining Cajun seasoning and add right away. Add the Worcestershire and hot sauce, stir and cook 5–6 minutes until the shrimp are opaque.</li><li>Remove the bay leaf, adjust the salt and sprinkle with green onion and parsley.</li></ol><p><em>Serve over steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('d031ede5-8294-55da-a21b-80c23ad8caaa', '20d67a7a-835d-5cf5-821d-99e3b2e17756', 'ru', 'Куриные окорочка, запечённые с китайской смесью пяти специй', 'Окорочка, замаринованные в соевом соусе с чесноком, шалотом, имбирём и пятью специями, запечённые в духовке с подливанием маринада.', '<ol><li>Измельчите в блендере или мелко порубите ножом чеснок, шалот, имбирь, сахар, соевый соус, пять специй и перец до однородной массы.</li><li>Переложите курицу в пакет или контейнер, залейте маринадом, перемешайте и уберите в холодильник на 6–8 часов или на ночь.</li><li>Разогрейте духовку до 200 °C. Выложите курицу на решётку в противне, застеленном фольгой, и неплотно накройте фольгой.</li><li>Запекайте 30 минут, затем снимите фольгу и допекайте около 45 минут, время от времени поливая маринадом, пока температура внутри не достигнет 74–77 °C.</li></ol><p><em>Подайте с отварным рисом и овощами на пару.</em></p>', CURRENT_TIMESTAMP),
  ('bf2e4a7a-5f11-5aeb-8470-9dd3156a34d1', '20d67a7a-835d-5cf5-821d-99e3b2e17756', 'en', 'Five-spice soy roasted chicken legs', 'Chicken leg quarters marinated in soy sauce with garlic, shallot, ginger and Chinese five-spice, then roasted and basted in the oven.', '<ol><li>Blend (or finely chop) the garlic, shallot, ginger, sugar, soy sauce, five-spice and pepper into a smooth marinade.</li><li>Put the chicken in a zip-top bag or container, pour in the marinade, toss to coat and refrigerate 6–8 hours or overnight.</li><li>Heat the oven to 400°F (200°C). Set the chicken on a rack in a foil-lined roasting pan and tent loosely with foil.</li><li>Roast 30 minutes, remove the foil and keep cooking about 45 minutes longer, basting occasionally, until the internal temperature reaches 165–170°F (74–77°C).</li></ol><p><em>Serve with steamed rice and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('ed717c1e-4a23-58ca-b27d-84b0f23bc94b', '39501b43-1f98-5386-8810-b216cf9a216a', 'ru', 'Салат с куриными шашлычками, фетой и свежими овощами', 'Маринованные кубики куриной грудки на шпажках на подушке из салата с помидорами, огурцами, перцем, оливками, красным луком, фетой и зеленью.', '<ol><li>Смешайте кубики курицы с лимонным соком, орегано, чесноком, солью и перцем и оставьте мариноваться на 2–3 часа или на ночь в холодильнике.</li><li>Смешайте огурец, помидор, перец, красный лук, оливки, уксус, лимонный сок, масло, укроп, петрушку, орегано, соль и перец и уберите в холодильник, чтобы вкусы соединились.</li><li>Нанижите курицу на 4 шпажки (деревянные замочите на 30 минут) и жарьте на разогретом гриле 10–12 минут до готовности.</li><li>Разложите салат по тарелкам, сверху выложите овощную смесь, тёртую фету и куриные шашлычки. Подайте с дольками лимона.</li></ol><p><em>Подайте с дольками лимона.</em></p>', CURRENT_TIMESTAMP),
  ('0b4be25c-ed75-555a-9c36-670d4effbe36', '39501b43-1f98-5386-8810-b216cf9a216a', 'en', 'Mediterranean chicken kebab salad with feta', 'Marinated chicken breast skewers over lettuce with tomatoes, cucumber, bell pepper, olives, red onion, feta and herbs.', '<ol><li>Toss the chicken cubes with the lemon juice, oregano, garlic, salt and pepper and marinate in the fridge 2–3 hours or overnight.</li><li>Combine the cucumber, tomato, pepper, red onion, olives, vinegar, lemon juice, oil, dill, parsley, oregano, salt and pepper and chill so the flavours meld.</li><li>Thread the chicken onto 4 skewers (soak wooden ones 30 minutes) and cook on a hot grill 10–12 minutes until cooked through.</li><li>Divide the lettuce between plates and top with the tomato-cucumber mixture, grated feta and the chicken skewers. Serve with lemon wedges.</li></ol><p><em>Serve with lemon wedges.</em></p>', CURRENT_TIMESTAMP),
  ('ff5e6432-6d60-5752-9b0d-9ce7e03b3978', '77c87055-bd59-5f36-a2ac-e17a26960f9a', 'ru', 'Курица, запечённая с куркумой, свёклой и луком-пореем', 'Куриные бёдра и голени с куркумой и имбирём на подушке из золотистой свёклы и порея, запечённые в белом вине и лимонном соке.', '<ol><li>Разогрейте духовку до 220 °C. Разрежьте порей вдоль, промойте, раздвигая слои, и нарежьте тонкими полукольцами.</li><li>Отделите от свёклы ботву, ополосните и грубо нарежьте. Свёклу разрежьте пополам и каждую половину на 4 дольки.</li><li>В большой миске смешайте порей, свёклу и ботву с чесноком, 1 ч. л. куркумы, имбирём, солью, лимонным соком и маслом. Выложите ровным слоем в форму 23×33 см.</li><li>В той же миске обваляйте курицу в оставшейся куркуме и остатках смеси, уложите на овощи. Полейте оставшимся маринадом, влейте вино вокруг.</li><li>Запекайте без крышки около часа, пока курица не станет мягкой, а свёкла не будет готова.</li></ol><p><em>Хорошо сочетается с рисом или хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('898b217c-ebb2-5e76-a90f-8c9cdf0a27ac', '77c87055-bd59-5f36-a2ac-e17a26960f9a', 'en', 'Turmeric braised chicken with golden beets and leeks', 'Chicken thighs and drumsticks seasoned with turmeric and ginger on a bed of golden beets and leeks, baked in white wine and lemon juice.', '<ol><li>Heat the oven to 425°F (220°C). Halve the leeks lengthwise, rinse well fanning out the layers and slice into thin half-moons.</li><li>Remove the beet greens, rinse and coarsely chop. Halve the beets and cut each half into four wedges.</li><li>In a large bowl toss the leeks, beets and greens with the garlic, 1 tsp of the turmeric, ginger, salt, lemon juice and olive oil. Spread in an even layer in a 9x13-inch baking dish.</li><li>In the same bowl coat the chicken in the remaining turmeric and marinade, nestle it among the vegetables, drizzle with any marinade left and pour the wine around the sides.</li><li>Roast uncovered about 1 hour until the chicken is fork-tender and the beets are soft.</li></ol><p><em>Serve with rice or bread to soak up the juices.</em></p>', CURRENT_TIMESTAMP),
  ('37226911-c21e-5f50-a40b-9dbddc902f12', '93e8128f-a898-560d-bb1f-3c06d31a598d', 'ru', 'Мексиканский рис с фасолью, кукурузой и лаймом', 'Тёплый рис с чёрной фасолью, кукурузой, помидором, зелёным луком, кинзой и лаймовым соком. Отличный гарнир из остатков риса.', '<ol><li>Разогрейте варёный рис, а также чёрную фасоль и кукурузу (на плите или в микроволновке).</li><li>В большой миске смешайте горячий рис, кукурузу, фасоль, нарезанный помидор, зелёный лук, кинзу, лаймовый сок и соль по вкусу. Перемешайте и подавайте.</li></ol><p><em>Подайте к курице, рыбе или в тортилье с овощами.</em></p>', CURRENT_TIMESTAMP),
  ('57522019-e779-5e56-9197-5fc4e55ee429', '93e8128f-a898-560d-bb1f-3c06d31a598d', 'en', 'Fiesta lime rice with black beans and corn', 'Warm rice with black beans, corn, tomato, green onion, cilantro and lime juice. A colourful side that makes good use of leftover rice.', '<ol><li>Heat the cooked rice, the black beans and the corn (on the stove or in the microwave).</li><li>In a large bowl combine the hot rice, corn, beans, diced tomato, green onion, cilantro, lime juice and salt to taste. Toss and serve.</li></ol><p><em>Serve with chicken or fish, or stuff into tortillas.</em></p>', CURRENT_TIMESTAMP),
  ('e53171fd-50c7-5390-ae6d-5876e61c75d2', '943b56e7-6a2b-5194-af38-89172ee8dc20', 'ru', 'Куриный шницель в сухарях с лимоном', 'Тонко отбитые куриные грудки в муке, яйце и сухарях со специями, обжаренные до золотистой хрустящей корочки за несколько минут.', '<ol><li>Каждую грудку по очереди положите в пакет и отбейте молотком или тяжёлой сковородой до толщины около 3 мм.</li><li>Смешайте чесночный порошок, паприку и орегано. Посолите и поперчите курицу и посыпьте смесью специй.</li><li>Приготовьте три миски: мука, взбитые яйца, сухари. Обваляйте каждую грудку в муке, затем в яйце и сухарях.</li><li>Разогрейте в большой сковороде масло на средне-сильном огне до лёгкого шимера. Жарьте шницели порциями по 3–4 минуты с каждой стороны до золотистого цвета. Выложите на бумажные полотенца.</li><li>Перед подачей сбрызните лимонным соком и подавайте с дольками лимона.</li></ol><p><em>Сбрызните лимонным соком и подавайте с картофелем или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e296f9dd-3cd1-5f69-9999-6af22e4b0478', '943b56e7-6a2b-5194-af38-89172ee8dc20', 'en', 'Crispy chicken schnitzel with lemon', 'Thinly pounded chicken breasts coated in flour, egg and seasoned breadcrumbs and fried until golden and crisp in just a few minutes.', '<ol><li>Put each chicken breast in a zip bag, one at a time, and pound with a mallet or heavy skillet to about 3 mm thick.</li><li>Mix the garlic powder, paprika and oregano. Season the chicken with salt and pepper, then sprinkle with the spice mix.</li><li>Set up three bowls: flour, beaten eggs, breadcrumbs. Coat each breast in flour, then egg, then breadcrumbs.</li><li>Heat the olive oil in a large skillet over medium-high until shimmering. Fry the schnitzels in batches 3-4 minutes per side until golden brown. Drain on paper towels.</li><li>Just before serving squeeze lemon juice over the top and serve with lemon wedges.</li></ol><p><em>Squeeze lemon over the top and serve with potatoes or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('dc2a5cd5-11a3-59d4-ae33-2552a07066ba', 'c4cf9d37-38b5-5b7d-a15a-d6712600ce1c', 'ru', 'Кофта-кебаб из говядины и баранины на шпажках', 'Рубленое мясо с петрушкой, луком, чесноком и ближневосточными специями, сформированное на шпажках и обжаренное на гриле. Получается ароматным и сочным.', '<ol><li>Замочите 10 деревянных шпажек в воде на 30–60 минут (металлические замачивать не нужно). Смажьте решётку маслом и разогрейте гриль до средне-сильного огня.</li><li>Поджарьте ломтик хлеба до румяности и размочите в воде, затем отожмите. Измельчите в комбайне лук, чеснок и петрушку.</li><li>Добавьте говядину, баранину, отжатый хлеб и специи и обрабатывайте до однородной пастообразной массы.</li><li>Разделите фарш на 10 равных частей и плотно обмотайте каждую вокруг шпажки, придав форму ровной колбаски толщиной около 2,5 см. Выложите на противень с пергаментом.</li><li>Жарьте на гриле на средне-сильном огне 4 минуты, переверните и жарьте ещё 3–4 минуты, пока внутри не будет 71 °C.</li><li>Сразу подавайте с питой, тахини и нарезанными овощами.</li></ol><p><em>Подавайте в пите с тахини, помидорами и луком (2 шпажки на порцию).</em></p>', CURRENT_TIMESTAMP),
  ('dd3d27cb-1732-5f9e-b7ae-dea541f9eeb4', 'c4cf9d37-38b5-5b7d-a15a-d6712600ce1c', 'en', 'Beef and lamb kofta kebab skewers', 'Ground beef and lamb with parsley, onion, garlic and Middle Eastern spices, shaped onto skewers and grilled until juicy and fragrant.', '<ol><li>Soak 10 wooden skewers in water for 30-60 minutes (skip for metal skewers). Oil the grill grates and preheat to medium-high.</li><li>Toast the bread slice until browned, soak it in water and squeeze it dry. Pulse the onion, garlic and parsley in a food processor until finely chopped.</li><li>Add the beef, lamb, squeezed bread and spices and process until you have a smooth, pasty mixture.</li><li>Divide the mixture into 10 equal portions and press each firmly around a skewer into an even log about 1 inch thick. Place on a parchment-lined tray.</li><li>Grill on medium-high 4 minutes, turn and grill another 3-4 minutes until the inside reaches 71°C (160°F).</li><li>Serve immediately with pita, tahini and sliced vegetables.</li></ol><p><em>Serve in pita with tahini, tomatoes and onion (2 skewers per serving).</em></p>', CURRENT_TIMESTAMP),
  ('8fe597a8-2431-539a-ae4e-1ebada4a31e9', '8818f3b5-57f2-5e91-a96e-38ee1c9c4be1', 'ru', 'Курица с рисом и чоризо в одной сковороде (арроз кон поло)', 'Бёдра и голени, обжаренные с чоризо, перцем, луком и томатами и доведённые вместе с рисом на одной сковороде до мягкости.', '<ol><li>Тщательно промойте рис, залейте водой и замочите на 15 минут, затем слейте воду.</li><li>Смешайте копчёную паприку, чесночный порошок, соль, чёрный перец и кайенский перец. Обсушите курицу и натрите смесью сверху и под кожей.</li><li>В глубокой сковороде с крышкой разогрейте оливковое масло на средне-сильном огне и хорошо обжарьте курицу с обеих сторон. Отложите на тарелку.</li><li>В той же сковороде обжаривайте чоризо 10 минут, помешивая, до румяности. Добавьте перец, лук и чеснок и готовьте 5 минут на среднем огне.</li><li>Добавьте помидор, томатную пасту и бульон, верните курицу в сковороду. Доведите до кипения, убавьте огонь до среднего, накройте и готовьте 15–20 минут.</li><li>Откройте крышку, переложите курицу на тарелку и всыпьте рис в жидкость. Варите без крышки на сильном огне 1–2 минуты, затем положите курицу сверху, убавьте огонь до слабого, накройте и готовьте ещё 20 минут до готовности риса.</li><li>Выключите огонь и оставьте блюдо под крышкой на 10 минут, затем подавайте горячим.</li></ol><p><em>Дайте блюду постоять под крышкой 10 минут и подавайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('b32f5244-ed8d-599b-b564-d7b047b46d76', '8818f3b5-57f2-5e91-a96e-38ee1c9c4be1', 'en', 'One-pan Spanish chicken and rice with chorizo (arroz con pollo)', 'Chicken thighs and drumsticks browned with chorizo, bell pepper, onion and tomato, then finished with rice in the same pan.', '<ol><li>Rinse the rice well, cover with water and soak 15 minutes, then drain.</li><li>Mix the smoked paprika, garlic powder, salt, black pepper and cayenne. Pat the chicken dry and rub the mix over and under the skin.</li><li>In a covered deep skillet or braiser, heat the olive oil over medium-high and brown the chicken deeply on both sides. Set aside.</li><li>In the same pan cook the chorizo 10 minutes, stirring, until nicely browned. Add the bell pepper, onion and garlic and cook 5 minutes over medium heat.</li><li>Add the tomato, tomato paste and broth and return the chicken to the pan. Bring to a boil, lower to medium, cover and cook 15-20 minutes.</li><li>Uncover, move the chicken to a plate and stir the rice into the liquid. Cook uncovered on high 1-2 minutes, place the chicken on top, turn the heat to low, cover and cook 20 more minutes until the rice is done.</li><li>Turn off the heat and let it stand covered for 10 minutes, then serve hot.</li></ol><p><em>Let it rest covered for 10 minutes and serve with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('0adce40a-6ec1-5fdb-bb17-d4e81ffe6b9a', 'be5cf93c-6c9b-5f56-8086-5cdc2bf21044', 'ru', 'Курица с орзо, перцем и томатами по-гречески в одной кастрюле', 'Бёдра в пряной обмазке, уложенные на орзо с луком, перцем и томатами и запечённые, пока паста не впитает почти весь соус.', '<ol><li>Разогрейте духовку до 175 °C.</li><li>В большой миске смешайте 2 ч. л. орегано, 1 ч. л. паприки, кориандр, 1 ч. л. соли и перец. Обсушите курицу, обваляйте в смеси, добавьте лимонный сок и немного масла и оставьте на несколько минут.</li><li>В жаропрочной кастрюле на 5 л разогрейте 2 ст. л. масла на средне-сильном огне и обжарьте курицу с обеих сторон 8–10 минут (готовить до конца не нужно). Переложите на тарелку.</li><li>В той же кастрюле обжарьте кольца перца по паре минут с каждой стороны и переложите к курице.</li><li>Добавьте при необходимости ещё масла, обжарьте лук 5 минут до мягкости, затем чеснок 30 секунд. Влейте томаты с соком и бульон, добавьте орегано, паприку, соль и перец, доведите до кипения и всыпьте орзо.</li><li>Уложите курицу на орзо, сверху положите кольца перца и запекайте без крышки 20–25 минут, пока орзо не сварится и не впитает жидкость. Накройте крышкой и оставьте на 5 минут.</li><li>Сбрызните оливковым маслом и посыпьте петрушкой и фетой, если хотите.</li></ol><p><em>Посыпьте петрушкой и крошёной фетой.</em></p>', CURRENT_TIMESTAMP),
  ('ca453ab5-20d6-56ff-b662-cefe6ce63906', 'be5cf93c-6c9b-5f56-8086-5cdc2bf21044', 'en', 'Greek one-pan chicken with orzo, peppers and tomatoes', 'Spiced chicken thighs set on a bed of orzo cooked with onions, peppers and tomatoes and baked until the pasta absorbs nearly all the sauce.', '<ol><li>Heat the oven to 175°C (350°F).</li><li>In a large bowl mix 2 tsp oregano, 1 tsp paprika, the coriander, 1 tsp salt and the pepper. Pat the chicken dry, toss it in the mix with the lemon juice and a drizzle of oil and set aside a few minutes.</li><li>In a 5-quart oven-safe pot heat 2 tbsp oil over medium-high and brown the chicken on both sides, 8-10 minutes in total (it doesn''t need to cook through). Move to a plate.</li><li>In the same pot sear the pepper rounds on both sides and set them with the chicken.</li><li>Add more oil if needed, soften the onion 5 minutes, then the garlic 30 seconds. Add the tomatoes with their juice, the broth, oregano, paprika, salt and pepper, bring to a boil and stir in the orzo.</li><li>Nestle the chicken into the orzo mixture, top with the pepper slices and bake uncovered 20-25 minutes until the orzo is cooked and has absorbed the liquid. Cover and rest 5 minutes.</li><li>Drizzle with olive oil and garnish with parsley and feta if you like.</li></ol><p><em>Garnish with parsley and crumbled feta.</em></p>', CURRENT_TIMESTAMP),
  ('7339613d-5a73-5113-8bd8-298dd5c5ae1e', 'f154406d-ae02-527c-a986-cc5186df993b', 'ru', 'Средиземноморское рагу из белой фасоли с морковью и томатами', 'Постное густое блюдо из белой фасоли, моркови и томатов с кориандром, зирой и паприкой. В конце добавляют лимонный сок, петрушку и оливковое масло.', '<ol><li>В большой кастрюле с толстым дном разогрейте 2–3 ст. л. масла на средне-сильном огне. Обжарьте лук 3–5 минут до золотистого цвета.</li><li>Добавьте чеснок и морковь, щедро посолите и поперчите и готовьте, часто помешивая, около 5 минут до мягкости моркови.</li><li>Добавьте фасоль и размятые томаты, кориандр, паприку, зиру и хлопья перца, ещё масла, соль и перец.</li><li>Кипятите около 5 минут, затем убавьте огонь до слабого и варите, не до конца закрыв крышкой, около 15 минут, пока фасоль не станет мягкой, а соус слегка не загустеет.</li><li>Добавьте лимонный сок и петрушку, разлейте по тарелкам и сбрызните оливковым маслом.</li></ol><p><em>Сбрызните оливковым маслом и подайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('4044b5f1-d30b-5ead-9936-f71e3437275f', 'f154406d-ae02-527c-a986-cc5186df993b', 'en', 'Mediterranean white bean stew with carrots and tomatoes', 'A thick vegan one-pot stew of white beans, carrots and tomatoes seasoned with coriander, cumin and paprika, finished with lemon, parsley and olive oil.', '<ol><li>In a large Dutch oven warm 2-3 tbsp olive oil over medium-high heat and cook the onion 3-5 minutes until golden.</li><li>Add the garlic and carrots, season generously with salt and pepper and cook, stirring often, about 5 minutes until the carrots soften.</li><li>Add the beans, crushed tomatoes, coriander, paprika, cumin and pepper flakes, another drizzle of oil and more salt and pepper.</li><li>Boil about 5 minutes, then reduce to low and simmer partially covered about 15 minutes until the beans soften and the sauce thickens slightly.</li><li>Stir in the lemon juice and parsley, ladle into bowls and finish with a drizzle of olive oil.</li></ol><p><em>Drizzle with olive oil and serve with bread.</em></p>', CURRENT_TIMESTAMP),
  ('7a2de56e-be95-5c99-b05b-d42b6214ac39', '4d966c7b-1bc6-5061-b5aa-d5fe02f492d8', 'ru', 'Греческий лимонный рис с орзо и укропом', 'Рассыпчатый рис басмати с поджаренной пастой орзо, луком и чесноком, сваренный в бульоне с лимонным соком и заправленный петрушкой, укропом и цедрой.', '<ol><li>Промойте рис в мелком сите до прозрачной воды, затем замочите в свежей воде на 15–20 минут и слейте.</li><li>В большой кастрюле на средне-сильном огне разогрейте 3 ст. л. масла и обжарьте лук 3–4 минуты до прозрачности. Добавьте чеснок и орзо и помешивайте до лёгкой золотистости, затем всыпьте рис.</li><li>Влейте лимонный сок и бульон, доведите до кипения, убавьте огонь до слабого, накройте крышкой и варите 15–20 минут, пока жидкость не впитается, а рис не станет мягким, но не слипшимся.</li><li>Снимите с огня и не открывая крышку оставьте на 10 минут.</li><li>Перемешайте с петрушкой, укропом и лимонной цедрой и подавайте.</li></ol><p><em>Хорош с курицей, рыбой или запечёнными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('2f78c023-2ddc-57b2-b542-7838158814a2', '4d966c7b-1bc6-5061-b5aa-d5fe02f492d8', 'en', 'Greek lemon rice with orzo and dill', 'Fluffy basmati rice with toasted orzo, onion and garlic cooked in broth and lemon juice, finished with parsley, dill and lemon zest.', '<ol><li>Rinse the rice in a fine sieve until the water runs clear, then soak it in fresh water for 15-20 minutes and drain.</li><li>In a large saucepan heat 3 tbsp olive oil over medium-high and cook the onion 3-4 minutes until translucent. Add the garlic and orzo and stir until the orzo takes on some color, then add the rice.</li><li>Pour in the lemon juice and broth and bring to a rolling boil, then reduce to low, cover and cook 15-20 minutes until the liquid is absorbed and the rice is tender but not sticky.</li><li>Remove from the heat and leave covered and undisturbed for 10 minutes.</li><li>Stir in the parsley, dill and lemon zest and serve.</li></ol><p><em>Great with chicken, fish or roasted vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('e13784a4-4b77-5786-8057-6ddaccf9d1f6', '73602e04-0499-5b1c-98e1-fae06fa8f97b', 'ru', 'Марокканский овощной тажин с нутом и курагой', 'Постное рагу из картофеля, моркови, батата, нута, кураги и томатов с тёплыми специями. В конце добавляют лимон, петрушку и оливковое масло.', '<ol><li>В большой кастрюле с толстым дном разогрейте масло на среднем огне. Добавьте лук, прибавьте огонь и обжаривайте 5 минут, помешивая.</li><li>Добавьте чеснок, морковь, картофель и батат, посолите и приправьте харисой или раc-эль-ханутом, кориандром, корицей и куркумой. Готовьте на средне-сильном огне 5–7 минут, помешивая.</li><li>Добавьте томаты, курагу и бульон, слегка посолите. Кипятите 10 минут на среднем огне, затем убавьте огонь, накройте и тушите 20–25 минут до мягкости овощей.</li><li>Добавьте нут и прогревайте на слабом огне ещё 5 минут.</li><li>Добавьте лимонный сок и петрушку, попробуйте и при желании досолите. Разложите по тарелкам и щедро сбрызните оливковым маслом.</li></ol><p><em>Подавайте с хлебом, кускусом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('e4a09e85-85db-5542-a16c-be7c01ba0592', '73602e04-0499-5b1c-98e1-fae06fa8f97b', 'en', 'Moroccan vegetable tagine with chickpeas and apricots', 'A vegan one-pot stew of potatoes, carrots, sweet potato, chickpeas, dried apricots and tomatoes with warm spices, finished with lemon, parsley and olive oil.', '<ol><li>In a large heavy pot heat the olive oil over medium. Add the onions, raise the heat to medium-high and sauté 5 minutes, tossing regularly.</li><li>Add the garlic, carrots, potatoes and sweet potato, season with salt, spice blend, coriander, cinnamon and turmeric and cook over medium-high 5-7 minutes, stirring regularly.</li><li>Add the tomatoes, apricots and broth with a little more salt. Cook 10 minutes at medium-high, then reduce, cover and simmer 20-25 minutes until the vegetables are tender.</li><li>Stir in the chickpeas and warm through over low heat for 5 more minutes.</li><li>Stir in the lemon juice and parsley, adjust the seasoning and serve drizzled generously with olive oil.</li></ol><p><em>Serve with bread, couscous or rice.</em></p>', CURRENT_TIMESTAMP),
  ('5cda99cf-2983-5f85-a7e6-1cecc853d47a', '0a5e94f1-55e5-515f-af3e-dc12a7d13261', 'ru', 'Куриные отбивные с грибами в чесночном соусе на сковороде', 'Быстрые куриные эскалопы с пряностями под лёгким соусом из шампиньонов, бульона, чеснока и капли масла, без сливок. Готовятся за 20 минут.', '<ol><li>Разрежьте грудки вдоль на тонкие эскалопы, обсушите, посолите и поперчите. Смешайте орегано, паприку и кориандр и натрите смесью куриные ломтики с обеих сторон.</li><li>Разогрейте в большой сковороде масло на средне-сильном огне. Жарьте курицу порциями, чтобы не переполнять сковороду, 3–4 минуты до золотистого цвета, переверните и жарьте ещё около 3 минут до 74 °C внутри. Держите готовые кусочки в тепле.</li><li>В той же сковороде растопите масло, добавьте грибы и жарьте около 5 минут до мягкости и румяности. Добавьте бульон, зелёный лук и чеснок, посолите и поперчите. Доведите до кипения, соскребая румяные частицы со дна, и уварите до лёгкого загустения.</li><li>Уложите курицу в соус, польте грибами и прогрейте. Снимите с огня, посыпьте петрушкой и подавайте.</li></ol><p><em>Подавайте с рисом, картофелем или макаронами.</em></p>', CURRENT_TIMESTAMP),
  ('3ab1779a-d025-5f62-8ed5-c84e42a22cd2', '0a5e94f1-55e5-515f-af3e-dc12a7d13261', 'en', '20-minute skillet mushroom chicken in garlic sauce', 'Quick spiced chicken cutlets coated in a light pan sauce of mushrooms, broth, garlic and a touch of butter, with no cream. Ready in 20 minutes.', '<ol><li>Slice the chicken breasts horizontally into thinner cutlets, pat dry and season with salt and pepper. Mix the oregano, paprika and coriander and rub over both sides.</li><li>Heat the olive oil in a large skillet over medium-high. Cook the chicken in batches 3-4 minutes until golden, flip and cook about 3 minutes more until 74°C (165°F) inside. Keep warm.</li><li>In the same skillet add the butter and mushrooms and cook about 5 minutes until soft and browning. Add the broth, green onions and garlic and season. Bring to a boil, scraping up the browned bits, and cook until slightly thickened.</li><li>Nestle the chicken into the sauce, spoon the mushrooms over and warm through. Remove from the heat, garnish with parsley and serve.</li></ol><p><em>Serve with rice, potatoes or pasta.</em></p>', CURRENT_TIMESTAMP),
  ('dc8c5ef0-9951-5911-9483-bad3a78bf82e', 'cb455516-7cd5-5e45-953a-7c28dd00ef29', 'ru', 'Запеканка из кабачков с говяжьим фаршем и томатным соусом', 'Слои кабачков, моркови и лука под мясным соусом с томатами, душистым перцем, паприкой и мускатом, запечённые до мягкости.', '<ol><li>Разогрейте духовку до 190 °C.</li><li>В кастрюле разогрейте масло на среднем огне, обжарьте половину лука (мелко нарезанную) и чеснок до мягкости без румяности. Вторую половину лука нарежьте кольцами и отложите.</li><li>Добавьте фарш, разделяя на мелкие кусочки, посолите и поперчите. Прибавьте огонь и обжаривайте до полной румяности, затем слейте лишний жир.</li><li>Добавьте душистый перец, паприку и мускатный орех, затем томаты с соком, томатную пасту и воду. Доведите до кипения и варите 7–10 минут на слабом огне.</li><li>Выложите в форму кружки кабачков и моркови и кольца лука, равномерно покройте мясным соусом.</li><li>Плотно накройте фольгой и запекайте около 40 минут до мягкости овощей. Снимите фольгу и на несколько минут включите гриль, следя за блюдом.</li><li>Посыпьте петрушкой, разложите по тарелкам и сбрызните оливковым маслом.</li></ol><p><em>Подавайте с рисом или хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('438356ea-7b43-5175-b65d-d24d90c68103', 'cb455516-7cd5-5e45-953a-7c28dd00ef29', 'en', 'Zucchini and ground beef casserole with tomato sauce', 'Layers of zucchini, carrot and onion under a meat sauce with tomatoes, allspice, paprika and nutmeg, baked until tender.', '<ol><li>Heat the oven to 190°C (375°F).</li><li>In a saucepan heat the oil over medium and soften the chopped half of the onion with the garlic without browning. Reserve the other half, sliced into rings.</li><li>Add the ground beef, breaking it up, and season with salt and pepper. Raise the heat and cook until fully browned, then drain excess fat.</li><li>Stir in the allspice, paprika and nutmeg, then the tomatoes with their juice, tomato paste and water. Bring to a boil and simmer 7-10 minutes.</li><li>Arrange the zucchini and carrot rounds and onion rings in a casserole dish and spread the meat sauce evenly over them.</li><li>Cover tightly with foil and bake about 40 minutes until the vegetables are tender. Remove the foil and broil a few minutes, watching closely.</li><li>Garnish with parsley, spoon into bowls and drizzle with olive oil.</li></ol><p><em>Serve with rice or crusty bread to mop up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('7f312d2f-7524-50bf-b1a2-efdc3886ceb4', 'f3be03a6-6368-5705-9d63-17c687ed0e08', 'ru', 'Греческое рагу из баклажанов с нутом и томатами', 'Баклажаны, нут и томаты, тушёные с луком, перцем, чесноком и тёплыми специями до бархатистой мягкости. Постное блюдо, вкусное горячим и комнатной температуры.', '<ol><li>Разогрейте духовку до 200 °C. Выложите кубики баклажана в дуршлаг, посыпьте солью и оставьте на 20 минут. Промойте и тщательно обсушите.</li><li>В жаропрочной кастрюле на сильном огне разогрейте масло, добавьте лук, зелёный перец и морковь и готовьте 2–3 минуты, часто помешивая.</li><li>Добавьте чеснок, лавровый лист, паприку, кориандр, орегано, корицу, куркуму, перец и щепотку соли и обжаривайте минуту до аромата.</li><li>Добавьте баклажаны, томаты, нут и жидкость из банок, перемешайте.</li><li>Доведите до кипения и варите около 10 минут, часто помешивая.</li><li>Накройте крышкой и поставьте в духовку примерно на 45 минут, пока баклажаны не станут совсем мягкими. Если рагу сухое, добавляйте по ½ стакана воды.</li><li>Щедро сбрызните оливковым маслом, посыпьте петрушкой или мятой и подавайте горячим или тёплым.</li></ol><p><em>Сбрызните оливковым маслом, посыпьте петрушкой или мятой, подайте с хлебом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('d76fe22e-e73d-5ccc-ac5b-4c8d159f1927', 'f3be03a6-6368-5705-9d63-17c687ed0e08', 'en', 'Greek braised eggplant and chickpea stew', 'Eggplant, chickpeas and tomatoes braised with onion, pepper, garlic and warm spices until velvety. A vegan main or side, good hot or at room temperature.', '<ol><li>Heat the oven to 200°C (400°F). Put the eggplant cubes in a colander, sprinkle with salt and leave 20 minutes. Rinse and pat thoroughly dry.</li><li>In an oven-safe braiser or Dutch oven heat the oil over medium-high, add the onion, green pepper and carrot and cook 2-3 minutes, stirring regularly.</li><li>Stir in the garlic, bay leaves, paprika, coriander, oregano, cinnamon, turmeric, pepper and a dash of salt and cook 1 minute until fragrant.</li><li>Add the eggplant, tomatoes, chickpeas and the reserved canning liquid and stir.</li><li>Bring to a rolling boil and cook about 10 minutes, stirring often.</li><li>Cover and transfer to the oven for about 45 minutes until the eggplant is very tender. If it looks dry, stir in ½ cup of water at a time.</li><li>Drizzle generously with olive oil, garnish with parsley or mint and serve hot or at room temperature.</li></ol><p><em>Drizzle with olive oil, garnish with parsley or mint and serve with bread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('422181aa-407f-5320-853d-8a585f563bea', '851db27c-005b-58dc-95c9-fa74f8173ba8', 'ru', 'Курица с куркумой, фенхелем и апельсинами в духовке', 'Куриные окорочка в цитрусовом маринаде с куркумой, кориандром и паприкой, запечённые на подушке из фенхеля, лука и апельсинов.', '<ol><li>Смешайте в большой миске ингредиенты маринада. В маленькой миске смешайте специи с солью и перцем и половину добавьте в маринад. Обсушите курицу и натрите оставшейся смесью специй, подняв кожу и положив часть специй под неё.</li><li>Добавьте курицу в маринад вместе с фенхелем, луком, апельсинами и лаймом, перемешайте, накройте и уберите в холодильник на 1–2 часа. Если нет времени, просто оставьте при комнатной температуре, пока греется духовка.</li><li>Разогрейте духовку до 245 °C. Переложите всё содержимое миски в большой противень в один слой, кожей курицы вверх. Посыпьте солью и при желании коричневым сахаром.</li><li>Запекайте 40–45 минут, пока курица не прогреется до 74 °C внутри, а кожа не зарумянится.</li></ol><p><em>Подайте с рисом или другой крупой, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('e02fbb86-1323-5c1b-a0e3-b24a46160d04', '851db27c-005b-58dc-95c9-fa74f8173ba8', 'en', 'Turmeric citrus roast chicken with fennel and orange', 'Chicken leg quarters in a citrus marinade with turmeric, coriander and paprika, roasted over fennel, onion and orange slices.', '<ol><li>Mix the marinade ingredients in a large bowl. In a small bowl mix the spices with salt and pepper and stir about half into the marinade. Pat the chicken dry and rub with the remaining spice mix, lifting the skin to season underneath.</li><li>Add the chicken to the marinade with the fennel, onion, oranges and lime, toss, cover and refrigerate 1–2 hours. If short on time, let it sit at room temperature while the oven heats.</li><li>Heat the oven to 475°F (245°C). Transfer everything from the bowl to a large baking pan in one layer, chicken skin side up. Sprinkle with a little salt and, if you like, more brown sugar.</li><li>Roast 40–45 minutes until the chicken reaches 165°F (74°C) and the skin is nicely browned.</li></ol><p><em>Serve with rice or another grain to soak up the pan juices.</em></p>', CURRENT_TIMESTAMP),
  ('dbdadfa4-b6f4-59dc-8915-eca660c441e8', '72e8f297-4009-57fa-bb4d-44600d2d958a', 'ru', 'Палтус с зелёной фасолью и черри на одном противне', 'Кусочки палтуса, стручковая фасоль, помидоры черри и лук, запечённые в лимонно-чесночном соусе с оливковым маслом, укропом и орегано.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>В большой миске взбейте цедру и сок лимонов, оливковое масло, чеснок, укроп, соль, перец, орегано и кориандр. Добавьте стручковую фасоль, помидоры и лук, перемешайте и выложите овощи шумовкой на одну половину противня в один слой.</li><li>В оставшийся соус добавьте полоски палтуса, перемешайте, выложите на вторую половину противня и полейте остатками соуса. Слегка посыпьте солью.</li><li>Запекайте 15 минут, затем переставьте противень на верхнюю полку и на 3 минуты включите гриль, следя, чтобы помидоры лопнули, но не подгорели.</li></ol><p><em>Хорош с ячменём или булгуром, чтобы впитать соус. Подойдёт и треска, пикша.</em></p>', CURRENT_TIMESTAMP),
  ('b7ec6eaf-4a9e-5dc8-90c1-e1b0546948f3', '72e8f297-4009-57fa-bb4d-44600d2d958a', 'en', 'One-pan baked halibut with green beans and cherry tomatoes', 'Halibut pieces, green beans, cherry tomatoes and onion baked in a lemon, garlic, olive oil, dill and oregano sauce.', '<ol><li>Heat the oven to 425°F (220°C).</li><li>In a large bowl whisk the lemon zest and juice, olive oil, garlic, dill, salt, pepper, oregano and coriander. Add the green beans, tomatoes and onion, toss, and lift the vegetables with a slotted spoon onto one half of a large baking sheet in a single layer.</li><li>Add the halibut strips to the remaining sauce, toss, place on the other half of the sheet and pour the rest of the sauce on top. Sprinkle lightly with salt.</li><li>Bake 15 minutes, then move to the top rack and broil about 3 minutes, watching closely until the tomatoes begin to pop.</li></ol><p><em>Serve over barley or bulgur to soak up the sauce. Cod or haddock also work.</em></p>', CURRENT_TIMESTAMP),
  ('2283d69f-7308-5b32-b992-6dff74a2c16e', '9b2a2d60-e379-5ae6-93af-180a748167f3', 'ru', 'Боул с киноа, курицей в ливанских специях, халуми и огуречным салатом', 'Киноа, запечённые куриные бёдра с ливанской смесью семи специй, тёртый халуми, салат из огурцов и черри с йогуртом, кедровые орехи и зелень.', '<ol><li>Разогрейте духовку до 200 °C и застелите противень пергаментом.</li><li>Огурцы слегка раздавите боковой стороной ножа, разломайте на куски и переложите в дуршлаг. Добавьте половинки черри, посолите и оставьте стекать на 30 минут.</li><li>Перемешайте курицу с ливанской смесью специй, 1 ч. л. соли и ложкой оливкового масла, выложите на противень и запекайте около 20 минут до 74 °C внутри. Оставьте на 10 минут, затем нарежьте кусочками.</li><li>Промойте киноа до прозрачной воды, залейте водой с солью, доведите до кипения, убавьте огонь до минимума и варите под крышкой около 15 минут. Выключите и оставьте на 10 минут.</li><li>Обжарьте кедровые орехи с чайной ложкой масла 2–3 минуты до золотистого цвета. Смешайте стёкшие огурцы и помидоры с йогуртом и лимонным соком.</li><li>Разложите киноа по мискам, сверху курицу, огуречный салат и халуми. Посыпьте орехами, оливками, мятой и петрушкой, полейте соусом из салата и подавайте с лимоном.</li></ol><p><em>Хорошо подходит для заготовки обедов на неделю; подавайте с дольками лимона.</em></p>', CURRENT_TIMESTAMP),
  ('481a3a47-02fc-54cb-8d0d-c288ed2cf066', '9b2a2d60-e379-5ae6-93af-180a748167f3', 'en', 'Lebanese-spiced chicken quinoa bowls with halloumi', 'Quinoa topped with roasted chicken thighs in Lebanese seven spice, grated halloumi, a smashed cucumber and cherry tomato salad with yogurt, pine nuts and herbs.', '<ol><li>Heat the oven to 400°F (200°C) and line a baking sheet with parchment.</li><li>Smash the cucumbers with the side of a knife, break into bite-size chunks and put in a colander. Add the halved cherry tomatoes, salt and drain for 30 minutes.</li><li>Toss the chicken with the Lebanese 7 spice, 1 tsp salt and about a tablespoon of olive oil, spread on the sheet and roast about 20 minutes until 165°F (74°C). Rest 10 minutes and slice into bite-size pieces.</li><li>Rinse the quinoa until the water runs clear, add the water and salt, bring to a boil, reduce to low and cook covered about 15 minutes. Turn off and steam 10 more minutes.</li><li>Toast the pine nuts with a teaspoon of oil 2–3 minutes until golden. Mix the drained cucumbers and tomatoes with the yogurt and lemon juice.</li><li>Divide the quinoa between bowls and top with the chicken, cucumber salad and halloumi. Add the pine nuts, olives, mint and parsley, drizzle with the salad dressing and serve with lemon wedges.</li></ol><p><em>Great for weekly meal prep; serve with lemon wedges.</em></p>', CURRENT_TIMESTAMP),
  ('51b23831-a85c-5e05-94f7-3f6351bb052e', '1fd735e2-7f6e-5b17-835e-0fb1db282e89', 'ru', 'Ризотто с креветками, лимоном и шпинатом в мультиварке', 'Кремовое ризотто из арборио на курином бульоне с шалотом, лимонными креветками и шпинатом. Готовится под давлением за 6 минут.', '<ol><li>Включите режим жарки в мультиварке, влейте 1 ст. л. масла и обжарьте креветки с ¼ ч. л. соли 3–4 минуты до готовности. Переложите в миску, отключите режим и перемешайте креветки с лимонной цедрой и хлопьями чили.</li><li>Снова включите жарку, влейте оставшиеся 2 ст. л. масла, обжарьте шалот 2–3 минуты. Добавьте рис и жарьте 2 минуты до прозрачности. Влейте бульон, добавьте ½ ч. л. соли, соскребите осадок со дна. Закройте крышку и готовьте на высоком давлении 6 минут.</li><li>Сбросьте давление быстро. Помешивайте 1–2 минуты, чтобы ризотто загустело, добавьте шпинат, масло и оставшийся ¼ ч. л. соли и перемешайте, пока шпинат не увянет.</li><li>Подавайте, выложив сверху креветки с их соком.</li></ol><p><em>Подавайте сразу, пока ризотто горячее и кремовое.</em></p>', CURRENT_TIMESTAMP),
  ('d7acefce-48bf-5244-b4df-5bb23d53d5a0', '1fd735e2-7f6e-5b17-835e-0fb1db282e89', 'en', 'Instant Pot lemon shrimp risotto with spinach', 'Creamy Arborio risotto in chicken broth with shallot, lemony shrimp and wilted spinach, pressure-cooked in 6 minutes.', '<ol><li>Set the multicooker to Sauté, add 1 tbsp of the oil and cook the shrimp with ¼ tsp of the salt 3–4 minutes until just cooked. Move to a bowl, cancel, and toss with the lemon zest and chilli flakes.</li><li>Sauté again, add the remaining 2 tbsp oil and the shallot for 2–3 minutes. Add the rice and cook 2 minutes until translucent. Pour in the broth with ½ tsp salt and scrape the bottom. Lock the lid and cook at high pressure for 6 minutes.</li><li>Quick-release the pressure. Stir 1–2 minutes to thicken, then add the spinach, butter and remaining ¼ tsp salt and stir until the spinach wilts.</li><li>Serve topped with the shrimp and their juices.</li></ol><p><em>Serve right away while hot and creamy.</em></p>', CURRENT_TIMESTAMP),
  ('bd209324-b0ec-5db6-8c49-7fd579ad4957', '3d50cbbc-d102-5e8e-a883-e8984ab8b65b', 'ru', 'Киш без теста с кабачком, помидорами и сыром', 'Запеканка-киш с «корочкой» из обжаренных кабачков и шалота, помидорами, моцареллой, пармезаном и лёгкой яичной заливкой с мукой и петрушкой.', '<ol><li>Разогрейте духовку до 175 °C, слегка смажьте маслом форму диаметром 23 см.</li><li>Разложите кружки помидора на бумажном полотенце, посолите на несколько минут и промокните.</li><li>В большой сковороде разогрейте 2 ст. л. масла, добавьте кабачок и шалот, половину паприки, соль и перец. Жарьте, часто помешивая, до мягкости и лёгкой румяности.</li><li>Выложите кабачки в форму ровным слоем, сверху помидоры, затем моцареллу и пармезан.</li><li>Взбейте яйца с молоком, оставшейся паприкой, разрыхлителем, мукой и петрушкой. Залейте смесью форму и выпекайте около 30 минут, пока заливка не схватится. Дайте постоять 5–7 минут перед нарезкой.</li></ol><p><em>Подойдёт на завтрак, обед или лёгкий ужин с салатом.</em></p>', CURRENT_TIMESTAMP),
  ('0d4dc942-221c-5297-a86f-8930d9d9dc84', '3d50cbbc-d102-5e8e-a883-e8984ab8b65b', 'en', 'Crustless zucchini and tomato quiche with cheese', 'A quiche with a base of sautéed zucchini and shallots topped with tomatoes, mozzarella, parmesan and a light egg custard with flour and parsley.', '<ol><li>Heat the oven to 350°F (175°C) and lightly oil a 9-inch pie dish.</li><li>Lay the tomato slices on paper towel, salt them for a few minutes and pat dry.</li><li>In a large skillet heat 2 tbsp oil, add the zucchini and shallots with half of the paprika, salt and pepper and sauté, tossing regularly, until tender and starting to brown.</li><li>Press the zucchini mixture across the bottom of the dish, top with the tomatoes, then the mozzarella and parmesan.</li><li>Whisk the eggs with the milk, remaining paprika, baking powder, flour and parsley. Pour into the dish and bake about 30 minutes until set. Rest 5–7 minutes before slicing.</li></ol><p><em>Works for breakfast, lunch or a light dinner with a salad.</em></p>', CURRENT_TIMESTAMP),
  ('f92e7bf9-8877-5bc6-84d0-a140025ce505', '7823fc04-4e22-506e-9c6e-e71d18a6b1f1', 'ru', 'Курица с песто, сливками и овощами на сковороде', 'Куриные эскалопы, обжаренные со сладким перцем, кабачком, помидорами и красным луком, в сливочном соусе с песто и лимоном.', '<ol><li>Обсушите куриные эскалопы, посолите и поперчите. В чугунной сковороде разогрейте около 2 ст. л. масла и обжарьте курицу на среднем и сильном огне по 2–3 минуты с каждой стороны. Переложите на тарелку.</li><li>При необходимости добавьте масла, положите кабачок, перец, лук и помидоры, посолите и поперчите. Готовьте, помешивая, 6–7 минут до мягкости овощей.</li><li>Смешайте песто со сливками, верните курицу в сковороду, влейте соус и прогрейте на среднем и слабом огне около минуты.</li><li>Снимите с огня, добавьте цедру и половину сока лимона, при необходимости добавьте соль, перец и лимонный сок. Украсьте кедровыми орехами и базиликом.</li></ol><p><em>Подайте с макаронами, рисом или хлебом. Посыпьте базиликом и кедровыми орехами.</em></p>', CURRENT_TIMESTAMP),
  ('4f11ecdb-f71e-5bfd-a9f5-12754df05d6c', '7823fc04-4e22-506e-9c6e-e71d18a6b1f1', 'en', 'Creamy pesto chicken with zucchini and peppers', 'Seared chicken cutlets with bell pepper, zucchini, tomatoes and red onion in a creamy pesto and lemon sauce, all in one skillet.', '<ol><li>Pat the chicken dry and season with salt and pepper. Heat about 2 tbsp oil in a cast iron skillet and sear the chicken over medium-high heat 2–3 minutes per side. Set aside.</li><li>Add more oil if needed, then add the zucchini, bell pepper, onion and tomatoes, season and cook, tossing, 6–7 minutes until softened.</li><li>Mix the pesto with the cream, return the chicken to the skillet, pour in the sauce and warm through over medium-low heat about a minute.</li><li>Remove from the heat and finish with the lemon zest and half the juice, adjusting with more juice, salt and pepper. Garnish with pine nuts and basil.</li></ol><p><em>Serve with pasta, rice or bread. Garnish with basil and pine nuts.</em></p>', CURRENT_TIMESTAMP),
  ('70f41110-ca5b-5c0f-99c4-7b2e7d820d13', '48fe1f71-ec11-5699-99e8-3f2d26d3f961', 'ru', 'Салат из зелёной чечевицы с огурцом, перцем и свежей зеленью', 'Тёплая чечевица в лимонно-чесночной заправке с огурцом, сладким перцем, зелёным луком, петрушкой и мятой. Веганское сытное блюдо.', '<ol><li>Взбейте лимонный сок, чеснок, соль, перец и урфа бибер, тонкой струйкой влейте оливковое масло и взбивайте до эмульсии. Отставьте.</li><li>Положите в кастрюлю чечевицу, лавровый лист и воду так, чтобы она покрывала крупу на 2,5 см. Доведите до кипения, убавьте огонь, накройте и варите 20–25 минут до мягкости при сохранении формы. Слейте воду.</li><li>Смешайте тёплую чечевицу с заправкой и дайте немного остыть.</li><li>Добавьте огурец, оба перца, зелёный лук, петрушку и мяту, аккуратно перемешайте, подправьте вкус. Подавайте сразу или охладите.</li></ol><p><em>Можно подать как гарнир или как основное блюдо на 4 порции. Хранится до 3 дней.</em></p>', CURRENT_TIMESTAMP),
  ('416bc18b-e06f-5ac0-9fe2-69ceeaa15456', '48fe1f71-ec11-5699-99e8-3f2d26d3f961', 'en', 'French lentil salad with cucumber, bell pepper and fresh herbs', 'Warm lentils tossed in a lemon-garlic dressing with cucumber, bell peppers, green onions, parsley and mint. A satisfying vegan dish.', '<ol><li>Whisk the lemon juice, garlic, salt, pepper and Urfa biber, drizzle in the olive oil while whisking until emulsified. Set aside.</li><li>Put the lentils, bay leaf and water to cover by 1 inch in a pan. Bring to a boil, reduce the heat, cover and simmer 20–25 minutes until tender but still with some bite. Drain.</li><li>Toss the warm lentils with the dressing and cool a few minutes.</li><li>Add the cucumber, both peppers, green onions, parsley and mint, toss gently and adjust the seasoning. Serve right away or chill.</li></ol><p><em>Serve as a side or as a main for four. Keeps up to 3 days.</em></p>', CURRENT_TIMESTAMP),
  ('60ae7abb-1a91-5386-a08b-839f85c693b1', 'f4e647ac-658d-55ff-927c-4e6028949a91', 'ru', 'Белая фасоль с чесноком, помидорами черри и пармезаном', 'Фасоль каннеллини, быстро прогретая с чесноком, помидорами черри, зирой и перцем алеппо, с петрушкой, пармезаном, пекорино и лимонным соком.', '<ol><li>В большой сковороде разогрейте 2 ст. л. оливкового масла на среднем огне и недолго обжарьте чеснок до золотистого цвета, помешивая.</li><li>Добавьте фасоль и ½ стакана воды, приправьте солью, перцем, алеппо и зирой, положите помидоры. Прогревайте около 10 минут, иногда помешивая.</li><li>Вмешайте петрушку, сыры и лимонный сок. Сбрызните оливковым маслом и сразу подавайте.</li></ol><p><em>Подайте с лепёшкой пита или хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('0bb9bbae-0ebe-5c39-869b-124c270e5b58', 'f4e647ac-658d-55ff-927c-4e6028949a91', 'en', 'Garlic parmesan white beans with cherry tomatoes', 'Cannellini beans quickly warmed with garlic, cherry tomatoes, cumin and Aleppo pepper, finished with parsley, parmesan, pecorino and lemon juice.', '<ol><li>In a large pan warm 2 tbsp of olive oil over medium heat and cook the garlic briefly, tossing, until just golden.</li><li>Add the beans and ½ cup of water, season with salt, pepper, Aleppo and cumin and add the tomatoes. Cook about 10 minutes, stirring occasionally, until warmed through.</li><li>Stir in the parsley, cheeses and lemon juice, drizzle with olive oil and serve immediately.</li></ol><p><em>Serve with pita or crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('f05c55d4-5d0e-5ec7-9ba7-9e7a01396770', '73896382-fe90-55fd-b208-ec2e789951c8', 'ru', 'Куриный суп с заварными клёцками и зеленью', 'Густой суп с курицей, картофелем, морковью и сельдереем с нежными клёцками из заварного теста, сваренными прямо в бульоне.', '<ol><li>Растопите в кастрюле 2 ст. л. масла и на среднем огне 5–8 минут обжарьте лук, морковь, сельдерей и чеснок с солью и перцем до мягкости. Если овощи липнут, добавьте немного воды.</li><li>Всыпьте 2 ст. л. муки, перемешайте и прогрейте около минуты. Влейте часть бульона, размешивая до гладкости, затем остальной бульон. Доведите до кипения и убавьте огонь.</li><li>Добавьте картофель и тимьян и варите под крышкой 10–15 минут до мягкости картофеля.</li><li>Тем временем доведите до кипения стакан бульона с 6 ст. л. масла и 1 ч. л. соли. Сразу всыпьте стакан муки и энергично мешайте около минуты, затем на слабом огне ещё 3 минуты, пока тесто не соберётся в шар и не перестанет липнуть.</li><li>Переложите тесто в миску и остудите (или взбивайте миксером 3–5 минут), затем вмешайте яйца по одному.</li><li>Переложите тесто в пакет, срежьте уголок и выдавливайте над кипящим супом полоски, нарезая их ножницами по 4 см. Варите под крышкой на слабом огне 8–10 минут до готовности клёцок.</li><li>Добавьте курицу, прогрейте минуту, выключите огонь и посыпьте зеленью.</li></ol><p><em>Посыпьте свежей петрушкой и укропом.</em></p>', CURRENT_TIMESTAMP),
  ('8678f274-1107-5194-876c-78552eacaedf', '73896382-fe90-55fd-b208-ec2e789951c8', 'en', 'Chicken soup with choux dumplings and dill', 'A thick soup of chicken, potatoes, carrots and celery with tender choux-dough dumplings cooked right in the broth.', '<ol><li>Melt 2 tbsp of the butter in a pot over medium heat and cook the onion, carrots, celery and garlic with salt and pepper 5-8 minutes until tender, adding a splash of water if they stick.</li><li>Stir in 2 tbsp flour and cook about 1 minute. Pour in some of the broth, stirring until smooth, then the rest. Bring to a boil and reduce to a simmer.</li><li>Add the potatoes and thyme and simmer covered 10-15 minutes until the potatoes are cooked.</li><li>Meanwhile bring 1 cup broth, 6 tbsp butter and 1 tsp salt to a boil. Add 1 cup flour all at once and stir hard for about a minute, then 3 more minutes on low until the dough forms a ball and is no longer sticky.</li><li>Transfer the dough to a bowl and cool it (or beat with a mixer 3-5 minutes), then beat in the eggs one at a time.</li><li>Put the dough in a zip bag, snip a corner and pipe it over the simmering soup, cutting it with scissors into 4 cm pieces. Cook covered at a low simmer 8-10 minutes until the dumplings are cooked.</li><li>Add the chicken, warm for a minute, turn off the heat and garnish with herbs.</li></ol><p><em>Garnish with fresh parsley and dill.</em></p>', CURRENT_TIMESTAMP),
  ('ec40d23b-66b0-59f4-9f98-6bc5a00273aa', '8c1e8faa-9bea-502d-aa7e-9d23574c0987', 'ru', 'Говядина с луком в мультиварке (рагу к пасте или картофелю)', 'Говяжья лопатка, томлёная на тёртых овощах и луке в соусе из красного вина, бульона и соевого соуса. Мясо разбирают на волокна и подают с гарниром.', '<ol><li>Выложите на дно мультиварки мелко нарубленный лук, натёртые на мелкой тёрке морковь и сельдерей и чеснок. Посолите, поперчите, добавьте сушёные травы и перемешайте.</li><li>Обсушите мясо, щедро посолите и поперчите, посыпьте кориандром. Разогрейте масло на сильном огне и обжарьте говядину с двух сторон до корочки. Переложите на овощи в мультиварке.</li><li>В той же сковороде вмешайте в жир муку и томатную пасту, влейте красное вино, соскребая румяные частицы, затем постепенно бульон, помешивая до гладкости. Доведите до кипения, добавьте соевый соус и вылейте на мясо.</li><li>Готовьте на высоком режиме 4–6 часов или на низком 6–9 часов, пока мясо не станет мягким. Достаньте мясо и разберите вилкой на кусочки.</li><li>Снимите жир с жидкости, перелейте её в кастрюлю и уварите на сильном огне до загустения. Верните мясо в соус и посыпьте зеленью.</li></ol><p><em>Подавайте с лапшой, пастой, рисом или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('fbc5279c-fd3a-56d8-8bb1-b2a39d6f7612', '8c1e8faa-9bea-502d-aa7e-9d23574c0987', 'en', 'Slow cooker beef and onion ragu', 'Beef chuck slow-cooked over grated vegetables and onions in a sauce of red wine, broth and soy, then shredded and served over a side.', '<ol><li>Put the finely minced onions, finely grated carrot and celery and the garlic in the bottom of the slow cooker. Season with salt, pepper and dried herbs and mix.</li><li>Dry the beef and season generously with salt, pepper and coriander. Heat the oil in a skillet on high and brown the beef on both sides, then set it on the vegetables in the slow cooker.</li><li>In the same skillet whisk the flour and tomato paste into the drippings, pour in the wine and scrape up the browned bits, then gradually add the broth, whisking smooth. Bring to a boil, add the soy sauce and pour over the beef.</li><li>Cook on high 4-6 hours or low 6-9 hours until fork-tender. Remove the beef and shred it into bite-size pieces.</li><li>Skim the fat from the liquid, pour it into a saucepan and boil down until thickened. Return the beef to the sauce and garnish with herbs.</li></ol><p><em>Serve over noodles, pasta, rice or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('f544d3b0-398a-52e9-9cbe-46ecf6619e30', 'a928365f-29e6-5820-ab5d-0c2bfff73571', 'ru', 'Рыбный пирог с картофельной корочкой, помидорами и луком', 'Лёгкая версия пастушьего пирога: филе белой рыбы на слое лука и помидоров под золотистым картофельным пюре с желтками.', '<ol><li>Разогрейте духовку до 200 °C. Очистите картофель, нарежьте кусками по 5 см и варите в подсоленной воде на слабом кипении до мягкости.</li><li>Смажьте маслом круглую глубокую форму диаметром 23 см, включая бортики. Распределите на дне один зубчик чеснока и тонкие кольца лука, посолите и поперчите.</li><li>Выложите внахлёст кружки помидоров, посолите, поперчите, сбрызните 2 ст. л. масла, посыпьте вторым зубчиком чеснока, свежей и сушёной зеленью.</li><li>Нарежьте рыбу порциями, посолите, поперчите и положите на помидоры. Сбрызните оставшимся маслом и посыпьте травами.</li><li>Слейте воду с картофеля, добавьте масло и разомните. Вливайте молоко небольшими порциями до нужной густоты, вмешайте желтки.</li><li>Выложите пюре поверх рыбы, чтобы полностью её закрыть, и выровняйте. Запекайте 35–40 минут, в последние 2–3 минуты включите гриль, чтобы корочка слегка подрумянилась.</li></ol><p><em>Подавайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('78216ac8-9daa-5084-ac1e-4c644d03271a', 'a928365f-29e6-5820-ab5d-0c2bfff73571', 'en', 'Fisherman''s pie with tomatoes and mashed potato crust', 'A light take on shepherd''s pie: white fish fillets over onion and tomatoes under a golden crust of mashed potato enriched with egg yolks.', '<ol><li>Heat the oven to 200°C (400°F). Peel the potatoes, cut into 2-inch pieces and simmer in salted water until fork-tender.</li><li>Brush a deep 9-inch pie plate with oil, including the sides. Spread one minced garlic clove on the bottom, add thin onion rings, and season.</li><li>Shingle the tomato slices in one layer, season, drizzle with 2 tbsp oil and sprinkle with the second garlic clove and fresh and dried herbs.</li><li>Cut the fish into portions, season and place on the tomatoes. Drizzle with the remaining oil and sprinkle with herbs.</li><li>Drain the potatoes, add the butter and mash. Add the milk a little at a time to your preferred thickness, then mix in the egg yolks.</li><li>Spread the mash over the fish so it covers it completely and level it. Bake 35-40 minutes, broiling the last 2-3 minutes for a light golden crust.</li></ol><p><em>Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('584cc3bf-fb38-55eb-af5f-d787f6f618bf', 'da42bada-d91f-5af2-81f8-8b1611c576e1', 'ru', 'Жёлтый рис с перцем, томатами и куркумой', 'Ароматный гарнир из риса с луком, сладким перцем, помидорами, чесноком и куркумой, сваренный в горячем бульоне.', '<ol><li>Доведите бульон до кипения в небольшой кастрюле и держите горячим.</li><li>В большой сковороде или кастрюле разогрейте масло на средне-сильном огне, обжарьте лук с солью и перцем 3–5 минут до прозрачности.</li><li>Добавьте нарезанные перцы и халапеньо и готовьте ещё 2–3 минуты, затем помидоры и чеснок на 2–3 минуты.</li><li>Добавьте томатную пасту и куркуму и перемешайте около минуты. Куркума даёт цвет, без неё рис не будет жёлтым.</li><li>Всыпьте рис, прибавьте огонь и 2 минуты постоянно помешивайте, чтобы он покрылся овощами. Добавьте лавровый лист.</li><li>Влейте кипящий бульон, дайте закипеть, убавьте огонь до слабого и готовьте под крышкой 15 минут. Взрыхлите вилкой, выньте лавровый лист и посыпьте зеленью.</li></ol><p><em>Посыпьте зелёным луком или кинзой, подайте к мясу, курице или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('00c1072d-7228-5b32-ad66-35cb9e5a5da7', 'da42bada-d91f-5af2-81f8-8b1611c576e1', 'en', 'Yellow rice with peppers, tomatoes and turmeric', 'A fragrant rice side with onion, bell peppers, tomatoes, garlic and turmeric cooked in hot broth.', '<ol><li>Bring the chicken broth to a boil in a small saucepan and keep it hot.</li><li>Heat the oil in a large skillet or pot over medium-high and cook the onion with salt and pepper 3-5 minutes until translucent.</li><li>Add the chopped peppers and jalapeño for 2-3 more minutes, then the tomatoes and garlic for 2-3 minutes.</li><li>Stir in the tomato paste and turmeric for about a minute. The turmeric gives the colour, so don''t leave it out.</li><li>Add the rice, turn the heat to high and stir constantly for 2 minutes so it''s coated. Add the bay leaf.</li><li>Pour in the boiling broth and bring to a boil, then reduce to low and cook covered 15 minutes. Fluff with a fork, discard the bay leaf and garnish with herbs.</li></ol><p><em>Garnish with scallions or cilantro and serve with meat, chicken or fish.</em></p>', CURRENT_TIMESTAMP),
  ('f61cb589-8aa8-5912-967e-7c6b5d29afe0', '8ff76963-1096-5008-9114-92c959e910ca', 'ru', 'Ленивая лазанья из пасты с фаршем и рикоттой', 'Вместо листов лазаньи используется обычная паста: её смешивают с мясным томатным соусом, прослаивают сырной начинкой из рикотты и моцареллы и запекают.', '<ol><li>Разогрейте духовку до 175 °C. Отварите пасту на 3 минуты меньше, чем указано на упаковке, чтобы она осталась слегка недоваренной. Слейте воду, оставив полстакана.</li><li>Пока варится паста, обжарьте в масле фарш (он не обязан дойти до конца), добавьте лук и чеснок, посолите, поперчите и готовьте около 8 минут до золотистости лука.</li><li>Влейте измельчённые томаты, добавьте сушёные травы и готовьте ещё 8–10 минут под крышкой на слабом огне. Для более сочной лазаньи добавьте ещё немного томатов.</li><li>Смешайте рикотту, яйца, пармезан и часть моцареллы, посолите, поперчите, при желании добавьте чесночный порошок или мускатный орех.</li><li>Выключите огонь под соусом, добавьте сливки и свежую зелень. Смешайте соус с пастой, при необходимости разведите оставленной водой.</li><li>Половину пасты выложите в форму 23×33 см, сверху выровняйте сырную начинку и посыпьте третью часть моцареллы. Добавьте остальную пасту и оставшуюся моцареллу.</li><li>Накройте фольгой и запекайте до пузырьков по краям: около 20 минут сразу после сборки или 45–55 минут из холодильника. Снимите фольгу за последние 15 минут, чтобы сыр подрумянился.</li></ol><p><em>Хорошо готовить заранее и замораживать порциями.</em></p>', CURRENT_TIMESTAMP),
  ('26e81308-4107-5e91-98a8-959925513b8f', '8ff76963-1096-5008-9114-92c959e910ca', 'en', 'Lazy lasagna with pasta, ground beef and ricotta', 'Instead of lasagna sheets, ordinary pasta is tossed with a meaty tomato sauce, layered with a ricotta and mozzarella filling and baked.', '<ol><li>Heat the oven to 175°C (350°F). Cook the pasta 3 minutes less than the package says so it''s slightly underdone. Drain, reserving ½ cup of the cooking water.</li><li>Meanwhile brown the ground beef in the oil (it needn''t cook through), add the onion and garlic with salt and pepper and cook about 8 minutes until the onion is golden.</li><li>Add the crushed tomatoes and dried herbs and cook 8-10 more minutes covered on medium-low. For a saucier lasagna add a little extra tomato.</li><li>Mix the ricotta, eggs, parmesan and some of the mozzarella with salt and pepper; garlic powder or nutmeg are optional.</li><li>Turn off the sauce, stir in the cream and fresh herbs and toss with the pasta, loosening with reserved pasta water if needed.</li><li>Put half the pasta in a 9x13-inch dish, spread the cheese filling on top and sprinkle with a third of the mozzarella. Add the rest of the pasta and the remaining mozzarella.</li><li>Cover with foil and bake until bubbly around the edges: about 20 minutes if freshly assembled, 45-55 minutes if chilled. Uncover for the last 15 minutes to brown the cheese.</li></ol><p><em>Great made ahead and frozen in portions.</em></p>', CURRENT_TIMESTAMP),
  ('b73a6113-ef33-5fd9-b3f9-de3bb14fe4ed', '7a5cf5ce-b651-5cef-b882-35f8fc566db5', 'ru', 'Суп с индейкой, кейлом, бататом и мелкой лапшой', 'Лёгкий суп с овощами, картофелем, бататом и листьями кейла, в который кладут мелкую пасту и варёную индейку или курицу. Хороший способ использовать остатки мяса.', '<ol><li>Разогрейте в большой кастрюле масло и обжарьте на среднем огне лук, сельдерей, морковь и чеснок с солью и перцем около 5 минут до мягкости.</li><li>Добавьте картофель, батат и бульон, доведите до кипения и варите под крышкой 10–15 минут до мягкости картофеля.</li><li>Добавьте пасту, кейл и мясо и варите ещё около 5 минут до готовности пасты.</li><li>Попробуйте, досолите и поперчите, посыпьте петрушкой и при желании пармезаном.</li></ol><p><em>Посыпьте петрушкой и тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('e32ff10c-297d-5e97-95c1-0318b156a485', '7a5cf5ce-b651-5cef-b882-35f8fc566db5', 'en', 'Turkey, kale and sweet potato noodle soup', 'A light soup of vegetables, potato, sweet potato and kale with small pasta and cooked turkey or chicken. A good way to use leftover meat.', '<ol><li>Heat the butter in a large pot and sauté the onion, celery, carrots and garlic with salt and pepper on medium about 5 minutes until tender.</li><li>Add the potato, sweet potato and broth, bring to a boil and simmer covered 10-15 minutes until cooked through.</li><li>Add the pasta, kale and turkey and cook about 5 more minutes until the pasta is done.</li><li>Taste and adjust the seasoning, then add parsley and, if you like, grated parmesan.</li></ol><p><em>Garnish with parsley and grated parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('f3b2328c-4fd1-5687-b568-dcb49ad28435', 'c512ef9e-d12b-5aa3-889e-e01faa448def', 'ru', 'Картофель с копчёной колбасой, грибами и перцем на противне', 'Запечённый на одном противне картофель с копчёной колбасой, болгарским перцем, шампиньонами, луком и чесноком. Быстрый сытный ужин.', '<ol><li>Разогрейте духовку до 245 °C (с конвекцией, если есть) и поставьте в неё пустой противень, чтобы он раскалился.</li><li>Вымойте картофель, нарежьте кусками по 3–4 см, залейте водой и доведите до кипения. Варите под крышкой около 5 минут, пока он не будет готов наполовину. Слейте воду.</li><li>Нарежьте грибы пополам или на четвертинки, лук толстыми полукольцами, перец кусками по 2,5 см и колбасу кружками.</li><li>В большой миске смешайте лук, перец, грибы, масло, чеснок, тимьян, соль, перец и сушёные травы. Добавьте полуготовый картофель и колбасу и аккуратно перемешайте.</li><li>Достаньте раскалённый противень и быстро выложите всё ровным слоем. Запекайте без крышки 20–30 минут, перевернув на середине, до золотистой корочки. В конце можно включить гриль на пару минут.</li><li>Посыпьте свежей зеленью и подавайте.</li></ol><p><em>Посыпьте свежей зеленью: петрушкой, укропом или зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('2ac1cf50-6d08-5636-b5da-f4aa697a2977', 'c512ef9e-d12b-5aa3-889e-e01faa448def', 'en', 'Sheet pan smoked sausage with potatoes, mushrooms and peppers', 'Roasted potatoes with smoked sausage, bell pepper, mushrooms, onion and garlic, all on one pan. A quick, hearty dinner.', '<ol><li>Heat the oven to 245°C (475°F), with convection if you have it, and put an empty rimmed baking sheet in to heat.</li><li>Scrub the potatoes, cut into 1-1½ inch pieces, cover with water and bring to a boil. Simmer covered about 5 minutes until halfway cooked, then drain.</li><li>Halve or quarter the mushrooms, cut the onion into thick half circles, the pepper into 1-inch pieces and the sausage into 1-inch slices.</li><li>In a large bowl combine the onion, pepper, mushrooms, olive oil, garlic, thyme, salt, pepper and dried herbs. Add the par-cooked potatoes and sausage and toss gently.</li><li>Take out the hot pan and spread everything in one layer. Roast uncovered 20-30 minutes, turning halfway, until golden. Broil the last few minutes if you like.</li><li>Garnish with fresh herbs and serve.</li></ol><p><em>Garnish with fresh herbs such as parsley, dill or chives.</em></p>', CURRENT_TIMESTAMP),
  ('b7b2e7d7-1498-5e01-a17c-f5936bc705d3', '791d6e18-2e40-5c3e-a567-d3988e08844c', 'ru', 'Курица с рисом, шиитаке и брокколи в азиатском стиле в одной сковороде', 'Куриные бёдра в соевом маринаде с грибами шиитаке, морковью, имбирём и рисом, приготовленные в одной глубокой сковороде, с брокколи в конце.', '<ol><li>Смешайте в миске курицу, 2 ст. л. соевого соуса, 2 ст. л. масла и крахмал.</li><li>Разогрейте в большой глубокой сковороде 1½–2 ст. л. масла, обжарьте курицу 5–7 минут до золотистого цвета с двух сторон и переложите в миску.</li><li>В той же сковороде обжарьте лук с солью на средне-слабом огне 2–3 минуты, затем грибы с солью 5–7 минут до лёгкого золотистого цвета.</li><li>Добавьте чеснок, имбирь, хлопья перца и морковь, готовьте 3 минуты. Всыпьте рис и перемешайте, чтобы он покрылся маслом и овощами.</li><li>Влейте горячий бульон, доведите до кипения, добавьте оставшийся соевый соус по вкусу. Убавьте огонь, накройте и готовьте около 8 минут.</li><li>Верните курицу, добавьте брокколи, вдавив её в рис, накройте и готовьте на слабом огне ещё 3–5 минут. Выключите огонь и оставьте на 5 минут. Посыпьте зелёным луком.</li></ol><p><em>Посыпьте зелёным луком и подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('ff3c8180-c493-52b8-81e0-711f4abc0f46', '791d6e18-2e40-5c3e-a567-d3988e08844c', 'en', 'One-pan Asian chicken and rice with shiitake and broccoli', 'Chicken thighs in a soy marinade cooked with shiitake, carrot, ginger and rice in one deep skillet, finished with broccoli.', '<ol><li>In a bowl combine the chicken, 2 tbsp soy sauce, 2 tbsp oil and the cornstarch.</li><li>Heat 1½-2 tbsp oil in a large deep skillet and brown the chicken 5-7 minutes on both sides. Transfer to a bowl.</li><li>In the same skillet cook the onion with salt on medium-low 2-3 minutes, then the mushrooms with salt 5-7 minutes until wilted and golden.</li><li>Add the garlic, ginger, red pepper and carrot and cook 3 minutes. Stir in the rice until evenly coated.</li><li>Pour in the hot broth, bring to a boil and add the remaining soy sauce to taste. Reduce to a simmer, cover and cook about 8 minutes.</li><li>Return the chicken and nestle in the broccoli, cover and cook on low another 3-5 minutes. Turn off the heat and rest 5 minutes. Garnish with green onion.</li></ol><p><em>Garnish with sliced green onion and serve right away.</em></p>', CURRENT_TIMESTAMP),
  ('7af253ea-83dd-54eb-9548-a9e66b1166f6', '2fe5702f-d67b-5f05-ad7d-85220c33825d', 'ru', 'Курица с запечённой перловкой и тыквой в медово-лимонной глазури', 'Обжаренные куриные бёдра на слое перловки с луком, мускатной тыквой, морковью и сельдереем, запечённые и смазанные медово-лимонной глазурью.', '<ol><li>Разогрейте духовку до 175 °C. Обрежьте лишний жир с бёдер, обсушите и посолите и поперчите с двух сторон.</li><li>Разогрейте масло на сильном огне и обжаривайте бёдра кожей вниз 5–8 минут до золотистой корочки, затем переверните. Не трогайте их, пока не подрумянятся. Если нужно, жарьте в два приёма. Отложите.</li><li>Слейте почти весь вытопленный жир, оставив 1 ст. л. Убавьте огонь, обжарьте лук 5 минут до мягкости.</li><li>Добавьте тыкву, морковь, сельдерей и чеснок, посолите и поперчите и готовьте ещё 5 минут. Добавьте перловку и бульон.</li><li>Доведите до кипения, переложите всё в форму 23×33 см и уложите сверху курицу кожей вверх. Накройте фольгой и запекайте 45–60 минут, пока жидкость не впитается.</li><li>Снимите фольгу и запекайте ещё 10 минут. Смешайте мёд, лимонный сок и тёртый чеснок, смажьте курицу глазурью и поставьте под гриль на 3–5 минут. Смажьте ещё раз перед подачей.</li></ol><p><em>Подавайте прямо из формы со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('4b854c5b-918c-59fc-9413-0b5a7fbcf1fd', '2fe5702f-d67b-5f05-ad7d-85220c33825d', 'en', 'Honey-lemon glazed chicken thighs with baked barley and butternut squash', 'Browned chicken thighs set on a bed of barley with onion, butternut squash, carrot and celery, baked and brushed with a honey-lemon glaze.', '<ol><li>Heat the oven to 175°C (350°F). Trim excess fat from the thighs, pat dry and season both sides.</li><li>Heat the oil on high and brown the thighs skin side down 5-8 minutes until golden, then turn. Leave them alone until ready to flip; brown in two batches if needed. Set aside.</li><li>Pour off most of the rendered fat, leaving 1 tbsp. Lower the heat and soften the onion about 5 minutes.</li><li>Add the squash, carrot, celery and garlic, season and cook 5 more minutes. Stir in the barley and broth.</li><li>Bring to a boil, pour into a 9x13-inch dish and set the chicken on top skin side up. Cover with foil and bake 45-60 minutes until the liquid is absorbed.</li><li>Uncover and bake 10 more minutes. Mix the honey, lemon juice and grated garlic, brush the chicken and broil 3-5 minutes. Brush again before serving.</li></ol><p><em>Serve straight from the dish with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('3ac557cf-bae9-5747-b007-c17bfa099a31', '42ddca91-6138-5979-9f54-836c2ca23c49', 'ru', 'Блинчики с курицей, грибами и яйцом', 'Тонкие блинчики с начинкой из курицы, шампиньонов, жареного лука, варёных яиц и сыра, которые обжаривают перед подачей до румяной корочки.', '<ol><li>Взбейте в блендере молоко, 4 яйца, крахмал, муку, масло и соль до однородности. Тесто лучше постоит несколько часов или ночь.</li><li>Разогрейте на средне-сильном огне антипригарную сковороду диаметром 25–30 см, смажьте маслом. Влейте чуть меньше ¼ стакана теста, наклоняя сковороду. Жарьте 2–3 минуты до золотистости, переверните и жарьте ещё 30–60 секунд. Испеките все блинчики.</li><li>Для начинки растопите масло, обжарьте лук с солью и перцем около 5 минут до мягкости, добавьте грибы и готовьте 5–7 минут, пока они не станут мягкими и золотистыми и не впитают выделившуюся жидкость.</li><li>Измельчите курицу, лук и грибы в комбайне или блендере короткими импульсами в мелкую крошку, не превращая в пюре. Переложите в миску.</li><li>Натрите варёные яйца на мелкой тёрке и добавьте в миску вместе с тёртым сыром и бульоном (нужное количество зависит от сухости начинки). Посолите и поперчите по вкусу.</li><li>Положите на каждый блинчик около ¼ стакана начинки, аккуратно распределите тонким слоем и плотно сверните. Уложите швом вниз.</li><li>Перед подачей обжарьте блинчики на масле на средне-слабом огне по 3 минуты с каждой стороны до золотистой корочки и прогрева. Подавайте со сметаной и зеленью.</li></ol><p><em>Подавайте со сметаной и рубленой зеленью (2 блинчика на порцию).</em></p>', CURRENT_TIMESTAMP),
  ('e4fc44e0-00c8-5df5-ba4a-271a40779ca6', '42ddca91-6138-5979-9f54-836c2ca23c49', 'en', 'Chicken and mushroom crepes (blinchiki) with egg and cheese', 'Thin crepes filled with chicken, mushrooms, caramelized onion, hard-boiled eggs and cheese, pan-fried before serving until golden.', '<ol><li>Blend the milk, 4 eggs, cornstarch, flour, oil and salt until smooth. The batter is best rested for a few hours or overnight.</li><li>Heat a 10-12 inch non-stick skillet over medium-high and grease it. Pour in slightly less than ¼ cup batter, tilting to spread. Cook 2-3 minutes until golden, flip and cook 30-60 seconds more. Make all the crepes.</li><li>For the filling heat the butter and cook the onions with salt and pepper about 5 minutes until soft, then add the mushrooms and cook 5-7 minutes until tender and golden, letting the liquid they release cook off.</li><li>Pulse the chicken, onions and mushrooms in a food processor or blender into very small pieces, not a purée. Transfer to a bowl.</li><li>Finely grate the hard-boiled eggs and add them with the cheese and broth (as much as the filling needs to bind). Season to taste.</li><li>Spread about ¼ cup filling thinly over each crepe and roll up tightly, seam side down.</li><li>Before serving fry the crepes in butter or oil over medium-low about 3 minutes per side until golden and hot throughout. Serve with sour cream and herbs.</li></ol><p><em>Serve with sour cream and fresh herbs (2 crepes per serving).</em></p>', CURRENT_TIMESTAMP),
  ('362808c8-b451-5321-bca6-3351809b82f8', 'b40a2241-3222-5297-a251-076648c63eef', 'ru', 'Дже чхе: корейская стеклянная лапша из батата с говядиной и овощами', 'Лапша из батата, обжаренная с полосками говядины, морковью, сладким перцем, шампиньонами, шпинатом и тонкими полосками омлета в сладко-солёном соевом соусе с кунжутом.', '<ol><li>Отварите лапшу по инструкции, слейте воду и ополосните холодной. Смешайте ингредиенты соуса для лапши и отставьте.</li><li>Смешайте ингредиенты маринада для говядины с чёрным перцем, добавьте мясо, перемешайте и оставьте на 10 минут.</li><li>Шпинат залейте кипятком на 1 минуту, откиньте, ополосните холодной водой и отожмите. Смешайте с чесноком, кунжутным маслом, кунжутом и ¼ ч. л. соли.</li><li>Взбейте яйцо с щепоткой соли и испеките на небольшой сковороде с маслом очень тонкий омлет (по 30 секунд с каждой стороны). Остудите, сверните в трубочку и нарежьте полосками по 0,5 см.</li><li>В большой сковороде обжарьте говядину 1–2 минуты и отложите. Затем по очереди, протирая сковороду бумажным полотенцем и добавляя немного масла, обжарьте морковь с щепоткой соли 2 минуты, перец 2–3 минуты и грибы 6–8 минут до золотистого цвета.</li><li>Протрите сковороду, разогрейте оставшееся масло и 2 минуты прогревайте лапшу. Влейте соус, добавьте все приготовленные ингредиенты и зелёный лук и перемешивайте на сильном огне ещё 2 минуты. Подавайте с кунжутом.</li></ol><p><em>Подавайте сразу, посыпав кунжутом. Можно подать и как гарнир на 4 порции.</em></p>', CURRENT_TIMESTAMP),
  ('d21f79b4-ebef-59bb-b163-e5f2f5133d3f', 'b40a2241-3222-5297-a251-076648c63eef', 'en', 'Japchae: Korean sweet potato noodles with beef and vegetables', 'Sweet potato noodles stir-fried with beef strips, carrot, red pepper, mushrooms, spinach and thin omelette strips in a sweet-savoury soy and sesame sauce.', '<ol><li>Cook the noodles per the packet, drain and rinse under cold water. Mix the japchae sauce ingredients and set aside.</li><li>Mix the beef marinade ingredients with black pepper, add the beef, toss and marinate 10 minutes.</li><li>Cover the spinach with boiling water for 1 minute, drain, rinse in cold water and squeeze dry. Mix with the garlic, sesame oil, sesame seeds and ¼ tsp salt.</li><li>Beat the egg with a pinch of salt and cook a very thin omelette in a small oiled pan (30 seconds per side). Cool, roll up and slice into 0.5 cm strips.</li><li>In a large pan fry the beef 1–2 minutes and set aside. Then in turn, wiping the pan and adding a little oil each time, fry the carrot with a pinch of salt 2 minutes, the pepper 2–3 minutes and the mushrooms 6–8 minutes until golden.</li><li>Wipe the pan, heat the remaining oil and warm the noodles 2 minutes. Add the sauce, all the prepared ingredients and the spring onions and toss over high heat 2 more minutes. Serve with sesame seeds.</li></ol><p><em>Serve immediately sprinkled with sesame seeds. Also works as a side for four.</em></p>', CURRENT_TIMESTAMP),
  ('33e1a408-d4af-5501-ab47-013814af8636', 'a7d4c5fb-7e4c-5ca7-80d1-4b3baeb1173a', 'ru', 'Лёгкая курица корма с йогуртом, миндалём и изюмом', 'Мягкое индийское карри из куриной грудки в соусе из лука, чеснока, имбиря и пасты корма с молотым миндалём, изюмом и греческим йогуртом вместо сливок.', '<ol><li>Измельчите в комбайне лук, чеснок и имбирь в пасту (можно вручную мелко порубить).</li><li>Выложите пасту в большую сковороду с высокими бортами, добавьте 3 ст. л. воды и готовьте 5 минут. Добавьте пасту корма и прогревайте ещё 2 минуты до аромата.</li><li>Добавьте нарезанную кусочками курицу, молотый миндаль, изюм, бульон и сахар. Перемешайте, накройте и варите на слабом огне 10 минут до готовности курицы.</li><li>Снимите с огня, вмешайте йогурт, посолите и поперчите. Посыпьте кинзой и молотым миндалём. Подавайте с рисом.</li></ol><p><em>Подайте с бурым или белым рисом басмати и посыпьте миндалём.</em></p>', CURRENT_TIMESTAMP),
  ('c14bc1b2-62c6-5fa9-802d-402cd7ddfca9', 'a7d4c5fb-7e4c-5ca7-80d1-4b3baeb1173a', 'en', 'Light chicken korma with yogurt, almonds and sultanas', 'A mild Indian curry of chicken breast in an onion, garlic, ginger and korma paste sauce with ground almonds, sultanas and Greek yogurt instead of cream.', '<ol><li>Blitz the onion, garlic and ginger to a paste in a food processor (or chop very finely by hand).</li><li>Tip the paste into a large high-sided pan with 3 tbsp water and cook 5 minutes. Add the korma paste and cook 2 more minutes until aromatic.</li><li>Stir in the chicken pieces, ground almonds, sultanas, stock and sugar. Mix, cover and simmer 10 minutes until the chicken is cooked.</li><li>Remove from the heat, stir in the yogurt and season. Scatter with coriander and extra ground almonds. Serve with rice.</li></ol><p><em>Serve with brown or white basmati rice, topped with almonds.</em></p>', CURRENT_TIMESTAMP),
  ('8a020359-c0a1-5251-9df0-4acc4a68683d', '912523e6-5c7c-51a0-82a1-81af7126bd22', 'ru', 'Лёгкое катсу-карри: курица в миндальной панировке с бурым рисом', 'Куриное филе в корочке из рубленого миндаля, запечённое в духовке, с гладким соусом карри из лука, чеснока, имбиря и специй, бурым рисом и свежим салатом из моркови и огурца.', '<ol><li>Разогрейте духовку до 220 °C (аэрогриль — до 180 °C на 4 минуты). Варите бурый рис в большом количестве кипящей воды 35 минут до мягкости.</li><li>Мелко измельчите миндаль и рассыпьте на тарелке. Смажьте противень маслом. Смажьте курицу маслом с двух сторон, приправьте, обваляйте в миндале и выложите на противень, прижав оставшиеся орехи. Запекайте 20 минут (в аэрогриле 18–20 минут) до румяности. Дайте отдохнуть 4–5 минут и нарежьте толстыми ломтиками.</li><li>Для соуса в кастрюле разогрейте масло, 8 минут слегка обжаривайте лук, чеснок и имбирь под неплотной крышкой до мягкости и лёгкой золотистости.</li><li>Добавьте карри, бадьян, куркуму и перец, прогрейте несколько секунд. Всыпьте муку, перемешайте и постепенно влейте 400 мл воды. Варите на слабом огне 10 минут, затем пробейте погружным блендером до гладкости и посолите.</li><li>Когда рис готов, добавьте нарезанный зелёный лук на минуту, слейте воду. Смешайте морковь и огурец (ленточки овощечисткой) с чили, соком лайма и травами.</li><li>Разложите курицу по тарелкам, полейте соусом, подайте с рисом, салатом и дольками лайма.</li></ol><p><em>Подайте с дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('eacfc0e7-6044-5d08-b9df-e6a37a0e74f1', '912523e6-5c7c-51a0-82a1-81af7126bd22', 'en', 'Healthy baked almond-crusted chicken katsu curry with brown rice', 'Chicken breast in a chopped almond crust baked in the oven, served with a smooth onion, garlic, ginger and spice curry sauce, brown rice and a fresh carrot and cucumber salad.', '<ol><li>Heat the oven to 220°C (200°C fan), or the air fryer to 180°C for 4 minutes. Cook the brown rice in plenty of boiling water for 35 minutes until tender.</li><li>Finely chop the almonds and spread on a plate. Grease the tray with a little oil. Brush the chicken on both sides with the remaining oil, season, coat in the nuts and set on the tray, pressing on any remaining nuts. Bake 20 minutes (18–20 in an air fryer) until browned. Rest 4–5 minutes and slice thickly.</li><li>For the sauce heat the oil in a saucepan and gently fry the onion, garlic and ginger loosely covered for 8 minutes until softened and lightly browned.</li><li>Stir in the curry powder, star anise, turmeric and pepper for a few seconds. Sprinkle over the flour, stir and gradually add 400 ml water. Simmer 10 minutes, then blitz smooth with a stick blender and season.</li><li>When the rice is tender add the spring onions for 1 minute and drain. Toss the carrot and cucumber ribbons with the chilli, lime juice and herbs.</li><li>Divide the chicken between plates, pour over the sauce and serve with the rice, salad and lime wedges.</li></ol><p><em>Serve with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('4ea6323a-be54-5653-be6c-711cbb6ac7db', '8ade2ce1-b52b-5c73-a325-e99574e80eae', 'ru', 'Простая паэлья с морепродуктами и копчёной паприкой', 'Рис для паэльи с луком, копчёной паприкой, тимьяном, томатами и куриным бульоном, с готовым коктейлем из морепродуктов и лимоном. Всё в одной сковороде.', '<ol><li>Разогрейте масло в большой сковороде или воке, 5 минут обжаривайте лук до мягкости.</li><li>Добавьте копчёную паприку, тимьян и рис, помешивайте минуту, влейте херес или вино, дайте испариться. Добавьте томаты и бульон.</li><li>Посолите, поперчите и готовьте без крышки около 15 минут, иногда помешивая, пока рис не станет почти мягким, а жидкости останется немного.</li><li>Добавьте размороженные морепродукты, накройте крышкой и варите 5 минут до их готовности и мягкости риса.</li><li>Сбрызните лимонным соком, посыпьте петрушкой и подавайте с дольками лимона.</li></ol><p><em>Подайте с дольками лимона и петрушкой. Можно добавить чоризо и горошек.</em></p>', CURRENT_TIMESTAMP),
  ('b792c22f-fa9c-58b9-918d-18bce86bd8bf', '8ade2ce1-b52b-5c73-a325-e99574e80eae', 'en', 'Easy seafood paella with tomato and smoked paprika', 'Paella rice cooked with onion, smoked paprika, thyme, tomatoes and chicken stock, finished with a mixed seafood and lemon, all in one pan.', '<ol><li>Heat the olive oil in a large frying pan or wok and soften the onion for 5 minutes.</li><li>Add the smoked paprika, thyme and rice, stir 1 minute, splash in the sherry or wine and let it evaporate. Stir in the tomatoes and stock.</li><li>Season and cook uncovered about 15 minutes, stirring now and then, until the rice is almost tender with a little liquid left.</li><li>Stir in the defrosted seafood, cover and simmer 5 minutes until the seafood is cooked and the rice tender.</li><li>Squeeze over the lemon juice, scatter with parsley and serve with lemon wedges.</li></ol><p><em>Serve with lemon wedges and parsley. Add chorizo and peas if you like.</em></p>', CURRENT_TIMESTAMP),
  ('104c7284-dc63-5784-8e49-e80fdce804a0', 'aecb8814-fb0b-5cae-838a-2e92a86a4c54', 'ru', 'Сегединский гуляш со свининой и квашеной капустой', 'Тушёная свинина с луком, паприкой, тмином и квашеной капустой, с добавлением сливок и ложкой сметаны при подаче.', '<ol><li>В кастрюле на среднем огне растопите сало и обжарьте мелко нарезанный лук до золотистого цвета, 5–8 минут. Добавьте тмин и свинину, обжаривайте со всех сторон 10 минут.</li><li>Добавьте чеснок, посолите и поперчите, посыпьте мукой и готовьте минуту. Добавьте паприку ещё на минуту.</li><li>Влейте половину бульона, добавьте лавровый лист и варите под крышкой на слабом огне 30 минут.</li><li>Добавьте капусту, оставшийся бульон и немного рассола от капусты. Тушите под крышкой ещё 30 минут, иногда помешивая, до мягкости мяса.</li><li>Влейте сливки, прогрейте 5 минут, попробуйте и приправьте. Подавайте со сметаной.</li></ol><p><em>Хорош с картофельными или хлебными кнедликами, картофелем или хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('01558c4f-a271-5aca-878b-1e8af9cb16d4', 'aecb8814-fb0b-5cae-838a-2e92a86a4c54', 'en', 'Szegedin pork and sauerkraut goulash with cream', 'Slow-cooked pork with onions, paprika, caraway-style cumin and sauerkraut, finished with cream and topped with a spoonful of soured cream.', '<ol><li>Melt the lard in a pot over medium heat and fry the finely chopped onion until golden, 5–8 minutes. Add the cumin and pork and brown all over for 10 minutes.</li><li>Add the garlic, season well, scatter over the flour and cook for a minute. Add the paprika for 1 minute more.</li><li>Pour in half of the stock, add the bay leaves and simmer covered on low heat 30 minutes.</li><li>Add the sauerkraut, remaining stock and a drizzle of the pickling juices. Simmer covered another 30 minutes, stirring occasionally, until the pork is tender.</li><li>Stir in the cream and simmer 5 minutes, taste and season. Serve with a spoonful of soured cream.</li></ol><p><em>Serve with dumplings, potatoes or crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('9f0202a8-be19-56d2-8b90-70e10d7f96a6', '89214f42-61fa-57ad-9655-7dd896849c23', 'ru', 'Курица по-испански с чоризо, фасолью и оливками', 'Куриные бёдра на кости, запечённые в соусе из томатов с копчёной паприкой, колечками чоризо, сладким перцем, зелёными оливками и белой фасолью.', '<ol><li>Разогрейте духовку до 200 °C. В большой жаропрочной сковороде на среднем огне разогрейте масло и 15 минут обжаривайте лук, чоризо и перцы с щепоткой соли и перца, пока овощи не станут мягкими, а чоризо не выделит жир.</li><li>Добавьте паприку и чеснок и готовьте ещё несколько минут до аромата.</li><li>Влейте томаты, добавьте оливки и фасоль, перемешайте, приправьте. Уложите куриные бёдра, посолите и поперчите.</li><li>Запекайте около 40 минут, пока кожа не станет хрустящей, а мясо готовым и мягким. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой. Подайте с хлебом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('19af377d-af79-5e98-a365-e1159d0c81fd', '89214f42-61fa-57ad-9655-7dd896849c23', 'en', 'Spanish chicken thighs with chorizo, butter beans and olives', 'Bone-in chicken thighs baked in a tomato and smoked paprika sauce with chorizo rings, sweet peppers, green olives and butter beans.', '<ol><li>Heat the oven to 200°C (180°C fan). In a large ovenproof frying pan heat the oil over medium heat and fry the onion, chorizo and peppers with a pinch of salt and pepper for 15 minutes until the vegetables soften and the chorizo releases its oils.</li><li>Add the paprika and garlic and cook a few minutes more until fragrant.</li><li>Tip in the tomatoes, olives and butter beans, stir and season. Nestle in the chicken thighs and season well.</li><li>Bake about 40 minutes until the skin is crisp and the chicken cooked through and tender. Scatter with parsley.</li></ol><p><em>Sprinkle with parsley and serve with crusty bread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('95886cb4-4ab6-5e7c-b3b7-db7ecd6087b9', '83302026-9d3c-5f1d-b4a3-c44748725d71', 'ru', 'Курица саг: карри со шпинатом и бурым басмати', 'Лёгкое индийское карри из куриной грудки со шпинатом, помидорами, имбирём и специями, с йогуртом в конце. Подаётся с бурым рисом с куркумой и кардамоном.', '<ol><li>Положите рис, куркуму и семена кардамона в кастрюлю с щепоткой соли и водой так, чтобы она хорошо покрывала рис. Накройте и варите 20 минут. Выключите и отставьте.</li><li>В большой сковороде на слабом и среднем огне разогрейте масло, добавьте лук, имбирь и чеснок, накройте и готовьте 5 минут до лёгкого румянца. Добавьте специи и прогрейте до аромата.</li><li>Добавьте курицу и обжаривайте несколько минут. Влейте нарезанные помидоры, добавьте томатную пасту и шпинат, готовьте 5 минут, помешивая, пока шпинат не увянет.</li><li>Вмешайте йогурт и прогрейте минуту. При необходимости слейте воду с риса и подайте с курицей.</li></ol><p><em>Блюдо можно заморозить без йогурта до трёх месяцев.</em></p>', CURRENT_TIMESTAMP),
  ('39702719-5779-56b9-bcec-2482c9a186d5', '83302026-9d3c-5f1d-b4a3-c44748725d71', 'en', 'Chicken saag with spinach and brown basmati rice', 'A light Indian curry of chicken breast with spinach, tomatoes, ginger and spices, finished with yogurt and served with turmeric and cardamom brown rice.', '<ol><li>Put the rice, turmeric and cardamom seeds in a pan with a pinch of salt and enough water to cover generously. Cover and simmer 20 minutes. Turn off the heat and set aside.</li><li>In a large pan over low-medium heat warm the oil, add the onion, ginger and garlic, cover and cook 5 minutes until starting to brown. Add the spices and toast briefly until fragrant.</li><li>Add the chicken and stir-fry a few minutes. Add the chopped tomatoes, tomato purée and spinach and cook 5 minutes, stirring, until the spinach wilts.</li><li>Stir in the yogurt and heat 1 minute. Drain the rice if needed and serve with the chicken.</li></ol><p><em>Can be frozen without the yogurt for up to three months.</em></p>', CURRENT_TIMESTAMP),
  ('46ec073d-b464-526c-a2d1-2a9a4baf708b', 'fb753176-fb54-5f57-9e41-9a39366dff14', 'ru', 'Шашлык из свинины на минералке с луком', 'Кубики свиной лопатки, замаринованные с большим количеством лука, кориандром, солью и газированной минеральной водой, чтобы мясо стало мягким, и обжаренные на шпажках на гриле.', '<ol><li>Нарежьте свинину крупными кубиками по 4 см.</li><li>В большой миске смешайте мясо, лук полукольцами, кориандр, соль и перец. Разомните лук с мясом руками около 3 минут (удобно в перчатках).</li><li>Влейте газированную воду и хорошо перемешайте. Мариновать минимум 6 часов в холодильнике, можно до 4 суток.</li><li>Нанижите мясо на шпажки, лук и маринад выбросьте.</li><li>Жарьте на гриле, разогретом до 200 °C, 15–20 минут, поворачивая каждые 3–4 минуты, чтобы мясо прожарилось равномерно.</li></ol><p><em>Подавайте с луком, свежими овощами, лавашом и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('c87442b5-0e6d-5734-9aeb-346cb15437f6', 'fb753176-fb54-5f57-9e41-9a39366dff14', 'en', 'Pork shashlik with onion and sparkling water marinade', 'Cubes of pork shoulder marinated with plenty of onion, coriander, salt and sparkling mineral water to tenderise the meat, then grilled on skewers.', '<ol><li>Cut the pork into large 1.5-inch cubes.</li><li>In a large bowl combine the pork, sliced onions, coriander, salt and pepper. Massage the onions into the meat for about 3 minutes (gloves make it easier).</li><li>Pour in the sparkling water and mix well. Marinate in the fridge at least 6 hours, up to 4 days.</li><li>Thread the meat onto skewers and discard the onions and marinade.</li><li>Grill on a preheated 200°C (400°F) grill 15-20 minutes, turning every 3-4 minutes so the meat cooks evenly.</li></ol><p><em>Serve with onions, fresh vegetables, flatbread and herbs.</em></p>', CURRENT_TIMESTAMP),
  ('14f910bd-75f7-5c4d-9ac1-8a53e84cd174', '86b0a88a-73c0-5e2c-9b11-9e21b0243aca', 'ru', 'Тушёная картошка со свининой, сливками и майонезом', 'Классическая домашняя тушёная картошка с кусочками свинины, паприкой и лавровым листом в сливочно-томатном соусе, приготовленная в мультиварке или скороварке.', '<ol><li>Включите режим жарки в мультиварке-скороварке и обжаривайте мясо на 2 ст. л. масла 10 минут.</li><li>Выключите и добавьте картофель, майонез, кетчуп, паприку, соль, перец, лавровый лист, чесночный порошок, сливки и воду. Перемешайте.</li><li>Закройте крышку и включите режим «тушение» на 45 минут. Давление должно набраться, затем начнётся отсчёт.</li><li>После окончания сбросьте пар и откройте крышку. Выньте лавровый лист и подавайте горячим.</li></ol><p><em>Подавайте с солёными огурцами или квашеной капустой.</em></p>', CURRENT_TIMESTAMP),
  ('d1b4cd55-09ea-54ae-b5ac-d221c0a46ccd', '86b0a88a-73c0-5e2c-9b11-9e21b0243aca', 'en', 'Stewed potatoes with pork in a creamy tomato sauce', 'A classic Ukrainian home-style dish of potatoes and pork chunks stewed with paprika and bay leaves in a creamy tomato sauce, made in a pressure cooker or multicooker.', '<ol><li>Select the brown/sauté function on the pressure cooker and brown the meat in 2 tbsp oil for 10 minutes.</li><li>Switch off and stir in the potatoes, mayo, ketchup, paprika, salt, pepper, bay leaves, garlic powder, cream and water.</li><li>Close the lid and select the stew setting for 45 minutes. The pressure will build and then the countdown starts.</li><li>When finished release the pressure, open the lid, discard the bay leaves and serve hot.</li></ol><p><em>Serve with pickles or sauerkraut.</em></p>', CURRENT_TIMESTAMP),
  ('4221b933-a753-5162-8356-fa0ac7e41c4e', '6dea5fd1-75ee-5a09-ade7-331e1712db45', 'ru', 'Салат из тёртой моркови с горошком, грибами и чесночным майонезом', 'Сытный украинский салат: тёртая морковь, слегка прогретая на сухой сковороде, с зелёным горошком, консервированными шампиньонами и майонезом с чесноком.', '<ol><li>Разогрейте на сильном огне большую глубокую антипригарную сковороду без масла. Выложите тёртую морковь и прогревайте, помешивая, около 2 минут.</li><li>Добавьте горошек и грибы и прогревайте ещё около 5 минут. Переложите в большую миску и полностью остудите.</li><li>Добавьте чеснок, соль, перец и майонез и перемешайте. Майонез нельзя добавлять в горячую смесь: он растечётся.</li><li>Уберите в холодильник минимум на несколько часов и подавайте охлаждённым.</li></ol><p><em>Дайте салату настояться в холодильнике несколько часов и подайте охлаждённым.</em></p>', CURRENT_TIMESTAMP),
  ('703c13ff-5f8f-5d64-9014-589dcad9f16d', '6dea5fd1-75ee-5a09-ade7-331e1712db45', 'en', 'Carrot salad with peas, mushrooms and garlic mayonnaise', 'A hearty Ukrainian salad of grated carrots warmed in a dry pan, tossed with green peas, canned mushrooms and garlicky mayonnaise.', '<ol><li>Heat a deep large non-stick skillet over high heat with no oil. Add the shredded carrots and stir about 2 minutes to warm through.</li><li>Add the peas and mushrooms and heat another 5 minutes. Transfer to a large bowl and cool completely.</li><li>Stir in the garlic, salt, pepper and mayonnaise. Don''t add the mayo while the mixture is hot or it will turn runny.</li><li>Refrigerate for at least several hours before serving.</li></ol><p><em>Chill for several hours and serve cold.</em></p>', CURRENT_TIMESTAMP),
  ('7eae8841-6ee1-59b9-bf37-c54e66acb207', '40922f6d-2e9b-5eeb-8ad9-176ec82b213a', 'ru', 'Кабачковая икра с морковью и болгарским перцем', 'Мягкая закуска-намазка из тушёных кабачков, моркови, перца, лука и чеснока. Можно есть тёплой или холодной, как закуску, гарнир или намазку на хлеб.', '<ol><li>Нарежьте кабачки и перцы, лук нарежьте кубиками, морковь натрите.</li><li>Разогрейте две сковороды: на большой 80 мл масла, на меньшей 3 ст. л. Разделите кабачки между ними и тушите на средне-слабом огне 25 минут, иногда помешивая.</li><li>Переложите кабачки в большую миску. В большую сковороду добавьте ещё около 8 ст. л. масла, морковь и лук и жарьте 15 минут.</li><li>Одновременно в маленькой сковороде обжарьте перец на 2 ст. л. масла 15 минут.</li><li>Соедините перец и кабачки с морковью и луком, добавьте соль, перец, сахар, уксус, чеснок и халапеньо. Готовьте ещё 10 минут.</li><li>Разложите по стеклянным банкам (получится около 1,4 л) и подавайте тёплой или охлаждённой.</li></ol><p><em>Подавайте с чёрным хлебом, тостами или как гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('531d8f8c-2cb6-5b44-988b-f9aa347c8368', '40922f6d-2e9b-5eeb-8ad9-176ec82b213a', 'en', 'Zucchini ikra spread with carrot and bell pepper', 'A soft vegetable spread of slowly sautéed zucchini, carrots, peppers, onion and garlic. Enjoy it warm or cold as an appetizer, side or spread on bread.', '<ol><li>Chop the zucchini and bell peppers, dice the onion and grate the carrots.</li><li>Heat two pans: about 1/3 cup oil in a large one and 3 tbsp in a smaller one. Divide the zucchini between them and cook 25 minutes over medium-low, stirring occasionally.</li><li>Transfer the zucchini to a large bowl. Add about 8 tbsp oil, the carrots and the onion to the large pan and sauté 15 minutes.</li><li>Meanwhile sauté the bell peppers in 2 tbsp oil in the small pan for 15 minutes.</li><li>Combine the peppers and zucchini with the carrot and onion, add salt, pepper, sugar, vinegar, crushed garlic and jalapeño and cook 10 more minutes.</li><li>Pack into glass jars (makes about 1.4 L) and serve warm or cold.</li></ol><p><em>Serve with dark bread, toast or as a side dish.</em></p>', CURRENT_TIMESTAMP),
  ('486d6769-439e-51a9-b54f-fe67b8403eb1', 'b9d7dde4-aa2f-5f7f-873b-d92b8546e3ba', 'ru', 'Салат из ромэна с огурцом, гранатом и чесночной заправкой', 'Свежий салат из листьев ромэн, огурцов, помидоров черри и красного лука с зёрнами граната и заправкой из сметаны, майонеза и чеснока.', '<ol><li>Смешайте для заправки сметану, майонез, молоко, чеснок, орегано и соль. Уберите в холодильник.</li><li>Разложите листья салата на блюде, сверху выложите огурцы, помидоры черри, тонко нарезанный лук и зёрна граната.</li><li>До подачи храните в холодильнике, перед подачей полейте заправкой и перемешайте.</li></ol><p><em>Заправляйте салат непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('4c211f55-cbf9-54ce-9c52-518873904b0b', 'b9d7dde4-aa2f-5f7f-873b-d92b8546e3ba', 'en', 'Romaine, cucumber and pomegranate salad with creamy garlic dressing', 'A fresh salad of romaine, cucumber, cherry tomatoes and red onion topped with pomegranate seeds and a sour cream, mayo and garlic dressing.', '<ol><li>Whisk together the sour cream, mayonnaise, milk, garlic, oregano and salt for the dressing and refrigerate.</li><li>Arrange the lettuce on a platter and top with the cucumbers, cherry tomatoes, thinly sliced onion and pomegranate seeds.</li><li>Keep chilled until needed, then toss with the dressing just before serving.</li></ol><p><em>Dress the salad right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('2df37818-635c-563d-842a-a1cf63009c5c', 'dbe8d8d7-52d8-5cdb-a727-fcd485ffe32a', 'ru', 'Салат с креветками, кускусом, ромэном и фетой с греческой заправкой', 'Лёгкий салат с хрустящим ромэном, креветками, крупным кускусом, сладким перцем, оливками и фетой под лимонной заправкой с орегано.', '<ol><li>Доведите до кипения 360 мл воды с ½ ч. л. соли и 1 ч. л. масла. Сварите кускус до аль денте по инструкции (8–10 минут), слейте, промойте холодной водой и перемешайте с 1 ч. л. масла. Охладите.</li><li>Для заправки встряхните в банке оба масла, уксусы, лимонный сок, дижонскую горчицу, пармезан, соль, перец, чесночный порошок и орегано до однородности.</li><li>Полностью разморозьте креветки и обсушите. Нарежьте и обсушите ромэн.</li><li>В большой миске соедините ромэн, кускус, лук, фету, оливки, креветки и полоски печёного перца. Полейте заправкой и подавайте.</li></ol><p><em>Заправьте салат перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('13fd4c09-cd02-5dab-8393-c90f08cf405a', 'dbe8d8d7-52d8-5cdb-a727-fcd485ffe32a', 'en', 'Shrimp and pearl couscous Mediterranean salad with feta and Greek dressing', 'A light salad of crisp romaine, shrimp, pearl couscous, roasted peppers, olives and feta with a lemony oregano dressing.', '<ol><li>Bring 1½ cups water to a boil with ½ tsp salt and 1 tsp olive oil. Cook the couscous al dente per the package (8-10 minutes), drain, rinse with cold water and toss with 1 tsp oil. Chill.</li><li>For the dressing shake the oils, vinegars, lemon juice, Dijon, parmesan, salt, pepper, garlic powder and oregano in a jar until emulsified.</li><li>Make sure the shrimp is fully thawed and pat it dry. Chop and dry the lettuce.</li><li>In a large bowl combine the lettuce, couscous, onion, feta, olives, shrimp and roasted pepper strips. Add the dressing and serve.</li></ol><p><em>Dress the salad just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('e5982d07-f5e9-5f09-9f24-3dedf18ac2d9', '7e8c4643-70a7-5bd7-b150-d8a84b6f1e68', 'ru', 'Лосось в соусе терияки с брокколи и морковью на одном противне', 'Кусочки лосося, замаринованные в домашнем терияки с мёдом и коричневым сахаром, запечённые с брокколи и морковью и покрытые густой глазурью.', '<ol><li>Нарежьте лосось кусками по 5 см.</li><li>Смешайте мёд, коричневый сахар, соевый соус и специи для соуса, кроме крахмала и воды.</li><li>Натрите лук на мелкой тёрке в большую миску, добавьте лосось и половину соуса и перемешайте. Мариновать 30 минут.</li><li>Разогрейте духовку до 215 °C. Застелите противень фольгой, выложите рыбу, морковь и брокколи и полейте овощи маринадом. Запекайте 15 минут.</li><li>Пока запекается, нагрейте оставшийся соус в ковшике на среднем огне до растворения сахара. Смешайте крахмал с водой, влейте и помешивайте до лёгкого загустения. Покройте лосось глазурью и подавайте.</li></ol><p><em>Подавайте горячим с рисом или остывшим.</em></p>', CURRENT_TIMESTAMP),
  ('c905407b-394a-58f8-9db7-d7f846a4d413', '7e8c4643-70a7-5bd7-b150-d8a84b6f1e68', 'en', 'One-pan teriyaki salmon with broccoli and carrots', 'Salmon chunks marinated in homemade honey and brown sugar teriyaki, baked with broccoli and carrots and brushed with a thick glaze.', '<ol><li>Cut the salmon into 2-inch chunks.</li><li>Whisk together the honey, brown sugar, soy sauce and seasoning, leaving out the cornstarch and water.</li><li>Finely grate the onion into a large bowl, add the salmon and half the sauce and toss to coat. Marinate 30 minutes.</li><li>Heat the oven to 215°C (420°F). Line a baking pan with foil, arrange the fish and vegetables and pour the marinade over the vegetables. Bake 15 minutes.</li><li>Meanwhile warm the remaining sauce in a small saucepan over medium until the sugar dissolves. Mix the cornstarch with water, stir it in until slightly thickened, then glaze the salmon and serve.</li></ol><p><em>Serve hot over rice or enjoy it cold.</em></p>', CURRENT_TIMESTAMP),
  ('64644b02-092b-5ef4-80de-0db6e9108333', '41946f1d-e56e-5ede-87e6-430b260d4ec6', 'ru', 'Паста с курицей в каджунских специях и сливочном соусе', 'Куриные грудки в пряной каджунской смеси с обжаренным перцем и луком и пастой в сливочном соусе с томатами, сливочным сыром и пармезаном.', '<ol><li>Смешайте соль, чёрный перец, чесночный и луковый порошок, чили, копчёную паприку, кайенский перец и горчичный порошок для каджунской смеси.</li><li>Отварите пасту в подсоленной воде до аль денте, оставьте полстакана отвара, воду слейте.</li><li>Нарежьте перцы полосками и лук кубиками, измельчите чеснок. Разрежьте грудки поперёк пополам или отбейте, посыпьте паприкой и 1 ст. л. каджунской смеси.</li><li>На сковороде на среднем огне растопите 1 ст. л. масла и 1 ст. л. сливочного. Жарьте курицу по 4–6 минут с каждой стороны, после переворота добавьте ещё 1 ст. л. сливочного масла и накройте крышкой, чтобы мясо дошло до 74 °C. Дайте отдохнуть 10 минут и нарежьте.</li><li>В той же сковороде обжарьте перцы и лук 3–4 минуты до румяных пятен и отложите.</li><li>Добавьте оставшееся сливочное масло и чеснок до аромата. Влейте уксус и томаты и уварите вдвое, затем растопите в соусе сливочный сыр.</li><li>Влейте сливки, добавьте пармезан и ½ ч. л. каджунской смеси. При необходимости разведите отваром пасты и варите 3–4 минуты до кремовой консистенции. Добавьте пасту и овощи, сверху выложите курицу.</li></ol><p><em>Посыпьте петрушкой и пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('bfb73bb9-3b82-5a13-8ca5-f13dd522340b', '41946f1d-e56e-5ede-87e6-430b260d4ec6', 'en', 'Creamy Cajun chicken pasta with peppers', 'Cajun-spiced chicken breasts over pasta in a creamy tomato, cream cheese and parmesan sauce with seared peppers and onion.', '<ol><li>Mix the salt, black pepper, garlic powder, onion powder, chili powder, smoked paprika, cayenne and mustard powder into a Cajun seasoning.</li><li>Cook the pasta in salted water until al dente, reserve ½ cup of the cooking water and drain.</li><li>Slice the peppers into strips, dice the onion and mince the garlic. Slice the chicken breasts in half crosswise or pound evenly and season with the paprika and 1 tbsp of the Cajun mix.</li><li>Heat 1 tbsp olive oil and 1 tbsp butter in a skillet over medium. Sear the chicken 4-6 minutes per side, adding 1 tbsp butter and covering after the flip, until 74°C (165°F). Rest 10 minutes and slice.</li><li>In the same skillet sauté the peppers and onion 3-4 minutes until charred and set aside.</li><li>Add the last tablespoon of butter and the garlic until fragrant. Pour in the vinegar and tomatoes and reduce by half, then melt in the cream cheese.</li><li>Pour in the cream, add the parmesan and ½ tsp of the Cajun mix, thinning with pasta water if needed, and simmer 3-4 minutes until creamy. Toss in the pasta and peppers and top with the chicken.</li></ol><p><em>Garnish with parsley and extra parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('50913794-6bd1-5c36-81ab-1c597a46fb04', '1dbd3fec-b551-58d0-bd30-bd2a25f63a7e', 'ru', 'Паста с запечённой фетой, помидорами черри и сливочным сыром', 'Помидоры черри запекаются с брынзой-фетой и сливочным сыром и чесноком, затем смешиваются со сливками, пармезаном и пастой.', '<ol><li>Выложите помидоры черри в форму 23×33 см, добавьте 4 ст. л. масла, чеснок и специи: перец, чесночный и луковый порошок, кайенский перец, хлопья чили и петрушку.</li><li>Поставьте в центр кусок феты, разложите кусочки сливочного сыра между помидорами и сбрызните фету 1 ст. л. масла.</li><li>Запекайте при 200 °C 25 минут (ещё 15 минут, если хотите, чтобы помидоры лопнули). В это время отварите пасту.</li><li>Выньте из духовки, влейте сливки, добавьте пармезан и перемешайте, разбивая фету. Добавьте пасту и подавайте.</li></ol><p><em>Посыпьте свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('a781636e-e91c-5340-9ba0-b6b5104dee69', '1dbd3fec-b551-58d0-bd30-bd2a25f63a7e', 'en', 'Baked feta pasta with cherry tomatoes and cream cheese', 'Cherry tomatoes roast with a block of feta, cream cheese and garlic, then are stirred with cream, parmesan and pasta into a creamy tomato sauce.', '<ol><li>Put the cherry tomatoes in a 9x13-inch dish with 4 tbsp oil, the garlic and the spices: pepper, garlic powder, onion powder, cayenne, chili flakes and parsley.</li><li>Place the block of feta in the middle, dot the tomatoes with pieces of cream cheese and drizzle the feta with 1 tbsp oil.</li><li>Bake at 200°C (400°F) for 25 minutes (15 more if you want the tomatoes to burst). Meanwhile cook the pasta.</li><li>Remove from the oven, add the cream and parmesan and stir, breaking up the feta. Toss with the pasta and serve.</li></ol><p><em>Finish with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('a3886de7-5523-55e6-a79d-12b7c3c339e1', '4cde5d36-fb41-5bfe-8546-614a3eab23a0', 'ru', 'Густой сливочный куриный суп с картофелем, морковью и сливочным сыром', 'Сытный суп-чаудер из курицы, картофеля и моркови, загущенный мучной смесью с молоком и растворённым сливочным сыром.', '<ol><li>В большой кастрюле обжарьте лук в сливочном масле около 5 минут до прозрачности.</li><li>Очистите морковь и картофель: морковь нарежьте тонкими кружками, картофель кубиками.</li><li>Добавьте овощи и бульон к луку, доведите до кипения и варите около 15 минут до мягкости.</li><li>Добавьте нарезанную курицу, петрушку, соль, перец и чесночный порошок и прогрейте, пока готовите смесь для загущения.</li><li>В миске понемногу вливайте молоко в муку, чтобы не было комков. Влейте в суп и прогрейте 2 минуты.</li><li>Добавьте кубики сливочного сыра и мешайте, пока он не растворится. Подавайте с багетом.</li></ol><p><em>Подавайте с хрустящим багетом.</em></p>', CURRENT_TIMESTAMP),
  ('dbe4c13b-214a-5136-b2b5-1333aa15088e', '4cde5d36-fb41-5bfe-8546-614a3eab23a0', 'en', 'Creamy chicken chowder with potatoes, carrots and cream cheese', 'A hearty chicken, potato and carrot chowder thickened with a flour and milk slurry and enriched with melted cream cheese.', '<ol><li>In a large pot sauté the onion in the butter about 5 minutes until translucent.</li><li>Peel the carrots and potatoes; slice the carrots into thin rings and cube the potatoes.</li><li>Add the vegetables and broth to the onion, bring to a boil and simmer about 15 minutes until tender.</li><li>Add the chopped chicken, parsley, salt, pepper and garlic powder and heat through while you make the slurry.</li><li>In a bowl gradually whisk the milk into the flour to avoid lumps. Pour into the soup and heat 2 more minutes.</li><li>Stir in the cubed cream cheese until melted and serve with a baguette.</li></ol><p><em>Serve with a crusty baguette.</em></p>', CURRENT_TIMESTAMP),
  ('468319bb-4233-5fec-a0fd-8912ef22faaa', '9d24632e-2294-5c86-8f6e-85d930319f45', 'ru', 'Пибимпап: рис с овощами, яйцом и соусом кочуджан', 'Хрустящий жареный рис с кочуджаном, сверху отдельно обжаренные ростки фасоли, грибы, кабачок, шпинат и яичница. Корейское блюдо в одной миске.', '<ol><li>Нарежьте грибы, морковь и кабачок тонкой соломкой. Подогрейте жаропрочную тарелку в микроволновке или тёплой духовке для готовых овощей.</li><li>В антипригарной сковороде разогрейте 2 ч. л. кунжутного масла, 3 минуты обжаривайте ростки фасоли до мягкости с хрустом и переложите на тарелку. Добавьте ещё 2 ч. л. масла и 3–5 минут обжаривайте грибы, затем тоже переложите.</li><li>В другой сковороде 6–8 минут обжаривайте варёный рис в 2 ч. л. растительного масла до горячего и слегка хрустящего состояния. Вмешайте кочуджан и отставьте.</li><li>В сковороде с овощами добавьте ещё 2 ч. л. кунжутного масла, 2 минуты быстро обжарьте кабачок и переложите. Затем 30 секунд прогрейте шпинат до увядания.</li><li>Добавьте в сковороду 2 ст. л. растительного масла и пожарьте 4 яйца до желаемой готовности желтка.</li><li>Разложите рис по 4 мискам, в центр положите яйцо, а овощи выложите секторами вокруг. Полейте остальным кочуджаном и посыпьте кунжутом.</li></ol><p><em>Перед едой всё перемешайте. Дополнительно можно подать кимчи и больше соуса.</em></p>', CURRENT_TIMESTAMP),
  ('dc95b623-a6b5-508f-858f-8fe231cf6196', '9d24632e-2294-5c86-8f6e-85d930319f45', 'en', 'Bibimbap with vegetables, fried egg and gochujang', 'Crisp fried rice with gochujang topped with separately cooked bean sprouts, mushrooms, courgette, spinach and a fried egg. A Korean one-bowl meal.', '<ol><li>Slice the mushrooms and cut the carrot and courgette into thin matchsticks. Warm a heatproof plate in the microwave or a low oven for the cooked toppings.</li><li>In a non-stick pan heat 2 tsp sesame oil and stir-fry the bean sprouts 3 minutes until just tender with a little bite, then move to the plate. Add another 2 tsp sesame oil and cook the mushrooms 3–5 minutes, then add to the plate.</li><li>In another pan fry the cooked rice in 2 tsp vegetable oil 6–8 minutes until piping hot and starting to crisp. Stir in the gochujang and set aside.</li><li>In the vegetable pan add another 2 tsp sesame oil and flash-fry the courgette 2 minutes, then move to the plate. Wilt the spinach 30 seconds.</li><li>Add 2 tbsp vegetable oil to the pan and fry the four eggs to your liking.</li><li>Divide the rice between four bowls, put an egg in the centre and arrange the vegetables around in sections. Drizzle with more gochujang and sprinkle with sesame seeds.</li></ol><p><em>Mix everything together before eating. Serve with kimchi and extra sauce if you like.</em></p>', CURRENT_TIMESTAMP),
  ('45e0ed18-7158-5b70-9c56-da7ef4b75e7f', 'edb162ad-ff32-59b1-bbad-dd42beda1e97', 'ru', 'Кимчи-тиге: острый корейский суп-рагу со свининой и тофу', 'Согревающее блюдо из выдержанного кимчи, свиной грудинки и лука, сваренное с корейским красным перцем, с кубиками тофу и зелёным луком.', '<ol><li>Откиньте кимчи на сито над мерным кувшином (нужно около 100 мл рассола, при необходимости добавьте из банки). В большой кастрюле на сильном огне разогрейте масло и обжарьте кимчи, лук и свиную грудинку 5 минут.</li><li>Добавьте гочугару и сахар и жарьте ещё 2 минуты. Влейте 800 мл воды и рассол от кимчи, доведите до кипения и варите без крышки на сильном огне 15 минут.</li><li>Нарежьте тофу квадратами 5 см толщиной около 1 см и выложите сверху. Накройте крышкой и прогрейте 3–4 минуты. Посыпьте зелёным луком.</li></ol><p><em>Подавайте горячим с варёным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('ae8205d9-5b59-58d7-ac68-292dc396b0cf', 'edb162ad-ff32-59b1-bbad-dd42beda1e97', 'en', 'Kimchi jjigae with pork belly and tofu', 'A warming Korean stew of mature kimchi, pork belly and onion simmered with Korean chilli flakes, topped with tofu and spring onions.', '<ol><li>Drain the kimchi in a sieve over a jug (you need about 100 ml brine, top up from the jar if needed). Heat the oil in a large saucepan over high heat and fry the drained kimchi, onion and pork belly for 5 minutes.</li><li>Stir in the gochugaru and sugar and fry 2 more minutes. Pour in 800 ml water and the kimchi brine, bring to a boil and simmer uncovered on high 15 minutes.</li><li>Slice the tofu into 5 cm squares about 1 cm thick and lay over the stew. Cover and cook 3–4 minutes until heated through. Scatter over the spring onions.</li></ol><p><em>Serve hot with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('bafb34ae-165c-5bf0-8d7d-deda46bf8efb', '27987f76-2859-5a48-8fd0-551b41073d93', 'ru', 'Гаспачо из спелых помидоров с печёным перцем', 'Холодный испанский суп из помидоров, обжаренного хлеба, печёного сладкого перца, огурца, чеснока и хересного уксуса. Настаивается и охлаждается несколько часов.', '<ol><li>Выложите нарезанные помидоры в большую миску. На сковороде разогрейте оливковое масло и обжарьте хлеб по 2–3 минуты с каждой стороны до золотистого цвета. Порвите на куски и добавьте к помидорам.</li><li>Обожгите перец на открытом огне конфорки с щипцами 5–10 минут, поворачивая, до равномерно почерневшей кожицы (или под раскалённым грилем). Переложите в пакет, закройте и оставьте на 10 минут. Снимите кожицу и семена, мякоть порвите.</li><li>Добавьте перец, огурец, щепотку соли, 2 ст. л. уксуса и чеснок к помидорам и хлебу. Оставьте на 2 часа при комнатной температуре.</li><li>Пропустите через крупное сито в кувшин, приправьте, добавьте уксуса при необходимости. Вмешайте оливковое масло extra virgin и охладите минимум 4 часа, лучше на ночь.</li></ol><p><em>Подавайте охлаждённым, с оливковым маслом, нарезанным огурцом и листьями базилика.</em></p>', CURRENT_TIMESTAMP),
  ('ee5fefee-b495-56f5-91a0-aee4528fc46d', '27987f76-2859-5a48-8fd0-551b41073d93', 'en', 'Tomato gazpacho with roasted red pepper', 'A cold Spanish soup of ripe tomatoes, fried bread, charred red pepper, cucumber, garlic and sherry vinegar, macerated and chilled for several hours.', '<ol><li>Put the chopped tomatoes in a large bowl. Heat the olive oil in a frying pan and fry the bread 2–3 minutes per side until golden, then tear into pieces and add to the tomatoes.</li><li>Char the pepper over the hob flame with tongs 5–10 minutes, turning, until blackened all over (or under a hot grill). Put in a bag, seal and leave to steam 10 minutes. Peel off the skin and seeds and tear the flesh.</li><li>Add the pepper, cucumber, a pinch of sea salt, 2 tbsp of the vinegar and the garlic to the tomatoes and bread. Leave 2 hours at room temperature.</li><li>Pass through a coarse sieve into a jug, season and add more vinegar if needed. Whisk in the extra virgin olive oil and chill at least 4 hours, ideally overnight.</li></ol><p><em>Serve chilled with a drizzle of olive oil, chopped cucumber and basil leaves.</em></p>', CURRENT_TIMESTAMP),
  ('9dc0b596-8234-54dc-94d5-8626d2dc625f', '67aa5e37-17c4-5502-8ec3-eeb2fa83727f', 'ru', 'Окономияки: японский капустный блин со свиной грудинкой', 'Блин из шинкованной капусты на яичном тесте с кусочками запечённой свиной грудинки, с соусом, майонезом, нори и зелёным луком.', '<ol><li>Разбейте яйцо в большую миску, добавьте муку, бульонный порошок и 100 мл воды, перемешайте. Добавьте шинкованную капусту, посолите и поперчите.</li><li>В небольшой глубокой сковороде (около 19 см) разогрейте масло на среднем огне и 4–5 минут жарьте ломтики свиной грудинки до золотистого цвета. Влейте капустную смесь, разровняйте и жарьте 5 минут до тёмной корочки снизу. Переверните и жарьте ещё 5 минут.</li><li>Смешайте вустерский соус, кетчуп и сахар для соуса, слегка приправьте.</li><li>Переложите блин на тарелку, полейте соусом и майонезом, посыпьте нори и зелёным луком.</li></ol><p><em>Хороший способ использовать остатки мяса. Подавайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('973a85bf-247a-5332-9234-f0d2cae51a8e', '67aa5e37-17c4-5502-8ec3-eeb2fa83727f', 'en', 'Okonomiyaki: Japanese cabbage pancake with pork belly', 'A savoury pancake of shredded cabbage in an egg batter with pieces of cooked pork belly, topped with a tangy sauce, mayo, nori and spring onions.', '<ol><li>Crack the egg into a large bowl, add the flour, bouillon powder and 100 ml water and mix well. Stir in the shredded cabbage and season.</li><li>In a small deep skillet (about 19 cm) heat the oil over medium heat and fry the pork belly slices 4–5 minutes until golden. Pour over the cabbage mixture, flatten and fry 5 minutes until dark brown underneath. Flip and cook 5 minutes more.</li><li>Whisk the Worcestershire sauce, ketchup and sugar for the sauce and season lightly.</li><li>Transfer the pancake to a plate and top with the sauce, mayo, nori and spring onions.</li></ol><p><em>A great way to use up leftover meat. Serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('c3bc3a38-dbba-53d6-af73-333341031226', '4066128f-b8ea-5766-8033-315692b4f47d', 'ru', 'Польские говяжьи котлеты (котлеты мелоне) с майораном', 'Котлеты из говяжьего фарша с жареным луком, булкой, вымоченной в молоке, яйцом и майораном, в сухарях, обжаренные до золотистой корочки.', '<ol><li>Замочите булку в молоке до полного размягчения. Пока она мокнет, обжарьте лук в масле около 8 минут до мягкости и золотистого цвета.</li><li>Добавьте к фаршу обжаренный лук, яйцо, чеснок, майоран, соль и перец. Отожмите булку от молока, добавьте в фарш и тщательно вымесите.</li><li>Разделите массу на 8 котлет и обваляйте в сухарях со всех сторон.</li><li>На глубокой сковороде разогрейте масло и жарьте котлеты порциями с двух сторон до золотистой корочки и полной готовности, по 6–7 минут с каждой стороны.</li></ol><p><em>Подайте с картофельным пюре и свежим салатом или квашеной капустой.</em></p>', CURRENT_TIMESTAMP),
  ('739e1640-9434-5e2a-9f3a-bb274caa4af8', '4066128f-b8ea-5766-8033-315692b4f47d', 'en', 'Polish beef patties (kotlety mielone) with marjoram', 'Beef mince patties with fried onion, a bread roll soaked in milk, egg and marjoram, coated in breadcrumbs and pan-fried until golden.', '<ol><li>Soak the bread roll in the milk until completely soft. Meanwhile fry the onion in the oil about 8 minutes until soft and golden.</li><li>Add the fried onion, egg, garlic, marjoram and seasoning to the mince. Squeeze the roll from the milk, add to the mince and mix well.</li><li>Divide the meat into 8 patties and coat in the breadcrumbs all over.</li><li>Heat oil in a deep frying pan and fry the patties in batches on both sides until browned and cooked through, 6–7 minutes per side.</li></ol><p><em>Serve with mashed potatoes and a fresh salad or sauerkraut.</em></p>', CURRENT_TIMESTAMP),
  ('8355ced0-1a79-5b07-830d-849e98ea4777', '8bb617d5-8247-5be6-9676-ad73532d8ddf', 'ru', 'Лахорский дал из чана-дал с зирой, томатом и гхи', 'Густой дал из колотого нута с лучком, чесноком, имбирём, томатной пастой и специями, как на лахорских уличных лотках. Подаётся с зелёным чили, кинзой и имбирём.', '<ol><li>Промойте и замочите нут-дал на 30 минут. Выложите в кастрюлю, залейте 2 л воды и варите на среднем огне 20 минут, пока не станет мягким, но не разварится. При необходимости подлейте воды. Слейте остаток воды.</li><li>В кастрюле на среднем огне растопите масло с гхи, на 15–20 секунд добавьте зиру и чёрный кардамон. Добавьте лук и жарьте до золотистого цвета, затем убавьте огонь и помешивайте ещё 5 минут.</li><li>Добавьте чеснок и имбирь на 30 секунд, постоянно помешивая. Добавьте томатную пасту, немного воды, куркуму, соль и порошок чили, жарьте около 2 минут, пока вода не выпарится.</li><li>Добавьте варёный нут-дал и 150 мл воды, убавьте огонь, накройте и готовьте 8–10 минут, регулярно помешивая.</li><li>Подавайте, посыпав рубленым чили, кинзой и соломкой имбиря.</li></ol><p><em>Подайте с лепёшками или рисом, посыпав свежим имбирём, кинзой и зелёным чили.</em></p>', CURRENT_TIMESTAMP),
  ('9c9f5980-0221-5a30-9be9-321dc0f06f18', '8bb617d5-8247-5be6-9676-ad73532d8ddf', 'en', 'Lahori chana dal with cumin, tomato and ghee', 'A thick dal of split chickpeas with onion, garlic, ginger, tomato purée and spices in the style of Lahore street stalls, finished with green chilli, cilantro and ginger.', '<ol><li>Wash and soak the chana dal about 30 minutes. Tip into a pan with 2 litres of water and boil over medium heat 20 minutes until soft but not mushy, adding water if needed. Drain any remaining water.</li><li>In a saucepan over medium heat melt the oil with the ghee, add the cumin seeds and black cardamom 15–20 seconds. Add the onion and cook until golden, then lower the heat and keep stirring 5 minutes.</li><li>Add the garlic and ginger for 30 seconds, stirring constantly. Add the tomato purée, a splash of water, turmeric, salt and chilli powder and fry about 2 minutes until the water has reduced.</li><li>Add the cooked dal and 150 ml of water, lower the heat, cover and cook 8–10 minutes, stirring regularly.</li><li>Serve scattered with chopped chilli, cilantro and julienned ginger.</li></ol><p><em>Serve with flatbread or rice topped with fresh ginger, cilantro and green chilli.</em></p>', CURRENT_TIMESTAMP),
  ('abe1647b-494b-5bb4-9699-70c531af1471', '3b5c8b88-f5ec-5693-804b-730e4c305994', 'ru', 'Гуляш-паста в одной кастрюле с говяжьим фаршем и цельнозерновым пенне', 'Лёгкий гуляш из постного говяжьего фарша, лука, перцев и томатов с копчёной паприкой, в котором прямо в соусе варится цельнозерновая паста пенне.', '<ol><li>В большой кастрюле с крышкой на среднем огне разогрейте масло и 10 минут часто помешивая обжаривайте лук до золотистого цвета. Добавьте фарш, разбивая комочки, затем перцы и готовьте 5 минут.</li><li>Добавьте чеснок, тимьян и паприку, перемешайте. Влейте томаты, томатную пасту и бульон, доведите до кипения, убавьте огонь и варите под крышкой 10 минут.</li><li>Всыпьте пенне, закройте крышкой, доведите до кипения и варите на слабом огне ещё 12 минут до мягкости пасты. Оставьте на 5 минут и подавайте.</li></ol><p><em>Остатки можно охладить и хранить до четырёх дней, разогревая с каплей воды.</em></p>', CURRENT_TIMESTAMP),
  ('35bb9a66-791c-5a91-aa87-822e547bb568', '3b5c8b88-f5ec-5693-804b-730e4c305994', 'en', 'One-pot goulash pasta with beef mince and wholemeal penne', 'A light goulash of lean beef mince, onion, peppers and tomatoes with smoked paprika in which wholemeal penne cooks right in the sauce.', '<ol><li>In a large lidded pan over medium heat heat the oil and fry the onions 10 minutes, stirring often, until golden. Add the mince, breaking up lumps, then the peppers and cook 5 minutes.</li><li>Add the garlic, thyme and paprika and stir. Add the tomatoes, tomato purée and stock, bring to a boil, reduce the heat and simmer covered 10 minutes.</li><li>Add the penne, cover, bring back to the boil and simmer another 12 minutes until the pasta is tender. Leave to stand 5 minutes and serve.</li></ol><p><em>Leftovers keep chilled up to four days; reheat with a splash of water.</em></p>', CURRENT_TIMESTAMP),
  ('0cc2ac71-3467-54d5-88e1-6b124e5a459f', 'fada1aef-2d96-5354-b43c-5ba7cb985ea4', 'ru', 'Боул с лососем, рисом для суши, эдамаме и овощами', 'Тёплый рис для суши с рисовым уксусом, сверху кусочки готового лосося, эдамаме, ленточки моркови, редис и огурец. Заправляется соевым соусом и кунжутом.', '<ol><li>Всыпьте рис в кастрюлю, залейте 200 мл воды, добавьте щепотку соли. Доведите до кипения на сильном огне, убавьте до минимума, накройте крышкой и варите 15 минут.</li><li>Выключите огонь, разрыхлите рис вилкой, закройте крышкой на 5 минут. Он должен впитать всю воду и быть мягким. Вмешайте сахар и рисовый уксус, снова накройте и держите в тепле.</li><li>Варите замороженный эдамаме в слегка кипящей воде 3 минуты, слейте.</li><li>Снимите с моркови ленточки овощечисткой, редис нарежьте тонко, огурец нарежьте брусочками и потом тонкими пластинками. Разломайте лосось руками на кусочки, удаляя кости.</li><li>Разложите тёплый рис по двум мискам, сверху выложите остальные ингредиенты, полейте соевым соусом и посыпьте кунжутом. При желании добавьте имбирь для суши.</li></ol><p><em>Хорошее простое блюдо для готовки вместе с детьми. Можно добавить имбирь для суши.</em></p>', CURRENT_TIMESTAMP),
  ('c391e996-d73a-5725-b29c-b5c74c37972c', 'fada1aef-2d96-5354-b43c-5ba7cb985ea4', 'en', 'Salmon sushi rice bowl with edamame and vegetables', 'Warm seasoned sushi rice topped with flaked cooked salmon, edamame, carrot ribbons, radish and cucumber, drizzled with soy sauce and sesame.', '<ol><li>Tip the rice into a saucepan, cover with 200 ml water and add a pinch of salt. Bring to a boil on high, reduce to very low, cover and cook 15 minutes.</li><li>Turn off the heat, fluff with a fork and leave covered 5 minutes. It should have absorbed all the water and be soft but not mushy. Stir in the sugar and rice vinegar, cover again and keep warm.</li><li>Cook the frozen edamame in gently boiling water 3 minutes and drain.</li><li>Peel the carrot into ribbons, thinly slice the radishes and cut the cucumber into batons then thin slices. Break the salmon into small pieces by hand, removing any bones.</li><li>Divide the warm rice between two bowls, arrange the other ingredients on top, drizzle with soy sauce and sesame seeds, and add sushi ginger if using.</li></ol><p><em>A simple dish for cooking with kids. Add pickled sushi ginger if you like.</em></p>', CURRENT_TIMESTAMP),
  ('d90b67c4-27d8-5821-abb7-840264050886', '41b1b0d4-0dff-5e34-bcf3-d148f4f03e40', 'ru', 'Нут с бататом и томатами в одной кастрюле с чипотле', 'Бюджетное сытное блюдо: батат, нут и томаты с луком, чесноком и каплей пасты чипотле. Хорошо замораживается.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло и 5 минут обжаривайте лук с чесноком до начала размягчения лука.</li><li>Добавьте остальные ингредиенты, влейте 190 мл кипятка, посолите и поперчите. Доведите до кипения, убавьте огонь и варите 25–30 минут, иногда помешивая, пока батат не станет мягким.</li><li>Разложите по 4 мискам, посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подайте с чесночным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('8e71cd1f-2d9e-587b-8e77-b456e0f7811f', '41b1b0d4-0dff-5e34-bcf3-d148f4f03e40', 'en', 'Veggie chickpea and sweet potato one pot with chipotle', 'A budget-friendly hearty pot of sweet potato, chickpeas and tomatoes with onion, garlic and a little chipotle paste. Freezes well.', '<ol><li>Heat the oil in a large pan over medium heat and cook the onion and garlic 5 minutes until the onion starts to soften.</li><li>Stir in the remaining ingredients with 190 ml boiling water and seasoning. Bring to a boil, reduce the heat and simmer 25–30 minutes, stirring occasionally, until the sweet potato is tender.</li><li>Divide between 4 bowls and top with parsley.</li></ol><p><em>Sprinkle with parsley and serve with garlic bread.</em></p>', CURRENT_TIMESTAMP),
  ('359b272e-1c5b-5e8d-9046-41ee95d9eb5e', '6ef6758d-d0f1-5b93-bdd8-18b51f589d13', 'ru', 'Арабский суп с пастой орзо на курином бульоне (шорбет лисан асфур)', 'Лёгкий прозрачный суп из обжаренной на гхи пасты орзо в крепком курином бульоне с кардамоном и лавровым листом.', '<ol><li>В кастрюле на среднем огне растопите гхи, добавьте орзо и перемешайте, обжаривайте 2–3 минуты, часто помешивая, до золотистого цвета.</li><li>Влейте куриный бульон, добавьте кардамон и лавровый лист, доведите до кипения и варите 6–8 минут, пока орзо не станет мягким. Выньте кардамон и лавровый лист, посолите и подавайте горячим.</li></ol><p><em>Хорош как начало трапезы, особенно после поста.</em></p>', CURRENT_TIMESTAMP),
  ('3c3f9ee2-7bd6-572e-bdcc-041320e4c3d2', '6ef6758d-d0f1-5b93-bdd8-18b51f589d13', 'en', 'Shorbet lesan asfour: orzo soup in chicken broth', 'A light soup of orzo toasted in ghee in a good chicken broth with cardamom and bay leaves.', '<ol><li>Melt the ghee in a saucepan over medium heat, add the orzo and stir to coat, toasting 2–3 minutes, stirring often, until golden.</li><li>Pour in the chicken stock, add the cardamom pods and bay leaves and bring to a boil. Simmer 6–8 minutes until the orzo is just tender. Remove the cardamom and bay leaves, season and serve hot.</li></ol><p><em>A gentle starter, especially after fasting.</em></p>', CURRENT_TIMESTAMP),
  ('15c6ee77-b184-5a96-9b7c-89af9c257acb', '4305b3da-1893-5dfe-a6cc-3e84c2e84235', 'ru', 'Густой суп с курицей, рисом и белой фасолью', 'Сытный суп из готовой курицы, риса, фасоли каннеллини и зелени, слегка размятый для густоты. Идеален из остатков курицы.', '<ol><li>В кастрюле на среднем огне разогрейте масло, добавьте лук с щепоткой соли и готовьте 8–10 минут до мягкости. Добавьте чеснок на 2 минуты.</li><li>Влейте бульон, добавьте разобранную курицу, фасоль вместе с жидкостью из банки и рис. Варите 10 минут, затем толкушкой слегка размять часть фасоли и риса, чтобы суп загустел, оставив куски.</li><li>Добавьте зелень и готовьте 5 минут. Посолите, поперчите, посыпьте лимонной цедрой.</li></ol><p><em>Посыпьте лимонной цедрой перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('d962dbb0-4d60-5efd-a608-2e708ff39782', '4305b3da-1893-5dfe-a6cc-3e84c2e84235', 'en', 'Creamy chicken, rice and cannellini bean soup', 'A hearty soup of cooked chicken, rice, cannellini beans and greens, lightly mashed for body. Perfect for leftover chicken.', '<ol><li>Heat the oil in a saucepan over medium heat, add the onion with a generous pinch of salt and cook 8–10 minutes until softening. Add the garlic for 2 minutes.</li><li>Pour in the stock, shredded chicken, cannellini beans with their liquid and the rice. Cook 10 minutes, then roughly mash with a potato masher so some beans and rice break up and thicken the soup.</li><li>Stir in the greens and cook 5 minutes. Season and scatter with lemon zest.</li></ol><p><em>Scatter with lemon zest before serving.</em></p>', CURRENT_TIMESTAMP),
  ('a40f999a-441a-526c-a3cc-7afd7c710439', 'b2c8ca96-ca8c-55be-bd08-49009c9adf7c', 'ru', 'Турецкий рис с вермишелью (шехриели пилав)', 'Рассыпчатый длиннозёрный рис с обжаренной до золотистого цвета вермишелью на курином бульоне со сливочным маслом.', '<ol><li>Промойте рис в большой миске под холодной водой, сливая через сито, до прозрачной воды. Залейте холодной водой и оставьте на 10 минут.</li><li>В средней кастрюле на среднем огне разогрейте масло, добавьте раздробленную вермишель и постоянно помешивайте 2–3 минуты до насыщенного золотистого цвета.</li><li>Снимите с огня, вмешайте сливочное масло до растворения и дайте остыть 1–2 минуты.</li><li>Хорошо слейте воду с риса, добавьте в кастрюлю и перемешайте. Влейте горячий бульон, посолите ½ ч. л. соли, перемешайте и поставьте на сильный огонь.</li><li>Доведите до кипения, убавьте огонь до минимума, накройте крышкой и варите 7–9 минут.</li><li>Снимите с огня, накройте салфеткой и крышкой и оставьте на 10 минут. Разрыхлите вилкой.</li></ol><p><em>Хороший гарнир к мясу, котлетам и тушёным овощам.</em></p>', CURRENT_TIMESTAMP),
  ('8bdf86b3-e472-5cbb-acca-884dcc74e050', 'b2c8ca96-ca8c-55be-bd08-49009c9adf7c', 'en', 'Turkish vermicelli rice pilaf (şehriyeli pilav)', 'Fluffy long-grain rice with golden toasted vermicelli, cooked in chicken stock and butter.', '<ol><li>Rinse the rice in a large bowl under cold running water, draining through a sieve, until the water is clear. Cover with cold water and soak 10 minutes.</li><li>Heat the oil in a medium pan over medium heat, add the crushed vermicelli and stir constantly 2–3 minutes until a rich golden brown.</li><li>Remove from the heat, stir in the butter until melted and cool 1–2 minutes.</li><li>Drain the rice thoroughly, add to the pan and stir. Pour in the hot stock, sprinkle in ½ tsp salt, stir and return to high heat.</li><li>Bring to a boil, reduce the heat to the lowest, cover and simmer 7–9 minutes.</li><li>Remove from the heat, cover with kitchen paper and the lid and rest 10 minutes. Fluff with a fork.</li></ol><p><em>A good side for meat, kebabs and stewed vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('99515816-b5b5-5623-bd23-6f9444203b02', '6837abbe-e55d-51f2-9694-4cd77f273e5c', 'ru', 'Плов с грибами и специями на одном противне', 'Смесь грибов, запечённая с луком, чесноком, зирой, кориандром и чили, затем с рисом басмати на грибном бульоне из сушёных грибов под фольгой.', '<ol><li>Положите сушёные белые грибы и шиитаке, соевый соус и грибной порошок в большой кувшин, залейте 650 мл кипятка и оставьте на 20 минут. Разогрейте духовку до 220 °C.</li><li>Выложите свежие грибы, лук и целые зубчики чеснока на большой противень, посыпьте специями, солью и перцем, полейте маслом. Запекайте 40 минут, перемешав на середине, до золотистого цвета и мягкости.</li><li>Вмешайте в противень рис, залейте грибным бульоном и добавьте размоченные грибы. Накройте фольгой и запекайте 25 минут, затем оставьте под фольгой на 15 минут.</li><li>Посыпьте рубленой кинзой, зелёным луком и по желанию острым маслом.</li></ol><p><em>Посыпьте кинзой и зелёным луком, при желании добавьте острое масло с чили.</em></p>', CURRENT_TIMESTAMP),
  ('04efd414-8b00-507b-9075-18eaff821f09', '6837abbe-e55d-51f2-9694-4cd77f273e5c', 'en', 'One-tray spiced mushroom pilaf with basmati rice', 'Mixed mushrooms roasted with onion, garlic, cumin, coriander and chilli, then baked under foil with basmati rice in a stock infused with dried mushrooms.', '<ol><li>Put the porcini, shiitake, soy sauce and mushroom powder in a large jug, add 650 ml boiling water and leave to infuse 20 minutes. Heat the oven to 220°C (fan).</li><li>Put the fresh mushrooms, onion and whole garlic cloves in a large roasting tray, sprinkle with the spices, salt and pepper and drizzle with oil. Roast 40 minutes, tossing halfway, until golden and softened.</li><li>Stir the rice into the tray, pour in the mushroom stock and add the rehydrated mushrooms. Cover with foil and cook 25 minutes, then stand covered 15 more minutes.</li><li>Sprinkle with chopped cilantro, spring onions and crispy chilli oil if you like.</li></ol><p><em>Top with cilantro and spring onions, plus crispy chilli oil if you like.</em></p>', CURRENT_TIMESTAMP),
  ('fd7ff036-a305-56c5-b00e-0b8225a0e40a', '0f531aef-96f3-5f88-ba95-ea6fc4c55045', 'ru', 'Рагу из белой рыбы с фасолью борлотти, кале и томатами черри', 'Нежное филе белой рыбы на подушке из фасоли борлотти, тёмной листовой капусты и томатов с розмарином и чесноком.', '<ol><li>Срежьте у кале стебли и мелко нарежьте, листья нашинкуйте и отложите. В широкой кастрюле на средне-сильном огне прогрейте масло со стеблями, затем добавьте лук и розмарин и 10–12 минут тушите до мягкости.</li><li>Добавьте чеснок на несколько минут до аромата, влейте томаты. Банку сполосните бульоном и тоже влейте. Доведите до кипения и варите 5–7 минут до уваривания.</li><li>Добавьте фасоль, уложите в рагу рыбу и листья кале. Накройте крышкой и готовьте ещё 7–9 минут до готовности рыбы. Посолите, поперчите и подавайте с хлебом.</li></ol><p><em>Подайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('82ff4990-d4ca-565b-8324-145b487d471b', '0f531aef-96f3-5f88-ba95-ea6fc4c55045', 'en', 'Borlotti bean and white fish tomato stew with kale', 'Tender white fish fillets set on a bed of borlotti beans, dark leafy greens and cherry tomatoes with rosemary and garlic.', '<ol><li>Remove the stalks from the kale and chop finely, shred the leaves and set aside. In a wide pan over medium-high heat warm the oil with the stalks, add the onion and rosemary and cook 10–12 minutes until softened.</li><li>Stir in the garlic for a few minutes until fragrant, then pour in the tomatoes. Swill the can with the stock and add that too. Simmer 5–7 minutes until reduced.</li><li>Stir in the beans, nestle in the fish and kale leaves, cover and cook 7–9 minutes until the fish is cooked through and tender. Season and serve with bread.</li></ol><p><em>Serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('afc06cb7-7b07-59b0-953b-4cb2a4e30c43', '835d70c2-d85a-50a5-aa8a-bd53627d80c4', 'ru', 'Пряный суп-пюре из моркови и красной чечевицы', 'Густой суп из тёртой моркови и красной чечевицы с зирой и чили. Готовится меньше чем за полчаса.', '<ol><li>Разогрейте кастрюлю и 1 минуту обжаривайте на сухую зиру и хлопья чили, пока не начнут подпрыгивать и пахнуть. Половину специй отложите.</li><li>Добавьте оливковое масло, тёртую морковь, чечевицу, горячий овощной бульон и молоко, доведите до кипения.</li><li>Варите 15 минут, пока чечевица не набухнет и не размягчится.</li><li>Пробейте суп погружным блендером или в комбайне до гладкости (или оставьте с кусочками). Посолите и подавайте с йогуртом и отложенными специями.</li></ol><p><em>Подайте с ложкой йогурта и тёплой лепёшкой наан.</em></p>', CURRENT_TIMESTAMP),
  ('d5f298fa-265f-5853-a47e-35bef11888e2', '835d70c2-d85a-50a5-aa8a-bd53627d80c4', 'en', 'Spiced carrot and red lentil soup', 'A thick soup of grated carrots and split red lentils with cumin and chilli, ready in under half an hour.', '<ol><li>Heat a large saucepan and dry-fry the cumin seeds and chilli flakes 1 minute until they jump and smell fragrant. Set half aside.</li><li>Add the olive oil, grated carrots, lentils, hot vegetable stock and milk and bring to a boil.</li><li>Simmer 15 minutes until the lentils have swollen and softened.</li><li>Blend with a stick blender or food processor until smooth (or leave chunky). Season and serve with yogurt and the reserved toasted spices.</li></ol><p><em>Serve with a spoonful of yogurt and warm naan.</em></p>', CURRENT_TIMESTAMP),
  ('787e00fb-ed06-500c-8f3f-ff18af029091', '39cf3b59-c417-5360-b8da-c26b94e36043', 'ru', 'Курица в масляном томатно-сливочном соусе (баттер чикен)', 'Курица, замаринованная в йогурте со специями, обжаренная и протушенная в нежном соусе из томатов и сливок. Одно из самых простых индийских блюд.', '<ol><li>Смешайте йогурт, лимонный сок, куркуму, гарам масалу, чили, зиру, имбирь и чеснок, добавьте нарезанную курицу. Накройте и уберите в холодильник минимум на 3 часа, лучше на ночь.</li><li>Разогрейте на сильном огне в большой сковороде топлёное или сливочное масло. Достаньте курицу из маринада, не стряхивая его, и обжаривайте около 3 минут, пока мясо не побелеет.</li><li>Добавьте томатную пасату, сливки, сахар, соль и остатки маринада. Убавьте огонь и тушите 20 минут, при необходимости досолите.</li><li>Посыпьте кинзой и подавайте с рисом басмати.</li></ol><p><em>Подавайте с рисом басмати и свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('30e8e4b4-a6e9-5977-a01a-1829d6dceea3', '39cf3b59-c417-5360-b8da-c26b94e36043', 'en', 'Butter chicken in tomato cream sauce', 'Chicken marinated in spiced yogurt, seared and simmered in a silky tomato and cream sauce. One of the easiest Indian curries to make.', '<ol><li>Mix the yogurt, lemon juice, turmeric, garam masala, chili, cumin, ginger and garlic, then add the cut-up chicken. Cover and refrigerate at least 3 hours, ideally overnight.</li><li>Heat the ghee or butter over high heat in a large pan. Lift the chicken out of the marinade without wiping it off and cook about 3 minutes until white all over.</li><li>Add the passata, cream, sugar, salt and any remaining marinade. Turn to low and simmer 20 minutes, adjusting the salt.</li><li>Garnish with cilantro and serve with basmati rice.</li></ol><p><em>Serve with basmati rice and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('6f571fa2-1e83-5408-b69c-8f023aacf048', 'fb5e85c8-639a-5c71-822a-9efec3d36543', 'ru', 'Чоу-мейн с курицей, капустой и ростками фасоли', 'Яичная лапша, жареная в воке с курицей, капустой, морковью и ростками в соусе из соевого и устричного соусов. Готовится за 5 минут.', '<ol><li>Для соуса смешайте крахмал с соевым соусом, затем остальные ингредиенты соуса (устричный соус, сахар, кунжутное масло, белый перец).</li><li>Полейте курицу 1 ст. л. соуса, перемешайте и оставьте на 10 минут.</li><li>Приготовьте лапшу по инструкции на упаковке (обычно запарить кипятком на 1 минуту) и слейте воду.</li><li>Разогрейте масло в воке на сильном огне. Обжарьте чеснок 10 секунд, добавьте курицу и жарьте около минуты, пока снаружи не появится румянец.</li><li>Добавьте капусту, морковь и белые части зелёного лука и жарьте 1,5 минуты до увядания капусты.</li><li>Добавьте лапшу, соус и воду и жарьте минуту, постоянно перемешивая. Затем ростки фасоли и остальной зелёный лук на 30 секунд и сразу подавайте.</li></ol><p><em>Подавайте сразу после приготовления.</em></p>', CURRENT_TIMESTAMP),
  ('7d14aac4-d13a-5414-8393-b8ff934e919d', 'fb5e85c8-639a-5c71-822a-9efec3d36543', 'en', 'Chicken chow mein with cabbage and bean sprouts', 'Egg noodles stir-fried in a wok with chicken, cabbage, carrot and bean sprouts in a soy and oyster sauce. Done in 5 minutes of cooking.', '<ol><li>For the sauce mix the cornstarch with the soy sauce, then stir in the remaining sauce ingredients (oyster sauce, sugar, sesame oil, white pepper).</li><li>Pour 1 tbsp of the sauce over the chicken, toss and marinate 10 minutes.</li><li>Prepare the noodles per the package (usually soak in boiling water 1 minute) and drain.</li><li>Heat the oil in a wok on high. Stir-fry the garlic 10 seconds, add the chicken and cook about 1 minute until just tinged brown outside.</li><li>Add the cabbage, carrot and white parts of the green onion and stir-fry 1½ minutes until the cabbage wilts.</li><li>Add the noodles, sauce and water and toss 1 minute. Add the bean sprouts and remaining green onion for 30 seconds, then serve immediately.</li></ol><p><em>Serve immediately.</em></p>', CURRENT_TIMESTAMP),
  ('c0b5b53b-c777-5e75-bd6d-b260b0f8b640', '6aeae389-55da-5d62-bbba-7583b35a36eb', 'ru', 'Бифштексы из говяжьего фарша в грибном соусе', 'Сочные овальные котлеты из говяжьего фарша с тёртым луком и сухарями, дотушенные прямо в соусе из шампиньонов и бульона.', '<ol><li>Насыпьте сухари в миску и натрите на них половину луковицы. Перемешайте и дайте несколько минут набухнуть.</li><li>Добавьте фарш, чеснок, яйцо, кетчуп, крошку бульонного кубика, вустерский соус и горчицу. Месите руками пару минут до пастообразной массы, чтобы котлеты держали форму.</li><li>Разделите на 5 частей и плотно сформируйте овальные котлеты толщиной около 1,5 см.</li><li>Разогрейте масло на сильном огне и обжарьте котлеты по минуте с каждой стороны до румяности (внутри останутся сырыми). Переложите на тарелку.</li><li>В той же сковороде 2 минуты обжарьте лук с чесноком, затем 2–3 минуты грибы до золотистости.</li><li>Убавьте огонь до среднего, растопите масло, всыпьте муку и прогревайте 30 секунд. Постепенно влейте бульон, помешивая, затем воду, горчицу и вустерский соус.</li><li>Верните котлеты с соком с тарелки в соус и готовьте 5–7 минут, пока соус не загустеет. Отложите котлеты, досолите и поперчите соус и полейте им котлеты.</li></ol><p><em>Подавайте с картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('2e5810c4-65f2-5fd9-8568-c5f9707a988a', '6aeae389-55da-5d62-bbba-7583b35a36eb', 'en', 'Salisbury steak with mushroom gravy', 'Juicy oval ground beef patties with grated onion and breadcrumbs, finished in a mushroom and beef broth gravy.', '<ol><li>Put the breadcrumbs in a bowl and grate half the onion over them. Mix and let soak a few minutes.</li><li>Add the beef, garlic, egg, ketchup, crumbled bouillon cube, Worcestershire and mustard. Mix with your hands a couple of minutes until pasty so the patties hold together.</li><li>Divide into 5 and press firmly into oval patties about ¾ inch thick.</li><li>Heat the oil on high and brown the patties about 1 minute per side (they stay raw inside). Move to a plate.</li><li>In the same skillet cook the onion and garlic 2 minutes, then the mushrooms 2-3 minutes until golden.</li><li>Reduce to medium, melt the butter, add the flour and cook 30 seconds. Gradually pour in the broth, stirring, then the water, mustard and Worcestershire.</li><li>Return the patties with their juices and cook 5-7 minutes until the gravy thickens. Move the patties to a plate, season the gravy and spoon it over.</li></ol><p><em>Serve over mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('5eb8579b-f76d-5958-94d8-cb3b5f14cdf6', '12a69484-b1bc-5160-9fa3-814f0199d280', 'ru', 'Куриная грудка в медово-чесночном соусе на сковороде', 'Куриные эскалопы в муке, обжаренные до золотистой корочки и дотушенные в быстром соусе из мёда, чеснока, яблочного уксуса и соевого соуса.', '<ol><li>Разрежьте грудки вдоль пополам, получится 4 эскалопа. Посолите и поперчите с обеих сторон.</li><li>Обваляйте курицу в муке, стряхните лишнюю.</li><li>Растопите на сильном огне почти всё масло (немного оставьте). Жарьте курицу 2–3 минуты до золотистой корочки, переверните и жарьте ещё минуту.</li><li>Убавьте огонь до средне-сильного, освободите место, добавьте чеснок и оставшееся масло. Когда масло растопится, быстро размешайте чеснок.</li><li>Влейте уксус, соевый соус и мёд, встряхните сковороду. Доведите до кипения и варите минуту до лёгкого загустения. Перевернитесь курицу, чтобы соус её покрыл. При необходимости добавьте немного воды.</li><li>Сразу снимите с огня, выложите курицу на тарелки и полейте оставшимся соусом.</li></ol><p><em>Подавайте с рисом или картофельным пюре и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('a84f453e-9825-59f0-9060-be5ac7a4d225', '12a69484-b1bc-5160-9fa3-814f0199d280', 'en', 'Pan-seared honey garlic chicken breast', 'Floured chicken steaks seared golden and finished in a quick honey, garlic, cider vinegar and soy sauce.', '<ol><li>Cut the breasts in half horizontally to make 4 steaks and season both sides with salt and pepper.</li><li>Coat the chicken in flour and shake off the excess.</li><li>Melt most of the butter over high heat, keeping a little back. Cook the chicken 2-3 minutes until golden, turn and cook 1 minute more.</li><li>Lower to medium-high, make room in the pan and add the garlic and remaining butter. Stir the garlic briefly once the butter melts.</li><li>Add the vinegar, soy sauce and honey and swirl. Bring to a simmer for 1 minute until slightly thickened, then turn the chicken to coat, adding a touch of water if the sauce gets too thick.</li><li>Remove from the heat immediately, plate the chicken and drizzle with the remaining sauce.</li></ol><p><em>Serve with rice or mashed potatoes and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('16d9ba25-ca6f-5960-92c9-19c3f157ac1f', 'efd411f1-bb7c-5da6-b31f-b25214566cda', 'ru', 'Куриные бёдра в липкой глазури из кетчупа и соевого соуса, запечённые', 'Куриные бёдра без кожи и костей, запечённые под сладко-солёной глазурью из кетчупа, сахара, соевого соуса и вустерского соуса, с карамелизованной корочкой под грилем.', '<ol><li>Разогрейте духовку до 220 °C. Выстелите форму фольгой и выложите бёдра в один слой.</li><li>Смешайте кетчуп, коричневый сахар, соевый соус, уксус, масло, вустерский соус и чеснок. Нанесите около двух третей глазури на верх каждого бедра, остальное отложите.</li><li>Запекайте 15 минут, затем достаньте форму.</li><li>Включите гриль на максимум, поставьте форму на расстояние около 20 см от нагревателя. Полейте курицу соком из формы и нанесите оставшуюся глазурь.</li><li>Запекайте под грилем 8–10 минут до карамелизации. Дайте постоять несколько минут и подавайте с соком.</li></ol><p><em>Полейте соком со дна формы и подавайте с рисом или пюре.</em></p>', CURRENT_TIMESTAMP),
  ('c3b19958-bfe9-5f9a-a99a-2408d30e047f', 'efd411f1-bb7c-5da6-b31f-b25214566cda', 'en', 'Sticky baked chicken thighs with ketchup and soy glaze', 'Boneless skinless thighs baked under a sweet-savoury glaze of ketchup, brown sugar, soy and Worcestershire, then caramelised under the broiler.', '<ol><li>Heat the oven to 220°C (420°F). Line a pan with foil and lay the thighs flat in one layer.</li><li>Mix the ketchup, brown sugar, soy sauce, vinegar, oil, Worcestershire and garlic. Spoon about two-thirds of the glaze over the top of each thigh and reserve the rest.</li><li>Bake 15 minutes, then remove the pan.</li><li>Switch the grill to high with the shelf about 8 inches from the element. Spoon the pan juices over the chicken, then the remaining glaze.</li><li>Broil 8-10 minutes until caramelised. Stand a few minutes and serve with the pan juices.</li></ol><p><em>Drizzle with the pan juices and serve with rice or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('f7c3a476-08ff-573b-9b9c-981ce0473462', '49f57347-d438-57d0-8f9a-1bf0686a734d', 'ru', 'Куриная грудка в сливочно-грибном соусе с пармезаном', 'Тонкие эскалопы в муке, обжаренные до румяности, под соусом из шампиньонов, белого вина, бульона, сливок и пармезана. Подходит и для гостей.', '<ol><li>Разрежьте каждую грудку вдоль пополам, получится 4 тонких эскалопа.</li><li>Посолите и поперчите куриные ломти с двух сторон, посыпьте мукой и разровняйте пальцами по поверхности.</li><li>Растопите 1 ст. л. масла на среднем огне в большой антипригарной сковороде и обжарьте курицу по 2,5 минуты с каждой стороны до румяности и готовности. Отложите и накройте.</li><li>Добавьте оставшееся масло, прибавьте огонь и жарьте грибы 4 минуты до золотистых краёв, затем чеснок и щепотку соли и перца ещё минуту.</li><li>Влейте вино, оно должно зашипеть. Варите 30 секунд, соскребая румяные частицы со дна, пока запах алкоголя не исчезнет.</li><li>Добавьте бульон и сильно кипятите минуту. Влейте сливки, убавьте огонь до среднего и варите 2 минуты до лёгкого загустения. Добавьте пармезан и приправьте.</li><li>Верните курицу в соус на 30 секунд, посыпьте шнитт-луком и подавайте.</li></ol><p><em>Подавайте с картофельным пюре или рисом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('6e51e8ab-622f-51b9-abe2-9cbdd91b4172', '49f57347-d438-57d0-8f9a-1bf0686a734d', 'en', 'Chicken breast in creamy mushroom and parmesan sauce', 'Thin floured chicken steaks seared golden and served in a sauce of mushrooms, white wine, stock, cream and parmesan. Elegant enough for company.', '<ol><li>Cut each breast in half horizontally to make 4 thin steaks.</li><li>Sprinkle each side with salt and pepper, then with flour, spreading it over the surface with your fingers.</li><li>Melt 1 tbsp butter in a large non-stick pan over medium-high and cook the chicken about 2½ minutes per side until golden and just cooked. Remove and cover to keep warm.</li><li>Add the remaining butter, increase the heat and cook the mushrooms 4 minutes until golden on the edges, then the garlic with a pinch of salt and pepper for a minute.</li><li>Pour in the wine and let it bubble for 30 seconds, scraping the bottom, until mostly evaporated and the alcohol smell is gone.</li><li>Add the stock and boil hard 1 minute, then add the cream, reduce to medium and simmer 2 minutes until slightly thickened. Stir in the parmesan and season.</li><li>Return the chicken to the sauce for 30 seconds, garnish with chives and serve.</li></ol><p><em>Serve with mashed potatoes or rice to soak up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('a9d10d06-1597-5ece-a736-a53596501ad7', '6b8e363c-e914-5c33-af22-f0b4227f7f86', 'ru', 'Свиная вырезка в медово-чесночном соусе, запечённая', 'Свиная вырезка в сухой приправе, обжаренная до золотистой корочки и запечённая в соусе из мёда, чеснока, яблочного уксуса и соевого соуса.', '<ol><li>Разогрейте духовку до 180 °C.</li><li>Смешайте уксус, соевый соус и мёд для соуса. Смешайте сухие приправы и натрите ими вырезку.</li><li>Разогрейте масло в большой жаропрочной сковороде на сильном огне и обжарьте вырезку со всех сторон до золотистого цвета. Почти в конце сдвиньте мясо в сторону и обжарьте чеснок до золотистого.</li><li>Влейте соус, один раз переверните мясо и сразу отправьте сковороду в духовку на 15–18 минут, пока внутри не станет 68 °C.</li><li>Переложите мясо на тарелку, неплотно накройте фольгой на 5 минут. Тем временем уварите соус в сковороде на сильном огне 3 минуты до консистенции жидкого сиропа.</li><li>Верните мясо в соус, переверните, нарежьте толстыми ломтями и подавайте с соусом.</li></ol><p><em>Нарежьте толстыми ломтями и полейте соусом из сковороды.</em></p>', CURRENT_TIMESTAMP),
  ('343f0a55-efa8-5183-a552-17576019a361', '6b8e363c-e914-5c33-af22-f0b4227f7f86', 'en', 'Baked pork tenderloin with honey garlic sauce', 'Pork tenderloin with a spice rub, seared golden and baked in a sauce of honey, garlic, cider vinegar and soy until sticky outside and juicy inside.', '<ol><li>Heat the oven to 180°C (350°F).</li><li>Mix the vinegar, soy sauce and honey for the sauce. Mix the rub and sprinkle it over the pork.</li><li>Heat the oil in a large oven-safe skillet over high heat and sear the pork until golden all over. Near the end push it aside and cook the garlic until golden.</li><li>Pour in the sauce, turn the pork once and transfer to the oven for 15-18 minutes until the center reaches 68°C (155°F).</li><li>Move the pork to a plate and loosely cover with foil for 5 minutes. Meanwhile boil the sauce in the skillet 3 minutes to a thin syrup.</li><li>Return the pork to the sauce and turn to coat, slice thickly and serve with the sauce.</li></ol><p><em>Slice thickly and drizzle with the pan sauce.</em></p>', CURRENT_TIMESTAMP),
  ('8f068dfa-8e4e-504f-b0a7-c2d4eae83192', '338087df-e7e7-5c63-8299-88eeaea27519', 'ru', 'Лосось с мёдом, лаймом и чили на противне с картофелем и стручковой фасолью', 'Золотистый запечённый картофель, лосось в медово-лаймовой глазури и зелёная фасоль на одном противне. Полноценный ужин без лишней посуды.', '<ol><li>Разогрейте духовку до 180 °C и поставьте внутрь большой противень с бортами.</li><li>Смешайте ингредиенты маринада (лаймовый сок, цедру, мёд, соевый соус, чеснок), положите лосось и оставьте на 20 минут, пока жарится картофель.</li><li>Перемешайте картофель с маслом, солью и чесноком, высыпьте на горячий противень и запекайте 20 минут.</li><li>Перемешайте фасоль с оливковым маслом в той же миске, чтобы налипло оставшееся масло.</li><li>Достаньте лосось из маринада (маринад сохраните). Сдвиньте картофель на один край противня, лосось положите посередине кожей вниз, фасоль уложите кучкой в углу. Посолите, поперчите и сбрызните лосось маринадом.</li><li>Запекайте по 5 минут на каждые 1,5 см толщины рыбы (около 10 минут для 3 см). Включите гриль на максимум, полейте остатками маринада и подрумяньте 2 минуты.</li><li>Дайте постоять 3 минуты, посыпьте цедрой лайма и чили и подавайте с дольками лайма.</li></ol><p><em>Подавайте с дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('31e3e63c-519c-5266-bba3-580169144a4f', '338087df-e7e7-5c63-8299-88eeaea27519', 'en', 'One-tray honey chili lime salmon with roast potatoes and green beans', 'Golden roast potatoes, salmon glazed with honey, lime and chili, and green beans, all on one tray for a complete meal.', '<ol><li>Heat the oven to 180°C (350°F) and put a large rimmed baking tray inside.</li><li>Combine the marinade ingredients (lime juice, zest, honey, soy sauce, garlic), add the salmon and set aside 20 minutes while the potatoes roast.</li><li>Toss the potatoes with butter, salt and garlic, tip onto the hot tray and roast 20 minutes.</li><li>Toss the green beans with the olive oil in the same bowl so the residual butter coats them.</li><li>Lift the salmon from the marinade, reserving it. Push the potatoes to one side, set the salmon in the middle skin side down and pile the beans in a corner. Season and drizzle the salmon with marinade.</li><li>Bake 5 minutes per 1.5 cm of thickness (about 10 minutes for 3 cm). Switch to the broiler on max, drizzle with remaining marinade and broil 2 minutes.</li><li>Rest 3 minutes, grate lime zest and chili over the top and serve with lime wedges.</li></ol><p><em>Serve with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('02c42e36-a2f7-577d-81f6-07335b97a049', 'ec9beef0-3f3e-55ae-8711-eb4d61e25b83', 'ru', 'Стручковая фасоль, обжаренная с чесноком', 'Классический гарнир: фасоль, отваренная до яркого зелёного цвета и обжаренная с хрустящим золотистым чесноком.', '<ol><li>Доведите до кипения воду с 1 ч. л. соли. Варите фасоль 4 минуты до ярко-зелёного цвета, слейте и охладите под холодной водой, стряхните воду.</li><li>Разогрейте масло на сковороде на средне-сильном огне, добавьте фасоль и чеснок и перемешивайте 2 минуты, пока чеснок не станет золотистым и хрустящим. Посолите и поперчите.</li><li>Переложите в блюдо и подавайте тёплыми.</li></ol><p><em>Подходит к мясу, рыбе и птице.</em></p>', CURRENT_TIMESTAMP),
  ('17348c66-6894-54a7-9a65-6436632fd731', 'ec9beef0-3f3e-55ae-8711-eb4d61e25b83', 'en', 'Garlic sautéed green beans', 'A classic side: green beans simmered until bright green, then tossed with crisp golden garlic.', '<ol><li>Bring a pot of water to a boil with 1 tsp salt. Cook the beans 4 minutes until bright green, drain and rinse under cold water, then shake off the water.</li><li>Heat the oil in a skillet over medium-high, add the beans and garlic and toss 2 minutes until the garlic is golden and crisp. Add salt and pepper.</li><li>Transfer to a dish and serve warm.</li></ol><p><em>Serve with meat, fish or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('847a61f1-fa37-5fcc-a766-dacaeebd14e5', '6a3ebf98-64d0-54bc-9e23-ea8c43031680', 'ru', 'Хрустящий раздавленный картофель, запечённый с маслом', 'Мелкий картофель сначала отваривают, потом придавливают и запекают с маслом до хрустящей корочки снаружи и нежной мякоти внутри.', '<ol><li>Доведите до кипения воду с 1 ст. л. соли и варите картофель до мягкости: мелкий 20–25 минут, средний около 30. Если кожица лопнет, ничего страшного.</li><li>Разогрейте духовку до 200 °C. Слейте воду и оставьте картофель в дуршлаге на 5 минут, чтобы подсох.</li><li>Выложите на противень и придавите вилкой или толкушкой, не разламывая. Чем тоньше, тем хрустящее, чем толще, тем нежнее внутри. Оставьте на 5 минут подсохнуть.</li><li>Сбрызните растопленным маслом и оливковым маслом, посыпьте солью и перцем.</li><li>Запекайте 45 минут (мелкий) – 55 минут (средний) до глубокого золотистого цвета. Не переворачивайте. Подавайте горячим с петрушкой.</li></ol><p><em>Посыпьте рубленой петрушкой и подавайте горячим как гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('862e1b21-680b-5f88-a64d-babf024533a6', '6a3ebf98-64d0-54bc-9e23-ea8c43031680', 'en', 'Ultra crispy smashed potatoes with butter', 'Small potatoes boiled, smashed flat and baked with butter until crisp outside and fluffy inside.', '<ol><li>Bring a pot of water to a boil with 1 tbsp salt and cook the potatoes until soft, small ones 20-25 minutes, medium about 30. It''s fine if the skins split.</li><li>Heat the oven to 200°C (390°F). Drain the potatoes and let them dry in the colander for about 5 minutes.</li><li>Place on a tray and smash with a fork or masher, keeping each in one piece. Thinner is crisper, thicker is fluffier. Let steam dry 5 minutes.</li><li>Drizzle with melted butter and olive oil and sprinkle with salt and pepper.</li><li>Bake 45 minutes (small) to 55 minutes (medium) until deep golden and crispy; do not flip. Serve hot with parsley.</li></ol><p><em>Sprinkle with chopped parsley and serve hot as a side.</em></p>', CURRENT_TIMESTAMP),
  ('b6a15ef4-eb19-5541-b0b4-0613a5fff099', 'b3832ea5-1530-5d7c-9cf6-0aea2dae82e6', 'ru', 'Запеканка из пасты с курицей в томатно-молочном соусе без сливок', 'Паста с курицей в нежном соусе из молока и томатной пасаты, запечённая с чеддером и моцареллой. Готовится в одной сковороде.', '<ol><li>Разогрейте духовку до 180 °C.</li><li>В глубокой сковороде на среднем огне растопите масло, 5 минут обжарьте лук и чеснок до прозрачности, добавьте муку и готовьте 2 минуты.</li><li>Влейте молоко и взбивайте минуту до загустения. Добавьте пасату, воду, соль и перец, прибавьте огонь и варите около 5 минут, пока соус не начнёт обволакивать ложку (в последние 2 минуты мешайте постоянно).</li><li>Если соус кислит, добавьте 1–2 ч. л. сахара. Всыпьте сырую пасту, курицу и чеддер, перемешайте и варите на плите около минуты.</li><li>Посыпьте моцареллой, накройте крышкой или фольгой и запекайте 10 минут, затем откройте и запекайте ещё 5. Дайте постоять 5 минут и подавайте с базиликом и пармезаном.</li></ol><p><em>Посыпьте свежим базиликом и пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('fbd68de0-260c-525b-822a-6f1b20f6677b', 'b3832ea5-1530-5d7c-9cf6-0aea2dae82e6', 'en', 'One-pot creamy tomato chicken pasta bake with cheddar', 'Pasta and chicken in a silky milk and tomato passata sauce, baked with cheddar and mozzarella. Cooked in one pan with no cream.', '<ol><li>Heat the oven to 180°C (350°F).</li><li>In a deep skillet melt the butter over medium and sauté the onion and garlic 5 minutes until translucent, then add the flour and cook 2 minutes.</li><li>Add the milk and whisk 1 minute until it starts to thicken. Add the passata, water, salt and pepper, turn up the heat and cook about 5 minutes until the sauce coats a spoon, whisking constantly for the last 2.</li><li>If the sauce tastes sour add 1-2 tsp sugar. Mix in the uncooked pasta, chicken and cheddar and cook on the stove 1 minute.</li><li>Scatter with mozzarella, cover with a lid or foil and bake 10 minutes, then uncover and bake 5 more. Rest 5 minutes and serve with basil and parmesan.</li></ol><p><em>Garnish with fresh basil and parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('e5d1a51b-e730-5fee-b91d-6743a5caf774', 'ca2b19f8-398c-5f30-9f6b-5a28c56715b7', 'ru', 'Грибное ризотто с арборио, пармезаном и обжаренными шампиньонами', 'Кремовое ризотто с белым вином, сливками и пармезаном, в которое добавлены золотистые грибы с чесноком и маслом; остальные грибы выкладываются сверху.', '<ol><li>В большой кастрюле с толстым дном на сильном огне растопите 1 ст. л. масла и половину сливочного масла, обжарьте половину грибов до золотистого цвета (около 4 минут). Добавьте половину чеснока и по ¼ ч. л. соли и перца и жарьте ещё 1,5 минуты. Переложите в миску. Так же обжарьте остальные грибы.</li><li>Убавьте огонь до среднего. В той же кастрюле растопите масло, добавьте чеснок и шалот на 2 минуты до прозрачности. Влейте вино и 2 минуты интенсивно уваривайте, соскребая осадок.</li><li>Всыпьте рис и помешивайте минуту до полупрозрачности. Добавляйте тёплый бульон по 1,5 стакана, каждый раз помешивая и дожидаясь, пока впитается (около 3 минут). Повторите, пока весь бульон не будет использован, а рис станет почти готов, но ризотто останется кремовым (около 15 минут).</li><li>Добавьте сливки и масло, энергично перемешайте до кремовости, затем пармезан, соль и перец. Вмешайте половину грибов, попробуйте и приправьте.</li><li>Разложите по тарелкам, сверху выложите разогретые остальные грибы с маслом, посыпьте петрушкой и пармезаном.</li></ol><p><em>Подавайте сразу, посыпав зеленью и пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('47a10e6e-1352-50b4-9d0f-5f7569385dd3', 'ca2b19f8-398c-5f30-9f6b-5a28c56715b7', 'en', 'Mushroom risotto with Arborio rice, parmesan and garlic butter mushrooms', 'Creamy risotto with white wine, cream and parmesan, with golden garlic butter mushrooms stirred in and more piled on top.', '<ol><li>In a large heavy pot over high heat melt 1 tbsp oil and half the butter and cook half the mushrooms until golden (about 4 minutes). Add half the garlic and ¼ tsp each salt and pepper for 1½ minutes. Transfer to a bowl and repeat with the remaining mushrooms.</li><li>Reduce to medium. In the same pot melt the butter, add the garlic and shallot for 2 minutes until translucent. Add the wine and boil rapidly 2 minutes, scraping the base, until mostly evaporated.</li><li>Add the rice and stir 1 minute until semi-translucent. Add about 1½ cups warm stock at a time, stirring now and then until mostly absorbed (about 3 minutes). Repeat until all the stock is used and the rice is just cooked but the risotto still creamy and loose (about 15 minutes).</li><li>Add the cream and butter and stir vigorously until creamy, then the parmesan, salt and pepper. Stir through half of the mushrooms, taste and adjust.</li><li>Spoon into bowls and top with the reheated remaining mushrooms and their buttery juices, then parsley and extra parmesan.</li></ol><p><em>Serve immediately with parsley and extra parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('83a1e84b-a64b-5c40-8f73-49a958bedab8', '2d8589f0-f163-582a-8b4b-224222bcf321', 'ru', 'Запечённая белая рыба в лимонно-сливочном соусе', 'Филе белой рыбы, запечённое в соусе из сливочного масла, сливок, горчицы, лимонного сока и чеснока. Всё готовится в одной форме за 15 минут.', '<ol><li>Разогрейте духовку до 200 °C.</li><li>Выложите рыбу в форму не слишком плотно, посолите и поперчите с обеих сторон.</li><li>В жаропрочной посуде смешайте масло, сливки, чеснок, горчицу, лимонный сок, соль и перец. Прогрейте в микроволновке 2 раза по 30 секунд, перемешивая, до гладкого соуса.</li><li>Посыпьте рыбу шалотом, залейте соусом и запекайте 10–12 минут до готовности рыбы.</li><li>Переложите рыбу на тарелки, полейте соусом, украсьте петрушкой и дольками лимона.</li></ol><p><em>Подайте с отварным картофелем или рисом и зелёными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('5e3badc3-b5ec-559e-a63d-a30f853f4e26', '2d8589f0-f163-582a-8b4b-224222bcf321', 'en', 'Baked white fish in lemon cream sauce', 'White fish fillets baked in a sauce of butter, cream, mustard, lemon juice and garlic, all in one baking dish in 15 minutes.', '<ol><li>Heat the oven to 200°C (390°F).</li><li>Put the fish in a baking dish without crowding and season both sides with salt and pepper.</li><li>In a microwave-safe jug combine the butter, cream, garlic, mustard, lemon juice, salt and pepper. Microwave in two 30-second bursts, stirring between, until melted and smooth.</li><li>Sprinkle the fish with the shallot, pour over the sauce and bake 10–12 minutes until just cooked.</li><li>Plate the fish, spoon over the sauce and garnish with parsley and lemon.</li></ol><p><em>Serve with boiled potatoes or rice and green vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('f4813aca-5140-5272-b719-a2ff8542e304', 'dd5c6d62-b8d2-52f4-80c5-92547bdd92c3', 'ru', 'Лосось в медово-чесночном соусе с соевым соусом', 'Филе лосося, обжаренное до золотистой корочки и политое быстрым соусом из мёда, соевого соуса, уксуса и чеснока. Готовится за 15 минут.', '<ol><li>Достаньте лосось из холодильника за 20 минут до готовки. Обсушите, посолите и поперчите.</li><li>Взбейте мёд, соевый соус, уксус и чеснок для соуса.</li><li>На антипригарной сковороде на среднем и сильном огне с каплей масла жарьте лосось первую сторону 3–4 минуты до золотистой корочки, переверните и жарьте 2–3 минуты.</li><li>Влейте соус и готовьте 1 минуту, пока он слегка не загустеет. Если соус густеет слишком рано, добавьте воды по ложке. Подавайте, полив соусом, посыпав кунжутом и зелёным луком.</li></ol><p><em>Посыпьте кунжутом и зелёным луком, подайте с рисом и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('1cc7a06c-6266-5090-a15c-3fd99bd1426f', 'dd5c6d62-b8d2-52f4-80c5-92547bdd92c3', 'en', 'Honey garlic soy pan-seared salmon', 'Salmon fillets pan-seared golden and glazed with a quick honey, soy, vinegar and garlic sauce. Ready in 15 minutes.', '<ol><li>Take the salmon out of the fridge 20 minutes before cooking. Pat dry and season with salt and pepper.</li><li>Whisk together the honey, soy sauce, vinegar and garlic for the sauce.</li><li>Heat a drizzle of oil in a non-stick pan over medium-high heat and cook the salmon 3–4 minutes on the first side until golden, then turn and cook 2–3 minutes.</li><li>Pour the sauce over and cook 1 minute until it thickens slightly, adding water by the spoonful if it thickens too fast. Serve drizzled with sauce and sprinkled with sesame seeds and green onion.</li></ol><p><em>Sprinkle with sesame seeds and green onion and serve with rice and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('3d0e5832-18f1-5896-8487-313f1847b688', 'aa3f838e-80b6-5c10-abb0-99ab98a2812f', 'ru', 'Рис с курицей по-мексикански в одной сковороде (как энчиладас)', 'Рис с куриной грудкой, томатами, кукурузой, перцем и пряностями для энчиладас, запечённый под сыром. Всё готовится в одной сковороде.', '<ol><li>В большой сковороде на среднем и сильном огне разогрейте масло. Обжарьте куриные стейки по 2 минуты с каждой стороны до готовности, переложите на тарелку.</li><li>При необходимости добавьте масла. Обжарьте лук с чесноком 1,5 минуты, добавьте болгарский перец ещё на 2 минуты.</li><li>Добавьте пассату, бульон, кукурузу, специи, сахар, соль и перец. Доведите до кипения, всыпьте рис, перемешайте, накройте крышкой, убавьте огонь до среднего и слабого и варите 15–18 минут, не помешивая, пока рис не станет мягким и жидкость в основном не впитается.</li><li>Разберите или нарубите курицу, вмешайте в рис, посыпьте сыром и поставьте под гриль до золотистой пузырящейся корочки. Подайте с кинзой.</li></ol><p><em>Посыпьте свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('9ce81b6f-c812-5bef-aedc-5633ee5dc599', 'aa3f838e-80b6-5c10-abb0-99ab98a2812f', 'en', 'One-pot chicken enchilada rice casserole with corn and cheese', 'Rice cooked with chicken breast, tomatoes, corn, bell pepper and enchilada spices, finished under the grill with cheese, all in one skillet.', '<ol><li>Heat the oil in a large skillet over medium-high heat. Cook the chicken 2 minutes per side until cooked and set on a plate.</li><li>Add more oil if dry. Cook the onion and garlic 1½ minutes, then add the bell pepper for 2 more minutes.</li><li>Add the passata, broth, corn, spices, sugar, salt and pepper. Bring to a simmer, add the rice, stir, cover and cook on medium-low 15–18 minutes without stirring until the rice is cooked and most of the liquid is absorbed.</li><li>Shred or chop the chicken, stir through the rice, sprinkle with the cheese and broil until golden and bubbly. Serve with cilantro.</li></ol><p><em>Sprinkle with fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('24279ffb-ac2c-5fa6-b3dc-5430cd65b7fe', '8c757c3f-1112-5766-b9b7-789325b4c00d', 'ru', 'Сливочный орзо с горячим копчёным лососем, горошком и пармезаном', 'Паста орзо, сваренная в соусе из молока, бульона, лука и муки, с зелёным горошком, пармезаном и кусочками копчёного лосося. Готовится за 15 минут.', '<ol><li>В глубокой сковороде или кастрюле на среднем и сильном огне растопите масло. Обжарьте лук с чесноком 2 минуты до прозрачности, всыпьте муку и готовьте минуту.</li><li>Влейте венчиком половину молока, размешайте до гладкости, затем добавьте остальное молоко, бульон, орзо и горошек.</li><li>Доведите до кипения, убавьте огонь до среднего и варите 5 минут, сначала иногда помешивая, а ближе к концу чаще. Снимите с огня: соус ещё жидковат, но дойдёт при подаче.</li><li>Вмешайте пармезан, соль и перец, затем осторожно добавьте лосось кусками. Подавайте сразу, посыпав петрушкой.</li></ol><p><em>Подайте сразу, посыпав петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('8e83a211-21de-5480-8390-c9db980777e1', '8c757c3f-1112-5766-b9b7-789325b4c00d', 'en', 'Creamy hot-smoked salmon orzo with peas and parmesan', 'Orzo cooked in a sauce of milk, stock, onion and flour with green peas, parmesan and chunks of hot-smoked salmon. On the table in 15 minutes.', '<ol><li>Melt the butter in a deep skillet or pot over medium-high heat. Cook the onion and garlic 2 minutes until translucent, add the flour and cook 1 minute.</li><li>Whisk in half the milk until smooth, then add the remaining milk, stock, orzo and peas.</li><li>Bring to a simmer, reduce to medium and cook 5 minutes, stirring occasionally at first and more often toward the end. Take off the heat while still quite saucy; it will reduce as it stands.</li><li>Stir through the parmesan, salt and pepper, then gently fold in the salmon. Serve immediately sprinkled with parsley.</li></ol><p><em>Serve right away with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('d30cd36c-d4da-584a-8562-24f5f2baddcc', 'd0e7a171-47a7-52dd-b8a7-213e2a4fe09b', 'ru', 'Рыбные палочки в духовке с соусом тартар', 'Домашние рыбные палочки в хрустящей панировке из сухарей: запекаются, а не жарятся. Подаются со сливочно-горчичным соусом тартар.', '<ol><li>Разогрейте духовку до 220 °C. Решётку для запекания смажьте маслом и поставьте на противень.</li><li>Нарежьте рыбу брусочками толщиной 2,5–4 см, посолите и поперчите со всех сторон.</li><li>Подготовьте три миски: в первую насыпьте большую часть муки с паприкой, во вторую смешайте оставшуюся муку, майонез, яйца и горчицу.</li><li>Подрумяньте сухари на сковороде со сливочным маслом до золотистого цвета, слегка остудите и переложите в третью миску.</li><li>Обваляйте рыбу сначала в муке, затем в яичной смеси и в сухарях, плотно прижимая панировку руками.</li><li>Выложите палочки на решётку и запекайте 10–12 минут до золотистой корочки.</li><li>Пока рыба печётся, смешайте ингредиенты для соуса, при необходимости подсолите и поперчите. Подайте палочки с соусом.</li></ol><p><em>Подавайте с картофелем или свежим салатом и долькой лимона.</em></p>', CURRENT_TIMESTAMP),
  ('fbfebb8f-40af-5e63-90d3-7649a112cfce', 'd0e7a171-47a7-52dd-b8a7-213e2a4fe09b', 'en', 'Baked fish sticks with tartar sauce', 'Homemade fish sticks in a crunchy toasted-crumb coating, baked instead of fried. Served with a creamy tartar sauce.', '<ol><li>Preheat the oven to 220 °C (425 °F). Oil a wire rack and set it over a baking sheet.</li><li>Cut the fish into strips 2.5–4 cm thick and season them with salt and pepper on all sides.</li><li>Set up three shallow dishes: most of the flour mixed with paprika in the first, and the remaining flour whisked with mayonnaise, eggs and mustard in the second.</li><li>Toast the breadcrumbs with the butter in a skillet until golden, cool them slightly and transfer to the third dish.</li><li>Dredge each strip in flour, then in the egg mixture, then in the crumbs, pressing the coating on firmly.</li><li>Place the sticks on the rack and bake for 10–12 minutes until golden.</li><li>While the fish bakes, mix the sauce ingredients, adjusting the salt and pepper. Serve the sticks with the sauce.</li></ol><p><em>Serve with potatoes or a fresh salad and a lemon wedge.</em></p>', CURRENT_TIMESTAMP),
  ('4d804d17-c157-5cff-854c-d46779b9eca8', '22162a70-5584-5382-b425-195ad80376c4', 'ru', 'Паста со спаржей и грибами в сливочном соусе на одной сковороде', 'Макароны варятся прямо в бульоне вместе с обжаренными грибами и луком, затем соединяются со сливками, пармезаном и спаржей.', '<ol><li>Срежьте жёсткие концы спаржи, нарежьте её кусочками по 5 см. Лук нарубите, свежие грибы нарежьте ломтиками. Сушёные грибы залейте кипятком на 10 минут, откиньте и мелко порубите.</li><li>В большой сковороде разогрейте половину масла, на сильном огне обжарьте спаржу 2–4 минуты, посолите, поперчите и переложите в миску.</li><li>Влейте оставшееся масло, на среднем огне обжарьте лук, свежие и сушёные грибы и чеснок около 8 минут до золотистого цвета.</li><li>Всыпьте сухие макароны, влейте бульон, доведите до кипения, убавьте огонь и варите под крышкой 10–12 минут до готовности пасты.</li><li>Влейте сливки, добавьте пармезан и перемешайте. Выключите огонь, положите спаржу, подавайте с петрушкой.</li></ol><p><em>Посыпьте свежей петрушкой и добавьте ещё немного пармезана.</em></p>', CURRENT_TIMESTAMP),
  ('0a484bea-9bd4-5e09-a873-3738b717d9ba', '22162a70-5584-5382-b425-195ad80376c4', 'en', 'One-pan asparagus and mushroom cream pasta', 'Pasta cooks right in the broth with sautéed mushrooms and onion, then gets finished with cream, Parmesan and tender asparagus.', '<ol><li>Trim the tough ends of the asparagus and cut into 5 cm pieces. Chop the onion and slice the fresh mushrooms. Soak the dried mushrooms in boiling water for 10 minutes, drain and mince.</li><li>Heat half the oil in a large skillet and sauté the asparagus over high heat for 2–4 minutes, seasoning with salt and pepper. Transfer to a bowl.</li><li>Add the remaining oil and cook the onion, fresh and dried mushrooms and garlic over medium heat for about 8 minutes until golden.</li><li>Add the dry pasta and the broth, bring to a boil, then reduce to a simmer and cook covered for 10–12 minutes until the pasta is tender.</li><li>Stir in the cream and Parmesan. Turn off the heat, fold in the asparagus and serve with parsley.</li></ol><p><em>Top with fresh parsley and extra Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('ebfa9e36-2158-5d04-87c2-7426b3b9c75c', '70f30104-39de-53cd-8add-39d508006364', 'ru', 'Бурый рис с морковью и грибами', 'Рассыпчатый бурый рис, запечённый в духовке, с луком, морковью, лесными грибами и тимьяном. Хороший постный гарнир.', '<ol><li>Разогрейте духовку до 190 °C. Насыпьте рис в квадратную форму, добавьте сливочное масло, соль и залейте кипятком.</li><li>Накройте форму крышкой или фольгой и запекайте 1 час. Затем взрыхлите рис вилкой.</li><li>Пока варится рис, залейте сушёные грибы кипятком на 15 минут, затем прокипятите их в небольшой кастрюле около 15 минут. Грибы выньте, а бульон процедите через ткань или бумажный фильтр.</li><li>На сковороде растопите масло, обжарьте лук с солью и перцем около 5 минут до мягкости. Добавьте морковь и чеснок, готовьте ещё 3–5 минут.</li><li>Добавьте веточку тимьяна и грибы, влейте процеженный грибной бульон так, чтобы он покрывал овощи наполовину. Тушите под крышкой на слабом огне, пока грибы не станут мягкими и жидкость не впитается. Выньте тимьян.</li><li>Смешайте овощи с рисом и рубленой петрушкой и подавайте.</li></ol><p><em>Подавайте с запечённой рыбой, курицей или со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('9b26f027-9058-55c7-8297-d3459031d934', '70f30104-39de-53cd-8add-39d508006364', 'en', 'Carrot and mushroom brown rice', 'Fluffy oven-baked brown rice tossed with onion, carrot, wild mushrooms and thyme. A hearty meatless side dish.', '<ol><li>Preheat the oven to 190 °C (375 °F). Spread the rice in a square baking dish, add the butter and salt, and pour the boiling water over it.</li><li>Cover the dish with a lid or foil and bake for 1 hour, then fluff the rice with a fork.</li><li>While the rice bakes, soak the dried mushrooms in boiling water for 15 minutes, then simmer them in a small pot for about 15 minutes. Lift out the mushrooms and strain the liquid through cloth or a paper filter.</li><li>Melt the butter in a skillet and cook the onion with salt and pepper for about 5 minutes until soft. Add the carrot and garlic and cook for another 3–5 minutes.</li><li>Add the thyme sprig and mushrooms, then pour in enough strained mushroom liquid to come halfway up the vegetables. Simmer covered over low heat until the mushrooms are tender and the liquid is absorbed. Remove the thyme.</li><li>Mix the vegetables into the rice with the chopped parsley and serve.</li></ol><p><em>Serve with baked fish or chicken, or with a spoonful of sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('c5fd2fbd-ba93-5b5d-983d-014de5cdc31b', '442e8e0e-6237-5f5d-a463-0ca2fa07b361', 'ru', 'Запечённый картофель с мясом в стиле тако', 'Крупный картофель с хрустящей кожурой, начинённый пряным говяжьим фаршем в томатном соусе. Сверху сыр, сметана, помидоры и зелень.', '<ol><li>Разогрейте духовку до 200 °C. Тщательно вымойте картофель и наколите ножом по 3–4 раза с каждой стороны.</li><li>Натрите картофель маслом и щедро посолите. Выложите на решётку над противнем и запекайте около часа, перевернув на середине.</li><li>Пока картофель печётся, обжарьте лук на масле с солью и перцем до мягкости, добавьте чеснок на 30 секунд.</li><li>Добавьте фарш и специи, жарьте до исчезновения розового цвета. Влейте сальсу, добавьте томатную пасту и готовьте ещё 3–5 минут.</li><li>Достаньте картофель, надрежьте крестом сверху и разомните мякоть вилкой. Положите мясную начинку и сыр, при желании верните в духовку, пока сыр не расплавится.</li><li>Сверху выложите помидоры, сметану, зелень и раздробленные чипсы.</li></ol><p><em>Дополните свежим авокадо, листьями салата или оливками.</em></p>', CURRENT_TIMESTAMP),
  ('3e4d3378-f9fb-57c2-8d94-7d43863ebc07', '442e8e0e-6237-5f5d-a463-0ca2fa07b361', 'en', 'Taco baked potatoes with beef', 'Large baked potatoes with crisp skins, loaded with spiced ground beef in tomato salsa. Topped with cheese, sour cream, tomatoes and herbs.', '<ol><li>Preheat the oven to 200 °C (400 °F). Scrub the potatoes well and prick each one 3–4 times per side with a knife.</li><li>Rub the potatoes with oil and salt them generously. Set them on a rack over a baking sheet and bake for about an hour, turning once halfway.</li><li>Meanwhile, cook the onion in oil with salt and pepper until soft, then add the garlic for 30 seconds.</li><li>Add the ground beef and spices and cook until no longer pink. Stir in the salsa and tomato paste and simmer for another 3–5 minutes.</li><li>Take the potatoes out, cut an X in the top and fluff the flesh with a fork. Spoon in the meat and cheese, and return to the oven if you want the cheese melted.</li><li>Top with tomatoes, sour cream, herbs and crushed chips.</li></ol><p><em>Add avocado, shredded lettuce or olives on top.</em></p>', CURRENT_TIMESTAMP),
  ('d8944716-e962-531f-9866-2d3551b3772c', 'f279a507-115c-5c95-9870-08f781bb5c21', 'ru', 'Курица по-китайски с овощами (маринованная в крахмале)', 'Нежная курица, замаринованная в соевом соусе и крахмале, с брокколи, цветной капустой, морковью и кукурузой в густом соусе.', '<ol><li>Нарежьте куриную грудку тонкими полосками толщиной около 0,5 см. Смешайте с соевым соусом, вином, маслом и крахмалом и оставьте мариноваться.</li><li>Нарежьте все овощи. Для соуса взбейте вместе бульон, соевый соус, мирин, мёд, крахмал и острый соус.</li><li>На сильном огне обжарьте курицу в антипригарной сковороде порциями до золотистого цвета, по 1–2 минуты с первой стороны и до минуты со второй. Переложите в миску.</li><li>Обжарьте морковь, сельдерей и лук с солью, добавив пару ложек воды и накрыв крышкой, 3–5 минут до мягкости. Отложите. Так же по очереди приготовьте брокколи и цветную капусту, добавляя немного воды и накрывая крышкой, чтобы они остались зелёными и плотными.</li><li>Обжарьте чеснок с имбирём 30 секунд, влейте взбитый соус и прогрейте до загустения на среднем огне.</li><li>Верните в сковороду курицу, морковь, сельдерей, лук и кукурузу, прогрейте. В конце добавьте брокколи и цветную капусту, перемешайте и подавайте с рисом.</li></ol><p><em>Подавайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('08283946-70b0-5cd3-8b1f-c9e0a1c8e117', 'f279a507-115c-5c95-9870-08f781bb5c21', 'en', 'Velveted chicken and vegetable stir-fry', 'Tender chicken marinated in soy sauce and cornstarch, stir-fried with broccoli, cauliflower, carrots and baby corn in a glossy sauce.', '<ol><li>Cut the chicken breast into thin strips about 0.5 cm thick. Toss with soy sauce, wine, oil and cornstarch and let it marinate.</li><li>Prepare all the vegetables. Whisk together the broth, soy sauce, mirin, honey, cornstarch and chili sauce for the sauce.</li><li>Sear the chicken in a nonstick skillet over high heat in batches until browned, 1–2 minutes on the first side and up to a minute on the second. Set aside in a bowl.</li><li>Cook the carrots, celery and onion with salt, adding a few spoonfuls of water and covering, for 3–5 minutes until softened. Set aside. Cook the broccoli and then the cauliflower the same way, covered with a little water, so they stay bright and firm.</li><li>Sauté the garlic and ginger for 30 seconds, then pour in the whisked sauce and simmer over medium heat until thickened.</li><li>Return the chicken, carrots, celery, onion and baby corn to the pan and heat through. Fold in the broccoli and cauliflower at the end and serve with rice.</li></ol><p><em>Serve over steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('deb1d3ee-9b13-509c-9d3f-655ac8ec63e2', '45e8e8d5-207e-558e-8f62-de54ad6c8c12', 'ru', 'Белая рыба, обжаренная в муке, с лимонно-луковым соусом', 'Филе белой рыбы в пряной муке и яйце, обжаренное до золотистой корочки. Подаётся с быстрым соусом из шалота, лимона и сливочного масла.', '<ol><li>Смешайте в широкой миске муку, соль, перец, сушёные травы, паприку, чесночный и луковый порошки и кайенский перец. В другой миске слегка взбейте яйца.</li><li>Разогрейте часть масла в антипригарной сковороде на среднем огне.</li><li>Обваляйте рыбу в муке, окуните в яйцо и сразу выложите на сковороду. Жарьте по 3–5 минут с каждой стороны, при необходимости порциями. Переложите на бумажное полотенце.</li><li>Слейте почти всё масло, добавьте шалот и чеснок, посолите, поперчите и готовьте около 3 минут до мягкости.</li><li>Добавьте цедру и сок лимона. Снимите с огня, положите сливочное масло и петрушку, перемешайте и полейте рыбу.</li></ol><p><em>Подавайте с картофельным пюре или рисом и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('042d22be-00a6-5eff-bb62-1a5bc56733bc', '45e8e8d5-207e-558e-8f62-de54ad6c8c12', 'en', 'Pan-fried white fish with lemon shallot butter sauce', 'White fish fillets dredged in seasoned flour and egg, fried until golden. Finished with a quick shallot, lemon and butter sauce.', '<ol><li>Combine the flour, salt, pepper, dried herbs, paprika, garlic and onion powders and cayenne in a wide dish. Lightly beat the eggs in another.</li><li>Heat part of the oil in a nonstick skillet over medium heat.</li><li>Dredge the fish in the seasoned flour, dip it in the egg and place straight into the hot oil. Fry 3–5 minutes per side, in batches if needed. Drain on paper towels.</li><li>Pour off most of the oil, add the shallot and garlic with salt and pepper, and cook for about 3 minutes until tender.</li><li>Add the lemon zest and juice. Off the heat, stir in the butter and parsley and spoon over the fish.</li></ol><p><em>Serve with mashed potatoes or rice and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('ade74bdb-c7f8-5910-aa04-9fc48399aba4', '0657e8df-972a-5f32-98bb-f81a5d6f7100', 'ru', 'Минестроне с фасолью и капустой', 'Густой овощной суп с картофелем, капустой, фасолью, нутом и томатами. Подаётся с пармезаном и свежей зеленью.', '<ol><li>Нарежьте все овощи. В большой кастрюле разогрейте масло и обжарьте лук, морковь, сельдерей и чеснок 5–7 минут на небольшом огне до мягкости, посолите и поперчите.</li><li>Добавьте картофель, капусту, лавровый лист, корку пармезана и сушёные травы, залейте бульоном и водой. Доведите до кипения и варите под крышкой 7–10 минут, пока картофель и капуста почти не размягчатся.</li><li>Выложите промытые фасоль и нут, добавьте томаты вместе с соком. При необходимости долейте воды. Варите на слабом огне ещё 10–15 минут.</li><li>Выньте лавровый лист и корку пармезана, проверьте соль. Подайте суп с тёртым пармезаном и зеленью.</li></ol><p><em>Посыпьте тёртым пармезаном и рубленой зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('1ada080b-3f10-51b9-870f-e259e71925e9', '0657e8df-972a-5f32-98bb-f81a5d6f7100', 'en', 'Minestrone with beans and cabbage', 'A hearty vegetable soup with potatoes, cabbage, beans, chickpeas and tomatoes, finished with Parmesan and fresh herbs.', '<ol><li>Chop all the vegetables. Heat the oil in a large pot and sauté the onion, carrots, celery and garlic over low-medium heat for 5–7 minutes until soft, seasoning with salt and pepper.</li><li>Add the potatoes, cabbage, bay leaves, Parmesan rind and dried herbs, then pour in the stock and water. Bring to a boil and simmer covered for 7–10 minutes until the potatoes and cabbage are almost tender.</li><li>Add the rinsed beans and chickpeas and the tomatoes with their juice. Top up with water if needed and simmer for another 10–15 minutes.</li><li>Remove the bay leaves and Parmesan rind and adjust the seasoning. Serve topped with grated Parmesan and herbs.</li></ol><p><em>Top with grated Parmesan and chopped fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('ec7ce139-3fcb-5add-8d0f-4683944fe6e9', '3e898a50-fca7-5f5e-93d1-957edd20184e', 'ru', 'Крем-суп из брокколи с чеддером и овощами', 'Лёгкий сливочный суп-пюре из брокколи, цветной капусты, кабачка и картофеля с сыром чеддер.', '<ol><li>Нарежьте овощи. Около 1,5 стакана соцветий брокколи отложите для украшения.</li><li>В большой кастрюле разогрейте масло, обжарьте лук, морковь и чеснок с солью и перцем 5–7 минут до мягкости.</li><li>Влейте бульон, добавьте картофель, доведите до кипения и варите 5–7 минут.</li><li>Тем временем на сковороде в капле масла 1–2 минуты обжарьте отложенную брокколи, посолите, влейте немного воды, накройте крышкой и доведите до нужной мягкости.</li><li>Добавьте в суп остальную брокколи, цветную капусту, кабачок и помидоры, при необходимости долейте воды. Варите примерно 15 минут до мягкости овощей.</li><li>Пюрируйте суп порциями в блендере или кухонном комбайне, либо погружным блендером.</li><li>Верните суп в кастрюлю, добавьте сливки и тёртый чеддер, перемешайте и посолите по вкусу. Подайте с обжаренной брокколи.</li></ol><p><em>Украсьте обжаренными соцветиями брокколи.</em></p>', CURRENT_TIMESTAMP),
  ('e3579032-dcca-5ea0-835c-80ae73dbc22e', '3e898a50-fca7-5f5e-93d1-957edd20184e', 'en', 'Broccoli cheddar soup with vegetables', 'A lightened-up creamy puréed soup of broccoli, cauliflower, zucchini and potato with cheddar cheese.', '<ol><li>Prep the vegetables, setting aside about 1½ cups of broccoli florets for garnish.</li><li>Heat the butter in a large pot and cook the onion, carrot and garlic with salt and pepper for 5–7 minutes until tender.</li><li>Pour in the stock, add the potato, bring to a boil and simmer for 5–7 minutes.</li><li>Meanwhile, fry the reserved broccoli in a little oil for 1–2 minutes, season, add a splash of water, cover and cook to the softness you like.</li><li>Add the remaining broccoli, cauliflower, zucchini and tomatoes to the soup, topping up with liquid if needed. Simmer about 15 minutes until all the vegetables are tender.</li><li>Purée the soup in batches in a blender or food processor, or use an immersion blender.</li><li>Return the soup to the pot, stir in the cream and grated cheddar, and season to taste. Serve topped with the sautéed broccoli.</li></ol><p><em>Garnish with sautéed broccoli florets.</em></p>', CURRENT_TIMESTAMP),
  ('07acbfbb-f67c-5a55-95a1-d5a9b82bf794', 'f6b9e1ad-b58a-5553-92cf-8d729ab6b478', 'ru', 'Креветки в кисло-сладком соусе со сладким перцем и горошком', 'Быстрый стир-фрай: маринованные креветки, сахарный горошек и сладкий перец в кисло-сладком соусе с кетчупом и соевым соусом.', '<ol><li>Очистите креветки и удалите кишечную жилку. Смешайте их с мелко рубленым чесноком, имбирём, столовой ложкой масла и половиной чайной ложки соли и оставьте мариноваться не менее 30 минут.</li><li>Пока креветки маринуются, смешайте в миске все ингредиенты соуса.</li><li>Раскалите сковороду с половиной столовой ложки масла почти до дымка, обжарьте горошек и перец с щепоткой соли около 4 минут, пока не начнут подрумяниваться. Переложите в миску.</li><li>В той же сковороде в оставшемся масле обжарьте лук и нарезанный чеснок с солью около минуты. Убавьте огонь до слабого и выложите креветки, помешивая 2 минуты до розового цвета.</li><li>Влейте соус, верните горошек и перец, прибавьте огонь и готовьте минуту, пока соус не загустеет. Досолите по вкусу.</li></ol><p><em>Подавайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('f40dc352-f019-5796-bce1-e8aa16ed50a8', 'f6b9e1ad-b58a-5553-92cf-8d729ab6b478', 'en', 'Sweet and sour shrimp stir fry with snow peas', 'Quick stir fry of marinated shrimp, snow peas and red bell pepper in a tangy-sweet sauce made with ketchup and soy sauce.', '<ol><li>Peel and devein the shrimp. Toss with the minced garlic, ginger, 1 tablespoon oil and ½ teaspoon salt and marinate for at least 30 minutes.</li><li>While the shrimp marinate, whisk all the sauce ingredients together in a bowl.</li><li>Heat ½ tablespoon oil in a nonstick skillet until almost smoking and cook the peas and pepper with a pinch of salt for about 4 minutes until they begin to brown. Remove from the pan.</li><li>In the same pan cook the onion and sliced garlic in the remaining oil with a pinch of salt for about a minute. Lower the heat, add the shrimp and stir for 2 minutes until just pink.</li><li>Pour in the sauce, return the peas and pepper, raise the heat and cook for a minute until thickened. Adjust the salt.</li></ol><p><em>Serve over steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('1c43a1bb-2042-54e7-a493-120bcdcb948e', 'f9d0c404-0886-58ce-b776-67bc665ddf0e', 'ru', 'Паста с креветками и овощами в белом вине', 'Тонкая паста с обжаренными креветками, шалотом, перцем, кабачком и свежими помидорами в чесночном соусе на белом вине.', '<ol><li>Вскипятите большую кастрюлю подсоленной воды и отварите пасту до нужной степени готовности. Перед тем как слить, отлейте около 400 мл воды от пасты.</li><li>Тонко нарежьте шалот, сельдерей, перец и кабачок соломкой, помидоры без семян нарежьте кубиками, измельчите чеснок и зелень. Креветки обсушите, посолите и поперчите.</li><li>В большой сковороде разогрейте половину масла и обжарьте креветки в один слой по 2 минуты с каждой стороны до золотистого цвета, при необходимости порциями. Отложите.</li><li>В той же сковороде на среднем огне обжарьте шалот и сельдерей 3–5 минут, смочите водой от пасты и соскребите со дна румяные кусочки.</li><li>Добавьте перец и готовьте ещё 3 минуты, затем чеснок на 30–60 секунд. Добавьте кабачок, жарьте 2–3 минуты.</li><li>Влейте вино, увеличьте огонь и выпаривайте 3–5 минут, пока соус немного не уменьшится.</li><li>Соедините пасту с креветками и овощами, добавьте помидоры и зелень, перемешайте, разбавляя водой от пасты до нужной консистенции. Подавайте горячей.</li></ol><p><em>Подавайте сразу, посыпав рубленой зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('f4e99d89-d5b1-5647-acb0-5374655a286e', 'f9d0c404-0886-58ce-b776-67bc665ddf0e', 'en', 'Shrimp and vegetable pasta in white wine', 'Angel hair pasta with seared shrimp, shallots, bell pepper, zucchini and fresh tomatoes in a garlicky white wine sauce.', '<ol><li>Boil a large pot of salted water and cook the pasta to your liking. Before draining, reserve about 1½–2 cups of the pasta water.</li><li>Thinly slice the shallots and celery, cut the pepper and zucchini into strips, chop the seeded tomatoes, and mince the garlic and herbs. Pat the shrimp dry and season with salt and pepper.</li><li>Heat half the oil in a large skillet and sear the shrimp in one layer, about 2 minutes per side, in batches if needed. Set aside.</li><li>In the same skillet over medium heat cook the shallots and celery 3–5 minutes, then deglaze with a little pasta water, scraping up the browned bits.</li><li>Add the pepper and cook 3 more minutes, then the garlic for 30–60 seconds. Add the zucchini and cook 2–3 minutes.</li><li>Pour in the wine, raise the heat and reduce for 3–5 minutes until the sauce thickens slightly.</li><li>Toss the pasta with the shrimp and vegetables, tomatoes and herbs, loosening with pasta water as needed. Serve hot.</li></ol><p><em>Serve right away with chopped fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('b96e7a6e-6272-5f7e-b2a7-401cbb8bf67e', 'ecefc7da-e209-5365-9963-73b0975932f3', 'ru', 'Салат с апельсинами и тыквенными семечками', 'Свежий салат из ломтиков апельсина и зелёных листьев с сушёной клюквой, тыквенными семечками и апельсиново-лимонной заправкой.', '<ol><li>Срежьте с апельсинов верх и низ, затем снимите кожуру вместе с белой плёнкой. Нарежьте тонкими кружками. Кожуру можно использовать для сока в заправке.</li><li>Смешайте в банке апельсиновый и лимонный сок, шалот, чеснок, петрушку, соль и перец, затем постепенно добавьте масло и взбейте или встряхните до однородности.</li><li>На большое блюдо выложите апельсины внахлёст, сверху листья салата, клюкву и семечки, можно слоями.</li><li>Полейте салат заправкой и сразу подавайте.</li></ol><p><em>Заправку и дополнительные семечки подайте отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('600d6554-b68e-5d9d-8f28-cf06d2a7bbac', 'ecefc7da-e209-5365-9963-73b0975932f3', 'en', 'Orange salad with pepitas', 'Fresh orange slices layered with salad greens, dried cranberries and pepitas, dressed with orange-lemon vinaigrette.', '<ol><li>Cut the tops and bottoms off the oranges, then slice away the peel and pith. Cut into thin rounds.</li><li>In a jar combine the orange and lemon juice, shallot, garlic, parsley, salt and pepper, then gradually add the olive oil and whisk or shake until emulsified.</li><li>Arrange the orange slices on a large platter, then layer with the salad greens, cranberries and pepitas.</li><li>Drizzle with the vinaigrette and serve immediately.</li></ol><p><em>Serve extra dressing and pepitas on the side.</em></p>', CURRENT_TIMESTAMP),
  ('e286c487-77aa-5c8b-8ff4-41ad6f303eff', 'dccf7937-f3e5-5eb4-8fef-b54fabbfac74', 'ru', 'Овощи, запечённые с бальзамическим уксусом и соевым соусом', 'Брюссельская капуста, стручковая фасоль, брокколи, морковь, кабачок и грибы, запечённые на раскалённом противне с соевым соусом и бальзамиком.', '<ol><li>Разогрейте духовку до 260 °C вместе с глубоким противнем. Нарежьте овощи, стручковую фасоль на минуту опустите в кипящую воду и слейте.</li><li>Смешайте все овощи, посолите и поперчите (учтите, что соевый соус солёный), добавьте масло, соевый соус и бальзамический уксус и перемешайте.</li><li>Выложите половину овощей на раскалённый противень, они сразу зашипят. Снизьте температуру до 230 °C.</li><li>Запекайте 20–30 минут до желаемой мягкости, затем запеките вторую половину овощей. Подавайте горячими.</li></ol><p><em>Подавайте как гарнир к мясу или с рисом как самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('8e9c7b32-f099-5a68-8427-56580a656004', 'dccf7937-f3e5-5eb4-8fef-b54fabbfac74', 'en', 'Balsamic and soy roasted vegetables', 'Brussels sprouts, green beans, broccoli, carrots, zucchini and mushrooms roasted on a hot pan with soy sauce and balsamic vinegar.', '<ol><li>Preheat the oven to 260 °C (500 °F) with a large rimmed baking sheet inside. Prep the vegetables and blanch the green beans in boiling water for about a minute, then drain.</li><li>Toss all the vegetables with salt and pepper (remember the soy sauce is salty), the olive oil, soy sauce and balsamic vinegar.</li><li>Spread half the vegetables on the hot baking sheet, where they will sizzle at once. Reduce the oven to 230 °C (450 °F).</li><li>Roast 20–30 minutes until tender as you like, then roast the second batch. Serve hot.</li></ol><p><em>Serve as a side with meat, or with rice as a light main.</em></p>', CURRENT_TIMESTAMP),
  ('80ccc8e9-709a-5366-879c-6574866df104', '540ca161-826c-52fa-b79e-d2b6d57d09aa', 'ru', 'Огуречный салат с чесноком, укропом и майонезной заправкой', 'Тонкие ломтики огурцов с красным луком и зеленью в пикантной заправке из масла, уксуса, чеснока и немного майонеза. Готовится за 5 минут.', '<ol><li>Смешайте в миске заправку: оливковое масло, уксус, майонез, чеснок, соль и перец.</li><li>Тонко нарежьте огурцы и красный лук, выложите в салатник, добавьте зелень.</li><li>Полейте заправкой и перемешайте.</li></ol><p><em>Хорошо идёт к мясу на гриле, картофелю и жареной рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('fb80d9a3-d598-54fd-ba9b-2149b6473ed2', '540ca161-826c-52fa-b79e-d2b6d57d09aa', 'en', 'Cucumber salad with garlic, dill and creamy dressing', 'Thinly sliced cucumbers with red onion and fresh herbs in a tangy dressing of oil, vinegar, garlic and a little mayonnaise. Ready in 5 minutes.', '<ol><li>Whisk the olive oil, vinegar, mayonnaise, garlic, salt and pepper together in a bowl.</li><li>Thinly slice the cucumbers and red onion and put them in a salad bowl with the chopped herbs.</li><li>Pour the dressing over the salad and toss.</li></ol><p><em>Great with grilled meat, potatoes and fried fish.</em></p>', CURRENT_TIMESTAMP),
  ('0aa5d878-fd12-5230-83dc-37146e841060', '69757934-1fe8-51d0-ac36-64164dcb8817', 'ru', 'Капустный салат коулслоу с морковью', 'Хрустящая белая и краснокочанная капуста с морковью в густой майонезной заправке с мёдом и лимонным соком.', '<ol><li>Мелко нашинкуйте белую и краснокочанную капусту, натрите морковь, мелко нарежьте зелёный лук.</li><li>Смешайте майонез, мёд, сахар, соль, перец и лимонный сок до однородности.</li><li>Перемешайте овощи в миске, влейте заправку и хорошо перемешайте.</li></ol><p><em>Подавайте к котлетам, курице гриль или как начинку для бургеров.</em></p>', CURRENT_TIMESTAMP),
  ('e74be4b9-f85b-5313-80e7-d89f6dad1b10', '69757934-1fe8-51d0-ac36-64164dcb8817', 'en', 'Creamy coleslaw with red and green cabbage', 'Crunchy shredded green and red cabbage with carrot in a thick mayonnaise dressing sweetened with honey and brightened with lemon.', '<ol><li>Finely shred the green and red cabbage, grate the carrot and finely chop the green onion.</li><li>Stir the mayonnaise, honey, sugar, salt, pepper and lemon juice into a smooth dressing.</li><li>Toss the vegetables in a bowl, add the dressing and mix until evenly coated.</li></ol><p><em>Serve alongside burgers, grilled chicken or as a sandwich topping.</em></p>', CURRENT_TIMESTAMP),
  ('5aefbd96-9865-5b61-a0f2-bc3ead9542d4', '6fb46538-573a-50d1-a62c-7d8dddd10804', 'ru', 'Говяжья лопатка с овощами в мультиварке', 'Обжаренный кусок говядины томится в пряном бульоне с картофелем, морковью и грибами, пока мясо не начнёт разваливаться на волокна.', '<ol><li>Посолите и поперчите говядину, посыпьте чесночным порошком со всех сторон.</li><li>Разогрейте масло на большой сковороде и обжарьте мясо по 2–3 минуты с каждой стороны до румяной корочки.</li><li>Переложите мясо в чашу мультиварки, добавьте стебли сельдерея. Смешайте бульон, соль, итальянские травы, муку и чеснок, влейте в чашу.</li><li>Готовьте на высокой мощности 2–3 часа или на низкой около 4 часов. Выньте и выбросьте сельдерей.</li><li>Добавьте картофель, грибы и морковь, залейте жидкостью. Готовьте ещё 2–3 часа на высокой мощности или 3–4 часа на низкой, пока овощи и мясо не станут мягкими.</li><li>Выньте мясо и разберите вилками на волокна. Выложите на блюдо с картофелем, морковью и грибами, полейте соусом.</li></ol><p><em>Разберите мясо вилками, выложите с овощами и полейте соусом из блюда.</em></p>', CURRENT_TIMESTAMP),
  ('71dc1763-079b-5e9e-9ee7-ed4526e0abc6', '6fb46538-573a-50d1-a62c-7d8dddd10804', 'en', 'Slow cooker pot roast with vegetables', 'Seared chuck roast simmers in seasoned beef broth with potatoes, carrots and mushrooms until it falls apart into tender shreds.', '<ol><li>Season the beef on all sides with salt, pepper and garlic powder.</li><li>Heat the oil in a large skillet and sear the beef 2–3 minutes per side until browned and crisp.</li><li>Move the beef to the slow cooker and add the celery sticks. Whisk the broth with salt, Italian herbs, flour and garlic and pour it in.</li><li>Cook on high for 2–3 hours or on low for about 4 hours. Remove and discard the celery.</li><li>Add the potatoes, mushrooms and carrots and submerge them in the liquid. Cook another 2–3 hours on high or 3–4 hours on low until the meat and vegetables are tender.</li><li>Lift out the beef and shred it with two forks. Serve on a platter with the potatoes, carrots and mushrooms and drizzle with some liquid.</li></ol><p><em>Pull the meat apart with forks, plate with the vegetables and spoon the cooking liquid over.</em></p>', CURRENT_TIMESTAMP),
  ('71b9919b-9232-5b27-9ed3-4be74bd38606', '429cedd4-4e69-5655-8387-f084a255e786', 'ru', 'Салат с тунцом и яйцом', 'Консервированный тунец, варёные яйца, маринованный огурец и красный лук под лёгкой майонезной заправкой. Можно готовить заранее.', '<ol><li>Сварите яйца вкрутую около 10 минут, охладите, очистите и нарежьте.</li><li>Слейте жидкость с тунца. Смешайте в миске тунец, яйца, мелко нарезанный огурец и лук, чеснок, майонез и соль.</li><li>Охладите до подачи.</li></ol><p><em>Подавайте на хлебе, в листьях салата или как закуску на крекерах.</em></p>', CURRENT_TIMESTAMP),
  ('aefe55e9-1e3d-507a-8d84-aeefb9c9c611', '429cedd4-4e69-5655-8387-f084a255e786', 'en', 'Tuna and egg salad', 'Canned tuna, hard-boiled eggs, pickle and red onion bound with a light mayonnaise dressing. An easy make-ahead salad.', '<ol><li>Hard-boil the eggs for about 10 minutes, cool, peel and chop them.</li><li>Drain the tuna. Combine it in a bowl with the eggs, finely diced pickle and onion, garlic, mayonnaise and salt.</li><li>Chill until ready to serve.</li></ol><p><em>Serve on bread, in lettuce leaves or with crackers.</em></p>', CURRENT_TIMESTAMP),
  ('bb61e0e1-0b36-5ef7-b948-d88a1e35fb84', '6ec9ea49-a680-59fd-9f9b-8c57b767cece', 'ru', 'Омлет с беконом, грибами и сыром', 'Пышный омлет из четырёх яиц на порцию с хрустящим беконом, обжаренными шампиньонами, помидорами и расплавленным сыром.', '<ol><li>Нарежьте бекон небольшими кусочками и обжарьте до нужной хрустящести. Жир оставьте на сковороде.</li><li>Обжарьте нарезанные шампиньоны в беконном жире до готовности.</li><li>Взбейте яйца со сливками, посолите и поперчите.</li><li>Разогрейте на сковороде половину масла и половину сливочного масла, влейте половину яичной смеси и готовьте на слабом-среднем огне, пока низ не схватится.</li><li>На одну половину омлета выложите половину бекона, грибов, помидоров и сыра, накройте второй половиной. Прикройте крышкой, пока сыр не расплавится. Так же приготовьте второй омлет.</li></ol><p><em>Подавайте горячим с тостами или свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('cc5bd24b-f0f0-58ee-ac0c-440150fbd9fd', '6ec9ea49-a680-59fd-9f9b-8c57b767cece', 'en', 'Bacon, mushroom and cheese omelet', 'A fluffy four-egg omelet filled with crisp bacon, sautéed mushrooms, tomatoes and melted cheese.', '<ol><li>Chop the bacon and cook it to your preferred crispness, leaving the fat in the pan.</li><li>Sauté the sliced mushrooms in the bacon fat until fully cooked.</li><li>Whisk the eggs with the cream and season with salt and pepper.</li><li>Heat half the oil and half the butter in a skillet, pour in half the egg mixture and cook over low-medium heat until the bottom is set.</li><li>Top one half of the omelet with half the bacon, mushrooms, tomatoes and cheese, then fold the other half over. Cover with a lid until the cheese melts. Repeat for the second omelet.</li></ol><p><em>Serve hot with toast or fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('c10f5983-2cbc-50fc-952f-13be599b0383', 'b6cea24d-a7b9-5cd7-a442-6dea641a39b0', 'ru', 'Запеканка из кукурузы с сыром', 'Сытный гарнир на стыке кукурузного хлеба и пудинга: консервированная кукуруза, кукурузная мука, яйца, сметана и сыр, запечённые до золотистой корочки.', '<ol><li>Разогрейте духовку до 180 °C. На большой сковороде на среднем огне разогрейте масло со сливочным и 8 минут обжаривайте лук до мягкости.</li><li>Добавьте чеснок, тимьян и паприку и готовьте 30 секунд до аромата. Всыпьте кукурузу и кукурузную муку, перемешайте и снимите с огня.</li><li>Взбейте яйца, сметану, молоко и сыр, влейте в кукурузную смесь, посолите, поперчите и перемешайте.</li><li>Переложите массу в форму, посыпьте сверху оставшимся сыром и выпекайте 45 минут до золотистой корочки и плотной консистенции. Если сыр темнеет слишком быстро, накройте фольгой.</li><li>Дайте запеканке остыть до комнатной температуры и подавайте.</li></ol><p><em>Дайте остыть до комнатной температуры и подавайте как гарнир к мясу или птице.</em></p>', CURRENT_TIMESTAMP),
  ('c787a133-be13-5a26-b37c-c57433803f69', 'b6cea24d-a7b9-5cd7-a442-6dea641a39b0', 'en', 'Corn casserole with cornmeal and cheese', 'A hearty side between cornbread and a savoury pudding: sweetcorn, cornmeal, eggs, soured cream and cheese baked until golden.', '<ol><li>Heat the oven to 180 °C (160 °C fan). Warm the oil and butter in a large frying pan over medium heat and fry the onion for 8 minutes until soft.</li><li>Add the garlic, thyme and paprika and cook for 30 seconds until fragrant. Stir in the corn and cornmeal, then take off the heat.</li><li>Whisk the eggs, soured cream, milk and cheese together, pour into the corn mixture, season and stir to combine.</li><li>Transfer to a casserole dish, top with extra cheese and bake 45 minutes until golden and set, covering with foil if the cheese browns too fast.</li><li>Leave to cool to room temperature, then serve.</li></ol><p><em>Let it cool to room temperature and serve alongside meat or poultry.</em></p>', CURRENT_TIMESTAMP),
  ('ec280e4b-f046-5229-b45f-2c9bd0d601fb', 'd2de3393-c727-5853-96a5-0504055244bb', 'ru', 'Хумус с пряной бараниной и кедровыми орехами', 'Нежный хумус из нута и тахини, а сверху ароматный фарш из баранины с луком, зирой и корицей и поджаренные кедровые орехи.', '<ol><li>Обжарьте кедровые орехи на сухой сковороде на среднем огне до золотистого цвета и отложите.</li><li>В той же сковороде на масле 2 минуты обжарьте лук до прозрачности. Усильте огонь, добавьте фарш, специи и соль и жарьте, разбивая комочки, около 3 минут до готовности. Накройте и дайте остыть.</li><li>Для хумуса измельчите в блендере или комбайне нут, воду, чеснок, лимонный сок, тахини и масло до гладкости. Попробуйте и посолите по вкусу, добавьте воды до консистенции жидкого кетчупа.</li><li>Размажайте хумус по тарелке ложкой волнами, выложите бараний фарш, посыпьте орехами и петрушкой и полейте маслом.</li></ol><p><em>Подавайте с тёплой питой.</em></p>', CURRENT_TIMESTAMP),
  ('d95a999c-4564-5a43-a037-d12c5852aa3d', 'd2de3393-c727-5853-96a5-0504055244bb', 'en', 'Hummus with spiced lamb and pine nuts', 'Silky chickpea and tahini hummus topped with aromatic lamb mince with onion, cumin and cinnamon and toasted pine nuts.', '<ol><li>Toast the pine nuts in a dry pan over medium-high heat until golden and set aside.</li><li>In the same pan sauté the onion in the oil for 2 minutes until translucent. Turn the heat to high, add the lamb, spices and salt and cook, breaking up the mince, about 3 minutes until browned. Cover and let cool.</li><li>For the hummus, blend the chickpeas, water, garlic, lemon juice, tahini and oil in a food processor or blender until smooth. Season to taste and add water until the texture is like thin ketchup.</li><li>Spread the hummus on a plate in swirls, top with the lamb, pine nuts and parsley, and finish with a drizzle of oil.</li></ol><p><em>Serve with warm pita bread.</em></p>', CURRENT_TIMESTAMP),
  ('cc16ab98-e0c7-5a27-8ff4-1edbecd00f3d', '9cdd406a-1416-588b-9e85-937ed5bfabb2', 'ru', 'Фаршированные перцы по-гречески с говядиной, рисом и нутом', 'Болгарский перец с начинкой из говяжьего фарша, риса, нута, петрушки и душистого перца, запечённый в духовке.', '<ol><li>Замочите рис в воде на 20–30 минут и слейте. В толстостенной кастрюле разогрейте ложку масла и обжарьте лук до золотистого цвета.</li><li>Добавьте фарш и жарьте на средне сильном огне, изредка помешивая, до глубокой румяности. Приправьте солью, перцем, душистым перцем и чесноком, добавьте нут и прогрейте.</li><li>Добавьте петрушку, рис, паприку и томатный соус, влейте воду. Доведите до сильного кипения и уварите жидкость наполовину, затем накройте и готовьте на слабом огне 20 минут, пока рис не станет мягким.</li><li>Пока варится рис, обжарьте перцы с обрезанными верхушками на гриле, сковороде-гриль или обычной сковороде 10–15 минут под крышкой, переворачивая, до мягкости и румяных боков. Разогрейте духовку до 180 °C.</li><li>Поставьте перцы в форму отверстием вверх, влейте на дно бульон или воду и наполните перцы начинкой.</li><li>Накройте форму фольгой, чтобы она не касалась перцев, и запекайте 20–30 минут. Посыпьте петрушкой и подавайте.</li></ol><p><em>Подавайте с цацики и греческим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('cd0e014e-f9d1-5eba-8bf8-5e34bcc534a6', '9cdd406a-1416-588b-9e85-937ed5bfabb2', 'en', 'Greek-style stuffed peppers with beef, rice and chickpeas', 'Bell peppers filled with a seasoned mix of ground beef, rice, chickpeas, parsley and allspice, then baked in the oven.', '<ol><li>Soak the rice in water for 20–30 minutes, then drain. In a heavy pot heat a tablespoon of oil and sauté the onion until golden.</li><li>Add the beef and cook over medium-high heat, stirring now and then, until deeply browned. Season with salt, pepper, allspice and garlic, stir in the chickpeas and cook briefly.</li><li>Add the parsley, rice, paprika and tomato sauce, then pour in the water. Bring to a high simmer and reduce the liquid by half, then cover and cook on low for 20 minutes until the rice is tender.</li><li>While the rice cooks, grill the trimmed peppers on a grill, griddle or skillet over medium-high for 10–15 minutes, covered and turning, until soft and lightly charred. Preheat the oven to 180 °C (350 °F).</li><li>Stand the peppers open side up in a baking dish with the broth or water on the bottom and fill them with the stuffing.</li><li>Cover the dish with foil without letting it touch the peppers and bake 20–30 minutes. Garnish with parsley and serve.</li></ol><p><em>Serve with tzatziki and a Greek salad.</em></p>', CURRENT_TIMESTAMP),
  ('d7384947-a36f-5bb3-995c-de0ec2a085e1', 'dda431b9-5fdf-5dda-8106-07bd126c7235', 'ru', 'Блинчики-конвертики с яйцом, ветчиной и сыром', 'Тонкие блинчики с начинкой из мягкого омлета, ветчины и чеддера, свёрнутые конвертом и обжаренные на масле. Хорошо замораживаются.', '<ol><li>Взбейте в блендере или венчиком воду, молоко, 4 яйца, растопленное масло, муку, сахар и соль до гладкого теста.</li><li>На слабом-среднем огне смажьте сковороду каплей масла, влейте 3–4 ложки теста и распределите по дну. Обжарьте по минуте с каждой стороны, выложите остывать. Остывшие блинчики можно складывать стопкой.</li><li>Взбейте 10 яиц со сливками, приготовьте мягкий пышный омлет на масле, оставьте остыть.</li><li>Смажьте блинчик горчицей, положите в центр щепотку сыра, затем ветчину, яйцо и ещё сыр. Загните верхний край, затем боковые и сверните конвертом. Так же заверните остальные.</li><li>Перед подачей обжарьте конвертики на масле по 3 минуты с каждой стороны на слабом-среднем огне до золотистого цвета. Для заморозки заверните каждый в бумагу и уберите в пакет.</li></ol><p><em>Подавайте с кубиками помидора, авокадо или острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('ec70ef30-43c2-50bb-8143-8f6e65beace5', 'dda431b9-5fdf-5dda-8106-07bd126c7235', 'en', 'Egg, ham and cheese crepe pockets', 'Thin crepes filled with soft scrambled eggs, ham and cheddar, folded into pockets and pan-crisped in butter. They freeze well.', '<ol><li>Blend or whisk the water, milk, 4 eggs, melted butter, flour, sugar and salt into a smooth batter.</li><li>Over medium-low heat, grease a nonstick pan with a dot of butter, pour in 3–4 tablespoons of batter and swirl to coat. Cook about 1 minute per side, then cool; cooled crepes can be stacked.</li><li>Whisk 10 eggs with the cream and scramble in butter until fluffy but still moist; let cool.</li><li>Brush a crepe with mustard, put a pinch of cheese in the center, then ham, eggs and more cheese. Fold over the top, tuck in the sides and roll up. Repeat with the rest.</li><li>To serve, pan-fry the pockets in butter 3 minutes per side over medium-low heat until golden. To freeze, wrap each in parchment and store in a freezer bag.</li></ol><p><em>Serve with diced tomato, avocado or hot sauce.</em></p>', CURRENT_TIMESTAMP),
  ('e147b4c9-32c0-5f22-ac5d-693ccf10e354', 'f9a22e97-bf10-521f-be89-fdd7fb4e29d6', 'ru', 'Куриные наггетсы в духовке с хрустящей панировкой', 'Домашние наггетсы из измельчённой куриной грудки в панировке из кукурузных хлопьев и пармезана. Запекаются, поэтому легче жареных.', '<ol><li>Разогрейте духовку до 190 °C и выстелите противень пергаментом.</li><li>Измельчите кукурузные хлопья в мелкую крошку. Смешайте крошку с тёртым пармезаном в неглубокой миске.</li><li>Пробейте в комбайне или блендере куриное мясо с картофельными хлопьями, водой, чесночной солью и перцем до мелкой массы.</li><li>Мокрыми руками слепите из ложки массы небольшие плоские наггетсы и обваляйте в панировке, слегка прижимая.</li><li>Выложите на противень и выпекайте 15 минут, перевернув на середине, пока не будут готовы. Не пересушивайте. Дайте постоять несколько минут.</li></ol><p><em>Подавайте с овощами и любимым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('fbcc9ad7-9ec8-59b5-abee-8e7a956bd8ce', 'f9a22e97-bf10-521f-be89-fdd7fb4e29d6', 'en', 'Baked chicken nuggets with cornflake-Parmesan crust', 'Homemade nuggets from finely chopped chicken breast coated in crushed corn flakes and Parmesan, baked instead of fried.', '<ol><li>Preheat the oven to 190 °C (375 °F) and line a baking sheet with parchment.</li><li>Pulse the corn flakes into fine crumbs, then mix the crumbs with the grated Parmesan in a shallow bowl.</li><li>Pulse the chicken with the potato flakes, water, garlic salt and pepper in the food processor or blender until finely chopped.</li><li>With wet hands, shape about a tablespoon of the mixture into small flat nuggets and press them into the crumbs.</li><li>Place on the baking sheet and bake 15 minutes, flipping halfway, just until cooked through. Don''t overbake or they will dry out. Rest a few minutes before serving.</li></ol><p><em>Serve with vegetables and a favorite dipping sauce.</em></p>', CURRENT_TIMESTAMP),
  ('689f8da2-081a-57ec-a1cf-14e1545b5b46', '9c89af4b-a51c-5b15-9377-5e529f80ad22', 'ru', 'Креветочные оладьи с сыром и лимонным соусом', 'Мелко нарубленные креветки с моцареллой и петрушкой, обжаренные до румяной корочки. Подаются с чесночно-лимонным майонезным соусом.', '<ol><li>Обсушите креветки бумажными полотенцами и нарежьте кусочками размером с горошину.</li><li>В миске смешайте креветки с моцареллой, яйцом, майонезом, петрушкой, солью и перцем, добавьте муку и перемешайте до кремовой массы.</li><li>Разогрейте на сковороде масло на среднем огне, выкладывайте массу полными ложками, приплюснув до толщины около 1 см. Жарьте примерно по 3 минуты с каждой стороны до золотистых краёв.</li><li>Для соуса размешайте майонез, добавьте лимонную цедру, сок и пропущенный через пресс чеснок. Подавайте к оладьям.</li></ol><p><em>Подавайте по два оладья на порцию с зеленью или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('3694c009-ab3f-52b1-9b57-adec164debfe', '9c89af4b-a51c-5b15-9377-5e529f80ad22', 'en', 'Cheesy shrimp cakes with lemon aioli', 'Finely diced shrimp bound with mozzarella, egg and parsley, pan-fried until golden. Served with a garlicky lemon aioli.', '<ol><li>Pat the shrimp dry and dice them into pea-sized pieces.</li><li>Mix the shrimp with the mozzarella, egg, mayonnaise, parsley, salt and pepper, then stir in the flour until creamy.</li><li>Heat the oil in a nonstick skillet over medium heat and spoon in heaping tablespoons of batter, flattening to about 1 cm thick. Fry about 3 minutes per side until golden.</li><li>For the aioli, stir the mayonnaise with lemon zest, lemon juice and pressed garlic. Serve with the cakes.</li></ol><p><em>Serve two cakes per person with greens or a simple salad.</em></p>', CURRENT_TIMESTAMP),
  ('4755b63a-6f72-5b78-86bc-347932fad4c8', 'b49aef1d-e00b-5d78-a011-ac4cb193a52d', 'ru', 'Тако с запечённой рыбой, капустой и соусом из лайма и чеснока', 'Кукурузные лепёшки с кусочками запечённой рыбы со специями, красной капустой, авокадо и свежей зеленью под кремовым соусом со сметаной и лаймом.', '<ol><li>Застелите противень пергаментом. Смешайте зиру, кайенский перец, соль и чёрный перец и посыпьте рыбу с обеих сторон.</li><li>Сбрызните рыбу оливковым маслом, положите сверху кусочки сливочного масла и запекайте при 190 °C 20–25 минут. По желанию подрумяньте под грилем 3–5 минут.</li><li>Смешайте сметану, майонез, сок лайма, чесночный порошок и острый соус для соуса.</li><li>Нарежьте капусту, авокадо, помидоры и красный лук, нарубите кинзу, натрите сыр.</li><li>Быстро подогрейте тортильи на сухой горячей сковороде. Выложите на каждую рыбу, овощи, кинзу, сыр и соус. Подавайте с лаймом.</li></ol><p><em>Рассчитано по 3 тако на порцию. Подавайте с дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('8abb2dfd-b997-5b7e-a632-c3ebd12dfb70', 'b49aef1d-e00b-5d78-a011-ac4cb193a52d', 'en', 'Baked fish tacos with cabbage and garlic-lime crema', 'Corn tortillas filled with spiced baked white fish, red cabbage, avocado and cilantro, finished with a creamy sour cream and lime sauce.', '<ol><li>Line a baking sheet with parchment. Mix the cumin, cayenne, salt and black pepper and sprinkle over both sides of the fish.</li><li>Drizzle the fish with olive oil, dot with butter and bake at 190 °C (375 °F) for 20–25 minutes. Broil for 3–5 minutes at the end if you like browned edges.</li><li>Whisk the sour cream, mayonnaise, lime juice, garlic powder and hot sauce into the taco sauce.</li><li>Shred the cabbage, slice the avocado, dice the tomatoes and onion, chop the cilantro and grate the cheese.</li><li>Quickly warm the tortillas in a dry hot skillet. Top each with fish, vegetables, cilantro, cheese and sauce, and serve with lime.</li></ol><p><em>Plan on about 3 tacos per serving. Serve with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('3df16dfa-795d-595e-b35a-308979640667', 'e6e2e0ba-a92c-5cab-9b92-bd919c34f5d7', 'ru', 'Свиные отбивные на гриле с лимоном и чесноком', 'Сочные свиные стейки на кости в простом маринаде из оливкового масла, лимонного сока и чеснока, обжаренные на сильном огне до румяной корочки.', '<ol><li>Обсушите мясо бумажным полотенцем.</li><li>Смешайте оливковое масло, лимонный сок, чеснок, соль и перец для маринада.</li><li>Натрите отбивные маринадом, накройте плёнкой и оставьте в холодильнике минимум на час.</li><li>Жарьте на гриле на сильном огне примерно по 5 минут с каждой стороны, пока температура внутри не достигнет 63 °C (время зависит от толщины).</li><li>Дайте мясу отдохнуть 10 минут перед подачей.</li></ol><p><em>Дайте мясу отдохнуть 10 минут и подавайте с овощами или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('15214020-a75e-52a0-8304-300dfa0899ac', 'e6e2e0ba-a92c-5cab-9b92-bd919c34f5d7', 'en', 'Grilled pork chops with lemon garlic marinade', 'Juicy bone-in pork chops marinated in olive oil, lemon juice and garlic, then seared hot for a well-seasoned crust.', '<ol><li>Pat the pork chops dry with paper towels.</li><li>Mix the olive oil, lemon juice, garlic, salt and pepper into a marinade.</li><li>Rub the marinade all over the chops, cover and refrigerate for at least an hour.</li><li>Grill over high heat about 5 minutes per side, until the internal temperature reaches 63 °C (145 °F); time depends on thickness.</li><li>Let the chops rest for 10 minutes before serving.</li></ol><p><em>Let the chops rest for 10 minutes and serve with vegetables or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('cd9f99a9-8947-5bf2-8a51-d78e04f0f2e8', '8a8724ac-80b1-5ddc-89b4-af414dff521f', 'ru', 'Лосось в медово-соевой глазури', 'Филе лосося в тонкой мучной корочке, обжаренное с глазурью из мёда и соевого соуса. Готовится за 20 минут.', '<ol><li>Смешайте мёд с соевым соусом для глазури.</li><li>Нарежьте лосось на 6 порций, посолите и поперчите. Обваляйте с обеих сторон в муке и стряхните лишнее.</li><li>Разогрейте масло в большой антипригарной сковороде на среднем огне. Смажьте верхнюю сторону рыбы половиной глазури и выложите на сковороду глазурью вниз, затем смажьте другую сторону оставшейся глазурью.</li><li>Жарьте по 3 минуты с каждой стороны: глазурь должна карамелизоваться, а рыба стать непрозрачной и легко расслаиваться.</li><li>Сбрызните лаймом и посыпьте шнитт-луком.</li></ol><p><em>Выжмите на рыбу лайм и подавайте с рассыпчатым рисом.</em></p>', CURRENT_TIMESTAMP),
  ('0e4e120e-aa82-5173-95d1-e8b7a9f13312', '8a8724ac-80b1-5ddc-89b4-af414dff521f', 'en', 'Honey soy glazed pan-seared salmon', 'Salmon fillets lightly floured and seared with a sticky honey and soy glaze. On the table in 20 minutes.', '<ol><li>Stir the honey and soy sauce together for the glaze.</li><li>Cut the salmon into 6 portions, season with salt and pepper and dredge both sides in flour, shaking off the excess.</li><li>Heat the oil in a large nonstick skillet over medium heat. Brush the top of each fillet with half the glaze and lay it glaze-side down in the pan, then brush the other side with the remaining glaze.</li><li>Cook 3 minutes per side, until the glaze caramelizes and the fish is opaque and flakes easily.</li><li>Squeeze lime over the top and garnish with chives.</li></ol><p><em>Squeeze lime over the top and serve with fluffy white rice.</em></p>', CURRENT_TIMESTAMP),
  ('1f295180-0eae-50dc-9237-802bc122abc1', 'e583e61f-0a02-5d61-90fa-da020b899145', 'ru', 'Суп с индейкой, лапшой и картофелем', 'Сытный суп из овощей, картофеля и яичной лапши с кусочками варёной индейки. Хороший способ использовать остатки мяса.', '<ol><li>В большой кастрюле разогрейте 2 ст. л. масла на среднем-сильном огне. Обжарьте лук, морковь и сельдерей 5–7 минут до мягкости и золотистого цвета.</li><li>Влейте бульон и воду, добавьте картофель, лавровый лист, соль и перец. Доведите до кипения и варите на среднем огне 10 минут.</li><li>Добавьте лапшу и индейку, варите ещё 5 минут, пока лапша и картофель не станут мягкими. Подсолите по вкусу с учётом солёности бульона.</li><li>Добавьте чеснок и петрушку, сразу снимите с огня, выньте лавровый лист и подавайте.</li></ol><p><em>Посыпьте свежей петрушкой при подаче.</em></p>', CURRENT_TIMESTAMP),
  ('c8c94e15-d1c9-5fd7-bba2-3aeb10531b98', 'e583e61f-0a02-5d61-90fa-da020b899145', 'en', 'Turkey noodle soup with potatoes', 'Hearty soup of sautéed vegetables, potatoes and egg noodles with chunks of cooked turkey. A good use for leftover meat.', '<ol><li>Heat 2 tablespoons of oil in a large pot over medium-high heat. Sauté the onion, carrots and celery for 5–7 minutes until soft and golden.</li><li>Add the stock, water, potatoes, bay leaves, salt and pepper. Bring to a boil and cook at a medium boil for 10 minutes.</li><li>Add the noodles and turkey and cook 5 more minutes until the noodles and potatoes are tender. Adjust the salt, depending on how salty the stock and meat are.</li><li>Stir in the garlic and parsley, remove from the heat at once, discard the bay leaves and serve.</li></ol><p><em>Garnish with fresh parsley.</em></p>', CURRENT_TIMESTAMP),
  ('44a257d2-e5f0-5ff1-b414-331dedcfaa30', '156bce47-bdda-561b-8866-7af0f7f9b2a3', 'ru', 'Куриный суп с бататом и кейлом', 'Сытный суп на курином бульоне с курицей на косточке, бататом, капустой кейл и пряностями. Хорошо согревает и отлично подходит на следующий день.', '<ol><li>Натрите курицу солью и чесночным порошком, отложите, пока готовите овощи.</li><li>В большой кастрюле с антипригарным покрытием на небольшом огне разогрейте масло и 8–10 минут пассеруйте лук и сельдерей до мягкости и золотистого цвета. Добавьте чеснок и сухие специи и прогрейте 2–3 минуты.</li><li>Влейте бульон, добавьте курицу, половинку халапеньо и кинзу. Накройте и варите 20 минут.</li><li>Добавьте батат и кейл и варите ещё 25–30 минут, пока батат не станет мягким, а курица готовой.</li><li>Достаньте курицу, разберите мясо на волокна и выбросьте кости. Верните мясо в суп, уберите халапеньо и разлейте суп по тарелкам.</li></ol><p><em>Подавайте горячим, при желании добавьте свежую кинзу.</em></p>', CURRENT_TIMESTAMP),
  ('93c522cd-5b4b-5ec1-a771-80ef0ef5dc73', '156bce47-bdda-561b-8866-7af0f7f9b2a3', 'en', 'Chicken sweet potato and kale soup', 'A hearty chicken broth soup with bone-in chicken, sweet potato, kale and warm spices. Even better the next day.', '<ol><li>Season the chicken with the salt and garlic powder and set aside while you prep the vegetables.</li><li>In a large nonstick pot over medium-low heat warm the oil and cook the onion and celery for 8–10 minutes until soft and golden. Add the garlic and dried spices and cook 2–3 minutes.</li><li>Pour in the broth and add the chicken, halved jalapeño and cilantro. Cover and cook for 20 minutes.</li><li>Add the sweet potato and kale and cook another 25–30 minutes until the sweet potato is tender and the chicken is cooked through.</li><li>Lift out the chicken, shred the meat and discard the bones. Return it to the pot, remove the jalapeño and ladle into bowls.</li></ol><p><em>Serve hot, with extra fresh cilantro if you like.</em></p>', CURRENT_TIMESTAMP),
  ('b3abe45e-8be9-5ebf-9d31-8ecb7a781c3e', 'cf05e9c4-478c-5d7e-b9b1-48fd9b3336db', 'ru', 'Суп из чёрной фасоли с овощами', 'Густой суп из сухой чёрной фасоли с зажаркой из лука, моркови, перца и петрушки, с зирой и орегано. Часть супа пробивают блендером для густоты.', '<ol><li>Промойте фасоль и замочите в воде (около 2 литров) на ночь. Для быстрого способа доведите фасоль до кипения, снимите с огня и оставьте под крышкой на 1 час.</li><li>Слейте воду, залейте фасоль 2 литрами свежей холодной воды. Добавьте половинку перца, небольшую луковицу, 2 зубчика чеснока и лавровый лист, доведите до кипения, убавьте огонь и варите под крышкой около 1,5 часов, иногда помешивая, до мягкости фасоли. Овощи затем выбросьте.</li><li>Пока варится фасоль, на сковороде на слабом огне разогрейте масло и 5–6 минут пассеруйте лук, петрушку, морковь, перец и чеснок с половиной чайной ложки соли и перцем.</li><li>Через час варки добавьте зажарку в суп, затем вино, уксус, зиру, орегано и бульонный кубик, при необходимости долейте воды. Накройте и варите на слабом огне ещё около 30 минут.</li><li>Выньте лавровый лист и на 10 секунд пробейте часть супа погружным блендером, либо переложите около 3 стаканов супа в блендер и верните в кастрюлю. Досолите по вкусу.</li><li>Разлейте суп по тарелкам и украсьте сметаной, авокадо, зелёным луком или кинзой.</li></ol><p><em>Подавайте со сметаной, авокадо и зелёным луком или кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('87eb333b-62df-52da-9b28-c6585b1c2c8a', 'cf05e9c4-478c-5d7e-b9b1-48fd9b3336db', 'en', 'Black bean soup from scratch', 'A thick soup of dried black beans with a sautéed onion, carrot, pepper and parsley base, cumin and oregano, partly blended for body.', '<ol><li>Rinse the beans and soak them in about 2 litres of water overnight. For a quicker method, bring the beans to a boil, remove from the heat and leave covered for 1 hour.</li><li>Drain and discard the soaking water and cover the beans with 2 litres of fresh cold water. Add the halved pepper, small onion, 2 garlic cloves and bay leaves, bring to a boil, then simmer covered about 1½ hours until the beans are tender. Discard the vegetables.</li><li>Meanwhile, heat the oil in a skillet on medium-low and sauté the onion, parsley, carrots, pepper and garlic with ½ teaspoon salt and pepper for 5–6 minutes until soft.</li><li>After the beans have simmered an hour, add the sautéed vegetables, then the wine, vinegar, cumin, oregano and bouillon, topping up with water if needed. Cover and simmer about 30 more minutes.</li><li>Remove the bay leaves and blend part of the soup with an immersion blender for about 10 seconds, or blend about 3 cups in a blender and return to the pot. Adjust the seasoning.</li><li>Ladle into bowls and top with sour cream, avocado, scallions or cilantro.</li></ol><p><em>Top with sour cream, avocado and scallions or cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('135957f0-781c-5c4d-9ec6-c1b87b8e05d0', '0514b70c-7a83-506f-b703-a0aee84f714e', 'ru', 'Греческий салат с нутом и фетой', 'Свежий салат с нутом, огурцами, помидорами черри, сладким перцем, оливками и фетой под лимонно-оливковой заправкой.', '<ol><li>Разложите по 4 контейнерам или мискам нут, огурец, перец, помидоры, оливки и красный лук, сверху выложите толстые ломтики феты.</li><li>Смешайте венчиком лимонный сок, оливковое масло, орегано, соль и перец.</li><li>Подайте салат, добавив к каждой порции около полутора столовых ложек заправки.</li></ol><p><em>Хорошо подходит для готовки на несколько дней: заправку храните отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('81270d26-0449-5e08-8af5-eb03af8cff80', '0514b70c-7a83-506f-b703-a0aee84f714e', 'en', 'Greek chickpea salad with feta and olives', 'Fresh salad of chickpeas, cucumber, cherry tomatoes, bell pepper, olives and feta with a lemon and olive oil dressing.', '<ol><li>Divide the chickpeas, cucumber, pepper, tomatoes, olives and red onion among 4 containers or bowls and top with thick slices of feta.</li><li>Whisk together the lemon juice, olive oil, oregano, salt and pepper.</li><li>Serve each salad with about 1½ tablespoons of dressing.</li></ol><p><em>Great for meal prep: keep the dressing separate until serving.</em></p>', CURRENT_TIMESTAMP),
  ('61af4380-691e-5940-9223-7d4000e49fac', '4fae4b3b-98aa-5662-84dc-609e69305da5', 'ru', 'Салат из чечевицы с овощами и лимонным соком', 'Сытный салат из варёной коричневой чечевицы с морковью, сельдереем, красным перцем, луком и петрушкой под лимонной заправкой. Подаётся холодным или комнатной температуры.', '<ol><li>В кастрюле соедините чечевицу, лавровый лист и тимьян, залейте водой так, чтобы она покрывала чечевицу на 2–3 см.</li><li>Доведите до кипения, убавьте огонь и варите без крышки 16–20 минут, пока чечевица не станет мягкой, но не развариться. Слейте воду, выньте лавровый лист и тимьян.</li><li>Переложите чечевицу в большую миску, добавьте морковь, сельдерей, перец, лук, петрушку, чеснок, лимонный сок, масло, соль и перец. Перемешайте и подайте охлаждённым или тёплым.</li></ol><p><em>Хорошо готовить заранее и брать с собой на обед.</em></p>', CURRENT_TIMESTAMP),
  ('c5c5600e-7ce4-5474-bda8-9e4ed53763c5', '4fae4b3b-98aa-5662-84dc-609e69305da5', 'en', 'Lentil salad with carrot, celery and parsley', 'Cooked brown lentils tossed with carrot, celery, red pepper, onion and parsley in a lemon dressing, served chilled or at room temperature.', '<ol><li>Combine the lentils, bay leaf and thyme in a saucepan and add water to cover by 1 inch.</li><li>Bring to a boil, reduce the heat and simmer uncovered 16–20 minutes until the lentils are tender but not mushy. Drain and discard the bay leaf and thyme.</li><li>Transfer the lentils to a large bowl, add the carrots, celery, pepper, onion, parsley, garlic, lemon juice, oil, salt and pepper, toss and serve chilled or at room temperature.</li></ol><p><em>Make ahead and pack for lunch.</em></p>', CURRENT_TIMESTAMP),
  ('67b6e852-5af9-5822-a470-505c315e22dd', '52a0ffc9-63b4-59b3-94f8-da6650e4bd54', 'ru', 'Бурый рис со шпинатом и чесноком', 'Рассыпчатый бурый рис, обжаренный в сливочном масле, с чесночным шпинатом. Простой гарнир.', '<ol><li>В небольшой кастрюле с толстым дном растопите сливочное масло, добавьте рис и обжаривайте около минуты.</li><li>Влейте воду, добавьте бульонный кубик, доведите до кипения на сильном огне. Накройте крышкой и варите около 45 минут, пока вся вода не впитается.</li><li>Пока варится рис, прогрейте масло на сковороде, обжарьте чеснок до золотистого цвета. Добавьте размороженный отжатый шпинат и щепотку соли и тушите, перемешивая, около 4 минут.</li><li>Смешайте рис со шпинатом и подавайте, посыпав тёртым сыром, если хотите.</li></ol><p><em>Посыпьте тёртым пекорино или другим твёрдым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('c1b2974e-d6f3-579e-aec5-d9eae5270e0d', '52a0ffc9-63b4-59b3-94f8-da6650e4bd54', 'en', 'Brown rice with spinach and garlic', 'Fluffy brown rice toasted in butter and tossed with garlicky sautéed spinach. A simple side dish.', '<ol><li>Melt the butter in a small heavy pot, add the rice and toast for about a minute.</li><li>Pour in the water, add the bouillon cube and bring to a boil over high heat. Cover and cook about 45 minutes until all the water is absorbed.</li><li>Meanwhile heat the olive oil in a sauté pan and cook the garlic until golden. Add the thawed, squeezed spinach and a pinch of salt and stir for about 4 minutes.</li><li>Toss the rice with the spinach and serve, topped with grated cheese if you like.</li></ol><p><em>Sprinkle with grated Pecorino Romano or another hard cheese.</em></p>', CURRENT_TIMESTAMP),
  ('7725b938-5caf-5951-b781-33301a1d1487', 'e8af36b7-d4c3-55d7-8801-0d16a6957c34', 'ru', 'Куриные голени в горчично-лаймовом соусе', 'Голени без кожи в соусе из дижонской горчицы, лайма, чеснока и майонеза, запечённые до золотистой корочки. Очень быстрый ужин.', '<ol><li>Разогрейте духовку до 200 °C. Снимите с голеней кожу и весь жир, обсушите, переложите в большую миску и посолите.</li><li>Смешайте горчицу, майонез, сок и цедру лайма, чеснок и перец. Полейте курицу соусом и хорошо перемешайте.</li><li>Слегка смажьте маслом противень, чтобы курица без кожи не прилипла, выложите голени в один слой и посыпьте сушёной петрушкой.</li><li>Запекайте около 35 минут до готовности, затем 2–3 минуты подержите под грилем до золотистой корочки.</li></ol><p><em>Подавайте с рисом или картофелем и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e3032bd7-d68e-59a9-bf52-a95189df156c', 'e8af36b7-d4c3-55d7-8801-0d16a6957c34', 'en', 'Baked Dijon and lime chicken drumsticks', 'Skinless drumsticks coated in a Dijon, lime, garlic and mayonnaise sauce and baked until golden. An easy weeknight dinner.', '<ol><li>Preheat the oven to 200 °C (400 °F). Remove the skin and any fat from the drumsticks, pat dry, place in a large bowl and season with salt.</li><li>Mix the Dijon, mayonnaise, lime juice and zest, garlic and pepper. Pour over the chicken and toss to coat.</li><li>Lightly grease a baking pan so the skinless chicken doesn''t stick, arrange the drumsticks in a single layer and sprinkle with dried parsley.</li><li>Bake about 35 minutes until cooked through, then broil for 2–3 minutes until golden.</li></ol><p><em>Serve with rice or potatoes and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('7fdbaa86-1384-56d6-ae08-612eab7996ac', '5b3375f7-4cf1-511d-a4c0-6550b91f8f6a', 'ru', 'Курица с «рисом» из цветной капусты и брокколи и сыром', 'Быстрый ужин на сковороде: кубики куриной грудки, рубленые цветная капуста и брокколи вместо риса и расплавленный чеддер. Мало углеводов.', '<ol><li>Нарежьте курицу мелкими кубиками, приправьте половиной нормы соли, чесночным порошком и перцем.</li><li>Раскалите большую антипригарную сковороду, влейте половину масла и обжарьте половину курицы по 2–3 минуты с каждой стороны до румяности и готовности. Отложите, затем так же обжарьте остальное.</li><li>Влейте остаток масла, на среднем огне 2 минуты пассеруйте лук с чесноком. Добавьте замороженную смесь рубленых овощей, остаток соли и перец и прогревайте 5–6 минут.</li><li>Верните курицу в сковороду, посыпьте сыром, накройте крышкой и на слабом огне растопите сыр 2–3 минуты.</li></ol><p><em>Подайте сразу, пока сыр горячий.</em></p>', CURRENT_TIMESTAMP),
  ('5155959c-02c4-548d-b65c-8d5527e4f01f', '5b3375f7-4cf1-511d-a4c0-6550b91f8f6a', 'en', 'Skillet cheesy chicken with cauliflower and broccoli rice', 'A fast one-pan dinner of diced chicken breast, riced cauliflower and broccoli and melted cheddar. Low in carbs.', '<ol><li>Dice the chicken small and season with half the salt, the garlic powder and pepper.</li><li>Heat a large nonstick skillet on high, add half the oil and brown half the chicken 2–3 minutes per side until cooked through. Set aside and repeat with the rest.</li><li>Add the remaining oil and cook the onion and garlic over medium heat for 2 minutes. Add the frozen riced vegetables, the remaining salt and pepper and cook 5–6 minutes until heated through.</li><li>Return the chicken to the pan, top with the cheese, cover and melt on low heat for 2–3 minutes.</li></ol><p><em>Serve right away while the cheese is hot.</em></p>', CURRENT_TIMESTAMP),
  ('bac34ef6-a678-51c3-bca7-bdfdf7276e7a', '08897898-2f5b-54ce-9cf1-8d90d9f28591', 'ru', 'Свиные отбивные в сухарях с лаймом', 'Тонкие свиные отбивные в сухарной панировке с белком, обжаренные на сковороде до золотистой корочки. Подаются с долькой лайма.', '<ol><li>Посолите отбивные и посыпьте чесночным порошком.</li><li>Насыпьте сухари на мелкую тарелку. В другой посуде взбейте белки с паприкой.</li><li>Обмакните каждую отбивную в белок, затем обваляйте в сухарях, стряхнув лишнее.</li><li>Разогрейте на большой антипригарной сковороде масло на среднем огне и обжаривайте отбивные примерно по 6 минут с каждой стороны до золотистой корочки и готовности внутри. Для воздушного гриля сбрызните маслом и готовьте при 200 °C по 4 минуты с каждой стороны.</li><li>Подавайте с дольками лайма.</li></ol><p><em>Подавайте с картофелем или рисом и свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('84f8c0c4-12a0-507d-84bf-70be658cb10d', '08897898-2f5b-54ce-9cf1-8d90d9f28591', 'en', 'Breaded pork cutlets with lime', 'Thin lean pork cutlets coated in egg white and breadcrumbs and pan-fried until golden, served with lime wedges.', '<ol><li>Season the cutlets with salt and garlic powder.</li><li>Put the breadcrumbs on a shallow plate. In another bowl beat the egg whites with the paprika.</li><li>Dip each cutlet in the egg white, then in the breadcrumbs, shaking off the excess.</li><li>Heat the oil in a large nonstick pan over medium heat and fry the cutlets about 6 minutes per side until golden and no longer pink inside. For the air fryer, spray with oil and cook at 200 °C (400 °F) for 4 minutes per side.</li><li>Serve with lime wedges.</li></ol><p><em>Serve with potatoes or rice and a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('492aa2d9-9d4e-5e26-84b4-c0e0fc578ea8', '7aa1623e-8eed-5f7a-8234-6e0b1c27088d', 'ru', 'Рагу из нута и батата со шпинатом', 'Постное густое рагу с нутом, бататом, луком и мягкими специями: зирой, кориандром, имбирём и корицей. Томится в мультиварке, кастрюле или скороварке.', '<ol><li>Нарежьте лук и батат кубиками, нут промойте и откиньте.</li><li>Выложите в мультиварку всё, кроме шпината: лук, нут, батат, чеснок, соль, перец, специи и бульон.</li><li>Готовьте на низкой мощности 6–7 часов или на высокой 3–4 часа. Можно варить на плите на слабом огне 35–40 минут, помешивая, или 8 минут под высоким давлением.</li><li>Добавьте шпинат, перемешайте и прогрейте ещё 15 минут на высокой мощности (на плите достаточно 2 минут), пока он не опадёт.</li></ol><p><em>Подавайте с лепёшкой или рисом и ложкой йогурта по желанию.</em></p>', CURRENT_TIMESTAMP),
  ('43122e9a-139b-5b81-a909-7945bf1fa9af', '7aa1623e-8eed-5f7a-8234-6e0b1c27088d', 'en', 'Chickpea and sweet potato stew with spinach', 'A hearty vegan stew of chickpeas, sweet potato and onion with warm cumin, coriander, ginger and cinnamon. Cooks in a slow cooker, pot or pressure cooker.', '<ol><li>Chop the onion and sweet potato and drain and rinse the chickpeas.</li><li>Put everything except the spinach in the slow cooker: onion, chickpeas, sweet potato, garlic, salt, pepper, spices and broth.</li><li>Cook on low for 6–7 hours or on high for 3–4 hours. Alternatively simmer on the stove over medium-low heat 35–40 minutes, stirring, or pressure cook 8 minutes.</li><li>Stir in the spinach and cook 15 more minutes on high (just 2 minutes on the stove) until wilted.</li></ol><p><em>Serve with flatbread or rice and a spoon of yogurt if you like.</em></p>', CURRENT_TIMESTAMP),
  ('3b61a117-241e-5db7-9c7d-e8bd25f30b82', '7887780a-2488-53ff-82a4-6eb5f1748ad1', 'ru', 'Свиные отбивные в медово-горчичной панировке в аэрогриле', 'Постные свиные отбивные маринуются в дижонской горчице с мёдом, обваливаются в сухарях и запекаются до хрустящей корочки.', '<ol><li>Посолите отбивные с обеих сторон.</li><li>Смешайте горчицу с мёдом, обмажьте мясо и оставьте мариноваться минимум на 4 часа или на ночь в холодильнике.</li><li>Насыпьте сухари в широкую миску. Не стряхивая горчицу с мяса, хорошо обваляйте каждую отбивную в сухарях.</li><li>Слегка смажьте маслом корзину аэрогриля, выложите отбивные (при необходимости порциями) и сбрызните сверху маслом.</li><li>Готовьте при 200 °C 10–12 минут, перевернув на середине и сбрызнув маслом обе стороны. Без аэрогриля запекайте в духовке при 220 °C 20–25 минут.</li></ol><p><em>Подавайте с овощным гарниром или салатом из свежей капусты.</em></p>', CURRENT_TIMESTAMP),
  ('0308efaf-e0da-5cca-b4ba-fb7de0d1f455', '7887780a-2488-53ff-82a4-6eb5f1748ad1', 'en', 'Honey-mustard panko pork chops in the air fryer', 'Lean boneless pork chops marinated in Dijon and honey, coated in panko and air fried until crisp. Can also be baked in the oven.', '<ol><li>Season the pork chops on both sides with salt.</li><li>Stir the mustard and honey together, coat the chops and marinate at least 4 hours or overnight in the fridge.</li><li>Put the panko in a wide dish. Leaving the mustard on the meat, press each chop firmly into the crumbs.</li><li>Lightly oil the air fryer basket, add the chops in batches if needed and spritz the tops with oil.</li><li>Air fry at 200 °C (400 °F) for 10–12 minutes, turning halfway and spritzing both sides. Without an air fryer, bake at 220 °C (425 °F) for 20–25 minutes.</li></ol><p><em>Serve with a vegetable side or a crunchy cabbage slaw.</em></p>', CURRENT_TIMESTAMP),
  ('6b5bd676-6d01-565c-85b3-66d27c43cc55', '9369473c-54a1-5f96-a161-6ecc9280936f', 'ru', 'Куриная грудка, фаршированная шпинатом, фетой и вялеными томатами', 'Куриные грудки с карманом, набитым шпинатом, вялеными томатами, фетой и травами. Сначала обжариваются на сковороде, затем доходят в духовке.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>Острым ножом сделайте в каждой грудке глубокий карман сбоку, не прорезая насквозь.</li><li>Посолите грудки, посыпьте паприкой и чесночным порошком с обеих сторон.</li><li>Смешайте вяленые томаты, шпинат, фету, шалот, чеснок, базилик, сухари, орегано, пармезан, оставшуюся соль и половину ложки масла.</li><li>Разделите начинку между грудками и заполните карманы, при необходимости заколите зубочистками.</li><li>Разогрейте жаропрочную сковороду, добавьте оставшееся масло и обжарьте грудки по 2–3 минуты с каждой стороны до румяности.</li><li>Переставьте сковороду в духовку на 12–15 минут, пока температура внутри не достигнет 74 °C. Накройте фольгой на 5 минут, выньте зубочистки.</li></ol><p><em>Дайте мясу отдохнуть под фольгой 5 минут и подавайте с запечёнными овощами.</em></p>', CURRENT_TIMESTAMP),
  ('447baef2-ba16-5744-b683-fed6e8474e10', '9369473c-54a1-5f96-a161-6ecc9280936f', 'en', 'Spinach, feta and sun-dried tomato stuffed chicken breast', 'Chicken breasts with a pocket filled with spinach, sun-dried tomatoes, feta and herbs, seared in a skillet and finished in the oven.', '<ol><li>Preheat the oven to 220 °C (425 °F).</li><li>With a sharp knife, cut a deep pocket into the side of each breast without cutting all the way through.</li><li>Season both sides of the chicken with salt, paprika and garlic powder.</li><li>Mix the sun-dried tomatoes, spinach, feta, shallot, garlic, basil, breadcrumbs, oregano, Parmesan, remaining salt and half a tablespoon of olive oil.</li><li>Divide the filling between the breasts and stuff the pockets, securing with toothpicks if needed.</li><li>Heat an oven-safe skillet, add the remaining oil and sear the breasts 2–3 minutes on each side until browned.</li><li>Transfer the skillet to the oven for 12–15 minutes, until the chicken reaches 74 °C (165 °F). Tent with foil for 5 minutes and remove the toothpicks.</li></ol><p><em>Rest under foil for 5 minutes and serve with roasted vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('94b5af2d-13ff-50cd-804e-e87b88b69075', '36152b5b-38b0-58ac-8930-1c10811cc285', 'ru', 'Картофельный салат со стручковой фасолью и бальзамической заправкой', 'Тёплый картофель и отварная фасоль с маслинами и зелёным луком под заправкой из бальзамического уксуса и оливкового масла. Без майонеза.', '<ol><li>Сварите картофель, нарезанный кубиками по 2,5 см, в подсоленной воде 25–30 минут до мягкости. Слейте воду.</li><li>В другой кастрюле отварите стручковую фасоль 6–7 минут до мягкости, слейте воду и быстро охладите под холодной водой, чтобы она не переварилась.</li><li>В большой миске смешайте бальзамический уксус, масло, соль и перец.</li><li>Добавьте картофель, фасоль, зелёный лук и маслины, хорошо перемешайте и подавайте при комнатной температуре.</li></ol><p><em>Подавайте тёплым или комнатной температуры как гарнир к мясу и рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('91629941-f205-57f7-8eac-f6d8ff425142', '36152b5b-38b0-58ac-8930-1c10811cc285', 'en', 'Potato and green bean salad with balsamic dressing', 'Tender potatoes and green beans tossed with black olives and scallions in a balsamic and olive oil dressing. A mayo-free potato salad.', '<ol><li>Boil the 2.5 cm potato chunks in salted water for 25–30 minutes until tender, then drain.</li><li>In a second pot boil the green beans for 6–7 minutes until tender, then drain and rinse quickly under cold water to stop the cooking.</li><li>Whisk the balsamic vinegar, oil, salt and pepper in a large bowl.</li><li>Add the potatoes, green beans, scallions and olives, toss well and serve at room temperature.</li></ol><p><em>Serve at room temperature as a side for meat or fish.</em></p>', CURRENT_TIMESTAMP),
  ('5a587bdc-5053-5d11-90d3-1895febed23c', '2d6c1648-0d62-5b2b-ae75-5e8ae12f2cbf', 'ru', 'Запечённые крокеты из индейки и картофеля', 'Крокеты из мелко нарубленной варёной индейки, картофельного пюре, жареного лука и чеснока в сухарях. Запекаются, а не жарятся.', '<ol><li>Сварите картофель до мягкости и разомните его с четвертью стакана бульона, солью и перцем.</li><li>Обжарьте на масле на слабом огне чеснок и лук, добавьте петрушку, соль и перец и готовьте 2–3 минуты до мягкости.</li><li>Добавьте мелко нарубленную индейку и оставшийся бульон, перемешайте и выключите огонь. Соедините с картофельным пюре, перемешайте руками и при необходимости досолите.</li><li>Разогрейте духовку до 230 °C. Сформуйте из четверти стакана массы крокеты, обмакните в яйцо, затем в сухари.</li><li>Выложите на противень с пергаментом, обильно сбрызните маслом и выпекайте около 15 минут до золотистого цвета.</li></ol><p><em>Подавайте по 3 крокета на порцию с овощами или соусом.</em></p>', CURRENT_TIMESTAMP),
  ('da34b1ce-30b0-5835-adc2-2b911b949ab5', '2d6c1648-0d62-5b2b-ae75-5e8ae12f2cbf', 'en', 'Baked turkey and potato croquettes', 'Croquettes of finely chopped cooked turkey, mashed potatoes, sautéed onion and garlic, breaded and baked instead of fried.', '<ol><li>Boil the potatoes until tender and mash them with a quarter cup of broth, salt and pepper.</li><li>Sauté the garlic and onion in oil over low heat, add the parsley, salt and pepper, and cook 2–3 minutes until soft.</li><li>Add the finely chopped turkey and the remaining broth, stir and turn off the heat. Mix with the mashed potatoes by hand and adjust the salt.</li><li>Preheat the oven to 230 °C (450 °F). Shape about 1/4 cup of mixture into croquettes, dip in the egg and then in the breadcrumbs.</li><li>Set on a parchment-lined baking sheet, spray generously with oil and bake about 15 minutes until golden.</li></ol><p><em>Serve three croquettes per person with vegetables or a sauce.</em></p>', CURRENT_TIMESTAMP),
  ('3056d305-e18d-58c8-9f79-9d2e650548c5', '0bffbb58-5fc7-5cde-9290-deadf09290db', 'ru', 'Лёгкий крем-суп из кабачков', 'Нежный суп-пюре из кабачков с луком и чесноком на курином бульоне, с ложкой сметаны для кремовости. Готовится за 25 минут.', '<ol><li>Соедините в большой кастрюле бульон, лук, чеснок и кабачки, нарезанные крупными кусками, и доведите до кипения на среднем огне.</li><li>Убавьте огонь, накройте крышкой и варите около 20 минут до мягкости овощей.</li><li>Снимите с огня, пробейте суп погружным блендером, добавьте сметану и пробейте ещё раз до гладкости.</li><li>Посолите и поперчите по вкусу и подавайте горячим.</li></ol><p><em>Посыпьте тёртым пармезаном, если хотите.</em></p>', CURRENT_TIMESTAMP),
  ('c22708f3-1906-5268-b25e-a0c1fbd51263', '0bffbb58-5fc7-5cde-9290-deadf09290db', 'en', 'Light cream of zucchini soup', 'A silky puréed soup of zucchini, onion and garlic in broth, enriched with a spoonful of sour cream. Ready in 25 minutes.', '<ol><li>Combine the broth, onion, garlic and chunked zucchini in a large pot over medium heat and bring to a boil.</li><li>Reduce the heat, cover and simmer about 20 minutes until the vegetables are tender.</li><li>Remove from the heat, purée with an immersion blender, add the sour cream and blend again until smooth.</li><li>Season with salt and pepper to taste and serve hot.</li></ol><p><em>Top with grated Parmesan if desired.</em></p>', CURRENT_TIMESTAMP),
  ('6c31bfce-bc32-59e1-b67e-10ad5a38b96f', '5273cc6b-dd93-5e7e-a42f-ccfb6e6c0ad4', 'ru', 'Томатный суп с нутом и розмарином', 'Густой суп из нута и измельчённых томатов с морковью, сельдереем, розмарином и шпинатом. Готовится на плите или в мультиварке.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло и 6–8 минут пассеруйте лук, морковь, сельдерей и чеснок до мягкости и аромата.</li><li>Добавьте бульон, томаты, нут, пармезан и перец, затем розмарин, лавровый лист и базилик. Накройте и варите на слабом огне 30 минут. В мультиварке готовьте на низком режиме около 6 часов.</li><li>Добавьте шпинат и дайте ему завять около 2 минут. Выньте розмарин и лавровый лист, посолите по вкусу и подавайте с пармезаном.</li></ol><p><em>Посыпьте тёртым пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('4ae83662-3c24-5295-b256-16d1d874d756', '5273cc6b-dd93-5e7e-a42f-ccfb6e6c0ad4', 'en', 'Chickpea tomato soup with rosemary', 'A hearty soup of chickpeas and crushed tomatoes with carrot, celery, rosemary and spinach. Cooks on the stovetop or in a slow cooker.', '<ol><li>Heat the oil in a large pot over medium heat and sauté the onion, carrot, celery and garlic for 6–8 minutes until tender and fragrant.</li><li>Add the broth, tomatoes, chickpeas, Parmesan and pepper, then the rosemary, bay leaves and basil. Cover and simmer on low for 30 minutes, or cook in a slow cooker on low for about 6 hours.</li><li>Stir in the spinach and let it wilt for about 2 minutes. Remove the rosemary and bay leaves, season to taste and serve with extra Parmesan.</li></ol><p><em>Top with grated Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('bfe66d39-2feb-597d-9525-2181ef99f697', '1e476a29-5ec3-5901-b987-6b20de41477f', 'ru', 'Орзо с кабачком и помидором', 'Быстрый гарнир из пасты орзо с обжаренным чесноком, кабачком и помидором, с тёртым пармезаном. Подойдёт к курице или свинине.', '<ol><li>Отварите орзо в подсоленной воде до состояния аль денте. Отлейте около 120 мл воды от пасты, затем слейте орзо в дуршлаг.</li><li>Влейте в ту же кастрюлю масло, обжарьте чеснок минуту до аромата, добавьте кабачок и помидор, посолите и поперчите. Тушите 3–4 минуты до мягкости.</li><li>Верните орзо в кастрюлю, перемешайте, при необходимости добавьте отложенную воду. Посыпьте тёртым сыром и перемешайте.</li></ol><p><em>Удвойте порцию, чтобы подать как самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('cfcea0bd-bd8d-5b41-a9e0-9d56f40abc9f', '1e476a29-5ec3-5901-b987-6b20de41477f', 'en', 'Orzo with zucchini and tomato', 'A quick side of orzo pasta tossed with sautéed garlic, zucchini and tomato and finished with grated Parmesan. Goes well with chicken or pork.', '<ol><li>Cook the orzo in salted water until al dente. Reserve about ½ cup of the cooking water, then drain.</li><li>Add the oil to the same pot, sauté the garlic for a minute, then add the zucchini and tomato, season and cook 3–4 minutes until tender.</li><li>Add the orzo back, stir together, loosening with some reserved water if needed, then stir in the grated cheese.</li></ol><p><em>Double the portion to serve as a main dish.</em></p>', CURRENT_TIMESTAMP),
  ('944839fe-0506-54c7-aa42-4cc74a667694', '66418011-5456-52cc-adc2-578122b15a95', 'ru', 'Паста э фаджоли: суп с фасолью и пастой', 'Итальянский густой суп с белой фасолью, томатами, овощами, пряными травами и мелкой пастой. Часть фасоли взбивается в пюре для густоты.', '<ol><li>В большой кастрюле с толстым дном на среднем огне обжарьте в оливковом масле лук и чеснок.</li><li>Взбейте фасоль вместе с жидкостью из банки и стаканом воды в блендере почти до гладкости.</li><li>Добавьте в кастрюлю пюре из фасоли, томатный соус, сельдерей, морковь, бульон, базилик, лавровый лист, петрушку, орегано, соль и перец. Влейте воду, доведите до кипения и варите под крышкой 20 минут, иногда помешивая.</li><li>Добавьте пасту и варите без крышки до состояния аль денте по инструкции на упаковке. Разлейте по тарелкам, посыпьте сыром и базиликом.</li></ol><p><em>Подавайте с тёртым пармезаном и свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('18c1d955-539f-5276-835a-d8068a4fbcb2', '66418011-5456-52cc-adc2-578122b15a95', 'en', 'Pasta fagioli (pasta and bean soup)', 'A thick Italian soup of white beans, tomatoes, vegetables, herbs and small pasta, thickened with blended beans.', '<ol><li>In a large heavy pot or Dutch oven, sauté the onion and garlic in the olive oil over medium heat.</li><li>Blend the beans with their liquid and 1 cup of water in a blender until almost smooth.</li><li>Add the bean purée, tomato sauce, celery, carrot, broth, basil, bay leaf, parsley, oregano, salt and pepper to the pot. Add water, bring to a boil and simmer covered for 20 minutes, stirring occasionally.</li><li>Add the pasta and cook uncovered until al dente according to the package. Ladle into bowls and top with cheese and basil.</li></ol><p><em>Serve with grated Parmesan and fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('f6fd6b5d-1e2b-55b7-a55a-74b68efd7dbb', '959aceb0-6857-55b2-97ef-13d268ca2709', 'ru', 'Креветки в красном тайском карри с кокосовым молоком', 'Быстрое блюдо на одной сковороде: креветки в соусе из красной пасты карри, кокосового молока и рыбного соуса. Баланс сладкого, острого и солёного.', '<ol><li>В большой антипригарной сковороде разогрейте масло на среднем огне, обжарьте белые части зелёного лука с пастой карри 1 минуту до аромата.</li><li>Добавьте креветки и чеснок, посолите и обжаривайте около 2 минут до лёгкой румяности.</li><li>Влейте кокосовое молоко и рыбный соус, перемешайте и тушите 2–3 минуты, пока креветки не приготовятся.</li><li>Снимите с огня, добавьте зелёные части лука и кинзу. Подавайте с рисом и дольками лайма.</li></ol><p><em>Подавайте с рисом или рисом из цветной капусты и дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('7a9581a8-ff29-5c6a-bb6b-2c15d7b6fe71', '959aceb0-6857-55b2-97ef-13d268ca2709', 'en', 'Red Thai coconut curry shrimp', 'A quick one-pan dish of shrimp in a sauce of red curry paste, coconut milk and fish sauce, balancing sweet, spicy and savoury flavours.', '<ol><li>Heat the oil in a large nonstick skillet over medium-high heat and sauté the scallion whites with the curry paste for 1 minute until fragrant.</li><li>Add the shrimp and garlic, season with a few pinches of salt and brown for about 2 minutes.</li><li>Pour in the coconut milk and fish sauce, stir and simmer 2–3 minutes until the shrimp are cooked through.</li><li>Remove from the heat and stir in the scallion greens and cilantro. Serve over rice with lime wedges.</li></ol><p><em>Serve over rice or cauliflower rice with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('2dd85ea8-ec14-511d-8814-2aecb6b0e0c8', 'eadee6d7-4fbe-50a9-ac08-8226e2bfbde7', 'ru', 'Рваная говядина в скороварке с чипотле и пряностями', 'Говяжья лопатка, томлёная под давлением с томатами, чесноком, орегано, зирой и острым чипотле. Мясо разбирается на волокна и подходит для тако, риса и энчилад.', '<ol><li>Нарежьте мясо на 4 куска, посолите и поперчите.</li><li>Включите режим «Жарка», смажьте чашу маслом и обжарьте мясо в два приёма по 3 минуты с каждой стороны. Переложите на тарелку.</li><li>Обжарьте лук и чеснок 2 минуты, добавьте орегано, зиру и лавровый лист ещё на минуту. Выключите нагрев.</li><li>Добавьте томаты без жидкости, рубленый чипотле с соусом, бульон и корицу. Верните мясо с соком в чашу.</li><li>Закройте крышку и готовьте под высоким давлением 60 минут. Дайте давлению сбрасываться само 10 минут, затем выпустите остаток пара.</li><li>Выньте мясо, снимите жир с жидкости и процедите её, отжав овощи. Верните жидкость в чашу и уварите вдвое (до 350 мл) в режиме жарки, около 10 минут.</li><li>Разберите мясо вилками на волокна, при необходимости досолите и подавайте с соусом.</li></ol><p><em>Подавайте с рисом, в лепёшках или как начинку для запеканок, смочив мясо соусом.</em></p>', CURRENT_TIMESTAMP),
  ('e0165659-8503-5dad-96a4-17e96480c573', 'eadee6d7-4fbe-50a9-ac08-8226e2bfbde7', 'en', 'Pressure cooker braised spiced beef with chipotle', 'Beef chuck braised under pressure with tomatoes, garlic, oregano, cumin and smoky chipotle, then shredded. Great for rice bowls, tacos and enchiladas.', '<ol><li>Cut the beef into 4 pieces and season with salt and pepper.</li><li>Set the cooker to sauté, oil the pot and brown the beef in two batches, about 3 minutes per side. Transfer to a plate.</li><li>Cook the onion and garlic for 2 minutes, then add the oregano, cumin and bay leaves for another minute. Turn off the heat.</li><li>Add the drained tomatoes, chopped chipotle and adobo sauce, broth and cinnamon stick, then return the beef and its juices to the pot.</li><li>Seal the lid and pressure cook on high for 60 minutes. Let the pressure release naturally for 10 minutes, then vent the rest.</li><li>Remove the beef, skim the fat off the liquid and strain it, pressing the solids. Return it to the pot and boil down by half (to about 350 ml), about 10 minutes.</li><li>Shred the beef with two forks, adjust the salt and serve with the sauce.</li></ol><p><em>Serve over rice, in tortillas or in casseroles, moistened with the reduced sauce.</em></p>', CURRENT_TIMESTAMP),
  ('4546a0da-0347-5c11-a054-77dedf3a20c1', '04fee7f2-37be-5313-bcb8-923e2cf27927', 'ru', 'Томатный суп с говяжьим фаршем и мелкой пастой', 'Сытный суп из говяжьего фарша, томатов, лука, моркови и сельдерея с мелкой пастой. Готовится в скороварке, мультиварке или на плите.', '<ol><li>Разогрейте чашу до сильного нагрева, обжарьте фарш с солью, разбивая на мелкие кусочки, до коричневого цвета.</li><li>Добавьте лук, сельдерей и морковь и готовьте 3–4 минуты.</li><li>Влейте томаты и бульон, положите лавровый лист. Готовьте под давлением в режиме «Суп» около 35 минут (на плите под крышкой на слабом огне 1–1,5 часа).</li><li>Сбросьте давление, добавьте пасту, перемешайте и готовьте ещё 6 минут (на плите по инструкции на упаковке). Выньте лавровый лист и подавайте.</li></ol><p><em>Посыпьте тёртым пармезаном и добавьте ложку рикотты.</em></p>', CURRENT_TIMESTAMP),
  ('06a20ead-b551-5444-986f-f55469144d9b', '04fee7f2-37be-5313-bcb8-923e2cf27927', 'en', 'Beef, tomato and tiny pasta soup', 'A comforting soup of ground beef, tomatoes, onion, carrot and celery with tiny pasta. Made in a pressure cooker, slow cooker or on the stove.', '<ol><li>Heat the pot until very hot and brown the ground beef with the salt, breaking it into small pieces.</li><li>Add the onion, celery and carrot and cook for 3–4 minutes.</li><li>Add the tomatoes, stock and bay leaves. Pressure cook on the soup setting for about 35 minutes (or simmer covered on the stove 1–1.5 hours).</li><li>Release the pressure, stir in the pasta and cook another 6 minutes (or per package directions on the stove). Remove the bay leaves and serve.</li></ol><p><em>Top with grated Parmesan and a spoonful of ricotta.</em></p>', CURRENT_TIMESTAMP),
  ('5c06da3f-f41a-5404-a395-2e4585003967', 'd2a84b0b-a845-544c-b282-c25a0df14b6c', 'ru', 'Запечённые фрикадельки из индейки с имбирём и соусом из лайма и кунжута', 'Нежные фрикадельки из фарша индейки с имбирём, зелёным луком и кинзой, запечённые в духовке. Подаются с кисло-солёным соусом с кунжутным маслом.', '<ol><li>Разогрейте духовку до 260 °C.</li><li>Смешайте индейку, сухари, яйцо, соль, зелёный лук, чеснок, имбирь, кинзу, ложку соевого соуса и 2 ч. л. кунжутного масла. Аккуратно перемешайте руками.</li><li>Слепите 12 фрикаделек (примерно по 1/4 стакана), выложите на противень и запекайте 15–18 минут до золотистой корочки.</li><li>Для соуса смешайте сок лайма, воду, соевый соус и кунжутное масло, добавьте нарезанный зелёный лук.</li><li>Выложите фрикадельки на блюдо, полейте немного соусом, остальное подайте отдельно.</li></ol><p><em>Подавайте с рисом и свежими овощами, соус налейте отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('61c71e31-2194-5558-a9d3-85052c16ba74', 'd2a84b0b-a845-544c-b282-c25a0df14b6c', 'en', 'Asian turkey meatballs with lime-sesame dipping sauce', 'Tender baked meatballs of ground turkey with ginger, scallions and cilantro, served with a tangy soy, lime and sesame oil dipping sauce.', '<ol><li>Preheat the oven to 260 °C (500 °F).</li><li>Combine the turkey, breadcrumbs, egg, salt, scallions, garlic, ginger, cilantro, 1 tbsp soy sauce and 2 tsp sesame oil. Mix gently by hand.</li><li>Shape 12 meatballs (about 1/4 cup each), place on a baking sheet and bake 15–18 minutes until browned and cooked through.</li><li>For the sauce, stir together the lime juice, water, soy sauce and sesame oil, then add the scallions.</li><li>Arrange the meatballs on a platter, drizzle with some sauce and serve the rest on the side.</li></ol><p><em>Serve with rice and fresh vegetables and the sauce on the side.</em></p>', CURRENT_TIMESTAMP),
  ('3f78e118-4c8d-59c8-a40a-10f59b760d72', '1ff9ef43-b161-5a98-a381-e4fb4269755e', 'ru', 'Вегетарианские тако с чёрной фасолью, авокадо и сыром', 'Хрустящие кукурузные шапочки с пряной чёрной фасолью, мятым авокадо с лаймом, чеддером, помидором и салатом. Без мяса, но сытно.', '<ol><li>Разогрейте духовку по инструкции на упаковке тако-шапочек, выложите их на противень и прогрейте 6–7 минут.</li><li>На сковороде на среднем огне обжарьте лук на масле 2–3 минуты до прозрачности, добавьте чеснок на 30 секунд.</li><li>Добавьте фасоль, специи, томатную пасту и воду, перемешайте и прогревайте около 3 минут.</li><li>Разомните авокадо вилкой с соком лайма, солью и перцем.</li><li>В каждую шапочку положите фасоль, сыр, авокадо, помидор и нарезанный салат. Подавайте сразу.</li></ol><p><em>Рассчитано по 2 тако на порцию. Подавайте сразу, пока шапочки хрустят.</em></p>', CURRENT_TIMESTAMP),
  ('467a949d-5c89-5800-989b-0b985cadeb68', '1ff9ef43-b161-5a98-a381-e4fb4269755e', 'en', 'Vegetarian crunchy black bean tacos with avocado and cheddar', 'Crunchy corn shells filled with spiced black beans, lime-mashed avocado, cheddar, tomato and lettuce. Meat-free but satisfying.', '<ol><li>Preheat the oven according to the taco shell package, lay the shells on a baking sheet and warm for 6–7 minutes.</li><li>Sauté the onion in oil in a skillet over medium heat for 2–3 minutes until translucent, then add the garlic for 30 seconds.</li><li>Add the beans, spices, tomato paste and water; stir and cook about 3 minutes until heated through.</li><li>Mash the avocado with a fork with the lime juice, salt and pepper.</li><li>Fill each shell with beans, cheese, avocado, tomato and shredded lettuce. Serve immediately.</li></ol><p><em>Plan on 2 tacos per serving and eat right away while the shells are crisp.</em></p>', CURRENT_TIMESTAMP),
  ('fc75291b-ca6f-52ba-a71d-6cd334551c8a', 'a4e96bb2-ffab-5de5-b4ec-b69debf19651', 'ru', 'Салат капрезе с куриными шницелями в сухарях', 'Тонкие куриные отбивные в хрустящей панировке с пармезаном подаются с черри, шариками моцареллы, базиликом и зелёным салатом.', '<ol><li>Разрежьте каждую грудку вдоль на два тонких пласта и отбейте до толщины около 0,5 см. Посолите и поперчите.</li><li>Смешайте сухари с пармезаном, в другой миске взбейте яйца. Обмакните шницели в яйцо, затем в сухари.</li><li>На сковороде на среднем огне растопите масло с оливковым маслом и жарьте шницели по 4–6 минут с каждой стороны до золотистого цвета и готовности, при необходимости в два приёма.</li><li>Нарежьте шницели полосками. На блюдо выложите зелень, сверху курицу, половинки помидоров, моцареллу и базилик.</li><li>Подавайте, полив бальзамической заправкой.</li></ol><p><em>Заправьте бальзамической заправкой из равных частей уксуса и оливкового масла.</em></p>', CURRENT_TIMESTAMP),
  ('a97efe61-2a9d-51f9-a994-442c3ee90252', 'a4e96bb2-ffab-5de5-b4ec-b69debf19651', 'en', 'Chicken cutlet caprese salad', 'Thin crispy chicken cutlets with Parmesan breading served over mixed greens with cherry tomatoes, fresh mozzarella and basil.', '<ol><li>Slice each chicken breast in half horizontally and pound to about 0.5 cm thick. Season with salt and pepper.</li><li>Mix the breadcrumbs with the Parmesan and beat the eggs in another bowl. Dip the cutlets in egg, then in the crumbs.</li><li>Melt the butter with the olive oil in a skillet over medium heat and fry the cutlets 4–6 minutes per side until golden and cooked through, in two batches if needed.</li><li>Slice the cutlets. Arrange the greens on a platter and top with the chicken, halved tomatoes, mozzarella and basil.</li><li>Serve drizzled with the balsamic dressing.</li></ol><p><em>Dress with a simple balsamic vinaigrette of equal parts balsamic and olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('c48d89e3-540a-5a61-bde6-2407a3917f6a', 'd997a305-156c-592d-892a-d7ec6452c468', 'ru', 'Кубинская свинина с чесноком и цитрусовым маринадом', 'Постная свиная лопатка в маринаде из чеснока, грейпфрутового и лаймового сока, зиры и орегано, томлёная до мягкости и разобранная на волокна.', '<ol><li>Нарежьте свинину на 4 куска и сложите в миску.</li><li>В блендере или мини-комбайне взбейте до однородности чеснок, грейпфрутовый и лаймовый соки, орегано, зиру и соль.</li><li>Залейте мясо маринадом и оставьте на час при комнатной температуре или до суток в холодильнике.</li><li>Переложите мясо с маринадом в скороварку, добавьте лавровый лист и готовьте под высоким давлением 80 минут. Дайте давлению сброситься самому.</li><li>Выньте мясо и разберите вилками. Слейте жидкость, верните мясо в чашу и добавьте примерно стакан жидкости, при необходимости досолите.</li><li>Подавайте с дольками лайма, кинзой и острым соусом.</li></ol><p><em>Подавайте с рисом и фасолью, в лепёшках с сальсой и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('192621e4-df86-5f1d-b05c-feb83193c43b', 'd997a305-156c-592d-892a-d7ec6452c468', 'en', 'Garlicky Cuban pulled pork (pressure cooker)', 'Lean pork shoulder marinated in garlic, grapefruit and lime juice, cumin and oregano, then cooked until fork-tender and shredded.', '<ol><li>Cut the pork into 4 pieces and place in a bowl.</li><li>Blend the garlic, grapefruit juice, lime juice, oregano, cumin and salt until smooth in a blender or mini food processor.</li><li>Pour the marinade over the pork and leave for 1 hour at room temperature or up to overnight in the fridge.</li><li>Transfer the pork and marinade to the pressure cooker, add the bay leaf and cook on high pressure for 80 minutes. Let the pressure release naturally.</li><li>Remove the pork and shred it with two forks. Pour off the liquid, return the pork to the pot and add back about 1 cup of the juices, adjusting the salt.</li><li>Serve with lime wedges, cilantro and hot sauce.</li></ol><p><em>Serve with rice and beans, or in tortillas with salsa and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('f35478bc-4e4a-5377-b1c3-97c6dde2f764', 'fe7a76b7-a6c5-5339-a6da-a3eb264905b4', 'ru', 'Кубинский рис с чёрной фасолью (конгри)', 'Рассыпчатый рис, сваренный с чёрной фасолью, сладким перцем, луком, чесноком и зирой. Подходит как гарнир или постное основное блюдо.', '<ol><li>В тяжёлой кастрюле разогрейте масло на среднем огне. Обжарьте лук, оба перца и чеснок 4–5 минут до мягкости.</li><li>Добавьте рис, фасоль вместе с жидкостью из банки, воду, зиру, лавровый лист, орегано, соль и перец. Варите на среднем-слабом огне, помешивая, пока рис не впитает почти всю воду.</li><li>Плотно накройте крышкой, убавьте огонь до минимума и готовьте 20 минут, не открывая. Выключите и дайте постоять под крышкой ещё 5 минут.</li></ol><p><em>Подавайте к мясу или птице, или с авокадо и лаймом как самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('3e37f1b3-4d11-54dd-9e0f-8170574f2e45', 'fe7a76b7-a6c5-5339-a6da-a3eb264905b4', 'en', 'Arroz congri (Cuban rice and black beans)', 'Fluffy rice cooked together with black beans, sweet peppers, onion, garlic and cumin. Works as a side dish or a meatless main.', '<ol><li>Heat the oil in a heavy pot over medium heat and sauté the onion, both peppers and the garlic for 4–5 minutes until soft.</li><li>Add the rice, the beans with their liquid, water, cumin, bay leaf, oregano, salt and pepper. Simmer over medium-low heat, stirring now and then, until the rice has absorbed most of the water.</li><li>Cover tightly, reduce the heat to low and cook 20 minutes without peeking. Turn off the heat and let it stand covered another 5 minutes.</li></ol><p><em>Serve with meat or poultry, or with avocado and lime as a meatless meal.</em></p>', CURRENT_TIMESTAMP),
  ('4ad3fb9c-93df-5589-9434-4a6bc47244bf', '9e559702-47a7-5c99-ae65-32f684473c37', 'ru', 'Лёгкий куриный суп с авокадо, кинзой и лаймом', 'Прозрачный бульон с зелёным луком, томатом и чесноком, который подаётся с курицей, кубиками авокадо и кинзой. Готовится за 25 минут.', '<ol><li>Разогрейте кастрюлю на среднем огне, добавьте масло, примерно 3/4 зелёного лука и чеснок. Обжарьте 2–3 минуты до мягкости.</li><li>Добавьте помидор и готовьте ещё минуту.</li><li>Влейте бульон, добавьте зиру и острый перец, доведите до кипения и варите под крышкой на слабом огне около 15 минут.</li><li>В четыре миски положите курицу, авокадо, оставшийся зелёный лук и кинзу. Залейте горячим бульоном, посолите, поперчите и подавайте с лаймом.</li></ol><p><em>Выжмите в тарелку дольку лайма перед едой.</em></p>', CURRENT_TIMESTAMP),
  ('214476f0-b17f-56c7-8296-5ecca92f9c7f', '9e559702-47a7-5c99-ae65-32f684473c37', 'en', 'Light chicken and avocado soup with lime and cilantro', 'A clear broth with scallions, tomato and garlic, served over shredded chicken, diced avocado and cilantro. Ready in 25 minutes.', '<ol><li>Heat a large pot over medium heat, add the oil, about three quarters of the scallions and the garlic. Sauté 2–3 minutes until soft.</li><li>Add the tomato and cook another minute until soft.</li><li>Pour in the stock, add the cumin and chile powder, bring to a boil and simmer covered over low heat for about 15 minutes.</li><li>Divide the chicken, avocado, remaining scallions and cilantro among four bowls. Ladle in the hot broth, season to taste and serve with lime.</li></ol><p><em>Squeeze a lime wedge into each bowl before eating.</em></p>', CURRENT_TIMESTAMP),
  ('2c91b7b8-a33b-5998-95ae-77e29cb04fbe', '9576127a-3d8c-58b1-9673-c524c755c9a6', 'ru', 'Боул с курицей и капустой в стиле эгг-ролла', 'Куриный фарш, обжаренный с капустой, морковью, бок-чоем, чесноком и имбирём в соевом соусе, подаётся с рисом. Начинка эгг-ролла без теста.', '<ol><li>В большой антипригарной сковороде на средне сильном огне обжарьте куриный фарш с половиной столовой ложки соевого соуса около 5 минут, разбивая комочки, до румяности и готовности.</li><li>Добавьте белую и светло-зелёную части лука, чеснок и имбирь и готовьте 2–3 минуты до мягкости.</li><li>Добавьте капусту, морковь и бок-чой, влейте оставшийся соевый соус, рисовое вино и кунжутное масло. Готовьте, помешивая, около 4 минут, пока овощи не завянут, но останутся хрустящими.</li><li>Снимите с огня, посыпьте зелёным луком и подавайте с рисом.</li></ol><p><em>Посыпьте зелёным луком и подавайте на рисе.</em></p>', CURRENT_TIMESTAMP),
  ('df25c15d-b20e-549a-bbb4-9c0ae1e70213', '9576127a-3d8c-58b1-9673-c524c755c9a6', 'en', 'Chicken egg roll bowl with rice', 'Ground chicken stir-fried with cabbage, carrot, bok choy, garlic and ginger in soy sauce and served over rice. Egg roll filling without the wrapper.', '<ol><li>In a large nonstick skillet over medium-high heat, cook the ground chicken with ½ tablespoon of the soy sauce for about 5 minutes, breaking it up, until browned and cooked through.</li><li>Add the scallion whites and light green parts, garlic and ginger and cook 2–3 minutes until soft.</li><li>Add the cabbage, carrot and bok choy, pour in the remaining soy sauce, rice wine and sesame oil, and cook, stirring, about 4 minutes until the vegetables wilt but stay crunchy.</li><li>Take off the heat, sprinkle with the scallion greens and serve with rice.</li></ol><p><em>Top with scallion greens and serve over rice.</em></p>', CURRENT_TIMESTAMP),
  ('4f750b62-285d-5e04-84d1-c8d0a89b8cd4', '784eefdb-0389-5861-951c-3a86d8620ee2', 'ru', 'Треска, запечённая с фенхелем, черри и каперсами', 'Филе трески с тушёными луком, фенхелем, помидорами черри и чесноком, каперсами и лимоном. Лёгкое средиземноморское блюдо за 35 минут.', '<ol><li>Разогрейте духовку до 200 °C. Приправьте треску лимонным соком, половиной чайной ложки соли, перцем и тимьяном с обеих сторон, уложите в форму и отложите.</li><li>В большой сковороде на среднем огне разогрейте масло и 10 минут тушите лук, фенхель, помидоры и чеснок до мягкости. Добавьте каперсы, бульон и оставшуюся соль и готовьте ещё 4 минуты.</li><li>Переложите овощи в форму, положите сверху рыбу и ломтики лимона. Запекайте 15 минут, пока рыба не начнёт расслаиваться по краям. Посыпьте петрушкой и подавайте горячим.</li></ol><p><em>Посыпьте петрушкой и подавайте горячим с овощами из формы.</em></p>', CURRENT_TIMESTAMP),
  ('bb9d2430-f981-57b5-a481-806f8f171a0f', '784eefdb-0389-5861-951c-3a86d8620ee2', 'en', 'Baked cod with fennel, cherry tomatoes and capers', 'Cod fillets baked over sautéed onion, fennel, cherry tomatoes and garlic with capers and lemon. A light Mediterranean dish ready in 35 minutes.', '<ol><li>Preheat the oven to 200 °C (400 °F). Season the cod on both sides with the lemon juice, ½ teaspoon salt, pepper and thyme, set it in a baking dish and leave aside.</li><li>In a large skillet over medium-high heat, warm the oil and sauté the onion, fennel, tomatoes and garlic for 10 minutes until tender. Add the capers, broth and remaining salt and cook 4 more minutes.</li><li>Transfer the vegetables to the baking dish, add the fish and lemon slices, and bake for 15 minutes until the fish flakes at the edges. Top with parsley and serve hot.</li></ol><p><em>Sprinkle with parsley and serve hot with the vegetables from the dish.</em></p>', CURRENT_TIMESTAMP),
  ('d2da0534-f8f0-521d-8b94-86d4045d399b', '578dc31f-70f1-5695-9270-0219465c3499', 'ru', 'Позоле верде с курицей', 'Мексиканский сытный суп с курицей, хоминни и зелёным соусом из запечённых томатилло, перца поблано, кинзы и шпината.', '<ol><li>В большой кастрюле соедините курицу, половину луковицы, 2 зубчика чеснока, бульон, лавровый лист и соль. Доведите до кипения, убавьте огонь, накройте и варите 30 минут, снимая пену, до мягкости мяса.</li><li>Достаньте курицу и разберите на волокна. Выбросьте лавровый лист, шумовкой переложите варёные лук и чеснок в блендер.</li><li>Тем временем включите гриль в духовке. Выложите на противень с фольгой томатилло, поблано, оставшиеся лук и чеснок, посыпьте солью и сбрызните маслом. Запекайте под грилем 5–6 минут, затем переверните и добавьте 3–4 минуты, пока овощи не обуглятся и не станут мягкими.</li><li>Переложите запечённые овощи в блендер, добавьте кинзу, шпинат, зиру и стакан бульона. Взбейте до гладкости.</li><li>Влейте зелёный соус в бульон, добавьте хоминни и курицу, доведите до кипения и варите 5–10 минут. Посолите по вкусу.</li><li>Разлейте по глубоким тарелкам и посыпьте кинзой и выбранными добавками.</li></ol><p><em>Подайте с авокадо, шинкованной капустой, сметаной и чипсами.</em></p>', CURRENT_TIMESTAMP),
  ('716d77c8-94ae-5183-b139-923759914fc3', '578dc31f-70f1-5695-9270-0219465c3499', 'en', 'Chicken pozole verde', 'A hearty Mexican soup of shredded chicken and hominy in a green sauce of broiled tomatillos, poblano, cilantro and spinach.', '<ol><li>In a large pot combine the chicken, half an onion, 2 garlic cloves, the broth, bay leaves and salt. Bring to a boil, reduce to a simmer, cover and cook 30 minutes, skimming foam, until the meat is tender.</li><li>Remove the chicken and shred it. Discard the bay leaves and use a slotted spoon to move the cooked onion and garlic to a blender.</li><li>Meanwhile, heat the oven broiler. On a foil-lined baking sheet put the tomatillos, poblano, remaining onion and garlic, season with a pinch of salt and spritz with oil. Broil 5–6 minutes, flip and broil 3–4 more minutes until charred and tender.</li><li>Transfer the roasted vegetables to the blender with the cilantro, spinach, cumin and a cup of the broth and blend until smooth.</li><li>Add the green sauce, hominy and shredded chicken to the broth, bring to a simmer and cook 5–10 minutes. Adjust the salt.</li><li>Ladle into shallow bowls and top with cilantro and any toppings.</li></ol><p><em>Top with avocado, shredded cabbage, sour cream and tortilla chips.</em></p>', CURRENT_TIMESTAMP),
  ('ac1b7c57-42d2-5bcc-b8b7-5d5424cb581c', 'e47b6032-c224-5c05-84d0-359e1b3e66d4', 'ru', 'Рис басмати с куркумой и зелёным горошком', 'Золотистый рассыпчатый рис басмати с луком, чесноком, куркумой и горошком. Гарнир к карри, мясу и птице.', '<ol><li>В кастрюле с толстым дном и плотной крышкой разогрейте масло на среднем огне и 2 минуты пассеруйте лук, чеснок и куркуму.</li><li>Всыпьте рис и жарьте 2 минуты, часто помешивая. Влейте воду, добавьте горошек, бульонные кубики, лавровый лист и перец. Попробуйте на соль: вода должна быть по вкусу как суп.</li><li>Доведите до кипения на среднем огне, один раз перемешайте. Когда вода почти выкипит до уровня риса, убавьте огонь до минимума и накройте на 15 минут, не открывая крышку.</li><li>Выключите огонь и оставьте под крышкой ещё минимум на 5 минут. Выньте лавровый лист, взрыхлите рис вилкой и подавайте.</li></ol><p><em>Подавайте к карри или мясу на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('548a0b68-6414-5d31-b33b-f7c00d8a9f89', 'e47b6032-c224-5c05-84d0-359e1b3e66d4', 'en', 'Turmeric basmati rice with peas', 'Golden, fluffy basmati rice with onion, garlic, turmeric and green peas. A side for curries, grilled meats and poultry.', '<ol><li>In a heavy pot with a tight lid heat the oil over medium heat and sauté the onion, garlic and turmeric for about 2 minutes until tender.</li><li>Add the rice and stir-fry for 2 more minutes. Pour in the water and add the peas, bouillon cubes, bay leaves and pepper. Taste for salt: the liquid should taste as seasoned as a soup.</li><li>Bring to a boil over medium-high heat, stirring once. When the liquid has cooked down to the level of the rice, reduce the heat to very low and cover for 15 minutes without opening the lid.</li><li>Turn off the heat and let the rice sit covered for at least 5 more minutes. Remove the bay leaves, fluff with a fork and serve.</li></ol><p><em>Serve with curries or grilled meats.</em></p>', CURRENT_TIMESTAMP),
  ('37cf6790-f73d-530c-b060-43f328dac425', 'ee900400-8113-569c-9a7a-1dd5c830b743', 'ru', 'Греческий салат с пастой орзо и фетой', 'Лёгкий паста-салат из орзо с оливками, огурцом, помидорами, сладким перцем, красным луком и фетой под лимонно-винной заправкой.', '<ol><li>Отварите орзо в кипящей подсоленной воде до состояния аль денте по инструкции, добавив ещё одну минуту. Слейте и промойте холодной водой.</li><li>Смешайте в большой миске уксус, лимонный сок, масло, чесночный порошок, орегано и соль. Добавьте оливки, лук и рассол из-под оливок.</li><li>Добавьте пасту, огурец, помидоры и перец, хорошо перемешайте, при необходимости досолите. Добавьте фету перед подачей.</li></ol><p><em>Фету добавляйте непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('0eddbf19-a717-5381-93e4-54e929107c3e', 'ee900400-8113-569c-9a7a-1dd5c830b743', 'en', 'Greek orzo salad with feta and olives', 'A light pasta salad of orzo with olives, cucumber, tomatoes, bell pepper, red onion and feta in a lemony red wine vinegar dressing.', '<ol><li>Cook the orzo in rapidly boiling salted water according to the package for al dente, adding an extra minute. Drain and rinse under cold water.</li><li>In a large bowl whisk together the vinegar, lemon juice, oil, garlic powder, oregano and salt. Add the olives, onion and olive brine.</li><li>Stir in the pasta, cucumber, tomatoes and pepper, toss well and adjust the salt. Add the feta just before serving.</li></ol><p><em>Add the feta just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('e1fd414d-6206-58d6-b032-a7107e8870dd', '1c121bfd-5f9f-511f-93d0-ff2b2e15998e', 'ru', 'Суп с говядиной и перловкой', 'Классический наваристый суп с говядиной, морковью, луком, сельдереем и перловой крупой. Мясо тушится до мягкости, крупа добавляется в конце.', '<ol><li>В большой кастрюле с толстым дном на среднем огне разогрейте масло, добавьте говядину, слегка посолите и обжаривайте несколько минут до румяности.</li><li>Добавьте морковь, лук, сельдерей и чеснок и хорошо перемешайте. Влейте воду, добавьте соль и лавровый лист и доведите до кипения.</li><li>Убавьте огонь, накройте и варите 1,5–2 часа, пока мясо не станет очень мягким.</li><li>Всыпьте перловку, при необходимости досолите, добавьте перец и варите ещё 30–35 минут. Выньте лавровый лист и подавайте.</li></ol><p><em>Подавайте горячим со свежей зеленью и хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('67e11fd9-ac27-59f4-839a-37ebe71f0876', '1c121bfd-5f9f-511f-93d0-ff2b2e15998e', 'en', 'Beef and barley soup', 'A classic hearty soup of beef, carrots, onion, celery and pearl barley. The beef simmers until very tender and the barley goes in at the end.', '<ol><li>Heat the oil in a large heavy pot or Dutch oven over medium heat, add the beef, season lightly with salt and brown for a few minutes.</li><li>Add the carrots, onion, celery and garlic and stir well. Pour in the water, add the salt and bay leaves and bring to a boil.</li><li>Reduce the heat, cover and simmer 1½–2 hours until the beef is very tender.</li><li>Add the barley, adjust the salt, add pepper and simmer another 30–35 minutes. Remove the bay leaves and serve.</li></ol><p><em>Serve hot with fresh herbs and bread.</em></p>', CURRENT_TIMESTAMP),
  ('3faa4650-86c2-5a95-b23a-bf05e53cdd57', '26dd30e1-5a7f-5249-a7b3-6eba629c786c', 'ru', 'Лёгкий сливочный суп с курицей и грибами', 'Нежный суп с курицей, шиитаке и шампиньонами, загущенный мукой и частью овощей, пробитых блендером. Готовится за 25 минут.', '<ol><li>Взбейте в блендере холодную воду с мукой до гладкости и вылейте в кастрюлю на среднем огне.</li><li>Добавьте сельдерей, грибы, куриный бульон (концентрат) и масло и доведите до кипения.</li><li>Положите курицу, накройте и варите на слабом огне 15 минут до готовности. Выньте курицу и варите суп ещё 5 минут, пока овощи не станут мягкими.</li><li>Взбейте в блендере сельдерей с стаканом супа до гладкости, верните в кастрюлю и прогрейте несколько минут.</li><li>Разберите курицу на волокна, верните в суп и посыпьте петрушкой.</li></ol><p><em>Посыпьте рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('da3324c7-822c-51b7-8841-08d29094d772', '26dd30e1-5a7f-5249-a7b3-6eba629c786c', 'en', 'Light creamy chicken and mushroom soup', 'A cozy soup of chicken, shiitake and cremini mushrooms thickened with flour and a blended portion of the vegetables. Ready in 25 minutes.', '<ol><li>Blend the cold water and flour in a blender until smooth and pour into a medium pot over medium heat.</li><li>Add the celery, mushrooms, chicken bouillon and butter and bring to a boil.</li><li>Add the chicken, cover and simmer 15 minutes until cooked through. Remove the chicken and cook the soup 5 more minutes until the vegetables are soft.</li><li>Blend the celery with a cup of soup until smooth, return it to the pot and simmer a few minutes.</li><li>Shred or chop the chicken, return it to the soup and garnish with parsley.</li></ol><p><em>Garnish with chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('33950c71-c21e-579d-93fe-c830ce77334d', '0736a9d4-a631-5803-9ec0-69550c746c87', 'ru', 'Рыбные котлеты в сухарях с соусом из печёного перца', 'Хрустящие рыбные котлеты из любой белой рыбы с сельдереем, зеленью и горчицей, запечённые или приготовленные в аэрогриле, с соусом из печёного красного перца.', '<ol><li>Для соуса взбейте в мини-блендере печёный перец, чеснок и паприку, смешайте с майонезом и отложите.</li><li>Выложите рыбу в корзину аэрогриля и готовьте при 200 °C около 6 минут, пока не будет расслаиваться вилкой. Остудите и разделите на мелкие кусочки. (В духовке запекайте рыбу при 220 °C около 10 минут.)</li><li>Смешайте рыбу с 1/2 стакана сухарей, сельдереем, майонезом, горчицей, лимонным соком, одним яйцом, петрушкой, зелёным луком, паприкой, солью и перцем.</li><li>Разделите массу на 8 частей и сформируйте котлеты. Если рассыпаются, добавьте немного сухарей. Обмакните в оставшееся взбитое яйцо, обваляйте в сухарях и сбрызните маслом с обеих сторон.</li><li>Готовьте в аэрогриле порциями в один слой при 200 °C около 8 минут, перевернув в середине, до золотистой корочки. В духовке запекайте по 5–6 минут с каждой стороны. Подавайте с лимоном и соусом.</li></ol><p><em>Подайте с лимоном и соусом из красного перца.</em></p>', CURRENT_TIMESTAMP),
  ('a8ac86d3-816e-5b3c-b12c-44c6c5674b1b', '0736a9d4-a631-5803-9ec0-69550c746c87', 'en', 'Baked fish cakes with roasted red pepper sauce', 'Crispy fish cakes made with any white fish, celery, herbs and mustard, baked or air-fried, with a roasted red pepper sauce.', '<ol><li>For the sauce, purée the roasted pepper, garlic and paprika in a mini blender, mix with the mayonnaise and set aside.</li><li>Place the fish in the air fryer basket and cook at 200 °C (400 °F) for about 6 minutes until it flakes easily. Cool and flake into small pieces. (In the oven, bake the fish at 220 °C / 425 °F for about 10 minutes.)</li><li>Combine the fish with ½ cup of the breadcrumbs, celery, mayonnaise, mustard, lemon juice, one egg, parsley, scallions, paprika, salt and pepper.</li><li>Divide into 8 portions and shape into patties, adding a little more breadcrumbs if they fall apart. Dip in the remaining beaten egg, coat with breadcrumbs and spray both sides with oil.</li><li>Air-fry in a single layer at 200 °C (400 °F) about 8 minutes, turning halfway, until golden and crisp. In the oven bake 5–6 minutes per side. Serve with lemon wedges and the sauce.</li></ol><p><em>Serve with lemon wedges and the red pepper sauce.</em></p>', CURRENT_TIMESTAMP),
  ('165108a9-7c4b-568c-b0ae-d0d4e3e465da', '450c7997-6694-54bb-b111-b84437ce211a', 'ru', 'Лосось, запечённый в духовке, со свежим томатным соусом с базиликом', 'Сочное филе лосося, быстро запечённое на раскалённом противне, с яркой свежей начинкой из помидоров, чеснока, лайма и зелени.', '<ol><li>Разогрейте духовку до 260 °C вместе с пустым противнем с бортиками.</li><li>Посолите и поперчите лосось, смажьте оливковым маслом со всех сторон.</li><li>Достаньте горячий противень, положите на него рыбу (она сразу зашипит), снизьте температуру до 120 °C и запекайте 12–14 минут до 54–57 °C в центре для средней прожарки.</li><li>Пока запекается рыба, нарежьте помидоры без семян и зелень, добавьте чеснок и половину сока лайма, посолите и поперчите.</li><li>Сразу снимите рыбу с противня, сбрызните лаймом, выложите томатную смесь и полейте бальзамической глазурью.</li></ol><p><em>Подавайте сразу с рисом, картофелем или овощами.</em></p>', CURRENT_TIMESTAMP),
  ('aa49d8d6-58d9-5ca6-8aa2-a08cff158f42', '450c7997-6694-54bb-b111-b84437ce211a', 'en', 'Oven-roasted salmon with fresh tomato basil topping', 'Juicy salmon fillets roasted on a preheated pan, topped with a fresh tomato, garlic, lime and herb salsa.', '<ol><li>Preheat the oven to 260 °C (500 °F) with a large rimmed baking sheet inside.</li><li>Season the salmon with salt and pepper and coat it with olive oil on all sides.</li><li>Take out the hot pan, lay the salmon on it (it will sizzle), lower the oven to 120 °C (250 °F) and roast 12–14 minutes until the center reaches 54–57 °C (130–135 °F) for medium.</li><li>While the salmon cooks, chop the seeded tomatoes and herbs, then mix with the garlic, half the lime juice, salt and pepper.</li><li>Move the salmon off the pan right away, squeeze lime over it, spoon the tomato topping on and drizzle with balsamic glaze.</li></ol><p><em>Serve right away with rice, potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('b490b72e-ed21-50bd-884e-08c8f023bf0e', '58c56e75-8343-524b-9dfb-15df3cc71910', 'ru', 'Курица, томлёная с чесноком в сливочно-винном соусе', 'Куриные бёдра и голени, обжаренные до золотистой корочки и запечённые в духовке в соусе из лука, целого чеснока, белого вина и сливок.', '<ol><li>Разогрейте духовку до 175 °C.</li><li>Срежьте с курицы лишний жир, хорошо обсушите бумажным полотенцем, посолите и поперчите.</li><li>В глубокой сковороде или жаровне разогрейте масло до дымка. Обжарьте курицу с двух сторон по 5–8 минут до золотистого цвета, при необходимости в два приёма. Не переворачивайте, пока корочка не схватится. Отложите.</li><li>Слейте лишний жир, оставив около 2 ст. л. Обжарьте лук с солью и перцем на слабом-среднем огне 5–7 минут до мягкости, соскребая подгоревшие кусочки со дна.</li><li>Добавьте зубчики чеснока и муку, перемешайте. Постепенно влейте вино и бульон, помешивая до гладкости, доведите до кипения и убавьте огонь. Добавьте сливки, лавровый лист, травы, соль и перец.</li><li>Уложите курицу сверху на соус, чтобы кожа не размокла. Запекайте без крышки от 1 часа до 1 часа 45 минут. Для хрустящей кожи на последние 5 минут можно поднять температуру до 230 °C.</li><li>Выньте курицу. Соус для гладкости процедите через сито и подавайте отдельно или поверх мяса.</li></ol><p><em>Подавайте с картофельным пюре, пастой или хлебом, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('79f443da-ac5c-530c-9e4c-a9a826205f28', '58c56e75-8343-524b-9dfb-15df3cc71910', 'en', 'Garlic braised chicken in creamy white wine sauce', 'Chicken thighs and drumsticks seared until golden, then braised in the oven in a sauce of onion, whole garlic cloves, white wine and cream.', '<ol><li>Preheat the oven to 175 °C (350 °F).</li><li>Trim excess fat from the chicken, pat it very dry and season with salt and pepper.</li><li>Heat the oil in a deep skillet or Dutch oven until smoking. Brown the chicken 5–8 minutes per side until golden, in two batches if needed, without flipping too soon. Set aside.</li><li>Pour off the fat, leaving about 2 tablespoons. Cook the onions with salt and pepper over medium-low heat for 5–7 minutes until tender, scraping up the browned bits.</li><li>Add the whole garlic cloves and flour and stir. Gradually pour in the wine and broth, whisking until smooth, bring to a boil and then simmer. Stir in the cream, bay leaf, herbs, salt and pepper.</li><li>Lay the chicken on top of the sauce so the skin doesn''t get soggy. Braise uncovered for 1 hour to 1 hour 45 minutes; raise the oven to 230 °C (450 °F) for the last 5 minutes to crisp the skin.</li><li>Remove the chicken. For a smoother sauce, strain it through a fine sieve and serve alongside or over the chicken.</li></ol><p><em>Serve with mashed potatoes, pasta or bread to mop up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('527eb22b-a08d-5102-b696-c015a976f661', '7ab7fc86-84ae-5a91-a654-fd6bfb1c08f9', 'ru', 'Кабачки, запечённые с сыром и чесноком', 'Кабачки кусочками с чесноком и петрушкой, запечённые под шапкой из моцареллы и пармезана до золотистой корочки.', '<ol><li>Разогрейте духовку до 200 °C.</li><li>Нарежьте кабачки кусочками 1,5–2,5 см. Смешайте в миске с чесноком, петрушкой, маслом, солью и перцем.</li><li>Выложите ровным слоем в форму 23×33 см и посыпьте тёртой моцареллой и пармезаном.</li><li>Запекайте без крышки около 20 минут, затем 3–5 минут под грилем до золотистого цвета сыра.</li></ol><p><em>Хорошо подходит к курице, рыбе и мясу на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('db33ad89-a567-5d8f-9811-d31924bfd0a5', '7ab7fc86-84ae-5a91-a654-fd6bfb1c08f9', 'en', 'Cheesy roasted zucchini with garlic', 'Zucchini chunks tossed with garlic and parsley and roasted under a blanket of mozzarella and Parmesan until golden.', '<ol><li>Preheat the oven to 200 °C (400 °F).</li><li>Cut the zucchini into 1.5–2.5 cm pieces and toss with the garlic, parsley, oil, salt and pepper.</li><li>Spread in an even layer in a 9x13 inch baking dish and top with the grated mozzarella and Parmesan.</li><li>Roast uncovered about 20 minutes, then broil 3–5 minutes until the cheese is golden.</li></ol><p><em>A great side for chicken, fish or grilled meat.</em></p>', CURRENT_TIMESTAMP),
  ('af455a48-e67d-5fed-babb-279c99ba1779', '611d949d-5b50-58d8-b377-8bbdebd78a01', 'ru', 'Говядина с шиитаке и стручковой фасолью в устричном соусе', 'Тонкие полоски говядины, обжаренные с луком, перцем, грибами шиитаке и стручковой фасолью в блестящем соусе из соевого и устричного соусов.', '<ol><li>Подержите говядину 15–30 минут в морозилке, чтобы легче резалась. Разрежьте вдоль волокон пополам, затем поперёк волокон на тонкие полоски 3–6 мм.</li><li>Замаринуйте мясо в 2 ст. л. соевого соуса на 15 минут. Пока оно маринуется, подготовьте овощи, а все ингредиенты соуса смешайте.</li><li>В большой антипригарной сковороде разогрейте немного масла на сильном огне. Обжарьте слитую от маринада говядину в два приёма примерно по 3 минуты. Переложите в миску.</li><li>В той же сковороде 3–5 минут обжарьте лук и перец, отложите к мясу. Затем обжарьте шиитаке 3 минуты, добавьте фасоль и жарьте 1–2 минуты.</li><li>Освободите место в центре, на 30 секунд положите чеснок и имбирь. Влейте 120 мл бульона, накройте крышкой и тушите, пока жидкость почти не впитается, а фасоль не станет мягкой.</li><li>Влейте соус, сделайте огонь сильным и прогрейте несколько минут до загустения. Верните говядину, лук и перец, перемешайте и подавайте.</li></ol><p><em>Подавайте с рисом или лапшой, посыпав зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('bdf1461e-b167-5c93-b5f0-3906f1806940', '611d949d-5b50-58d8-b377-8bbdebd78a01', 'en', 'Beef, shiitake and green bean stir-fry', 'Thin strips of beef stir-fried with onion, pepper, shiitake mushrooms and green beans in a glossy soy and oyster sauce.', '<ol><li>Chill the beef in the freezer for 15–30 minutes so it slices easily. Halve it lengthwise with the grain, then cut across the grain into thin 3–6 mm strips.</li><li>Marinate the beef in 2 tablespoons of soy sauce for 15 minutes while you prep the vegetables and whisk together the sauce ingredients.</li><li>Heat a little oil in a large nonstick skillet over high heat. Sauté the drained beef in two batches, about 3 minutes each, and set aside.</li><li>In the same pan sauté the onion and pepper 3–5 minutes and set aside with the beef. Then cook the shiitake 3 minutes, add the green beans and cook 1–2 minutes.</li><li>Make a space in the center and cook the garlic and ginger 30 seconds. Pour in 120 ml of broth, cover and cook until mostly absorbed and the beans are tender.</li><li>Pour in the sauce, raise the heat and cook a few minutes until thickened. Return the beef, onion and pepper, toss to heat through and serve.</li></ol><p><em>Serve over rice or noodles, garnished with green onions.</em></p>', CURRENT_TIMESTAMP),
  ('ae9aadef-9846-562e-b254-38f20ecab2dd', '1af271bf-f3a7-5180-a885-3013bd6158f2', 'ru', 'Курица с базиликом и чили по-тайски', 'Острая, чесночная и слегка сладкая курица, обжаренная на сильном огне в соусе из устричного и соевого соусов с листьями тайского базилика. Готовится за 15 минут.', '<ol><li>Смешайте в маленькой миске все ингредиенты соуса.</li><li>Разогрейте масло в воке или сковороде на сильном огне, на 10 секунд добавьте чеснок и чили (осторожно, пары острые).</li><li>Добавьте белую часть зелёного лука и курицу и обжаривайте около 2 минут до готовности.</li><li>Влейте соус и готовьте минуту, пока он не станет густым и глянцевым.</li><li>Добавьте зелёную часть лука и листья базилика, перемешайте до слегка увядшего состояния и сразу подавайте с рисом.</li></ol><p><em>Подавайте сразу с отварным рисом жасмин.</em></p>', CURRENT_TIMESTAMP),
  ('d071c99c-5035-563d-8a04-a8b956c5a1e7', '1af271bf-f3a7-5180-a885-3013bd6158f2', 'en', 'Thai chilli basil chicken', 'Spicy, garlicky and savoury chicken stir-fried over high heat in an oyster and soy sauce with Thai basil leaves. Ready in 15 minutes.', '<ol><li>Mix the sauce ingredients in a small bowl.</li><li>Heat the oil in a wok or pan over high heat and cook the garlic and chilli for 10 seconds (careful, the fumes are sharp).</li><li>Add the white part of the green onion and the chicken and fry about 2 minutes until cooked.</li><li>Pour in the sauce and cook 1 minute until thick and glossy.</li><li>Toss through the green part of the onion and the basil leaves until just wilted and serve immediately with rice.</li></ol><p><em>Serve immediately with steamed jasmine rice.</em></p>', CURRENT_TIMESTAMP),
  ('f4d96502-684d-59a0-80d3-b935e6f5c84a', 'ee5cf846-5b79-51cc-9afd-1c3d9d0c1c31', 'ru', 'Карри из чечевицы с кокосовым молоком', 'Сливочное густое карри из чечевицы на кокосовом молоке и томатах, с луком, чесноком, имбирём, порошком карри и куркумой. Упрощённая версия дала.', '<ol><li>В кастрюле на среднем огне растопите масло и 10 минут медленно обжаривайте лук, чеснок и имбирь, помешивая, до золотистого цвета и сладости.</li><li>Прибавьте огонь, добавьте порошок карри и куркуму и 1,5 минуты прогревайте, помешивая.</li><li>Добавьте остальные ингредиенты (чечевицу, кокосовое молоко, томаты, воду, соль, перец, кайенский перец), перемешайте, доведите до кипения, накройте крышкой и варите на слабом огне 30 минут.</li><li>Снимите крышку и варите ещё 10 минут, пока соус не загустеет, а чечевица не станет мягкой. Слишком густое разбавьте водой.</li><li>Добавьте половину кинзы, посолите по вкусу и подавайте на рисе с оставшейся кинзой и йогуртом.</li></ol><p><em>Подавайте с рисом басмати, свежей кинзой и ложкой йогурта.</em></p>', CURRENT_TIMESTAMP),
  ('c579ae6e-7c0b-5cb2-8c4a-eb9a481d4067', 'ee5cf846-5b79-51cc-9afd-1c3d9d0c1c31', 'en', 'Coconut lentil curry with tomatoes', 'A thick, creamy lentil curry in coconut milk and tomatoes with onion, garlic, ginger, curry powder and turmeric. A streamlined take on dahl.', '<ol><li>Melt the butter in a pot over medium heat and slowly cook the onion, garlic and ginger for 10 minutes, stirring occasionally, until tinged with gold and sweet.</li><li>Turn the heat to high, add the curry powder and turmeric and stir for 1½ minutes.</li><li>Add the remaining ingredients (lentils, coconut milk, tomatoes, water, salt, pepper and cayenne), stir, bring to a simmer, cover and cook gently for 30 minutes.</li><li>Remove the lid and simmer 10 more minutes until the sauce thickens and the lentils are soft. Add water if too thick.</li><li>Stir in half the cilantro, adjust the salt and serve over rice with the remaining cilantro and yogurt.</li></ol><p><em>Serve over basmati rice with fresh cilantro and a dollop of yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('4ca8c94b-460d-59a9-8fc1-b896ba1aada3', 'b1ad5c29-d70e-5cdc-9bf1-e3c7baee58ee', 'ru', 'Китайский суп с лапшой, курицей и бок-чоем', 'Простой прозрачный суп с ароматным бульоном на чесноке, имбире и соевом соусе, яичной лапшой, варёной курицей и бок-чоем. Готовится на покупном бульоне.', '<ol><li>Соедините в кастрюле бульон, чеснок, имбирь, соевый соус, сахар, кулинарное вино и кунжутное масло. Накройте, доведите до кипения и варите на среднем огне 8–10 минут, чтобы бульон настоялся.</li><li>Тем временем отварите лапшу по инструкции на упаковке.</li><li>Разрежьте бок-чой пополам или на четвертинки и тщательно промойте. Опустите на 1 минуту в бульон или в воду от лапши.</li><li>Выньте чеснок и имбирь из бульона. Разложите лапшу по мискам, сверху курицу и бок-чой, залейте бульоном и посыпьте зелёным луком.</li></ol><p><em>Подавайте с пастой чили или свежим перцем.</em></p>', CURRENT_TIMESTAMP),
  ('101c90f4-3c54-54cf-aaef-fda584c0f5cf', 'b1ad5c29-d70e-5cdc-9bf1-e3c7baee58ee', 'en', 'Chinese noodle soup with chicken and bok choy', 'A simple clear soup with a fragrant broth of garlic, ginger and soy sauce, egg noodles, shredded cooked chicken and bok choy, made with store-bought stock.', '<ol><li>Place the stock, garlic, ginger, soy sauce, sugar, cooking wine and sesame oil in a saucepan, cover, bring to a simmer and cook over medium heat for 8–10 minutes to infuse.</li><li>Meanwhile, cook the noodles according to the package.</li><li>Halve or quarter the bok choy and wash well. Blanch in the broth or noodle water for 1 minute.</li><li>Pick the garlic and ginger out of the broth. Divide the noodles into bowls, top with chicken and bok choy, ladle over the broth and garnish with green onion.</li></ol><p><em>Serve with chilli paste or fresh chillies.</em></p>', CURRENT_TIMESTAMP),
  ('eb411464-7cba-5db5-bc5a-f923ecdd4b21', '12377ff8-cafd-5e56-99cf-71419fa8529a', 'ru', 'Суп из говяжьего фарша с чечевицей и овощами', 'Сытный суп в одной кастрюле из говяжьего фарша, чечевицы, моркови, сельдерея, кабачка и стручковой фасоли в томатах с пряностями. Хорошо замораживается.', '<ol><li>Смешайте в миске все специи.</li><li>В большой кастрюле разогрейте масло на средне сильном огне, 3 минуты обжаривайте лук и чеснок до золотистых краёв.</li><li>Усильте огонь, добавьте фарш и жарьте, разбивая комочки, пока он не перестанет быть красным. Всыпьте 2 ст. л. смеси специй и прогрейте 2 минуты.</li><li>Добавьте морковь и сельдерей, перемешайте минуту. Влейте воду и бульон, добавьте томаты, чечевицу и остаток специй. Доведите до кипения, накройте и варите на слабом огне.</li><li>Через 15 минут добавьте кабачок и стручковую фасоль и варите ещё около 10 минут, пока чечевица не станет мягкой (общее время 25–30 минут).</li><li>Попробуйте, досолите и разлейте по тарелкам с йогуртом и кинзой.</li></ol><p><em>Подавайте с йогуртом и свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('7857f620-862d-5949-8961-8b5a633405ea', '12377ff8-cafd-5e56-99cf-71419fa8529a', 'en', 'Spiced beef and lentil soup with vegetables', 'A hearty one-pot soup of ground beef, lentils, carrots, celery, zucchini and green beans in spiced tomato broth. Freezes well.', '<ol><li>Mix all the spices in a small bowl.</li><li>Heat the oil in a large pot over medium-high heat and cook the onion and garlic for 3 minutes until golden at the edges.</li><li>Turn the heat to high, add the beef and cook, breaking it up, until no longer red. Add 2 tablespoons of the spice mix and cook 2 more minutes.</li><li>Add the carrot and celery and stir for a minute. Pour in the water and stock, add the tomatoes, lentils and the remaining spice mix. Bring to a simmer, cover and simmer gently.</li><li>After 15 minutes add the zucchini and green beans and cook about 10 more minutes until the lentils are soft (25–30 minutes total).</li><li>Taste, adjust the salt and serve with yogurt and cilantro.</li></ol><p><em>Serve with yogurt and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('4ee7873b-8dd9-5ea9-8766-39872c982adc', 'fe36a169-2bbd-5944-a03d-6d1c719dea48', 'ru', 'Палак панир: шпинат со сливками и сыром панир', 'Классическое индийское вегетарианское блюдо: много шпината, тушёного с луком, специями, помидорами и сливками, и золотистые кубики сыра панир.', '<ol><li>Нарежьте панир ломтиками толщиной 1,25 см, а затем кусочками примерно 2,5 × 2 см. Растопите половину ги на антипригарной сковороде на средне сильном огне и обжарьте панир в два приёма по 1–1,5 минуты с каждой стороны до золотистого цвета. Переложите на бумажное полотенце.</li><li>В большой кастрюле на среднем огне растопите оставшееся ги, добавьте лук, пажитник, зиру, кориандр, соль и перец. Готовьте 3 минуты, пока лук не размягчится.</li><li>Добавьте чеснок и имбирь на 2 минуты, затем помидоры и чили на 3 минуты.</li><li>Добавляйте шпинат порциями вместе с водой, каждый раз давая ему завянуть. Готовьте ещё 10 минут на среднем огне, иногда помешивая.</li><li>Влейте сливки и лимонный сок и 3 минуты аккуратно помешивайте. Половину шпината переложите в высокую ёмкость и пробейте погружным блендером, затем верните в кастрюлю.</li><li>Осторожно вмешайте обжаренный панир и подавайте.</li></ol><p><em>Подавайте с рисом басмати или лепёшками.</em></p>', CURRENT_TIMESTAMP),
  ('6df3501c-4ac4-571e-bf1b-df9b00e811ac', 'fe36a169-2bbd-5944-a03d-6d1c719dea48', 'en', 'Palak paneer: spinach curry with paneer', 'A classic Indian vegetarian dish of plenty of spinach simmered with onion, spices, tomatoes and cream, with golden pan-fried paneer cubes.', '<ol><li>Cut the paneer into ½-inch slices, then into pieces about 1 × ¾ inch. Melt half the ghee in a nonstick pan over medium-high heat and fry the paneer in two batches, 1–1½ minutes per side, until golden. Drain on paper towels.</li><li>Melt the remaining ghee in a large pot over medium heat, add the onion, fenugreek, cumin, coriander, salt and pepper and cook 3 minutes until the onion is soft.</li><li>Add the garlic and ginger for 2 minutes, then the tomatoes and chilli for 3 minutes.</li><li>Add the spinach in batches with the water, letting each batch wilt. Cook another 10 minutes over medium heat, stirring occasionally.</li><li>Add the cream and lemon juice and cook gently for 3 minutes. Move half the spinach to a tall container, purée with a stick blender and return it to the pot.</li><li>Gently fold in the pan-fried paneer and serve.</li></ol><p><em>Serve over basmati rice or with flatbread.</em></p>', CURRENT_TIMESTAMP),
  ('deb5d7f0-4728-564c-9aab-5c6282fddb2f', 'a17071ca-49a9-5221-89ad-f0eeb3acf3bb', 'ru', 'Южноиндийское карри из запечённых баклажанов', 'Баклажаны, запечённые при высокой температуре, а затем протушенные в насыщенном соусе с горчичными семенами, листьями карри, чесноком, имбирём и специями. Веганское и умеренно острое.', '<ol><li>Разогрейте духовку до 240 °C. Нарежьте баклажаны брусочками 2 см, перемешайте с маслом, солью и перцем, выложите на противень с пергаментом. Запекайте 20 минут, переверните и запекайте ещё 10 минут до карамельных краёв и мягкой серединки.</li><li>В большой кастрюле на среднем огне разогрейте масло, добавьте горчичные семена на 15 секунд, затем листья карри ещё на 15 секунд.</li><li>Добавьте лук и 5 минут обжаривайте до золотисто-коричневого цвета. Добавьте томатное пюре на минуту, затем чеснок и имбирь на 2 минуты.</li><li>Всыпьте специи и соль и готовьте ещё 3 минуты: получится густая паста, не давайте ей подгореть, при необходимости добавьте воды.</li><li>Влейте воду, добавьте баклажаны, аккуратно перемешайте, прикройте крышкой и тушите на слабом огне 30 минут, пару раз осторожно помешав и при необходимости подлив воды.</li><li>Влейте кокосовое молоко, посолите по вкусу. Подавайте с рисом, йогуртом и кинзой.</li></ol><p><em>Подавайте с рисом басмати, йогуртом и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('90776dc1-6710-5eb4-9202-5fdd676d648a', 'a17071ca-49a9-5221-89ad-f0eeb3acf3bb', 'en', 'South Indian roasted eggplant curry', 'Eggplant roasted at high heat then simmered in an intensely spiced sauce of mustard seeds, curry leaves, garlic, ginger and ground spices. Vegan and fairly mild.', '<ol><li>Preheat the oven to 240 °C (450 °F). Cut the eggplant into 2 cm batons, toss with oil, salt and pepper and spread on a parchment-lined tray. Roast 20 minutes, turn and roast 10 more until edges are caramelised and the centres soft.</li><li>Heat the oil in a large pot over medium heat, add the mustard seeds for 15 seconds, then the curry leaves for another 15 seconds.</li><li>Add the onion and cook 5 minutes until golden brown. Stir in the tomato for a minute, then the garlic and ginger for 2 minutes.</li><li>Add the ground spices and salt and cook 3 more minutes into a thick paste, adding a splash of water if it starts to burn.</li><li>Pour in the water, add the eggplant, stir gently, partially cover and simmer on low 30 minutes, stirring carefully once or twice and adding water if it dries out.</li><li>Stir in the coconut milk and adjust the salt. Serve with rice, yogurt and cilantro.</li></ol><p><em>Serve with basmati rice, yogurt and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('f66ff5d2-736b-555a-984d-ab8c716d173d', '7eb1623c-d0e7-5587-b564-fc1c5fecfe98', 'ru', 'Курица в медово-горчичном соусе', 'Золотистые полоски куриной грудки в сливочно-кисловатом соусе из дижонской горчицы, мёда и куриного бульона. Домашний аналог готовых соусов.', '<ol><li>Посолите и поперчите курицу, посыпьте чесночным порошком.</li><li>Для загустителя смешайте в миске майонез, муку и крахмал.</li><li>Разогрейте 1,5 ст. л. масла на сковороде на средне сильном огне и обжарьте курицу по 2 минуты с каждой стороны до золотистого цвета. Переложите на тарелку.</li><li>Убавьте огонь до среднего, добавьте оставшееся масло, 20 секунд обжарьте чеснок, влейте бульон, доведите до кипения, соскребая со дна румяные кусочки.</li><li>Вмешайте венчиком горчицу и мёд, затем загуститель. Добавьте тимьян и зернистую горчицу и готовьте 1–2 минуты до загустения.</li><li>Верните курицу с соком в соус, переверните и прогрейте около 1,5 минут. Посыпьте петрушкой и подавайте.</li></ol><p><em>Подавайте на картофельном пюре с простым салатом.</em></p>', CURRENT_TIMESTAMP),
  ('f2f0a7c8-4a22-5099-99e2-1a453d283d49', '7eb1623c-d0e7-5587-b564-fc1c5fecfe98', 'en', 'Honey mustard chicken', 'Golden strips of chicken breast in a tangy, sweet and creamy sauce of Dijon mustard, honey and chicken stock. A homemade take on supermarket simmer sauces.', '<ol><li>Season the chicken with salt, pepper and the garlic powder.</li><li>For the thickener, mix the mayonnaise, flour and cornstarch together in a small bowl.</li><li>Heat 1½ tablespoons of the oil in a skillet over medium-high heat and brown the chicken 2 minutes per side. Transfer to a plate.</li><li>Reduce the heat to medium, add the remaining oil, sauté the garlic 20 seconds, pour in the stock and bring to a simmer, scraping up the browned bits.</li><li>Whisk in the Dijon and honey, then the thickener. Add the thyme and wholegrain mustard and cook 1–2 minutes until thickened.</li><li>Return the chicken and its juices to the sauce, turn to coat and heat through about 1½ minutes. Garnish with parsley and serve.</li></ol><p><em>Serve on mashed potatoes with a simple side salad.</em></p>', CURRENT_TIMESTAMP),
  ('fff1542b-616b-5522-b7b0-4bf98dc36475', '20a5610d-3a1b-5433-8e0d-f32445c5da9b', 'ru', 'Курица с рисом и бок-чоем в одной кастрюле по-китайски', 'Что-то среднее между жареным рисом и курицей по-китайски: маринованные куриные бёдра, рис и бок-чой, приготовленные в одной кастрюле в устричном и тёмном соевом соусе.', '<ol><li>В большой миске смешайте кулинарное вино, устричный и тёмный соевый соус, белый перец и 2 зубчика чеснока. Добавьте куриные бёдра, разрезанные пополам, и оставьте мариноваться минимум на 10 минут.</li><li>Стебли бок-чоя нарежьте по 2,5 см, листья крупнее. Достаньте курицу из маринада, стряхните лишнее, маринад сохраните.</li><li>Разогрейте масло в кастрюле на средне сильном огне и обжарьте курицу по 90 секунд с каждой стороны до золотистого цвета. Переложите на тарелку.</li><li>В ту же кастрюлю добавьте лук, чеснок и имбирь и обжарьте 2 минуты. Всыпьте рис и перемешайте, добавьте бульон, оставшийся маринад и стебли бок-чоя.</li><li>Выложите курицу сверху с накопившимся соком. Накройте крышкой, доведите до кипения, убавьте огонь и готовьте 12–15 минут, пока жидкость не впитается.</li><li>Снимите с огня, быстро разложите листья бок-чоя сверху и закройте крышкой на 10 минут. Перемешайте и подавайте с зелёным луком и кунжутом.</li></ol><p><em>Посыпьте зелёным луком и кунжутом, подайте с пастой чили.</em></p>', CURRENT_TIMESTAMP),
  ('2f1f69db-6996-596b-8e7c-8e969902622b', '20a5610d-3a1b-5433-8e0d-f32445c5da9b', 'en', 'One-pot Chinese chicken and rice with bok choy', 'Something between fried rice and Chinese chicken: marinated chicken thighs, rice and bok choy cooked in one pot with oyster and dark soy sauce.', '<ol><li>In a large bowl mix the cooking wine, oyster sauce, dark soy sauce, white pepper and 2 cloves of garlic. Add the halved chicken thighs and marinate at least 10 minutes.</li><li>Cut the bok choy stems into 2.5 cm pieces and the leaves a little larger. Remove the chicken from the marinade, shaking off the excess, and reserve the marinade.</li><li>Heat the oil in a large pot over medium-high heat and brown the chicken 90 seconds per side. Remove to a plate.</li><li>In the same pot cook the onion, garlic and ginger for 2 minutes, then stir in the rice. Add the stock, reserved marinade and bok choy stems.</li><li>Lay the chicken on top with the pooled juices. Cover, bring to a simmer, reduce to medium and cook 12–15 minutes until the liquid is absorbed.</li><li>Remove from the heat, quickly scatter the bok choy leaves on top, replace the lid and rest 10 minutes. Toss and serve with green onion and sesame seeds.</li></ol><p><em>Garnish with green onion and sesame seeds and serve with chilli paste.</em></p>', CURRENT_TIMESTAMP),
  ('69896d02-5e91-509f-852a-4c24567d1673', 'a1d6c279-a522-588b-b887-0992ddfcee7a', 'ru', 'Куриная грудка в духовке с паприкой и коричневым сахаром', 'Сочная куриная грудка, отбитая до ровной толщины и запечённая при высокой температуре. Щепотка коричневого сахара в специях даёт румяную корочку и немного сока.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>Отбейте грудки скалкой или молоточком до толщины около 1,5 см. Так они приготовятся равномерно и останутся нежными.</li><li>Смешайте коричневый сахар, паприку, орегано, чесночный порошок, соль и перец.</li><li>Застелите противень фольгой и пергаментом. Выложите грудки, сбрызните половиной масла, разотрите и посыпьте половиной специй. Переверните и повторите с другой стороны.</li><li>Запекайте около 18 минут, пока поверхность не станет золотистой или температура внутри не достигнет 74 °C.</li><li>Сразу переложите на тарелки, дайте постоять 3–5 минут и посыпьте петрушкой.</li></ol><p><em>Подождите 3–5 минут перед подачей и посыпьте петрушкой. Подходит к рису, картофелю и овощам.</em></p>', CURRENT_TIMESTAMP),
  ('33529ae6-2468-5b8d-b178-5fa535b637e6', 'a1d6c279-a522-588b-b887-0992ddfcee7a', 'en', 'Oven-baked chicken breast with brown sugar and paprika', 'Juicy chicken breasts pounded to an even thickness and baked hot and fast. A touch of brown sugar in the rub gives a golden crust and a little natural sauce.', '<ol><li>Preheat the oven to 220 °C (425 °F).</li><li>Pound the chicken to about 1.5 cm thick with a rolling pin or mallet so it cooks evenly and stays tender.</li><li>Mix the brown sugar, paprika, oregano, garlic powder, salt and pepper.</li><li>Line a tray with foil and parchment. Place the chicken on it, drizzle with half the oil, rub it in and sprinkle with half the seasoning; flip and repeat on the other side.</li><li>Bake about 18 minutes, until the surface is golden or the internal temperature reaches 74 °C (165 °F).</li><li>Transfer to plates at once, let rest 3–5 minutes and sprinkle with parsley.</li></ol><p><em>Rest 3–5 minutes, then scatter with parsley. Great with rice, potatoes or vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('00578c53-2c4e-5cdb-8e19-64367db17b75', 'dd0f6435-e82c-540a-8c98-6e81a8213f11', 'ru', 'Свиная корейка в мультиварке в медово-чесночном масляном соусе', 'Большой кусок свинины с пряной сухой смесью, обжаренный и томлённый в мультиварке в соусе из мёда, сливочного масла, чеснока и яблочного уксуса. Соус уваривается до сиропа.', '<ol><li>Натрите свинину небольшим количеством масла. Смешайте паприку, тимьян, чесночный и луковый порошки, кайенский перец, перец и соль и посыпьте мясо, прижимая специи ладонью.</li><li>Разогрейте оставшееся масло на большой сковороде и обжарьте мясо со всех сторон до насыщенной золотистой корочки, не пережигая специи. Переложите в мультиварку.</li><li>Вытрите сковороду, растопите сливочное масло, обжарьте чеснок минуту до золотистого цвета. Добавьте мёд, яблочный уксус, соль и перец, быстро прокипятите 30 секунд.</li><li>Залейте мясо соусом, накройте крышкой и готовьте на низкой мощности 4–5 часов (корейка) или около 10 часов (лопатка).</li><li>Переложите мясо на блюдо, накройте фольгой на 10–20 минут. Слейте жидкость из чаши в кастрюлю, добавьте крахмал, растворённый в воде, и уварите 5 минут до сиропообразной консистенции.</li><li>Нарежьте мясо толстыми ломтями и подавайте с горячим соусом.</li></ol><p><em>Нарежьте толстыми ломтями и подавайте с обильным количеством соуса и картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('67f1e21d-2d11-5d40-8ec9-9c347fc9408e', 'dd0f6435-e82c-540a-8c98-6e81a8213f11', 'en', 'Slow cooker honey garlic butter pork loin', 'A large pork loin rubbed with spices, seared and slow cooked in a sauce of honey, butter, garlic and cider vinegar that reduces to a syrup.', '<ol><li>Rub the pork with a little oil. Mix the paprika, thyme, garlic powder, onion powder, cayenne, pepper and salt and pat the rub all over the meat.</li><li>Heat the remaining oil in a large skillet and sear the pork on all sides until deep golden, without burning the spices. Move to the slow cooker.</li><li>Wipe the pan, melt the butter and cook the garlic for 1 minute until golden. Add the honey, cider vinegar, salt and pepper and boil briskly for 30 seconds.</li><li>Pour the sauce over the pork, cover and cook on low for 4–5 hours for loin, or about 10 hours for shoulder.</li><li>Transfer the pork to a platter and tent with foil for 10–20 minutes. Pour the cooking juices into a saucepan, stir in the cornstarch mixed with water and simmer 5 minutes until syrupy.</li><li>Slice the pork thickly and serve with plenty of hot sauce.</li></ol><p><em>Slice thickly and serve with plenty of sauce and mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('7902f4a3-77cc-5ed4-acbd-d01253e8b996', '45149597-3047-5b04-b428-42c6b8acba6e', 'ru', 'Спагетти с консервированным тунцом, каперсами и лимоном', 'Быстрая паста из запасов: тунец в масле, чеснок, анчоусы, каперсы, лимонный сок и цедра. Масло из банки служит основой соуса.', '<ol><li>Доведите до кипения 3 л подсоленной воды и сварите спагетти на минуту меньше, чем указано на упаковке. Перед сливом отлейте стакан воды от пасты.</li><li>В той же кастрюле разогрейте масло из банок с тунцом на среднем огне, добавьте чеснок, анчоусы и хлопья чили. Готовьте минуту, помешивая.</li><li>Добавьте пасту, каперсы и около 80 мл воды от пасты. Перемешивайте двумя лопатками 2 минуты.</li><li>Выключите огонь, добавьте тунец, петрушку, лимонную цедру и сок, соль и перец. Аккуратно перемешайте, сохраняя кусочки тунца, и сразу подавайте.</li></ol><p><em>Подавайте сразу, пока паста горячая.</em></p>', CURRENT_TIMESTAMP),
  ('3303d7e1-a54e-5afa-bc44-5ca2fa8510ae', '45149597-3047-5b04-b428-42c6b8acba6e', 'en', 'Spaghetti with canned tuna, capers and lemon', 'A quick pantry pasta with tuna in oil, garlic, anchovies, capers, lemon juice and zest. The oil from the can becomes the base of the sauce.', '<ol><li>Boil 3 litres of salted water and cook the spaghetti 1 minute less than the package says. Before draining, scoop out about a cup of the pasta water.</li><li>In the same pot heat the oil from the tuna cans over medium heat and add the garlic, anchovies and chilli flakes. Cook, stirring, for 1 minute.</li><li>Add the pasta, capers and about 80 ml of pasta water. Toss with two spatulas for 2 minutes.</li><li>Turn off the heat and add the tuna, parsley, lemon zest and juice, salt and pepper. Toss gently, keeping some chunks of tuna, and serve at once.</li></ol><p><em>Serve immediately while hot.</em></p>', CURRENT_TIMESTAMP),
  ('4bf8a24d-60af-5ab7-a47e-516e5e43fe6e', '40c37c15-7e1c-59a9-a7e5-60b039b8b064', 'ru', 'Запечённый молодой картофель с чесноком и тимьяном', 'Мелкий картофель, запечённый половинками с оливковым маслом, тимьяном и раздавленным чесноком в кожуре до золотистой хрустящей корочки.', '<ol><li>Разогрейте духовку до 200 °C.</li><li>Раздавите зубчики чеснока в кожуре плоской стороной ножа так, чтобы они лопнули, но остались целыми.</li><li>На противне полейте картофель маслом, посолите и поперчите, перемешайте. Добавьте тимьян и чеснок и разложите в один слой.</li><li>Запекайте 30 минут, перемешайте и запекайте ещё 25–35 минут до золотистой корочки.</li><li>Посыпьте рубленой зеленью и подавайте сразу.</li></ol><p><em>Хорошо подходит ко всему: к мясу, птице, рыбе. Посыпьте петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('14fcf7c5-96fc-582a-8c3a-ad1b8a7fcabf', '40c37c15-7e1c-59a9-a7e5-60b039b8b064', 'en', 'Easy roast baby potatoes with garlic and thyme', 'Halved baby potatoes roasted with olive oil, thyme and smashed unpeeled garlic until golden and crisp.', '<ol><li>Preheat the oven to 200 °C (400 °F).</li><li>Smash the unpeeled garlic cloves with the flat of a knife so they burst open but stay mostly whole.</li><li>On a baking tray drizzle the halved potatoes with oil, season with salt and pepper and toss. Add the thyme and garlic and spread them out.</li><li>Roast 30 minutes, toss, then roast another 25–35 minutes until golden.</li><li>Sprinkle with chopped herbs and serve immediately.</li></ol><p><em>A side for almost anything. Finish with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('aab133d9-a6b3-54f7-b8fb-9697a5ecb344', '3d2ccf0b-68d9-576a-a011-6c017a5f1435', 'ru', 'Феттучини со сливочным соусом и жареными грибами', 'Золотистые шампиньоны с чесноком, обжаренные на сливочном масле, соус из белого вина, бульона, сливок и пармезана, и феттучини.', '<ol><li>Сварите феттучини в подсоленной воде на минуту меньше, чем указано на упаковке. Перед сливом отлейте стакан воды от пасты.</li><li>На большой сковороде на сильном огне растопите сливочное масло с оливковым и обжарьте нарезанные грибы, помешивая. Когда они пустят сок, добавьте щепотку соли и перца.</li><li>Когда грибы зарумянятся, добавьте чеснок и готовьте до золотистого цвета.</li><li>Влейте вино (будет много пара), соскребите прикипевшее со дна и выпаривайте, пока запах вина не исчезнет.</li><li>Добавьте бульон, сливки, пармезан, соль и перец, перемешайте и варите 2 минуты.</li><li>Переложите пасту в соус и перемешивайте 1–2 минуты, пока он не загустеет. Если соус слишком густой, добавьте ложку воды от пасты. Подавайте с петрушкой и пармезаном.</li></ol><p><em>Посыпьте пармезаном и петрушкой, подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('1ef6f347-1429-5a4c-b27c-562be97d3720', '3d2ccf0b-68d9-576a-a011-6c017a5f1435', 'en', 'Creamy garlic mushroom fettuccine', 'Golden buttery garlic mushrooms in a white wine, broth, cream and Parmesan sauce tossed with fettuccine.', '<ol><li>Cook the fettuccine in salted water 1 minute less than the package time; scoop out a cup of pasta water before draining.</li><li>In a large skillet over high heat, melt the butter with the oil and cook the sliced mushrooms, stirring. When they begin to release liquid, add a pinch of salt and pepper.</li><li>When the mushrooms are golden, add the garlic and cook until golden.</li><li>Add the wine (it will steam!), scrape the bottom and simmer rapidly until the wine smell is gone.</li><li>Add the broth, cream, Parmesan, salt and pepper, stir and simmer for 2 minutes.</li><li>Add the pasta to the sauce and toss for 1–2 minutes until it thickens. If too thick, add a splash of pasta water. Serve with parsley and extra Parmesan.</li></ol><p><em>Top with extra Parmesan and parsley and serve at once.</em></p>', CURRENT_TIMESTAMP),
  ('eee6ea4f-bb0e-5311-b1db-1a98eea0a70a', 'de72ea30-ee81-54c8-92d8-801e23361b03', 'ru', 'Карамелизированный свиной фарш по-вьетнамски с рисом', 'Быстрое блюдо на сковороде: свиной фарш с луком, имбирём и чесноком, глазированный в карамели из коричневого сахара и рыбного соуса. Подаётся с рисом.', '<ol><li>Разогрейте масло на большой сковороде на сильном огне.</li><li>Обжарьте лук, имбирь, чеснок и чили 2 минуты.</li><li>Добавьте фарш и жарьте около 2 минут, разбивая лопаткой, пока он не побелеет.</li><li>Добавьте сахар и рыбный соус, перемешайте и оставьте без помешивания примерно на 2 минуты, пока жидкость не выпарится и мясо не начнёт карамелизироваться. Затем перемешайте и снова оставьте на 30 секунд; повторите ещё 2 раза до нужного цвета.</li><li>Подавайте на рисе с зелёным луком, огурцом, морковью и помидором.</li></ol><p><em>Подавайте с рисом или рисовой вермишелью, огурцом, морковью и помидором.</em></p>', CURRENT_TIMESTAMP),
  ('13f90c70-fab2-5923-b45a-ac05b4f6752c', 'de72ea30-ee81-54c8-92d8-801e23361b03', 'en', 'Vietnamese caramelised ground pork rice bowls', 'A quick skillet dish of ground pork with onion, ginger and garlic glazed in a brown sugar and fish sauce caramel. Served over rice.', '<ol><li>Heat the oil in a large skillet over high heat.</li><li>Sauté the onion, ginger, garlic and chili for 2 minutes.</li><li>Add the pork and cook about 2 minutes, breaking it up, until it turns white all over.</li><li>Add the sugar and fish sauce, stir, and leave untouched about 2 minutes until the juices cook off and the pork starts to caramelise. Stir, then leave 30 seconds; repeat twice more to your preferred colour.</li><li>Serve over rice garnished with green onion and with cucumber, carrot and tomato on the side.</li></ol><p><em>Serve over rice or vermicelli with cucumber, carrot and tomato on the side.</em></p>', CURRENT_TIMESTAMP),
  ('bf5446fa-eccc-5bf3-832a-72d4b12fa45e', '05573326-b1fe-548a-8ea3-f561f8554835', 'ru', 'Куриные бёдра без кожи с хрустящей корочкой и чесночным соусом', 'Бёдра без кожи обжариваются на среднем огне до золотистой хрустящей корочки, затем получают чесночно-масляный соус на белом вине. Готовится за 15 минут.', '<ol><li>Посыпьте бёдра с обеих сторон чесночным порошком, солью и перцем.</li><li>Разогрейте масло на большой сковороде на среднем огне и выложите курицу гладкой стороной вниз. Слегка прижмите лопаткой и жарьте 5 минут до золотистой хрустящей корочки.</li><li>Переверните, снова прижмите и жарьте 2 минуты. Добавьте чеснок и сливочное масло и готовьте минуту, пока чеснок не станет золотистым.</li><li>Влейте вино, прибавьте огонь и размешайте, растворяя прикипевшие кусочки. Быстро выпаривайте около 1,5 минут, пока запах алкоголя не исчезнет.</li><li>Снимите с огня и подавайте курицу с соусом, посыпав петрушкой.</li></ol><p><em>Подавайте с рисом, картофельным пюре или салатом, полив соусом со сковороды.</em></p>', CURRENT_TIMESTAMP),
  ('9352a000-90ca-509a-bd6f-f7d9aae1036b', '05573326-b1fe-548a-8ea3-f561f8554835', 'en', 'Crispy garlic chicken thighs with white wine pan sauce', 'Skinless chicken thighs seared slowly until crisp and golden, then finished with a garlic butter and white wine pan sauce. Ready in 15 minutes.', '<ol><li>Season both sides of the chicken with garlic powder, salt and pepper.</li><li>Heat the oil in a large skillet over medium heat and lay the chicken smooth-side down. Press lightly with a spatula and cook 5 minutes until deep golden and crisp.</li><li>Turn, press lightly again and cook for 2 minutes. Add the garlic and butter and cook 1 minute until the garlic is light golden.</li><li>Pour in the wine, turn up the heat and stir to dissolve the browned bits. Simmer rapidly for about 1½ minutes until the alcohol smell is gone.</li><li>Remove from the heat and serve the chicken with the sauce, sprinkled with parsley.</li></ol><p><em>Serve with rice, mashed potatoes or a salad, spooning over the pan sauce.</em></p>', CURRENT_TIMESTAMP),
  ('455a4b10-a89f-561a-9d7e-286c86bcfa56', 'ed5133ed-889f-5d70-9065-e05cb8d5e3fe', 'ru', 'Вьетнамские боулы с лемонграссовой курицей и рисовой вермишелью', 'Курица в маринаде с лемонграссом и чесноком, жаренная до золотистого цвета, подаётся на рисовой вермишели со свежими овощами, зеленью и кисло-сладким соусом нуок тям.', '<ol><li>Смешайте курицу с ингредиентами маринада и оставьте минимум на час, можно до суток.</li><li>Для соуса нуок тям смешайте все ингредиенты, размешав сахар. Настаивайте не менее 20 минут.</li><li>Разогрейте масло на сковороде на среднем огне. Достаньте курицу из маринада, стряхните кусочки лемонграсса и жарьте с каждой стороны до тёмно-золотистой корочки и готовности, около 6–8 минут всего.</li><li>Дайте курице отдохнуть 5 минут и нарежьте тонкими ломтиками.</li><li>Замочите вермишель в горячей воде на 3 минуты (или по инструкции), откиньте и промойте холодной водой.</li><li>В каждую миску положите вермишель, овощи, зелень и курицу, щедро полейте соусом и подавайте с лаймом.</li></ol><p><em>Выложите курицу, овощи, лапшу и соус отдельно, чтобы каждый собрал свою миску. Подавайте с дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('e07f03b0-781e-50d0-9172-971f9f596367', 'ed5133ed-889f-5d70-9065-e05cb8d5e3fe', 'en', 'Vietnamese lemongrass chicken vermicelli bowls', 'Chicken marinated in lemongrass and garlic, pan-fried until golden and served over rice vermicelli with fresh vegetables, herbs and a sweet-sour nuoc cham sauce.', '<ol><li>Combine the chicken with the marinade ingredients and refrigerate for at least 1 hour and up to 24 hours.</li><li>Mix the nuoc cham ingredients, stirring until the sugar dissolves, and let stand at least 20 minutes.</li><li>Heat oil in a pan over medium heat. Remove the chicken from the marinade, shake off the lemongrass bits and cook each side until dark golden and cooked through, about 6–8 minutes total.</li><li>Rest the chicken 5 minutes, then slice thinly.</li><li>Soak the vermicelli in hot water for 3 minutes (or per package), drain and rinse under cold water.</li><li>Into each bowl put noodles, vegetables, herbs and chicken, drizzle generously with sauce and serve with lime.</li></ol><p><em>Set out the chicken, vegetables, noodles and sauce separately so everyone builds their own bowl. Serve with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('c5fd18cb-976d-5817-8354-8bed0ba24fc5', 'cdfe3efc-bac0-5d4e-ae5c-3cbc13010cd8', 'ru', 'Курица пармиджана в аэрогриле с моцареллой', 'Тонкие куриные отбивные в хрустящей панировке с пармезаном запекаются в аэрогриле, затем получают томатный соус и ломтик моцареллы.', '<ol><li>Разрежьте грудки вдоль пополам, накройте пергаментом и отбейте до одинаковой толщины.</li><li>Выложите на три тарелки муку, взбитое яйцо и смесь сухарей с пармезаном.</li><li>Обваляйте куриное филе в муке, затем в яйце и в сухарях.</li><li>Выложите в аэрогриль и готовьте при 180 °C 15 минут до золотистого цвета.</li><li>Выложите на каждый кусок 1–2 ложки томатного соуса и ломтик моцареллы. Верните в аэрогриль ещё на 5–10 минут, пока сыр не зарумянится, а курица не будет готова.</li><li>Подавайте с томатным соусом, чёрным перцем и листьями базилика.</li></ol><p><em>Подавайте со спагетти и дополнительным томатным соусом, посыпав листьями базилика.</em></p>', CURRENT_TIMESTAMP),
  ('716ab561-5e55-5ba3-91eb-629df9ec7622', 'cdfe3efc-bac0-5d4e-ae5c-3cbc13010cd8', 'en', 'Air fryer chicken parmigiana with mozzarella', 'Thin breaded chicken cutlets with a Parmesan crumb are air fried, then topped with tomato sauce and a slice of mozzarella.', '<ol><li>Halve the chicken breasts lengthways, cover with parchment and bash to an even thickness.</li><li>Put the flour, beaten egg and the panko mixed with Parmesan on three separate plates.</li><li>Coat the chicken in flour, then egg, then the panko mix.</li><li>Place in the air fryer and cook at 180 °C (350 °F) for 15 minutes until golden.</li><li>Spoon 1–2 tablespoons of tomato sauce on each piece and top with a mozzarella slice. Return to the air fryer for 5–10 minutes until the cheese is golden and the chicken cooked through.</li><li>Serve with more tomato sauce, black pepper and torn basil leaves.</li></ol><p><em>Serve with spaghetti and extra tomato sauce, scattered with basil leaves.</em></p>', CURRENT_TIMESTAMP),
  ('133feb1d-d27e-5ff7-b1b6-8834e1b3cc4b', 'a93dbfe0-d9a1-5bf6-a6c4-43ab8c17c10b', 'ru', 'Джамбалайя с курицей и чоризо в одной сковороде', 'Рис, тушёный с курицей, острой колбасой чоризо, сладким перцем и томатами в каджунской приправе. Всё готовится в одной сковороде с крышкой.', '<ol><li>В большой глубокой сковороде с крышкой разогрейте масло на средне-сильном огне и обжарьте нарезанную курицу 5–8 минут до золотистого цвета. Переложите на тарелку.</li><li>В той же сковороде 3–4 минуты готовьте лук до мягкости.</li><li>Добавьте перец, чеснок, чоризо и каджунскую приправу и готовьте ещё 5 минут.</li><li>Верните курицу, всыпьте рис, добавьте томаты и бульон. Накройте крышкой и тушите на среднем огне 20–25 минут до мягкости риса.</li></ol><p><em>Подавайте прямо из сковороды с зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('8d0a4a17-cbdf-588e-a236-260f26efd07a', 'a93dbfe0-d9a1-5bf6-a6c4-43ab8c17c10b', 'en', 'One-pot chicken and chorizo jambalaya', 'Rice simmered with chicken, spicy chorizo, sweet pepper and tomatoes in Cajun seasoning, all cooked in one lidded pan.', '<ol><li>Heat the oil in a large lidded frying pan over medium-high heat and brown the chopped chicken for 5–8 minutes until golden. Set aside.</li><li>In the same pan cook the onion for 3–4 minutes until soft.</li><li>Add the pepper, garlic, chorizo and Cajun seasoning and cook 5 minutes more.</li><li>Stir in the chicken and rice, then add the tomatoes and stock. Cover and simmer over medium heat for 20–25 minutes until the rice is tender.</li></ol><p><em>Serve straight from the pan with chopped herbs.</em></p>', CURRENT_TIMESTAMP),
  ('a4ab28d8-9b1c-5474-a96c-7d473669d039', '7bf1b224-9f9a-5eae-a9b5-282a1c5ee96e', 'ru', 'Ригатони с колбасным фаршем, брокколи и чили', 'Быстрая паста: хрустящий фарш из свиных колбасок, брокколи, чеснок, чили, лимон и немного сметаны или крем-фреша.', '<ol><li>Сварите ригатони в кипящей подсоленной воде по инструкции, за 3–4 минуты до готовности добавьте брокколи. Слейте воду, оставив кружку отвара.</li><li>Пока варится паста, выдавите мясо из колбасок и положите на холодную сковороду с маслом. Готовьте на среднем огне 6–8 минут, помешивая, пока жир не вытопится, а мясо не станет золотистым и хрустящим. Переложите в миску.</li><li>Добавьте хлопья чили, чеснок и стебли петрушки и готовьте 2–3 минуты. Добавьте лимонную цедру и верните мясо в сковороду.</li><li>Добавьте пасту и брокколи, сметану, сок лимона и немного отвара. Прогрейте минуту. Подавайте с красным чили и петрушкой.</li></ol><p><em>Подавайте в мисках, посыпав кольцами свежего красного чили.</em></p>', CURRENT_TIMESTAMP),
  ('751ff899-d7de-50ee-a867-45ba31155ac1', '7bf1b224-9f9a-5eae-a9b5-282a1c5ee96e', 'en', 'Sausage, broccoli and chilli rigatoni', 'A quick pasta of crisp sausagemeat, broccoli, garlic, chilli, lemon and a little crème fraîche.', '<ol><li>Cook the rigatoni in boiling salted water per package directions, adding the broccoli for the last 3–4 minutes. Drain, reserving a mugful of the cooking water.</li><li>Meanwhile, squeeze the sausagemeat from its skins into a cold pan with the oil. Cook over medium heat 6–8 minutes, stirring, until the fat renders and the meat is golden and crisp. Remove to a bowl.</li><li>Add the chilli flakes, garlic and parsley stems and cook 2–3 minutes. Stir in the lemon zest and return the sausagemeat.</li><li>Toss in the pasta and broccoli, crème fraîche, lemon juice and a splash of cooking water and cook another minute. Serve with the sliced red chilli and parsley.</li></ol><p><em>Serve in bowls topped with sliced fresh red chilli.</em></p>', CURRENT_TIMESTAMP),
  ('9caadee7-1986-586c-b744-fa2218aad7cb', '87bd1789-ea66-5a75-b444-fe1d6bb78bdd', 'ru', 'Картофельный суп с беконом, чеддером и сметаной', 'Густой молочный суп с картофелем, жареным луком и хрустящим беконом. Сверху сметана, сыр, зелёный лук и шнитт-лук.', '<ol><li>Выложите бекон в один слой в большую глубокую сковороду, включите средний огонь и жарьте 7–8 минут, переворачивая, до хруста. Переложите на бумажное полотенце, затем грубо нарубите.</li><li>В беконном жире обжарьте лук 8–10 минут на среднем огне до золотистых краёв, в конце добавьте чеснок. Влейте молоко и бульон и доведите до кипения.</li><li>Добавьте картофель, убавьте огонь и варите 10 минут, пока он не станет очень мягким. Измельчите суп погружным блендером: можно оставить немного кусочков или взбить до гладкости.</li><li>Добавьте сметану и сыр, размешайте до расплавления, посолите и поперчите. При необходимости ненадолго верните на огонь.</li><li>Разлейте по тарелкам и украсьте сметаной, беконом, зелёным луком, шнитт-луком и сыром.</li></ol><p><em>Подавайте горячим с ложкой сметаны, беконом и тёртым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('bcccc160-d9e7-5123-813f-e95f9c1186f1', '87bd1789-ea66-5a75-b444-fe1d6bb78bdd', 'en', 'Loaded baked potato soup with bacon and cheddar', 'A thick creamy soup of potatoes, golden onion and crisp bacon, finished with soured cream, cheddar, spring onions and chives.', '<ol><li>Lay the bacon in a single layer in a large deep pan over medium heat and cook 7–8 minutes, flipping, until very crisp. Drain on kitchen paper and roughly chop.</li><li>Cook the onion in the bacon fat 8–10 minutes over medium heat until softening and golden at the edges, adding the garlic at the end. Pour in the milk and stock and bring to a boil.</li><li>Add the potatoes, reduce to a simmer and cook 10 minutes until very tender. Blitz with a hand blender, leaving it a little chunky or completely smooth.</li><li>Stir in the soured cream and cheese until melted; season. Return briefly to the heat if they do not melt.</li><li>Ladle into bowls and top with soured cream, bacon, spring onions, chives and more cheese.</li></ol><p><em>Serve hot topped with soured cream, bacon bits and extra cheese.</em></p>', CURRENT_TIMESTAMP),
  ('078b78ae-35e4-5fe7-b721-54080821aad2', '5666c919-a5cc-5a31-9a85-bf242e23543a', 'ru', 'Белая фасоль в соусе карбонара', 'Фасоль в сливочном соусе из яиц и пармезана с хрустящей панчеттой. Простой вариант карбонары без пасты.', '<ol><li>Положите панчетту на холодную сковороду, включите средний огонь и жарьте 4–5 минут, пока жир не вытопится, а мясо не станет золотистым. Достаньте шумовкой на бумажное полотенце, жир оставьте и снимите сковороду с огня.</li><li>Взбейте яйца с пармезаном и большим количеством чёрного перца. Медленно влейте половину горячего жира, постоянно взбивая, чтобы яйца не свернулись.</li><li>Верните сковороду на слабый огонь, выложите фасоль в оставшийся жир и прогрейте на среднем огне 3–4 минуты, пока не пойдёт пар.</li><li>Снимите с огня и постепенно влейте яичную смесь, постоянно перемешивая. Добавьте несколько ложек жидкости из банки до шелковистой консистенции.</li><li>Верните почти всю панчетту, оставьте немного для украшения. Подавайте с пармезаном и перцем.</li></ol><p><em>Посыпьте пармезаном и чёрным перцем. Подойдёт с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('d96edbbf-66a8-58e7-a799-bfac8bef00b7', '5666c919-a5cc-5a31-9a85-bf242e23543a', 'en', 'Carbonara butter beans', 'Butter beans in a silky egg and Parmesan sauce with crisp pancetta. A pasta-free take on carbonara.', '<ol><li>Put the pancetta in a cold pan over medium heat and cook 4–5 minutes until the fat renders and it turns crisp and golden. Lift out onto kitchen paper, keep the fat and take the pan off the heat.</li><li>Whisk the eggs, Parmesan and plenty of black pepper. Slowly pour in half the hot fat, whisking constantly so the eggs don''t scramble.</li><li>Return the pan to low heat, tip the beans into the remaining fat, turn to medium and cook 3–4 minutes until steaming.</li><li>Remove from the heat and gradually pour in the egg mixture, stirring continuously. Loosen with a few spoonfuls of the bean liquid to a silky sauce.</li><li>Return most of the pancetta, saving a few pieces to garnish. Serve with extra Parmesan and pepper.</li></ol><p><em>Top with extra Parmesan and black pepper. Good with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('35388b79-f733-5f1e-a0a4-60cafb60d444', '6e8b9a54-5f80-5df9-a803-e7b105b87f14', 'ru', 'Курица карри в кокосовом молоке с запечённой цветной капустой', 'Куриные бёдра в томатно-кокосовом соусе с гарам масалой, куркумой и имбирём. Сверху подаётся цветная капуста, запечённая со специями до румяных краёв.', '<ol><li>Разогрейте духовку до 200 °C. Разберите цветную капусту на соцветия, листья тонко нарежьте, кочерыжку мелко порубите. Смешайте соцветия с маслом, зирой, кориандром и куркумой.</li><li>Выложите соцветия на противень и запекайте 30–40 минут до мягкости и подрумянивания краёв.</li><li>Тем временем на слабо-среднем огне 8–10 минут обжарьте красный лук, листья и кочерыжку цветной капусты до мягкости.</li><li>Добавьте куриные бёдра и обжарьте 4–5 минут до румяности. Добавьте чеснок и имбирь на пару минут, затем специи на минуту.</li><li>Добавьте томатную пасту и соевый соус, затем томаты с четвертью банки воды и кокосовое молоко. Доведите до кипения и варите 15–20 минут, пока курица не приготовится, а соус не загустеет.</li><li>Разложите карри по тарелкам, сверху положите запечённую цветную капусту и кинзу. Подавайте с рисом и лаймом.</li></ol><p><em>Подавайте с рисом басмати, лепёшками или пападамом, с кинзой и дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('6639dc64-e4a7-53d5-afc3-27c71ef47220', '6e8b9a54-5f80-5df9-a803-e7b105b87f14', 'en', 'Roasted cauliflower and chicken coconut curry', 'Chicken thighs in a tomato and coconut sauce with garam masala, turmeric and ginger, topped with spiced roasted cauliflower with charred edges.', '<ol><li>Heat the oven to 200 °C (180 °C fan). Break the cauliflower into florets, finely slice the leaves and chop the core. Toss the florets with the oil, cumin, coriander and turmeric.</li><li>Spread on a baking tray and roast for 30–40 minutes until tender with charred edges.</li><li>Meanwhile fry the red onion, cauliflower leaves and core in oil over medium-low heat for 8–10 minutes until softened.</li><li>Add the chicken and brown for 4–5 minutes. Mix in the garlic and ginger for a couple of minutes, then the spices for 1 minute.</li><li>Add the tomato purée and soy sauce, then the tomatoes with a quarter can of water and the coconut milk. Simmer 15–20 minutes until the chicken is cooked and the sauce thickens.</li><li>Divide the curry between bowls, top with the roasted cauliflower and coriander, and serve with rice and lime.</li></ol><p><em>Serve with basmati rice, naan or poppadums, topped with coriander and lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('27332cf4-48e2-50e3-a51a-5897d56915ea', '4ff0f940-53a3-5b4c-9cfe-c45377eb2e25', 'ru', 'Постное чили из трёх видов фасоли в мультиварке', 'Недорогое веганское чили с красной, чёрной фасолью и фасолью пинто, сладким перцем, томатами и копчёной паприкой. Всё складывается в мультиварку и готовится само.', '<ol><li>Выложите в мультиварку лук и перец. Добавьте всю фасоль вместе с жидкостью из банок.</li><li>Добавьте порошок чили, паприку, чесночные гранулы, зиру, кориандр и сушёные травы, затем томатную пасту и томаты. Перемешайте.</li><li>Готовьте на высокой мощности 3–4 часа, пока лук и перец не станут мягкими, а соус не загустеет. На плите достаточно 45–60 минут на слабом огне.</li><li>Посыпьте листьями кинзы и подавайте.</li></ol><p><em>Подавайте с рисом, лепёшками или картофелем, посыпав кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('4bace1b1-3a00-50a3-8d51-5b69b17107b0', '4ff0f940-53a3-5b4c-9cfe-c45377eb2e25', 'en', 'Slow cooker three-bean vegan chilli', 'A budget vegan chilli of kidney, black and pinto beans with peppers, tomatoes and smoked paprika. Everything goes into the slow cooker and cooks itself.', '<ol><li>Tip the onion and peppers into the slow cooker, then pour in all the beans with their liquid.</li><li>Add the chilli powder, paprika, garlic granules, cumin, coriander and dried herbs, then the tomato purée and chopped tomatoes. Stir.</li><li>Cook on high for 3–4 hours until the onion and peppers are soft and the sauce has thickened. On the stove, simmer gently for 45–60 minutes.</li><li>Scatter with coriander leaves and serve.</li></ol><p><em>Serve with rice, flatbreads or jacket potatoes, topped with coriander.</em></p>', CURRENT_TIMESTAMP),
  ('e7a4e203-5041-5b91-b7c6-b328fc6adebe', 'e51c61db-549f-5fb6-bb11-a6707cb7c03e', 'ru', 'Салат капрезе с курицей и бальзамической заправкой', 'Сытный салат: обжаренная курица на ромэне с помидорами черри, авокадо, моцареллой, базиликом и красным луком под заправкой из бальзамика и мёда.', '<ol><li>Смешайте в маленькой миске все ингредиенты заправки.</li><li>Посолите и поперчите куриное филе. Разогрейте на сковороде 1 ст. л. масла на сильном огне и обжарьте курицу по 2 минуты с каждой стороны. Убавьте огонь, накройте крышкой и готовьте ещё 5–6 минут до мягкости. Дайте чуть остыть и нарежьте.</li><li>В большой миске соедините ромэн, курицу, авокадо, черри, моцареллу, базилик и красный лук.</li><li>Полейте салат заправкой, аккуратно перемешайте и подавайте.</li></ol><p><em>Заправляйте салат непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('3fae1dff-1367-507b-947f-352131e1cbaf', 'e51c61db-549f-5fb6-bb11-a6707cb7c03e', 'en', 'Chicken caprese salad with balsamic dressing', 'A hearty salad of pan-seared chicken over romaine with cherry tomatoes, avocado, mozzarella, basil and red onion in a balsamic and honey dressing.', '<ol><li>Whisk all the dressing ingredients together in a small bowl.</li><li>Season the chicken with salt and pepper. Heat 1 tablespoon of oil in a skillet on high and sear the chicken 2 minutes per side. Reduce the heat to low, cover and cook another 5–6 minutes until tender. Let cool slightly and slice.</li><li>In a large bowl combine the romaine, chicken, avocado, cherry tomatoes, mozzarella, basil and red onion.</li><li>Pour the dressing over the salad, toss and serve.</li></ol><p><em>Dress the salad right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('48a1eb85-cf3f-5de5-905c-fe9d16db8a8a', 'bb1da669-509f-556e-882d-dd2778c68daf', 'ru', 'Салат с курицей, ромэном и авокадо', 'Обжаренное куриное филе на ромэне с помидорами черри, огурцами, красным луком и авокадо под лимонной заправкой с итальянскими травами.', '<ol><li>Посолите и поперчите курицу. Разогрейте в сковороде столовую ложку масла на сильном огне и обжарьте курицу по 2 минуты с каждой стороны. Убавьте огонь, накройте крышкой и готовьте ещё 5–6 минут до мягкости.</li><li>Тем временем смешайте масло, итальянские травы, чеснок, лимонный сок, соль и перец для заправки.</li><li>Соедините в миске ромэн, помидоры, огурцы, лук и авокадо. Нарежьте курицу, добавьте в салат, полейте заправкой и аккуратно перемешайте.</li></ol><p><em>Курицу нарежьте и положите на салат тёплой или остывшей.</em></p>', CURRENT_TIMESTAMP),
  ('d60f1050-98b8-5cb1-9c6b-bc74d260a723', 'bb1da669-509f-556e-882d-dd2778c68daf', 'en', 'Romaine avocado chicken salad', 'Pan-seared chicken over romaine with cherry tomatoes, cucumbers, red onion and avocado, with a lemony Italian-herb dressing.', '<ol><li>Season the chicken. Heat a tablespoon of oil in a skillet on high and sear the chicken 2 minutes per side. Turn the heat to low, cover and cook another 5–6 minutes until tender.</li><li>Meanwhile mix the oil, Italian seasoning, garlic, lemon juice, salt and pepper for the dressing.</li><li>Combine the romaine, tomatoes, cucumbers, onion and avocado in a bowl. Slice the chicken, add it, drizzle with the dressing and toss gently.</li></ol><p><em>Slice the chicken and add it to the salad warm or cooled.</em></p>', CURRENT_TIMESTAMP),
  ('fe3ca0da-3b72-54b6-8de5-052066159874', 'd3d92051-0f7f-590c-aa9f-c4189bea60ca', 'ru', 'Салат из кукурузы, цветной капусты и огурцов с майонезом', 'Хрустящий салат из сырой цветной капусты, огурцов, красного перца, зелёного лука и консервированной кукурузы с майонезом и укропом.', '<ol><li>Разберите цветную капусту на мелкие соцветия, огурцы нарежьте тонкими кружками, перец кубиками, зелёный лук мелко. Слейте жидкость с кукурузы и соедините всё в миске.</li><li>Добавьте майонез, соль и перец, хорошо перемешайте. Посыпьте укропом, если хотите.</li></ol><p><em>Хорошо подходит как лёгкая закуска или гарнир к мясу.</em></p>', CURRENT_TIMESTAMP),
  ('55befdbc-c5cc-5375-8126-d41f4049882a', 'd3d92051-0f7f-590c-aa9f-c4189bea60ca', 'en', 'Corn, cauliflower and cucumber salad with mayo', 'A crunchy salad of raw cauliflower, cucumbers, red pepper, green onions and canned corn dressed with mayonnaise and dill.', '<ol><li>Cut the cauliflower into small florets, slice the cucumbers thin, cube the pepper and finely chop the green onions. Drain the corn and combine everything in a bowl.</li><li>Add the mayonnaise, salt and pepper and mix well. Sprinkle with dill if you like.</li></ol><p><em>Works as a light starter or a side for meat.</em></p>', CURRENT_TIMESTAMP)
ON CONFLICT ("foodId", "language") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "content" = EXCLUDED."content", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "food_translations" ("id", "foodId", "language", "name", "description", "content", "updatedAt") VALUES
  ('50567c68-4dc8-5d42-993f-95d59f19612d', 'bbd664e8-4035-5457-8912-52e08ee9180b', 'ru', 'Салат из брокколи и цветной капусты с беконом и чеддером', 'Хрустящий салат из сырых соцветий брокколи и цветной капусты с хрустящим беконом, чеддером, семечками и клюквой в сладко-кисловатой майонезной заправке.', '<ol><li>Обжарьте нарезанный бекон на сковороде до хруста, переложите на бумажное полотенце и остудите.</li><li>Разберите брокколи и цветную капусту на мелкие соцветия, лук мелко нарубите.</li><li>В большой миске соедините брокколи, цветную капусту, лук, сыр, семечки, клюкву и бекон.</li><li>В отдельной миске взбейте майонез, сахар и уксус, добавьте заправку к салату и перемешайте.</li></ol><p><em>Дайте настояться в холодильнике 30 минут.</em></p>', CURRENT_TIMESTAMP),
  ('3a904b84-e963-5b49-b24a-33aa5076e982', 'bbd664e8-4035-5457-8912-52e08ee9180b', 'en', 'Broccoli cauliflower salad with bacon and cheddar', 'Crunchy raw broccoli and cauliflower florets with crispy bacon, cheddar, sunflower seeds and dried cranberries in a sweet and tangy mayonnaise dressing.', '<ol><li>Cook the chopped bacon in a pan until crispy and cool it on a paper towel.</li><li>Cut the broccoli and cauliflower into small florets and finely chop the onion.</li><li>In a large bowl combine the broccoli, cauliflower, onion, cheese, sunflower seeds, cranberries and bacon.</li><li>Whisk the mayonnaise, sugar and vinegar in a separate bowl, add to the salad and toss.</li></ol><p><em>Chill 30 minutes before serving to let the flavours meld.</em></p>', CURRENT_TIMESTAMP),
  ('2a482a1d-1453-503f-bf96-b76caccb36bd', 'b1fe3f4a-3b9d-5af9-bb4e-62896188b2b1', 'ru', 'Тако с курицей, авокадо и сметаной', 'Пшеничные тортильи с обжаренными кусочками куриных бёдер в пряной смеси, салатом, помидорами, кинзой, авокадо и сметаной. Ужин за 20 минут.', '<ol><li>Смешайте специи и натрите ими куриные бёдра. Обжарьте в сковороде с маслом до полной готовности.</li><li>Нарежьте курицу кубиками или ломтиками. Подготовьте начинки: нарежьте салат, помидоры, кинзу и авокадо.</li><li>Прогрейте тортильи на сухой сковороде.</li><li>Соберите тако: на тортилью выложите салат, курицу и остальные начинки, добавьте сметану.</li></ol><p><em>Каждому по два тако, с долькой лайма.</em></p>', CURRENT_TIMESTAMP),
  ('4e7f446b-9272-5497-aff9-a1ac2bf5abda', 'b1fe3f4a-3b9d-5af9-bb4e-62896188b2b1', 'en', 'Chicken tacos with avocado and sour cream', 'Flour tortillas filled with spice-rubbed seared chicken thighs, lettuce, tomatoes, cilantro, avocado and sour cream. Dinner in 20 minutes.', '<ol><li>Mix the spices and rub them over the chicken thighs. Sauté in oil in a skillet until fully cooked.</li><li>Cube or slice the chicken. Prepare the toppings: shred the lettuce, chop the tomatoes and cilantro and slice the avocado.</li><li>Warm the tortillas in a dry skillet.</li><li>Assemble: layer lettuce, chicken and the other toppings on a tortilla and add sour cream.</li></ol><p><em>Two tacos per person, with a lime wedge.</em></p>', CURRENT_TIMESTAMP),
  ('18c27dbe-d840-50a8-abf1-b2c812aeace1', '3e35427c-e207-526a-9323-0298698f1a53', 'ru', 'Омлет с беконом, шпинатом и сыром', 'Сытный омлет из четырёх яиц со сливками, хрустящим беконом, шпинатом, помидорами черри и расплавленным сыром, доведённый в духовке.', '<ol><li>Включите гриль в духовке (230 °C). Нарежьте бекон небольшими кусочками и обжарьте до нужной хрусткости, переложите на тарелку, оставив жир на сковороде.</li><li>Нарежьте помидоры черри пополам или на четвертинки, нарубите шпинат. Взбейте яйца со сливками, солью и перцем.</li><li>Разогрейте жир на сковороде, влейте яичную смесь и жарьте на средне сильном огне 1–2 минуты, пока низ не схватится.</li><li>Добавьте шпинат, помидоры, бекон и сыр и поставьте сковороду в духовку на 1–2 минуты, пока верх не схватится (ручка будет горячей).</li><li>Достаньте из духовки, сложите омлет пополам и разрежьте на 2 порции.</li></ol><p><em>Подавайте сразу, пока сыр горячий.</em></p>', CURRENT_TIMESTAMP),
  ('05e4f864-6a86-57b4-8125-48c9da4642ae', '3e35427c-e207-526a-9323-0298698f1a53', 'en', 'Bacon, spinach and cheese omelette', 'A hearty four-egg omelette with cream, crispy bacon, spinach, cherry tomatoes and melted cheese, finished under the broiler.', '<ol><li>Preheat the oven broiler (450 °F). Chop the bacon and cook to your preferred crispness, then remove, leaving the fat in the pan.</li><li>Halve or quarter the cherry tomatoes and chop the spinach. Beat the eggs with the cream, salt and pepper.</li><li>Reheat the fat in the pan, pour in the eggs and cook over medium-high heat for 1–2 minutes until the bottom sets.</li><li>Add the spinach, tomatoes, bacon and cheese and place the pan in the oven for 1–2 minutes until the top sets (the handle will be hot).</li><li>Remove from the oven, fold the omelette over and cut into 2 portions.</li></ol><p><em>Serve right away while the cheese is hot.</em></p>', CURRENT_TIMESTAMP),
  ('d92125aa-7fbd-52ad-b335-b414d5cdab47', '220f4cb3-bc28-54df-ad0c-518f0a6a29ad', 'ru', 'Креветки с брокколи и грибами в медово-соевом соусе', 'Быстрое блюдо: креветки, брокколи, шампиньоны и сладкий перец с чесноком и имбирём в густом соусе из соевого соуса, мёда и бульона.', '<ol><li>Разогрейте сковороду на среднем огне, добавьте 1 ст. л. масла и 1 ст. л. сливочного масла. Выложите креветки в один слой и жарьте по 2 минуты с каждой стороны. Переложите в миску.</li><li>В той же сковороде растопите ещё по 1 ст. л. масел и 3–4 минуты обжарьте лук до мягкости.</li><li>Добавьте оставшееся сливочное масло, брокколи, грибы и перец и готовьте около 5 минут до мягкости. Добавьте чеснок и имбирь на пару минут.</li><li>Смешайте ингредиенты соуса, влейте в сковороду и доведите до лёгкого кипения. Готовьте на среднем огне, пока соус не загустеет.</li><li>Верните креветки в сковороду, прогрейте и подавайте с рисом, посыпав луком и кунжутом.</li></ol><p><em>Подавайте с отварным белым рисом.</em></p>', CURRENT_TIMESTAMP),
  ('5ad0642c-b251-51e5-8bb2-534af74b2603', '220f4cb3-bc28-54df-ad0c-518f0a6a29ad', 'en', 'Shrimp stir fry with broccoli and mushrooms in honey soy sauce', 'A fast dish of shrimp, broccoli, mushrooms and red pepper with garlic and ginger in a thick sauce of soy, honey and stock.', '<ol><li>Heat a skillet over medium heat with 1 tablespoon oil and 1 tablespoon butter. Add the shrimp in a single layer and cook 2 minutes per side. Set aside.</li><li>In the same pan heat another tablespoon each of oil and butter and sauté the onion for 3–4 minutes until soft.</li><li>Add the remaining butter with the broccoli, mushrooms and pepper and cook about 5 minutes until tender. Add the garlic and ginger for a couple of minutes.</li><li>Mix the sauce ingredients, pour into the pan and bring to a light simmer. Cook on medium heat until the sauce thickens.</li><li>Return the shrimp to the pan, heat through and serve over rice, garnished with green onion and sesame seeds.</li></ol><p><em>Serve over steamed white rice.</em></p>', CURRENT_TIMESTAMP),
  ('00b683aa-910e-5469-b362-6326407268f2', '5bb532ea-2b94-5b7f-b315-44d86a51356d', 'ru', 'Куриные голени, томлённые в духовке', 'Голени с луком, чесноком и тимьяном томятся в закрытой форме, а затем подрумяниваются. Мясо получается нежным и отходит от кости.', '<ol><li>Смешайте голени с нарезанным луком, раздавленным чесноком, маслом, лимонным соком, паприкой, солью, перцем и тимьяном. Если есть время, оставьте мариноваться в холодильнике до суток.</li><li>Разогрейте духовку до 180–200 °C.</li><li>Выложите курицу с луком, чесноком и зеленью в форму, накройте фольгой или крышкой и запекайте около 45 минут.</li><li>Снимите крышку и готовьте ещё 45 минут, пока мясо не станет мягким, а кожа золотистой. Для румяной корочки в конце включите гриль.</li></ol><p><em>Подайте с картофельным пюре или гречкой.</em></p>', CURRENT_TIMESTAMP),
  ('5caa8f86-080b-5d0b-8327-f00a2fd79a0e', '5bb532ea-2b94-5b7f-b315-44d86a51356d', 'en', 'Oven-braised chicken drumsticks', 'Drumsticks cook with onion, garlic and thyme in a covered dish, then brown uncovered. The meat turns tender and falls off the bone.', '<ol><li>Toss the drumsticks with sliced onion, smashed garlic, oil, lemon juice, paprika, salt, pepper and thyme. If you have time, marinate in the fridge for up to a day.</li><li>Preheat the oven to 350–400 °F (180–200 °C).</li><li>Put the chicken with the onion, garlic and herbs in a baking dish, cover with foil or a lid and bake for about 45 minutes.</li><li>Uncover and cook another 45 minutes until the meat is tender and the skin golden. Switch on the broiler at the end for a browner crust.</li></ol><p><em>Serve with mashed potatoes or buckwheat.</em></p>', CURRENT_TIMESTAMP),
  ('145e72d8-e268-5db5-ba33-b91c6b82d4bc', '44e49db0-14ef-525e-960d-a982a0d67e85', 'ru', 'Фриттата с кабачками, помидорами и творогом', 'Запечённая яичная масса с творогом, пармезаном и обжаренными кабачками, сверху украшенная кружками помидоров.', '<ol><li>Разогрейте духовку до 190 °C. Смажьте круглую форму диаметром около 23 см маслом.</li><li>Обжарьте тонко нарезанные кабачки на масле 3 минуты, посолите и поперчите. Они должны стать мягче, но остаться ярко-зелёными. Немного остудите.</li><li>Взбейте яйца, добавьте творог, пармезан, муку, соль, перец и половину петрушки. Хорошо перемешайте.</li><li>Добавьте кабачки в яичную массу, вылейте в форму и разровняйте. Посыпьте моцареллой и ещё немного пармезаном.</li><li>На той же сковороде за минуту прогрейте ломтики помидоров с чесноком, солью и перцем. Выложите помидоры кругом на фриттату без сока.</li><li>Посыпьте оставшейся петрушкой и выпекайте 30–35 минут, пока края не зарумянятся, а середина не схватится.</li></ol><p><em>Подайте тёплой или холодной со свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('c4004867-9868-52ee-bf5a-d8d1fff720ab', '44e49db0-14ef-525e-960d-a982a0d67e85', 'en', 'Zucchini and tomato frittata with cottage cheese', 'A baked egg mixture with cottage cheese, Parmesan and sautéed zucchini, topped with a ring of tomato slices.', '<ol><li>Preheat the oven to 375 °F (190 °C). Grease a 9-inch round pie dish with a little oil.</li><li>Sauté the thinly sliced zucchini in oil for 3 minutes, season with salt and pepper. They should soften but stay bright green. Cool a little.</li><li>Whisk the eggs, then add cottage cheese, Parmesan, flour, salt, pepper and half the parsley. Mix well.</li><li>Fold the zucchini into the egg mixture, pour into the dish and level the top. Sprinkle with mozzarella and a bit more Parmesan.</li><li>In the same pan, warm the tomato slices with garlic, salt and pepper for a minute. Arrange the tomatoes in a circle on the frittata, leaving the juice behind.</li><li>Sprinkle with the remaining parsley and bake for 30–35 minutes until the edges are golden and the centre is set.</li></ol><p><em>Serve warm or cold with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('1836b219-8050-5371-873c-9b29f1736142', 'adcc6867-9471-5ab9-a6fc-969b2b670cbc', 'ru', 'Лосось, погашенный в белом вине с луком', 'Филе лосося томится на подушке из лука и петрушки в небольшом количестве вина с водой. Рыба получается сочной и нежной.', '<ol><li>Посолите и поперчите лосось с обеих сторон.</li><li>Выложите на дно сковороды кружки лука, сверху стебли петрушки, чеснок и лавровый лист. Влейте вино и воду.</li><li>Положите рыбу на лук так, чтобы жидкость едва касалась филе. Доведите до кипения и убавьте огонь до слабого.</li><li>Готовьте под крышкой на слабом огне 5–8 минут, пока температура в центре рыбы не достигнет 55–57 °C.</li><li>Подайте с лимонным соком и рубленой зеленью, например укропом или петрушкой.</li></ol><p><em>Подайте с долькой лимона и свежим укропом.</em></p>', CURRENT_TIMESTAMP),
  ('d5da2627-7713-5269-9b5c-50fdd8c3f349', 'adcc6867-9471-5ab9-a6fc-969b2b670cbc', 'en', 'Poached salmon with white wine and onion', 'Salmon fillets gently simmer on a bed of onion and parsley in a little white wine and water. The fish stays juicy and tender.', '<ol><li>Season the salmon with salt and pepper on both sides.</li><li>Lay onion rounds on the bottom of a skillet, top with parsley stems, garlic and bay leaves. Pour in the wine and water.</li><li>Set the fish on the onions so the liquid barely touches it. Bring to a boil, then reduce to a low simmer.</li><li>Cook covered at a low simmer for 5–8 minutes, until the centre of the fish reaches 130–135 °F (55–57 °C).</li><li>Serve with lemon juice and chopped fresh herbs such as dill or parsley.</li></ol><p><em>Serve with a lemon wedge and fresh dill.</em></p>', CURRENT_TIMESTAMP),
  ('ea85d4e5-06b5-5a48-869e-81a6a969f3fb', 'eb128172-9e68-5549-b83f-c41e9f633b87', 'ru', 'Запеканка на завтрак с хлебом, шпинатом и ветчиной', 'Кубики хлеба с шпинатом, ветчиной и сыром заливаются яично-сливочной смесью на ночь, а утром запекаются. Получается пышная и сытная запеканка.', '<ol><li>Нарежьте хлеб кубиками и сложите в большую миску.</li><li>Растопите в сковороде столовую ложку масла, обжарьте мелко нарезанный лук 3–5 минут, посолите.</li><li>Добавьте хорошо отжатый шпинат и прогрейте 2 минуты. Немного остудите.</li><li>Добавьте к хлебу шпинат с луком, ветчину и 100 г тёртого сыра, перемешайте.</li><li>Взбейте яйца со сливками, солью и перцем до однородности.</li><li>Смажьте форму оставшимся маслом, выложите хлебную смесь, залейте яичной массой и придавите, чтобы хлеб пропитался. Посыпьте оставшимся сыром.</li><li>Накройте плёнкой, придавите грузом и уберите в холодильник на ночь.</li><li>Утром разогрейте духовку до 180 °C, 20 минут выдержите форму при комнатной температуре, затем запекайте 40–50 минут до золотистой пышной корочки и плотной середины.</li></ol><p><em>Подайте горячей со свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('c1f22187-7e10-5300-913f-a38e6c240452', 'eb128172-9e68-5549-b83f-c41e9f633b87', 'en', 'Overnight breakfast casserole with spinach, ham and cheese', 'Bread cubes with spinach, ham and cheese soak in an egg custard overnight and bake in the morning. It turns out fluffy and hearty.', '<ol><li>Cut the bread into cubes and put them in a large bowl.</li><li>Melt a tablespoon of butter in a skillet and cook the minced onion for 3–5 minutes with some salt.</li><li>Add the well-squeezed spinach and warm for 2 minutes. Let cool slightly.</li><li>Add the spinach and onion, the ham and about two-thirds of the grated cheese to the bread and mix.</li><li>Whisk the eggs with the cream, salt and pepper until smooth.</li><li>Butter a baking dish with the remaining butter, add the bread mixture, pour the custard over it and press down so the bread soaks. Top with the remaining cheese.</li><li>Cover with plastic wrap, weigh it down and refrigerate overnight.</li><li>In the morning preheat the oven to 350 °F (180 °C), keep the dish at room temperature for 20 minutes, then bake for 40–50 minutes until golden, puffed and set in the centre.</li></ol><p><em>Serve hot with fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('05c38255-5fc6-584e-9e7b-508025ce5c40', '0c9f7b34-342e-547f-bbe8-202778a1e3bd', 'ru', 'Сэндвич с круассаном, лососем и авокадо', 'Тёплый круассан с яичницей, расплавленным сыром, слабосолёным лососем и авокадо. Сытный завтрак за 25 минут.', '<ol><li>Разрежьте круассаны пополам и подсушите в духовке под грилем до золотистого цвета, около 30 секунд.</li><li>Растопите масло на сковороде, разбейте яйца, посолите и поперчите. Жарьте на слабом огне до нужной готовности.</li><li>В конце жарки положите сыр на яйца, чтобы он начал плавиться.</li><li>На нижние половинки круассанов выложите лосось, на верхние авокадо и сбрызните его соком лайма.</li><li>Положите яйца с сыром на лосось, посыпьте шнитт-луком и накройте верхними половинками.</li></ol><p><em>Подавайте сразу, пока яйцо и сыр тёплые.</em></p>', CURRENT_TIMESTAMP),
  ('b3351764-8f3a-5730-9355-b080038d4340', '0c9f7b34-342e-547f-bbe8-202778a1e3bd', 'en', 'Smoked salmon, avocado and egg croissant sandwich', 'A warm croissant filled with fried eggs, melted cheese, smoked salmon and avocado. A filling breakfast ready in 25 minutes.', '<ol><li>Cut the croissants in half and toast them under the oven broiler until golden, about 30 seconds.</li><li>Melt the butter in a skillet, crack in the eggs, season with salt and pepper and cook over low heat to your liking.</li><li>Near the end, lay the cheese on the eggs so it starts to melt.</li><li>Put the salmon on the bottom halves of the croissants and the sliced avocado on the top halves, then squeeze lime juice over the avocado.</li><li>Place the eggs with cheese on the salmon, sprinkle with chives and close with the top halves.</li></ol><p><em>Serve right away while the egg and cheese are warm.</em></p>', CURRENT_TIMESTAMP),
  ('92827714-9259-5b8f-9e42-55e0374705ad', '40574a12-404d-568d-8099-9aff9ec1a92a', 'ru', 'Буррито на завтрак с говядиной, картофелем и яйцом', 'Лепёшки с жареным картофелем, мягкой яичной скрэмбл, ломтиками говядины и сыром. Их удобно готовить заранее и замораживать.', '<ol><li>Нарежьте картофель кубиками около 1 см. Разогрейте на сковороде 1 ст. л. масла и жарьте картофель на среднем огне 5–7 минут.</li><li>Добавьте мелко нарезанный лук, посолите, поперчите и готовьте под крышкой на небольшом огне ещё 5–7 минут, пока картофель не станет мягким. Добавьте белую часть зелёного лука и отставьте. Сковороду протрите.</li><li>Взбейте яйца с щепоткой соли и перца. Разогрейте в сковороде оставшееся масло и вылейте яйца.</li><li>Готовьте скрэмбл на слабом огне, пока яйца почти схватятся, но останутся чуть влажными: в буррито они дойдут.</li><li>В нижнюю часть каждой лепёшки положите картофель, яйца, говядину, сыр и зелень. Заверните боковые края внутрь и плотно сверните рулетом.</li><li>Подавайте сразу или заверните в пергамент и фольгу и уберите в холодильник на 3–5 дней, либо в морозилку. Перед подачей разогрейте в микроволновке или обжарьте на сковороде под крышкой до золотистой корочки.</li></ol><p><em>Подавайте с сальсой, сметаной или гуакамоле.</em></p>', CURRENT_TIMESTAMP),
  ('43952549-9b85-5ebc-8a81-43dd31db6c88', '40574a12-404d-568d-8099-9aff9ec1a92a', 'en', 'Steak and potato breakfast burritos', 'Tortillas filled with fried potatoes, soft scrambled eggs, sliced beef and cheese. They are easy to make ahead and freeze.', '<ol><li>Cut the potatoes into 1 cm cubes. Heat 1 tbsp of oil in a skillet and fry the potatoes over medium heat for 5–7 minutes.</li><li>Add the minced onion, season and cook covered over medium-low heat for another 5–7 minutes until the potatoes are tender. Stir in the white part of the green onion and set aside. Wipe the skillet clean.</li><li>Whisk the eggs with a little salt and pepper. Heat the remaining oil in the skillet and pour in the eggs.</li><li>Scramble over low heat until the eggs are nearly set but still slightly loose; they will finish cooking in the burritos.</li><li>On the lower part of each tortilla, layer potatoes, eggs, beef, cheese and herbs. Fold in the sides and roll up tightly.</li><li>Serve right away, or wrap in parchment and foil and refrigerate for 3–5 days or freeze. To serve, reheat in the microwave or brown in a covered skillet.</li></ol><p><em>Serve with salsa, sour cream or guacamole.</em></p>', CURRENT_TIMESTAMP),
  ('c175a9b7-0622-5ff3-a003-cb4aec39b187', 'fed2d997-eee9-5c61-80f6-101d4a8ee82f', 'ru', 'Яичные маффины с картофелем и беконом', 'Порционные запеканки в формочках для маффинов: тёртый картофель, хрустящий бекон, сыр и яйца. Хорошо подходят для заготовки на несколько дней.', '<ol><li>Разогрейте духовку до 200 °C. Выложите 12 формочек для маффинов бумажными вкладышами.</li><li>Обжарьте бекон до хруста на сковороде или в духовке, остудите и покрошите.</li><li>Очистите картофель и натрите на крупной тёрке. Смешайте с беконом, сыром, зелёным луком, щепоткой соли и перца.</li><li>Взбейте яйца с молоком, посолите и поперчите.</li><li>Разложите картофельную смесь по формочкам и залейте яичной массой. Можно сыпать немного сыра сверху.</li><li>Выпекайте около 20 минут, пока яйца полностью не схватятся, а верх не зарумянится.</li></ol><p><em>Порция — два маффина. Подавайте тёплыми, со свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('0210d935-5f5f-5191-b22f-f1bbbd75016b', 'fed2d997-eee9-5c61-80f6-101d4a8ee82f', 'en', 'Bacon and hash brown egg muffins', 'Individual egg bakes in a muffin tin made with grated potato, crispy bacon, cheese and eggs. Great for making ahead.', '<ol><li>Preheat the oven to 200°C (400°F). Line a 12-cup muffin tin with paper liners.</li><li>Cook the bacon until crisp on the stove or in the oven, cool and crumble it.</li><li>Peel the potatoes and grate them on the large holes of a box grater. Mix with the bacon, cheese, green onion, and a pinch of salt and pepper.</li><li>Whisk the eggs with the milk, then season with salt and pepper.</li><li>Divide the potato mixture among the cups and pour the egg mixture over it. Top with a little extra cheese if you like.</li><li>Bake for about 20 minutes, until the eggs are set and the tops are golden.</li></ol><p><em>One serving is two muffins. Serve warm with fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('88cbd596-62c7-5aab-a5be-f669ef15301b', '45dced1f-1d68-5625-a381-6679ca200556', 'ru', 'Сочная куриная грудка на гриле в рассоле', 'Куриная грудка на косточке, которую выдерживают час в солёном рассоле с чесноком и лавром, а потом жарят на гриле. Получается сочное мясо, подходящее к любому гарниру.', '<ol><li>Смешайте воду с солью, сахаром, лавровым листом, перцем горошком и чесноком (зубчики надавите или разрежьте пополам). Размешайте до растворения соли и сахара.</li><li>Погрузите грудки в рассол полностью, накройте и уберите в холодильник на час.</li><li>Слейте рассол и обсушите курицу бумажными полотенцами. Это можно сделать накануне и хранить мясо в холодильнике.</li><li>Разогрейте гриль на сильном огне не менее 15 минут, почистите решётку и смажьте её маслом. Затем убавьте огонь до средне-сильного.</li><li>Положите грудки кожей вниз и жарьте 10–15 минут до золотистой корочки, затем переверните.</li><li>Жарьте ещё 15–25 минут, пока температура в середине не достигнет 71 °C. Дайте мясу отдохнуть 10–15 минут и нарежьте.</li></ol><p><em>Дайте мясу отдохнуть 10–15 минут перед нарезкой. Хорошо с овощами и рисом.</em></p>', CURRENT_TIMESTAMP),
  ('241c452b-5f18-5b14-9acc-51ac2acb6a1b', '45dced1f-1d68-5625-a381-6679ca200556', 'en', 'Juicy brined grilled chicken breast', 'Bone-in chicken breasts brined for an hour with garlic and bay, then grilled. The brine keeps the meat juicy and seasoned through.', '<ol><li>Mix the water with the salt, sugar, bay leaves, peppercorns and garlic (crush or halve the cloves). Stir until the salt and sugar dissolve.</li><li>Submerge the chicken completely in the brine, cover and refrigerate for 1 hour.</li><li>Discard the brine and pat the chicken dry with paper towels. You can do this a day ahead and keep the chicken refrigerated.</li><li>Heat the grill on high for at least 15 minutes, clean the grates and oil them. Then lower the heat to medium-high.</li><li>Place the chicken skin side down and grill for 10–15 minutes until golden, then flip.</li><li>Grill for another 15–25 minutes, until the center reaches 71°C (160°F). Rest for 10–15 minutes, then slice.</li></ol><p><em>Let the chicken rest for 10–15 minutes before slicing. Good with vegetables and rice.</em></p>', CURRENT_TIMESTAMP),
  ('f8679338-d7d6-5775-95d4-dd3fc302c848', '3ed9d69d-fa1e-59a4-9d19-850e4ca8b56b', 'ru', 'Креветки на гриле с лимоном и чесноком', 'Крупные креветки в простом маринаде из лимона, чеснока и петрушки, обжаренные на шпажках за несколько минут.', '<ol><li>Очистите креветки, при необходимости удалите кишечную жилку: сделайте неглубокий надрез вдоль спинки и выньте её.</li><li>Смешайте креветки с чесноком, лимонным соком, цедрой, солью, сахаром, перцем, петрушкой и 1,5 ст. л. масла. Можно сразу жарить, а можно промариновать заранее.</li><li>Нанижите креветки на шпажки (6–8 штук) и смажьте остальным маслом. Бамбуковые шпажки предварительно замочите в воде на 10 минут.</li><li>Разогрейте гриль на сильном огне около 15 минут и смажьте решётку маслом.</li><li>Жарьте креветки 4–5 минут до следов гриля, переверните и жарьте ещё 1–2 минуты. Не передерживайте: креветки дойдут и после снятия.</li><li>Сразу подавайте, выжав сверху лимонный сок.</li></ol><p><em>Добавьте свежий лимонный сок перед подачей. Подойдут рис или овощной салат.</em></p>', CURRENT_TIMESTAMP),
  ('29d45972-676c-523a-bd30-dd50b06c42bf', '3ed9d69d-fa1e-59a4-9d19-850e4ca8b56b', 'en', 'Lemon garlic grilled shrimp skewers', 'Large shrimp in a simple marinade of lemon, garlic and parsley, grilled on skewers in just a few minutes.', '<ol><li>Peel the shrimp and devein them if needed: make a shallow cut along the back and lift out the vein.</li><li>Combine the shrimp with the garlic, lemon juice, zest, salt, sugar, pepper, parsley and 1.5 tbsp of oil. Grill right away or marinate ahead.</li><li>Thread the shrimp onto 6–8 skewers and brush with the remaining oil. Soak bamboo skewers in water for 10 minutes first.</li><li>Preheat the grill on high for about 15 minutes and oil the grates.</li><li>Grill the shrimp 4–5 minutes until charred, flip and cook another 1–2 minutes. Don''t overcook; they keep cooking after leaving the heat.</li><li>Serve immediately with extra lemon juice squeezed on top.</li></ol><p><em>Squeeze extra lemon juice over the shrimp before serving. Good with rice or a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('d934e79d-d58b-52b1-9403-b33d0ff982ea', 'bdc54b2d-8a4b-54bf-8721-a6de2a7a7d7f', 'ru', 'Салат с пастой в стиле антипасти', 'Холодный салат из пасты, брокколи, обжаренных шампиньонов, салями, помидоров и проволоне с лёгкой винной заправкой.', '<ol><li>Отварите пасту по инструкции на упаковке и остудите. Отлейте 60 мл воды после варки в сковороду.</li><li>Доведите воду в сковороде до кипения, добавьте соцветия брокколи, накройте и готовьте на слабом огне около 5 минут, чтобы они остались хрустящими и зелёными. Переложите в миску остывать.</li><li>Грибы разрежьте на половинки или четвертинки. Смешайте 1,5 ст. л. оливкового масла, ½ ст. л. уксуса и ½ ст. л. рассола от перцев. Влейте на сковороду, добавьте грибы и 2 зубчика чеснока, посолите и поперчите. Жарьте до золотистого цвета, пока жидкость не испарится.</li><li>Для заправки смешайте 2 ст. л. масла, ½ ст. л. уксуса и ½ ст. л. рассола, добавьте 2 раздавленных зубчика чеснока и оставьте на 15 минут, затем чеснок выньте.</li><li>Соедините пасту, брокколи, грибы, салями, помидоры, сыр, перец и зелень с заправкой. Посолите и поперчите по вкусу. Можно подавать сразу или дать настояться.</li></ol><p><em>Вкуснее, если салат постоит около часа. Подавайте охлаждённым.</em></p>', CURRENT_TIMESTAMP),
  ('4fe821e0-ee14-5916-9c5f-4e86e0723c11', 'bdc54b2d-8a4b-54bf-8721-a6de2a7a7d7f', 'en', 'Antipasto pasta salad with broccoli and salami', 'A cold pasta salad with broccoli, browned mushrooms, salami, tomatoes and provolone in a light vinaigrette.', '<ol><li>Cook the pasta according to the package, then cool it. Keep 60 ml of the pasta water in a skillet.</li><li>Bring the water in the skillet to a boil, add the broccoli florets, cover and cook over medium-low heat for about 5 minutes, until crisp-tender and bright green. Move to a bowl to cool.</li><li>Halve or quarter the mushrooms. Whisk 1.5 tbsp of olive oil, ½ tbsp of vinegar and ½ tbsp of pepper brine. Pour into the skillet, add the mushrooms and 2 minced garlic cloves, season, and cook until golden and the liquid has evaporated.</li><li>For the vinaigrette, whisk 2 tbsp of oil, ½ tbsp of vinegar and ½ tbsp of brine, add 2 smashed garlic cloves and let stand 15 minutes, then discard the garlic.</li><li>Toss the pasta, broccoli, mushrooms, salami, tomatoes, cheese, peppers and herbs with the vinaigrette. Season to taste. Serve right away or let it stand.</li></ol><p><em>Tastes even better after standing for about an hour. Serve chilled.</em></p>', CURRENT_TIMESTAMP),
  ('86a801e1-56dc-5e62-bfaf-fe30b3cb3c13', '25c08264-a94b-5d28-bc5e-c76d7aeaf7ad', 'ru', 'Кесадильи с курицей и сыром', 'Лепёшки с начинкой из варёной курицы, пармезана, вяленых томатов и сладкого перца на майонезе с йогуртом, с моцареллой, обжаренные на сковороде.', '<ol><li>Нарежьте готовую курицу (запечённую, варёную или с рынка гриль) на мелкие кусочки.</li><li>Смешайте курицу с пармезаном, вялеными томатами, болгарским перцем, чесноком и петрушкой.</li><li>Взбейте майонез с йогуртом, добавьте к курице, посолите и поперчите.</li><li>На лепёшку выложите около ½ стакана начинки, посыпьте моцареллой и накройте второй лепёшкой. Так соберите все кесадильи.</li><li>Растопите немного масла на сковороде и жарьте кесадильи под крышкой на средне-слабом огне до золотистого цвета с обеих сторон, по одной.</li></ol><p><em>Подавайте с сальсой или сметаной. Порция — одна кесадилья из двух лепёшек.</em></p>', CURRENT_TIMESTAMP),
  ('ba09fdbb-6b0b-503a-a5c2-26ed2c8d4e3b', '25c08264-a94b-5d28-bc5e-c76d7aeaf7ad', 'en', 'Chicken quesadillas with parmesan and mozzarella', 'Tortillas filled with cooked chicken, parmesan, sun-dried tomatoes and bell pepper in a mayo-yogurt dressing, with mozzarella, pan-fried until golden.', '<ol><li>Chop the cooked chicken (roasted, boiled or rotisserie) into small pieces.</li><li>Combine the chicken with the parmesan, sun-dried tomatoes, bell pepper, garlic and parsley.</li><li>Whisk the mayonnaise with the yogurt, stir into the chicken, then season with salt and pepper.</li><li>Spread about ½ cup of filling on a tortilla, sprinkle with mozzarella and cover with a second tortilla. Assemble all the quesadillas this way.</li><li>Melt a little butter in a skillet and cook the quesadillas one at a time, covered, over medium-low heat until golden on both sides.</li></ol><p><em>Serve with salsa or sour cream. One serving is one quesadilla made of two tortillas.</em></p>', CURRENT_TIMESTAMP),
  ('504ae3e4-e1bf-5f32-929d-119695cdf00d', '5c7947d9-f3f2-5142-ba65-fb9e28d47123', 'ru', 'Сырный суп с индейкой и картофелем', 'Густой суп с фаршем из индейки, картофелем и овощами, в который добавлено пюре из цветной капусты и тёртый чеддер. По вкусу напоминает чизбургер.', '<ol><li>Обжарьте фарш из индейки в кастрюле, разбивая на мелкие кусочки, 4–5 минут. Переложите в миску, лишний жир слейте.</li><li>В той же кастрюле растопите масло, пассеруйте лук, морковь, сельдерей и чеснок около 5 минут. Всыпьте муку, соль и перец и прогрейте минуту.</li><li>Верните фарш, влейте бульон, добавьте кубики картофеля и целый кусок цветной капусты. Доведите до кипения и варите под крышкой на слабом огне 25–30 минут (в мультиварке под давлением — 10 минут), пока овощи не станут мягкими.</li><li>Взбейте цветную капусту с 1 стаканом бульона из кастрюли до гладкости и верните пюре в суп.</li><li>Всыпьте чеддер и помешивайте, пока он не растает. Подавайте с зелёным луком.</li></ol><p><em>Посыпьте зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('ad893188-7bf2-579d-982e-d0dec63e5bc9', '5c7947d9-f3f2-5142-ba65-fb9e28d47123', 'en', 'Cheeseburger soup with turkey and cauliflower', 'A thick soup of ground turkey, potatoes and vegetables enriched with pureed cauliflower and shredded cheddar. It tastes like a cheeseburger in a bowl.', '<ol><li>Brown the ground turkey in a large pot, breaking it into small pieces, for 4–5 minutes. Transfer to a bowl and drain off excess fat.</li><li>In the same pot melt the butter and cook the onion, carrots, celery and garlic for about 5 minutes. Stir in the flour, salt and pepper and cook for 1 minute.</li><li>Return the turkey, add the broth, diced potatoes and the whole cauliflower wedge. Bring to a boil and simmer covered for 25–30 minutes (or pressure-cook for 10 minutes) until the vegetables are tender.</li><li>Blend the cauliflower with 1 cup of the cooking liquid until smooth and stir the purée back into the soup.</li><li>Add the cheddar and stir until melted. Serve topped with scallions.</li></ol><p><em>Top with chopped scallions.</em></p>', CURRENT_TIMESTAMP),
  ('2e7cb7d1-42d6-5061-a0d0-4af732024128', '539c53a9-e564-5afd-8cfc-7e701f491e67', 'ru', 'Греческий салат с пастой, фетой и оливками', 'Холодный салат из пасты со свежими овощами, оливками и фетой под лимонно-уксусной заправкой с орегано.', '<ol><li>Отварите пасту в подсоленной воде до состояния аль денте (на минуту дольше, чем указано на упаковке), промойте холодной водой и откиньте.</li><li>Для заправки смешайте красный винный уксус, лимонный сок, оливковое масло, чесночный порошок, орегано и соль.</li><li>Добавьте в заправку оливки с 2 ст. л. рассола и красный лук, перемешайте.</li><li>Добавьте пасту, огурец, помидоры и перец, хорошо перемешайте. Фету положите непосредственно перед подачей.</li></ol><p><em>Фету добавляйте перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('f53d8ce2-e402-50a6-9fc2-5f42559248a2', '539c53a9-e564-5afd-8cfc-7e701f491e67', 'en', 'Greek pasta salad with feta and olives', 'A cold pasta salad with fresh vegetables, olives and feta in a lemony red-wine vinaigrette with oregano.', '<ol><li>Cook the pasta in salted boiling water until al dente (one minute longer than the package says), rinse with cold water and drain.</li><li>Whisk the red wine vinegar, lemon juice, olive oil, garlic powder, oregano and salt into a dressing.</li><li>Add the olives with 2 tablespoons of their brine and the red onion to the dressing and stir.</li><li>Add the pasta, cucumber, tomatoes and bell pepper and toss well. Stir in the feta just before serving.</li></ol><p><em>Add the feta just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('29df8967-b746-571a-8ea0-d35217f14991', 'fa4e5637-a8eb-5df5-9c6e-8ec67cf8962e', 'ru', 'Салат из брокколи с беконом и клюквой', 'Хрустящая сырая брокколи с хрустящим беконом, красным луком, вялой клюквой и семечками в лёгкой заправке из майонеза и йогурта.', '<ol><li>Обжарьте бекон на сковороде на среднем огне до хруста, примерно по 4 минуты с каждой стороны (или запеките при 200 °C 15–20 минут).</li><li>Переложите бекон на бумажное полотенце, остудите и покрошите.</li><li>В большой миске соедините соцветия брокколи, красный лук, клюкву, семечки и козий сыр.</li><li>Смешайте майонез с йогуртом, заправьте салат, добавьте бекон и перемешайте.</li></ol><p><em>Хорошо подходит к мясу на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('7fb5ad36-cfba-5d5b-b325-b4613d5361f2', 'fa4e5637-a8eb-5df5-9c6e-8ec67cf8962e', 'en', 'Broccoli salad with bacon and cranberries', 'Crunchy raw broccoli with crispy bacon, red onion, dried cranberries and seeds in a light mayo-and-yogurt dressing.', '<ol><li>Cook the bacon in a skillet over medium heat until crisp, about 4 minutes per side (or bake at 400 °F / 200 °C for 15–20 minutes).</li><li>Drain the bacon on paper towels, let it cool and crumble it.</li><li>In a large bowl combine the broccoli florets, red onion, cranberries, seeds and goat cheese.</li><li>Stir the mayonnaise and yogurt together, then toss with the salad and the bacon.</li></ol><p><em>Great alongside grilled meat.</em></p>', CURRENT_TIMESTAMP),
  ('5408372f-2864-55bd-b5e2-e0405a6fbf98', '8f2c5ae5-c268-547c-a75e-cd08c5391fa7', 'ru', 'Боул с курицей в йогурте, киноа и дзадзики', 'Курица, замаринованная в йогурте с куркумой и чесноком, подаётся на киноа с огурцами, помидорами, оливками, фетой и дзадзики.', '<ol><li>Нарежьте бёдра кусочками около 2,5 см. Смешайте йогурт, масло, уксус, чеснок, орегано, куркуму, соль и хлопья перца, добавьте курицу и маринуйте в холодильнике от 1 до 8 часов.</li><li>Отварите киноа по инструкции на упаковке и остудите.</li><li>Для дзадзики смешайте йогурт с натёртым огурцом, чесноком, лимонным соком и укропом, посолите.</li><li>Нанижите курицу на шпажки, посолите и поперчите. Жарьте на гриль-сковороде на средне-слабом огне, периодически переворачивая, около 15 минут до золотистой корочки.</li><li>Взбейте масло и уксус с солью и перцем, добавьте нарезанные огурцы, помидоры и лук.</li><li>В миски выложите киноа, овощной салат, ложку дзадзики, фету, оливки и шпажку с курицей.</li></ol><p><em>Дзадзики подавайте холодным.</em></p>', CURRENT_TIMESTAMP),
  ('de72df57-53e3-5e35-b28a-61986a6cea88', '8f2c5ae5-c268-547c-a75e-cd08c5391fa7', 'en', 'Chicken tzatziki quinoa bowls', 'Yogurt-and-turmeric marinated chicken skewers served over quinoa with cucumber, tomatoes, olives, feta and tzatziki.', '<ol><li>Cut the thighs into 1-inch (2.5 cm) pieces. Mix the yogurt, oil, vinegar, garlic, oregano, turmeric, salt and pepper flakes, add the chicken and marinate in the fridge for 1 to 8 hours.</li><li>Cook the quinoa according to the package directions and let it cool.</li><li>For the tzatziki, mix the yogurt with grated cucumber, garlic, lemon juice and dill, then season with salt.</li><li>Thread the chicken onto skewers, season with salt and pepper and cook on a grill pan over medium-low heat, turning occasionally, for about 15 minutes until golden and cooked through.</li><li>Whisk the oil and vinegar with salt and pepper, then toss in the sliced cucumbers, tomatoes and red onion.</li><li>Divide the quinoa among bowls and top with the vegetable salad, a spoonful of tzatziki, feta, olives and a chicken skewer.</li></ol><p><em>Serve the tzatziki cold.</em></p>', CURRENT_TIMESTAMP),
  ('99ea967f-2754-5494-95cf-d7fbafb017ea', '7cc704ac-1d4f-5462-8d2f-00f60f43558d', 'ru', 'Куриные бёдра с бальзамиком и запечёнными овощами', 'Куриные бёдра и овощи в маринаде из бальзамического уксуса, розмарина и шалфея запекаются на противне. Готовая еда на одном противне.', '<ol><li>Разогрейте духовку до 220 °C. Смажьте два больших противня маслом.</li><li>Посолите и поперчите бёдра.</li><li>Руками перемешайте в миске все ингредиенты и разложите в один слой на противнях. Овощи не должны касаться курицы, иначе они будут тушиться.</li><li>Запекайте 20–25 минут, поменяв противни местами на середине, пока курица не прожарится, а овощи не станут мягкими и румяными.</li></ol><p><em>Выкладывайте овощи отдельно от курицы, чтобы они запеклись, а не тушились.</em></p>', CURRENT_TIMESTAMP),
  ('f270ed6b-e27e-56e9-9e70-e8168140e039', '7cc704ac-1d4f-5462-8d2f-00f60f43558d', 'en', 'Balsamic chicken thighs with roasted vegetables', 'Chicken thighs and vegetables coated in balsamic vinegar, rosemary and sage, then roasted on sheet pans. A full meal from the oven.', '<ol><li>Preheat the oven to 425 °F (220 °C). Lightly oil two large baking sheets.</li><li>Season the chicken thighs with salt and pepper.</li><li>Mix everything together by hand in a large bowl, then spread it in a single layer on the baking sheets. Vegetables should not touch the chicken or they will steam.</li><li>Bake for 20–25 minutes, swapping the pans halfway, until the chicken is cooked through and the vegetables are tender and roasted.</li></ol><p><em>Keep the vegetables from touching the chicken so they roast instead of steam.</em></p>', CURRENT_TIMESTAMP),
  ('4e585ee8-4460-5c0c-baa8-488e64c0686f', '469de70c-d141-5566-b61e-34c21b7ecc80', 'ru', 'Запечённая паста ригатони с куриной колбаской, шпинатом и рикоттой', 'Ригатони слоями с томатным соусом, куриным фаршем из колбасок, шпинатом, рикоттой и моцареллой, запечённые до плавленой сырной корочки.', '<ol><li>Разогрейте духовку до 190 °C, смажьте форму 23×33 см маслом. Поставьте воду для пасты.</li><li>Смешайте рикотту, 6 ст. л. пекорино и половину моцареллы.</li><li>Обжарьте колбасный фарш (без оболочки) на глубокой сковороде, разбивая на кусочки, до готовности. Отложите.</li><li>В ту же сковороду добавьте масло и чеснок на минуту, затем шпинат, соль и перец ещё на минуту. Верните колбасу, влейте соус и прогрейте 2–3 минуты.</li><li>Отварите пасту на 4 минуты меньше, чем указано на упаковке, и слейте воду.</li><li>Выложите в форму половину пасты, затем половину соуса с колбасой, ложками рикотную смесь, остальную пасту и соус. Посыпьте оставшимися моцареллой и пекорино.</li><li>Накройте фольгой и запекайте 20 минут, затем снимите фольгу и допеките 6–7 минут, пока сыр не расплавится и края не зарумянятся.</li></ol><p><em>Подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('7fe44732-9ed1-5c9d-9b02-b23191c0d7f5', '469de70c-d141-5566-b61e-34c21b7ecc80', 'en', 'Baked rigatoni with chicken sausage, spinach and ricotta', 'Layers of rigatoni with tomato sauce, crumbled chicken sausage, spinach, ricotta and mozzarella baked until bubbly and golden.', '<ol><li>Preheat the oven to 375 °F (190 °C) and grease a 9×13-inch baking dish. Put a large pot of salted water on to boil.</li><li>Combine the ricotta, 6 tablespoons of the Pecorino and half of the mozzarella.</li><li>Brown the sausage meat (removed from the casing) in a deep skillet, breaking it up, until cooked through. Set aside.</li><li>Add the oil and garlic to the same skillet for a minute, then the spinach with salt and pepper for another minute. Return the sausage, add the sauce and warm through for 2–3 minutes.</li><li>Cook the pasta 4 minutes short of the package time and drain.</li><li>Put half the pasta in the dish, then half the sausage sauce, spoon over the ricotta mixture, then the remaining pasta and sauce. Top with the rest of the mozzarella and Pecorino.</li><li>Cover with foil and bake for 20 minutes, then uncover and bake another 6–7 minutes until the cheese is melted and the edges lightly browned.</li></ol><p><em>Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('9486bb03-edee-5b57-ac11-89acaf0c0703', 'cdceea0c-00b6-5901-be9b-4c109d25395e', 'ru', 'Курица с кабачками в соево-имбирном соусе', 'Быстрое жаркое на сковороде: тонкие ломтики куриной грудки и кабачок в густом соевом соусе с имбирём и чесноком.', '<ol><li>В большой миске смешайте соевый соус, бульон, крахмал, мирин, сахар и кунжутное масло до полного растворения крахмала.</li><li>Курицу нарежьте очень тонкими ломтиками, кабачок полукружками толщиной около 6 мм.</li><li>Разогрейте на большой сковороде 1 ч. л. масла на среднем и сильном огне. Обжарьте половину курицы по 2–3 минуты с каждой стороны до готовности и переложите на тарелку. Так же приготовьте вторую половину на ещё 1 ч. л. масла.</li><li>Влейте в сковороду оставшееся масло, добавьте чеснок и имбирь и прогрейте 30–45 секунд, пока не появится аромат, не давая зажариться.</li><li>Перемешайте соус и влейте в сковороду, помешивая. Варите минуту, затем добавьте кабачок и готовьте ещё 2 минуты, пока соус не загустеет, а кабачок не станет мягким, но хрустящим.</li><li>Снимите с огня, верните курицу в сковороду и перемешайте. При желании посыпьте кунжутом и зелёным луком.</li></ol><p><em>Подавайте с отварным рисом, посыпав кунжутом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('9a290b7e-98e7-5f78-ab99-986063078fe4', 'cdceea0c-00b6-5901-be9b-4c109d25395e', 'en', 'Chicken and zucchini stir fry', 'A quick skillet stir fry of thinly sliced chicken breast and zucchini in a thick soy, ginger and garlic sauce.', '<ol><li>In a large bowl, whisk the soy sauce, broth, cornstarch, mirin, sugar and sesame oil until fully dissolved.</li><li>Slice the chicken very thinly and the zucchini into half-moons about 6 mm thick.</li><li>Heat 1 tsp of oil in a large skillet over medium-high heat. Cook half of the chicken for 2–3 minutes per side until done and move to a plate. Repeat with the second half and another 1 tsp of oil.</li><li>Add the remaining oil, garlic and ginger and cook for 30–45 seconds until fragrant but not browned.</li><li>Stir the sauce again and pour it in, whisking. Cook for 1 minute, add the zucchini and cook 2 minutes more, until the sauce thickens and the zucchini is tender-crisp.</li><li>Remove from the heat, return the chicken and stir to coat. Garnish with sesame seeds and scallions if you like.</li></ol><p><em>Serve over steamed rice, topped with sesame seeds and scallions.</em></p>', CURRENT_TIMESTAMP),
  ('50f66229-d96e-5d43-b94f-7fc926dd921e', '9c98edb1-9b67-56a8-a78a-9fe1ca672899', 'ru', 'Курица по-техасски со сладким перцем, кукурузой и кабачком', 'Куриные бёдра полосками, обжаренные с пряностями в стиле тексмекс, с перцем, кукурузой и кабачком. Всё готовится на одной сковороде.', '<ol><li>Смешайте специи: чили, зиру, копчёную паприку, орегано, хлопья чили, кайенский перец, чесночный и луковый порошок, чёрный перец. Это и есть мексиканская приправа.</li><li>Нарежьте курицу полосками толщиной около 2,5 см, смешайте с половиной масла, половиной приправы и ½ ч. л. соли.</li><li>Разогрейте большую сковороду на сильном огне, добавьте остальное масло и курицу. Жарьте 4 минуты, постоянно помешивая, до золотистого цвета и готовности. Переложите на тарелку и накройте фольгой.</li><li>В ту же сковороду положите перец соломкой, кукурузу и чеснок, посыпьте оставшейся приправой. Готовьте на среднем и сильном огне, часто помешивая, 5–8 минут, пока перец слегка не размягчится.</li><li>Добавьте тонко нарезанный кабачок и оставшуюся соль и готовьте ещё около 4 минут до слегка мягкого состояния.</li><li>Верните курицу в сковороду, влейте сок лайма и соскребите со дна подгоревшие кусочки, перемешав с соком. Снимите с огня и посыпьте кинзой, по желанию сыром.</li></ol><p><em>Хорошо с рисом или лепёшками. Сверху можно посыпать сыром котиха.</em></p>', CURRENT_TIMESTAMP),
  ('e706ad33-4f23-5866-a7d2-4559cc6e9c9d', '9c98edb1-9b67-56a8-a78a-9fe1ca672899', 'en', 'Southwest chicken skillet with corn and zucchini', 'Chicken thigh strips seared with Tex-Mex spices, then cooked with bell pepper, corn and zucchini. Everything comes together in one skillet.', '<ol><li>Mix the spices: chili powder, cumin, smoked paprika, oregano, chili flakes, cayenne, garlic and onion powder, and black pepper. This is the Mexican seasoning.</li><li>Cut the chicken into strips about 2.5 cm wide and toss with half of the oil, half of the spice mix and ½ tsp of salt.</li><li>Heat a large skillet over high heat, add the remaining oil and the chicken. Cook for 4 minutes, stirring constantly, until browned and cooked through. Transfer to a plate and cover with foil.</li><li>Add the sliced pepper, corn and garlic to the same skillet and sprinkle with the rest of the seasoning. Cook over medium-high heat, stirring often, for 5–8 minutes until the pepper softens slightly.</li><li>Add the thinly sliced zucchini and remaining salt and cook for about 4 minutes, until slightly softened.</li><li>Return the chicken to the skillet, add the lime juice and scrape up the browned bits, stirring with the juices. Remove from the heat and sprinkle with cilantro and, if you like, cheese.</li></ol><p><em>Good with rice or warm tortillas. Top with crumbled cotija if you like.</em></p>', CURRENT_TIMESTAMP),
  ('31090b9e-05de-5111-a885-48f66fa4e925', '23f99077-2062-5081-be00-1037c239aff2', 'ru', 'Зелёный суп-пюре с кейлом и фенхелем', 'Овощной суп-пюре с луком, фенхелем и капустой кейл, заправленный лимоном и свежей зеленью. Сверху подаётся хрустящая гремолата из обжаренных семян конопли с чесноком.', '<ol><li>Разогрейте в большой кастрюле 1 ст. л. масла. Добавьте лук, нарезанный фенхель и ¼ ч. л. соли и жарьте 3–5 минут, пока лук не начнёт золотиться.</li><li>Добавьте нарезанный кейл и готовьте 3–4 минуты, пока он не завянет. Если на дне пригорает, подливайте по 1 ст. л. воды.</li><li>Влейте овощной бульон, доведите до кипения, убавьте огонь, накройте крышкой и варите 10 минут. Снимите с огня.</li><li>Сразу добавьте две трети чеснока и оставьте суп остывать без крышки около 10 минут.</li><li>Тем временем разогрейте на сковороде оставшееся масло, всыпьте семена конопли, оставшуюся соль и чеснок. Разровняйте слоем и обжаривайте около 3 минут, помешивая, до золотистого цвета и аромата.</li><li>Переложите смесь в миску, остудите и добавьте цедру лимона и нарезанную зелень фенхеля. Это гремолата.</li><li>В суп добавьте кинзу, петрушку и лимонный сок и взбейте блендером до однородности.</li><li>Разлейте суп по двум тарелкам, посыпьте щедро гремолатой и при желании чёрным перцем.</li></ol><p><em>Посыпьте гремолатой непосредственно перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('f2d528f6-d645-5ab4-ac86-2da3b1b69d96', '23f99077-2062-5081-be00-1037c239aff2', 'en', 'Green detox soup with kale and fennel', 'A puréed vegetable soup of onion, fennel and kale, brightened with lemon and fresh herbs. It is topped with a crunchy gremolata of toasted hemp seeds and garlic.', '<ol><li>Heat 1 tbsp of oil in a large pot. Add the onion, chopped fennel and ¼ tsp of salt and cook for 3–5 minutes until the onion starts to brown.</li><li>Stir in the chopped kale and cook 3–4 minutes until wilted. If bits stick to the bottom, loosen them with 1 tbsp of water at a time.</li><li>Pour in the vegetable broth, bring to a boil, reduce the heat, cover and simmer for 10 minutes. Take off the heat.</li><li>Immediately stir in two-thirds of the garlic and let the soup cool uncovered for about 10 minutes.</li><li>Meanwhile, heat the remaining oil in a skillet, add the hemp seeds, remaining salt and garlic. Spread in a single layer and cook, stirring, for about 3 minutes until golden and fragrant.</li><li>Move the mixture to a bowl, let cool slightly and stir in the lemon zest and chopped fennel fronds. This is the gremolata.</li><li>Add the cilantro, parsley and lemon juice to the soup and blend until completely smooth.</li><li>Ladle the soup into two bowls, top generously with the gremolata and add pepper if you like.</li></ol><p><em>Spoon the gremolata over the soup right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('80c7de4b-75af-55d0-8848-837c62ac1e79', '562e08ab-1a38-5b83-a38c-3a121b936422', 'ru', 'Салат с нутом и авокадо', 'Лёгкий салат из ромэна, нута, огурца, черри и авокадо с оливковым маслом и яблочным уксусом или лимонным соком.', '<ol><li>Нарежьте ромэн, огурец и авокадо, разрежьте помидоры черри пополам. Нут промойте и обсушите.</li><li>Разложите салат, нут, огурец, помидоры и авокадо по двум мискам.</li><li>Посолите, поперчите и полейте оливковым маслом и яблочным уксусом (или лимонным соком).</li></ol><p><em>Заправляйте непосредственно перед подачей, чтобы авокадо не потемнело.</em></p>', CURRENT_TIMESTAMP),
  ('8cc1be9b-9151-5cfb-b293-b1f154971466', '562e08ab-1a38-5b83-a38c-3a121b936422', 'en', 'Chickpea and avocado salad', 'A light salad of romaine, chickpeas, cucumber, cherry tomatoes and avocado, dressed with olive oil and cider vinegar or lemon.', '<ol><li>Chop the romaine, dice the cucumber, slice the avocado and halve the tomatoes. Rinse and drain the chickpeas.</li><li>Divide the lettuce, chickpeas, cucumber, tomatoes and avocado between two bowls.</li><li>Season with salt and pepper and drizzle with olive oil and cider vinegar (or lemon juice).</li></ol><p><em>Dress it right before serving so the avocado stays green.</em></p>', CURRENT_TIMESTAMP),
  ('b441e199-9924-5fb1-ad34-25f4338a19ec', '105463e3-c41c-5a10-b35a-a3e1ad6d2326', 'ru', 'Курица по-охотничьи (качиаторе) в мультиварке', 'Куриные бёдра, тушёные с томатами, луком и сладким перцем в итальянском стиле. Соус получается густым и сытным.', '<ol><li>Посолите и поперчите куриные бёдра со всех сторон.</li><li>Включите режим жарки, слегка смажьте чашу маслом и обжарьте бёдра с двух сторон по несколько минут. Выложите на тарелку.</li><li>Добавьте ещё немного масла, лук и оба вида перца и обжарьте около 5 минут до мягкости и золотистого цвета.</li><li>Верните курицу, залейте томатами, добавьте орегано, лавровый лист, соль и перец, перемешайте и закройте крышку.</li><li>Готовьте под высоким давлением 25 минут, затем дайте давлению сбросить естественным образом.</li><li>Выньте лавровый лист, посыпьте базиликом или петрушкой и подавайте с гарниром.</li></ol><p><em>Подавайте с пастой, рисом или полентой.</em></p>', CURRENT_TIMESTAMP),
  ('498ee5e9-f7ff-5f1b-b17c-e33f160afd5a', '105463e3-c41c-5a10-b35a-a3e1ad6d2326', 'en', 'Pressure cooker chicken cacciatore', 'Chicken thighs braised with tomatoes, onion and bell peppers, Italian hunter style. The sauce turns out thick and hearty.', '<ol><li>Season the chicken thighs with salt and pepper on both sides.</li><li>Set the pot to sauté, lightly oil it and brown the thighs for a few minutes per side. Set aside.</li><li>Add a little more oil, the onion and both peppers and sauté for about 5 minutes until soft and golden.</li><li>Return the chicken, pour the tomatoes over, add the oregano, bay leaf, salt and pepper, stir briefly and close the lid.</li><li>Cook at high pressure for 25 minutes, then release the pressure naturally.</li><li>Remove the bay leaf, sprinkle with basil or parsley and serve with a side.</li></ol><p><em>Serve over pasta, rice or polenta.</em></p>', CURRENT_TIMESTAMP),
  ('8053c287-63aa-57e8-aa71-f6ac222b79ae', 'a859e544-d792-55d2-b03f-07856cca5ff1', 'ru', 'Запечённая курица с песто, помидорами и моцареллой', 'Тонкие куриные отбивные с песто, ломтиками помидора и сыром, запечённые в духовке. Быстрое блюдо с минимумом углеводов.', '<ol><li>Куриную грудку обсушите, разрежьте вдоль пополам на 4 тонких куска. Слегка посолите и поперчите.</li><li>Разогрейте духовку до 200 °C и застелите противень фольгой или пергаментом.</li><li>Выложите курицу на противень и смажьте каждый кусок примерно ч. л. песто.</li><li>Запекайте 15 минут, пока внутри мясо не перестанет быть розовым. Достаньте, положите сверху ломтики помидора, моцареллу и пармезан.</li><li>Верните в духовку ещё на 3–5 минут, пока сыр не расплавится.</li></ol><p><em>Подойдёт с овощным салатом или отварной пастой.</em></p>', CURRENT_TIMESTAMP),
  ('82308354-1a29-5beb-8d19-4c901c3ebcaf', 'a859e544-d792-55d2-b03f-07856cca5ff1', 'en', 'Baked chicken with pesto, tomato and mozzarella', 'Thin chicken cutlets topped with pesto, sliced tomato and melted cheese. A fast, low-carb oven dinner.', '<ol><li>Pat the chicken dry and slice each breast horizontally to make 4 thin cutlets. Season lightly with salt and pepper.</li><li>Preheat the oven to 200°C (400°F) and line a baking sheet with foil or parchment.</li><li>Place the chicken on the baking sheet and spread about 1 tsp of pesto over each piece.</li><li>Bake for 15 minutes, until no longer pink in the center. Remove, then top with the tomato slices, mozzarella and parmesan.</li><li>Return to the oven for 3–5 minutes, until the cheese melts.</li></ol><p><em>Serve with a green salad or pasta.</em></p>', CURRENT_TIMESTAMP),
  ('cc448784-be84-519e-aeeb-dbba9f91f830', '30249cf7-e3cd-50b7-a587-8dc6dda4a1dc', 'ru', 'Фриттата со спаржей и швейцарским сыром', 'Воздушная запеканка из яиц и белков со спаржей, шалотом и сыром. Начинают на сковороде, доводят в духовке.', '<ol><li>Спаржу очистите от жёстких концов и приготовьте на пару 3–4 минуты, чтобы она осталась хрустящей. Нарежьте наискосок кусочками по 1,5 см.</li><li>Разогрейте духовку до 180 °C.</li><li>Растопите масло в жаропрочной сковороде диаметром 25 см, обжарьте шалот 4–5 минут до золотистого цвета. Добавьте спаржу, соль и перец.</li><li>Взбейте яйца и белки с тёртым пекорино, солью и перцем, добавьте швейцарский сыр и перемешайте.</li><li>Влейте яйца в сковороду так, чтобы они покрыли спаржу. Готовьте на среднем огне около 4 минут, пока края не схватятся.</li><li>Переставьте сковороду в духовку на 16–18 минут, пока фриттата полностью не пропечётся. Нарежьте на 4 части.</li></ol><p><em>Нарежьте на 4 порции и подайте горячей или тёплой.</em></p>', CURRENT_TIMESTAMP),
  ('ee36aa5c-58dc-50be-9d5a-820b12e5a503', '30249cf7-e3cd-50b7-a587-8dc6dda4a1dc', 'en', 'Asparagus and Swiss cheese frittata', 'A light egg and egg-white frittata with asparagus, shallots and cheese, started on the stove and finished in the oven.', '<ol><li>Trim the tough ends off the asparagus and steam for 3–4 minutes until crisp-tender. Slice diagonally into 1.5 cm pieces.</li><li>Preheat the oven to 180°C (350°F).</li><li>Melt the butter in a 25 cm oven-safe skillet and sauté the shallots for 4–5 minutes until golden. Add the asparagus, salt and pepper.</li><li>Whisk the eggs and egg whites with the grated pecorino, salt and pepper, then mix in the Swiss cheese.</li><li>Pour the eggs into the skillet so they cover the asparagus. Cook over medium heat for about 4 minutes, until the edges begin to set.</li><li>Move the skillet to the oven for 16–18 minutes, until the frittata is cooked through. Cut into 4 wedges.</li></ol><p><em>Cut into 4 wedges and serve hot or warm.</em></p>', CURRENT_TIMESTAMP),
  ('990a83a6-1a85-5063-b8f0-9e03cc50bf29', 'f3907c03-1047-5cd1-99a9-04b091f6329c', 'ru', 'Паста с курицей и перцем в стиле фахитас', 'Куриная грудка с луком, сладким перцем и мексиканскими специями, сваренная вместе с пастой в томатном бульоне на одной сковороде. Подаётся со сметаной и авокадо.', '<ol><li>Нарежьте курицу небольшими кусочками и приправьте ¾ ч. л. соли, 1 ч. л. зиры, ½ ч. л. паприки, ¼ ч. л. чили и ¼ ч. л. чесночного порошка.</li><li>В большой глубокой сковороде разогрейте 1 ч. л. масла на сильном огне. Обжарьте курицу 5–6 минут, помешивая, до золотистого цвета. Переложите на тарелку.</li><li>Убавьте огонь до среднего, добавьте остальное масло, лук, оба перца, оставшиеся зиру, паприку, чили, чесночный порошок и ¼ ч. л. соли. Готовьте около 10 минут до мягкости.</li><li>Добавьте чеснок на 30 секунд и переложите овощи к курице.</li><li>В ту же сковороду влейте бульон, добавьте томаты с зелёным чили и сырую пасту. Доведите до кипения, накройте, убавьте огонь и готовьте 15 минут, пока паста не станет мягкой, а жидкость почти не впитается.</li><li>Верните курицу и овощи в сковороду и прогрейте 2 минуты. Добавьте сметану, посыпьте зелёным луком и кинзой и подавайте с авокадо.</li></ol><p><em>Посыпьте кинзой и зелёным луком, добавьте авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('f7798866-22f9-5f75-b0f2-29a2e94b1dec', 'f3907c03-1047-5cd1-99a9-04b091f6329c', 'en', 'One-pot chicken fajita pasta', 'Chicken breast with onion, bell peppers and Mexican spices, cooked together with pasta in a tomato broth in one skillet. Finished with sour cream and avocado.', '<ol><li>Cut the chicken into bite-size pieces and season with ¾ tsp salt, 1 tsp cumin, ½ tsp paprika, ¼ tsp chili powder and ¼ tsp garlic powder.</li><li>Heat 1 tsp of oil in a large deep skillet over high heat. Brown the chicken for 5–6 minutes, stirring, then move to a plate.</li><li>Reduce to medium heat, add the remaining oil, the onion, both peppers and the rest of the cumin, paprika, chili, garlic powder and ¼ tsp salt. Cook about 10 minutes until soft.</li><li>Stir in the garlic for 30 seconds, then move the vegetables to the plate with the chicken.</li><li>In the same skillet, combine the broth, tomatoes with green chilies and uncooked pasta. Bring to a boil, cover, reduce the heat and cook 15 minutes until the pasta is tender and most of the liquid is absorbed.</li><li>Return the chicken and vegetables and heat through for 2 minutes. Stir in the sour cream, then top with scallion and cilantro and serve with avocado.</li></ol><p><em>Top with cilantro, scallions and avocado.</em></p>', CURRENT_TIMESTAMP),
  ('8b7064df-4c95-5039-ab9d-778932d2ac14', '333727fa-4a41-5268-b6d5-993a72820134', 'ru', 'Лагман жареный с говядиной и домашней лапшой', 'Лапша ручной вытяжки с густой обжаркой из говядины, овощей и томатной пасты. Классическое блюдо Центральной Азии.', '<ol><li>Смешайте муку с солью, сделайте углубление и понемногу вливайте воду, замешивая тесто. Месите около 10 минут до мягкого гладкого теста, накройте плёнкой и оставьте на 15–20 минут.</li><li>Разделите тесто на 3 части. Смажьте маслом тарелку и стол, раскатайте каждую часть в длинный жгут тоньше пальца. Уложите жгуты спиралью на тарелку, смажьте маслом, накройте и оставьте на 20 минут.</li><li>В большой сковороде или воке разогрейте масло и обжарьте нарезанную тонкими ломтиками говядину до румяности. Если выделилось много жидкости, слейте её.</li><li>Добавьте чеснок и имбирь на минуту, затем лук, помидоры и пекинскую капусту, жарьте 3–4 минуты.</li><li>Добавьте стручковую фасоль, оба перца, соль, чёрный перец и соевый соус, жарьте, пока овощи не станут мягкими.</li><li>Влейте уксус, добавьте зелёный лук, томатную пасту и воду, перемешайте и держите на слабом огне, пока варится лапша.</li><li>Вскипятите подсоленную воду. Растяните каждый жгут теста ещё тоньше, наматывая на ладони и ударяя о стол, чтобы лапша стала тонкой и длинной.</li><li>Варите лапшу 2–3 минуты, слейте воду, оставив немного. Выложите лапшу в миски, сверху положите жареную смесь.</li></ol><p><em>Подавайте горячим, при желании с небольшим количеством бульона от лапши.</em></p>', CURRENT_TIMESTAMP),
  ('764ff289-8037-54e0-8f03-492736e7378c', '333727fa-4a41-5268-b6d5-993a72820134', 'en', 'Lagman: beef and vegetable stir fry with hand-pulled noodles', 'Hand-pulled noodles topped with a stir fry of beef, vegetables and tomato paste. A classic Central Asian dish.', '<ol><li>Mix the flour and salt, make a well and add the water a little at a time, working it into a dough. Knead for about 10 minutes until soft and smooth, cover and rest for 15–20 minutes.</li><li>Divide the dough into 3 pieces. Oil a plate and the work surface, roll each piece into a long rope thinner than a finger, coil the ropes on the plate, brush with oil, cover and let sit for 20 minutes.</li><li>Heat the oil in a large wok or pan and brown the thinly sliced beef. If it releases a lot of liquid, drain it off.</li><li>Add the garlic and ginger for a minute, then the onion, tomatoes and Chinese cabbage and stir-fry for 3–4 minutes.</li><li>Add the green beans, both peppers, salt, black pepper and soy sauce and stir-fry until the vegetables wilt.</li><li>Stir in the vinegar, green onion, tomato paste and water and keep on low heat while you cook the noodles.</li><li>Bring salted water to a boil. Stretch each rope even thinner by wrapping it over both hands and slapping it against the table until it becomes long thin noodles.</li><li>Boil the noodles for 2–3 minutes, drain (reserve a little water), put them in bowls and top with the stir fry.</li></ol><p><em>Serve hot, with a little noodle cooking water on the side if you like.</em></p>', CURRENT_TIMESTAMP),
  ('9da19b63-ee8c-5ffe-8ca8-96822119c4ca', '714876f9-89a1-53cb-9d2d-433d8f5f3d16', 'ru', 'Мусака с говядиной, свининой и баклажанами', 'Запеканка слоями: жареный картофель и баклажаны, мясной соус с корицей и мускатным орехом, сверху сырный бешамель.', '<ol><li>Нарежьте баклажаны кружками по 6 мм, выложите на бумажные полотенца и посолите. Через 15 минут промокните выступившую влагу, переверните, посолите вторую сторону и снова промокните через 15 минут.</li><li>В большой сковороде обжарьте лук с чесноком на оливковом масле около 5 минут, добавьте томатную пасту. Добавьте фарш и жарьте, разбивая комочки, до готовности.</li><li>Откиньте мясо на сито и отожмите лишний жир. Верните в сковороду, добавьте корицу, мускатный орех, соль и перец, прогрейте минуту.</li><li>Влейте вино и готовьте около 5 минут, затем добавьте томаты и тушите без крышки 25–30 минут, помешивая, пока почти вся жидкость не выпарится.</li><li>Разогрейте в сковороде масло примерно на 6 мм до 175 °C. Обжарьте баклажаны по 3–5 минут с каждой стороны до румяности, затем так же картофельные кружки. Выложите на бумажные полотенца и промокните от масла.</li><li>Для бешамеля растопите масло, всыпьте муку и готовьте 2 минуты. Влейте молоко, помешивая, доведите до лёгкого кипения и варите 2 минуты до загустения. Посолите и по частям добавьте часть тёртого сыра.</li><li>Разогрейте духовку до 175 °C. Смажьте форму 20×20 см маслом, выложите картофель, половину баклажанов и половину мясного соуса, затем остальные баклажаны и соус.</li><li>Залейте бешамелем, посыпьте оставшимся сыром и запекайте около 45 минут до золотистой корочки. Дайте постоять 30 минут.</li></ol><p><em>Дайте запеканке постоять 30 минут перед нарезкой.</em></p>', CURRENT_TIMESTAMP),
  ('cdc77cdf-d40b-5da9-a82b-ea1532f6e35d', '714876f9-89a1-53cb-9d2d-433d8f5f3d16', 'en', 'Moussaka with beef, pork and eggplant', 'A layered casserole of fried potatoes and eggplant, a cinnamon-and-nutmeg meat sauce and a cheesy béchamel on top.', '<ol><li>Slice the eggplant into ¼-inch rounds, lay them on paper towels and salt generously. After 15 minutes blot off the moisture, flip, salt the other side and blot again after another 15 minutes.</li><li>In a large skillet sauté the onion and garlic in olive oil for about 5 minutes, then stir in the tomato paste. Add the ground meats and cook, breaking them up, until done.</li><li>Drain the meat in a colander, pressing out excess fat. Return it to the skillet with cinnamon, nutmeg, salt and pepper and cook for a minute.</li><li>Pour in the wine and cook for about 5 minutes, then add the tomatoes and simmer uncovered for 25–30 minutes, stirring, until almost all the liquid has evaporated.</li><li>Heat about ¼ inch of oil to 350 °F (175 °C). Fry the eggplant rounds 3–5 minutes per side until browned, then do the same with the potato slices. Drain on paper towels and blot off excess oil.</li><li>For the béchamel, melt the butter, stir in the flour and cook for 2 minutes. Whisk in the milk, bring to a gentle simmer and cook for 2 minutes until thick. Season with salt and stir in part of the grated cheese in portions.</li><li>Preheat the oven to 350 °F (175 °C). Oil an 8×8-inch dish and layer the potatoes, half the eggplant and half the meat sauce, then the remaining eggplant and sauce.</li><li>Spread the béchamel on top, sprinkle with the remaining cheese and bake for about 45 minutes until browned. Let rest for 30 minutes.</li></ol><p><em>Let the casserole rest for 30 minutes before slicing.</em></p>', CURRENT_TIMESTAMP),
  ('d34b8cdd-2354-595e-ac18-1030d778cb62', '2adf2955-a8fc-52f5-85ab-29629a23086a', 'ru', 'Куриный паприкаш со сметаной', 'Курица, тушёная с луком и сладкой паприкой, в густом сметанном соусе. Классика венгерской кухни.', '<ol><li>Посолите куски курицы и отложите.</li><li>В кастрюле с толстым дном растопите жир, обжарьте нарезанный лук до прозрачности, добавьте чеснок на минуту.</li><li>Снимите кастрюлю с огня, всыпьте паприку и перемешайте с луком. Добавьте курицу, обваляйте в паприке и верните на огонь.</li><li>Накройте крышкой на 5 минут. Если курица выпустила мало сока, влейте около стакана воды, чтобы жидкость доходила до половины кусков.</li><li>Тушите под крышкой 20 минут, переверните курицу и готовьте ещё около 30 минут, пока мясо не будет готово (в середине 74 °C).</li><li>Достаньте курицу. Разведите сметану несколькими ложками соуса, верните в кастрюлю и перемешайте. При желании пробейте соус блендером до гладкости.</li><li>Если соус жидкий, смешайте муку с ложкой соуса и добавьте в кастрюлю, прогрейте несколько минут. Верните курицу в соус.</li></ol><p><em>Подайте с лапшой, галушками или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('ca56b218-b79c-5133-91d5-3f340b3a05f9', '2adf2955-a8fc-52f5-85ab-29629a23086a', 'en', 'Chicken paprikash with sour cream', 'Chicken stewed with onion and sweet paprika in a thick sour cream sauce. A Hungarian classic.', '<ol><li>Season the chicken pieces with salt and set aside.</li><li>Melt the fat in a heavy pot, cook the diced onion until translucent and add the garlic for a minute.</li><li>Take the pot off the heat, stir in the paprika to coat the onions, add the chicken and coat it too, then return to the heat.</li><li>Cover for 5 minutes. If the chicken released little juice, add about a cup of water so the liquid comes halfway up the pieces.</li><li>Simmer covered for 20 minutes, turn the chicken and cook about 30 minutes more until done (165 °F / 74 °C inside).</li><li>Take out the chicken. Thin the sour cream with a few spoonfuls of the sauce, stir it back into the pot and, if you like, blend the sauce smooth with a stick blender.</li><li>If the sauce is thin, stir the flour with a spoonful of sauce, add it to the pot and cook a few minutes. Return the chicken to the sauce.</li></ol><p><em>Serve with noodles, dumplings or mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('dc21eab3-d180-515d-adaa-1c065893b618', 'b75f5e5b-35e2-5717-892d-9d5beb0b5446', 'ru', 'Спанакопита: греческий пирог со шпинатом, фетой и филло', 'Начинка из шпината, феты, творога и сливочного сыра между хрустящими слоями теста филло, пропитанными маслом.', '<ol><li>Разогрейте духовку до 175 °C. Разморозьте шпинат (удобно оставить на сите на ночь) и отожмите досуха небольшими порциями через чистое полотенце, иначе пирог будет сырым.</li><li>Миксером взбейте сливочный сыр с яйцами.</li><li>Деревянной ложкой смешайте шпинат, фету, творог, добавьте укроп, соль и перец, затем сливочно-яичную массу.</li><li>Растопите масло и смажьте форму 23×33 см. Выложите 10 листов филло, смазывая каждый маслом.</li><li>Распределите начинку ровным слоем и накройте ещё 10 листами филло, каждый смазывая маслом. Заправьте свисающие края внутрь, смажьте верх маслом и надрежьте на квадраты, не прорезая насквозь.</li><li>Выпекайте 45 минут до хрустящей золотистой корочки. Немного остудите и нарежьте.</li></ol><p><em>Дайте пирогу немного остыть перед нарезкой. Хорошо подходит с овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e59298ad-fdc0-5fce-8344-2d5bc6ce47db', 'b75f5e5b-35e2-5717-892d-9d5beb0b5446', 'en', 'Spanakopita: Greek spinach, feta and phyllo pie', 'A filling of spinach, feta, cottage cheese and cream cheese between crisp, buttery layers of phyllo dough.', '<ol><li>Preheat the oven to 350 °F (175 °C). Thaw the spinach (easiest overnight in a strainer) and squeeze it completely dry in small batches in a clean towel, otherwise the pie will be soggy.</li><li>Beat the cream cheese and eggs with a mixer.</li><li>With a wooden spoon mix the spinach, feta and cottage cheese, add the dill, salt and pepper, then the cream cheese and egg mixture.</li><li>Melt the butter and brush a 9×13-inch pan. Lay down 10 sheets of phyllo, brushing each with butter.</li><li>Spread the filling evenly and top with 10 more buttered phyllo sheets. Tuck in overhanging edges, brush the top with butter and score into squares without cutting through.</li><li>Bake for 45 minutes until crisp and golden. Cool slightly and cut.</li></ol><p><em>Let it cool slightly before cutting. Good with a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('54f5b594-08d5-5929-a636-594f768b3683', 'afe2386c-7391-559a-8df0-d7f36bedd6ac', 'ru', 'Ирландское рагу из говядины с пастернаком и пореем', 'Говядина тушится с картофелем, морковью, пореем и пастернаком в говяжьем бульоне до мягкости. Сытное блюдо в одной кастрюле.', '<ol><li>В жаропрочной кастрюле разогрейте 3 ст. л. масла и обжарьте говядину до румяной корочки. Переложите на тарелку.</li><li>Добавьте 1 ст. л. масла, лук и чеснок, готовьте до прозрачности.</li><li>Добавьте морковь, порей и пастернак и обжаривайте около 5 минут. Положите тимьян, лавровый лист и перец и готовьте ещё 5 минут.</li><li>Добавьте картофель, мясо и тёплый бульон. Накройте крышкой, доведите до кипения и варите на слабом огне около часа, изредка помешивая.</li><li>Проверьте мясо: если оно ещё жёсткое, готовьте ещё 20 минут. Подавайте горячим.</li></ol><p><em>Подайте с ржаным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('2cdc23c3-455b-59dc-8ad6-eda9a51a2ba7', 'afe2386c-7391-559a-8df0-d7f36bedd6ac', 'en', 'Irish beef stew with parsnip and leek', 'Beef simmers with potatoes, carrots, leek and parsnip in beef stock until tender. A hearty one-pot meal.', '<ol><li>In a Dutch oven heat 3 tablespoons of oil and sear the beef until browned. Transfer to a plate.</li><li>Add 1 tablespoon of oil, the onion and garlic and cook until translucent.</li><li>Add the carrots, leek and parsnip and cook for about 5 minutes. Add the thyme, bay leaves and pepper and cook another 5 minutes.</li><li>Add the potatoes, beef and warm stock. Cover, bring to a boil and simmer for about an hour, stirring occasionally.</li><li>Check the beef; if it is still tough, cook another 20 minutes. Serve hot.</li></ol><p><em>Serve with rye bread.</em></p>', CURRENT_TIMESTAMP),
  ('0c8f8056-b4f6-583d-be02-aeaac4f2bce6', 'aae7f68d-3770-5944-9d43-51b0798164ca', 'ru', 'Рататуй запечённый слоями', 'Тонкие кружки кабачка, баклажана, помидоров, перца и лука, выложенные кругами на томатной подушке с тимьяном и запечённые в сковороде.', '<ol><li>Разогрейте духовку до 190 °C.</li><li>Нарежьте кабачки, помидоры, баклажан, перцы и лук тонкими кружками.</li><li>Распределите измельчённые томаты по дну чугунной сковороды диаметром 30 см, посыпьте половиной соли, перцем и положите веточки тимьяна.</li><li>Выкладывайте кружки овощей по кругу, чередуя: кабачок, помидор, баклажан, перец, лук. Заполните всю сковороду, постепенно переходя к центру. Крупные кружки можно разрезать на половинки.</li><li>Посыпьте остальной солью и чесноком. Запекайте около 55 минут, пока овощи не станут мягкими.</li></ol><p><em>Подайте как гарнир к мясу или рыбе либо с хлебом как лёгкое блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('343eb802-a23d-5426-95d7-361b040233a6', 'aae7f68d-3770-5944-9d43-51b0798164ca', 'en', 'Baked layered ratatouille', 'Thin rounds of zucchini, eggplant, tomato, pepper and onion arranged in circles over a thyme-scented tomato base and baked in a skillet.', '<ol><li>Preheat the oven to 375 °F (190 °C).</li><li>Slice the zucchini, tomatoes, eggplant, peppers and onion into thin rounds.</li><li>Spread the crushed tomatoes over the bottom of a 12-inch cast iron skillet and sprinkle with half the salt, the pepper and the thyme sprigs.</li><li>Arrange the vegetable rounds in circles, alternating zucchini, tomato, eggplant, pepper, onion, working toward the centre until the skillet is full. Halve larger rounds if needed.</li><li>Sprinkle with the remaining salt and the garlic. Bake about 55 minutes until the vegetables are soft.</li></ol><p><em>Serve as a side with meat or fish, or with bread as a light meal.</em></p>', CURRENT_TIMESTAMP),
  ('d27ac31a-5c1c-51dd-b315-d109c8016d49', '696e99c4-c642-5ac6-943e-0b5fc7d49901', 'ru', 'Куриные бёдра барбекю, маринованные с луком', 'Бёдрышки без кожи маринуются с луком, майонезом и специями от 6 часов до ночи, затем жарятся на гриле или запекаются с соусом барбекю. Получаются сочными и удобны для гостей.', '<ol><li>Приправьте бёдра с обеих сторон солью, перцем и чесночным порошком, переверните, чтобы специи легли равномерно.</li><li>Добавьте майонез и перемешайте, затем лук толстыми кольцами. Накройте плотно плёнкой или крышкой и уберите мариноваться на 6 часов или на ночь.</li><li>На гриле: разогрейте гриль, обильно смажьте решётку маслом, убавьте огонь до слабого и выложите бёдра гладкой стороной вверх. Накройте крышкой и жарьте 12–15 минут, один раз повернув решётку для рисунка. Перед переворотом смажьте соусом барбекю.</li><li>Переверните, смажьте обратную сторону соусом, накройте и жарьте ещё 12–15 минут, пока сок из самого толстого места не станет прозрачным. Снова переверните, покройте соусом и снимите. Дайте отдохнуть 5–10 минут.</li><li>В духовке: разогрейте до 200 °C, разложите бёдра гладкой стороной вверх в один слой на противне с бортиками и запекайте 30 минут.</li><li>Повысьте температуру до 230 °C, обильно смажьте бёдра соусом барбекю и верните в духовку на 5 минут, пока глазурь слегка не подсохнет.</li></ol><p><em>Дайте мясу полежать 5–10 минут перед подачей. Хорошо с кукурузой, салатом или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('39ec5acc-80e5-5f0f-ae5b-00e8626168ee', '696e99c4-c642-5ac6-943e-0b5fc7d49901', 'en', 'Marinated barbecued chicken thighs', 'Boneless thighs marinated with onion, mayo and spices for 6 hours or overnight, then grilled or baked and glazed with barbecue sauce. Juicy and great for entertaining.', '<ol><li>Season both sides of the thighs with salt, pepper and garlic powder, turning to coat evenly.</li><li>Stir in the mayonnaise until evenly coated, then add the thickly sliced onion. Cover tightly and marinate for 6 hours or overnight.</li><li>On the grill: preheat, oil the grates generously, reduce to low and place the thighs smooth side up. Cover and cook 12–15 minutes, rotating once for grill marks. Baste with barbecue sauce before flipping.</li><li>Flip, baste the other side, cover and cook another 12–15 minutes, until the juices of the thickest part run clear. Flip once more, brush with sauce and remove. Rest for 5–10 minutes.</li><li>In the oven: preheat to 200°C (400°F), lay the thighs smooth side up in a single layer on a rimmed baking dish and bake for 30 minutes.</li><li>Raise the heat to 230°C (450°F), brush the thighs generously with barbecue sauce and return to the oven for 5 minutes until the glaze sets slightly.</li></ol><p><em>Rest the chicken for 5–10 minutes before serving. Good with corn, salad or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('04436108-9fb1-58a7-8beb-9e155d077dec', '2ec8acf0-e89c-5553-8278-b5f68218cad2', 'ru', 'Запеканка-лазанья с пастой пенне и фаршем', 'Быстрая версия лазаньи без слоёв: пенне, мясной соус, творожно-сырная масса и сверху плавленый сыр. Всё смешивается в одной форме и запекается.', '<ol><li>Отварите пенне в подсоленной воде до состояния al dente. Оставьте 1 стакан воды от варки, пасту слейте.</li><li>В большой глубокой жаропрочной сковороде обжаривайте фарш с луком на среднем и сильном огне 5–8 минут, разминая лопаткой, пока мясо не будет готово. Слейте лишний жир.</li><li>Добавьте сахар, орегано, соль, зиру и перец, влейте томатный соус и доведите до кипения. Снимите с огня.</li><li>Тем временем размять кесо фреско в миске, добавьте сметану, яйцо, 1 стакан тёртой моцареллы, петрушку и чесночную соль. Перемешайте и добавьте в мясной соус, смешивая лишь до однородности.</li><li>Добавьте пасту и по вкусу воду от варки (около ½ стакана) для сочности. Разровняйте, посыпьте чеддером и оставшейся моцареллой.</li><li>Запекайте при 180 °C около 20 минут, пока сыр не расплавится, а середина не станет горячей.</li></ol><p><em>Подавайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('f24f8b93-a643-5562-a742-00e493b72836', '2ec8acf0-e89c-5553-8278-b5f68218cad2', 'en', 'Lasagna casserole with penne and ground beef', 'A quick no-layer lasagna: penne, meat sauce, a creamy cheese mixture and more cheese on top, mixed in one dish and baked.', '<ol><li>Cook the penne in salted water until al dente. Reserve 1 cup of the pasta water, then drain.</li><li>In a large deep oven-safe pan, sauté the beef with the onion over medium-high heat for 5–8 minutes, breaking up the meat, until cooked through. Drain off excess fat.</li><li>Stir in the sugar, oregano, salt, cumin and pepper, add the tomato sauce and bring to a simmer. Remove from the heat.</li><li>Meanwhile, crumble the queso fresco in a bowl and mix with the sour cream, egg, 1 cup of the mozzarella, parsley and garlic salt. Add to the meat sauce and fold just until combined.</li><li>Stir in the pasta and some reserved pasta water (about ½ cup) for juiciness. Smooth the top and sprinkle with the cheddar and remaining mozzarella.</li><li>Bake at 180°C (350°F) for about 20 minutes, until the cheese melts and the centre is steaming hot.</li></ol><p><em>Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('f0eb056b-9054-5050-8e23-ef29238612f1', '028939f8-4deb-5a87-82af-7d70e320459e', 'ru', 'Запечённый картофель с паприкой', 'Картофель кубиками, запечённый с оливковым маслом и паприкой до золотистой корочки. Простой гарнир к яичнице, мясу или рыбе.', '<ol><li>Разогрейте духовку до 200 °C, выстелите противень пергаментом. Картофель вымойте, очистите и нарежьте кубиками по 1,5 см.</li><li>Перемешайте картофель с маслом, паприкой, солью и перцем так, чтобы он равномерно покрылся.</li><li>Сразу выложите на противень в один слой и запекайте около 20 минут до готовности.</li><li>Быстро перемешайте, включите режим гриля и допеките 2–4 минуты до золотистой корочки. Посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('2f4c313d-6b3a-57ce-8e6d-9e9409e50dd1', '028939f8-4deb-5a87-82af-7d70e320459e', 'en', 'Oven-baked paprika breakfast potatoes', 'Diced potatoes roasted with olive oil and paprika until golden and crisp at the edges. A simple side for eggs, meat or fish.', '<ol><li>Preheat the oven to 200°C (400°F) and line a rimmed baking sheet with parchment. Wash, peel and dice the potatoes into 1.5 cm cubes.</li><li>Toss the potatoes with the oil, paprika, salt and pepper until evenly coated.</li><li>Immediately spread on the sheet in a single layer and bake for about 20 minutes until tender.</li><li>Stir quickly, switch the oven to broil and cook another 2–4 minutes until golden. Garnish with parsley.</li></ol><p><em>Sprinkle with parsley and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('932779e8-d674-5ccd-9fdf-c4ab5fd00a7d', '26a3f744-3c17-533a-9539-335989dce510', 'ru', 'Баклажаны, запечённые с пармезаном и моцареллой', 'Хрустящие запечённые кружки баклажана в панировке, слоями с томатным соусом и сыром. Лёгкая версия итальянской пармиджаны без фритюра.', '<ol><li>Разогрейте духовку до 190 °C и обильно смажьте маслом два противня. Баклажаны нарежьте кружками толщиной около 8 мм.</li><li>Приготовьте три миски: в первой смешайте муку, соль и перец; во второй взбейте яйца; в третьей смешайте сухари с пармезаном.</li><li>Обваляйте каждый кружок сначала в муке, затем в яйце, затем в сухарях с сыром. Выложите на противни, слегка посолите и сбрызните маслом.</li><li>Запекайте 30–35 минут, перевернув кружки на середине и поменяв противни местами. Достаньте из духовки.</li><li>Для соуса прогрейте в кастрюле масло, обжарьте чеснок минуту, влейте томатный соус и доведите до кипения. Добавьте базилик, перемешайте 30 секунд и снимите с огня.</li><li>На дно формы 23x33 см налейте немного соуса, выложите половину баклажанов, половину соуса и половину моцареллы. Повторите слои.</li><li>Запекайте без крышки при 190 °C 20–25 минут, пока сыр не расплавится и слегка не подрумянится.</li></ol><p><em>Дайте постоять 10 минут после духовки, чтобы слои держались. Подавайте с зелёным салатом или пастой.</em></p>', CURRENT_TIMESTAMP),
  ('033cd748-2aeb-566d-9f80-20d7186b07ab', '26a3f744-3c17-533a-9539-335989dce510', 'en', 'Baked eggplant parmesan', 'Crisp baked breaded eggplant rounds layered with marinara and cheese. A lighter version of Italian parmigiana without deep frying.', '<ol><li>Preheat the oven to 190°C (375°F) and generously oil two baking sheets. Slice the eggplants into rounds about 8 mm thick.</li><li>Set up three dishes: flour with salt and pepper; beaten eggs; breadcrumbs mixed with parmesan.</li><li>Dip each slice in flour, then egg, then the breadcrumb mixture. Place on the baking sheets, salt lightly and drizzle with oil.</li><li>Bake 30–35 minutes, flipping halfway and swapping the pans. Remove from the oven.</li><li>For the sauce, heat the oil in a saucepan, cook the garlic for 1 minute, add the tomato sauce and bring to a simmer. Stir in the basil for 30 seconds and remove from the heat.</li><li>Spread a little sauce in a 23x33 cm baking dish, add half the eggplant, then half the sauce and half the mozzarella. Repeat the layers.</li><li>Bake uncovered at 190°C (375°F) for 20–25 minutes, until the cheese is melted and slightly golden.</li></ol><p><em>Let it rest 10 minutes after baking so the layers hold. Serve with a green salad or pasta.</em></p>', CURRENT_TIMESTAMP),
  ('e2dee4c7-d9a7-5dd4-8f07-c62c28d52d0d', '849030c0-d9ad-5d88-a63e-fc8dff794679', 'ru', 'Классический омлет с сыром', 'Нежный пышный омлет из двух яиц с сыром, который готовится на сливочном масле за несколько минут. Главное не пересушить: он должен остаться светло-жёлтым.', '<ol><li>Взбейте яйца с щепоткой соли в небольшой миске до пены.</li><li>Поставьте небольшую сковороду с антипригарным покрытием на средний огонь и растопите масло. Когда оно запенится, вылейте яйца и сразу убавьте огонь до слабого.</li><li>Лопаткой отодвигайте схватившиеся края к центру, давая жидкому яйцу растекаться, и так по кругу, пока омлет почти не загустеет.</li><li>Когда омлет свободно двигается по сковороде, переверните его и выключите огонь.</li><li>Посыпьте сыром и начинкой, сложите пополам и переложите на тарелку.</li></ol><p><em>Добавьте любимую начинку: ветчину, овощи, зелень.</em></p>', CURRENT_TIMESTAMP),
  ('371c4012-8509-557c-9b2e-8ef8216a6716', '849030c0-d9ad-5d88-a63e-fc8dff794679', 'en', 'Classic cheese omelette', 'A tender, fluffy two-egg omelette with cheese, cooked in butter in a few minutes. The key is not to overcook it: it should stay light yellow.', '<ol><li>Beat the eggs with a pinch of salt in a small bowl until foamy.</li><li>Place a small nonstick skillet over medium heat and melt the butter. When it bubbles, pour in the eggs and immediately turn the heat to low.</li><li>Use a spatula to pull the set edges toward the centre, letting the liquid egg fill in, working around the pan until nearly set.</li><li>When the omelette slides freely, flip it and turn off the heat.</li><li>Sprinkle with cheese and fillings, fold in half and slide onto a plate.</li></ol><p><em>Add your favorite fillings: ham, vegetables, herbs.</em></p>', CURRENT_TIMESTAMP),
  ('bd13e592-7e97-5d9a-912f-cf9aaa9d131f', '721c8477-0bbb-5384-9ddc-265f65435a13', 'ru', 'Лосось со спаржей на противне с лимонно-чесночным маслом', 'Филе лосося и спаржа запекаются на одном противне под ароматным маслом с лимоном, чесноком и петрушкой. Готовится за 20 минут.', '<ol><li>Разогрейте духовку до 230 °C, решётку поставьте в верхнюю треть. Выстелите противень пергаментом, обрезав его по размеру, чтобы он не обгорел под грилем.</li><li>Выложите филе лосося в центр противня, по бокам разложите спаржу без жёстких концов. Спаржу сбрызните маслом, всё посолите и поперчите.</li><li>Разомните вилкой мягкое масло с лимонным соком, чесноком, петрушкой, солью и перцем. Намажьте ¾ масла на лосось, остальное разложите на спарже.</li><li>Положите на каждый кусок лосося по кружку лимона и запекайте 10–12 минут (тонкое филе 10 минут, толстое 12).</li><li>Включите гриль и подрумяньте ещё 2–3 минуты, пока лосось не станет слоистым, а внутри не достигнет 63 °C.</li></ol><p><em>Подавайте сразу с рисом или картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('4c3ed70d-ad17-53c9-a033-08517da62814', '721c8477-0bbb-5384-9ddc-265f65435a13', 'en', 'Sheet pan salmon and asparagus with lemon garlic butter', 'Salmon fillets and asparagus baked on one tray under a flavoured butter of lemon, garlic and parsley. Ready in 20 minutes.', '<ol><li>Preheat the oven to 230°C (450°F) with the rack in the top third. Line a rimmed baking sheet with parchment trimmed to fit so it won''t char under the broiler.</li><li>Place the salmon in a row down the centre and arrange the trimmed asparagus on the sides. Drizzle the asparagus with olive oil, then season everything with salt and pepper.</li><li>Mash the softened butter with the lemon juice, garlic, parsley, salt and pepper. Spread ¾ of it over the salmon and dab the rest on the asparagus.</li><li>Top each fillet with a lemon slice and bake for 10–12 minutes (10 for thinner, 12 for thicker fillets).</li><li>Switch to broil and cook another 2–3 minutes until the salmon is flaky and reaches 63°C (145°F) inside.</li></ol><p><em>Serve right away with rice or potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('fa0c457d-351a-51bf-ba74-7c9acb43ea43', '9bb69414-32cd-58e2-816a-77d17bba5ff2', 'ru', 'Салат из нута с огурцами, авокадо и фетой', 'Свежий белковый салат из нута, помидоров черри, огурца, красного лука, авокадо, кинзы и сыра фета с лимонно-масляной заправкой.', '<ol><li>Для заправки взбейте оливковое масло, лимонный сок, чеснок, соль и перец.</li><li>В салатнике соедините нут, помидоры, огурец, лук, авокадо, кинзу и фету.</li><li>Полейте заправкой по вкусу и аккуратно перемешайте.</li></ol><p><em>Заправляйте незадолго до подачи.</em></p>', CURRENT_TIMESTAMP),
  ('57619fe3-d065-5e80-abf8-7ba2cf1b75a0', '9bb69414-32cd-58e2-816a-77d17bba5ff2', 'en', 'Chickpea salad with cucumber, avocado and feta', 'A fresh, protein-packed salad of chickpeas, cherry tomatoes, cucumber, red onion, avocado, cilantro and feta with a lemon-olive oil dressing.', '<ol><li>Whisk the olive oil, lemon juice, garlic, salt and pepper for the dressing.</li><li>In a salad bowl, combine the chickpeas, tomatoes, cucumber, onion, avocado, cilantro and feta.</li><li>Add dressing to taste and toss gently.</li></ol><p><em>Toss with the dressing shortly before serving.</em></p>', CURRENT_TIMESTAMP),
  ('f8ffc9dc-1670-5710-a6c3-5226816d101d', '0bf7d1bd-add4-5eb1-867b-f71798b889ea', 'ru', 'Запечённая рыба с чесноком, базиликом и болгарским перцем', 'Филе белой рыбы маринуется в оливковом масле с чесноком, базиликом и лимоном и запекается на подушке из перца и шалота.', '<ol><li>Обсушите рыбу, посолите и поперчите. Положите в пакет с замком, добавьте орегано, кориандр, паприку, чеснок, базилик, масло и лимонный сок, встряхните, чтобы маринад покрыл рыбу. Оставьте в холодильнике на 30–60 минут.</li><li>Разогрейте духовку до 220 °C. Выложите на дно формы 23×33 см нарезанный перец и шалот.</li><li>Положите рыбу сверху, залейте маринадом и запекайте 15 минут, пока мясо не начнёт легко расслаиваться вилкой.</li></ol><p><em>Подайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('9a7807b0-1e98-5a7b-b985-9cc75806e1b5', '0bf7d1bd-add4-5eb1-867b-f71798b889ea', 'en', 'Baked fish with garlic, basil and peppers', 'White fish fillets marinate in olive oil with garlic, basil and lemon, then bake on a bed of bell peppers and shallots.', '<ol><li>Pat the fish dry and season with salt and pepper. Put it in a zip-top bag with the oregano, coriander, paprika, garlic, basil, oil and lemon juice and massage to coat. Marinate in the fridge for 30–60 minutes.</li><li>Preheat the oven to 425 °F (220 °C). Arrange the sliced peppers and shallots in a 9×13-inch baking dish.</li><li>Lay the fish on top, pour over the marinade and bake for 15 minutes, until it flakes easily with a fork.</li></ol><p><em>Serve with a fresh salad.</em></p>', CURRENT_TIMESTAMP),
  ('244fe0f5-8ae7-5fad-8279-ec77768d241f', 'fa35fccf-bfcc-57c2-9303-69c657751a74', 'ru', 'Мангольд с томатами и рисом по-турецки', 'Мангольд тушится в оливковом масле с луком, чесноком, томатами и рисом до мягкости. Лёгкое постное блюдо в стиле зейтинъяглы.', '<ol><li>В широкой кастрюле разогрейте масло на средне-сильном огне и 3–4 минуты потушите лук до мягкости.</li><li>Добавьте перец чили, чеснок, томатную пасту и резаные томаты, перемешайте и готовьте 2 минуты.</li><li>Добавьте нарезанный мангольд и 2–3 минуты прогревайте, пока он не осядет. Всыпьте промытый рис и перемешайте.</li><li>Влейте горячую воду, посолите и поперчите. Накройте крышкой и тушите на слабо-среднем огне 20–25 минут, пока рис и овощи не станут мягкими.</li><li>Выключите огонь и оставьте под крышкой на 10 минут. Подайте с йогуртом и оливковым маслом.</li></ol><p><em>Подайте с ложкой йогурта и каплей оливкового масла.</em></p>', CURRENT_TIMESTAMP),
  ('de994d7c-ddec-51ca-92d9-2aaff7b409d8', 'fa35fccf-bfcc-57c2-9303-69c657751a74', 'en', 'Turkish Swiss chard with tomato and rice', 'Swiss chard braises in olive oil with onion, garlic, tomato and rice until tender. A light meat-free dish in the Turkish zeytinyağlı style.', '<ol><li>Heat the oil in a wide pan over medium-high heat and soften the onion for 3–4 minutes.</li><li>Add the chilli, garlic, tomato paste and diced tomatoes, stir and cook for 2 minutes.</li><li>Stir in the chopped chard and wilt it for 2–3 minutes, then add the rinsed rice and mix.</li><li>Pour in the hot water, season with salt and pepper, cover and cook over medium-low heat for 20–25 minutes until the rice and vegetables are tender.</li><li>Turn off the heat and let it rest covered for 10 minutes. Serve with yogurt and a drizzle of olive oil.</li></ol><p><em>Serve with a spoonful of yogurt and a drizzle of olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('ef798325-a5a4-5195-b47d-f93bb489e8f0', 'b4911b62-fc73-5c78-be1f-ed72fa11f7fa', 'ru', 'Бамия: египетское рагу из окры с томатами', 'Окра тушится с луком, чесноком, острым перцем и специями в томатном соусе. Подаётся с рисом или лепёшкой, чуть острая и кисловатая.', '<ol><li>В глубокой сковороде с крышкой разогрейте масло. Обжаривайте лук, чеснок и рубленый халапеньо 4–5 минут, не давая чесноку подгореть.</li><li>Добавьте окру и обжаривайте 5–7 минут. Приправьте солью, перцем, душистым перцем, кориандром и паприкой.</li><li>Влейте томаты и воду, сверху выложите кружки помидора. Доведите до кипения, убавьте огонь, прикройте крышкой не полностью и тушите 20–25 минут до мягкости окры.</li><li>Откройте крышку, добавьте сок лайма и подавайте с рисом или питой.</li></ol><p><em>Выжмите ещё лайма по вкусу и подайте с рисом или тёплым питой.</em></p>', CURRENT_TIMESTAMP),
  ('ba0248e5-775a-50f4-8e90-dba4d902b176', 'b4911b62-fc73-5c78-be1f-ed72fa11f7fa', 'en', 'Bamya: Egyptian okra and tomato stew', 'Okra simmers with onion, garlic, chilli and warm spices in tomato sauce. Lightly spicy and tangy, served with rice or pita.', '<ol><li>Heat the oil in a large skillet with a lid. Cook the onion, garlic and chopped jalapeño for 4–5 minutes, stirring, without letting the garlic burn.</li><li>Add the okra and sauté for 5–7 minutes. Season with salt, pepper, allspice, coriander and paprika.</li><li>Add the crushed tomatoes and water and lay the tomato slices on top. Bring to a boil, reduce the heat, partly cover and simmer for 20–25 minutes until the okra is soft.</li><li>Uncover, stir in the lime juice and serve with rice or pita.</li></ol><p><em>Add more lime juice to taste and serve with rice or warm pita.</em></p>', CURRENT_TIMESTAMP),
  ('9e783101-d320-5103-916e-bcbc251dcb7f', '2fd61cea-41be-5eaa-a43e-37845834c952', 'ru', 'Пастицио: греческая запеканка из макарон с мясом и бешамелем', 'Макароны, мясной соус с говядиной, томатами и греческими специями и золотистая яичная заливка бешамель. Запекается до румяной корочки.', '<ol><li>Разогрейте духовку до 175 °C. Отварите пасту в хорошо подсоленной воде до аль денте, слейте, сбрызните оливковым маслом, посыпьте пармезаном и перемешайте. Выложите в форму 23×33 см, по возможности в одном направлении.</li><li>Для мясного соуса обжарьте лук на масле до золотистого цвета, добавьте фарш и чеснок, посолите. Жарьте 8–10 минут, разбивая комочки, затем слейте лишнюю жидкость.</li><li>Добавьте вино, томаты, лавровый лист, душистый перец, корицу, мускатный орех и щепотку сахара. Кипятите 5 минут, затем томите 10–15 минут до густоты и отрегулируйте соль.</li><li>Для бешамеля прогрейте масло, всыпьте муку с солью и перцем и подрумяньте. Постепенно влейте тёплое молоко, постоянно взбивая, и варите 5–7 минут до густоты. Добавьте мускатный орех.</li><li>Слегка взбейте яйца, влейте в них половник горячего соуса, затем верните смесь в сковороду, постоянно взбивая. Доведите до слабого кипения на 2 минуты и снимите с огня.</li><li>Покройте пасту мясным соусом, сверху ровным слоем распределите бешамель.</li><li>Запекайте около часа до золотистой корочки, затем дайте постоять 10 минут и нарежьте квадратами.</li></ol><p><em>Дайте остыть 10 минут и нарежьте квадратами.</em></p>', CURRENT_TIMESTAMP),
  ('4c1bc46e-ed68-5de2-9e5d-e97335c41ea0', '2fd61cea-41be-5eaa-a43e-37845834c952', 'en', 'Greek pastitsio with beef and béchamel', 'Pasta layered with a beef and tomato sauce spiced the Greek way and topped with an egg-enriched béchamel, baked until golden.', '<ol><li>Preheat the oven to 350 °F (175 °C). Boil the pasta in well-salted water until al dente, drain, toss with a little olive oil and the Parmesan and spread in a 9×13-inch dish, aligning the tubes if you can.</li><li>For the meat sauce, brown the onion in oil, add the ground beef and garlic, season with salt and cook for 8–10 minutes, breaking it up, then drain off excess liquid.</li><li>Add the wine, tomatoes, bay leaves, allspice, cinnamon, nutmeg and a pinch of sugar. Boil for 5 minutes, then simmer 10–15 minutes until thick and adjust the salt.</li><li>For the béchamel, heat the oil, stir in the flour with salt and pepper and toast until golden. Slowly whisk in the warm milk and cook 5–7 minutes until smooth and thick. Stir in the nutmeg.</li><li>Lightly beat the eggs, whisk in a ladle of the hot sauce, then return the mixture to the pan, whisking constantly. Bring to a gentle boil for 2 minutes and remove from the heat.</li><li>Cover the pasta with the meat sauce and spread the béchamel evenly on top.</li><li>Bake for about an hour until golden brown, then rest for 10 minutes and cut into squares.</li></ol><p><em>Rest for 10 minutes and cut into squares.</em></p>', CURRENT_TIMESTAMP),
  ('2c8204e1-ea17-58cf-9d42-8119dea4cf93', '9de6f4ce-8ffa-5068-9b71-65a85a8779f7', 'ru', 'Греческое рагу из чёрной фасоли (вигна) с томатами и морковью', 'Консервированная фасоль с овощами, томатами и пряностями варится в одной кастрюле. Сок лимона и петрушка освежают вкус.', '<ol><li>В кастрюле разогрейте масло на среднем огне, обжарьте лук с чесноком до прозрачности лука.</li><li>Добавьте перец и морковь, готовьте 5 минут, помешивая.</li><li>Влейте томаты с соком и воду, добавьте лавровый лист, зиру, орегано, паприку, соль, перец и хлопья чили. Доведите до кипения.</li><li>Добавьте промытую фасоль и кипятите 5 минут, затем убавьте огонь, прикройте крышкой не полностью и варите 25–30 минут, изредка помешивая и при необходимости подливая воду.</li><li>Вмешайте сок лимона и петрушку, разложите по мискам и полейте оливковым маслом.</li></ol><p><em>Подайте с тёплой питой или рисом, сбрызнув оливковым маслом.</em></p>', CURRENT_TIMESTAMP),
  ('f0bd348f-883c-5a63-b59f-985bef86bf27', '9de6f4ce-8ffa-5068-9b71-65a85a8779f7', 'en', 'Greek-style black-eyed peas stew with tomato and carrot', 'Canned black-eyed peas simmer with vegetables, tomatoes and spices in one pot, brightened with citrus and parsley.', '<ol><li>Heat the oil in a pot over medium heat and cook the onion and garlic until the onion is translucent.</li><li>Add the bell pepper and carrots and cook for 5 minutes, stirring.</li><li>Add the tomatoes with their juice and the water, plus the bay leaf, cumin, oregano, paprika, salt, pepper and chilli flakes. Bring to a boil.</li><li>Add the rinsed peas, boil for 5 minutes, then lower the heat, partly cover and simmer for 25–30 minutes, stirring occasionally and adding water if it gets dry.</li><li>Stir in the lemon juice and parsley, ladle into bowls and drizzle with olive oil.</li></ol><p><em>Serve with warm pita or rice and a drizzle of olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('89567e8b-49a7-5243-9715-35dab84022da', '6830f733-439e-50c6-82b3-73808541f157', 'ru', 'Запечённый картофель с дзадзики, фетой и оливками', 'Крупный картофель запекается до хрустящей кожицы, пюрируется внутри с маслом и орегано и подаётся с дзадзики, помидорами, оливками и фетой.', '<ol><li>Разогрейте духовку до 190 °C. Проколите вымытые сухие картофелины вилкой, натрите оливковым маслом и посолите.</li><li>Запекайте на противне около часа (до 75 минут для крупных), пока мякоть не станет мягкой, а кожица хрустящей.</li><li>Пока картофель печётся, смешайте дзадзики: йогурт с натёртым огурцом, чесноком, лимонным соком и укропом. Нарежьте помидор, петрушку, раскрошите фету.</li><li>Дайте картофелю отдохнуть 5 минут, разрежьте вдоль, не прорезая нижнюю кожицу. Выберите мякоть в миску, добавьте ложку масла, соль, перец и орегано и разомните вилкой.</li><li>Выложите пюре обратно в кожицу и украсьте дзадзики, помидором, оливками, фетой и зеленью.</li></ol><p><em>Посыпьте свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('74d2be5c-8db3-5d48-93e5-c2f338daeb24', '6830f733-439e-50c6-82b3-73808541f157', 'en', 'Mediterranean loaded baked potatoes with tzatziki and feta', 'Large potatoes baked until the skin is crisp, mashed inside with olive oil and oregano and topped with tzatziki, tomato, olives and feta.', '<ol><li>Preheat the oven to 375 °F (190 °C). Prick the scrubbed, dry potatoes with a fork, rub with olive oil and sprinkle with salt.</li><li>Bake on a baking sheet for about an hour (up to 75 minutes for large ones) until soft inside and crisp outside.</li><li>Meanwhile make the tzatziki by mixing yogurt with grated cucumber, garlic, lemon juice and dill. Dice the tomato, chop the parsley and crumble the feta.</li><li>Rest the potatoes for 5 minutes, slice each open without cutting through the bottom skin and scoop the flesh into a bowl. Add a spoonful of olive oil, salt, pepper and oregano and mash with a fork.</li><li>Spoon the mash back into the skins and top with tzatziki, tomato, olives, feta and herbs.</li></ol><p><em>Finish with fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('4ca4ee55-5f5d-5519-8b64-2e5623a51290', 'ef0074cd-4f0a-523b-939e-adbcfd1da77e', 'ru', 'Пармиджана из баклажанов с моцареллой и пармезаном', 'Обжаренные в муке и яйце ломтики баклажана слоями с томатным соусом, базиликом, моцареллой и пармезаном, запечённые до пузырящегося сыра.', '<ol><li>Разогрейте духовку до 165 °C. Нарежьте баклажаны вдоль тонкими ломтиками, выложите на бумажные полотенца, посолите и оставьте на 30 минут, затем промокните.</li><li>Приготовьте панировку: взбейте яйца с перцем в одной миске, в другой насыпьте муку. Обваляйте каждый ломтик в муке, затем в яйце.</li><li>Разогрейте масло в большой сковороде на среднем огне и обжарьте баклажаны партиями по 3–5 минут с каждой стороны до золотистого цвета. Выложите на бумажные полотенца.</li><li>Смажьте дно формы томатным соусом, выложите слой баклажанов, пармезан, базилик и ломтики моцареллы, слегка посолите и поперчите. Повторяйте слои, закончив соусом и моцареллой.</li><li>Запекайте 30 минут, пока соус не запузырится, а сыр не расплавится. Дайте постоять 10 минут.</li></ol><p><em>Дайте постоять 10 минут и украсьте свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('d08b9b01-6189-5a4a-a3fb-69ae3111912c', 'ef0074cd-4f0a-523b-939e-adbcfd1da77e', 'en', 'Eggplant Parmesan with mozzarella', 'Eggplant slices breaded in flour and egg and fried, layered with tomato sauce, basil, mozzarella and Parmesan and baked until bubbly.', '<ol><li>Preheat the oven to 325 °F (165 °C). Slice the eggplants lengthwise, lay on paper towels, salt and leave for 30 minutes, then pat dry.</li><li>Set up two bowls, one with the beaten eggs and pepper, the other with flour. Dredge each slice in flour, then dip it in egg.</li><li>Heat the oil in a large skillet over medium heat and fry the eggplant in batches for 3–5 minutes per side until golden. Drain on paper towels.</li><li>Spread a little tomato sauce in a baking dish, add a layer of eggplant, Parmesan, basil and mozzarella slices, season lightly and repeat, finishing with sauce and mozzarella.</li><li>Bake for 30 minutes until the sauce bubbles and the cheese melts. Rest for 10 minutes.</li></ol><p><em>Rest for 10 minutes and garnish with fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('698aa2d7-6222-5f37-a576-9a361aee0582', '18c7db00-d017-5992-af97-28ce07c6a9d0', 'ru', 'Батата харра: острый картофель по-ближневосточному', 'Отварной картофель, обжаренный на оливковом масле с чесноком, кориандром, куркумой и хлопьями чили, с лаймом и свежей зеленью.', '<ol><li>Очистите картофель, залейте водой и варите около 10 минут до готовности, но чтобы он оставался плотным.</li><li>Слейте воду, немного остудите и нарежьте картофель небольшими кусочками.</li><li>Разогрейте масло в чугунной сковороде на среднем огне, на 2–3 минуты добавьте чеснок, хлопья чили и семена кориандра, затем куркуму и сок лайма.</li><li>Добавьте картофель, перемешайте и добавьте половину кинзы, петрушки и укропа. Готовьте ещё 4 минуты, посолите и поперчите.</li><li>Снимите с огня, посыпьте оставшейся зеленью и дополнительными хлопьями чили.</li></ol><p><em>Подавайте тёплым или комнатной температуры как гарнир или закуску.</em></p>', CURRENT_TIMESTAMP),
  ('c3f831af-52a3-5339-9f6f-4903e43a23ca', '18c7db00-d017-5992-af97-28ce07c6a9d0', 'en', 'Batata harra: Middle Eastern spicy potatoes', 'Boiled potatoes pan-fried in olive oil with garlic, coriander, turmeric and chilli flakes, finished with lime and fresh herbs.', '<ol><li>Peel the potatoes, cover with water and boil for about 10 minutes until cooked through but still firm.</li><li>Drain, cool briefly and cut the potatoes into bite-size pieces.</li><li>Heat the oil in a cast-iron skillet over medium heat, add the garlic, chilli flakes and coriander seeds for 2–3 minutes, then the turmeric and lime juice.</li><li>Add the potatoes, toss, and add half of the cilantro, parsley and dill. Cook 4 more minutes, then season with salt and pepper.</li><li>Remove from the heat and top with the remaining herbs and more chilli flakes.</li></ol><p><em>Serve warm or at room temperature as a side or appetizer.</em></p>', CURRENT_TIMESTAMP),
  ('e89d8626-5a81-5261-a35d-e5e8c03b3548', 'a1c39e14-e0b2-58e6-89c6-35da055bc561', 'ru', 'Рагу из белой фасоли с панчеттой и чёрной капустой', 'Быстрое лёгкое рагу из белой фасоли, хрустящей панчетты, овощей и тосканской капусты на курином бульоне.', '<ol><li>Обжарьте панчетту в глубокой жаропрочной кастрюле на среднем огне 5–6 минут до хруста. Выньте шумовкой, оставив жир.</li><li>Влейте масло, добавьте лук, сельдерей и морковь. Готовьте 12–15 минут до золотистого цвета, затем добавьте чеснок на минуту.</li><li>Добавьте фасоль (одну банку слейте, вторую оставьте с жидкостью), бульон и корку пармезана. Варите 15 минут на среднем огне.</li><li>Добавьте нарезанную чёрную капусту и панчетту и готовьте ещё 5 минут. Влейте хересный уксус и посолите по вкусу.</li><li>Разлейте по четырём мискам и посыпьте шнитт-луком.</li></ol><p><em>Подавайте с хрустящим хлебом, посыпав шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('d11b448b-bf77-5166-94dd-a41eacdaed59', 'a1c39e14-e0b2-58e6-89c6-35da055bc561', 'en', 'Pancetta and white bean stew with cavolo nero', 'A speedy, light stew of white beans, crispy pancetta, vegetables and Tuscan kale in chicken stock.', '<ol><li>Cook the pancetta in a deep flameproof casserole over medium heat for 5–6 minutes until crisp. Remove with a slotted spoon, leaving the fat behind.</li><li>Pour in the oil, add the onion, celery and carrot and cook for 12–15 minutes until golden. Stir in the garlic for 1 minute.</li><li>Add the beans (drain one can, leave the other undrained), the stock and the parmesan rind. Cook for 15 minutes over medium heat.</li><li>Stir in the chopped kale and pancetta and cook 5 more minutes. Add the sherry vinegar and season.</li><li>Divide among four bowls and sprinkle with chives.</li></ol><p><em>Serve with crusty bread, topped with chives.</em></p>', CURRENT_TIMESTAMP),
  ('fc11a322-e949-5ba1-b5de-c2ea4a416179', '57e99795-bdad-541e-9838-81edee7d29bd', 'ru', 'Минестроне с красным песто и савойской капустой', 'Овощной суп-минестроне с морковью, сельдереем, капустой и кусочками листов для лазаньи вместо пасты, с ложкой красного песто.', '<ol><li>Разогрейте масло в большой жаропрочной кастрюле. Добавьте лук, морковь, сельдерей и мелко нарезанную кочерыжку капусты, щепотку соли и готовьте около 15 минут до мягкости.</li><li>Добавьте чеснок, хлопья чили и сушёные травы, готовьте 2 минуты. Влейте томатную пасту и обжаривайте 3–4 минуты, пока она не потемнеет.</li><li>Влейте бульон, доведите до кипения, убавьте огонь и варите 5 минут.</li><li>Добавьте 3 ст. л. красного песто, нашинкованную капусту и поломанные листы лазаньи. Хорошо размешайте, чтобы не слиплись, и варите 6–8 минут, часто помешивая, пока капуста и паста не станут мягкими, но не разварятся.</li><li>Разлейте по мискам, добавьте в каждую немного оставшегося песто и посыпьте пармезаном.</li></ol><p><em>Посыпьте тёртым пармезаном и подайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('dc71649f-0b7e-5db5-ae87-04ab7f32e97f', '57e99795-bdad-541e-9838-81edee7d29bd', 'en', 'Red pesto minestrone with Savoy cabbage', 'A vegetable minestrone with carrot, celery, cabbage and snapped lasagne sheets for pasta, finished with a spoonful of red pesto.', '<ol><li>Heat the oil in a large flameproof casserole. Add the onion, carrot, celery and finely chopped cabbage core with a pinch of salt and cook for about 15 minutes until soft.</li><li>Add the garlic, chilli flakes and dried herbs and cook for 2 minutes. Stir in the tomato paste and cook 3–4 minutes until it darkens.</li><li>Pour in the stock, bring to a boil, reduce the heat and simmer for 5 minutes.</li><li>Stir in 3 tbsp of the red pesto, the shredded cabbage and snapped lasagne sheets. Stir well so the pasta doesn''t clump, and cook 6–8 minutes, stirring often, until the pasta and cabbage are tender but still have some bite.</li><li>Ladle into bowls, top each with a little more pesto and sprinkle with parmesan.</li></ol><p><em>Top with grated parmesan and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('e1108eff-23d2-5889-933a-131bb8174405', 'b5fdc11b-d0b1-52f0-b3c1-f98a842d366f', 'ru', 'Паста с нутом и овощами в томатном соусе', 'Простая паста из запасов: мелкая паста, нут, овощи и томатная паста с сыром. Подходит и для ланчбокса.', '<ol><li>Отварите пасту по инструкции на упаковке.</li><li>Тем временем разогрейте на сковороде масло или масло сливочное, добавьте чеснок и нарезанные овощи и обжарьте пару минут до слегка мягкого состояния.</li><li>Добавьте томатную пасту с щепоткой сахара, нут, орегано и половник воды от пасты. Посолите, поперчите и готовьте ещё 1–2 минуты.</li><li>Слейте пасту, оставив чашку воды. Добавьте пасту к овощам и всыпьте сыр. Перемешайте, при необходимости добавьте воду от варки.</li></ol><p><em>Добавьте больше сыра при подаче. Хранится в холодильнике до трёх дней.</em></p>', CURRENT_TIMESTAMP),
  ('9b3abc6b-0ea5-5dfe-9464-8e97a80064d0', 'b5fdc11b-d0b1-52f0-b3c1-f98a842d366f', 'en', 'Storecupboard pasta with chickpeas and vegetables', 'A simple pantry pasta of small pasta shapes, chickpeas, vegetables and tomato paste with cheese. Works well for a packed lunch.', '<ol><li>Cook the pasta following the pack instructions.</li><li>Meanwhile, heat the oil or butter in a frying pan, add the garlic and chopped vegetables and fry for a couple of minutes until just softened.</li><li>Add the tomato paste mixed with a pinch of sugar, the chickpeas, oregano and a ladleful of pasta water. Season well and cook for 1–2 minutes more.</li><li>Drain the pasta, reserving a cup of the water. Add the pasta to the vegetables and stir in the cheese, adding a splash of cooking water if too dry.</li></ol><p><em>Add extra cheese to serve. Keeps chilled for up to three days.</em></p>', CURRENT_TIMESTAMP),
  ('931a391d-b8e3-599c-9f94-69d76ccc3f26', '9389f72d-f032-55a2-8a72-41bf71173408', 'ru', 'Курица с чечевицей, брокколи, лимоном и фетой', 'Быстрый ужин из готовой курицы: брокколи, консервированная зелёная чечевица, анчоусы и лимон, сверху сыр фета и укроп.', '<ol><li>Разделите брокколи на соцветия и нарежьте кочерыжку кусочками, храните отдельно. Разогрейте масло (или жир от запечённой курицы) на сковороде и добавьте кочерыжку с 100 мл воды. Доведите до кипения и варите 4 минуты.</li><li>Добавьте соцветия и готовьте ещё 3 минуты, пока вода не испарится. Добавьте размятый чеснок и анчоусы и жарьте 4 минуты, пока анчоусы не растворятся.</li><li>Всыпьте чечевицу, курицу, лимонный сок, оставшееся масло и 3 ст. л. воды. Накройте крышкой, убавьте огонь и прогрейте 5 минут.</li><li>Подавайте, посыпав фетой, укропом и лимонной цедрой.</li></ol><p><em>Посыпьте фетой, укропом и цедрой прямо перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('8bf4d65b-0110-5847-b6cd-11a6d9722002', '9389f72d-f032-55a2-8a72-41bf71173408', 'en', 'Lemony chicken with green lentils, broccoli and feta', 'A quick supper from leftover cooked chicken: broccoli, canned green lentils, anchovies and lemon, topped with feta and dill.', '<ol><li>Cut the broccoli into florets and the stalk into bite-size pieces, keeping them separate. Heat the oil (or leftover chicken fat) in a frying pan, add the stalks with 100 ml of water, bring to the boil and cook for 4 minutes.</li><li>Add the florets and cook 3 more minutes until the water has evaporated. Add the mashed garlic and anchovies and sizzle for 4 minutes until the anchovies dissolve.</li><li>Add the lentils, chicken, lemon juice, remaining oil and 3 tbsp water. Cover, lower the heat and cook for 5 minutes until heated through.</li><li>Serve scattered with the feta, dill and lemon zest.</li></ol><p><em>Scatter the feta, dill and zest on top right before serving.</em></p>', CURRENT_TIMESTAMP),
  ('fc760811-33b1-545a-ab46-92b41651c9ea', '91914f93-3a83-5380-9885-3a66a5d9d1e3', 'ru', 'Рыбное рагу с картофелем, креветками и мидиями', 'Рагу в одной сковороде с картофелем, томатами, копчёной паприкой и чесноком, с белой рыбой, креветками и мидиями. Малокалорийное и сытное.', '<ol><li>Влейте 2 ст. л. масла в большую неглубокую сковороду с крышкой на среднем огне. Добавьте лук и картофель, накройте и готовьте около 5 минут, помешивая, пока лук не станет мягким.</li><li>Добавьте оставшееся масло, чеснок и специи и готовьте 2 минуты. Влейте лимонный сок и дайте зашипеть.</li><li>Добавьте томаты и 200 мл воды, раскрошите бульонный кубик, слегка посолите и тушите 15–20 минут, пока картофель почти не будет готов.</li><li>Положите креветки и рыбу, сверху разложите мидии. Накройте и готовьте около 8 минут, один–два раза осторожно перемешав. Смешайте петрушку с лимонной цедрой.</li><li>Когда мидии раскроются, а рыба станет непрозрачной, снимите с огня, посыпьте петрушкой с цедрой и сбрызните маслом.</li></ol><p><em>Подавайте прямо из сковороды с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('d061ca52-77b2-592e-a96c-d6c77ac609e1', '91914f93-3a83-5380-9885-3a66a5d9d1e3', 'en', 'One-pan paprika fish, prawn and mussel potato stew', 'A one-pan stew of potatoes, tomatoes, smoked paprika and garlic with white fish, prawns and mussels. Low in fat and filling.', '<ol><li>Heat 2 tbsp of the oil in a large, shallow lidded pan over medium heat. Add the onion and potatoes, cover and cook about 5 minutes, stirring, until the onion softens.</li><li>Add the remaining oil, garlic and spices and cook for 2 minutes. Pour in the lemon juice and let it sizzle briefly.</li><li>Add the tomatoes and 200 ml of water, crumble in the stock cube, season lightly and simmer for 15–20 minutes until the potatoes are nearly cooked.</li><li>Add the prawns and fish and scatter the mussels over. Cover and cook about 8 minutes, stirring gently once or twice. Mix the parsley with the lemon zest.</li><li>When the mussels open and the fish is just cooked, remove from the heat, scatter over the parsley and zest and drizzle with a little oil.</li></ol><p><em>Serve straight from the pan with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('332e31f9-c5db-59f8-9efa-01c937fd933c', 'cc58c2e5-6a9c-5c81-aa12-69cafc5a527a', 'ru', 'Салат с тунцом, фасолью, стручковой фасолью и оливками', 'Сытный салат из консервированного тунца, красной фасоли, стручковой фасоли, оливок, сельдерея и красного лука с лимонно-горчичной заправкой.', '<ol><li>Опустите стручковую фасоль в кипящую воду на 1 минуту, слейте и охладите под холодной водой.</li><li>В большой миске смешайте 1–2 ч. л. масла из банки тунца, 1 ст. л. оливкового масла, цедру лимона и 2 ч. л. сока, винный уксус и горчицу. Посолите, поперчите и взбейте до однородности.</li><li>Добавьте стручковую фасоль, тунец, красную фасоль, лук, сельдерей, оливки и петрушку и перемешайте. Подавайте, посыпав листьями сельдерея.</li></ol><p><em>Для ланчбокса храните заправку отдельно и перемешайте перед едой.</em></p>', CURRENT_TIMESTAMP),
  ('2db73fcc-b59f-513f-a213-cbea281d1fbe', 'cc58c2e5-6a9c-5c81-aa12-69cafc5a527a', 'en', 'Tuna, borlotti bean and green bean salad with olives', 'A hearty salad of tinned tuna, borlotti beans, green beans, olives, celery and red onion in a lemon-mustard dressing.', '<ol><li>Boil the green beans for 1 minute, drain and run under cold water.</li><li>In a large bowl, whisk 1–2 tsp of the oil from the tuna tin, 1 tbsp olive oil, the lemon zest and 2 tsp juice, vinegar and mustard until smooth. Season.</li><li>Add the green beans, tuna, borlotti beans, onion, celery, olives and parsley and toss. Serve topped with celery leaves.</li></ol><p><em>For a packed lunch, keep the dressing separate and toss just before eating.</em></p>', CURRENT_TIMESTAMP),
  ('60575176-06ad-5e41-8551-a788310a9798', '46cfaf88-b7a6-508c-9c8a-0742bd8cfb60', 'ru', 'Паста с курицей, шпинатом, базиликом и сливочным соусом', 'Быстрая паста из остатков запечённой курицы со шпинатом, базиликом, чесноком, белым вином и крем-фреш.', '<ol><li>Отварите пасту по инструкции, оставив кружку воды после варки.</li><li>Разогрейте на большой сковороде масло (или жир от курицы) на среднем и сильном огне. Обжарьте лук 8–10 минут до мягкости.</li><li>Добавьте чили, чеснок и томатную пасту и готовьте 5 минут, пока паста не карамелизуется. Влейте вино и уварите почти полностью, 2–3 минуты.</li><li>Добавьте шпинат, курицу и немного воды от пасты, прогрейте 3–4 минуты. Влейте лимонный сок, добавьте большую часть базилика, крем-фреш и пасту. Перемешайте, при необходимости подлейте воду от варки. Посолите и поперчите.</li><li>Подавайте, посыпав оставшимся базиликом.</li></ol><p><em>Посыпьте оставшимся базиликом и подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('02438725-d795-5045-92bb-ff3c6c978f21', '46cfaf88-b7a6-508c-9c8a-0742bd8cfb60', 'en', 'Creamy spinach, basil and chicken pasta', 'A speedy pasta using leftover roast chicken with spinach, basil, garlic, white wine and crème fraîche.', '<ol><li>Cook the pasta according to the pack and reserve a mugful of the cooking water.</li><li>Heat the oil (or leftover chicken fat) in a large frying pan over medium-high heat. Cook the onion 8–10 minutes until softened.</li><li>Add the chilli, garlic and tomato paste and cook 5 minutes until the paste caramelises. Pour in the wine and simmer 2–3 minutes until almost fully reduced.</li><li>Add the spinach, chicken and a splash of pasta water and cook 3–4 minutes until the chicken is hot. Squeeze in the lemon juice, add most of the basil, the crème fraîche and the pasta. Toss with a splash of cooking water, then season.</li><li>Serve scattered with the remaining basil.</li></ol><p><em>Scatter the remaining basil on top and serve right away.</em></p>', CURRENT_TIMESTAMP),
  ('4e7915b7-66f7-5ae3-84e9-1f281189390c', '0d48a488-8c3b-5bb5-b464-4e192270082a', 'ru', 'Креветки с орзо в чесночно-томатном соусе', 'Крупные креветки в соусе из томатов, чеснока, шалота и белого вина, поданные на орзо со шпинатом. Ужин за 30 минут.', '<ol><li>Поставьте кастрюлю с подсоленной водой на кипячение.</li><li>Для соуса разогрейте масло с маслом сливочным в большой сковороде на среднем и сильном огне. Обжарьте шалот около 3 минут, добавьте чеснок до аромата.</li><li>Влейте вино и варите минуту. Добавьте сок лимона, томаты и воду, доведите до кипения, убавьте огонь до среднего и готовьте 15 минут, иногда помешивая. Добавьте тимьян, щепотку соли и кайенский перец.</li><li>Отварите орзо до состояния al dente по инструкции, слейте и переложите на блюдо.</li><li>Положите креветки в соус и перемешайте. Готовьте около 5 минут, пока они не станут розовыми, не передерживайте.</li><li>Снимите с огня, вмешайте шпинат, чтобы он завял. Выложите креветки на орзо, посыпьте зеленью и подавайте с дольками лимона.</li></ol><p><em>Подавайте сразу, с дольками лимона и свежей зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('53675bb9-0c0f-5345-8e1c-e95ad1f4acfa', '0d48a488-8c3b-5bb5-b464-4e192270082a', 'en', 'Shrimp and orzo in garlicky tomato sauce', 'Large shrimp in a sauce of tomatoes, garlic, shallots and white wine, served over orzo with wilted spinach. Dinner in 30 minutes.', '<ol><li>Bring a medium pot of salted water to a boil.</li><li>For the sauce, heat the olive oil and butter in a large heavy skillet over medium-high. Sauté the shallots about 3 minutes, then add the garlic until fragrant.</li><li>Add the wine and cook 1 minute. Add the lemon juice, tomatoes and water, bring to a boil, lower to medium and cook 15 minutes, stirring occasionally. Stir in the thyme, a pinch of salt and cayenne.</li><li>Cook the orzo until al dente according to the package, drain and transfer to a serving dish.</li><li>Add the shrimp to the sauce and stir to coat. Cook about 5 minutes just until pink; don''t overcook.</li><li>Remove from the heat and stir in the spinach to wilt. Spoon the shrimp over the orzo, garnish with herbs and serve with lemon slices.</li></ol><p><em>Serve immediately with lemon slices and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('d66818cd-cd1e-5d66-8417-bcdca9af2f50', '0aae67c7-50eb-5368-88f8-d2661e2352be', 'ru', 'Куриная грудка по-итальянски, запечённая с помидорами и луком', 'Отбитая куриная грудка с орегано, тимьяном, паприкой, чесноком и лимоном, запечённая на красном луке с помидорами. Получается сочной за 18 минут.', '<ol><li>Разогрейте духовку до 220 °C.</li><li>Обсушите грудки. Положите каждую в пакет с застёжкой, выпустите воздух и отбейте молотком до ровной толщины.</li><li>Посолите и поперчите, переложите в миску и смешайте с орегано, тимьяном, паприкой, чесноком, оливковым маслом и лимонным соком.</li><li>На дно слегка смазанной жаропрочной формы выложите ломтики красного лука, сверху курицу и половинки помидоров.</li><li>Плотно накройте фольгой и запекайте 10 минут, затем снимите фольгу и запекайте ещё 8–10 минут, пока температура в центре не достигнет 74 °C.</li><li>Дайте мясу отдохнуть 5–10 минут под фольгой. Посыпьте петрушкой и базиликом.</li></ol><p><em>Дайте мясу отдохнуть 5–10 минут, посыпьте петрушкой и базиликом. Хорошо с рисом, пастой или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('39aaee0f-0a7c-5d30-9fa2-edccb6ac2c40', '0aae67c7-50eb-5368-88f8-d2661e2352be', 'en', 'Italian baked chicken breast with tomatoes and red onion', 'Pounded chicken breasts seasoned with oregano, thyme, paprika, garlic and lemon, baked over red onion with tomatoes. Juicy in just 18 minutes.', '<ol><li>Preheat the oven to 220°C (425°F).</li><li>Pat the chicken dry. Place each breast in a zip-top bag, press out the air and pound to an even thickness.</li><li>Season with salt and pepper, put in a bowl and coat with the oregano, thyme, paprika, garlic, olive oil and lemon juice.</li><li>Spread the onion slices over the bottom of a lightly oiled baking dish, then arrange the chicken and tomatoes on top.</li><li>Cover tightly with foil and bake 10 minutes, then uncover and bake another 8–10 minutes until it registers 74°C (165°F) inside.</li><li>Let the chicken rest 5–10 minutes covered. Garnish with parsley and basil.</li></ol><p><em>Rest 5–10 minutes, then garnish with parsley and basil. Good with rice, pasta or a salad.</em></p>', CURRENT_TIMESTAMP),
  ('36af7d73-54e5-5a44-ba33-1108129cc850', 'acc7c3a9-e6ec-5738-8bfb-aa5d365844dd', 'ru', 'Куриный гирос в пите с цацики и овощами', 'Курица, замаринованная в йогурте со специями, обжаренная на сковороде и завёрнутая в питу с цацики, помидором, огурцом, перцем, луком и маслинами.', '<ol><li>В большой миске смешайте йогурт, сок лимона, 2 ст. л. масла, уксус, чеснок, орегано, паприку, зиру, кориандр, кайенский перец, соль и перец.</li><li>Добавьте курицу, перемешайте, накройте и мариновать в холодильнике 30 минут или всю ночь.</li><li>Разогрейте на антипригарной сковороде 1 ст. л. масла на среднем и сильном огне. Стряхните лишний маринад и выложите курицу. Жарьте без помешивания около 5 минут до румяной корочки.</li><li>Переверните щипцами и жарьте ещё около 5 минут до готовности.</li><li>Подогрейте питу над огнём или на сухой сковороде. Намажьте цацики, выложите 2–3 кусочка курицы, помидор, огурец, перец, лук и маслины, заверните.</li></ol><p><em>Курицу можно приготовить и на гриле или в духовке. Заворачивайте в тёплую питу.</em></p>', CURRENT_TIMESTAMP),
  ('bba926eb-165f-5387-9024-bc8c7ac0192a', 'acc7c3a9-e6ec-5738-8bfb-aa5d365844dd', 'en', 'Greek chicken gyros with yogurt marinade and pita', 'Chicken marinated in spiced yogurt, pan-seared and wrapped in pita with tzatziki, tomato, cucumber, pepper, onion and olives.', '<ol><li>In a large bowl mix the yogurt, lemon juice, 2 tbsp oil, vinegar, garlic, oregano, paprika, cumin, coriander, cayenne, salt and pepper.</li><li>Add the chicken, toss to coat, cover and marinate in the fridge for 30 minutes or overnight.</li><li>Heat 1 tbsp of oil in a nonstick skillet over medium-high. Shake off excess marinade and add the chicken. Cook undisturbed about 5 minutes until well browned.</li><li>Flip with tongs and cook about 5 minutes more until cooked through.</li><li>Warm the pita over a burner or in a dry skillet. Spread with tzatziki, add 2–3 pieces of chicken, tomato, cucumber, pepper, onion and olives, then wrap.</li></ol><p><em>The chicken also works on the grill or in the oven. Wrap in warm pita.</em></p>', CURRENT_TIMESTAMP),
  ('11dd29f1-e7a9-553c-a3f7-47efca5a3bb1', '37fe6939-5817-5803-9299-df13fff485c3', 'ru', 'Средиземноморский салат из трёх видов фасоли', 'Салат из красной и белой фасоли и нута с сладким перцем, огурцом, луком, каперсами и свежей зеленью в заправке из лимона, горчицы и чеснока.', '<ol><li>В большой миске взбейте чеснок, горчицу, лимонный сок, сахар, оливковое масло, соль и перец.</li><li>Слейте жидкость с консервированной фасоли и нута, промойте и добавьте в миску.</li><li>Добавьте оба перца, огурец, лук, каперсы, петрушку, мяту и базилик и перемешайте.</li><li>Накройте и охладите минимум 30 минут. Перед подачей снова перемешайте.</li></ol><p><em>Выдержите в холодильнике хотя бы 30 минут, чтобы фасоль пропиталась заправкой.</em></p>', CURRENT_TIMESTAMP),
  ('743f25f3-d041-56fd-840d-c428aac5d94c', '37fe6939-5817-5803-9299-df13fff485c3', 'en', 'Mediterranean three bean salad', 'A salad of kidney beans, cannellini beans and chickpeas with sweet peppers, cucumber, onion, capers and fresh herbs in a lemon, mustard and garlic vinaigrette.', '<ol><li>In a serving bowl, whisk the garlic, mustard, lemon juice, sugar, olive oil, salt and pepper.</li><li>Drain and rinse the canned beans and chickpeas, then add them to the bowl.</li><li>Add both peppers, cucumber, onion, capers, parsley, mint and basil and toss.</li><li>Cover and chill for at least 30 minutes. Toss again before serving.</li></ol><p><em>Chill at least 30 minutes so the beans soak up the dressing.</em></p>', CURRENT_TIMESTAMP),
  ('bdaf49fa-e983-5f1e-9aaa-2ff5521ad583', 'acc139cf-d806-59ab-9df1-97ce7c365a85', 'ru', 'Салат из перловки с запечёнными овощами', 'Тёплый или холодный салат из перловки с запечёнными кабачками, перцем и луком, зеленью, лимоном и пряностями. Подходит как гарнир или самостоятельное блюдо.', '<ol><li>Разогрейте духовку до 220 °C. Промойте перловку на мелком сите.</li><li>Переложите перловку в кастрюлю, залейте водой, доведите до кипения, убавьте огонь, накройте и варите 30–45 минут, пока не станет мягкой, но не потеряет упругость.</li><li>Тем временем разложите на противне кабачки, перцы и лук. Сбрызните маслом, посолите, поперчите, добавьте 1½ ч. л. бахарата и ½ ч. л. копчёной паприки, перемешайте. Запекайте около 25 минут до мягкости и карамелизации.</li><li>Слейте воду с перловки на сите, переложите в миску и приправьте солью, перцем, оставшимися ½ ч. л. бахарата и ¼ ч. л. паприки.</li><li>Добавьте запечённые овощи, зелёный лук, чеснок и петрушку, заправьте лимонным соком и маслом и перемешайте. Подавайте тёплым, комнатной температуры или холодным.</li></ol><p><em>Сверху можно добавить феты и обжаренных кедровых орешков.</em></p>', CURRENT_TIMESTAMP),
  ('120986b7-671b-5bc6-941b-9444f1128572', 'acc139cf-d806-59ab-9df1-97ce7c365a85', 'en', 'Barley salad with roasted vegetables', 'A warm or cold salad of pearl barley with roasted zucchini, peppers and onion, fresh herbs, lemon and warm spices. Works as a side or a light main.', '<ol><li>Preheat the oven to 220°C (425°F). Rinse the barley in a fine-mesh sieve.</li><li>Put the barley in a saucepan with the water, bring to a boil, lower the heat, cover and cook 30–45 minutes until tender but still chewy.</li><li>Meanwhile, spread the zucchini, peppers and onion on a rimmed baking sheet. Drizzle with oil, season with salt, pepper, 1½ tsp baharat and ½ tsp smoked paprika, and toss. Roast about 25 minutes until soft and beginning to caramelize.</li><li>Drain the barley, transfer to a large bowl and season with salt, pepper, the remaining ½ tsp baharat and ¼ tsp paprika.</li><li>Add the roasted vegetables, green onions, garlic and parsley, dress with lemon juice and a drizzle of oil and toss. Serve warm, room temperature or chilled.</li></ol><p><em>Top with crumbled feta and toasted pine nuts if you like.</em></p>', CURRENT_TIMESTAMP),
  ('c3d66ab9-6cf7-508e-9497-c25cbffb6381', '957a8414-783e-5473-b929-42cd45b734ec', 'ru', 'Паста с тремя видами грибов, пармезаном и грецкими орехами', 'Паста с обжаренными грибами, шалотом, чесноком, томатной пастой и красным вином, без сливок, но с шелковистым соусом. Сверху пармезан, петрушка и грецкие орехи.', '<ol><li>Отварите пасту в подсоленной воде до состояния al dente. Оставьте 1 стакан воды от варки и слейте.</li><li>Разогрейте в большой сковороде масло со сливочным на среднем и сильном огне. Обжаривайте шалот и чеснок 2–3 минуты, часто помешивая, чтобы чеснок не подгорел.</li><li>Добавьте грибы и ещё немного масла, посыпьте розмарином, солью и перцем. Жарьте 7–10 минут, пока грибы не станут золотистыми и не отдадут сок.</li><li>Добавьте томатную пасту, вино и ½–¾ стакана воды от пасты. Уваривайте 4–5 минут на среднем огне.</li><li>Переложите пасту в соус и перемешайте, при необходимости добавьте воды от пасты. Всыпьте пармезан, посыпьте петрушкой, грецкими орехами и хлопьями чили.</li></ol><p><em>Подавайте горячей, посыпав хлопьями чили по желанию.</em></p>', CURRENT_TIMESTAMP),
  ('e49431ec-d870-51b6-b4aa-ff70bc831f61', '957a8414-783e-5473-b929-42cd45b734ec', 'en', 'Mushroom pasta with parmesan and walnuts', 'Pasta with three kinds of sautéed mushrooms, shallots, garlic, tomato paste and red wine: a silky sauce without cream. Finished with parmesan, parsley and walnuts.', '<ol><li>Cook the pasta in salted water until al dente. Reserve 1 cup of the pasta water and drain.</li><li>In a large skillet heat the olive oil and butter over medium-high. Cook the shallots and garlic 2–3 minutes, stirring often so the garlic doesn''t burn.</li><li>Add the mushrooms and a drizzle more oil, season with the rosemary, salt and pepper. Cook 7–10 minutes until golden and their juices are released.</li><li>Add the tomato paste, wine and ½–¾ cup of the pasta water. Reduce over medium heat for 4–5 minutes.</li><li>Add the pasta to the sauce and toss, adding a splash more pasta water if dry. Stir in the parmesan, then finish with parsley, walnuts and red pepper flakes.</li></ol><p><em>Serve hot, with red pepper flakes if you like.</em></p>', CURRENT_TIMESTAMP),
  ('b71aa45e-5c5b-5558-90c8-0bcfade9aa12', 'a22aff01-bc48-5c65-a6c1-a9b9132a4003', 'ru', 'Мусака с баклажанами, мясным фаршем и бешамелем', 'Греческая запеканка слоями: запечённые баклажаны, пряный мясной соус с томатами и вином и нежный яичный бешамель сверху.', '<ol><li>Обрежьте концы у баклажанов и нарежьте пластинами толщиной 6 мм (самые крайние куски с кожей уберите). Разложите, посыпьте солью и оставьте на 30 минут, чтобы вышла горечь.</li><li>Для мясного соуса разогрейте 2 ст. л. масла в большой сковороде и обжарьте лук около 5 минут до золотистого цвета. Добавьте фарш и жарьте до полной готовности, слейте лишний жир.</li><li>Добавьте орегано, корицу, перец, мускатный орех, паприку и ½ ч. л. соли. Влейте вино и кипятите минуту, затем добавьте томаты, сахар и горячий бульон. Тушите на слабом огне 20–30 минут.</li><li>Включите гриль духовки на максимум. Противень смажьте маслом. Обсушите баклажаны, выложите в один слой и щедро смажьте маслом с обеих сторон.</li><li>Подрумяньте баклажаны под грилем на расстоянии 15 см с обеих сторон, пока не станут мягкими и золотистыми. Следите, чтобы не подгорели.</li><li>Выключите гриль, разогрейте духовку до 180 °C и слегка смажьте маслом форму 24x33 см.</li><li>Для бешамеля разогрейте масло в кастрюле, добавьте муку, соль и перец и обжаривайте до золотистого цвета. Постепенно вливайте тёплое молоко, постоянно взбивая, и варите 5–7 минут до густоты. Добавьте мускат.</li><li>Взбейте яйца в миске, влейте половник горячего бешамеля, перемешайте и верните в соус. Доведите до слабого кипения на 2 минуты, снимите с огня и дайте слегка остыть.</li><li>Выложите в форму половину баклажанов, затем мясной соус, остальные баклажаны, сверху бешамель. Посыпьте сухарями.</li><li>Выпекайте в центре духовки 45 минут. При желании переставьте на верхнюю решётку и подрумяньте под грилем. Дайте постоять 10 минут и нарежьте квадратами.</li></ol><p><em>Дайте мусаке постоять 10 минут после духовки, чтобы кусочки держали форму. Подавайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('842ac8e9-9b13-59c7-a58f-b76e993b28e1', 'a22aff01-bc48-5c65-a6c1-a9b9132a4003', 'en', 'Greek moussaka with eggplant, beef and béchamel', 'A layered Greek casserole of broiled eggplant, spiced meat sauce with tomatoes and wine, and a creamy egg béchamel on top.', '<ol><li>Trim the eggplant and slice into 6 mm slabs (discard outermost skin-heavy slices). Spread out, sprinkle with salt and let sit for 30 minutes to draw out bitterness.</li><li>For the meat sauce, heat 2 tbsp of oil in a large skillet and brown the onion about 5 minutes. Add the ground meat and cook until fully browned, then pour off excess fat.</li><li>Stir in the oregano, cinnamon, pepper, nutmeg, paprika and ½ tsp salt. Add the wine and boil 1 minute, then add the tomatoes, sugar and hot stock. Simmer over medium-low heat 20–30 minutes.</li><li>Turn the oven broiler to high. Oil a large sheet pan. Pat the eggplant dry, arrange in one layer and brush generously with oil on both sides.</li><li>Broil the eggplant about 15 cm from the heat, turning, until both sides are soft and golden. Watch so it doesn''t burn.</li><li>Turn off the broiler, heat the oven to 180°C (350°F) and lightly oil a 24x33 cm baking dish.</li><li>For the béchamel, heat the oil in a large saucepan, stir in the flour, salt and pepper and cook until golden. Gradually whisk in the warm milk and cook 5–7 minutes until it coats the back of a spoon. Season with nutmeg.</li><li>Whisk the eggs in a small bowl, temper with a ladleful of hot béchamel, then whisk back into the sauce. Bring to a gentle boil for 2 minutes, remove from the heat and let cool and thicken slightly.</li><li>Layer half the eggplant in the dish, then the meat sauce, then the remaining eggplant and the béchamel. Sprinkle with breadcrumbs.</li><li>Bake in the centre of the oven for 45 minutes. If you like, move to the top rack and broil briefly to brown. Rest 10 minutes and cut into squares.</li></ol><p><em>Let it rest 10 minutes after baking so the squares hold their shape. Serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('fa2adda3-5fee-5226-bdc2-548ba17e03a9', '630d8e8b-f3f0-5db5-aaa0-50bed182ae8a', 'ru', 'Кремовая полента с маслом и пармезаном', 'Мягкая кукурузная каша, которую медленно варят и в конце взбивают с маслом и пармезаном. Подходит как подушка для рагу и овощей.', '<ol><li>Смешайте кукурузную крупу, холодную воду и соль в кастрюле с толстым дном. Поставьте на средне-сильный огонь и доведите до кипения, помешивая, чтобы не было комков.</li><li>Убавьте огонь до слабого и варите около 45 минут, часто помешивая, пока крупа полностью не разварится.</li><li>Снимите с огня, при необходимости досолите, вмешайте масло и тёртый пармезан и сразу подавайте.</li></ol><p><em>Подавайте сразу, пока полента горячая и мягкая.</em></p>', CURRENT_TIMESTAMP),
  ('b121af50-5210-52e5-8177-63dc5d253e7e', '630d8e8b-f3f0-5db5-aaa0-50bed182ae8a', 'en', 'Creamy polenta with butter and Parmesan', 'A soft cornmeal porridge cooked slowly and finished with butter and Parmesan. A perfect base for stews and vegetables.', '<ol><li>Combine the cornmeal, cold water and salt in a heavy-bottomed pot. Set over medium-high heat and bring to a simmer, stirring to avoid lumps.</li><li>Reduce to low and cook about 45 minutes, stirring often so it doesn''t stick, until the grains are fully cooked.</li><li>Remove from the heat, adjust the salt, stir in the butter and grated Parmesan and serve immediately.</li></ol><p><em>Serve right away while hot and soft.</em></p>', CURRENT_TIMESTAMP),
  ('4edff888-487a-5b60-95b6-5e7b4ac4f62a', '7a5a9c42-900c-5d9f-a1ec-80898ec695d9', 'ru', 'Пепероната: тушёный болгарский перец с фенхелем и томатами', 'Сладкий перец медленно тушится с луком, фенхелем и чесноком в оливковом масле, затем томатным соусом, каперсами и бальзамическим уксусом.', '<ol><li>В большой сковороде с толстым дном смешайте масло, лук, фенхель, перец и слегка раздавленный чеснок. Готовьте на среднем огне 10 минут, часто помешивая.</li><li>Посолите, прикройте крышкой не полностью и тушите ещё 10–15 минут, пока овощи не станут мягкими, но сохранят форму.</li><li>Добавьте томатный соус и каперсы и готовьте без крышки около 10 минут, пока соус не уварится и не обволакивает овощи.</li><li>Добавьте бальзамический уксус, прокипятите минуту, затем готовьте ещё пару минут на слабом огне. Снимите с огня, добавьте базилик и мяту, оставьте на 10 минут, уберите чеснок и сбрызните маслом.</li></ol><p><em>Подайте тёплой или холодной к мясу, рыбе или на хлебе.</em></p>', CURRENT_TIMESTAMP),
  ('ba61ccaf-c8c3-52bc-bdc4-2656b9ed722f', '7a5a9c42-900c-5d9f-a1ec-80898ec695d9', 'en', 'Peperonata: stewed peppers with fennel and tomato', 'Sweet peppers slowly braise with onion, fennel and garlic in olive oil, then finish with tomato sauce, capers and balsamic vinegar.', '<ol><li>In a large heavy skillet combine the oil, onion, fennel, peppers and lightly crushed garlic. Cook over medium heat for 10 minutes, tossing often.</li><li>Season with salt, partly cover and cook another 10–15 minutes until the vegetables are soft but still hold their shape.</li><li>Stir in the tomato sauce and capers and cook uncovered for about 10 minutes until the sauce reduces and coats the vegetables.</li><li>Add the balsamic vinegar, simmer briskly for a minute, then a couple more minutes on lower heat. Remove from the heat, stir in the basil and mint, let stand 10 minutes, discard the garlic and finish with a drizzle of oil.</li></ol><p><em>Serve warm or cold with meat, fish or on bread.</em></p>', CURRENT_TIMESTAMP),
  ('83fc0bb0-d9a1-583e-9403-70cb6d02e684', 'e74ca5f5-5c9b-5bd2-8d00-5ebc818c3428', 'ru', 'Креветки, запечённые в томатном соусе с сумахом', 'Креветки в густом соусе из томатов, перца и чеснока с кориандром, сумахом и кардамоном запекаются и слегка поджариваются под грилем. По желанию с кедровыми орешками и кунжутом.', '<ol><li>Разогрейте духовку до 190 °C. В глубокой огнеупорной сковороде разогрейте масло, 3–4 минуты обжаривайте лук, перец и чеснок.</li><li>Добавьте кориандр, сумах, зиру, хлопья чили и кардамон и прогрейте около минуты до аромата.</li><li>Добавьте томаты с водой, посолите и поперчите. Доведите до кипения и варите на слабом огне 10–15 минут.</li><li>Если сковорода не жаропрочная, переложите соус в форму. Вмешайте креветки, петрушку и, если используете, орешки с кунжутом. Накройте крышкой или фольгой.</li><li>Запекайте 7–9 минут, затем снимите крышку и недолго подержите под грилем, пока креветки не станут плотными и непрозрачными.</li><li>Подавайте с дольками лимона, хлебом или рисом.</li></ol><p><em>Подайте с хрустящим хлебом или рисом, лимон на стол.</em></p>', CURRENT_TIMESTAMP),
  ('85ed8434-54d1-5e11-9d0f-8d3e9d85ff35', 'e74ca5f5-5c9b-5bd2-8d00-5ebc818c3428', 'en', 'Baked shrimp stew with tomato, sumac and pine nuts', 'Shrimp baked in a chunky tomato, pepper and garlic sauce with coriander, sumac and cardamom, then briefly broiled. Optional pine nuts and sesame.', '<ol><li>Preheat the oven to 375 °F (190 °C). In a deep oven-safe skillet heat the oil and cook the onion, bell pepper and garlic for 3–4 minutes.</li><li>Stir in the coriander, sumac, cumin, chilli flakes and cardamom and cook about 1 minute until fragrant.</li><li>Add the tomatoes and water, season with salt and pepper, bring to a boil and simmer for 10–15 minutes.</li><li>If your skillet isn''t oven-safe, move the sauce to a baking dish. Stir in the shrimp, parsley and the pine nuts and sesame if using. Cover with a lid or foil.</li><li>Bake for 7–9 minutes, then uncover and broil briefly until the shrimp are firm and opaque.</li><li>Serve with lemon wedges and bread or rice.</li></ol><p><em>Serve with crusty bread or rice and lemon wedges.</em></p>', CURRENT_TIMESTAMP),
  ('34d67db1-9878-580b-8a32-b3898d051fe6', 'c778bb18-dcbf-52d9-9d33-ee189981a970', 'ru', 'Курица с розмарином и овощами на противне', 'Куриные бёдра и голени с чесноком под кожей, розмарином, кориандром и лимоном запекаются на одном противне с картофелем, морковью и луком.', '<ol><li>Разогрейте духовку до 200 °C, слегка смажьте большой противень маслом.</li><li>Смешайте розмарин, кориандр, перец и мускатный орех; 1 ч. л. смеси отложите для овощей.</li><li>Обсушите курицу, посолите со всех сторон и под кожей. Осторожно приподнимите кожу и распределите под ней чеснок, затем натрите курицу оставшейся смесью специй.</li><li>Выложите курицу на противень, полейте лимонным соком и оливковым маслом и разотрите.</li><li>Смешайте картофель, морковь и лук с отложенной ложкой специй, солью и маслом и разложите вокруг курицы в один слой.</li><li>Запекайте 30–40 минут, пока курица не достигнет 74 °C в самом толстом месте, а картофель и морковь не станут мягкими. Для румяной корочки в конце включите гриль.</li></ol><p><em>Посыпьте рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('8932974e-c715-5eca-ade6-c5ee36ec4507', 'c778bb18-dcbf-52d9-9d33-ee189981a970', 'en', 'Rosemary chicken with potatoes and carrots on a sheet pan', 'Bone-in thighs and drumsticks with garlic under the skin, rosemary, coriander and lemon roast on one pan with potatoes, carrots and onion.', '<ol><li>Preheat the oven to 400 °F (200 °C) and lightly oil a large sheet pan.</li><li>Mix the rosemary, coriander, pepper and nutmeg, setting aside 1 teaspoon for the vegetables.</li><li>Pat the chicken dry and salt it all over and under the skin. Lift the skin gently and spread the garlic beneath it, then rub the chicken with the remaining spice mix.</li><li>Arrange the chicken on the pan and rub with the lemon juice and a generous drizzle of olive oil.</li><li>Toss the potatoes, carrots and onion with the reserved teaspoon of spice mix, a pinch of salt and some oil and arrange around the chicken in a single layer.</li><li>Roast for 30–40 minutes until the chicken reaches 165 °F (74 °C) in the thickest part and the potatoes and carrots are fork-tender. Broil briefly at the end for more colour.</li></ol><p><em>Garnish with chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('06fedbb1-ac27-5d73-90e2-1087a15d8513', '32f78e96-e718-5446-a42e-599d0126b46a', 'ru', 'Крем-суп из спаржи и порея', 'Лёгкий суп-пюре из спаржи и порея на курином бульоне, который подаётся с ложкой сметаны и зелёным луком.', '<ol><li>В большой кастрюле с толстым дном растопите масло на среднем огне. Добавьте тонко нарезанный порей и готовьте 8–10 минут до мягкости.</li><li>Добавьте чеснок на минуту. Спаржу нарежьте кусочками по 5 см и положите в кастрюлю.</li><li>Влейте бульон, доведите до кипения, накройте и варите 20–25 минут до очень мягкой спаржи.</li><li>Снимите с огня и пробейте блендером до гладкости. Посолите и поперчите.</li><li>Разлейте по 5 тарелкам, в каждую положите чайную ложку сметаны и шнитт-лук.</li></ol><p><em>Подайте с ложкой сметаны и нарезанным шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('4b9761c8-978c-5786-a395-489557f2fcbb', '32f78e96-e718-5446-a42e-599d0126b46a', 'en', 'Cream of asparagus and leek soup', 'A light puréed soup of asparagus and leeks in chicken broth, topped with a spoonful of sour cream and chives.', '<ol><li>Melt the butter in a large heavy pot over medium-low heat. Add the thinly sliced leeks and cook for 8–10 minutes until soft.</li><li>Add the garlic for a minute. Cut the asparagus into 2-inch pieces and add to the pot.</li><li>Pour in the broth, bring to a boil, cover and cook 20–25 minutes until the asparagus is very tender.</li><li>Remove from the heat and purée with a blender until smooth. Season with salt and pepper.</li><li>Divide among 5 bowls and top each with a teaspoon of sour cream and chives.</li></ol><p><em>Top with a spoonful of sour cream and chopped chives.</em></p>', CURRENT_TIMESTAMP),
  ('8cf32623-c472-5731-9803-65530fbeb646', '7213da42-9d2a-5555-b0bc-a950c219863d', 'ru', 'Боулы с запечённым бататом, чёрной фасолью и соусом чипотле', 'Батат со специями, фасоль, бурый рис, кале и авокадо, маринованный лук и йогуртовый соус с чипотле. Сытный вегетарианский ужин.', '<ol><li>Нарвите кале, добавьте оливковое масло и щепотку соли и мните руками около минуты, пока не уменьшится в объёме. Оставьте.</li><li>Для маринованного лука нарежьте красный лук полукольцами, залейте уксусом с сахаром и щепоткой соли и оставьте.</li><li>Отварите бурый рис по инструкции на упаковке.</li><li>Разогрейте духовку до 200 °C. Поместите очищенный батат в кастрюлю с водой, доведите до кипения и варите около 8 минут, пока края не станут чуть мягче. Слейте, обсушите и нарежьте кусочками.</li><li>Смешайте батат с двумя ложками масла и смесью соли, порошка чили, копчёной паприки, зиры, кориандра и чесночного порошка. Выложите на противень и запекайте 15–20 минут, один раз перевернув, до румяности.</li><li>Для соуса пробейте йогурт, чипотле в адобо, лаймовый сок, чеснок и щепотку соли до гладкости.</li><li>Разложите по мискам кале, батат, фасоль, рис и авокадо, добавьте маринованный лук, соус и кинзу, подайте с дольками лайма.</li></ol><p><em>Выжмите на боул лайм.</em></p>', CURRENT_TIMESTAMP),
  ('0382de11-beb3-55b5-99a0-cdd4d1a4ed88', '7213da42-9d2a-5555-b0bc-a950c219863d', 'en', 'Roasted sweet potato and black bean bowls with chipotle yogurt sauce', 'Spiced roasted sweet potatoes with black beans, brown rice, kale and avocado, quick-pickled onions and a creamy chipotle yogurt sauce.', '<ol><li>Place the kale with the oil and a pinch of salt in a bowl and massage for about a minute until it shrinks. Set aside.</li><li>For the pickled onions, slice the red onion into half-rings, cover with vinegar, sugar and a pinch of salt and leave to pickle.</li><li>Cook the brown rice following package directions.</li><li>Preheat the oven to 400 °F (200 °C). Boil the peeled sweet potatoes in water for about 8 minutes until the edges just give. Drain, pat dry and cut into bite-size pieces.</li><li>Toss the sweet potatoes with 2 tablespoons of oil and the mix of salt, chilli powder, smoked paprika, cumin, coriander and garlic powder. Spread on a sheet pan and roast 15–20 minutes, flipping once, until browned.</li><li>For the sauce, blend the yogurt, chipotle in adobo, lime juice, garlic and a pinch of salt until smooth.</li><li>Fill bowls with the kale, sweet potatoes, beans, rice and avocado, then garnish with pickled onions, sauce and cilantro and serve with lime wedges.</li></ol><p><em>Squeeze lime over each bowl.</em></p>', CURRENT_TIMESTAMP),
  ('0c08e9aa-eab6-5f96-b48d-791ddffe6a6c', 'd6eabe6e-3480-57ff-a43b-d2d6797b4bda', 'ru', 'Салат из нута с тунцом и каперсами без майонеза', 'Быстрый салат из консервированного нута и тунца с красным луком, каперсами и красным винным уксусом. Сытный и с белком.', '<ol><li>Слейте жидкость с нута и тунца, нут промойте.</li><li>Смешайте нут, тунец, красный лук, каперсы с рассолом и уксус. Отрегулируйте количество уксуса и рассола по вкусу; при желании добавьте нарезанный салат.</li></ol><p><em>Подайте на листьях салата или с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('b804d22a-875f-5065-a3fd-47a097fb463e', 'd6eabe6e-3480-57ff-a43b-d2d6797b4bda', 'en', 'Chickpea and tuna salad with capers (no mayo)', 'A quick salad of canned chickpeas and tuna with red onion, capers and red wine vinegar. Filling and high in protein.', '<ol><li>Drain the chickpeas and tuna and rinse the chickpeas.</li><li>Combine the chickpeas, tuna, red onion, capers with their brine and the vinegar. Adjust the vinegar and brine to taste and add chopped lettuce if you like.</li></ol><p><em>Serve on lettuce leaves or with bread.</em></p>', CURRENT_TIMESTAMP),
  ('8c8a7b30-9371-59e0-80c0-9761919d10dc', '7500cec9-da75-5817-824a-7f6602aa4802', 'ru', 'Жареный рис с эдамаме и яйцом', 'Лёгкая домашняя версия жареного риса с бурым рисом, овощами, эдамаме и яичной стружкой, заправленная соевым соусом.', '<ol><li>Взбейте яйцо и белки, посолите и поперчите. Приготовьте омлет-болтунью на слегка смазанной горячей сковороде или воке и отложите.</li><li>Хорошо разогрейте вок, добавьте масло и 30–60 секунд обжаривайте лук, белую часть зелёного лука, морковь и чеснок, не давая им подгореть.</li><li>Добавьте рис и прогрейте несколько минут, хорошо перемешивая.</li><li>Верните яйцо, добавьте соевый соус, зелёную часть лука и эдамаме. Перемешивайте ещё 3–4 минуты.</li></ol><p><em>Хорошо подходит как гарнир к курице или рыбе.</em></p>', CURRENT_TIMESTAMP),
  ('ccab5ded-fd4c-5c52-a07d-485a11ccbc31', '7500cec9-da75-5817-824a-7f6602aa4802', 'en', 'Edamame fried rice with egg', 'A lighter homemade fried rice with brown rice, vegetables, edamame and scrambled egg, seasoned with soy sauce.', '<ol><li>Whisk the egg and whites with salt and pepper. Scramble them in a hot, lightly oiled wok or pan and set aside.</li><li>Heat the wok until very hot, add the oil and stir-fry the onion, scallion whites, carrots and garlic for 30–60 seconds without burning.</li><li>Add the rice and stir for a few minutes to heat through.</li><li>Return the egg and add the soy sauce, scallion greens and edamame. Stir for 3–4 minutes more.</li></ol><p><em>Great as a side with chicken or fish.</em></p>', CURRENT_TIMESTAMP),
  ('e2ec3dcc-bd06-51ef-89dd-7dd6011cd9bf', '3f6fff11-9f32-5178-87b8-e19d149454ca', 'ru', 'Паста лингвине с белой фасолью, шпинатом и чесночным соусом скампи', 'Вегетарианский вариант скампи: цельнозерновая паста с белой фасолью, шпинатом, черри и соусом из вина, чеснока и лимона.', '<ol><li>Вскипятите воду с большим количеством соли. Отварите пасту на минуту меньше, чем указано на упаковке, отлейте полстакана воды и слейте остальное.</li><li>В той же кастрюле прогрейте масло, примерно минуту обжарьте чеснок с хлопьями чили и чёрным перцем.</li><li>Влейте вино, добавьте соль и уварите до небольшого загустения. Добавьте половинки помидоров на 1–2 минуты, затем порциями шпинат, помешивая, пока он не осядет.</li><li>Верните пасту с отложенной водой и прогревайте на среднем огне 1–2 минуты, пока соус не загустеет.</li><li>Добавьте фасоль и лимонный сок, прогрейте минуту, затем снимите с огня, вмешайте масло и подавайте с петрушкой и пармезаном.</li></ol><p><em>Подайте сразу, посыпав петрушкой и пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('b12a3977-ef85-5897-8248-2bd8dc659805', '3f6fff11-9f32-5178-87b8-e19d149454ca', 'en', 'White bean scampi with linguine and spinach', 'A vegetarian take on scampi: whole-wheat linguine with white beans, spinach and cherry tomatoes in a garlic, white wine and lemon sauce.', '<ol><li>Bring generously salted water to a boil. Cook the pasta one minute less than the package says, reserve ½ cup of the water and drain.</li><li>In the same pot warm the oil and cook the garlic, chilli flakes and black pepper for about a minute until fragrant.</li><li>Pour in the wine, add the salt and reduce slightly. Add the halved tomatoes for 1–2 minutes, then the spinach a handful at a time until wilted.</li><li>Add the pasta with the reserved water and cook over medium-high heat for 1–2 minutes until the sauce thickens.</li><li>Add the beans and lemon juice and warm for a minute, then remove from the heat, stir in the butter and serve with parsley and Parmesan.</li></ol><p><em>Serve right away, topped with parsley and Parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('0d658db0-c0c6-5690-b4f6-b0fbb9963cb9', 'e29fdb8a-20f3-532f-9368-7e436a928c18', 'ru', 'Бургеры из куриного фарша со шпинатом', 'Сочные котлеты из куриного фарша с рубленым шпинатом и специями, поданные в булочке с любимыми добавками или в листьях салата.', '<ol><li>В большой миске руками смешайте фарш, мелко нарубленный шпинат, чесночный и луковый порошок, тимьян, паприку, соль и перец. Сформируйте 5 плоских котлет.</li><li>Разогрейте сковороду-гриль или обычную сковороду на средне-слабом огне, смажьте маслом и выложите котлеты.</li><li>Жарьте по 4–5 минут с каждой стороны до золотистой корочки и полной готовности.</li><li>Положите котлету на нижнюю половинку булочки, добавьте соусы и овощи по вкусу и накройте второй половинкой.</li></ol><p><em>Подайте с помидором, листьями салата и авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('fc260765-d3a1-5bf2-9beb-b0b204f1e6dd', 'e29fdb8a-20f3-532f-9368-7e436a928c18', 'en', 'Ground chicken and spinach burgers', 'Juicy ground chicken patties with chopped spinach and spices, served on a bun with your favourite toppings or in lettuce wraps.', '<ol><li>In a large bowl mix the chicken, finely chopped spinach, garlic and onion powder, thyme, paprika, salt and pepper by hand. Shape into 5 flat patties.</li><li>Heat a grill pan or skillet over medium-low heat, lightly oil it and add the patties.</li><li>Cook 4–5 minutes per side until golden and cooked through.</li><li>Place each patty on a bottom bun, add your toppings and cover with the top bun.</li></ol><p><em>Top with tomato, lettuce and avocado.</em></p>', CURRENT_TIMESTAMP),
  ('f99a634f-9a66-54d3-b4ea-8e76d985ca90', 'a05855e9-45c3-54fe-bad3-f34402165734', 'ru', 'Томатный суп с тортеллини, шпинатом и базиликом', 'Густой томатный суп на курином бульоне с тортеллини с сыром, молодым шпинатом и базиликом. Готовится за полчаса.', '<ol><li>В большой кастрюле с толстым дном прогрейте масло на среднем огне. Добавьте лук, чеснок и итальянские травы и пассеруйте 2–3 минуты до мягкости лука.</li><li>Добавьте томатную пасту и помешивайте около 2 минут, пока она не потемнеет. Влейте бульон, раздробленные томаты и томатный соус, добавьте коричневый сахар, соль и перец.</li><li>Накройте крышкой и доведите до кипения. Положите тортеллини и варите по инструкции на упаковке.</li><li>Смешайте молоко с крахмалом в миске вилкой и влейте в суп: он быстро загустеет.</li><li>Когда тортеллини будут готовы, убавьте огонь до слабого и добавьте шпинат и базилик тонкими лентами.</li></ol><p><em>Подавайте горячим с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('0aab8702-3d5e-5b41-8fba-fd597cadcc38', 'a05855e9-45c3-54fe-bad3-f34402165734', 'en', 'Tomato tortellini soup with spinach and basil', 'A rich tomato soup in chicken broth with cheese tortellini, baby spinach and basil. Ready in half an hour.', '<ol><li>In a large Dutch oven over medium heat, warm the oil. Add the onion, garlic and Italian seasoning and sauté 2–3 minutes until the onion softens.</li><li>Stir in the tomato paste and cook about 2 minutes until it darkens. Add the stock, crushed tomatoes and tomato sauce, then the brown sugar, salt and pepper.</li><li>Cover and bring to a boil. Add the tortellini and cook according to the package directions.</li><li>Whisk the milk and cornstarch in a small bowl with a fork and stir into the soup; it will thicken quickly.</li><li>When the tortellini are cooked, reduce the heat to a simmer and stir in the spinach and basil ribbons.</li></ol><p><em>Serve hot with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('bb53b081-6f50-5fda-83b2-58873bd6c7c1', 'a5f9ba8a-d36b-5e32-b9a5-47cbf6d8d790', 'ru', 'Картофельный рёшти на топлёном масле', 'Одна большая хрустящая картофельная лепёшка из тёртого картофеля, жареная на топлёном масле до золотистой корочки. Внутри мягкая, снаружи хрустящая.', '<ol><li>Очистите картофель и натрите на крупной тёрке, лучше длинной соломкой. Отожмите лишнюю влагу горстями, чтобы рёшти получился хрустящим.</li><li>Переложите в миску, добавьте растопленное масло (15 г), соль и перец, перемешайте. Если картофель потемнеет, это нормально, при жарке цвет вернётся.</li><li>Растопите половину оставшегося топлёного масла в сковороде 26 см с антипригарным покрытием на средне-слабом огне. Выложите картофель, не утрамбовывая, выровняйте края и слегка прижмите.</li><li>Жарьте 12 минут до золотистой хрустящей корочки снизу, проверяя лопаткой. Если за 8 минут цвета нет, увеличьте огонь.</li><li>Накройте сковороду доской с ручкой и быстро переверните. Растопите остальное топлёное масло, верните рёшти в сковороду и жарьте ещё 12 минут, пока нож не будет входить в середину без сопротивления.</li><li>Переложите на доску, разрежьте на 4–6 клиньев и сразу подавайте.</li></ol><p><em>Нарежьте клиньями и подайте сразу, например с яйцом или сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('ebb954e0-0ab3-5794-b53e-e5b426280d13', 'a5f9ba8a-d36b-5e32-b9a5-47cbf6d8d790', 'en', 'Crispy potato rosti with ghee', 'One large crispy potato cake from grated potatoes, pan-fried in clarified butter until deep golden. Soft inside and crunchy outside.', '<ol><li>Peel and coarsely grate the potatoes, ideally into long strands. Squeeze out excess liquid in handfuls so the rosti turns out crisp.</li><li>Place in a bowl, add the melted ghee (15 g), salt and pepper and toss. If the potato turns brownish, that''s fine; it lightens as it cooks.</li><li>Melt half the remaining ghee in a 10-inch non-stick skillet over medium-low heat. Add the potato without packing it down, tidy the edges and pat lightly flat.</li><li>Cook 12 minutes until the underside is deep golden and crisp, checking with a spatula. If it hasn''t coloured by 8 minutes, raise the heat.</li><li>Cover the pan with a board that has a handle and flip quickly. Melt the remaining ghee, slide the rosti back and cook another 12 minutes until a knife slips into the centre with no resistance.</li><li>Slide onto a board, cut into 4–6 wedges and serve at once.</li></ol><p><em>Cut into wedges and serve right away, for example with an egg or sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('95f6699c-2257-5a90-849d-4106ca81732d', '52f8b2ab-69ff-5cef-aca3-8d2031bd6ac3', 'ru', 'Плов в стиле мусаки с говяжьим фаршем, баклажанами и нутом', 'Фарш с чесноком и орегано, кубики баклажана, нут и рис варятся в одной кастрюле в томатном бульоне. Вкус мусаки без трудоёмкой сборки.', '<ol><li>Нарежьте баклажан кубиками не больше 1,5 см, иначе он не пропечётся.</li><li>В большой кастрюле на сильном огне прогрейте масло, 2 минуты обжарьте лук с чесноком. Добавьте фарш и жарьте, разбивая, пока не исчезнет розовый цвет. Всыпьте 1/2 ч. л. соли и орегано, через минуту добавьте томатную пасту и прогрейте ещё минуту.</li><li>Добавьте баклажан и перемешайте с мясным соком. Добавьте рис и перемешайте.</li><li>Добавьте нут, томаты, бульон, оставшуюся соль и перец. Доведите до слабого кипения по всей поверхности, накройте крышкой и уменьшите огонь до средне-слабого.</li><li>Готовьте 20 минут, не открывая крышку и не помешивая. Снимите с огня и оставьте на 10 минут под крышкой.</li><li>Перемешайте рис, разложите по тарелкам, сбрызните маслом и посыпьте петрушкой.</li></ol><p><em>Сбрызните оливковым маслом и добавьте ложку греческого йогурта.</em></p>', CURRENT_TIMESTAMP),
  ('202a7cef-66ef-5b7d-b885-6022acf18339', '52f8b2ab-69ff-5cef-aca3-8d2031bd6ac3', 'en', 'Moussaka-style beef, rice and chickpea one-pot pilaf', 'Beef mince with garlic and oregano, diced eggplant, chickpeas and rice cook in one pot in a tomato broth. Moussaka flavours without the layering.', '<ol><li>Dice the eggplant into cubes no larger than ½ inch (1.5 cm), otherwise it may not cook through.</li><li>In a large pot over high heat warm the oil and cook the onion and garlic for 2 minutes. Add the beef and cook, breaking it up, until no red remains. Stir in ½ teaspoon of the salt and the oregano, then after a minute add the tomato paste and cook another minute.</li><li>Stir in the eggplant to coat it in the beef juices, then add the rice and stir.</li><li>Add the chickpeas, crushed tomatoes, stock, remaining salt and pepper. Bring to a simmer with gentle bubbles across the surface, cover and turn the heat to medium-low.</li><li>Cook 20 minutes without peeking or stirring. Remove from the heat and rest covered for 10 minutes.</li><li>Toss the rice, divide into bowls, drizzle with oil and sprinkle with parsley.</li></ol><p><em>Drizzle with olive oil and add a spoonful of Greek yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('a980ba9a-2569-5980-9514-ac7b79bc87f1', 'e2642f9a-f1df-5552-96e0-45d5d0a08b3f', 'ru', 'Пенне аррабьята: острая паста с томатами', 'Паста в остром томатном соусе с чесноком, свежим перцем чили и хлопьями чили. Простое блюдо, которое готовится за полчаса.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло, 10 секунд пассеруйте чеснок. Добавьте нарезанный свежий чили и хлопья чили и готовьте минуту, пока чеснок слегка не золотится.</li><li>Добавьте томаты, соль и перец. Промойте банки небольшим количеством воды и влейте её в кастрюлю. Доведите до кипения на сильном огне, затем уменьшите до среднего и варите 15 минут. Если соус кислый, добавьте сахар.</li><li>Тем временем отварите пасту в подсоленной воде по инструкции на упаковке. Перед сливанием отлейте 1 стакан воды из-под пасты.</li><li>Добавьте пасту и 1/2 стакана воды в соус и хорошо перемешайте на огне, пока паста не покроется соусом. При необходимости разведите ещё водой.</li><li>Разложите по тарелкам, посыпьте пармезаном и петрушкой.</li></ol><p><em>Посыпьте тёртым пармезаном и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('feab5229-1b83-5ec6-9b75-4f7e1ca0d3e6', 'e2642f9a-f1df-5552-96e0-45d5d0a08b3f', 'en', 'Penne all''arrabbiata (spicy tomato pasta)', 'Pasta in a spicy tomato sauce with garlic, fresh chilli and chilli flakes. A simple dish ready in about half an hour.', '<ol><li>Heat the oil in a large pot over medium heat and stir the garlic for 10 seconds. Add the chopped fresh chilli and the flakes and cook for a minute until the garlic is light golden.</li><li>Add the tomatoes, salt and pepper, rinse the cans with a little water and pour that in too. Bring to a simmer over high heat, then lower to medium and simmer for 15 minutes. If the sauce tastes sour add the sugar.</li><li>Meanwhile cook the pasta in salted water as directed on the package. Scoop out 1 cup of pasta water just before draining.</li><li>Add the pasta and ½ cup of pasta water to the sauce and toss over the heat until coated, adding more water if needed.</li><li>Divide into bowls and sprinkle with Parmesan and parsley.</li></ol><p><em>Top with grated Parmesan and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('bc6fe8bc-69f9-5ae0-900d-f21470c8a29d', '9114307d-6a0e-5a00-8622-57901ecdaceb', 'ru', 'Китайский омлет фу-юн с курицей и ростками фасоли', 'Небольшие пышные омлеты с ростками бобов, зелёным луком и куриным фаршем под лёгким соево-устричным соусом. Хорошо с рисом.', '<ol><li>Для соуса смешайте крахмал с соевым соусом, затем добавьте устричный соус, кунжутное масло, воду и белый перец. Прогрейте в ковше на среднем огне, помешивая, 1 минуту до консистенции жидкого сиропа. Отставьте.</li><li>Смешайте фарш с соевым соусом, устричным соусом, сахаром и каплей кунжутного масла.</li><li>Взбейте яйца, добавьте ростки, нарезанный зелёный лук, фарш, соль и белый перец, перемешайте.</li><li>В антипригарной сковороде на среднем огне разогрейте немного масла с каплей кунжутного. 10 секунд обжарьте чеснок и сдвиньте в центр. Влейте четверть смеси, подберите края лопаткой, чтобы получился круг.</li><li>Жарьте около 1,5 минут до золотистого низа, переверните и жарьте ещё минуту. Так же приготовьте остальные 3 омлета.</li><li>Переложите омлеты на тарелки, полейте соусом и посыпьте кунжутом и зелёным луком.</li></ol><p><em>Подайте с рисом и овощами на пару; соус можно удвоить.</em></p>', CURRENT_TIMESTAMP),
  ('c79142ad-2e92-515f-a85e-1df5d4025c88', '9114307d-6a0e-5a00-8622-57901ecdaceb', 'en', 'Egg foo young with chicken and bean sprouts', 'Small fluffy omelettes with bean sprouts, spring onion and ground chicken under a light soy-oyster sauce. Good with rice.', '<ol><li>For the sauce mix the cornstarch and soy sauce, then add the oyster sauce, sesame oil, water and white pepper. Heat in a saucepan over medium heat, stirring, for 1 minute until it thickens to a thin syrup. Set aside.</li><li>Mix the ground chicken with the soy sauce, oyster sauce, sugar and a dash of sesame oil.</li><li>Whisk the eggs, then stir in the bean sprouts, green onions, filling, salt and white pepper.</li><li>Heat a little oil and a drizzle of sesame oil in a non-stick pan over medium heat, sauté a little garlic for 10 seconds and push it to the centre. Ladle in a quarter of the batter and nudge the edges into a round.</li><li>Cook about 1½ minutes until the underside is golden, flip and cook another minute. Repeat to make 4 omelettes.</li><li>Plate the omelettes, pour over the sauce and sprinkle with sesame seeds and green onion.</li></ol><p><em>Serve with rice and steamed vegetables; double the sauce if you like.</em></p>', CURRENT_TIMESTAMP),
  ('19ad000b-d762-5335-ac88-10b4bdf210c2', '3ccd355a-95a4-56ce-a17c-6d07f527527a', 'ru', 'Французский луковый суп с сырными гренками', 'Лук медленно карамелизуется на сливочном масле до глубокого золотого цвета, затем варится в говяжьем бульоне. Подаётся с гренками, запечёнными с грюйером.', '<ol><li>Растопите масло в тяжёлой кастрюле на среднем огне. Когда оно запенится, добавьте тонко нарезанный лук и перемешайте.</li><li>Уменьшите огонь до средне-слабого и готовьте 30 минут, помешивая каждые несколько минут, пока лук не станет мягким и полупрозрачным.</li><li>Посолите, увеличьте огонь до среднего или чуть выше и готовьте ещё 20–30 минут, чаще помешивая, до глубокого золотистого цвета и сладости.</li><li>Всыпьте муку и готовьте минуту. Влейте бульон, добавьте тимьян и лавровый лист. Накройте крышкой и варите на слабом огне 30 минут.</li><li>Для гренок разогрейте гриль духовки на сильный нагрев, подсушите ломтики хлеба с двух сторон, посыпьте сыром и запекайте до расплавления и золотистых пятен.</li><li>Посолите и поперчите суп по вкусу, разлейте по мискам и положите сверху 1–2 гренки.</li></ol><p><em>Накройте суп гренками перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('c462c7c5-cb75-5353-8e5a-efe4144bdd0f', '3ccd355a-95a4-56ce-a17c-6d07f527527a', 'en', 'French onion soup with Gruyère toast', 'Onions slowly caramelise in butter to a deep golden colour, then simmer in beef broth. Served with cheesy Gruyère toasts.', '<ol><li>Melt the butter in a heavy casserole over medium heat. When it foams, add the sliced onions and toss to coat.</li><li>Lower the heat to medium-low and cook 30 minutes, stirring every few minutes, until the onions are soft and translucent.</li><li>Add salt, raise the heat to medium or medium-high and cook another 20–30 minutes, stirring more often, until deep golden and sweet.</li><li>Sprinkle over the flour and cook 1 minute. Add the broth, thyme and bay leaves, cover and simmer gently for 30 minutes.</li><li>For the toasts, heat the oven grill to high, toast the bread slices on both sides, top with cheese and grill until melted with brown spots.</li><li>Season the soup to taste, ladle into bowls and top with 1–2 cheese toasts.</li></ol><p><em>Top each bowl with the cheese toast just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('3ba5f36c-bfe1-5309-b6a4-8c5b1ebdc16c', '4f03668d-d08d-5cf4-8d44-42cc0444d158', 'ru', 'Суп из запечённых помидоров с копчёной паприкой', 'Помидоры и чеснок запекаются до обугленных краёв, затем пюрируются с овощным бульоном и луком. Лёгкий копчёный вкус и сливочная нота.', '<ol><li>Разогрейте духовку до 220 °C. Разрежьте помидоры пополам, удалите плодоножку, выложите срезом вверх на противень вместе с неочищенным чесноком.</li><li>Сбрызните маслом, посыпьте паприкой, солью и перцем, оботрите срезы помидоров в масле. Запекайте 40–45 минут, пока края не обуглятся.</li><li>В кастрюле на среднем огне разогрейте масло и 3 минуты обжарьте лук с чесноком до прозрачности.</li><li>Добавьте запечённые помидоры с соком, выдавите в кастрюлю мякоть запечённого чеснока и влейте бульон. Пробейте блендером до гладкости.</li><li>Доведите до кипения и варите на среднем огне 10 минут, при кислом вкусе добавьте сахар. Влейте сливки, разлейте по тарелкам и украсьте базиликом.</li></ol><p><em>Хорошо с гренками с сыром, сверху сливки и базилик.</em></p>', CURRENT_TIMESTAMP),
  ('a0495492-990a-5615-8552-967b417e0259', '4f03668d-d08d-5cf4-8d44-42cc0444d158', 'en', 'Smoky roasted tomato soup with garlic', 'Tomatoes and garlic roast until charred, then blend with vegetable stock and onion. A light smoky flavour with a creamy finish.', '<ol><li>Preheat the oven to 425 °F (220 °C). Halve the tomatoes, cut out the cores and place cut side up on a tray with the unpeeled garlic.</li><li>Drizzle with oil and sprinkle with paprika, salt and pepper, pressing the cut sides into the oil. Roast 40–45 minutes until the edges char.</li><li>In a pot over medium-high heat warm the oil and cook the onion and garlic 3 minutes until the onion is translucent.</li><li>Add the roasted tomatoes and their juices, squeeze in the roasted garlic and pour in the stock. Purée with a blender until smooth.</li><li>Bring to a simmer and cook over medium heat for 10 minutes, adding sugar if it tastes sharp. Stir in the cream, ladle into bowls and garnish with basil.</li></ol><p><em>Great with grilled cheese for dipping, topped with cream and basil.</em></p>', CURRENT_TIMESTAMP),
  ('b31ee66a-9aec-5db8-bd5a-0cfd6947c1d4', '1e155f98-4d43-568a-a332-8a789c520906', 'ru', 'Тёплый немецкий картофельный салат с беконом и укропом', 'Ломтики отварного картофеля заправлены горячей заправкой из бекона, лука, яблочного уксуса и сахара. Сверху зелёный лук и укроп.', '<ol><li>Положите мелкий картофель в кастрюлю с холодной водой и солью, доведите до кипения и варите на слабом огне около 10 минут, пока он не будет почти готов, но чуть плотным в середине.</li><li>Слейте воду, немного остудите и нарежьте кружками по 7 мм.</li><li>Выложите бекон в холодную сковороду и разогревайте, пока не растопится жир, затем на среднем огне до золотистого цвета, около 3 минут.</li><li>Добавьте красный лук на 3 минуты. Влейте уксус, всыпьте сахар, доведите до кипения, счищая прилипшие кусочки. Добавьте масло и кипятите 2 минуты.</li><li>Добавьте картофель и аккуратно перемешайте в течение минуты, чтобы он впитал заправку. Попробуйте на соль.</li><li>Выкладывайте слоями, посыпая каждый слой зелёным луком и укропом.</li></ol><p><em>Подавайте тёплым или при комнатной температуре.</em></p>', CURRENT_TIMESTAMP),
  ('f19b5c93-fa87-55f8-8c37-fa8e9f23dc70', '1e155f98-4d43-568a-a332-8a789c520906', 'en', 'Warm German potato salad with bacon and dill', 'Sliced boiled potatoes tossed in a hot bacon, onion and apple cider vinegar dressing, topped with spring onion and dill.', '<ol><li>Put the baby potatoes in a pot of cold salted water, bring to a boil and simmer about 10 minutes until just cooked but slightly firm in the centre.</li><li>Drain, cool slightly and slice into ¼-inch rounds.</li><li>Put the bacon in a cold skillet and heat until the fat renders, then cook over medium-high until golden, about 3 minutes.</li><li>Add the red onion for 3 minutes. Pour in the vinegar and sugar, bring to a simmer scraping up the browned bits, then add the oil and simmer 2 minutes.</li><li>Add the potatoes and toss gently for about a minute so they absorb the dressing. Taste for salt.</li><li>Layer the potatoes on a platter, sprinkling each layer with green onion and dill.</li></ol><p><em>Serve warm or at room temperature.</em></p>', CURRENT_TIMESTAMP),
  ('eae12eed-d045-555a-9086-983d1460ebd5', 'e4f514a0-bd11-57bb-8461-e4a21ee6bbb6', 'ru', 'Курица по-французски: фрикасе с грибами и сливочным соусом', 'Бёдра и голени тушатся с шампиньонами, луком, чесноком и тимьяном в белом вине и курином бульоне, затем соус заправляется сливками.', '<ol><li>Обсушите курицу бумажным полотенцем, посолите и поперчите.</li><li>Растопите масло в большой сковороде или кастрюле с крышкой на сильном огне. Обжарьте бёдра кожей вниз 4–5 минут до золотистого цвета, затем минуту с другой стороны, переложите на тарелку. Так же обжарьте голени со всех сторон.</li><li>Обжарьте грибы, лук, лавровый лист и тимьян 5 минут, добавьте чеснок на 30 секунд, затем муку на минуту.</li><li>Влейте вино и бульон, добавьте соль и перец, соскребая со дна прилипшие кусочки. Верните курицу кожей вверх.</li><li>Доведите до кипения, убавьте огонь, накройте и тушите 10 минут, затем откройте и тушите ещё 20 минут, пока мясо не будет готово (около 75 °C).</li><li>Выньте курицу, влейте сливки и дождитесь кипения, посолите по вкусу. Верните курицу, посыпьте петрушкой и подавайте.</li></ol><p><em>Подайте с картофельным пюре, рисом или короткой пастой.</em></p>', CURRENT_TIMESTAMP),
  ('968f5e4a-5b0d-5ed4-88b5-ebdbbcfb0c06', 'e4f514a0-bd11-57bb-8461-e4a21ee6bbb6', 'en', 'Chicken fricassée with mushroom cream sauce', 'Thighs and drumsticks braise with mushrooms, onion, garlic and thyme in white wine and chicken stock, then the sauce is finished with cream.', '<ol><li>Pat the chicken dry and season with salt and pepper.</li><li>Melt the butter in a large lidded skillet or pot over medium-high heat. Brown the thighs skin side down 4–5 minutes, then 1 minute on the other side, and set aside. Brown the drumsticks on all sides the same way.</li><li>Cook the mushrooms, onion, bay leaf and thyme for 5 minutes, add the garlic for 30 seconds, then the flour for 1 minute.</li><li>Pour in the wine and stock with the salt and pepper, scraping up the browned bits, and return the chicken skin side up.</li><li>Bring to a simmer, lower the heat, cover and simmer 10 minutes, then uncover and simmer another 20 minutes until the chicken is cooked (about 167 °F / 75 °C).</li><li>Remove the chicken, stir in the cream and bring to a simmer, adjusting the salt. Return the chicken, sprinkle with parsley and serve.</li></ol><p><em>Serve over mashed potatoes, rice or short pasta.</em></p>', CURRENT_TIMESTAMP),
  ('6ef61369-5fe6-5627-a02c-6758f4b9af04', '94fcb399-5c71-55ec-9418-49cdab8756e9', 'ru', 'Запеканка из пасты с тунцом, томатами и моцареллой', 'Паста с томатным соусом и консервированным тунцом, запечённая под сыром до золотистой корочки. Простой ужин из продуктов из кладовки.', '<ol><li>Разогрейте духовку до 180 °C. Отварите пасту на минуту меньше, чем указано на упаковке, слейте и промойте холодной водой.</li><li>В жаропрочной сковороде на среднем огне 3 минуты обжарьте чеснок с луком до золотистого цвета.</li><li>Добавьте томаты, томатную пасту, воду, травы, соль и перец, доведите до кипения и варите 5 минут, пока соус не загустеет.</li><li>Выключите огонь, добавьте пасту, затем осторожно вмешайте тунца, не разбивая его на мелкие кусочки.</li><li>Сбрызните маслом, посыпьте сыром и запекайте 20 минут до золотистой корочки. Дайте постоять 3 минуты.</li></ol><p><em>Дайте постоять 3 минуты перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('10d6adcd-703a-5aa9-8c46-23f4ac8e65d5', '94fcb399-5c71-55ec-9418-49cdab8756e9', 'en', 'Tuna pasta bake with tomato and mozzarella', 'Pasta in a tomato sauce with canned tuna, baked under cheese until golden. An easy dinner from pantry staples.', '<ol><li>Preheat the oven to 350 °F (180 °C). Cook the pasta 1 minute less than the package says, drain and rinse under cold water.</li><li>In an oven-safe skillet over medium-high heat cook the garlic and onion for 3 minutes until golden.</li><li>Add the tomatoes, tomato paste, water, herbs, salt and pepper, bring to a boil and simmer briskly for 5 minutes until thickened.</li><li>Turn off the heat, stir in the pasta, then gently fold in the tuna without breaking it up too much.</li><li>Drizzle with oil, top with cheese and bake 20 minutes until golden and crusty. Stand for 3 minutes.</li></ol><p><em>Let it stand for 3 minutes before serving.</em></p>', CURRENT_TIMESTAMP),
  ('844831d9-1bf0-5a40-9739-52939254d1ca', '747ed5c7-a027-580b-b81c-aada301451c5', 'ru', 'Армянский суп с мясными шариками и булгуром (сулу кюфта)', 'Крошечные фрикадельки из говядины с булгуром варятся в лимонно-томатном бульоне и заканчиваются сушёной мятой. Сытный домашний суп.', '<ol><li>Поставьте рядом с миской для фарша небольшую миску с водой для смачивания рук.</li><li>Смешайте руками булгур, говяжий фарш, лук, соль, перец и паприку, добавляя воду по горсти, пока масса не станет плотной и цельной.</li><li>Смачивая руки, скатайте маленькие шарики диаметром 2–2,5 см (получится около 130 штук) и выложите на поднос.</li><li>В кастрюле растопите масло на средне-сильном огне и обжарьте лук до мягкости. Влейте воду, томатный соус, бульон, добавьте соль, перец и паприку, доведите до кипения на сильном огне.</li><li>Влейте лимонный сок и осторожно опускайте шарики порциями, помешивая, чтобы не слиплись. При желании добавьте нут или рис.</li><li>Когда суп снова закипит, убавьте огонь и варите 10–15 минут до готовности шариков. Попробуйте на соль и положите сушёную мяту перед снятием с огня. Подавайте сразу.</li></ol><p><em>Мяту добавляйте перед самым снятием с огня. По желанию положите в суп нут или рис.</em></p>', CURRENT_TIMESTAMP),
  ('ab8849d6-586a-56a4-a8ab-e94aafab0ca3', '747ed5c7-a027-580b-b81c-aada301451c5', 'en', 'Armenian meatball soup with bulgur (sulu kofte)', 'Tiny beef-and-bulgur meatballs poached in a lemony tomato broth and finished with dried mint. A hearty family soup.', '<ol><li>Set a small bowl of water next to the mixing bowl for wetting your hands.</li><li>Mix the bulgur, beef, onion, salt, pepper and paprika by hand, adding water a handful at a time until cohesive and firm.</li><li>With wet hands, roll small balls about 2–2.5 cm across (about 130 of them) and place on a tray.</li><li>In a pot, melt the butter over medium-high heat and soften the onion. Add the water, tomato sauce, broth, salt, pepper and paprika and bring to a boil over high heat.</li><li>Add the lemon juice and carefully drop in the meatballs a few at a time, stirring so they don''t stick. Add chickpeas or rice if you like.</li><li>When it returns to a boil, reduce the heat and simmer 10–15 minutes until the meatballs are cooked through. Adjust the salt, add the dried mint just before removing from the heat and serve immediately.</li></ol><p><em>Add the mint right before removing from the heat. Chickpeas or rice are a good optional addition.</em></p>', CURRENT_TIMESTAMP),
  ('5a4f51f7-9d16-5822-af4a-3f8d87977b7f', 'ffb92ed9-e304-5287-a80d-3c0703b4d6e8', 'ru', 'Чахохбили из курицы с томатами и кинзой', 'Грузинское тушёное блюдо: курица в густом томатном соусе с большим количеством лука, чесноком и кинзой, слегка пикантное.', '<ol><li>Нарежьте курицу кусками по 5 см, посолите и поперчите. Разогрейте половину масла в казане или большой кастрюле на среднем и сильном огне и обжарьте курицу порциями до румяности, не доводя до полной готовности. Отложите на тарелку.</li><li>Влейте остальное масло, добавьте лук, посолите. Убавьте огонь до среднего, накройте и тушите около 5 минут, иногда помешивая, чтобы лук стал мягким.</li><li>Снимите крышку и помешивайте ещё около 10 минут, счищая подгоревшие кусочки со дна, пока лук не станет мягким.</li><li>Добавьте чеснок, томатную пасту, аджику и измельчённый перец алеппо, перемешайте и готовьте около минуты.</li><li>Влейте томаты и доведите до слабого кипения. Посолите, верните курицу с накопившимся соком, убавьте огонь, накройте и тушите около 10 минут (бёдра дольше), пока курица не будет готова (74 °C внутри).</li><li>Добавьте кинзу, при необходимости досолите и подавайте.</li></ol><p><em>Подавайте с белым рисом, хлебом или лепёшкой, чтобы собирать соус.</em></p>', CURRENT_TIMESTAMP),
  ('0612912d-00a8-5e6a-b4a1-cd2f236b9c11', 'ffb92ed9-e304-5287-a80d-3c0703b4d6e8', 'en', 'Chakhokhbili: Georgian chicken stew with tomatoes and cilantro', 'A slightly spicy Georgian stew: chicken in a thick tomato sauce with lots of onion, garlic and cilantro.', '<ol><li>Cut the chicken into 5 cm pieces and season with salt and pepper. Heat half the oil in a Dutch oven over medium-high heat and brown the chicken in two batches without cooking through. Set aside.</li><li>Add the remaining oil and the onions and season with salt. Lower to medium, cover and cook about 5 minutes, stirring occasionally, until softened.</li><li>Uncover and stir about 10 more minutes, scraping up the browned bits, until the onions are tender.</li><li>Add the garlic, tomato paste, adjika and crushed Aleppo pepper, stir well and cook about 1 minute.</li><li>Add the tomatoes and bring to a gentle boil. Season, return the chicken with its juices, lower the heat, cover and simmer about 10 minutes (longer for thighs) until cooked through (74°C/165°F inside).</li><li>Stir in the cilantro, adjust the seasoning and serve.</li></ol><p><em>Serve with white rice, crusty bread or flatbread to soak up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('c759603d-213e-5397-8068-77580221c533', '7c6f7392-0f1d-5d57-82e2-a0b06a07ee9d', 'ru', 'Армянский салат из печёных овощей', 'Баклажаны и болгарский перец запекают до чёрной кожицы, очищают, нарезают и смешивают с помидорами, луком и петрушкой. Подаётся к мясу на гриле и в мезе.', '<ol><li>Запекайте баклажаны и перцы на гриле, периодически поворачивая и прокалывая баклажаны, чтобы выходил пар, пока кожица не почернеет, а овощи не станут мягкими.</li><li>Горячие овощи положите в плотный пакет, завяжите и оставьте на несколько минут, чтобы они пропарились. Так кожица снимется легче.</li><li>Очистите овощи, удалите плодоножки и семена перцев и нарежьте всё кубиками 0,6–1,2 см. Переложите в большую миску.</li><li>Добавьте помидоры, лук, петрушку, лимонный сок, масло, соль, паприку, чёрный и красный перец и хорошо перемешайте. Подавайте комнатной температуры или холодным.</li></ol><p><em>Подавайте холодным или комнатной температуры, например к шашлыку. Если нет гриля, овощи можно запечь в духовке.</em></p>', CURRENT_TIMESTAMP),
  ('fbba7f69-da56-5088-a73f-1de202c787ec', '7c6f7392-0f1d-5d57-82e2-a0b06a07ee9d', 'en', 'Armenian grilled vegetable salad', 'Eggplants and bell peppers are charred, peeled and chopped, then mixed with tomatoes, onion and parsley. A summer side for grilled meats and meze.', '<ol><li>Grill the eggplants and peppers, turning occasionally and piercing the eggplants so steam escapes, until the skins are blackened and the vegetables are tender.</li><li>Put the hot vegetables in a large plastic bag, seal and leave for a few minutes to steam. This helps the skins peel off easily.</li><li>Peel the vegetables, remove stems and pepper seeds and chop everything into 0.6–1.2 cm dice. Transfer to a large bowl.</li><li>Add the tomatoes, onion, parsley, lemon juice, oil, salt, paprika, black pepper and cayenne and mix well. Serve at room temperature or cold.</li></ol><p><em>Serve cold or at room temperature with grilled meat. In bad weather, roast the vegetables in the oven.</em></p>', CURRENT_TIMESTAMP),
  ('a4d0f218-3ce1-5d56-985c-17faebd4c1cf', 'b82061f7-a57e-5cbf-b87c-f09ecaf2913c', 'ru', 'Булгур с томатами по-армянски', 'Рассыпчатый гарнир, похожий на армянский плов: крупный булгур, потушенный с луком и тёртыми свежими помидорами на сливочном масле.', '<ol><li>Растопите масло в большой кастрюле на средне-сильном огне и обжаривайте лук около 5 минут до мягкости.</li><li>Добавьте тёртые помидоры с соком, доведите до кипения, убавьте огонь и готовьте около 5 минут, помешивая.</li><li>Влейте кипяток, всыпьте булгур, перемешайте, посолите и поперчите.</li><li>Когда смесь закипит, убавьте огонь до минимума, накройте и готовьте 15–18 минут (более крупному булгуру нужно около 25 минут), пока вся жидкость не впитается.</li><li>Снимите с огня и дайте постоять несколько минут перед подачей.</li></ol><p><em>Хорошо к мясу, курице и овощам на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('66f5f2a8-e819-5cec-84f9-ab8db3b3f7b3', 'b82061f7-a57e-5cbf-b87c-f09ecaf2913c', 'en', 'Armenian tomato bulgur pilaf', 'A fluffy side similar to Armenian rice pilaf, with coarse bulgur cooked in butter with onion and grated fresh tomatoes.', '<ol><li>Melt the butter in a large pot over medium-high heat and cook the onion about 5 minutes until soft.</li><li>Add the grated tomatoes with their juice, bring to a simmer, lower the heat and cook about 5 minutes, stirring.</li><li>Pour in the boiling water, add the bulgur, stir and season with salt and pepper.</li><li>When it starts to bubble, lower the heat to minimum, cover and cook 15–18 minutes (coarser bulgur takes about 25 minutes) until all the liquid is absorbed.</li><li>Remove from the heat and let rest a few minutes before serving.</li></ol><p><em>Good with meat, chicken and grilled vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('4db56bae-15ec-5477-a8a4-00a9772a045d', '7938fc41-96a0-58b7-a985-2579b6f8e4b3', 'ru', 'Армянский чечевичный суп с макаронами, лимоном и зирой', 'Простой сытный суп из бурой чечевицы с маленькими макаронами, чесноком, томатной пастой и щедрой порцией зиры. Лимонный сок придаёт свежесть.', '<ol><li>Отварите макароны в подсоленной воде почти до состояния al dente, слейте, промойте холодной водой и отставьте.</li><li>Тем временем разогрейте в кастрюле масло и пассеруйте лук до мягкости.</li><li>Добавьте чечевицу, бульон и воду, накройте и доведите до кипения. Убавьте огонь и варите под крышкой около 30 минут, иногда помешивая, пока чечевица не станет мягкой.</li><li>Добавьте макароны, томатную пасту, чеснок, лимонный сок и зиру. Посолите и добавьте щепотку острого перца. Подавайте сразу.</li></ol><p><em>Для вегетарианской версии замените куриный бульон водой.</em></p>', CURRENT_TIMESTAMP),
  ('01a28a00-cd57-51e8-b95e-f4038817326a', '7938fc41-96a0-58b7-a985-2579b6f8e4b3', 'en', 'Armenian lentil soup with macaroni, lemon and cumin', 'A simple, hearty brown lentil soup with small macaroni, garlic, tomato paste and plenty of cumin, brightened with lemon juice.', '<ol><li>Boil the pasta in salted water until almost al dente, drain, rinse under cold water and set aside.</li><li>Meanwhile, heat the oil in a pot and cook the onions until softened.</li><li>Add the lentils, broth and water, cover and bring to a boil. Lower the heat and simmer covered about 30 minutes, stirring now and then, until the lentils are tender.</li><li>Stir in the pasta, tomato paste, garlic, lemon juice and cumin. Season with salt and a pinch of hot pepper. Serve immediately.</li></ol><p><em>For a vegetarian version, replace the chicken broth with water.</em></p>', CURRENT_TIMESTAMP),
  ('6de4a1ad-944f-5afe-9c72-aebede6d5849', '96f312b5-a036-5d9d-93a8-a4e3b20e1ba1', 'ru', 'Суп из красной чечевицы с картофелем и рисом', 'Густой ближневосточный суп из красной чечевицы, риса и картофеля с чесноком, зирой и паприкой. Готовится меньше получаса.', '<ol><li>Растопите масло в большой кастрюле на среднем огне и обжаривайте лук 4–5 минут до мягкости. Влейте бульон и воду, доведите до кипения.</li><li>Добавьте чечевицу, рис, картофель, чеснок, зиру и паприку, посолите и поперчите.</li><li>Когда суп снова закипит, убавьте огонь, накройте и варите 15–20 минут, иногда помешивая, пока чечевица, рис и картофель не станут мягкими.</li><li>Проверьте приправы и подавайте.</li></ol><p><em>Для вегетарианской версии замените куриный бульон овощным или водой.</em></p>', CURRENT_TIMESTAMP),
  ('ca8a35eb-5b61-5ee2-82f0-c9da349e150d', '96f312b5-a036-5d9d-93a8-a4e3b20e1ba1', 'en', 'Red lentil, potato and rice soup', 'A thick Middle Eastern soup of red lentils, rice and potato with garlic, cumin and paprika. Ready in under 30 minutes.', '<ol><li>Melt the butter in a large pot over medium heat and cook the onion 4–5 minutes until soft. Add the broth and water and bring to a boil.</li><li>Add the lentils, rice, potato, garlic, cumin and paprika and season with salt and pepper.</li><li>When it returns to a boil, lower the heat, cover and simmer 15–20 minutes, stirring occasionally, until the lentils, rice and potato are tender.</li><li>Adjust the seasoning and serve.</li></ol><p><em>For a vegetarian version swap the chicken broth for vegetable broth or water.</em></p>', CURRENT_TIMESTAMP),
  ('d78bb80e-1285-5e62-ae28-f53a9ddeff8f', '1b28518f-d2a6-5ed3-bb78-7641cf17fd1c', 'ru', 'Греческая тушёная стручковая фасоль с томатами (фасолакия)', 'Стручковая фасоль, медленно тушёная с луком, чесноком и свежими томатами в оливковом масле. Подаётся как постное основное блюдо или как гарнир.', '<ol><li>Разогрейте масло в большой сковороде или кастрюле с крышкой на среднем огне. Обжарьте лук до мягкости, около 5 минут. Добавьте чеснок на 15–30 секунд, затем тёртые помидоры, соль и перец.</li><li>Когда помидоры закипят, добавьте стручковую фасоль, перемешайте, накройте крышкой, убавьте огонь и тушите около 30 минут, иногда помешивая, пока фасоль не станет мягкой, а жидкость почти не выпарится.</li><li>Если сковорода сухая, подлейте воды. Если жидкости слишком много, прогрейте без крышки, чтобы выпарить.</li><li>Добавьте петрушку, попробуйте и при необходимости досолите.</li></ol><p><em>Хорошо с хлебом и фетой. Подавайте тёплой или комнатной температуры.</em></p>', CURRENT_TIMESTAMP),
  ('06233355-b3fc-5247-b1e8-333f645c8c77', '1b28518f-d2a6-5ed3-bb78-7641cf17fd1c', 'en', 'Fasolakia: Greek stewed green beans with tomatoes', 'Green beans slowly stewed with onion, garlic and fresh tomatoes in olive oil. Served as a vegan main course or as a side dish.', '<ol><li>Heat the olive oil in a large lidded skillet or Dutch oven over medium heat. Sauté the onion until tender, about 5 minutes. Add the garlic for 15–30 seconds, then the grated tomatoes, salt and pepper.</li><li>When the tomatoes bubble, add the green beans and stir, cover, lower the heat and simmer about 30 minutes, stirring occasionally, until the beans are tender and most of the liquid has evaporated.</li><li>If the pan looks dry, add a little water. If there is too much liquid at the end, cook briefly uncovered to reduce.</li><li>Stir in the parsley, taste and adjust the seasoning.</li></ol><p><em>Good with bread and feta. Serve warm or at room temperature.</em></p>', CURRENT_TIMESTAMP),
  ('922c0593-d798-58ea-b54c-dee02d032b45', '41b1e976-2b9e-585c-a124-ec85fb5d1d86', 'ru', 'Греческий рис со шпинатом (спанакоризо)', 'Рис с большим количеством шпината, свежей зелени, лимона, лука, чеснока и оливкового масла. Подаётся как вегетарианское основное блюдо или как гарнир.', '<ol><li>Промойте рис в холодной воде до прозрачной воды, откиньте и отставьте.</li><li>Разогрейте масло в большой кастрюле на средне-сильном огне, пассеруйте лук и зелёный лук 4–5 минут. Убавьте огонь, добавьте чеснок, лимонный сок и томатную пасту и перемешайте.</li><li>Добавляйте шпинат порциями, помешивая, пока он не завянет полностью.</li><li>Добавьте рис и бульон (или воду), посолите и поперчите. Доведите до кипения, попробуйте жидкость на соль, накройте и убавьте огонь до минимума.</li><li>Готовьте без помешивания около 20 минут, пока рис не станет мягким, а жидкость почти не впитается. Снимите с огня и оставьте под крышкой на 5–10 минут.</li><li>Вмешайте петрушку. Подавайте с фетой и зеленью.</li></ol><p><em>Посыпьте крошкой феты и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('fa33f46e-aac7-597d-8262-eba8096f6b10', '41b1e976-2b9e-585c-a124-ec85fb5d1d86', 'en', 'Spanakorizo: Greek spinach rice', 'Rice with lots of spinach, fresh herbs, lemon, onion, garlic and olive oil. Served as a vegetarian main or a healthy side.', '<ol><li>Rinse the rice in cold water until the water runs clear, drain and set aside.</li><li>Heat the oil in a large pot over medium-high heat and sauté the onion and scallions 4–5 minutes. Reduce the heat, add the garlic, lemon juice and tomato paste and stir to combine.</li><li>Add the spinach in batches, stirring until fully wilted.</li><li>Add the drained rice and broth (or water), season with salt and pepper. Bring to a boil, taste the liquid for salt, then cover and lower the heat.</li><li>Cook undisturbed about 20 minutes until the rice is tender and most liquid absorbed. Remove from the heat and rest covered 5–10 minutes.</li><li>Stir in the parsley. Serve topped with feta and herbs.</li></ol><p><em>Top with crumbled feta and fresh herbs.</em></p>', CURRENT_TIMESTAMP),
  ('3ae428c8-c5c5-5d2e-8632-7d8ee8f2e5a1', '6745c35e-9308-5660-9b3f-3ec717b2c1cf', 'ru', 'Мексиканские боулы на завтрак с чёрной фасолью, яйцами и пико-де-гальо', 'Омлет-болтунья с пюре из чёрной фасоли с кумином, свежим пико-де-гальо и авокадо. Сытно и подходит и для ужина.', '<ol><li>Для пико-де-гальо смешайте помидоры, лук, кинзу, лаймовый сок и щепотку соли. Оставьте пропитаться.</li><li>В кастрюле на среднем огне разогрейте масло, 5–8 минут пассеруйте лук до прозрачности. Добавьте зиру и чеснок на 30 секунд.</li><li>Добавьте фасоль и воду, накройте и готовьте 5 минут. Уменьшите огонь, снимите крышку и разомните не менее половины фасоли вилкой. Готовьте ещё 3 минуты, затем добавьте соль, перец и лаймовый сок.</li><li>Взбейте яйца со сливками, солью, перцем и хлопьями чили. Разогрейте масло на сковороде 25 см и влейте яйца.</li><li>Помешивайте, пока яйца не схватятся примерно на 90 %, снимите с огня и вмешайте сыр, если используете.</li><li>Разложите фасоль и яйца по 4 мискам, добавьте пико-де-гальо без сока, ломтики авокадо и сальсу.</li></ol><p><em>Подайте с сальсой и жареным картофелем.</em></p>', CURRENT_TIMESTAMP),
  ('1f0ba6a4-a9e5-5300-beb8-d8f3a60741f7', '6745c35e-9308-5660-9b3f-3ec717b2c1cf', 'en', 'Tex-Mex breakfast bowls with black beans, eggs and pico de gallo', 'Scrambled eggs with cumin-spiced mashed black beans, fresh pico de gallo and avocado. Hearty and good for dinner too.', '<ol><li>For the pico de gallo, combine the tomatoes, onion, cilantro, lime juice and a pinch of salt. Set aside to marinate.</li><li>Warm the oil in a saucepan over medium heat and cook the onion for 5–8 minutes until translucent. Add the cumin and garlic for 30 seconds.</li><li>Add the beans and water, cover and cook 5 minutes. Reduce the heat, uncover and mash at least half the beans. Cook 3 more minutes, then stir in salt, pepper and lime juice.</li><li>Whisk the eggs with the cream, salt, pepper and chilli flakes. Warm the oil in a 10-inch skillet over medium heat and pour in the eggs.</li><li>Stir until the eggs are about 90 percent set, remove from the heat and fold in the cheese if using.</li><li>Divide the beans and eggs among 4 bowls and top with the drained pico de gallo, avocado slices and salsa.</li></ol><p><em>Serve with salsa and roasted potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('3ee5f705-6057-5437-ba63-3c73f25cddb1', '8a758000-18e3-5d23-9497-353369aeed2d', 'ru', 'Тако на завтрак с омлетом-болтуньей и овощами', 'Мягкие лепёшки с нежной яичной болтуньей и обжаренными с пряностями овощами: капустой, перцем и морковью. Хорошо использовать остатки овощей.', '<ol><li>Прогрейте лепёшки на сухой сковороде по 20–30 секунд с каждой стороны (или в микроволновке 15–20 секунд), сложите стопкой и накройте полотенцем.</li><li>Взбейте яйца вилкой со сметаной, острым соусом и половиной соли.</li><li>В большой сковороде растопите 1 ст. л. масла, добавьте овощи, оставшуюся соль, порошок чили и зиру. Готовьте около 5 минут до мягкости, уменьшив огонь, и переложите в миску.</li><li>Растопите остальное масло на слабом огне, влейте яйца и мягко перемешивайте 3–5 минут, пока не получатся влажные комочки.</li><li>Снимите с огня, вмешайте сыр и зелёный лук. Выложите яйца в лепёшки, добавьте овощи и любимые добавки.</li></ol><p><em>Добавьте сметану, кинзу, авокадо или сальсу.</em></p>', CURRENT_TIMESTAMP),
  ('402d2862-5bd5-5039-8b40-b1f01ad23845', '8a758000-18e3-5d23-9497-353369aeed2d', 'en', 'Egg and veggie breakfast tacos with flour tortillas', 'Soft tortillas filled with creamy scrambled eggs and spiced sautéed vegetables such as cabbage, pepper and carrot. A good way to use leftover vegetables.', '<ol><li>Warm the tortillas in a dry skillet 20–30 seconds per side (or microwave 15–20 seconds), stack them and wrap in a towel.</li><li>Whisk the eggs with the sour cream, hot sauce and half the salt.</li><li>In a large skillet melt 1 tablespoon of the butter, add the vegetables, remaining salt, chilli powder and cumin and cook about 5 minutes until tender, lowering the heat after a few minutes. Transfer to a bowl.</li><li>Melt the remaining butter over medium-low heat, pour in the eggs and stir gently for 3–5 minutes until clumpy but still slightly wet.</li><li>Remove from the heat and stir in the cheese and green onion. Spoon the eggs into the tortillas, add the vegetables and your toppings.</li></ol><p><em>Top with sour cream, cilantro, avocado or salsa.</em></p>', CURRENT_TIMESTAMP),
  ('4cd3e318-6e72-5c6d-a600-30fa84354fc3', '37eb34ae-9681-536f-9c78-5344c49b679d', 'ru', 'Вегетарианские буррито на завтрак с яйцами, фасолью и хэш-браунами', 'Буррито с яичной болтуньей, фасолью, сыром, зеленью и хрустящими картофельными хэш-браунами. Можно заморозить на потом.', '<ol><li>Для хэш-браунов натрите картофель на крупной тёрке, промойте в сите до прозрачной воды, отожмите досуха в полотенце и смешайте с солью, чесночным и луковым порошком.</li><li>Разогрейте масло в большой сковороде, выложите картофель ровным слоем и жарьте, прижимая и переворачивая через каждые 2 минуты, 8–12 минут до золотистой хрустящей корочки. Переложите на бумажные полотенца.</li><li>Взбейте яйца вилкой, добавьте фасоль, соль и острый соус.</li><li>Растопите масло на средней сковороде, влейте яйца и помешивайте 2–4 минуты до схватывания. Вмешайте сыр и переложите в миску, добавьте кинзу и зелёный лук (немного оставьте для подачи).</li><li>Чтобы лепёшки не ломались, быстро подержите каждую под водой и прогрейте в микроволновке 10–20 секунд или на сковороде.</li><li>На каждую лепёшку выложите около 1/3 стакана хэш-браунов, ложку сальсы и 1/3 стакана яиц с фасолью. Заверните: сначала низ, затем бока, и скрутите.</li><li>Подавайте сразу с тёплой сальсой, авокадо, кинзой и луком. Для заморозки остудите буррито, заверните в плёнку по одному и уберите в морозилку.</li></ol><p><em>Подайте с тёплой сальсой и авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('751a1ea1-6425-5bd0-ab86-4cb0027ad403', '37eb34ae-9681-536f-9c78-5344c49b679d', 'en', 'Vegetarian breakfast burritos with eggs, beans and hash browns', 'Burritos filled with scrambled eggs, beans, cheese, herbs and crisp potato hash browns. Easy to freeze for later.', '<ol><li>For the hash browns, grate the potatoes on a large-holed grater, rinse in a sieve until the water runs clear, squeeze dry in a towel and toss with salt, garlic powder and onion powder.</li><li>Warm the oil in a large skillet, spread the potatoes in an even layer and cook, pressing and stirring every 2 minutes, 8–12 minutes until golden and crisp. Drain on paper towels.</li><li>Whisk the eggs, then stir in the beans, salt and hot sauce.</li><li>Melt the butter in a medium skillet, pour in the eggs and stir 2–4 minutes until just set. Stir in the cheese, transfer to a bowl and mix in the cilantro and green onion (reserve a little for garnish).</li><li>To keep the tortillas pliable, quickly run each under water and warm for 10–20 seconds in the microwave or a skillet.</li><li>On each tortilla spoon about ⅓ cup hash browns, a spoonful of salsa and ⅓ cup of the egg and bean mixture. Fold the bottom over, then the sides, and roll up.</li><li>Serve right away with warm salsa, avocado, cilantro and green onion. To freeze, cool the burritos, wrap each in plastic and freeze.</li></ol><p><em>Serve with warm salsa and avocado.</em></p>', CURRENT_TIMESTAMP),
  ('637a7832-2e7b-55b5-8d88-845d0ce833dc', 'ebf6e992-7826-5d9c-9f65-7a564be264d2', 'ru', 'Табуле с петрушкой, булгуром и мятой', 'Ливанский салат, в котором главное — много мелко рубленой петрушки. Булгур, огурец, помидор, мята и лимонно-масляная заправка с чесноком.', '<ol><li>Приготовьте или замочите булгур до мягкости по инструкции на упаковке, слейте воду и остудите.</li><li>Смешайте огурец и помидор с половиной соли и оставьте минимум на 10 минут.</li><li>Срежьте толстые стебли петрушки и мелко порубите остальное (удобно в кухонном комбайне). Сложите в большую миску.</li><li>К петрушке добавьте остывший булгур, мяту и зелёный лук. Слейте сок с огурцов и помидоров и добавьте овощи в миску.</li><li>Взбейте масло, 3 ст. л. лимонного сока, чеснок и оставшуюся соль, заправьте салат и отрегулируйте вкус. Выдержите 15 минут перед подачей.</li></ol><p><em>Дайте салату постоять 15 минут. Подайте с питой или к мясу на гриле.</em></p>', CURRENT_TIMESTAMP),
  ('e5b8ac7b-91ae-542a-8f01-466ef302957e', 'ebf6e992-7826-5d9c-9f65-7a564be264d2', 'en', 'Tabbouleh with parsley, bulgur and mint', 'A Lebanese salad built around lots of finely chopped parsley, with bulgur, cucumber, tomato, mint and a lemony garlic olive oil dressing.', '<ol><li>Cook or soak the bulgur until tender following the package directions, drain and cool.</li><li>Toss the cucumber and tomato with half the salt and leave for at least 10 minutes.</li><li>Cut off the thick parsley stems and finely chop the rest (easiest in a food processor). Transfer to a large bowl.</li><li>Add the cooled bulgur, mint and green onion to the parsley. Drain the liquid from the cucumber and tomato and add the vegetables to the bowl.</li><li>Whisk the oil, 3 tablespoons lemon juice, garlic and remaining salt, dress the salad and adjust to taste. Rest 15 minutes before serving.</li></ol><p><em>Let it rest 15 minutes. Serve with pita or grilled meat.</em></p>', CURRENT_TIMESTAMP),
  ('baf28304-9494-50b8-9ebd-b24ceaec4ac1', 'ce2cf085-0bb0-5974-a904-2bd2df481d7f', 'ru', 'Овощная паэлья с артишоками, нутом и бурым рисом', 'Рис с копчёной паприкой и нутом запекается в духовке, сверху запечённые артишоки, перец и оливки, горошек и лимон.', '<ol><li>Разогрейте духовку до 175 °C, расположите решётки в верхней и нижней трети. Подготовьте жаропрочную кастрюлю с крышкой диаметром около 28 см.</li><li>Нагрейте 2 ст. л. масла, обжарьте лук с щепоткой соли около 5 минут. Добавьте чеснок и паприку на 30 секунд, затем томаты на 2 минуты до сгущения.</li><li>Всыпьте рис и перемешайте минуту. Добавьте нут, бульон, шафран и 1 ч. л. соли, доведите до кипения, накройте и поставьте в нижнюю часть духовки на 50–55 минут, пока не впитается жидкость.</li><li>Пока рис печётся, смешайте на противне с пергаментом артишоки, перец, оливки, 1 ст. л. масла, соль и перец и запекайте на верхней решётке 40–45 минут до мягкости и румяных краёв.</li><li>Добавьте к овощам петрушку и лимонный сок, посолите по вкусу. Для хрустящей корочки (сокарат) прогрейте открытую кастрюлю с рисом на плите 5 минут.</li><li>Разложите овощи и горошек поверх риса, накройте и оставьте на 5 минут. Подавайте с лимоном и петрушкой.</li></ol><p><em>Подайте с дольками лимона и рубленой петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('ff2bf3de-c4ae-5460-ab8d-35e25bc9c215', 'ce2cf085-0bb0-5974-a904-2bd2df481d7f', 'en', 'Vegetable paella with artichokes, chickpeas and brown rice', 'Smoky paprika rice with chickpeas bakes in the oven, topped with roasted artichokes, peppers and olives, peas and lemon.', '<ol><li>Preheat the oven to 350 °F (175 °C) with racks in the upper and lower thirds. Choose an oven-safe lidded Dutch oven or skillet about 11–12 inches wide.</li><li>Heat 2 tablespoons of oil and cook the onion with a pinch of salt about 5 minutes. Add the garlic and paprika for 30 seconds, then the tomatoes for 2 minutes until thickened.</li><li>Stir in the rice for a minute. Add the chickpeas, broth, saffron and 1 teaspoon salt, bring to a boil, cover and bake on the lower rack for 50–55 minutes until the liquid is absorbed.</li><li>While the rice bakes, toss the artichokes, peppers, olives, 1 tablespoon of oil, salt and pepper on a parchment-lined sheet and roast on the upper rack 40–45 minutes until tender and browned.</li><li>Toss the roasted vegetables with parsley and lemon juice and adjust the seasoning. For an optional crispy bottom (socarrat), cook the uncovered rice on the stovetop for 5 minutes.</li><li>Scatter the vegetables and peas over the rice, cover and let sit 5 minutes. Serve with lemon wedges and parsley.</li></ol><p><em>Serve with lemon wedges and chopped parsley.</em></p>', CURRENT_TIMESTAMP),
  ('ae6c6917-b7e0-5318-bc24-fed3c537d349', '916fc92f-d46d-5d4a-afe8-fbe5c26bb10d', 'ru', 'Перцы, фаршированные чечевицей и кускусом с фетой и базиликом', 'Запечённые половинки сладкого перца с начинкой из чечевицы, кускуса, лука, помидора, феты и базилика. Лёгкое вегетарианское блюдо.', '<ol><li>Разогрейте духовку до 200 °C. Разрежьте перцы вдоль, удалите семена, смажьте маслом, посолите и поперчите и выложите срезом вверх на противень с пергаментом. Запекайте 20–25 минут до мягкости.</li><li>Сварите чечевицу с лавровым листом в бульоне или воде 23–25 минут до мягкости, слейте лишнюю жидкость, уберите лавровый лист.</li><li>В кастрюле обжарьте лук с щепоткой соли 10–12 минут до золотистого цвета, добавьте чеснок и помидор на 30 секунд. Снимите с огня, всыпьте кускус, влейте бульон, накройте на 5 минут и разрыхлите вилкой.</li><li>Соедините чечевицу и кускус, добавьте фету, масло, лимонный сок, базилик, соль и хлопья чили, перемешайте.</li><li>Наполните половинки перцев начинкой и посыпьте базиликом.</li></ol><p><em>Подайте с салатом.</em></p>', CURRENT_TIMESTAMP),
  ('c1d6496b-ef28-5105-87fd-a6d4b101207e', '916fc92f-d46d-5d4a-afe8-fbe5c26bb10d', 'en', 'Lentil and couscous stuffed peppers with feta and basil', 'Roasted bell pepper halves filled with lentils, couscous, onion, tomato, feta and basil. A light vegetarian dinner.', '<ol><li>Preheat the oven to 400 °F (200 °C). Halve the peppers, remove seeds and membranes, rub with 2 tablespoons oil, season, and place cut side up on a parchment-lined sheet. Bake 20–25 minutes until tender and blistered.</li><li>Simmer the lentils with the bay leaf in broth or water for 23–25 minutes until tender, drain off excess liquid and discard the bay leaf.</li><li>In a pot cook the onion with a pinch of salt 10–12 minutes until golden, add the garlic and tomato for 30 seconds. Remove from the heat, add the couscous and broth, cover for 5 minutes and fluff with a fork.</li><li>Combine the lentils and couscous with the feta, oil, lemon juice, basil, salt and chilli flakes and stir.</li><li>Fill the pepper halves with the mixture and top with basil.</li></ol><p><em>Serve with a side salad.</em></p>', CURRENT_TIMESTAMP),
  ('f447090d-2915-5da2-831f-bdd9bb75e454', '776a2046-a7b6-59b9-ab41-1be5744253ea', 'ru', 'Зелёная паста с кале, горошком, лимоном и рикоттой', 'Паста в ярком зелёном соусе из кале с чесноком, лимоном и оливковым маслом, с зелёным горошком, пармезаном и ложками рикотты.', '<ol><li>Вскипятите кастрюлю хорошо подсоленной воды. Срежьте листья кале со стеблей, толстые основания выбросьте, а стебли нарежьте полосками по 6 мм и положите в сито.</li><li>Опустите сито со стеблями в кипяток на 3 минуты, затем добавьте листья кале, снова накройте ситом и варите 5 минут. Воду не сливайте.</li><li>Тем временем прогрейте масло с чесноком на среднем огне до шипения, затем на слабом около 5 минут до мягкости и лёгкой золотистости. Перелейте в блендер.</li><li>Добавьте в блендер стебли и листья кале с небольшим количеством воды, цедру и 1 ст. л. лимонного сока, соль, хлопья чили и перец. Взбейте до гладкости.</li><li>Отварите пасту в той же воде до аль денте, за 1–3 минуты до готовности положите горошек в сито. Отлейте полстакана воды из-под пасты и слейте остальное.</li><li>Верните пасту в кастрюлю, влейте зелёный соус, добавьте горошек и около 3/4 пармезана и немного воды из-под пасты. Осторожно перемешайте.</li><li>Разложите по тарелкам, добавьте остатки пармезана, ложки рикотты, цедру и каплю масла.</li></ol><p><em>Подавайте сразу, пока цвет ярко-зелёный.</em></p>', CURRENT_TIMESTAMP),
  ('a228a080-3644-5d28-a5bb-4918c284dec6', '776a2046-a7b6-59b9-ab41-1be5744253ea', 'en', 'Lemony green kale pasta with peas and ricotta', 'Pasta in a bright green sauce of kale, garlic, lemon and olive oil, with peas, Parmesan and dollops of ricotta.', '<ol><li>Bring a large pot of heavily salted water to a boil. Strip the kale leaves from the stems, discard the tough bases and slice the stems ¼-inch wide into a sieve.</li><li>Lower the sieve with the stems into the boiling water for 3 minutes, then add the leaves, set the sieve back on top and cook 5 minutes. Don''t drain the water.</li><li>Meanwhile warm the oil with the garlic over medium heat until it sizzles, then gently over low about 5 minutes until soft and lightly golden. Pour into a blender.</li><li>Add the kale stems and leaves with a little of their water, most of the lemon zest, 1 tablespoon of juice, salt, chilli flakes and pepper. Blend until completely smooth.</li><li>Cook the pasta in the same water until al dente, adding the peas in the sieve for the last 1–3 minutes. Reserve ½ cup of pasta water and drain.</li><li>Return the pasta to the pot with the green sauce, peas, about ¾ of the Parmesan and a splash of pasta water and stir gently.</li><li>Divide into bowls and top with the remaining Parmesan, dollops of ricotta, zest and a drizzle of oil.</li></ol><p><em>Serve immediately for the best colour and texture.</em></p>', CURRENT_TIMESTAMP),
  ('331f244a-3418-562c-9116-49f0e742ab1f', 'c95c201a-d133-5df4-b9f1-aba4f9d79a36', 'ru', 'Завтрак из киноа с корицей, пеканом и вяленой вишней', 'Готовая киноа прогревается с поджаренным пеканом, кокосовым маслом, корицей и кленовым сиропом. По вкусу напоминает тосты с корицей.', '<ol><li>Прогрейте рубленый пекан в небольшой кастрюле на среднем огне, встряхивая, 4–6 минут до аромата.</li><li>Добавьте кокосовое масло, корицу и соль и помешивайте около 15 секунд. Всыпьте готовую киноа и прогрейте минуту.</li><li>Снимите с огня, добавьте кленовый сироп, переложите в миску и посыпьте вяленой вишней и корицей. Подавайте сразу.</li></ol><p><em>Подайте с молоком или йогуртом и семенами.</em></p>', CURRENT_TIMESTAMP),
  ('dac183d5-6bba-5d39-a5d2-bdb55ab0b367', 'c95c201a-d133-5df4-b9f1-aba4f9d79a36', 'en', 'Cinnamon toast breakfast quinoa with pecans and dried cherries', 'Pre-cooked quinoa warmed with toasted pecans, coconut oil, cinnamon and maple syrup. Tastes like cinnamon toast.', '<ol><li>Warm the chopped pecans in a small saucepan over medium heat, shaking often, for 4–6 minutes until fragrant and toasty.</li><li>Add the coconut oil, cinnamon and salt and stir for about 15 seconds. Add the cooked quinoa and warm through for about a minute.</li><li>Remove from the heat, stir in the maple syrup, transfer to a bowl and top with the dried cherries and a sprinkle of cinnamon. Serve promptly.</li></ol><p><em>Serve with milk or yogurt and seeds.</em></p>', CURRENT_TIMESTAMP),
  ('ebdcd77b-de87-5016-be55-6b497579f630', '4778cd8c-68e4-5ed1-9754-2bd2d4c1ca81', 'ru', 'Цельнозерновые панкейки на кислом молоке с кленовым сиропом', 'Пышные панкейки из цельнозерновой муки с корицей, подслащённые кленовым сиропом. Молоко с уксусом заменяет пахту.', '<ol><li>Смешайте молоко с уксусом и оставьте минимум на 5 минут, пока оно слегка не свернётся.</li><li>В миске смешайте муку, разрыхлитель, соду, соль и корицу.</li><li>В кислое молоко добавьте яйцо, растопленное масло, кленовый сироп и ваниль и взбейте. Влейте в сухую смесь и перемешайте до однородности (небольшие комочки допустимы). Дайте тесту постоять 5 минут.</li><li>Разогрейте тяжёлую сковороду на средне-слабом огне, при необходимости слегка смажьте маслом. Выкладывайте тесто порциями по 1/3 стакана.</li><li>Жарьте 2–3 минуты до пузырьков на поверхности, переверните и жарьте ещё 1–2 минуты до золотистого цвета. Остальное тесто приготовьте так же.</li></ol><p><em>Подайте с бананом и миндальной пастой или ягодами.</em></p>', CURRENT_TIMESTAMP),
  ('0dc35dac-c6be-5696-a253-63e20d7b3d94', '4778cd8c-68e4-5ed1-9754-2bd2d4c1ca81', 'en', 'Whole wheat buttermilk pancakes with maple syrup', 'Fluffy whole wheat pancakes with a hint of cinnamon, sweetened with maple syrup. Milk with vinegar stands in for buttermilk.', '<ol><li>Mix the milk and vinegar and leave at least 5 minutes until lightly curdled.</li><li>In a bowl whisk the flour, baking powder, baking soda, salt and cinnamon.</li><li>Add the egg, melted butter, maple syrup and vanilla to the soured milk and whisk. Pour into the dry ingredients and stir just until combined (small lumps are fine). Let the batter rest 5 minutes.</li><li>Heat a heavy skillet or non-stick griddle over medium-low heat, lightly oiling if needed, and scoop batter by ⅓ cup.</li><li>Cook 2–3 minutes until bubbles form, flip and cook 1–2 minutes more until golden. Repeat with the rest of the batter.</li></ol><p><em>Serve with sliced banana and almond butter or berries.</em></p>', CURRENT_TIMESTAMP),
  ('060c7f28-cfc9-58ec-8d27-70587af8a89c', '3d49f429-486d-54c1-93f6-c776be8152e9', 'ru', 'Армянская запеканка из яичной лапши с брынзой', 'Самая простая запечённая «макарони с сыром»: яичная лапша, фета, яйца, молоко и петрушка под хрустящей панировкой. Хорошо замораживается и подходит для гостей.', '<ol><li>Разогрейте духовку до 180 °C. Смажьте форму 23x33 см маслом и присыпьте дно третью–половиной сухарей.</li><li>Отварите лапшу в подсоленной кипящей воде 6–8 минут до al dente и слейте.</li><li>Верните лапшу в кастрюлю с огня, добавьте масло и размешайте до растворения. Добавьте фету, взбитые яйца, петрушку, молоко, перец и немного соли (сыр уже солёный).</li><li>Переложите в форму и разровняйте ложкой. Оставшиеся сухари смешайте с оливковым маслом и щедро посыпьте сверху.</li><li>Выпекайте 40–50 минут, пока запеканка не схватится, а сухари не станут светло-золотистыми. Включите гриль на пару минут, чтобы корочка потемнела.</li><li>Дайте слегка остыть и нарежьте на 12 больших или 24 маленьких квадрата.</li></ol><p><em>Дайте слегка остыть и нарежьте квадратами. Подавайте с овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('d66bd6f4-d011-544b-b835-05a5621c83f2', '3d49f429-486d-54c1-93f6-c776be8152e9', 'en', 'Armenian baked egg noodle casserole with feta', 'The easiest baked mac and cheese: egg noodles, feta, eggs, milk and parsley under a crisp breadcrumb crust. Freezes well and is great for entertaining.', '<ol><li>Preheat the oven to 180°C (360°F). Grease a 23x33 cm baking dish with butter and dust the bottom with ⅓–½ cup of the breadcrumbs.</li><li>Cook the noodles in salted boiling water 6–8 minutes until al dente and drain.</li><li>Return the noodles to the pot off the heat, add the butter and stir until melted. Mix in the feta, beaten eggs, parsley, milk, pepper and a little salt (the cheese is already salty).</li><li>Pour into the dish and level with a spoon. Toss the remaining breadcrumbs with the olive oil and spread generously over the top.</li><li>Bake 40–50 minutes until set and the crumbs are light golden, then broil a couple of minutes for a darker crust.</li><li>Let cool slightly and cut into 12 large or 24 small squares.</li></ol><p><em>Cool slightly and cut into squares. Serve with a vegetable salad.</em></p>', CURRENT_TIMESTAMP),
  ('56dc97d0-ced3-5f2b-816e-c992181abb4e', 'd00d3400-1612-5d5c-909f-059fbadaa210', 'ru', 'Курица по-бирмански с карри, помидорами и луком', 'Быстрое жаркое: куриная грудка с порошком карри, много лука и чеснока, свежие помидоры в конце. Овощи остаются слегка хрустящими.', '<ol><li>Нарежьте курицу полосками шириной 1 см. Перемешайте руками с порошком карри, рыбным соусом и солью и оставьте при комнатной температуре, пока готовите остальное (или уберите в холодильник на ночь).</li><li>Очистите лук, половину нарежьте тонкими ломтиками и отложите на конец, а вторую половину нарежьте мелкими кубиками.</li><li>Разогрейте масло в воке или большой сковороде на средне-сильном огне, обжарьте нарезанный кубиками лук 3–4 минуты, затем добавьте чеснок ещё на минуту.</li><li>Добавьте курицу и готовьте на среднем огне около 5 минут. Влейте воду и готовьте ещё около 5 минут, пока курица не будет готова, а вода не выпарится.</li><li>Добавьте тонкие ломтики лука и дольки помидоров и готовьте минуту: лук должен остаться хрустящим внутри. Подавайте с кинзой и дольками лайма.</li></ol><p><em>Посыпьте кинзой и подавайте с дольками лайма и рисом.</em></p>', CURRENT_TIMESTAMP),
  ('b2a959db-8f00-5845-8c8f-2372ba798a90', 'd00d3400-1612-5d5c-909f-059fbadaa210', 'en', 'Burmese-style chicken curry stir-fry with tomatoes and onion', 'A quick stir-fry of chicken breast with curry powder, plenty of onion and garlic, and fresh tomatoes at the end. The onions stay slightly crisp.', '<ol><li>Slice the chicken into 1 cm strips. Mix by hand with the curry powder, fish sauce and salt and let marinate at room temperature while you prep the rest (or refrigerate overnight).</li><li>Peel the onion; slice half thinly and set aside for the end, and finely dice the other half.</li><li>Heat the oil in a wok or large skillet over medium-high heat and cook the diced onion 3–4 minutes, then add the garlic for 1 minute more.</li><li>Add the chicken and cook over medium heat about 5 minutes. Add the water and cook another 5 minutes until the chicken is cooked through and the water has evaporated.</li><li>Stir in the sliced onion and tomato wedges and cook about 1 minute; the onion should stay crisp in the centre. Serve with cilantro and lime wedges.</li></ol><p><em>Top with cilantro and serve with lime wedges and rice.</em></p>', CURRENT_TIMESTAMP),
  ('4bcc0a23-0e83-58d2-b4cc-360c9288dc57', 'b89ebaec-0f79-50e7-aa29-c775e1b971e7', 'ru', 'Тас-кебаб: армянское тушёное мясо с пряностями', 'Простое ближневосточное рагу из говядины с томатной пастой, душистым перцем, корицей и лавром. Томится около 2,5 часов до такого состояния, что мясо распадается.', '<ol><li>Вскипятите 1,4 л воды в большой кастрюле и отставьте.</li><li>Промойте говядину холодной водой и переложите в большую кастрюлю, залейте холодной водой на 5 см. Нагревайте на средне-сильном огне, снимая пену. Когда закипит, снимите с огня, слейте воду на дуршлаг и промойте мясо холодной водой.</li><li>Завяжите в марлю перец горошком, душистый перец и лавровый лист.</li><li>Вытрите кастрюлю, верните туда говядину, влейте кипячёную воду, добавьте масло, томатную пасту, соль, корицу и мешочек со специями. Доведите до кипения на сильном огне.</li><li>Убавьте огонь, накройте и тушите около 2,5 часов, пока мясо не будет легко резаться ложкой (чем дольше, тем лучше, до распада на волокна).</li><li>Подавайте мясо с соусом на рисе пилав.</li></ol><p><em>Подавайте поверх рассыпчатого риса пилав в глубоких тарелках.</em></p>', CURRENT_TIMESTAMP),
  ('f8f5ed13-c76f-5eb8-a92d-21b65cc216ef', 'b89ebaec-0f79-50e7-aa29-c775e1b971e7', 'en', 'Tas kebab: Armenian spiced beef stew', 'A simple Middle Eastern beef stew with tomato paste, allspice, cinnamon and bay. It simmers about 2.5 hours until the meat falls apart.', '<ol><li>Bring 1.4 litres (6 cups) of water to a boil in a large saucepan and set aside.</li><li>Rinse the beef, put in a large pot and cover with 5 cm of cold water. Heat over medium-high, skimming the scum. When it boils, remove from the heat, drain in a colander and rinse the meat.</li><li>Tie the peppercorns, allspice berries and bay leaves in a piece of cheesecloth.</li><li>Wipe the pot clean, return the beef with the boiled water, butter, tomato paste, salt, cinnamon and spice bundle. Bring to a boil over high heat.</li><li>Reduce the heat, cover and simmer about 2½ hours until the meat cuts easily with a spoon (the longer the better, until it falls apart).</li><li>Serve the stew spooned over rice pilaf.</li></ol><p><em>Spoon over rice pilaf in wide bowls.</em></p>', CURRENT_TIMESTAMP),
  ('9fde1627-9157-5496-8635-2c7430f9cb1b', 'f923a8f4-6658-5729-85cd-a603266397ac', 'ru', 'Юветси: греческая запеканка из тушёной говядины с орзо', 'Медленно тушёная говядина (или баранина) с томатами, вином и корицей, запечённая с обжаренной пастой орзо. Сытное воскресное блюдо.', '<ol><li>Посолите и поперчите мясо. Разогрейте 2 ст. л. масла в кастрюле на среднем огне и обжарьте мясо порциями со всех сторон по 2–3 минуты с каждой стороны. Переложите на тарелку.</li><li>В той же кастрюле 2–3 минуты обжарьте лук и морковь, затем добавьте чеснок ещё на 1–2 минуты.</li><li>Добавьте томатную пасту, влейте вино и счистите осадок со дна. Добавьте бульон, томаты с соком, корицу, соль, перец и обжаренное мясо с соком.</li><li>Доведите до кипения, накройте, убавьте огонь и тушите на слабом огне 1,5–2,25 часа, иногда помешивая, пока мясо не станет очень мягким.</li><li>Разогрейте духовку до 175 °C. Прогрейте оставшиеся 2 ст. л. масла на сковороде и слегка обжарьте сырую пасту орзо 2 минуты, не давая ей зарумяниться. Переложите в форму на 3 л вместе с маслом.</li><li>Переложите мясо с соусом в форму с орзо и очень осторожно перемешайте.</li><li>Запекайте без крышки 25 минут, затем дайте постоять около 15 минут. Блюдо будет жидковатым, но орзо впитает остатки соуса. Перемешайте и подавайте с тёртым сыром.</li></ol><p><em>Дайте постоять 15 минут, пока орзо впитает жидкость, и подавайте с тёртым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('2c61f8d5-4ce9-56ce-94e2-7925938092fd', 'f923a8f4-6658-5729-85cd-a603266397ac', 'en', 'Giouvetsi: Greek beef stew and orzo casserole', 'Slow-stewed beef (or lamb) with tomatoes, wine and cinnamon, baked with toasted orzo pasta. A cozy Sunday dinner.', '<ol><li>Season the meat with salt and pepper. Heat 2 tbsp of oil in a Dutch oven over medium heat and brown the meat in batches, 2–3 minutes per side. Set aside.</li><li>In the same pot, cook the onions and carrots 2–3 minutes, then add the garlic for 1–2 minutes.</li><li>Stir in the tomato paste, deglaze with the wine, then add the broth, tomatoes with juices, cinnamon, salt, pepper and the seared meat with its juices.</li><li>Bring to a simmer, cover, lower the heat and simmer gently 1½–2¼ hours, stirring occasionally, until the meat is very tender.</li><li>Preheat the oven to 175°C (350°F). Heat the remaining 2 tbsp of oil in a skillet and lightly toast the uncooked orzo for 2 minutes without browning. Transfer with the oil to a 3-litre baking dish.</li><li>Transfer the meat and sauce to the dish and gently stir.</li><li>Bake uncovered 25 minutes, then rest about 15 minutes. It may look liquidy but the orzo will absorb the rest. Stir and serve with grated cheese.</li></ol><p><em>Rest 15 minutes so the orzo absorbs the liquid, then serve with grated cheese.</em></p>', CURRENT_TIMESTAMP),
  ('53bdedc9-c6cd-5cce-a5a8-74976d8e7615', '5d0eddde-5cf7-53c9-8df1-74fc50556276', 'ru', 'Греческая запечённая фасоль гигантес в томатном соусе', 'Крупная белая фасоль, предварительно сваренная и запечённая в густом томатном соусе с луком, морковью, чесноком и орегано. Нежная и кремовая. Постное основное блюдо, гарнир или закуска.', '<ol><li>Замоченную с вечера фасоль слейте, промойте, залейте большим количеством свежей воды и доведите до кипения. Варите на слабом огне, приоткрыв крышку, 55–65 минут, пока она почти не станет мягкой (она дойдёт в духовке).</li><li>Тем временем на сковороде разогрейте масло, обжарьте лук и морковь 5–7 минут до мягкости, затем добавьте чеснок на минуту, не давая ему зарумяниться.</li><li>Добавьте помидоры, воду, орегано и хлопья чили, посолите и поперчите. Доведите до кипения и тушите 10–15 минут, чтобы соус слегка загустел.</li><li>Разогрейте духовку до 180 °C. Слейте фасоль, смешайте с соусом и переложите в форму объёмом около 1,7 л. Если смесь суховата, подлейте воды.</li><li>Запекайте без крышки 50–60 минут, пока фасоль не станет мягкой и кремовой, а соус не загустеет и не уварится.</li><li>Посыпьте петрушкой и фетой и подавайте горячей или комнатной температуры.</li></ol><p><em>Посыпьте петрушкой и фетой и подавайте горячей или комнатной температуры с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('de99c7a8-33d7-5bb1-9436-fa9762e31619', '5d0eddde-5cf7-53c9-8df1-74fc50556276', 'en', 'Gigantes plaki: Greek baked giant beans in tomato sauce', 'Giant white beans simmered, then baked in a thick tomato sauce with onion, carrot, garlic and oregano until creamy. A vegetarian main, side or appetizer.', '<ol><li>Drain and rinse the overnight-soaked beans, cover with plenty of fresh water and bring to a boil. Simmer partially covered 55–65 minutes until mostly tender; they finish in the oven.</li><li>Meanwhile heat the oil in a skillet and cook the onion and carrot 5–7 minutes until soft, then add the garlic for 1 minute without browning.</li><li>Add the tomatoes, water, oregano and chili flakes, season, bring to a simmer and cook 10–15 minutes until slightly thickened.</li><li>Preheat the oven to 180°C (350°F). Drain the beans, combine with the sauce and transfer to a baking dish of about 1.7 litres. If dry, add more water.</li><li>Bake uncovered 50–60 minutes until the beans are soft and creamy and the sauce has thickened and reduced.</li><li>Garnish with parsley and feta and serve hot or at room temperature.</li></ol><p><em>Top with parsley and feta and serve hot or at room temperature with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('8458fea3-c621-5c1d-836c-a11c11158c80', '170f7008-e5c6-5e47-aada-fde493cc4917', 'ru', 'Рис басмати с зирой (джира райс)', 'Ароматный индийский гарнир: басмати, обжаренный с зирой, гвоздикой, корицей и лавровым листом, и сваренный под крышкой. Идеально к карри.', '<ol><li>Несколько раз промойте рис, залейте водой на 2,5 см и замочите примерно на 30 минут. Слейте воду.</li><li>В кастрюле с плотной крышкой нагрейте топлёное масло на среднем огне. Добавьте гвоздику, корицу, лавровый лист и зиру и обжаривайте несколько секунд, пока зира не начнёт потрескивать. Не пережгите.</li><li>Сразу добавьте рис и помешивайте около минуты, чтобы он покрылся маслом.</li><li>Влейте воду, добавьте соль, доведите до кипения, сразу убавьте огонь до минимума, накройте и готовьте 8–10 минут, пока вода не испарится.</li><li>Снимите с огня, подложите под крышку бумажное полотенце и оставьте на 10 минут. Взрыхлите вилкой и подавайте.</li></ol><p><em>Специи можно оставить в рисе для аромата или вынуть перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('75dd9f7d-0a8e-5d3d-8608-093cb4437169', '170f7008-e5c6-5e47-aada-fde493cc4917', 'en', 'Jeera rice: Indian cumin basmati rice', 'A fragrant Indian side: basmati fried with cumin seeds, cloves, cinnamon and bay, then steamed under a lid. Ideal with curry.', '<ol><li>Rinse the rice several times, cover with at least 2.5 cm of water and soak about 30 minutes. Drain.</li><li>In a pot with a tight lid heat the ghee over medium heat. Add the cloves, cinnamon, bay leaf and cumin seeds and toast a few seconds until the cumin sputters. Don''t let it burn.</li><li>Add the rice immediately and stir about a minute to coat in the fat.</li><li>Add the water and salt, bring to a boil, then immediately lower the heat, cover and cook 8–10 minutes until the water has evaporated.</li><li>Remove from the heat, place a paper towel under the lid and rest 10 minutes. Fluff with a fork and serve.</li></ol><p><em>Leave the whole spices in for authenticity or remove them before serving.</em></p>', CURRENT_TIMESTAMP),
  ('9e4c5501-a3ff-5f9d-b835-595651daca39', 'ef82e155-e338-55fe-a877-8b2f9cd2835c', 'ru', 'Классический минестроне с белой фасолью, картофелем и цукини', 'Итальянский овощной суп с фасолью каннеллини, картофелем, цукини и мелкой пастой в томатном бульоне. Рецепт легко менять под свои вкусы.', '<ol><li>Разогрейте масло в большой кастрюле на среднем огне. Обжарьте лук, морковь и сельдерей около 4 минут, часто помешивая, пока не начнут размягчаться.</li><li>Добавьте картофель, цукини, чеснок, петрушку и розмарин, посолите, поперчите, добавьте хлопья чили. Готовьте ещё 3–4 минуты, затем добавьте томатную пасту и обжарьте 1–2 минуты.</li><li>Добавьте томаты, фасоль и корку пармезана, влейте бульон, доведите до кипения. Накройте не полностью, убавьте огонь и варите около 15 минут.</li><li>Попробуйте и досолите. Положите пасту и варите без крышки ещё 10 минут до состояния al dente.</li><li>Выньте корку пармезана, разлейте суп по тарелкам и посыпьте тёртым сыром.</li></ol><p><em>Посыпьте тёртым пармезаном и подайте с итальянским хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('ce0ce7b3-d39a-5472-a875-8c0078219ec0', 'ef82e155-e338-55fe-a877-8b2f9cd2835c', 'en', 'Classic Italian minestrone with cannellini, potato and zucchini', 'An Italian vegetable soup with cannellini beans, potatoes, zucchini and small pasta in a tomato broth. Easy to customize.', '<ol><li>Heat the oil in a large pot over medium heat. Cook the onion, carrots and celery about 4 minutes, stirring often, until starting to soften.</li><li>Add the potato, zucchini, garlic, parsley and rosemary, season with salt, pepper and chili flakes. Cook 3–4 minutes more, then stir in the tomato paste for 1–2 minutes.</li><li>Stir in the tomatoes, beans and parmesan rind, add the broth and bring to a simmer. Partially cover, lower the heat and simmer about 15 minutes.</li><li>Taste and adjust the seasoning. Add the pasta and cook uncovered 10 more minutes until al dente.</li><li>Remove the cheese rind, ladle into bowls and top with grated cheese.</li></ol><p><em>Top with grated parmesan and serve with crusty Italian bread.</em></p>', CURRENT_TIMESTAMP),
  ('6fd5e4d4-2021-5a72-b56b-50d8950993a9', 'c17586f3-b9d2-57ac-a5b0-4e9042d3d75c', 'ru', 'Польский томатный суп с рисом (зупа помидорова)', 'Лёгкий суп на курином бульоне с томатным пюре и чесноком, заправленный сливками или сметаной. Подаётся с рисом или макаронами и готовится за 15 минут.', '<ol><li>В кастрюле на средне-сильном огне доведите бульон до кипения. Добавьте томатное пюре и чеснок, доведите до слабого кипения, убавьте огонь до минимума. Посолите и поперчите.</li><li>Сливки можно влить прямо в суп. Сметану сначала разведите в миске четвертью стакана горячего супа, понемногу добавляя его, а затем влейте в кастрюлю и перемешайте.</li><li>Разлейте по тарелкам, положите готовый рис или пасту, посыпьте петрушкой.</li></ol><p><em>Положите в тарелки готовый рис или пасту и посыпьте петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('74b425a0-3be5-509b-bf3c-5351b24ed7a7', 'c17586f3-b9d2-57ac-a5b0-4e9042d3d75c', 'en', 'Zupa pomidorowa: Polish tomato soup with rice', 'A light tomato soup in chicken broth with passata and garlic, finished with cream or sour cream and served with rice or pasta. Ready in 15 minutes.', '<ol><li>In a pot over medium-high heat, bring the broth to a simmer. Add the tomato puree and garlic, bring to a gentle boil, then reduce to a low simmer. Season with salt and pepper.</li><li>Heavy cream can go straight into the soup. Sour cream needs tempering: put it in a bowl, whisk in about ¼ cup of hot soup a little at a time, then stir into the pot.</li><li>Ladle into bowls, add cooked rice or pasta and top with chopped parsley.</li></ol><p><em>Add cooked rice or pasta to the bowls and sprinkle with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('097c09b1-8d86-584e-9cf4-0d6329ebfa0b', '488c0ac5-330e-500a-9c7c-7e6bcaff5c71', 'ru', 'Курица бирьяни с басмати, шафраном и жареным луком', 'Курица в йогуртовом маринаде со специями, накрытая слоем частично отварного риса басмати, шафрана и золотистого лука. Всё томится под крышкой.', '<ol><li>В большой кастрюле (около 26 см) смешайте йогурт, воду, масло, чеснок, имбирь и все специи для маринада с солью. Добавьте курицу, хорошо обваляйте и оставьте на 20 минут или на ночь.</li><li>Вскипятите 3 литра воды, всыпьте соль, гвоздику, лавровый лист, бадьян и кардамон. Положите рис, снова доведите до кипения и варите 4 минуты, пока он не будет почти готов, но чуть плотным в середине. Сразу слейте.</li><li>Для хрустящего лука нагрейте масло в сотейнике и порциями жарьте лук 3–4 минуты до золотистого цвета, не пережаривая. Выложите на бумажные полотенца.</li><li>Залейте шафран тёплой водой и оставьте минимум на 10 минут.</li><li>Поставьте кастрюлю с курицей на средний огонь, накройте и готовьте 5 минут, затем без крышки ещё 5 минут, дважды перевернув курицу. Снимите с огня.</li><li>Переверните курицу кожей вниз, посыпьте половиной жареного лука и половиной кинзы. Сверху выложите весь рис, разровняйте и слегка прижмите.</li><li>Полейте рис шафраном в случайном порядке и растопленным топлёным маслом. Накройте крышкой, поставьте на средний огонь, а когда пойдёт пар, убавьте до слабого и готовьте 25 минут. Оставьте под крышкой на 10 минут.</li><li>Подавайте, глубоко зачерпывая, чтобы захватить все слои. Посыпьте остатками лука и кинзы, йогурт отдельно.</li></ol><p><em>Подайте с йогуртом или мятным соусом на йогуртовой основе.</em></p>', CURRENT_TIMESTAMP),
  ('28e0bb55-3c7a-55b1-85ca-9e75fe5c92ca', '488c0ac5-330e-500a-9c7c-7e6bcaff5c71', 'en', 'Chicken biryani with basmati, saffron and crispy onions', 'Chicken in a spiced yogurt marinade topped with a layer of par-boiled basmati rice, saffron and golden onions, then steamed under a lid.', '<ol><li>In a large pot (about 11 inches) mix the yogurt, water, oil, garlic, ginger, marinade spices and salt. Add the chicken, coat well and marinate for 20 minutes or overnight.</li><li>Bring 3 litres of water to a boil with the salt, cloves, bay leaves, star anise and cardamom. Add the rice, return to a boil and cook 4 minutes until just cooked but still firm in the middle. Drain immediately.</li><li>For the crispy onions, heat the oil in a saucepan and fry the onion in batches for 3–4 minutes until golden, without burning. Drain on paper towels.</li><li>Steep the saffron in the warm water for at least 10 minutes.</li><li>Set the pot with the chicken over medium heat, cover and cook 5 minutes, then uncovered another 5 minutes, turning the chicken twice. Remove from the heat.</li><li>Turn the chicken skin side down, scatter over half the onions and half the cilantro, then top with all the rice and pat down gently.</li><li>Drizzle the saffron over the rice in a random pattern, then the melted ghee. Cover with the lid over medium heat, turn to low when steam appears and cook 25 minutes, then rest 10 minutes with the lid on.</li><li>Dig deep with a large spoon to catch all the layers. Garnish with the remaining onions and cilantro and serve with yogurt on the side.</li></ol><p><em>Serve with plain or mint yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('d8199aae-4836-5e25-a93b-931b832911a1', '139a08f8-8542-5ea7-8ce8-6a2cc1bf9dda', 'ru', 'Киш лорен с беконом и грюйером', 'Классический открытый пирог на песочной основе с нежной сливочно-яичной заливкой, беконом и сыром.', '<ol><li>Выпеките основу из песочного теста в форме 23 см по инструкции на упаковке или своему рецепту.</li><li>Разогрейте духовку до 180–200 °C. Растопите масло в сковороде, обжарьте лук, чеснок и бекон (200 г) до светло-золотистого цвета. Остудите на бумажных полотенцах.</li><li>Взбейте яйца со сливками, солью и перцем.</li><li>Выложите на готовую основу остывший бекон с луком, сверху сыр. Аккуратно залейте яичной смесью и слегка утопите сыр и бекон.</li><li>Запекайте 35–40 минут до золотистой корочки, середина должна слегка колыхаться.</li><li>Посыпьте обжаренным до золотистого цвета беконом, остудите 10 минут перед нарезкой.</li></ol><p><em>Дайте пирогу постоять 10 минут и подайте с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('d2408ffb-3968-58aa-8b72-b71a7acf634f', '139a08f8-8542-5ea7-8ce8-6a2cc1bf9dda', 'en', 'Quiche Lorraine with bacon and Gruyère', 'A classic open tart in a shortcrust shell with a smooth cream and egg custard, bacon and cheese.', '<ol><li>Bake the shortcrust shell in a 9-inch tart tin following the package or your own recipe.</li><li>Preheat the oven to 350–390 °F (180–200 °C). Melt the butter in a skillet and cook the onion, garlic and 200 g of bacon until light golden. Cool on paper towels.</li><li>Whisk the eggs with the cream, salt and pepper.</li><li>Spread the cooled bacon mixture over the baked shell, top with cheese and carefully pour in the custard, pushing some cheese and bacon below the surface.</li><li>Bake 35–40 minutes until golden on top, with the centre still slightly jiggly.</li><li>Garnish with the remaining bacon fried until golden and rest 10 minutes before slicing.</li></ol><p><em>Rest 10 minutes and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('321b943b-5c79-505c-b655-0f9dbb41d162', '50b2bda3-e46e-5838-8534-b71f0fe751d9', 'ru', 'Овощное карри с бататом, цветной капустой и горошком', 'Густое пряное карри из томатов с бататом, цветной капустой, кабачком, перцем и горошком. Сытное блюдо без мяса.', '<ol><li>Разогрейте масло в большой кастрюле на средне-сильном огне, 2 минуты обжарьте чеснок и лук, добавьте чили и готовьте, пока лук не станет прозрачным.</li><li>Всыпьте все специи (карри, душистый перец, мускатный орех, паприку, тимьян, зиру, кайенский и чёрный перец) и жарьте, помешивая, 1–2 минуты. Если слишком сухо, добавьте каплю воды или масла.</li><li>Добавьте перец и кабачок на 1 минуту. Затем томаты, бульон, батат и цветную капусту, перемешайте, доведите до кипения, накройте и убавьте огонь до среднего.</li><li>Тушите 15 минут до мягкого батата, затем снимите крышку и варите ещё 10 минут, пока соус не загустеет.</li><li>Добавьте горошек на 2 минуты, затем кинзу и шпинат до увядания. Посолите и поперчите по вкусу и подайте.</li></ol><p><em>Подайте с рисом басмати и йогуртом, посыпьте кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('e4df8c0d-f2a0-5af6-86a5-22c633b7f49f', '50b2bda3-e46e-5838-8534-b71f0fe751d9', 'en', 'Spiced vegetable curry with sweet potato, cauliflower and peas', 'A thick spiced tomato curry with sweet potato, cauliflower, zucchini, bell pepper and peas. A hearty meat-free dinner.', '<ol><li>Heat the oil in a large pot over medium-high heat and cook the garlic and onion for 2 minutes, add the chilli and cook until the onion is translucent.</li><li>Add all the spices (curry powder, allspice, nutmeg, paprika, thyme, cumin, cayenne and black pepper) and cook, stirring, 1–2 minutes. Add a touch of water or oil if too dry.</li><li>Add the bell pepper and zucchini for 1 minute, then the tomatoes, broth, sweet potato and cauliflower. Stir, bring to a simmer, cover and lower to medium.</li><li>Simmer 15 minutes until the sweet potato is quite soft, then uncover and cook 10 more minutes until the sauce thickens.</li><li>Add the peas for 2 minutes, then stir in the cilantro and spinach until wilted. Season to taste and serve.</li></ol><p><em>Serve over basmati rice with yogurt and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('d7148b84-d381-5bcd-8e30-437f7f2d610b', 'fcaffcdf-48ce-5e87-9716-fdadf67615a6', 'ru', 'Тайский тыквенный суп с кокосовым молоком и красной пастой карри', 'Суп-пюре из тыквы с луком, чесноком, пастой карри и кокосовым молоком. Привычный тыквенный суп с тайским вкусом.', '<ol><li>В большой кастрюле с толстым дном разогрейте масло, 2 минуты обжарьте лук и чеснок до мягкости.</li><li>Добавьте пасту карри и готовьте 2 минуты, затем тыкву и перемешивайте около 2 минут.</li><li>Отложите 1/4 стакана кокосового молока для подачи. Влейте бульон, остальное кокосовое молоко и рыбный соус, доведите до кипения и варите 8 минут на среднем огне до мягкой тыквы.</li><li>Пробейте суп погружным блендером до гладкости.</li><li>Разлейте по тарелкам, сверху добавьте кокосовое молоко, кинзу, жареный шалот и чили.</li></ol><p><em>Посыпьте кинзой и жареным луком-шалотом, добавьте ложку кокосового молока.</em></p>', CURRENT_TIMESTAMP),
  ('0a7b9de4-541b-5275-a045-4616ad336d0a', 'fcaffcdf-48ce-5e87-9716-fdadf67615a6', 'en', 'Thai coconut pumpkin soup with red curry paste', 'A pureed pumpkin soup with onion, garlic, red curry paste and coconut milk. A classic pumpkin soup with Thai flavours.', '<ol><li>Heat the oil in a large heavy pot and cook the onion and garlic for 2 minutes until soft.</li><li>Add the curry paste and cook 2 minutes, then the pumpkin and stir about 2 minutes to coat.</li><li>Set aside ¼ cup of the coconut milk for garnish. Add the stock, remaining coconut milk and fish sauce, bring to a simmer and cook 8 minutes over medium heat until the pumpkin is soft.</li><li>Blend the soup smooth with a stick blender.</li><li>Ladle into bowls and top with the reserved coconut milk, cilantro, crispy shallots and chilli.</li></ol><p><em>Top with cilantro, crispy shallots and a swirl of coconut milk.</em></p>', CURRENT_TIMESTAMP),
  ('c6190ab0-fe9d-52fb-8b63-f69ccf1601bd', 'a51ec1f6-6dc1-5352-b241-b86888016fe2', 'ru', 'Крем-суп из батата с луком-пореем и зирой', 'Мягкий суп-пюре из батата с луком, пореем и зирой, заправленный сливками. Можно посыпать орехами или гренками.', '<ol><li>В большой кастрюле на среднем огне растопите масло с оливковым, 5 минут обжарьте лук, порей и чеснок до мягкости.</li><li>Добавьте батат и зиру и готовьте ещё 3 минуты, помешивая.</li><li>Влейте бульон, добавьте соль и перец. Варите без крышки на слабом кипении 20 минут, пока батат не станет очень мягким.</li><li>Снимите с огня и пробейте погружным блендером до гладкости. Влейте сливки.</li><li>Разлейте по тарелкам и добавьте топпинги.</li></ol><p><em>Подайте с каплей сливок или йогурта и чем-нибудь хрустящим: фисташками, гренками, жареным луком.</em></p>', CURRENT_TIMESTAMP),
  ('969852a4-bcad-5ca8-b14d-f4da31a23863', 'a51ec1f6-6dc1-5352-b241-b86888016fe2', 'en', 'Sweet potato soup with leek and cumin', 'A smooth sweet potato soup with onion, leek and cumin, finished with cream. Top with nuts or croutons if you like.', '<ol><li>In a large heavy pot over medium heat melt the butter with the olive oil and cook the onion, leek and garlic 5 minutes until soft.</li><li>Add the sweet potato and cumin and cook 3 minutes more, stirring.</li><li>Pour in the stock, salt and pepper and simmer gently, uncovered, for 20 minutes until the sweet potato is very tender.</li><li>Remove from the heat and purée with a stick blender until smooth, then stir in the cream.</li><li>Ladle into bowls and add your toppings.</li></ol><p><em>Top with a drizzle of cream or yogurt and something crunchy such as pistachios, croutons or crispy shallots.</em></p>', CURRENT_TIMESTAMP),
  ('0b7d1f88-0fc2-5f99-b59f-ad79e6d77289', '3d62b98d-b99b-5412-9df9-f8d3d58e5c91', 'ru', 'Густой рыбный суп-чаудер с картофелем, кукурузой и горошком', 'Сливочный суп на молоке и бульоне с белой рыбой, картофелем, морковью, кукурузой и горошком. Большие хлопья рыбы в густом бульоне.', '<ol><li>Растопите масло в большой кастрюле на среднем огне, 5 минут пассеруйте чеснок и лук до прозрачности, без золотистого цвета. Добавьте морковь.</li><li>Всыпьте муку и перемешивайте 30 секунд. Постепенно влейте бульон, размешивая комки, затем молоко.</li><li>Добавьте картофель, кукурузу, соль и перец. Доведите до кипения, уменьшите огонь и варите 8 минут, изредка помешивая, пока картофель почти не будет готов.</li><li>Добавьте рыбу и горошек и варите 3 минуты, пока рыба не будет легко расслаиваться. Отрегулируйте соль и перец, при густоте разбавьте водой или молоком.</li><li>Разлейте по тарелкам и посыпьте зелёным луком.</li></ol><p><em>Посыпьте зелёным луком и подайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('ec6d69f2-66dd-58db-becc-73096e85af0a', '3d62b98d-b99b-5412-9df9-f8d3d58e5c91', 'en', 'White fish chowder with potato, corn and peas', 'A creamy milk-and-stock soup with white fish, potatoes, carrots, sweet corn and peas. Big flakes of fish in a thick broth.', '<ol><li>Melt the butter in a large pot over medium heat and cook the garlic and onion 5 minutes until translucent but not golden. Add the carrots.</li><li>Stir in the flour for 30 seconds, then slowly pour in the stock, stirring to dissolve the paste, followed by the milk.</li><li>Add the potato, corn, salt and pepper, bring to a simmer, lower the heat and cook gently 8 minutes, stirring now and then, until the potato is almost done.</li><li>Add the fish and peas and simmer 3 minutes until the fish flakes easily. Adjust the seasoning and thin with a little water or milk if too thick.</li><li>Ladle into bowls and sprinkle with green onions.</li></ol><p><em>Garnish with green onions and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('b248ce44-7bfd-523f-963d-9e285f9752f1', '081f2c7f-18d0-5d20-9eb5-777fd854f63d', 'ru', 'Курица с мексиканским рисом, фасолью и кукурузой в одной сковороде', 'Куриные бёдра, обжаренные с пряностями, запекаются поверх риса с томатами, кукурузой, фасолью и перцем. Всё готовится в одной сковороде, рис не подгорает.', '<ol><li>Разогрейте духовку до 180 °C. Смешайте чесночный порошок, паприку, зиру, соль, кайенский и чёрный перец.</li><li>Возьмите 1,5 ст. л. смеси, добавьте ложку масла и лайм, получится паста. Натрите ею курицу и, если есть время, оставьте мариноваться на час или на ночь.</li><li>В глубокой сковороде с крышкой разогрейте остальное масло и обжарьте курицу кожей вниз 4 минуты, затем 1,5 минуты с другой стороны (внутри она ещё сырая). Переложите на тарелку.</li><li>В той же сковороде 3 минуты обжарьте лук, чеснок и красный перец. Всыпьте рис, перемешайте, влейте бульон и томатное пюре, добавьте кукурузу, фасоль и остальную смесь специй.</li><li>Положите курицу кожей вверх поверх риса, доведите до кипения, накройте крышкой или фольгой и запекайте 25 минут. Затем снимите крышку и запекайте ещё 15 минут, пока не останутся лишь небольшие лужицы жидкости.</li><li>Оставьте на 10 минут без крышки. Выжмите на блюдо сок лайма, посыпьте кинзой и подавайте с дольками лайма и халапеньо.</li></ol><p><em>Выжмите лайм, посыпьте кинзой и подайте со сметаной или гуакамоле.</em></p>', CURRENT_TIMESTAMP),
  ('df8f7a15-2026-5558-8367-99bf4112fbad', '081f2c7f-18d0-5d20-9eb5-777fd854f63d', 'en', 'One-pot Mexican chicken and rice with black beans and corn', 'Spice-rubbed chicken thighs baked on top of seasoned Mexican red rice with corn, black beans and peppers. Cooked in a single skillet without scorching the rice.', '<ol><li>Preheat the oven to 350 °F (180 °C). Mix the garlic powder, paprika, cumin, salt, cayenne and black pepper.</li><li>Mix 1½ tablespoons of the spice mix with 1 tablespoon of oil and the lime juice into a paste, rub it on the chicken and marinate for an hour or overnight if you have time.</li><li>In a deep lidded skillet heat the remaining oil and sear the chicken skin side down 4 minutes, then 1½ minutes on the other side (still raw inside). Set aside on a plate.</li><li>In the same skillet cook the onion, garlic and red pepper for 3 minutes, add the rice, then the stock, tomato purée, corn, beans and remaining spice mix and stir.</li><li>Place the chicken skin side up on the rice, bring to a simmer, cover with a lid or foil and bake 25 minutes, then uncover and bake 15 minutes more until only small puddles of liquid remain.</li><li>Rest uncovered 10 minutes, squeeze over the lime juice, scatter cilantro and serve with lime wedges and jalapeños.</li></ol><p><em>Squeeze lime over it, scatter cilantro and serve with sour cream or guacamole.</em></p>', CURRENT_TIMESTAMP),
  ('73c93f8d-a5b8-5d28-8eba-1cd2eed832fa', '6f73ac92-f0f9-5641-914d-af14d55cbfe8', 'ru', 'Запечённые баклажаны по-марокански с пряным мясным фаршем', 'Половинки баклажана запекаются в смеси специй и подаются с фаршем, томатной пастой, йогуртом, кинзой и кедровыми орешками.', '<ol><li>Разогрейте духовку до 180 °C. Разрежьте баклажаны пополам и сделайте на мякоти надрезы сеткой на глубину около 2,5 см. Натрите солью (в том числе в надрезы), положите срезом вниз в дуршлаг и оставьте на 30 минут.</li><li>Слегка отожмите баклажаны, как губку, и промокните. Смешайте кориандр, паприку, зиру, душистый перец, чесночный порошок, имбирь, куркуму, корицу и кайенский перец. Отложите 3 ч. л. смеси для мяса, а в остальную добавьте масло и лимонный сок.</li><li>Выложите баклажаны на противень, намажьте пастой и запекайте около 45 минут до мягкости.</li><li>Тем временем на сковороде обжарьте лук с чесноком минуту, на сильном огне добавьте фарш и жарьте, разбивая, до исчезновения розового цвета. Добавьте отложенные специи и соль на минуту, затем томатную пасту на минуту и воду, готовьте ещё минуту.</li><li>Выложите фарш на баклажаны, посыпьте кинзой и кедровыми орешками, добавьте йогурт и каплю масла.</li></ol><p><em>Подайте с салатом, кускусом или лепёшкой.</em></p>', CURRENT_TIMESTAMP),
  ('c5aa802f-849b-5e15-9915-702abf33bec1', '6f73ac92-f0f9-5641-914d-af14d55cbfe8', 'en', 'Moroccan-spiced baked eggplant with ground beef', 'Eggplant halves roasted in a spice paste and topped with spiced mince, tomato paste, yogurt, cilantro and pine nuts.', '<ol><li>Preheat the oven to 350 °F (180 °C). Halve the eggplants and score the flesh in a diamond pattern about 1 inch deep. Rub with salt, including into the slits, and leave cut side down in a colander for 30 minutes.</li><li>Gently squeeze out excess water and pat dry. Mix the coriander, paprika, cumin, allspice, garlic powder, ginger, turmeric, cinnamon and cayenne. Set aside 3 teaspoons for the meat and stir the oil and lemon juice into the rest to make a paste.</li><li>Place the eggplant on a baking tray, slather with the spice paste and roast about 45 minutes until soft.</li><li>Meanwhile cook the onion and garlic in a skillet for a minute, turn the heat to high, add the mince and cook, breaking it up, until no red remains. Add the reserved spices and salt for a minute, then the tomato paste for a minute and the water for another minute.</li><li>Top the eggplant with the mince, sprinkle with cilantro and pine nuts, add a dollop of yogurt and a drizzle of oil.</li></ol><p><em>Serve with a salad, couscous or flatbread.</em></p>', CURRENT_TIMESTAMP),
  ('4df40e89-ad6f-530c-8e46-143daaae6b62', '22c32095-18e9-534a-96e1-49326d123f5d', 'ru', 'Курица в карамели с имбирём по-вьетнамски', 'Куски куриных бёдер в блестящей карамельной глазури с имбирём, шалотом и рыбным соусом. Сладко-солёное блюдо за 30 минут.', '<ol><li>Перемешайте курицу с рыбным соусом и чили и оставьте, пока готовите остальное (можно даже на ночь).</li><li>Смешайте масло и сахар в холодной большой антипригарной сковороде (около 30 см) и поставьте на средне-сильный огонь. Как только сахар растает, снимите сковороду с огня и осторожно добавьте курицу, имбирь и шалот. Карамель может застыть, потом она снова растает.</li><li>Верните сковороду на огонь и помешивайте, пока курица не побелеет снаружи, не жаря её до готовности.</li><li>Влейте кипяток и доведите до кипения. Готовьте на сильном кипении 10–12 минут, пока жидкость не уварится до глазури, периодически помешивая, а в конце регулярно переворачивая, чтобы курица прокрасилась.</li><li>Подавайте с рисом, украсив кинзой или зелёным луком и красным чили.</li></ol><p><em>Подайте с рисом жасмин, огурцом и свежей кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('db116228-33b2-5432-837f-51ac2d5f99a3', '22c32095-18e9-534a-96e1-49326d123f5d', 'en', 'Vietnamese caramel ginger chicken', 'Chicken thigh pieces in a glossy caramel glaze with ginger, shallots and fish sauce. A sweet-savoury dinner in about half an hour.', '<ol><li>Toss the chicken with the fish sauce and chilli and set aside while you prepare the rest (or marinate overnight).</li><li>Mix the oil and sugar in a cold large non-stick pan (about 12 inches) and place over medium-high heat. As soon as the sugar melts, take the pan off the heat and carefully add the chicken, ginger and shallots. The caramel may harden but will melt again.</li><li>Return to the heat and stir just until the chicken turns from pink to white on the outside, not browned or cooked through.</li><li>Pour in the boiling water and bring to a boil. Simmer rapidly 10–12 minutes until the liquid reduces to a glaze, stirring now and then and at the end tossing regularly for colour.</li><li>Serve with rice, garnished with cilantro or green onion and sliced red chilli.</li></ol><p><em>Serve with jasmine rice, cucumber and fresh cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('cfaf1d8b-70dd-5a6d-b8ef-5e4840affc5e', '94c52048-d10e-5c7f-9ce7-4b3d96800ecc', 'ru', 'Нежная кремовая болтунья на тосте', 'Яйца, взбитые с молоком и приготовленные за минуту до мягких сливочных комочков, на горячем хрустящем тосте с маслом.', '<ol><li>Взбейте яйца с молоком, солью и перцем. Возьмите антипригарную или хорошо прогретую чугунную сковороду около 25 см и мягкую лопатку.</li><li>Растопите масло на среднем огне, влейте яйца и через 5 секунд начните неторопливо двигать лопаткой по сковороде, отодвигая схватившееся и давая сырому стекать.</li><li>Через 30 секунд начните складывать яйца. Готовьте всего около минуты, пока не получатся мягкие комочки без жидкости по краям. Снимите с огня, пока яйца чуть недоготовлены.</li><li>Подсушите хлеб в тостере или на сухой сковороде и щедро намажьте маслом.</li><li>Мягко перемешайте яйца ещё 10 секунд, они дойдут от тепла сковороды, и выложите на горячие тосты. Посыпьте перцем и подавайте сразу.</li></ol><p><em>Подавайте сразу. Можно посыпать зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('51c788b8-50c1-5791-9b17-f92a1014af96', '94c52048-d10e-5c7f-9ce7-4b3d96800ecc', 'en', 'Soft creamy scrambled eggs on toast', 'Eggs whisked with milk and cooked for about a minute into soft, custardy curds, served on hot buttered toast.', '<ol><li>Whisk the eggs with the milk, salt and pepper. Use a non-stick or well-seasoned cast iron pan of about 10 inches and a soft spatula.</li><li>Melt the butter over medium heat and pour in the eggs. After 5 seconds start pushing the spatula slowly back and forth, moving set egg aside so raw egg runs onto the pan.</li><li>After about 30 seconds start folding. Cook about 60 seconds in total until soft custardy curds with no liquid at the edges, taking the pan off the heat while still slightly undercooked.</li><li>Toast the bread in a toaster or dry pan and spread generously with butter.</li><li>Gently fold the eggs another 10 seconds to finish with residual heat, slide onto the hot toast, sprinkle with pepper and serve at once.</li></ol><p><em>Serve immediately, with herbs if you like.</em></p>', CURRENT_TIMESTAMP),
  ('73016924-8347-58d9-9174-af8eb5b630da', '2197942d-879e-52e1-be59-2374f05a8c23', 'ru', 'Говядина по-монгольски с зелёным луком', 'Тонкие ломтики говядины, замаринованные, обвалянные в крахмале и обжаренные до хрустящей корочки, в густом соевом соусе с чесноком и имбирём. Менее сладкая, чем в ресторанах.', '<ol><li>Смешайте нарезанную поперёк волокон говядину с ингредиентами маринада: маслом, вином, соевым соусом, крахмалом, водой и содой. Оставьте на 1 час. Мясо должно остаться влажным; если сухое, добавьте ложку воды.</li><li>Для соуса растворите коричневый сахар в горячей воде (или бульоне) и смешайте с обычным и тёмным соевым соусом.</li><li>Обваляйте замаринованную говядину в крахмале со всех сторон.</li><li>Разогрейте в воке масло на сильном огне почти до дымка. Выложите говядину в один слой и обжаривайте по минуте с каждой стороны до хрустящей корочки. Снимите вок с огня, переложите мясо на тарелку.</li><li>Слейте масло, оставив 1 ст. л. Включите средне-сильный огонь, добавьте имбирь и сушёный чили. Через 15 секунд добавьте чеснок и белую часть лука на 15 секунд, затем влейте соус.</li><li>Варите соус около 2 минут, затем постепенно влейте крахмальную смесь и готовьте, пока соус не загустеет настолько, чтобы покрывать ложку.</li><li>Верните говядину, добавьте зелёную часть лука и перемешайте за 30 секунд. Соус должен обволакивать мясо. Подавайте с рисом.</li></ol><p><em>Подавайте с рисом на пару.</em></p>', CURRENT_TIMESTAMP),
  ('17cbe6f0-e6a0-5cbd-a7dd-8d9e4e53edd4', '2197942d-879e-52e1-be59-2374f05a8c23', 'en', 'Mongolian beef with crispy flank steak and scallions', 'Thin beef slices marinated, dredged in cornstarch and seared crisp, tossed in a thick soy sauce with garlic and ginger. Less sweet than the restaurant version.', '<ol><li>Combine the beef sliced across the grain with the marinade: oil, wine, soy sauce, cornstarch, water and baking soda. Marinate 1 hour. The beef should stay moist; add a tablespoon of water if dry.</li><li>For the sauce, dissolve the brown sugar in hot water (or stock) and stir in the light and dark soy sauces.</li><li>Dredge the marinated beef slices in cornstarch until thoroughly coated.</li><li>Heat the oil in a wok over high heat until just before smoking. Spread the beef in a single layer and sear 1 minute per side until crisp. Turn off the heat and move the beef to a plate.</li><li>Pour off the oil, leaving 1 tbsp. Over medium-high heat add the ginger and dried chilies. After 15 seconds add the garlic and white scallion parts for 15 seconds, then pour in the sauce.</li><li>Simmer the sauce about 2 minutes, then slowly stir in the cornstarch slurry and cook until thick enough to coat the back of a spoon.</li><li>Return the beef, add the green scallion parts and toss 30 seconds. The sauce should cling to the beef. Serve with steamed rice.</li></ol><p><em>Serve with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('069338f3-c52b-585e-b437-82c82b961fef', 'fb64cdcc-57f9-534c-b41c-8449642ba3c3', 'ru', 'Гюдон: японская тарелка с рисом, говядиной и яйцом', 'Тонкие ломтики говядины, потушенные с луком в слегка сладком соусе из мирина и соевого соуса, поверх риса с глазуньей.', '<ol><li>Разогрейте масло на большой сковороде на средне-сильном огне и готовьте тонко нарезанный лук около 10 минут, часто помешивая.</li><li>Добавьте говядину и сахар и готовьте до лёгкого подрумянивания. Влейте мирин, соевый соус и бульон, доведите до кипения и варите 10–15 минут, пока бульон не превратится в жидкий соус. При необходимости добавьте соевого соуса.</li><li>Тем временем разогрейте ещё пару ложек масла на другой сковороде и пожарьте глазунью, желтки оставьте жидкими.</li><li>Разложите рис по четырём мискам, сверху выложите говядину с соусом и яйцо. Посыпьте зелёным луком и кунжутом.</li></ol><p><em>Посыпьте зелёным луком и кунжутом, желток оставьте жидким.</em></p>', CURRENT_TIMESTAMP),
  ('aab9815c-f2f4-5659-bdbc-c21d9d3eeca6', 'fb64cdcc-57f9-534c-b41c-8449642ba3c3', 'en', 'Gyudon: Japanese beef and rice bowls with egg', 'Thinly sliced beef simmered with onions in a lightly sweet mirin and soy sauce, served over rice with a fried egg.', '<ol><li>Heat the oil in a large skillet over medium-high and cook the very thinly sliced onions about 10 minutes, stirring often.</li><li>Add the beef and sugar and cook until lightly browned. Add the mirin, soy sauce and stock, bring to a simmer and cook 10–15 minutes to reduce into a thin sauce. Add a little more soy if needed.</li><li>Meanwhile heat a couple more tablespoons of oil in another skillet and fry the eggs sunny-side up with runny yolks.</li><li>Divide the rice among four bowls and top each with the beef, sauce and an egg. Garnish with scallion and sesame seeds.</li></ol><p><em>Top with scallion and sesame seeds; keep the yolk runny.</em></p>', CURRENT_TIMESTAMP),
  ('99090c12-6ffd-5f1e-b2d8-8c56b78fc8dc', '36f3a34c-c06f-553b-bceb-62c61b970ed1', 'ru', 'Стручковая фасоль с фаршем и чесноком по-китайски', 'Стручковая фасоль, обжаренная в воке до лёгких подпалин, и хрустящий свиной фарш в соевом соусе с имбирём, чесноком и перцем.', '<ol><li>Смешайте фарш с ингредиентами маринада и перемешивайте, пока жидкость не впитается. Оставьте на 15–20 минут.</li><li>Разогрейте в воке 2 ст. л. масла на среднем огне. Выложите фасоль, нарезанную на кусочки по 1,2 см, в один слой. Через 30 секунд перемешайте и снова разровняйте. Повторяйте 5–8 минут, пока фасоль не станет слегка подпечённой и готовой. Переложите на тарелку.</li><li>Добавьте в вок 1 ст. л. масла на сильном огне и обжарьте фарш до румяной корочки, не перемешивая слишком часто. Затем убавьте огонь до среднего.</li><li>Добавьте чеснок, болгарский перец и чили, жарьте минуту. Верните фасоль, добавьте сахар, кунжутное масло, соевый соус, белый перец, щепотку соли и воду. На сильном огне перемешайте 10–15 секунд и подавайте.</li></ol><p><em>Подавайте с рисом. Свинину можно заменить курицей или говядиной.</em></p>', CURRENT_TIMESTAMP),
  ('fd951026-9a98-5e3e-82e4-73133be9b276', '36f3a34c-c06f-553b-bceb-62c61b970ed1', 'en', 'Chinese stir-fried green beans with ground pork and garlic', 'Green beans wok-seared until lightly charred and tossed with crispy ground pork in a soy, ginger and garlic sauce.', '<ol><li>Mix the ground pork with the marinade ingredients until any standing liquid is absorbed. Marinate 15–20 minutes.</li><li>Heat 2 tbsp of oil in a wok over medium heat. Add the green beans cut to 1.2 cm and spread in a single layer. After 30 seconds stir and respread. Repeat 5–8 minutes until slightly charred and cooked through. Transfer to a plate.</li><li>Add 1 tbsp of oil to the wok on high heat and brown the pork, stirring sparingly so it crisps. Then reduce to medium.</li><li>Add the garlic, bell pepper and chilies and stir-fry 1 minute. Return the beans and add the sugar, sesame oil, soy sauce, white pepper, a pinch of salt and water. Stir-fry on high 10–15 seconds and serve.</li></ol><p><em>Serve with rice. Ground chicken or beef also works.</em></p>', CURRENT_TIMESTAMP),
  ('609c29a6-1e9d-5f5e-8714-a48c4012609e', 'fec232df-0cb0-5818-811e-12436324d3bc', 'ru', 'Классический тыквенный суп-пюре с сыром грюйер', 'Нежный суп-пюре из тыквы с луком-пореем, тимьяном и мускатным орехом, с тёртым грюйером и сливками.', '<ol><li>Разрежьте тыкву пополам, выньте семена и волокна ложкой, срежьте кожуру и нарежьте мякоть кусками.</li><li>В большой кастрюле с толстым дном на среднем огне растопите масло, добавьте лук-порей (или репчатый) и тимьян. Готовьте 5 минут до мягкости без румянца.</li><li>Добавьте тыкву, бульон и лавровый лист. Доведите до кипения, убавьте огонь, накройте и варите около 35 минут, пока тыква не станет очень мягкой. Выньте лавровый лист и тимьян.</li><li>Снимите с огня и пюрируйте погружным блендером (или порциями в блендере) до гладкости. Добавьте сыр, дайте расплавиться и ещё раз взбейте, чтобы сыр полностью растворился.</li><li>Добавьте соль, перец, мускатный орех и сливки. Держите на слабом огне, но не доводите до кипения, иначе сливки свернутся.</li><li>Разлейте по тарелкам и посыпьте шнитт-луком.</li></ol><p><em>Посыпьте шнитт-луком или подайте с гренками, обжаренным беконом или тыквенными семечками.</em></p>', CURRENT_TIMESTAMP),
  ('b6df157e-ae2b-5076-b67e-58a7c83fd230', 'fec232df-0cb0-5818-811e-12436324d3bc', 'en', 'Classic pumpkin soup with leek and gruyère', 'A smooth pumpkin purée soup with leek, thyme and nutmeg, enriched with grated gruyère and cream.', '<ol><li>Halve the pumpkin, scoop out the seeds and stringy bits, slice off the rind and cut the flesh into chunks.</li><li>In a large Dutch oven over medium heat, melt the butter and add the leek (or onion) and thyme. Cook 5 minutes until soft but not browned.</li><li>Add the pumpkin, stock and bay leaf. Bring to a boil, lower to a simmer, cover and cook about 35 minutes until very tender. Remove the bay leaf and thyme.</li><li>Off the heat, purée with an immersion blender (or in batches in a blender) until smooth. Stir in the cheese; once melted, blend again so it is fully emulsified.</li><li>Stir in the salt, pepper, nutmeg and cream. Keep warm over low heat but do not boil or the cream will split.</li><li>Serve in bowls garnished with chives.</li></ol><p><em>Garnish with chives, or serve with croutons, crumbled bacon or toasted pumpkin seeds.</em></p>', CURRENT_TIMESTAMP),
  ('b9856e33-9d41-55e5-81ef-cd6f82e46395', 'd6de48a0-4a46-55b1-a9f5-955203f17d1d', 'ru', 'Пибимпап с говяжьим фаршем, овощами и яйцом', 'Корейская тарелка с рисом: говяжий фарш, бланшированные ростки и зелень, морковь, кимчи и глазунья с острой пастой кочхуджан.', '<ol><li>Сварите рис (в мультиварке или на плите). Поставьте на плиту кастрюлю с водой на кипячение.</li><li>Вымойте ростки и шпинат (или кресс-салат), морковь нарежьте соломкой, чеснок мелко порубите.</li><li>Бланшируйте ростки около 5 минут и выньте шумовкой. В той же воде бланшируйте зелень 1 минуту. Промойте обе холодной водой и тщательно отожмите.</li><li>Зелень сверните в рулет и нарежьте. Ростки и зелень разложите по двум мискам, приправьте солью и ½ ч. л. кунжутного масла, добавьте чеснок и перемешайте.</li><li>На сковороде на средне-сильном огне обжарьте морковь в масле около минуты, чтобы она осталась хрустящей, и переложите.</li><li>Увеличьте огонь, обжарьте говяжий фарш, разминая его, и добавьте соевый соус. Отдельно пожарьте яйца глазуньей, желток должен остаться жидким.</li><li>Разложите рис по четырём мискам, сверху выложите мясо, зелень, ростки, морковь, кимчи и яйцо. Подавайте с кочхуджаном и кунжутом.</li></ol><p><em>Перед едой перемешайте всё в миске с кочхуджаном.</em></p>', CURRENT_TIMESTAMP),
  ('c60f3eac-2994-5e75-aa7a-d3edf955a5b6', 'd6de48a0-4a46-55b1-a9f5-955203f17d1d', 'en', 'Beef bibimbap: Korean rice bowl with vegetables and egg', 'A Korean rice bowl with ground beef, blanched sprouts and greens, carrot, kimchi and a fried egg with spicy gochujang.', '<ol><li>Cook the rice in a rice cooker or on the stove. Put a pot of water on to boil.</li><li>Wash the bean sprouts and spinach (or watercress), julienne the carrot and mince the garlic.</li><li>Blanch the bean sprouts about 5 minutes and remove with a slotted spoon. Blanch the greens in the same water for 1 minute. Rinse both under cold water and squeeze out well.</li><li>Roll the greens up and slice. Put the sprouts and greens in separate bowls, season each with salt and ½ tsp sesame oil, add the garlic and toss.</li><li>In a skillet over medium-high heat stir-fry the carrots in oil about 1 minute until tender but crisp, then remove.</li><li>Turn up the heat and brown the ground beef, breaking it up, then stir in the soy sauce. In a separate pan fry the eggs sunny-side up with runny yolks.</li><li>Divide the rice among four bowls and top with the beef, greens, sprouts, carrots, kimchi and egg. Serve with gochujang and sesame seeds.</li></ol><p><em>Mix everything together in the bowl with gochujang before eating.</em></p>', CURRENT_TIMESTAMP),
  ('a22fe11c-cd57-5844-8345-dde7efff4c55', '87bc7c5d-4edf-59e1-99b8-f57eb7d83d7c', 'ru', 'Пак-чой, обжаренный с чесноком и имбирём', 'Базовый китайский гарнир: пак-чой быстро обжаривается в воке с чесноком и имбирём и заправляется крахмалом, чтобы блестел. Подходит почти ко всему.', '<ol><li>Мелкий пак-чой разрежьте вдоль пополам или на четвертинки. Крупный разберите на стебли, срежьте жёсткие основания и нарежьте наискосок кусками по 2,5 см.</li><li>Замочите пак-чой в большой миске с холодной водой на 5–10 минут, перемешивая руками, чтобы вышел песок. Повторите ещё два раза, пока вода не станет чистой. Хорошо стряхните воду.</li><li>Разогрейте вок или большую сковороду на слабом огне, влейте масло, добавьте имбирь (и чеснок, если любите сильнее). Добавьте овощи, пока чеснок ещё белый.</li><li>Увеличьте огонь до сильного и обжаривайте, перемешивая широкими движениями, затем добавьте соль, кунжутное масло и белый перец. Готовьте ещё 1–2 минуты.</li><li>Влейте смесь крахмала с водой в центр, перемешайте, пока овощи не заблестят. Подавайте сразу.</li></ol><p><em>Подавайте сразу, пока овощи хрустят.</em></p>', CURRENT_TIMESTAMP),
  ('95676806-8310-58a6-a801-1ebfaa9ff9a7', '87bc7c5d-4edf-59e1-99b8-f57eb7d83d7c', 'en', 'Garlic bok choy stir-fry with ginger', 'A basic Chinese side: bok choy quickly stir-fried in a wok with garlic and ginger and glossed with a cornstarch slurry. Goes with almost anything.', '<ol><li>Halve or quarter small bok choy lengthwise. For larger heads, separate the stems, trim the tough bases and cut on the diagonal into 2.5 cm pieces.</li><li>Soak the bok choy in a large bowl of cold water 5–10 minutes, agitating by hand to loosen dirt. Repeat two more times until clean, then shake off the excess water.</li><li>Heat a wok or large pan over low heat, add the oil and ginger (and the garlic if you like it stronger). Add the vegetables while the garlic is still white.</li><li>Increase to high heat and stir-fry with a scooping motion, then add the salt, sesame oil and white pepper. Stir-fry another 1–2 minutes.</li><li>Pour the cornstarch slurry into the centre and toss until the vegetables glisten. Serve immediately.</li></ol><p><em>Serve immediately while the stems are still crisp.</em></p>', CURRENT_TIMESTAMP),
  ('50f8c13b-c654-540c-aef1-68af1287de4a', '3f9b58bd-d792-5797-9d20-6a96727cf750', 'ru', 'Жареный рис с говяжьим фаршем, горошком и яйцом', 'Быстрый будничный ужин: рис, обжаренный с говяжьим фаршем, луком, зелёным горошком и соусом из соевого и устричного соусов. Сверху глазунья со сладким соевым соусом.', '<ol><li>В небольшой миске смешайте тёплый бульон, оба соевых соуса, устричный соус, кунжутное масло и перец.</li><li>Взрыхлите готовый рис вилкой или руками, разделив комки.</li><li>Разогрейте вок до лёгкого дымка и влейте 2 ст. л. масла. Обжарьте говяжий фарш до румяности и аромата, разминая не слишком мелко. Добавьте лук, чеснок и вино, убавьте огонь до средне-сильного и готовьте до прозрачности лука.</li><li>Влейте соус и доведите до кипения, чтобы очистить дно. Добавьте рис и перемешивайте около минуты на сильном огне. Добавьте горошек и жарьте ещё 2–4 минуты, пока рис не прогреется.</li><li>Добавьте зелёный лук и разложите рис по тарелкам. Пожарьте яйца в разогретой сковороде.</li><li>Смешайте соевый соус с горячей водой и сахаром. Положите яйцо поверх риса и сбрызните сладким соусом.</li></ol><p><em>Используйте вчерашний рис: он не слипается.</em></p>', CURRENT_TIMESTAMP),
  ('22b25320-34f5-5000-9204-ccd02bc7b27f', '3f9b58bd-d792-5797-9d20-6a96727cf750', 'en', 'Hamburger fried rice with peas and fried egg', 'A quick weeknight dinner: rice stir-fried with ground beef, onion, green peas and a soy and oyster sauce. Topped with a fried egg and sweet soy sauce.', '<ol><li>In a small bowl combine the warm stock, both soy sauces, oyster sauce, sesame oil and black pepper.</li><li>Fluff the cooked rice with a fork or hands, breaking up any clumps.</li><li>Heat a wok until just smoking and coat with 2 tbsp of oil. Stir-fry the ground beef until browned and fragrant, breaking it up without being obsessive. Add the onion, garlic and wine, lower to medium-high and cook until the onion is translucent.</li><li>Pour in the sauce mixture and simmer to deglaze. Add the rice and stir about 1 minute over high heat. Add the peas and stir-fry 2–4 minutes until heated through.</li><li>Stir in the scallion and plate the rice. Fry the eggs in a very hot pan with a little oil.</li><li>Mix the soy sauce with the hot water and sugar. Top the rice with the egg and drizzle with the sweet soy sauce.</li></ol><p><em>Use day-old rice so it doesn''t clump.</em></p>', CURRENT_TIMESTAMP),
  ('54004a40-f549-5037-a2d3-ac0829686919', '61ae11bb-bc8a-5354-b6fa-c28a29fca917', 'ru', 'Капуста, обжаренная с фунчозой, имбирём и чесноком', 'Быстрое китайское блюдо: нашинкованная капуста и размоченная фунчоза обжариваются в воке с имбирём, чесноком и соевым соусом. Подходит как гарнир или постный обед.', '<ol><li>Замочите фунчозу в холодной воде на 5 минут до лёгкой мягкости. Слейте, разрежьте пополам вдоль и отставьте.</li><li>Тонко нашинкуйте капусту. Смешайте соус: светлый и тёмный соевый соус, уксус, белый перец, кунжутное масло, сахар и воду.</li><li>Разогрейте в воке масло на среднем огне, обжаривайте имбирь и чеснок, пока чеснок слегка не зарумянится. Добавьте капусту, включите максимальный огонь и жарьте 1–2 минуты до лёгкого увядания. Добавьте сушёный чили.</li><li>Влейте соус, добавьте фунчозу и хорошо перемешайте. Убавьте огонь, если блюдо сохнет. Посолите по вкусу, добавьте зелёный лук, перемешайте и подавайте.</li></ol><p><em>Подавайте горячим. Для сытности добавьте яйцо или тофу.</em></p>', CURRENT_TIMESTAMP),
  ('bfd2e234-b585-5b0b-b44c-1f5bdaa2fa7f', '61ae11bb-bc8a-5354-b6fa-c28a29fca917', 'en', 'Stir-fried cabbage with glass noodles, ginger and garlic', 'A quick Chinese dish of shredded cabbage and soaked glass noodles stir-fried in a wok with ginger, garlic and soy sauce. Works as a side or a light meatless meal.', '<ol><li>Soak the glass noodles in cold water for 5 minutes until slightly softened. Drain, cut in half and set aside.</li><li>Thinly shred the cabbage. Mix the sauce: light and dark soy sauce, vinegar, white pepper, sesame oil, sugar and water.</li><li>Heat the oil in a wok over medium heat and cook the ginger and garlic until the garlic is lightly browned. Add the cabbage, turn the heat to maximum and stir-fry 1–2 minutes until slightly wilted. Add the dried chilies.</li><li>Add the sauce and the glass noodles and mix well, lowering the heat if it gets too dry. Salt to taste, add the scallions, toss once more and serve.</li></ol><p><em>Serve hot. Add egg or tofu for more protein.</em></p>', CURRENT_TIMESTAMP),
  ('f94cc77c-73c9-5211-a691-faee6d8a8151', 'c75de466-8ade-5858-b275-e00b1ef9bdf1', 'ru', 'Курица с бурым рисом, пореем и овощами в одной сковороде', 'Куриные бёдра с чесноком и пряностями томятся над рисом и пореем в овощном бульоне, в конце добавляются замороженные овощи. Сытный ужин за час, мыть одну посуду.', '<ol><li>В большой миске смешайте паприку, кориандр, чеснок и масло, обваляйте в смеси курицу.</li><li>Разогрейте большую антипригарную сковороду с крышкой и обжарьте курицу без масла на средне-сильном огне 5 минут, перевернув на половине времени. Переложите на тарелку.</li><li>Влейте бульон, соскребая прилипшие кусочки. Добавьте рис, порей, орегано и лавровый лист, сверху выложите курицу, накройте, доведите до кипения, убавьте огонь и варите 20 минут.</li><li>Добавьте замороженные овощи, накройте и прогревайте около 5 минут, затем оставьте на 5–10 минут и аккуратно перемешайте.</li></ol><p><em>Дайте постоять 5–10 минут и подайте.</em></p>', CURRENT_TIMESTAMP),
  ('0142f16e-19cc-5d31-82c2-46805a1f15c2', 'c75de466-8ade-5858-b275-e00b1ef9bdf1', 'en', 'One-pot chicken with brown rice, leeks and vegetables', 'Garlicky spiced chicken thighs simmer over rice and leeks in vegetable stock, finished with frozen vegetables. A wholesome dinner in under an hour with one pan to wash.', '<ol><li>Mix the spices, garlic and oil in a large bowl and turn the chicken in the mixture until coated.</li><li>Heat a large lidded non-stick pan and fry the chicken without extra oil over medium-high heat for 5 minutes, turning halfway. Set aside on a plate.</li><li>Pour the stock into the pan, scraping up the browned bits. Add the rice, leeks, oregano and bay, lay the chicken on top, cover, bring to a boil, turn down and simmer 20 minutes.</li><li>Stir in the frozen vegetables, cover and heat through about 5 minutes, then stand 5–10 minutes and lightly mix.</li></ol><p><em>Rest for 5–10 minutes before serving.</em></p>', CURRENT_TIMESTAMP),
  ('21e9b99c-c065-5e29-9120-38e940ea2783', 'f9913c8d-e778-5094-8a8f-2aa8b8a336ed', 'ru', 'Паста с запечённой фетой, черри и оливками', 'Брусок феты запекается с помидорами черри, чесноком и оливками, затем разминается и смешивается с пастой в кремовый соус.', '<ol><li>Разогрейте духовку до 200 °C. Поставьте фету в центр большой формы, вокруг разложите помидоры, оливки и неочищенный чеснок. Полейте маслом и приправьте.</li><li>Запекайте 30 минут, пока помидоры не лопнут, а фета не зарумянится по краям. Выдавите чеснок из шелухи в форму и слегка разомните с помидорами.</li><li>Тем временем отварите пасту в подсоленной воде по инструкции, слейте, оставив кружку воды.</li><li>Добавьте пасту и немного воды в форму и перемешайте, пока фета не разойдётся и не получится кремовый соус. Поперчите и посыпьте базиликом.</li></ol><p><em>Посыпьте свежим базиликом.</em></p>', CURRENT_TIMESTAMP),
  ('40ce9887-6895-5e62-96af-95510d0a90e0', 'f9913c8d-e778-5094-8a8f-2aa8b8a336ed', 'en', 'Baked feta pasta with cherry tomatoes and olives', 'A block of feta bakes with cherry tomatoes, garlic and olives, then is mashed and tossed with pasta into a creamy sauce.', '<ol><li>Heat the oven to 400 °F (200 °C). Put the feta in the centre of a large baking dish and scatter the tomatoes, olives and unpeeled garlic around it. Drizzle with oil and season.</li><li>Bake 30 minutes until the tomatoes burst and blister and the feta is golden at the edges. Squeeze the garlic out of its skins into the dish and mash lightly with the tomatoes.</li><li>Meanwhile cook the pasta in salted water as directed, then drain, reserving a mugful of water.</li><li>Add the pasta and a splash of the water to the dish and mix until the feta breaks up into a creamy sauce. Season with pepper and scatter with basil.</li></ol><p><em>Scatter with fresh basil.</em></p>', CURRENT_TIMESTAMP),
  ('a95cb198-7890-50b4-acc0-ace42d7f3c70', '225f0957-f000-57de-ac0e-94144c69a083', 'ru', 'Карри из свёклы с кокосовым молоком', 'Свёкла тушится в сливочном кокосовом соусе с луком, имбирём, чесноком, куркумой и зирой. Сладковатое землистое карри без мяса.', '<ol><li>В глубокой кастрюле на средне-сильном огне разогрейте масло, 2–3 минуты обжарьте листья карри, пока не станут ароматными.</li><li>Добавьте лук, куркуму, зиру, кориандр и перец чили, жарьте на среднем огне 10–12 минут до лёгкой золотистости.</li><li>Добавьте имбирь, чеснок и томатную пасту, готовьте 4 минуты до тёмно-красного цвета.</li><li>Добавьте дольки свёклы, бульон и кокосовое молоко, посолите. Доведите до слабого кипения и тушите на среднем огне 35–40 минут до мягкой свёклы.</li><li>Влейте сок лайма, отрегулируйте соль и подавайте.</li></ol><p><em>Подайте с рисом или лепёшкой и ложкой йогурта.</em></p>', CURRENT_TIMESTAMP),
  ('1f08a7d9-e105-53e0-9c9e-0a5c29f665c3', '225f0957-f000-57de-ac0e-94144c69a083', 'en', 'Beetroot coconut curry', 'Beetroot simmers in a creamy coconut sauce with onion, ginger, garlic, turmeric and cumin. A sweet, earthy meat-free curry.', '<ol><li>Heat the oil in a large deep pan over medium-high heat and fry the curry leaves 2–3 minutes until fragrant and popping.</li><li>Add the onion, turmeric, cumin, coriander and chilli powder and fry over medium heat 10–12 minutes until lightly browned.</li><li>Stir in the ginger, garlic and tomato purée and cook 4 minutes until fragrant and dark red.</li><li>Add the beetroot wedges, stock and coconut milk, season and bring to a gentle simmer. Cook over medium heat 35–40 minutes until the beetroot is tender.</li><li>Stir in the lime juice, adjust the seasoning and serve.</li></ol><p><em>Serve with rice or flatbread and a spoon of yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('38d8ea60-8d12-5c4f-9c64-e87ee5b82427', '7789344d-aea4-5f55-8268-23984effcbcd', 'ru', 'Овощной суп с кале, пастой, фасолью и перцем', 'Сытный томатный суп с луком, сельдереем, перцем, зелёной фасолью, капустой кале и цельнозерновыми пенне.', '<ol><li>В большой кастрюле на среднем огне разогрейте масло, 5 минут обжарьте лук и чеснок. Добавьте сельдерей и перец и жарьте ещё 5 минут, в последнюю минуту добавив паприку.</li><li>Влейте томаты, добавьте орегано и бульон, доведите до кипения.</li><li>Добавьте пенне, зелёную фасоль и кале, снова доведите до кипения и варите на среднем огне 10 минут.</li><li>Добавьте помидоры черри и базилик и готовьте ещё несколько минут, пока помидоры не лопнут. Разлейте по тарелкам и посыпьте сыром.</li></ol><p><em>Посыпьте тёртым твёрдым сыром.</em></p>', CURRENT_TIMESTAMP),
  ('5c399993-f73a-5056-a18f-68c076b3f0f2', '7789344d-aea4-5f55-8268-23984effcbcd', 'en', 'Kale pasta soup with peppers and green beans', 'A filling tomato soup with onion, celery, peppers, green beans, kale and wholemeal penne.', '<ol><li>Heat the oil in a large pan over medium heat and fry the onions and garlic 5 minutes. Add the celery and peppers and fry 5 minutes more, adding the paprika in the last minute.</li><li>Stir in the tomatoes, oregano and stock and bring to a boil.</li><li>Add the penne, green beans and kale, return to the boil and cook over medium heat for 10 minutes.</li><li>Add the cherry tomatoes and basil and cook a few minutes until the tomatoes burst. Serve topped with cheese.</li></ol><p><em>Sprinkle with grated hard cheese.</em></p>', CURRENT_TIMESTAMP),
  ('c1605a35-a2c9-5358-a23c-142c92158d60', '27c63e94-a666-5dcc-8bca-688e260d1924', 'ru', 'Треска, запечённая с помидорами черри и оливками, с фасолью и картофелем', 'Филе трески запекается на помидорах черри с оливками, базиликом и чесноком, подаётся с зелёной фасолью и молодым картофелем.', '<ol><li>Разогрейте духовку до 200 °C. Смешайте половинки помидоров черри с 2 ст. л. базилика, оливками, чесноком и 1 ст. л. оливкового масла в небольшой форме. Положите сверху треску и запекайте 15–18 минут до готовности рыбы.</li><li>Тем временем варите половинки картофеля в кастрюле 15 минут, над ней в пароварке приготовьте зелёную фасоль, пока всё не станет мягким.</li><li>Выложите фасоль на тарелки, сверху треску. Смешайте помидоры с соком, остатком базилика, оливковым маслом и бальзамическим уксусом.</li><li>Полейте рыбу помидорами и подавайте с картофелем и чёрным перцем.</li></ol><p><em>Полейте рыбу соком помидоров, заправленным бальзамическим уксусом.</em></p>', CURRENT_TIMESTAMP),
  ('dc2ef88a-cc60-5d8c-b479-76c83520d913', '27c63e94-a666-5dcc-8bca-688e260d1924', 'en', 'Cod baked with cherry tomatoes and olives, with green beans and new potatoes', 'Cod loins bake on cherry tomatoes with olives, basil and garlic, served with green beans and new potatoes.', '<ol><li>Heat the oven to 400 °F (200 °C). Toss the halved cherry tomatoes with 2 tablespoons of the basil, the olives, garlic and 1 tablespoon oil in a small roasting dish. Add the cod loins and bake 15–18 minutes until cooked through.</li><li>Meanwhile boil the halved potatoes 15 minutes in a pan with a steamer set on top for the green beans, until both are tender.</li><li>Arrange the beans on plates and top with the cod. Mix the tomatoes and their juices with the remaining basil, olive oil and balsamic vinegar.</li><li>Spoon the tomatoes over the fish and serve with the potatoes and cracked black pepper.</li></ol><p><em>Spoon the tomato juices dressed with balsamic vinegar over the fish.</em></p>', CURRENT_TIMESTAMP),
  ('b07fdcd9-b40a-5248-ac05-8193df0f31b1', '5fb4ce13-5115-57dd-933e-8c7b72d6ee31', 'ru', 'Веганский строганов из шампиньонов с овсяным молоком', 'Обжаренные до золотистого цвета шампиньоны в соусе из белого вина, овощного бульона, овсяного молока и копчёной паприки с лимоном.', '<ol><li>Разогрейте половину масла в глубокой сковороде на средне-сильном огне. Жарьте шампиньоны около 10 минут, изредка помешивая, до глубокого золотистого цвета. Переложите в миску.</li><li>Влейте остальное масло, 5–7 минут обжарьте лук и чеснок до лёгкой мягкости.</li><li>Всыпьте муку, горчичный порошок и оба вида паприки и готовьте пару минут. Понемногу влейте вино, каждый раз перемешивая, доведите до кипения и уварите вдвое.</li><li>Влейте бульон и овсяное молоко, верните грибы и варите 15–20 минут, пока соус не уварится. Посолите, поперчите, добавьте лимонный сок и посыпьте петрушкой.</li></ol><p><em>Подайте с отварным рисом или картофельным пюре, посыпав петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('def51240-708a-5669-9d93-8e4763843483', '5fb4ce13-5115-57dd-933e-8c7b72d6ee31', 'en', 'Vegan mushroom stroganoff with white wine and oat milk', 'Deeply browned mushrooms in a sauce of white wine, vegetable stock, oat drink and smoked paprika, brightened with lemon.', '<ol><li>Heat half the oil in a wide deep frying pan over medium-high heat. Cook the mushrooms about 10 minutes, stirring occasionally, until deeply browned. Transfer to a bowl.</li><li>Add the remaining oil and cook the onion and garlic 5–7 minutes over medium heat until slightly softened.</li><li>Stir in the flour, mustard powder and paprikas and cook a couple of minutes. Pour in the wine bit by bit, stirring after each addition, bring to a simmer and reduce by half.</li><li>Add the stock and oat drink, return the mushrooms and simmer 15–20 minutes until reduced. Season with salt, pepper and lemon juice and sprinkle with parsley.</li></ol><p><em>Serve over rice or mashed potato, sprinkled with parsley.</em></p>', CURRENT_TIMESTAMP),
  ('af104fb0-f196-5a6e-89f1-599f5f4c7cf4', 'fc70bf5d-6555-5a23-bfc5-3424934a87c6', 'ru', 'Свиные отбивные с кремовым луком-пореем и пармезаном', 'Румяные свиные отбивные, доведённые в духовке, подаются с пореем в сливках с пармезаном. Простой ужин, который готовится быстро.', '<ol><li>Разогрейте духовку до 180 °C. Посолите и поперчите отбивные, обжарьте на большой сковороде на среднем огне по 2–3 минуты с каждой стороны до румяности.</li><li>Переложите на противень и доведите в духовке 8–12 минут. Проверьте: сок из самой толстой части должен быть прозрачным.</li><li>Тем временем прогрейте масло в сковороде на среднем огне и 3–4 минуты обжарьте порей кружками до мягкости и лёгких подпалин.</li><li>Влейте сливки, доведите до кипения и варите минуту. Снимите с огня, добавьте пармезан и приправьте. Подавайте с отбивными.</li></ol><p><em>Подайте с картофельным пюре или полентой.</em></p>', CURRENT_TIMESTAMP),
  ('ab41b88c-4e81-5035-a48f-2d4694b36e7b', 'fc70bf5d-6555-5a23-bfc5-3424934a87c6', 'en', 'Pork chops with creamy leeks and Parmesan', 'Golden pork chops finished in the oven and served with leeks in cream and Parmesan. A quick and simple dinner.', '<ol><li>Heat the oven to 350 °F (180 °C). Season the chops and fry in a large pan over medium heat 2–3 minutes per side until nicely coloured.</li><li>Transfer to a baking tray and finish in the oven 8–12 minutes. The juices from the thickest part should run clear.</li><li>Meanwhile warm the oil in a pan over medium heat and cook the leek discs 3–4 minutes until softened and lightly charred.</li><li>Pour in the cream, bring to a simmer for 1 minute, take off the heat, stir in the Parmesan and season. Serve with the chops.</li></ol><p><em>Serve with mashed potatoes or polenta.</em></p>', CURRENT_TIMESTAMP),
  ('388734de-f958-509e-8736-8f11acf28b7f', 'b5a21d3e-3dc2-5694-9d55-22d6293ea7bf', 'ru', 'Пирог ковбоя: колбаски с печёной фасолью под сырным пюре', 'Запеканка из обжаренных колбасок с фасолью в томатном соусе с копчёной паприкой и барбекю под слоем картофельного пюре с чеддером.', '<ol><li>Для пюре отварите картофель в подсоленной воде 15–20 минут до мягкости, слейте, дайте паре улетучиться и разомните с маслом и молоком. Накройте крышкой.</li><li>Разогрейте духовку до 200 °C. Обжарьте лук на масле 6–8 минут до мягкости, добавьте нарезанные колбаски и жарьте 4 минуты до румяности.</li><li>Добавьте чеснок на минуту, затем копчёную паприку на минуту. Влейте фасоль и соус барбекю, прогрейте до начала кипения и снимите с огня.</li><li>Переложите смесь в форму 20×20 см, сверху выложите пюре и посыпьте тёртым чеддером.</li><li>Запекайте 25–30 минут, пока края не запузырятся, а сыр не зарумянится. Посыпьте шнитт-луком.</li></ol><p><em>Посыпьте зелёным луком или шнитт-луком.</em></p>', CURRENT_TIMESTAMP),
  ('7665fa53-a2ed-5cac-8025-d1f0a5edac5b', 'b5a21d3e-3dc2-5694-9d55-22d6293ea7bf', 'en', 'Cowboy pie with sausages, baked beans and cheesy mash', 'Browned sausages and baked beans in a smoky barbecue sauce, topped with cheddar mashed potatoes and baked until bubbling.', '<ol><li>For the mash, boil the potatoes in salted water 15–20 minutes until tender, drain, let steam dry a couple of minutes and mash with the butter and milk. Cover to keep warm.</li><li>Heat the oven to 400 °F (200 °C). Fry the onion in the oil 6–8 minutes until soft, add the cut sausages and fry 4 minutes until browned.</li><li>Add the garlic for a minute, then the smoked paprika for a minute. Pour in the beans and barbecue sauce, heat until just about to simmer and remove from the heat.</li><li>Spoon the sausage mixture into a 20×20 cm dish, top with the mash and sprinkle with grated cheddar.</li><li>Bake 25–30 minutes until bubbling at the edges and the cheese is golden. Scatter with chives.</li></ol><p><em>Scatter with chives.</em></p>', CURRENT_TIMESTAMP),
  ('6cf1b8ac-ab6d-565b-82e4-97366f4154b7', '8a0f360b-e6bc-50b5-a758-52999c37430c', 'ru', 'Гороховый суп-пюре с мятой и сырными палочками из слоёного теста', 'Бархатный суп из зелёного горошка, картофеля и мяты с хрустящими палочками из слоёного теста с чеддером для обмакивания.', '<ol><li>Разогрейте духовку до 200 °C. В большой кастрюле на среднем огне 6–8 минут обжарьте лук на масле до мягкости. Добавьте картофель и чеснок на пару минут, влейте бульон и варите 12–15 минут до мягкого картофеля.</li><li>Тем временем раскатайте тесто и нарежьте наискосок полосками разной ширины (палочки). Выложите на противень, посыпьте сыром и перцем и выпекайте 10–12 минут до золотистого цвета.</li><li>Добавьте в суп горошек и мяту и варите 5–8 минут, пока горошек не оттает и не станет мягким. Снимите с огня и пробейте погружным блендером.</li><li>Разлейте по тарелкам, посыпьте рубленой мятой и подавайте с палочками.</li></ol><p><em>Посыпьте суп листьями мяты и подавайте с палочками.</em></p>', CURRENT_TIMESTAMP),
  ('429987d8-9003-5e59-8f56-d583f8e4ee28', '8a0f360b-e6bc-50b5-a758-52999c37430c', 'en', 'Pea and mint soup with cheesy puff pastry wands', 'A velvety soup of green peas, potato and mint with crisp cheddar puff pastry wands for dunking.', '<ol><li>Heat the oven to 400 °F (200 °C). Fry the onion in the oil in a large pan over medium heat 6–8 minutes until soft, add the potato and garlic for a couple of minutes, pour in the stock and simmer 12–15 minutes until the potato is just tender.</li><li>Meanwhile unroll the pastry and cut slightly diagonal strips, thicker at one end, to make wands. Place on a baking tray, sprinkle with cheese and pepper and bake 10–12 minutes until golden.</li><li>Add the peas and mint to the soup and cook 5–8 minutes until the peas defrost and soften. Remove from the heat and blend with a hand blender.</li><li>Ladle into bowls, scatter over shredded mint and serve with the pastry wands.</li></ol><p><em>Scatter with shredded mint and serve with the wands.</em></p>', CURRENT_TIMESTAMP),
  ('f4b0a972-6fb2-5c03-9656-4761492f639a', '41612932-5d87-5ddf-924e-707b11d6e7a2', 'ru', 'Кёфте из красной чечевицы и булгура с овощным салатом (воспов кёфте)', 'Постные армянские котлетки-шарики из красной чечевицы, булгура и жареного лука. Подаются со свежим сочным салатом из помидоров, огурца, перца и зелени.', '<ol><li>Для салата смешайте все ингредиенты и отставьте. Салат должен получиться очень сочным.</li><li>В большой кастрюле доведите чечевицу с водой до кипения на сильном огне. Убавьте огонь и варите, не полностью накрыв крышкой, 15–20 минут, пока чечевица не станет очень мягкой. Жидкости останется много. Посолите.</li><li>Тем временем разогрейте масло на сковороде на среднем огне и пассеруйте лук около 7 минут до мягкости и прозрачности.</li><li>Всыпьте в чечевицу булгур, перемешайте, добавьте жареный лук. Накройте и оставьте на 20–25 минут и больше, пока булгур не впитает лишнюю жидкость и не станет мягким.</li><li>Когда масса нужной консистенции, вымесите её деревянной ложкой, добавьте половину зелёного лука, остальную соль и перец. Хорошо перемешайте и дайте остыть до удобной для лепки температуры.</li><li>Смачивая руки тёплой водой, формуйте небольшие продолговатые кёфте (около 16–18 штук), слегка сжимая в кулаке, чтобы остались следы пальцев. Можно использовать ложку для мороженого.</li><li>Посыпьте паприкой, оставшимся зелёным луком и петрушкой и подавайте с салатом.</li></ol><p><em>Посыпьте паприкой, зелёным луком и петрушкой и подайте с салатом.</em></p>', CURRENT_TIMESTAMP),
  ('e092d88b-a932-5b33-b9e8-29ee9a886f91', '41612932-5d87-5ddf-924e-707b11d6e7a2', 'en', 'Armenian red lentil and bulgur kofte with chopped salad', 'Vegan Armenian lentil and bulgur balls with sautéed onion, served with a juicy fresh salad of tomato, cucumber, pepper and herbs.', '<ol><li>For the salad, mix all the ingredients together and set aside. It should be very juicy.</li><li>In a large pot bring the lentils and water to a boil over high heat. Reduce the heat and simmer partially covered 15–20 minutes until very tender. A lot of liquid will remain. Season with salt.</li><li>Meanwhile heat the oil in a skillet over medium heat and cook the onion about 7 minutes until soft and translucent.</li><li>Stir the bulgur into the lentils, add the cooked onions, cover and set aside 20–25 minutes or more until the bulgur absorbs the liquid and is tender.</li><li>When the texture is right, knead with a wooden spoon, mix in half the scallions, the remaining salt and pepper. Mix thoroughly and let cool enough to shape.</li><li>With hands dipped in warm water, shape small oblong kofte (about 16–18), lightly squeezing in your fist to leave finger imprints. An ice cream scoop works too.</li><li>Dust with paprika, then top with the remaining scallions and parsley and serve with the salad.</li></ol><p><em>Garnish with paprika, scallions and parsley and serve with the salad.</em></p>', CURRENT_TIMESTAMP),
  ('92c4970e-f644-56d9-bbde-8fc50de9c24e', '48049bf5-2e0c-5db7-ac1f-d3ec9b7d0347', 'ru', 'Ямайский рис с красной фасолью на кокосовом молоке', 'Классический гарнир карибской кухни: красная фасоль и длиннозёрный рис, сваренные в кокосовом молоке с луком, чесноком, имбирём, тимьяном и душистым перцем.', '<ol><li>Замоченную на ночь (не менее 8 часов) красную фасоль слейте, промойте, переложите в кастрюлю и залейте водой. Доведите до кипения на средне-сильном огне.</li><li>Добавьте кокосовое молоко, лук, зелёный лук, чеснок, имбирь, целый острый перец, тимьян, душистый перец, соль и чёрный перец. Доведите до кипения, накройте, убавьте огонь и варите 35–40 минут, пока фасоль не станет почти мягкой (не переварите).</li><li>Всыпьте рис, добавьте ещё соли, доведите до кипения, накройте и готовьте на слабом огне 25–30 минут, пока вся жидкость не впитается, а рис не станет мягким.</li><li>Снимите с огня и, не открывая крышку, оставьте на 10 минут. Выбросьте острый перец, ветки тимьяна и душистый перец, взрыхлите вилкой, при необходимости досолите. Посыпьте зелёным луком.</li></ol><p><em>Выньте чили, веточки тимьяна и перец горошком перед подачей. Подходит к курице джерк, карри и тушёным блюдам.</em></p>', CURRENT_TIMESTAMP),
  ('a922ed7f-1681-5538-a55a-885f6d2ca7ba', '48049bf5-2e0c-5db7-ac1f-d3ec9b7d0347', 'en', 'Jamaican rice and peas with kidney beans and coconut milk', 'A classic Caribbean side of kidney beans and long grain rice cooked in coconut milk with onion, garlic, ginger, thyme and allspice.', '<ol><li>Place the overnight-soaked (8+ hours), rinsed kidney beans in a pot and cover with the water. Bring to a boil over medium-high heat.</li><li>Stir in the coconut milk, onion, scallions, garlic, ginger, whole hot pepper, thyme, allspice, salt and black pepper. Bring to a simmer, cover, lower the heat and cook 35–40 minutes until the beans are just tender (don''t overcook).</li><li>Add the rice and a bit more salt, return to a simmer, cover and cook over low heat 25–30 minutes until all liquid is absorbed and the rice is tender.</li><li>Remove from the heat and rest covered 10 minutes. Discard the hot pepper, thyme stems and allspice berries, fluff with a fork and adjust the salt. Garnish with scallions.</li></ol><p><em>Remove the chili, thyme stems and allspice berries before serving. Goes well with jerk chicken, curry or stews.</em></p>', CURRENT_TIMESTAMP),
  ('be9ab3be-adbb-58aa-9d01-d4833c4f3f6c', '55e4929f-e320-517b-b0e9-61e85a76d451', 'ru', 'Арроз кальдосо с курицей: испанский суповой рис с шафраном', 'Рис с курицей в густом ароматном бульоне: бёдра томятся с томатами, луком, вином и шафраном, а рис варится прямо в бульоне вместе с пикадой из миндаля и петрушки. Нечто среднее между супом и рагу.', '<ol><li>Снимите с курицы кожу и посолите мясо.</li><li>В кастрюле с толстым дном разогрейте масло на среднем огне и обжарьте курицу мясной стороной вниз 7–9 минут до лёгкой румяности.</li><li>Переверните курицу, добавьте лук и перец и готовьте около 3 минут до мягкости.</li><li>Добавьте тёртые помидоры и готовьте 3 минуты, затем чеснок на минуту. Влейте вино и варите на слабом огне 10 минут.</li><li>Залейте водой, обильно посолите, доведите до кипения, убавьте огонь и тушите без крышки около 45 минут, пока курица не станет мягкой, а жидкость не уварится.</li><li>Для пикады измельчите миндальную муку (или миндаль) с петрушкой и 2–3 ст. л. кипящего бульона до гладкости.</li><li>Попробуйте бульон на соль. Всыпьте рис, шафран (разотрите пальцами) и добавьте пикаду. Варите без крышки 14–16 минут, пока рис не станет почти мягким, оставив лёгкую упругость.</li><li>Снимите с огня, накройте и оставьте на 3–4 минуты. Разлейте по тарелкам и подавайте сразу.</li></ol><p><em>Подавайте сразу: чем дольше стоит, тем больше рис впитывает жидкости.</em></p>', CURRENT_TIMESTAMP),
  ('f872f83c-9bcf-5bf5-aed6-6fa4093ee208', '55e4929f-e320-517b-b0e9-61e85a76d451', 'en', 'Arroz caldoso de pollo: Spanish soupy rice with chicken and saffron', 'Rice and chicken in a rich broth: thighs braised with tomatoes, onion, wine and saffron, with rice cooked right in the broth with an almond and parsley picada. Between a soup and a stew.', '<ol><li>Remove the skin from the chicken and season with salt.</li><li>In a heavy pot heat the oil over medium heat and brown the chicken flesh-side down 7–9 minutes.</li><li>Flip the chicken, add the onion and pepper and cook about 3 minutes until softened.</li><li>Add the grated tomatoes and cook 3 minutes, then the garlic for 1 minute. Pour in the wine and simmer 10 minutes.</li><li>Cover with water, season generously, bring to a boil, lower the heat and simmer uncovered about 45 minutes until the chicken is tender and the liquid has reduced.</li><li>For the picada, blend the almond meal (or almonds), parsley and 2–3 tbsp of the simmering liquid until smooth.</li><li>Taste the broth for salt. Sprinkle in the rice and the saffron, crushing it between your fingers, and stir in the picada. Cook uncovered 14–16 minutes until the rice is nearly tender with some bite.</li><li>Remove from the heat, cover and let sit 3–4 minutes. Ladle into bowls and serve immediately.</li></ol><p><em>Serve immediately; the rice keeps absorbing broth the longer it sits.</em></p>', CURRENT_TIMESTAMP),
  ('b0ad5234-c852-526b-9916-460a8edda737', '9df21652-e885-5fc0-8fbe-d44a49ed5c47', 'ru', 'Куриное рагу с овощами и клёцками на кефире', 'Лёгкая версия американского блюда: рагу из курицы с морковью, сельдереем, луком и горошком, покрытое воздушными клёцками на пахте (кефире).', '<ol><li>Обсушите курицу, посолите и поперчите со всех сторон. Разогрейте масло в большой кастрюле почти до дымка и обжарьте курицу со всех сторон около 8 минут. Переложите на тарелку и снимите кожу.</li><li>В оставшийся жир добавьте морковь, лук, сельдерей и щепотку соли. Накройте и готовьте на среднем и слабом огне 8–10 минут до мягкости. Влейте вино, счистите осадок со дна.</li><li>Добавьте бульон, тимьян и курицу с соком. Доведите до кипения, убавьте огонь, накройте и готовьте 20–25 минут, пока курица не достигнет 71 °C.</li><li>Снимите с огня, остудите курицу, разберите на крупные куски, выбросьте кости и верните мясо в кастрюлю.</li><li>Для клёцек смешайте муку, сахар, соль и соду. В другой миске размешайте холодную пахту (кефир) с горячим растопленным маслом, чтобы масло свернулось в комочки, и вмешайте яичный белок. Соедините с мукой лопаткой до однородности. Тесто должно быть довольно плотным.</li><li>Доведите рагу до кипения, добавьте горошек и петрушку, посолите, поперчите. Смазанной ложкой выкладывайте клёцки сверху на небольшом расстоянии друг от друга.</li><li>Накройте крышкой, обернув её кухонным полотенцем (не рядом с огнём), чтобы конденсат не капал на клёцки. Готовьте на слабом огне 13–16 минут, пока клёцки не увеличатся вдвое. Подавайте сразу.</li></ol><p><em>Подавайте сразу, пока клёцки пышные.</em></p>', CURRENT_TIMESTAMP),
  ('d58ce37d-6b49-5652-9717-1f62d476731f', '9df21652-e885-5fc0-8fbe-d44a49ed5c47', 'en', 'Chicken and buttermilk dumplings stew with carrots and peas', 'A lighter version of the American classic: shredded chicken stew with carrots, celery, onion and peas topped with fluffy buttermilk dumplings.', '<ol><li>Pat the chicken dry and season on all sides. Heat the oil in a large Dutch oven until just smoking and brown the chicken well, about 8 minutes. Transfer to a plate and remove the skin.</li><li>Add the carrots, onions, celery and a pinch of salt to the fat. Cover and cook over medium-low heat 8–10 minutes until soft. Add the wine, scraping up any browned bits.</li><li>Add the broth, thyme and chicken with its juices. Bring to a simmer, then reduce, cover and cook 20–25 minutes until the chicken reaches 71°C (160°F).</li><li>Remove from the heat, let the chicken cool, shred into large pieces, discard the bones and return the meat to the pot.</li><li>For the dumplings, whisk the flour, sugar, salt and baking soda. In another bowl stir the chilled buttermilk and hot melted butter until the butter forms clumps, then whisk in the egg white. Fold into the flour just until combined. The dough should be fairly firm.</li><li>Return the stew to a simmer, stir in the peas and parsley and season. Using a greased tablespoon, drop the dumplings on top, spaced apart.</li><li>Cover with the lid wrapped in a clean kitchen towel (away from the flame) so condensation doesn''t drip on the dumplings. Cook over low heat 13–16 minutes until doubled in size. Serve immediately.</li></ol><p><em>Serve right away while the dumplings are fluffy.</em></p>', CURRENT_TIMESTAMP),
  ('1edce982-a864-5a9a-aa4b-581dc44b4a59', '13b92377-661b-5071-a85e-3dc71e6135fd', 'ru', 'Чесночный суп по-чешски (чеснечка) с картофелем и ржаными гренками', 'Очень чесночный чешский суп на бульоне с картофелем, майораном и тмином, с хрустящими ржаными гренками и сыром. Согревает в холода.', '<ol><li>Растопите масло в кастрюле на среднем огне, добавьте раздавленный чеснок и готовьте 4–5 минут до мягкости и аромата (при подгорании убавьте огонь). Влейте бульон и доведите до кипения.</li><li>Посолите и поперчите, добавьте нарезанный кубиками картофель, майоран и тмин. Убавьте огонь и варите под крышкой 15–20 минут до мягкости картофеля.</li><li>При желании влейте взбитое яйцо тонкой струйкой, помешивая, чтобы образовались ленточки (как в яичном супе).</li><li>Тем временем разогрейте духовку до 180 °C. Нарежьте ржаной хлеб кубиками, сбрызните маслом и обжарьте в духовке 10–15 минут до золотистой хрустящей корочки, иногда помешивая.</li><li>Подавайте суп с гренками и петрушкой, добавив сыр по желанию.</li></ol><p><em>Положите сыр в тарелку и залейте горячим супом, сверху гренки и петрушка.</em></p>', CURRENT_TIMESTAMP),
  ('77ad6458-d334-573f-801a-bb1e93e48d4c', '13b92377-661b-5071-a85e-3dc71e6135fd', 'en', 'Česnečka: Czech garlic soup with potatoes and rye croutons', 'An extremely garlicky Czech soup in broth with potatoes, marjoram and caraway, topped with crisp rye croutons and cheese. Comforting in cold weather.', '<ol><li>Melt the butter in a pan over medium heat and add the crushed garlic. Cook 4–5 minutes until soft and aromatic (lower the heat if it browns). Add the broth and bring to a boil.</li><li>Season with salt and pepper, add the diced potatoes, marjoram and caraway. Reduce the heat and simmer covered 15–20 minutes until the potatoes are tender.</li><li>If using the egg, pour it in slowly while stirring to form ribbons, as in egg drop soup.</li><li>Meanwhile heat the oven to 180°C (350°F). Toss the cubed rye bread with olive oil and toast 10–15 minutes until golden and crisp, stirring occasionally.</li><li>Serve the soup topped with croutons and parsley, with cheese if you like.</li></ol><p><em>Put the cheese in the bowl first and pour the hot soup over, then top with croutons and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('6a21f1be-3bfc-567b-b56f-fa807fd4ab32', 'b144fc98-7171-55b5-a167-6e484fcb0d00', 'ru', 'Швейцарский сырный суп с картофелем, макаронами и шпинатом', 'Сливочный суп с картофелем, мелкими макаронами и шпинатом, который заправляется тёртым грюйером и сливками. Готовится меньше получаса.', '<ol><li>В кастрюле на среднем огне растопите масло и обжарьте лук около 5 минут до мягкости. Добавьте картофель и помешивайте 20–30 секунд.</li><li>Влейте овощной бульон, доведите до кипения на сильном огне, посолите и поперчите. Убавьте огонь, накройте не полностью и варите 8 минут.</li><li>Добавьте макароны и варите ещё около 8 минут, пока макароны и картофель не станут мягкими.</li><li>Добавьте отжатый размороженный шпинат, сливки и грюйер. Хорошо перемешайте, чтобы сыр растворился. Проверьте приправы и подавайте сразу.</li></ol><p><em>Хорошо перемешайте, чтобы сыр равномерно растворился в бульоне, и подавайте сразу.</em></p>', CURRENT_TIMESTAMP),
  ('a0a09f62-8029-51aa-9af1-b0e20ee97a06', 'b144fc98-7171-55b5-a167-6e484fcb0d00', 'en', 'Swiss chalet soup with potato, macaroni, spinach and gruyère', 'A creamy soup of potatoes, small macaroni and spinach finished with grated gruyère and cream. Ready in under 30 minutes.', '<ol><li>Melt the butter in a pot over medium heat and cook the onion about 5 minutes until soft. Add the potatoes and stir 20–30 seconds.</li><li>Add the vegetable stock, bring to a boil over high heat and season. Lower the heat, partially cover and simmer 8 minutes.</li><li>Add the macaroni and cook about 8 more minutes until the macaroni and potatoes are tender.</li><li>Stir in the squeezed thawed spinach, cream and grated gruyère. Stir well so the cheese melts evenly, adjust the seasoning and serve immediately.</li></ol><p><em>Stir well so the cheese melts evenly and serve immediately.</em></p>', CURRENT_TIMESTAMP),
  ('633ef5d1-33f7-5495-baec-f20dc008b34e', '7f0a8f40-8820-5809-ad0e-ba421350e22f', 'ru', 'Австрийский картофельный салат на бульоне с уксусом', 'Картофельный салат без майонеза: тёплый картофель заправляется горячей смесью из выпаренного бульона, винного уксуса и горчицы, с красным луком и шнитт-луком.', '<ol><li>Хорошо вымойте картофель, не очищая. Положите в кастрюлю, залейте холодной подсоленной водой, доведите до кипения и варите 20–30 минут, пока вилка не будет входить легко. Не переваривайте.</li><li>Тем временем доведите бульон до кипения в небольшой кастрюле и упарьте наполовину, около 20–25 минут, до примерно 160 мл. Сразу добавьте уксус, горчицу и сахар. Держите горячим.</li><li>Слейте картофель, остудите, пока его можно держать в руках, очистите тёплым и нарежьте кружками по 6 мм в большую миску.</li><li>Влейте горячую смесь бульона и уксуса, добавьте красный лук, соль и перец, перемешайте. Добавьте масло и перемешайте снова, чтобы крахмал загустил заправку.</li><li>Оставьте при комнатной температуре на 30 минут, помешивая каждые 10 минут. Добавьте шнитт-лук, попробуйте и подайте тёплым, комнатной температуры или холодным.</li></ol><p><em>Подавайте тёплым к шницелю или другому мясу, либо охлаждённым.</em></p>', CURRENT_TIMESTAMP),
  ('dd8f2752-83a6-5a24-b20f-b694981d6d10', '7f0a8f40-8820-5809-ad0e-ba421350e22f', 'en', 'Erdäpfelsalat: Austrian potato salad with broth and vinegar', 'A mayonnaise-free potato salad: warm potatoes dressed in a hot reduced broth, wine vinegar and mustard with red onion and chives.', '<ol><li>Wash the potatoes well but don''t peel. Put in a pot, cover with cold salted water, bring to a boil and cook 20–30 minutes until a fork pierces easily. Don''t overcook.</li><li>Meanwhile boil the broth in a small saucepan and reduce by half, about 20–25 minutes, to about 160 ml. Immediately stir in the vinegar, mustard and sugar. Keep hot.</li><li>Drain the potatoes, cool until just handleable but still warm, peel and slice 6 mm thick into a large bowl.</li><li>Pour the hot broth-vinegar mixture over the warm potatoes, add the red onion, salt and pepper and stir. Add the oil and stir again so the starch thickens the dressing.</li><li>Rest at room temperature 30 minutes, stirring every 10 minutes. Stir in the chives, taste and serve warm, room temperature or cold.</li></ol><p><em>Serve warm with schnitzel or other meat, or chilled.</em></p>', CURRENT_TIMESTAMP),
  ('e553bded-404c-564a-b085-b0a2143d2ade', '60b7c3e3-0f33-5912-8f15-9cfadfa2b553', 'ru', 'Сливочный суп-чаудер с ветчиной, кукурузой и картофелем', 'Густой сытный суп на молоке и курином бульоне с картофелем, кукурузой и обжаренной ветчиной. Подходит для остатков праздничной ветчины.', '<ol><li>В большой кастрюле на среднем огне растопите масло. Обжарьте лук с чесноком 5 минут до прозрачности, не давая лук зарумяниться.</li><li>Всыпьте муку и взбейте с маслом. Влейте 1 стакан молока и взбивайте до загустения, около 1,5 минут, затем влейте остальное молоко и взбивайте ещё 1–1,5 минуты. Добавьте бульон и 350 мл воды и перемешайте.</li><li>Увеличьте огонь до средне-сильного, положите картофель и варите 10–12 минут, часто помешивая, чтобы суп не пригорел. При необходимости подливайте оставшуюся воду.</li><li>Незадолго до готовности картофеля добавьте кукурузу, чтобы она прогрелась.</li><li>Пока варится картофель, обжарьте ветчину в масле на сильном огне 1–2 минуты до румяности и отставьте.</li><li>Когда картофель мягкий, но держит форму, снимите суп с огня и вмешайте тимьян и большую часть ветчины. При необходимости разбавьте водой или молоком, посолите и поперчите. Подавайте с оставшейся ветчиной и тимьяном.</li></ol><p><em>Посыпьте тимьяном и ветчиной. Для большей питательности добавьте замороженные овощи вместе с кукурузой.</em></p>', CURRENT_TIMESTAMP),
  ('482d3eac-f76c-5221-b054-afef8cb396a7', '60b7c3e3-0f33-5912-8f15-9cfadfa2b553', 'en', 'Creamy ham, corn and potato chowder', 'A thick, hearty soup of milk and chicken stock with potatoes, corn and sautéed ham. A good use for leftover holiday ham.', '<ol><li>Melt the butter in a large saucepan over medium heat. Cook the onion and garlic for 5 minutes until translucent, without browning.</li><li>Add the flour and whisk into the butter. Pour in 1 cup of milk and whisk until it starts to thicken (about 1½ minutes), then add the remaining milk and whisk 1–1½ minutes more. Add the chicken stock and about 350 ml of water.</li><li>Increase the heat to medium-high, add the potatoes and cook 10–12 minutes, whisking regularly so it doesn''t stick. Add the remaining water if too thick.</li><li>Just before the potato is cooked, add the corn to heat through.</li><li>While the potato cooks, sauté the ham in the olive oil over high heat 1–2 minutes until browned and set aside.</li><li>When the potato is tender but holds its shape, remove from the heat and stir in most of the thyme and ham. Thin with water or milk if needed, season, and serve garnished with the rest of the ham and thyme.</li></ol><p><em>Garnish with thyme and ham. Add frozen mixed vegetables with the corn for a more complete meal.</em></p>', CURRENT_TIMESTAMP),
  ('b0f35d33-0822-5970-821c-1eab7f7c53ee', '5a244346-ed8f-52ac-88fd-cb59cfa6aa3c', 'ru', 'Рис с курицей, имбирём и грибами в одной кастрюле (по-гонконгски)', 'Рис с кусочками куриных бёдер, имбирём и слоем обжаренных грибов, который пропаривается под крышкой, как в гонконгском глиняном горшке. В конце поливается соусом.', '<ol><li>Смешайте кечап манис, рыбный соус и белый перец. Обваляйте курицу в 1,5 ст. л. этого соуса, остальное оставьте для поливки.</li><li>Разогрейте в большой кастрюле с толстым дном 1,5 ст. л. масла на сильном огне. Слегка обжарьте половину грибов с щепоткой соли и белого перца до лёгкого румянца (до конца готовить не нужно), переложите в миску. Так же обжарьте вторую половину.</li><li>Разогрейте оставшееся масло, обжарьте курицу в течение минуты до схватывания поверхности (внутри ещё сырая). Добавьте белую часть зелёного лука, чеснок и тёртый имбирь на 30 секунд. Всыпьте рис и перемешайте в масле, не промывая его.</li><li>Влейте бульон, добавьте ломтики имбиря и доведите до интенсивного кипения. Выложите сверху грибы с накопившимся соком и снова доведите до кипения.</li><li>Накройте крышкой, убавьте огонь до слабого и готовьте 20 минут, не помешивая, пока жидкость не впитается. Снимите с плиты и оставьте под крышкой на 10 минут.</li><li>Полейте оставшимся соусом, добавьте зелёную часть лука и аккуратно перемешайте, пока лук не слегка завянет. Подавайте.</li></ol><p><em>Выньте ломтики имбиря перед подачей. Подойдут любые грибы.</em></p>', CURRENT_TIMESTAMP),
  ('38efdc6d-685d-52ef-a858-948e1cba6c8f', '5a244346-ed8f-52ac-88fd-cb59cfa6aa3c', 'en', 'One-pot ginger chicken rice with mushrooms (Hong Kong claypot style)', 'Rice with bite-size chicken thighs and ginger, steamed under a layer of seared mushrooms like Hong Kong claypot rice and finished with a sauce drizzle.', '<ol><li>Mix the kecap manis, fish sauce and white pepper. Toss the chicken with 1½ tbsp of this sauce and keep the rest for drizzling.</li><li>Heat 1½ tbsp of oil in a large heavy pot on high heat. Lightly sear half the mushrooms with a pinch of salt and white pepper until tinged golden (not cooked through) and remove. Repeat with the rest.</li><li>Heat the remaining oil and stir the chicken for 1 minute until the surface is sealed. Add the white green onion, garlic and grated ginger for 30 seconds, then add the unrinsed rice and stir to coat.</li><li>Add the stock and ginger slices and bring to a rapid simmer. Scatter the mushrooms and their juices on top and return to a rapid simmer.</li><li>Cover, reduce the heat to low and cook 20 minutes without stirring until the liquid is absorbed. Remove from the heat and rest covered 10 minutes.</li><li>Drizzle with the remaining sauce, add the green onion tops and toss gently until slightly wilted. Serve.</li></ol><p><em>Pick out the ginger slices before serving. Any mushrooms work.</em></p>', CURRENT_TIMESTAMP),
  ('e5714c72-0d96-5b3d-a936-7690dc4e0b67', 'ca0fe570-4841-58d8-b5c6-7cb3cff08fae', 'ru', 'Рис с копчёными колбасками, перцем и горошком в одной кастрюле', 'Быстрый ужин в духе джамбалайи без острых специй: копчёные колбаски, лук, сладкий перец и рис, сваренные в курином бульоне. Горошек добавляется в конце.', '<ol><li>Разогрейте в большой кастрюле с толстым дном 2 ст. л. масла на средне-сильном огне и обжарьте нарезанные колбаски до золотистого цвета. Выньте шумовкой.</li><li>Влейте оставшееся масло, добавьте чеснок и лук на 2 минуты, затем перец на ещё 2 минуты, пока лук не станет прозрачным.</li><li>Добавьте рис, бульон, паприку, соль, перец и колбаски. Перемешайте, доведите до кипения и убавьте огонь, чтобы бульон едва кипел.</li><li>Накройте крышкой и готовьте 20 минут.</li><li>Снимите кастрюлю с огня, быстро откройте, высыпьте разморозившийся горошек и сразу закройте. Оставьте на 10 минут: остаточное тепло приготовит горошек.</li><li>Добавьте петрушку, взрыхлите рис вилкой и подавайте сразу.</li></ol><p><em>Посыпьте петрушкой и подавайте сразу. Можно взять любые копчёные колбаски или чоризо.</em></p>', CURRENT_TIMESTAMP),
  ('b8fb637e-9510-5006-b478-a32dfa6a9924', 'ca0fe570-4841-58d8-b5c6-7cb3cff08fae', 'en', 'One-pot smoked sausage and rice with peppers and peas', 'A quick, jambalaya-style dinner without the heat: smoked sausage, onion, sweet peppers and rice cooked in chicken stock, with peas folded in at the end.', '<ol><li>Heat 2 tbsp of oil in a large heavy pot over medium-high heat and brown the sliced sausages. Remove with a slotted spoon.</li><li>Add the remaining oil, then the garlic and onion for 2 minutes, then the peppers for 2 minutes until the onion is translucent.</li><li>Add the rice, stock, paprika, salt, pepper and sausage. Stir, bring to a boil, then reduce so it simmers very gently.</li><li>Cover and cook for 20 minutes.</li><li>Remove from the heat, quickly lift the lid, add the thawed peas and replace the lid. Rest 10 minutes; the residual heat will cook the peas.</li><li>Add the parsley, fluff the rice with a fork and serve immediately.</li></ol><p><em>Sprinkle with parsley and serve right away. Any smoked sausage or chorizo works.</em></p>', CURRENT_TIMESTAMP),
  ('77fa1c6f-d2af-5b39-956d-8b36d4a52b66', 'e35105b8-77b1-5ce0-bd9e-cf2be9e95c4b', 'ru', 'Запеканка из пасты с тунцом и кукурузой под сливочным соусом', 'Паста с консервированным тунцом и сладкой кукурузой в сливочном соусе бешамель с пармезаном, запечённая под хрустящей панировкой.', '<ol><li>Разогрейте духовку до 180 °C. Смешайте ингредиенты хрустящей посыпки.</li><li>Отварите пасту на 1 минуту меньше, чем указано на упаковке, слейте, слегка остудите и верните в кастрюлю.</li><li>Для соуса растопите масло в большой кастрюле на среднем огне, 30 секунд обжарьте чеснок, всыпьте муку и перемешайте. Постепенно влейте треть молока, вмешайте и добавьте остальное молоко, взбивая.</li><li>Добавьте бульонный порошок, горчичный, луковый и чесночный порошки и взбейте. Когда молоко нагреется, постоянно взбивайте, чтобы соус не пригорел.</li><li>Через 4–5 минут соус должен загустеть так, чтобы след на ложке оставался. Снимите с огня и вмешайте пармезан.</li><li>Добавьте к пасте тунец, разломав крупными кусками вилкой, затем кукурузу. Залейте соусом и аккуратно перемешайте.</li><li>Переложите в форму, сверху посыпьте хрустящей посыпкой. Запекайте 25 минут, пока верх не зарумянится, а края не забулькают.</li></ol><p><em>Посыпьте зелёным луком или петрушкой и подавайте горячей.</em></p>', CURRENT_TIMESTAMP),
  ('8279d7cf-ea03-54cb-ac73-c08a7eafd618', 'e35105b8-77b1-5ce0-bd9e-cf2be9e95c4b', 'en', 'Tuna mornay: creamy tuna pasta bake with corn and parmesan', 'Pasta with canned tuna and sweet corn in a creamy parmesan white sauce, baked under a crunchy breadcrumb topping.', '<ol><li>Preheat the oven to 180°C (350°F). Mix the crunchy topping ingredients.</li><li>Cook the pasta 1 minute less than the pack says, drain, cool slightly and return to the pot.</li><li>For the sauce, melt the butter in a large pot over medium heat, cook the garlic 30 seconds, stir in the flour. Gradually pour in about a third of the milk, whisk in, then add the rest of the milk.</li><li>Add the stock powder, mustard, onion and garlic powders and whisk. When the milk heats, whisk constantly so the sauce doesn''t catch.</li><li>After 4–5 minutes the sauce should coat the back of a spoon with a visible trail. Remove from the heat and stir in the parmesan.</li><li>Add the tuna to the pasta, flaking in large chunks with a fork, then the corn. Pour over the sauce and gently stir.</li><li>Scrape into a baking dish and cover with the crunchy topping. Bake 25 minutes until golden on top and bubbling at the edges.</li></ol><p><em>Sprinkle with chives or parsley and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('650c6cc1-3cfa-5feb-a00a-1e1442589722', 'b2149457-6716-582b-be4c-79fd1f11b97b', 'ru', 'Быстрая паста с брокколи, лимоном и пармезаном', 'Паста с большим количеством брокколи, сыра и заправкой из оливкового масла, лимона, чеснока и хлопьев чили, перемешанной с водой от пасты. Готовится за 15 минут.', '<ol><li>Вскипятите большую кастрюлю воды с 2 ч. л. соли и положите пасту.</li><li>Разделите брокколи на мелкие соцветия и добавьте в воду за 1–2 минуты до готовности пасты.</li><li>Положите ингредиенты соуса в банку с крышкой.</li><li>Перед тем как слить, зачерпните 1 стакан воды от пасты. Слейте пасту с брокколи и верните в ту же кастрюлю на выключенную плиту.</li><li>Влейте в банку 120 мл воды от пасты и хорошо встряхните. Вылейте соус на пасту, добавьте тёртый сыр и энергично перемешайте, при необходимости подливая воду. Досолите, поперчите и подавайте с пармезаном.</li></ol><p><em>Посыпьте ещё пармезаном. Подходит и как гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('2d63bbad-7903-5b1f-9979-2301027388c9', 'b2149457-6716-582b-be4c-79fd1f11b97b', 'en', 'Really quick broccoli pasta with lemon and parmesan', 'Pasta with lots of broccoli and cheese in a dressing of olive oil, lemon, garlic and chili flakes loosened with pasta water. Ready in 15 minutes.', '<ol><li>Boil a large pot of water with 2 tsp salt and cook the pasta.</li><li>Cut the broccoli into small florets and add to the water 1–2 minutes before the pasta is done.</li><li>Put the sauce ingredients in a jar with a lid.</li><li>Scoop out 1 cup of pasta water just before draining. Drain the pasta and broccoli and return to the pot on the turned-off stove.</li><li>Add ½ cup of pasta water to the jar and shake well. Pour the sauce over the pasta, add the cheese and stir vigorously, adding more pasta water if needed. Season and serve with parmesan.</li></ol><p><em>Top with more parmesan. Also works as a side.</em></p>', CURRENT_TIMESTAMP),
  ('af15c255-2ad4-5b50-b997-929fc7c098a3', 'a662693e-b348-5b90-b6ef-01553efc044c', 'ru', 'Сливочный суп-пюре из корнеплодов с карри', 'Нежный суп из картофеля, батата, моркови, пастернака и сельдерея-корня на воде, без бульона. Карри и тимьян придают вкус, а немного сливок делают его бархатистым.', '<ol><li>В большой кастрюле с толстым дном растопите масло оливковое со сливочным на средне-сильном огне и обжарьте лук с чесноком 2 минуты до мягкости.</li><li>Добавьте нарезанные корнеплоды, тимьян и карри и готовьте 3 минуты, помешивая, пока овощи не начнут размягчаться снаружи.</li><li>Включите сильный огонь, влейте воду, добавьте соль и перец. Когда закипит, убавьте до средне-сильного и варите без крышки 15 минут, пока овощи не станут мягкими.</li><li>Влейте сливки и варите минуту.</li><li>Снимите с огня и пюрируйте погружным блендером до однородности. Разбавьте водой, при необходимости досолите.</li><li>Разлейте по тарелкам, сбрызните сливками, посыпьте щепоткой карри, петрушкой и перцем.</li></ol><p><em>Подавайте с тёплым хлебом, каплей сливок, щепоткой карри и петрушкой.</em></p>', CURRENT_TIMESTAMP),
  ('bce8a79e-a5cb-5bc8-9c8a-78216b5dcb94', 'a662693e-b348-5b90-b6ef-01553efc044c', 'en', 'Creamy root vegetable soup with curry, parsnip and celeriac', 'A velvety soup of potato, sweet potato, carrot, parsnip and celeriac made with water, not stock. Curry powder and thyme add flavour and a little cream adds richness.', '<ol><li>In a large heavy pot, heat the olive oil and butter over medium-high heat and cook the onion and garlic 2 minutes until softened.</li><li>Add the root vegetables, thyme and curry powder and cook 3 minutes, stirring, until the outsides start to soften.</li><li>Turn to high, add the water, salt and pepper. Once simmering, lower to medium-high and simmer rapidly uncovered for 15 minutes until the vegetables are soft.</li><li>Stir in the cream and simmer 1 minute.</li><li>Remove from the heat and purée with a stick blender until smooth. Thin with water and adjust the seasoning.</li><li>Serve in bowls drizzled with cream, a pinch of curry powder, parsley and pepper.</li></ol><p><em>Serve with warm crusty bread, a drizzle of cream, a pinch of curry powder and parsley.</em></p>', CURRENT_TIMESTAMP),
  ('0ab3e7db-a1f8-5e87-933c-b74b7db304a5', 'af2adcbd-0401-5b2c-90ea-16b2c815fae2', 'ru', 'Азиатский говяжий фарш с рисом в соусе хойсин и устричном соусе', 'Быстрый стир-фрай из говяжьего фарша: без нарезки мяса и без жидкого соуса. Фарш обжаривается с луком и чесноком в сладко-солёной смеси и подаётся на рисе.', '<ol><li>Смешайте в миске хойсин, устричный соус, рисовое вино, тёмный соевый соус, сахар, кунжутное масло и белый перец.</li><li>Разогрейте масло в большой сковороде на сильном огне, обжарьте чеснок и лук около минуты, пока лук не начнёт золотиться.</li><li>Добавьте говяжий фарш и обжаривайте, разминая, пока он не изменит цвет с красного на коричневый.</li><li>Влейте соус и готовьте ещё 2 минуты, пока он не выпарится, а фарш не будет готов. Вмешайте зелёный лук.</li><li>Подавайте на рисе, посыпав зелёным луком и кунжутом.</li></ol><p><em>Подавайте поверх риса, посыпав зелёным луком и кунжутом. Для менее калорийного варианта возьмите рис из цветной капусты.</em></p>', CURRENT_TIMESTAMP),
  ('1a306eb8-d90a-50ff-bcf9-4a77edc5fa87', 'af2adcbd-0401-5b2c-90ea-16b2c815fae2', 'en', 'Asian ground beef bowls with hoisin and oyster sauce', 'A quick ground beef stir-fry: no slicing, and not saucy. The beef is cooked with onion and garlic in a sweet-savory sauce and served over rice.', '<ol><li>Mix the hoisin, oyster sauce, rice wine, dark soy sauce, sugar, sesame oil and white pepper in a bowl.</li><li>Heat the oil in a large skillet over high heat and cook the garlic and onion about 1 minute until the onion starts to brown.</li><li>Add the beef and cook, breaking it up, until it turns from red to brown.</li><li>Pour in the sauce and cook 2 more minutes until it has evaporated and the beef is cooked. Stir through the scallions.</li><li>Serve over rice, topped with extra scallions and sesame seeds.</li></ol><p><em>Serve over rice with scallions and sesame seeds. For lower carbs, use cauliflower rice.</em></p>', CURRENT_TIMESTAMP),
  ('58d78a6a-81bd-5b2c-aeca-6449e0591009', '0e51436a-7b0b-5480-a860-941b274fc193', 'ru', 'Баклажаны, фаршированные креветками и курицей, на пару с соусом', 'Ломтики баклажана с начинкой из креветок и куриного фарша обжариваются, затем доходят на пару и подаются в густом соусе с устричным соусом и чесноком.', '<ol><li>Измельчите креветки с куриным фаршем, солью, сахаром, белым перцем, кунжутным маслом и растительным маслом в блендере или вручную до грубой пасты. Вмешайте яйцо, крахмал и половину зелёного лука, уберите в холодильник на 30 минут.</li><li>Нарежьте баклажаны наискосок ломтиками по 4 см и надрежьте каждый ломтик посередине, не прорезая насквозь. Заполните надрезы начинкой.</li><li>Разогрейте масло в сковороде на средне-сильном огне и обжарьте ломтики с двух сторон до золотистого цвета, подливая по ложке масла при необходимости. Переложите на жаропрочную тарелку.</li><li>Готовьте на пару 7–10 минут в пароварке или в воке с подставкой под крышкой, пока баклажан не станет очень мягким.</li><li>Для соуса прогрейте масло, кунжутное масло и чеснок 30 секунд, влейте бульон, устричный и соевый соусы, сахар, соль и белый перец. Доведите до кипения и загустите половиной крахмальной смеси.</li><li>Влейте в соус жидкость с тарелки, при необходимости загустите. Добавьте оставшийся лук, полейте баклажаны соусом и подавайте.</li></ol><p><em>Подайте с рисом и свежим зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('9606f122-1787-5744-ad35-2bf57c013018', '0e51436a-7b0b-5480-a860-941b274fc193', 'en', 'Chinese stuffed eggplant with shrimp and chicken, steamed in sauce', 'Eggplant slices stuffed with a shrimp and chicken filling are fried until golden, then steamed and served in a glossy oyster-garlic sauce.', '<ol><li>Process the shrimp with the ground chicken, salt, sugar, white pepper, sesame oil and vegetable oil in a food processor or chop by hand into a rough paste. Mix in the egg, cornstarch and half the scallions and chill 30 minutes.</li><li>Cut the eggplants on the diagonal into 1½-inch slices and slit each slice through the middle without cutting all the way. Fill each pocket with the filling.</li><li>Heat oil in a skillet over medium-high heat and fry the slices on both sides until golden, adding a spoonful of oil whenever the pan looks dry. Move to a heatproof plate.</li><li>Steam for 7–10 minutes in a steamer or covered wok with a rack until the eggplant is very soft.</li><li>For the sauce, warm the oils and garlic for 30 seconds, add the stock, oyster and soy sauces, sugar, salt and white pepper, bring to a simmer and thicken with half the cornstarch slurry.</li><li>Pour the liquid from the steaming plate into the sauce, thicken more if needed, stir in the remaining scallions, pour over the eggplant and serve.</li></ol><p><em>Serve with rice and fresh scallions.</em></p>', CURRENT_TIMESTAMP),
  ('13ce27bb-c703-5142-9291-abe3f429187d', '322c0c93-1726-5652-aeee-a67a66535beb', 'ru', 'Картофельная соломка по-сычуаньски с чили', 'Тонкая соломка картофеля быстро обжаривается в масле с ароматом сычуаньского перца, чесноком, имбирём и сушёным чили. Острый и хрустящий гарнир.', '<ol><li>Очистите картофель и нарежьте тонкой соломкой. Несколько раз промойте холодной водой, пока она не станет почти прозрачной, слейте и отложите (не дольше 20 минут, иначе потемнеет).</li><li>В воке на среднем огне прогрейте масло с сычуаньским перцем до аромата, затем выключите огонь и достаньте перец, оставив масло.</li><li>Добавьте имбирь, чеснок и сушёный чили на минуту, затем картофель и острый перец. Жарьте на сильном огне 30 секунд.</li><li>Добавьте соевый соус, сахар, уксус, кунжутное масло, воду и соль, жарьте минуту, накройте на 45 секунд. Откройте, добавьте зелёный лук и подавайте.</li></ol><p><em>Подайте сразу, пока картофель хрустит, с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('77437e80-25ce-5f9f-9500-9eaef442bbea', '322c0c93-1726-5652-aeee-a67a66535beb', 'en', 'Sichuan stir-fried potato strips with chilli', 'Thin potato matchsticks are quickly stir-fried in oil infused with Sichuan peppercorns, with garlic, ginger and dried chilli. A spicy, crunchy side dish.', '<ol><li>Peel the potatoes and julienne them. Rinse in cold water several times until the water is fairly clear, drain and set aside (no more than 20 minutes or they''ll brown).</li><li>In a wok over medium heat warm the oil with the Sichuan peppercorns until fragrant, then turn off the heat and scoop out the peppercorns, leaving the oil.</li><li>Add the ginger, garlic and dried chilli for a minute, then the potatoes and hot pepper and stir-fry over high heat for 30 seconds.</li><li>Add the soy sauce, sugar, vinegar, sesame oil, water and salt, stir-fry a minute, cover for 45 seconds, then uncover, stir in the scallion and serve.</li></ol><p><em>Serve right away while crisp, with rice.</em></p>', CURRENT_TIMESTAMP),
  ('294c9990-95de-55d1-99c1-02f5a02c3a1a', 'fa0bb5c3-a0d7-5b24-b525-a0036168ac0b', 'ru', 'Китайские фрикадельки «львиная голова» тушёные в соевом соусе', 'Крупные свиные тефтели с имбирём, зелёным луком и водяными каштанами, обжаренные и затем тушёные в соусе из соевого и устричного соусов.', '<ol><li>Смешайте жирный свиной фарш с имбирём, зелёным луком, яйцом, сухарями, оставшимися приправами для фарша, перцем, пятью специями, крахмалом и водой. Взбивайте в одну сторону около 10 минут до пастообразной массы.</li><li>Раздавите и мелко порубите водяные каштаны, добавьте в фарш и перемешивайте ещё 5 минут.</li><li>Нагрейте масло для фритюра до 175 °C в небольшой глубокой кастрюле. Смазав руки маслом, сформируйте 8–9 шариков и по одному опускайте в масло. Жарьте партиями по 2 минуты до золотистого цвета и выложите на тарелку.</li><li>В воке на слабом огне прогрейте 1 ст. л. масла с имбирём и белой частью лука 1 минуту, добавьте сахар до растворения. Влейте соевый (светлый и тёмный) и устричный соусы и воду, доведите до кипения.</li><li>Положите фрикадельки, накройте и тушите на среднем-слабом огне 12–15 минут, перевернув на половине времени. Выложите на блюдо.</li><li>Влейте в соус крахмальную смесь и дайте загустеть, добавьте кунжутное масло и зелёную часть лука. Полейте фрикадельки соусом.</li></ol><p><em>Подайте с бланшированным бок-чой и рисом.</em></p>', CURRENT_TIMESTAMP),
  ('ef4d0b7d-566c-58c6-92fb-d80596bb18d5', 'fa0bb5c3-a0d7-5b24-b525-a0036168ac0b', 'en', 'Lion''s head meatballs braised in soy-oyster sauce', 'Large pork meatballs with ginger, scallion and water chestnuts, fried and then braised in a soy and oyster sauce.', '<ol><li>Combine the fatty ground pork with the ginger, scallion, egg, breadcrumbs, light soy sauce, oyster sauce, pepper, five spice, cornstarch and water. Whip in one direction about 10 minutes until a paste.</li><li>Smash and finely mince the water chestnuts, add to the meat and keep mixing 5 more minutes.</li><li>Heat oil for deep frying to 350 °F (175 °C) in a small deep pot. With oiled hands shape 8–9 balls and lower in one at a time. Fry in batches 2 minutes each until golden and set aside.</li><li>In a wok over low heat warm 1 tbsp oil with the ginger and scallion whites for 1 minute, add the sugar until dissolved, then the light and dark soy sauces, oyster sauce and water and bring to a boil.</li><li>Add the fried meatballs, cover and cook 12–15 minutes over medium-low heat, flipping halfway. Transfer to a plate.</li><li>Stir the cornstarch slurry into the sauce until it coats a spoon, add the sesame oil and scallion greens and drizzle over the meatballs.</li></ol><p><em>Serve with blanched baby bok choy and rice.</em></p>', CURRENT_TIMESTAMP),
  ('bc399ba0-a749-50da-861c-5eb664a419e8', '81651134-cbf0-511d-bb35-49c766ecb04e', 'ru', 'Свинина соломкой с овощами и сушёным чили', 'Тонкая соломка свинины и овощей (брокколи, морковь, перцы) быстро обжаривается на сильном огне с сушёным чили и острым маслом.', '<ol><li>Смешайте свинину с 1 ч. л. крахмала и 1 ч. л. масла. Нарежьте овощи соломкой. Разведите оставшийся крахмал в 3 ст. л. воды.</li><li>В воке на сильном огне разогрейте 1 ст. л. масла и обжарьте свинину около минуты. Переложите на тарелку.</li><li>Добавьте ещё немного масла, бросьте сушёный чили на 10 секунд, затем овощи. Жарьте на самом сильном огне 2 минуты, влейте воду по краю вока для шипения (вместо вина).</li><li>Верните свинину, перемешайте, добавьте уксус, сахар, соль и белый перец, затем крахмальную смесь и острое масло. Перемешайте и подавайте с рисом.</li></ol><p><em>Подайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('01db3c7e-e8f1-54ba-b36d-0bc76b0831c5', '81651134-cbf0-511d-bb35-49c766ecb04e', 'en', 'Shredded pork and vegetable stir-fry with dried chilli', 'Thin strips of pork and vegetables (broccoli stems, carrot, peppers) stir-fried over high heat with dried chilli and chilli oil.', '<ol><li>Coat the pork in 1 teaspoon cornstarch and 1 teaspoon oil. Cut the vegetables into strips and mix the remaining cornstarch with 3 tablespoons water.</li><li>Heat 1 tablespoon oil in a wok over high heat and stir-fry the pork about 1 minute. Remove to a plate.</li><li>Add a little more oil, toss in the dried chillies for 10 seconds, then the vegetables. Cook over the highest heat 2 minutes, then splash water around the edge of the wok to sizzle (in place of wine).</li><li>Return the pork, toss, add the vinegar, sugar, salt and white pepper, then the cornstarch slurry and chilli oil. Give a final stir and serve with rice.</li></ol><p><em>Serve with rice.</em></p>', CURRENT_TIMESTAMP),
  ('58578e08-46c3-5f02-83b5-7fa5daeaf8ca', '22a9d866-c0b3-5f29-92e3-77db94706102', 'ru', 'Брокколи с чесноком в соусе по-китайски', 'Бланшированная брокколи обжаривается с чесноком и заливается лёгким соусом из куриного бульона, загущённым крахмалом. Простой гарнир к курице или рыбе.', '<ol><li>Промойте брокколи. Размешайте крахмал с водой в гладкую смесь, измельчите чеснок.</li><li>Вскипятите воду в воке, бланшируйте брокколи минуту, слейте и опустите в холодную воду.</li><li>Разогрейте вок на сильном огне, добавьте масло, чеснок и брокколи и жарьте минуту. Влейте бульон и доведите до кипения.</li><li>Добавьте соль, белый перец и кунжутное масло, затем половину крахмальной смеси. Дайте соусу загустеть, добавьте остальную смесь при необходимости и подавайте горячей.</li></ol><p><em>Подайте горячей к курице или лососю.</em></p>', CURRENT_TIMESTAMP),
  ('9f6f7852-9c6a-5803-b804-e1e98fbdb8e6', '22a9d866-c0b3-5f29-92e3-77db94706102', 'en', 'Garlicky broccoli stir-fry in a light sauce', 'Blanched broccoli stir-fried with garlic and glazed with a light chicken stock sauce thickened with cornstarch. A simple side for chicken or fish.', '<ol><li>Wash the broccoli, stir the cornstarch into the water until dissolved and mince the garlic.</li><li>Bring water to a boil in a wok, blanch the broccoli for a minute, drain and plunge into cold water.</li><li>Heat the wok over high heat, add the oil, garlic and broccoli and stir-fry for a minute, then pour in the stock and bring to a boil.</li><li>Add the salt, white pepper and sesame oil, then half the cornstarch slurry. Let the sauce thicken, add more slurry if needed and serve hot.</li></ol><p><em>Serve hot with seared chicken or salmon.</em></p>', CURRENT_TIMESTAMP),
  ('4acfce4e-d751-5081-be87-7d8615cd421f', 'a985bdd0-f164-5449-b975-5065765584ff', 'ru', 'Тофу, тушёный с овощами в соевом соусе', 'Ломтики тофу обжариваются, тушатся в соево-чесночном соусе с шиитаке и заканчиваются со стручковым горошком, морковью и перцем.', '<ol><li>Смешайте крахмал с водой. Откиньте тофу, нарежьте ломтиками по 1,2 см. Нарежьте грибы шиитаке.</li><li>Смешайте бульон, кунжутное масло, оба соевых соуса, сахар и соль.</li><li>Разогрейте вок на сильном огне, добавьте масло и в один слой выложите тофу, обжарьте минуту с каждой стороны, добавьте чеснок.</li><li>Влейте соусную смесь и добавьте грибы. Доведите до кипения, убавьте огонь до среднего, накройте и тушите 5 минут.</li><li>Откройте, увеличьте огонь, добавьте овощи и аккуратно перемешайте. Понемногу вливайте крахмал, пока соус не обволакивает тофу и овощи, и сразу подавайте.</li></ol><p><em>Подайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('1b0ccfec-229e-5e44-bc41-a4c51fff931a', 'a985bdd0-f164-5449-b975-5065765584ff', 'en', 'Braised tofu with vegetables in soy sauce (hongshao dofu)', 'Tofu slices are seared, braised in a soy-garlic sauce with shiitake and finished with snow peas, carrot and bell pepper.', '<ol><li>Mix the cornstarch with the water into a slurry. Drain the tofu and cut into ½-inch slices; slice the shiitake.</li><li>Combine the stock, sesame oil, both soy sauces, sugar and salt.</li><li>Heat the wok over high heat, add the oil and arrange the tofu in one layer, searing about a minute per side, then add the garlic.</li><li>Pour in the sauce mixture and add the mushrooms, bring to a boil, lower to medium, cover and cook 5 minutes.</li><li>Uncover, turn up the heat, add the vegetables and toss gently. Add the slurry a little at a time until the sauce coats the tofu and vegetables and serve at once.</li></ol><p><em>Serve with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('4f23983a-e037-560e-af35-3c1265e87d55', '8dec1421-41b7-591f-b6f5-899385b57ba1', 'ru', 'Курица в арахисовом соусе с баклажанами и томатами', 'Обжаренные в духовке куриные кусочки тушатся с луком, баклажаном, томатами и бульоном, а в конце в рагу добавляют арахисовую пасту. Сытное блюдо в африканском стиле.', '<ol><li>Смешайте курицу с оливковым маслом, кориандром, паприкой, кайенским перцем, солью и перцем. Маринуйте не менее 2 часов или на ночь.</li><li>Разогрейте духовку до 200 °C и запекайте курицу 45 минут.</li><li>Параллельно в большой сковороде или жаровне обжаривайте на масле лук, баклажан и хлопья чили 30 минут до полной мягкости.</li><li>Добавьте томатную пасту, помидоры, бульон и запечённую курицу. Доведите до кипения и варите без крышки 30 минут.</li><li>Вмешайте арахисовую пасту и тушите ещё 30 минут. Посыпьте арахисом и кинзой и подавайте с рисом.</li></ol><p><em>Посыпьте рублеными орехами и кинзой и подайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('176f5a97-b8ed-5064-92ac-741ba1d8cb70', '8dec1421-41b7-591f-b6f5-899385b57ba1', 'en', 'African-style chicken peanut stew with eggplant and tomato', 'Oven-roasted chicken pieces simmer with onion, eggplant, tomatoes and stock, then peanut butter is stirred in at the end. A hearty African-style stew.', '<ol><li>Toss the chicken with olive oil, coriander, smoked paprika, cayenne, salt and pepper. Marinate at least 2 hours or overnight.</li><li>Preheat the oven to 400 °F (200 °C) and roast the chicken 45 minutes.</li><li>Meanwhile cook the onions, eggplant and chilli flakes in olive oil in a large skillet or Dutch oven for 30 minutes until very tender.</li><li>Add the tomato paste, tomatoes, stock and roasted chicken, bring to a boil and simmer uncovered 30 minutes.</li><li>Stir in the peanut butter and simmer another 30 minutes. Garnish with peanuts and cilantro and serve with rice.</li></ol><p><em>Garnish with chopped peanuts and cilantro and serve with rice.</em></p>', CURRENT_TIMESTAMP),
  ('151b62c4-7392-5b62-9457-60f3525077f7', '5a3e41da-d1b0-5ebb-9e80-0a5937a2de53', 'ru', 'Солёная овсяная каша из цельных овсяных зёрен с сыром и яйцом', 'Не сладкая каша из овсяной крупы (steel-cut), предварительно обжаренной в масле и сваренной на воде с молоком. Подаётся с яйцом, овощами, зеленью и сыром.', '<ol><li>В большой кастрюле доведите воду с молоком до слабого кипения на среднем огне.</li><li>Тем временем растопите масло на сковороде диаметром 30 см на среднем огне, всыпьте овсяную крупу и обжаривайте, помешивая, около 2 минут до золотистого цвета и аромата.</li><li>Всыпьте крупу в кипящую жидкость, убавьте огонь до средне-слабого и варите 20–25 минут, иногда помешивая, пока масса не загустеет.</li><li>Посолите и продолжайте варить около 10 минут, пока почти вся жидкость не впитается. Кашу можно варить дольше, если рецепт удвоен.</li><li>Снимите с огня и оставьте на 5 минут. Добавьте соль, перец, специи и любые добавки по вкусу, разложите по тарелкам и добавьте начинку.</li></ol><p><em>Сверху можно положить яйцо-пашот, обжаренные овощи, сыр и орехи.</em></p>', CURRENT_TIMESTAMP),
  ('32173b74-d23b-5294-a558-8266a7a42047', '5a3e41da-d1b0-5ebb-9e80-0a5937a2de53', 'en', 'Savory steel-cut oatmeal with milk and butter', 'A non-sweet porridge of steel-cut oats toasted in butter and simmered in water and milk. Serve with an egg, vegetables, herbs and cheese.', '<ol><li>In a large saucepan, bring the water and milk to a simmer over medium heat.</li><li>Meanwhile, melt the butter in a 12-inch skillet over medium heat, add the oats and toast, stirring, about 2 minutes until golden and fragrant.</li><li>Stir the oats into the simmering liquid, reduce to medium-low and simmer gently 20–25 minutes, stirring occasionally, until very thick.</li><li>Stir in the salt and keep simmering about 10 minutes until almost all the liquid is absorbed.</li><li>Remove from the heat and rest 5 minutes. Season with more salt, pepper and spices, stir in any mix-ins, then portion into bowls and add toppings.</li></ol><p><em>Top with a poached egg, sautéed vegetables, cheese and nuts.</em></p>', CURRENT_TIMESTAMP),
  ('febbf955-1703-5923-a5b7-6dd10cefa527', '22076ff3-515f-50e7-9d68-79cb55e3ba91', 'ru', 'Запечённая овсянка с черникой, пеканом и кленовым сиропом', 'Запеканка из овсяных хлопьев с черникой, орехами пекан, корицей и мускатным орехом, подсластённая кленовым сиропом. Можно приготовить сразу на несколько дней.', '<ol><li>Разогрейте духовку до 190 °C и смажьте квадратную форму 23 см. Подсушите пекан на противне в духовке 4–5 минут до аромата.</li><li>В миске смешайте овсяные хлопья, орехи, корицу, разрыхлитель, соль и мускатный орех.</li><li>В другой миске взбейте молоко, кленовый сироп, яйца, половину масла и ваниль.</li><li>Около ½ стакана ягод отложите для верха, остальные разложите по дну формы. Накройте сухой смесью и вылейте сверху жидкую. Встряхните форму, чтобы молоко пропитало овсянку, и слегка прижмите сухие хлопья.</li><li>Выложите сверху оставшуюся чернику, по желанию посыпьте сахаром. Запекайте 42–45 минут (с замороженной ягодой 45–50) до золотистой корочки.</li><li>Дайте остыть несколько минут и полейте оставшимся растопленным маслом. Подавайте тёплой, комнатной температуры или холодной.</li></ol><p><em>Подавайте тёплой с йогуртом или сливками и ещё немного сиропа. Хорошо хранится и разогревается порциями.</em></p>', CURRENT_TIMESTAMP),
  ('f49385ad-213b-5ef0-8987-390aada4b7c3', '22076ff3-515f-50e7-9d68-79cb55e3ba91', 'en', 'Blueberry baked oatmeal with pecans and maple', 'An oat bake with blueberries, pecans, cinnamon and nutmeg, sweetened with maple syrup. Easy to make ahead for several days.', '<ol><li>Preheat the oven to 190°C (375°F) and grease a 9-inch square baking dish. Toast the pecans on a baking sheet 4–5 minutes until fragrant.</li><li>In a bowl, whisk the oats, toasted nuts, cinnamon, baking powder, salt and nutmeg.</li><li>In another bowl whisk the milk, maple syrup, eggs, half the butter and the vanilla.</li><li>Reserve about ½ cup of the berries for the top and spread the rest over the bottom of the dish. Cover with the oat mixture and pour the wet mixture over. Wiggle the dish so the milk soaks through and pat down any dry oats.</li><li>Scatter the remaining berries and sprinkle with raw sugar if you like. Bake 42–45 minutes (45–50 with frozen berries) until golden on top.</li><li>Cool for a few minutes and drizzle with the remaining melted butter. Serve warm, at room temperature or chilled.</li></ol><p><em>Serve warm with yogurt or cream and a drizzle of syrup. Reheats well in portions.</em></p>', CURRENT_TIMESTAMP),
  ('36f6dc61-8684-5c7c-893f-911e75dd9683', '16925ccb-0713-5881-8197-7f8d3b594915', 'ru', 'Тостады на завтрак с фасолью, яйцом и сальсой', 'Хрустящие запечённые кукурузные лепёшки с тёплой пюрированной фасолью, сыром чеддер, яйцом и свежей сальсой пико-де-гайо. Подходят для завтрака и лёгкого ужина.', '<ol><li>Разогрейте духовку до 200 °C, две решётки поставьте в середину. Застелите два противня пергаментом.</li><li>Смажьте обе стороны каждой лепёшки маслом и разложите по 4 на противень. Запекайте 10–12 минут, перевернув на середине, до золотистого цвета и хруста.</li><li>Пока лепёшки запекаются, подогрейте пюре из фасоли и приготовьте яйца (глазунья или болтунья).</li><li>На каждую тостаду намажьте фасоль, посыпьте сыром, положите яйцо и сверху пико-де-гайо шумовкой. Добавьте остальные добавки и подавайте сразу.</li></ol><p><em>Подавайте сразу, пока лепёшки хрустят. Можно добавить авокадо и острый соус. Порция: две тостады.</em></p>', CURRENT_TIMESTAMP),
  ('462426cc-af5b-52ca-9295-7b728c70e608', '16925ccb-0713-5881-8197-7f8d3b594915', 'en', 'Breakfast tostadas with refried beans, egg and pico de gallo', 'Crisp baked corn tortillas topped with warm refried beans, cheddar, eggs and fresh pico de gallo. Good for breakfast or a light dinner.', '<ol><li>Preheat the oven to 200°C (400°F) with two racks near the middle. Line two baking sheets with parchment.</li><li>Brush both sides of each tortilla with oil and put 4 on each tray. Bake 10–12 minutes, turning halfway, until golden and crisp.</li><li>Meanwhile warm the refried beans and cook the eggs fried or scrambled.</li><li>Spread beans on each tostada, sprinkle with cheese, add the egg and top with pico de gallo using a slotted spoon. Add any garnishes and serve promptly.</li></ol><p><em>Serve right away while the tortillas are crisp. Add avocado and hot sauce if you like. One serving is two tostadas.</em></p>', CURRENT_TIMESTAMP),
  ('86e49df4-5a55-5179-87b9-72a1ab76b15c', '59bd9f1e-bb63-5cff-8ca5-455e2b571ede', 'ru', 'Рататуй из запечённых овощей в томатном соусе', 'Провансальское овощное рагу: баклажан, кабачки и перец сначала запекаются, затем добавляются в томатный соус с луком, чесноком и базиликом. Вкус лучше на следующий день.', '<ol><li>Разогрейте духовку до 220 °C, одну решётку поставьте в середину, другую в верхнюю треть. Застелите два противня пергаментом.</li><li>Помидоры очистите от плотных сердцевинок и натрите на крупной тёрке в миску, нарежьте оставшуюся кожицу. Или измельчите в кухонном комбайне в пюре.</li><li>На одном противне смешайте баклажан с 2 ст. л. масла, разложите в один слой и посолите (¼ ч. л.). На втором перемешайте перец, цукини и сквош с 1 ст. л. масла и ¼ ч. л. соли.</li><li>Поставьте баклажан в середину, остальные овощи наверх и запекайте 15 минут.</li><li>Тем временем разогрейте в кастрюле 2 ст. л. масла на среднем огне, обжарьте лук с ¼ ч. л. соли 8–10 минут до мягкости и карамелизации по краям. Добавьте чеснок на 30 секунд, затем помидоры, соскребая прилипшее со дна. Убавьте огонь, чтобы томаты слегка кипели.</li><li>Через 15 минут достаньте противни, перемешайте овощи и поменяйте противни местами. Запекайте баклажан ещё около 10 минут до золотистых краёв, затем переложите в соус.</li><li>Остальные овощи допекайте ещё 5–10 минут до карамелизации перца, затем добавьте в соус и варите 5 минут, чтобы вкусы соединились.</li><li>Снимите с огня, добавьте 1 ч. л. масла, базилик, хлопья чили и орегано (разотрите пальцами), посолите и поперчите по вкусу.</li></ol><p><em>Подавайте тёплым или охлаждённым, с каплей оливкового масла и свежим базиликом, с хлебом или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('e8a24231-23f9-524c-b0fc-9321a7d09973', '59bd9f1e-bb63-5cff-8ca5-455e2b571ede', 'en', 'Roasted vegetable ratatouille', 'Provençal vegetable stew: eggplant, zucchini and peppers roasted first, then added to a simmering tomato sauce with onion, garlic and basil. Tastes even better the next day.', '<ol><li>Preheat the oven to 220°C (425°F) with one rack in the middle and one in the upper third. Line two baking sheets with parchment.</li><li>Core the tomatoes and grate on the large holes of a box grater into a bowl, chopping any leftover skin. Or pulse in a food processor to a frothy pulp.</li><li>On one tray, toss the eggplant with 2 tbsp of oil, spread in a single layer and sprinkle with ¼ tsp salt. On the other, toss the pepper, zucchini and squash with 1 tbsp oil and ¼ tsp salt.</li><li>Put the eggplant on the middle rack and the other vegetables on top and roast for 15 minutes.</li><li>Meanwhile heat 2 tbsp oil in a Dutch oven over medium heat and cook the onion with ¼ tsp salt 8–10 minutes until tender and caramelizing at the edges. Add the garlic 30 seconds, then the tomatoes, scraping up the browned bits. Lower the heat to a gentle simmer.</li><li>After 15 minutes stir the vegetables and swap the trays. Bake the eggplant about 10 more minutes until golden at the edges, then stir it into the sauce.</li><li>Let the remaining vegetables roast 5–10 minutes more until the peppers caramelize, add to the sauce and simmer 5 minutes so the flavours meld.</li><li>Remove from the heat. Stir in 1 tsp oil, the basil, chili flakes and the oregano crumbled between your fingers, then season to taste.</li></ol><p><em>Serve warm or chilled with a drizzle of olive oil and fresh basil, with bread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('a9b701d2-815d-5b77-b6c8-3c814d40dde6', 'de23ef2e-7cf7-59a8-83ef-7e03915af697', 'ru', 'Фаршированный перец с бурым рисом, фасолью и сыром (вегетарианский)', 'Запечённые половинки сладкого перца с начинкой из бурого риса, фасоли пинто, помидоров черри и пряностей в мексиканском стиле, сверху расплавленный сыр.', '<ol><li>Разогрейте духовку до 220 °C. Разрежьте перцы вдоль пополам, удалите семена и перегородки. Выложите в форму 23x33 см, сбрызните маслом, посолите, поперчите и разотрите руками. Разложите срезом вверх.</li><li>Запекайте 20–25 минут, пока перцы слегка не подпекутся по краям и не станут мягкими. Духовку не выключайте.</li><li>Тем временем промойте рис в мелком сите. Опустите его в большую кастрюлю с кипящей водой и варите без крышки 30 минут. Слейте воду и верните рис в кастрюлю.</li><li>Для начинки разогрейте на сковороде 2 ст. л. масла, обжарьте лук с ½ ч. л. соли 5 минут до мягкости, добавьте помидоры черри и готовьте ещё около 5 минут.</li><li>Добавьте кинзу, чеснок, чили и зиру и готовьте, помешивая, 30–60 секунд. Снимите с огня и добавьте рис, фасоль, сок лайма и чёрный перец. Попробуйте и досолите.</li><li>Слейте лишний сок из перцев и щедро наполните их начинкой. Сверху посыпьте сыром.</li><li>Запекайте при 220 °C 12–13 минут, пока сыр не зарумянится пятнами. Подавайте тёплыми с кинзой.</li></ol><p><em>Подавайте тёплыми с кинзой, авокадо или сальсой. Порция: 2 половинки перца.</em></p>', CURRENT_TIMESTAMP),
  ('20a367ea-e990-5d95-95c4-42df557f508f', 'de23ef2e-7cf7-59a8-83ef-7e03915af697', 'en', 'Vegetarian stuffed peppers with brown rice, pinto beans and cheese', 'Roasted bell pepper halves filled with brown rice, pinto beans, cherry tomatoes and Mexican spices, topped with melted cheese.', '<ol><li>Preheat the oven to 220°C (425°F). Halve the peppers from stem to base and remove seeds and membranes. Put in a 9x13 baking dish, drizzle with oil, season and rub in. Arrange cut-side up.</li><li>Roast 20–25 minutes until slightly blistered at the edges and easily pierced with a fork. Leave the oven on.</li><li>Meanwhile rinse the rice in a fine-mesh sieve until the water runs clear. Boil in a large pot of water uncovered for 30 minutes, then drain and return to the pot.</li><li>For the filling, heat 2 tbsp oil in a skillet and cook the onion with ½ tsp salt about 5 minutes until tender, then add the tomatoes and cook another 5 minutes.</li><li>Add the cilantro, garlic, chili powder and cumin and cook, stirring, 30–60 seconds. Remove from the heat and add the rice, beans, lime juice and pepper. Taste and adjust salt.</li><li>Pour off any juice pooled in the peppers and stuff generously with the filling. Top with cheese.</li><li>Bake at 220°C (425°F) 12–13 minutes until the cheese is golden in spots. Serve warm with cilantro.</li></ol><p><em>Serve warm with cilantro, avocado or salsa. One serving is 2 pepper halves.</em></p>', CURRENT_TIMESTAMP),
  ('18177aef-24e7-51c2-bc13-7bc0bed190b1', '2f6b723e-f654-55d7-8d35-fd7223eb1555', 'ru', 'Полента с козьим сыром, запечённой тыквой и яйцом', 'Кремовая кукурузная каша-полента с козьим сыром, сверху запечённая тыква с красным луком и яйцо. Подходит для плотного завтрака и ужина.', '<ol><li>Разогрейте духовку до 200 °C. На большом противне перемешайте нарезанные овощи с 2 ст. л. масла, солью и перцем, разложите в один слой.</li><li>Запекайте 25–40 минут, перемешав на середине, пока овощи не станут мягкими и золотистыми по краям.</li><li>Для поленты разогрейте в кастрюле 2 ч. л. масла на среднем огне, обжарьте нарезанный перец с ½ ч. л. соли около 5 минут до мягкости.</li><li>Влейте воду по инструкции на упаковке, доведите до кипения, всыпьте полентy, взбейте, убавьте огонь до средне-слабого. Варите, часто взбивая, пока не загустеет (от 5 минут).</li><li>Снимите с огня, добавьте масло, сальсу верде и перец. Осторожно вмешайте козий сыр. Накройте.</li><li>Пожарьте яйца. Разложите полентy и яйца по четырём мискам, сверху овощи и зелёный лук.</li></ol><p><em>Подавайте с сальсой верде или острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('ab35c917-3053-51d4-8a98-d3da8486b361', '2f6b723e-f654-55d7-8d35-fd7223eb1555', 'en', 'Goat cheese polenta with roasted butternut squash and fried egg', 'Creamy polenta with goat cheese, topped with roasted butternut squash and red onion and a fried egg. Works for a hearty brunch or dinner.', '<ol><li>Preheat the oven to 200°C (400°F). On a large rimmed sheet toss the vegetables with 2 tbsp oil, salt and pepper and spread in a single layer.</li><li>Roast 25–40 minutes, tossing halfway, until tender and deeply golden at the edges.</li><li>For the polenta, warm 2 tsp oil in a saucepan over medium heat and cook the chopped bell pepper with ½ tsp salt about 5 minutes until tender.</li><li>Add the water per the package, bring to a boil, pour in the polenta, whisk and reduce to medium-low. Cook, whisking often, until thickened (5 minutes or more).</li><li>Remove from the heat and stir in the butter, salsa verde and pepper. Gently fold in the goat cheese and cover.</li><li>Cook the eggs. Divide the polenta and eggs among 4 bowls and top with the vegetables and green onion.</li></ol><p><em>Serve with salsa verde or hot sauce on the side.</em></p>', CURRENT_TIMESTAMP),
  ('335345bd-edb0-5fb3-a9e6-ff4341d32c1d', '16d2db19-d102-5744-beff-f9655ba55424', 'ru', 'Простое пюре из фасоли пинто (рефрайд бинс) с кинзой и лаймом', 'Быстрое мексиканское пюре из консервированной фасоли с луком, чесноком, чили и зирой. Постное и без глютена, готово за 25 минут.', '<ol><li>В кастрюле на среднем огне разогрейте масло, добавьте лук и соль и готовьте 5–8 минут, пока лук не станет мягким и прозрачным.</li><li>Добавьте чеснок, чили и зиру и готовьте 30 секунд, помешивая. Влейте промытую фасоль и воду, накройте и готовьте 5 минут.</li><li>Убавьте огонь, снимите крышку и разомните толкушкой или вилкой хотя бы половину фасоли до нужной консистенции. Готовьте ещё 3 минуты без крышки, помешивая.</li><li>Снимите с огня, добавьте кинзу и лаймовый сок, попробуйте и при необходимости досолите. Если сухо, добавьте немного воды.</li></ol><p><em>Подходит к лепёшкам, начинкой для буррито и кесадильи, как гарнир к яйцам и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('741ac71c-2cf9-5d01-9e41-dc355ab59ca1', '16d2db19-d102-5744-beff-f9655ba55424', 'en', 'Easy refried pinto beans with cilantro and lime', 'Quick Mexican mashed beans from canned pinto beans with onion, garlic, chili and cumin. Vegan and gluten-free, ready in 25 minutes.', '<ol><li>In a saucepan over medium heat warm the oil, add the onion and salt and cook 5–8 minutes until softened and translucent.</li><li>Add the garlic, chili powder and cumin and stir 30 seconds. Add the drained beans and water, cover and cook 5 minutes.</li><li>Reduce the heat, uncover and mash at least half the beans with a potato masher or fork to your desired consistency. Cook 3 more minutes uncovered, stirring.</li><li>Remove from the heat, stir in the cilantro and lime juice, taste and adjust salt. Add a splash of water if dry.</li></ol><p><em>Great with tortillas, in burritos and quesadillas, or beside eggs and meat.</em></p>', CURRENT_TIMESTAMP),
  ('1c57d002-a5f0-5872-9776-ffb6a2551904', '025fb02d-1482-5b2f-b46a-ad03a8e4db71', 'ru', 'Сукоташ из кукурузы, лимской фасоли и перцев с базиликом', 'Американский гарнир с корнями индейской кухни: кукуруза, лимская фасоль, поблано, красный перец и лук, обжаренные на сковороде со сливочным маслом и свежим базиликом.', '<ol><li>На большой сковороде на средне-сильном огне разогрейте масло до лёгкого шипения. Добавьте кукурузу и ½ ч. л. соли и жарьте 5–7 минут, помешивая раз в минуту, пока зёрна не станут золотистыми по краям.</li><li>Убавьте огонь до средне-слабого. Добавьте лук, поблано, болгарский перец, халапеньо (если берёте) и оставшуюся соль. Готовьте 5–8 минут, часто помешивая, счищая прилипшее со дна, пока лук не станет прозрачным.</li><li>Добавьте чеснок на 30 секунд, затем лимскую фасоль на 2 минуты, чтобы прогреть.</li><li>Добавьте масло и размешайте до растворения. Снимите с огня, остудите несколько минут, поперчите, при желании добавьте щепотку кайенского перца и половину базилика.</li><li>Переложите на блюдо, посыпьте остальным базиликом и зелёным луком, добавьте кусочек масла и щепотку крупной соли.</li></ol><p><em>Лучше есть в течение пары часов после приготовления. Сверху положите ещё кусочек масла и щепотку крупной соли.</em></p>', CURRENT_TIMESTAMP),
  ('a106ea1d-176b-57a3-93d4-0f58f06d3ea7', '025fb02d-1482-5b2f-b46a-ad03a8e4db71', 'en', 'Vegetarian succotash with corn, lima beans, poblano and basil', 'A side dish with Native American roots: corn, lima beans, poblano and red pepper and onion sautéed in a skillet, finished with butter and fresh basil.', '<ol><li>Warm the oil in a large skillet over medium-high heat until it shimmers. Add the corn and ½ tsp salt and cook 5–7 minutes, stirring every minute, until golden at the edges.</li><li>Lower to medium-low. Add the onion, poblano, bell pepper, jalapeño (if using) and remaining salt. Cook 5–8 minutes, stirring often and scraping the bottom, until the onion is translucent.</li><li>Add the garlic for 30 seconds, then the lima beans for 2 minutes to warm through.</li><li>Add the butter and stir until mostly melted. Remove from the heat, cool a few minutes, season with pepper, a pinch of cayenne if you like and half the basil.</li><li>Transfer to a plate and top with the remaining basil, green onion, a few pats of butter and flaky salt.</li></ol><p><em>Best eaten within a couple of hours. Top with a pat of butter and flaky salt.</em></p>', CURRENT_TIMESTAMP),
  ('c2339bb7-9f09-5e52-848e-e3f47c7b4018', '6b15828b-8141-5df8-88bd-09aa28499437', 'ru', 'Тайский омлет кай-джио из двух яиц', 'Простой омлет из двух яиц с рыбным соусом, поджаренный до золотистого цвета. Самое первое блюдо, которое готовят в Таиланде, обычно с рисом.', '<ol><li>Хорошо взбейте яйца с рыбным соусом вилкой.</li><li>Нагрейте в воке или небольшой сковороде достаточно масла, чтобы покрыть дно, на средне-сильном огне. Капля яйца должна сразу вспениться.</li><li>Влейте яйца и придвигайте края к центру, чтобы сырое стекало к краям. Когда омлет схватится, переверните и жарьте ещё несколько секунд.</li><li>Подавайте с рисом и острым соусом.</li></ol><p><em>Подайте с рисом жасмин и острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('28934459-b200-51e6-8c02-224073c410f0', '6b15828b-8141-5df8-88bd-09aa28499437', 'en', 'Basic Thai omelette (kai jiew) with two eggs', 'A simple two-egg omelette seasoned with fish sauce and fried until golden. The first dish most Thais learn, usually eaten with rice.', '<ol><li>Beat the eggs with the fish sauce well with a fork.</li><li>Heat enough oil to coat the bottom of a wok or small pan over medium-high heat. A drop of egg should bubble up right away.</li><li>Pour in the eggs and push the edges inward so raw egg runs to the pan. When set enough, flip and cook a few more seconds.</li><li>Serve with rice and hot sauce.</li></ol><p><em>Serve with jasmine rice and hot sauce.</em></p>', CURRENT_TIMESTAMP),
  ('c00b521f-0872-5e88-bd1f-ba25b9f74557', '772c5bad-45ec-5122-9e1f-6af2434c2a3b', 'ru', 'Китайская яичница с помидорами', 'Нежная яичная болтунья с мягкими помидорами, соевым соусом и щепоткой сахара. Быстрый ужин, который любят дети.', '<ol><li>Разрежьте каждый помидор пополам, удалите сердцевину и нарежьте крупными кусочками.</li><li>Взбейте яйца вилкой с рыбным соусом и белым перцем до исчезновения крупных комков белка.</li><li>В антипригарной сковороде на сильном огне нагрейте 1 ст. л. масла, добавьте помидоры, соевый соус и сахар и готовьте 1–2 минуты, пока помидоры не станут мягкими, но сохранят форму. Добавьте зелёный лук и переложите в миску.</li><li>Протрите сковороду, нагрейте ещё 1 ст. л. масла. Влейте яйца и быстро помешивайте лопаткой до готовности примерно на 80 %. Сразу верните помидоры и осторожно перемешайте, пока яйца не схватятся.</li><li>Выложите на тарелку и подавайте с рисом.</li></ol><p><em>Подайте с горячим рисом.</em></p>', CURRENT_TIMESTAMP),
  ('87e9d45a-b660-504c-831f-cd12c8ed4b3f', '772c5bad-45ec-5122-9e1f-6af2434c2a3b', 'en', 'Chinese tomato and egg stir-fry', 'Soft scrambled eggs folded with tender tomatoes seasoned with soy sauce and a pinch of sugar. A quick, kid-friendly dinner.', '<ol><li>Halve each tomato, remove the core and cut into chunky wedges.</li><li>Beat the eggs with the fish sauce and white pepper with a fork until no big gloopy bits of white remain.</li><li>Heat 1 tablespoon of oil in a non-stick skillet over medium-high heat, add the tomatoes, soy sauce and sugar and cook 1–2 minutes until soft but still holding shape. Stir in the green onion and transfer to a bowl.</li><li>Wipe the pan, heat another tablespoon of oil, add the eggs and scramble quickly until about 80% cooked. Immediately fold in the tomatoes just until the eggs are cooked through.</li><li>Transfer to a plate and serve with rice.</li></ol><p><em>Serve over hot rice.</em></p>', CURRENT_TIMESTAMP),
  ('2e441b72-aabc-5c9a-9dfe-0bc6191ad815', '3e15710d-4858-5963-9773-06958089a820', 'ru', 'Рыба на пару с имбирём, чесноком и соевым соусом', 'Филе белой рыбы готовится на пару, затем поливается горячим соусом из бульона, имбиря, чеснока, грибов шиитаке, соевого и устричного соусов.', '<ol><li>Выньте размокшие сушёные грибы из воды, отожмите, срежьте ножки и тонко нарежьте шляпки.</li><li>Положите рыбу в глубокую тарелку и готовьте на пару над сильно кипящей водой 6–8 минут, в зависимости от толщины.</li><li>Смешайте бульон, соевый и устричный соусы, сахар и кунжутное масло. В сковороде на среднем огне разогрейте масло и 1–2 минуты обжарьте чеснок, имбирь и грибы. Влейте соус, добавьте белый перец и прокипятите 30 секунд.</li><li>Выключите пароварку, слейте воду, скопившуюся на тарелке с рыбой. Полейте рыбу соусом, посыпьте зелёным луком и закройте крышку ещё на 30 секунд.</li></ol><p><em>Подавайте сразу с рисом жасмин.</em></p>', CURRENT_TIMESTAMP),
  ('4c851a05-3569-5a98-be4b-d9525d0d5baf', '3e15710d-4858-5963-9773-06958089a820', 'en', 'Steamed white fish with ginger, garlic and soy sauce', 'White fish fillet steamed, then topped with a hot sauce of stock, ginger, garlic, shiitake, soy and oyster sauces.', '<ol><li>Take the soaked dried mushrooms out of the water, squeeze, cut off the stems and slice the caps thinly.</li><li>Put the fish in a deep plate and steam over vigorously boiling water 6–8 minutes depending on thickness.</li><li>Combine the stock, soy and oyster sauces, sugar and sesame oil. In a pan heat the oil over medium-high heat and stir the garlic, ginger and mushrooms 1–2 minutes. Add the sauce mix and white pepper and simmer 30 seconds.</li><li>Turn off the steamer and pour off the water collected on the plate. Spoon the sauce over the fish, top with green onions and cover for another 30 seconds.</li></ol><p><em>Serve immediately with jasmine rice.</em></p>', CURRENT_TIMESTAMP),
  ('07db5572-d38d-5e1a-94f0-bec09eba58e4', '9b870b48-ae60-5b26-8eed-09f05c74252a', 'ru', 'Цветная капуста в жёлтом карри с кокосовым молоком', 'Обжаренная цветная капуста тушится в густом соусе из жёлтой пасты карри и кокосового молока с помидорами черри.', '<ol><li>В большой сковороде на среднем огне нагрейте немного масла, добавьте соцветия цветной капусты и щепотку соли или немного рыбного соуса. Обжарьте срезом вниз несколько минут до золотистости (по желанию с двух сторон), не доводя до готовности.</li><li>В воке доведите до кипения половину кокосового молока, добавьте пасту карри и паприку и уваривайте, пока масло не начнёт отделяться и паста не зашипит. Добавьте сахар, перемешайте до растворения, влейте остальное молоко.</li><li>Добавьте лук, затем цветную капусту и перемешивайте до нужной мягкости. Если соус сильно выпарится, добавьте немного воды.</li><li>Добавьте помидоры на 30 секунд, выключите огонь, при необходимости досолите рыбным или соевым соусом, добавьте кинзу и подавайте.</li></ol><p><em>Подайте с рисом жасмин, посыпьте кинзой и жареным луком.</em></p>', CURRENT_TIMESTAMP),
  ('a2f1ddf4-a1dc-5766-8ef3-2ad327ba9296', '9b870b48-ae60-5b26-8eed-09f05c74252a', 'en', 'Cauliflower stir-fry in yellow curry with coconut milk', 'Seared cauliflower simmers in a thick yellow curry and coconut milk sauce with cherry tomatoes.', '<ol><li>Heat a little oil in a large skillet over medium-high heat, add the cauliflower with a pinch of salt or some fish sauce and sear flat side down a few minutes until browned (both sides if you like), without cooking through.</li><li>In a wok bring half the coconut milk to a boil, stir in the curry paste and paprika and reduce until the oil separates and the paste sizzles. Add the sugar, stir until mostly dissolved, then add the remaining coconut milk.</li><li>Add the onion, then the cauliflower and toss until done to your liking, adding a splash of water if the sauce dries up.</li><li>Add the tomatoes for 30 seconds, turn off the heat, season with more fish or soy sauce if needed, toss in cilantro and serve.</li></ol><p><em>Serve with jasmine rice, topped with cilantro and crispy shallots.</em></p>', CURRENT_TIMESTAMP),
  ('507cfd51-4501-5bd3-8f0c-47312de92378', 'f51cee52-9de8-59f1-9be2-9251c9d6f60c', 'ru', 'Суп с вонтонами со свининой и креветками и бок-чой', 'Вонтоны с начинкой из свиного фарша и креветок варятся и подаются в прозрачном бульоне с бок-чой, жареным чесноком и зелёным луком.', '<ol><li>Разотрите чеснок с белым перцем. В кухонном комбайне взбейте эту смесь с креветками, свиным фаршем, яйцом, соевым и устричным соусами, сахаром и крахмалом, пока не останется крупных кусков креветок. Перемешайте ещё раз.</li><li>Положите на каждый лист для вонтонов по круглой чайной ложке начинки, а остальные листы держите под полотенцем. Скрутите вонтоны «рюшами» (кошельком).</li><li>В одной кастрюле вскипятите воду для вонтонов. В другой доведите бульон до кипения, добавьте соль, соевый и рыбный соусы, сахар и белый перец, накройте и держите горячим.</li><li>Бланшируйте бок-чой в кипятке 1 минуту, выложите в миски. В той же воде варите вонтоны 1–1,5 минуты до готовности, добавьте в миски.</li><li>Залейте горячим бульоном, посыпьте жареным чесноком, острым маслом, зелёным луком или кинзой и сразу подавайте.</li></ol><p><em>Добавьте острое масло по вкусу.</em></p>', CURRENT_TIMESTAMP),
  ('da4b835b-5abe-56ef-8dae-676f79b26358', 'f51cee52-9de8-59f1-9be2-9251c9d6f60c', 'en', 'Thai-style wonton soup with pork, shrimp and bok choy', 'Wontons filled with ground pork and shrimp are boiled and served in a clear seasoned broth with bok choy, fried garlic and green onion.', '<ol><li>Pound the garlic with the white pepper. In a food processor blitz it with the shrimp, ground pork, egg, soy and oyster sauces, sugar and starch until no big shrimp chunks remain, then stir once more.</li><li>Place a rounded teaspoon of filling on each wrapper, keeping the rest covered with a towel so they don''t dry out. Fold into ruffled purses.</li><li>Bring a pot of water to a boil for the wontons. In another pot simmer the stock with the salt, soy sauce, fish sauce, sugar and white pepper, cover and keep hot.</li><li>Blanch the bok choy 1 minute in the boiling water and put in bowls. Boil the wontons in the same water 1–1½ minutes until cooked and add to the bowls.</li><li>Ladle over the hot broth, top with fried garlic, chilli oil, green onion or cilantro and serve immediately.</li></ol><p><em>Add chilli oil to taste.</em></p>', CURRENT_TIMESTAMP),
  ('b7fc92ea-a45e-5422-8723-da623babe369', 'cc9fbbea-af33-5994-9cf5-8c375563b333', 'ru', 'Тайские кукурузные оладьи с кокосовой стружкой и зелёным луком', 'Хрустящие оладьи из зёрен свежей кукурузы в лёгком кляре с кокосовой стружкой, жареные в масле до золотистого цвета.', '<ol><li>Острым ножом срежьте зёрна с початка в миску.</li><li>В другой миске смешайте муку, крахмал, соль, разрыхлитель, кокосовую стружку, зелёный лук, кунжут и халапеньо. Влейте стакан ледяной воды и размешайте до гладкого жидкого теста, остальную воду добавляйте по необходимости.</li><li>Влейте примерно 3/4 теста к кукурузе и перемешайте, при необходимости добавьте остальное.</li><li>Нагрейте в кастрюле 2–3 см масла до 190 °C. Выкладывайте тесто по полной столовой ложке и жарьте 3–4 минуты, перевернув на половине, до золотистого цвета. Переложите на бумажные полотенца и подавайте сразу.</li></ol><p><em>Подайте сразу с острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('090cbeb6-c254-57c2-87c3-60ff0cd34927', 'cc9fbbea-af33-5994-9cf5-8c375563b333', 'en', 'Thai corn fritters with coconut and green onion', 'Crispy fritters of fresh corn kernels in a light batter with shredded coconut, fried in oil until golden.', '<ol><li>Slice the kernels off the cob with a sharp knife into a bowl.</li><li>In another bowl stir the flour, cornstarch, salt, baking powder, coconut, green onion, sesame and jalapeño. Add 1 cup of ice water and stir into a smooth, pourable batter, adding more only as needed.</li><li>Pour about ¾ of the batter over the corn and mix, adding more if needed.</li><li>Heat 1 inch of oil in a pot to 375 °F (190 °C). Drop in heaping tablespoons of batter and fry 3–4 minutes, flipping halfway, until golden. Drain on paper towels and serve at once.</li></ol><p><em>Serve immediately with hot sauce.</em></p>', CURRENT_TIMESTAMP),
  ('68f5e41b-81cd-5e8a-8fa4-fb53426cccfc', 'a947f590-2495-5029-8ed1-122fc5a0204a', 'ru', 'Томатный суп-пюре с овощами, бататом и розмарином', 'Лёгкий семейный суп из помидоров, моркови, сладкого перца и батата со сливками. Хорошо замораживается, на следующий день ещё вкуснее.', '<ol><li>Разогрейте масло в большой кастрюле и готовьте лук 8–10 минут до мягкости и лёгкой золотистости.</li><li>Добавьте морковь, чеснок, перец и батат и готовьте ещё 10 минут, часто помешивая и не давая чесноку подгореть.</li><li>Добавьте помидоры, бульонный кубик, орегано, розмарин и 1 л воды. Доведите до кипения, накройте и варите 20 минут, пока батат не станет мягким.</li><li>Пюрируйте суп погружным блендером до однородности, влейте сливки и посолите по вкусу.</li></ol><p><em>Подавайте с хлебом или сырными булочками. Для малышей можно оставить без соли.</em></p>', CURRENT_TIMESTAMP),
  ('b226bab1-fa66-5f76-b592-54f9c96518d7', 'a947f590-2495-5029-8ed1-122fc5a0204a', 'en', 'Healthy five-veg creamy tomato soup with sweet potato and rosemary', 'A light family soup of tomatoes, carrots, sweet peppers and sweet potato finished with cream. Freezes well and tastes even better the next day.', '<ol><li>Heat the oil in a large pan and cook the onion 8–10 minutes until soft and just taking on colour.</li><li>Add the carrots, garlic, peppers and sweet potato and cook 10 more minutes, stirring often and taking care not to burn the garlic.</li><li>Add the tomatoes, stock cube, oregano, rosemary and 1 litre of water. Bring to a simmer, cover and cook 20 minutes until the sweet potato is soft.</li><li>Blend the soup with a hand blender until smooth, stir in the cream and season to taste.</li></ol><p><em>Serve with bread or cheese pinwheels. Can be made salt-free for young children.</em></p>', CURRENT_TIMESTAMP),
  ('474e4279-7605-5fef-baa3-051c98345a0b', '1995d6a6-2fb6-546a-9cb1-12c80a8f59e1', 'ru', 'Ньокки по-тоскански с колбасным фаршем и шпинатом', 'Быстрый ужин в одной сковороде: колбаски без оболочки, лук, паприка, орегано, шпинат и ньокки в лёгком бульоне, сверху пармезан.', '<ol><li>Разогрейте масло в большой сковороде на среднем огне и обжаривайте лук 6 минут до мягкости, не давая ему стать золотистым.</li><li>Добавьте колбасный фарш (колбаски без оболочки) и разминайте деревянной ложкой на мелкие кусочки. Готовьте 5 минут до румяности.</li><li>Посыпьте паприкой и орегано, готовьте минуту. Влейте вино и немного выпарите, затем добавьте бульон и перец и готовьте 3 минуты. Добавьте шпинат и размораживайте 5–6 минут.</li><li>Убедитесь, что бульон слегка кипит, добавьте ньокки и варите 3 минуты. Вмешайте большую часть пармезана и подавайте, посыпав остатком.</li></ol><p><em>Хорошо замораживается. Вино можно не добавлять и взять больше бульона.</em></p>', CURRENT_TIMESTAMP),
  ('fa74f71c-3958-586e-95ff-19a68029f242', '1995d6a6-2fb6-546a-9cb1-12c80a8f59e1', 'en', 'Tuscan sausage gnocchi with spinach and parmesan', 'A quick one-pan dinner of skinless sausage, onion, paprika, oregano, spinach and gnocchi in a light broth, topped with parmesan.', '<ol><li>Heat the oil in a large frying pan over medium heat and fry the onion 6 minutes until soft but not golden.</li><li>Add the sausagemeat, breaking it into small pieces with a wooden spoon. Cook 5 minutes until starting to brown.</li><li>Sprinkle in the paprika and oregano and cook 1 minute. Pour in the wine and reduce a little, then add the stock and pepper and cook 3 minutes. Add the spinach and cook 5–6 minutes until defrosted.</li><li>Make sure the stock is simmering, add the gnocchi and cook 3 minutes. Stir in most of the parmesan and serve with the rest sprinkled on top.</li></ol><p><em>Freezes well. The wine is optional; use more stock instead.</em></p>', CURRENT_TIMESTAMP),
  ('ddcc22ae-445e-576f-b1af-43b3e9a003f8', 'cd9180c7-ba18-5ab9-8cc9-f265f401c167', 'ru', 'Запечённые колбаски с бататом, кукурузой и манго на противне', 'Колбаски, красный лук, батат, початки кукурузы и манго, запечённые в пряной смеси из зиры, паприки, фенхеля, орегано и соуса барбекю. Простой семейный ужин.', '<ol><li>Разогрейте духовку до 200 °C (180 °C с конвекцией) или аэрогриль до 200 °C. Смешайте в миске ингредиенты пряного соуса: зиру, паприку, фенхель, орегано, соус барбекю и масло.</li><li>Выложите в противень четвертинки лука, кусочки кукурузы, нарезанное манго, дольки батата и колбаски. Залейте соусом, перемешайте и посолите.</li><li>Запекайте 45–50 минут, перемешав на середине, пока колбаски не прожарятся, а батат не станет мягким.</li><li>Подавайте, посыпав кинзой и острым перцем по желанию.</li></ol><p><em>Посыпьте кинзой и острым перцем. Можно заморозить для будних дней.</em></p>', CURRENT_TIMESTAMP),
  ('642d7be6-3ca5-5fbb-8498-fc1dae0a7a9c', 'cd9180c7-ba18-5ab9-8cc9-f265f401c167', 'en', 'Sausage, sweet potato, corn and mango traybake with barbecue spices', 'Sausages, red onion, sweet potato, corn on the cob and mango roasted in a spiced sauce of cumin, paprika, fennel, oregano and barbecue sauce. An easy family supper.', '<ol><li>Heat the oven to 200°C (180°C fan) or an air fryer to 200°C. Mix the spiced sauce ingredients in a bowl: cumin, paprika, fennel, oregano, barbecue sauce and oil.</li><li>Tip the onion quarters, corn, mango, sweet potato wedges and sausages into a roasting tin, pour over the sauce, stir to coat and season.</li><li>Bake 45–50 minutes, tossing halfway, until the sausages are cooked through and the sweet potato is soft.</li><li>Serve sprinkled with chopped coriander and chilli if you like.</li></ol><p><em>Sprinkle with coriander and chilli. Freezes well for busy weeknights.</em></p>', CURRENT_TIMESTAMP),
  ('1951b270-165c-5e3b-b88a-88f900def3f2', '1576b37e-f1de-51cd-97d3-a38a9ad8fbce', 'ru', 'Миска с рисом, хрустящим нутом, овощами и арахисовой заправкой', 'Бурый рис с запечённым хрустящим нутом, морковью, огурцом, красной капустой и кинзой. Заправка из арахисовой пасты, соевого соуса и лайма.', '<ol><li>Разогрейте духовку или аэрогриль до 200 °C. Смешайте ингредиенты заправки и слегка посолите.</li><li>Высыпьте высушенный бумажным полотенцем нут на противень, перемешайте с половиной заправки и запекайте 20–25 минут до золотистой хрустящей корочки. Дайте остыть 5 минут.</li><li>Остальную заправку разведите водой до жидкой консистенции. Смешайте кинзу, морковь, огурец и красную капусту, слегка посолите.</li><li>Разложите рис по мискам, сверху овощи и нут. Посыпьте листьями кинзы, кунжутом, жареным луком и перцем, полейте заправкой.</li></ol><p><em>Посыпьте кунжутом, жареным луком или перцем чили. Остатки можно взять на обед.</em></p>', CURRENT_TIMESTAMP),
  ('34ddce70-d86b-558f-ab3d-b688d4a52d9c', '1576b37e-f1de-51cd-97d3-a38a9ad8fbce', 'en', 'Peanut chickpea rice bowl with crispy chickpeas and cabbage', 'Brown rice with oven-crisped chickpeas, carrot, cucumber, red cabbage and cilantro, with a dressing of peanut butter, soy sauce and lime.', '<ol><li>Heat the oven or air fryer to 200°C (190°C fan). Mix all the dressing ingredients together and season lightly.</li><li>Pour the chickpeas, dried with kitchen paper, onto a lined baking sheet and toss with half the dressing. Bake 20–25 minutes until crispy and golden. Cool 5 minutes.</li><li>Thin the remaining dressing with water to a pourable consistency. Mix the cilantro, carrot, cucumber and red cabbage and season lightly.</li><li>Divide the rice among bowls and top with the vegetables and crispy chickpeas. Scatter with cilantro leaves, sesame seeds, crispy onions and chilli and drizzle with the dressing.</li></ol><p><em>Top with sesame seeds, crispy onions or chilli. Leftovers make a good lunch.</em></p>', CURRENT_TIMESTAMP),
  ('437f479d-86a5-5ba1-ad02-f18a00160535', '2611772a-26e3-5e37-9d5e-044927d4aecc', 'ru', 'Чечевица в кокосовом соусе с листьями карри и куркумой (большая порция)', 'Насыщенное блюдо из зелёной чечевицы с луком, чесноком, имбирём, кокосовым молоком, куркумой, зирой и листьями карри. Удобно приготовить сразу на три приёма.', '<ol><li>Разогрейте кокосовое масло в большой глубокой кастрюле на средне-сильном огне. Добавьте лук, семена горчицы, листья карри и щепотку соли и готовьте 8–10 минут, часто помешивая, пока лук слегка не карамелизуется, а семена не лопнут.</li><li>Добавьте чеснок, имбирь, чили, куркуму, кориандр, зиру и семена калинджи. Убавьте огонь до среднего и готовьте 3–4 минуты до аромата.</li><li>Влейте овощной бульон, кокосовое молоко и добавьте промытую чечевицу. Ополосните банку водой и тоже влейте. Доведите до кипения.</li><li>Варите 30–40 минут, пока чечевица не станет мягкой, а соус не уварится. Посолите по вкусу и разделите на три порции. Хранится в холодильнике 5 дней или в морозилке до 3 месяцев.</li></ol><p><em>Подавайте с рисом или лепёшками. Хранится 5 дней в холодильнике или 3 месяца в морозилке.</em></p>', CURRENT_TIMESTAMP),
  ('2b24f702-c488-50b4-ae56-c80fc06fc9ca', '2611772a-26e3-5e37-9d5e-044927d4aecc', 'en', 'Coconut, curry leaf and turmeric saucy lentils (batch)', 'A rich green lentil dish with onion, garlic, ginger, coconut milk, turmeric, cumin and curry leaves. Easy to make in one big batch for several meals.', '<ol><li>Heat the coconut oil in a large deep saucepan over medium-high heat. Add the onions, mustard seeds, curry leaves and a pinch of salt and cook 8–10 minutes, stirring often, until the onions caramelise a little and the seeds pop.</li><li>Stir in the garlic, ginger, chilli, turmeric, coriander, cumin and nigella seeds. Lower to medium and cook 3–4 minutes until fragrant.</li><li>Pour in the vegetable stock and coconut milk and add the rinsed lentils. Rinse out the coconut milk can with water and add that too. Bring to a boil.</li><li>Cook 30–40 minutes until the lentils are tender and the sauce reduced. Season to taste and divide into three batches. Keeps chilled for 5 days or frozen up to 3 months.</li></ol><p><em>Serve with rice or flatbreads. Keeps 5 days chilled or 3 months frozen.</em></p>', CURRENT_TIMESTAMP),
  ('791eb20e-562e-54ae-89f6-8c23f5564332', '58aeabba-c532-595d-bb72-24173a98f511', 'ru', 'Запечённая морковь с нутом, помидорами и фетой на противне', 'Морковь, нут и помидоры черри, запечённые с копчёной паприкой, зирой, кориандром и корицей, сверху фета с лимоном и травами. Сытное вегетарианское блюдо.', '<ol><li>Разогрейте духовку до 200 °C (180 °C с конвекцией). В большом противне смешайте 1 ст. л. масла, лук, чеснок, специи, морковь, помидоры черри и нут. Ополосните банку от помидоров водой и вылейте в противень. Посолите, поперчите, добавьте немного лимонного сока.</li><li>Запекайте 35–40 минут, пока морковь не станет мягкой, а соус не уварится.</li><li>Тем временем смешайте цедру лимона, фету и зелень с оставшимися 3 ст. л. масла.</li><li>Досолите блюдо по вкусу, добавьте лимонный сок, посыпьте фетой с зеленью и подавайте с лепёшками.</li></ol><p><em>Подавайте с лепёшками, чтобы собирать соус.</em></p>', CURRENT_TIMESTAMP),
  ('67150122-cc4c-5b40-b63f-eea34a3a5359', '58aeabba-c532-595d-bb72-24173a98f511', 'en', 'Smoky carrot and chickpea traybake with feta and herbs', 'Carrots, chickpeas and cherry tomatoes roasted with smoked paprika, cumin, coriander and cinnamon, topped with feta, lemon and herbs. A filling vegetarian supper.', '<ol><li>Heat the oven to 200°C (180°C fan). In a large roasting tin toss 1 tbsp of oil, the onion, garlic, spices, carrots, cherry tomatoes and chickpeas. Swill out the tomato can with water and pour it over. Season and add a splash of lemon juice.</li><li>Roast 35–40 minutes until the carrots are tender and the sauce has reduced.</li><li>Meanwhile, combine the lemon zest, feta and herbs with the remaining 3 tbsp of oil.</li><li>Season the traybake with salt, pepper and lemon juice, scatter over the feta mixture and serve with flatbreads.</li></ol><p><em>Serve with flatbreads for scooping up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('2551ec7a-3c31-5e43-95c8-362e27a6c4e2', 'c3635293-74e7-5978-bd69-8f636a6339a2', 'ru', 'Запечённые ньокки с ветчиной, горошком и луком-пореем в сливках', 'Ньокки с луком-пореем, зелёным горошком, копчёной рулькой и соусом из крем-фреша и горчицы, запечённые под сырно-сухарной корочкой. Простой семейный ужин.', '<ol><li>Разогрейте духовку до 220 °C (200 °C с конвекцией). Разогрейте 2 ст. л. масла в глубокой жаропрочной сковороде на среднем огне и готовьте лук-порей с щепоткой соли и перца 10–12 минут до мягкости. Добавьте горошек и готовьте 1–2 минуты.</li><li>Добавьте ветчину, мускатный орех, крем-фреш и горчицу. Убавьте огонь, перемешайте до жидкого соуса, затем добавьте ньокки и большую часть сыра. Посолите и поперчите.</li><li>Смешайте остальной сыр с сухарями и оставшейся ½ ст. л. масла и посыпьте сверху.</li><li>Запекайте в духовке 20–25 минут, пока не зарумянится и не запузырится.</li></ol><p><em>Посыпьте свежемолотым чёрным перцем. Можно подать с зелёным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('5c6c036a-0efc-5cf3-bb46-320d83db2e59', 'c3635293-74e7-5978-bd69-8f636a6339a2', 'en', 'Ham hock, pea and leek gnocchi traybake with crème fraîche', 'Gnocchi with leeks, peas, ham hock and a crème fraîche and mustard sauce, baked under a cheesy breadcrumb crust. An easy midweek family dish.', '<ol><li>Heat the oven to 220°C (200°C fan). Heat 2 tbsp oil in a large deep ovenproof frying pan over medium heat and cook the leeks with a pinch of salt and pepper 10–12 minutes until soft. Add the peas and cook 1–2 minutes more.</li><li>Stir in the ham, nutmeg, crème fraîche and mustard. Lower the heat and stir until the sauce loosens, then add the gnocchi and most of the cheese. Season to taste.</li><li>Mix the remaining cheese with the breadcrumbs and the remaining ½ tbsp oil and scatter on top.</li><li>Bake 20–25 minutes until bubbling and golden.</li></ol><p><em>Finish with freshly ground black pepper. Good with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('d806fed5-9900-50d4-bce7-b6bd7be49efc', '72e026ca-47c0-5fcb-b485-ae63124d1248', 'ru', 'Яичная запеканка на завтрак с беконом, шпинатом и грюйером', 'Запеканка из яиц с молоком, шалотом, шпинатом, беконом и сыром грюйер, запечённая до золотистой корочки. Подходит для завтрака на всю семью и заготовки на неделю.', '<ol><li>Разогрейте духовку до 180 °C и смажьте форму 23×33 см маслом.</li><li>Обжарьте нарезанный бекон на сковороде до готовности, переложите на бумажное полотенце. Оставьте на сковороде 2 ст. л. жира.</li><li>Обжарьте шалот около 2 минут до аромата, добавьте шпинат в два приёма и готовьте около 3 минут до увядания. Снимите с огня.</li><li>Взбейте яйца. Отложите 1 стакан сыра, остальной добавьте к яйцам вместе с молоком, солью, перцем, шпинатом и беконом, хорошо перемешайте.</li><li>Вылейте смесь в форму, посыпьте оставшимся сыром и запекайте 35 минут, затем 2–3 минуты под грилем до румяной корочки, следя, чтобы не подгорело.</li></ol><p><em>Дайте остыть 10 минут и нарежьте на 8 кусков.</em></p>', CURRENT_TIMESTAMP),
  ('3d8d832b-ca86-53e2-b2a2-9ca4f0ab854c', '72e026ca-47c0-5fcb-b485-ae63124d1248', 'en', 'Egg breakfast casserole with bacon, spinach and Gruyère', 'Eggs and milk baked with shallots, spinach, bacon and Gruyère until golden. Good for feeding a crowd or meal-prepping for the week.', '<ol><li>Preheat the oven to 350 °F (180 °C) and grease a 9×13-inch dish.</li><li>Cook the chopped bacon in a large skillet until done, transfer to paper towels and leave 2 tablespoons of fat in the pan.</li><li>Sauté the shallots about 2 minutes until fragrant, add the spinach in two batches and cook about 3 minutes until wilted, then remove from the heat.</li><li>Whisk the eggs. Set aside 1 cup of the cheese and stir the rest into the eggs with the milk, salt, pepper, spinach mixture and bacon.</li><li>Pour into the dish, top with the remaining cheese and bake 35 minutes, then broil 2–3 minutes until browned, watching closely.</li></ol><p><em>Cool 10 minutes and cut into 8 pieces.</em></p>', CURRENT_TIMESTAMP),
  ('2cc68738-3341-52c3-b122-191c360f60a8', 'f6ae7adc-7d18-5c7a-9409-736d2b842c18', 'ru', 'Феттучине со спаржей и яйцами пашот', 'Паста с кусочками спаржи, сверху яйцо пашот и стружка пекорино. Быстрый вегетарианский ужин, в котором желток работает как соус.', '<ol><li>Нарежьте спаржу наискосок кусочками по 2,5 см.</li><li>Отварите пасту в подсоленной воде до аль денте. За 2 минуты до готовности добавьте спаржу. Перед сливанием отлейте стакан воды.</li><li>Тем временем приготовьте яйца пашот в кипящей воде или в специальной форме и выньте шумовкой.</li><li>Верните пасту со спаржей в кастрюлю, добавьте немного воды. Разложите по 4 мискам, положите яйцо, стружку сыра и перец.</li></ol><p><em>Проколите желток и перемешайте с пастой.</em></p>', CURRENT_TIMESTAMP),
  ('a46843bb-3d6f-5672-93b8-c3960613abb8', 'f6ae7adc-7d18-5c7a-9409-736d2b842c18', 'en', 'Fettuccine with asparagus and poached eggs', 'Pasta tossed with asparagus pieces, topped with a poached egg and shaved Pecorino. A quick vegetarian dinner where the yolk becomes the sauce.', '<ol><li>Cut the asparagus on an angle into 1-inch pieces.</li><li>Cook the pasta in salted boiling water until al dente, adding the asparagus 2 minutes before it''s done. Reserve 1 cup of the pasta water before draining.</li><li>Meanwhile poach the eggs in simmering water or an egg poacher and lift out with a slotted spoon.</li><li>Return the pasta and asparagus to the pot with a splash of the water, divide among four bowls and top with an egg, shaved cheese and pepper.</li></ol><p><em>Break the yolk and mix well with the pasta.</em></p>', CURRENT_TIMESTAMP),
  ('dee1e57e-7a29-502a-8f7f-f1a17f99c2c9', 'e164dcc1-66d7-5450-b7d1-3f97821a445b', 'ru', 'Чили с индейкой, тыквой и белой фасолью', 'Густое чили из фарша индейки с томатами, тыквенным пюре, белой фасолью и шпинатом. Пряность корицы, какао и чили делает вкус глубже.', '<ol><li>Смажьте кастрюлю маслом и разогрейте на среднем огне. Обжаривайте лук и перец около 7 минут до мягкости.</li><li>Добавьте чеснок на 30 секунд, затем фарш индейки. Разбивайте комочки и готовьте 6–7 минут до готовности.</li><li>Добавьте фасоль, томаты, томатную пасту, пюре из тыквы, бульон, порошок чили, какао, корицу, зиру, соль, перец и по желанию кайенский перец.</li><li>Убавьте огонь и варите 20–30 минут, помешивая. Перед подачей добавьте шпинат и перемешайте.</li></ol><p><em>Подайте с авокадо, йогуртом или сметаной и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('0c224890-00e3-51e7-9b33-2068cb6ca35e', 'e164dcc1-66d7-5450-b7d1-3f97821a445b', 'en', 'Turkey pumpkin chili with white beans and spinach', 'A thick chili of ground turkey, tomatoes, pumpkin purée, white beans and spinach. Cinnamon, cocoa and chilli powder give it depth.', '<ol><li>Lightly oil a large pot or Dutch oven and warm over medium-high heat. Sauté the onion and bell pepper about 7 minutes until softened.</li><li>Add the garlic for 30 seconds, then the ground turkey and cook 6–7 minutes, breaking it up, until done.</li><li>Add the beans, tomatoes, tomato paste, pumpkin purée, broth, chilli powder, cocoa, cinnamon, cumin, salt, pepper and optional cayenne.</li><li>Reduce the heat and simmer 20–30 minutes, stirring occasionally. Stir in the spinach just before serving.</li></ol><p><em>Top with avocado, yogurt or sour cream and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('bef9a3df-64e4-5f48-bb0b-1bb33cb1f6eb', 'afba206f-76e4-5ec4-9324-70a998bf688e', 'ru', 'Бистекес а-ля мексикана: мексиканское рагу из говядины с томатами и халапеньо', 'Кубики говядины тушатся на слабом огне с луком, халапеньо, помидорами, орегано и зирой. Подаются с лепёшками и рисом.', '<ol><li>Посолите нарезанную кубиками (около 2 см) говядину и оставьте на час.</li><li>В чугунной сковороде или жаровне на сильном огне разогрейте масло и жарьте мясо 4–5 минут, помешивая.</li><li>Добавьте лук, халапеньо, орегано и зиру и жарьте около 10 минут, пока овощи не станут мягкими.</li><li>Убавьте огонь до слабого, добавьте томаты с соком, накройте и тушите около 45 минут, каждые 5 минут помешивая, пока мясо не станет мягким. Добавьте кинзу.</li></ol><p><em>Подайте с тёплыми кукурузными лепёшками, рисом и маринованным халапеньо.</em></p>', CURRENT_TIMESTAMP),
  ('4518627f-e2ad-59a9-b32b-74dd43f3493d', 'afba206f-76e4-5ec4-9324-70a998bf688e', 'en', 'Bisteces a la Mexicana: Mexican beef stew with tomato and jalapeño', 'Diced beef simmers slowly with onion, jalapeño, tomatoes, oregano and cumin. Served with warm tortillas and rice.', '<ol><li>Salt the beef cubes (about ¾ inch) and let them sit for 1 hour.</li><li>In a cast iron pan or Dutch oven heat the oil over high heat and cook the beef, stirring, 4–5 minutes.</li><li>Add the onion, jalapeños, oregano and cumin and cook about 10 minutes until the vegetables are tender.</li><li>Reduce to low, add the tomatoes with their juice, cover and cook about 45 minutes, stirring every 5 minutes, until the meat is tender. Stir in the cilantro.</li></ol><p><em>Serve with warm corn tortillas, rice and pickled jalapeños.</em></p>', CURRENT_TIMESTAMP),
  ('4a735cdb-f427-5f7d-9b16-89e62143df3b', '7ee47729-e8d8-5497-ab51-e5dc2c7d0a58', 'ru', 'Куриные голени с овощным «рисом» из цветной капусты и оливками', 'Низкоуглеводная версия арроз кон полло: голени тушатся с томатной пастой, луком, перцем и кинзой, затем добавляется измельчённая цветная капуста и оливки.', '<ol><li>Посолите и поперчите голени, добавьте чесночный порошок и орегано.</li><li>В средней сковороде на среднем огне разогрейте немного масла и обжарьте голени со всех сторон около 5 минут. Переложите на тарелку, сковороду протрите.</li><li>Прогрейте остальное масло, 2 минуты обжарьте лук, перец, чеснок и кинзу. Влейте воду, добавьте томатную пасту, паприку с зирой и щепотку соли, верните голени.</li><li>Накройте и тушите на средне-слабом огне 30 минут, переворачивая на середине, пока курица не станет мягкой. Переложите на тарелку.</li><li>Добавьте цветную капусту, увеличьте огонь, верните голени, добавьте оливки с ложкой рассола и тушите под крышкой 6 минут.</li></ol><p><em>Подайте прямо из сковороды с дольками лайма.</em></p>', CURRENT_TIMESTAMP),
  ('05f81052-106c-55b4-a587-53e59eba84f0', '7ee47729-e8d8-5497-ab51-e5dc2c7d0a58', 'en', 'Skillet chicken drumsticks with cauliflower rice and olives', 'A low-carb take on arroz con pollo: drumsticks braise with tomato paste, onion, pepper and cilantro, then riced cauliflower and olives are stirred in.', '<ol><li>Season the drumsticks with salt, pepper, garlic powder and oregano.</li><li>Heat a little oil in a medium skillet over medium-high heat and brown the drumsticks on all sides, about 5 minutes. Set aside and wipe the pan.</li><li>Heat the remaining oil and cook the onion, pepper, garlic and cilantro 2 minutes. Add the water, tomato paste, paprika, cumin and a pinch of salt and return the drumsticks.</li><li>Cover and cook over medium-low heat 30 minutes, turning halfway, until the chicken is tender, then move to a plate.</li><li>Add the riced cauliflower, increase the heat, return the chicken, add the olives with some brine and simmer covered about 6 minutes.</li></ol><p><em>Serve straight from the skillet with lime wedges.</em></p>', CURRENT_TIMESTAMP),
  ('4113a7cc-b6db-5284-802f-3552825d51ed', '8565b5ee-bc78-5f77-b293-982717fdee85', 'ru', 'Куриные голени в мультиварке с кленовым сиропом и дижонской горчицей', 'Голени без кожи томятся в сладко-пряном соусе из кленового сиропа, дижонской горчицы и бальзамического уксуса. Мясо отходит от кости.', '<ol><li>Посолите и поперчите голени и сложите в чашу мультиварки на 6 л.</li><li>Смешайте кленовый сироп, бальзамический уксус и дижонскую горчицу до гладкости и залейте голени так, чтобы они были покрыты.</li><li>Готовьте на режиме «высокая температура» 4 часа, пока мясо не станет мягким и готовым.</li></ol><p><em>Подайте с рисом или картофельным пюре и овощами.</em></p>', CURRENT_TIMESTAMP),
  ('3cd8187d-6238-560c-8483-386f42bde886', '8565b5ee-bc78-5f77-b293-982717fdee85', 'en', 'Slow cooker maple Dijon chicken drumsticks', 'Skinless drumsticks cook in a sweet-tangy sauce of maple syrup, Dijon mustard and balsamic vinegar until they fall off the bone.', '<ol><li>Season the drumsticks with garlic salt and pepper and place in a 6-quart slow cooker.</li><li>Whisk the maple syrup, balsamic vinegar and Dijon until smooth and pour over the drumsticks to cover.</li><li>Cook on HIGH for 4 hours until tender and cooked through.</li></ol><p><em>Serve with rice or mashed potatoes and vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('275feaae-5c92-5928-8b49-48860e5b0a3b', '542c4995-8108-508d-95d5-2bfd124a28b2', 'ru', 'Куриные тефтели с сыром пекорино и соусом из белого вина с лимоном', 'Тефтели из куриного фарша с чесноком, петрушкой и тёртым сыром обжариваются и доходят в духовке в лимонном соусе с шалотом и вином.', '<ol><li>Разогрейте духовку до 180 °C. Смешайте фарш с чесноком, яйцом, сухарями, сыром, петрушкой, базиликом, орегано, хлопьями чили, солью и перцем, не перемешивая слишком долго.</li><li>Сформируйте около 24 тефтелей диаметром 2,5 см.</li><li>В жаропрочной сковороде на среднем огне разогрейте масло и обжарьте тефтели со всех сторон около 5–6 минут. Полностью готовить не нужно. Переложите на тарелку.</li><li>В той же сковороде 5 минут тушите шалот и чеснок с щепоткой соли. Влейте вино, соскребите осадок и кипятите 2 минуты.</li><li>Добавьте ломтики лимона и бульон, верните тефтели и запекайте 15 минут, пока температура внутри не достигнет 74 °C.</li></ol><p><em>Подайте с пастой, рисом или овощами либо в булочке.</em></p>', CURRENT_TIMESTAMP),
  ('19765ddc-8cbb-5bc0-a8ff-3d4c520b7382', '542c4995-8108-508d-95d5-2bfd124a28b2', 'en', 'Chicken Romano meatballs with white wine and lemon sauce', 'Chicken meatballs with garlic, parsley and grated Romano are browned and finished in the oven in a lemony shallot and white wine sauce.', '<ol><li>Preheat the oven to 350 °F (180 °C). Mix the chicken with the garlic, egg, breadcrumbs, cheese, parsley, basil, oregano, chilli flakes, salt and pepper by hand until just combined.</li><li>Shape into about 24 meatballs about 1 inch wide.</li><li>In an oven-safe skillet over medium heat warm the oil and brown the meatballs on all sides about 5–6 minutes; they don''t need to cook through. Set aside.</li><li>In the same pan cook the shallot and garlic with a pinch of salt for 5 minutes, add the wine, scrape up the browned bits and simmer 2 minutes.</li><li>Add the lemon slices and stock, return the meatballs and bake 15 minutes until they reach 165 °F (74 °C) inside.</li></ol><p><em>Serve with pasta, rice or vegetables, or on sandwiches.</em></p>', CURRENT_TIMESTAMP),
  ('c518dae9-8b8f-5788-a37f-7da16cb61768', 'de714da1-ae5f-531f-987d-ca16a031a5f6', 'ru', 'Боулы с лососем в медово-сирачном глазури, бурым рисом и огурцом', 'Кубики лосося в глазури из мёда, шрирачи и имбиря запекаются под грилем и подаются на рисе с огурцами и авокадо.', '<ol><li>Включите гриль духовки, решётку поставьте примерно в 15 см от нагревателя. Застелите противень фольгой.</li><li>Смешайте мёд, шрирачу, соевый соус и имбирь до растворения мёда.</li><li>Нарежьте лосось кубиками по 2,5 см, выложите на противень с небольшими промежутками и смажьте глазурью. Готовьте под грилем 3–4 минуты до золотистой корочки.</li><li>Смешайте огурцы с рисовым уксусом, кунжутным маслом и солью.</li><li>В каждую миску положите по 3/4 стакана риса, сверху лосось, авокадо и огурцы. Добавьте шрирачу и кунжут.</li></ol><p><em>Добавьте ещё шрирачи и посыпьте кунжутом или фурикаке.</em></p>', CURRENT_TIMESTAMP),
  ('d2f10d26-faea-5da1-9d8e-9b93daee2562', 'de714da1-ae5f-531f-987d-ca16a031a5f6', 'en', 'Honey sriracha salmon bowls with brown rice and cucumber', 'Salmon cubes in a honey, sriracha and ginger glaze are broiled and served over rice with cucumber and avocado.', '<ol><li>Preheat the broiler with a rack about 6 inches below it and line a rimmed baking sheet with foil.</li><li>Stir the honey, sriracha, soy sauce and ginger until the honey dissolves.</li><li>Cut the salmon into 1-inch cubes, arrange with a little space on the sheet, brush with the glaze and broil 3–4 minutes until golden and flaky.</li><li>Toss the cucumber with the rice vinegar, sesame oil and salt.</li><li>Put about ¾ cup of rice in each bowl and top with salmon, avocado and cucumber, then sriracha and sesame seeds.</li></ol><p><em>Add more sriracha and sprinkle with sesame seeds or furikake.</em></p>', CURRENT_TIMESTAMP),
  ('933a0a28-85d1-593a-8aa5-78b579e9fcd9', '222ae548-eb0b-58ec-9fdc-42d88819f8be', 'ru', 'Салат из курицы-гриль с лимоном и укропом без майонеза', 'Куриное филе из готовой запечённой курицы, заправленное лимонным соком и цедрой, оливковым маслом и свежим укропом. Быстрый белковый салат.', '<ol><li>Отделите от курицы грудки, остальные части отложите на другой раз. Снимите кожу, мясо снимите с кости и разберите на кусочки руками или ножом.</li><li>Выложите в миску, добавьте укроп, лимонный сок, цедру, масло и соль, перемешайте и охладите до подачи.</li></ol><p><em>Подайте на листьях салата или с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('6bbea080-9ad1-5a6c-a8c3-19313e42fe09', '222ae548-eb0b-58ec-9fdc-42d88819f8be', 'en', 'Rotisserie chicken salad with lemon and dill (no mayo)', 'Breast meat from a cooked rotisserie chicken dressed with lemon juice and zest, olive oil and fresh dill. A quick high-protein salad.', '<ol><li>Remove the breasts from the rotisserie chicken (save the rest for another meal), take off the skin, remove the meat from the bone and break it into chunks.</li><li>Put into a bowl with the dill, lemon juice and zest, oil and salt, mix and refrigerate until ready to eat.</li></ol><p><em>Serve on lettuce leaves or with bread.</em></p>', CURRENT_TIMESTAMP),
  ('cd70ba6b-f3fb-5381-a520-5513b6151a69', '01a4d812-8a82-5732-9689-8d1771efea08', 'ru', 'Мини-тефтели из говядины и индейки в медово-лаймовом соусе', 'Небольшие тефтели из говяжьего фарша и острой индюшиной колбаски с овсянкой и зелёным луком обжариваются и томятся в мультиварке, затем заливаются соусом из мёда, соевого соуса и лайма.', '<ol><li>Смешайте говяжий фарш, колбасный фарш без оболочки, овсяные хлопья, яйца, зелёный лук, вустерский соус и хлопья чили.</li><li>Сформируйте около 60 тефтелей по 5 см.</li><li>Обжарьте тефтели партиями на смазанной сковороде на среднем огне, один раз перевернув, до румяности, и выложите в чашу мультиварки.</li><li>Готовьте под крышкой на слабом нагреве 4–5 часов или на сильном 2–2,5 часа.</li><li>Смешайте мёд, соевый соус и сок лайма, полейте тефтели и осторожно перемешайте. Подавайте сразу или держите тёплыми до часа.</li></ol><p><em>Подавайте тёплыми как закуску или с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('da084d07-6ce8-5ccb-ba17-9ab6ca627917', '01a4d812-8a82-5732-9689-8d1771efea08', 'en', 'Honey lime soy mini meatballs with beef and turkey sausage (slow cooker)', 'Mini meatballs of lean beef and spicy turkey sausage with oats and scallions are browned and slow-cooked, then glazed with honey, soy sauce and lime.', '<ol><li>Mix the ground beef, sausage meat (casings removed), oats, eggs, green onions, Worcestershire sauce and crushed red pepper.</li><li>Shape into about 60 meatballs of about 2 inches.</li><li>Brown the meatballs in batches in a lightly oiled skillet over medium heat, turning once, and transfer to the slow cooker.</li><li>Cover and cook on low for 4–5 hours or on high for 2–2½ hours.</li><li>Whisk the honey, soy sauce and lime juice, pour over the meatballs and toss gently. Serve at once or keep warm up to 1 hour.</li></ol><p><em>Serve warm as an appetiser or over rice.</em></p>', CURRENT_TIMESTAMP),
  ('69057cf4-e8aa-55eb-9733-c4393347f18a', 'dae0954b-75f7-5559-aa67-a263903399c4', 'ru', 'Хрустящий салат из брокколи и кейла с халуми, клюквой и пеканом', 'Сытный салат из сырой брокколи, промассированного кейла, обжаренного халуми, сушёной клюквы, семечек и орехов пекан с горчично-медовой заправкой.', '<ol><li>Срежьте соцветия брокколи и нарежьте на небольшие кусочки, мелко порубите стебель и отложите.</li><li>В большой миске взбейте горчицу, сок лимона, уксус, мёд, чесночный порошок и масло до эмульсии, посолите и поперчите.</li><li>Оторвите листья кейла от стеблей, грубо нарежьте и положите в заправку. Мелко порубите стебли и тоже добавьте. Руками втирайте заправку в кейл 1–2 минуты, пока он не потемнеет и не станет мягче.</li><li>Разогрейте антипригарную сковороду на средне-сильном огне и обжарьте ломтики халуми с обеих сторон по 2–3 минуты до золотистого цвета. Переложите на доску и грубо нарежьте.</li><li>Добавьте халуми, брокколи, большую часть клюквы, семян и пекана к кейлу, хорошо перемешайте и посыпьте остатками сверху.</li></ol><p><em>Хорошо подходит для обеда на работу. Халуми и орехи можно заменить на то, что есть дома.</em></p>', CURRENT_TIMESTAMP),
  ('701c3aec-a2f0-59cc-8728-2ff5439784cc', 'dae0954b-75f7-5559-aa67-a263903399c4', 'en', 'Crunchy broccoli and kale salad with halloumi, cranberries and pecans', 'A hearty salad of raw broccoli, massaged kale, fried halloumi, dried cranberries, seeds and pecans with a mustard and honey dressing.', '<ol><li>Slice the florets off the broccoli and cut into bite-size pieces, finely chop the stalk and set aside.</li><li>In a large bowl whisk the mustard, lemon juice, vinegar, honey, garlic powder and oil until emulsified, then season.</li><li>Strip the kale leaves from the stalks and roughly chop, adding them to the dressing; finely chop the stalks and add too. Rub the dressing into the kale with your hands for 1–2 minutes until darker and softer.</li><li>Heat a non-stick pan over medium-high heat and fry the halloumi slices 2–3 minutes per side until golden. Move to a board and roughly chop.</li><li>Mix the halloumi, broccoli and most of the cranberries, seeds and pecans into the kale salad, toss well and scatter the remainder on top.</li></ol><p><em>Works well as a make-ahead lunch. Swap the halloumi or nuts for what you have at home.</em></p>', CURRENT_TIMESTAMP),
  ('18e2a0e9-26d3-5b90-b782-0a1591d4887f', 'ef3549c3-40cd-5ab7-9868-5fcd0b2b8a24', 'ru', 'Запечённая морковь с маслом с семенами кориандра и цитрусовой цедрой', 'Мелкая морковь, запечённая целиком и поданная с ароматным маслом из поджаренных семян кориандра, цедры и петрушки. Нарядный гарнир к воскресному обеду.', '<ol><li>Разогрейте духовку до 200 °C (180 °C с конвекцией). Обрежьте повреждённые кончики моркови, выложите в противень, сбрызните маслом и посолите. Запекайте 45 минут, перемешав на середине.</li><li>Обжарьте семена кориандра на сухой сковороде и слегка растолките в ступке, не превращая в порошок: нужна текстура. Остудите.</li><li>Смешайте растолчённые семена, цедру цитруса и петрушку с мягким маслом. Заверните в пергамент рулетом.</li><li>Подавайте морковь с несколькими ломтиками ароматного масла сверху и свежемолотым перцем.</li></ol><p><em>Остатки ароматного масла можно хранить в холодильнике до 3 дней или в морозилке. Положите несколько ломтиков на горячую морковь.</em></p>', CURRENT_TIMESTAMP),
  ('96a61cf6-66d2-503b-ade0-39ba91c52827', 'ef3549c3-40cd-5ab7-9868-5fcd0b2b8a24', 'en', 'Roasted carrots with toasted coriander seed and citrus butter', 'Small carrots roasted whole and served with a butter flavoured with toasted coriander seeds, citrus zest and parsley. A showy side for Sunday lunch.', '<ol><li>Heat the oven to 200°C (180°C fan). Trim any damaged ends off the carrots, put in a roasting tin, drizzle with oil and salt. Roast 45 minutes, tossing halfway.</li><li>Toast the coriander seeds in a dry frying pan and crush lightly in a mortar, keeping some texture. Leave to cool.</li><li>Mix the crushed seeds, citrus zest and parsley into the softened butter and roll up in baking parchment.</li><li>Serve the carrots with a few slices of the flavoured butter on top and black pepper.</li></ol><p><em>Leftover flavoured butter keeps chilled for up to 3 days or frozen. Melt a few slices over the hot carrots.</em></p>', CURRENT_TIMESTAMP),
  ('028c804e-02e9-5f91-8934-8af972d7b701', '5507f58d-e94b-5ec1-9a8c-0b9c9ac425d9', 'ru', 'Раздавленный хрустящий молодой картофель с розмарином, тимьяном и чесноком', 'Отварной мелкий картофель слегка раздавливают и запекают с ароматным маслом до хрустящей корочки. Простой гарнир для мяса, рыбы и птицы.', '<ol><li>Положите картофель в кастрюлю с холодной подсоленной водой, доведите до кипения и варите 9–10 минут, пока нож не войдёт легко. Слейте воду и дайте картофелю подсохнуть в дуршлаге несколько минут.</li><li>Мелко порубите розмарин и тимьян, смешайте с чесночным порошком, влейте масло, добавьте соль и перец.</li><li>Разогрейте аэрогриль до 200 °C. Выложите картофель на противень и слегка раздавите донышком стакана, чтобы он сплющился, но не развалился. Смажьте ароматным маслом и выложите в аэрогриль в один слой (партиями).</li><li>Готовьте 15–20 минут, перевернув на середине, до золотистой хрустящей корочки.</li></ol><p><em>Не давите картофель слишком сильно, чтобы он не развалился. Готовить можно партиями.</em></p>', CURRENT_TIMESTAMP),
  ('a70d3c75-7a1e-593d-ab72-49db9e022e26', '5507f58d-e94b-5ec1-9a8c-0b9c9ac425d9', 'en', 'Crispy smashed potatoes with rosemary, thyme and garlic', 'Small boiled potatoes are lightly smashed and cooked with herb oil until crisp outside. A simple side for meat, fish or poultry.', '<ol><li>Put the potatoes in a pan of cold salted water, bring to the boil and cook 9–10 minutes until a knife goes in easily. Drain and steam-dry in a colander for a few minutes.</li><li>Finely chop the rosemary and thyme, mix with the garlic powder, stir in the oil and plenty of salt and pepper.</li><li>Heat the air fryer to 200°C. Put the potatoes on a tray and flatten lightly with the bottom of a glass so they hold together. Brush with the herby oil and place in the air fryer in a single layer, in batches if needed.</li><li>Cook 15–20 minutes, turning halfway, until crisp and golden.</li></ol><p><em>Don''t press too firmly or the potatoes will fall apart. Cook in batches if needed.</em></p>', CURRENT_TIMESTAMP),
  ('1859340e-ff8a-5fd8-ac8f-138a56cb4922', '4e4fa865-ba66-5b40-9760-4c4a963e661e', 'ru', 'Брокколи, запечённая в духовке с чесноком и кунжутом', 'Простой гарнир к рыбе и курице: брокколи запекается в оливковом масле до хрустящих краёв. Подойдёт тем, кто не любит варёную брокколи.', '<ol><li>Разогрейте духовку до 180 °C (160 °C с конвекцией). Разберите брокколи на соцветия, стебель грубо нарежьте и выложите на противень.</li><li>Сбрызните маслом, обильно посолите и поперчите, добавьте луковый и чесночный порошок и кунжут. Перемешайте руками и разложите в один слой.</li><li>Запекайте 25–30 минут, встряхнув противень на середине, до мягкости и хрустящих краёв. Подавайте сразу.</li></ol><p><em>Подавайте сразу или добавьте к крупам.</em></p>', CURRENT_TIMESTAMP),
  ('6b9e5f7b-eaf8-5e16-8b65-5c74c009af29', '4e4fa865-ba66-5b40-9760-4c4a963e661e', 'en', 'Oven-roasted broccoli with garlic and sesame', 'A simple side for fish or chicken: broccoli roasted in olive oil until crisp at the edges. A good way to enjoy broccoli if you don''t like it boiled.', '<ol><li>Heat the oven to 180°C (160°C fan). Break the broccoli into florets, roughly chop the stalk and put on a large tray.</li><li>Drizzle with the oil, season generously and add the onion and garlic powder and sesame seeds. Toss with your hands and spread in a single layer.</li><li>Bake 25–30 minutes, shaking the tray halfway, until tender and crisp at the edges. Serve straight away.</li></ol><p><em>Serve right away or stir into grains.</em></p>', CURRENT_TIMESTAMP),
  ('e459278f-f721-54b9-b121-c79becd88540', '7c73da2c-002a-5874-a383-c29327239967', 'ru', 'Пюре из цветной капусты со сметаной, чеддером и укропом', 'Популярный в Польше гарнир: цветная капуста на пару, взбитая со сливочным маслом, сметаной и сыром чеддер. Нежное и сытное.', '<ol><li>Нарежьте соцветия и кочерыжку цветной капусты небольшими кусочками. Готовьте на пару над кипящей водой около 10 минут до полной мягкости.</li><li>Переложите в миску, добавьте масло и сметану и взбейте блендером до гладкости (можно в кухонном комбайне).</li><li>Вмешайте сыр, посолите и поперчите. Подавайте с укропом и каплей оливкового масла.</li></ol><p><em>Посыпьте укропом и сбрызните оливковым маслом.</em></p>', CURRENT_TIMESTAMP),
  ('cd1e86db-c48e-5e72-8601-5f5aba1fb8e0', '7c73da2c-002a-5874-a383-c29327239967', 'en', 'Cauliflower purée with soured cream, cheddar and dill', 'A popular Polish side: steamed cauliflower blended with butter, soured cream and cheddar. Smooth and luxurious.', '<ol><li>Cut the cauliflower florets and stalk into bite-size pieces. Steam over simmering water for about 10 minutes until completely tender.</li><li>Tip into a bowl with the butter and soured cream and blitz smooth with a hand blender (or a food processor).</li><li>Mix in the cheese, season well and serve scattered with dill and a drizzle of olive oil.</li></ol><p><em>Scatter with dill and drizzle with olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('ba668c32-f96c-50ea-a161-3d17446cb1d9', '4b62bd67-4a8e-580b-b7e8-2d119ce02efd', 'ru', 'Запечённые кабачки с лимонной цедрой и хлопьями чили', 'Кабачки брусочками, запечённые с оливковым маслом и лимонной цедрой до мягкости и лёгкого подгорания. Лёгкий гарнир к мясу, рыбе и овощным блюдам.', '<ol><li>Разогрейте духовку до 200 °C (180 °C с конвекцией). Разрежьте кабачки на четвертинки вдоль, затем на брусочки.</li><li>Выложите на противень, сбрызните маслом, добавьте лимонную цедру, соль, перец и хлопья чили и перемешайте.</li><li>Запекайте 15–20 минут, переместив кабачки на середине, до мягкости и лёгкого подгорания.</li></ol><p><em>Подавайте горячими к любому основному блюду.</em></p>', CURRENT_TIMESTAMP),
  ('a58a3b5c-ec58-5dc3-9750-1c6baab91440', '4b62bd67-4a8e-580b-b7e8-2d119ce02efd', 'en', 'Roasted zucchini with lemon zest and chilli flakes', 'Zucchini batons roasted with olive oil and lemon zest until soft and slightly charred. A light side for meat, fish or vegetable mains.', '<ol><li>Heat the oven to 200°C (180°C fan). Cut the courgettes into quarters lengthways, then into batons.</li><li>Tip onto a baking tray, drizzle with the oil, add the lemon zest, salt, pepper and chilli flakes and toss.</li><li>Roast 15–20 minutes, moving the pieces halfway, until softened and slightly charred.</li></ol><p><em>Serve hot with any main.</em></p>', CURRENT_TIMESTAMP),
  ('41ea2cc6-53ce-5557-97f3-dd6e8ca8f2e7', '7b53350d-f6da-58cb-807a-210bb37c3adf', 'ru', 'Армянский борек: слоёные треугольники с сыром фета', 'Квадраты слоёного теста с начинкой из феты и петрушки, сложенные треугольниками и запечённые до золотистой корочки. Всего четыре ингредиента.', '<ol><li>Разогрейте духовку до 200 °C, застелите два противня пергаментом.</li><li>Разморозьте тесто, развернув, слегка присыпьте мукой и нарежьте на квадраты примерно 8–10 см (около 18–24 штук).</li><li>Смешайте тёртую или раскрошенную фету с петрушкой. В центр каждого квадрата положите полную чайную-столовую ложку начинки, сложите треугольником или прямоугольником и прижмите края пальцами, затем вилкой.</li><li>Выложите на противни, смажьте взбитым яйцом и выпекайте 18–20 минут, поменяв противни местами на середине, до золотистой корочки. Слегка остудите.</li></ol><p><em>Подавайте тёплыми или при комнатной температуре, лучше в день приготовления.</em></p>', CURRENT_TIMESTAMP),
  ('621e202e-3497-5a27-82da-429a17c186d0', '7b53350d-f6da-58cb-807a-210bb37c3adf', 'en', 'Armenian cheese borek: feta puff pastry turnovers', 'Squares of puff pastry filled with feta and parsley, folded into triangles and baked until golden. Only four ingredients.', '<ol><li>Preheat the oven to 400 °F (200 °C) and line two baking sheets with parchment.</li><li>Thaw the puff pastry, unfold it, flour lightly and cut into squares of about 3–4 inches (about 18–24 in total).</li><li>Mix the feta with the parsley. Put a heaping spoonful in the middle of each square, fold into a triangle or rectangle and press the edges with your fingers, then a fork.</li><li>Place on the sheets, brush with beaten egg and bake 18–20 minutes, swapping the pans halfway, until golden. Cool slightly.</li></ol><p><em>Serve warm or at room temperature, best on the day they''re baked.</em></p>', CURRENT_TIMESTAMP),
  ('40ce8a60-09f6-5bd7-806c-46da8960e0a1', 'a5a358d8-88f1-57f6-adfd-b08444920254', 'ru', 'Армянские запечённые манты с говядиной и чесночным йогуртом', 'Маленькие лодочки из теста с начинкой из говяжьего фарша запекаются, затем доходят в бульоне и подаются с йогуртом с чесноком и сумахом.', '<ol><li>Взбейте яйца с водой, солью и оливковым маслом. Сделайте в муке углубление, влейте смесь и замесите гладкое тесто (вручную или в миксере с крюком 3–4 минуты). Накройте полотенцем на 30 минут.</li><li>Смешайте фарш с луком, петрушкой, солью, перцем и паприкой. Уберите в холодильник.</li><li>Разогрейте духовку до 200 °C и смажьте маслом два противня 23×33 см. Тесто частями раскатайте очень тонко, нарежьте квадратами по 4 см.</li><li>В центр каждого квадрата положите по 1/2 ч. л. начинки и соедините концы пальцами, получится лодочка. Плотно выложите манты в противни, сверху разложите кусочки масла.</li><li>Запекайте 40–50 минут до золотистого цвета. Тем временем смешайте йогурт с чесноком и солью, а бульон с водой доведите до кипения, посолите и поперчите.</li><li>Залейте манты горячим бульоном на 3/4 высоты и верните в духовку ещё на 10 минут, пока большая часть бульона не впитается.</li><li>Подавайте в мисках с добавлением бульона, чесночным йогуртом и сумахом.</li></ol><p><em>Подайте в глубоких мисках с бульоном, йогуртовым соусом и сумахом.</em></p>', CURRENT_TIMESTAMP),
  ('e89257d3-3b7d-572c-bf8b-a95518ab3a7c', 'a5a358d8-88f1-57f6-adfd-b08444920254', 'en', 'Armenian baked beef manti with garlic yogurt', 'Tiny canoe-shaped dumplings of beef filling are baked, finished in broth and served with garlicky yogurt and sumac.', '<ol><li>Beat the eggs with the water, salt and oil. Make a well in the flour, add the wet mix and knead into a smooth dough (by hand or 3–4 minutes with a dough hook). Cover and rest 30 minutes.</li><li>Mix the ground beef with the onion, parsley, salt, pepper and paprika and chill.</li><li>Preheat the oven to 400 °F (200 °C) and grease two 9×13-inch pans with butter. Roll the dough very thin in batches and cut into 1½-inch squares.</li><li>Place ½ teaspoon of filling in the centre of each square and pinch two ends to form a canoe. Pack the manti close together in the pans and dot with butter.</li><li>Bake 40–50 minutes until golden. Meanwhile stir the yogurt with the garlic and salt, and simmer the stock with the water, salt and pepper.</li><li>Ladle the broth over the manti until about ¾ up their sides and bake 10 minutes longer until most of the broth is absorbed.</li><li>Serve in bowls with more hot broth, garlic yogurt and sumac.</li></ol><p><em>Serve in wide bowls with broth, yogurt sauce and sumac.</em></p>', CURRENT_TIMESTAMP),
  ('b478f457-be23-5b0a-86f9-b09648147d83', 'e9362057-4457-5a52-8eb3-bc1ee3df5fb3', 'ru', 'Армянский суп с говяжьими фрикадельками, рисом, картофелем и морковью', 'Мелкие говяжьи фрикадельки с рисом варятся в томатно-куриной основе с картофелем и морковью. Сытный суп без глютена и молочных продуктов.', '<ol><li>Смешайте руками говяжий фарш, промытый рис, мелко нарезанную треть лука, петрушку, соль, паприку и перец. Смачивая ладони, скатайте шарики диаметром около 2,5 см (около 120 штук) и уберите в холодильник.</li><li>В кастрюле на среднем огне прогрейте масло, 2–3 минуты обжарьте оставшийся лук, затем морковь ещё 2–3 минуты.</li><li>Влейте бульон и томатный соус, приправьте солью, перцем и паприкой, доведите до кипения. Добавьте картофель и варите 18–20 минут, пока он не будет почти готов.</li><li>Осторожно добавьте фрикадельки, помешивая, доведите до лёгкого кипения и варите 10 минут, пока рис внутри не будет готов. Добавьте петрушку и подавайте.</li></ol><p><em>Посыпьте петрушкой и подайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('c1b8f748-dde9-55a6-8ae7-90b90ba8f098', 'e9362057-4457-5a52-8eb3-bc1ee3df5fb3', 'en', 'Armenian meatball soup with rice, potatoes and carrots', 'Small beef and rice meatballs simmer in a tomato and chicken broth with potatoes and carrots. A hearty gluten-free and dairy-free soup.', '<ol><li>Mix the beef, rinsed rice, minced third of the onion, parsley, salt, paprika and pepper by hand. With wet palms roll into 1-inch meatballs (about 120) and refrigerate.</li><li>Warm the oil in a pot over medium-high heat, sauté the remaining onion 2–3 minutes, then the carrots 2–3 minutes.</li><li>Add the broth and tomato sauce, season with salt, pepper and paprika and bring to a boil. Add the potatoes and simmer 18–20 minutes until almost cooked.</li><li>Carefully add the meatballs, stirring, bring to a gentle boil and simmer 10 minutes until the rice inside is cooked. Stir in the parsley and serve.</li></ol><p><em>Sprinkle with parsley and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('4faa2718-1901-585c-83f3-90d98b34eb98', 'b0871b64-1255-5c04-99f6-b57bd7a2db8d', 'ru', 'Масала с курицей в сливочно-томатном соусе (баттер чикен)', 'Курица в йогуртовом маринаде с пряностями запекается и подаётся в нежном соусе из томатов, сливок и масла с имбирём и чесноком.', '<ol><li>Смешайте йогурт, лимонный сок, чеснок, имбирь, зиру, гарам масалу, соль, куркуму и острый перец. Добавьте курицу, перемешайте и уберите в холодильник минимум на 2 часа, лучше на ночь.</li><li>За 30 минут до готовки достаньте курицу. Разогрейте духовку до 220 °C и застелите противень.</li><li>Выложите кусочки курицы на противень с промежутками (маринад не стирайте, но остатки не добавляйте) и запекайте 15–20 минут до готовности.</li><li>Тем временем растопите в кастрюле масло, минуту обжарьте чеснок с имбирём, затем 15–30 секунд специи (гарам масала, кориандр, острый перец).</li><li>Влейте томатное пюре, сливки, добавьте соль и сахар. Когда закипит, убавьте огонь и варите 5–7 минут.</li><li>Добавьте запечённую курицу и тушите на слабом огне ещё несколько минут, пока соус не станет густым и бархатистым. Посыпьте кинзой и подавайте.</li></ol><p><em>Подайте с рисом басмати или лепёшкой наан.</em></p>', CURRENT_TIMESTAMP),
  ('f9461842-1110-5b23-a706-cfd0d25f610c', 'b0871b64-1255-5c04-99f6-b57bd7a2db8d', 'en', 'Murgh makhani: Indian butter chicken with yogurt marinade', 'Chicken marinated in spiced yogurt, roasted and finished in a silky tomato, cream and butter sauce with ginger and garlic.', '<ol><li>Combine the yogurt, lemon juice, garlic, ginger, cumin, garam masala, salt, turmeric and chilli powder, add the chicken, coat and chill at least 2 hours, ideally overnight.</li><li>Take the chicken out 30 minutes before cooking. Preheat the oven to 425 °F (220 °C) and line a baking sheet.</li><li>Arrange the chicken pieces with gaps (leave the marinade on but don''t add extra) and roast 15–20 minutes until cooked through.</li><li>Meanwhile melt the butter in a pot, cook the garlic and ginger 1 minute, then the spices (garam masala, coriander, chilli) 15–30 seconds.</li><li>Stir in the tomato passata, cream, salt and sugar. When it bubbles, reduce the heat and simmer 5–7 minutes.</li><li>Add the roasted chicken and simmer a few more minutes until the sauce is thick and velvety. Garnish with cilantro and serve.</li></ol><p><em>Serve with basmati rice or naan.</em></p>', CURRENT_TIMESTAMP),
  ('f87af979-7608-5167-8ae8-00208a27f74e', 'bf787048-b283-5539-8d12-6c5d418a082f', 'ru', 'Курица корма в йогуртовом соусе с кешью', 'Мягкое индийское карри: курица в маринаде из йогурта, измельчённых орехов и специй, затем тушится с пюре из обжаренного лука и сливками.', '<ol><li>Мелко измельчите кешью или миндаль в комбайне, добавьте йогурт, томатную пасту, чеснок, имбирь и все специи и взбейте до гладкости. Переложите в миску.</li><li>Добавьте курицу, перемешайте и уберите в холодильник на 2 часа или на ночь.</li><li>В большой сковороде на среднем огне разогрейте масло и обжаривайте лук 5–7 минут до мягкости и золотистости. Взбейте лук с ложкой-двумя бульона в пюре.</li><li>В той же сковороде готовьте курицу с маринадом около 7 минут. Влейте бульон, пюре из лука и сахар, убавьте огонь и тушите без крышки 7 минут до загустения.</li><li>Влейте сливки и готовьте ещё 3–4 минуты. Отрегулируйте соль, переложите в миску, украсьте орехами и зеленью и подавайте с рисом.</li></ol><p><em>Подайте с рисом басмати и посыпьте орехами и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('456cd82d-bf22-518d-bda3-f49f26c62e8d', 'bf787048-b283-5539-8d12-6c5d418a082f', 'en', 'Chicken korma in cashew yogurt sauce', 'A mild Indian curry: chicken marinated in yogurt, ground nuts and spices, then simmered with a purée of browned onion and cream.', '<ol><li>Finely grind the cashews or almonds in a food processor, add the yogurt, tomato paste, garlic, ginger and all the spices and process until smooth. Transfer to a bowl.</li><li>Add the chicken, coat well and chill 2 hours or overnight.</li><li>In a large skillet over medium heat warm the oil and cook the onion 5–7 minutes until soft and golden. Purée with a splash of broth.</li><li>In the same skillet cook the chicken with its marinade about 7 minutes. Add the broth, onion purée and sugar, reduce the heat and cook uncovered 7 minutes until thickened.</li><li>Stir in the cream and cook 3–4 more minutes, adjust the salt, transfer to a bowl, garnish with nuts and herbs and serve with rice.</li></ol><p><em>Serve with basmati rice, garnished with nuts and herbs.</em></p>', CURRENT_TIMESTAMP),
  ('7537dc8e-e4a2-54f9-8393-2505e6bef884', 'b5e57b3b-fce8-5ce5-8208-bce2809dbadb', 'ru', 'Итальянский куриный суп с мелкой пастой пастина и овощным пюре', 'Лёгкий куриный суп с морковью, сельдереем, луком и чесноком, частично пюрированный, с маленькими звёздочками пасты и кусочками курицы.', '<ol><li>В большой кастрюле соедините бульон, морковь, сельдерей, лук, чеснок, лавровый лист, тимьян, корку пармезана (если есть), соль и перец. Накройте, доведите до кипения и варите 10 минут до мягких овощей.</li><li>Выньте лавровый лист и корку. По желанию пробейте часть или все овощи погружным блендером или перенесите их с частью бульона в блендер и верните в кастрюлю.</li><li>Доведите суп до кипения, добавьте пасту и варите 5–10 минут до готовности. В последние 2 минуты добавьте курицу.</li><li>Попробуйте и досолите. Разлейте по мискам, посыпьте петрушкой и подайте с пармезаном.</li></ol><p><em>Посыпьте петрушкой, тёртый пармезан подайте отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('72de96a4-8725-5cf2-a2aa-e25a4d148e33', 'b5e57b3b-fce8-5ce5-8208-bce2809dbadb', 'en', 'Italian chicken pastina soup with puréed vegetables', 'A light chicken soup with carrot, celery, onion and garlic, partly puréed, with tiny pasta stars and shredded chicken.', '<ol><li>In a large pot combine the broth, carrots, celery, onion, garlic, bay leaf, thyme, Parmesan rind (if using), salt and pepper. Cover, bring to a boil and simmer 10 minutes until the vegetables are tender.</li><li>Remove the bay leaf and rind. If you like, purée some or all of the vegetables with a stick blender, or blend them with a little broth and return to the pot.</li><li>Bring back to a boil, add the pastina and cook 5–10 minutes until tender, stirring in the shredded chicken for the last 2 minutes.</li><li>Taste and adjust the seasoning, ladle into bowls, sprinkle with parsley and serve with Parmesan.</li></ol><p><em>Sprinkle with parsley and serve grated Parmesan on the side.</em></p>', CURRENT_TIMESTAMP),
  ('6b2ec655-999c-5f17-afb7-0ef0d18e8fa9', '3b2a7189-ea8c-51bc-a0a9-2fbbffed9815', 'ru', 'Пирог с курицей и пореем под слоёным тестом', 'Классический британский пирог: курица и порей в сливочном соусе с горчицей и тимьяном под золотистой крышкой из слоёного теста.', '<ol><li>Разогрейте духовку до 200 °C. Выложите курицу на противень, посолите и поперчите и запекайте 15–25 минут до 75 °C внутри. Остудите и разберите на волокна.</li><li>Растопите масло в большой сковороде на среднем огне, обжарьте порей с тимьяном и щепоткой соли 5–8 минут до мягкости.</li><li>Всыпьте муку и перемешивайте минуту. Постепенно влейте бульон, доведите до кипения и варите до загустения 5 минут. Добавьте сливки, горчицу и курицу, посолите и поперчите.</li><li>Переложите начинку в круглую жаропрочную форму или сковороду, накройте листом слоёного теста, прижав края, и смажьте яйцом. Сделайте в центре небольшие надрезы для пара.</li><li>Запекайте 25–30 минут до золотистой крышки и бурлящей начинки.</li></ol><p><em>Подайте с зелёным горошком или салатом.</em></p>', CURRENT_TIMESTAMP),
  ('bf30395a-3355-5af7-93ec-b44d3b9a3fc7', '3b2a7189-ea8c-51bc-a0a9-2fbbffed9815', 'en', 'Chicken and leek pie with puff pastry lid', 'A classic British pie: chicken and leeks in a creamy mustard-thyme sauce under a golden puff pastry lid.', '<ol><li>Heat the oven to 400 °F (200 °C). Season the chicken on a baking sheet and roast 15–25 minutes until 165 °F (75 °C). Cool and shred.</li><li>Melt the butter in a large skillet over medium heat and cook the leeks with the thyme and a pinch of salt 5–8 minutes until soft.</li><li>Stir in the flour for a minute, gradually pour in the stock, bring to a boil and simmer 5 minutes until thick. Stir in the cream, mustard and chicken and season.</li><li>Transfer the filling to a round ovenproof dish or skillet, cover with the puff pastry sheet pressing the edges, brush with egg and cut small slits for steam.</li><li>Bake 25–30 minutes until the pastry is golden and the filling bubbles.</li></ol><p><em>Serve with peas or a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('8d69d2fb-443a-5f1b-88cf-2aabeee067ee', '8f23a485-16cd-5377-8a6e-9974ca772062', 'ru', 'Овсянка на ночь с чиа, миндальной пастой и ягодами', 'Холодный завтрак без готовки: овсяные хлопья с семенами чиа и ореховой пастой, залитые молоком и оставленные в холодильнике на ночь. Сверху ягоды.', '<ol><li>В банке или миске смешайте овсяные хлопья с корицей, семена чиа и ореховую пасту. Влейте немного молока и разотрите пасту с хлопьями, затем добавьте остальное молоко и перемешайте.</li><li>Сверху положите ягоды (мягкие фрукты вроде банана или яблока лучше добавить при подаче). Закройте крышкой и уберите в холодильник на ночь (до 5 дней).</li><li>Перед подачей при желании добавьте немного кленового сиропа или мёда. Ешьте охлаждённой.</li></ol><p><em>Рецепт на одну банку, умножайте на нужное число порций. Мёд или кленовый сироп добавляйте при подаче.</em></p>', CURRENT_TIMESTAMP),
  ('2b0fb1a9-aea0-5473-b115-a86c78919012', '8f23a485-16cd-5377-8a6e-9974ca772062', 'en', 'Overnight oats with chia, almond butter and berries', 'A no-cook cold breakfast: oats with chia seeds and nut butter, covered with milk and left in the fridge overnight, topped with berries.', '<ol><li>In a jar or bowl combine the oats with the cinnamon, chia seeds and nut butter. Add a splash of milk and work the nut butter into the oats, then add the rest of the milk and stir.</li><li>Top with the berries (add soft fruit such as banana or apple just before serving). Cover and refrigerate overnight or up to 5 days.</li><li>Add a drizzle of maple syrup or honey if you like and serve chilled.</li></ol><p><em>The recipe makes one jar; multiply as needed. Add maple syrup or honey when serving.</em></p>', CURRENT_TIMESTAMP),
  ('b23f221e-2e85-5ccb-a159-62e167218c8c', '83886c68-fd32-5c72-8edd-3e39801858e8', 'ru', 'Мюсли бирхер с яблоком, овсянкой, изюмом и миндальной пастой', 'Холодные мюсли по-швейцарски: овсяные хлопья, изюм, корица, ореховая паста и яблочное пюре, залитые молоком, с тёртым яблоком. Выстаиваются минимум 30 минут.', '<ol><li>В банке или миске смешайте овсяные хлопья, изюм, корицу, ореховую пасту и яблочное пюре. Добавьте молоко и перемешайте.</li><li>Половину яблока натрите на тёрке и вмешайте в овсянку.</li><li>Закройте крышкой и уберите в холодильник минимум на 30 минут (можно до 5 дней).</li><li>Перед подачей нарежьте оставшуюся половину яблока соломкой, положите сверху, добавьте орехи, немного молока и мёд по желанию.</li></ol><p><em>Перед подачей добавьте соломку из яблока, немного молока, орехи и мёд.</em></p>', CURRENT_TIMESTAMP),
  ('86f8f165-9f63-5389-979f-e2062c5ee23c', '83886c68-fd32-5c72-8edd-3e39801858e8', 'en', 'Bircher muesli with apple, oats, raisins and almond butter', 'Swiss-style cold muesli: oats, raisins, cinnamon, nut butter and applesauce covered with milk, with grated apple. Rests at least 30 minutes.', '<ol><li>In a jar or bowl combine the oats, raisins, cinnamon, nut butter and applesauce. Add the milk and stir.</li><li>Grate half of the apple and stir it into the oats.</li><li>Cover and refrigerate for at least 30 minutes, or up to 5 days.</li><li>Before serving cut the remaining apple half into matchsticks and add on top with nuts, a splash of milk and honey if you like.</li></ol><p><em>Top with apple matchsticks, a splash of milk, nuts and honey before serving.</em></p>', CURRENT_TIMESTAMP),
  ('0c0c2373-9e66-5f09-822f-8107c9354288', '0d44d1e2-24ee-59e7-9a40-461f7c657813', 'ru', 'Тост с авокадо на цельнозерновом хлебе', 'Хрустящий тост с мягко размятым авокадо и щепоткой соли. Простой завтрак или лёгкий перекус.', '<ol><li>Поджарьте ломтик хлеба до золотистого цвета и плотной корочки.</li><li>Вынимите косточку из авокадо, выньте мякоть ложкой в миску и разомните вилкой до желаемой консистенции. Добавьте щепотку соли и при желании ещё.</li><li>Намажьте авокадо на тост. Подавайте как есть или с добавками, например, крупной солью.</li></ol><p><em>Ешьте сразу, пока авокадо не потемнело. Сверху можно добавить яйцо, помидоры, зелень или хлопья чили.</em></p>', CURRENT_TIMESTAMP),
  ('0e455724-0784-59cd-b748-48ea65da5fe7', '0d44d1e2-24ee-59e7-9a40-461f7c657813', 'en', 'Avocado toast on whole-grain bread', 'Crisp toast with lightly mashed ripe avocado and a pinch of salt. A simple breakfast or light snack.', '<ol><li>Toast the slice of bread until golden and firm.</li><li>Remove the pit from the avocado, scoop the flesh into a bowl and mash with a fork until as smooth as you like. Mix in a pinch of salt and more to taste.</li><li>Spread the avocado on the toast. Enjoy as is or with extra toppings such as flaky salt.</li></ol><p><em>Eat right away before the avocado browns. Add an egg, tomato, herbs or chili flakes on top.</em></p>', CURRENT_TIMESTAMP),
  ('376b5106-c159-5877-b4dc-cb895b45e2dc', '0d6c56fb-aba9-57e4-867c-3a33b5f9f5fa', 'ru', 'Хэш из батата с нутом и заатаром и яйцом-пашот', 'Кубики батата, обжаренные в оливковом масле с красным луком, сладким перцем и нутом, приправленные кориандром, паприкой, куркумой и заатаром, с яйцом-пашот сверху.', '<ol><li>Доведите до слабого кипения воду для пашот в среднем горшке на среднем и слабом огне.</li><li>В сковороде 30 см разогрейте масло на средне-сильном огне. Добавьте красный лук, батат и нут, посолите и поперчите (по ½ ч. л.), добавьте кориандр, зиру, паприку и куркуму. Готовьте, часто помешивая, 10–15 минут, пока лук не карамелизуется, а батат заметно не размягчится.</li><li>Убавьте огонь до среднего, добавьте чеснок и перец и готовьте ещё 5–10 минут, пока перец не размягчится, а батат не будет готов. Посыпьте заатаром.</li><li>В кипящую воду влейте уксус. Разбейте яйца по одному в чашку и осторожно вылейте в воду, помешав воду. Варите ровно 3 минуты, достаньте шумовкой на бумажное полотенце, посолите, поперчите и посыпьте заатаром.</li><li>Разложите хэш по 4 мискам, сверху положите яйцо-пашот и подавайте сразу.</li></ol><p><em>Яйцо можно приготовить любым способом. Разрежьте желток, чтобы он растёкся по батату.</em></p>', CURRENT_TIMESTAMP),
  ('55e89fe1-7f7a-54ea-8691-f2ad9f082bcd', '0d6c56fb-aba9-57e4-867c-3a33b5f9f5fa', 'en', 'Sweet potato and chickpea hash with za''atar and poached eggs', 'Cubed sweet potatoes cooked in olive oil with red onion, bell pepper and chickpeas, seasoned with coriander, paprika, turmeric and za''atar, topped with a poached egg.', '<ol><li>Bring a medium pot of water to a steady simmer over medium-low heat for poaching.</li><li>In a 12-inch skillet heat the oil over medium-high. Add the red onion, sweet potatoes and chickpeas, season with ½ tsp each salt and pepper, add the coriander, cumin, paprika and turmeric. Cook, stirring often, 10–15 minutes until the onion caramelizes and the sweet potatoes soften.</li><li>Reduce to medium, add the garlic and bell pepper and cook another 5–10 minutes until the pepper is soft and the potatoes cooked through. Sprinkle with za''atar.</li><li>Add the vinegar to the simmering water. Crack each egg into a ramekin and slide gently into the swirled water. Cook exactly 3 minutes, lift out with a slotted spoon onto paper towel and season with salt, pepper and a little za''atar.</li><li>Divide the hash among 4 bowls, top each with a poached egg and serve immediately.</li></ol><p><em>The eggs can be cooked any way you like. Cut into the yolk and let it run over the sweet potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('d679fe01-ca52-5154-9476-8edc016a3dbf', '4b168944-b65a-57e9-a54b-3cfc1ff7c060', 'ru', 'Салат с печёным бататом, кускусом, руколой, фетой и миндалём', 'Сытный салат из запечённого батата, жемчужного кускуса, рукколы, красного лука, феты и обжаренного миндаля с медово-лимонной заправкой.', '<ol><li>Разогрейте духовку до 200 °C и застелите противень пергаментом. Очистите батат и нарежьте кусочками по 2 см.</li><li>Перемешайте батат с ¼ стакана масла, солью и перцем. Выложите на противень одним слоем и запекайте 30–45 минут, перемешав на середине, до мягкости, карамелизации и лёгких подпалин. Остудите.</li><li>Влейте 1 ст. л. масла в миску, добавьте кускус и соль, залейте кипятком, накройте и оставьте на 5–10 минут, пока он не впитает воду. Взрыхлите вилкой и остудите.</li><li>Подсушите миндаль на сухой сковороде на слабом и среднем огне 5–10 минут до золотистого цвета, часто помешивая.</li><li>Для заправки взбейте мёд, лимонный сок, чеснок, горчицу, масло, соль и перец.</li><li>На большое блюдо выложите рукколу, смешанную с несколькими чайными ложками заправки. Сверху разложите батат и кускус, посыпьте луком, фетой и миндалём и полейте заправкой.</li></ol><p><em>Выложите на плоское блюдо и поливайте заправкой перед подачей. Хватает на самостоятельное блюдо.</em></p>', CURRENT_TIMESTAMP),
  ('96626855-a728-57af-81a8-d52f82b0aa24', '4b168944-b65a-57e9-a54b-3cfc1ff7c060', 'en', 'Roasted sweet potato salad with pearl couscous, arugula, feta and almonds', 'A filling salad of roasted sweet potato, pearl couscous, arugula, red onion, feta and toasted almonds with a honey-lemon dressing.', '<ol><li>Preheat the oven to 200°C (390°F) and line a baking tray with parchment. Peel the sweet potato and cut into 2 cm pieces.</li><li>Toss the sweet potato with ¼ cup of oil, salt and pepper. Spread in a single layer and bake 30–45 minutes, tossing halfway, until soft, caramelized and slightly charred. Cool.</li><li>Drizzle 1 tbsp oil into a bowl, add the couscous and salt and cover with boiling water. Cover and let sit 5–10 minutes until the liquid is absorbed. Fluff with a fork and cool.</li><li>Toast the almonds in a dry pan over low-medium heat 5–10 minutes until golden, tossing often.</li><li>For the dressing whisk the honey, lemon juice, garlic, mustard, oil, salt and pepper.</li><li>On a large platter spread the arugula tossed with a few teaspoons of dressing. Layer the sweet potato and couscous on top, scatter with onion, feta and almonds and drizzle with the dressing.</li></ol><p><em>Assemble on a flat platter and dress just before serving. Filling enough for a meal.</em></p>', CURRENT_TIMESTAMP),
  ('dfe5a6f5-857b-5b36-b996-da6b1b531f45', 'ae0e8cb2-3056-506a-86e2-a6e72b7f44c4', 'ru', 'Салат из помидоров с фетой, петрушкой, укропом и сумахом', 'Салат из спелых помидоров с красным луком, чесноком, большим количеством свежей зелени и сумахом, заправленный оливковым маслом и лимоном, сверху крупные куски феты.', '<ol><li>В большой миске аккуратно смешайте помидоры, лук, чеснок, петрушку и укроп.</li><li>Добавьте сумах, посолите и поперчите. Влейте лимонный сок, уксус и оливковое масло и перемешайте. Попробуйте и подправьте вкус.</li><li>Переложите на блюдо и сверху положите крупные куски хорошей феты.</li></ol><p><em>Подавайте с хорошим хлебом, чтобы обмакивать в томатный сок.</em></p>', CURRENT_TIMESTAMP),
  ('8a73dda4-15a2-5808-a2f5-440431259787', 'ae0e8cb2-3056-506a-86e2-a6e72b7f44c4', 'en', 'Tomato salad with feta, parsley, dill and sumac', 'Ripe tomatoes with red onion, garlic, plenty of fresh herbs and sumac, dressed with olive oil and lemon and topped with large pieces of feta.', '<ol><li>In a large bowl gently toss the tomatoes, onion, garlic, parsley and dill.</li><li>Add the sumac, season with salt and pepper, then add the lemon juice, vinegar and olive oil and toss. Taste and adjust.</li><li>Transfer to a platter and top with large pieces of good feta.</li></ol><p><em>Serve with good bread to soak up the tomato juices.</em></p>', CURRENT_TIMESTAMP),
  ('c98def33-3705-5a95-824c-95531ea082f9', '0398040d-37a1-54ba-9ad0-77791b81f57c', 'ru', 'Салат со свёклой, апельсином, яблоком, рукколой и фетой', 'Холодный салат из варёной свёклы, апельсина и зелёного яблока на рукколе с фетой и грецкими орехами в лимонной греческой заправке.', '<ol><li>Для заправки (ладолемоно) взбейте оливковое масло с лимонным соком и щепоткой орегано и соли.</li><li>Выложите на блюдо рукколу и шалот, полейте 2–3 ст. л. заправки и перемешайте.</li><li>Разложите сверху дольки апельсина, яблока и свёклы. Полейте ещё заправкой.</li><li>Посыпьте фетой и грецкими орехами и подавайте.</li></ol><p><em>Подавайте как гарнир к рыбе или мясу. Красную свёклу можно заменить золотистой.</em></p>', CURRENT_TIMESTAMP),
  ('27b1271e-ef37-50b5-a2a5-4e947e36d2e9', '0398040d-37a1-54ba-9ad0-77791b81f57c', 'en', 'Beet salad with orange, apple, arugula, feta and walnuts', 'A cold salad of cooked beets, orange and green apple over arugula with feta and walnuts in a lemony Greek dressing.', '<ol><li>For the ladolemono dressing whisk the olive oil with the lemon juice and a pinch of oregano and salt.</li><li>Put the arugula and shallots on a platter, drizzle with 2–3 tbsp of the dressing and toss.</li><li>Arrange the orange, apple and beet slices on top and drizzle with more dressing.</li><li>Sprinkle with feta and walnuts and serve.</li></ol><p><em>Serve as a side with fish or meat. Golden beets work in place of red.</em></p>', CURRENT_TIMESTAMP),
  ('2853ebfb-b1c8-56d5-a8f5-a90e581c7c5a', 'e9df0a89-da79-58e7-a6fe-1e62897eac08', 'ru', 'Быстрое кимчи из пекинской капусты', 'Хрустящая пекинская капуста с морковью и редисом в чесночно-имбирной пасте с чили. Готовится за час и подаётся как острая закуска или гарнир.', '<ol><li>Нарежьте капусту полосками по 2,5 см, посолите, перемешайте и оставьте на 1 час. За это время взбейте в блендере чеснок, имбирь, рыбный соус, шрирачу, сахар и рисовый уксус в пасту.</li><li>Промойте капусту холодной водой и тщательно обсушите. Переложите в большую миску, добавьте пасту, натёртые редис и морковь, нашинкованный зелёный лук и перемешайте.</li><li>Подавайте сразу или плотно уложите в банку и оставьте на ночь при комнатной температуре для брожения, затем уберите в холодильник. Хранится до 2 недель.</li></ol><p><em>Подавайте к рису, жареному мясу или лапше.</em></p>', CURRENT_TIMESTAMP),
  ('d20e38a5-1f68-580b-abe7-f23b21fb3aeb', 'e9df0a89-da79-58e7-a6fe-1e62897eac08', 'en', 'Quick kimchi with Chinese cabbage', 'Crunchy Chinese cabbage with carrot and radish in a garlic, ginger and chilli paste. Ready in about an hour and served as a spicy side.', '<ol><li>Slice the cabbage into 2.5 cm strips, mix with the salt and leave for 1 hour. Meanwhile blitz the garlic, ginger, fish sauce, sriracha, sugar and rice vinegar into a paste.</li><li>Rinse the cabbage under cold water and dry it thoroughly. Put it in a large bowl and toss with the paste, grated radish and carrot and shredded spring onions.</li><li>Serve right away, or pack into a jar and leave at room temperature overnight to ferment, then chill. It keeps for up to 2 weeks.</li></ol><p><em>Serve with rice, grilled meat or noodles.</em></p>', CURRENT_TIMESTAMP),
  ('7ccf499e-947c-538e-8e78-93406d477a73', 'fbd62011-730e-5659-9b17-97f7dc58dc15', 'ru', 'Куриные бёдра на картофельном гратене', 'Куриные бёдра с ароматным сухим рубом запекаются на картофеле в молоке с пармезаном. Куриный сок пропитывает гратен, и получается целое блюдо в одной сковороде.', '<ol><li>Разогрейте духовку до 180 °C. Смешайте луковый и чесночный порошок, паприку, тимьян, ½ ч. л. соли и перец и натрите курицу, больше всего со стороны кожи.</li><li>Разогрейте масло в жаропрочной сковороде на среднем огне. Обжаривайте курицу кожей вниз 10 минут, чтобы вытопился жир, переверните, жарьте 2 минуты и переложите на тарелку.</li><li>Слейте жир, но сковороду не вытирайте. На среднем сильном огне 2 минуты обжарьте лук с чесноком, влейте половину молока и соскоблите подгоревшие кусочки со дна.</li><li>Выложите половину тонко нарезанного картофеля, посыпьте солью, перцем и половиной пармезана. Повторите слой, залейте оставшимся молоком и 10 минут томите, придавливая картофель лопаткой.</li><li>Положите курицу на картофель и запекайте 40–50 минут, пока курица не приготовится, а картофель не зарумянится. Дайте постоять 5 минут.</li></ol><p><em>Подайте со свежим салатом или зелёной фасолью.</em></p>', CURRENT_TIMESTAMP),
  ('50b26ec4-e22e-597b-b129-16bb7d3b238d', 'fbd62011-730e-5659-9b17-97f7dc58dc15', 'en', 'Chicken thighs on potato gratin', 'Chicken thighs rubbed with herbs and paprika bake on top of sliced potatoes in milk and parmesan. The chicken juices flavour the gratin, so the whole dinner comes out of one pan.', '<ol><li>Preheat the oven to 180°C. Mix the onion and garlic powders, paprika, thyme, ½ tsp salt and pepper, and rub it onto the chicken, mostly on the skin side.</li><li>Heat the oil in an ovenproof frying pan over medium heat. Cook the chicken skin side down for 10 minutes to render the fat, flip and cook 2 minutes, then move to a plate.</li><li>Pour off the fat without wiping the pan. Over medium-high heat sauté the onion and garlic for 2 minutes, add half the milk and scrape up the browned bits from the bottom.</li><li>Layer in half the thinly sliced potatoes with salt, pepper and half the parmesan. Add the rest of the potatoes and parmesan, pour over the remaining milk and simmer for 10 minutes, pressing the potatoes down.</li><li>Place the chicken on top of the potatoes and bake for 40–50 minutes until the chicken is cooked and the potatoes are golden. Rest for 5 minutes.</li></ol><p><em>Serve with a fresh salad or green beans.</em></p>', CURRENT_TIMESTAMP),
  ('e3fbe095-7af8-5439-a5e8-852870db20d3', '1b7c6af5-8224-50d8-8b47-60b511b41d9b', 'ru', 'Боул с фарро, чечевицей и нутом', 'Сытный средиземноморский боул: зерновая основа, бобовые, обжаренные кабачки, свежие овощи, оливки и заправка из лимона с дижонской горчицей.', '<ol><li>Отварите фарро по инструкции на упаковке и дайте немного остыть.</li><li>Разогрейте 2 ст. л. масла на сковороде, обжарьте кружки кабачка с двух сторон до мягкости, выложите на бумажное полотенце и слегка посолите.</li><li>Взболтайте в закрытой банке масло, лимонный сок, чеснок, горчицу, соль, перец, заатар и сумах.</li><li>Разложите по четырём мискам фарро, чечевицу и нут, сверху выложите кабачки, помидоры, шалот, авокадо, петрушку и оливки. Полейте заправкой и посыпьте фетой.</li></ol><p><em>Перед подачей перемешайте боул, чтобы заправка пропитала все ингредиенты.</em></p>', CURRENT_TIMESTAMP),
  ('50310f0c-cb83-58c0-bc7e-34edd7438248', '1b7c6af5-8224-50d8-8b47-60b511b41d9b', 'en', 'Mediterranean farro, lentil and chickpea bowl', 'A hearty Mediterranean bowl with farro, lentils and chickpeas, sautéed zucchini, fresh vegetables, olives and a lemon-Dijon dressing.', '<ol><li>Cook the farro following the package instructions and let it cool a little.</li><li>Heat 2 tbsp oil in a pan and fry the zucchini rounds on both sides until tender. Drain on paper towel and season lightly with salt.</li><li>Shake the olive oil, lemon juice, garlic, mustard, salt, pepper, za''atar and sumac in a closed jar.</li><li>Divide the farro, lentils and chickpeas among four bowls and top with zucchini, tomatoes, shallot, avocado, parsley and olives. Drizzle with dressing and sprinkle with feta.</li></ol><p><em>Toss everything in the bowl before eating so the dressing coats it all.</em></p>', CURRENT_TIMESTAMP),
  ('1298f9dc-53a0-5837-b872-a2183a3d2fe0', '0f8e990a-6170-5c84-adcb-ab632afbdabb', 'ru', 'Курица в хрустящей панировке с пюре и салатом', 'Тонкие куриные отбивные с корочкой из майонеза, пармезана и панировочных сухарей запекаются под грилем за 8 минут. Подаются с картофельным пюре и салатом из огурцов и помидоров.', '<ol><li>Включите гриль на максимум и поставьте решётку примерно на 20 см от нагревателя. Картофель в кожуре запекайте в микроволновке на полной мощности 3 минуты, переверните и готовьте ещё 2 минуты до мягкости.</li><li>Смешайте майонез с пармезаном. Выложите курицу в жаропрочную сковороду и намажьте смесью каждый кусок, затем посыпьте сухарями и прижмите пальцами.</li><li>Готовьте курицу под грилем около 8 минут до золотистой корочки; на 6-й минуте проверьте и при необходимости поверните сковороду. Дайте постоять несколько минут.</li><li>Разрежьте картофель пополам, выньте мякоть ложкой, добавьте молоко, масло, соль и перец и разомните в пюре, подбирая густоту молоком.</li><li>Срежьте с огурца ленты овощечисткой, помидоры разрежьте пополам, сбрызните лимонным соком и маслом, посолите и поперчите. Подавайте курицу на пюре, салат рядом.</li></ol><p><em>Посыпьте курицу рубленой петрушкой и полейте оливковым маслом.</em></p>', CURRENT_TIMESTAMP),
  ('93c7923b-9bf1-50e2-a66c-e2fafbcabea8', '0f8e990a-6170-5c84-adcb-ab632afbdabb', 'en', 'Crunchy crumbed chicken with mash and salad', 'Thin chicken steaks coated in a mayonnaise and parmesan crust with breadcrumbs, grilled in 8 minutes. Served with mashed potato and a cucumber and tomato salad.', '<ol><li>Turn the grill on high with the rack about 20 cm from the heat. Microwave the unpeeled potatoes on high for 3 minutes, flip and cook 2 minutes more until soft.</li><li>Mix the mayonnaise and parmesan. Place the chicken in an ovenproof pan, spread the mixture over each piece, sprinkle with breadcrumbs and pat them down.</li><li>Grill the chicken for about 8 minutes until golden and cooked through, checking at 6 minutes and rotating the pan if needed. Rest for a few minutes.</li><li>Halve the potatoes, scoop out the flesh, add the milk, butter, salt and pepper and mash, adjusting the thickness with more milk.</li><li>Peel the cucumber into ribbons, halve the tomatoes, dress with lemon juice and oil, and season. Serve the chicken on the mash with the salad on the side.</li></ol><p><em>Sprinkle the chicken with chopped parsley and drizzle with olive oil.</em></p>', CURRENT_TIMESTAMP),
  ('029422a3-8240-52ca-9bc8-c53bd02afb5d', 'fddec1e3-a373-554e-9bc4-2d491fcca88a', 'ru', 'Салат из сладкого перца с укропом', 'Быстрый салат из тонко нарезанного сладкого перца и лука с укропом, уксусом и оливковым маслом. Даже лучше на следующий день.', '<ol><li>Удалите у перцев плодоножки и семена, разрежьте вдоль пополам и нарежьте тонкой соломкой. Сложите в большую миску.</li><li>Тонко нарежьте лук, добавьте его в миску вместе с рубленым укропом.</li><li>Взбейте вилкой уксус, масло, чесночную соль и перец, залейте салат и хорошо перемешайте. Подавайте сразу или уберите в холодильник на несколько часов.</li></ol><p><em>Хорошо подходит к картофельному пюре и жареному мясу.</em></p>', CURRENT_TIMESTAMP),
  ('812f2401-e565-5164-a315-fb5c0330de27', 'fddec1e3-a373-554e-9bc4-2d491fcca88a', 'en', 'Sweet pepper and dill salad', 'A quick salad of thinly sliced sweet peppers and onion with dill, vinegar and olive oil. It tastes even better the next day.', '<ol><li>Remove the tops and seeds from the peppers, halve them lengthwise and cut into thin strips. Put them in a large bowl.</li><li>Thinly slice the onion and add it to the bowl with the chopped dill.</li><li>Whisk the vinegar, oil, garlic salt and pepper with a fork, pour over the salad and toss well. Serve right away or chill for a few hours.</li></ol><p><em>Great alongside mashed potatoes or grilled meat.</em></p>', CURRENT_TIMESTAMP),
  ('c48b5ef0-bbeb-5f2d-831a-e01f588540f3', 'be4d31c1-2838-5091-92e9-c6a3011559da', 'ru', 'Слоёные тако с курицей и кукурузной сальсой', 'Стопки из кукурузных тортилий, пряной курицы, сыра и сальсы из кукурузы и помидоров, запечённые до расплавленного сыра. Подаются со сметаной и зеленью.', '<ol><li>Разогрейте духовку до 180 °C. Нарезанное полосками куриное бедро смешайте с чесночным порошком, зирой, паприкой, орегано, кайенским перцем, солью, перцем и соком лайма.</li><li>Обжарьте курицу на сильном огне в масле до румяности и полной готовности. Остудите и порвите вилкой или нарежьте мелко.</li><li>Для сальсы обжарьте кукурузу в масле на сильном огне пару минут до румяных пятен (шаг можно пропустить), остудите и смешайте с нарезанными помидорами, зелёным луком, соком лайма, солью и перцем.</li><li>Подсушите тортильи в духовке по 3–5 минут с каждой стороны, чтобы они стали плотнее, но не подрумянились.</li><li>На противне соберите стопки: тортилья, курица, сальса, сыр, затем повторите ещё дважды и накройте четвёртой тортильей. Должно получиться две стопки.</li><li>Выпекайте 10 минут, пока всё не прогреется и сыр не расплавится. Подавайте с оставшейся сальсой, сметаной, кинзой, авокадо и халапеньо.</li></ol><p><em>Сверху добавьте сметану, кинзу, авокадо и немного халапеньо.</em></p>', CURRENT_TIMESTAMP),
  ('f4b13734-4224-578b-84ad-2b6a91b2b446', 'be4d31c1-2838-5091-92e9-c6a3011559da', 'en', 'Taco stack with Mexican chicken and corn salsa', 'Stacks of corn tortillas layered with spiced chicken, cheese and a corn and tomato salsa, baked until the cheese melts. Finished with sour cream and herbs.', '<ol><li>Preheat the oven to 180°C. Toss the sliced chicken thigh with the garlic powder, cumin, paprika, oregano, cayenne, salt, pepper and lime juice.</li><li>Sauté the chicken in oil over high heat until browned and cooked through. Cool slightly and shred with a fork or chop.</li><li>For the salsa, sauté the corn in oil over high heat for a couple of minutes until lightly charred (optional), cool slightly and toss with the diced tomatoes, spring onion, lime juice, salt and pepper.</li><li>Warm the tortillas in the oven for 3–5 minutes per side so they firm up without browning.</li><li>On a baking tray build stacks: tortilla, chicken, salsa, cheese, repeat twice more and top with a fourth tortilla. You should end up with two stacks.</li><li>Bake for 10 minutes until heated through and the cheese melts. Serve with the remaining salsa, sour cream, cilantro, avocado and jalapeño.</li></ol><p><em>Top with sour cream, cilantro, avocado and a little jalapeño.</em></p>', CURRENT_TIMESTAMP),
  ('f58c6aae-559c-5d1d-8c34-7d9be98638ce', 'a861ce1f-f1bf-5db8-9d84-0d490ba7a225', 'ru', 'Свекольник холодный', 'Освежающий холодный суп из отварной свёклы и картофеля со свежим огурцом, зеленью и чесноком. Подаётся со сметаной и яйцом.', '<ol><li>Очистите свёклу и картофель, нарежьте тонкой соломкой.</li><li>Выложите свёклу и картофель в кастрюлю, залейте 1,5 л воды, добавьте уксус и чеснок. Доведите до кипения и варите на слабом огне около 20 минут до мягкости.</li><li>Добавьте сахар и соль, проварите ещё 2 минуты и уберите отвар в холодильник остывать.</li><li>Огурцы нарежьте тонкой соломкой, яйца сварите вкрутую и разрежьте пополам.</li><li>В холодный суп добавьте зелёный лук, огурцы и укроп, при необходимости досолите или подсластите.</li><li>Охладите суп в холодильнике несколько часов. Подавайте с половинкой яйца и сметаной.</li></ol><p><em>Подавайте охлаждённым со сметаной, половинкой варёного яйца и ржаным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('f1002769-8a35-5643-807f-916561e77563', 'a861ce1f-f1bf-5db8-9d84-0d490ba7a225', 'en', 'Svekolnik (cold beet soup)', 'A refreshing cold soup of boiled beets and potatoes with fresh cucumber, herbs and garlic, served with sour cream and egg.', '<ol><li>Peel the beets and potatoes and cut them into thin strips.</li><li>Put the beets and potatoes in a saucepan with 1.5 l water, the vinegar and garlic. Bring to a boil and simmer about 20 minutes until tender.</li><li>Stir in the sugar and salt, cook 2 more minutes, then chill the soup in the fridge.</li><li>Cut the cucumbers into thin strips; hard-boil the eggs and halve them.</li><li>Add the green onion, cucumbers and dill to the cold soup and adjust the salt and sugar.</li><li>Chill for a few hours. Serve with half an egg and a spoonful of sour cream.</li></ol><p><em>Serve well chilled with sour cream, half a boiled egg and rye bread.</em></p>', CURRENT_TIMESTAMP),
  ('89fc1568-3eeb-597c-b1e9-a024bba76478', '4a10d059-b273-5092-a40e-8fee97a4f62e', 'ru', 'Котлеты с томатной подливкой и пастой', 'Говяжьи котлеты, обжаренные в муке и протушенные в подливке из томатной пасты с грибами и сладким перцем. Подаются с пастой или пюре.', '<ol><li>Смешайте фарш с тёртым луком, чесноком, сухарями, яйцом, петрушкой, солью и перцем.</li><li>Сформуйте круглые слегка приплюснутые котлеты и обваляйте в муке, стряхнув лишнее.</li><li>Обжарьте котлеты на разогретом масле по 2–3 минуты с каждой стороны до лёгкой корочки.</li><li>Отдельно карамелизуйте лук, затем обжарьте грибы до золотистого цвета (7–8 минут) и на 1–2 минуты обжарьте кубики красного перца.</li><li>Растопите масло, добавьте муку и жарьте 2 минуты, постоянно помешивая. Добавьте томатную пасту и ещё минуту прогрейте.</li><li>Добавьте лук, постепенно влейте горячую воду, размешивая до однородности. Положите лавровый лист и варите 5 минут до загустения, посолите и поперчите.</li><li>Переложите котлеты в кастрюлю, сверху выложите грибы и перец, залейте подливкой и тушите на слабом огне 10 минут.</li><li>Пока тушатся котлеты, отварите пасту по инструкции на упаковке и подайте с котлетами и подливкой.</li></ol><p><em>Подавайте с макаронами-спиралями или картофельным пюре.</em></p>', CURRENT_TIMESTAMP),
  ('548e48c8-ceeb-55b1-8d20-f7cf193cd74c', '4a10d059-b273-5092-a40e-8fee97a4f62e', 'en', 'Russian kotleti with tomato gravy and pasta', 'Beef patties dusted in flour, fried and simmered in a tomato-roux gravy with mushrooms and sweet pepper, served over pasta.', '<ol><li>Mix the ground beef with the grated onion, garlic, breadcrumbs, egg, parsley, salt and pepper.</li><li>Shape into rounded, slightly flattened patties and coat lightly in flour, shaking off the excess.</li><li>Fry the patties in hot oil 2–3 minutes per side until lightly golden.</li><li>Separately caramelize the onion, brown the mushrooms for 7–8 minutes, and flash-fry the red pepper for 1–2 minutes.</li><li>Melt the butter, stir in the flour and cook 2 minutes, stirring constantly. Add the tomato paste and cook 1 more minute.</li><li>Add the onion, slowly whisk in the hot water until smooth, add the bay leaf and simmer 5 minutes until thickened. Season.</li><li>Put the patties in a pot, top with the mushrooms and pepper, pour over the gravy and simmer 10 minutes.</li><li>Meanwhile cook the pasta according to the package and serve with the patties and gravy.</li></ol><p><em>Serve over spiral pasta or with mashed potatoes.</em></p>', CURRENT_TIMESTAMP),
  ('eff02553-7192-50b0-af2b-c78c008b8a65', '5e4b6e5d-7e6d-5cdb-8144-bc60efd5b0fd', 'ru', 'Солянка мясная сборная', 'Густой наваристый суп на говяжьем бульоне с копчёностями, солёными огурцами, оливками и лимоном. Кисло-солёный, согревающий.', '<ol><li>Обжарьте говяжьи рёбра в масле до корочки, в конце добавьте лук, чеснок и морковь для бульона.</li><li>Влейте 5 л воды, добавьте лавровый лист, доведите до кипения и варите на слабом огне под неплотной крышкой около часа. Процедите бульон (должно остаться около 4 л).</li><li>Снимите мясо с костей и нарежьте кусочками. Овощи и кости выбросьте.</li><li>Лук нарежьте кубиками, морковь натрите, огурцы нарежьте мелкой соломкой. Бекон и колбасы нарежьте кусочками и обжарьте до лёгкой хрусткости.</li><li>В кастрюле обжарьте лук до прозрачности, добавьте морковь, затем огурцы и готовьте 3–4 минуты. Добавьте томатную пасту, через 5 минут влейте огуречный рассол.</li><li>Добавьте обжаренные мясные продукты и говядину, влейте бульон, доведите до кипения и варите 15 минут.</li><li>Добавьте оливки и сок половины лимона, при необходимости посолите (колбасы уже солёные). Подавайте с долькой лимона, сметаной и укропом.</li></ol><p><em>Подавайте со сметаной, зеленью, долькой лимона и ржаным хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('6f9fb8ef-98a2-52b5-8731-df18d548a9a0', '5e4b6e5d-7e6d-5cdb-8144-bc60efd5b0fd', 'en', 'Solyanka (Russian meat and pickle soup)', 'A hearty, tangy soup built on beef broth with smoked meats, pickled cucumbers, olives and lemon.', '<ol><li>Sear the beef ribs in oil until crusted; in the last minutes add the onion, garlic and carrot for the broth.</li><li>Add 5 l water and the bay leaves, bring to a boil and simmer partially covered for about an hour. Strain the broth (about 4 l should remain).</li><li>Pull the meat off the bones and cut it into bite-size pieces; discard the bones and vegetables.</li><li>Dice the onions, grate the carrot, cut the pickles into small strips. Slice the bacon and sausages and fry until slightly crisp.</li><li>In the pot fry the onions until translucent, add the carrot, then the pickles and cook 3–4 minutes. Stir in the tomato paste, cook 5 minutes, and pour in the pickle brine.</li><li>Add the fried meats and beef, pour in the broth, bring to a boil and simmer 15 minutes.</li><li>Stir in the olives and the juice of half a lemon; salt only if needed. Serve with a lemon slice, sour cream and dill.</li></ol><p><em>Serve with sour cream, dill, a lemon slice and dark rye bread.</em></p>', CURRENT_TIMESTAMP),
  ('00adbe3c-bf52-577f-9520-3248fe44cfab', 'b4364f2d-7e36-5264-b001-32ffb99f61ff', 'ru', 'Запечённый баклажан с тахини, гранатом и кедровыми орехами', 'Золотистые кружки баклажана с заатаром и сумахом, петрушкой, гранатом и обжаренными кедровыми орехами. Подаются с соусом из тахини.', '<ol><li>Нарежьте баклажан кружками толщиной 2–2,5 см, посолите с обеих сторон, выложите на бумажные полотенца и оставьте на 30 минут, чтобы вышла влага.</li><li>Разогрейте духовку до 200 °C. Для соуса взбейте тахини с лимонным соком, измельчённым чесноком, солью и водой до гладкости и кремовой густоты.</li><li>Обсушите баклажан, щедро смажьте оливковым маслом с обеих сторон и разложите на противне с промежутками. Запекайте 20 минут, переверните и готовьте ещё 10–15 минут до золотистого цвета.</li><li>Обжарьте кедровые орехи на сухой сковороде до золотистого цвета.</li><li>Выложите баклажан на блюдо, посыпьте заатаром и сумахом, полейте соусом тахини и украсьте петрушкой, зёрнами граната и кедровыми орехами.</li></ol><p><em>Подавайте как гарнир или мезе с тёплой питой.</em></p>', CURRENT_TIMESTAMP),
  ('9b22316a-b727-5032-9a36-201e6d1ea95c', 'b4364f2d-7e36-5264-b001-32ffb99f61ff', 'en', 'Roasted eggplant with tahini, pomegranate and pine nuts', 'Golden roasted eggplant rounds seasoned with za''atar and sumac, topped with parsley, pomegranate seeds and toasted pine nuts, served with tahini sauce.', '<ol><li>Slice the eggplant into 2–2.5 cm rounds, salt both sides, lay them on paper towels and leave for 30 minutes to draw out moisture.</li><li>Preheat the oven to 200°C. For the sauce, whisk the tahini with lemon juice, minced garlic, salt and water until smooth and creamy.</li><li>Pat the eggplant dry, brush both sides generously with olive oil and arrange on a baking sheet with space between. Roast 20 minutes, flip and roast another 10–15 minutes until golden.</li><li>Toast the pine nuts in a dry pan until golden.</li><li>Arrange the eggplant on a platter, sprinkle with za''atar and sumac, drizzle with tahini sauce and top with parsley, pomegranate seeds and pine nuts.</li></ol><p><em>Serve as a side or mezze with warm pita.</em></p>', CURRENT_TIMESTAMP),
  ('3bb1eea4-9271-5601-a054-7d432183e987', '890f0a0d-fd58-531f-baf9-a714f47d29dc', 'ru', 'Салат из апельсинов и авокадо с красным луком', 'Свежий зимний салат из ломтиков апельсина и авокадо с хрустящим красным луком, соком лайма, кинзой и оливковым маслом.', '<ol><li>Тонко нарежьте красный лук и замочите в ледяной воде на 10–20 минут: он станет хрустящим и мягче по вкусу.</li><li>Очистите апельсины и нарежьте кружками по 6 мм. Выложите на большое блюдо слоями вместе с тонкими ломтиками авокадо.</li><li>Хорошо отожмите лук и разложите между и поверх фруктов. Сбрызните лаймовым соком и посолите.</li><li>Посыпьте семенами калинджи и листьями кинзы, полейте оливковым маслом и сразу подавайте.</li></ol><p><em>Подавайте сразу после заправки, пока авокадо не потемнел.</em></p>', CURRENT_TIMESTAMP),
  ('8424b7d2-08bd-551f-8329-a5b69443f964', '890f0a0d-fd58-531f-baf9-a714f47d29dc', 'en', 'Orange and avocado salad with red onion', 'A bright winter salad of orange and avocado slices with crisp red onion, lime juice, cilantro and olive oil.', '<ol><li>Thinly slice the red onion and soak it in ice water for 10–20 minutes to make it crisp and milder.</li><li>Peel the oranges and slice into 6 mm rounds. Layer them on a large plate with thin avocado slices.</li><li>Drain the onion well and tuck it between and over the fruit. Drizzle with lime juice and sprinkle with salt.</li><li>Scatter with nigella seeds and cilantro leaves, drizzle with olive oil and serve at once.</li></ol><p><em>Serve right after dressing, before the avocado darkens.</em></p>', CURRENT_TIMESTAMP),
  ('228e301b-edad-539c-b0ad-d3188ce58908', 'c526f7d2-13ee-51ff-818a-97c15b722016', 'ru', 'Капоната сицилийская', 'Тушёные баклажаны с луком, перцем, сельдереем и томатами, оливками, каперсами и изюмом в кисло-сладком соусе. Вкуснее на следующий день.', '<ol><li>Разогрейте духовку до 200 °C. Нарежьте баклажан кубиками по 2,5 см, посолите и оставьте на 20–30 минут, затем промокните бумажным полотенцем.</li><li>Смешайте баклажан с 3 ст. л. оливкового масла, разложите на противне и запекайте 25–30 минут до румяности.</li><li>Разогрейте 2 ст. л. масла на большой сковороде, обжаривайте лук, перец и сельдерей с солью и чёрным перцем 5–7 минут до мягкости.</li><li>Добавьте томаты, каперсы, оливки, изюм, мёд, лавровый лист и хлопья чили, влейте уксус и вино. Тушите на слабом огне 10 минут.</li><li>Добавьте запечённый баклажан и прогрейте 2–3 минуты. Уберите лавровый лист, посыпьте петрушкой и мятой.</li></ol><p><em>Подавайте при комнатной температуре с хлебом, как закуску или гарнир к рыбе и мясу.</em></p>', CURRENT_TIMESTAMP),
  ('92c009ce-ba10-52d1-8845-e79c963a6e46', 'c526f7d2-13ee-51ff-818a-97c15b722016', 'en', 'Sicilian caponata', 'Roasted eggplant with onion, pepper, celery and tomato, olives, capers and raisins in a sweet-and-sour sauce. It tastes best the next day.', '<ol><li>Preheat the oven to 200°C. Cut the eggplant into 2.5 cm cubes, salt them and let sit for 20–30 minutes, then pat dry.</li><li>Toss the eggplant with 3 tbsp olive oil, spread on a baking sheet and roast for 25–30 minutes until browned.</li><li>Heat 2 tbsp oil in a large skillet and cook the onion, pepper and celery with salt and black pepper for 5–7 minutes until soft.</li><li>Add the tomatoes, capers, olives, raisins, honey, bay leaf and chilli flakes, then pour in the vinegar and wine. Simmer over medium-low heat for 10 minutes.</li><li>Stir in the roasted eggplant and cook 2–3 minutes. Remove the bay leaf and finish with parsley and mint.</li></ol><p><em>Serve at room temperature with bread, as a starter or a side for fish and meat.</em></p>', CURRENT_TIMESTAMP),
  ('4a5a5c69-7618-53d2-99ec-aaa0460bf00c', '909ad15c-6fe1-5499-b924-2e47c9463f16', 'ru', 'Запеканка из хлеба с курицей, шпинатом и сыром', 'Кубики багета, курица, шпинат и сыр заливаются яично-молочной смесью и запекаются до золотистой корочки. Удобный способ пустить в дело остатки курицы и хлеба.', '<ol><li>Разморозьте шпинат и тщательно отожмите лишнюю воду. Взбейте яйца с молоком, пармезаном, солью и перцем.</li><li>Выложите в форму 25×25 см половину кубиков хлеба, затем шпинат, курицу и половину тёртого сыра. Закройте оставшимся хлебом и придавите.</li><li>Залейте яичной смесью так, чтобы пропитался весь хлеб, посыпьте оставшимся сыром и снова придавите. Оставьте минимум на 15–30 минут.</li><li>Разогрейте духовку до 180 °C. Накройте форму фольгой и выпекайте 20 минут, затем снимите фольгу и запекайте ещё 10 минут до золотистой корочки.</li></ol><p><em>Посыпьте рубленой петрушкой и подайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('5d0d79ef-5ff3-586c-9baa-461eba5bda65', '909ad15c-6fe1-5499-b924-2e47c9463f16', 'en', 'Chicken, spinach and cheese bread bake (strata)', 'Bread cubes, chicken, spinach and cheese soaked in an egg and milk custard and baked until golden. A handy way to use leftover chicken and bread.', '<ol><li>Thaw the spinach and squeeze out the excess water. Whisk the eggs with the milk, parmesan, salt and pepper.</li><li>Spread half the bread cubes in a 25×25 cm baking dish, then layer the spinach, chicken and half the cheese. Top with the remaining bread and press down.</li><li>Pour over the egg mixture so it soaks all the bread, top with the remaining cheese and press down again. Leave for at least 15–30 minutes.</li><li>Preheat the oven to 180°C. Cover the dish with foil and bake for 20 minutes, then remove the foil and bake 10 more minutes until golden.</li></ol><p><em>Sprinkle with chopped parsley and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('4cee70ff-8e66-56dd-95e8-7dc73b3a87ab', 'f39f86d3-0bdc-5db4-8af4-377989836023', 'ru', 'Нут в соусе Генерала Цо с брокколи и перцем', 'Быстрое вегетарианское блюдо в китайском стиле: нут, брокколи и сладкий перец в сладко-остром соусе из соевого соуса, хойсина и абрикосового джема.', '<ol><li>При необходимости отварите рис или другую крупу. Промойте нут, обсушите полотенцем.</li><li>Смешайте воду, соевый соус, хойсин, джем, рисовый уксус, имбирь, крахмал и 1 ст. л. соуса чили с чесноком. По вкусу добавьте ещё соуса.</li><li>Разогрейте масло в большой сковороде или воке на средне-сильном огне. Обжарьте брокколи и перец 2 минуты, добавьте чеснок, белую часть лука и нут.</li><li>Готовьте ещё 3 минуты, затем влейте соус, доведите до кипения и варите около 2 минут, пока он не загустеет.</li><li>Посыпьте зелёным луком и кунжутом и подавайте горячим.</li></ol><p><em>Подавайте с бурым рисом или киноа и посыпьте кунжутом.</em></p>', CURRENT_TIMESTAMP),
  ('28b11c54-3ec2-5a3e-9550-82640f2807c5', 'f39f86d3-0bdc-5db4-8af4-377989836023', 'en', 'General Tso''s chickpeas with broccoli and peppers', 'A quick vegan Chinese-style stir-fry of chickpeas, broccoli and sweet peppers in a sticky sweet-spicy sauce of soy, hoisin and apricot jam.', '<ol><li>Prepare the rice or other grain if serving with it. Rinse the chickpeas and pat dry with a towel.</li><li>Whisk the water, soy sauce, hoisin, jam, rice vinegar, ginger, cornstarch and 1 tbsp chilli garlic sauce. Add more chilli sauce if you like more heat.</li><li>Heat the oil in a large nonstick skillet or wok over medium-high heat. Stir-fry the broccoli and peppers for 2 minutes, then add the garlic, white parts of the green onion and chickpeas.</li><li>Cook 3 more minutes, pour in the sauce, bring to a simmer and cook about 2 minutes until thickened.</li><li>Sprinkle with the green onion tops and sesame seeds and serve hot.</li></ol><p><em>Serve over brown rice or quinoa and sprinkle with sesame seeds.</em></p>', CURRENT_TIMESTAMP),
  ('018c6895-8e17-57aa-aca3-f4841bb7aa4e', 'a09d3bcf-7c47-5d78-a5df-e882c81fce02', 'ru', 'Завтрак-кесадилья с беконом, яйцом и сыром', 'Двойные цельнозерновые тортильи с яичницей-болтуньей, хрустящим беконом и тягучим сыром, обжаренные до золотистой корочки.', '<ol><li>Обжарьте бекон на сковороде на среднем огне до хруста. Переложите на бумажное полотенце, жир слейте в миску, оставив 1–2 ст. л. для яиц.</li><li>Взбейте яйца с молоком, солью и перцем. Вылейте на сковороду и приготовьте болтунью до готовности, переложите яйца в миску, а сковороду протрите.</li><li>Разложите три тортильи, на каждую выложите сыр, болтунью, раскрошенный бекон и ещё сыр, накройте оставшимися тортильями.</li><li>Обжарьте кесадильи на 2 ст. л. оставленного жира на средне-сильном огне с двух сторон до хруста и расплавленного сыра. Разрежьте на клинья.</li></ol><p><em>Подавайте со сметаной, сальсой или острым соусом.</em></p>', CURRENT_TIMESTAMP),
  ('78623fc6-c82a-53c6-aef9-2a9697267c28', 'a09d3bcf-7c47-5d78-a5df-e882c81fce02', 'en', 'Bacon, egg and cheese breakfast quesadilla', 'Double-decker whole-wheat tortillas filled with scrambled eggs, crisp bacon and melty cheese, fried until golden.', '<ol><li>Fry the bacon in a skillet over medium heat until crisp. Drain on paper towel and pour the fat into a bowl, keeping 1–2 tbsp for the eggs.</li><li>Whisk the eggs with the milk, salt and pepper. Scramble them in the skillet until set, transfer to a bowl and wipe the pan clean.</li><li>Lay out three tortillas and top each with cheese, scrambled egg, crumbled bacon and more cheese. Cover with the remaining tortillas.</li><li>Fry the quesadillas in 2 tbsp of the reserved fat over medium-high heat on both sides until crisp and the cheese melts. Cut into wedges.</li></ol><p><em>Serve with sour cream, salsa or hot sauce.</em></p>', CURRENT_TIMESTAMP),
  ('9a950c58-b97f-5d9a-a7a6-9b7883bccdaf', 'f743dda6-3a49-5b41-a607-6e4a175a5eb6', 'ru', 'Селёдка под шубой', 'Классический слоёный салат из сельди, картофеля, моркови, свёклы и яиц под майонезом. Подаётся холодным, лучше дать настояться.', '<ol><li>Отварите картофель и морковь в кожуре или очищенными около 20 минут до мягкости, остудите. Свёклу варите около 45 минут, остудите.</li><li>Сварите яйца вкрутую (около 10 минут), остудите и очистите.</li><li>Нарежьте филе селёдки мелкими кубиками, лук мелко порубите. Острый лук залейте кипятком на 2 минуты и откиньте на сито.</li><li>Выложите на дно формы слой тёртого картофеля (1 картофелина), сверху разложите селёдку и посыпьте луком. Тонко смажьте майонезом.</li><li>Натрите оставшийся картофель, посолите и поперчите. Сверху выложите слой тёртой моркови и смажьте майонезом.</li><li>Натрите свёклу ровным слоем и покройте остатком майонеза. Сверху натрите яйца.</li><li>Уберите салат в холодильник минимум на пару часов. Перед подачей украсьте укропом.</li></ol><p><em>Перед подачей посыпьте укропом и дайте салату настояться в холодильнике.</em></p>', CURRENT_TIMESTAMP),
  ('9b4f21e0-c2ee-5c3d-a182-afc0898a6bce', 'f743dda6-3a49-5b41-a607-6e4a175a5eb6', 'en', 'Herring under a fur coat (shuba)', 'A classic Russian layered salad of herring, potatoes, carrots, beets and eggs dressed with mayonnaise, served cold.', '<ol><li>Boil the potatoes and carrots for about 20 minutes until soft and let them cool. Boil the beets about 45 minutes and cool.</li><li>Hard-boil the eggs (about 10 minutes), cool and peel them.</li><li>Dice the herring fillets and finely chop the onion. If the onion is sharp, scald it in boiling water for 2 minutes and drain.</li><li>Grate 1 potato into the base of a springform pan, top with the herring and onion, and spread a thin layer of mayonnaise.</li><li>Grate the remaining potatoes on top, season with salt and pepper, then add grated carrots and another layer of mayonnaise.</li><li>Add a layer of grated beets, cover with the remaining mayonnaise and grate the eggs over the top.</li><li>Refrigerate for at least a couple of hours; garnish with dill before serving.</li></ol><p><em>Garnish with dill and let it rest in the fridge before serving.</em></p>', CURRENT_TIMESTAMP),
  ('6355839d-a8ba-51eb-a4cf-baa30e2c2698', 'ec77dc97-edf2-5f54-af2e-3fbb475429bc', 'ru', 'Салат «Мимоза» с тунцом', 'Слоёный салат из картофеля, консервированного тунца, моркови и яиц с майонезом. Верхний слой из желтков напоминает цветы мимозы.', '<ol><li>Отварите картофель и морковь около 20 минут до мягкости, остудите, натрите по отдельности на тёрке.</li><li>Сварите яйца вкрутую: доведите до кипения, накройте крышкой, снимите с огня на 11 минут и охладите в холодной воде.</li><li>Очистите яйца, белки натрите, желтки раскрошите вилкой. Лук мелко нарежьте.</li><li>Слейте жидкость с тунца и разомните его вилкой с четвертью стакана майонеза.</li><li>Соберите салат в разъёмной форме слоями: картофель, тонкий слой майонеза, соль и перец; тунец с луком и майонезом; морковь и майонез; тёртый сыр; белки и майонез.</li><li>Посыпьте салат желтками, украсьте укропом и уберите в холодильник минимум на 2 часа.</li></ol><p><em>Дайте салату настояться в холодильнике не меньше двух часов, украсьте укропом.</em></p>', CURRENT_TIMESTAMP),
  ('73fda2fa-ee87-5241-8584-e5a31a7eceb2', 'ec77dc97-edf2-5f54-af2e-3fbb475429bc', 'en', 'Mimosa salad with tuna', 'A layered salad of potatoes, canned tuna, carrots and eggs with mayonnaise, topped with crumbled yolks that look like mimosa flowers.', '<ol><li>Boil the potatoes and carrots for about 20 minutes until soft, cool, then grate each separately.</li><li>Hard-boil the eggs: bring to a boil, cover, remove from heat for 11 minutes, then cool in cold water.</li><li>Peel the eggs, grate the whites and crumble the yolks with a fork. Finely dice the onion.</li><li>Drain the tuna and mash it with a fork and about ¼ cup of the mayonnaise.</li><li>Layer in a springform pan: potatoes with a thin coat of mayonnaise, salt and pepper; tuna with onion and mayonnaise; carrots and mayonnaise; cheese; egg whites and mayonnaise.</li><li>Finish with the crumbled yolks, garnish with dill and refrigerate at least 2 hours.</li></ol><p><em>Chill for at least 2 hours and garnish with dill.</em></p>', CURRENT_TIMESTAMP),
  ('16eaa8ea-395f-57f7-ab80-e823af435ea0', '4c920081-935f-5d61-a354-de946646664a', 'ru', 'Суп с галушками и говядиной', 'Сытный суп на говяжьем бульоне с картофелем и домашними галушками из яичного теста.', '<ol><li>Смешайте муку, яйца, соль и воду, замесите гладкое плотное тесто и дайте ему отдохнуть под миской.</li><li>Обжарьте тонкие полоски говядины в масле на сильном огне, пока не выпарится жидкость, посолите и жарьте до румяности.</li><li>Добавьте лук и жарьте до золотистого цвета. Влейте воду, положите лавровый лист и перец, доведите до кипения и варите 30 минут. Через 15 минут добавьте картофель.</li><li>Раскатайте тесто в пласт толщиной с основу для пиццы, нарежьте на полосы. Отщипывайте кусочки и по одному бросайте в кипящий суп (или нарежьте квадратами).</li><li>Когда галушки всплывут, суп готов. Добавьте рубленые петрушку и укроп, проверьте соль.</li></ol><p><em>Посыпьте свежей зеленью и подайте со сметаной.</em></p>', CURRENT_TIMESTAMP),
  ('31f1a1dd-003d-52f2-bdf1-af907674c854', '4c920081-935f-5d61-a354-de946646664a', 'en', 'Galushki soup (beef and dumpling soup)', 'A hearty beef and potato soup with pinched homemade egg-dough dumplings.', '<ol><li>Mix the flour, eggs, salt and water, knead about 5 minutes into a smooth, semi-firm dough and let it rest covered.</li><li>Fry the thin beef strips in oil over high heat until the released liquid evaporates, salt, and brown.</li><li>Add the onions and cook until golden. Pour in the water, add the bay leaf and pepper, bring to a boil and simmer 30 minutes, adding the potatoes after 15 minutes.</li><li>Roll the dough out to pizza-base thickness and cut into strips. Pinch off pieces and drop them one by one into the simmering soup (or cut squares).</li><li>When the dumplings float, the soup is done. Stir in chopped parsley and dill and adjust the salt.</li></ol><p><em>Finish with fresh herbs and a spoonful of sour cream.</em></p>', CURRENT_TIMESTAMP),
  ('6250ab60-30ba-52d8-82f8-a960c148fea8', '984448ca-ca2c-59ac-bc03-e12e3aaf725a', 'ru', 'Холодник на кефире со свёклой', 'Холодный суп из варёной свёклы, свежего огурца, яиц и зелени на кефире и свекольном отваре. Освежающий и лёгкий в летнюю жару.', '<ol><li>Очистите свёклу и варите до мягкости около 40 минут. Отлейте 4 стакана отвара, свёклу остудите и натрите.</li><li>Сварите яйца вкрутую: доведите до кипения, накройте крышкой, снимите с огня на 11 минут, охладите в ледяной воде.</li><li>Огурец нарежьте тонкой соломкой, зелёный лук мелко порежьте, 6 яиц нарежьте кубиками, остальные 4 разрежьте пополам.</li><li>Смешайте кефир, лимонный сок и охлаждённый свекольный отвар, посолите.</li><li>Добавьте тёртую свёклу, огурец, нарезанные яйца и зелёный лук. Охладите минимум 2 часа.</li><li>Разлейте по тарелкам, добавьте половинки яиц, сметану и укроп.</li></ol><p><em>Подавайте охлаждённым с половинкой яйца, сметаной и укропом.</em></p>', CURRENT_TIMESTAMP),
  ('c8fc4dba-094c-5fba-813e-b0e14e6269c6', '984448ca-ca2c-59ac-bc03-e12e3aaf725a', 'en', 'Holodnik (cold beet and kefir soup)', 'A chilled soup of boiled beets, fresh cucumber, eggs and herbs in a kefir and beet-broth base.', '<ol><li>Peel the beets and boil about 40 minutes until tender. Reserve 4 cups of the cooking liquid, cool and grate the beets.</li><li>Hard-boil the eggs: bring to a boil, cover and remove from heat for 11 minutes, then cool in ice water.</li><li>Cut the cucumber into matchsticks, slice the green onions, dice 6 eggs and halve the other 4.</li><li>Combine the kefir, lemon juice and cooled beet broth and season with salt.</li><li>Stir in the grated beets, cucumber, diced eggs and green onions. Chill for at least 2 hours.</li><li>Ladle into bowls and top with egg halves, sour cream and dill.</li></ol><p><em>Serve cold with half an egg, sour cream and dill.</em></p>', CURRENT_TIMESTAMP),
  ('89e2140d-f9ed-5669-8262-f3e9cdbc3dd3', '922325b3-8a86-5b32-9843-41f8366df3c2', 'ru', 'Грибной крем-суп с пивом', 'Пюрированный суп из шампиньонов, картофеля и лука с добавлением пива и тимьяна. Насыщенный грибной вкус с лёгкой хмельной ноткой.', '<ol><li>В кастрюле разогрейте масло, обжарьте лук и чеснок до прозрачности.</li><li>Добавьте нарезанные грибы и жарьте 10–12 минут, пока не выпарится влага и грибы не подрумянятся.</li><li>Влейте пиво и проварите 2–3 минуты.</li><li>Добавьте бульон, картофель, лавровый лист и тимьян, доведите до кипения и варите на слабом огне 15 минут до мягкости картофеля. Посолите и поперчите.</li><li>Выньте лавровый лист, слегка остудите суп и пюрируйте блендером до гладкости.</li><li>При необходимости аккуратно разогрейте суп, проверьте приправы и разлейте по тарелкам.</li></ol><p><em>Украсьте веточкой тимьяна, подайте с гренками.</em></p>', CURRENT_TIMESTAMP),
  ('be074dce-f1bd-52d1-b3a9-2059388befdc', '922325b3-8a86-5b32-9843-41f8366df3c2', 'en', 'Mushroom beer soup', 'A pureed soup of mushrooms, potatoes and onion with beer and thyme: earthy with a slight malty note.', '<ol><li>Heat oil in a pot and sauté the onion and garlic until translucent.</li><li>Add the sliced mushrooms and cook 10–12 minutes until their liquid evaporates and they brown.</li><li>Pour in the beer and simmer 2–3 minutes.</li><li>Add the broth, potatoes, bay leaf and thyme, bring to a boil and simmer 15 minutes until the potatoes are soft. Season with salt and pepper.</li><li>Remove the bay leaf, cool slightly and blend until smooth.</li><li>Reheat gently if needed, adjust the seasoning and serve.</li></ol><p><em>Garnish with a sprig of thyme and serve with croutons.</em></p>', CURRENT_TIMESTAMP),
  ('227cf98b-e487-5b17-babd-c75ad62e8f8f', '72b379b3-a21a-5b2d-96a2-e55a9b9dc69f', 'ru', 'Мясо по-французски с телятиной и картофелем', 'Запеканка из картофеля, тонких ломтиков телятины, лука и грибов под майонезом и золотистой сырной корочкой.', '<ol><li>Разогрейте духовку до 200 °C, слегка смажьте маслом прямоугольную форму.</li><li>Нарежьте картофель тонкими ломтиками (до 6 мм), выложите ровным слоем в форму, посолите и поперчите.</li><li>Лук нарежьте тонкими полукольцами. Половину лука выложите на картофель и щедро смажьте майонезом.</li><li>Выложите тонко нарезанную телятину, посолите и поперчите. Сверху разложите грибы и оставшийся лук, равномерно покройте майонезом.</li><li>Запекайте около 45 минут, посыпьте тёртым сыром и запекайте ещё 10 минут до золотистой корочки.</li></ol><p><em>Подавайте горячей со свежими овощами или солёными огурцами.</em></p>', CURRENT_TIMESTAMP),
  ('525dbc2c-ef76-504a-b58f-3a3817508f16', '72b379b3-a21a-5b2d-96a2-e55a9b9dc69f', 'en', 'Meat French-style (veal, potato and mushroom bake)', 'A Russian-style casserole of sliced potatoes, thin veal, onions and mushrooms baked under mayonnaise with a golden cheese crust.', '<ol><li>Heat the oven to 200 °C and lightly oil a rectangular baking dish.</li><li>Slice the potatoes thinly (no more than ¼ inch), layer evenly in the dish and season with salt and pepper.</li><li>Thinly slice the onions. Spread half over the potatoes and drizzle generously with mayonnaise.</li><li>Lay the thin veal slices on top, season, then add the mushrooms and remaining onion and cover evenly with mayonnaise.</li><li>Bake about 45 minutes, sprinkle with grated cheese and bake 10 more minutes until golden.</li></ol><p><em>Serve hot with fresh vegetables or pickles.</em></p>', CURRENT_TIMESTAMP),
  ('04be4c97-313d-5753-bae0-ec095ef3c632', '9799c794-4f1a-55e5-9bd2-c49981b2b302', 'ru', 'Кавардак: тушёная говядина с картофелем', 'Густое рагу из говядины с картофелем, морковью, луком и болгарским перцем со специями зира и кориандром.', '<ol><li>Обжарьте кубики говядины в масле около 10 минут, пока не выпарится вытопившаяся жидкость. Добавьте соль и перец.</li><li>Добавьте лук и тушите 7–8 минут до мягкости.</li><li>Положите морковь, чеснок и перец и обжаривайте около 5 минут.</li><li>Добавьте картофель, бульон и лавровый лист. Жидкости может не хватать, чтобы покрыть картофель: это рагу, а не суп. Доведите до кипения, накройте и тушите 20 минут до мягкости картофеля.</li><li>Добавьте кориандр и зиру, проверьте соль. Подайте с зеленью и хлебом.</li></ol><p><em>Подавайте с зеленью и хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('fb13e808-3de7-55be-b40f-d8b1f2338e77', '9799c794-4f1a-55e5-9bd2-c49981b2b302', 'en', 'Kavardak (beef and potato stew)', 'A thick winter stew of beef, potatoes, carrots, onions and sweet pepper seasoned with cumin and coriander.', '<ol><li>Brown the beef cubes in oil for about 10 minutes until the released liquid has evaporated. Season with salt and pepper.</li><li>Add the onions and sauté 7–8 minutes until soft.</li><li>Add the carrots, garlic and bell pepper and cook about 5 minutes.</li><li>Add the potatoes, stock and bay leaf. The liquid needn''t cover the potatoes: it''s a stew, not a soup. Bring to a boil, cover and simmer 20 minutes until the potatoes are soft.</li><li>Stir in the coriander and cumin, adjust the seasoning, garnish with parsley and serve with bread.</li></ol><p><em>Garnish with parsley and serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('7de89d54-5fd7-52fa-8c19-75472086edef', '7b44ba27-2902-5886-9ccd-4462ab64a946', 'ru', 'Мексиканский рис с томатной пастой', 'Рассыпчатый рис, обжаренный до золотистого цвета и сваренный в бульоне с томатной пастой, зирой, чесноком и луком. Простой гарнир к мясу, курице и бобам.', '<ol><li>Разогрейте масло в глубокой сковороде на средне-сильном огне, добавьте рис и постоянно помешивайте, пока он не станет золотистым: чем сильнее поджарите, тем вкуснее.</li><li>Влейте бульон (он забурлит), сразу добавьте томатную пасту, луковый и чесночный порошок, зиру, перец чили, чёрный перец и соль.</li><li>Доведите до кипения, размешивая пасту, накройте плотной крышкой, убавьте огонь до минимума и варите 20 минут.</li><li>Если рис готов, но влажный, оставьте крышку приоткрытой. Если пахнет подгоревшим, снимите с огня. Если рис ещё твёрдый, добавьте немного воды и доварите. Взрыхлите вилкой.</li></ol><p><em>Подавайте к тако, буррито, курице или фасоли.</em></p>', CURRENT_TIMESTAMP),
  ('9fbcafc4-c1d7-5074-b682-d7c13d3bfe3b', '7b44ba27-2902-5886-9ccd-4462ab64a946', 'en', 'Mexican tomato rice', 'Long-grain rice toasted until golden, then simmered in stock with tomato paste, cumin, garlic and onion. An easy side for meat, chicken and beans.', '<ol><li>Heat the oil in a deep skillet over medium-high heat, add the rice and stir constantly until golden brown. The more toasted the rice, the better the flavour.</li><li>Pour in the stock (it will bubble up), then immediately add the tomato paste, onion and garlic powders, cumin, chilli powder, black pepper and salt.</li><li>Bring to a boil, stirring to dissolve the paste, cover tightly, reduce the heat to low and cook for 20 minutes.</li><li>If the rice is cooked but wet, leave the lid ajar. If it smells scorched, take it off the heat; if it is still firm, add a little water and keep cooking. Fluff with a fork.</li></ol><p><em>Serve with tacos, burritos, chicken or beans.</em></p>', CURRENT_TIMESTAMP),
  ('4cd0938a-319e-5d79-a947-d0e40963acdd', 'efd65a2d-2efe-510b-88f2-00a8f37889ca', 'ru', 'Скумбрия, обжаренная на сковороде', 'Филе скумбрии, посоленное и быстро обжаренное кожей вниз до хрустящей корочки. Минимум ингредиентов и 6 минут у плиты.', '<ol><li>Удалите с внутренней стороны брюшка тёмную плёнку (она горчит) и промойте филе.</li><li>Тщательно обсушите филе, посолите с обеих сторон и оставьте на 20 минут при комнатной температуре.</li><li>Разогрейте сковороду на средне-сильном огне до тех пор, пока капли воды не начнут подпрыгивать. Вытрите её насухо, влейте масло и выложите филе кожей вниз. Жарьте по 3 минуты с каждой стороны.</li></ol><p><em>Подавайте с лимоном, отварным картофелем или рисом и свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('7ab9e7f3-1866-57ac-bc3a-f7b577c3e721', 'efd65a2d-2efe-510b-88f2-00a8f37889ca', 'en', 'Pan-fried mackerel fillets', 'Mackerel fillets salted and quickly pan-fried skin side down until crisp. Just three ingredients and six minutes on the stove.', '<ol><li>Remove the black membrane from the belly side of the fillets, as it tastes bitter and fishy, and rinse.</li><li>Pat the fillets very dry, salt both sides and leave for 20 minutes at room temperature.</li><li>Heat a pan over medium-high heat until water drops dance on the surface, then wipe it dry. Add the oil and place the fillets skin side down. Fry about 3 minutes per side.</li></ol><p><em>Serve with lemon, boiled potatoes or rice and fresh vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('11cf977a-3545-553b-9ea3-a2c81afc223b', 'd71adc4e-69f4-5570-a984-66145aa2cdf6', 'ru', 'Курица в соусе с бурбоном и соевым соусом', 'Кусочки курицы, обжаренные на сильном огне и глазированные густым сладко-солёным соусом с имбирём, чесноком и каплей бурбона. Готовится за 25 минут.', '<ol><li>Смешайте курицу с водой и 1 ч. л. соевого соуса и вмешивайте руками, пока жидкость не впитается. Добавьте 2 ч. л. крахмала и перемешайте.</li><li>Смешайте для соуса соевый и тёмный соевый соусы, уксус, коричневый сахар, тёплый бульон, кунжутное масло и белый перец.</li><li>Разогрейте масло в воке или большой сковороде на сильном огне до лёгкого дымка. Выложите курицу ровным слоем и обжарьте по минуте с каждой стороны, затем переложите на тарелку.</li><li>На среднем огне обжарьте имбирь, чеснок и лук 20 секунд, влейте бурбон и через 30 секунд добавьте соус. Верните курицу и доведите до кипения.</li><li>Постепенно влейте крахмал, разведённый водой, и варите, помешивая, пока соус не обволакивает ложку. Уберите имбирь, добавьте лук и подавайте.</li></ol><p><em>Подавайте с отварным белым рисом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('e6b45f05-6d42-5252-b825-1818d72ef275', 'd71adc4e-69f4-5570-a984-66145aa2cdf6', 'en', 'Bourbon chicken', 'Chicken chunks seared over high heat and glazed in a sticky sweet-savoury sauce with ginger, garlic and a splash of bourbon. Ready in 25 minutes.', '<ol><li>Work the chicken with the water and 1 tsp soy sauce until the liquid is absorbed, then mix in 2 tsp cornstarch.</li><li>For the sauce, mix the soy sauce, dark soy sauce, vinegar, brown sugar, warm stock, sesame oil and white pepper.</li><li>Heat the oil in a wok or large pan over high heat until just smoking. Spread the chicken in one layer and sear 1 minute per side, then move to a plate.</li><li>Over medium heat stir-fry the ginger, garlic and onion for 20 seconds, add the bourbon and after 30 seconds pour in the sauce. Return the chicken and bring to a simmer.</li><li>Gradually stir in the cornstarch slurry and cook until the sauce coats a spoon. Remove the ginger, stir in the scallion and serve.</li></ol><p><em>Serve with steamed white rice and scallions.</em></p>', CURRENT_TIMESTAMP),
  ('a286ba49-fcdd-5843-8553-78cdd0d0a668', '23bf4a25-c7fe-5eed-a463-52f4c8744cb1', 'ru', 'Куриные бёдра с картофелем, лимоном и чесноком', 'Бёдрышки с кожей обжариваются в жаровне, затем запекаются с картофелем, дольками лимона и целым чесноком. Всё готовится в одной посуде.', '<ol><li>Разогрейте духовку до 220 °C. Посолите и поперчите бёдра.</li><li>Разогрейте оливковое масло в жаропрочной форме на двух конфорках и обжарьте бёдра кожей вниз 5–7 минут. Переверните.</li><li>Добавьте картофель, дольки лимона и очищенный чеснок, перемешайте с маслом.</li><li>Отправьте форму в духовку на 30 минут, пока курица не прожарится, а картофель не станет мягким. Добавьте рубленую зелень и подавайте.</li></ol><p><em>Посыпьте рубленой зеленью и подайте с овощным салатом.</em></p>', CURRENT_TIMESTAMP),
  ('6b0840fb-7b09-5fcf-b9ca-0923b7d61841', '23bf4a25-c7fe-5eed-a463-52f4c8744cb1', 'en', 'Roasted lemon chicken thighs with potatoes and garlic', 'Bone-in thighs are seared in a roasting pan, then roasted with potatoes, lemon slices and whole garlic cloves in one pan.', '<ol><li>Heat the oven to 220 °C (425 °F) and season the thighs with salt and pepper.</li><li>Heat the olive oil in a roasting pan over two burners and sear the chicken skin-side down for 5–7 minutes, then flip.</li><li>Add the potatoes, lemon slices and peeled garlic and toss everything in the oil.</li><li>Roast for 30 minutes until the chicken is cooked through and the potatoes tender. Stir in the herbs and serve.</li></ol><p><em>Sprinkle with chopped herbs and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('4e626d48-73e6-5bb2-b278-88a5790c1104', '61a0ab19-9c44-5912-9819-9da6802fed36', 'ru', 'Грибной суп по-китайски из шампиньонов', 'Лёгкий прозрачный постный суп из обжаренных до румяности шампиньонов, с соевым соусом, кинзой и зелёным луком. Готовится за 20 минут.', '<ol><li>Вымойте шампиньоны и тщательно обсушите. Отделите ножки (их тоже добавьте в суп).</li><li>В хорошо разогретой кастрюле на среднем огне разогрейте масло и выложите шляпки вверх «чашечками» одним слоем, добавьте ножки.</li><li>Убавьте огонь и жарьте без помешивания, пока шляпки не подрумянятся и «чашечки» не наполнятся соком.</li><li>Влейте воду и соевый соус, доведите до кипения, накройте и варите на слабом огне 5 минут.</li><li>Посолите по вкусу, при желании влейте крахмал, разведённый водой, и проварите 30 секунд до загустения. В конце добавьте кинзу и зелёный лук.</li></ol><p><em>Подавайте горячим, щедро посыпав кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('8f40308e-59fa-5110-a1cf-8e385f8901a9', '61a0ab19-9c44-5912-9819-9da6802fed36', 'en', 'Chinese-style button mushroom soup', 'A light, vegan clear soup of pan-browned button mushrooms with soy sauce, cilantro and scallion, ready in 20 minutes.', '<ol><li>Wash the mushrooms and dry them thoroughly. Detach the stems (add them to the soup too).</li><li>Heat the oil in a very hot pot over medium-high heat and arrange the caps cup-side up in a single layer, adding the stems.</li><li>Reduce the heat and cook without stirring until the caps are browned and each cup fills with juice.</li><li>Pour in the water and soy sauce, bring to a boil, cover and simmer 5 minutes.</li><li>Salt to taste, optionally stir in the cornstarch slurry and simmer 30 seconds to thicken. Finish with cilantro and scallion.</li></ol><p><em>Serve hot with plenty of cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('3146f707-db49-5b37-b7cf-35290000ee0c', 'a34e86e5-06cb-5632-b576-c7a98a239e25', 'ru', 'Яичница-скрэмбл по-китайски с зелёным перцем', 'Быстрое блюдо из мягких взбитых яиц с обжаренным до пятен сладким перцем, чесноком и соевым соусом.', '<ol><li>Взбейте яйца с белым перцем, кунжутным маслом, солью (¼ ч. л.) и, если используете, 1 ч. л. вина.</li><li>В сухом воке на среднем огне обжарьте перец 3–5 минут, пока не появятся тёмные пятна и он не станет мягким. Переложите на тарелку.</li><li>Увеличьте огонь, влейте 2 ст. л. масла и сразу вылейте яйца. Готовьте, пока они не схватятся, но останутся мягкими, и переложите на отдельную тарелку.</li><li>Убавьте огонь, добавьте оставшееся масло, на 20 секунд обжарьте чеснок, верните перец, влейте соевый соус, добавьте остаток соли и сахар.</li><li>Верните яйца, добавьте зелёный лук (и вино, если используете), на сильном огне быстро перемешайте и сразу подавайте.</li></ol><p><em>Подавайте с рисом как основное блюдо или как гарнир.</em></p>', CURRENT_TIMESTAMP),
  ('bde85757-7a2c-57b6-a3bd-a63375b5e023', 'a34e86e5-06cb-5632-b576-c7a98a239e25', 'en', 'Chinese egg stir-fry with green peppers', 'Soft wok-scrambled eggs with blistered green peppers, garlic and soy sauce.', '<ol><li>Beat the eggs with the white pepper, sesame oil, ¼ tsp salt and, if using, 1 tsp of the wine.</li><li>Dry-fry the peppers in a clean wok over medium heat for 3–5 minutes until blistered and soft. Set aside.</li><li>Turn the heat to high, add 2 tbsp oil and pour in the eggs at once. Cook until set but still soft; transfer to a separate dish.</li><li>Lower the heat, add the remaining oil, cook the garlic 20 seconds, return the peppers and add the soy sauce, remaining salt and sugar.</li><li>Return the eggs, add the scallion (and the wine, if using), toss quickly over high heat and serve at once.</li></ol><p><em>Serve over rice as a light main or as a side dish.</em></p>', CURRENT_TIMESTAMP),
  ('dff64cad-8a90-5983-b36a-7608bc43e6cd', '62e81473-59d2-5c7c-b2a2-2faf88e66890', 'ru', 'Капуста по-китайски, обжаренная с грудинкой', 'Быстрая жареная капуста с хрустящей свиной грудинкой, чесноком и сушёным чили. Пикантная, чуть кисловатая, очень бюджетная.', '<ol><li>Разогрейте в воке масло на сильном огне и обжарьте тонко нарезанную грудинку до карамельной корочки.</li><li>Убавьте огонь до среднего, добавьте чеснок и сушёный чили, обжаривайте минуту, не допуская подгорания чеснока.</li><li>Добавьте руками порванную капусту, вино, соевый соус, сахар и воду. Включите сильный огонь, накройте крышкой и готовьте 1–2 минуты.</li><li>Снимите крышку, добавьте чёрный уксус, зелёный лук и соль по вкусу. Капуста должна завянуть, но остаться чуть хрустящей. Подавайте горячей.</li></ol><p><em>Подавайте горячей с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('7680207a-3fdc-57d6-96bb-b0f77f7da231', '62e81473-59d2-5c7c-b2a2-2faf88e66890', 'en', 'Chinese shredded cabbage stir-fry with pork', 'Quick wok-fried cabbage with caramelized pork belly, garlic and dried chilies, savory and slightly tangy.', '<ol><li>Heat the oil in a wok over high heat and sear the thinly sliced pork until caramelized.</li><li>Reduce the heat to medium, add the garlic and dried chilies and stir-fry for a minute without letting the garlic burn.</li><li>Add the hand-torn cabbage, wine, soy sauce, sugar and water. Turn the heat to high, cover and cook 1–2 minutes.</li><li>Uncover, stir in the black vinegar, scallions and salt to taste. The cabbage should be wilted but still slightly crunchy. Serve hot.</li></ol><p><em>Serve hot with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('17611fbc-33c4-5097-b136-370f8ce31dae', '515a763d-574c-5f79-90ea-8305fdb8cb7f', 'ru', 'Баклажаны со стручковой фасолью по-китайски', 'Хрустящая стручковая фасоль и мягкий баклажан, обжаренные с чесноком, имбирём и чили в соусе из соевого и устричного соусов.', '<ol><li>В сковороде на среднем огне разогрейте масло и обжаривайте стручковую фасоль, медленно перекатывая, пока она не сморщится и не станет слегка хрустящей. Выньте шумовкой.</li><li>В оставшемся масле на чуть более сильном огне обжарьте полоски баклажана до румяных краёв и мягкости. Выньте к фасоли.</li><li>Оставьте в воке 1 ст. л. масла, на среднем огне минуту обжарьте имбирь, чеснок и чили.</li><li>Верните фасоль и баклажан, добавьте соевый и устричный соусы, соль и белый перец. Обжаривайте 1–2 минуты и подавайте.</li></ol><p><em>Подавайте с отварным рисом.</em></p>', CURRENT_TIMESTAMP),
  ('4e30f9de-3858-582b-98a1-770b599003df', '515a763d-574c-5f79-90ea-8305fdb8cb7f', 'en', 'Chinese eggplant and green bean stir-fry', 'Shallow-fried green beans and tender eggplant tossed with garlic, ginger, chili, soy and oyster sauce.', '<ol><li>Heat the oil in a flat-bottomed pan over medium heat and shallow-fry the green beans, rolling them, until wrinkled and slightly crisp. Remove with a slotted spoon.</li><li>In the same oil over slightly higher heat fry the eggplant strips until the edges brown and they are tender. Remove and combine with the beans.</li><li>Leave about 1 tbsp of the oil in a wok and cook the ginger, garlic and chili over medium heat for a minute.</li><li>Return the beans and eggplant, add the soy sauce, oyster sauce, salt and white pepper and stir-fry 1–2 minutes.</li></ol><p><em>Serve with steamed rice.</em></p>', CURRENT_TIMESTAMP),
  ('808e1875-9244-5ab3-96b6-fc79a512c85e', 'a90cc0c8-7a22-5fb3-9b0f-28d07000a408', 'ru', 'Дайкон с морковью, обжаренный по-китайски', 'Нежный тушёный дайкон с морковью, имбирём и чесноком в устричном соусе. Быстрый и лёгкий овощной гарнир.', '<ol><li>В воке на среднем огне разогрейте масло, обжарьте имбирь и чеснок 20 секунд.</li><li>Добавьте морковь и жарьте 30 секунд, затем дайкон, включите сильный огонь и обжаривайте ещё 30 секунд.</li><li>Добавьте вино (по желанию), устричный соус, белый перец, кунжутное масло, соль, воду и белые части лука. Накройте и тушите на среднем огне 5–8 минут до мягкости.</li><li>Снимите крышку, добавьте остальной зелёный лук и перемешайте. Блюдо готово, когда дайкон прозрачный и мягкий.</li></ol><p><em>Подавайте горячим как гарнир к рису или мясу.</em></p>', CURRENT_TIMESTAMP),
  ('c50cefa4-33ee-5685-b6f3-f7d2f3692563', 'a90cc0c8-7a22-5fb3-9b0f-28d07000a408', 'en', 'Carrot and daikon stir-fry', 'Tender daikon and carrot stir-fried with ginger and garlic in oyster sauce, a quick light vegetable side.', '<ol><li>Heat the oil in a wok over medium heat and cook the ginger and garlic for 20 seconds.</li><li>Add the carrot and stir-fry 30 seconds, then the daikon, turn up the heat and stir-fry another 30 seconds.</li><li>Add the wine (optional), oyster sauce, white pepper, sesame oil, salt, water and the white parts of the scallions. Cover and simmer over medium heat 5–8 minutes until tender.</li><li>Uncover, stir in the rest of the scallions and mix. It''s done when the daikon is translucent and tender.</li></ol><p><em>Serve hot alongside rice or meat.</em></p>', CURRENT_TIMESTAMP),
  ('7932a178-d4c0-53cc-a199-906a8a3800e2', 'aee713c4-e47b-5e7c-b62f-21ecb50898b5', 'ru', 'Свиные отбивные в азиатском маринаде', 'Свиные стейки мариную 20 минут в соевом соусе с пятью специями и кунжутным маслом и быстро обжариваю на сковороде.', '<ol><li>Смешайте в неглубокой посуде соевый соус, белый перец, кунжутное масло, крахмал, пять специй и вино (по желанию).</li><li>Положите в маринад свиные отбивные и оставьте на 20 минут – 1 час.</li><li>Вынуть мясо из маринада заранее, чтобы оно согрелось до комнатной температуры. Разогрейте масло на большой сковороде и обжаривайте отбивные по 5 минут с каждой стороны (толщина 2,5 см) до готовности. Остатки маринада выбросьте.</li><li>Дайте мясу отдохнуть 5 минут и подавайте.</li></ol><p><em>Подавайте с рисом и овощами на пару.</em></p>', CURRENT_TIMESTAMP),
  ('5c72bb69-1acb-574c-b21e-4cb400154dfe', 'aee713c4-e47b-5e7c-b62f-21ecb50898b5', 'en', 'Asian-marinated seared pork chops', 'Pork chops marinated for 20 minutes in soy sauce, five spice and sesame oil, then seared in a skillet.', '<ol><li>Combine the soy sauce, white pepper, sesame oil, cornstarch, five spice and wine (if using) in a shallow dish.</li><li>Marinate the pork chops in the mixture for 20 minutes to an hour.</li><li>Let the pork come to room temperature. Heat the oil in a large skillet and sear the chops about 5 minutes per side for 1-inch thick chops until cooked through. Discard the leftover marinade.</li><li>Rest the chops 5 minutes before serving.</li></ol><p><em>Serve with rice and steamed vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('26242b7d-531b-5a59-acec-b4eb39a07e73', '2499ced8-b013-5fe4-a238-6fc88c66c537', 'ru', 'Курица по-милански, запечённая, с руколой и помидорами', 'Тонкие куриные отбивные в хрустящей панировке с сыром запекаются в духовке и подаются со свежим салатом из руколы и помидоров с бальзамическим уксусом.', '<ol><li>Взбейте оливковое масло с бальзамическим уксусом, добавьте нарезанные помидоры, красный лук и базилик, посолите, поперчите и оставьте минимум на 10 минут.</li><li>Разогрейте духовку до 230 °C и поставьте в неё противень. Смешайте сухари с тёртым сыром, а в другой миске соедините масло, лимонный сок и перец.</li><li>Слегка отбейте куриное филе, чтобы получилось 6 эскалопов, обсушите, посолите и поперчите. Обмакните в масляно-лимонную смесь, затем в сухари, плотно прижимая.</li><li>Достаньте горячий противень, смажьте маслом, выложите эскалопы и сбрызните сверху маслом. Запекайте около 15 минут, перевернув на середине, до золотистой корочки.</li><li>Выложите на курицу руколу и томатный салат и сразу подавайте.</li></ol><p><em>Выкладывайте салат на горячую курицу прямо перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('810fea6d-576f-581d-8535-b9194f67d0cc', '2499ced8-b013-5fe4-a238-6fc88c66c537', 'en', 'Baked chicken Milanese with arugula and tomato salad', 'Thin breaded chicken cutlets with cheese baked until crisp and topped with a fresh arugula and tomato salad dressed with balsamic vinegar.', '<ol><li>Whisk the olive oil and balsamic vinegar, toss in the diced tomatoes, red onion and basil, season, and leave for at least 10 minutes.</li><li>Preheat the oven to 230°C and put a baking pan in to heat. Mix the breadcrumbs with the grated cheese, and in another bowl combine the oil, lemon juice and pepper.</li><li>Lightly pound the chicken into 6 cutlets, pat dry and season. Dip each in the lemon-oil mixture, then in the crumbs, pressing firmly.</li><li>Take out the hot pan, oil it, lay the cutlets on it and spray the tops with oil. Bake about 15 minutes, turning once halfway, until golden.</li><li>Top the chicken with the arugula and tomato salad and serve at once.</li></ol><p><em>Pile the salad on the hot chicken just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('a88ba87d-1504-5855-9a10-4faa6c77dde1', 'edc61250-c899-5a42-98ca-4f72c6a838e8', 'ru', 'Рулетики из кабачков с курицей по-энчилада', 'Полоски кабачка, свёрнутые с пряной курицей и луком, запечены под соусом энчилада и сыром. Вместо лепёшек кабачок, поэтому блюдо низкоуглеводное.', '<ol><li>Разогрейте духовку до 200 °C. Распределите 60 мл соуса энчилада по дну формы 23×33 см.</li><li>Нарежьте кабачки вдоль пластинами толщиной 6 мм, чтобы вышло 12 штук одинакового размера. Посолите и поперчите с обеих сторон.</li><li>Обжарьте кабачки на гриль-сковороде на сильном огне по 2 минуты с каждой стороны, чтобы они стали гибкими, но не размякли.</li><li>Разогрейте масло в сковороде, 2 минуты потушите лук с чесноком, добавьте курицу, кинзу, зиру, орегано, перец чили и 60 мл соуса и прогревайте 4–5 минут.</li><li>Выложите на каждую полоску кабачка по 3 ст. л. начинки, сверните и уложите швом вниз в форму. Залейте остатком соуса, посыпьте сыром и плотно накройте фольгой.</li><li>Запекайте 20 минут, пока сыр не расплавится. Подайте со сметаной и кинзой.</li></ol><p><em>Полейте сметаной и посыпьте кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('8f077d1f-e348-5aa4-8e0d-216553207ff2', 'edc61250-c899-5a42-98ca-4f72c6a838e8', 'en', 'Zucchini chicken enchilada roll-ups', 'Thin zucchini strips rolled around spiced shredded chicken and baked under enchilada sauce and melted cheese. A low-carb take on enchiladas.', '<ol><li>Preheat the oven to 200°C. Spread about 60 ml of the enchilada sauce over the bottom of a 23×33 cm baking dish.</li><li>Slice the zucchini lengthwise into 6 mm planks to get 12 even slices. Season both sides with salt and pepper.</li><li>Cook the zucchini on a grill pan over high heat for about 2 minutes per side, until pliable with grill marks but not fully cooked.</li><li>Heat the oil in a skillet, soften the onion and garlic for 2 minutes, then add the chicken, cilantro, cumin, oregano, chilli powder and 60 ml sauce and cook 4–5 minutes.</li><li>Spoon about 3 tbsp filling on each zucchini slice, roll up and place seam side down in the dish. Top with the remaining sauce and cheese and cover tightly with foil.</li><li>Bake 20 minutes until the cheese is hot and melted. Serve with sour cream and cilantro.</li></ol><p><em>Drizzle with sour cream and scatter with cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('4d245cc8-eb18-587d-bdef-fa8fd2beb608', '0b42f456-46ac-586f-b76f-0e508484d9e6', 'ru', 'Яйца в томатном соусе со спаржей и пекорино', 'Яйца, томлёные в лёгком томатном соусе с бульоном и спаржей, с тёртым сыром. Сытное блюдо из одной сковороды за 25 минут.', '<ol><li>Разогрейте глубокую антипригарную сковороду на среднем огне, смажьте маслом и обжарьте чеснок до светло-золотистого цвета, не пережарьте.</li><li>Влейте томатный соус и бульон, перемешайте, добавьте спаржу, нарезанную пополам, и накройте крышкой.</li><li>Когда соус слегка закипит, аккуратно разбейте в него яйца, посыпьте сыром, убавьте огонь и томите под крышкой на слабом огне около 10 минут, пока белок не схватится.</li></ol><p><em>Подавайте с кусочком хлеба, чтобы собрать соус.</em></p>', CURRENT_TIMESTAMP),
  ('091cdd86-ba4c-5237-9f07-1aadd9c1530d', '0b42f456-46ac-586f-b76f-0e508484d9e6', 'en', 'Eggs in purgatory with asparagus and pecorino', 'Eggs gently poached in a light tomato and broth sauce with asparagus and grated cheese. A filling one-pan dish in 25 minutes.', '<ol><li>Heat a deep non-stick skillet over medium heat, oil it and cook the garlic until light golden without burning.</li><li>Add the tomato sauce and broth, stir, add the asparagus cut in half and cover.</li><li>When the sauce boils gently, crack in the eggs, sprinkle with the cheese, reduce the heat and simmer covered about 10 minutes, until the whites are set.</li></ol><p><em>Serve with a slice of bread to mop up the sauce.</em></p>', CURRENT_TIMESTAMP),
  ('d80e2f96-7337-57f3-8733-7ff48983d8f7', 'a4846881-de45-5d8c-b096-4a1baea064de', 'ru', 'Салат с цветной капустой вместо картофеля, с яйцами и огурцами', 'Низкоуглеводная версия картофельного салата: отварная цветная капуста, варёные яйца, солёные огурцы, сельдерей и красный лук под майонезной заправкой с укропом.', '<ol><li>Налейте в большую кастрюлю воды на 2,5 см, добавьте 1 ч. л. соли и доведите до кипения. Варите цветную капусту, нарезанную кусочками по 1 см, 8–10 минут до мягкости, слейте воду и переложите в миску.</li><li>Смешайте майонез, горчицу, укроп, щепотку соли и перец. Крупно порубите 4 варёных яйца, остальные 2 нарежьте кружками для украшения.</li><li>Добавьте к капусте рубленые яйца, огурцы, сельдерей, лук, ¼ ч. л. соли и перец. Влейте майонезную заправку и рассол, аккуратно перемешайте. Украсьте яйцами и паприкой.</li></ol><p><em>Посыпьте паприкой и охладите перед подачей.</em></p>', CURRENT_TIMESTAMP),
  ('2cc4f47a-b6ba-59c0-b396-61714b6422c3', 'a4846881-de45-5d8c-b096-4a1baea064de', 'en', 'Cauliflower ''potato'' salad with eggs and pickles', 'A low-carb take on potato salad: tender cauliflower, hard-boiled eggs, pickles, celery and red onion in a creamy dill-mustard mayonnaise dressing.', '<ol><li>Bring 2.5 cm of water with 1 tsp salt to a boil in a large pot. Cook the cauliflower, chopped into 1 cm pieces, for 8–10 minutes until tender, drain and put in a large bowl.</li><li>Mix the mayonnaise, mustard, dill, a pinch of salt and pepper. Chop 4 of the eggs and slice the other 2 for the topping.</li><li>Add the chopped eggs, pickles, celery, onion, ¼ tsp salt and pepper to the cauliflower. Stir in the mayonnaise mix and pickle juice, then garnish with sliced eggs and paprika.</li></ol><p><em>Sprinkle with paprika and chill before serving.</em></p>', CURRENT_TIMESTAMP),
  ('7fee47c8-6ee6-5b5d-a85b-1ee889a16d10', '9e43be0f-bb38-58d7-a24d-95a7741eb845', 'ru', 'Куриные рулетики с кабачком и моцареллой', 'Тонкие куриные эскалопы, свёрнутые с начинкой из тёртого кабачка, чеснока и сыров, в хрустящей панировке запекаются в духовке.', '<ol><li>Обсушите эскалопы, посолите и поперчите. Разогрейте духовку до 230 °C и слегка смажьте форму маслом.</li><li>Обжарьте чеснок в масле 1 минуту до золотистого цвета, добавьте тёртый кабачок, ¼ стакана сыра, соль и перец и тушите 3–4 минуты. Остудите и смешайте с моцареллой.</li><li>Выложите на каждый эскалоп по 3 ст. л. начинки и неплотно сверните, швом вниз.</li><li>Смешайте сухари с оставшимся тёртым сыром, а в другой миске соедините масло, лимонный сок и перец. Обмакните рулетики сначала в масляную смесь, затем в сухари и уложите швом вниз в форму.</li><li>Запекайте 25–30 минут и сразу подавайте. В аэрогриле при 200 °C готовьте двумя партиями по 12 минут, переворачивая на середине.</li></ol><p><em>Подавайте со свежим салатом, на порцию можно взять два рулетика.</em></p>', CURRENT_TIMESTAMP),
  ('a1c0967b-9c21-5207-a94a-88a0c64523db', '9e43be0f-bb38-58d7-a24d-95a7741eb845', 'en', 'Chicken rollatini with zucchini and mozzarella', 'Thin chicken cutlets rolled around a filling of shredded zucchini, garlic and cheeses, breaded and baked until golden.', '<ol><li>Pat the cutlets dry and season with salt and pepper. Preheat the oven to 230°C and lightly oil a baking dish.</li><li>Sauté the garlic in oil for 1 minute until golden, add the shredded zucchini, ¼ cup of the grated cheese, salt and pepper and cook 3–4 minutes. Cool, then mix in the mozzarella.</li><li>Put about 3 tbsp filling on each cutlet and roll up loosely, seam side down.</li><li>Mix the breadcrumbs with the remaining cheese; in another bowl combine the oil, lemon juice and pepper. Dip each roll in the lemon-oil, then in the crumbs, and place seam side down in the dish.</li><li>Bake 25–30 minutes and serve right away. In an air fryer at 200°C cook in two batches for 12 minutes, turning halfway.</li></ol><p><em>Serve with a green salad; two rolls per person is plenty.</em></p>', CURRENT_TIMESTAMP),
  ('f8132a93-8307-5c50-96d8-f2ec42cb86d3', '9f2980ff-dde6-5a52-9109-ea0bca9be8a3', 'ru', 'Яйца в кольцах болгарского перца', 'Яйца, пожаренные в кольцах сладкого перца. Лёгкая и быстрая замена тосту, подходит для низкоуглеводного и безглютенового питания.', '<ol><li>Нарежьте перец кольцами толщиной около 1,2 см. Разогрейте антипригарную сковороду на среднем огне и смажьте маслом.</li><li>Выложите кольца перца на сковороду на минуту, затем разбейте в центр каждого по яйцу, посолите и поперчите.</li><li>Готовьте 2–3 минуты, пока белок почти не схватится, а желток останется жидким. Аккуратно переверните и жарьте ещё минуту, или дольше, если любите плотный желток.</li></ol><p><em>Подавайте с зеленью и ломтиком авокадо или свежими овощами.</em></p>', CURRENT_TIMESTAMP),
  ('108ea332-c319-5b83-9508-7663a1b8b665', '9f2980ff-dde6-5a52-9109-ea0bca9be8a3', 'en', 'Eggs in bell pepper rings', 'Eggs fried inside rings of sweet bell pepper. A quick, light, low-carb and gluten-free alternative to egg-in-a-hole toast.', '<ol><li>Cut the pepper into rings about 1.2 cm thick. Heat a large nonstick skillet over medium heat and oil it.</li><li>Place the pepper rings in the pan for a minute, then crack an egg into the centre of each and season with salt and pepper.</li><li>Cook 2–3 minutes until the whites are mostly set and the yolks runny. Gently flip and cook 1 more minute, or longer for firm yolks.</li></ol><p><em>Serve with fresh herbs and avocado or raw vegetables.</em></p>', CURRENT_TIMESTAMP),
  ('e9ccfefb-0468-51d6-a591-b92c245326cf', '4c4100e3-3980-5135-80e9-23745b2133f7', 'ru', 'Курица с овощами на противне в бальзамико-травяной маринаде', 'Куриное филе в бальзамическом уксусе с чесноком и травами запекается на одном противне с перцем, кабачком, спаржей, цветной капустой и красным луком.', '<ol><li>Разогрейте духовку до 230 °C. Если нужно, застелите противень пергаментом.</li><li>Разрежьте куриное филе пополам, смешайте с 1 ст. л. бальзамического уксуса, ½ ст. л. масла, чесноком, базиликом, петрушкой и ¾ ч. л. соли. Оставьте мариноваться, пока готовите овощи.</li><li>Нарежьте овощи кусочками по 2,5 см и перемешайте с 2 ст. л. бальзамического уксуса, 1½ ст. л. масла, солью, перцем, базиликом и петрушкой.</li><li>Разложите овощи на противне, уложите между ними курицу и запекайте на нижней решётке около 20 минут, пока курица не приготовится. Сразу подавайте.</li></ol><p><em>Подавайте сразу, можно с рисом или кускусом.</em></p>', CURRENT_TIMESTAMP),
  ('37742648-2d0d-55fc-b56e-1f67e4769228', '4c4100e3-3980-5135-80e9-23745b2133f7', 'en', 'Sheet-pan balsamic herb chicken with mixed vegetables', 'Chicken breast marinated in balsamic, garlic and herbs roasts on one pan with bell pepper, zucchini, asparagus, cauliflower and red onion.', '<ol><li>Preheat the oven to 230°C. Line a large sheet pan with parchment if you like.</li><li>Halve the chicken breasts and mix with 1 tbsp balsamic, ½ tbsp oil, the garlic, basil, parsley and ¾ tsp salt. Let it marinate while you prep the vegetables.</li><li>Cut the vegetables into 2.5 cm pieces and toss with 2 tbsp balsamic, 1½ tbsp oil, salt, pepper, basil and parsley.</li><li>Spread the vegetables on the pan, nestle the chicken among them and roast on the lower rack for about 20 minutes until the chicken is cooked through. Serve immediately.</li></ol><p><em>Serve right away, optionally with rice or couscous.</em></p>', CURRENT_TIMESTAMP),
  ('2cf4b488-d14e-50d5-8e5c-4aa34720e33f', '3d956c65-220b-50ba-9a2e-37080a224344', 'ru', 'Греческие боулы с курицей, бурым рисом, оливками и фетой', 'Куриное филе в лимонно-орегановом маринаде с бурым рисом, свежими овощами, оливками и фетой. Удобно готовить заранее и брать с собой.', '<ol><li>Смешайте лимонный сок, винный уксус, 1 ст. л. масла, чеснок и орегано. Отбейте куриное филе в пакете до толщины около 1,3 см, залейте маринадом и оставьте минимум на 30 минут.</li><li>Доведите рис с бульоном до кипения, накройте и варите на слабом огне 10–12 минут, пока рис не станет мягким, а жидкость не впитается.</li><li>Разогрейте гриль-сковороду на среднем огне, смажьте маслом. Выложите курицу (маринад слейте) и жарьте по 5–6 минут с каждой стороны до готовности. Дайте отдохнуть.</li><li>Нарежьте курицу. В каждую миску положите рис, курицу, помидоры, огурец, перец и оливки, сбрызните маслом и лимонным соком, посыпьте фетой.</li></ol><p><em>Перед подачей сбрызните боул оливковым маслом и лимонным соком.</em></p>', CURRENT_TIMESTAMP),
  ('429c47e0-b778-5550-b50d-9b3e0cf538a8', '3d956c65-220b-50ba-9a2e-37080a224344', 'en', 'Greek chicken brown rice bowls with olives and feta', 'Lemon-oregano marinated chicken breast over brown rice with fresh vegetables, olives and feta. Great for meal prep.', '<ol><li>Mix the lemon juice, vinegar, 1 tbsp oil, garlic and oregano. Pound the chicken in a bag to about 1.3 cm thick, add the marinade and chill at least 30 minutes.</li><li>Bring the rice and broth to a boil, cover and simmer 10–12 minutes until the rice is tender and the broth is absorbed.</li><li>Heat a grill pan over medium heat and oil it. Cook the chicken (discard the marinade) 5–6 minutes per side until cooked through, then rest.</li><li>Slice the chicken. Divide the rice, chicken, tomatoes, cucumber, pepper and olives among bowls, drizzle with oil and lemon juice and sprinkle with feta.</li></ol><p><em>Drizzle with olive oil and lemon juice just before eating.</em></p>', CURRENT_TIMESTAMP),
  ('783d97e4-380b-5bf7-87ce-bb3e3e82632e', 'bbd56924-11bf-5bc3-8c9e-47b8c9993b57', 'ru', 'Ризотто со спаржей, пармезаном и лимоном', 'Кремовое ризотто с шалотом, белым вином, свежей спаржей и петрушкой, с пармезаном и лимонной цедрой. Вегетарианское основное блюдо.', '<ol><li>Доведите бульон до кипения в большой кастрюле, убавьте огонь и держите на слабом нагреве, при необходимости досолите.</li><li>В другой тяжёлой кастрюле на среднем огне обжарьте шалот в масле 3–4 минуты. Добавьте рис и жарьте 2–3 минуты, пока он не станет слегка прозрачным.</li><li>Влейте вино и помешивайте, пока оно не впитается. Затем добавляйте горячий бульон по половнику, постоянно помешивая и ожидая, пока жидкость впитается перед каждой порцией.</li><li>Вместе с последним половником бульона добавьте спаржу и готовьте ещё 5 минут. Рис должен быть кремовым, мягким, но слегка упругим в центре.</li><li>Снимите с огня, вмешайте лимонный сок, петрушку и пармезан. Подавайте сразу.</li></ol><p><em>Подавайте сразу, посыпав чёрным перцем, цедрой и дополнительным пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('9ffde087-07d3-505c-a49e-077e43b265e0', 'bbd56924-11bf-5bc3-8c9e-47b8c9993b57', 'en', 'Asparagus risotto with parmesan and lemon', 'Creamy risotto with shallots, white wine, fresh asparagus and parsley, finished with parmesan and lemon zest. A vegetarian main.', '<ol><li>Bring the broth to a boil in a large saucepan, reduce to a simmer and keep it hot, adjusting the salt.</li><li>In a heavy saucepan over medium heat, soften the shallots in the oil for 3–4 minutes. Add the rice and stir 2–3 minutes until slightly translucent.</li><li>Pour in the wine and stir until absorbed. Then add the hot broth a ladleful at a time, stirring almost constantly and waiting for each to be absorbed.</li><li>Add the asparagus with the last ladle of broth and cook 5 more minutes. The rice should be creamy and tender with a slight bite.</li><li>Remove from the heat and stir in the lemon juice, parsley and parmesan. Serve immediately.</li></ol><p><em>Serve immediately with black pepper, zest and extra parmesan.</em></p>', CURRENT_TIMESTAMP),
  ('bad24f15-1867-599e-b9bf-a641989d537b', 'd30b7fe2-3e0a-584c-83e6-94ec657a5c07', 'ru', 'Овощной пастуший пирог с грибами и картофельным пюре', 'Вегетарианская запеканка: тушёные шампиньоны или портобелло с морковью, луком, горошком и кукурузой в густом соусе под слоем картофельного пюре с пармезаном.', '<ol><li>Сварите картофель в подсоленной воде до мягкости, слейте воду и разомните с молоком, 15 г масла, чесноком и солью в пюре. Можно использовать готовое пюре.</li><li>Разогрейте масло в большой сковороде, добавьте грибы кубиками и ½ ч. л. соли и жарьте 10 минут, помешивая.</li><li>Добавьте лук, морковь, петрушку, тимьян, ½ ч. л. соли и перец и жарьте ещё 10 минут. Положите чеснок на 30 секунд, затем томатную пасту, вустерский соус, остаток соли и перец.</li><li>Посыпьте овощи мукой, перемешайте и готовьте 3–4 минуты, соскребая налёт со дна. Влейте бульон, добавьте горошек и кукурузу и варите до загустения соуса около 5 минут.</li><li>Включите гриль духовки. Переложите овощи в форму, разровняйте сверху пюре, посыпьте пармезаном и запекайте под грилем около 5 минут до золотистой корочки.</li></ol><p><em>Посыпьте петрушкой и подайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('5e26b51f-fd01-5b97-833e-e2cb5160a0cf', 'd30b7fe2-3e0a-584c-83e6-94ec657a5c07', 'en', 'Vegetable shepherd''s pie with mushrooms and parmesan mash', 'A vegetarian bake of mushrooms, carrots, onion, peas and corn in a savoury sauce, topped with garlicky mashed potatoes and parmesan.', '<ol><li>Boil the potatoes in salted water until soft, drain and mash with the milk, 15 g butter, garlic and salt. Leftover mash works too.</li><li>Heat the butter and oil in a large sauté pan, add the diced mushrooms and ½ tsp salt and cook 10 minutes, stirring.</li><li>Add the onion, carrots, parsley, thyme, ½ tsp salt and pepper and cook another 10 minutes. Stir in the garlic for 30 seconds, then the tomato paste, Worcestershire, remaining salt and pepper.</li><li>Sprinkle the flour over the vegetables, stir and cook 3–4 minutes, scraping up the browned bits. Add the broth, peas and corn and cook about 5 minutes until the sauce thickens.</li><li>Heat the oven broiler. Transfer the vegetables to a baking dish, spread the mash on top, sprinkle with parmesan and broil about 5 minutes until golden.</li></ol><p><em>Garnish with parsley and serve with a green salad.</em></p>', CURRENT_TIMESTAMP)
ON CONFLICT ("foodId", "language") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "content" = EXCLUDED."content", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "food_translations" ("id", "foodId", "language", "name", "description", "content", "updatedAt") VALUES
  ('df47b608-ca68-5f4f-a0cc-04a7f7b89d6d', '11172a5a-fc85-5f35-9e10-03a67c80b234', 'ru', 'Креветки с нутом в соусе харисса', 'Быстрое блюдо из одной сковороды: нут и креветки в пряном соусе харисса с чесноком, лимоном и свежей мятой или кинзой.', '<ol><li>Разогрейте масло в большой сковороде на среднем огне, обжарьте нарезанный чеснок около минуты до почти золотистого цвета.</li><li>Убавьте огонь, добавьте харриссу, воду и нут. Доведите до кипения, накройте и тушите 5 минут на слабом огне.</li><li>Добавьте креветки, накройте и готовьте 2–3 минуты, пока они не станут непрозрачными. Сбрызните лимонным соком и посыпьте зеленью.</li></ol><p><em>Подавайте с хрустящим хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('a8ba7a9a-9249-5f92-ac01-7d8c6db0a85b', '11172a5a-fc85-5f35-9e10-03a67c80b234', 'en', 'Harissa shrimp and chickpeas', 'A one-skillet dish of chickpeas and shrimp in spicy harissa sauce with garlic, lemon and fresh mint or cilantro. Ready in under 15 minutes.', '<ol><li>Heat the oil in a large skillet over medium heat and cook the sliced garlic about 1 minute until nearly golden.</li><li>Reduce the heat and add the harissa, water and chickpeas. Bring to a boil, cover and simmer 5 minutes.</li><li>Add the shrimp, cover and cook 2–3 minutes until opaque. Squeeze over the lemon juice and sprinkle with herbs.</li></ol><p><em>Serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('62b48ee3-3143-5594-84db-5ec94943768b', 'fe13c901-53c8-580a-9166-3e7232f20ce1', 'ru', 'Сибас в томатном соусе с фенхелем и оливками', 'Филе морского окуня, обжаренное и запечённое в духовке, подаётся с густым соусом из томатов, белого вина, фенхеля, базилика и оливок.', '<ol><li>Разогрейте духовку до 220 °C. В большой сковороде на среднем огне разогрейте масло, 5 минут обжаривайте лук, чеснок и хлопья чили до золотистого цвета, затем добавьте фенхель и готовьте ещё 3–5 минут.</li><li>Добавьте томаты с соком и разомните ложкой, готовьте 5 минут. Влейте вино, положите базилик, оливки, 1 ч. л. соли и перец и томите на слабом огне 15 минут, пока соус немного не загустеет.</li><li>Обсушите филе, посолите и поперчите. В жаропрочной сковороде на сильном огне разогрейте масло и жарьте филе закруглённой стороной вниз 2 минуты, переверните.</li><li>Запекайте рыбу 8–10 минут, пока она не перестанет быть полупрозрачной, затем включите гриль и подрумяньте 2–4 минуты. Подавайте с соусом.</li></ol><p><em>Подавайте с отварным картофелем или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('d1f44486-6ab7-5159-96c5-bfea272cac48', 'fe13c901-53c8-580a-9166-3e7232f20ce1', 'en', 'Sea bass with tomato, fennel and olive sauce', 'Pan-seared and oven-finished sea bass fillets served over a thick sauce of tomatoes, white wine, fennel, basil and olives.', '<ol><li>Preheat the oven to 220°C. In a large skillet over medium heat, cook the onion, garlic and chilli flakes in oil for 5 minutes until golden, then add the fennel and cook 3–5 minutes more.</li><li>Add the tomatoes with their juices, crush them with a spoon and cook 5 minutes. Add the basil, wine, olives, 1 tsp salt and pepper and simmer on low 15 minutes until slightly thickened.</li><li>Pat the fillets dry and season. In an ovenproof skillet over high heat, heat the oil and sear the fillets rounded side down for 2 minutes, then flip.</li><li>Bake the fish 8–10 minutes until no longer translucent, then switch to broil for 2–4 minutes to brown. Serve with the sauce.</li></ol><p><em>Serve with boiled potatoes or rice.</em></p>', CURRENT_TIMESTAMP),
  ('25e08399-161d-5d4c-a9c4-61ec0729c40a', 'ad458982-b321-56db-b40b-ec56ce10155d', 'ru', 'Куриные шашлычки с заатаром и огуречным йогуртовым соусом', 'Кубики курицы маринуются с лимоном, чесноком и заатаром, жарятся на гриле и подаются с прохладным соусом из йогурта, огурца, мяты и укропа.', '<ol><li>Смешайте лимонный сок, масло, заатар, чеснок, соль и перец. Залейте курицу, нарезанную кубиками по 2,5 см, и мариновайте минимум 2–3 часа или всю ночь в холодильнике.</li><li>Деревянные шпажки для гриля на улице замочите в воде на 30 минут. Смешайте йогурт, огурец, лимонный сок, укроп, мяту, соль и перец и уберите в холодильник.</li><li>Нанижите курицу на шпажки, получится 4 шашлычка. Разогрейте гриль или гриль-сковороду на среднем огне, смажьте и жарьте, часто поворачивая, 12–15 минут до готовности.</li><li>Подавайте шашлычки с лимонными дольками и йогуртовым соусом.</li></ol><p><em>Подавайте с дольками лимона, лепёшкой или рисом.</em></p>', CURRENT_TIMESTAMP),
  ('ea93f02d-0b1f-50e3-8e09-8fbde2a6e1b9', 'ad458982-b321-56db-b40b-ec56ce10155d', 'en', 'Za''atar chicken kabobs with cucumber yogurt sauce', 'Chicken cubes marinated in lemon, garlic and za''atar, grilled and served with a cool yogurt sauce with cucumber, mint and dill.', '<ol><li>Mix the lemon juice, oil, za''atar, garlic, salt and pepper. Pour over the chicken cut into 2.5 cm cubes and marinate at least 2–3 hours or overnight in the fridge.</li><li>Soak wooden skewers in water for 30 minutes if grilling outdoors. Combine the yogurt, cucumber, lemon juice, dill, mint, salt and pepper and refrigerate.</li><li>Thread the chicken onto skewers to make 4 kabobs. Heat the grill or grill pan over medium heat, oil it and cook, turning often, 12–15 minutes until cooked through.</li><li>Serve the kabobs with lemon wedges and the yogurt sauce.</li></ol><p><em>Serve with lemon wedges, flatbread or rice.</em></p>', CURRENT_TIMESTAMP),
  ('ca755ca0-4a11-52ad-9c73-0f6da4c007fc', '81e9f21d-a337-5426-ab4b-27b46449c814', 'ru', 'Карри из белой фасоли и баклажана с райтой', 'Сытное веганское карри из консервированной фасоли, баклажана и томатов со специями. Подаётся с рисом и свежей райтой из банана, огурца и лайма.', '<ol><li>Обжарьте лук на масле 8 минут, добавьте имбирь, чеснок и чили и готовьте ещё несколько минут. Разведите бульонный порошок в 300 мл жидкости из банок с фасолью.</li><li>Добавьте зиру и карри, затем томаты, фасоль, кубики баклажана и бульон. Доведите до кипения, накройте и тушите на слабом огне 30 минут до мягкости овощей. Добавьте половину кинзы.</li><li>Для райты полейте нарезанные бананы лаймовым соком, добавьте огурец, красный лук, чили и остальную кинзу.</li><li>Разогрейте рис, подайте с половиной карри и райтой. Остальное охладите.</li></ol><p><em>Подавайте с тёплым рисом и райтой. Остаток карри хорошо хранится и подходит для начинки лепёшек.</em></p>', CURRENT_TIMESTAMP),
  ('90f039f8-282b-599a-ad56-732d7245202a', '81e9f21d-a337-5426-ab4b-27b46449c814', 'en', 'Butter bean and aubergine curry with banana raita', 'A hearty vegan curry of canned butter beans, aubergine and tomatoes, served with rice and a fresh banana, cucumber and lime raita.', '<ol><li>Fry the onions in the oil for 8 minutes, add the ginger, garlic and chilli and cook a few minutes more. Stir the bouillon powder into 300 ml of the liquid from the bean cans.</li><li>Stir in the cumin and curry powder, then the tomatoes, beans, aubergine and stock. Bring to a boil, cover and simmer 30 minutes until tender. Add half the coriander.</li><li>For the raita toss the bananas in lime juice and mix in the cucumber, red onion, chilli and remaining coriander.</li><li>Warm the rice and serve with half the curry and raita. Chill the rest.</li></ol><p><em>Serve with warm rice and the raita; leftover curry also works in wraps.</em></p>', CURRENT_TIMESTAMP),
  ('0ff6d8db-6004-51b6-ba53-e37be5168809', '471e02e9-204d-52ee-909d-372043a9ed09', 'ru', 'Дал из красной чечевицы с паниром', 'Густой пряный дал из красной чечевицы с кардамоном, корицей и куркумой, с обжаренными кубиками панира. Чили можно не добавлять для детей.', '<ol><li>Обжарьте кубики панира на масле 5–7 минут до золотистого цвета и переложите в миску.</li><li>В той же кастрюле 1–2 минуты прогрейте кардамон и корицу, затем добавьте лук, чеснок, имбирь, чили и куркуму и готовьте 5 минут.</li><li>Добавьте чечевицу и бульон, посолите, доведите до кипения и варите 15–20 минут до мягкости и загустения.</li><li>Верните панир, посыпьте кинзой и подавайте.</li></ol><p><em>Подавайте с лепёшкой или рисом и ложкой йогурта.</em></p>', CURRENT_TIMESTAMP),
  ('e9e961d9-6345-59bf-9dc7-e07e99cc15dc', '471e02e9-204d-52ee-909d-372043a9ed09', 'en', 'Spiced paneer and red lentil dhal', 'A thick, fragrant red lentil dhal with cardamom, cinnamon and turmeric topped with golden paneer cubes. Skip the chilli for kids.', '<ol><li>Fry the paneer cubes in the oil 5–7 minutes until golden and set aside.</li><li>In the same pan toast the cardamom and cinnamon 1–2 minutes, then add the onion, garlic, ginger, chilli and turmeric and cook 5 minutes.</li><li>Add the lentils and stock, season, bring to a simmer and cook 15–20 minutes until tender and thick.</li><li>Stir the paneer back in, scatter with coriander and serve.</li></ol><p><em>Serve with naan or chapati and a spoonful of yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('54a35892-7c81-5ddd-a440-a2340f02a606', '15f66059-83ac-5974-a50d-128b302ed682', 'ru', 'Суп с зелёной чечевицей, капустой и мисо', 'Сытный овощной суп с зелёной чечевицей, белокочанной капустой, грибами и пастой мисо. Большая кастрюля на несколько приёмов пищи.', '<ol><li>В глубокой кастрюле обжарьте нарезанные грибы в 1 ст. л. масла до румяности и переложите в миску.</li><li>Влейте оставшееся масло, добавьте лук, чеснок, морковь и сельдерей с листьями. Тушите 10 минут до лёгкой мягкости.</li><li>Добавьте мисо, овощной бульон и 1 л воды, доведите до кипения.</li><li>Положите промытую чечевицу, капусту и грибы. Накройте и варите 30–35 минут до мягкости чечевицы, приправьте и подавайте с йогуртом.</li></ol><p><em>Подавайте с ложкой густого йогурта.</em></p>', CURRENT_TIMESTAMP),
  ('a4863cda-35fb-5176-a5c9-86ffb7514106', '15f66059-83ac-5974-a50d-128b302ed682', 'en', 'Miso, green lentil and cabbage soup', 'A filling vegetable soup with green lentils, white cabbage, mushrooms and miso, made in a big batch.', '<ol><li>In a deep pan brown the sliced mushrooms in 1 tbsp oil and transfer to a bowl.</li><li>Add the remaining oil, then the onion, garlic, carrots and celery with leaves; cook gently 10 minutes.</li><li>Stir in the miso, stock and 1 l water and bring to a simmer.</li><li>Add the rinsed lentils, cabbage and mushrooms, cover and simmer 30–35 minutes until the lentils are tender. Season and serve with yogurt.</li></ol><p><em>Top with a spoonful of thick yogurt.</em></p>', CURRENT_TIMESTAMP),
  ('83c67a9d-4d2f-56bd-b24c-3b682bc8cbcb', '9ce786f5-d762-54d0-ac2b-be6eb12e7019', 'ru', 'Лапша с яйцом и ростками фасоли', 'Быстрая лапша из цельной пшеницы, обжаренная в воке с луком, перцем, карри, ростками фасоли и яйцом. Подаётся с острым лаймовым соусом.', '<ol><li>Отварите лапшу по инструкции. Смешайте лаймовый сок, тамари, тёртый чеснок и чили в мисочке.</li><li>В воке на сильном огне обжарьте лук, имбирь и перец 5 минут (последнюю минуту добавьте нарезанный чеснок). Всыпьте карри, готовьте минуту.</li><li>Добавьте ростки фасоли, прогрейте до мягкости, вмешайте тахини.</li><li>Сдвиньте овощи в сторону, вылейте яйца и взбейте их до почти готовых, затем смешайте с овощами, лапшой и кинзой. Подайте с соусом.</li></ol><p><em>Подайте лаймовый соус отдельно.</em></p>', CURRENT_TIMESTAMP),
  ('80d4207a-cca8-5fbf-a1dd-d994902dc297', '9ce786f5-d762-54d0-ac2b-be6eb12e7019', 'en', 'Egg-fried noodles with beansprouts', 'Wholemeal noodles stir-fried with onions, pepper, curry powder, beansprouts and egg, served with a zesty lime-chilli sauce.', '<ol><li>Cook the noodles per the pack. Mix the lime juice, tamari, grated garlic and chilli in a small bowl.</li><li>In a wok over high heat stir-fry the onions, ginger and pepper 5 minutes (add the chopped garlic for the last minute). Add the curry powder and cook a minute.</li><li>Add the beansprouts, heat until soft and piping hot, then mix in the tahini.</li><li>Push the veg aside, pour in the eggs and scramble until mostly set, then toss with the veg, noodles and coriander. Serve with the sauce.</li></ol><p><em>Serve the lime sauce on the side.</em></p>', CURRENT_TIMESTAMP),
  ('f0250443-c013-53a0-9623-993e720fb3ca', 'e3dee7f1-2c92-5763-b662-9d30f71f82cf', 'ru', 'Ямайское карри с курицей и картофелем', 'Курица, замаринованная в карри, аллспайс и перце скотч-боннет, тушится с морковью и картофелем в кокосовом молоке. Чем дольше маринад, тем вкуснее.', '<ol><li>Смешайте курицу со всеми ингредиентами маринада и 1 ч. л. соли. Оставьте минимум на 30 минут, лучше на ночь в холодильнике.</li><li>Разогрейте масло в толстостенной кастрюле, выложите курицу с маринадом и обжарьте по 3 минуты с каждой стороны. Добавьте морковь и картофель, перемешайте 2 минуты.</li><li>Влейте 400 мл горячей воды (ополоснув миску маринада) и кокосовое молоко, добавьте соевый соус. На сильном огне доведите до кипения, затем убавьте, накройте и тушите 30 минут.</li><li>Снимите крышку и готовьте ещё 10–15 минут до нужной густоты. Приправьте перцем и сахаром, посыпьте кинзой.</li></ol><p><em>Подавайте с белым рисом и ломтиками авокадо.</em></p>', CURRENT_TIMESTAMP),
  ('70244199-d3d7-50b5-895d-2a7bfeb38708', 'e3dee7f1-2c92-5763-b662-9d30f71f82cf', 'en', 'Jamaican curry chicken with potatoes', 'Chicken marinated in curry, allspice and scotch bonnet, simmered with carrots and potatoes in coconut milk. The longer the marinade the better.', '<ol><li>Combine the chicken with all the marinade ingredients and 1 tsp salt. Marinate at least 30 minutes, ideally overnight in the fridge.</li><li>Heat the oil in a heavy pot, add the chicken with its marinade and brown about 3 minutes per side. Add the carrots and potatoes and stir 2 minutes.</li><li>Add 400 ml hot water (swilled round the marinade bowl), the coconut milk and soy sauce. Bring to a boil on high, then cover and simmer on low for 30 minutes.</li><li>Uncover and cook 10–15 minutes more until thickened. Season with pepper and sugar and scatter with coriander.</li></ol><p><em>Serve with white rice and sliced avocado.</em></p>', CURRENT_TIMESTAMP),
  ('965317e5-bb43-5893-af62-77db9d70c455', '6305c0c3-34d1-54fc-908d-5ab319c54926', 'ru', 'Курица виндалу', 'Острая индийская курица, замаринованная в специях и лимонном соке, затем протушенная в томатном соусе с луком. Очень острое блюдо.', '<ol><li>Смешайте курицу с лимонным соком, чесноком, имбирём, сухими специями и 2 ч. л. соли. Маринуйте в холодильнике 3–4 часа или всю ночь.</li><li>В кастрюле на 2 ст. л. масла прогрейте куркуму, томатное пюре и хлопья чили. Выложите на тарелку.</li><li>Добавьте остальное масло и лук, готовьте 10–15 минут до мягкости. Всыпьте оставшиеся специи (корица, кайенский перец) на 2 минуты.</li><li>Влейте томаты и 200 мл воды, верните курицу, накройте и тушите 15–20 минут до готовности. Проверьте соль и подавайте.</li></ol><p><em>Подавайте с рисом или тёплыми лепёшками, кинзой и свежим чили.</em></p>', CURRENT_TIMESTAMP),
  ('e295f7e5-a553-5fb3-bfdb-ae6074c85350', '6305c0c3-34d1-54fc-908d-5ab319c54926', 'en', 'Chicken vindaloo', 'A fiery Indian curry: chicken marinated in spices and lemon juice, then simmered in a tomato and onion sauce.', '<ol><li>Mix the chicken with the lemon juice, garlic, ginger, dry spices and 2 tsp salt. Marinate in the fridge 3–4 hours or overnight.</li><li>In a pan with 2 tbsp oil warm the turmeric, tomato purée and chilli flakes, then set aside on a plate.</li><li>Add the remaining oil and the onion and cook 10–15 minutes until soft. Add the cinnamon and cayenne and cook 2 minutes.</li><li>Pour in the tomatoes and 200 ml water, return the chicken, cover and simmer 15–20 minutes until cooked through. Check the seasoning and serve.</li></ol><p><em>Serve with rice or warm flatbreads, coriander and fresh chilli.</em></p>', CURRENT_TIMESTAMP),
  ('c3069a01-97df-58ea-a7d5-ddc371991f83', 'c99ea2c0-1382-5cf4-8cd4-4197c5b63848', 'ru', 'Рагу из колбасок и белой фасоли со спагетти', 'Бюджетный сытный соус из свиного колбасного фарша, лука, томатов и белой фасоли, поданный со спагетти. На следующий день ещё вкуснее.', '<ol><li>Обжарьте колбасный фарш в масле 6–7 минут, разбивая на кусочки, пока не выделится жир. Переложите шумовкой на бумажное полотенце.</li><li>В выделившемся жире обжарьте лук 4–5 минут, добавьте чеснок, орегано и перец, накройте и готовьте ещё около 6 минут. Верните фарш, добавьте вустерский соус.</li><li>Добавьте томаты, соль, сахар и бульон (ополосните им банку). Варите 15 минут на слабом огне, затем добавьте фасоль с жидкостью и готовьте 10–15 минут до лёгкого загустения.</li><li>Отварите спагетти по инструкции, смешайте с рагу и подавайте.</li></ol><p><em>Подавайте со спагетти и тёртым сыром, если хотите.</em></p>', CURRENT_TIMESTAMP),
  ('6b0e3bed-dce3-513d-a128-b4c990104438', 'c99ea2c0-1382-5cf4-8cd4-4197c5b63848', 'en', 'Sausage and cannellini bean ragu with spaghetti', 'A budget-friendly, filling sauce of pork sausagemeat, onions, tomatoes and white beans tossed with spaghetti. Even better the next day.', '<ol><li>Fry the sausagemeat in the oil 6–7 minutes, breaking it up, until browned and the fat is released. Drain on kitchen paper, leaving the fat in the pan.</li><li>Fry the onions in the fat 4–5 minutes, add the garlic, oregano and pepper, cover and cook about 6 minutes more. Return the sausagemeat and add the Worcestershire sauce.</li><li>Add the tomatoes, salt, sugar and stock (swill the can with it). Simmer 15 minutes, then add the beans with their liquid and cook 10–15 minutes until thickened.</li><li>Cook the spaghetti per the pack, toss with the ragu and serve.</li></ol><p><em>Toss with spaghetti and top with grated cheese if you like.</em></p>', CURRENT_TIMESTAMP),
  ('4c1968aa-7cf9-5412-b9c1-601540ac1e13', '376cc0bf-3f51-538f-8a20-033bf8be18a6', 'ru', 'Рисовая лапша со свиным фаршем и пак-чой', 'Быстрая лапша в воке со свиным фаршем, сушёными грибами и креветками, пак-чой и двумя видами соевого соуса.', '<ol><li>Замочите сушёные грибы и креветки в горячей воде на 20 минут, отожмите и мелко нарежьте. Лапшу отварите 4 минуты, промойте холодной водой.</li><li>Разогрейте вок, влейте масло, обжарьте чеснок, имбирь, грибы и креветки несколько секунд. Добавьте фарш и жарьте до румяности.</li><li>Влейте рисовое вино, добавьте тёмный и светлый соевый соусы и пак-чой, налейте горячий бульон и доведите до кипения.</li><li>Через минуту добавьте кунжутное масло, зелёный лук и кинзу, затем лапшу, перемешайте и сразу подавайте.</li></ol><p><em>Подавайте сразу, добавив соевого соуса по вкусу.</em></p>', CURRENT_TIMESTAMP),
  ('c775034f-f407-5b35-8345-206c90e51e3f', '376cc0bf-3f51-538f-8a20-033bf8be18a6', 'en', 'Minced soy pork with rice noodles and pak choi', 'A quick wok dish of pork mince, dried mushrooms and shrimp, pak choi and rice noodles seasoned with light and dark soy sauce.', '<ol><li>Soak the dried mushrooms and shrimps in hot water for 20 minutes, drain and chop finely. Cook the noodles 4 minutes, drain and rinse with cold water.</li><li>Heat a wok, add the oil and stir-fry the garlic, ginger, mushrooms and shrimps for a few seconds. Add the mince and fry until browned.</li><li>Add the rice wine, dark and light soy sauces and pak choi, pour in the hot stock and bring to a simmer.</li><li>After 1 minute stir in the sesame oil, spring onions and coriander, then the noodles; toss and serve at once.</li></ol><p><em>Serve immediately with a little extra soy sauce.</em></p>', CURRENT_TIMESTAMP),
  ('a34861c4-09b8-5d0f-ab0f-5783167ca0cf', '8f939005-ba55-544f-8fa8-165e2c438586', 'ru', 'Ямайская тушёная курица (brown stew)', 'Целая курица, нарезанная на куски, обжаривается в карамелизованном сахаре и тушится с луком, имбирём, тимьяном и перцем. Тёмный сладковатый соус.', '<ol><li>Разделайте курицу на части: отделите крылья, ножки и бёдра, грудку нарежьте на три части.</li><li>Приправьте курицу пимент, луком, универсальной приправой, соевым соусом, перцем и солью.</li><li>Растопите сахар в большой кастрюле на среднем огне до тёмно-коричневого цвета. Порциями обжарьте курицу до румяности и вынимайте.</li><li>В оставшемся соке обжарьте лук, чеснок, имбирь, зелёный лук и тимьян 5–8 минут. Верните курицу.</li><li>Влейте бульон и 100 мл воды, добавьте кетчуп и целый перец скотч-боннет, накройте и готовьте 20 минут. Добавьте красный перец и тушите без крышки 20–25 минут до загустения. Выньте скотч-боннет.</li></ol><p><em>Подавайте с рисом.</em></p>', CURRENT_TIMESTAMP),
  ('1a3d49a9-7288-5f4d-a905-0055266febb3', '8f939005-ba55-544f-8fa8-165e2c438586', 'en', 'Jamaican brown stew chicken', 'A whole chicken in pieces browned in burnt sugar and stewed with onion, ginger, thyme and pepper in a dark, savoury-sweet sauce.', '<ol><li>Cut the chicken into pieces: wings, legs, thighs and the breast in three.</li><li>Season the chicken with the pimento, onion, all-purpose seasoning, soy sauce, pepper and salt.</li><li>Melt the sugar in a large pan over medium heat until dark brown, just past caramel. Brown the chicken in batches and remove.</li><li>In the pan cook the onion, garlic, ginger, spring onions and thyme 5–8 minutes, then return the chicken.</li><li>Add the stock, 100 ml water, ketchup and whole scotch bonnet, cover and cook 20 minutes. Add the red pepper and cook uncovered 20–25 minutes until thick. Remove the scotch bonnet.</li></ol><p><em>Serve with rice.</em></p>', CURRENT_TIMESTAMP),
  ('8418183a-4ff3-50eb-ac90-7872941b0383', 'c25c2ce1-e642-5124-844d-0434d9043d07', 'ru', 'Паста с курицей, артишоками и кейлом в одной сковороде', 'Паста варится прямо в сковороде вместе с курицей, обжаренными артишоками, кейлом и вялеными томатами с лимоном, чесноком и орегано.', '<ol><li>Разогрейте большую глубокую антипригарную сковороду на среднем огне и слегка смажьте маслом. Порциями обжарьте артишоки 3–4 минуты до тёмно-золотистого цвета и переложите на тарелку.</li><li>Посолите и поперчите курицу, обжарьте на масле 5 минут, перевернув на середине. Переложите на тарелку.</li><li>Обжарьте лук с чесноком и 2 ч. л. орегано 4 минуты до мягкости и золотистого цвета. Добавьте вяленые томаты и кейл, посолите и поперчите.</li><li>Влейте лимонный сок и воду, добавьте пасту, накройте крышкой и готовьте 10 минут.</li><li>Нарежьте курицу кусочками по 2,5 см. Верните в сковороду курицу и артишоки, убавьте огонь, накройте и готовьте ещё 5 минут до состояния al dente. Выпарите лишнюю жидкость и подавайте с пармезаном.</li></ol><p><em>Посыпьте стружкой пармезана и свежим орегано.</em></p>', CURRENT_TIMESTAMP),
  ('5bd6520e-b168-5249-ab00-cce051db719a', 'c25c2ce1-e642-5124-844d-0434d9043d07', 'en', 'One-pot chicken, artichoke and kale pasta', 'Pasta cooked in the same pan as chicken, charred artichokes, kale and sun-dried tomatoes, flavoured with lemon, garlic and oregano.', '<ol><li>Heat a large deep nonstick skillet over medium heat and lightly oil it. Char the artichokes in two batches for 3–4 minutes until dark golden and remove to a plate.</li><li>Season the chicken with salt and pepper and cook in oil for 5 minutes, turning halfway. Transfer to a plate.</li><li>Cook the onion, garlic and about 2 tsp of the oregano for 4 minutes until soft and golden. Add the sun-dried tomatoes and kale, then season with salt and pepper.</li><li>Add the lemon juice and water, stir in the pasta, cover and cook for 10 minutes.</li><li>Cut the chicken into 2.5 cm pieces. Return the chicken and artichokes to the pan, reduce the heat, cover and cook 5 more minutes until the pasta is al dente. Cook off excess liquid and serve with parmesan.</li></ol><p><em>Top with shaved parmesan and fresh oregano.</em></p>', CURRENT_TIMESTAMP),
  ('59a491e1-e981-5456-a85d-2c083d0a79f9', '19c7263a-ff0c-52b3-a9ba-0b6e679467a3', 'ru', 'Салат с киноа, нутом, авокадо и огурцом', 'Сытный вегетарианский салат из киноа и нута с помидорами, огурцом, красным луком, кинзой и соком лайма. Много белка и клетчатки.', '<ol><li>Промойте киноа и сварите в двойном объёме воды 12–15 минут до готовности, остудите.</li><li>Смешайте киноа, помидоры, нут, красный лук, кинзу и лаймовый сок, посолите и поперчите. Уберите в холодильник до подачи.</li><li>Непосредственно перед подачей добавьте нарезанные огурец и авокадо и аккуратно перемешайте.</li></ol><p><em>Добавляйте огурец и авокадо перед самой подачей.</em></p>', CURRENT_TIMESTAMP),
  ('e6764eed-dee6-557f-acce-da690f321d8f', '19c7263a-ff0c-52b3-a9ba-0b6e679467a3', 'en', 'Quinoa, chickpea, avocado and cucumber salad with lime', 'A hearty vegan salad of quinoa and chickpeas with tomatoes, cucumber, red onion, cilantro and lime juice, rich in protein and fibre.', '<ol><li>Rinse the quinoa and simmer in twice its volume of water for 12–15 minutes until tender, then let it cool.</li><li>Combine the quinoa, tomatoes, chickpeas, red onion, cilantro and lime juice, then season. Refrigerate until serving.</li><li>Just before serving, fold in the diced cucumber and avocado.</li></ol><p><em>Add the cucumber and avocado just before serving.</em></p>', CURRENT_TIMESTAMP),
  ('b9210553-4732-5fcd-ad87-3b7764bdef8b', '09ac2125-4232-5dee-a69e-7cd9f8384fa4', 'ru', 'Запечённые макароны со шпинатом, рикоттой и моцареллой', 'Макароны зити в томатном соусе со шпинатом, рикоттой, пармезаном и моцареллой запекаются под фольгой до расплавленного сыра. Вегетарианская запеканка для семьи.', '<ol><li>Разогрейте духовку до 190 °C. Смажьте форму 23×33 см маслом.</li><li>Отварите пасту в подсоленной воде до состояния al dente, не доварив 3–4 минуты, слейте воду.</li><li>В кастрюле обжарьте чеснок в масле, добавьте размороженный шпинат, измельчённые томаты, базилик, орегано, соль и перец и варите 5 минут.</li><li>Смешайте соус с пастой, добавьте половину моцареллы, пармезан и рикотту. Переложите в форму, посыпьте оставшейся моцареллой и накройте фольгой.</li><li>Запекайте около 30 минут, пока сыр не расплавится, а края не подрумянятся. Дайте постоять 5 минут.</li></ol><p><em>Дайте постоять 5 минут и подайте со свежим салатом.</em></p>', CURRENT_TIMESTAMP),
  ('7a1c5703-bce1-5f51-b01c-ac3749de6dfb', '09ac2125-4232-5dee-a69e-7cd9f8384fa4', 'en', 'Baked ziti with spinach, ricotta and mozzarella', 'Ziti pasta in tomato sauce with spinach, ricotta, parmesan and mozzarella, baked under foil until the cheese melts. A family-friendly vegetarian bake.', '<ol><li>Preheat the oven to 190°C and oil a 23×33 cm baking dish.</li><li>Cook the pasta in salted water until al dente, about 3–4 minutes under the package time, then drain.</li><li>In a saucepan sauté the garlic in oil, add the thawed spinach, crushed tomatoes, basil, oregano, salt and pepper and cook 5 minutes.</li><li>Combine the sauce with the pasta, mix in half the mozzarella, parmesan and ricotta, transfer to the dish, top with the remaining mozzarella and cover with foil.</li><li>Bake about 30 minutes until the cheese melts and the edges brown lightly. Let stand 5 minutes.</li></ol><p><em>Rest 5 minutes and serve with a green salad.</em></p>', CURRENT_TIMESTAMP),
  ('0485a86f-fa6a-5056-aa93-0b5c0243bc7f', '06ba908c-70c9-5724-a101-ea2724210a8c', 'ru', 'Куриная грудка в арахисовом соусе с салатом из капусты', 'Куриное филе тушится в имбирно-арахисовом соусе с чесноком и шрирачей и подаётся с хрустящим салатом из краснокочанной капусты и моркови с лаймом.', '<ol><li>Смешайте капусту и морковь с соком 1 лайма, 1 ч. л. масла и ¾ ч. л. соли. Оставьте мариноваться, пока готовите курицу.</li><li>Посолите и поперчите курицу. Разогрейте большую антипригарную сковороду на средне-сильном огне, добавьте 1 ч. л. масла и обжарьте курицу 5 минут до золотистого цвета с одной стороны.</li><li>Переверните курицу, влейте воду и добавьте арахисовую пасту, шрирачу, имбирь и чеснок. Доведите до кипения, разбивая пасту лопаткой.</li><li>Убавьте огонь и тушите около 20 минут, иногда переворачивая курицу и помешивая соус, пока мясо не будет готово, а соус не уварится. Дайте курице отдохнуть 5 минут и нарежьте.</li><li>Добавьте в соус сок оставшейся половины лайма. Разложите салат по тарелкам, сверху курицу, полейте соусом и посыпьте кинзой.</li></ol><p><em>Подавайте с бурым рисом и кинзой.</em></p>', CURRENT_TIMESTAMP),
  ('be644047-b3c1-5368-a0ed-38828f9ced6b', '06ba908c-70c9-5724-a101-ea2724210a8c', 'en', 'Peanut-braised chicken breast with lime cabbage slaw', 'Chicken breasts braised in a gingery, mildly spicy peanut sauce with garlic and sriracha, served with a crisp red cabbage and carrot slaw with lime.', '<ol><li>Toss the cabbage and carrots with the juice of 1 lime, 1 tsp oil and ¾ tsp salt. Let sit while you cook the chicken.</li><li>Season the chicken. Heat a large nonstick skillet over medium-high, add 1 tsp oil and sear the chicken about 5 minutes until golden on one side.</li><li>Flip the chicken, then add the water, peanut butter, sriracha, ginger and garlic. Bring to a boil, breaking up the peanut butter with a spatula.</li><li>Reduce the heat and simmer about 20 minutes, flipping the chicken occasionally, until cooked through and the sauce reduces. Rest 5 minutes and slice.</li><li>Stir the juice of the remaining lime into the sauce. Plate the slaw, top with the chicken, spoon over the sauce and garnish with cilantro.</li></ol><p><em>Serve with brown rice and cilantro.</em></p>', CURRENT_TIMESTAMP),
  ('6389663a-6a2b-5037-84c3-01395fe5b1c5', 'f8725b7b-90f5-5804-b0e7-a7518b92ec8b', 'ru', 'Салат из фарро с фетой, огурцом и вялеными томатами', 'Лёгкий средиземноморский салат из полбы с огурцом, сладким перцем, вялеными томатами, фетой, мятой и лимонным соком. Подходит как гарнир или обед.', '<ol><li>Отварите фарро в подсоленной воде 15–20 минут до состояния al dente, слейте воду и остудите.</li><li>Смешайте фарро с красным луком, вялеными томатами, фетой, огурцом, перцем, лимонным соком, маслом и мятой, посолите и поперчите. Подавайте охлаждённым или комнатной температуры.</li></ol><p><em>Подавайте охлаждённым или при комнатной температуре.</em></p>', CURRENT_TIMESTAMP),
  ('4d5e544d-0cdf-539e-9dd2-9e25a54a23da', 'f8725b7b-90f5-5804-b0e7-a7518b92ec8b', 'en', 'Farro salad with feta, cucumber and sun-dried tomatoes', 'A light Mediterranean farro salad with cucumber, bell pepper, sun-dried tomatoes, feta, mint and lemon juice. Works as a side or a lunch.', '<ol><li>Cook the farro in salted water for 15–20 minutes until al dente, drain and cool.</li><li>Toss the farro with the red onion, sun-dried tomatoes, feta, cucumber, pepper, lemon juice, oil and mint, and season. Serve chilled or at room temperature.</li></ol><p><em>Serve chilled or at room temperature.</em></p>', CURRENT_TIMESTAMP),
  ('b484b1ce-e4f9-54f0-af18-c83feb6da029', 'ff6a4464-5dc3-5b1a-841c-aa16cab92c12', 'ru', 'Овощной суп с бурым рисом', 'Густой суп с морковью, пастернаком, сельдереем, луком-пореем и бурым рисом. Часть можно пюрировать для кремовой текстуры.', '<ol><li>Разогрейте масло, добавьте лук, чеснок, сельдерей, морковь, пастернак и тимьян. Накройте и тушите 15 минут, пока лук не размягчится.</li><li>Всыпьте рис, влейте бульон, доведите до кипения и варите без крышки 15 минут.</li><li>Посолите и поперчите, добавьте порей и варите ещё 5 минут. При желании пюрируйте половину супа блендером.</li><li>Разлейте по тарелкам и посыпьте петрушкой.</li></ol><p><em>Посыпьте петрушкой и подавайте в глубоких тарелках.</em></p>', CURRENT_TIMESTAMP),
  ('acf81c12-d0e1-5a55-87cc-a004c57511d9', 'ff6a4464-5dc3-5b1a-841c-aa16cab92c12', 'en', 'Chunky vegetable and brown rice soup', 'A hearty soup of carrots, parsnips, celery, leeks and brown rice; blitz half for a creamier texture.', '<ol><li>Heat the oil and add the onion, garlic, celery, carrots, parsnips and thyme. Cover and cook gently 15 minutes until the onion softens.</li><li>Add the rice and stock, bring to a boil and simmer uncovered 15 minutes.</li><li>Season, stir in the leeks and cook 5 more minutes. Optionally blitz half the soup with a stick blender.</li><li>Ladle into bowls and top with parsley.</li></ol><p><em>Garnish with parsley and serve in deep bowls.</em></p>', CURRENT_TIMESTAMP),
  ('4a73b157-bb4d-5315-9369-55d6a23b252b', '82eb8fbb-a47c-51c7-bb47-7385dc88249f', 'ru', 'Суп с картофелем, пореем и чоризо', 'Наваристый зимний суп: картофель и порей, сваренные в курином бульоне с ломтиками чоризо и петрушкой.', '<ol><li>Доведите картофель с бульоном и щепоткой соли до кипения и варите 10 минут.</li><li>Промойте порей от песка, добавьте в кастрюлю вместе с чоризо и варите 15–20 минут до мягкости овощей.</li><li>Приправьте, снимите с огня, добавьте петрушку и дайте постоять 5 минут. Подайте с хлебом.</li></ol><p><em>Подавайте с ломтями хрустящего хлеба.</em></p>', CURRENT_TIMESTAMP),
  ('17989c6a-90d1-5d52-a65c-bdbef3e4e7ba', '82eb8fbb-a47c-51c7-bb47-7385dc88249f', 'en', 'Potato, leek and chorizo soup', 'A hearty winter soup of potatoes and leeks simmered in chicken stock with sliced chorizo and parsley.', '<ol><li>Simmer the potatoes in the stock with a pinch of salt for 10 minutes.</li><li>Rinse the leeks of grit, add them with the chorizo and simmer 15–20 minutes until very tender.</li><li>Season, remove from the heat, stir in the parsley and rest 5 minutes. Serve with bread.</li></ol><p><em>Serve with thick slices of crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('6b634b58-206f-58ec-90c5-d7ef5525dffa', '4008d65a-e9b0-567f-a08c-c8e62f05511f', 'ru', 'Тайский кокосовый суп с курицей и грибами', 'Согревающий сливочный суп на кокосовом молоке с курицей, шампиньонами, лемонграссом, галангалом и пастой карри.', '<ol><li>В кастрюле на среднем огне обжарьте шалот, лемонграсс, чеснок, галангал, чили, стебли кинзы и пасту карри 1–2 минуты до аромата.</li><li>Влейте кокосовое молоко и бульон, проварите 10–15 минут.</li><li>Добавьте курицу и листья лайма, варите 10 минут, за 5 минут до конца добавьте грибы.</li><li>Добавьте рыбный соус, сахар и сок лайма по вкусу. Выньте лемонграсс и галангал, посыпьте кинзой.</li></ol><p><em>Посыпьте листьями кинзы, лимонграсс и галангал не ешьте.</em></p>', CURRENT_TIMESTAMP),
  ('39500e8d-6c29-5e11-b017-49ef6e05f769', '4008d65a-e9b0-567f-a08c-c8e62f05511f', 'en', 'Thai-inspired coconut chicken soup', 'A warming creamy coconut soup with chicken, mushrooms, lemongrass, galangal and red curry paste.', '<ol><li>In a saucepan over medium-high heat cook the shallots, lemongrass, garlic, galangal, chillies, coriander stalks and curry paste 1–2 minutes until fragrant.</li><li>Pour in the coconut milk and stock and simmer 10–15 minutes.</li><li>Add the chicken and lime leaves and cook 10 minutes, adding the mushrooms for the last 5.</li><li>Stir in the fish sauce, sugar and lime juice to taste. Remove the lemongrass and galangal and scatter with coriander.</li></ol><p><em>Sprinkle with coriander leaves; don''t eat the lemongrass or galangal slices.</em></p>', CURRENT_TIMESTAMP),
  ('0b9c3aa8-5403-5dcd-b14c-b94651f1e228', '20cca8f5-3724-58eb-8e35-0c0ec649fa47', 'ru', 'Рыбный суп с картофелем, морковью и укропом', 'Лёгкий суп с белой рыбой, картофелем, морковью, перцем и пореем, ароматный от укропа и лимона.', '<ol><li>Обжарьте лук 5–7 минут, добавьте чеснок, картофель, морковь, перец, порей и томатную пасту на 3–5 минут.</li><li>Влейте бульон, добавьте лавровый лист, накройте и варите 15 минут до почти готовых овощей.</li><li>Нарежьте рыбу кусочками, посолите, поперчите и сбрызните лимонным соком. Добавьте в суп с цедрой и рубленым укропом, варите 5–7 минут на слабом огне.</li><li>Выньте лавровый лист, проверьте приправы, посыпьте укропом.</li></ol><p><em>Посыпьте веточками укропа и подавайте горячим.</em></p>', CURRENT_TIMESTAMP),
  ('0e0e6241-f978-5ab4-b428-f95756c7e573', '20cca8f5-3724-58eb-8e35-0c0ec649fa47', 'en', 'White fish soup with potatoes, carrots and dill', 'A light soup of white fish with potatoes, carrots, peppers and leeks, flavoured with dill and lemon.', '<ol><li>Cook the onion 5–7 minutes, then add the garlic, potatoes, carrots, pepper, leek and tomato purée for 3–5 minutes.</li><li>Pour in the stock, add the bay leaf, cover and cook 15 minutes until the veg is almost tender.</li><li>Cut the fish into pieces, season with salt, pepper and lemon juice. Add to the soup with the zest and chopped dill and simmer gently 5–7 minutes.</li><li>Remove the bay leaf, adjust the seasoning and top with dill sprigs.</li></ol><p><em>Scatter with dill sprigs and serve hot.</em></p>', CURRENT_TIMESTAMP),
  ('08369b40-a68c-5482-872b-b952c4fb9da2', 'b6f86397-2400-5668-8a06-a271f81c64cf', 'ru', 'Крем-суп из пастернака и яблока', 'Бархатистый овощной суп из сладкого пастернака и кислого яблока с имбирём, тимьяном и сливками.', '<ol><li>Растопите масло, накройте и тушите лук, чеснок, тимьян, имбирь и соль 15 минут на слабом огне до мягкости.</li><li>Добавьте нарезанный пастернак (крупные корни освободите от жёсткой сердцевины), яблоко и бульон. Доведите до кипения и варите под крышкой 35–40 минут.</li><li>Слегка остудите, пюрируйте до гладкости, влейте сливки и проверьте приправы. Разогрейте и подавайте.</li></ol><p><em>Добавьте ложку сливок и семена калинджи, подавайте с хлебом.</em></p>', CURRENT_TIMESTAMP),
  ('c7ad25b4-6c21-560f-82e9-8f0a115270ad', 'b6f86397-2400-5668-8a06-a271f81c64cf', 'en', 'Parsnip and apple cream soup', 'A velvety soup of sweet parsnip and tart apple with ginger, thyme and cream.', '<ol><li>Melt the butter and cook the onion, garlic, thyme, ginger and salt covered over low heat 15 minutes until soft.</li><li>Add the chopped parsnips (core out large ones), apple and stock. Bring to a boil and simmer covered 35–40 minutes.</li><li>Cool slightly, blend until smooth, stir in the cream and check the seasoning. Reheat and serve.</li></ol><p><em>Swirl with cream and sprinkle with nigella seeds; serve with crusty bread.</em></p>', CURRENT_TIMESTAMP),
  ('b8dcf87d-275d-575f-9fd2-1f60c1bcee92', '25a9006c-ff0c-5f99-b726-785fa4102332', 'ru', 'Зелёный суп-пюре из кейла, гороха и картофеля', 'Яркий веганский крем-суп из капусты кейл, зелёного горошка и картофеля с лаймом.', '<ol><li>Тушите лук, чеснок и нарезанные стебли кейла с солью под крышкой 10–15 минут. Добавьте картофель и готовьте ещё 5 минут.</li><li>Влейте бульон, доведите до кипения и варите 20 минут. Добавьте листья кейла и горошек и готовьте 5–10 минут.</li><li>Слегка остудите и пюрируйте до гладкости. Разогрейте и подавайте с лаймом.</li></ol><p><em>Подавайте с долькой лайма и тыквенными семечками.</em></p>', CURRENT_TIMESTAMP),
  ('69baeef3-458c-503c-95e9-accc5d955c80', '25a9006c-ff0c-5f99-b726-785fa4102332', 'en', 'Kale, pea and potato green soup', 'A bright vegan blended soup of kale, peas and potatoes finished with lime.', '<ol><li>Cook the onion, garlic, kale stalks and salt covered 10–15 minutes, then add the potatoes for 5 more minutes.</li><li>Pour in the stock, boil, then simmer 20 minutes. Add the kale leaves and peas and cook 5–10 minutes.</li><li>Cool a little and blend until smooth. Reheat and serve with lime.</li></ol><p><em>Serve with lime wedges and toasted pumpkin seeds.</em></p>', CURRENT_TIMESTAMP),
  ('d0e208c2-ec4f-586d-aa98-4538638c3620', '30c02fcc-8cbc-53fe-8888-0556045e6e12', 'ru', 'Запечённые баклажаны с глазурью из мисо и рисом', 'Половинки баклажана с надрезами, запечённые с мисо, мирином и мёдом до карамельной корочки. Подаются на буром рисе с кунжутом.', '<ol><li>Разогрейте духовку до 200 °C. Сделайте на мякоти баклажанов глубокую сетку надрезов, смажьте кунжутным маслом и выложите срезом вниз на противень с пергаментом. Запекайте 15–20 минут.</li><li>Смешайте мисо, мирин, мёд и 1 ст. л. воды. Переверните баклажаны, смажьте глазурью и запекайте ещё 15–20 минут до мягкости.</li><li>Включите гриль на максимум и подержите баклажаны 5 минут до пузырьков. Разогрейте рис, выложите баклажаны, посыпьте кунжутом и луком.</li></ol><p><em>Посыпьте кунжутом и зелёным луком.</em></p>', CURRENT_TIMESTAMP),
  ('ad9cc42e-3149-50bd-b990-3f0271d4d0a4', '30c02fcc-8cbc-53fe-8888-0556045e6e12', 'en', 'Sticky miso aubergine traybake with rice', 'Scored aubergine halves roasted with a miso, mirin and honey glaze until caramelised, served on brown rice with sesame.', '<ol><li>Heat the oven to 200 °C. Score the aubergine flesh in a deep criss-cross, brush with sesame oil and roast cut-side down on a lined tray 15–20 minutes.</li><li>Mix the miso, mirin, honey and 1 tbsp water. Turn the aubergines cut-side up, brush with the glaze and roast 15–20 minutes more until soft.</li><li>Grill on high for 5 minutes until bubbling. Warm the rice, top with the aubergines, sesame seeds and spring onions.</li></ol><p><em>Top with sesame seeds and spring onions.</em></p>', CURRENT_TIMESTAMP),
  ('d763e14c-d019-58eb-b7b9-6f3f9d671dba', 'fd7f881c-e95a-56a2-b7a6-3de38b18c88a', 'ru', 'Колбаски с тыквой и красным луком в духовке', 'Простое блюдо на одном противне: колбаски, мускатная тыква и красный лук в медово-пряной глазури с копчёной паприкой, зирой, фенхелем и хариссой.', '<ol><li>Разогрейте духовку до 200 °C. В большой миске смешайте фенхель, паприку, зиру, масло, мёд, томатную пасту и харису.</li><li>Добавьте колбаски, дольки лука и ломти тыквы (2 см), аккуратно перемешайте руками и выложите ровным слоем в форму.</li><li>Запекайте 30–40 минут, периодически перемешивая, до румяности. Посыпьте петрушкой и подавайте.</li></ol><p><em>Подавайте с отварным молодым картофелем и зеленью.</em></p>', CURRENT_TIMESTAMP),
  ('09324fc3-1967-51a2-8b27-8c5958ebaf1f', 'fd7f881c-e95a-56a2-b7a6-3de38b18c88a', 'en', 'Smoky sausage and butternut squash traybake', 'A one-tray dinner of sausages, butternut squash and red onions coated in a honey-spice glaze of smoked paprika, cumin, fennel and harissa.', '<ol><li>Heat the oven to 200 °C. In a large bowl mix the fennel, paprika, cumin, oil, honey, tomato purée and harissa.</li><li>Add the sausages, onion wedges and squash slices (2 cm), toss to coat and spread in a roasting tin.</li><li>Roast 30–40 minutes, stirring occasionally, until browned. Scatter with parsley and serve.</li></ol><p><em>Serve with steamed new potatoes and greens.</em></p>', CURRENT_TIMESTAMP),
  ('5ef7fb04-c90c-5482-a635-99647f25682d', 'c139711a-94cc-5ab6-a5af-6d3dfa9ddcbf', 'ru', 'Суп с орзо, нутом и томатами', 'Лёгкий и сытный суп с пастой орзо, нутом, морковью, сельдереем и томатами. Подаётся с оливковым маслом и сыром.', '<ol><li>Обжарьте лук, морковь и сельдерей на оливковом масле 15 минут до мягкости. Добавьте томатную пасту, чеснок и розмарин или тимьян, готовьте до карамелизации пасты.</li><li>Влейте бульон, томаты и нут с жидкостью, варите 15 минут.</li><li>Залейте орзо кипятком на 15 минут, слейте воду и добавьте в суп. Варите 5–8 минут до мягкости пасты.</li><li>Выньте ветки трав, приправьте, сбрызните маслом и подавайте.</li></ol><p><em>Сбрызните оливковым маслом и посыпьте пармезаном.</em></p>', CURRENT_TIMESTAMP),
  ('fe620c77-ce42-5a18-9598-7d413e020748', 'c139711a-94cc-5ab6-a5af-6d3dfa9ddcbf', 'en', 'Orzo, chickpea and tomato soup', 'A light but filling soup of orzo, chickpeas, carrots, celery and tomatoes, finished with olive oil and cheese.', '<ol><li>Cook the onion, carrots and celery in olive oil for 15 minutes until soft. Stir in the tomato purée, garlic and herbs and cook until the purée caramelises.</li><li>Add the stock, tomatoes and chickpeas with their liquid and simmer 15 minutes.</li><li>Soak the orzo in boiling water 15 minutes, drain, add to the soup and cook 5–8 minutes until tender.</li><li>Remove the herb stalks, season, drizzle with oil and serve.</li></ol><p><em>Drizzle with olive oil and sprinkle with grated parmesan.</em></p>', CURRENT_TIMESTAMP)
ON CONFLICT ("foodId", "language") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "content" = EXCLUDED."content", "updatedAt" = EXCLUDED."updatedAt";

